/**
 * Cross-platform launcher for the Vitest CLI.
 *
 * WHY THIS EXISTS
 * ---------------
 * On Windows, Vite builds its module URLs from the working directory and from
 * the path it was started with, verbatim, while Node's ESM loader canonicalises
 * the same files against their real path on disk. When those disagree only in
 * drive-letter case (this repo is checked out at `D:\projects\Findmedi\...` but
 * VS Code / the integrated terminal opens it as `d:\projects\Findmedi\...`), the
 * very same file ends up with two different module URLs. Vite's module runner
 * then evaluates `@vitest/runner` twice, so the copy that receives the test file
 * never has its internal `runner` set and EVERY test file dies at its first
 * `describe(...)` with:
 *
 *   TypeError: Cannot read properties of undefined (reading 'config')
 *
 * That error looks like broken tests but is purely a path-casing issue: the same
 * suite passes when the shell, the working directory and the Vitest entry path
 * all use the on-disk drive case. This wrapper normalises all of them, then
 * spawns Vitest, so `npm test` behaves identically on every platform. It is a
 * no-op on Linux/macOS (where CI runs) and whenever the case already matches, so
 * it cannot regress CI.
 *
 * Usage (see package.json scripts):
 *   node scripts/run-vitest.cjs run
 *   node scripts/run-vitest.cjs            # watch mode
 */
const { spawn } = require('node:child_process');
const path = require('node:path');

/**
 * Uppercases the drive letter on Windows so a path matches its on-disk form.
 * @param {string} target
 * @returns {string}
 */
function normaliseDriveCase(target) {
  if (process.platform !== 'win32') return target;
  return target.replace(/^[a-z]:/, (letter) => letter.toUpperCase());
}

const resolvedRoot = path.resolve(__dirname, '..');
const projectRoot = normaliseDriveCase(resolvedRoot);
const vitestBin = path.join(projectRoot, 'node_modules', 'vitest', 'vitest.mjs');

if (projectRoot !== resolvedRoot) {
  console.log(`[run-vitest] normalised root: ${resolvedRoot} -> ${projectRoot}`);
}

const child = spawn(process.execPath, [vitestBin, ...process.argv.slice(2)], {
  cwd: projectRoot,
  stdio: 'inherit',
});

child.on('error', (error) => {
  console.error('[run-vitest] failed to start Vitest:', error.message);
  process.exit(1);
});

child.on('exit', (code, signal) => {
  if (signal) {
    process.kill(process.pid, signal);
    return;
  }
  process.exit(code ?? 1);
});

const fs = require('fs');
const path = require('path');

const filesToUpdate = [
  { 
    file: 'HospitalProfile.jsx', 
    type: 'hospital', 
    idVar: '{id}', 
    nameVar: '{hospital?.name}', 
    reviewsState: 'setReviews' 
  },
  { 
    file: 'ClinicDetail.jsx', 
    type: 'clinic', 
    idVar: '{clinicId}', 
    nameVar: '{clinic?.name}', 
    reviewsState: 'setReviews' 
  },
  { 
    file: 'DiagnosticCenterDetail.jsx', 
    type: 'lab', 
    idVar: '{clinicId}', 
    nameVar: '{clinic?.name}', 
    reviewsState: 'setReviewsData' 
  },
  { 
    file: 'HospitalDoctor.jsx', 
    type: 'doctor', 
    idVar: '{id}', 
    nameVar: '{doctor?.name}', 
    reviewsState: 'setReviews' 
  },
  { 
    file: 'ClinicDoctor.jsx', 
    type: 'doctor', 
    idVar: '{id}', 
    nameVar: '{doctor?.name}', 
    reviewsState: 'setReviews' 
  },
  { 
    file: 'MedicineStoreDetail.jsx', 
    type: 'pharmacy', 
    idVar: '{storeId}', 
    nameVar: '{store?.name}', 
    reviewsState: 'setReviewsData' 
  },
  { 
    file: 'TechnicianDetail.jsx', 
    type: 'technician', 
    idVar: '{id}', 
    nameVar: '{technician?.name}', 
    reviewsState: 'setReviewsData' 
  }
];

const basePath = path.resolve(__dirname, '..', 'src', 'pages');

filesToUpdate.forEach(item => {
  const filePath = path.join(basePath, item.file);
  if (!fs.existsSync(filePath)) {
    console.log(`Skipping ${item.file} - not found`);
    return;
  }

  let content = fs.readFileSync(filePath, 'utf8');
  let modified = false;

  // 1. Add import if not exists
  if (!content.includes('import ReviewDialog from')) {
    // Find the last import
    const lastImportIndex = content.lastIndexOf('import ');
    const endOfLastImport = content.indexOf('\n', lastImportIndex);
    content = content.slice(0, endOfLastImport + 1) + `import ReviewDialog from '@/components/ReviewDialog';\n` + content.slice(endOfLastImport + 1);
    modified = true;
  }

  // 2. Add state if not exists
  if (!content.includes('const [showReviewDialog, setShowReviewDialog]')) {
    // Find where states are defined (after export default function)
    const functionMatch = content.match(/export default function \w+\s*\([^)]*\)\s*\{/);
    if (functionMatch) {
      const insertPos = functionMatch.index + functionMatch[0].length;
      content = content.slice(0, insertPos) + `\n  const [showReviewDialog, setShowReviewDialog] = useState(false);` + content.slice(insertPos);
      modified = true;
    }
  }

  // 3. Replace toast.info buttons
  const oldButtonRegex = /onClick=\{\(\) => toast\.info\(['`]Write a review feature coming soon['`]\)\}/g;
  if (oldButtonRegex.test(content)) {
    content = content.replace(oldButtonRegex, `onClick={() => setShowReviewDialog(true)}`);
    modified = true;
  }

  // 4. Add ReviewDialog component before the last closing div
  if (!content.includes('<ReviewDialog')) {
    const dialogComponent = `
      <ReviewDialog 
        open={showReviewDialog} 
        onOpenChange={setShowReviewDialog}
        entityType="${item.type}"
        entityId=${item.idVar}
        entityName=${item.nameVar}
        onReviewSubmitted={(review) => {
          ${item.reviewsState}(prev => [review, ...(Array.isArray(prev) ? prev : [])]);
        }}
      />
    </div>`;
    
    // Find the last </div>
    const lastDivIndex = content.lastIndexOf('</div>');
    if (lastDivIndex !== -1) {
      content = content.slice(0, lastDivIndex) + dialogComponent + content.slice(lastDivIndex + 6);
      modified = true;
    }
  }

  if (modified) {
    fs.writeFileSync(filePath, content, 'utf8');
    console.log(`Updated ${item.file}`);
  }
});

