/**
 * Convert a number to an ordinal string: 1 → "1st", 2 → "2nd", 3 → "3rd".
 */
export function ordinal(n: number) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

