  const [bookingNotes, setBookingNotes] = useState('');
  // APPT-M-02: optional recurring pattern for the selected slot. Hidden for
  // package bookings (a package IS the multi-session product).
  const [repeatFreq, setRepeatFreq] = useState<'none' | 'weekly' | 'biweekly' | 'monthly'>('none');
  const [repeatCount, setRepeatCount] = useState(4);
  const [bookingLoading, setBookingLoading] = useState(false);
  const [bookedSlots, setBookedSlots] = useState<ApiRow[]>([]);
  const [lockedSlots, setLockedSlots] = useState<ApiRow[]>([]);
  const [lockingSlot, setLockingSlot] = useState(false);
  const [slotCounts, setSlotCounts] = useState<ApiRow>({});
  const [dateDisabledSlots, setDateDisabledSlots] = useState<ApiRow[]>([]);
  const [pendingDisabledSlots, setPendingDisabledSlots] = useState<ApiRow[]>([]);
  const [bookingWindow, setBookingWindow] = useState<Unmodelled>(null);
  const [selectedHour, setSelectedHour] = useState<Unmodelled>(null);
  const [paymentMethod, setPaymentMethod] = useState('card');
  const [paymentLoading, setPaymentLoading] = useState(false);
  const [waitlistLoading, setWaitlistLoading] = useState(false);
  const [bookingDetails, setBookingDetails] = useState<Unmodelled>(null);
  const [appointmentMode, setAppointmentMode] = useState('offline');
  // Mind package selection (counsellor/psychiatrist booking me alag section)
  const [selectedPackageId, setSelectedPackageId] = useState('single');
  const [packageInfoId, setPackageInfoId] = useState<Unmodelled>(null);
  const [intakeFormData, setIntakeFormData] = useState({
    chiefComplaint: '', chiefComplaintOther: '', symptomsDuration: '',
    pastMedicalHistory: { hasHistory: null, details: '' },
    currentTreatment: { hasPastTreatment: null, doctorName: '', cityState: '', when: '', prescriptionFile: '', takingMedicines: null },
    testReports: { hasReports: null, reportFile: '' },
    currentMedications: { hasMedications: null, details: '' },
    allergies: { hasAllergies: null, details: '' },
    familyHistory: { hasHistory: null, details: '' },
  });
  const processingRef = useRef(false);

  // Booking target: 'self' | 'family' | 'other'
  const [bookingFor, setBookingFor] = useState('self');
  const [selectedFamilyMember, setSelectedFamilyMember] = useState<Unmodelled>(null);
  const [familyMembers, setFamilyMembers] = useState<ApiRow[]>([]);
  const [fetchingFamily, setFetchingFamily] = useState(false);
  const [otherPatient, setOtherPatient] = useState({ name: '', gender: 'Male', phone: '', age: '', bloodGroup: '' });
  // Guardian consent: required when booking for a family member / other person
  // (minor or dependent). Recorded as a checkbox confirmation sent with payment.
  const [guardianConsent, setGuardianConsent] = useState(false);
  // Discreet mode: neutral copy when the category is sensitive (mental health,
  // sexual/reproductive, de-addiction, IVF) or the user toggles it on.
  const [discreetMode, setDiscreetMode] = useState(false);
  // Slot-hold countdown stub: a held slot is released after SLOT_HOLD_SECONDS.
  // The server lock is authoritative; this is the visible countdown only.
  const [slotHoldLeft, setSlotHoldLeft] = useState<number | null>(null);

  const { user } = useAuth();
  const navigate = useNavigate();

  // Reset state when opened
  useEffect(() => {
    if (open) {
      const doc = doctor || null;
      setSelectedDoctor(doc);
      setBookingStep(doc ? 0 : -1);
      setBookingDate(getISTDateString());
      setBookingTime('');
      setSelectedHour(null);
      setDateDisabledSlots([]);
      setPendingDisabledSlots([]);
      setLockedSlots([]);
      setBookingWindow(null);
      setBookingNotes('');
      setRepeatFreq('none');
      setRepeatCount(4);
      setPaymentMethod('card');
      setBookingDetails(null);
      // Mind providers (offline mode nahi dete) ke liye pehla available mode default
      {
        const modes = doc?.appointmentModes;
        setAppointmentMode(modes && modes.length > 0 && !modes.includes('offline') ? modes[0] : 'offline');
      }
      setIntakeFormData({
        chiefComplaint: '', chiefComplaintOther: '', symptomsDuration: '',
        pastMedicalHistory: { hasHistory: null, details: '' },
        currentTreatment: { hasPastTreatment: null, doctorName: '', cityState: '', when: '', prescriptionFile: '', takingMedicines: null },
        testReports: { hasReports: null, reportFile: '' },
        currentMedications: { hasMedications: null, details: '' },
        allergies: { hasAllergies: null, details: '' },
        familyHistory: { hasHistory: null, details: '' },
      });
      setBookingFor('self');
      setSelectedFamilyMember(null);
      setGuardianConsent(false);
      setSlotHoldLeft(null);
      setSelectedPackageId('single');
      setPackageInfoId(null);
      setOtherPatient({ name: '', gender: 'Male', phone: '', age: '', bloodGroup: '' });

      // Fetch family members
      if (user) {
        setFetchingFamily(true);
        api.dispatch(null, '/patient/family')
          .then(res => setFamilyMembers(res?.members || []))
          .catch(() => setFamilyMembers([]))
          .finally(() => setFetchingFamily(false));
      }

      if (!doc && facility && (!facility.doctors || facility.doctors.length === 0)) {
        setFetchingDoctors(true);
        const query = facility.type === 'clinic' ? { clinicId: facility._id } : { hospitalId: facility._id };
        api.getDoctors(query)
          .then(res => {
            const docs = Array.isArray(res) ? res : (res?.data || res?.doctors || []);
            setFetchedDoctors(docs);
          })
          .catch(err => console.error('Failed to fetch facility doctors:', err))
          .finally(() => setFetchingDoctors(false));
      } else {
        setFetchedDoctors(facility?.doctors || []);
      }
    }
  }, [open, doctor, facility]);

  const currentDoc = selectedDoctor || doctor || null;

  // Discreet: sensitive specializations render neutral copy automatically.
  const categorySensitive = isSensitiveCategory(currentDoc?.specialization);
  const discreet = discreetMode || categorySensitive;
  const discreetTitle = (original: string) =>
    discreet ? neutralText(original, { category: currentDoc?.specialization, discreet: true, kind: 'appointment' }) : original;

  // Slot-hold countdown stub: (re)start on slot select, clear on change/unmount.
  useEffect(() => {
    if (!bookingTime) { setSlotHoldLeft(null); return; }
    setSlotHoldLeft(SLOT_HOLD_SECONDS);
    const t = setInterval(() => {
      setSlotHoldLeft((s) => {
        if (s == null || s <= 1) { clearInterval(t); return 0; }
        return s - 1;
      });
    }, 1000);
    return () => clearInterval(t);
  }, [bookingTime]);

  const isOnlineMode = ['chat', 'video', 'audio', 'call', 'voice'].includes(appointmentMode);
  const isAutoConfirm = isOnlineMode
    ? (currentDoc?.autoConfirmAppointment === true)
    : (currentDoc?.autoConfirmAppointment ?? facility?.settings?.autoConfirmAppointment ?? true);

  // Compute fee based on selected appointment mode
  const getModeBasedFee = (mode: Unmodelled, doc: Unmodelled) => {
    if (!doc) return 0;
    const fees = doc.appointmentFees || {};
    if (mode === 'chat') return Number(fees.chat || doc.chat_fee || doc.consultation_fees || doc.fees || 0);
    if (mode === 'video') return Number(fees.video || doc.video_fee || doc.consultation_fees || doc.fees || 0);
    if (mode === 'audio' || mode === 'call' || mode === 'voice') return Number(fees.audio || fees.call || doc.audio_fee || doc.voice_fee || fees.video || doc.video_fee || doc.consultation_fees || doc.fees || 0);
    if (mode === 'home_visit' || mode === 'home') return Number(fees.home_visit || doc.home_visit_fee || doc.consultation_fees || doc.fees || 0);
    return Number(fees.offline || doc.offline_fee || doc.consultation_fees || doc.fees || 0);
  };
  // Fallback multipliers for counsellor/psychiatrist jab appointmentFees set nahi hai
  const MODE_FALLBACK_MULT: Unmodelled = { video: 1, audio: 0.8, call: 0.8, voice: 0.8, chat: 0.6, offline: 1, home_visit: 1.2, home: 1.2 };
  const hasExplicitModeFees = !!(currentDoc?.appointmentFees?.video || currentDoc?.appointmentFees?.chat || currentDoc?.appointmentFees?.audio || currentDoc?.video_fee || currentDoc?.chat_fee || currentDoc?.audio_fee);
  const getResolvedModeFee = (mode: Unmodelled, doc: Unmodelled) => {
    if (!doc) return 0;
    if (hasExplicitModeFees) return getModeBasedFee(mode, doc);
    const base = Number(doc?.consultation_fees || doc?.fees || doc?.sessionPricing || 800) || 800;
    const mult = MODE_FALLBACK_MULT[mode] ?? 1;
    return Math.round(base * mult);
  };
  const currentFee = getResolvedModeFee(appointmentMode, currentDoc);

  // ---- Mind packages (counsellor/psychiatrist ke supportPlanPrices se) ----
  // Sirf packages dikhte hain + har package par (i) button se complete details.
  const PLAN_META: Unmodelled = {
    shortTerm: { name: 'Short-Term Pack', sessions: 4, validity: '30 days', desc: '4 sessions — stress, anxiety, exam pressure ke liye.' },
    mediumTerm: { name: 'Medium-Term Pack', sessions: 8, validity: '60 days', desc: '8 sessions — recovery aur personal growth ke liye.' },
    longTerm: { name: 'Long-Term Pack', sessions: 12, validity: '90 days', desc: '12 sessions — lambi therapy aur steady progress ke liye.' },
  };
  const providerPlans = useMemo(() => {
    const doc = currentDoc;
    if (!doc) return [];
    const spp = doc.supportPlanPrices || {};
    const plans = [];
    // Custom packages (counsellor ke apne) sabse pehle
    const customs = Array.isArray(doc.customPackages) ? doc.customPackages.filter((c: Unmodelled) => c && c.isActive !== false) : [];
    for (const c of customs) {
      const price = Number(c.price ?? c.bookingPrice ?? c.perSessionPrice ?? 0);
      if (!price || price <= 0) continue;
      plans.push({
        id: `custom:${c._id || c.id || c.name}`,
        name: c.name || 'Custom Pack',
        sessions: Number(c.sessions ?? c.sessionsTotal ?? 1) || 1,
        validity: c.validity || c.duration || 'As agreed',
        price,
        desc: c.description || c.summary || '',
        modes: c.modes || doc.appointmentModes || [],
        raw: c,
      });
    }
    for (const key of Object.keys(PLAN_META)) {
      const price = Number(spp[key] ?? 0);
      if (!price || price <= 0) continue;
      plans.push({ id: key, price, modes: doc.appointmentModes || [], ...PLAN_META[key] });
    }
    // Fallback: counsellor/psychiatrist Doctor doc me supportPlanPrices nahi bhi ho tab bhi packages dikhao
    if (plans.length === 0 && doc) {
      const spec = String(doc.specialization || '').toLowerCase();
      const isMindProvider = spec.includes('counsell') || spec.includes('psychiatr') || spec.includes('psycholog');
      if (isMindProvider) {
        const base = Number(doc.consultation_fees || doc.fees || 800) || 800;
        const fallback: Unmodelled = {
          shortTerm: Math.round(base * 4 * 0.85),
          mediumTerm: Math.round(base * 8 * 0.75),
          longTerm: Math.round(base * 12 * 0.70),
        };
        for (const key of Object.keys(PLAN_META)) {
          plans.push({ id: key, price: fallback[key], modes: doc.appointmentModes || [], ...PLAN_META[key] });
        }
      }
    }
    return plans;
  }, [currentDoc]);
  // ── Mode pe package price change: Video = base, Audio/Chat ka ratio se scale ──
  const basePackageFee = useMemo(() => {
    if (hasExplicitModeFees) return Number(currentDoc?.appointmentFees?.video || currentDoc?.video_fee || 500) || 500;
    return Number(currentDoc?.consultation_fees || currentDoc?.fees || currentDoc?.sessionPricing || 800) || 800;
  }, [currentDoc, hasExplicitModeFees]);
  const modeFeeRatio = useMemo(() => {
    if (hasExplicitModeFees) {
      const mf = getModeBasedFee(appointmentMode, currentDoc);
      const vf = Number(currentDoc?.appointmentFees?.video || currentDoc?.video_fee || basePackageFee) || basePackageFee || 1;
      if (!mf || !vf) return 1;
      return mf / vf;
    }
    return MODE_FALLBACK_MULT[appointmentMode] ?? 1;
  }, [appointmentMode, currentDoc, basePackageFee, hasExplicitModeFees]);
  const getAdjustedPrice = (basePrice: Unmodelled) => Math.max(0, Math.round(Number(basePrice || 0) * modeFeeRatio));
  const adjustedProviderPlans = useMemo(() => providerPlans.map(p => {
    const adj = getAdjustedPrice(p.price);
    return { ...p, displayPrice: adj, perSessionDisplay: p.sessions > 0 ? Math.round(adj / p.sessions) : adj, originalPrice: p.price };
  }), [providerPlans, modeFeeRatio]);
  const hasPackages = providerPlans.length > 0;
  const selectedPackageBase = selectedPackageId === 'single' ? null : (providerPlans.find(p => p.id === selectedPackageId) || null);
  const selectedPackage = selectedPackageId === 'single' ? null : (adjustedProviderPlans.find(p => p.id === selectedPackageId) || null);
  // Single session fee bhi mode-aware (counsellor ke liye bhi video < chat < audio alag)
  const singleFee = currentFee || Number(currentDoc?.consultation_fees || currentDoc?.fees || 0);
  const effectiveFee = hasPackages ? (selectedPackage ? selectedPackage.displayPrice : singleFee) : currentFee;

  const isHospital = useMemo(() => {
    if (facility?.type === 'hospital') return true;
    if (facility?.type === 'clinic') return false;
    if (currentDoc?.hospitalId) return true;
    if (currentDoc?.clinicId) return false;
    if (currentDoc?.role === 'doctor') return true;
    if (currentDoc?.role === 'clinic_doctor') return false;
    if (facility?.name && /hospital/i.test(facility.name)) return true;
    if (facility?.name && /clinic/i.test(facility.name)) return false;
    return false;
  }, [facility, currentDoc]);

  const offlineLabel = isHospital ? 'In Hospital' : 'In Clinic';
  const offlineDesc = isHospital ? 'Hospital visit' : 'Clinic visit';
  const offlineConsultationType = isHospital ? 'In Hospital Consultation' : 'In Clinic Consultation';
  const offlineFeeName = isHospital ? 'In Hospital' : 'In Clinic';

  // Available modes from the doctor (fallback to all 5)
  const availableModes = (currentDoc?.appointmentModes && currentDoc.appointmentModes.length > 0)
    ? currentDoc.appointmentModes
    : ['offline', 'home_visit', 'video', 'audio', 'chat'];

  // Doctor + date change hone par uske already-booked slots fetch karo WITH COUNTS
  useEffect(() => {
    if (!currentDoc?._id || !bookingDate) { setBookedSlots([]); setLockedSlots([]); setSlotCounts({}); setDateDisabledSlots([]); setPendingDisabledSlots([]); setBookingWindow(null); return; }
    api.getBookedSlots({ doctorId: currentDoc._id, date: bookingDate })
      .then(res => {
        if (res && typeof res === 'object' && !Array.isArray(res) && res.counts) {
          setSlotCounts(res.counts || {});
          setBookedSlots(res.fullSlots || Object.keys(res.counts || {}));
          setLockedSlots(res.lockedSlots || []);
          setDateDisabledSlots(res.dateDisabled || []);
          setPendingDisabledSlots(res.pendingDisabledSlots || []);
          setBookingWindow(res.bookingWindow || null);
        } else {
          const arr = Array.isArray(res) ? res : [];
          setBookedSlots(arr);
          setLockedSlots([]);
          const counts: Unmodelled = {};
          arr.forEach(s => { counts[s] = (counts[s] || 0) + 1; });
          setSlotCounts(counts);
          setDateDisabledSlots([]);
          setPendingDisabledSlots([]);
          setBookingWindow(null);
        }
      })
      .catch(() => { setBookedSlots([]); setLockedSlots([]); setSlotCounts({}); setDateDisabledSlots([]); setPendingDisabledSlots([]); setBookingWindow(null); });
  }, [currentDoc?._id, bookingDate, currentDoc?.maxBookingsPerSlot]);

  const isSlotFull = (time: Unmodelled) => {
    const bookedCount = slotCounts[time] || 0;
    return bookedCount >= 1;
  };

  const isSlotLocked = (time: Unmodelled) => {
    return lockedSlots.includes(time) && bookingTime !== time;
  };

  const handleSelectSlot = async (t: Unmodelled) => {
    if (t === bookingTime) return;
    if (isSlotLocked(t)) {
      toast.error(`Slot ${t} is currently being booked by another patient. Please select another.`);
      return;
    }
    if (user && currentDoc?._id && bookingDate) {
      setLockingSlot(true);
      try {
        if (bookingTime) {
          api.releaseAppointmentSlot({ doctorId: currentDoc._id, date: bookingDate, time: bookingTime }).catch(() => {});
        }
        const lockRes = await api.lockAppointmentSlot({ doctorId: currentDoc._id, date: bookingDate, time: t });
        if (lockRes && !lockRes.success && lockRes.lockedByOther) {
          toast.error(lockRes.message || 'This slot is currently being booked by another patient.');
          setLockingSlot(false);
          return;
        }
      } catch (err: any) {
        console.warn('Slot lock failed', err);
      } finally {
        setLockingSlot(false);
      }
    }
    setBookingTime(t);
  };

  // APPT-M-01: a full slot can be queued instead of dead-ended. The server
  // refuses if the slot is actually free, the patient already holds a seat, or
  // they are already queued - all of which are self-explanatory 4xx copies.
  const handleJoinWaitlist = async () => {
    if (!currentDoc) { toast.error('No doctor selected'); return; }
    if (!bookingDate || !bookingTime) { toast.error('Please select date and time'); return; }
    setWaitlistLoading(true);
    try {
      await api.joinWaitlist({ doctorId: currentDoc._id, date: bookingDate, time: bookingTime });
      toast.success("You're on the waitlist. We'll alert you the moment this slot opens (15 minutes to claim it).");
    } catch (err: any) {
      toast.error(userFacingError(err));
    } finally {
      setWaitlistLoading(false);
    }
  };

  const handleProceedToPayment = () => {
    if (processingRef.current) return;
    if (!currentDoc) { toast.error('No doctor selected'); return; }
    if (!user) { toast.error('Please login to book an appointment'); navigate('/login'); return; }

    // Validate inputs
    if (!bookingDate || !bookingTime) { toast.error('Please select date and time'); return; }

    // Check if slot is full
    if (isSlotFull(bookingTime)) {
      toast.error('This time slot is full. Please choose a different time.');
      return;
    }

    // consultation/package price must be a valid positive number
    if (!effectiveFee || effectiveFee <= 0) {
      toast.error('Doctor consultation fee is not set. Please contact support.');
      return;
    }
    setBookingDetails({ doctor: currentDoc.name, specialization: currentDoc.specialization, date: bookingDate, time: bookingTime, fees: effectiveFee, mode: appointmentMode, packageId: selectedPackage?.id || '', packageName: selectedPackage?.name || '' });

    setBookingStep(1); // Package & Mode already selected in Quick booking (step 0) for counsellor/psychiatrist
  };

  const handlePayment = async () => {
    if (processingRef.current) return;
    if (!currentDoc) { toast.error('No doctor selected'); return; }
    if (!user) { toast.error('Please login to book an appointment'); navigate('/login'); return; }

    // APPT-M-02: a recurring series is booked as N real appointments, each paid
    // through the existing referenceId checkout so every occurrence gets its
    // own payment/billing rows and auto-confirms. A package is already the
    // multi-session product - never stack a repeat pattern on top of one.
    if (repeatFreq !== 'none' && !selectedPackage) {
      processingRef.current = true;
      setPaymentLoading(true);
      try {
        const fees = effectiveFee;
        if (!fees || fees <= 0) throw new Error('Doctor consultation fee is not set. Please contact support.');
        const type = appointmentMode === 'chat'
          ? 'Chat Consultation'
          : appointmentMode === 'video'
          ? 'Video Consultation'
          : appointmentMode === 'audio' || appointmentMode === 'call' || appointmentMode === 'voice'
          ? 'Audio Call Consultation'
          : appointmentMode === 'home_visit' || appointmentMode === 'home'
          ? 'Home Visit Consultation'
          : offlineConsultationType;
        const seriesRes = await api.createAppointmentSeries({
          doctorId: currentDoc._id,
          date: bookingDate,
          time: bookingTime,
          frequency: repeatFreq,
          count: repeatCount,
          feesPerOccurrence: fees,
          appointmentMode,
          type,
          department: currentDoc.specialization || 'General',
          notes: bookingNotes,
        });
        let lastPay: any = null;
        let paidCount = 0;
        try {
          for (const occ of seriesRes.appointments) {
            lastPay = await api.payTransaction({
              serviceType: 'appointment',
              amount: fees,
              method: paymentMethod,
              referenceId: occ._id,
              description: `Consultation with ${currentDoc.name} (${occ.date})`,
              provider: facility?.name || currentDoc.name,
              lineItems: [{ name: `Consultation Fee ${occ.date}`, price: fees, qty: 1 }],
            });
            paidCount += 1;
          }
        } catch (payErr: any) {
          // Partial: the series and the paid visits are real; unpaid children
          // die via the existing 15-minute sweeps, exactly like an abandoned
          // single checkout. Say so instead of pretending the booking failed.
          toast.error(`Series saved - ${paidCount} of ${seriesRes.appointments.length} visits paid. ${userFacingError(payErr)} Unpaid visits expire in 15 minutes; cancel the rest from My Appointments.`);
          if (onSuccess) onSuccess();
          return;
        }
        toast.success(`Recurring series booked: ${paidCount} visits confirmed.`);
        setBookingDetails({
          ...seriesRes.appointments[0],
          doctor: currentDoc.name,
          specialization: currentDoc.specialization,
          date: bookingDate,
          time: bookingTime,
          fees: fees * paidCount,
          transactionId: lastPay?.transaction_id,
          invoiceId: lastPay?.invoice_id,
          appointmentStatus: 'Confirmed',
        });
        setBookingStep(5);
        if (onSuccess) onSuccess();
      } catch (e: any) {
        toast.error(userFacingError(e));
      } finally {
        setPaymentLoading(false);
        processingRef.current = false;
      }
      return;
    }

    processingRef.current = true;
    setPaymentLoading(true);

    let apptId = null;

    try {
      // Pre-check: confirm slot is still available before processing payment
      try {
        const slotCheck = await api.getBookedSlots({ doctorId: currentDoc._id, date: bookingDate });
        const counts = (slotCheck && slotCheck.counts) ? slotCheck.counts : {};
        if ((counts[bookingTime] || 0) >= 1) {
          toast.error('This slot is already booked. Please try another slot.');
          setBookingTime('');
          setBookingStep(0);
          setSlotCounts(counts);
          setBookedSlots(slotCheck.fullSlots || Object.keys(counts));
          setDateDisabledSlots(slotCheck.dateDisabled || []);
          setBookingLoading(false);
          processingRef.current = false;
          return;
        }
      } catch (_: any) { /* proceed even if check fails — server will catch duplicates */ }

      const fees = effectiveFee;
      if (!fees || fees <= 0) {
        throw new Error('Doctor consultation fee is not set. Please contact support.');
      }

      const payResult = await api.payTransaction({
        serviceType: 'appointment',
        appointment: {
          doctorId: currentDoc._id,
          doctor: currentDoc.name,
          doctorName: currentDoc.name,
          department: currentDoc.specialization || 'General',
          facilityId: facility?._id || currentDoc.clinicProfile?.clinic_id,
          date: bookingDate,
          time: bookingTime,
          notes: bookingNotes,
          type: appointmentMode === 'chat'
            ? 'Chat Consultation'
            : appointmentMode === 'video'
            ? 'Video Consultation'
            : appointmentMode === 'audio' || appointmentMode === 'call' || appointmentMode === 'voice'
            ? 'Audio Call Consultation'
            : appointmentMode === 'home_visit' || appointmentMode === 'home'
            ? 'Home Visit Consultation'
            : offlineConsultationType,
          appointmentMode,
          bookingFor: bookingFor,
          familyMemberId: bookingFor === 'family' ? selectedFamilyMember?._id : undefined,
          familyMemberName: bookingFor === 'family' ? selectedFamilyMember?.name : undefined,
          otherPatientDetails: bookingFor === 'other' ? otherPatient : undefined,
          guardianConsent: bookingFor !== 'self' ? guardianConsent : undefined,
          preConsultationDetails: intakeFormData,
          packageId: selectedPackage?.id || '',
          packageName: selectedPackage?.name || '',
          packageSessions: selectedPackage?.sessions || 0,
        },
        amount: fees,
        method: paymentMethod,
        description: selectedPackage ? `${selectedPackage.name} with ${currentDoc.name}` : `Consultation with ${currentDoc.name}`,
        provider: facility?.name || currentDoc.name,
        lineItems: [{
          name: selectedPackage
            ? `${selectedPackage.name} (${selectedPackage.sessions} session${selectedPackage.sessions > 1 ? 's' : ''})`
            : `${
            appointmentMode === 'chat'
              ? 'Chat'
              : appointmentMode === 'video'
              ? 'Video'
              : appointmentMode === 'audio' || appointmentMode === 'call' || appointmentMode === 'voice'
              ? 'Audio Call'
              : appointmentMode === 'home_visit' || appointmentMode === 'home'
              ? 'Home Visit'
              : offlineFeeName
          } Consultation Fee`,
          price: fees,
          qty: 1
        }],
      });

      if (!payResult?.success) {
        throw new Error(payResult?.message || 'Payment failed');
      }

      const appointmentStatus = payResult.appointmentStatus || 'Confirmed';
      const appointmentData = payResult.appointment || {};
      apptId = appointmentData._id || '';

      toast.success(appointmentStatus === 'Confirmed' ? 'Payment successful! Appointment confirmed.' : 'Payment successful! Awaiting clinic confirmation.');
      setBookingDetails({
        ...appointmentData,
        doctor: currentDoc.name,
        specialization: currentDoc.specialization,
        date: bookingDate,
        time: bookingTime,
        fees,
        transactionId: payResult.transaction_id,
        invoiceId: payResult.invoice_id,
        appointmentStatus,
      });
      setBookingStep(5);
      if (onSuccess) onSuccess();

    } catch (e: any) {
      const msg = userFacingError(e, { fallback: '' });
      const status = e.response?.status;
      // Already-paid idempotency case — treat as success
      if (status === 200 && msg.includes('already be completed')) {
        toast.success('Appointment already booked');
        setBookingStep(5);
        if (onSuccess) onSuccess();
      } else if (status === 409) {
        toast.error(msg || 'This slot is already booked. Please pick a different time.');
        // Force back to slot-selection step so the user can't accidentally
        // resubmit the exact same (now-confirmed) date/time again.
        setBookingTime('');
        setBookingStep(0);
        // Refresh booked slots for this doctor/date so the taken slot
        // shows as disabled immediately, instead of only failing on submit.
        if (currentDoc?._id && bookingDate) {
          api.getBookedSlots({ doctorId: currentDoc._id, date: bookingDate })
            .then(res => {
                if (res && typeof res === 'object' && !Array.isArray(res) && res.counts) {
                  setSlotCounts(res.counts || {});
                  setBookedSlots(res.fullSlots || Object.keys(res.counts || {}));
                  setDateDisabledSlots(res.dateDisabled || []);
                  setPendingDisabledSlots(res.pendingDisabledSlots || []);
                  setBookingWindow(res.bookingWindow || null);
                } else {
                  const arr = Array.isArray(res) ? res : [];
                  setBookedSlots(arr);
                  const counts: Unmodelled = {};
                  arr.forEach(s => { counts[s] = (counts[s] || 0) + 1; });
                  setSlotCounts(counts);
                  setDateDisabledSlots([]);
                  setPendingDisabledSlots([]);
                }
            })
            .catch(() => {});
        }
      } else {
        toast.error(msg || 'Booking failed');
        if (apptId) {
          try { await api.deleteAppointment(apptId); } catch (_: any) {}
        }
      }
    }
    setPaymentLoading(false);
    processingRef.current = false;
  };

  // ─── Slot helpers: group flat time_slots into hours + build time ranges ───
  const slotDuration = currentDoc?.slotDuration || 15;

  // Max bookable date from doctor's booking window (e.g. 2 weeks from today)
  const maxBookableDate = useMemo(() => {
    const bw = bookingWindow;
    if (!bw || typeof bw.value !== 'number' || bw.value <= 0 || !bw.unit) return null;
    const d = new Date();
    switch (bw.unit) {
      case 'hours': d.setHours(d.getHours() + bw.value); break;
      case 'days': d.setDate(d.getDate() + bw.value); break;
      case 'weeks': d.setDate(d.getDate() + bw.value * 7); break;
      case 'months': d.setMonth(d.getMonth() + bw.value); break;
      default: return null;
    }
    const yy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yy}-${mm}-${dd}`;
  }, [bookingWindow]);

  // "09:15 AM" -> minutes since midnight (e.g. 555)
  const slotToMinutes = (t: Unmodelled) => {
    const m = t?.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
    if (!m) return null;
    let h = parseInt(m[1], 10) % 12;
    if (/PM/i.test(m[3])) h += 12;
    return h * 60 + parseInt(m[2], 10);
  };

  // minutes since midnight -> "9:15 AM"
  const minutesToSlot = (mins: Unmodelled) => {
    const h = Math.floor(mins / 60) % 24;
    const mm = mins % 60;
    const ampm = h >= 12 ? 'PM' : 'AM';
    let h12 = h % 12; if (h12 === 0) h12 = 12;
    return `${h12}:${String(mm).padStart(2, '0')} ${ampm}`;
  };

  // minutes -> short "9:00" for range display
  const minutesToShort = (mins: Unmodelled) => {
    const h = Math.floor(mins / 60) % 24;
    const mm = mins % 60;
    let h12 = h % 12; if (h12 === 0) h12 = 12;
    return `${h12}:${String(mm).padStart(2, '0')}`;
  };

  // Is a slot disabled for this specific date by the doctor in My Schedule?
  const isSlotDisabled = (slotStr: Unmodelled) => dateDisabledSlots.includes(slotStr);

  // Is a slot pending removal (doctor requested to disable it, awaiting admin approval)?
  const isSlotPendingUpdate = (slotStr: Unmodelled) => pendingDisabledSlots.includes(slotStr);

  // Group all time_slots (enabled + date-disabled + pending-disabled) into hours.
  const hourGroups = useMemo(() => {
    const enabledSlots = currentDoc?.time_slots || [];
    const allSlots = [...enabledSlots,
      ...dateDisabledSlots.filter(s => !enabledSlots.includes(s)),
      ...pendingDisabledSlots.filter(s => !enabledSlots.includes(s) && !dateDisabledSlots.includes(s))];
    // Fallback if nothing
    const slots = allSlots.length > 0 ? allSlots : ['09:00 AM', '10:00 AM', '11:00 AM', '02:00 PM', '03:00 PM', '04:00 PM'];
    const groups: Record<string, string[]> = {};
    slots.forEach(t => {
      const mins = slotToMinutes(t);
      if (mins == null) return;
      const h24 = Math.floor(mins / 60) % 24;
      let h12 = h24 % 12; if (h12 === 0) h12 = 12;
      const key = `${h12} ${h24 >= 12 ? 'PM' : 'AM'}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(t);
    });
    return Object.entries(groups).sort((x: Unmodelled, y: Unmodelled) => (slotToMinutes(x[1]?.[0]) as Unmodelled) - (slotToMinutes(y[1]?.[0]) as Unmodelled));
  }, [currentDoc?.time_slots, dateDisabledSlots]);

  // Range string for a slot: "9:00–9:15"
  const rangeFor = (slotStr: Unmodelled) => {
    const start = slotToMinutes(slotStr);
    if (start == null) return slotStr;
    const end = start + slotDuration;
    return `${minutesToShort(start)}–${minutesToShort(end)}`;
  };

  const fullRangeFor = (slotStr: Unmodelled) => {
    const start = slotToMinutes(slotStr);
    if (start == null) return slotStr;
    const end = start + slotDuration;
    return `${minutesToSlot(start)} – ${minutesToSlot(end)}`;
  };

  return (
    <>
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[580px] md:max-w-[620px] max-h-[90vh] overflow-y-auto w-[calc(100%-2rem)] sm:w-full rounded-2xl">
        {bookingStep === -1 && (
          <>
            <DialogHeader>
              <DialogTitle>Select Doctor</DialogTitle>
              <DialogDescription>
                Choose a doctor at {facility?.name || 'this facility'}
              </DialogDescription>
            </DialogHeader>
            <div className="py-2 space-y-3">
              {fetchingDoctors ? (
                <div className="text-center text-sm text-muted-foreground py-6">Loading doctors...</div>
              ) : fetchedDoctors.length > 0 ? (
                fetchedDoctors.map((doc, idx) => (
                <motion.div
                  key={doc._id || idx}
                  whileHover={{ scale: 1.02 }}
                  className="p-3 rounded-xl border border-border/50 bg-card hover:border-primary/40 cursor-pointer"
                  onClick={() => { setSelectedDoctor(doc); setBookingStep(0); }}
                >
                  <div className="flex items-start gap-3">
                    <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center shrink-0">
                      <span className="text-primary-foreground font-bold text-xs">{doc.name?.split(' ').map((n: Unmodelled)=>n[0]).join('').slice(0,2) || 'DR'}</span>
                    </div>
                    <div className="min-w-0 flex-1">
                      <h3 className="font-heading font-semibold text-sm text-foreground truncate">{doc.name}</h3>
                      <p className="text-xs font-medium text-primary mt-0.5">{doc.specialization}</p>
                      <div className="flex items-center gap-2 mt-1.5">
                        <span className="text-xs text-muted-foreground">{doc.experience || `${doc.experienceYears || 0} yrs`}</span>
                        <span className="text-xs text-muted-foreground">•</span>
                        <span className="text-xs font-medium text-primary">₹{doc.fees || doc.consultation_fees || 0}</span>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4 text-muted-foreground self-center" />
                  </div>
                </motion.div>
              ))
              ) : (
                <div className="text-center text-sm text-muted-foreground py-6">No doctors available.</div>
              )}
            </div>
            <DialogFooter>
              <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>Cancel</Button>
            </DialogFooter>
          </>
        )}

        {bookingStep === 0 && currentDoc && (
          <>
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                {!doctor && (
                  <Button variant="ghost" size="icon" className="w-7 h-7 -ml-1" onClick={() => setBookingStep(-1)}>
                    <ArrowLeft className="w-4 h-4" />
                  </Button>
                )}
                Book Appointment
              </DialogTitle>
              <DialogDescription>
                {discreetTitle(`Quick booking for ${facility?.name || 'Clinic'} - ${currentDoc?.name}`)}
              </DialogDescription>
            </DialogHeader>
            {/* Discreet-mode toggle: neutral text for sensitive categories */}
            <label className="flex items-center gap-2 text-xs text-muted-foreground px-0.5">
              <input type="checkbox" checked={discreetMode} onChange={(e) => setDiscreetMode(e.target.checked)} className="w-3.5 h-3.5" />
              Discreet mode (neutral labels &amp; notifications)
              {categorySensitive && <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted">auto-on: sensitive category</span>}
            </label>
            <div className="flex flex-col gap-3 py-2">
              <div className="flex items-center gap-2.5">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center shrink-0">
                  <span className="text-primary-foreground font-bold text-xs">{currentDoc?.name?.split(' ')?.map((n: Unmodelled)=>n?.[0])?.join('')?.slice(0,2) || 'DR'}</span>
                </div>
                <div className="min-w-0">
                  <h3 className="font-heading font-semibold text-foreground text-sm truncate">{currentDoc?.name}</h3>
                  <p className="text-xs text-primary">{currentDoc?.specialization}</p>
                  {isAutoConfirm ? (
                    <p className="text-[10px] text-muted-foreground mt-1">
                      Auto accept appointment is on
                    </p>
                  ) : (
                    <p className="text-[11px] text-amber-600 mt-1 font-medium">
                      ⚠️ You may have to wait for booking confirmation
                    </p>
                  )}
                </div>
              </div>
              {/* Appointment Mode Selector */}
              <div className={`space-y-2 ${hasPackages ? 'order-1' : 'order-1'}`}>
                <label className="text-xs font-semibold text-foreground">{hasPackages ? 'Modes Provided' : 'Mode of Appointment'}</label>
                <div className={`grid gap-2 ${availableModes.length === 1 ? 'grid-cols-1' : availableModes.length === 2 ? 'grid-cols-2' : availableModes.length === 3 ? 'grid-cols-3' : availableModes.length === 4 ? 'grid-cols-2 sm:grid-cols-4' : 'grid-cols-2 sm:grid-cols-5'}`}>
                  {[
                    { key: 'offline', label: offlineLabel, desc: offlineDesc, Icon: MapPin, color: 'text-violet-600', activeBg: 'border-violet-500 bg-violet-50 dark:bg-violet-500/10' },
                    { key: 'home_visit', label: 'Home Visit', desc: 'At Home', Icon: Home, color: 'text-amber-600', activeBg: 'border-amber-500 bg-amber-50 dark:bg-amber-500/10' },
                    { key: 'video', label: 'Video Call', desc: 'Live Video', Icon: Video, color: 'text-emerald-600', activeBg: 'border-emerald-500 bg-emerald-50 dark:bg-emerald-500/10' },
                    { key: 'audio', label: 'Audio Call', desc: 'Voice Call', Icon: Phone, color: 'text-teal-600', activeBg: 'border-teal-500 bg-teal-50 dark:bg-teal-500/10' },
                    { key: 'chat', label: 'Chat', desc: 'Text', Icon: MessageSquare, color: 'text-blue-600', activeBg: 'border-blue-500 bg-blue-50 dark:bg-blue-500/10' },
                  ].filter(m => availableModes.includes(m.key) || (m.key === 'home_visit' && availableModes.includes('home')) || (m.key === 'audio' && (availableModes.includes('audio') || availableModes.includes('call') || availableModes.includes('voice') || availableModes.includes('video')))).map(({ key, label, desc, Icon, color, activeBg }) => {
                    const active = appointmentMode === key || (key === 'home_visit' && appointmentMode === 'home') || (key === 'audio' && (appointmentMode === 'voice' || appointmentMode === 'call'));
                    const fee = getResolvedModeFee(key, currentDoc);
                    return (
                      <button key={key} type="button" onClick={() => setAppointmentMode(key)}
                        className={`relative flex flex-col items-center gap-1.5 py-3 px-2.5 rounded-xl border-2 text-center transition-all ${
                          active ? activeBg + ' shadow-sm' : 'border-border/60 bg-card hover:border-primary/30'
                        }`}>
                        {active && (
                          <div className="absolute top-1.5 right-1.5 w-4 h-4 rounded-full bg-primary flex items-center justify-center">
                            <svg className="w-2.5 h-2.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}><path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" /></svg>
                          </div>
                        )}
                        <Icon className={`w-4 h-4 ${active ? color : 'text-muted-foreground'}`} />
                        <p className={`text-[11px] font-semibold leading-none ${active ? color : 'text-foreground'}`}>{label}</p>
                        {hasPackages ? (
                          <p className={`text-[10px] ${active ? 'text-foreground' : 'text-muted-foreground'}`}>{desc}</p>
                        ) : (
                          <p className={`text-[10px] font-bold ${active ? 'text-foreground' : 'text-muted-foreground'}`}>
                            {fee > 0 ? `₹${fee}` : 'Free'}
                          </p>
                        )}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Package selection — sirf counsellor/psychiatrist (jinke packages hain) */}
              {hasPackages && (
                <div className="space-y-2 rounded-xl border border-primary/20 bg-primary/[0.03] p-3 order-2">
                  <div className="flex items-center gap-1.5">
                    <PackageIcon className="w-3.5 h-3.5 text-primary" />
                    <label className="text-xs font-semibold text-foreground">Select Package <span className="font-normal text-muted-foreground">(optional)</span></label>
                  </div>
                  <div className="space-y-1.5">
                    <button key="single" type="button" onClick={() => setSelectedPackageId('single')}
                      className={`w-full flex items-center gap-2 px-3 py-2 rounded-xl border-2 text-left transition-all ${selectedPackageId === 'single' ? 'border-primary bg-primary/5 shadow-sm' : 'border-border/60 bg-card hover:border-primary/30'}`}>
                      <span className={`w-4 h-4 rounded-full border-2 flex items-center justify-center shrink-0 ${selectedPackageId === 'single' ? 'border-primary' : 'border-muted-foreground/40'}`}>
                        {selectedPackageId === 'single' && <span className="w-2 h-2 rounded-full bg-primary" />}
                      </span>
                      <span className="flex-1 min-w-0">
                        <span className="block text-xs font-semibold text-foreground">Single Session</span>
                        <span className="block text-[10px] text-muted-foreground">Sirf ye wali appointment</span>
                      </span>
                      <span className="text-xs font-bold text-primary shrink-0">₹{hasPackages ? (singleFee || 0) : (currentFee || 0)}</span>
                    </button>
                    {adjustedProviderPlans.map((p) => {
                      const active = selectedPackageId === p.id;
                      return (
                        <div key={p.id} className={`w-full flex items-center gap-2 px-3 py-2 rounded-xl border-2 text-left transition-all ${active ? 'border-primary bg-primary/5 shadow-sm' : 'border-border/60 bg-card hover:border-primary/30'}`}>
                          <button type="button" onClick={() => setSelectedPackageId(active ? 'single' : p.id)} className="flex items-center gap-2 flex-1 min-w-0 text-left">
                            <span className={`w-4 h-4 rounded-full border-2 flex items-center justify-center shrink-0 ${active ? 'border-primary' : 'border-muted-foreground/40'}`}>
                              {active && <span className="w-2 h-2 rounded-full bg-primary" />}
                            </span>
                            <span className="flex-1 min-w-0">
                              <span className="block text-xs font-semibold text-foreground truncate">{p.name}</span>
                              <span className="block text-[10px] text-muted-foreground">{p.sessions} session{p.sessions > 1 ? 's' : ''} • {p.validity} • ~₹{p.perSessionDisplay}/session</span>
                            </span>
                            <span className="text-xs font-bold text-primary shrink-0">₹{p.displayPrice}</span>
                          </button>
                          <button type="button" aria-label={`${p.name} details`} title="Package details"
                            onClick={() => setPackageInfoId(p.id)}
                            className="w-6 h-6 rounded-full border border-border bg-background flex items-center justify-center shrink-0 hover:border-primary hover:text-primary text-muted-foreground transition-colors">
                            <Info className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
              <div className={`grid grid-cols-2 gap-2 ${hasPackages ? 'order-3' : 'order-2'}`}>
                <div className="p-2 rounded-xl bg-primary/5 border border-primary/10 text-center">
                  <p className="text-[11px] text-muted-foreground mb-0.5">{selectedPackage ? 'Package Price' : 'Consultation Fee'}</p>
                  <p className="font-bold text-sm text-primary">₹{effectiveFee || 0}</p>
                  {hasPackages && <p className="text-[9px] text-muted-foreground mt-0.5">Mode ke hisaab se auto update</p>}
                </div>
                <div className="p-2 rounded-xl bg-emerald-50 border border-emerald-200 dark:bg-emerald-500/10 text-center">
                  <p className="text-[11px] text-muted-foreground mb-0.5">Avg Treatment Time</p>
                  <p className="font-semibold text-xs text-emerald-600">
                    {currentDoc?.slotDuration || 15} mins
                  </p>
                </div>
              </div>
              {!hasPackages && (
                <div className="space-y-1.5 order-3">
                  <label className="text-xs font-medium text-foreground">Select Date</label>
                  <Input type="date" className="w-full" value={bookingDate} onChange={e => setBookingDate(e.target.value)} min={getISTDateString()} max={maxBookableDate || undefined} />
                  {maxBookableDate && bookingWindow && (
                    <p className="text-[10px] text-muted-foreground">
                      📅 You can book up to <strong>{bookingWindow.value} {bookingWindow.unit}</strong> in advance ({maxBookableDate})
                    </p>
                  )}
                </div>
              )}
              {!hasPackages && (
                <div className="space-y-1.5 order-4">
                <div className="flex items-center justify-between">
                  <label className="text-xs font-medium text-foreground">Select Time Slot</label>
                  <span className="inline-flex items-center gap-1 text-[10px] font-medium text-primary bg-primary/10 px-2 py-0.5 rounded-md">
                    <Clock className="w-3 h-3" /> Avg {slotDuration} mins
                  </span>
                </div>

                {/* Step A: Hour selector dropdown */}
                <select value={selectedHour || ''} onChange={e => { setSelectedHour(e.target.value); setBookingTime(''); }} className="w-full h-9 px-3 rounded-xl border border-border bg-background text-sm">
                  <option value="">Choose hour</option>
                  {hourGroups.map(([hourLabel, hourSlots]) => {
                    const allUnavailable = hourSlots.every(s => isSlotFull(s) || isSlotDisabled(s) || isSlotPendingUpdate(s));
                    const avail = hourSlots.filter(s => !isSlotFull(s) && !isSlotDisabled(s) && !isSlotPendingUpdate(s)).length;
                    return (
                      <option key={hourLabel} value={hourLabel} disabled={allUnavailable}>
                        {hourLabel}{allUnavailable ? ' (Full)' : ''}
                      </option>
                    );
                  })}
                </select>

                {/* Step B: Sub-slot boxes for selected hour */}
                {selectedHour && (
                  <div className="space-y-2">
                    <p className="text-[11px] text-muted-foreground">
                      {(() => {
                        const hs = hourGroups.find(([h]) => h === selectedHour)?.[1] || [];
                        const unavailableCount = hs.filter(s => isSlotFull(s) || isSlotDisabled(s) || isSlotPendingUpdate(s)).length;
                        return `${hs.length - unavailableCount} of ${hs.length} slots available in ${selectedHour}`;
                      })()}
                    </p>
                    <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                      {(hourGroups.find(([h]) => h === selectedHour)?.[1] || []).map(t => {
                        const disabled = isSlotDisabled(t);
                        const pendingUpdate = isSlotPendingUpdate(t);
                        const full = isSlotFull(t);
                        const locked = isSlotLocked(t);
                        const unavailable = disabled || full || pendingUpdate || locked;
                        const selected = bookingTime === t;
                        return (
                          <button
                            key={t}
                            type="button"
                            disabled={unavailable || lockingSlot}
                            onClick={() => handleSelectSlot(t)}
                            className={`flex flex-col items-center gap-0.5 px-1.5 py-2 rounded-lg border text-center transition-all ${
                              selected
                                ? 'border-primary bg-primary text-primary-foreground shadow-sm ring-2 ring-primary/30'
                                : locked
                                ? 'border-amber-300 bg-amber-500/10 text-amber-700 dark:text-amber-300 cursor-not-allowed'
                                : unavailable
                                ? 'border-red-300 bg-red-500/10 text-red-600 dark:text-red-300 cursor-not-allowed'
                                : 'border-border bg-card text-foreground hover:border-primary/50 hover:bg-primary/5'
                            }`}
                          >
                            <span className="text-xs font-semibold">{rangeFor(t)}</span>
                            <span className={`text-[9px] leading-none font-medium ${selected ? 'text-primary-foreground/90' : 'text-muted-foreground'}`}>
                              {disabled
                                ? 'Disabled'
                                : pendingUpdate
                                ? 'Pending Update'
                                : full
                                ? 'Booked'
                                : locked
                                ? '🔒 In Booking'
                                : 'Available'}
                            </span>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}

                {/* Selected slot confirmation pill with full range + hold countdown stub */}
                {bookingTime && (
                  <div className="flex items-center gap-2 text-xs mt-1 flex-wrap">
                    <div className={`px-2 py-1 rounded-md ${isSlotFull(bookingTime) ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                      {isSlotFull(bookingTime) ? '⚠️ This slot is full' : '✅ Slot Available'}
                    </div>
                    <div className="px-2 py-1 rounded-md bg-primary/10 text-primary font-medium">
                      {fullRangeFor(bookingTime)}
                    </div>
                    {isSlotFull(bookingTime) && (
                      <Button size="sm" variant="outline" className="h-6 px-2 text-xs ml-auto" disabled={waitlistLoading} onClick={handleJoinWaitlist}>
                        {waitlistLoading ? 'Joining…' : 'Join waitlist'}
                      </Button>
                    )}
                    {!isSlotFull(bookingTime) && slotHoldLeft != null && (
                      <div className="px-2 py-1 rounded-md bg-amber-50 text-amber-700 border border-amber-200 font-medium" title="Slot-hold countdown stub — the server lock is authoritative">
                        ⏳ Hold {formatHoldCountdown(slotHoldLeft)}
                      </div>
                    )}
                  </div>
                )}
              </div>
              )}
              {!hasPackages && (
                <div className="space-y-1.5 order-5">
                  <label className="text-xs font-medium text-foreground">Notes (optional)</label>
                  <textarea value={bookingNotes} onChange={e => setBookingNotes(e.target.value)} placeholder="Any specific concerns…" className="w-full px-3 py-2 rounded-xl border border-border bg-background text-sm resize-none" rows={2} />
                </div>
              )}
              {!hasPackages && (
                <div className="space-y-1.5 order-6">
                  <label className="text-xs font-medium text-foreground">Repeat booking</label>
                  <div className="flex flex-wrap items-center gap-2">
                    <select
                      aria-label="Repeat frequency"
                      value={repeatFreq}
                      onChange={(e) => setRepeatFreq(e.target.value as typeof repeatFreq)}
                      className="h-9 px-2 rounded-xl border border-border bg-background text-sm"
                    >
                      <option value="none">Does not repeat</option>
