              ) : (
                <>
                <Gavel className="w-4 h-4" /> Send Urgent Request
              </>
            )}
          </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from 'react';
import { AlertTriangle, Clock } from 'lucide-react';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function LicenseExpiryReminder() {
  const { user } = useAuth();
  const [expiringLicenses, setExpiringLicenses] = useState<ApiRow[]>([]);

  useEffect(() => {
    if (!['superadmin', 'doctor', 'clinic_doctor', 'pharmacy_owner', 'lab_owner', 'hospital_admin', 'ambulance'].includes((user?.role || '') as string)) return;

    const checkLicenses = async () => {
      try {
        const { licenses } = await api.getLicenses();
        if (licenses && licenses.length > 0) {
          const now = new Date();
          const thirtyDaysFromNow = new Date();
          thirtyDaysFromNow.setDate(now.getDate() + 30);

          const expiring = licenses.filter((lic: Unmodelled) => {
            const expDate = new Date(lic.expiryDate);
            return lic.status === 'Active' && expDate <= thirtyDaysFromNow;
          });
          setExpiringLicenses(expiring);
        }
      } catch (err: any) {
        console.error('Failed to fetch licenses for expiry check', err);
      }
    };
    checkLicenses();
  }, [user]);

  if (expiringLicenses.length === 0) return null;

  return (
    <div className="mb-6 space-y-3">
      {expiringLicenses.map(lic => {
        const isExpired = new Date(lic.expiryDate) < new Date();
        return (
          <div key={lic._id} className={`p-4 rounded-xl border flex items-center gap-3 ${isExpired ? 'bg-destructive/10 border-destructive/20 text-destructive' : 'bg-warning/10 border-warning/20 text-warning-foreground'}`}>
            <AlertTriangle className="w-5 h-5 shrink-0" />
            <div className="flex-1">
              <h4 className="font-semibold">{lic.licenseType} {isExpired ? 'Expired' : 'Expiring Soon'}</h4>
              <p className="text-sm opacity-90">
                Your {lic.licenseType} ({lic.licenseNumber}) {isExpired ? 'expired on' : 'will expire on'} {new Date(lic.expiryDate).toLocaleDateString()}. Please renew it to avoid service interruption.
              </p>
            </div>
            <Clock className="w-5 h-5 shrink-0 opacity-50" />
          </div>
        );
      })}
    </div>
  );
}

import { Link } from 'react-router-dom';
import { Bell } from 'lucide-react';
import { api } from '@/lib/api';
import { useNotificationCount } from '@/context/NotificationContext';
import type { Unmodelled } from '@/lib/apiTypes';

export default function NotificationBell({ className = '', onClick }: any = {}) {
  const { count, refreshCount } = useNotificationCount();

  const handleClick = async (e: Unmodelled) => {
    if (onClick) onClick(e);
    try {
      const list = (await api.getNotifications({}))?.data || [];
      const unread = list.filter((n: Unmodelled) => !n.read).length;
      if (unread !== count) refreshCount();
    } catch (e: any) { console.error(e); }
  };

  return (
    <Link
      to="/notifications"
      aria-label="Notifications"
      onClick={handleClick}
      className={`relative flex items-center justify-center w-9 h-9 rounded-xl hover:bg-sidebar-accent transition-colors ${className}`}
    >
      <Bell className="w-[18px] h-[18px]" />
      {count > 0 && (
        <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
          {count > 99 ? '99+' : count}
        </span>
      )}
    </Link>
  );
}

