                >
                  <div className="flex items-center gap-3 mb-3">
                    <input
                      type="checkbox"
                      checked={!!checkedFields[key]}
                      onChange={() => toggleField(key)}
                      className="w-4 h-4 rounded border-border text-primary focus:ring-primary/30 cursor-pointer shrink-0"
                    />
                    <Icon className="w-4 h-4 text-primary shrink-0" />
                    <span className="text-sm font-semibold text-foreground flex-1">{label}</span>
                    {changed ? (
                      <Badge variant="outline" className="text-amber-600 border-amber-300 bg-amber-50 dark:bg-amber-500/10 text-[10px]">
                        Changed
                      </Badge>
                    ) : (
                      <Badge variant="outline" className="text-muted-foreground text-[10px]">
                        Unchanged
                      </Badge>
                    )}
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 ml-7">
                    <div>
                      <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Current</p>
                      <p className="text-sm font-medium text-muted-foreground break-words">{curVal}</p>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase tracking-wider text-primary mb-1">Requested</p>
                      <p className="text-sm font-medium text-primary break-words">{reqVal}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Admin notes */}
          <div className="border-t border-border/40 pt-4 space-y-3">
            <div>
              <label className="text-xs font-medium text-muted-foreground">Admin Note (optional)</label>
              <Input
                value={adminNote}
                onChange={e => setAdminNote(e.target.value)}
                placeholder="Add a note for the doctor..."
                className="mt-1"
              />
            </div>

            {/* Decision buttons */}
            <div className="flex items-center gap-3 pt-2">
              <Button
                variant={decision === 'reject' ? 'destructive' : 'outline'}
                onClick={() => setDecision('reject')}
                className="gap-2 flex-1"
              >
                <XCircle className="w-4 h-4" /> Reject
              </Button>
              <Button
                variant={decision === 'approve' ? 'default' : 'outline'}
                onClick={() => setDecision('approve')}
                className="gap-2 flex-1"
              >
                <CheckCircle className="w-4 h-4" /> Confirm {checkedCount > 0 ? `(${checkedCount})` : ''}
              </Button>
            </div>

            {/* Rejection reason (only if reject selected) */}
            {decision === 'reject' && (
              <div>
                <label className="text-xs font-medium text-destructive">Rejection Reason (optional)</label>
                <Input
                  value={rejectionNote}
                  onChange={e => setRejectionNote(e.target.value)}
                  placeholder="Why are you rejecting this request?"
                  className="mt-1"
                />
              </div>
            )}

            {/* Warning when approve with 0 checked */}
            {decision === 'approve' && checkedCount === 0 && fields.length > 0 && (
              <p className="text-xs text-amber-600 flex items-center gap-1">
                <AlertTriangle className="w-3 h-3" /> No fields selected — confirming will reject the request
              </p>
            )}

            {/* Submit */}
            <Button
              onClick={handleSubmit}
              disabled={submitting || !decision}
              className="w-full gap-2"
            >
              {submitting ? 'Processing...' : decision === 'approve' ? 'Apply Selected Changes' : 'Reject Request'}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { CheckCircle, XCircle } from 'lucide-react';
import type { Unmodelled } from '@/lib/apiTypes';

const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

/**
 * Convert a field's raw value into a short human-readable string.
 * Used by both the inline highlight and the review modal.
 *
 * @param {string} fieldKey  - e.g. 'bookingWindow', 'slotDuration', 'workingHours'
 * @param {any}    value     - the raw stored value
 * @returns {string}
 */
export function formatFieldValue(fieldKey: Unmodelled, value: Unmodelled) {
  if (value == null) return '—';
  switch (fieldKey) {
    case 'slotDuration':
      return `${value} min`;
    case 'bufferPerHour':
      return `${value} slot${value !== 1 ? 's' : ''}/hr`;
    case 'workingHours':
      return value && (value.start || value.end) ? `${value.start || '—'} – ${value.end || '—'}` : '—';
    case 'breakTime': {
      if (!value) return 'None';
      const has = value.start && value.end;
      return has ? `${value.start} – ${value.end}` : 'None';
    }
    case 'bookingWindow':
      return value && (value.value != null) ? `${value.value} ${value.unit || 'weeks'}` : '—';
    case 'weekly_schedule': {
      if (!value || typeof value !== 'object') return 'None set';
      const on = days.filter(d => value[d]);
      return on.length > 0 ? on.map(d => d.charAt(0).toUpperCase() + d.slice(1)).join(', ') : 'None set';
    }
    case 'leaves':
      return Array.isArray(value) && value.length > 0 ? value.join(', ') : 'None';
    case 'dateDisabledSlots': {
      if (!value || typeof value !== 'object') return 'None';
      const entries = Object.entries(value).filter(([, s]) => Array.isArray(s) && s.length > 0);
      if (entries.length === 0) return 'None';
      return entries.map(([d, s]: Unmodelled) => `${d} (${s.length})`).join(', ');
    }
    default:
      return String(value);
  }
}

/**
 * Highlighter-style badge shown next to a schedule field on the doctor's page
 * after their change request has been reviewed by the admin.
 *
 * - approved → blue highlighter, "Current Setting" label, `old → new`
 * - rejected → red highlighter, `old → new (not applied)`
 *
 * Black text inside per spec.
 */
export default function ScheduleFieldHighlight({ status, label, oldText, newText }: Unmodelled) {
  if (!status || (status !== 'approved' && status !== 'rejected')) return null;
  const isApproved = status === 'approved';

  return (
    <div className="mt-1.5">
      {isApproved && (
        <p className="text-[11px] font-bold text-black leading-tight mb-0.5">Current Setting</p>
      )}
      <div
        className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md border text-xs font-semibold text-black ${
          isApproved
            ? 'bg-blue-200/60 border-blue-400'
            : 'bg-red-200/60 border-red-400'
        }`}
      >
        {isApproved
          ? <CheckCircle className="w-3 h-3 text-blue-700 shrink-0" />
          : <XCircle className="w-3 h-3 text-red-700 shrink-0" />
        }
        <span>{oldText} → {newText}{!isApproved && ' (not applied)'}</span>
        {label && <span className="text-black/60 font-normal">· {label}</span>}
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { KeyRound, Lock, Unlock, ShieldCheck, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

/**
 * File 22 P2-31: idle-PIN lock + WebAuthn passkey management.
 * - Idle timer: after N minutes of no pointer/keyboard activity, locks.
 * - PIN: 4–8 digits, bcrypt-hashed server-side (never stored in state).
 * - Passkeys: WebAuthn registration/removal against /api/webauthn.
 */

const IDLE_MS = 5 * 60 * 1000; // 5 minutes
const ACTIVITY_EVENTS = ['pointerdown', 'keydown', 'wheel', 'touchstart'];

function genChallenge(bytes = 32) {
  const buf = new Uint8Array(bytes);
  crypto.getRandomValues(buf);
  return buf;
}

function b64url(buf: Unmodelled) {
  return btoa(String.fromCharCode(...new Uint8Array(buf)))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromB64url(s: Unmodelled) {
  const b = atob(s.replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from(b, (c) => c.charCodeAt(0));
}

export default function SecuritySection() {
  const [locked, setLocked] = useState(false);
  const [pinInput, setPinInput] = useState('');
  const [settingPin, setSettingPin] = useState(false);
  const [hasPasskey, setHasPasskey] = useState(false);
  const idleTimer = useRef<Unmodelled>(null);

  // ── Idle detection ─────────────────────────────────────────────────────
  const poke = useCallback(() => {
    if (locked) return;
    clearTimeout(idleTimer.current);
    idleTimer.current = setTimeout(() => setLocked(true), IDLE_MS);
  }, [locked]);

  useEffect(() => {
    ACTIVITY_EVENTS.forEach((e) => window.addEventListener(e, poke, { passive: true }));
    poke();
    return () => {
      ACTIVITY_EVENTS.forEach((e) => window.removeEventListener(e, poke));
      clearTimeout(idleTimer.current);
    };
  }, [poke]);

  // ── PIN set ────────────────────────────────────────────────────────────
  const setPin = async () => {
    if (!/^\d{4,8}$/.test(pinInput)) return;
    try {
      await api.setPin(pinInput);
      setPinInput('');
      setSettingPin(false);
      toast.success('PIN set — you will need it after idle');
    } catch { toast.error('Could not set PIN'); }
  };

  // ── PIN unlock ─────────────────────────────────────────────────────────
  const unlock = async () => {
    try {
      await api.unlockWithPin(pinInput);
      setPinInput('');
      setLocked(false);
      poke();
    } catch { toast.error('Wrong PIN'); }
  };

  // ── Passkey registration ───────────────────────────────────────────────
  const registerPasskey = async () => {
    try {
      const WebAuthnClient = ((await import('@simplewebauthn/browser')) as Unmodelled);
      const optsResp = await fetch('/api/webauthn/register/options', { credentials: 'include' });
      const opts = await optsResp.json();
      opts.user.id = b64url(fromB64url(opts.user.id));
      opts.challenge = fromB64url(opts.challenge);
      if (opts.excludeCredentials) {
        opts.excludeCredentials = opts.excludeCredentials.map((c: Unmodelled) => ({ ...c, id: fromB64url(c.id) }));
      }
      const att = await WebAuthnClient.startRegistration({ optionsJSON: opts });
      const verResp = await fetch('/api/webauthn/register/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(att),
      });
      const ver = await verResp.json();
      if (ver?.verified) {
        setHasPasskey(true);
        toast.success('Passkey added');
      }
    } catch { toast.error('Registration failed or was cancelled'); }
  };

  const removePasskey = async () => {
    try {
      await (api as Unmodelled).removePasskey();
      setHasPasskey(false);
      toast.success('Passkey removed');
    } catch { toast.error('Could not remove passkey'); }
  };

  if (locked) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-background/90 backdrop-blur-md">
        <div className="flex w-72 flex-col items-center gap-3 rounded-2xl border bg-card p-6 shadow-2xl">
          <Lock className="text-primary" size={32} />
          <h2 className="font-heading text-lg font-bold">Session locked</h2>
          <p className="text-center text-xs text-muted-foreground">Enter your PIN to continue</p>
          <Input
            type="password"
            inputMode="numeric"
            maxLength={8}
            placeholder="PIN"
            value={pinInput}
            onChange={(e) => setPinInput(e.target.value)}
            className="text-center text-lg tracking-widest"
            autoFocus
          />
          <Button onClick={unlock} className="w-full" disabled={!pinInput}>Unlock</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <h3 className="flex items-center gap-1.5 text-sm font-semibold">
        <ShieldCheck size={16} /> Security
      </h3>

      {/* PIN */}
      <div className="flex flex-wrap items-center gap-2 rounded-lg border p-3">
        <KeyRound size={16} className="text-muted-foreground" />
        <span className="text-xs font-medium">Idle PIN lock (5 min)</span>
        <span className="flex-1" />
        {!settingPin ? (
          <Button size="sm" variant="outline" onClick={() => setSettingPin(true)}>Set PIN</Button>
        ) : (
          <>
            <Input
              type="password"
              inputMode="numeric"
              maxLength={8}
              placeholder="4–8 digits"
              value={pinInput}
              onChange={(e) => setPinInput(e.target.value)}
              className="h-8 w-32 text-xs"
              autoFocus
            />
            <Button size="sm" onClick={setPin} disabled={!/^\d{4,8}$/.test(pinInput)}>Save</Button>
            <Button size="sm" variant="ghost" onClick={() => { setSettingPin(false); setPinInput(''); }}>Cancel</Button>
          </>
        )}
      </div>

      {/* Passkey */}
      <div className="flex flex-wrap items-center gap-2 rounded-lg border p-3">
        <ShieldCheck size={16} className="text-muted-foreground" />
        <span className="text-xs font-medium">Passkey (WebAuthn)</span>
        {hasPasskey ? <span className="rounded bg-success/10 px-1.5 py-0.5 text-[10px] font-bold text-success">ENABLED</span> : null}
        <span className="flex-1" />
        {hasPasskey ? (
          <Button size="sm" variant="destructive" onClick={removePasskey}><Trash2 size={13} /> Remove</Button>
        ) : (
          <Button size="sm" variant="outline" onClick={registerPasskey}>Add passkey</Button>
        )}
      </div>

      {/* Allowed IPs */}
      <div className="rounded-lg border p-3">
        <p className="mb-2 text-xs font-medium">Allowed IPs / CIDR</p>
        <IPAllowlistEditor />
      </div>
    </div>
  );
}

function IPAllowlistEditor() {
  const [ips, setIps] = useState<Unmodelled[]>([]);
  const [val, setVal] = useState('');

  const add = () => {
    const v = val.trim();
    if (!/^(\d{1,3}\.){3}\d{1,3}(\/(16|24))?$/.test(v)) return;
    if (ips.includes(v)) return;
    setIps([...ips, v]);
    setVal('');
    void ipCall('put', { allowedIps: [...ips, v] });
  };

  const remove = (ip: Unmodelled) => {
    const next = ips.filter((x) => x !== ip);
    setIps(next);
    void ipCall('put', { allowedIps: next });
  };

  const ipCall = async (method: Unmodelled, body: Unmodelled) => {
    try {
      const r = await fetch('/api/auth/allowed-ips', {
        method,
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body),
      });
      return r.ok;
    } catch { return false; }
  };

  return (
    <div className="space-y-1.5">
      {ips.map((ip) => (
        <div key={ip} className="flex items-center justify-between rounded bg-muted/50 px-2 py-1 font-mono text-[11px]">
          <span>{ip}</span>
          <button onClick={() => remove(ip)} className="text-muted-foreground hover:text-destructive"><Trash2 size={12} /></button>
        </div>
      ))}
      <div className="flex gap-1">
        <Input className="h-8 font-mono text-xs" placeholder="10.0.0.0/24" value={val} onChange={(e) => setVal(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && add()} />
        <Button size="sm" variant="outline" onClick={add} disabled={!/^(\d{1,3}\.){3}\d{1,3}(\/(16|24))?$/.test(val.trim())}>Add</Button>
      </div>
    </div>
  );
}

