                {/* Symptoms fallback */}
                {apt.symptoms && !apt.chiefComplaints && !apt.preConsultationDetails?.filledAt && (
                  <div>
                    <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-1">Symptoms</p>
