                )}
              </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

import { useEffect } from 'react';

export interface SeoHeadProps {
  title: string;
  description?: string;
  canonical?: string;
  noindex?: boolean;
  jsonLd?: Record<string, unknown> | Record<string, unknown>[];
  ogImage?: string;
  locale?: string;
}

/** Public-page SEO head: title/meta/canonical + JSON-LD (MedicalOrganization/Physician/LocalBusiness/Event). Never render on private/dashboard pages. */
export default function SeoHead({ title, description, canonical, noindex, jsonLd, ogImage, locale = 'en' }: SeoHeadProps) {
  useEffect(() => {
    document.title = title;
    const setMeta = (selector: string, create: () => HTMLMetaElement) => {
      let el = document.head.querySelector(selector) as HTMLMetaElement | null;
      if (!el) { el = create(); document.head.appendChild(el); }
      return el;
    };
    if (description) {
      setMeta('meta[name="description"]', () => { const m = document.createElement('meta'); m.name = 'description'; return m; }).content = description;
    }
    setMeta('meta[name="robots"]', () => { const m = document.createElement('meta'); m.name = 'robots'; return m; }).content = noindex ? 'noindex,nofollow' : 'index,follow';
    let link = document.head.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
    if (canonical) {
      if (!link) { link = document.createElement('link'); link.rel = 'canonical'; document.head.appendChild(link); }
      link.href = canonical;
    } else if (link) link.remove();
    const SCRIPT_ID = 'fm-jsonld';
    document.getElementById(SCRIPT_ID)?.remove();
    if (jsonLd && !noindex) {
      const s = document.createElement('script');
      s.id = SCRIPT_ID;
      s.type = 'application/ld+json';
      s.text = JSON.stringify(jsonLd);
      document.head.appendChild(s);
    }
    if (ogImage) {
      setMeta('meta[property="og:image"]', () => { const m = document.createElement('meta'); m.setAttribute('property', 'og:image'); return m; }).content = ogImage;
    }
    document.documentElement.lang = locale;
  }, [title, description, canonical, noindex, jsonLd, ogImage, locale]);
  return null;
}

/** Genuine-reviews-only aggregateRating helper (never fabricate ratings). */
export function aggregateRating(ratingAvg?: number, ratingCount?: number) {
  if (!ratingAvg || !ratingCount || ratingCount < 3) return undefined;
  return { '@type': 'AggregateRating', ratingValue: ratingAvg, reviewCount: ratingCount };
}

import { useEffect, useRef, useState } from 'react';
import { Loader2, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { setStepUpPrompt } from '@/lib/stepUp';
import { api } from '@/lib/api';

/**
 * AUTHZ-M-03 (F7): the re-verification prompt behind STEP_UP_REQUIRED.
 *
 * 2FA at login proves who you are once; this proves it is still you at the
 * moment that moves money, amends a record, or walks out with an export.
 * The dialog collects the code and verifies it against /auth/step-up BEFORE
 * resolving, so a typo shows here (where the user can fix it) instead of
 * surfacing as a failed action.
 */

const SCOPE_LABELS: Record<string, string> = {
  'export:full': 'a bulk data export',
  'records:amend': 'a medical record amendment',
  'users:role-change': 'a staff role change',
  'payouts:add': 'a payout account change',
  'refunds:issue': 'a refund',
};

const labelFor = (scope: string): string => SCOPE_LABELS[scope] || 'this action';

export default function StepUpDialog() {
  const [scope, setScope] = useState<string | null>(null);
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const resolver = useRef<{ resolve: (code: string) => void; reject: (reason: Error) => void } | null>(null);

  useEffect(() => {
    setStepUpPrompt(
      (s: string) =>
        new Promise<string>((resolve, reject) => {
          resolver.current = { resolve, reject };
          setCode('');
          setError('');
          setScope(s);
        })
    );
    return () => setStepUpPrompt(null);
  }, []);

  const close = (result: string | Error) => {
    const r = resolver.current;
    resolver.current = null;
    setScope(null);
    setCode('');
    setError('');
    if (r) {
      if (result instanceof Error) r.reject(result);
      else r.resolve(result);
    }
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    const clean = code.trim();
    if (!clean || busy || !scope) return;
    setBusy(true);
    setError('');
    try {
      // Verify here so an incorrect code is fixable in the dialog; each
      // waiting request then exchanges the same (stateless) code for its own
      // single-use token.
      await api.stepUp(scope, clean);
      close(clean);
    } catch (err: any) {
      setError(err?.message || 'Incorrect verification code');
      setBusy(false);
    }
  };

  return (
    <Dialog open={!!scope} onOpenChange={(open) => { if (!open) close(new Error('Verification cancelled')); }}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <div className="w-12 h-12 rounded-2xl bg-primary/10 flex items-center justify-center mb-2">
            <ShieldCheck className="w-6 h-6 text-primary" />
          </div>
          <DialogTitle>Verify it is you</DialogTitle>
          <DialogDescription>
            {scope
              ? `Enter your 6-digit authenticator code (or a backup code) to confirm ${labelFor(scope)}.`
              : ''}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={submit} className="space-y-4">
          <Input
            autoFocus
            inputMode="numeric"
            autoComplete="one-time-code"
            placeholder="123456"
            value={code}
            onChange={(e) => setCode(e.target.value)}
            maxLength={64}
            aria-label="Verification code"
          />

          {error && (
            <p className="text-sm text-destructive bg-destructive/10 px-3 py-2 rounded-lg">{error}</p>
          )}

          <div className="flex gap-2 justify-end">
            <Button type="button" variant="outline" onClick={() => close(new Error('Verification cancelled'))} disabled={busy}>
              Cancel
            </Button>
            <Button type="submit" disabled={busy || !code.trim()} className="gap-2">
              {busy && <Loader2 className="w-4 h-4 animate-spin" />}
              Confirm
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import type { Unmodelled } from '@/lib/apiTypes';

/**
 * Parses time like "09:15 AM" into a numerical value for sorting.
 */
function parseTime(timeStr: Unmodelled) {
  if (!timeStr) return 0;
  const match = timeStr.match(/(\d+):(\d+)\s*(AM|PM)?/i);
  if (!match) return 0;
  let [_, h, m, period] = match;
  h = parseInt(h, 10);
  m = parseInt(m, 10);
  if (period && period.toUpperCase() === 'PM' && h !== 12) h += 12;
  if (period && period.toUpperCase() === 'AM' && h === 12) h = 0;
  return h * 60 + m;
}

/**
 * Formats a time value like { hour: 9, minute: 0 } to "09:00 AM"
 */
function formatTimeLabel(hour: Unmodelled, minute: Unmodelled) {
  const period = hour >= 12 ? 'PM' : 'AM';
  const h12 = hour === 0 ? 12 : hour > 12 ? hour - 12 : hour;
  return `${String(h12).padStart(2, '0')}:${String(minute).padStart(2, '0')} ${period}`;
}

/**
 * Generate all working hours from startHour to endHour.
 * Default: 9:00 AM to 5:00 PM
 */
function generateWorkingHours(startHour = 9, endHour = 17) {
  const hours = [];
  for (let h = startHour; h <= endHour; h++) {
    hours.push({
      label: formatTimeLabel(h, 0),
      hour: h,
    });
  }
  return hours;
}

/**
 * Generate 15-min sub-slots for a given hour.
 * e.g. hour=9 → ["09:00 AM", "09:15 AM", "09:30 AM", "09:45 AM"]
 */
function generateSubSlots(hour: Unmodelled) {
  const slots = [];
  for (let m = 0; m < 60; m += 15) {
    slots.push(formatTimeLabel(hour, m));
  }
  return slots;
}

/**
 * TimeSlotScroller - Shows all working hours (9:00 AM - 5:00 PM) with 15-min sub-slots.
 * 
 * Props:
 *   appointments - Array of appointment objects
 *   activeApt - Currently selected appointment
 *   onSelectApt - Callback when an appointment is selected
 *   onSelectHour - Callback when an hour is selected (optional)
 *   selectedHour - Currently selected hour (controlled)
 *   selectedSubSlot - Currently selected sub-slot (controlled)
 *   onSelectSubSlot - Callback when a sub-slot is selected
 */
export default function TimeSlotScroller({ 
  appointments = [], 
  activeApt, 
  onSelectApt,
  selectedHour: externalSelectedHour,
  onSelectHour: externalOnSelectHour,
  selectedSubSlot: externalSelectedSubSlot,
  onSelectSubSlot: externalOnSelectSubSlot,
}: Unmodelled) {
  const [internalSelectedHour, setInternalSelectedHour] = useState<Unmodelled>(null);
  const [internalSelectedSubSlot, setInternalSelectedSubSlot] = useState<Unmodelled>(null);

  // Use external state if provided, otherwise internal
  const selectedHour = externalSelectedHour !== undefined ? externalSelectedHour : internalSelectedHour;
  const selectedSubSlot = externalSelectedSubSlot !== undefined ? externalSelectedSubSlot : internalSelectedSubSlot;

  const setSelectedHour = externalOnSelectHour || setInternalSelectedHour;
  const setSelectedSubSlot = externalOnSelectSubSlot || setInternalSelectedSubSlot;

  // Working hours: 9:00 AM to 5:00 PM
  const workingHours = useMemo(() => generateWorkingHours(9, 17), []);

  // Build a map of time → appointment for quick lookup
  const appointmentMap = useMemo(() => {
    const map: Unmodelled = {};
    appointments.forEach((apt: Unmodelled) => {
      if (apt.time) {
        map[apt.time] = apt;
      }
    });
    return map;
  }, [appointments]);

  // Auto-select first hour on mount
  useEffect(() => {
    if (!selectedHour && workingHours.length > 0) {
      // Find the first hour that has appointments, or use the first hour
      const firstHourWithAppts = workingHours.find(h => {
        const subSlots = generateSubSlots(h.hour);
        return subSlots.some(s => appointmentMap[s]);
      });
      setSelectedHour(firstHourWithAppts?.label || workingHours[0].label);
    }
  }, [appointments, workingHours]);

  // Generate sub-slots for the selected hour
  const subSlots = useMemo(() => {
    if (!selectedHour) return [];
    const hour = workingHours.find(h => h.label === selectedHour);
    if (!hour) return [];
    return generateSubSlots(hour.hour);
  }, [selectedHour, workingHours]);

  // Auto-select sub-slot based on activeApt
  useEffect(() => {
    if (activeApt?.time && subSlots.includes(activeApt.time)) {
      setSelectedSubSlot(activeApt.time);
    }
  }, [activeApt, subSlots]);

  // When hour changes, auto-select first sub-slot with an appointment
  useEffect(() => {
    if (selectedHour && !selectedSubSlot) {
      const firstWithAppt = subSlots.find(s => appointmentMap[s]);
      if (firstWithAppt) {
        setSelectedSubSlot(firstWithAppt);
      }
    }
  }, [selectedHour, subSlots, appointmentMap]);

  const handleHourClick = (hourLabel: Unmodelled) => {
    if (selectedHour === hourLabel) {
      setSelectedHour(null);
      setSelectedSubSlot(null);
    } else {
      setSelectedHour(hourLabel);
      setSelectedSubSlot(null);
    }
  };

  const handleSubSlotClick = (time: Unmodelled) => {
    const apt = appointmentMap[time];
    if (apt) {
      if (onSelectApt) onSelectApt(apt);
      setSelectedSubSlot(time);
    }
  };

  const getPatientsForSubSlot = (time: Unmodelled) => {
    const apt = appointmentMap[time];
    return apt ? [apt] : [];
  };

  return (
    <div className="flex flex-col gap-3">
      {/* Hours Scroller */}
      <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
        {workingHours.map((hour) => {
          const subSlotsForHour = generateSubSlots(hour.hour);
          const hasAppts = subSlotsForHour.some(s => appointmentMap[s]);
          const apptCount = subSlotsForHour.filter(s => appointmentMap[s]).length;

          return (
            <button
              key={hour.label}
              onClick={() => handleHourClick(hour.label)}
              className={`relative px-4 py-2 rounded-xl text-sm font-bold whitespace-nowrap transition-all border ${
                selectedHour === hour.label 
                  ? 'bg-primary text-primary-foreground border-primary shadow-sm' 
                  : hasAppts
                    ? 'bg-primary/10 text-primary border-primary/20 hover:bg-primary/20'
                    : 'bg-card text-muted-foreground border-border/60 hover:bg-muted'
              }`}
            >
              {hour.label}
              {apptCount > 0 && (
                <span className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-amber-500 text-white text-[9px] font-bold flex items-center justify-center shadow-sm">
                  {apptCount}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Sub-slots Scroller */}
      {selectedHour && subSlots.length > 0 && (
        <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {subSlots.map((time) => {
            const apt = appointmentMap[time];
            const isSelected = selectedSubSlot === time;
            const hasAppt = !!apt;

            return (
              <button
                key={time}
                onClick={() => handleSubSlotClick(time)}
                disabled={!hasAppt}
                className={`px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap transition-all border ${
                  isSelected
                    ? 'bg-primary/20 text-primary border-primary/30 shadow-sm'
                    : hasAppt
                      ? 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100 cursor-pointer'
                      : 'bg-muted/20 text-muted-foreground/40 border-border/30 cursor-not-allowed'
                }`}
              >
                <span>{time}</span>
                {hasAppt && apt && (
                  <span className="ml-1.5 text-[10px] opacity-75">
                    ({apt.patient?.split(' ')[0] || '?'})
                  </span>
                )}
              </button>
            );
          })}
        </div>
      )}

      {/* No appointments message */}
      {selectedHour && subSlots.length > 0 && !subSlots.some(s => appointmentMap[s]) && (
        <p className="text-xs text-muted-foreground text-center py-2 italic">
          No appointments for {selectedHour}
        </p>
      )}
    </div>
  );
}

import { useState, useMemo, useCallback } from 'react';
