          <div className="flex items-center gap-1 bg-muted/60 p-1 rounded-xl border border-border/60 text-xs w-full sm:w-auto justify-center">
            <button
              onClick={() => setSelectedTimeframe('all')}
              className={`px-3 py-1 rounded-lg font-medium transition-all ${
                selectedTimeframe === 'all'
                  ? 'bg-card text-foreground shadow-sm font-semibold'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              All Upcoming
            </button>
            <button
              onClick={() => setSelectedTimeframe('tomorrow')}
              className={`px-3 py-1 rounded-lg font-medium transition-all ${
                selectedTimeframe === 'tomorrow'
                  ? 'bg-card text-foreground shadow-sm font-semibold'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              Tomorrow
            </button>
            <button
              onClick={() => setSelectedTimeframe('week')}
              className={`px-3 py-1 rounded-lg font-medium transition-all ${
                selectedTimeframe === 'week'
                  ? 'bg-card text-foreground shadow-sm font-semibold'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              Next 7 Days
            </button>
          </div>
        </div>

        {/* Mode filter pills */}
        <div className="flex items-center gap-2 flex-wrap pt-2 border-t border-border/50">
          <span className="text-xs text-muted-foreground font-medium flex items-center gap-1 mr-1">
            <Filter className="w-3.5 h-3.5" /> Filter by Mode:
          </span>
          <Button
            size="sm"
            variant={selectedMode === 'all' ? 'default' : 'outline'}
            className="h-7 text-xs rounded-lg px-3"
            onClick={() => setSelectedMode('all')}
          >
            All Modes ({stats.total})
          </Button>
          <Button
            size="sm"
            variant={selectedMode === 'video' ? 'default' : 'outline'}
            className={`h-7 text-xs rounded-lg px-3 gap-1.5 ${
              selectedMode === 'video' ? 'bg-emerald-600 hover:bg-emerald-700 text-white' : 'text-emerald-600 border-emerald-500/30'
            }`}
            onClick={() => setSelectedMode('video')}
          >
            <Video className="w-3 h-3" /> Video ({stats.video})
          </Button>
          <Button
            size="sm"
            variant={selectedMode === 'audio' ? 'default' : 'outline'}
            className={`h-7 text-xs rounded-lg px-3 gap-1.5 ${
              selectedMode === 'audio' ? 'bg-teal-600 hover:bg-teal-700 text-white' : 'text-teal-600 border-teal-500/30'
            }`}
            onClick={() => setSelectedMode('audio')}
          >
            <Phone className="w-3 h-3" /> Voice ({stats.audio})
          </Button>
          <Button
            size="sm"
            variant={selectedMode === 'chat' ? 'default' : 'outline'}
            className={`h-7 text-xs rounded-lg px-3 gap-1.5 ${
              selectedMode === 'chat' ? 'bg-blue-600 hover:bg-blue-700 text-white' : 'text-blue-600 border-blue-500/30'
            }`}
            onClick={() => setSelectedMode('chat')}
          >
            <MessageSquare className="w-3 h-3" /> Chat ({stats.chat})
          </Button>
        </div>
      </div>

      {/* ── Appointments List ── */}
      {filteredAppointments.length === 0 ? (
        <div className="bg-card rounded-2xl border border-dashed border-border/80 p-12 text-center">
          <div className="w-16 h-16 rounded-2xl bg-muted/60 flex items-center justify-center mx-auto mb-3 text-muted-foreground">
            <CalendarClock className="w-8 h-8 opacity-60" />
          </div>
          <h3 className="font-heading font-semibold text-foreground text-base mb-1">
            No Upcoming Online Consultations
          </h3>
          <p className="text-xs text-muted-foreground max-w-sm mx-auto">
            {search || selectedMode !== 'all' || selectedTimeframe !== 'all'
              ? 'No scheduled consultations match your current filters. Try resetting the filters.'
              : 'When patients book and you confirm online consultation requests for future dates, they will appear here.'}
          </p>
          {(search || selectedMode !== 'all' || selectedTimeframe !== 'all') && (
            <Button
              variant="outline"
              size="sm"
              className="mt-4 text-xs"
              onClick={() => { setSearch(''); setSelectedMode('all'); setSelectedTimeframe('all'); }}
            >
              Reset Filters
            </Button>
          )}
        </div>
      ) : (
        <div className="space-y-6">
          {Object.entries(groupedByDate).map(([dateStr, list]: Unmodelled) => {
            const relText = getRelativeDays(dateStr, today);
            return (
              <div key={dateStr} className="space-y-3">
                {/* Date header banner */}
                <div className="flex items-center justify-between gap-2 px-1">
                  <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-lg bg-primary/10 text-primary flex items-center justify-center font-bold text-xs">
                      <CalendarDays className="w-4 h-4" />
                    </div>
                    <div>
                      <span className="font-heading font-bold text-sm text-foreground">
                        {formatDisplayDate(dateStr) || dateStr}
                      </span>
                      <span className="ml-2 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-primary/10 text-primary">
                        {relText}
                      </span>
                    </div>
                  </div>
                  <span className="text-xs text-muted-foreground">
                    {list.length} {list.length === 1 ? 'consultation' : 'consultations'}
                  </span>
                </div>

                {/* Cards for this date */}
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                  {list.map((apt: Unmodelled) => {
                    const modeDetails = getModeDetails(apt);
                    const ModeIcon = modeDetails.icon;
                    const patient = apt.patientId;
                    const age = patient?.dateOfBirth
                      ? Math.floor((+new Date() - +new Date(patient.dateOfBirth)) / 31557600000)
                      : null;

                    return (
                      <div
                        key={apt._id}
                        className="group bg-card rounded-2xl border border-border/70 p-5 shadow-sm hover:shadow-md hover:border-primary/40 transition-all flex flex-col justify-between"
                      >
                        {/* Top Time + Mode Banner */}
                        <div>
                          <div className="flex items-center justify-between gap-2 mb-3">
                            <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-muted text-foreground text-xs font-semibold">
                              <Clock className="w-3.5 h-3.5 text-primary" />
                              <span>{apt.time} {subSlotFor && `· ${subSlotFor(apt.time)}`}</span>
                            </div>
                            <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-xl border text-[11px] font-semibold ${modeDetails.badgeClass}`}>
                              <ModeIcon className="w-3 h-3" />
                              {modeDetails.label}
                            </span>
                          </div>

                          {/* Patient Header */}
                          <div className="flex items-start gap-3 mb-3">
                            <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center text-sm font-bold text-primary shrink-0 overflow-hidden border border-primary/20">
                              {patient?.avatar ? (
                                <img src={patient.avatar} alt={apt.patient} className="w-full h-full object-cover" />
                              ) : (
                                (apt.patient || '?').slice(0, 2).toUpperCase()
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <h4 className="font-heading font-bold text-sm text-foreground truncate">
                                {apt.patient}
                              </h4>
                              <div className="flex items-center gap-2 text-xs text-muted-foreground mt-0.5 flex-wrap">
                                {age && <span>{age} yrs</span>}
                                {patient?.gender && <span>• {patient.gender}</span>}
                                {patient?.bloodGroup && (
                                  <span className="inline-flex items-center gap-0.5 text-red-500 font-medium">
                                    <Droplet className="w-2.5 h-2.5" /> {patient.bloodGroup}
                                  </span>
                                )}
                              </div>
                              {apt.tokenNumber && (
                                <span className="inline-block mt-1 px-2 py-0.2 rounded-md bg-muted text-muted-foreground text-[10px] font-semibold">
                                  Token #{apt.tokenNumber}
                                </span>
                              )}
                            </div>
                          </div>

                          {/* Phone / Contact */}
                          {(patient?.phone || apt.phone) && (
                            <p className="text-xs text-muted-foreground mb-2 flex items-center gap-1">
                              <Phone className="w-3 h-3 text-muted-foreground/70" />
                              {patient?.phone || apt.phone}
                            </p>
                          )}

                          {/* Symptoms */}
                          {apt.symptoms && (
                            <div className="p-2.5 rounded-xl bg-muted/40 border border-border/50 text-xs mb-3">
                              <p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground mb-0.5">
                                Symptoms / Complaints
                              </p>
                              <p className="text-foreground line-clamp-2 leading-relaxed">
                                {apt.symptoms}
                              </p>
                            </div>
                          )}
                        </div>

                        {/* Card Bottom / Action */}
                        <div className="pt-3 border-t border-border/60 flex items-center justify-between gap-2 mt-2">
                          <div className="flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-emerald-500" />
                            <span className="text-[11px] font-semibold text-emerald-600 dark:text-emerald-400">
                              Confirmed
                            </span>
                            {apt.fees > 0 && (
                              <span className="text-[11px] text-muted-foreground">
                                · ₹{apt.fees} Paid
                              </span>
                            )}
                          </div>

                          <Button
                            size="sm"
                            variant="outline"
                            className="h-7 text-xs gap-1 rounded-lg hover:border-primary hover:text-primary"
                            onClick={() => onViewDetails && onViewDetails(apt)}
                          >
                            <Eye className="w-3 h-3" /> View Details
                          </Button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { User, Clock, ChevronRight, ArrowLeft, Send, CalendarDays, BadgeCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { DialogFooter, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { toast } from 'sonner';
import { getISTDateString } from '@/lib/dateUtils';
import { getSubSlotsForHour, parseTime } from '@/lib/timeSlots';
import IntakeFormStep from './IntakeFormStep';
import { userFacingError } from '@/lib/errorCopy';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const bloodGroups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];
const genders = ['Male', 'Female', 'Other'];

const emptyForm = { name: '', age: '', gender: 'Male', phone: '', email: '', bloodGroup: '', address: '' };

const initialIntakeForm = {
  chiefComplaint: '', chiefComplaintOther: '', symptomsDuration: '',
  pastMedicalHistory: { hasHistory: null, details: '' },
  currentTreatment: { hasPastTreatment: null, doctorName: '', cityState: '', when: '', prescriptionFile: '', takingMedicines: null },
  testReports: { hasReports: null, reportFile: '' },
  currentMedications: { hasMedications: null, details: '' },
  allergies: { hasAllergies: null, details: '' },
  familyHistory: { hasHistory: null, details: '' },
};

/**
 * Walk-in booking wizard — flow & UI match BookingModal (real-time schedule,
 * booked-slot statuses, intake form).
 *
 * Step 1 — Slot Selection: doctor card + date + hour dropdown + sub-slot grid
 * Step 2 — Patient Details
 * Step 3 — Patient Intake Form
 *
 * Props:
 *  - timeSlots:        string[] — fallback slots (real source: doctor schedule)
 *  - onPatientCreated: fn() — called after a successful booking
 */
export default function WalkInPatientForm({ timeSlots, onPatientCreated }: Unmodelled) {
  const { user } = useAuth();
  const [step, setStep] = useState(1);
  const [date, setDate] = useState(getISTDateString());
  const [bookingTime, setBookingTime] = useState('');
  const [selectedHour, setSelectedHour] = useState('');
  const [notes, setNotes] = useState('');
  const [slotCounts, setSlotCounts] = useState<ApiRow>({});
  const [fullSlots, setFullSlots] = useState<ApiRow[]>([]);
  const [dateDisabledSlots, setDateDisabledSlots] = useState<ApiRow[]>([]);
  const [pendingDisabledSlots, setPendingDisabledSlots] = useState<ApiRow[]>([]);
  const [form, setForm] = useState(emptyForm);
  const [intakeForm, setIntakeForm] = useState(initialIntakeForm);
  const [creating, setCreating] = useState(false);

  const set = (k: Unmodelled, v: Unmodelled) => setForm(f => ({ ...f, [k]: v }));

  const doctorId = user?.doctorProfileId || null;

  // Doctor profile fetch — real schedule (time_slots), fee, slotDuration
  const [doctorProfile, setDoctorProfile] = useState<Unmodelled>(null);
  useEffect(() => {
    if (!doctorId) return;
    api.getDoctor(doctorId)
      .then(res => setDoctorProfile(res?.data || res))
      .catch(() => setDoctorProfile(null));
  }, [doctorId]);

  const consultationFee = Number(doctorProfile?.consultation_fees) || Number(user?.consultationFee) || Number(user?.fees) || 0;
  const slotDuration = Number(doctorProfile?.slotDuration) || user?.slotDuration || 15;

  // Booked/disabled slots fetch for this doctor + date (real-time)
  useEffect(() => {
    if (!doctorId || !date) { setSlotCounts({}); setFullSlots([]); setDateDisabledSlots([]); setPendingDisabledSlots([]); return; }
    api.getBookedSlots({ doctorId, date })
      .then(res => {
        if (res && typeof res === 'object' && !Array.isArray(res) && res.counts) {
          setSlotCounts(res.counts || {});
          setFullSlots(res.fullSlots || Object.keys(res.counts || {}));
          setDateDisabledSlots(res.dateDisabled || []);
          setPendingDisabledSlots(res.pendingDisabledSlots || []);
        } else {
          const arr = Array.isArray(res) ? res : [];
          setFullSlots(arr);
          const counts: Unmodelled = {};
          arr.forEach(s => { counts[s] = (counts[s] || 0) + 1; });
          setSlotCounts(counts);
          setDateDisabledSlots([]);
          setPendingDisabledSlots([]);
        }
      })
      .catch(() => { setSlotCounts({}); setFullSlots([]); setDateDisabledSlots([]); setPendingDisabledSlots([]); });
  }, [doctorId, date]);

  // ─── Slot helpers (same as BookingModal) ───
  const slotToMinutes = (t: Unmodelled) => {
    const m = t?.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
    if (!m) return null;
    let h = parseInt(m[1], 10) % 12;
    if (/PM/i.test(m[3])) h += 12;
    return h * 60 + parseInt(m[2], 10);
  };

  const minutesToSlot = (mins: Unmodelled) => {
    const h = Math.floor(mins / 60) % 24;
    const mm = mins % 60;
    const ampm = h >= 12 ? 'PM' : 'AM';
    let h12 = h % 12; if (h12 === 0) h12 = 12;
    return `${h12}:${String(mm).padStart(2, '0')} ${ampm}`;
  };

  const minutesToShort = (mins: Unmodelled) => {
    const h = Math.floor(mins / 60) % 24;
    const mm = mins % 60;
    let h12 = h % 12; if (h12 === 0) h12 = 12;
    return `${h12}:${String(mm).padStart(2, '0')}`;
  };

  const isSlotDisabled = (slotStr: Unmodelled) => dateDisabledSlots.includes(slotStr);
  const isSlotPendingUpdate = (slotStr: Unmodelled) => pendingDisabledSlots.includes(slotStr);
  const isSlotFull = (time: Unmodelled) => (slotCounts[time] || 0) >= 1;

  // Real-time hours: doctor schedule (time_slots) se, fallback = prop
  const hourGroups = useMemo(() => {
    const source = (doctorProfile?.time_slots?.length ? doctorProfile.time_slots : timeSlots) || [];
    const enabledHours = new Set();
    source.forEach((t: Unmodelled) => {
      const { hour } = parseTime(t);
      if (hour != null) enabledHours.add(hour);
    });
    const groups: Unmodelled = {};
    [...enabledHours].sort((a: Unmodelled, b: Unmodelled) => a - b).forEach((h: Unmodelled)  => {
      const h12 = h % 12 === 0 ? 12 : h % 12;
      const key = `${h12}:00 ${h >= 12 ? 'PM' : 'AM'}`;
      groups[key] = getSubSlotsForHour(key).map(sub => {
        const start = sub.split('-')[0];
        const [sh, sm] = start.split(':');
        const sh12 = Number(sh) % 12 === 0 ? 12 : Number(sh) % 12;
        return `${sh12}:${sm} ${h >= 12 ? 'PM' : 'AM'}`;
      });
    });
    return Object.entries(groups);
  }, [doctorProfile?.time_slots, timeSlots]);

  const rangeFor = (slotStr: Unmodelled) => {
    const start = slotToMinutes(slotStr);
    if (start == null) return slotStr;
    return `${minutesToShort(start)}–${minutesToShort(start + slotDuration)}`;
  };

  const fullRangeFor = (slotStr: Unmodelled) => {
    const start = slotToMinutes(slotStr);
    if (start == null) return slotStr;
    return `${minutesToSlot(start)} – ${minutesToSlot(start + slotDuration)}`;
  };

  const goToIntake = () => {
    if (!form.name) {
      toast.error('Please fill in Full Name');
      return;
    }
    if (!form.phone && !form.email) {
      toast.error('Please fill in Phone or Email');
      return;
    }
    setStep(3);
  };

  const handleRegister = async () => {
    if (!intakeForm.chiefComplaint) {
      toast.error('Please select your chief complaint or main symptom');
      return;
    }
    setCreating(true);
    try {
      const res = await api.walkInAppointment({
        patient: { ...form, age: form.age ? Number(form.age) : 0 },
        doctor: user?.name || '',
        department: user?.department || 'General',
        date,
        time: bookingTime,
        type: 'Consultation',
        symptoms: intakeForm.chiefComplaint,
        notes,
      });
      const apptId = res?.appointment?._id || res?._id;
      if (apptId) {
        try {
          await api.submitIntakeForm(apptId, {
            chiefComplaint: intakeForm.chiefComplaint,
            chiefComplaintOther: intakeForm.chiefComplaintOther,
            symptomsDuration: intakeForm.symptomsDuration,
            pastMedicalHistory: intakeForm.pastMedicalHistory,
            currentTreatment: intakeForm.currentTreatment,
            testReports: intakeForm.testReports,
            currentMedications: intakeForm.currentMedications,
            allergies: intakeForm.allergies,
            familyHistory: intakeForm.familyHistory,
          });
        } catch (e: any) { console.error('Intake save failed:', e); }
      }
      toast.success(res?.duplicate
        ? `Walk-in "${form.name}" already booked for ${bookingTime}`
        : `Walk-in "${form.name}" booked for ${bookingTime}`);
      setForm(emptyForm);
      setIntakeForm(initialIntakeForm);
      setBookingTime('');
      setSelectedHour('');
      setNotes('');
      setStep(1);
      onPatientCreated?.();
    } catch (e: any) {
      console.error(e);
      toast.error(userFacingError(e, { fallback: 'Failed to book walk-in' }));
    } finally {
      setCreating(false);
    }
  };

  return (
    <>
      {step === 1 && (
        <>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              Book Walk-in Appointment
            </DialogTitle>
            <DialogDescription>
              Walk-in booking for {user?.name || 'this facility'}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 py-2">
            {/* Doctor card */}
            <div className="flex items-center gap-2.5">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center shrink-0">
                <span className="text-primary-foreground font-bold text-xs">{user?.name?.split(' ')?.map(n => n?.[0])?.join('')?.slice(0, 2) || 'DR'}</span>
              </div>
              <div className="min-w-0">
                <h3 className="font-heading font-semibold text-foreground text-sm truncate">{user?.name}</h3>
                <p className="text-xs text-primary">{user?.specialization || 'Doctor'}</p>
                <p className="text-[10px] text-muted-foreground mt-1 flex items-center gap-1">
                  <BadgeCheck className="w-3 h-3 text-emerald-500" /> Walk-in confirmed immediately
                </p>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="p-2 rounded-xl bg-primary/5 border border-primary/10 text-center">
                <p className="text-[11px] text-muted-foreground mb-0.5">Consultation Fee</p>
                <p className="font-bold text-sm text-primary">₹{consultationFee}</p>
              </div>
              <div className="p-2 rounded-xl bg-emerald-50 border border-emerald-200 dark:bg-emerald-500/10 text-center">
                <p className="text-[11px] text-muted-foreground mb-0.5">Avg Treatment Time</p>
                <p className="font-semibold text-xs text-emerald-600">{slotDuration} mins</p>
              </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-foreground">Select Date</label>
              <Input type="date" className="w-full" value={date} onChange={e => setDate(e.target.value)} min={getISTDateString()} />
            </div>
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <label className="text-xs font-medium text-foreground">Select Time Slot</label>
                <span className="inline-flex items-center gap-1 text-[10px] font-medium text-primary bg-primary/10 px-2 py-0.5 rounded-md">
                  <Clock className="w-3 h-3" /> Avg {slotDuration} mins
                </span>
              </div>

              {/* Step A: Hour selector dropdown */}
              <select value={selectedHour || ''} onChange={e => { setSelectedHour(e.target.value); setBookingTime(''); }} className="w-full h-9 px-3 rounded-xl border border-border bg-background text-sm">
                <option value="">Choose hour</option>
                {hourGroups.map(([hourLabel, hourSlots]: Unmodelled) => {
                  const allUnavailable = hourSlots.every((s: Unmodelled) => isSlotFull(s) || isSlotDisabled(s) || isSlotPendingUpdate(s));
                  return (
                    <option key={hourLabel} value={hourLabel} disabled={allUnavailable}>
                      {hourLabel}{allUnavailable ? ' (Full)' : ''}
                    </option>
                  );
                })}
              </select>

              {/* Step B: Sub-slot boxes for selected hour */}
              {selectedHour && (
                <div className="space-y-2">
                  <p className="text-[11px] text-muted-foreground">
                    {(() => {
                      const hs: Unmodelled = hourGroups.find(([h]) => h === selectedHour)?.[1] || [];
                      const unavailableCount = hs.filter((s: Unmodelled) => isSlotFull(s) || isSlotDisabled(s) || isSlotPendingUpdate(s)).length;
                      return `${hs.length - unavailableCount} of ${hs.length} slots available in ${selectedHour}`;
                    })()}
                  </p>
                  <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                    {((hourGroups.find(([h]: Unmodelled) => h === selectedHour)?.[1]) as Unmodelled || []).map((t: Unmodelled) => {
                      const disabled = isSlotDisabled(t);
                      const pendingUpdate = isSlotPendingUpdate(t);
                      const full = isSlotFull(t);
                      const unavailable = disabled || full || pendingUpdate;
                      const selected = bookingTime === t;
                      return (
                        <button
                          key={t}
                          type="button"
                          disabled={unavailable}
                          onClick={() => setBookingTime(t)}
                          className={`flex flex-col items-center gap-0.5 px-1.5 py-2 rounded-lg border text-center transition-all ${
                            selected
                              ? 'border-primary bg-primary text-primary-foreground shadow-sm'
                              : unavailable
                              ? 'border-red-300 bg-red-50 text-red-600 cursor-not-allowed'
                              : 'border-border bg-card text-foreground hover:border-primary/50 hover:bg-primary/5'
                          }`}
                        >
                          <span className="text-xs font-semibold">{rangeFor(t)}</span>
                          <span className={`text-[9px] leading-none ${selected ? 'text-primary-foreground/80' : 'text-muted-foreground'}`}>
                            {disabled ? 'Not Available (Disabled)' : pendingUpdate ? 'Pending — may not be available' : full ? 'Booked' : 'Available'}
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* Selected slot confirmation pill with full range */}
