      {/* Slide/Collapsible In-app Chat Panel */}
      {showChat && (
        <div className="pt-4 border-t border-slate-100 dark:border-slate-800">
          <AssistantChatPanel
            bookingId={activeBooking._id}
            currentUser={user}
            targetUser={activeBooking.patientId}
            onClose={() => setShowChat(false)}
          />
        </div>
      )}
    </div>
  );
