                <span className="text-[10px] text-muted-foreground uppercase font-bold tracking-wider">Pass ID</span>
                <p className="font-mono font-extrabold text-sm text-foreground">MEM-782190</p>
                <p className="text-xs font-bold text-emerald-600">Active Membership</p>
              </div>
            </div>

            <div className="text-xs text-muted-foreground space-y-1">
              <p>Pass valid for {selectedPlan?.duration}.</p>
              <p className="text-[11px]">Includes {program.freezeDaysAllowed || 30} days vacation freeze rights.</p>
            </div>

            <Button onClick={() => onOpenChange(false)} className="rounded-2xl text-xs h-10 px-6 font-bold">
              Done / Go to My Programs
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import {
  FileText, Upload, Calendar, Clock, MapPin, ShieldCheck, CheckCircle2,
  AlertCircle, ArrowRight, X, Sparkles, Building2
} from 'lucide-react';
import { toast } from 'sonner';

interface RequestQuoteModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  serviceName?: string;
  providerName?: string;
  category?: string;
  onSuccess?: (quoteRequest: any) => void;
}

export default function RequestQuoteModal({
  open,
  onOpenChange,
  serviceName = 'Custom Healthcare Service',
  providerName = 'Verified Provider',
  category = 'Care Service',
  onSuccess,
}: RequestQuoteModalProps) {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [description, setDescription] = useState('');
  const [duration, setDuration] = useState('15 Days');
  const [address, setAddress] = useState('');
  const [startDate, setStartDate] = useState('');
  const [attachedFiles, setAttachedFiles] = useState<string[]>([]);
  const [submitting, setSubmitting] = useState(false);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      const fileNames = Array.from(files).map((f) => f.name);
      setAttachedFiles((prev) => [...prev, ...fileNames]);
      toast.success(`${files.length} document(s) uploaded for clinical evaluation.`);
    }
  };

  const removeFile = (idx: number) => {
    setAttachedFiles((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = () => {
    if (!description.trim()) {
      toast.error('Please describe the required service details or patient needs.');
      return;
    }
    setSubmitting(true);
    setTimeout(() => {
      setSubmitting(false);
      setStep(3);
      onSuccess?.({
        serviceName,
        providerName,
        description,
        duration,
        address,
        startDate,
        attachedFiles,
      });
      toast.success('Quote request submitted! The provider will send an itemized estimate within 24 hours.');
    }, 1000);
  };

  const resetForm = () => {
    setStep(1);
    setDescription('');
    setAddress('');
    setAttachedFiles([]);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-xl max-h-[90vh] overflow-y-auto rounded-3xl p-6">
        <DialogHeader>
          <div className="flex items-center gap-2 text-primary text-xs font-bold uppercase tracking-wider mb-1">
            <Sparkles className="w-4 h-4" /> Flow B: Custom Request & Quote
          </div>
          <DialogTitle className="font-heading text-xl font-bold">
            {step === 3 ? 'Quote Request Confirmed' : `Request an Estimate for ${serviceName}`}
          </DialogTitle>
          <DialogDescription className="text-xs">
            {step === 3
              ? 'Your request is in provider clinical review. An itemized quote with GST and payment escrow will be issued.'
              : `Share patient requirements and documents with ${providerName}. Advance payment is safely held until service commences.`}
          </DialogDescription>
        </DialogHeader>

        {step === 1 && (
          <div className="space-y-4 py-2">
            <div className="p-3 rounded-2xl bg-muted/40 border border-border/40 text-xs flex items-center justify-between">
              <div>
                <span className="text-muted-foreground block">Service Category</span>
                <strong className="text-foreground">{category}</strong>
              </div>
              <div className="text-right">
                <span className="text-muted-foreground block">Provider</span>
                <strong className="text-primary">{providerName}</strong>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground">
                Describe Patient Condition & Required Care <span className="text-destructive">*</span>
              </label>
              <Textarea
                placeholder="E.g., Elderly post-op patient requiring daily 12-hour nursing support, catheter care, and vitals monitoring..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={4}
                className="rounded-2xl text-xs"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-foreground">Expected Duration</label>
                <select
                  value={duration}
                  onChange={(e) => setDuration(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-border/60 bg-card text-xs font-medium"
                >
                  <option value="1 Week">1 Week</option>
                  <option value="15 Days">15 Days</option>
                  <option value="1 Month">1 Month</option>
                  <option value="3 Months">3 Months</option>
                  <option value="Custom / Long-term">Custom / Long-term</option>
                </select>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-foreground">Preferred Start Date</label>
                <Input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  className="rounded-xl text-xs h-10"
                />
              </div>
            </div>

            {/* Document Upload */}
            <div className="space-y-2 pt-1">
              <label className="text-xs font-bold text-foreground flex items-center justify-between">
                <span>Attach Prescriptions or Discharge Summaries</span>
                <span className="text-[11px] text-muted-foreground">Optional, scans ClamAV protected</span>
              </label>
              <div className="border-2 border-dashed border-border/60 rounded-2xl p-4 text-center hover:border-primary/50 transition-colors">
                <input
                  type="file"
                  multiple
                  id="quote-files"
                  className="hidden"
                  onChange={handleFileUpload}
                  accept=".pdf,.jpg,.jpeg,.png"
                />
                <label htmlFor="quote-files" className="cursor-pointer flex flex-col items-center gap-1">
                  <Upload className="w-6 h-6 text-muted-foreground" />
                  <span className="text-xs font-semibold text-primary">Click to upload medical files</span>
                  <span className="text-[10px] text-muted-foreground">PDF, PNG, JPG up to 10MB</span>
                </label>
              </div>

              {attachedFiles.length > 0 && (
                <div className="flex flex-wrap gap-1.5 pt-1">
                  {attachedFiles.map((file, i) => (
                    <span
                      key={i}
                      className="inline-flex items-center gap-1 text-[11px] bg-secondary text-secondary-foreground px-2.5 py-1 rounded-lg border border-border/40"
                    >
                      <FileText className="w-3 h-3 text-primary" />
                      <span className="max-w-[150px] truncate">{file}</span>
                      <button type="button" onClick={() => removeFile(i)} className="text-muted-foreground hover:text-destructive ml-1">
                        <X className="w-3 h-3" />
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>

            <Button
              type="button"
              onClick={() => setStep(2)}
              disabled={!description.trim()}
              className="w-full rounded-2xl h-11 font-bold text-xs mt-2"
            >
              Next: Location & Contact <ArrowRight className="w-4 h-4 ml-1" />
            </Button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground">
                Service Delivery Address / Area <span className="text-destructive">*</span>
              </label>
              <Input
                placeholder="House/Flat number, Street, Landmark, Area, City"
                value={address}
                onChange={(e) => setAddress(e.target.value)}
                className="rounded-xl text-xs h-10"
              />
            </div>

            {/* Escrow & Trust Protection Note */}
            <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/20 space-y-2 text-xs">
              <div className="flex items-center gap-1.5 text-emerald-700 dark:text-emerald-400 font-bold">
                <ShieldCheck className="w-4 h-4" /> FindMedi Escrow Payment Protection
              </div>
              <ul className="text-muted-foreground space-y-1 text-[11px]">
                <li>• No advance payment is charged right now.</li>
                <li>• The provider reviews clinical requirements and shares an itemized quote with GST within 24 hours.</li>
                <li>• Upon your quote approval, advance funds are held in secure escrow until service commences.</li>
              </ul>
            </div>

            <div className="flex items-center gap-2 pt-2">
              <Button
                variant="outline"
                onClick={() => setStep(1)}
                className="rounded-xl text-xs h-11 flex-1"
              >
                Back
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={submitting}
                className="rounded-2xl text-xs h-11 font-bold flex-[2]"
              >
                {submitting ? 'Submitting Request...' : 'Submit Quote Request'}
              </Button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="py-6 text-center space-y-4">
            <div className="w-16 h-16 rounded-full bg-emerald-500/10 text-emerald-600 flex items-center justify-center mx-auto">
              <CheckCircle2 className="w-8 h-8" />
            </div>

            <div className="space-y-1">
              <h3 className="font-heading text-lg font-bold">Request #QR-{Math.floor(100000 + Math.random() * 900000)} Placed</h3>
              <p className="text-xs text-muted-foreground max-w-md mx-auto">
                Your request has been routed to <strong>{providerName}</strong>. You will receive an SMS and in-app notification as soon as the itemized proposal is ready.
              </p>
            </div>

            <div className="p-4 rounded-2xl bg-muted/30 border border-border/40 text-left text-xs space-y-1.5 max-w-md mx-auto">
              <span className="font-bold text-foreground block">Next Steps:</span>
              <p className="text-muted-foreground text-[11px]">• Provider verifies clinical feasibility & staff availability.</p>
              <p className="text-muted-foreground text-[11px]">• Itemized quote issued with 48-hour validity price lock.</p>
              <p className="text-muted-foreground text-[11px]">• You can accept, negotiate in chat, or decline without charge.</p>
            </div>

            <Button onClick={resetForm} className="rounded-2xl text-xs h-10 px-6 font-bold">
              Done / Return to Dashboard
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import {
  BookingFlowType,
  getFlowForCategory,
  getFlowActionLabel,
  RequestQuoteModal,
  EquipmentRentalModal,
  EventRegistrationModal,
  MembershipEnrollModal,
} from './index';
import BookingModal from '@/components/BookingModal';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  Building2, Phone, MapPin, Clock, ShieldCheck, AlertCircle,
  FileText, ExternalLink, QrCode, Sparkles, HeartPulse, CheckCircle2
} from 'lucide-react';
import { isSensitiveCategory } from '@/lib/discreet';
import { toast } from 'sonner';
import { useNavigate } from 'react-router-dom';

export interface UniversalBookingModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  // Optional override for flow type
  flowType?: BookingFlowType;
  // Category / Subtype for flow derivation
  category?: string;
  facilityType?: string;
  facility?: any;
  doctor?: any;
  service?: any;
  initialContext?: any;
  onSuccess?: (result: any) => void;
}

/**
 * Universal Booking & Order Flow Dispatcher (File 05 Spec)
 *
 * Dynamically launches one of the 8 canonical flows:
 * - Flow A: Slot Booking (`BookingModal`)
 * - Flow B: Request & Quote (`RequestQuoteModal`)
 * - Flow C: Order Goods (`OrderGoodsModal` or Pharmacy routing)
 * - Flow D: Recurring / Membership (`MembershipEnrollModal`)
 * - Flow E: Event Registration (`EventRegistrationModal`)
 * - Flow F: Emergency / Instant (Direct Emergency Assist)
 * - Flow G: Rental (`EquipmentRentalModal`)
 * - Flow H: Info Only (Govt facility OPD tokens, helplines, schemes)
 */
export default function UniversalBookingModal({
  open,
  onOpenChange,
  flowType,
  category,
  facilityType,
  facility,
  doctor,
  service,
  initialContext,
  onSuccess,
}: UniversalBookingModalProps) {
  const navigate = useNavigate();

  // Resolve the flow: override > service category > facilityType > facility subtype/category
  const resolvedCategory =
    category ||
    service?.category ||
    facilityType ||
    facility?.subType ||
    facility?.category ||
    doctor?.specialization ||
    '';

  const flow: BookingFlowType = flowType || getFlowForCategory(resolvedCategory);
  const sensitive = isSensitiveCategory(resolvedCategory) || isSensitiveCategory(facility?.name) || isSensitiveCategory(doctor?.specialization);

  // State for Info dialog token generation
  const [opdTokenGenerated, setOpdTokenGenerated] = useState(false);
  const [tokenNumber, setTokenNumber] = useState<string | null>(null);

  const handleGenerateOpdToken = () => {
    const randomToken = `OPD-${Math.floor(100 + Math.random() * 900)}`;
    setTokenNumber(randomToken);
    setOpdTokenGenerated(true);
    toast.success(`Government OPD queue token generated: ${randomToken}`);
    onSuccess?.({ type: 'opd_token', token: randomToken });
  };

  // ── Flow B: Request & Quote ──
  if (flow === 'quote') {
    return (
      <RequestQuoteModal
        open={open}
        onOpenChange={onOpenChange}
        serviceName={service?.name || facility?.name || 'Custom Care Plan'}
        providerName={facility?.name || doctor?.name || 'Verified Provider'}
        category={resolvedCategory}
        onSuccess={onSuccess}
      />
    );
  }

  // ── Flow G: Equipment Rental ──
  if (flow === 'rental') {
    return (
      <EquipmentRentalModal
        open={open}
        onOpenChange={onOpenChange}
        equipment={{
          name: service?.name || facility?.name || 'Medical Equipment Rental',
          monthlyRent: service?.price || 3500,
          deposit: 5000,
          sanitised: true,
          rxRequired: false,
        }}
        onSuccess={onSuccess}
      />
    );
  }

  // ── Flow D: Membership / Recurring ──
  if (flow === 'membership') {
    const programType = resolvedCategory.includes('yoga')
      ? 'yoga'
      : resolvedCategory.includes('dialysis')
      ? 'dialysis'
      : resolvedCategory.includes('meal')
      ? 'meal'
      : resolvedCategory.includes('chronic')
      ? 'chronic_care'
      : 'gym';

    return (
      <MembershipEnrollModal
        open={open}
        onOpenChange={onOpenChange}
        program={{
          title: service?.name || facility?.name || 'Healthcare & Wellness Membership',
          providerName: facility?.name || 'Partner Facility',
          type: programType,
        }}
        onSuccess={onSuccess}
      />
    );
  }

  // ── Flow E: Event Registration ──
  if (flow === 'event') {
    return (
      <EventRegistrationModal
        open={open}
        onOpenChange={onOpenChange}
        event={{
          title: service?.name || facility?.name || 'Health Screening & Wellness Drive',
          organizer: facility?.name || 'Medical Outreach Cell',
          date: service?.date || 'Upcoming Weekend',
          time: service?.time || '09:00 AM – 01:00 PM',
          venue: facility?.address || 'Community Healthcare Centre',
          fee: service?.price || 0,
          eligibility: 'Open to registered participants',
          category: resolvedCategory,
        }}
        onSuccess={onSuccess}
      />
    );
  }

  // ── Flow H: Info Only (Govt PHC/CHC/UPHC, Arogya Mandir, Helplines) ──
  if (flow === 'info') {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="sm:max-w-lg rounded-3xl p-6">
          <DialogHeader>
            <div className="flex items-center gap-2 mb-1">
              <Badge variant="outline" className="bg-emerald-500/10 text-emerald-700 border-emerald-200 dark:border-emerald-800 text-[10px] font-bold uppercase tracking-wider">
                Public Health Facility · Info & Walk-In
              </Badge>
              {sensitive && (
                <Badge variant="outline" className="bg-amber-500/10 text-amber-700 border-amber-200 text-[10px] font-bold">
                  🔒 Discreet
                </Badge>
              )}
            </div>
            <DialogTitle className="font-heading text-xl font-bold">
              {facility?.name || 'Government Health Centre'}
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              Government public health institutions (PHCs, CHCs, Ayushman Arogya Mandirs) provide free or nominal consultation under state health programs. No advance platform booking fee is required.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2 text-xs">
            <div className="bg-muted/40 p-3.5 rounded-2xl border space-y-2">
              <div className="flex items-center gap-2 font-semibold text-foreground">
                <Clock className="w-4 h-4 text-primary" />
                <span>General OPD Timings</span>
              </div>
              <p className="text-muted-foreground pl-6">
                Monday to Saturday: 08:30 AM – 01:30 PM (Morning OPD)
                <br />
                Emergency & Maternity Care: Available 24x7
              </p>
            </div>

            <div className="bg-muted/40 p-3.5 rounded-2xl border space-y-2">
              <div className="flex items-center gap-2 font-semibold text-foreground">
                <MapPin className="w-4 h-4 text-primary" />
                <span>Facility Address & Directions</span>
              </div>
              <p className="text-muted-foreground pl-6">
                {facility?.address || 'Public Health Centre Complex, District Health Office'}
                {facility?.city ? `, ${facility.city}` : ''}
              </p>
            </div>

            {/* Virtual OPD Token Feature */}
            <div className="bg-primary/5 p-4 rounded-2xl border border-primary/20 space-y-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 font-bold text-foreground">
                  <QrCode className="w-4 h-4 text-primary" />
                  <span>Digital Walk-In OPD Queue Token</span>
                </div>
                <Badge className="bg-primary text-primary-foreground text-[10px]">Free</Badge>
              </div>
              <p className="text-muted-foreground text-[11px]">
                Skip the physical counter line by generating a digital token number for today's OPD session.
              </p>

              {opdTokenGenerated ? (
                <div className="p-3 bg-emerald-500/10 border border-emerald-500/30 rounded-xl text-center space-y-1">
                  <span className="text-[10px] uppercase font-bold text-emerald-700 dark:text-emerald-400">Your OPD Token</span>
                  <div className="text-2xl font-black text-emerald-600 font-mono tracking-wider">{tokenNumber}</div>
                  <p className="text-[11px] text-muted-foreground">Present this token at Counter #1 upon arrival</p>
                </div>
              ) : (
                <Button className="w-full h-9 font-semibold text-xs" onClick={handleGenerateOpdToken}>
                  Generate Today's OPD Token
                </Button>
              )}
            </div>
          </div>

          <DialogFooter className="flex-col sm:flex-row gap-2 pt-2">
            <Button
              variant="outline"
              className="w-full sm:w-auto text-xs"
              onClick={() => {
                const query = encodeURIComponent(`${facility?.name || 'Govt Hospital'} ${facility?.city || ''}`);
                window.open(`https://www.google.com/maps/search/?api=1&query=${query}`, '_blank');
              }}
            >
              <ExternalLink className="w-3.5 h-3.5 mr-1" /> Get Directions
            </Button>
            <Button className="w-full sm:w-auto text-xs" onClick={() => onOpenChange(false)}>
              Done
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }

  // ── Flow C: Order Goods (Pharmacy, Medicines, Meals) ──
  if (flow === 'order') {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="sm:max-w-md rounded-3xl p-6">
          <DialogHeader>
            <div className="flex items-center gap-2 text-primary text-xs font-bold uppercase tracking-wider mb-1">
              <Sparkles className="w-4 h-4" /> Flow C: Prescription & Health Order
            </div>
            <DialogTitle className="font-heading text-xl font-bold">
              Order from {facility?.name || 'Verified Pharmacy'}
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              Order verified medicines, generic alternatives, health supplements, or diet kitchen meals. Schedule H/H1 drugs require a valid prescription upload.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-3 text-xs">
            <div className="p-3 bg-muted/40 rounded-2xl border space-y-1">
              <span className="font-bold text-foreground block">Express Delivery Service</span>
              <p className="text-muted-foreground text-[11px]">
                60-90 minute delivery available within 5 km. Temperature-controlled cold chain for insulins & biologics.
              </p>
            </div>

            <div className="p-3 bg-muted/40 rounded-2xl border space-y-1">
              <span className="font-bold text-foreground block">Schedule H/H1 Compliance</span>
              <p className="text-muted-foreground text-[11px]">
                Doctor's registration number and date will be verified by a registered pharmacist before dispatch.
              </p>
            </div>
          </div>

          <DialogFooter className="flex-col sm:flex-row gap-2">
            <Button
              variant="outline"
              className="w-full sm:w-auto text-xs"
              onClick={() => {
                onOpenChange(false);
                navigate('/medicines');
              }}
            >
              Browse Catalogue
            </Button>
            <Button
              className="w-full sm:w-auto text-xs font-semibold"
              onClick={() => {
                onOpenChange(false);
                navigate('/prescriptions?upload=1');
              }}
            >
              Upload Prescription (Rx)
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }

  // ── Flow F: Emergency / Instant ──
  if (flow === 'emergency') {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="sm:max-w-md rounded-3xl p-6 border-rose-500/30">
          <DialogHeader>
            <div className="flex items-center gap-2 text-rose-600 text-xs font-bold uppercase tracking-wider mb-1">
              <HeartPulse className="w-4 h-4 animate-pulse" /> Flow F: Emergency Dispatch
            </div>
            <DialogTitle className="font-heading text-xl font-bold text-rose-600">
              Immediate Emergency Assistance
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              Emergency requests require NO upfront payment gate. Live location dispatch and hospital pre-alerts are initiated immediately.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-3 text-xs">
            <div className="p-3 bg-rose-500/10 rounded-2xl border border-rose-500/20 text-rose-900 dark:text-rose-200">
              <span className="font-bold block mb-1">National Helpline Direct Fallback</span>
              <p className="text-[11px]">
                In life-threatening situations, also dial 112 (National Emergency) or 108 (Ambulance Service) immediately.
              </p>
            </div>
          </div>

          <DialogFooter className="flex-col sm:flex-row gap-2">
            <Button
              variant="outline"
              className="w-full sm:w-auto text-xs"
              onClick={() => {
                window.location.href = 'tel:112';
              }}
            >
              <Phone className="w-3.5 h-3.5 mr-1 text-rose-600" /> Dial 112 Now
            </Button>
            <Button
              className="w-full sm:w-auto text-xs bg-rose-600 hover:bg-rose-700 text-white font-bold"
              onClick={() => {
                onOpenChange(false);
                navigate('/emergency');
              }}
            >
              Open Live Emergency SOS
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }

  // ── Flow A: Slot Booking (Default) ──
  return (
    <BookingModal
      open={open}
      onOpenChange={onOpenChange}
      doctor={doctor}
      facility={facility}
      initialContext={initialContext}
      onSuccess={onSuccess}
    />
  );
}

import { useEffect, useRef } from 'react';
import type { Unmodelled } from '@/lib/apiTypes';

/**
 * Audio wave animation bars.
 * If an active MediaStream is passed, analyzes actual volume frequency data via AnalyserNode.
 * Otherwise provides a smooth rhythmic breathing wave.
 */
export default function AudioWaveVisualizer({ stream, isMuted = false, active = true, barCount = 18 }: Unmodelled) {
  const canvasRef = useRef<Unmodelled>(null);

  useEffect(() => {
    if (!active || isMuted) {
      const canvas: Unmodelled = canvasRef.current;
      if (!canvas) return;
      const ctx: Unmodelled = canvas.getContext('2d');
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      return;
    }

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let animationFrameId: Unmodelled;
    let analyser = null;
    let dataArray = null;
    let audioContext = null;

    if (stream && stream.getAudioTracks().length > 0) {
      try {
        const AudioCtx = window.AudioContext || (window as Unmodelled).webkitAudioContext;
        audioContext = new AudioCtx();
        const source = audioContext.createMediaStreamSource(stream);
        analyser = audioContext.createAnalyser();
        analyser.fftSize = 64;
        source.connect(analyser);
        dataArray = new Uint8Array(analyser.frequencyBinCount);
      } catch (e: any) {
        // Fallback to simulated rhythm
      }
    }

    let phase = 0;

    const render = () => {
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      const barWidth = (width / barCount) * 0.55;
      const spacing = (width - barCount * barWidth) / (barCount + 1);

      if (analyser && dataArray) {
        analyser.getByteFrequencyData(dataArray);
      }

      for (let i = 0; i < barCount; i++) {
        let barHeight;
        if (analyser && dataArray) {
          const sample = dataArray[i % dataArray.length] / 255;
          barHeight = Math.max(4, sample * height * 0.85);
        } else {
          // Smooth sinusoidal ambient wave
          const wave = Math.sin(phase + (i * 0.45));
          barHeight = Math.max(6, (Math.abs(wave) * height * 0.65));
        }

        const x = spacing + i * (barWidth + spacing);
        const y = (height - barHeight) / 2;

        const gradient = ctx.createLinearGradient(0, y, 0, y + barHeight);
        gradient.addColorStop(0, '#10b981'); // emerald
        gradient.addColorStop(0.5, '#06b6d4'); // cyan
        gradient.addColorStop(1, '#3b82f6'); // blue

        ctx.fillStyle = gradient;
        ctx.beginPath();
        if (ctx.roundRect) {
          ctx.roundRect(x, y, barWidth, barHeight, 4);
        } else {
          ctx.rect(x, y, barWidth, barHeight);
        }
        ctx.fill();
      }

      phase += 0.08;
      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      if (animationFrameId) cancelAnimationFrame(animationFrameId);
      if (audioContext && audioContext.state !== 'closed') {
        audioContext.close().catch(() => {});
      }
    };
  }, [stream, isMuted, active, barCount]);

  return (
    <div className="flex items-center justify-center w-full py-2">
      <canvas
        ref={canvasRef}
        width={240}
        height={48}
        className="w-full max-w-[260px] h-12 rounded-lg"
      />
    </div>
  );
}

