const mediaUrl = (u: Unmodelled) => (String(u || '').startsWith('http') ? u : `${getServerOrigin()}${u}`);
const uid = (v: Unmodelled) => (v == null ? '' : (typeof v === 'object' ? String(v._id || v.userId || '') : String(v)));

export default function ChatDashboard() {
  const { user } = useAuth();
  const meId = uid(user?.id || user?._id);

  const audioCallCtx: Unmodelled = useAudioCall();
  const videoCallCtx = useVideoCall();

  // ── Core lists ──
  const [conversations, setConversations] = useState<ApiRow[]>([]);
  const [contacts, setContacts] = useState<ApiRow[]>([]);
  const [requests, setRequests] = useState<ApiRow[]>([]);
  const [blocked, setBlocked] = useState<ApiRow[]>([]);
  const [reports, setReports] = useState<ApiRow[]>([]);
  const [filter, setFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  // ── Active conversation ──
  const [selectedId, setSelectedId] = useState<Unmodelled>(null);
  const [messages, setMessages] = useState<ApiRow[]>([]);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [unreadDividerId, setUnreadDividerId] = useState<Unmodelled>(null);
  const [gallery, setGallery] = useState({ media: [], links: [], files: [], voice: [] });
  const [starred, setStarred] = useState<ApiRow[]>([]);

  // ── Composer ──
  const [draftText, setDraftText] = useState('');
  const [replyTo, setReplyTo] = useState<Unmodelled>(null);
  const [editMessage, setEditMessage] = useState<Unmodelled>(null);
  const [showEmoji, setShowEmoji] = useState(false);
  const [uploading, setUploading] = useState<Unmodelled>(false);
  const [pendingAttachments, setPendingAttachments] = useState<ApiRow[]>([]);
  const fileInputRef: Unmodelled = useRef<Unmodelled>(null);
  const [highlightId, setHighlightId] = useState<any>(null);
  const [recordingVoice, setRecordingVoice] = useState(false);

  // ── Realtime indicators ──
  const [typingUsers, setTypingUsers] = useState<ApiRow>({});
  const [recordingUsers, setRecordingUsers] = useState<ApiRow>({});
  const [onlineUsers, setOnlineUsers] = useState<ApiRow>({});
  const [connected, setConnected] = useState(true);
  const [queuedCount, setQueuedCount] = useState(0);

  // ── CHAT-M-04: offline push (Web Push) + push deep link ──
  const [pushState, setPushState] = useState<PushState>('off');
  const [searchParams] = useSearchParams();
  const pushDeepLinkHandledRef = useRef(false);

  // ── Selection / forward ──
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedMessages, setSelectedMessages] = useState<ApiRow[]>([]);
  const [forwardMessageIds, setForwardMessageIds] = useState<Unmodelled>(null);

  // ── Panels / dialogs ──
  const [showSettings, setShowSettings] = useState(false);
  const [showInfo, setShowInfo] = useState(false);
  const [reactionDetails, setReactionDetails] = useState<Unmodelled>(null);
  const [viewer, setViewer] = useState<Unmodelled>(null);
  const [messageInfo, setMessageInfo] = useState<Unmodelled>(null);

  // ── Prefs & privacy ──
  const [prefs, setPrefsState] = useState(DEFAULT_CHAT_PREFS);
  const [privacy, setPrivacy] = useState<ApiRow>({});
  const [theme, setTheme] = useState('system');
  const [storage, setStorage] = useState<Unmodelled>(null);
  const [backup, setBackup] = useState<ApiRow>({});
  const [backupRunning, setBackupRunning] = useState(false);
  const [pinSet, setPinSet] = useState(false);

  const setPrefs = useCallback((patch: Unmodelled) => {
    setPrefsState((p) => {
      const next = typeof patch === 'function' ? patch(p) : { ...p, ...patch };
      writeChatPrefs(next);
      return next;
    });
  }, []);

  const setPrivacyField = useCallback(async (key: Unmodelled, value: Unmodelled) => {
    const prev = privacy;
    setPrivacy((p) => ({ ...p, [key]: value }));
    try {
      const { data } = await api.put('/chat/privacy', { [key]: value });
      setPrivacy(data);
      setBackup(data.backup || {});
    } catch (err: any) {
      setPrivacy(prev);
      toast.error(userFacingError(err, { fallback: 'Setting save nahi hui' }));
    }
  }, [privacy]);

  const refreshConversations = useCallback(async () => {
    try {
      const { data } = await api.get('/chat/conversations');
      setConversations(data);
    } catch { toast.error('Conversations load nahi hui'); }
  }, []);

  const refreshSideData = useCallback(async () => {
    try {
      const [c, r, b, rep, st] = await Promise.all([
        api.get('/chat/contacts'),
        api.get('/chat/conversations/requests'),
        api.get('/chat/blocked'),
        api.get('/chat/report/my'),
        api.get('/chat/starred'),
      ]);
      setContacts(c.data);
      setRequests(r.data);
      setBlocked(b.data);
      setReports(rep.data);
      setStarred(st.data);
    } catch { /* non-fatal */ }
  }, []);

  const refreshPrivacy = useCallback(async () => {
    try {
      const { data } = await api.get('/chat/privacy');
      setPrivacy(data);
      setPinSet(Boolean(data.appLockPinSet));
      setBackup(data.backup || {});
      try { setTheme(JSON.parse((localStorage.getItem('findmedi_settings') || localStorage.getItem('medicore_settings')) || '{}').theme || 'system'); } catch { /* keep */ }
    } catch { /* non-fatal */ }
  }, []);

  const refreshStorage = useCallback(async () => {
    try {
      const { data } = await api.get('/chat/storage-usage');
      setStorage(data);
    } catch { /* non-fatal */ }
  }, []);

  /*__DERIVED_HERE__*/
  /* ── Derived ── */
  const activeConv = useMemo(
    () => conversations.find((c) => uid(c._id) === uid(selectedId)) || null,
    [conversations, selectedId]
  );
  const peer = useMemo(() => {
    const list = activeConv?.participants || [];
    const other = list.find((p: Unmodelled) => uid(p._id || p) !== meId) || null;
    return other ? {
      ...other,
      _id: uid(other._id || other),
      isOnline: onlineUsers[uid(other._id || other)]?.isOnline ?? other.isOnline,
      lastActive: onlineUsers[uid(other._id || other)]?.lastActive || other.lastActive,
    } : null;
  }, [activeConv, meId, onlineUsers]);

  const tables = useMemo(() => ({
    typing: Object.keys(typingUsers[uid(selectedId)] || {}).length > 0,
    recording: Object.keys(recordingUsers[uid(selectedId)] || {}).length > 0,
  }), [typingUsers, recordingUsers, selectedId]);

  const pinnedMsg = useMemo(
    () => messages.find((m) => m._id === (activeConv?.pinnedMessageId || activeConv?.pinnedMessage?._id)) || null,
    [messages, activeConv]
  );

  const grouped = useMemo(() => {
    const out: Unmodelled[] = [];
    let lastDay = '';
    messages.forEach((m) => {
      const day = new Date(m.createdAt).toDateString();
      if (day !== lastDay) {
        out.push({ kind: 'day', label: format(new Date(m.createdAt), 'dd MMM yyyy'), id: `d-${day}` });
        lastDay = day;
      }
      out.push({ kind: 'msg', message: m });
    });
    return out;
  }, [messages]);

  /* ── Boot: prefs + server data ── */
  useEffect(() => {
    setPrefsState(readChatPrefs());
    refreshPrivacy();
    refreshConversations();
    refreshSideData();
    refreshStorage();
  }, [refreshPrivacy, refreshConversations, refreshSideData, refreshStorage]);

  /* ── Socket.IO: presence, realtime messages, typing/recording, sync ── */
  /* ── Refs, drafts, offline queue flush ── */
  const scrollRef = useRef<Unmodelled>(null);
  const selectedIdRef = useRef<Unmodelled>(null);
  const replyToRef = useRef<Unmodelled>(null);
  const typingTimerRef = useRef<Unmodelled>(null);
  const [drafts, setDrafts] = useState<ApiRow>({});

  useEffect(() => { selectedIdRef.current = selectedId; }, [selectedId]);
  useEffect(() => { replyToRef.current = replyTo; }, [replyTo]);
  useEffect(() => { setDrafts(readDrafts()); }, []);

  const scrollToBottom = useCallback((smooth = true) => {
    const el: Unmodelled = scrollRef.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior: smooth ? 'smooth' : 'auto' });
  }, []);

  /** Reconnect / boot par offline queue ke messages server ko bhejta hai */
  const flushQueue = useCallback(async () => {
    const queue = readQueue(meId);
    if (!queue.length) return;
    let sent = 0;
    for (const item of queue) {
      try {

        const { data } = await api.post('/chat/messages', item.payload);
        setMessages((prev) => prev.map((m) => (m._id === item.clientGeneratedId ? data : m)));
        dequeueMessage(meId, item.clientGeneratedId);
        sent += 1;
      } catch (err: any) {
        if (err.response) {
          // permanent rejection — queue se hatao, failed mark karo
          setMessages((prev) => prev.map((m) => (m._id === item.clientGeneratedId ? { ...m, status: 'failed' } : m)));
          dequeueMessage(meId, item.clientGeneratedId);
        }
        // network error → item queue me hi rahega, agli flush me retry
      }
    }
    setQueuedCount(readQueue(meId).length);
    if (sent > 0) toast.success(`${sent} pending message bhej diye gaye`);
  }, [meId]);

  /** Draft update + typing indicator emit (2.5s debounce stop) */
  const updateDraft = useCallback((convId: Unmodelled, text: Unmodelled) => {
    setDraftText(text);
    saveDraft(convId, text);
    setDrafts(readDrafts());
    if (typingTimerRef.current) clearTimeout(typingTimerRef.current);
    const socket = getSocket();
    socket.emit('chat:typing', { conversationId: convId, isTyping: Boolean(text) });
    typingTimerRef.current = setTimeout(() => {
      socket.emit('chat:typing', { conversationId: convId, isTyping: false });
    }, 2500);
  }, []);

  useEffect(() => {
    if (!meId) return undefined;
    const socket = getSocket();
    const cleanupJoin = joinRoom('chat:join', meId);

    const onConnect = () => {
      setConnected(true);
      socket.emit('chat:presence', { online: true });
      socket.emit('chat:sync', { since: Date.now() - 60000 }); // reconnect → missed events
      flushQueue();
      refreshConversations();
    };
    const onDisconnect = () => setConnected(false);

    socket.on('connect', onConnect);
    socket.on('disconnect', onDisconnect);

    socket.on('chat:receive_message', (msg) => {
      if (!msg?._id) return;
      // Mere hi doosre device se aaya (multi-device sync) — local optimistic replace
      setMessages((prev) => {
        if (!prev.some((m) => m._id === msg._id)) return prev;
        return prev.map((m) => (m._id === msg._id ? msg : m));
      });
      setConversations((prev) => prev.map((c) => (uid(c._id) === uid(msg.conversationId)
        ? { ...c, lastMessage: { content: msg.content, type: msg.type, createdAt: msg.createdAt } }
        : c)));
      if (selectedIdRef.current === uid(msg.conversationId)) {
        api.put(`/chat/messages/read/${msg.conversationId}`).catch(() => {});
      }
    });

    socket.on('chat:read', ({ conversationId, userId }) => {
      if (uid(userId) === meId) return;
      setMessages((prev) => prev.map((m) => (uid(m.conversationId) === uid(conversationId)
        ? { ...m, readCount: Math.max(m.readCount || 0, 1) } : m)));
    });

    socket.on('chat:delivered', ({ conversationId, userId }) => {
      if (uid(userId) === meId) return;
      setMessages((prev) => prev.map((m) => (uid(m.conversationId) === uid(conversationId)
        ? { ...m, deliveredCount: Math.max(m.deliveredCount || 0, 1) } : m)));
    });

    socket.on('chat:reaction', (msg) => {
      setMessages((prev) => prev.map((m) => (m._id === msg._id ? { ...m, ...msg } : m)));
    });
    socket.on('chat:message_edited', (msg) => {
      setMessages((prev) => prev.map((m) => (m._id === msg._id ? { ...m, ...msg } : m)));
    });
    socket.on('chat:message_deleted', ({ messageId, deletedForEveryone }) => {
      setMessages((prev) => (deletedForEveryone
        ? prev.filter((m) => m._id !== messageId)
        : prev.map((m) => (m._id === messageId ? { ...m, deletedForEveryone: true, content: '' } : m))));
    });
    socket.on('chat:pinned_message', ({ conversationId, messageId }) => {
      setConversations((prev) => prev.map((c) => (uid(c._id) === uid(conversationId)
        ? { ...c, pinnedMessageId: messageId } : c)));
    });

    socket.on('chat:typing', ({ conversationId, userId, isTyping }) => {
      if (uid(userId) === meId) return;
      setTypingUsers((prev) => {
        const conv = { ...(prev[conversationId] || {}) };
        if (isTyping) conv[userId] = Date.now();
        else delete conv[userId];
        return { ...prev, [conversationId]: conv };
      });
    });

    socket.on('chat:recording', ({ conversationId, userId, isRecording }) => {
      if (uid(userId) === meId) return;
      setRecordingUsers((prev) => {
        const conv = { ...(prev[conversationId] || {}) };
        if (isRecording) conv[userId] = Date.now();
        else delete conv[userId];
        return { ...prev, [conversationId]: conv };
      });
    });

    socket.on('chat:presence', ({ userId, isOnline, lastActive }) => {
      setOnlineUsers((prev) => ({ ...prev, [userId]: { isOnline, lastActive } }));
    });

    socket.on('chat:conversation_updated', () => refreshConversations());
    socket.on('chat:new_message_notification', () => {
      refreshConversations();
      refreshSideData();
    });
    socket.on('chat:message_request', () => {
      refreshSideData();
      toast.info('New message request');
    });

    return () => {
      cleanupJoin();
      socket.emit('chat:presence', { online: false });
      ['connect', 'disconnect', 'chat:receive_message', 'chat:read', 'chat:delivered',
        'chat:reaction', 'chat:message_edited', 'chat:message_deleted', 'chat:pinned_message',
        'chat:typing', 'chat:recording', 'chat:presence', 'chat:conversation_updated',
        'chat:new_message_notification', 'chat:message_request'].forEach((e) => socket.off(e));
    };
  }, [meId, flushQueue, refreshConversations, refreshSideData]);

  /* ── Conversation open ── */
  const openConversation = useCallback(async (id: Unmodelled) => {
    setSelectedId(id);
    setSelectionMode(false); setSelectedMessages([]);
    setReplyTo(null); setEditMessage(null); setShowInfo(false);
    setDraftText(readDrafts()[id] || '');
    setLoadingMessages(true);
    try {
      const [m, g] = await Promise.all([
        api.get(`/chat/messages/${id}`),
        api.get(`/chat/messages/${id}/media`),
      ]);
      setMessages(m.data);
      setGallery(g.data || { media: [], links: [], files: [], voice: [] });
      api.put(`/chat/messages/read/${id}`).catch(() => {});
      api.put(`/chat/messages/delivered/${id}`).catch(() => {});
      setConversations((prev) => prev.map((c) => (uid(c._id) === uid(id) ? { ...c, unread: 0 } : c)));
      requestAnimationFrame(() => scrollToBottom(false));
    } catch (err: any) {
      toast.error(userFacingError(err, { fallback: 'Messages load nahi hue' }));
    } finally { setLoadingMessages(false); }
  }, [scrollToBottom]);

  /* ── CHAT-M-04: deep link from a push notification (?conversation=) ── */
  useEffect(() => {
    const convId = searchParams.get('conversation');
    if (convId && !pushDeepLinkHandledRef.current) {
      pushDeepLinkHandledRef.current = true;
      openConversation(convId);
    }
  }, [searchParams, openConversation]);

  /* ── CHAT-M-04: Web Push — auto-resync when permission is already granted;
       handles notification-click deep links + subscription rotation from the
       service worker (public/sw.js). ── */
  useEffect(() => {
    let cancelled = false;
    const syncPush = () => {
      if (isPushSupported() && Notification.permission === 'granted') {
        syncChatPush().then((s) => { if (!cancelled) setPushState(s); }).catch(() => {});
      } else {
        setPushState(isPushSupported() ? 'off' : 'unsupported');
      }
    };
    syncPush();

    const onSwMessage = (e: MessageEvent) => {
      const type = e?.data?.type;
      if (type === 'findmedi:notification-click' && typeof e?.data?.url === 'string') {
        try {
          const convId = new URL(e.data.url, window.location.origin).searchParams.get('conversation');
          if (convId) { pushDeepLinkHandledRef.current = true; openConversation(convId); }
        } catch { /* malformed deep link — ignore */ }
      } else if (type === 'findmedi:push-subscription-changed') {
        syncPush();
      }
    };
    if (typeof navigator !== 'undefined' && 'serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('message', onSwMessage);
    }
    return () => {
      cancelled = true;
      if (typeof navigator !== 'undefined' && 'serviceWorker' in navigator) {
        navigator.serviceWorker.removeEventListener('message', onSwMessage);
      }
    };
  }, [openConversation]);

  /* ── CHAT-M-04: bell button — user-gesture permission ask + subscribe ── */
  const enablePush = useCallback(async () => {
    try {
      const res = await enableChatPush();
      setPushState(res.state);
      if (res.ok) { toast.success('Chat push notifications on'); return; }
      if (res.reason === 'permission-denied') {
        toast.error('Browser notification permission block hai — site settings se allow karein');
      } else if (res.reason === 'not-configured') {
        toast.error('Push delivery abhi configured nahi hai');
      } else if (res.reason !== 'unsupported') {
        toast.error('Push enable nahi hua');
      }
    } catch { toast.error('Push enable nahi hua'); }
  }, []);

  /* ── Send (optimistic + offline queue) ── */
  const sendMessage = useCallback(async ({ text = '', type = 'text', attachments = [] } = {}) => {
    const convId = selectedIdRef.current;
    if (!convId || (!text.trim() && !attachments.length)) return;
    const clientGeneratedId = `c-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const replySnapshot: Unmodelled = replyToRef.current;
    setMessages((prev) => [...prev, {
      _id: clientGeneratedId, clientGeneratedId, conversationId: convId,
      sender: { _id: meId, name: user?.name || '', avatar: user?.avatar || '' },
      type, content: text, attachments, replyTo: replySnapshot,
      mine: true, status: 'sending', reactions: [], starred: false,
      deliveredCount: 0, readCount: 0, createdAt: new Date().toISOString(),
    }]);
    requestAnimationFrame(() => scrollToBottom());

    const payload = { conversationId: convId, type, content: text, attachments, replyTo: replySnapshot?._id || null, clientGeneratedId };
    setReplyTo(null);
    saveDraft(convId, ''); setDraftText(''); setDrafts(readDrafts());
    getSocket().emit('chat:typing', { conversationId: convId, isTyping: false });

    if (!connected) {
      enqueueMessage(meId, payload);
      setQueuedCount(readQueue(meId).length);
      setMessages((prev) => prev.map((m) => (m._id === clientGeneratedId ? { ...m, status: 'queued' } : m)));
      toast.info('Offline — queue me hai, internet aane par bhej denge');
      return;
    }
    try {
      const { data } = await api.post('/chat/messages', payload);
      setMessages((prev) => prev.map((m) => (m._id === clientGeneratedId ? data : m)));
      refreshConversations();
    } catch (err: any) {
      if (!err.response) {
        enqueueMessage(meId, payload);
        setQueuedCount(readQueue(meId).length);
        setMessages((prev) => prev.map((m) => (m._id === clientGeneratedId ? { ...m, status: 'queued' } : m)));
      } else {
        toast.error(userFacingError(err, { fallback: 'Message send nahi hua' }));
        setMessages((prev) => prev.map((m) => (m._id === clientGeneratedId ? { ...m, status: 'failed' } : m)));
      }
    }
  }, [meId, user, connected, scrollToBottom, refreshConversations]);

  /* ── Attachments (image/video/doc) + voice ── */
  const uploadDataUrl = useCallback(async (dataUrl: Unmodelled, name: Unmodelled) => {
    const { data } = await api.post('/chat/upload', { dataUrl, name });
    return data; // { url, name, size, mimeType } (CHAT-M-02: camelCase from the server)
  }, []);

  const handleFilesPicked = useCallback(async (fileList: Unmodelled) => {
    const files: Unmodelled[] = Array.from(fileList || []);
    if (!files.length) return;
    setUploading(0.15);
    try {
      const uploaded = [];
      for (const file of files) {
        if (file.size > 25 * 1024 * 1024) { toast.error(`${file.name} 25MB se bada hai`); continue; }
        const dataUrl = await new Promise((resolve, reject) => {
          const fr = new FileReader();
          fr.onload = () => resolve(fr.result);
          fr.onerror = reject;
          fr.readAsDataURL(file);
        });
        setUploading(0.5);

        const meta = await uploadDataUrl(dataUrl, file.name);
        uploaded.push(meta);
      }
      setUploading(false);
      if (!uploaded.length) return;
      const first = uploaded[0];
      // CHAT-M-02: the server returns `mimeType` (camelCase); the old lowercase
      // read left this undefined so every attachment was classified as 'file'.
      const mime = first.mimeType || first.mimetype;
      const type = mime?.startsWith('image/') ? 'image'
        : mime?.startsWith('video/') ? 'video'
          : mime?.startsWith('audio/') ? 'audio' : 'file';
      await sendMessage({ text: draftText.trim(), type, attachments: uploaded } as Unmodelled);
    } catch (err: any) {
      setUploading(false);
      toast.error(userFacingError(err, { fallback: 'Upload fail' }));
    }
  }, [uploadDataUrl, sendMessage, draftText]);

  const handleVoiceSend = useCallback(async ({ dataUrl, duration }: Unmodelled) => {
    setUploading(0.4);
    try {
      const meta = await uploadDataUrl(dataUrl, `voice-${Date.now()}.webm`);
      setUploading(false);
      await sendMessage({ type: 'voice', attachments: [{ ...meta, duration }] } as Unmodelled);
    } catch (err: any) {
      setUploading(false);
      toast.error(userFacingError(err, { fallback: 'Voice message fail' }));
    }
  }, [uploadDataUrl, sendMessage]);

  /* ── Message actions ── */
  const handleReact = useCallback(async (messageId: Unmodelled, emoji: Unmodelled) => {
    setMessages((prev) => prev.map((m) => (m._id === messageId
      ? { ...m, myReaction: m.myReaction === emoji ? null : emoji } : m)));
    try { await api.post(`/chat/messages/${messageId}/reactions`, { emoji }); }
    catch { toast.error('Reaction save nahi hua'); }
  }, []);

  const handleEditSubmit = useCallback(async (messageId: Unmodelled, content: Unmodelled) => {
    try {
      const { data } = await api.put(`/chat/messages/${messageId}`, { content });
      setMessages((prev) => prev.map((m) => (m._id === messageId ? { ...m, ...data, edited: true } : m)));
      setEditMessage(null);
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Edit fail' })); }
  }, []);

  const handleDelete = useCallback(async (messageId: Unmodelled, scope: Unmodelled) => {
    try {
      await api.delete(`/chat/messages/${messageId}`, { params: { scope } });
      setMessages((prev) => (scope === 'everyone'
        ? prev.map((m) => (m._id === messageId ? { ...m, deletedForEveryone: true, content: '', attachments: [] } : m))
        : prev.filter((m) => m._id !== messageId)));
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Delete fail' })); }
  }, []);

  const handleStar = useCallback(async (messageId: Unmodelled, current: Unmodelled) => {
    setMessages((prev) => prev.map((m) => (m._id === messageId ? { ...m, starred: !current } : m)));
    try { await api.put(`/chat/messages/${messageId}/star`, { starred: !current }); refreshSideData(); }
    catch { toast.error('Star update fail'); }
  }, [refreshSideData]);

  const handlePin = useCallback(async (messageId: Unmodelled) => {
    const convId = selectedIdRef.current;
    if (!convId) return;
    try {
      await api.put(`/chat/${convId}/pin-message`, { messageId });
      setConversations((prev) => prev.map((c) => (uid(c._id) === uid(convId) ? { ...c, pinnedMessageId: messageId } : c)));
      toast.success(messageId ? 'Message pinned' : 'Unpinned');
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Pin fail' })); }
  }, []);

  const handleCopy = useCallback((message: Unmodelled) => {
    const text = message.content || (message.attachments || []).map((a: Unmodelled) => a.url).join('\n');
    navigator.clipboard?.writeText(text).then(() => toast.success('Copied')).catch(() => {});
  }, []);

  const handleForward = useCallback(async (targetConvId: Unmodelled) => {
    if (!forwardMessageIds?.length) return;
    try {
      await api.post('/chat/messages/forward', { messageIds: forwardMessageIds, conversationId: targetConvId });
      toast.success('Message forward ho gaya');
      setForwardMessageIds(null); setSelectedMessages([]); setSelectionMode(false);
      refreshConversations();
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Forward fail' })); }
  }, [forwardMessageIds, refreshConversations]);

  const handleRetry = useCallback((message: Unmodelled) => {
    sendMessage({ text: message.content, type: message.type, attachments: message.attachments });
    setMessages((prev) => prev.filter((m) => m._id !== message._id));
  }, [sendMessage]);

  const openMessageInfo = useCallback(async (message: Unmodelled) => {
    try {
      const { data } = await api.get(`/chat/messages/${message._id}/info`);
      setMessageInfo({ message, info: data });
    } catch { setMessageInfo({ message, info: null }); }
  }, []);

  const openReactionDetails = useCallback(async (message: Unmodelled) => {
    try {
      const { data } = await api.get(`/chat/messages/${message._id}/reactions`);
      setReactionDetails({ message, reactions: data });
    } catch { /* ignore */ }
  }, []);

  const reportMessage = useCallback(async (message: Unmodelled) => {
    try {
      await api.post('/chat/report', {
        reportedUserId: uid(peer?.id || peer?._id), messageId: message._id,
        conversationId: selectedIdRef.current, reason: 'other', details: 'Reported from chat',
      });
      toast.success('Report bhej diya');
      refreshSideData();
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Report fail' })); }
  }, [peer, refreshSideData]);

  /* ── Conversation actions ── */
  const convAction = useCallback(async (action: Unmodelled, value: Unmodelled) => {
    const convId = selectedIdRef.current;
    if (!convId) return;
    try {
      await api.put(`/chat/settings/${convId}`, { action, value });
      await refreshConversations();
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Action fail' })); }
  }, [refreshConversations]);

  const markUnread = useCallback(async (convId: Unmodelled) => {
    try {
      await api.put(`/chat/messages/mark-unread/${convId}`);
      setConversations((prev) => prev.map((c) => (uid(c._id) === uid(convId) ? { ...c, unread: Math.max(1, c.unread || 0) } : c)));
    } catch { /* ignore */ }
  }, []);

  const clearChat = useCallback(async () => {
    const convId = selectedIdRef.current;
    if (!convId) return;
    try {
      await api.delete(`/chat/${convId}/clear`);
      setMessages([]);
      toast.success('Chat clear ho gayi (sirf aapke liye)');
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Clear fail' })); }
  }, []);

  const deleteChat = useCallback(async () => {
    const convId = selectedIdRef.current;
    if (!convId) return;
    try {
      await api.delete(`/chat/${convId}`);
      setConversations((prev) => prev.filter((c) => uid(c._id) !== uid(convId)));
      setSelectedId(null); setMessages([]);
      toast.success('Chat delete ho gayi');
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Delete fail' })); }
  }, []);

  const exportChat = useCallback(() => {
    if (!messages.length) { toast.error('Export ke liye messages nahi hain'); return; }
    const lines = messages.map((m) => {
      const who = m.mine ? (user?.name || 'Me') : (peer?.name || 'Contact');
      const when = new Date(m.createdAt).toLocaleString();
      const body = m.deletedForEveryone ? '[deleted]' : (m.content || (m.attachments || []).map((a: Unmodelled) => a.url).join(' '));
      return `[${when}] ${who}: ${body}`;
    });
    const blob = new Blob([lines.join('\n')], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `chat-${peer?.name || 'export'}-${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(a.href);
  }, [messages, user, peer]);

  const respondRequest = useCallback(async (conv: Unmodelled, action: Unmodelled) => {
    try {
      await api.put(`/chat/conversations/${conv._id}/request`, { action });
      refreshSideData(); refreshConversations();
      toast.success(action === 'accept' ? 'Request accept ho gayi' : 'Request hata di');
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Action fail' })); }
  }, [refreshSideData, refreshConversations]);

  const startChat = useCallback(async (contact: Unmodelled) => {
    try {
      const targetId = uid(contact.user?._id || contact.user?.id || contact._id);
      const { data } = await api.post('/chat/conversations', { targetUserId: targetId });
      await refreshConversations();
      await openConversation(data._id);
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Chat start nahi hui' })); }
  }, [refreshConversations, openConversation]);

  const searchInChat = useCallback(async (q: Unmodelled) => {
    const convId = selectedIdRef.current;
    if (!convId || !q) return [];
    try {
      const { data } = await api.get(`/chat/messages/${convId}/search`, { params: { q } });
      return data || [];
    } catch { return []; }
  }, []);

  const jumpToMessage = useCallback((messageId: Unmodelled) => {
    setHighlightId(messageId);
    const el = document.getElementById(`msg-${messageId}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    setTimeout(() => setHighlightId(null), 2200);
  }, []);

  const runBackup = useCallback(async () => {
    setBackupRunning(true);
    try {
      const { data } = await api.post('/chat/backup/run');
      setBackup((b) => ({ ...b, lastBackupAt: data.at }));
      toast.success('Backup complete');
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Backup fail' })); }
    finally { setBackupRunning(false); }
  }, []);

  const setAppPin = useCallback(async (pin: Unmodelled, currentPin: Unmodelled) => {
    try {
      await api.post('/chat/privacy/app-lock/pin', { pin, currentPin });
      setPinSet(true);
      toast.success('PIN set ho gaya');
      return true;
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'PIN set fail' })); return false; }
  }, []);

  const onThemeChange = useCallback((next: Unmodelled) => {
    setTheme(next);
    try {
      const stored = JSON.parse((localStorage.getItem('findmedi_settings') || localStorage.getItem('medicore_settings')) || '{}');
      localStorage.setItem('findmedi_settings', JSON.stringify({ ...stored, theme: next }));
      const prefersDark = typeof window !== 'undefined' && typeof window.matchMedia === 'function'
        ? window.matchMedia('(prefers-color-scheme: dark)').matches
        : false;
      document.documentElement.classList.toggle('dark', next === 'dark' || (next === 'system' && prefersDark));
    } catch { /* ignore */ }
  }, []);

  const requestDesktopPermission = useCallback(() => {
    try { Notification?.requestPermission?.(); } catch { /* ignore */ }
  }, []);

  const unblockUser = useCallback(async (userId: Unmodelled) => {
    const conv = conversations.find((c) => uid((c.participants || []).find((p: Unmodelled) => uid(p._id || p) !== meId)?._id) === uid(userId));
    if (!conv) { toast.error('Conversation nahi mili'); return; }
    try {
      await api.put(`/chat/settings/${conv._id}`, { action: 'block', value: false });
      refreshSideData(); refreshConversations();
      toast.success('Unblock ho gaya');
    } catch (err: any) { toast.error(userFacingError(err, { fallback: 'Unblock fail' })); }
  }, [conversations, meId, refreshSideData, refreshConversations]);

  /* ── Wallpaper apply ── */
  useEffect(() => {
    const isDark = document.documentElement.classList.contains('dark');
    const convWall = readConversationWallpapers()[uid(selectedId)] || prefs.wallpaper;
    const css = (wallpaperCss as Unmodelled)(convWall, isDark);
    const el = document.getElementById('chat-wallpaper');
    if (el) el.style.cssText = css;
  }, [selectedId, prefs.wallpaper, theme]);

  /* ── Draft autosave (local + server) ── */
  useEffect(() => {
    if (!selectedIdRef.current) return undefined;
    const convId = selectedIdRef.current;
    const t = setTimeout(() => {
      if (draftText) api.put(`/chat/${convId}/draft`, { text: draftText }).catch(() => {});
    }, 900);
    return () => clearTimeout(t);
  }, [draftText, selectedId]);

  /* ── Keyboard shortcuts ── */
  useEffect(() => {
    const onKey = (e: Unmodelled) => {
      if (e.key === 'Escape') {
        setShowEmoji(false); setViewer(null); setMessageInfo(null); setReactionDetails(null); setForwardMessageIds(null);
      }
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'f' && selectedIdRef.current) {
        e.preventDefault(); setShowInfo(true);
      }
      if (e.key === 'ArrowUp' && !draftText && messages.length && !editMessage) {
        const last = [...messages].reverse().find((m) => m.mine && !m.deletedForEveryone);
        if (last) { e.preventDefault(); setEditMessage({ _id: last._id, content: last.content }); setDraftText(last.content); }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [draftText, messages, editMessage]);

  const sendCurrent = useCallback(() => {
    if (editMessage) { handleEditSubmit(editMessage._id, draftText.trim()); setDraftText(''); return; }
    sendMessage({ text: draftText.trim() });
  }, [editMessage, draftText, handleEditSubmit, sendMessage]);

  const onComposerKeyDown = (e: Unmodelled) => {
    const enterSends = prefs.sendWithEnter !== false;
    if (e.key === 'Enter' && !e.shiftKey && enterSends) { e.preventDefault(); sendCurrent(); }
  };

  return (
    <div className="flex h-[calc(100vh-64px)] min-h-[520px] -m-4 sm:-m-6 bg-background overflow-hidden">
      <div className={`${selectedId ? 'hidden md:flex' : 'flex'} flex-shrink-0 h-full`}>
        <ChatList
          conversations={conversations.map((c) => ({ ...c, me: meId }))}
          contacts={contacts}
          requests={requests}
          filter={filter}
          setFilter={setFilter}
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          typingUsers={typingUsers}
          recordingUsers={recordingUsers}
          drafts={drafts}
          selectedId={selectedId}
          onOpen={(c: Unmodelled) => openConversation(c._id)}
          onTogglePin={(c: Unmodelled) => api.put(`/chat/settings/${c._id}`, { action: 'pin', value: !c.pinned }).then(refreshConversations)}
          onToggleMute={(c: Unmodelled) => api.put(`/chat/settings/${c._id}`, { action: 'mute', value: !c.muted }).then(refreshConversations)}
          onToggleArchive={(c: Unmodelled) => api.put(`/chat/settings/${c._id}`, { action: 'archive', value: !c.archived }).then(refreshConversations)}
          onDeleteChat={(c: Unmodelled) => api.delete(`/chat/${c._id}`).then(() => {
            setConversations((p) => p.filter((x) => uid(x._id) !== uid(c._id)));
            if (uid(selectedId) === uid(c._id)) setSelectedId(null);
            toast.success('Chat delete ho gayi');
          })}
          onMarkUnread={(c: Unmodelled) => markUnread(c._id)}
          onNewChat={startChat}
          onAcceptRequest={(r: Unmodelled) => respondRequest(r, 'accept')}
          onDeclineRequest={(r: Unmodelled, action: Unmodelled) => respondRequest(r, action)}
          onOpenSettings={() => setShowSettings(true)}
          onTogglePush={enablePush}
          pushState={pushState}
          hidePreviewsInLocked={privacy.hideLockedNotifications !== false}
        />
      </div>

      <div className={`flex-1 flex-col min-w-0 h-full ${selectedId ? 'flex' : 'hidden md:flex'}`}>
        {!selectedId ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center px-6 text-muted-foreground">
            <MessageCircle className="w-14 h-14 mb-4 opacity-30" />
            <p className="text-base font-medium text-foreground">Select a chat to start messaging</p>
            <p className="text-[13px] mt-1">Doctor ↔ patient ke beech secure 1-to-1 chat</p>
          </div>
        ) : (
          <>
            {/*__RENDER_HDR__*/}
            <div className="flex items-center gap-3 px-3 py-2.5 border-b border-border bg-card">
              <button onClick={() => setSelectedId(null)} className="md:hidden p-1.5 rounded-full hover:bg-muted text-muted-foreground">
                <ArrowLeft className="w-5 h-5" />
              </button>
              <button onClick={() => setShowInfo(true)} className="flex items-center gap-3 min-w-0 flex-1 text-left">
                <div className="relative flex-shrink-0">
                  <div className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center overflow-hidden">
                    {peer?.avatar ? <img src={peer.avatar} alt="" className="w-full h-full object-cover" /> : <UserIcon className="w-5 h-5 opacity-60" />}
                  </div>
                  {peer?.isOnline && <span className="absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full bg-emerald-500 border-2 border-card" />}
                </div>
                <div className="min-w-0">
                  <p className="text-[14px] font-semibold truncate">{peer?.name || 'Chat'}</p>
                  <p className="text-[11px] text-muted-foreground truncate">
                    {tables.recording ? 'recording audio…'
                      : tables.typing ? 'typing…'
                        : peer?.isOnline ? 'Online'
                          : peer?.lastActive ? `Last seen ${format(new Date(peer.lastActive), 'dd MMM, HH:mm')}`
                            : 'Offline'}
                  </p>
                </div>
              </button>
              <div className="flex items-center gap-0.5">
                {selectionMode ? (
                  <>
                    <button onClick={() => setForwardMessageIds(selectedMessages)} disabled={!selectedMessages.length} className="px-2.5 py-1.5 rounded-lg bg-muted text-[11px] font-medium disabled:opacity-50">
                      Forward
                    </button>
                    <button
                      onClick={async () => {
                        if (!selectedMessages.length) return;
                        await api.post('/chat/messages/bulk-delete', { messageIds: selectedMessages });
                        setMessages((p) => p.filter((m) => !selectedMessages.includes(m._id)));
                        setSelectedMessages([]); setSelectionMode(false);
                        toast.success('Deleted');
                      }}
                      className="px-2.5 py-1.5 rounded-lg bg-red-500/10 text-red-600 dark:text-red-400 text-[11px] font-medium"
                    >
                      Delete
                    </button>
                    <button onClick={() => { setSelectionMode(false); setSelectedMessages([]); }} className="p-2 rounded-full hover:bg-muted text-muted-foreground">
                      <X className="w-4 h-4" />
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      onClick={() => {
                        if (!peer?._id && !peer?.id) {
                          toast.error('Recipient details missing');
                          return;
                        }
                        audioCallCtx?.initiateCall?.({
                          id: peer._id || peer.id,
                          name: peer.name || 'User',
                          avatar: peer.avatar || '',
                          role: peer.role || 'patient',
                          phone: peer.phone || '',
                        });
                      }}
                      className="p-2 rounded-full hover:bg-muted text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 transition-colors"
                      title="Start Audio Call"
                    >
                      <Phone className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => {
                        if (!peer?._id && !peer?.id) {
                          toast.error('Recipient details missing');
                          return;
                        }
                        videoCallCtx?.initiateVideoCall?.({
                          id: peer._id || peer.id,
                          name: peer.name || 'User',
                          avatar: peer.avatar || '',
                          role: peer.role || 'patient',
                          phone: peer.phone || '',
                        });
                      }}
                      className="p-2 rounded-full hover:bg-muted text-cyan-600 dark:text-cyan-400 hover:text-cyan-700 transition-colors"
                      title="Start Full HD Video Call"
                    >
                      <Video className="w-4 h-4" />
                    </button>
                    <button onClick={() => setSelectionMode(true)} className="p-2 rounded-full hover:bg-muted text-muted-foreground hidden sm:block" title="Select messages">
                      <CheckSquare className="w-4 h-4" />
                    </button>
                    <button onClick={() => setShowInfo(true)} className="p-2 rounded-full hover:bg-muted text-muted-foreground" title="Chat info">
                      <Info className="w-4 h-4" />
                    </button>
                    <button onClick={() => setShowSettings(true)} className="p-2 rounded-full hover:bg-muted text-muted-foreground" title="Chat settings">
                      <SettingsIcon className="w-4 h-4" />
                    </button>
                  </>
                )}
              </div>
            </div>

            {!connected && (
              <div className="px-3 py-1.5 bg-amber-500/10 text-amber-700 dark:text-amber-400 text-[11px] flex items-center gap-1.5 justify-center">
                <WifiOff className="w-3.5 h-3.5" /> Offline — messages queue honge{queuedCount ? ` (${queuedCount} pending)` : ''}
              </div>
            )}

            {pinnedMsg && (
              <div className="px-3 py-1.5 bg-muted/60 border-b border-border flex items-center gap-2">
                <Pin className="w-3.5 h-3.5 text-primary flex-shrink-0" />
                <button onClick={() => jumpToMessage(pinnedMsg._id)} className="text-[11px] truncate flex-1 text-left">
                  {pinnedMsg.content || messagePreview(pinnedMsg) || 'Pinned message'}
                </button>
                <button onClick={() => handlePin(null)} className="text-muted-foreground text-[11px] hover:text-foreground">Unpin</button>
              </div>
            )}

            <div id="chat-wallpaper" ref={scrollRef} className="flex-1 overflow-y-auto chat-scroll relative">
              {loadingMessages ? (
                <div className="flex items-center justify-center h-full text-muted-foreground text-[13px]">Loading…</div>
              ) : !messages.length ? (
                <div className="flex items-center justify-center h-full text-muted-foreground text-[13px]">No messages yet — say hello 👋</div>
              ) : (
                <div className="py-3">
                  {grouped.map((item) => (item.kind === 'day' ? (
                    <DateSeparator key={item.id} label={item.label} />
                  ) : (
                    <div key={item.message._id} id={`msg-${item.message._id}`}>
                      <MessageBubble
                        message={item.message}
                        isMine={item.message.mine || uid(item.message.sender) === meId}
                        prefs={prefs}
                        peerName={peer?.name || 'Contact'}
                        onReply={(m: Unmodelled) => { setReplyTo(m); setEditMessage(null); }}
                        onReact={(m: Unmodelled, emoji: Unmodelled) => handleReact(m._id, emoji)}
                        onEdit={(m: Unmodelled) => { setEditMessage({ _id: m._id, content: m.content }); setDraftText(m.content); }}
                        onDelete={(m: Unmodelled, scope: Unmodelled) => handleDelete(m._id, scope)}
                        onStar={(m: Unmodelled) => handleStar(m._id, m.starred)}
                        onPin={(m: Unmodelled) => handlePin(uid(m._id) === uid(pinnedMsg?._id) ? null : m._id)}
                        onForward={(m: Unmodelled) => setForwardMessageIds([m._id])}
                        onCopy={handleCopy}
                        onInfo={openMessageInfo}
                        onReport={reportMessage}
                        onRetry={handleRetry}
                        onOpenMedia={(att: Unmodelled, all: Unmodelled) => {
                          const list = all || [att];
                          setViewer({ items: list.map((a: Unmodelled) => ({ ...a, url: mediaUrl(a.url) })), index: Math.max(0, list.findIndex((a: Unmodelled) => a.url === att.url)) });
                        }}
                        onJumpToReply={(id: Unmodelled) => id && jumpToMessage(id)}
                        onShowReactions={openReactionDetails}
                        selectionMode={selectionMode}
                        selected={selectedMessages.includes(item.message._id)}
                        onToggleSelect={(m: Unmodelled) => {
                          setSelectionMode(true);
                          setSelectedMessages((p) => (p.includes(m._id) ? p.filter((x) => x !== m._id) : [...p, m._id]));
                        }}
                        highlight={highlightId === item.message._id}
                      />
                    </div>
                  )))}
                </div>
              )}

              <button
                onClick={() => scrollToBottom()}
                className="absolute bottom-4 right-4 w-9 h-9 rounded-full bg-card border border-border shadow-lg flex items-center justify-center text-muted-foreground hover:text-foreground"
                title="Scroll to bottom"
              >
                <ChevronDown className="w-4 h-4" />
              </button>
            </div>

            <div className="border-t border-border bg-card">
              {(replyTo || editMessage) && (
                <div className="flex items-center gap-2 px-3 py-2 border-b border-border bg-muted/40">
                  {editMessage ? <Pencil className="w-4 h-4 text-primary" /> : <Reply className="w-4 h-4 text-primary" />}
                  <div className="min-w-0 flex-1">
                    <p className="text-[11px] font-semibold text-primary">
                      {editMessage ? 'Editing message' : `Replying to ${uid(replyTo?.sender) === meId ? 'yourself' : (peer?.name || 'Contact')}`}
                    </p>
                    <p className="text-[11px] text-muted-foreground truncate">
                      {(editMessage?.content || replyTo?.content || messagePreview(replyTo) || '').slice(0, 120)}
                    </p>
                  </div>
                  <button
                    onClick={() => { setReplyTo(null); setEditMessage(null); setDraftText(''); }}
                    className="p-1.5 rounded-full hover:bg-muted text-muted-foreground"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              )}

              {uploading !== false && (
                <div className="px-3 py-1.5 text-[11px] text-muted-foreground flex items-center gap-2">
                  <span className="w-3 h-3 rounded-full border-2 border-primary border-t-transparent animate-spin" /> Uploading…
                </div>
              )}

              <div className="flex items-end gap-1.5 p-2.5 relative">
                <button onClick={() => setShowEmoji((v) => !v)} className="p-2 rounded-full hover:bg-muted text-muted-foreground flex-shrink-0" title="Emoji / Stickers / GIF">
                  <Smile className="w-5 h-5" />
                </button>
                <button onClick={() => fileInputRef.current?.click()} className="p-2 rounded-full hover:bg-muted text-muted-foreground flex-shrink-0" title="Attach image / video / document">
                  <Paperclip className="w-5 h-5" />
                </button>
                    <input
                      ref={fileInputRef}
                      type="file"
                      multiple
                      accept="image/*,video/*,audio/*,application/pdf,.doc,.docx,.xls,.xlsx"
                      className="hidden"
                  onChange={(e) => { handleFilesPicked(e.target.files); e.target.value = ''; }}
                />

                {recordingVoice ? (
                  <VoiceRecorder
                    onSend={handleVoiceSend}
                    onCancel={() => {
                      setRecordingVoice(false);
                      getSocket().emit('chat:recording', { conversationId: selectedId, isRecording: false });
                    }}
                    onRecordingChange={(on: Unmodelled) => getSocket().emit('chat:recording', { conversationId: selectedId, isRecording: on })}
                  />
                ) : (
                  <>
                    <textarea
                      value={draftText}
                      onChange={(e) => updateDraft(selectedId, e.target.value)}
                      onKeyDown={onComposerKeyDown}
                      placeholder="Type a message…"
                      rows={1}
                      className="flex-1 resize-none bg-muted/50 border border-border rounded-2xl px-3.5 py-2 text-[13.5px] max-h-32 focus:outline-none focus:ring-1 focus:ring-primary/40"
                    />
                    {draftText.trim() || editMessage ? (
                      <button onClick={sendCurrent} className="p-2.5 rounded-full bg-primary text-primary-foreground flex-shrink-0" title="Send">
                        <Send className="w-[18px] h-[18px]" />
                      </button>
                    ) : (
                      <button onClick={() => setRecordingVoice(true)} className="p-2 rounded-full hover:bg-muted text-muted-foreground flex-shrink-0" title="Record voice message">
                        <Mic className="w-5 h-5" />
                      </button>
                    )}
                  </>
                )}

                {showEmoji && (
                  <div className="absolute bottom-[64px] left-2 z-40">
                    <EmojiPicker
                      onPickEmoji={(emoji: Unmodelled) => updateDraft(selectedId, `${draftText}${emoji}`)}
                      onPickSticker={(s: Unmodelled) => { sendMessage({ text: s }); setShowEmoji(false); }}
                      onPickGif={(url: Unmodelled) => { sendMessage({ text: url }); setShowEmoji(false); }}
                      onClose={() => setShowEmoji(false)}
                    />
                  </div>
                )}
              </div>
            </div>
          </>
        )}
      </div>

      {/* ── Info panel ── */}
      <ChatInfoPanel
        open={showInfo && Boolean(selectedId)}
        onClose={() => setShowInfo(false)}
        peer={peer}
        conversation={{ ...(activeConv || {}), wallpaper: readConversationWallpapers()[uid(selectedId)] }}
        media={gallery.media || []}
        links={gallery.links || []}
        files={gallery.files || []}
        starred={starred}
        onToggle={convAction}
        onOpenMedia={(items: Unmodelled, index: Unmodelled) => setViewer({ items: (items || []).map((a: Unmodelled) => ({ ...a, url: mediaUrl(a.url) })), index: index || 0 })}
        onJump={jumpToMessage}
        onClearChat={clearChat}
        onDeleteChat={deleteChat}
        onBlock={() => convAction('block', !(activeConv?.blocked))}
        onReport={() => reportMessage(messages[messages.length - 1] || {})}
        onExport={exportChat}
        onWallpaper={(value: Unmodelled) => {
          setConversationWallpaper(uid(selectedId), value);
          setPrefs({ wallpaper: value });
          convAction('wallpaper', value);
        }}
        onSearch={searchInChat}
        onUnstar={(m: Unmodelled) => handleStar(m._id, true)}
      />

      {/* ── Settings panel ── */}
      <ChatSettingsPanel
        open={showSettings}
        onClose={() => setShowSettings(false)}
        user={user}
        privacy={privacy}
        setPrivacyField={setPrivacyField}
        prefs={prefs}
        setPrefs={setPrefs}
        theme={theme}
        onThemeChange={onThemeChange}
        blocked={blocked}
        onUnblock={unblockUser}
        reports={reports}
        storage={storage}
        backup={backup}
        setBackup={(patch: Unmodelled) => setBackup((b) => ({ ...b, ...patch }))}
        onRunBackup={runBackup}
        backupRunning={backupRunning}
        pinSet={pinSet}
        onSetPin={setAppPin}
        onLogoutAll={() => toast.info('Account settings se logout-all karein')}
        onRequestDesktopPermission={requestDesktopPermission}
        locks={conversations.filter((c) => c.locked).map((c) => ({ ...c, other: (c.participants || []).find((p: Unmodelled) => uid(p._id || p) !== meId) }))}
        onOpenLocked={(c: Unmodelled) => { setShowSettings(false); openConversation(c._id); }}
        onClearAllDrafts={() => {
          Object.keys(readDrafts()).forEach((k) => saveDraft(k, ''));
          setDrafts({}); setDraftText('');
        }}
        onClearCache={() => { toast.success('Cache saaf ho gaya'); refreshStorage(); }}
      />

      {/* ── Media viewer ── */}
      {viewer && (
        <MediaViewer
          items={viewer.items}
          index={viewer.index}
          onClose={() => setViewer(null)}
          onSendToChat={() => setViewer(null)}
        />
      )}

      {/* ── Reaction details ── */}
      {reactionDetails && (
        <div className="fixed inset-0 z-[95] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40" onClick={() => setReactionDetails(null)} />
          <div className="relative bg-background border border-border rounded-2xl shadow-2xl w-full max-w-sm chat-pop-enter">
            <div className="flex items-center justify-between px-4 py-3 border-b border-border">
              <h3 className="text-sm font-semibold">Reactions</h3>
              <button onClick={() => setReactionDetails(null)} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground">
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="p-3 max-h-72 overflow-y-auto scrollbar-thin">
              {reactionDetails.reactions?.length ? reactionDetails.reactions.map((r: Unmodelled, i: Unmodelled) => (
                <div key={`${r.user?._id || i}-${i}`} className="flex items-center gap-3 py-2">
                  <span className="text-lg">{r.emoji}</span>
                  <span className="text-[13px] flex-1 truncate">{r.user?.name || 'User'}{r.mine ? ' (you)' : ''}</span>
                  <span className="text-[10px] text-muted-foreground">
                    {r.at ? new Date(r.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''}
                  </span>
                </div>
              )) : <p className="text-[12px] text-muted-foreground text-center py-6">No reactions</p>}
            </div>
          </div>
        </div>
      )}

      {/* ── Message info ── */}
      {messageInfo && (
        <div className="fixed inset-0 z-[95] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40" onClick={() => setMessageInfo(null)} />
          <div className="relative bg-background border border-border rounded-2xl shadow-2xl w-full max-w-sm chat-pop-enter">
            <div className="flex items-center justify-between px-4 py-3 border-b border-border">
              <h3 className="text-sm font-semibold">Message info</h3>
              <button onClick={() => setMessageInfo(null)} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground">
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="p-4 space-y-3 text-[12px]">
              <div className="bg-muted/50 rounded-lg p-3">
                {messageInfo.message.content || messagePreview(messageInfo.message)}
              </div>
              <p className="flex items-center gap-2">
                <Send className="w-3.5 h-3.5 text-muted-foreground" />
                Sent: {new Date(messageInfo.message.createdAt).toLocaleString()}
              </p>
              <p className="flex items-center gap-2">
                <CheckCheck className="w-3.5 h-3.5 text-muted-foreground" />
                Delivered: {(messageInfo.message.deliveredCount || 0) > 0 ? 'Yes' : 'Pending'}
              </p>
              <p className="flex items-center gap-2">
                <Check className="w-3.5 h-3.5 text-sky-500" />
                Read: {(messageInfo.message.readCount || 0) > 0 ? 'Yes' : 'Not yet'}
              </p>
              {messageInfo.message.edited && (
                <p className="flex items-center gap-2"><Pencil className="w-3.5 h-3.5 text-muted-foreground" /> Edited message</p>
              )}
              {messageInfo.message.starred && (
                <p className="flex items-center gap-2"><Star className="w-3.5 h-3.5 text-amber-500" /> Starred</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ── Forward picker ── */}
      {forwardMessageIds && (
        <div className="fixed inset-0 z-[95] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40" onClick={() => setForwardMessageIds(null)} />
          <div className="relative bg-background border border-border rounded-2xl shadow-2xl w-full max-w-sm chat-pop-enter">
            <div className="flex items-center justify-between px-4 py-3 border-b border-border">
              <h3 className="text-sm font-semibold">Forward to…</h3>
              <button onClick={() => setForwardMessageIds(null)} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground">
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="p-2 max-h-80 overflow-y-auto scrollbar-thin">
              {conversations.filter((c) => uid(c._id) !== uid(selectedId)).length === 0 && (
                <p className="text-[12px] text-muted-foreground text-center py-8">
                  Forward karne ke liye koi doosra chat nahi hai
                </p>
              )}
              {conversations.filter((c) => uid(c._id) !== uid(selectedId)).map((c) => {
                const other = (c.participants || []).find((p: Unmodelled) => uid(p._id || p) !== meId) || {};
                return (
                  <button
                    key={c._id}
                    onClick={() => handleForward(c._id)}
                    className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-muted text-left"
                  >
                    <div className="w-9 h-9 rounded-full bg-primary/10 text-primary flex items-center justify-center overflow-hidden">
                      {other.avatar ? <img src={other.avatar} alt="" className="w-full h-full object-cover" /> : <UserIcon className="w-4 h-4 opacity-60" />}
                    </div>
                    <span className="text-[13px] font-medium truncate flex-1">{other.name || 'Chat'}</span>
                    <Forward className="w-4 h-4 text-muted-foreground" />
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function DateSeparator({ label }: any) {
  return (
    <div className="flex items-center justify-center my-3">
      <span className="px-3 py-1 rounded-full text-[11px] font-medium bg-muted/80 text-muted-foreground border border-border/50 shadow-xs">
        {label}
      </span>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import {
  X, Search, Phone, Mail, Stethoscope, Calendar, Image as ImageIcon, Video, FileText,
  Link2, Star, BellOff, Bell, Lock, Unlock, Trash2, Ban, ShieldAlert, Download, Clock,
  Palette, Eraser, FileDown, Play, User as UserIcon, ChevronRight, Pin, Archive,
} from 'lucide-react';
import { WALLPAPERS, formatBytes, formatDuration } from '@/lib/chatPrefs';
import { Row, SectionCard, Segmented } from './ChatSettingsPanel';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const TABS = [
  { key: 'info', label: 'Info', icon: UserIcon },
  { key: 'media', label: 'Media', icon: ImageIcon },
  { key: 'links', label: 'Links', icon: Link2 },
  { key: 'files', label: 'Files', icon: FileText },
  { key: 'starred', label: 'Starred', icon: Star },
];

const DISAPPEAR_OPTIONS = [
  { value: 'off', label: 'Off' },
  { value: '24', label: '24 hours' },
  { value: '168', label: '7 days' },
  { value: '2160', label: '90 days' },
];

const WALLPAPER_OPTIONS = WALLPAPERS.map((w) => ({ value: w.value, label: w.label }));

/**
 * Right-side "Contact info / Media, links & files" panel.
 * Search tab se conversation ke andar message search hota hai (jump-to-message).
 */
export default function ChatInfoPanel({
  open,
  onClose,
  peer,
  conversation,
  media = [],
  links = [],
  files = [],
  starred = [],
  onToggle,
  onOpenMedia,
  onJump,
  onClearChat,
  onDeleteChat,
  onBlock,
  onReport,
  onExport,
  onWallpaper,
  onSearch,
  onUnstar,
}: Unmodelled) {
  const [tab, setTab] = useState('info');
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<ApiRow[]>([]);
  const [searching, setSearching] = useState(false);
  const [showWallpapers, setShowWallpapers] = useState(false);

  // Search sirf tab ke active hone par aur query change par chalega (debounced)
  useEffect(() => {
    if (!query.trim() || query.trim().length < 2) { setResults([]); return; }
    const t = setTimeout(async () => {
      setSearching(true);
      const found = await onSearch?.(query.trim());
      setResults(found || []);
      setSearching(false);
    }, 400);
    return () => clearTimeout(t);
  }, [query, onSearch]);

  const groupedMedia = useMemo(() => {
    // CHAT-M-02: server stores `mimeType` (camelCase); tolerate legacy lowercase.
    const mimeOf = (m: any) => m.mimeType || m.mimetype;
    const images = media.filter((m: Unmodelled) => mimeOf(m)?.startsWith('image/'));
    const videos = media.filter((m: Unmodelled) => mimeOf(m)?.startsWith('video/'));
    return { images, videos };
  }, [media]);

  const disappeared = conversation?.disappearing?.enabled
    ? String(conversation.disappearing.durationHours || 24)
    : 'off';

  if (!open) return null;

  const isDoctor = (peer?.role || '').includes('doctor');

  return (
    <div className="fixed inset-0 z-[80] flex justify-end chat-pop-enter">
      <div className="absolute inset-0 bg-black/40 md:hidden" onClick={onClose} />
      <div className="relative w-full sm:w-[380px] bg-background border-l border-border h-full flex flex-col shadow-2xl">
        <div className="flex items-center gap-2 px-3 py-3 border-b border-border">
          <button onClick={onClose} className="p-2 rounded-full hover:bg-muted text-muted-foreground">
            <X className="w-5 h-5" />
          </button>
          <h2 className="text-sm font-semibold flex-1">Chat info</h2>
        </div>

        {/* Peer card */}
        <div className="px-4 py-4 text-center border-b border-border">
          <div className="w-20 h-20 mx-auto rounded-full bg-primary/10 text-primary flex items-center justify-center text-2xl font-semibold overflow-hidden mb-3">
            {peer?.avatar
              ? <img src={peer.avatar} alt="" className="w-full h-full object-cover" />
              : <UserIcon className="w-9 h-9 opacity-60" />}
          </div>
          <p className="text-base font-semibold">{peer?.name || 'Contact'}</p>
          <p className="text-[12px] text-muted-foreground capitalize">
            {isDoctor ? 'Doctor' : 'Patient'}{peer?.specialization ? ` · ${peer.specialization}` : ''}
          </p>
          <p className="text-[11px] mt-1">
            {peer?.isOnline
              ? <span className="text-emerald-600 dark:text-emerald-400 font-medium">Online</span>
              : <span className="text-muted-foreground">{peer?.lastActive ? `Last seen ${new Date(peer.lastActive).toLocaleString()}` : 'Offline'}</span>}
          </p>
          <div className="mt-3 space-y-1.5 text-left">
            {peer?.phone && (
              <div className="flex items-center gap-2 text-[12px] text-muted-foreground">
                <Phone className="w-3.5 h-3.5" /> {peer.phone}
              </div>
            )}
            {peer?.email && (
              <div className="flex items-center gap-2 text-[12px] text-muted-foreground break-all">
                <Mail className="w-3.5 h-3.5 flex-shrink-0" /> {peer.email}
              </div>
            )}
            {isDoctor && peer?.specialization && (
              <div className="flex items-center gap-2 text-[12px] text-muted-foreground">
                <Stethoscope className="w-3.5 h-3.5" /> {peer.specialization}
              </div>
            )}
            {peer?.uhid && (
              <div className="flex items-center gap-2 text-[12px] text-muted-foreground">
                <Calendar className="w-3.5 h-3.5" /> UHID: {peer.uhid}
              </div>
            )}
          </div>
        </div>

        <div className="px-3 py-2 border-b border-border">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search in conversation…"
              className="w-full bg-muted/60 border border-border rounded-full pl-8 pr-3 py-1.5 text-[12px] focus:outline-none focus:ring-1 focus:ring-primary/40"
            />
          </div>
          {query.trim().length >= 2 && (
            <div className="mt-2 max-h-[220px] overflow-y-auto scrollbar-thin">
              {searching && <p className="text-[11px] text-muted-foreground py-2 text-center">Searching…</p>}
              {!searching && results.length === 0 && (
                <p className="text-[11px] text-muted-foreground py-2 text-center">No messages found</p>
              )}
              {results.map((m) => (
                <button
                  key={m._id}
                  onClick={() => { onJump?.(m._id); onClose?.(); }}
                  className="w-full text-left px-2 py-2 rounded-lg hover:bg-muted"
                >
                  <p className="text-[12px] line-clamp-2">{m.content || `📎 ${m.type}`}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">{new Date(m.createdAt).toLocaleString()}</p>
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex border-b border-border">
          {TABS.map(({ key, label, icon: Icon }) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              className={`flex-1 flex flex-col items-center gap-0.5 py-2 text-[10px] font-medium border-b-2 transition-colors ${
                tab === key ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              <Icon className="w-4 h-4" /> {label}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto scrollbar-thin p-3">

          {tab === 'info' && (
            <>
              <SectionCard title="Chat settings">
                <Row
                  icon={conversation?.muted ? BellOff : Bell}
                  title="Mute notifications"
                  description={conversation?.muted ? 'Muted' : 'Notifications on'}
                >
                  <button
                    onClick={() => onToggle?.('mute', !conversation?.muted)}
                    className={`px-2.5 py-1.5 rounded-lg text-[11px] font-medium ${conversation?.muted ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/70'}`}
                  >
                    {conversation?.muted ? 'Unmute' : 'Mute'}
                  </button>
                </Row>
                <Row icon={Pin} title="Pin chat" description="Chat list me sabse upar rahega.">
                  <button
                    onClick={() => onToggle?.('pin', !conversation?.pinned)}
                    className={`px-2.5 py-1.5 rounded-lg text-[11px] font-medium ${conversation?.pinned ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/70'}`}
                  >
                    {conversation?.pinned ? 'Unpin' : 'Pin'}
                  </button>
                </Row>
                <Row icon={Archive} title="Archive chat" description="Chat list se hide, archived section me.">
                  <button
                    onClick={() => onToggle?.('archive', !conversation?.archived)}
                    className={`px-2.5 py-1.5 rounded-lg text-[11px] font-medium ${conversation?.archived ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/70'}`}
                  >
                    {conversation?.archived ? 'Unarchive' : 'Archive'}
                  </button>
                </Row>
                <Row icon={conversation?.locked ? Lock : Unlock} title="Chat lock" description="PIN ke bina chat na khule.">
                  <button
                    onClick={() => onToggle?.('lock', !conversation?.locked)}
                    className={`px-2.5 py-1.5 rounded-lg text-[11px] font-medium ${conversation?.locked ? 'bg-primary text-primary-foreground' : 'bg-muted hover:bg-muted/70'}`}
                  >
                    {conversation?.locked ? 'Unlock' : 'Lock'}
                  </button>
                </Row>
                <Row
                  icon={Clock}
                  title="Disappearing messages"
                  description={disappeared === 'off' ? 'Off — messages rehte hain' : `Naye messages ~${disappeared} hours me delete`}
                >
                  <Segmented
                    value={disappeared}
                    options={DISAPPEAR_OPTIONS}
                    onChange={(v: Unmodelled) => {
                      const hours = v === 'off' ? 0 : Number(v);
                      onToggle?.('disappearing', { enabled: hours > 0, durationHours: hours || 24 });
                    }}
                  />
                </Row>
                <Row icon={Palette} title="Wallpaper" description="Is chat ke liye alag background.">
                  <button onClick={() => setShowWallpapers((v) => !v)} className="px-2.5 py-1.5 rounded-lg bg-muted hover:bg-muted/70 text-[11px] font-medium">
                    Change
                  </button>
                </Row>
                {showWallpapers && (
                  <div className="flex flex-wrap gap-1.5 py-2">
                    {WALLPAPERS.map((w) => (
                      <button
                        key={w.value}
                        onClick={() => { onWallpaper?.(w.value); setShowWallpapers(false); }}
                        style={{ background: w.css }}
                        title={w.label}
                        className={`w-9 h-9 rounded-lg border ${conversation?.myWallpaper === w.value ? 'border-primary ring-2 ring-primary/30' : 'border-border'}`}
                      />
                    ))}
                  </div>
                )}
              </SectionCard>

              <SectionCard title="Quick view">
                <Row icon={ImageIcon} title="Media" description={`${groupedMedia.images.length} photos · ${groupedMedia.videos.length} videos`}>
                  <button onClick={() => setTab('media')} className="text-muted-foreground"><ChevronRight className="w-4 h-4" /></button>
                </Row>
                <Row icon={Link2} title="Links" description={`${links.length} shared links`}>
                  <button onClick={() => setTab('links')} className="text-muted-foreground"><ChevronRight className="w-4 h-4" /></button>
                </Row>
                <Row icon={FileText} title="Documents" description={`${files.length} files`}>
                  <button onClick={() => setTab('files')} className="text-muted-foreground"><ChevronRight className="w-4 h-4" /></button>
                </Row>
                <Row icon={Star} title="Starred messages" description={`${starred.length} saved`}>
                  <button onClick={() => setTab('starred')} className="text-muted-foreground"><ChevronRight className="w-4 h-4" /></button>
                </Row>
              </SectionCard>
            </>
          )}

          {tab === 'media' && (
            <>
              {groupedMedia.images.length === 0 && groupedMedia.videos.length === 0 && (
                <p className="text-[12px] text-muted-foreground text-center py-8">Abhi koi media share nahi hui.</p>
              )}
              <div className="grid grid-cols-3 gap-1.5">
                {groupedMedia.images.map((m: Unmodelled, i: Unmodelled) => (
                  <button
                    key={m.url}
                    onClick={() => onOpenMedia?.(groupedMedia.images, i)}
                    className="aspect-square rounded-lg overflow-hidden border border-border"
                  >
                    <img src={m.thumbnail || m.url} alt="" className="w-full h-full object-cover" loading="lazy" />
                  </button>
                ))}
                {groupedMedia.videos.map((m: Unmodelled) => (
                  <button
                    key={m.url}
                    onClick={() => onOpenMedia?.([m], 0)}
                    className="aspect-square rounded-lg overflow-hidden border border-border relative bg-black/40"
                  >
                    <video src={m.url} muted className="w-full h-full object-cover" />
                    <span className="absolute inset-0 flex items-center justify-center">
                      <Play className="w-6 h-6 text-white" />
                    </span>
                  </button>
                ))}
              </div>
              {groupedMedia.videos.length > 0 && (
                <p className="text-[11px] text-muted-foreground mt-2">
                  Total video duration: {formatDuration(groupedMedia.videos.reduce((s: Unmodelled, v: Unmodelled) => s + (v.duration || 0), 0))}
                </p>
              )}
            </>
          )}

          {tab === 'links' && (
            <>
              {links.length === 0 && <p className="text-[12px] text-muted-foreground text-center py-8">Koi link share nahi hua.</p>}
              {links.map((l: Unmodelled) => (
                <a
                  key={`${l.url}-${l.createdAt}`}
                  href={l.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-start gap-2 p-2 rounded-lg hover:bg-muted"
                >
                  <Link2 className="w-4 h-4 mt-0.5 text-muted-foreground flex-shrink-0" />
                  <span className="min-w-0">
                    <span className="block text-[12px] break-all">{l.url}</span>
                    <span className="block text-[10px] text-muted-foreground">{new Date(l.createdAt).toLocaleString()}</span>
                  </span>
                </a>
              ))}
            </>
          )}

          {tab === 'files' && (
            <>
              {files.length === 0 && <p className="text-[12px] text-muted-foreground text-center py-8">Koi document share nahi hua.</p>}
              {files.map((f: Unmodelled) => (
                <div key={f.url} className="flex items-center gap-2 p-2 rounded-lg hover:bg-muted">
                  <FileText className="w-7 h-7 text-muted-foreground flex-shrink-0" />
                  <div className="min-w-0 flex-1">
                    <p className="text-[12px] font-medium truncate">{f.name || 'Document'}</p>
                    <p className="text-[10px] text-muted-foreground">
                      {formatBytes(f.size || 0)} · {new Date(f.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                  <a href={f.url} download={f.name} target="_blank" rel="noopener noreferrer" className="p-1.5 rounded-lg hover:bg-background">
                    <Download className="w-4 h-4" />
                  </a>
                </div>
              ))}
            </>
          )}

          {tab === 'starred' && (
            <>
              {starred.length === 0 && <p className="text-[12px] text-muted-foreground text-center py-8">Koi message star nahi kiya.</p>}
              {starred.map((m: Unmodelled) => (
                <div key={m._id} className="flex items-start gap-2 p-2 rounded-lg hover:bg-muted">
                  <button onClick={() => { onJump?.(m._id); onClose?.(); }} className="flex-1 text-left min-w-0">
                    <p className="text-[12px] line-clamp-2">{m.content || `📎 ${m.type}`}</p>
                    <p className="text-[10px] text-muted-foreground mt-0.5">
                      {String(m.sender?._id) === String(peer?._id) ? (peer?.name || 'Contact') : 'You'} · {new Date(m.createdAt).toLocaleString()}
                    </p>
                  </button>
                  <button onClick={() => onUnstar?.(m)} className="p-1.5 rounded-lg hover:bg-background text-amber-500" title="Remove from starred">
                    <Star className="w-4 h-4 fill-current" />
                  </button>
                </div>
              ))}
            </>
          )}

          <SectionCard title="Actions">
            <Row icon={Eraser} title="Clear chat" description="Mere liye saare messages hata dein (doosre ke paas rahenge).">
              <button onClick={onClearChat} className="px-2.5 py-1.5 rounded-lg bg-muted hover:bg-muted/70 text-[11px] font-medium">Clear</button>
            </Row>
            <Row icon={FileDown} title="Export chat" description="Chat ka text file download karein.">
              <button onClick={onExport} className="px-2.5 py-1.5 rounded-lg bg-muted hover:bg-muted/70 text-[11px] font-medium">Export</button>
            </Row>
            <Row
              icon={Ban}
              title={conversation?.blocked ? 'Unblock user' : 'Block user'}
              description="Block karne par messages aur calls band ho jaate hain."
              danger={!conversation?.blocked}
            >
              <button onClick={onBlock} className="px-2.5 py-1.5 rounded-lg bg-red-500/10 text-red-600 dark:text-red-400 text-[11px] font-medium">
                {conversation?.blocked ? 'Unblock' : 'Block'}
              </button>
            </Row>
            <Row icon={ShieldAlert} title="Report user" description="Moderation team ko bhejein." danger>
              <button onClick={onReport} className="px-2.5 py-1.5 rounded-lg bg-red-500/10 text-red-600 dark:text-red-400 text-[11px] font-medium">Report</button>
            </Row>
            <Row icon={Trash2} title="Delete chat" description="Chat list se hata dein (history bhi hategi)." danger>
              <button onClick={onDeleteChat} className="px-2.5 py-1.5 rounded-lg bg-red-500/10 text-red-600 dark:text-red-400 text-[11px] font-medium">Delete</button>
            </Row>
          </SectionCard>
        </div>
      </div>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import {
  Search, Pin, Bell, BellOff, Archive, Trash2, MailOpen, CheckCheck, UserPlus, X,
  MessageCircle, User as UserIcon, ShieldAlert, Lock, ChevronDown, Plus, Stethoscope,
} from 'lucide-react';
import { messagePreview, saveDraft } from '@/lib/chatPrefs';
import type { Unmodelled } from '@/lib/apiTypes';

const FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'unread', label: 'Unread' },
  { key: 'archived', label: 'Archived' },
  { key: 'locked', label: 'Locked' },
];

const timeLabel = (dateLike: Unmodelled) => {
  if (!dateLike) return '';
  const d = new Date(dateLike);
  const now = new Date();
  const sameDay = d.toDateString() === now.toDateString();
  if (sameDay) return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const diffDays = Math.floor((now.getTime() - d.getTime()) / 86400000);
  if (diffDays < 7) return d.toLocaleDateString([], { weekday: 'short' });
  return d.toLocaleDateString([], { day: '2-digit', month: 'short' });
};

function Avatar({ user, size = 12 }: Unmodelled) {
  const cls = size === 12 ? 'w-12 h-12' : 'w-10 h-10';
  return (
    <div className={`${cls} rounded-full bg-primary/10 text-primary flex items-center justify-center font-semibold overflow-hidden flex-shrink-0`}>
      {user?.avatar ? <img src={user.avatar} alt="" className="w-full h-full object-cover" /> : <UserIcon className="w-5 h-5 opacity-60" />}
    </div>
  );
}

/**
 * Chat list sidebar — search, filters, pinned/unread/online indicators,
 * typing preview, draft indicator, mute/pin/archive/delete row actions.
 */
export default function ChatList({
  conversations = [],
  contacts = [],
  requests = [],
  filter = 'all',
  setFilter,
  searchQuery = '',
  setSearchQuery,
  typingUsers = {},
  recordingUsers = {},
  drafts = {},
  selectedId,
  onOpen,
  onTogglePin,
  onToggleMute,
  onToggleArchive,
  onDeleteChat,
  onMarkUnread,
  onNewChat,
  onAcceptRequest,
  onDeclineRequest,
  onOpenSettings,
  onTogglePush = undefined as (() => void) | undefined,
  pushState = 'off',
  hidePreviewsInLocked,
}: Unmodelled) {
  const [showContacts, setShowContacts] = useState(false);
  const [contactQuery, setContactQuery] = useState('');

  const filtered = useMemo(() => conversations.filter((c: Unmodelled) => {
    if (filter === 'unread' && !c.unread) return false;
    if (filter === 'archived' && !c.archived) return false;
    if (filter === 'locked' && !c.locked) return false;
    if (filter === 'all' && c.archived) return false;
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      const other = (c.participants || []).find((p: Unmodelled) => String(p._id) !== String(c.me));
      const name = (c.other?.name || other?.name || '').toLowerCase();
      const last = (c.lastMessage?.content || '').toLowerCase();
      if (!name.includes(q) && !last.includes(q)) return false;
    }
    return true;
  }), [conversations, filter, searchQuery]);

  const peerOf = (c: Unmodelled) => c.other || (c.participants || []).find((p: Unmodelled) => String(p._id) !== String(c.me)) || {};

  const visibleContacts = useMemo(() => {
    const q = contactQuery.trim().toLowerCase();
    const list = contacts || [];
    if (!q) return list.slice(0, 40);
    return list.filter((c: Unmodelled) =>
      (c.user?.name || '').toLowerCase().includes(q) ||
      (c.user?.email || '').toLowerCase().includes(q) ||
      (c.user?.uhid || '').toLowerCase().includes(q) ||
      (c.specialization || '').toLowerCase().includes(q)
    );
  }, [contacts, contactQuery]);

  return (
    <div className="w-full md:w-[360px] flex-shrink-0 border-r border-border flex flex-col bg-card h-full">
      {/* Header */}
      <div className="p-3 border-b border-border">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-semibold">Chats</h2>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setShowContacts((v) => !v)}
              className="p-2 rounded-full hover:bg-muted text-muted-foreground"
              title="New chat (doctors / patients)"
            >
              <UserPlus className="w-4.5 h-4.5" style={{ width: 18, height: 18 }} />
            </button>
            {onTogglePush && pushState !== 'unsupported' && pushState !== 'server-off' && (
              <button
                onClick={onTogglePush}
                className={`p-2 rounded-full hover:bg-muted transition-colors ${pushState === 'on' ? 'text-primary' : 'text-muted-foreground'}`}
                title={pushState === 'on' ? 'Push notifications on — click to re-check' : 'Enable push notifications (offline bhi milegi)'}
              >
                {pushState === 'on' ? <Bell className="w-4.5 h-4.5" style={{ width: 18, height: 18 }} /> : <BellOff className="w-4.5 h-4.5" style={{ width: 18, height: 18 }} />}
              </button>
            )}
            <button onClick={onOpenSettings} className="p-2 rounded-full hover:bg-muted text-muted-foreground" title="Chat settings">
              <Lock className="w-4.5 h-4.5" style={{ width: 18, height: 18 }} />
            </button>
          </div>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search chats or messages"
            className="w-full bg-muted/60 border border-border rounded-full py-2 pl-9 pr-3 text-[13px] focus:outline-none focus:ring-1 focus:ring-primary/40"
          />
          {searchQuery && (
            <button onClick={() => setSearchQuery('')} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground">
              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        <div className="flex gap-1.5 mt-2">
          {FILTERS.map((f) => (
            <button
              key={f.key}
              onClick={() => setFilter?.(f.key)}
              className={`px-3 py-1 rounded-full text-[11px] font-medium transition-colors ${
                filter === f.key ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:text-foreground'
              }`}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Message requests (unknown senders) */}
      {requests.length > 0 && filter === 'all' && !searchQuery && (
        <div className="border-b border-border bg-amber-500/5">
          <div className="px-3 py-2 flex items-center gap-2 text-[11px] font-semibold text-amber-700 dark:text-amber-400">
            <ShieldAlert className="w-3.5 h-3.5" /> Message requests ({requests.length})
          </div>
          {requests.map((r: Unmodelled) => (
            <div key={r._id} className="px-3 pb-3">
              <div className="flex items-center gap-3 mb-2">
                <Avatar user={r.other} size={10} />
                <div className="min-w-0">
                  <p className="text-[13px] font-medium truncate">{r.other?.name || 'Unknown user'}</p>
                  <p className="text-[11px] text-muted-foreground truncate">
                    {r.lastMessage?.content || 'Wants to start a chat'}
                  </p>
                </div>
              </div>
              <div className="flex gap-1.5">
                <button
                  onClick={() => onAcceptRequest?.(r)}
                  className="flex-1 px-2.5 py-1.5 rounded-lg bg-primary text-primary-foreground text-[11px] font-medium"
                >
                  Accept
                </button>
                <button
                  onClick={() => onDeclineRequest?.(r, 'decline')}
                  className="px-2.5 py-1.5 rounded-lg bg-muted hover:bg-muted/70 text-[11px] font-medium"
                >
                  Delete
                </button>
                <button
                  onClick={() => onDeclineRequest?.(r, 'block')}
                  className="px-2.5 py-1.5 rounded-lg bg-red-500/10 text-red-600 dark:text-red-400 text-[11px] font-medium"
                >
                  Block
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* New chat: contacts (appointment-linked doctors / patients) */}
      {showContacts && (
        <div className="border-b border-border bg-muted/30 max-h-[45%] overflow-y-auto scrollbar-thin">
          <div className="px-3 py-2 flex items-center justify-between">
            <p className="text-[11px] font-semibold text-muted-foreground">
              {contacts.length} doctor/patient contacts
            </p>
            <button onClick={() => setShowContacts(false)} className="text-muted-foreground"><X className="w-3.5 h-3.5" /></button>
          </div>
          <div className="px-3 pb-2">
            <input
              value={contactQuery}
              onChange={(e) => setContactQuery(e.target.value)}
              placeholder="Search contacts…"
              className="w-full bg-background border border-border rounded-full px-3 py-1.5 text-[12px]"
            />
          </div>
          {visibleContacts.length === 0 && (
            <p className="px-3 pb-3 text-[12px] text-muted-foreground">
              Koi contact nahi mila. Chat sirf un doctors/patients ke saath hoti hai jinke saath appointment hai.
            </p>
          )}
          {visibleContacts.map((c: Unmodelled) => (
            <button
              key={c.user._id}
              onClick={() => { onNewChat?.(c); setShowContacts(false); }}
              className="w-full flex items-center gap-3 px-3 py-2 hover:bg-muted text-left"
            >
              <Avatar user={c.user} size={10} />
              <span className="min-w-0 flex-1">
                <span className="block text-[13px] font-medium truncate">{c.user.name}</span>
                <span className="block text-[11px] text-muted-foreground truncate">
                  {c.specialization || (c.user.role === 'patient' ? `Patient${c.uhid ? ` · ${c.uhid}` : ''}` : c.user.role)}
                  {c.appointmentCount ? ` · ${c.appointmentCount} appointment${c.appointmentCount > 1 ? 's' : ''}` : ''}
                </span>
              </span>
              {c.upcomingCount > 0 && (
                <span className="px-1.5 py-0.5 rounded-full bg-primary/10 text-primary text-[10px] font-semibold">
                  {c.upcomingCount} upcoming
                </span>
              )}
            </button>
          ))}
        </div>
      )}

      <div className="flex-1 overflow-y-auto scrollbar-thin chat-scroll">
        {filtered.length === 0 && (
          <div className="flex flex-col items-center justify-center text-center px-6 py-14 text-muted-foreground">
            <MessageCircle className="w-10 h-10 mb-3 opacity-40" />
            <p className="text-[13px] font-medium text-foreground">
              {filter === 'unread' ? 'No unread chats'
                : filter === 'archived' ? 'No archived chats'
                : filter === 'locked' ? 'No locked chats'
                : 'No conversations yet'}
            </p>
            {filter === 'all' && (
              <>
                <p className="text-[12px] mt-1">
                  Chat sirf un doctors/patients ke saath hoti hai jinke saath appointment hai.
                </p>
                <button
                  onClick={() => setShowContacts(true)}
                  className="mt-4 px-4 py-2 rounded-full bg-primary text-primary-foreground text-[12px] font-medium flex items-center gap-1.5"
                >
                  <Plus className="w-3.5 h-3.5" /> Start a chat
                </button>
              </>
            )}
          </div>
        )}

        {filtered.map((c: Unmodelled) => {
          const peer = peerOf(c);
          const typing = typingUsers[c._id];
          const recording = recordingUsers[c._id];
          const draft = drafts[c._id];
          const isActive = String(selectedId) === String(c._id);
          return (
            <div
              key={c._id}
              onClick={() => onOpen?.(c)}
              className={`group relative flex items-center gap-3 px-3 py-2.5 cursor-pointer transition-colors border-b border-border/40 ${
                isActive ? 'bg-primary/5 border-l-2 border-l-primary' : 'hover:bg-muted/50'
              }`}
            >
              <div className="relative">
                <Avatar user={peer} />
                {peer?.isOnline && (
                  <span className="absolute bottom-0.5 right-0.5 w-3 h-3 rounded-full bg-emerald-500 border-2 border-card" />
                )}
              </div>

              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-1.5">
                  <p className="text-[13.5px] font-semibold truncate flex-1">{peer?.name || 'Chat'}</p>
                  {c.pinned && <Pin className="w-3 h-3 text-muted-foreground flex-shrink-0" />}
                  {c.muted && <BellOff className="w-3 h-3 text-muted-foreground flex-shrink-0" />}
                  {c.locked && <Lock className="w-3 h-3 text-muted-foreground flex-shrink-0" />}
                  <span className="text-[10px] text-muted-foreground flex-shrink-0">
                    {timeLabel(c.lastMessageAt || c.lastMessage?.createdAt)}
                  </span>
                </div>

                <div className="flex items-center gap-2 mt-0.5">
                  {recording ? (
                    <span className="text-[12px] text-red-500 flex items-center gap-1">
                      <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse" /> recording…
                    </span>
                  ) : typing ? (
                    <span className="text-[12px] text-primary flex items-center gap-1">
                      typing
                      <span className="flex gap-0.5">
                        <span className="chat-typing-dot w-1 h-1 rounded-full bg-primary inline-block" />
                        <span className="chat-typing-dot w-1 h-1 rounded-full bg-primary inline-block" />
                        <span className="chat-typing-dot w-1 h-1 rounded-full bg-primary inline-block" />
                      </span>
                    </span>
                  ) : draft ? (
                    <span className="text-[12px] text-muted-foreground truncate flex-1">
                      <span className="text-red-500 font-medium">Draft: </span>{draft}
                    </span>
                  ) : (
                    <span className="text-[12px] text-muted-foreground truncate flex-1">
                      {c.locked && hidePreviewsInLocked
                        ? '🔒 Locked chat — tap to unlock'
                        : (c.lastMessage?.sender && String(c.lastMessage.sender) === String(c.me) ? 'You: ' : '') + messagePreview(c.lastMessage)}
                    </span>
                  )}

                  {c.unread > 0 && (
                    <span className={`min-w-[18px] h-[18px] px-1 rounded-full text-[10px] font-bold flex items-center justify-center flex-shrink-0 ${
                      c.muted ? 'bg-muted-foreground/40 text-background' : 'bg-primary text-primary-foreground'
                    }`}>
                      {c.unread}
                    </span>
                  )}
                </div>
              </div>

              <div className="absolute right-2 top-1 hidden group-hover:flex items-center gap-0.5 bg-card border border-border rounded-full shadow px-1 py-0.5">
                <button onClick={(e) => { e.stopPropagation(); onTogglePin?.(c); }} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground" title={c.pinned ? 'Unpin' : 'Pin'}>
                  <Pin className={`w-3.5 h-3.5 ${c.pinned ? 'fill-current text-primary' : ''}`} />
                </button>
                <button onClick={(e) => { e.stopPropagation(); onToggleMute?.(c); }} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground" title={c.muted ? 'Unmute' : 'Mute'}>
                  <BellOff className={`w-3.5 h-3.5 ${c.muted ? 'text-primary' : ''}`} />
                </button>
                <button onClick={(e) => { e.stopPropagation(); onToggleArchive?.(c); }} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground" title={c.archived ? 'Unarchive' : 'Archive'}>
                  <Archive className="w-3.5 h-3.5" />
                </button>
                <button onClick={(e) => { e.stopPropagation(); onMarkUnread?.(c); }} className="p-1.5 rounded-full hover:bg-muted text-muted-foreground" title="Mark as unread">
                  <MailOpen className="w-3.5 h-3.5" />
                </button>
                <button onClick={(e) => { e.stopPropagation(); onDeleteChat?.(c); }} className="p-1.5 rounded-full hover:bg-muted text-red-500" title="Delete chat">
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          );
        })}
      </div>

      <div className="px-3 py-2 border-t border-border flex items-center justify-between text-[10px] text-muted-foreground">
        <span className="flex items-center gap-1">
          <CheckCheck className="w-3 h-3" /> {conversations.reduce((s: Unmodelled, c: Unmodelled) => s + (c.unread || 0), 0)} unread
        </span>
        <span className="flex items-center gap-1">
          <Stethoscope className="w-3 h-3" /> Doctor ↔ Patient only
        </span>
      </div>
    </div>
  );
}

