            onChange={(e) => setTyped(e.target.value)}
          />
        ) : null}
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button variant="destructive" disabled={!ok} onClick={() => { setTyped(''); onConfirm(); }}>Confirm</Button>
        </DialogFooter>
      </DialogContent>
