      {action}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Siren, FlaskConical, Droplets, CheckCheck, Zap } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { startEmergencyRing, stopEmergencyRing } from '@/utils/emergencyRing';
import type { Unmodelled } from '@/lib/apiTypes';

// Tech 09: fullscreen hardware-locking clinical modal. Reuses the dispatch
// alert pattern (ProviderIncomingCall): z-[99999] viewport lock + Web Audio
// oscillator tone + WakeLock + vibration + countdown. Blocks ALL other UI
// until 1-tap acknowledge. Props:
//   alert: { alertId, kind: 'code_blue'|'lab_panic'|'mtp', title, detail,
//            toneType, actionLabel, room }
//   onAcked(ack), onAction()
const KIND_STYLE: Unmodelled = {
  code_blue: {
    icon: Siren,
    ring: 'border-sky-400',
    glow: 'bg-sky-500/20',
    banner: 'bg-sky-500',
    label: 'CODE BLUE',
    tone: 'code_blue',
  },
  lab_panic: {
    icon: FlaskConical,
    ring: 'border-red-500',
    glow: 'bg-red-500/20',
    banner: 'bg-red-600',
    label: 'STAT LAB PANIC',
    tone: 'lab_panic',
  },
  mtp: {
    icon: Droplets,
    ring: 'border-amber-400',
    glow: 'bg-amber-500/20',
    banner: 'bg-amber-500',
    label: 'MTP — MASSIVE TRANSFUSION',
    tone: 'siren',
  },
};

export default function ClinicalLockingAlert({ alert, onAcked, onAction }: Unmodelled) {
  const [secs, setSecs] = useState(0);
  const [acking, setAcking] = useState(false);
  const style = KIND_STYLE[alert?.kind] || KIND_STYLE.code_blue;
  const Icon = style.icon;

  useEffect(() => {
    try {
      startEmergencyRing(alert?.toneType || style.tone);
    } catch { /* audio unavailable */ }
    const t = setInterval(() => setSecs((s) => s + 1), 1000);
    return () => {
      clearInterval(t);
      try { stopEmergencyRing(); } catch { /* noop */ }
    };
  }, [alert?.alertId]);

  if (!alert) return null;

  const mm = String(Math.floor(secs / 60)).padStart(2, '0');
  const ss = String(secs % 60).padStart(2, '0');

  const ack = async () => {
    setAcking(true);
    try {
      const { api } = await import('@/lib/api');
      const res = await api.ackClinicalAlert(alert.alertId, {
        room: alert.room || '',
        action: 'acknowledged_from_locking_modal',
      });
      try { stopEmergencyRing(); } catch { /* noop */ }
      onAcked?.(res);
    } catch {
      try { stopEmergencyRing(); } catch { /* noop */ }
      onAcked?.({ alertId: alert.alertId, offline: true });
    } finally {
      setAcking(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[99999] bg-slate-950/95 backdrop-blur-xl flex items-center justify-center p-4"
      role="alertdialog"
      aria-modal="true"
      aria-label={style.label}
    >
      <motion.div
        initial={{ scale: 0.92, y: 40 }}
        animate={{ scale: 1, y: 0 }}
        transition={{ type: 'spring', stiffness: 25, damping: 350 }}
        className={`w-full max-w-md rounded-2xl border-2 ${style.ring} bg-slate-900 overflow-hidden`}
      >
        <div className={`${style.banner} px-4 py-2 flex items-center justify-between`}>
          <span className="text-white font-bold tracking-widest text-sm animate-pulse">{style.label}</span>
          <span className="text-white font-mono font-bold tabular-nums">{mm}:{ss}</span>
        </div>
        <div className={`relative px-6 pt-6 pb-4 text-center ${style.glow}`}>
          <div className="mx-auto w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center animate-pulse">
            <Icon className="w-8 h-8 text-white" />
          </div>
          <h2 className="mt-3 text-xl font-bold text-white">{alert.title}</h2>
          {alert.detail ? <p className="mt-1 text-sm text-slate-300">{alert.detail}</p> : null}
        </div>
        <div className="px-4 pb-5 space-y-2">
          {alert.actionLabel ? (
            <Button
              className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-5"
              onClick={() => { onAction?.(alert); }}
            >
              <Zap className="w-4 h-4 mr-2" /> {alert.actionLabel}
            </Button>
          ) : null}
          <Button
            className="w-full bg-white text-slate-900 font-bold py-5"
            onClick={ack}
            disabled={acking}
          >
            <CheckCheck className="w-4 h-4 mr-2" /> {acking ? 'ACKNOWLEDGING…' : 'ACKNOWLEDGE — STOP ALARM'}
          </Button>
          <p className="text-center text-[11px] text-slate-500">UI locked until acknowledged · timer keeps running</p>
        </div>
      </motion.div>
    </motion.div>
  );
}

import React, { useState } from 'react';
import { Navigation, Phone, HeartPulse, CheckCircle2, Siren, FileText, ExternalLink, ShieldAlert, Scale } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { Link } from 'react-router-dom';

interface ActiveHUDProps {
  activeRequest: any;
  onMarkArrived: (requestId: string) => Promise<void>;
  onCompleteVisit: (requestId: string, clinicalReport: any) => Promise<void>;
  onRequestAmbulanceBackup: (requestId: string) => Promise<void>;
}

export default function DoctorActiveEmergencyHUD({
  activeRequest,
  onMarkArrived,
  onCompleteVisit,
  onRequestAmbulanceBackup,
}: ActiveHUDProps) {
  const [pulse, setPulse] = useState('');
  const [bpSys, setBpSys] = useState('');
  const [bpDia, setBpDia] = useState('');
  const [spO2, setSpO2] = useState('');
  const [statMed, setStatMed] = useState('');
  const [assessment, setAssessment] = useState('');
  const [completing, setCompleting] = useState(false);
  const [markingArrived, setMarkingArrived] = useState(false);

  const openExternalNavigation = () => {
    const coords = activeRequest.pickupLocation?.coordinates;
    if (coords && coords.length === 2) {
      const [lng, lat] = coords;
      const url = `https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}&travelmode=driving`;
      window.open(url, '_blank');
    } else {
      toast.info('Pickup GPS coordinates not available for external maps');
    }
  };

  const handleArrival = async () => {
    try {
      setMarkingArrived(true);
      await onMarkArrived(activeRequest._id || activeRequest.requestId);
      toast.success('📍 Marked Arrived on Scene! Begin immediate clinical assessment.');
    } catch (err: any) {
      toast.error(err?.message || 'Failed to update arrival status');
    } finally {
      setMarkingArrived(false);
    }
  };

  const handleFinish = async () => {
    try {
      setCompleting(true);
      await onCompleteVisit(activeRequest._id || activeRequest.requestId, {
        vitals: {
          pulseRate: Number(pulse) || 75,
          bloodPressureSys: Number(bpSys) || 120,
          bloodPressureDia: Number(bpDia) || 80,
          spO2Percentage: Number(spO2) || 98,
        },
        initialAssessment: assessment || 'Patient vitals stabilized at scene.',
        statPrescriptions: statMed ? [{ drugName: statMed, route: 'Oral', instructions: 'Stat dose' }] : [],
        hospitalReferralNeeded: false,
      });
      toast.success('🎉 Emergency Run Completed! Payout credited to your wallet.');
    } catch (err: any) {
      toast.error(err?.message || 'Failed to complete visit');
    } finally {
      setCompleting(false);
    }
  };

  const isEnRoute = activeRequest.status === 'assigned' || activeRequest.status === 'en_route';

  return (
    <div className="bg-card rounded-3xl border-2 border-teal-500/40 p-5 sm:p-6 shadow-2xl space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 border-b border-border/60 pb-4">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-2xl bg-teal-500/20 text-teal-400 flex items-center justify-center flex-shrink-0">
            <HeartPulse className="w-6 h-6 animate-pulse" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-base sm:text-lg font-bold text-foreground">
                Active Run: {activeRequest.patientName}
              </h3>
              <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded-full bg-teal-500/20 text-teal-400 border border-teal-500/30">
                {activeRequest.status}
              </span>
            </div>
            <p className="text-xs text-muted-foreground mt-0.5">{activeRequest.pickupAddress}</p>
          </div>
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          {activeRequest.patientPhone && (
            <a
              href={`tel:${activeRequest.patientPhone}`}
              className="flex-1 sm:flex-none inline-flex items-center justify-center gap-1.5 px-3 py-2 bg-muted hover:bg-muted/80 text-foreground rounded-xl text-xs font-bold transition-colors"
            >
              <Phone className="w-3.5 h-3.5 text-teal-400" /> Call Patient
            </a>
          )}
          <Button
            onClick={openExternalNavigation}
            className="flex-1 sm:flex-none gap-2 bg-cyan-600 hover:bg-cyan-700 text-white rounded-xl text-xs font-bold"
          >
            <Navigation className="w-4 h-4" /> Turn-by-Turn GPS
          </Button>
        </div>
      </div>

      {/* Transit vs Bedside Stepper */}
      {isEnRoute ? (
        <div className="p-4 rounded-2xl bg-teal-500/10 border border-teal-500/20 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <p className="text-xs font-bold text-teal-400 uppercase tracking-wider">En Route To Patient Location</p>
            <p className="text-xs text-muted-foreground mt-0.5">
              Live GPS telemetry is streaming to the patient. Proceed safely to scene.
            </p>
          </div>
          <Button
            onClick={handleArrival}
            disabled={markingArrived}
            className="w-full sm:w-auto bg-teal-500 hover:bg-teal-600 text-white rounded-xl text-xs font-bold shadow-lg"
          >
            <CheckCircle2 className="w-4 h-4 mr-1.5" />
            {markingArrived ? 'Marking...' : 'I Have Arrived on Scene'}
          </Button>
        </div>
      ) : (
        /* Clinical Bedside Assessment Form */
        <div className="space-y-4 pt-1">
          <div className="flex items-center justify-between">
            <h4 className="text-xs font-black uppercase text-foreground tracking-wider flex items-center gap-1.5">
              <FileText className="w-4 h-4 text-teal-400" /> Bedside Triage & Vitals
            </h4>
            <span className="text-[11px] text-muted-foreground">Digital Prescription & Stat Rx</span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div>
              <label className="text-[11px] text-muted-foreground font-semibold block mb-1">Pulse (BPM)</label>
              <Input placeholder="78" value={pulse} onChange={(e) => setPulse(e.target.value)} className="h-9 text-xs rounded-xl" />
            </div>
            <div>
              <label className="text-[11px] text-muted-foreground font-semibold block mb-1">BP (Sys / Dia)</label>
              <div className="flex gap-1">
                <Input placeholder="120" value={bpSys} onChange={(e) => setBpSys(e.target.value)} className="h-9 text-xs rounded-xl" />
                <Input placeholder="80" value={bpDia} onChange={(e) => setBpDia(e.target.value)} className="h-9 text-xs rounded-xl" />
              </div>
            </div>
            <div>
              <label className="text-[11px] text-muted-foreground font-semibold block mb-1">SpO2 (%)</label>
              <Input placeholder="98" value={spO2} onChange={(e) => setSpO2(e.target.value)} className="h-9 text-xs rounded-xl" />
            </div>
            <div>
              <label className="text-[11px] text-muted-foreground font-semibold block mb-1">Stat Medication</label>
              <Input placeholder="e.g. Aspirin 300mg" value={statMed} onChange={(e) => setStatMed(e.target.value)} className="h-9 text-xs rounded-xl" />
            </div>
          </div>

          <div>
            <label className="text-[11px] text-muted-foreground font-semibold block mb-1">Clinical Assessment Notes</label>
            <Input
              placeholder="Clinical observation, interventions performed, patient responsiveness..."
              value={assessment}
              onChange={(e) => setAssessment(e.target.value)}
              className="h-9 text-xs rounded-xl"
            />
          </div>

          {/* Legal / Statutory Compliance Note */}
          <div className="rounded-xl border border-teal-500/20 bg-teal-500/5 p-2.5 flex items-center gap-2 text-[10px] text-muted-foreground">
            <Scale className="w-3.5 h-3.5 text-teal-400 flex-shrink-0" />
            <span>
              Clinical summary is digitally signed in compliance with IT Act 2000 & NMC Code of Medical Ethics. View{' '}
              <Link to="/terms" target="_blank" className="text-primary underline">Emergency Terms</Link>.
            </span>
          </div>

          <div className="flex flex-wrap items-center justify-between gap-3 pt-3 border-t border-border/60">
            <Button
              onClick={() => onRequestAmbulanceBackup(activeRequest._id || activeRequest.requestId)}
              variant="destructive"
              className="gap-2 rounded-xl text-xs font-bold"
            >
              <Siren className="w-4 h-4 animate-bounce" /> Request Backup ICU Ambulance
            </Button>

            <Button
              onClick={handleFinish}
              disabled={completing}
              className="bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-bold shadow-lg"
            >
              <CheckCircle2 className="w-4 h-4 mr-1.5" />
              {completing ? 'Completing...' : 'Complete & Settle Visit'}
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Stethoscope, MapPin, AlertTriangle, ShieldCheck, Heart, User, Phone, Check,
  X, Compass, Navigation, Clock, Activity, Siren, CheckCircle2, ChevronRight, Scale
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Link } from 'react-router-dom';
import EmergencyDoctorTrackingScreen from './EmergencyDoctorTrackingScreen';

const EMERGENCY_CATEGORIES = [
  { id: 'Cardiovascular / Chest Pain', label: 'Severe Chest Pain / Heart Attack', icon: '🫀', severity: 'Critical', bg: 'bg-rose-500/10 text-rose-500 border-rose-500/30' },
  { id: 'Respiratory Distress / Asthma', label: 'Difficulty Breathing / Severe Asthma', icon: '🫁', severity: 'Critical', bg: 'bg-cyan-500/10 text-cyan-500 border-cyan-500/30' },
  { id: 'Severe Trauma / Bleeding', label: 'Accident Trauma / Profuse Bleeding', icon: '🩸', severity: 'Critical', bg: 'bg-red-500/10 text-red-500 border-red-500/30' },
  { id: 'Pediatric High Fever / Seizures', label: 'Child High Fever / Convulsions', icon: '👶', severity: 'Severe', bg: 'bg-amber-500/10 text-amber-500 border-amber-500/30' },
  { id: 'Loss of Consciousness / Stroke', label: 'Sudden Unconsciousness / Facial Droop', icon: '🧠', severity: 'Critical', bg: 'bg-purple-500/10 text-purple-500 border-purple-500/30' },
  { id: 'General Medical Emergency', label: 'Other Acute Medical Crisis', icon: '🩺', severity: 'Severe', bg: 'bg-teal-500/10 text-teal-500 border-teal-500/30' },
];

interface DoctorModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentUser?: any;
}

export default function EmergencyDoctorModal({ isOpen, onClose, currentUser }: DoctorModalProps) {
  const [category, setCategory] = useState(EMERGENCY_CATEGORIES[0].id);
  const [symptoms, setSymptoms] = useState('');
  const [address, setAddress] = useState('');
  const [landmark, setLandmark] = useState('');
  const [patientName, setPatientName] = useState(currentUser?.name || '');
  const [patientPhone, setPatientPhone] = useState(currentUser?.phone || '');
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [locating, setLocating] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [activeRequest, setActiveRequest] = useState<any>(null);
  const [consentAgreed, setConsentAgreed] = useState(true);

  // Auto-acquire patient GPS coordinates on open
  useEffect(() => {
    if (!isOpen) return;
    if (currentUser?.name && !patientName) setPatientName(currentUser.name);
    if (currentUser?.phone && !patientPhone) setPatientPhone(currentUser.phone);

    setLocating(true);
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude });
          setAddress(`GPS Location (${pos.coords.latitude.toFixed(4)}, ${pos.coords.longitude.toFixed(4)})`);
          setLocating(false);
        },
        () => {
          setLocating(false);
          setAddress('Current Residence / Location');
          setCoords({ lat: 23.1815, lng: 79.9864 }); // Fallback
        },
        { enableHighAccuracy: true, timeout: 8000 }
      );
    } else {
      setLocating(false);
      setCoords({ lat: 23.1815, lng: 79.9864 });
    }
  }, [isOpen, currentUser]);

  const handleSubmit = async () => {
    if (!coords) {
      toast.error('Location is required for emergency doctor dispatch');
      return;
    }
    if (!consentAgreed) {
      toast.error('Please accept the Emergency Care Consent and Privacy Policy to proceed');
      return;
    }

    try {
      setSubmitting(true);
      const payload = {
        pickupLocation: {
          type: 'Point',
          coordinates: [coords.lng, coords.lat],
        },
        pickupAddress: address || 'Current GPS Location',
        landmark,
        emergencyCategory: category,
        symptomsDescription: symptoms || 'Urgent physician flying squad requested.',
        patientName: patientName || currentUser?.name || 'Emergency Patient',
        patientPhone: patientPhone || currentUser?.phone || '',
        severity: EMERGENCY_CATEGORIES.find((c) => c.id === category)?.severity || 'Severe',
      };

      const res: any = await api.post('/emergency-doctor/dispatch', payload);

      if (res?.request || res?.data?.request) {
        const reqData = res.request || res.data?.request;
        setActiveRequest(reqData);
        toast.success('🩺 Emergency Doctor Dispatch Initiated! Finding nearest physician...');
      } else {
        toast.success('🚨 Emergency Doctor Dispatch Initiated!');
        setActiveRequest({
          bookingId: `DOC-${Date.now().toString(36).toUpperCase()}`,
          status: 'searching',
          emergencyCategory: category,
          pickupAddress: address,
        });
      }
    } catch (err: any) {
      toast.error(err?.message || 'Failed to dispatch emergency doctor. Please call emergency services.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleCancel = async () => {
    if (activeRequest?._id) {
      try {
        await api.post(`/emergency-doctor/${activeRequest._id}/cancel`, {
          reason: 'Cancelled by patient',
          cancelledBy: 'patient',
        });
      } catch {}
    }
    setActiveRequest(null);
    onClose();
    toast.info('Emergency request cancelled');
  };

  if (!isOpen) return null;

  if (activeRequest) {
    return (
      <EmergencyDoctorTrackingScreen
        request={activeRequest}
        onCancel={handleCancel}
        onClose={() => {
          setActiveRequest(null);
          onClose();
        }}
      />
    );
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/70 backdrop-blur-md flex items-center justify-center p-3 sm:p-4">
      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 15 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 15 }}
        className="relative w-full max-w-xl max-h-[92vh] overflow-y-auto rounded-3xl bg-card border-2 border-teal-500/40 shadow-2xl p-5 sm:p-6"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header Bar */}
        <div className="flex items-start justify-between gap-3 border-b border-border/60 pb-4 mb-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-teal-500 to-cyan-500 text-white flex items-center justify-center shadow-lg relative">
              <span className="absolute inset-0 rounded-2xl bg-teal-400/40 animate-ping" />
              <Stethoscope className="w-6 h-6 text-white relative z-10" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="font-heading text-lg sm:text-xl font-black text-foreground">
                  Emergency Doctor Flying Squad
                </h2>
                <span className="text-[10px] font-black uppercase px-2 py-0.5 rounded-full bg-teal-500 text-white animate-pulse">
                  RAPID RESPONDER
                </span>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">
                Nearby clinic doctor dispatches to your exact GPS location with emergency triage kit
              </p>
            </div>
          </div>
          <button
            onClick={activeRequest ? handleCancel : onClose}
            className="p-2 rounded-xl text-muted-foreground hover:bg-muted/80 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* If Active Request Exists: Show Live Dispatch Radar */}
        {activeRequest ? (
          <div className="space-y-4 py-2">
            <div className="rounded-2xl border-2 border-teal-500/30 bg-teal-500/5 p-4 text-center">
              <div className="w-16 h-16 mx-auto rounded-full bg-teal-500/20 flex items-center justify-center mb-3 relative">
                <span className="absolute inset-0 rounded-full border-2 border-teal-500 animate-ping" />
                <Activity className="w-8 h-8 text-teal-400 animate-pulse" />
              </div>
              <h3 className="font-heading text-base font-bold text-foreground">
                Connecting with Nearest Clinic Doctor
              </h3>
              <p className="text-xs text-muted-foreground mt-1 max-w-sm mx-auto">
                Broadcasting emergency beacon to on-duty physicians within 10 km perimeter...
              </p>
              <div className="mt-3 inline-flex items-center gap-2 px-3 py-1 rounded-full bg-teal-500/20 text-teal-300 font-mono text-xs font-semibold">
                <span>Request ID:</span> {activeRequest.bookingId}
              </div>
            </div>

            {/* Doctor Readiness Kit Preview */}
            <div className="rounded-2xl border border-border/60 bg-muted/30 p-3.5 space-y-2">
              <p className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                <ShieldCheck className="w-4 h-4 text-teal-500" />
                Doctor Arrives Equipped With:
              </p>
              <div className="grid grid-cols-2 gap-2 text-[11px] text-muted-foreground">
                <div className="flex items-center gap-1.5">
                  <CheckCircle2 className="w-3.5 h-3.5 text-teal-500 flex-shrink-0" />
                  <span>BLS & Resuscitation Kit</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <CheckCircle2 className="w-3.5 h-3.5 text-teal-500 flex-shrink-0" />
                  <span>Pulse Oximeter & BP Monitor</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <CheckCircle2 className="w-3.5 h-3.5 text-teal-500 flex-shrink-0" />
                  <span>Nebulizer & Bronchodilators</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <CheckCircle2 className="w-3.5 h-3.5 text-teal-500 flex-shrink-0" />
                  <span>Emergency Stat Injections</span>
                </div>
              </div>
            </div>

            <div className="flex gap-3 pt-2">
              <Button
                variant="destructive"
                className="w-full font-bold text-xs h-11 rounded-xl"
                onClick={handleCancel}
              >
                Cancel Emergency Dispatch
              </Button>
            </div>
          </div>
