import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Stethoscope, Phone, ShieldCheck, MapPin, Clock, Star, Navigation, X, CheckCircle2, Siren, Scale, Video } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { getSocket } from '@/lib/socket';
import { Link } from 'react-router-dom';
import EmergencyVideoRoom from '@/components/emergency/EmergencyVideoRoom';

interface TrackingScreenProps {
  request: any;
  onCancel: () => void;
  onClose?: () => void;
}

export default function EmergencyDoctorTrackingScreen({ request, onCancel, onClose }: TrackingScreenProps) {
  const [status, setStatus] = useState<string>(request.status || 'searching');
  const [doctor, setDoctor] = useState<any>(request.assignedDoctor || request.doctor || null);
  const [etaMinutes, setEtaMinutes] = useState<number>(request.estimatedArrivalMinutes || 10);
  const [distanceKm, setDistanceKm] = useState<number>(request.transitDistanceKm || 3.2);
  // Spec 09: video triage room (LiveKit when configured, graceful fallback inside).
  const [showVideo, setShowVideo] = useState(false);

  const requestId = request._id || request.id || request.requestId;

  useEffect(() => {
    const socket = getSocket();
    if (!socket || !requestId) return;

    const room = `emergency:doctor:${requestId}`;
    socket.emit('join_room', { room });

    // Handle both event names for maximum resilience
    const handleDoctorAssigned = (data: any) => {
      setStatus('assigned');
      if (data.doctor) setDoctor(data.doctor);
      if (data.etaMinutes) setEtaMinutes(data.etaMinutes);
      if (data.distanceKm) setDistanceKm(data.distanceKm);
    };

    const handleGpsUpdate = (data: any) => {
      if (data.etaMinutes) setEtaMinutes(data.etaMinutes);
      if (data.distanceKm) setDistanceKm(data.distanceKm);
    };

    const handleStatusChanged = (data: any) => {
      if (data.status) setStatus(data.status);
    };

    socket.on('emergency_doctor_assigned', handleDoctorAssigned);
    socket.on('emergency_doctor:doctor_assigned', handleDoctorAssigned);
    socket.on('doctor_location_update', handleGpsUpdate);
    socket.on('emergency_doctor:gps_update', handleGpsUpdate);
    socket.on('emergency_doctor:status_changed', handleStatusChanged);
    socket.on('doctor_arrived_on_scene', () => setStatus('arrived'));
    socket.on('emergency_doctor_completed', () => setStatus('completed'));

    return () => {
      socket.emit('leave_room', { room });
      socket.off('emergency_doctor_assigned', handleDoctorAssigned);
      socket.off('emergency_doctor:doctor_assigned', handleDoctorAssigned);
      socket.off('doctor_location_update', handleGpsUpdate);
      socket.off('emergency_doctor:gps_update', handleGpsUpdate);
      socket.off('emergency_doctor:status_changed', handleStatusChanged);
      socket.off('doctor_arrived_on_scene');
      socket.off('emergency_doctor_completed');
    };
  }, [requestId]);

  const reqNum = request.bookingId || request.requestNumber || `DOC-${String(requestId).slice(-6)}`;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/85 backdrop-blur-xl p-3 sm:p-4">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-md bg-card rounded-3xl border-2 border-teal-500/50 p-5 sm:p-6 shadow-2xl text-card-foreground space-y-5"
      >
        {status === 'searching' ? (
          /* RADAR SEARCHING STATE */
          <div className="text-center py-4 space-y-4">
            <div className="relative w-28 h-28 mx-auto flex items-center justify-center">
              <span className="absolute inset-0 rounded-full bg-teal-500/20 animate-ping duration-1000" />
              <span className="absolute -inset-4 rounded-full border border-teal-500/40 animate-spin" />
              <div className="w-20 h-20 rounded-full bg-gradient-to-tr from-teal-500 to-cyan-500 text-white flex items-center justify-center shadow-xl">
                <Stethoscope className="w-10 h-10 animate-pulse" />
              </div>
            </div>

            <div>
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-teal-500/15 text-teal-400 font-mono text-xs font-semibold mb-2">
                <span>Request:</span> {reqNum}
              </div>
              <h3 className="font-heading font-black text-lg sm:text-xl text-foreground">
                Alerting Nearby Emergency Doctors...
              </h3>
              <p className="text-xs text-muted-foreground mt-1 max-w-xs mx-auto">
                Broadcasting emergency beacon to verified clinic physicians within your 5–15 km perimeter.
              </p>
            </div>

            <div className="rounded-2xl border border-teal-500/20 bg-teal-500/5 p-3 text-[11px] text-muted-foreground text-left space-y-1">
              <p className="font-semibold text-foreground flex items-center gap-1.5">
                <ShieldCheck className="w-4 h-4 text-teal-400" /> Statutory Rapid Response:
              </p>
              <p>
                First responding clinic physician will accept the dispatch and initiate immediate transit with basic life support kit.
              </p>
            </div>

            <Button onClick={onCancel} variant="outline" className="w-full rounded-xl text-xs font-bold h-11 border-border/80 text-muted-foreground hover:bg-muted">
              Cancel Emergency Dispatch
            </Button>
          </div>
        ) : (
          /* DOCTOR EN ROUTE / ARRIVED TRACKING HUD */
          <div className="space-y-4">
            <div className="flex items-center justify-between border-b border-border/60 pb-3">
              <div className="flex items-center gap-2">
                <span className={`w-3 h-3 rounded-full ${status === 'arrived' ? 'bg-emerald-500' : 'bg-teal-400'} animate-pulse`} />
                <span className="text-xs font-black uppercase text-teal-400 tracking-wider">
                  {status === 'arrived' ? 'Doctor Has Arrived on Scene!' : status === 'completed' ? 'Visit Completed' : 'Emergency Doctor En Route'}
                </span>
              </div>
              <span className="text-xs font-mono font-bold text-muted-foreground">{reqNum}</span>
            </div>

            {/* Doctor Profile Banner */}
            <div className="p-4 rounded-2xl bg-teal-500/10 border border-teal-500/30 flex items-center gap-3.5">
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-tr from-teal-500 to-cyan-500 text-white flex items-center justify-center text-xl font-bold flex-shrink-0 shadow-md">
                {doctor?.name ? doctor.name[0] : 'D'}
              </div>
              <div className="flex-1 min-w-0 text-xs">
                <h4 className="font-bold text-sm text-foreground truncate">
                  Dr. {doctor?.name || 'Assigned Physician'}
                </h4>
                <p className="text-muted-foreground truncate">{doctor?.specialization || 'Clinical Practitioner'}</p>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-[10px] px-2 py-0.5 rounded-full bg-teal-500/20 text-teal-400 font-semibold flex items-center gap-1">
                    <ShieldCheck className="w-3 h-3" /> NMC-VERIFIED
                  </span>
                  <span className="flex items-center gap-0.5 text-amber-400 font-bold text-[10px]">
                    <Star className="w-3 h-3 fill-amber-400" /> {doctor?.rating || 4.9}
                  </span>
                </div>
              </div>
            </div>

            {/* ETA & Distance Telemetry */}
            <div className="grid grid-cols-2 gap-3 text-center">
              <div className="p-3.5 rounded-2xl bg-card border border-border/70 shadow-sm">
                <span className="text-[10px] text-muted-foreground uppercase font-bold block">Estimated Arrival</span>
                <span className="text-lg font-black text-cyan-400 font-mono">
                  {status === 'arrived' ? 'ON SCENE' : `~${etaMinutes} Mins`}
                </span>
              </div>
              <div className="p-3.5 rounded-2xl bg-card border border-border/70 shadow-sm">
                <span className="text-[10px] text-muted-foreground uppercase font-bold block">Distance Away</span>
                <span className="text-lg font-black text-foreground font-mono">
                  {status === 'arrived' ? '0.0 Km' : `${distanceKm} Km`}
                </span>
              </div>
            </div>

            {/* Direct Calling & Emergency Actions */}
            <div className="space-y-2 pt-1">
              {(status === 'assigned' || status === 'in_progress') && (
                <Button
                  onClick={() => setShowVideo(true)}
                  className="w-full h-12 rounded-xl bg-cyan-600 hover:bg-cyan-700 text-white font-bold text-xs flex items-center justify-center gap-2 transition-colors shadow-lg"
                >
                  <Video className="w-4 h-4" /> Start Video Triage
                </Button>
              )}
              {doctor?.phone ? (
                <a
                  href={`tel:${doctor.phone}`}
                  className="w-full h-12 rounded-xl bg-teal-600 hover:bg-teal-700 text-white font-bold text-xs flex items-center justify-center gap-2 transition-colors shadow-lg"
                >
                  <Phone className="w-4 h-4" /> Call Attending Doctor ({doctor.phone})
                </a>
              ) : (
                <a
                  href="tel:108"
                  className="w-full h-12 rounded-xl bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs flex items-center justify-center gap-2 transition-colors shadow-lg"
                >
                  <Siren className="w-4 h-4" /> Call 108 Emergency Ambulance Hotline
                </a>
              )}
            </div>

            {/* Legal / Statutory Compliance Note */}
            <div className="rounded-xl border border-teal-500/20 bg-teal-500/5 p-2.5 flex items-center gap-2 text-[10px] text-muted-foreground">
              <Scale className="w-3.5 h-3.5 text-teal-400 flex-shrink-0" />
              <span>
                Encrypted GPS Telemetry in compliance with DPDP Act 2023. See{' '}
                <Link to="/terms" target="_blank" className="text-primary underline">Terms</Link> &{' '}
                <Link to="/privacy" target="_blank" className="text-primary underline">Privacy</Link>.
              </span>
            </div>

            {status === 'completed' && onClose && (
              <Button onClick={onClose} className="w-full rounded-xl text-xs font-bold bg-emerald-600 hover:bg-emerald-700 text-white h-11">
                Close Tracking Screen
              </Button>
            )}

            {showVideo && (
              <EmergencyVideoRoom
                room={String(requestId)}
                onClose={() => setShowVideo(false)}
              />
            )}
          </div>
        )}
      </motion.div>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/context/AuthContext';
import { getSocket } from '@/lib/socket';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { emergencyOverlayActive } from '@/lib/emergencyState';
import SOSButton from './SOSButton';
import DualEmergencyFAB from './DualEmergencyFAB';
import EmergencyDoctorModal from './EmergencyDoctorModal';
import SOSConfirmModal from './SOSConfirmModal';
import SOSSearchingScreen from './SOSSearchingScreen';
import SOSAssignedScreen from './SOSAssignedScreen';
import ProviderIncomingCall from './ProviderIncomingCall';
import ProviderHospitalSelect from './ProviderHospitalSelect';
import SOSModeSelect, { type SOSMode } from './SOSModeSelect';
import SOSVehicleTypeSelect from './SOSVehicleTypeSelect';
import SOSRadiusOptions from './SOSRadiusOptions';
import SOSAcceptedList from './SOSAcceptedList';
import { sosVehicleState } from '@/lib/emergencyState';
import { installEmergencyAudioUnlock } from '@/utils/emergencyRing';
import { userFacingError } from '@/lib/errorCopy';

export default function EmergencyFlowController() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [confirmModalOpen, setConfirmModalOpen] = useState(false);
  const [doctorModalOpen, setDoctorModalOpen] = useState(false);
  const [activeRequest, setActiveRequest] = useState<any>(null);
  const [searching, setSearching] = useState(false);
  const [noResponders, setNoResponders] = useState(false);
  const [searchPhase, setSearchPhase] = useState<'ambulance' | 'vehicle'>('ambulance');
  const [searchRadius, setSearchRadius] = useState<number>(5);
  const [assignedData, setAssignedData] = useState<any>(null);
  const [flowStep, setFlowStep] = useState<'idle' | 'mode_select' | 'vehicle_type_select' | 'radius_options'>('idle');
  const [sosMode, setSosMode] = useState<SOSMode>('auto_select_ambulance');
  const [vehicleTypes, setVehicleTypes] = useState<string[]>(['ambulance']);
  const [autoBook, setAutoBook] = useState(false);
  const [autoFind, setAutoFind] = useState(false);
  const [startRadius, setStartRadius] = useState(5);
  const [startingSearch, setStartingSearch] = useState(false);
  const [acceptedList, setAcceptedList] = useState<any[]>([]);
  const [bookingProvider, setBookingProvider] = useState(false);
  const [attemptNumber, setAttemptNumber] = useState<number | undefined>(undefined);
  const [pendingPayload, setPendingPayload] = useState<any>(null);
  const [windowOpen, setWindowOpen] = useState(true); // false = 30s window band, user ke paas next-step buttons

  const [incomingEmergency, setIncomingEmergency] = useState<any>(null);
  const [pendingAccept, setPendingAccept] = useState<{ requestId: string; endsAt: number } | null>(null);
  const [hospitalSelectRequestId, setHospitalSelectRequestId] = useState<string | null>(null);

  const activeRequestRef = useRef<any>(null);
  activeRequestRef.current = activeRequest;
  const incomingRef = useRef<any>(null);
  incomingRef.current = incomingEmergency;

  emergencyOverlayActive.current = !!incomingEmergency;

  // Pehle user tap par audio unlock — taaki ring bajne me browser autoplay block na kare
  useEffect(() => installEmergencyAudioUnlock(), []);

  // Sync state after room join (missed-event protection, Doc 03 §6)
  const syncRequestState = useCallback(async (requestId: string) => {
    try {
      const res: any = await api.get(`/emergency-sos/${requestId}`);
      const em = res?.emergency;
      if (!em) return;
      if (em.status === 'assigned' || em.status === 'en_route') {
        setSearching(false);
        setAssignedData(em.responder || { requestId });
      } else if (em.status === 'no_responders_found') {
        setSearching(false);
        setNoResponders(true);
      } else if (em.status === 'cancelled_by_user' || em.status === 'completed') {
        setSearching(false);
        setActiveRequest(null);
        setAssignedData(null);
      }
    } catch {}
  }, []);

  useEffect(() => {
    if (!user?.id) return; // login ke baad hi listeners lagao
    const socket = getSocket();
    if (!socket) return;

    const matches = (data: any) => {
      const cur = activeRequestRef.current;
      return cur && (cur._id === data.requestId || cur.id === data.requestId || String(cur._id) === String(data.requestId));
    };

    const onIncomingEmergency = (data: any) => {
      // Dedupe two tabs: same requestId already ringing
      if (incomingRef.current?.requestId === data.requestId) return;
      setIncomingEmergency(data);
      setPendingAccept(null);
    };

    const onSearchingUpdate = (data: any) => {
      if (matches(data)) {
        if (data.phase) setSearchPhase(data.phase);
        if (data.radiusKm) setSearchRadius(data.radiusKm);
        if (data.attemptNumber) setAttemptNumber(data.attemptNumber);
      }
    };

    const onEmergencyAssigned = (data: any) => {
      if (matches(data)) {
        setSearching(false);
        setAssignedData(data);
        toast.success('Emergency responder assigned and on the way!');
      }
    };

    const onAssignedToYou = (data: any) => {
      setPendingAccept(null);
      setIncomingEmergency(null);
      setHospitalSelectRequestId(data.requestId);
      toast.success('You have secured the emergency dispatch! En route to pickup.');
      // A-3: link overlay → dashboard — ambulance drivers land on the Active mission tab.
      if (user?.role === 'ambulance') {
        try { navigate('/ambulance/dashboard?tab=active'); } catch { /* ignore */ }
      }
    };

    const onLost = (data: any) => {
      setPendingAccept(null);
      setIncomingEmergency(null);
      toast.info(data?.message || 'Ye emergency kisi aur paas wale responder ko assign ho gayi.');
    };

    const onClosed = () => {
      setPendingAccept(null);
      setIncomingEmergency(null);
    };

    const onExpiredNoResponse = (data: any) => {
      if (incomingRef.current?.requestId === data.requestId) {
        setPendingAccept(null);
        setIncomingEmergency(null);
      }
    };

    const onNoResponders = (data: any) => {
      if (matches(data)) {
        setSearching(false);
        setNoResponders(true);
        toast.error('No emergency vehicles responded in time. Please dial 108 or 112 immediately!', { duration: 12000 });
      }
    };

    // Server ne 30s window band ki: accepted list ya "koi accept nahi" (Search Again / wider)
    const onWindowClosed = (data: any) => {
      if (!matches(data)) return;
      setWindowOpen(false);
      if (data.radiusKm) setSearchRadius(data.radiusKm);
      if (data.accepted?.length) {
        setAcceptedList(data.accepted);
        setSearching(false);
      }
    };

    const onEmergencyCancelled = (data: any) => {
      if (matches(data)) {
        setSearching(false);
        setAssignedData(null);
        setActiveRequest(null);
        setNoResponders(false);
        toast.info('Emergency request was cancelled.');
      }
      if (incomingRef.current?.requestId === data.requestId) {
        setIncomingEmergency(null);
        setPendingAccept(null);
        toast.info('The emergency request was cancelled by the requester.');
      }
    };

    const onCompleted = (data: any) => {
      if (matches(data)) {
        setAssignedData(null);
        setActiveRequest(null);
        setSearching(false);
        toast.success('Emergency completed.');
      }
    };

    const onHospitalSelected = (data: any) => {
      if (matches(data)) {
        setAssignedData((prev: any) => prev ? { ...prev, hospital: data.hospital } : prev);
      }
    };

    socket.on('incoming_emergency', onIncomingEmergency);
    socket.on('emergency_searching_update', onSearchingUpdate);
    socket.on('emergency_assigned', onEmergencyAssigned);
    socket.on('emergency_assigned_to_you', onAssignedToYou);
    socket.on('emergency_lost', onLost);
    socket.on('emergency_closed', onClosed);
    socket.on('emergency_expired_no_response', onExpiredNoResponse);
    socket.on('emergency_no_responders_found', onNoResponders);
    socket.on('emergency_window_closed', onWindowClosed);
    socket.on('emergency_cancelled', onEmergencyCancelled);
    socket.on('emergency_completed', onCompleted);
    socket.on('emergency_hospital_selected', onHospitalSelected);

    return () => {
      socket.off('incoming_emergency', onIncomingEmergency);
      socket.off('emergency_searching_update', onSearchingUpdate);
      socket.off('emergency_assigned', onEmergencyAssigned);
      socket.off('emergency_assigned_to_you', onAssignedToYou);
      socket.off('emergency_lost', onLost);
      socket.off('emergency_closed', onClosed);
      socket.off('emergency_expired_no_response', onExpiredNoResponse);
      socket.off('emergency_no_responders_found', onNoResponders);
      socket.off('emergency_window_closed', onWindowClosed);
      socket.off('emergency_cancelled', onEmergencyCancelled);
      socket.off('emergency_completed', onCompleted);
      socket.off('emergency_hospital_selected', onHospitalSelected);
    };
  }, [user?.id]);

  // Join room immediately when activeRequest set + one GET sync (Doc 01 §12 race fix)
  useEffect(() => {
    if (!activeRequest?._id) return;
    const socket = getSocket();
    if (!socket) return;
    socket.emit('join_emergency_room', { requestId: activeRequest._id });
    syncRequestState(String(activeRequest._id));
    return () => {
      socket.emit('leave_emergency_room', { requestId: activeRequest._id });
    };
  }, [activeRequest?._id, syncRequestState]);

  const handleSubmitSOS = async (payload: any) => {
    // Hold-to-confirm done → now choose mode (spec §0). Keep payload, open mode select.
    setPendingPayload(payload);
    setConfirmModalOpen(false);
    setSosMode('auto_select_ambulance');
    setVehicleTypes(['ambulance']);
    setAutoBook(true);
    setAutoFind(false);
    setStartRadius(5);
    setFlowStep('mode_select');
  };

  const startSearchWithMode = async () => {
    if (!pendingPayload) return;
    if (sosMode === 'manual_select' && vehicleTypes.length === 0) {
      toast.error('Kam se kam ek vehicle type chuno');
      return;
    }
    setStartingSearch(true);
    try {
      sosVehicleState.current = {
        requestMode: sosMode,
        selectedVehicleTypes: sosMode === 'manual_select' ? vehicleTypes : sosMode === 'auto_select_ambulance' ? ['ambulance'] : ['auto', 'e_rickshaw', 'car', 'van', 'ambulance'],
        autoBookEnabled: sosMode === 'auto_select_ambulance' ? true : autoBook,
        autoFindEnabled: autoFind,
        startingRadiusKm: startRadius,
      };
      const res: any = await api.post('/emergency-sos/start', {
        ...pendingPayload,
        requestMode: sosMode,
        selectedVehicleTypes: sosVehicleState.current.selectedVehicleTypes,
        autoBookEnabled: sosVehicleState.current.autoBookEnabled,
        autoFindEnabled: autoFind,
        startingRadiusKm: startRadius,
      });
      const requestId = res.requestId;
      if (requestId) {
        setActiveRequest({ _id: requestId, id: requestId, ...pendingPayload, requestMode: sosMode });
        setFlowStep('idle');
        setSearching(true);
        setNoResponders(false);
        setAssignedData(null);
        setAcceptedList([]);
        setWindowOpen(true);
        setAttemptNumber(undefined);
        setSearchPhase(sosMode === 'auto_select_ambulance' ? 'ambulance' : 'vehicle');
        setSearchRadius(startRadius);
        toast.success('Emergency SOS triggered! Searching nearby responders.');
        // Manual modes: poll accepted-candidates after window (~32s)
        if (sosMode === 'manual_select' || (sosMode === 'auto_select_vehicle' && !autoBook && !autoFind)) {
          setTimeout(async () => {
            try {
              const list: any = await api.get(`/emergency-sos/${requestId}/accepted-candidates`);
              if (list?.accepted?.length) {
                setAcceptedList(list.accepted);
                setSearching(false);
              }
            } catch {}
          }, 32000);
        }
      }
    } catch (err: any) {
      toast.error(userFacingError(err, { fallback: 'Failed to trigger Emergency SOS.' }));
    } finally {
      setStartingSearch(false);
    }
  };

  const handleSearchAgain = async () => {
    if (!activeRequest?._id) return;
    try {
      // Server fire-and-forget hai; result 'emergency_window_closed' socket event se aata hai
      await api.post(`/emergency-sos/${activeRequest._id}/search-again`, {});
      setAcceptedList([]);
      setWindowOpen(true);
      setSearching(true);
      toast.info('Search Again — same radius me dobara dhoondh rahe hain…');
    } catch (err: any) {
      toast.error(userFacingError(err, { fallback: 'Search failed' }));
    }
  };

  const handleSearchWider = async (km: number) => {
    if (!activeRequest?._id) return;
    try {
      setSearchRadius(km);
      await api.post(`/emergency-sos/${activeRequest._id}/search-radius/${km}`, {});
      setAcceptedList([]);
      setWindowOpen(true);
      setSearching(true);
      toast.info(`Search in ${km}km…`);
    } catch (err: any) {
      toast.error(userFacingError(err, { fallback: 'Search failed' }));
    }
  };

  const handleBookChosen = async (providerId: string) => {
    if (!activeRequest?._id) return;
    setBookingProvider(true);
    try {
      await api.post(`/emergency-sos/${activeRequest._id}/book/${providerId}`, {});
      setAcceptedList([]);
      toast.success('Booked! Responder aa raha hai.');
    } catch (err: any) {
      toast.error(userFacingError(err, { fallback: 'Booking failed — race ho gayi, dobara try karein.' }));
    } finally {
      setBookingProvider(false);
    }
  };

  const cancellingRef = useRef(false);
  const handleCancelSOS = async () => {
    if (!activeRequest?._id || cancellingRef.current) return;
    cancellingRef.current = true;
    try {
      await api.post(`/emergency-sos/${activeRequest._id}/cancel`, {
        reason: 'User cancelled emergency request',
      });
      setSearching(false);
      setActiveRequest(null);
      setNoResponders(false);
      setAcceptedList([]);
      toast.info('Emergency request cancelled.');
    } catch (err: any) {
      toast.error(userFacingError(err, { fallback: 'Failed to cancel emergency.' }));
    } finally {
      cancellingRef.current = false;
    }
  };

  const handleProviderAccept = async (requestId: string) => {
    if (!incomingEmergency) return;
    try {
      const res: any = await api.post(`/emergency-sos/${requestId}/accept`, {
        providerType: incomingEmergency.providerType,
        providerId: incomingEmergency.ambulanceId || incomingEmergency.providerId || (user as any)?.id || (user as any)?._id,
      });

      if (res.status === 'accepted_pending') {
        setPendingAccept({
          requestId,
          endsAt: res.windowEndsAt ? new Date(res.windowEndsAt).getTime() : Date.now() + 30000,
        });
        // overlay stays open in "confirmation ka wait" state — do NOT clear incomingEmergency
      } else if (res.status === 'too_late') {
        toast.warning(res.message || 'Another responder already accepted this request.');
        setIncomingEmergency(null);
      } else if (!res.success) {
        toast.error(res.message || 'Could not accept emergency request.');
      }
    } catch (err: any) {
      const msg = userFacingError(err, { fallback: '' });
      const status = err.response?.data?.status;
      if (status === 'too_late') {
        toast.warning(msg);
        setIncomingEmergency(null);
      } else {
        toast.error(msg || 'Failed to accept emergency.');
      }
    }
  };

  const handleProviderReject = async (requestId: string) => {
    setIncomingEmergency(null);
    setPendingAccept(null);
    try {
      await api.post(`/emergency-sos/${requestId}/reject`, {
        providerId: incomingEmergency?.ambulanceId || incomingEmergency?.providerId || (user as any)?.id || (user as any)?._id,
      }).catch(() => {});
    } catch {}
  };

  return (
    <>
      {user && !searching && !assignedData && (
        <DualEmergencyFAB
          onOpenAmbulance={() => setConfirmModalOpen(true)}
          onOpenDoctor={() => setDoctorModalOpen(true)}
        />
      )}

      <EmergencyDoctorModal
        isOpen={doctorModalOpen}
        onClose={() => setDoctorModalOpen(false)}
        currentUser={user}
      />

      <SOSConfirmModal
        open={confirmModalOpen}
        onOpenChange={setConfirmModalOpen}
        onSubmitSOS={handleSubmitSOS}
        currentUser={user}
      />

      {flowStep === 'mode_select' && (
        <SOSModeSelect
          selected={sosMode}
          onSelect={(m) => {
            setSosMode(m);
            if (m === 'auto_select_ambulance') { setVehicleTypes(['ambulance']); setAutoBook(true); }
            if (m === 'manual_select' && vehicleTypes.length === 0) setVehicleTypes(['auto']);
          }}
          onContinue={() => setFlowStep(sosMode === 'manual_select' ? 'vehicle_type_select' : 'radius_options')}
        />
      )}

      {flowStep === 'vehicle_type_select' && (
        <SOSVehicleTypeSelect
          selected={vehicleTypes}
          onToggle={(id) => setVehicleTypes((p) => (p.includes(id) ? p.filter((x) => x !== id) : [...p, id]))}
          onContinue={() => setFlowStep('radius_options')}
          onBack={() => setFlowStep('mode_select')}
        />
      )}

      {flowStep === 'radius_options' && (
        <SOSRadiusOptions
          mode={sosMode}
          radiusKm={startRadius}
          onRadius={setStartRadius}
          autoBook={sosMode === 'auto_select_ambulance' ? true : autoBook}
          onAutoBook={setAutoBook}
          autoFind={autoFind}
          onAutoFind={setAutoFind}
          onStart={startSearchWithMode}
          onBack={() => setFlowStep(sosMode === 'manual_select' ? 'vehicle_type_select' : 'mode_select')}
          starting={startingSearch}
        />
      )}

      {searching && (
        <SOSSearchingScreen
          radiusKm={searchRadius}
          phase={searchPhase}
          onCancel={handleCancelSOS}
          requestDetails={activeRequest}
          attemptNumber={attemptNumber}
          autoFind={autoFind}
          windowActive={windowOpen}
          onSearchAgain={handleSearchAgain}
          onSearchWider={handleSearchWider}
        />
      )}

      {!!acceptedList.length && (
        <SOSAcceptedList
          candidates={acceptedList}
          onBook={handleBookChosen}
          onSearchAgain={handleSearchAgain}
          onSearchWider={handleSearchWider}
          currentRadius={searchRadius}
          booking={bookingProvider}
        />
      )}

      {(!searching && noResponders) && (
        <SOSSearchingScreen
          radiusKm={searchRadius}
          phase={searchPhase}
          onCancel={() => { setNoResponders(false); setActiveRequest(null); }}
          requestDetails={activeRequest}
          noResponders
        />
      )}

      {assignedData && (
        <SOSAssignedScreen
          emergency={{ responder: assignedData }}
          onDismiss={() => setAssignedData(null)}
        />
      )}

      {incomingEmergency && (
        <ProviderIncomingCall
          data={incomingEmergency}
          acceptedWaiting={!!pendingAccept}
          onAccept={handleProviderAccept}
          onReject={handleProviderReject}
          onTimeout={handleProviderReject}
        />
      )}

      {hospitalSelectRequestId && (
        <ProviderHospitalSelect
          requestId={hospitalSelectRequestId}
          onHospitalSelected={(hospital) => {
            setHospitalSelectRequestId(null);
            toast.success(`Destination confirmed: ${hospital.name}`);
          }}
          onDismiss={() => setHospitalSelectRequestId(null)}
        />
      )}
    </>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Room, RoomEvent, Track } from 'livekit-client';
import { motion } from 'framer-motion';
import { PhoneOff, Mic, MicOff, Video, VideoOff, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { api } from '@/lib/api';
import { toast } from 'sonner';

interface EmergencyVideoRoomProps {
  room: string;
  identity?: string;
  onClose: () => void;
}

export default function EmergencyVideoRoom({ room, identity, onClose }: EmergencyVideoRoomProps) {
  const localVideoRef = useRef<HTMLVideoElement>(null);
  const remoteVideoRef = useRef<HTMLVideoElement>(null);
  const roomRef = useRef<Room | null>(null);
  const [status, setStatus] = useState<'connecting' | 'live' | 'unavailable' | 'error'>('connecting');
  const [muted, setMuted] = useState(false);
  const [videoOff, setVideoOff] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let roomObj: Room | null = null;

    (async () => {
      try {
        const res = await api.post('/video/token', { room, identity });
        const livekitUrl: string | undefined =
          res?.url || (import.meta as any).env?.VITE_LIVEKIT_URL || undefined;
        if (!res?.token || !livekitUrl) {
          if (!cancelled) setStatus('unavailable');
          return;
        }
        roomObj = new Room({ adaptiveStream: true, dynacast: true });
        roomRef.current = roomObj;
        roomObj.on(RoomEvent.TrackSubscribed, (track) => {
          if (track.kind === Track.Kind.Video && remoteVideoRef.current) {
            track.attach(remoteVideoRef.current);
          }
        });
        roomObj.on(RoomEvent.TrackUnsubscribed, (track) => track.detach());
        await roomObj.connect(livekitUrl, res.token);
        await roomObj.localParticipant.enableCameraAndMicrophone();
        const videoPub = roomObj.localParticipant.getTrackPublication(Track.Source.Camera);
        const videoTrack = videoPub?.videoTrack;
        if (videoTrack && localVideoRef.current) videoTrack.attach(localVideoRef.current);
        if (!cancelled) setStatus('live');
      } catch (err: any) {
        if (!cancelled) {
          setStatus('error');
          toast.error(err?.message || 'Video room failed — use call fallback');
        }
      }
    })();

    return () => {
      cancelled = true;
      try {
        roomObj?.disconnect();
      } catch { /* noop */ }
      roomRef.current = null;
    };
  }, [room, identity]);

  const toggleMute = async () => {
    try {
      await roomRef.current?.localParticipant.setMicrophoneEnabled(muted);
      setMuted(!muted);
    } catch { /* noop */ }
  };

  const toggleVideo = async () => {
    try {
      await roomRef.current?.localParticipant.setCameraEnabled(videoOff);
      setVideoOff(!videoOff);
    } catch { /* noop */ }
  };

  const leave = () => {
    try {
      roomRef.current?.disconnect();
    } catch { /* noop */ }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950/95 backdrop-blur-xl flex flex-col items-center justify-center p-4 text-white select-none">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-2xl rounded-3xl border border-white/10 bg-slate-900 p-4 sm:p-5 space-y-3"
      >
        <div className="flex items-center justify-between">
          <h3 className="font-black text-sm sm:text-base">🎥 Emergency Video Triage</h3>
          <span className="text-[11px] font-mono text-slate-400">Room #{room.slice(-6)}</span>
        </div>

        {status === 'connecting' && (
          <div className="aspect-video rounded-2xl bg-black/60 flex flex-col items-center justify-center gap-2">
            <Loader2 className="w-8 h-8 animate-spin text-teal-400" />
            <p className="text-xs text-slate-400">Connecting secure video…</p>
          </div>
        )}

        {status === 'unavailable' && (
          <div className="rounded-2xl border border-amber-500/40 bg-amber-500/10 p-4 text-xs text-amber-200">
            Video media is not configured on this server right now. Please use the Call button (audio fallback) — your consultation continues without interruption.
          </div>
        )}

        {status === 'error' && (
          <div className="rounded-2xl border border-red-500/40 bg-red-500/10 p-4 text-xs text-red-200">
            Could not join video. Check connection and retry, or fall back to the phone call option.
          </div>
        )}

        {(status === 'live' || status === 'connecting') && (
          <div className="grid grid-cols-2 gap-2.5">
            <div className="relative aspect-video rounded-2xl overflow-hidden bg-black/70 border border-white/10">
              <video ref={remoteVideoRef} autoPlay playsInline className="w-full h-full object-cover" />
              <span className="absolute bottom-1.5 left-2 text-[10px] font-bold bg-black/60 px-2 py-0.5 rounded-full">Doctor</span>
            </div>
            <div className="relative aspect-video rounded-2xl overflow-hidden bg-black/70 border border-white/10">
              <video ref={localVideoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
              <span className="absolute bottom-1.5 left-2 text-[10px] font-bold bg-black/60 px-2 py-0.5 rounded-full">You</span>
            </div>
          </div>
        )}

        <div className="flex items-center justify-center gap-2.5 pt-1">
          <Button type="button" size="icon" variant="outline" onClick={toggleMute} className="rounded-full w-11 h-11" aria-label={muted ? 'Unmute' : 'Mute'}>
            {muted ? <MicOff className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
          </Button>
          <Button type="button" size="icon" variant="outline" onClick={toggleVideo} className="rounded-full w-11 h-11" aria-label={videoOff ? 'Camera on' : 'Camera off'}>
            {videoOff ? <VideoOff className="w-4 h-4" /> : <Video className="w-4 h-4" />}
          </Button>
          <Button type="button" onClick={leave} className="rounded-full h-11 px-6 bg-red-600 hover:bg-red-700 font-bold text-xs gap-1.5">
            <PhoneOff className="w-4 h-4" /> End
          </Button>
        </div>
      </motion.div>
    </div>
  );
}

import React, { useRef, useState, useEffect } from 'react';
import { AlertOctagon } from 'lucide-react';

interface HoldToConfirmButtonProps {
  onConfirm: () => void;
  holdMs?: number;
  label?: string;
  className?: string;
}

export default function HoldToConfirmButton({
  onConfirm,
  holdMs = 1000,
  label = 'Hold to Confirm Emergency',
  className = '',
}: HoldToConfirmButtonProps) {
  const [progress, setProgress] = useState(0);
  const [isHolding, setIsHolding] = useState(false);
  const timerRef = useRef<any>(null);
  const startRef = useRef<number>(0);

  const startHold = () => {
    setIsHolding(true);
    startRef.current = Date.now();
    timerRef.current = setInterval(() => {
      const elapsed = Date.now() - startRef.current;
      const currentProgress = Math.min(100, (elapsed / holdMs) * 100);
      setProgress(currentProgress);
      if (elapsed >= holdMs) {
        clearInterval(timerRef.current);
        setIsHolding(false);
        setProgress(0);
        onConfirm();
      }
    }, 25);
  };

  const cancelHold = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setIsHolding(false);
    setProgress(0);
  };

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  return (
    <button
      type="button"
      onMouseDown={startHold}
      onMouseUp={cancelHold}
      onMouseLeave={cancelHold}
      onTouchStart={startHold}
      onTouchEnd={cancelHold}
      className={`relative overflow-hidden w-full py-3.5 px-6 rounded-2xl bg-red-600 hover:bg-red-700 active:scale-[0.99] text-white font-bold text-sm sm:text-base shadow-lg shadow-red-600/30 transition-all select-none flex items-center justify-center gap-2 cursor-pointer ${className}`}
    >
      {/* Background Fill Animation */}
      <span
        className="absolute left-0 top-0 bottom-0 bg-red-800 pointer-events-none transition-[width] duration-30 ease-linear"
        style={{ width: `${progress}%` }}
      />

      {/* Button Content */}
      <span className="relative z-10 flex items-center gap-2">
        <AlertOctagon className={`w-5 h-5 ${isHolding ? 'animate-spin' : ''}`} />
        <span>{isHolding ? `Keep holding... (${Math.round(progress)}%)` : label}</span>
      </span>
    </button>
  );
}

