import React, { useState, useEffect } from 'react';
import { Star, MessageSquare, ThumbsUp, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { toast } from 'sonner';
import { api } from '@/lib/api';

export interface FeedbackPromptProps {
  context: 'visit' | 'pharmacy' | 'lab' | 'admission' | 'teleconsult' | 'other';
  refModel?: 'Appointment' | 'Admission' | 'PharmacyOrder' | 'LabOrder' | 'Teleconsult' | 'Other';
  refId?: string;
  department?: string;
  title?: string;
  description?: string;
  onDone?: (submitted: boolean) => void;
  onSkip?: () => void;
  inline?: boolean;
}

export default function FeedbackPrompt({
  context,
  refModel,
  refId,
  department = '',
  title = 'How likely are you to recommend us?',
  description = 'Your feedback directly helps our clinical and support teams improve care.',
  onDone,
  onSkip,
  inline = false,
}: FeedbackPromptProps) {
  const [npsScore, setNpsScore] = useState<number | null>(null);
  const [rating, setRating] = useState<number>(0);
  const [comment, setComment] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const [checking, setChecking] = useState(Boolean(refId));

  // Check if user already submitted feedback for this reference
  useEffect(() => {
    if (!refId) {
      setChecking(false);
      return;
    }
    let isMounted = true;
    (async () => {
      try {
        const res: any = await api.get(`/feedback/mine?refId=${encodeURIComponent(refId)}`);
        if (isMounted && res?.hasSubmitted) {
          setHasSubmitted(true);
        }
      } catch {
        // fail-soft: allow submission attempt
      } finally {
        if (isMounted) setChecking(false);
      }
    })();
    return () => { isMounted = false; };
  }, [refId]);

  if (checking) {
    return null;
  }

  if (hasSubmitted) {
    return (
      <div className="flex items-center gap-2 p-3 text-xs text-muted-foreground bg-muted/40 rounded-lg border border-border/50">
        <ThumbsUp className="w-4 h-4 text-primary" />
        <span>You have already submitted feedback for this visit. Thank you!</span>
      </div>
    );
  }

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (npsScore === null && rating === 0) {
      toast.error('Please select an NPS score (0-10) or star rating (1-5)');
      return;
    }

    setSubmitting(true);
    try {
      const payload: Record<string, any> = {
        context,
        department: department || undefined,
        comment: comment.trim() || undefined,
        refModel: refModel || undefined,
        refId: refId || undefined,
      };
      if (npsScore !== null) payload.npsScore = npsScore;
      if (rating > 0) payload.rating = rating;

      await api.post('/feedback', payload);
      toast.success('Thank you for sharing your experience!');
      setHasSubmitted(true);
      onDone?.(true);
    } catch (err: any) {
      if (err?.response?.status === 409 || err?.code === 'FEEDBACK_DUPLICATE') {
        toast.info('Feedback for this visit was already recorded.');
        setHasSubmitted(true);
        onDone?.(true);
      } else {
        toast.error(err?.response?.data?.message || err?.message || 'Failed to submit feedback');
      }
    } finally {
      setSubmitting(false);
    }
  };

  const getNpsStyle = (score: number) => {
    const isSelected = npsScore === score;
    if (score <= 6) {
      return isSelected
        ? 'bg-red-500 text-white border-red-600 shadow-sm'
        : 'bg-red-500/10 text-red-700 hover:bg-red-500/20 border-red-300 dark:border-red-900/50';
    }
    if (score <= 8) {
      return isSelected
        ? 'bg-amber-500 text-white border-amber-600 shadow-sm'
        : 'bg-amber-500/10 text-amber-700 hover:bg-amber-500/20 border-amber-300 dark:border-amber-900/50';
    }
    return isSelected
      ? 'bg-emerald-500 text-white border-emerald-600 shadow-sm'
      : 'bg-emerald-500/10 text-emerald-700 hover:bg-emerald-500/20 border-emerald-300 dark:border-emerald-900/50';
  };

  const containerClasses = inline
    ? 'p-4 rounded-xl border border-border bg-card'
    : 'w-full max-w-xl mx-auto shadow-sm';

  return (
    <Card className={containerClasses} role="region" aria-label="Patient Feedback Prompt">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-2">
          <div>
            <CardTitle className="text-base font-semibold flex items-center gap-2">
              <MessageSquare className="w-4 h-4 text-primary" />
              {title}
            </CardTitle>
            <CardDescription className="text-xs text-muted-foreground mt-0.5">
              {description}
            </CardDescription>
          </div>
          {onSkip && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="h-7 w-7 p-0 text-muted-foreground hover:text-foreground"
              onClick={onSkip}
              aria-label="Skip feedback"
            >
              <X className="w-4 h-4" />
            </Button>
          )}
        </div>
      </CardHeader>

      <CardContent className="space-y-4 pt-1">
        {/* NPS 0-10 Button Scale */}
        <div>
          <div className="flex justify-between items-center text-[11px] text-muted-foreground mb-1.5 px-0.5 font-medium">
            <span>0 = Not likely at all</span>
            <span>10 = Extremely likely</span>
          </div>
          <div
            className="grid grid-cols-11 gap-1"
            role="radiogroup"
            aria-label="Net Promoter Score scale 0 to 10"
          >
            {Array.from({ length: 11 }, (_, i) => (
              <button
                key={i}
                type="button"
                role="radio"
                aria-checked={npsScore === i}
                aria-label={`Score ${i} out of 10`}
                className={`h-9 text-xs font-semibold rounded-md border transition-all flex items-center justify-center ${getNpsStyle(i)}`}
                onClick={() => setNpsScore(i)}
              >
                {i}
              </button>
            ))}
          </div>
        </div>

        {/* 1-5 Star Quick Rating */}
        <div className="flex items-center gap-3 pt-1">
          <span className="text-xs text-muted-foreground">Overall rating:</span>
          <div className="flex items-center gap-1" role="radiogroup" aria-label="1 to 5 star rating">
            {[1, 2, 3, 4, 5].map((star) => (
              <button
                key={star}
                type="button"
                role="radio"
                aria-checked={rating === star}
                aria-label={`${star} star${star > 1 ? 's' : ''}`}
                className="p-1 rounded hover:bg-muted/60 transition-colors focus:outline-none focus:ring-1 focus:ring-primary"
                onClick={() => setRating(star)}
              >
                <Star
                  className={`w-5 h-5 ${
                    star <= rating
                      ? 'fill-amber-400 text-amber-400'
                      : 'text-muted-foreground/40 hover:text-amber-400/60'
                  }`}
                />
              </button>
            ))}
          </div>
        </div>

        {/* Comment Textarea */}
        <div>
          <Textarea
            value={comment}
            onChange={(e) => setComment(e.target.value.slice(0, 2000))}
            placeholder="Tell us what went well, or what we can do better (optional)..."
            className="text-xs resize-none h-18"
            maxLength={2000}
            aria-label="Additional comments"
          />
          <div className="flex justify-end text-[10px] text-muted-foreground mt-1">
            {comment.length} / 2000
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-2 pt-1 border-t border-border/40">
          {onSkip && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onSkip}
              disabled={submitting}
              className="text-xs"
            >
              Skip for now
            </Button>
          )}
          <Button
            type="button"
            size="sm"
            onClick={() => handleSubmit()}
            disabled={submitting || (npsScore === null && rating === 0)}
            className="text-xs"
          >
            {submitting ? 'Submitting...' : 'Submit Feedback'}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';

/**
 * File 14 §14.1 — form renderer: template JSON → inputs. showIf/requiredIf
 * evaluated by a tiny local JSON-logic subset (==, !=, >, <, >=, <=, in,
 * and, or, not, var) — no eval, mirrors server json-logic-js for the
 * operators used in builders. Dense, keyboard-first, no decorative motion.
 */

const getVar = (values: any, path: string) => {
  if (path === '') return values;
  return String(path).split('.').reduce((o: any, k) => (o == null ? undefined : o[k]), values);
};

export function evalRule(rule: any, values: any): boolean {
  if (rule === null || rule === undefined) return true;
  if (typeof rule === 'boolean') return rule;
  if (typeof rule !== 'object') return Boolean(rule);
  const ops: Record<string, (a: any) => boolean> = {
    '==': ([a, b]) => a === b,
    '===': ([a, b]) => a === b,
    '!=': ([a, b]) => a !== b,
    '!==': ([a, b]) => a !== b,
    '>': ([a, b]) => a > b,
    '<': ([a, b]) => a < b,
    '>=': ([a, b]) => a >= b,
    '<=': ([a, b]) => a <= b,
    '!': ([a]) => !a,
    '!!': ([a]) => !!a,
    or: (args) => args.some(Boolean),
    and: (args) => args.every(Boolean),
    in: ([a, b]) => Array.isArray(b) ? b.includes(a) : String(b).includes(String(a)),
  };
  const keys = Object.keys(rule);
  if (keys.length === 1 && keys[0] === 'var') {
    const v = rule.var;
    return getVar(values, Array.isArray(v) ? String(v[0]) : String(v));
  }
  if (keys.length === 1 && ops[keys[0]]) {
    const raw = (rule as any)[keys[0]];
    const args = (Array.isArray(raw) ? raw : [raw]).map((x) => resolveVal(x, values));
    return ops[keys[0]](args);
  }
  return false;
}

const resolveVal = (x: any, values: any) => {
  if (x && typeof x === 'object' && Object.keys(x).length === 1 && 'var' in x) {
    const v = (x as any).var;
    return getVar(values, Array.isArray(v) ? String(v[0]) : String(v));
  }
  if (x && typeof x === 'object') return evalRule(x, values);
  return x;
};

export interface FormField {
  id: string;
  type: string;
  label?: string;
  /** Hindi (Devanagari) label — optional; rendered as secondary text when present or primary when locale === 'hi'. */
  labelHi?: string;
  placeholder?: string;
  placeholderHi?: string;
  help?: string;
  helpHi?: string;
  required?: boolean;
  options?: string[];
  optionsHi?: string[];
  showIf?: any;
  requiredIf?: any;
}

export default function FormRenderer({
  template, values, onChange, onSubmit, submitLabel, locale = 'en',
}: {
  template: any;
  values: Record<string, any>;
  onChange: (values: Record<string, any>) => void;
  onSubmit: () => void;
  submitLabel?: string;
  locale?: 'en' | 'hi' | string;
}) {
  const set = (id: string, v: any) => onChange({ ...values, [id]: v });
  const isHi = locale === 'hi';
  const sections = template?.definition?.sections || [];
  // Hindi label: show Devanagari under the primary label when the template
  // provides one (checklist item 12 — Hindi labels). When locale === 'hi',
  // prioritize Hindi with English fallback.
  const labelWithHi = (f: FormField, required: boolean) => {
    if (isHi) {
      const primary = f.labelHi || f.label;
      return (
        <span className="font-medium" lang="hi">
          {primary}{required ? ' *' : ''}
          {f.labelHi && f.label && f.labelHi !== f.label && (
            <span lang="en" className="block text-xs font-normal text-muted-foreground">{f.label}</span>
          )}
        </span>
      );
    }
    return (
      <span className="font-medium">
        {f.label}{required ? ' *' : ''}
        {f.labelHi && <span lang="hi" className="block text-xs font-normal text-muted-foreground">{f.labelHi}</span>}
      </span>
    );
  };

  const getPlaceholder = (f: FormField) => (isHi ? (f.placeholderHi || f.placeholder) : f.placeholder);
  const getOptions = (f: FormField) => (isHi && f.optionsHi?.length ? f.optionsHi : (f.options || []));
  const getHelp = (f: FormField) => (isHi ? (f.helpHi || f.help) : f.help);

  return (
    <div className="space-y-5">
      {sections.map((sec: any) => (
        <div key={sec.id} className="space-y-3">
          {(isHi ? (sec.titleHi || sec.title) : sec.title) && (
            <h3 className="font-bold text-sm" lang={isHi && sec.titleHi ? 'hi' : undefined}>
              {isHi ? (sec.titleHi || sec.title) : sec.title}
            </h3>
          )}
          {(sec.fields || []).map((f: FormField) => {
            if (!evalRule(f.showIf ?? null, values)) return null;
            const required = f.required || evalRule(f.requiredIf ?? null, values);
            const common = 'w-full';
            const placeholder = getPlaceholder(f);
            const options = getOptions(f);
            const help = getHelp(f);

            switch (f.type) {
              case 'textarea':
                return (
                  <label key={f.id} className="block text-sm">
                    {labelWithHi(f, required)}
                    <textarea
                      className={`${common} mt-1 rounded-md border border-input bg-background p-2 min-h-20`}
                      placeholder={placeholder}
                      value={values[f.id] ?? ''}
                      onChange={(e) => set(f.id, e.target.value)}
                    />
                    {help && <p className="text-xs text-muted-foreground mt-1">{help}</p>}
                  </label>
                );
              case 'number':
              case 'scale':
                return (
                  <label key={f.id} className="block text-sm">
                    {labelWithHi(f, required)}
                    <Input
                      className="mt-1"
                      type="number"
                      inputMode="numeric"
                      placeholder={placeholder}
                      value={values[f.id] ?? ''}
                      onChange={(e) => set(f.id, e.target.value === '' ? '' : Number(e.target.value))}
                    />
                    {help && <p className="text-xs text-muted-foreground mt-1">{help}</p>}
                  </label>
                );
              case 'select':
              case 'radio':
                return (
                  <label key={f.id} className="block text-sm">
                    {labelWithHi(f, required)}
                    <select
                      className="mt-1 h-10 w-full rounded-md border border-input bg-background px-3"
                      value={values[f.id] ?? ''}
                      onChange={(e) => set(f.id, e.target.value)}
                    >
                      <option value="">{isHi ? 'चयन करें' : 'Select'}</option>
                      {options.map((o: string) => <option key={o} value={o}>{o}</option>)}
                    </select>
                    {help && <p className="text-xs text-muted-foreground mt-1">{help}</p>}
                  </label>
                );
              case 'checkbox':
              case 'multiselect': {
                const cur: string[] = Array.isArray(values[f.id]) ? values[f.id] : [];
                return (
                  <fieldset key={f.id} className="text-sm">
                    <legend className="font-medium">{labelWithHi(f, required)}</legend>
                    {(f.options || []).map((o) => (
                      <label key={o} className="flex items-center gap-2 py-1">
                        <input type="checkbox" checked={cur.includes(o)} onChange={() => set(f.id, cur.includes(o) ? cur.filter((x) => x !== o) : [...cur, o])} />
                        {o}
                      </label>
                    ))}
                  </fieldset>
                );
              }
              case 'yesno':
                return (
                  <div key={f.id} className="flex items-center gap-2 text-sm">
                    {labelWithHi(f, required)}
                    {['yes', 'no', 'na'].map((o) => (
                      <Button key={o} size="sm" variant={values[f.id] === o ? 'default' : 'outline'} onClick={() => set(f.id, o)}>{o}</Button>
                    ))}
                  </div>
                );
              case 'section':
              case 'info':
                return <p key={f.id} className="text-sm text-muted-foreground">{f.label}</p>;
              case 'signature':
                return (
                  <label key={f.id} className="block text-sm">
                    {labelWithHi(f, required)}
                    <Input className="mt-1 font-mono" placeholder="Type full name to sign" value={values[f.id] ?? ''} onChange={(e) => set(f.id, e.target.value)} />
                  </label>
                );
              case 'calculated':
              case 'score':
                return (
                  <p key={f.id} className="text-sm"><span className="font-medium">{f.label}: </span><b>{values[f.id] ?? '—'}</b></p>
                );
              case 'text':
              case 'date':
              case 'time':
              default:
                return (
                  <label key={f.id} className="block text-sm">
                    {labelWithHi(f, required)}
                    <Input
                      className="mt-1"
                      type={f.type === 'text' ? 'text' : f.type}
                      placeholder={placeholder}
                      value={values[f.id] ?? ''}
                      onChange={(e) => set(f.id, e.target.value)}
                    />
                    {help && <p className="text-xs text-muted-foreground mt-1">{help}</p>}
                  </label>
                );
            }
          })}
        </div>
      ))}
      <Button onClick={onSubmit}>{submitLabel || 'Submit'}</Button>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { toast } from 'sonner';
import { HeartPulse, X, ArrowLeft, ExternalLink, ShieldCheck, ArrowRight } from 'lucide-react';
import { api } from '@/lib/api';
import { HEALTHCARE_CATALOGUE, type CatalogueItem } from '@/data/healthcareCatalogue';

export interface HealthcareCatalogueModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function HealthcareCatalogueModal({ isOpen, onClose }: HealthcareCatalogueModalProps) {
  const navigate = useNavigate();
  const [hospitalsCount, setHospitalsCount] = useState<number>(0);
  const [doctorsCount, setDoctorsCount] = useState<number>(0);
  const [activeItem, setActiveItem] = useState<CatalogueItem | null>(null);

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (activeItem) {
          setActiveItem(null);
        } else {
          onClose();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose, activeItem]);

  useEffect(() => {
    if (!isOpen) return;
    api.getHospitals({ status: 'approved' })
      .then((data: any) => {
        const list = Array.isArray(data) ? data : (data?.data || data?.hospitals || []);
        if (Array.isArray(list)) setHospitalsCount(list.length);
      })
      .catch(() => {});

    api.getDoctors({ doctor_type: 'clinic' })
      .then((data: any) => {
        const docList = Array.isArray(data) ? data : (data?.doctors || data?.data || []);
        if (Array.isArray(docList)) setDoctorsCount(docList.length);
      })
      .catch(() => {});
  }, [isOpen]);

  if (!isOpen) return null;

  const handleNavigate = (route?: string, label?: string) => {
    onClose();
    if (!route) {
      toast.info(`${label || 'Ye section'} abhi launch ho raha hai`);
      return;
    }
    if (route.startsWith('tel:') || route.startsWith('http')) {
      window.location.href = route;
      return;
    }
    navigate(route);
  };

  const handleCardClick = (item: CatalogueItem) => {
    if (item.subs && item.subs.length > 0) {
      setActiveItem(item);
    } else {
      handleNavigate(item.route, item.name);
    }
  };

  const modalContent = (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="healthcare-modal-title"
      className="fixed inset-0 z-[99999] bg-background flex flex-col w-screen h-screen overflow-hidden"
    >
      {/* Top Bar */}
      <div className="shrink-0 bg-background border-b border-border/80 px-4 sm:px-8 py-3.5 flex items-center justify-between">
        <div className="flex items-center gap-3">
          {activeItem ? (
            <button
              type="button"
              onClick={() => setActiveItem(null)}
              className="p-2 rounded-xl border border-border/80 hover:bg-muted text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
              aria-label="Back to all categories"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
          ) : (
            <div className="w-10 h-10 rounded-xl bg-teal-500/10 border border-teal-500/20 flex items-center justify-center text-teal-600">
              <HeartPulse className="w-5 h-5" />
            </div>
          )}
          <div>
            <h2 id="healthcare-modal-title" className="font-heading text-lg sm:text-xl font-bold text-foreground">
              {activeItem ? activeItem.name : 'Healthcare Categories'}
            </h2>
            <p className="text-xs text-muted-foreground">
              {activeItem
                ? `Available subcategories and services (${activeItem.subs.length})`
                : 'Aapko kis suvidha ki zarurat hai? Kisi bhi category par click karein:'}
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={() => {
            setActiveItem(null);
            onClose();
          }}
          className="p-2 rounded-xl border border-border/80 hover:bg-muted text-muted-foreground hover:text-foreground cursor-pointer transition-colors"
          aria-label="Close"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Main Body */}
      <div className="flex-1 overflow-y-auto px-4 sm:px-8 py-6 max-w-7xl mx-auto w-full">
        <AnimatePresence mode="wait">
          {activeItem ? (
            /* Subcategories Drill-Down View */
            <motion.div
              key="subcategories-view"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-6"
            >
              {/* Category Info Header Banner */}
              <div className="p-4 sm:p-5 rounded-2xl border border-border/70 bg-muted/20 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="flex items-center gap-3.5">
                  <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${activeItem.color} flex items-center justify-center shrink-0 shadow-xs`}>
                    {React.createElement(activeItem.icon, { className: `w-6 h-6 ${activeItem.textColor}` })}
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="font-heading text-lg font-bold text-foreground">
                        {activeItem.name}
                      </h3>
                      {activeItem.tier && (
                        <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-primary/10 text-primary border border-primary/20">
                          Tier {activeItem.tier}
                        </span>
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {activeItem.summary}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-2 shrink-0">
                  {activeItem.regulatedBy && (
                    <span className="flex items-center gap-1 text-xs text-teal-600 font-semibold px-2.5 py-1 rounded-lg bg-teal-500/10 border border-teal-500/20">
                      <ShieldCheck className="w-4 h-4" />
                      Regulated: {activeItem.regulatedBy}
                    </span>
                  )}
                  {activeItem.route && (
                    <button
                      type="button"
                      onClick={() => handleNavigate(activeItem.route, activeItem.name)}
                      className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-primary text-primary-foreground text-xs font-semibold hover:opacity-90 transition-opacity cursor-pointer shadow-xs"
                    >
                      <span>Explore All</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
              </div>

              {/* Subcategories Grid */}
              <div className="space-y-3">
                <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Select a Subcategory ({activeItem.subs.length})
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {activeItem.subs.map((sub, idx) => (
                    <button
                      key={sub.label}
                      type="button"
                      onClick={() => handleNavigate(sub.route ?? activeItem.route, sub.label)}
                      className="flex items-center justify-between p-3.5 rounded-xl border border-border/70 bg-card hover:bg-primary/5 hover:border-primary/50 text-left transition-all group cursor-pointer"
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <span className="w-7 h-7 rounded-lg bg-muted flex items-center justify-center text-xs font-bold text-muted-foreground group-hover:bg-primary group-hover:text-primary-foreground transition-colors shrink-0">
                          {idx + 1}
                        </span>
                        <span className="text-xs font-semibold text-foreground truncate group-hover:text-primary transition-colors">
                          {sub.label}
                        </span>
                      </div>
                      <ExternalLink className="w-4 h-4 text-muted-foreground group-hover:text-primary shrink-0 ml-2 transition-transform group-hover:translate-x-0.5" />
                    </button>
                  ))}
                </div>
              </div>
            </motion.div>
          ) : (
            /* All Categories Sections Grid */
            <motion.div
              key="all-categories-view"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="space-y-10"
            >
              {HEALTHCARE_CATALOGUE.map((section) => {
                const SectionIcon = section.icon;
                return (
                  <div key={section.title} className="space-y-3.5">
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between pb-1 border-b border-border/50">
                      <h3 className="font-heading text-base sm:text-lg font-bold text-foreground flex items-center gap-2">
                        <SectionIcon className="w-4 h-4 text-primary" />
                        <span>{section.title}</span>
                      </h3>
                      <p className="text-xs text-muted-foreground mt-0.5 sm:mt-0">
                        {section.subtitle}
                      </p>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2.5">
                      {section.items.map((item) => {
                        const ItemIcon = item.icon;
                        return (
                          <motion.button
                            key={item.id}
                            whileHover={{ scale: 1.04, y: -2 }}
                            whileTap={{ scale: 0.96 }}
                            onClick={() => handleCardClick(item)}
                            className="rounded-xl p-2.5 sm:p-3 border border-border/70 bg-card hover:bg-card/90 hover:border-primary/50 hover:shadow-sm transition-all text-center flex flex-col items-center justify-center min-h-[92px] sm:min-h-[100px] cursor-pointer group"
                          >
                            <div className={`w-9 h-9 sm:w-10 sm:h-10 rounded-lg bg-gradient-to-br ${item.color} flex items-center justify-center mb-1.5 mx-auto transition-transform group-hover:scale-110 shadow-xs`}>
                              <ItemIcon className={`w-4 h-4 sm:w-5 sm:h-5 ${item.textColor}`} />
                            </div>
                            <h4 className="font-medium text-[11px] sm:text-xs text-foreground leading-tight line-clamp-2 group-hover:text-primary transition-colors text-center px-0.5">
                              {item.name}
                            </h4>
                          </motion.button>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );

  return typeof document !== 'undefined' ? createPortal(modalContent, document.body) : null;
}

