    const socket = getSocket();
    if (!socket || !booking._id) return;

    const handleStatusUpdate = (data: any) => {
      if (data.bookingId === booking._id) {
        onRefresh();
      }
    };

    const handleCaseNote = (data: any) => {
      if (data.bookingId === booking._id) {
        onRefresh();
      }
    };

    socket.on('booking_status_update', handleStatusUpdate);
    socket.on('case_note_update', handleCaseNote);

    return () => {
      socket.off('booking_status_update', handleStatusUpdate);
      socket.off('case_note_update', handleCaseNote);
    };
  }, [booking._id]);

  const handleCancelBooking = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const reason = cancelReason.trim() || 'Cancelled by advocate';
    try {
      setActionLoading(true);
      await api.cancelLawyerBooking(booking._id, reason);
      toast.success('Consultation cancelled');
      setShowCancelModal(false);
      setCancelReason('');
      onRefresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to cancel');
    } finally {
      setActionLoading(false);
    }
  };

  const handleStartConsultation = async () => {
    try {
      setActionLoading(true);
      await api.startLawyerConsultation(booking._id);
      onRefresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to start consultation');
    } finally {
      setActionLoading(false);
    }
  };

  const handleAddCaseNote = async (note: string) => {
    await api.addLawyerCaseNote(booking._id, note);
    onRefresh();
  };

  const handleCompleteConsultation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!finalSummary.trim()) {
      toast.error('Please provide a final case summary and recommendations.');
      return;
    }
    try {
      setCompleting(true);
      const res: any = await api.completeLawyerConsultation(booking._id, finalSummary.trim());
      toast.success(res?.message || 'Consultation completed');
      setShowCompleteModal(false);
      onRefresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to complete consultation');
    } finally {
      setCompleting(false);
    }
  };

  const handleProcessDemoPay = async () => {
    try {
      setPaying(true);
      await api.payDemoRide({
        bookingId: booking._id,
        bookingType: 'lawyer',
        method: payMethod,
      });
      setPaySuccess(true);
      onRefresh();
    } catch (err: any) {
      toast.error(err.message || 'Payment simulation failed');
    } finally {
      setPaying(false);
    }
  };

  const handleSubmitRating = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setRatingSubmitting(true);
      await api.rateLawyerBooking(booking._id, {
        stars: ratingStars,
        comment: ratingComment,
      });
      setShowRateModal(false);
      toast.success('Rating submitted');
      onRefresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to submit rating');
    } finally {
      setRatingSubmitting(false);
    }
  };

  const handleDownloadReceipt = () => {
    api.downloadLawyerReceipt(
      booking._id,
      `Legal-Consultation-Receipt-${booking.bookingNumber || booking._id}.pdf`
    );
  };

  return (
    <div className="space-y-4">
      {/* ── 1. REQUESTED STATE ──────────────────────────────────── */}
      {status === 'requested' && (
        <div className="p-6 rounded-3xl bg-amber-50/70 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800 text-center animate-in fade-in">
          <div className="w-14 h-14 mx-auto mb-3 rounded-2xl bg-amber-100 dark:bg-amber-900/50 flex items-center justify-center text-amber-600 dark:text-amber-400 shadow-sm">
            <Clock className="w-7 h-7 animate-spin duration-3000" />
          </div>
          <h3 className="text-lg font-black text-slate-900 dark:text-slate-100">
            {booking.urgency === 'urgent'
              ? 'Broadcasting to Available Advocates...'
              : `Waiting for Adv. ${otherUser?.name || 'Advocate'} to confirm...`}
          </h3>
          <p className="mt-1 text-xs text-slate-500 max-w-md mx-auto">
            {booking.urgency === 'urgent'
              ? 'Urgent consultation request sent to verified advocates in this category. The first available advocate will accept and connect.'
              : 'The advocate is reviewing your matter details and scheduled time slot.'}
          </p>

          <div className="mt-5 flex items-center justify-center gap-3">
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={actionLoading}
              onClick={() => setShowCancelModal(true)}
              className="text-rose-600 hover:text-rose-700 hover:bg-rose-50 rounded-xl text-xs"
            >
              Cancel Request
            </Button>
          </div>
        </div>
      )}

      {/* ── 2. RESCHEDULE PROPOSED ──────────────────────────────── */}
      {status === 'reschedule_proposed' && (
        <div className="p-6 rounded-3xl bg-slate-100/70 dark:bg-white/10 border border-slate-200 dark:border-slate-700 text-center animate-in fade-in">
          <div className="w-14 h-14 mx-auto mb-3 rounded-2xl bg-slate-200 dark:bg-white/10 flex items-center justify-center text-slate-900 dark:text-slate-100">
            <Calendar className="w-7 h-7" />
          </div>
          <h3 className="text-lg font-black text-slate-900 dark:text-slate-100">
            Advocate Proposed an Alternate Slot
          </h3>
          <p className="mt-1 text-xs text-slate-600 dark:text-slate-400">
            New Proposed Time:{' '}
            <strong>
              {booking.proposedNewTime
                ? new Date(booking.proposedNewTime).toLocaleString()
                : 'Proposed Slot'}
            </strong>
          </p>
          <div className="mt-4 flex items-center justify-center gap-3">
            <Button
              size="sm"
              className="bg-slate-900 text-white rounded-xl text-xs"
              onClick={async () => {
                try {
                  await api.rescheduleLawyerBooking(
                    booking._id,
                    booking.proposedNewTime
                  );
                  toast.success('New time accepted');
                  onRefresh();
                } catch (err: any) {
                  toast.error(err.message);
                }
              }}
            >
              Accept New Time
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="text-xs rounded-xl"
              onClick={() => setShowCancelModal(true)}
            >
              Decline & Cancel
            </Button>
          </div>
        </div>
      )}

      {/* ── 3. CONFIRMED STATE ──────────────────────────────────── */}
      {status === 'confirmed' && (
        <div className="p-6 rounded-3xl bg-slate-100/60 dark:bg-white/10 border border-slate-200 dark:border-slate-700 shadow-sm space-y-4 animate-in fade-in">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-slate-900 text-white flex items-center justify-center shadow-md">
                <CheckCircle2 className="w-6 h-6" />
              </div>
              <div>
                <Badge className="bg-emerald-600 text-white font-bold text-[10px] uppercase tracking-wider mb-0.5">
                  Consultation Confirmed
                </Badge>
                <h3 className="text-base font-bold text-slate-900 dark:text-slate-100">
                  {isLawyer
                    ? `Client: ${otherUser?.name || 'Client'}`
                    : `Adv. ${otherUser?.name || 'Advocate'} will consult with you`}
                </h3>
                <div className="text-xs text-slate-500 flex items-center gap-2 mt-0.5">
                  <span className="flex items-center gap-1 font-medium text-slate-700 dark:text-slate-300">
                    <ModeIcon className="w-3.5 h-3.5 text-slate-900 dark:text-slate-100" />
                    {booking.consultationMode?.replace('_', ' ')}
                  </span>
                  <span>•</span>
                  <span>
                    {new Date(booking.scheduledDate).toLocaleDateString()} at{' '}
                    {new Date(booking.scheduledDate).toLocaleTimeString([], {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={() => setShowChat(!showChat)}
                className="gap-1.5 rounded-xl text-xs font-semibold"
              >
                <MessageSquare className="w-4 h-4 text-slate-900 dark:text-slate-100" />
                {showChat ? 'Hide Chat' : 'Open Chat'}
              </Button>

              {isLawyer && (
                <Button
                  type="button"
                  size="sm"
                  disabled={actionLoading}
                  onClick={handleStartConsultation}
                  className="bg-slate-900 hover:bg-black text-white font-bold rounded-xl text-xs gap-1.5 shadow-sm"
                >
                  <Scale className="w-4 h-4" />
                  Start Consultation
                </Button>
              )}
            </div>
          </div>

          {/* Reveal Phone (if phone or in-person mode) */}
          {(booking.consultationMode === 'phone' ||
            booking.consultationMode === 'in_person') &&
            otherUser?.phone && (
              <div className="p-3 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 flex items-center justify-between text-xs">
                <span className="text-slate-500 font-medium">Direct Phone Contact:</span>
                <a
                  href={`tel:${otherUser.phone}`}
                  className="font-bold text-slate-900 dark:text-slate-100 hover:underline flex items-center gap-1"
                >
                  <Phone className="w-3.5 h-3.5" />
                  {otherUser.phone}
                </a>
              </div>
            )}

          {/* Chat Panel Collapse */}
          {showChat && (
            <LawyerChatPanel
              bookingId={booking._id}
              currentUser={currentUser}
              targetUser={otherUser}
              onClose={() => setShowChat(false)}
            />
          )}

          <div className="pt-2 border-t border-slate-200 dark:border-slate-800 flex items-center justify-between text-xs">
            <span className="text-slate-500">
              Need changes? You can cancel or reschedule up to 2 hours before scheduled slot.
            </span>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => setShowCancelModal(true)}
              className="text-rose-600 hover:text-rose-700 hover:bg-rose-50 text-xs"
            >
              Cancel
            </Button>
          </div>
        </div>
      )}

      {/* ── 4. IN PROGRESS STATE ────────────────────────────────── */}
      {status === 'in_progress' && (
        <div className="p-6 rounded-3xl bg-white dark:bg-slate-900 border-2 border-slate-900/30 dark:border-white/30 shadow-xl space-y-5 animate-in fade-in">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-emerald-600 text-white flex items-center justify-center shadow-md animate-pulse">
                <Scale className="w-6 h-6" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-ping" />
                  <span className="text-xs font-black text-emerald-600 uppercase tracking-wider">
                    Consultation in Progress
                  </span>
                </div>
                <h3 className="text-base font-bold text-slate-900 dark:text-slate-100 mt-0.5">
                  {isLawyer
                    ? `Client: ${otherUser?.name || 'Client'}`
                    : `Adv. ${otherUser?.name || 'Advocate'}`}
                </h3>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={() => setShowChat(!showChat)}
                className="gap-1.5 rounded-xl text-xs font-semibold"
              >
                <MessageSquare className="w-4 h-4 text-slate-900 dark:text-slate-100" />
                {showChat ? 'Hide Chat' : 'In-App Chat'}
              </Button>

              {isLawyer && (
                <Button
                  type="button"
                  size="sm"
                  onClick={() => setShowCompleteModal(true)}
                  className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs gap-1.5 shadow-sm"
                >
                  <CheckCircle2 className="w-4 h-4" />
                  Mark Completed
                </Button>
              )}
            </div>
          </div>

          {/* Chat Panel in Progress */}
          {showChat && (
            <LawyerChatPanel
              bookingId={booking._id}
              currentUser={currentUser}
              targetUser={otherUser}
              onClose={() => setShowChat(false)}
            />
          )}

          {/* Live Case Notes View */}
          <CaseNotesView
            notes={booking.caseNotes || []}
            isLawyer={isLawyer}
            onAddNote={handleAddCaseNote}
          />
        </div>
      )}

      {/* ── 5. COMPLETED STATE ──────────────────────────────────── */}
      {status === 'completed' && (
        <div className="p-6 rounded-3xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-lg space-y-5 animate-in fade-in">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-emerald-600 text-white flex items-center justify-center shadow-md">
                <CheckCircle2 className="w-6 h-6" />
              </div>
              <div>
                <Badge className="bg-emerald-600 text-white font-bold text-[10px] uppercase tracking-wider mb-0.5">
                  Consultation Concluded
                </Badge>
                <h3 className="text-base font-bold text-slate-900 dark:text-slate-100">
                  {isLawyer
                    ? `Case Session with ${otherUser?.name || 'Client'}`
                    : `Adv. ${otherUser?.name || 'Advocate'} Legal Advisory`}
                </h3>
                <div className="text-xs text-slate-500 mt-0.5">
                  Session Fee: <strong>₹{booking.fee}</strong> •{' '}
                  <span
                    className={
                      isPaid
                        ? 'text-emerald-600 font-bold'
                        : 'text-amber-600 font-bold'
                    }
                  >
                    {isPaid ? 'Paid' : 'Payment Pending'}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={handleDownloadReceipt}
                className="gap-1.5 rounded-xl text-xs font-semibold"
              >
                <Download className="w-4 h-4 text-slate-900 dark:text-slate-100" />
                Download Receipt
              </Button>

              {!isLawyer && onBookFollowUp && (
                <Button
                  type="button"
                  size="sm"
                  onClick={() => onBookFollowUp(booking.caseThreadId || booking._id)}
                  className="bg-slate-900 hover:bg-black text-white font-bold rounded-xl text-xs gap-1.5 shadow-sm"
                >
                  <RotateCcw className="w-4 h-4" />
                  Book Follow-Up
                </Button>
              )}
            </div>
          </div>

          {/* Case Notes & Summary */}
          <CaseNotesView
            notes={booking.caseNotes || []}
            finalSummary={booking.finalCaseSummary}
          />

          {/* Payment Prompt (Client side, if not paid) */}
          {!isLawyer && !isPaid && (
            <div className="p-4 rounded-2xl bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
              <div>
                <div className="text-xs font-bold text-amber-900 dark:text-amber-200">
                  Consultation Payment Due: ₹{booking.fee}
                </div>
                <div className="text-[11px] text-amber-700 dark:text-amber-400">
                  Pay with Demo Wallet or Cash to settle legal fees and unlock rating.
                </div>
              </div>

              <Button
                type="button"
                size="sm"
                onClick={() => setShowPayModal(true)}
                className="bg-amber-600 hover:bg-amber-700 text-white font-bold text-xs rounded-xl shadow-sm gap-1.5"
              >
                <CreditCard className="w-4 h-4" />
                Pay Now (Demo)
              </Button>
            </div>
          )}

          {/* Rating Prompt (Client side, if paid and not rated) */}
          {!isLawyer && isPaid && !hasRated && (
            <div className="p-4 rounded-2xl bg-slate-100/70 dark:bg-white/10 border border-slate-200 dark:border-slate-700 flex items-center justify-between">
              <div>
                <div className="text-xs font-bold text-slate-900 dark:text-slate-100">
                  Rate Adv. {otherUser?.name || 'Advocate'}
                </div>
                <div className="text-[11px] text-slate-500">
                  Help other hospital patients choose verified legal counsel.
                </div>
              </div>
              <Button
                type="button"
                size="sm"
                onClick={() => setShowRateModal(true)}
                className="bg-slate-900 hover:bg-black text-white text-xs rounded-xl font-bold gap-1"
              >
                <Star className="w-3.5 h-3.5 fill-white" />
                Rate Consultation
              </Button>
            </div>
          )}
        </div>
      )}

      {/* ── 6. DECLINED / CANCELLED STATES ──────────────────────── */}
      {(status === 'declined_by_lawyer' ||
        status === 'cancelled_by_user' ||
        status === 'cancelled_by_lawyer') && (
        <div className="p-6 rounded-3xl bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 text-center animate-in fade-in">
          <div className="w-12 h-12 mx-auto mb-3 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-400 flex items-center justify-center">
            <XCircle className="w-6 h-6" />
          </div>
          <h3 className="text-base font-bold text-slate-800 dark:text-slate-200 capitalize">
            {status.replace(/_/g, ' ')}
          </h3>
          <p className="mt-1 text-xs text-slate-500">
            This consultation request was closed. You can search other verified advocates anytime.
          </p>
          {onNewBooking && (
            <Button
              type="button"
              size="sm"
              onClick={onNewBooking}
              className="mt-4 bg-slate-900 hover:bg-black text-white text-xs font-bold rounded-xl"
            >
              Find Another Lawyer
            </Button>
          )}
        </div>
      )}

      {/* ── LAWYER COMPLETE MODAL ───────────────────────────────── */}
      {showCompleteModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="relative w-full max-w-lg bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl p-6 sm:p-7">
            <h3 className="text-base font-bold text-slate-900 dark:text-slate-100 mb-1">
              Conclude Legal Consultation
            </h3>
            <p className="text-xs text-slate-500 mb-4">
              Enter the final legal advice summary, court filing guidance, or follow-up recommendation for the client.
            </p>

            <form onSubmit={handleCompleteConsultation} className="space-y-4">
              <textarea
                rows={4}
                value={finalSummary}
                onChange={(e) => setFinalSummary(e.target.value)}
                placeholder="E.g., Advised filing complaint under Consumer Protection Act before District Commission. Gather treatment bills & discharge summary. Follow-up consultation recommended in 2 weeks..."
                className="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-xs focus:outline-none focus:ring-2 focus:ring-slate-900/20 focus:border-slate-900 dark:focus:border-white dark:text-slate-100"
                required
              />

              <div className="flex justify-end gap-3">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setShowCompleteModal(false)}
                  className="rounded-xl text-xs"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={completing}
                  className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl"
                >
                  {completing ? 'Completing...' : 'Submit & Close Consultation'}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ── DEMO PAYMENT MODAL ──────────────────────────────────── */}
      {showPayModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl p-6 space-y-4">
            <div className="flex items-center gap-2.5">
              <div className="w-10 h-10 rounded-xl bg-amber-100 dark:bg-amber-900/40 text-amber-600 flex items-center justify-center">
                <CreditCard className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-base font-bold text-slate-900 dark:text-slate-100">
                  Consultation Fee Payment
                </h3>
                <span className="text-[10px] font-bold text-amber-600 uppercase tracking-wider bg-amber-50 dark:bg-amber-950/40 px-2 py-0.5 rounded">
                  DEMO MODE SIMULATION
                </span>
              </div>
            </div>

            <div className="p-4 rounded-2xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <span className="text-xs text-slate-500">Amount Due:</span>
              <span className="text-xl font-black text-slate-900 dark:text-slate-100">
                ₹{booking.fee}
              </span>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-700 dark:text-slate-300">
                Choose Payment Method:
              </label>
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => setPayMethod('demo_wallet')}
                  className={`p-3 rounded-xl border text-xs font-bold transition-all ${
                    payMethod === 'demo_wallet'
                      ? 'border-slate-900 dark:border-white bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-slate-200'
                      : 'border-slate-200 dark:border-slate-800 text-slate-600'
                  }`}
                >
                  💳 Demo Wallet
                </button>
                <button
                  type="button"
                  onClick={() => setPayMethod('cash')}
                  className={`p-3 rounded-xl border text-xs font-bold transition-all ${
                    payMethod === 'cash'
                      ? 'border-slate-900 dark:border-white bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-slate-200'
                      : 'border-slate-200 dark:border-slate-800 text-slate-600'
                  }`}
                >
                  💵 Cash / Direct
                </button>
              </div>
            </div>

            <div className="pt-3 flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setShowPayModal(false)}
                className="text-xs rounded-xl"
              >
                Close
              </Button>
              <Button
                type="button"
                size="sm"
                disabled={paying}
                onClick={handleProcessDemoPay}
                className="bg-slate-900 hover:bg-black text-white font-bold text-xs rounded-xl"
              >
                {paying ? 'Processing...' : 'Confirm Demo Pay'}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* ── CANCEL MODAL (inline reason, no window.prompt) ─────── */}
      {showCancelModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl p-6 space-y-4">
            <h3 className="text-base font-bold text-slate-900 dark:text-slate-100">
              Cancel Consultation
            </h3>
            <form onSubmit={handleCancelBooking} className="space-y-4">
              <textarea
                rows={3}
                value={cancelReason}
                onChange={(e) => setCancelReason(e.target.value)}
                placeholder="Reason for cancellation (e.g. Court commitment)..."
                className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-xs focus:outline-none focus:ring-2 focus:ring-slate-900/20 focus:border-slate-900 dark:focus:border-white dark:text-slate-100"
              />
              <div className="flex justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => { setShowCancelModal(false); setCancelReason(''); }}
                  className="rounded-xl text-xs"
                >
                  Keep Booking
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={actionLoading}
                  className="bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs rounded-xl"
                >
                  {actionLoading ? 'Cancelling...' : 'Confirm Cancel'}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ── RATING MODAL ────────────────────────────────────────── */}
      {showRateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl p-6 space-y-4">
            <h3 className="text-base font-bold text-slate-900 dark:text-slate-100">
              Rate Your Legal Consultation
            </h3>

            <form onSubmit={handleSubmitRating} className="space-y-4">
              <div className="flex justify-center gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setRatingStars(star)}
                    className="p-1 text-2xl transition-transform hover:scale-110"
                  >
                    <Star
                      className={`w-7 h-7 ${
                        star <= ratingStars
                          ? 'fill-amber-400 text-amber-400'
                          : 'text-slate-300 dark:text-slate-700'
                      }`}
                    />
                  </button>
                ))}
              </div>

              <textarea
                rows={3}
                value={ratingComment}
                onChange={(e) => setRatingComment(e.target.value)}
                placeholder="Share your experience with Adv. guidance, clarity, and professionalism..."
                className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-xs focus:outline-none focus:ring-2 focus:ring-slate-900/20 focus:border-slate-900 dark:focus:border-white dark:text-slate-100"
              />

              <div className="flex justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setShowRateModal(false)}
                  className="rounded-xl text-xs"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={ratingSubmitting}
                  className="bg-slate-900 hover:bg-black text-white font-bold text-xs rounded-xl"
                >
                  {ratingSubmitting ? 'Submitting...' : 'Submit Rating'}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { FileText, Clock, Plus, Send, CheckCircle2, ShieldAlert } from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { toast } from 'sonner';

interface CaseNoteItem {
  _id?: string;
  authorRole?: string;
  note: string;
  createdAt: string;
}

interface Props {
  notes: CaseNoteItem[];
  isLawyer?: boolean;
  onAddNote?: (note: string) => Promise<void>;
  finalSummary?: string;
}

export const CaseNotesView: React.FC<Props> = ({
  notes = [],
  isLawyer = false,
  onAddNote,
  finalSummary,
}) => {
  const [newNote, setNewNote] = useState('');
  const [saving, setSaving] = useState(false);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNote.trim() || !onAddNote) return;
    try {
      setSaving(true);
      await onAddNote(newNote.trim());
      setNewNote('');
    } catch (err: any) {
      toast.error(err.message || 'Failed to save note');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-xl bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-slate-100 flex items-center justify-center">
            <FileText className="w-4 h-4" />
          </div>
          <div>
            <h4 className="text-xs font-bold text-slate-900 dark:text-slate-100 uppercase tracking-wider">
              Legal Case Notes & Advisory Record
            </h4>
            <p className="text-[11px] text-slate-500">
              Live consultation notes, medical record review, and legal action steps
            </p>
          </div>
        </div>

        <Badge variant="outline" className="text-[10px] gap-1 font-mono">
          <ShieldAlert className="w-3 h-3 text-amber-500" />
          Privileged & Confidential
        </Badge>
      </div>

      {/* Final Case Summary (if completed) */}
      {finalSummary && (
        <div className="p-4 rounded-2xl bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-800">
          <div className="flex items-center gap-1.5 text-xs font-bold text-emerald-800 dark:text-emerald-300 mb-1">
            <CheckCircle2 className="w-4 h-4 text-emerald-600" />
            Final Legal Case Summary & Next Steps
          </div>
          <p className="text-xs sm:text-sm text-slate-800 dark:text-slate-200 leading-relaxed font-sans whitespace-pre-wrap">
            {finalSummary}
          </p>
        </div>
      )}

      {/* Lawyer Note Input (Only if isLawyer) */}
      {isLawyer && onAddNote && (
        <form onSubmit={handleSave} className="p-3.5 rounded-2xl bg-slate-50 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700 space-y-2">
          <textarea
            rows={3}
            value={newNote}
            onChange={(e) => setNewNote(e.target.value)}
            placeholder="Type live case observation, relevant medical law precedent, documents needed, or advice given..."
            className="w-full px-3 py-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-xs focus:outline-none focus:ring-2 focus:ring-slate-900/20 focus:border-slate-900 dark:focus:border-white dark:text-slate-100"
          />
          <div className="flex justify-end">
            <Button
              type="submit"
              disabled={saving || !newNote.trim()}
              size="sm"
              className="bg-slate-900 hover:bg-black text-white font-bold text-xs rounded-xl shadow-sm gap-1.5"
            >
              <Send className="w-3.5 h-3.5" />
              {saving ? 'Saving...' : 'Add Case Note'}
            </Button>
          </div>
        </form>
      )}

      {/* Notes Stream */}
      {notes.length === 0 && !finalSummary ? (
        <div className="p-6 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800 text-center text-xs text-slate-400">
          No case notes recorded yet. Advocate will log notes during consultation.
        </div>
      ) : (
        <div className="space-y-2.5">
          {notes.map((note, index) => (
            <div
              key={note._id || index}
              className="p-3.5 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/90 shadow-sm space-y-1.5 text-xs animate-in fade-in duration-200"
            >
              <div className="flex items-center justify-between text-[11px] text-slate-400">
                <span className="font-bold text-slate-900 dark:text-slate-100 flex items-center gap-1">
                  Advocate Case Note #{index + 1}
                </span>
                <span className="flex items-center gap-1">
                  <Clock className="w-3 h-3" />
                  {note.createdAt ? new Date(note.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'Live'}
                </span>
              </div>
              <p className="text-slate-800 dark:text-slate-200 leading-relaxed whitespace-pre-wrap">
                {note.note}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import {
  Video,
  Phone,
  UserCheck,
  MessageSquare,
  Zap,
  Calendar,
  Clock,
  IndianRupee,
  FileText,
  UploadCloud,
  X,
  Sparkles,
  ArrowRight,
  AlertCircle,
} from 'lucide-react';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Badge } from '../ui/badge';
import { LEGAL_CATEGORIES } from './LegalCategorySelector';
import { toast } from 'sonner';

export interface CaseRequirementData {
  category: string;
  caseDescription: string;
  urgency: 'normal' | 'urgent';
  consultationMode: 'video' | 'phone' | 'in_person' | 'chat';
  scheduledDate: string;
  startTime: string;
  budgetMin?: number;
  budgetMax?: number;
  documents: string[];
}

interface Props {
  selectedCategory: string;
  onBackToCategory: () => void;
  onSubmit: (data: CaseRequirementData) => void;
  loading?: boolean;
}

const CONSULTATION_MODES = [
  { id: 'video', label: 'Online Video Call', icon: Video, desc: 'Face-to-face video consultation' },
  { id: 'phone', label: 'Phone Call', icon: Phone, desc: 'Direct phone advisory' },
  { id: 'in_person', label: 'In-Person Chamber', icon: UserCheck, desc: 'Chamber / Hospital visit' },
  { id: 'chat', label: 'In-App Chat Only', icon: MessageSquare, desc: 'Text consultation & vetting' },
];

export const CaseRequirementForm: React.FC<Props> = ({
  selectedCategory,
  onBackToCategory,
  onSubmit,
  loading = false,
}) => {
  const currentCategory = LEGAL_CATEGORIES.find((c) => c.code === selectedCategory);

  const [description, setDescription] = useState('');
  const [urgency, setUrgency] = useState<'normal' | 'urgent'>('normal');
  const [mode, setMode] = useState<'video' | 'phone' | 'in_person' | 'chat'>('video');
  const [scheduledDate, setScheduledDate] = useState(
    new Date(Date.now() + 86400000).toISOString().split('T')[0]
  );
  const [startTime, setStartTime] = useState('11:00');
  const [budgetMin, setBudgetMin] = useState<number | ''>('');
  const [budgetMax, setBudgetMax] = useState<number | ''>('');
  const [documentInput, setDocumentInput] = useState('');
  const [documents, setDocuments] = useState<string[]>([]);

  const handleAddDocument = () => {
    if (!documentInput.trim()) return;
    setDocuments((prev) => [...prev, documentInput.trim()]);
    setDocumentInput('');
  };

  const handleRemoveDocument = (index: number) => {
    setDocuments((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim()) {
      toast.error('Please provide a brief description of your legal requirement or issue.');
      return;
    }
    onSubmit({
      category: selectedCategory,
      caseDescription: description.trim(),
      urgency,
      consultationMode: mode,
      scheduledDate,
      startTime,
      budgetMin: budgetMin === '' ? undefined : Number(budgetMin),
      budgetMax: budgetMax === '' ? undefined : Number(budgetMax),
      documents,
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Category Pill Banner */}
      <div className="p-4 rounded-2xl bg-slate-100/70 dark:bg-white/10 border border-slate-200 dark:border-slate-700 flex items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-slate-900 text-white flex items-center justify-center font-bold">
            {currentCategory?.icon ? (
              <currentCategory.icon className="w-5 h-5" />
            ) : (
              '⚖️'
            )}
          </div>
          <div>
            <div className="text-[11px] font-bold text-slate-900 dark:text-slate-100 uppercase tracking-wider">
              Selected Legal Category
            </div>
            <div className="text-base font-bold text-slate-900 dark:text-slate-100">
              {currentCategory?.name || selectedCategory}
            </div>
          </div>
        </div>

        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={onBackToCategory}
          className="text-xs rounded-xl"
        >
          Change Category
        </Button>
      </div>

      {/* Case Description */}
      <div>
        <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-1.5">
          Brief Description of Your Legal Matter / Issue <span className="text-rose-500">*</span>
        </label>
        <textarea
          rows={3}
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="E.g., Doctor did not disclose surgical complication, ICU bill has inflated charges, insurance company rejected reimbursement claim, need help drafting police FIR for accident..."
          className="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-slate-900/20 focus:border-slate-900 dark:focus:border-white dark:text-slate-100 placeholder:text-slate-400"
          required
        />
        <p className="mt-1 text-[11px] text-slate-500">
          Strictly confidential. Shared only with your assigned advocate.
        </p>
      </div>

      {/* Urgency Selector */}
      <div>
        <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-2">
          Urgency Level
        </label>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <button
            type="button"
            onClick={() => setUrgency('normal')}
            className={`p-3.5 rounded-2xl border text-left transition-all flex items-start gap-3 ${
              urgency === 'normal'
                ? 'border-slate-900 dark:border-white bg-slate-100/40 dark:bg-white/10 ring-1 ring-slate-900 dark:ring-white'
                : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-slate-300'
            }`}
          >
            <Calendar className="w-5 h-5 text-slate-900 dark:text-slate-100 mt-0.5" />
            <div>
              <div className="font-bold text-xs text-slate-900 dark:text-slate-100">
                Scheduled Consultation
              </div>
              <div className="text-[11px] text-slate-500 mt-0.5">
                Book for a convenient date & time slot
              </div>
            </div>
          </button>

          <button
            type="button"
            onClick={() => setUrgency('urgent')}
            className={`p-3.5 rounded-2xl border text-left transition-all flex items-start gap-3 ${
              urgency === 'urgent'
                ? 'border-rose-600 bg-rose-50/50 dark:bg-rose-950/30 ring-1 ring-rose-500'
                : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-slate-300'
            }`}
          >
            <Zap className="w-5 h-5 text-rose-600 mt-0.5 animate-pulse" />
            <div>
              <div className="font-bold text-xs text-rose-700 dark:text-rose-400 flex items-center gap-1.5">
                Urgent Legal Help (Within 1 Hour)
                <span className="text-[9px] px-1.5 py-0.2 bg-rose-600 text-white rounded-full uppercase font-bold">
                  Fast
                </span>
              </div>
              <div className="text-[11px] text-slate-500 mt-0.5">
                Broadcasts instantly to all available advocates in this category
              </div>
            </div>
          </button>
        </div>
      </div>

      {/* Preferred Consultation Mode */}
      <div>
        <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-2">
          Preferred Consultation Mode <span className="text-rose-500">*</span>
        </label>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
          {CONSULTATION_MODES.map((m) => {
            const Icon = m.icon;
            const isSelected = mode === m.id;
            return (
              <button
                key={m.id}
                type="button"
                onClick={() => setMode(m.id as any)}
                className={`p-3 rounded-xl border text-center transition-all flex flex-col items-center justify-center gap-1.5 ${
                  isSelected
                    ? 'border-slate-900 dark:border-white bg-slate-100/50 dark:bg-white/10 ring-1 ring-slate-900 dark:ring-white'
                    : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-slate-300'
                }`}
              >
                <Icon
                  className={`w-5 h-5 ${
                    isSelected ? 'text-slate-900 dark:text-slate-100' : 'text-slate-500'
                  }`}
                />
                <span className="font-bold text-xs text-slate-900 dark:text-slate-100">
                  {m.label}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Date & Time (Only if Normal urgency) */}
      {urgency === 'normal' && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
          <div>
            <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-1.5 flex items-center gap-1.5">
              <Calendar className="w-3.5 h-3.5 text-slate-900 dark:text-slate-100" />
              Consultation Date
            </label>
            <Input
              type="date"
              value={scheduledDate}
              min={new Date().toISOString().split('T')[0]}
              onChange={(e) => setScheduledDate(e.target.value)}
              className="rounded-xl text-xs"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-1.5 flex items-center gap-1.5">
              <Clock className="w-3.5 h-3.5 text-slate-900 dark:text-slate-100" />
              Preferred Time Slot
            </label>
            <Input
              type="time"
              value={startTime}
              onChange={(e) => setStartTime(e.target.value)}
              className="rounded-xl text-xs"
              required
            />
          </div>
        </div>
      )}

      {/* Budget Range (Optional) */}
      <div>
        <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-1.5 flex items-center gap-1.5">
          <IndianRupee className="w-3.5 h-3.5 text-slate-900 dark:text-slate-100" />
          Budget Range (Optional)
        </label>
        <div className="grid grid-cols-2 gap-3">
          <Input
            type="number"
            min={0}
            step={100}
            placeholder="Min Budget (₹)"
            value={budgetMin}
            onChange={(e) => setBudgetMin(e.target.value === '' ? '' : Number(e.target.value))}
            className="rounded-xl text-xs"
          />
          <Input
            type="number"
            min={0}
            step={100}
            placeholder="Max Budget (₹)"
            value={budgetMax}
            onChange={(e) => setBudgetMax(e.target.value === '' ? '' : Number(e.target.value))}
            className="rounded-xl text-xs"
          />
        </div>
      </div>

      {/* Upload Relevant Documents (Reports, Bills, FIR) */}
      <div>
        <label className="block text-xs font-bold text-slate-800 dark:text-slate-200 mb-1.5 flex items-center gap-1.5">
          <FileText className="w-3.5 h-3.5 text-slate-900 dark:text-slate-100" />
          Attach Relevant Documents / Reference Files (Optional)
        </label>
        <div className="flex gap-2">
          <Input
            type="text"
            placeholder="E.g., Discharge Summary.pdf, FIR Copy, Treatment Bill #492"
            value={documentInput}
            onChange={(e) => setDocumentInput(e.target.value)}
            className="rounded-xl text-xs"
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                handleAddDocument();
              }
            }}
          />
          <Button
            type="button"
            onClick={handleAddDocument}
            variant="outline"
            className="rounded-xl text-xs shrink-0"
          >
            + Add
          </Button>
        </div>

        {documents.length > 0 && (
          <div className="mt-2.5 flex flex-wrap gap-2">
            {documents.map((doc, idx) => (
              <Badge
                key={idx}
                variant="secondary"
                className="px-2.5 py-1 text-xs gap-1.5 rounded-lg bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-slate-200 border border-slate-200 dark:border-slate-700"
              >
                <FileText className="w-3 h-3" />
                <span>{doc}</span>
                <button
                  type="button"
                  onClick={() => handleRemoveDocument(idx)}
                  className="hover:text-rose-600"
                >
                  <X className="w-3 h-3" />
                </button>
              </Badge>
            ))}
          </div>
        )}
      </div>

      {/* Form Action */}
      <div className="pt-3 border-t border-slate-200 dark:border-slate-800 flex items-center justify-between gap-4">
        <Button
          type="button"
          variant="ghost"
          onClick={onBackToCategory}
          className="text-xs"
        >
          ← Back to Categories
        </Button>

        <Button
          type="submit"
          disabled={loading}
          className="bg-slate-900 hover:bg-black text-white font-bold text-xs rounded-xl shadow-md gap-1.5 px-6"
        >
          {loading ? 'Searching Advocates...' : 'Find Matching Lawyers →'}
        </Button>
      </div>
    </form>
  );
};

