                  >
                    Inquire / Book
                  </Button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { FileCheck, AlertOctagon, X, Mic, History, Wand2 } from 'lucide-react';
