import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search, Mic, MicOff, MapPin, X, AlertTriangle, Phone, ShieldAlert,
  Sparkles, Stethoscope, Building2, Pill, ChevronRight, CheckCircle2,
  HeartPulse, ArrowRight
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { allCities } from '@/data/cities';
import { useTranslation } from 'react-i18next';

export const QUICK_SYMPTOMS = [
  { label: '🦷 Tooth pain', query: 'tooth pain', hint: 'Dentist' },
  { label: '🦴 Hadda ka doctor', query: 'hadda ka doctor', hint: 'Orthopaedics' },
  { label: '❤️ Seene me dard', query: 'seene me dard', hint: 'Emergency / Cardiology' },
  { label: '👶 Fever in baby', query: 'fever in baby', hint: 'Pediatrician' },
  { label: '🧠 Tanav / Depression', query: 'tanav anxiety depression', hint: 'Mental Health' },
  { label: '👁️ Blurry vision', query: 'chashma eye test', hint: 'Ophthalmology' },
  { label: '💊 Sugar / Diabetes', query: 'sugar diabetes test', hint: 'Endocrinology' },
  { label: '🌿 Ayurvedic Clinic', query: 'ayurveda panchakarma', hint: 'AYUSH' },
];

interface Props {
  initialQuery?: string;
  initialCity?: string;
  compact?: boolean;
  autoNavigate?: boolean;
  onSearchSubmitted?: (query: string, city: string) => void;
  className?: string;
}

export default function UnifiedSearch({
  initialQuery = '',
  initialCity = '',
  compact = false,
  autoNavigate = true,
  onSearchSubmitted,
  className = '',
}: Props) {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const [query, setQuery] = useState(initialQuery);
  const [selectedCity, setSelectedCity] = useState(initialCity || 'All Cities');
  const [results, setResults] = useState<any[]>([]);
  const [taxonomy, setTaxonomy] = useState<any>(null);
  // Taxonomy-backed typeahead chips (/search/suggest — tiles, subs,
  // conditions, procedures, Hinglish symptoms; sensitive items stay hidden).
  const [suggestList, setSuggestList] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [isListening, setIsListening] = useState(false);

  // Unmet demand modal state
  const [unmetModalOpen, setUnmetModalOpen] = useState(false);
  const [unmetContact, setUnmetContact] = useState('');
  const [unmetSubmitted, setUnmetSubmitted] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const debounceTimer = useRef<any>(null);

  // Instant client-side emergency & mental health red-flag detection (zero-latency safety guard)
  const isImmediateEmergency = /chest pain|heart attack|cardiac|seene me dard|saans nahi aa rahi|stroke|unconscious/i.test(query);
  const isImmediateSensitive = /depression|tanav|suicid|hopeless|anxiety|panic attack/i.test(query);

  // Close dropdown on outside click
  useEffect(() => {
    const handleOutsideClick = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  // Fetch unified search live preview
  const fetchPreview = useCallback(async (qText: string, cName: string) => {
    if (!qText.trim() || qText.trim().length < 2) {
      setResults([]);
      setTaxonomy(null);
      setSuggestList([]);
      return;
    }
    setLoading(true);
    try {
      const qParams = new URLSearchParams();
      qParams.set('q', qText.trim());
      if (cName && cName !== 'All Cities') qParams.set('city', cName);
      qParams.set('limit', '8');

      const [res, sug]: any[] = await Promise.all([
        api.get(`/search/unified?${qParams.toString()}`).catch(() => null),
        api.get(`/search/suggest?q=${encodeURIComponent(qText.trim())}`).catch(() => null),
      ]);
      if (sug?.success) setSuggestList(sug.results || []); else setSuggestList([]);
      if (res?.success) {
        setResults(res.results || []);
        setTaxonomy(res.taxonomy || null);
      } else {
        setResults([]);
        setTaxonomy(null);
      }
    } catch {
      setResults([]);
      setSuggestList([]);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleQueryChange = (val: string) => {
    setQuery(val);
    setShowDropdown(true);
    clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(() => {
      fetchPreview(val, selectedCity);
    }, 280);
  };

  const handleCityChange = (cityName: string) => {
    setSelectedCity(cityName);
    if (query.trim()) {
      fetchPreview(query, cityName);
    }
  };

  const triggerSearch = (searchVal = query) => {
    setShowDropdown(false);
    if (onSearchSubmitted) {
      onSearchSubmitted(searchVal.trim(), selectedCity);
    }
    if (autoNavigate) {
      const q = new URLSearchParams();
      if (searchVal.trim()) q.set('q', searchVal.trim());
      if (selectedCity && selectedCity !== 'All Cities') q.set('city', selectedCity);
      navigate(`/search?${q.toString()}`);
    }
  };

  // Web Speech API Voice Search handler
  const toggleVoiceSearch = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      toast.error('Voice search is not supported on this browser. Please type your query.');
      return;
    }

    if (isListening) {
      setIsListening(false);
      return;
    }

    try {
      const recognition = new SpeechRecognition();
      recognition.lang = 'hi-IN'; // Supports Hindi/Hinglish/Indian English
      recognition.continuous = false;
      recognition.interimResults = false;

      recognition.onstart = () => {
        setIsListening(true);
        toast.info('Listening... Speak your symptom, doctor, or test name');
      };

      recognition.onresult = (event: any) => {
        const transcript = event.results?.[0]?.[0]?.transcript || '';
        if (transcript) {
          setQuery(transcript);
          setIsListening(false);
          setShowDropdown(true);
          fetchPreview(transcript, selectedCity);
          toast.success(`Heard: "${transcript}"`);
        }
      };

      recognition.onerror = () => {
        setIsListening(false);
        toast.error('Could not catch your voice. Please try typing.');
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognition.start();
    } catch {
      setIsListening(false);
      toast.error('Voice microphone access denied or failed.');
    }
  };

  // Submit unmet demand request
  const submitUnmetDemand = async () => {
    if (!query.trim()) return;
    try {
      await api.post('/search/unmet-demand', {
        query: query.trim(),
        city: selectedCity !== 'All Cities' ? selectedCity : 'Unspecified',
        userContact: unmetContact.trim(),
      });
      setUnmetSubmitted(true);
      toast.success('Service request logged! Our operations team prioritizes onboarding providers in high-demand areas.');
      setTimeout(() => {
        setUnmetModalOpen(false);
        setUnmetSubmitted(false);
        setUnmetContact('');
      }, 1500);
    } catch {
      toast.error('Failed to log request. Please try again.');
    }
  };

  return (
    <div ref={containerRef} className={`relative w-full ${className}`}>
      {/* ── Main Unified Search Input Bar ── */}
      <div className={`relative flex items-center bg-card rounded-2xl border-2 transition-all shadow-md ${
        showDropdown && results.length > 0
          ? 'border-primary ring-4 ring-primary/10 rounded-b-none'
          : 'border-border/80 hover:border-primary/50'
      }`}>
        {/* City Filter Selector */}
        <div className="relative border-r border-border/70 hidden sm:flex items-center pl-3.5 pr-2">
          <MapPin className="w-4 h-4 text-primary shrink-0 mr-1.5" />
          <select
            value={selectedCity}
            onChange={(e) => handleCityChange(e.target.value)}
            className="text-xs font-semibold bg-transparent text-foreground cursor-pointer focus:outline-none py-3 pr-1"
            aria-label="Select City"
          >
            <option value="All Cities">All Cities</option>
            {allCities.slice(0, 20).map((c) => (
              <option key={c.name} value={c.name}>{c.name}</option>
            ))}
          </select>
        </div>

        {/* Query Input */}
        <div className="relative flex-1 flex items-center">
          <Search className="w-5 h-5 text-muted-foreground ml-3 shrink-0" />
          <Input
            value={query}
            onChange={(e) => handleQueryChange(e.target.value)}
            onFocus={() => setShowDropdown(true)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                triggerSearch();
              }
            }}
            placeholder={t('common.search', { defaultValue: 'Search doctors, clinics, tests, medicines…' })}
            className="border-0 shadow-none focus-visible:ring-0 text-sm h-13 pl-3 pr-10 bg-transparent placeholder:text-muted-foreground/70"
          />
          {query && (
            <button
              type="button"
              onClick={() => { setQuery(''); setResults([]); setTaxonomy(null); }}
              className="p-1 text-muted-foreground hover:text-foreground mr-1"
              aria-label="Clear search"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        {/* Voice Search Mic Button */}
        <button
          type="button"
          onClick={toggleVoiceSearch}
          className={`p-2.5 mr-2 rounded-xl transition-all ${
            isListening
              ? 'bg-destructive text-white animate-pulse shadow-md'
              : 'text-muted-foreground hover:text-primary hover:bg-primary/10'
          }`}
          title={isListening ? 'Listening...' : 'Voice Search (Hindi / English)'}
          aria-label="Voice Search"
        >
          {isListening ? <MicOff className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
        </button>

        {/* Search CTA Button */}
        <Button
          onClick={() => triggerSearch()}
          className="mr-2 px-5 h-10 rounded-xl font-semibold gap-1.5 shrink-0 shadow-sm"
        >
          <Search className="w-4 h-4" /> Search
        </Button>
      </div>

      {/* ── Quick Symptom Suggestions Strip (if not compact) ── */}
      {!compact && (
        <div className="flex items-center gap-2 overflow-x-auto pt-2.5 pb-1 text-xs no-scrollbar">
          <span className="text-[11px] font-semibold text-muted-foreground shrink-0 uppercase tracking-wider">
            Popular Symptoms:
          </span>
          {QUICK_SYMPTOMS.map((s) => (
            <button
              key={s.label}
              type="button"
              onClick={() => {
                setQuery(s.query);
                fetchPreview(s.query, selectedCity);
                triggerSearch(s.query);
              }}
              className="px-2.5 py-1 rounded-full border border-border/70 bg-card hover:border-primary/50 hover:bg-primary/5 text-foreground transition-all shrink-0 font-medium"
            >
              {s.label}
            </button>
          ))}
        </div>
      )}

      {/* ── Typeahead Live Preview & Emergency Dropdown ── */}
      {showDropdown && (query.trim().length >= 2 || results.length > 0 || taxonomy) && (
        <div className="absolute top-full left-0 right-0 z-50 bg-card border-2 border-t-0 border-primary rounded-b-2xl shadow-2xl max-h-[80vh] overflow-y-auto divide-y divide-border/60">
          {/* Red-Flag Emergency Escalation Banner */}
          {(taxonomy?.isEmergency || isImmediateEmergency) && (
            <div className="p-3.5 bg-red-600 text-white flex items-start justify-between gap-3 animate-pulse">
              <div className="flex items-start gap-2.5">
                <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5 text-white" />
                <div>
                  <p className="text-sm font-bold">EMERGENCY RED-FLAG TRIGGERED: Chest pain / heart attack signs detected</p>
                  <p className="text-xs opacity-95 mt-0.5">
                    {taxonomy?.emergencyMessage || 'Possible life-threatening emergency. Do not wait for online booking.'}
                  </p>
                </div>
              </div>
              <a
                href="tel:108"
                className="px-3.5 py-1.5 bg-white text-red-700 rounded-lg text-xs font-bold hover:bg-red-50 flex items-center gap-1.5 shrink-0 shadow-sm"
              >
                <Phone className="w-3.5 h-3.5" /> Call 108 Ambulance
              </a>
            </div>
          )}

          {/* Mental Health Crisis Support Banner */}
          {(taxonomy?.isSensitive || isImmediateSensitive) && (
            <div className="p-3 bg-purple-600 text-white flex items-center justify-between gap-3 text-xs font-medium">
              <div className="flex items-center gap-2">
                <ShieldAlert className="w-4 h-4 text-purple-200 shrink-0" />
                <span>Mental health crisis support: You are not alone. 24x7 Free Tele-MANAS support available.</span>
              </div>
              <a
                href="tel:14416"
                className="px-2.5 py-1 bg-white text-purple-800 rounded-md font-bold text-[11px] hover:bg-purple-50 shrink-0"
              >
                Call Tele-MANAS (14416)
              </a>
            </div>
          )}

          {/* Symptom to Specialty Mapping Suggestion */}
          {taxonomy?.matchedSpecialty && (
            <div className="p-3 bg-primary/5 flex items-center justify-between text-xs">
              <div className="flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-primary shrink-0" />
                <span>
                  Symptom mapped to: <strong className="text-primary font-bold">{taxonomy.matchedSpecialty}</strong>
                </span>
              </div>
              {taxonomy.suggestedQuery && (
                <button
                  type="button"
                  onClick={() => {
                    setQuery(taxonomy.suggestedQuery);
                    triggerSearch(taxonomy.suggestedQuery);
                  }}
                  className="text-primary hover:underline font-semibold"
                >
                  Search {taxonomy.suggestedQuery} →
                </button>
              )}
            </div>
          )}

          {/* Taxonomy-backed specialty chips (§5.4) */}
          {suggestList.length > 0 && (
            <div className="py-1.5">
              <div className="px-3 py-1.5 text-[11px] font-bold uppercase text-muted-foreground tracking-wider">
                Specialties & symptoms
              </div>
              <div className="px-3 pb-2 flex flex-wrap gap-1.5">
                {suggestList.map((s, i) => (
                  <button
                    key={`${s.kind}-${s.code || s.label}-${i}`}
                    type="button"
                    onClick={() => {
                      setShowDropdown(false);
                      if (s.kind === 'specialty' && s.code) {
                        navigate(`/browse-specialties/${s.code}`);
                        return;
                      }
                      if (s.specialty?.name) {
                        navigate(`/clinic-doctors?specialty=${encodeURIComponent(s.specialty.name)}`);
                        return;
                      }
                      triggerSearch(s.label || s.name || '');
                    }}
                    className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full border border-border/70 bg-card hover:border-primary/50 hover:bg-primary/5 transition-colors"
                  >
                    {s.specialty?.icon && <span className="text-muted-foreground">{s.specialty.icon}</span>}
                    <span className={s.kind === 'symptom' ? 'text-muted-foreground' : 'text-foreground font-medium'}>
                      {s.label || s.name}{s.nameHi ? ` · ${s.nameHi}` : ''}
                    </span>
                    {s.parentName && (
                      <span className="text-[10px] text-muted-foreground/70">in {s.parentName}</span>
                    )}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Live Search Results List */}
          {loading ? (
            <div className="p-6 text-center text-sm text-muted-foreground">
              <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-2" />
              Searching across clinics, doctors, tests & medicines...
            </div>
          ) : results.length > 0 ? (
            <div className="py-2">
              <div className="px-3 py-1.5 text-[11px] font-bold uppercase text-muted-foreground tracking-wider">
                Matching Providers & Services
              </div>
              {results.map((item) => {
                const isDoc = item.vertical === 'doctor';
                const isMed = item.vertical === 'medicine';
                const Icon = isDoc ? Stethoscope : isMed ? Pill : Building2;

                return (
                  <button
                    key={`${item.vertical}-${item.id}`}
                    type="button"
                    onClick={() => {
                      setShowDropdown(false);
                      if (isDoc) navigate(`/doctor/${item.id}`);
                      else if (isMed) navigate(`/buy-medicine?q=${encodeURIComponent(item.fullName)}`);
                      else navigate(`/facility/${item.slug || item.id}`);
                    }}
                    className="w-full px-4 py-2.5 flex items-center justify-between hover:bg-muted/60 text-left transition-colors group"
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-9 h-9 rounded-xl bg-primary/10 text-primary flex items-center justify-center shrink-0">
                        <Icon className="w-4 h-4" />
                      </div>
                      <div className="min-w-0">
                        <p className="font-semibold text-sm text-foreground truncate group-hover:text-primary">
                          {item.fullName}
                        </p>
                        <p className="text-xs text-muted-foreground truncate">
                          {[item.specialization || item.category, item.city].filter(Boolean).join(' · ')}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                      {item.verified && (
                        <Badge variant="outline" className="text-[10px] gap-1 text-success border-success/30">
                          <CheckCircle2 className="w-2.5 h-2.5" /> Verified
                        </Badge>
                      )}
                      <ChevronRight className="w-4 h-4 text-muted-foreground group-hover:translate-x-0.5 transition-transform" />
                    </div>
                  </button>
                );
              })}
              <div className="p-2.5 bg-muted/30 border-t border-border flex justify-between items-center text-xs">
                <span className="text-muted-foreground">Showing top matches for "{query}"</span>
                <Button size="sm" variant="ghost" className="h-7 text-xs font-semibold gap-1 text-primary" onClick={() => triggerSearch()}>
                  View all results <ArrowRight className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ) : query.trim().length >= 2 ? (
            /* ── Zero Results Unmet Demand State ── */
            <div className="p-6 text-center space-y-3">
              <HeartPulse className="w-10 h-10 text-muted-foreground/40 mx-auto" />
              <div>
                <p className="font-semibold text-foreground text-sm">
                  No verified providers found matching "{query}" in {selectedCity}
                </p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  Looking for this service in your area? Let us know and our onboarding team will bring them on board.
                </p>
              </div>
              <Button
                size="sm"
                variant="outline"
                onClick={() => setUnmetModalOpen(true)}
                className="gap-1.5 font-semibold"
              >
                Request this service in {selectedCity}
              </Button>
            </div>
          ) : null}
        </div>
      )}

      {/* ── Unmet Demand Request Modal ── */}
      {unmetModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm" role="dialog" aria-modal="true" aria-labelledby="unmet-title">
          <div className="bg-card border rounded-2xl shadow-2xl p-6 w-full max-w-md space-y-4">
            <div className="flex items-center justify-between">
              <h3 id="unmet-title" className="text-base font-bold text-foreground flex items-center gap-2">
                <Building2 className="w-5 h-5 text-primary" /> Request Service in Your City
              </h3>
              <button
                type="button"
                onClick={() => setUnmetModalOpen(false)}
                className="text-muted-foreground hover:text-foreground"
                aria-label="Close modal"
              >
                ✕
              </button>
            </div>
            <p className="text-xs text-muted-foreground">
              We monitor unmet search requests to partner with clinics, diagnostic labs, and specialists where patients need them most.
            </p>
            <div className="space-y-3">
              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">Service / Specialty Needed</label>
                <Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Service name" className="text-sm" />
              </div>
              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">City / Locality</label>
                <Input value={selectedCity} onChange={(e) => setSelectedCity(e.target.value)} placeholder="e.g. Bengaluru, Indiranagar" className="text-sm" />
              </div>
              <div>
                <label className="text-xs font-semibold text-muted-foreground block mb-1">Phone or Email (Optional, for notifications)</label>
                <Input value={unmetContact} onChange={(e) => setUnmetContact(e.target.value)} placeholder="+91 9876543210" className="text-sm" />
              </div>
            </div>
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" size="sm" onClick={() => setUnmetModalOpen(false)}>Cancel</Button>
              <Button size="sm" disabled={unmetSubmitted} onClick={submitUnmetDemand}>
                {unmetSubmitted ? 'Submitted!' : 'Submit Request'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * File 22 P2-38: shared UI system — DataGrid, FilterBar, EntityPicker,
 * AlertBanner, BarcodeScanner, PdfViewer.
 * Every list page uses DataGrid; every detail page uses EntityPicker;
 * alerts route through AlertBanner; scanning uses BarcodeScanner;
 * PDF previews use PdfViewer. One component set, every surface.
 */
import { Fragment, useCallback, useEffect, useId, useMemo, useRef, useState } from 'react';
import {
  flexRender, getCoreRowModel, getFilteredRowModel, getPaginationRowModel,
  getSortedRowModel, useReactTable,
} from '@tanstack/react-table';
import { observeElementRect, useVirtualizer } from '@tanstack/react-virtual';
import { X, ChevronLeft, ChevronRight, Search, AlertTriangle, Camera, Loader2 } from 'lucide-react';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

/* ─── AlertBanner ────────────────────────────────────────────────────────── */
export function AlertBanner({ alerts = [], onAck, onSnooze }: Unmodelled) {
  if (!alerts.length) return null;
  return (
    <div className="space-y-1.5" role="alert">
      {alerts.filter((a: Unmodelled) => a.status === 'open').slice(0, 5).map((a: Unmodelled) => (
        <div key={a._id} className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-sm ${
          a.severity === 'critical' ? 'border-red-300 bg-red-50 text-red-900'
          : a.severity === 'warning' ? 'border-amber-300 bg-amber-50 text-amber-900'
          : 'border-sky-300 bg-sky-50 text-sky-900'
        }`}>
          {a.severity === 'critical' ? <AlertTriangle size={15} /> : null}
          <span className="flex-1 truncate">{a.message}</span>
          <button onClick={() => onAck?.(a._id)} className="rounded bg-white/70 px-2 py-0.5 text-xs font-semibold hover:bg-white">Ack</button>
          {onSnooze ? <button onClick={() => onSnooze?.(a._id)} className="rounded bg-white/70 px-2 py-0.5 text-xs hover:bg-white">Snooze 1h</button> : null}
        </div>
      ))}
    </div>
  );
}

/* ─── DataGrid ───────────────────────────────────────────────────────────── */
/**
 * File 22 P2-38: TanStack Table v8 owns the MODELS (filter / sort / paginate /
 * row identity) and TanStack Virtual owns the RENDER WINDOW. The public API
 * stays `{ columns: [{key,label,sortable,render}], rows, rowKey, onRowClick }`
 * so every call site keeps working — the checklist called for TanStack Table
 * + Virtual and a hand-rolled equivalent does not buy the same guarantees.
 *
 * Above `virtualizeThreshold` rows the pager is replaced by a scroller: only
 * the visible window plus overscan is in the DOM, so a 50k-row audit log does
 * not cost 50k <tr>s. Below the threshold behaviour is the classic paged grid
 * (jsdom cannot measure a scroller, so small grids are what CI exercises).
 */
const ROW_HEIGHT = 36;
// Matches the inline height on the scroller below. Used as the measurement
// floor when a layout engine reports 0 (jsdom).
const SCROLLER_HEIGHT = 480;

/**
 * Nulls always sort LAST, in both directions.
 *
 * TanStack negates the comparator result for descending sorts, so returning a
 * plain "null is greater" would flip nulls to the TOP on the second click.
 * `sortUndefined` cannot help either — it only tests `=== undefined`, and
 * Mongo/API rows carry `null`. So the comparator closes over the direction.
 */
const nullsLastComparator = (desc: Unmodelled) => (rowA: Unmodelled, rowB: Unmodelled, columnId: Unmodelled) => {
  const a = rowA.getValue(columnId);
  const b = rowB.getValue(columnId);
  if (a == null && b == null) return 0;
  if (a == null) return desc ? -1 : 1;
  if (b == null) return desc ? 1 : -1;
  return a > b ? 1 : a < b ? -1 : 0;
};

/**
 * jsdom reports a 0-height rect for every element, so TanStack Virtual would
 * cache size 0 for each measured row, collapse the scroll height and unmount
 * the very rows it needs to measure — a feedback loop to an empty table. Real
 * browsers take the ResizeObserver/rect value; the estimate is the fallback
 * only when measurement genuinely returned nothing.
 */
const measureElementOrDefault = (element: Unmodelled, entry: Unmodelled) => {
  const fromEntry = entry?.borderBoxSize?.[0]?.blockSize;
  const fromRect = element?.getBoundingClientRect?.().height;
  return Math.round(fromEntry || fromRect) || ROW_HEIGHT;
};

/**
 * jsdom has no layout engine, so it reports 0x0 for the scroller. TanStack
 * then computes `outerSize === 0`, `calculateRange` returns null and NO rows
 * render — a 5000-row grid becomes an empty table in tests while working fine
 * in a browser. Flooring the measurement at the declared height keeps the
 * virtualiser honest in both environments.
 */
const observeElementRectWithFloor = (instance: Unmodelled, cb: Unmodelled) => {
  observeElementRect(instance, (rect) => {
    cb({ width: rect.width || 800, height: rect.height || SCROLLER_HEIGHT });
  });
};

export function DataGrid({
  columns = [],
  rows,
  rowKey,
  onRowClick,
  empty = 'No records',
  pageSize = 20,
  virtualizeThreshold = 100,
  /**
   * Most list pages already own their search box (it hits the API with a
   * `search` param so the server can index). Rendering a SECOND filter on top
   * would be confusing, so those callers hide this one.
   */
  showSearch = true,
  /**
   * For server-paginated lists: the caller owns the page window, so the grid
   * must not paginate again on top of it. Renders every row it is handed and
   * suppresses the pager; virtualisation still applies past the threshold.
   */
  manualPagination = false,
  /**
   * Per-row tinting some lists need (flagged users, low stock, expiring…).
   * Receives the original row object, returns extra class names.
   */
  rowClassName,
  /**
   * Columns whose values are sensitive (PHI/PII) and should be masked by
   * default with a per-cell reveal toggle. Pass an array of column keys.
   */
  maskedColumns,
  /**
   * Master-detail lists (e.g. a hospital row that expands to its doctors).
   * When `expandedRowKey` matches a row's `rowKey` value, an extra full-width
   * row renders underneath with this content. Virtualised grids skip it — a
   * measured detail row would desync the virtual offsets.
   */
  expandedRowKey,
  renderDetail,
}: Unmodelled) {
  const [globalFilter, setGlobalFilter] = useState('');
  const [revealedCells, setRevealedCells] = useState<Set<string>>(new Set());
  const [sorting, setSorting] = useState<Unmodelled[]>([]);
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize });
  const parentRef = useRef<Unmodelled>(null);

  // Keep the pager's pageSize in sync when the prop changes.
  useEffect(() => {
    setPagination(p => (p.pageSize === pageSize ? p : { ...p, pageSize, pageIndex: 0 }));
  }, [pageSize]);

  const tanstackColumns = useMemo(() => columns.map((c: Unmodelled) => ({
    id: c.key,
    accessorFn: (row: Unmodelled) => row[c.key],
    header: c.label,
    enableSorting: c.sortable !== false,
    sortingFn: nullsLastComparator(sorting.some(s => s.id === c.key && s.desc)),
    cell: (info: Unmodelled) => (c.render ? c.render(info.getValue(), info.row.original) : String(info.getValue() ?? '')),
  })), [columns, sorting]);

  // Search spans every declared column, exactly like the hand-rolled filter did.
  const globalFilterFn = useCallback((row: Unmodelled, _columnId: Unmodelled, filterValue: Unmodelled) => {
    const needle = String(filterValue ?? '').trim().toLowerCase();
    if (!needle) return true;
    return columns.some((c: Unmodelled) => String(row.getValue(c.key) ?? '').toLowerCase().includes(needle));
  }, [columns]);

  const table = useReactTable({
    data: useMemo(() => rows || [], [rows]),
    columns: tanstackColumns,
    state: { globalFilter, sorting, pagination },
    onGlobalFilterChange: setGlobalFilter,
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    // The index is part of the id on purpose: a list where the business key is
    // missing (new unsaved row) or repeated (two lines with the same UHID)
    // would otherwise hand TanStack duplicate row ids, and React then keys two
    // <tr>s identically — rendering the row twice and breaking sort order.
    // The index is the SOURCE index, so it stays stable across sorts.
    getRowId: (row: Unmodelled, index) => `${rowKey != null && (row as Unmodelled)?.[rowKey] != null ? String(row[rowKey]) : 'row'}-${index}`,
    globalFilterFn,
    // TanStack's auto sort dir is DESC for numeric columns. Every other list in
    // this product starts with the first click = ascending, so pin it.
    sortDescFirst: false,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    // The caller owns the page window when manualPagination is on, so installing
    // the pagination model would silently re-page a slice that is already one page.
    ...(manualPagination ? {} : { getPaginationRowModel: getPaginationRowModel() }),
  });

  const filteredCount = table.getFilteredRowModel().rows.length;
  const virtualize = filteredCount > virtualizeThreshold;
  // getFilteredRowModel applies the SEARCH ONLY — it does not sort. The sorted
  // model is what builds on it, and getRowModel() is that plus the pager. Any
  // mode that renders rows itself must take the sorted model, or clicking a
  // header silently does nothing.
  // A virtual scroller IS the page (paging it double-counts); manualPagination
  // has the same shape (the caller already owns the window).
  const pageRows = (virtualize || manualPagination)
    ? table.getSortedRowModel().rows
    : table.getRowModel().rows;

  const rowVirtualizer = useVirtualizer({
    count: pageRows.length,
    estimateSize: () => ROW_HEIGHT,
    getScrollElement: () => parentRef.current,
    overscan: 10,
    measureElement: measureElementOrDefault,
    observeElementRect: observeElementRectWithFloor,
    // jsdom reports a zero-size scroller; without this the virtual list is
    // empty in tests and the component silently renders nothing.
    initialRect: { width: 800, height: SCROLLER_HEIGHT },
  });
  const virtualRows = virtualize ? rowVirtualizer.getVirtualItems() : [];

  const pages = Math.max(1, table.getPageCount());
  const pageIndex = table.getState().pagination.pageIndex;

  const sortLabel = (header: Unmodelled) => {
    const sorted = header.column.getIsSorted();
    if (sorted === 'asc') return 'ascending';
    if (sorted === 'desc') return 'descending';
    return header.column.getCanSort() ? 'none' : undefined;
  };

  const renderRow = (row: Unmodelled, virtualIndex: Unmodelled) => {
    const r = row.original;
    const isExpanded = !virtualize && renderDetail && expandedRowKey != null
      && rowKey != null && r?.[rowKey] === expandedRowKey;
    const mainRow = (
      <tr
        key={row.id}
        data-index={virtualIndex}
        // ARIA requires the ABSOLUTE row number when a table is virtualised,
        // or a screen reader believes a 50k-row grid has 20 rows.
        aria-rowindex={virtualize ? virtualIndex + 2 : undefined}
        ref={virtualize ? (node) => { if (node) rowVirtualizer.measureElement(node); } : undefined}
        style={virtualize ? { transform: `translateY(${virtualRows[virtualIndex]?.start ?? 0}px)`, position: 'absolute', left: 0, right: 0 } : undefined}
        onClick={onRowClick ? () => onRowClick(r) : undefined}
        className={[onRowClick ? 'cursor-pointer hover:bg-muted/30 transition-colors' : '', rowClassName ? rowClassName(r) : ''].filter(Boolean).join(' ') || undefined}
      >
        {columns.map((c: Unmodelled) => {
          const isMasked = Array.isArray(maskedColumns) && maskedColumns.includes(c.key);
          const cellKey = `${row.id}-${c.key}`;
          const revealed = revealedCells.has(cellKey);
          const value = c.render ? c.render(r[c.key], r) : String(r[c.key] ?? '');
          return (
            <td key={c.key} className="px-3 py-2 text-sm">
              {isMasked ? (
                <span className="inline-flex items-center gap-1.5">
                  <span className={revealed ? '' : 'blur-sm select-none'}>{value}</span>
                  <button
                    type="button"
                    className="text-xs text-muted-foreground hover:text-foreground"
                    aria-label={revealed ? 'Hide value' : 'Reveal value'}
                    onClick={(e) => {
                      e.stopPropagation();
                      setRevealedCells((prev) => {
                        const next = new Set(prev);
                        if (next.has(cellKey)) next.delete(cellKey); else next.add(cellKey);
                        return next;
                      });
                    }}
                  >
                    {revealed ? 'Hide' : 'Show'}
                  </button>
                </span>
              ) : value}
            </td>
          );
        })}
      </tr>
    );
    if (!isExpanded) return mainRow;
    return (
      <Fragment key={`${row.id}-detail`}>
        {mainRow}
        <tr className="bg-muted/20">
          <td colSpan={columns.length} className="px-3 py-2 text-sm">
            {renderDetail(r)}
          </td>
        </tr>
      </Fragment>
    );
  };

  const body = () => {
    if (virtualize) {
      return (
        <>
          {virtualRows.map((vr) => renderRow(pageRows[vr.index], vr.index))}
        </>
      );
    }
    if (pageRows.length === 0) {
      return (
        <tr><td colSpan={columns.length} className="px-3 py-8 text-center text-sm text-muted-foreground">{empty}</td></tr>
      );
    }
    return pageRows.map((row, i) => renderRow(row, i));
  };

  return (
    <div className="space-y-2">
      {showSearch ? (
        <div className="relative max-w-xs">
          <Search className="absolute left-2.5 top-2 text-muted-foreground" size={14} />
          <input
            className="h-9 w-full rounded-md border pl-8 pr-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
            placeholder="Filter rows…"
            value={globalFilter}
            onChange={(e) => { setGlobalFilter(e.target.value); table.setPageIndex(0); }}
            aria-label="Filter table rows"
          />
        </div>
      ) : null}
      <div
        ref={virtualize ? parentRef : undefined}
        className={`rounded-lg border ${virtualize ? 'overflow-auto' : 'overflow-x-auto'}`}
        style={virtualize ? { height: SCROLLER_HEIGHT } : undefined}
      >
        <table className="w-full" aria-rowcount={virtualize ? filteredCount + 1 : undefined}>
          <thead className="bg-muted/40 border-b">
            <tr>
              {table.getHeaderGroups()[0].headers.map((header) => (
                <th
                  key={header.id}
                  scope="col"
                  aria-sort={sortLabel(header)}
                  className="px-3 py-2 text-left text-xs font-semibold uppercase tracking-wide text-muted-foreground"
                >
                  {header.isPlaceholder ? null : (
                    <button
                      type="button"
                      className="inline-flex items-center gap-1 rounded focus:outline-none focus:ring-2 focus:ring-ring disabled:opacity-50"
                      disabled={!header.column.getCanSort()}
                      onClick={header.column.getToggleSortingHandler()}
                    >
                      {flexRender(header.column.columnDef.header, header.getContext())}
                      {header.column.getIsSorted() === 'asc' ? <span aria-hidden="true">▲</span> : null}
                      {header.column.getIsSorted() === 'desc' ? <span aria-hidden="true">▼</span> : null}
                    </button>
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y" style={virtualize ? { height: rowVirtualizer.getTotalSize(), position: 'relative' } : undefined}>
            {body()}
          </tbody>
        </table>
      </div>
      <div className="flex items-center justify-between text-xs text-muted-foreground">
        {virtualize ? (
          <span>{filteredCount} rows · virtualised</span>
        ) : manualPagination ? (
          // The caller is already showing "page 3 of 12"; a second pager here
          // would page the slice it handed us a second time.
          <span>{filteredCount} rows</span>
        ) : (
          <>
            <span>{filteredCount} rows · page {pageIndex + 1}/{pages}</span>
            <div className="flex gap-1">
              <button
                type="button"
                aria-label="Previous page"
                className="rounded border px-2 py-1 disabled:opacity-40"
                disabled={!table.getCanPreviousPage()}
                onClick={() => table.previousPage()}
              >
                <ChevronLeft size={13} aria-hidden="true" />
              </button>
              <button
                type="button"
                aria-label="Next page"
                className="rounded border px-2 py-1 disabled:opacity-40"
                disabled={!table.getCanNextPage()}
                onClick={() => table.nextPage()}
              >
                <ChevronRight size={13} aria-hidden="true" />
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

/* ─── FilterBar ──────────────────────────────────────────────────────────── */
export function FilterBar({ filters = [], value = {}, onChange }: Unmodelled) {
  const set = (key: Unmodelled, val: Unmodelled) => onChange({ ...value, [key]: val });
  return (
    <div className="flex flex-wrap gap-2">
      {filters.map((f: Unmodelled) => {
        if (f.type === 'select') {
          return (
            <select
              key={f.key}
              className="h-9 rounded-md border px-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              value={value[f.key] || ''}
              onChange={e => set(f.key, e.target.value || undefined)}
              aria-label={f.label}
            >
              <option value="">{f.label}: all</option>
              {f.options.map((o: Unmodelled) => <option key={o} value={o}>{o}</option>)}
            </select>
          );
        }
        return (
          <input
            key={f.key}
            type={f.type || 'text'}
            className="h-9 w-40 rounded-md border px-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
            // A placeholder disappears the moment someone types, so it is not a
            // label: name the control explicitly for screen readers.
            aria-label={f.label}
            placeholder={f.label}
            value={value[f.key] || ''}
            onChange={e => set(f.key, e.target.value)}
          />
        );
      })}
      {Object.keys(value).length > 0 && (
        <button
          className="h-9 rounded-md border px-3 text-sm text-muted-foreground hover:text-foreground"
          onClick={() => onChange({})}
        >
          Clear filters
        </button>
      )}
    </div>
  );
}

/* ─── EntityPicker ───────────────────────────────────────────────────────── */
export function EntityPicker({ label, search, onSelect, renderOption, placeholder = 'Type to search…', debounceMs = 250 }: Unmodelled) {
  const [q, setQ] = useState('');
  const [options, setOptions] = useState<ApiRow[]>([]);
  const [open, setOpen] = useState(false);
  const boxRef: Unmodelled = useRef<Unmodelled>(null);
  const inputId = useId();

  useEffect(() => {
    if (!q.trim()) { setOptions([]); return; }
    const t = setTimeout(async () => {
      try { setOptions(await search(q)); } catch { setOptions([]); }
    }, debounceMs);
    return () => clearTimeout(t);
  }, [q]);

  useEffect(() => {
    const onDoc = (e: Unmodelled) => { if (boxRef.current && !boxRef.current.contains(e.target)) setOpen(false); };
    document.addEventListener('click', onDoc);
    return () => document.removeEventListener('click', onDoc);
  }, []);

  return (
    <div ref={boxRef} className="relative">
      <label htmlFor={inputId} className="mb-1 block text-xs font-medium text-muted-foreground">{label}</label>
      <input
        id={inputId}
        className="h-10 w-full rounded-md border px-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
        placeholder={placeholder}
        value={q}
        onChange={e => { setQ(e.target.value); setOpen(true); }}
        onFocus={() => setOpen(true)}
      />
      {open && options.length > 0 && (
        <div className="absolute z-50 mt-1 max-h-52 w-full overflow-auto rounded-md border bg-card shadow-lg">
          {options.map((o, i) => (
            <button
              key={o.id || i}
              className="flex w-full items-center justify-between px-3 py-2 text-left text-sm hover:bg-muted"
              onClick={() => { onSelect(o); setQ(o.name || o.label || ''); setOpen(false); }}
            >
              {renderOption ? renderOption(o) : <span>{o.name || o.label || String(o)}</span>}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* ─── BarcodeScanner ─────────────────────────────────────────────────────── */
export function BarcodeScanner({ onScan, label = 'Scan code' }: Unmodelled) {
  const [manual, setManual] = useState('');
  const inputId = useId();
  return (
    <div className="flex flex-wrap items-end gap-2 rounded-lg border p-3">
      <div className="flex-1 min-w-40">
        <label htmlFor={inputId} className="mb-1 block text-xs font-medium text-muted-foreground">{label}</label>
        <div className="flex items-center gap-2">
          <input
            id={inputId}
            className="h-10 flex-1 rounded-md border px-3 font-mono text-sm focus:outline-none focus:ring-2 focus:ring-ring"
            placeholder="scan or type code…"
            value={manual}
            onChange={e => setManual(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter' && manual.trim()) { onScan(manual.trim()); setManual(''); } }}
          />
          <Camera className="text-muted-foreground" size={18} />
        </div>
      </div>
    </div>
  );
}

/* ─── PdfViewer (embed) ──────────────────────────────────────────────────── */
export function PdfViewer({ src, height = 520 }: Unmodelled) {
  if (!src) return <p className="py-8 text-center text-sm text-muted-foreground">No document selected.</p>;
  return (
    <iframe
      title="PDF preview"
      src={src}
      className="w-full rounded-lg border"
      style={{ height }}
    />
  );
}

/* ��� MapPinCard ��������������������������������������������������������� */
export function MapPinCard({ title, address, lat, lng, onDirections }: Unmodelled) {
  return (
    <div className="rounded-lg border bg-card p-3">
      <div className="text-sm font-semibold">{title}</div>
      {address ? <div className="text-xs text-muted-foreground mt-0.5">{address}</div> : null}
      {lat != null && lng != null ? (
        <div className="mt-2 text-xs text-muted-foreground">Pin: {Number(lat).toFixed(5)}, {Number(lng).toFixed(5)}</div>
      ) : null}
      {onDirections ? (
        <button
          type="button"
          className="mt-2 rounded-md border px-3 py-1 text-xs font-medium hover:bg-muted"
          onClick={() => onDirections(lat, lng)}
        >
          Get directions
        </button>
      ) : null}
    </div>
  );
}

/* ��� ConsentToggle �������������������������������������������������������� */
export function ConsentToggle({ label, checked, onChange, description, disabled }: Unmodelled) {
  return (
    <label className={`flex items-start gap-3 ${disabled ? 'opacity-60' : ''}`}>
      <input
        type="checkbox"
        className="mt-1 h-4 w-4 rounded border"
        checked={!!checked}
        disabled={disabled}
        onChange={e => onChange?.(e.target.checked)}
      />
      <span className="text-sm">
        <span className="font-medium">{label}</span>
        {description ? <span className="block text-xs text-muted-foreground">{description}</span> : null}
      </span>
    </label>
  );
}

/* ��� DiscreetBanner ������������������������������������������������������ */
export function DiscreetBanner({ message, onDismiss }: Unmodelled) {
  return (
