/**
 * Map UI primitives built on maplibre-gl.
 *
 * Ported from client/src/components/ui/map.jsx.
 *
 * Exports: Map, MapControls, MapMarker, MapPopup, MapRoute,
 *          MarkerContent, MarkerTooltip, MarkerLabel, MarkerPopup, useMap
 */
import * as React from 'react';
import { createRoot } from 'react-dom/client';
import type { Feature, LineString } from 'geojson';
import * as maplibregl from 'maplibre-gl';
import { Compass, LocateFixed, Maximize2, Minimize2, Minus, Plus } from 'lucide-react';
import type { MarkerSmoother } from '../../utils/markerInterpolation';
import { cn } from '@/lib/utils';

const MapContext = React.createContext<MapContextValue | null>(null);

const DEFAULT_CENTER: [number, number] = [77.209, 28.6139];

function finiteNumber(value: unknown, fallback: number): number {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function normalizeLngLat(
  value: unknown,
  fallback: [number, number] | null = DEFAULT_CENTER,
): [number, number] | null {
  if (!value) return fallback;
  const pair = Array.isArray(value)
    ? value
    : [(value as Record<string, unknown>).longitude ?? (value as Record<string, unknown>).lng, (value as Record<string, unknown>).latitude ?? (value as Record<string, unknown>).lat];
  const lng = Number(pair[0]);
  const lat = Number(pair[1]);
  return Number.isFinite(lng) && Number.isFinite(lat) ? [lng, lat] : fallback;
}

function normalizeRouteCoordinates(coordinates: unknown[] = []): [number, number][] {
  return coordinates
    .map((point) => normalizeLngLat(point, null))
    .filter((c): c is [number, number] => c !== null);
}

interface MapContextValue {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  containerRef: React.RefObject<HTMLDivElement | null>;
}

export function useMap(): MapContextValue {
  const context = React.useContext(MapContext);
  if (!context) {
    throw new Error('useMap must be used inside a Map component');
  }
  return context;
}

// Base map style.
//
// OpenFreeMap "liberty" — a vector (not raster) style derived from the
// Mapbox-Streets look, which is why its road hierarchy reads the way
// ride/navigation apps expect: motorways thick and orange, arterials
// white and medium, residential thin but visible. No API key, no quota.
//
// Previously this was a hand-rolled raster style pointing at
// tile.openstreetmap.org, which is a low-contrast raster that makes the
// route line hard to pick out against the basemap.
//
// A remote style URL is a deliberate trade-off: MapLibre fetches this JSON
// (plus vector tiles + glyphs) from tiles.openfreemap.org at runtime, so
// that origin must be allowed by the backend CSP `connect-src` — see
// backend/src/index.js. The old inline style needed no such allowance.
const OPENFREEMAP_STYLE = 'https://tiles.openfreemap.org/styles/liberty';

// Last-resort style, used only when the primary style fails to load (network
// blocked, OpenFreeMap down, bad style JSON). It is a plain inline object with
// no remote style fetch, so the map still renders *something* instead of a
// blank canvas. Keep this independent of OPENFREEMAP_STYLE — pointing the
// recovery path at the same failing remote URL would defeat its purpose.
const FALLBACK_RASTER_STYLE: maplibregl.StyleSpecification = {
  version: 8,
  glyphs: 'https://demotiles.maplibre.org/font/{fontstack}/{range}.pbf',
  sources: {
    'osm-raster': {
      type: 'raster',
      tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
      tileSize: 256,
      minzoom: 0,
      maxzoom: 19,
      attribution: 'OpenStreetMap contributors',
    },
  },
  layers: [{ id: 'osm-raster-layer', type: 'raster', source: 'osm-raster' }],
} as const;

// Vite inlines `import.meta.env.VITE_*` at build time (typed via src/vite-env.d.ts).
// The old fallback also read `process.env.NEXT_PUBLIC_MAPTILER_API_KEY`, a leftover
// from the Next.js client this file was ported from: in the browser bundle `process`
// is undefined and `vite.config.js` defines `process.env` as `{}`, so that branch
// always evaluated to `undefined`. Dropped in favour of the single Vite-idiomatic
// read; `MAPTILER_KEY` stays optional so `maptilerBasicStyle` is null without a key
// and `getActiveStyle` falls back to the free OpenFreeMap Liberty vector style.
const MAPTILER_KEY: string | undefined = import.meta.env.VITE_MAPTILER_API_KEY;
const maptilerBasicStyle = MAPTILER_KEY
  ? {
      light: `https://api.maptiler.com/maps/streets-v2/style.json?key=${MAPTILER_KEY}`,
      dark: `https://api.maptiler.com/maps/streets-v2-dark/style.json?key=${MAPTILER_KEY}`,
    }
  : null;

type MapStyle = string | { light: string; dark: string };

function isStyleSpec(value: unknown): value is maplibregl.StyleSpecification {
  return (
    typeof value === 'object' &&
    value !== null &&
    'version' in value &&
    'layers' in value
  );
}

function getActiveStyle(styles?: MapStyle | null): string | maplibregl.StyleSpecification {
  const activeStyles = styles ?? maptilerBasicStyle ?? OPENFREEMAP_STYLE;
  if (typeof activeStyles === 'string') return activeStyles;
  if (isStyleSpec(activeStyles)) return activeStyles;
  const theme = document.documentElement.classList.contains('dark') ? 'dark' : 'light';
  return activeStyles[theme] ?? activeStyles.light ?? activeStyles.dark ?? FALLBACK_RASTER_STYLE;
}

export function Map({
  children,
  className,
  center = DEFAULT_CENTER,
  zoom = 13,
  styles,
  onViewportChange,
  onReady,
  ...options
}: React.PropsWithChildren<{
  className?: string;
  center?: [number, number];
  zoom?: number;
  styles?: MapStyle | null;
  onViewportChange?: (viewport: { center: [number, number]; zoom: number; bearing: number; pitch: number }) => void;
  onReady?: (map: maplibregl.Map) => void;
} & Record<string, unknown>>) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<maplibregl.Map | null>(null);
  const [mapInstance, setMapInstance] = React.useState<maplibregl.Map | null>(null);
  const [isLoaded, setIsLoaded] = React.useState(false);
  const [loadError, setLoadError] = React.useState('');
  const activeStyle = React.useMemo(() => getActiveStyle(styles), [styles]);

  React.useEffect(() => {
    if (!containerRef.current) return undefined;
    if (mapRef.current) return undefined;
    setIsLoaded(false);
    setLoadError('');

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: activeStyle as string | maplibregl.StyleSpecification,
      center: normalizeLngLat(center) ?? DEFAULT_CENTER,
      // Zoom must be part of the initial camera, not just the post-load
      // easeTo below: without it MapLibre's default zoom (0 = whole world)
      // renders first and the correction only runs after the remote style
      // finishes loading — so users see a world-view flash (and, if 'load'
      // is late or never fires, stay stuck at zoom 0 with no roads/labels).
      zoom: finiteNumber(zoom, 13),
      attributionControl: false,
      ...options,
    });

    map.addControl(new maplibregl.AttributionControl({ compact: true }), 'bottom-right');
    mapRef.current = map;
    setMapInstance(map);

    function handleLoad() {
      setIsLoaded(true);
      onReady?.(map);
    }

    let didFallback = false;
    function handleError() {
      if (!isLoaded && !didFallback && typeof activeStyle === 'string') {
        didFallback = true;
        map.setStyle(FALLBACK_RASTER_STYLE);
      }
      if (!isLoaded) setLoadError('Map is having trouble loading.');
    }

    map.once('load', handleLoad);
    map.on('error', handleError);

    let resizeObserver: ResizeObserver | undefined;
    if (typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(() => map.resize());
      resizeObserver.observe(containerRef.current);
    }

    return () => {
      resizeObserver?.disconnect();
      map.off('error', handleError);
      try {
        map.remove();
      } catch {
        /* map already removed */
      }
      mapRef.current = null;
      setMapInstance(null);
      setIsLoaded(false);
    };
  }, [activeStyle]); // eslint-disable-line react-hooks/exhaustive-deps -- map init must run once per style only; adding center/onReady/options/isLoaded would destroy and re-create the map instance (and its listeners) on every parent re-render

  React.useEffect(() => {
    if (!mapRef.current || !isLoaded) return;
    mapRef.current.setStyle(activeStyle as string | maplibregl.StyleSpecification);
  }, [activeStyle, isLoaded]);

  React.useEffect(() => {
    if (!mapRef.current || !isLoaded) return;
    mapRef.current.easeTo({
      center: normalizeLngLat(center) ?? DEFAULT_CENTER,
      zoom: finiteNumber(zoom, mapRef.current.getZoom()),
      duration: 700,
      essential: true,
    });
  }, [center?.[0], center?.[1], isLoaded, zoom]); // eslint-disable-line react-hooks/exhaustive-deps -- camera effect intentionally depends on derived center coordinates (not the center array identity) so a new-but-equal array from the parent does not retrigger easeTo and make the map jitter

  React.useEffect(() => {
    if (!mapRef.current || !onViewportChange) return undefined;
    const handleMove = () => {
      const c = mapRef.current!.getCenter();
      onViewportChange({
        center: [c.lng, c.lat],
        zoom: mapRef.current!.getZoom(),
        bearing: mapRef.current!.getBearing(),
        pitch: mapRef.current!.getPitch(),
      });
    };
    mapRef.current.on('move', handleMove);
    return () => {
      mapRef.current?.off('move', handleMove);
    };
  }, [onViewportChange]);

  const value = React.useMemo(
    () => ({ map: mapInstance, isLoaded, containerRef }),
    [isLoaded, mapInstance],
  );

  return (
    <MapContext.Provider value={value}>
      <div className={`relative h-full w-full overflow-hidden ${className || ''}`}>
        <div ref={containerRef} className="h-full w-full" />
        {loadError && !isLoaded && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/90 p-4 text-center text-sm font-bold text-muted-foreground backdrop-blur-sm">
            {loadError}
          </div>
        )}
        {isLoaded && children}
      </div>
    </MapContext.Provider>
  );
}

const controlPosition = {
  'top-left': 'left-3 top-3',
  'top-right': 'right-3 top-3',
  'bottom-left': 'bottom-8 left-3',
  'bottom-right': 'bottom-8 right-3',
};

interface ControlButtonProps {
  title: string;
  children: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
}

function ControlButton({ title, children, onClick, disabled }: ControlButtonProps) {
  return (
    <button
      type="button"
      title={title}
      aria-label={title}
      disabled={disabled}
      onClick={onClick}
      className="flex h-9 w-9 items-center justify-center border-b border-border/70 bg-card text-foreground shadow-sm transition-colors last:border-b-0 hover:bg-accent disabled:pointer-events-none disabled:opacity-50"
    >
      {children}
    </button>
  );
}

interface MapControlsProps {
  position?: keyof typeof controlPosition;
  showZoom?: boolean;
  showCompass?: boolean;
  showLocate?: boolean;
  showFullscreen?: boolean;
  className?: string;
  onLocate?: (coords: { longitude: number; latitude: number; accuracy: number }) => void;
  children?: React.ReactNode;
}

export function MapControls({
  position = 'bottom-right',
  showZoom = true,
  showCompass = false,
  showLocate = false,
  showFullscreen = false,
  className,
  onLocate,
  children,
}: MapControlsProps) {
  const { map, isLoaded, containerRef } = useMap();
  const [isFullscreen, setIsFullscreen] = React.useState(false);

  React.useEffect(() => {
    const handleFullscreen = () => {
      setIsFullscreen(document.fullscreenElement === containerRef.current);
      setTimeout(() => map?.resize(), 80);
    };
    document.addEventListener('fullscreenchange', handleFullscreen);
    return () => document.removeEventListener('fullscreenchange', handleFullscreen);
  }, [containerRef, map]);

  const locate = () => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition((position) => {
      const coords = {
        longitude: position.coords.longitude,
        latitude: position.coords.latitude,
        accuracy: position.coords.accuracy,
      };
      map?.flyTo({ center: [coords.longitude, coords.latitude], zoom: Math.max(map!.getZoom(), 13) });
      onLocate?.(coords);
    });
  };

  const toggleFullscreen = async () => {
    if (!containerRef.current) return;
    if (document.fullscreenElement) {
      await document.exitFullscreen?.();
    } else {
      await containerRef.current.requestFullscreen?.();
    }
  };

  return (
    <div
      className={cn(
        'absolute z-30 overflow-hidden rounded-lg border border-border/70 bg-card/95 shadow-lg backdrop-blur',
        controlPosition[position],
        className,
      )}
    >
      {showZoom && (
        <>
          <ControlButton title="Zoom in" disabled={!isLoaded} onClick={() => map?.zoomIn()}>
            <Plus className="h-4 w-4" />
          </ControlButton>
          <ControlButton title="Zoom out" disabled={!isLoaded} onClick={() => map?.zoomOut()}>
            <Minus className="h-4 w-4" />
          </ControlButton>
        </>
      )}
      {showCompass && (
        <ControlButton title="Reset bearing" disabled={!isLoaded} onClick={() => map?.resetNorthPitch()}>
          <Compass className="h-4 w-4" />
        </ControlButton>
      )}
      {showLocate && (
        <ControlButton title="Current location" disabled={!isLoaded} onClick={locate}>
          <LocateFixed className="h-4 w-4" />
        </ControlButton>
      )}
      {showFullscreen && (
        <ControlButton title="Full map" disabled={!isLoaded} onClick={toggleFullscreen}>
          {isFullscreen ? <Minimize2 className="h-4 w-4" /> : <Maximize2 className="h-4 w-4" />}
        </ControlButton>
      )}
      {children}
    </div>
  );
}

interface MapMarkerProps {
  longitude?: number;
  latitude?: number;
  coordinates?: [number, number];
  bearing?: number;
  smoothGlide?: boolean;
  children?: React.ReactNode;
  draggable?: boolean;
  onClick?: (e: maplibregl.MapMouseEvent) => void;
  onMouseEnter?: (e: maplibregl.MapMouseEvent) => void;
  onMouseLeave?: (e: maplibregl.MapMouseEvent) => void;
  onDragStart?: (lngLat: maplibregl.LngLat) => void;
  onDrag?: (lngLat: maplibregl.LngLat) => void;
  onDragEnd?: (lngLat: maplibregl.LngLat) => void;
}

export function MapMarker({
  longitude,
  latitude,
  coordinates,
  bearing = 0,
  smoothGlide = false,
  children,
  draggable = false,
  onClick,
  onMouseEnter,
  onMouseLeave,
  onDragStart,
  onDrag,
  onDragEnd,
  ...markerOptions
}: MapMarkerProps) {
  const { map, isLoaded } = useMap();
  const elementRef = React.useRef<HTMLDivElement | null>(null);
  const markerRef = React.useRef<maplibregl.Marker | null>(null);
  const smootherRef = React.useRef<MarkerSmoother | null>(null);
  const rootRef = React.useRef<ReturnType<typeof createRoot> | null>(null);
  const markerPosition = coordinates ? normalizeLngLat(coordinates, null) : normalizeLngLat([longitude, latitude], null);

  React.useEffect(() => {
    if (elementRef.current || typeof document === 'undefined') return;
    elementRef.current = document.createElement('div');
    elementRef.current.className = 'mapcn-marker group cursor-pointer';
  }, []);

  React.useEffect(() => {
    if (!map || !isLoaded || !elementRef.current || !markerPosition) return undefined;

    const marker = new maplibregl.Marker({
      element: elementRef.current,
      draggable,
      ...(markerOptions as object),
    })
      .setLngLat(markerPosition)
      .addTo(map);

    markerRef.current = marker;

    const emitDragStart = () => onDragStart?.(marker.getLngLat());
    const emitDrag = () => onDrag?.(marker.getLngLat());
    const emitDragEnd = () => onDragEnd?.(marker.getLngLat());
    marker.on('dragstart', emitDragStart);
    marker.on('drag', emitDrag);
    marker.on('dragend', emitDragEnd);

    return () => {
      marker.off('dragstart', emitDragStart);
      marker.off('drag', emitDrag);
      marker.off('dragend', emitDragEnd);
      marker.remove();
      markerRef.current = null;
    };
  }, [map, isLoaded, draggable, markerPosition?.[0], markerPosition?.[1], onDragStart, onDrag, onDragEnd, markerOptions]); // eslint-disable-line react-hooks/exhaustive-deps -- marker creation intentionally depends on derived markerPosition coordinates (not the array identity) so parent re-renders do not destroy/recreate the marker

  React.useEffect(() => {
    if (!markerPosition || !markerRef.current) return;

    if (smoothGlide) {
      if (!smootherRef.current) {
        import('../../utils/markerInterpolation').then(({ MarkerSmoother }) => {
          smootherRef.current = new MarkerSmoother(
            { lat: markerPosition?.[1] ?? 0, lng: markerPosition?.[0] ?? 0, bearing },
            ([lng, lat], rot) => {
              markerRef.current?.setLngLat([lng, lat]);
              if (rot != null && elementRef.current) {
                elementRef.current.style.transform += ` rotate(${rot}deg)`;
              }
            }
          );
        });
      } else {
        smootherRef.current.setNextTarget({ lat: markerPosition?.[1] ?? 0, lng: markerPosition?.[0] ?? 0, bearing }, 1200);
      }
    } else {
      markerRef.current.setLngLat(markerPosition);
    }
  }, [markerPosition?.[0], markerPosition?.[1], bearing, smoothGlide]); // eslint-disable-line react-hooks/exhaustive-deps -- glide effect intentionally depends on the derived markerPosition coordinates (not the array identity) so an equal-but-new array from the parent does not restart the smoother; latitude/longitude are the same values markerPosition is derived from

  React.useEffect(() => {
    if (!elementRef.current) return undefined;
    const element = elementRef.current;
    const handleClick = (event: MouseEvent) => {
      event.stopPropagation();
      onClick?.(event as unknown as maplibregl.MapMouseEvent);
    };
    const handleEnter = (event: MouseEvent) => onMouseEnter?.(event as unknown as maplibregl.MapMouseEvent);
    const handleLeave = (event: MouseEvent) => onMouseLeave?.(event as unknown as maplibregl.MapMouseEvent);
    element.addEventListener('click', handleClick);
    element.addEventListener('mouseenter', handleEnter);
    element.addEventListener('mouseleave', handleLeave);
    return () => {
      element.removeEventListener('click', handleClick);
      element.removeEventListener('mouseenter', handleEnter);
      element.removeEventListener('mouseleave', handleLeave);
    };
  }, [onClick, onMouseEnter, onMouseLeave]);

  React.useEffect(() => {
    if (!elementRef.current) return undefined;
    if (!rootRef.current) rootRef.current = createRoot(elementRef.current);
    rootRef.current.render(children);
    return undefined;
  }, [children]);

  React.useEffect(
    () => () => {
      setTimeout(() => rootRef.current?.unmount(), 0);
    },
    [],
  );

  return null;
}

