import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Wallet, Banknote, CheckCircle2, ShieldCheck, Loader2, IndianRupee, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import { toast } from 'sonner';

interface DemoPaymentSheetProps {
  rideId: string;
  amount: number;
  onPaymentComplete: (payment: any) => void;
}

export default function DemoPaymentSheet({
  rideId,
  amount,
  onPaymentComplete,
}: DemoPaymentSheetProps) {
  const [loadingMethod, setLoadingMethod] = useState<string | null>(null);
  const [successData, setSuccessData] = useState<{ transactionRef: string; method: string } | null>(null);

  const handlePay = async (method: 'demo_wallet' | 'cash') => {
    setLoadingMethod(method);
    try {
      const res = await api.payDemoRide({ rideId, method });
      setSuccessData({
        transactionRef: res.transactionRef || `DEMO-TXN-${Math.floor(100000 + Math.random() * 900000)}`,
        method,
      });
      toast.success(res.message || 'Payment completed successfully (Demo Mode)');
      setTimeout(() => {
        onPaymentComplete(res.payment || { status: 'paid', method });
      }, 1600);
    } catch (err: any) {
      toast.error(err.message || 'Payment processing failed');
    } finally {
      setLoadingMethod(null);
    }
  };

  return (
    <div className="rounded-2xl border border-border/80 bg-card p-5 shadow-lg space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-bold text-lg text-foreground">Ride Completed</h3>
          <p className="text-xs text-muted-foreground">Select payment method to settle fare</p>
        </div>
        <Badge variant="destructive" className="bg-amber-600 hover:bg-amber-600 text-white font-bold text-[10px] tracking-wider uppercase px-2 py-0.5 shadow-sm">
          Demo Mode
        </Badge>
      </div>

      <div className="rounded-xl bg-primary/5 border border-primary/20 p-4 text-center">
        <p className="text-xs text-muted-foreground font-medium">Total Fare Amount</p>
        <div className="flex items-center justify-center gap-0.5 text-3xl font-extrabold text-foreground mt-1">
          <span>₹</span>
          <span>{amount}</span>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {successData ? (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="rounded-xl bg-emerald-500/10 border border-emerald-500/30 p-4 text-center space-y-2"
          >
            <CheckCircle2 className="w-10 h-10 text-emerald-600 mx-auto" />
            <h4 className="font-bold text-foreground text-sm">Payment Successful!</h4>
            <p className="text-xs text-muted-foreground font-mono">
              Ref: {successData.transactionRef}
            </p>
            <p className="text-[11px] text-emerald-700 dark:text-emerald-400 font-medium">
              Receipt verified. Redirecting to rating...
            </p>
          </motion.div>
        ) : (
          <div className="space-y-2.5">
            {/* Wallet Option */}
            <Button
              type="button"
              onClick={() => handlePay('demo_wallet')}
              disabled={!!loadingMethod}
              className="w-full h-13 justify-start gap-3.5 rounded-xl border border-primary/20 bg-primary/10 hover:bg-primary/20 text-primary font-semibold"
            >
              <div className="w-8 h-8 rounded-lg bg-primary text-primary-foreground flex items-center justify-center shrink-0 shadow-sm">
                {loadingMethod === 'demo_wallet' ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Wallet className="w-4 h-4" />
                )}
              </div>
              <div className="text-left flex-1">
                <p className="text-xs font-bold leading-tight">Pay with Demo Wallet</p>
                <p className="text-[10px] opacity-80">Simulated instant digital wallet deduction</p>
              </div>
            </Button>

            {/* Cash Option */}
            <Button
              type="button"
              variant="outline"
              onClick={() => handlePay('cash')}
              disabled={!!loadingMethod}
              className="w-full h-13 justify-start gap-3.5 rounded-xl border-border/80 hover:bg-muted font-semibold"
            >
              <div className="w-8 h-8 rounded-lg bg-muted flex items-center justify-center shrink-0 border">
                {loadingMethod === 'cash' ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Banknote className="w-4 h-4 text-foreground" />
                )}
              </div>
              <div className="text-left flex-1">
                <p className="text-xs font-bold leading-tight text-foreground">Cash (Mark as Paid)</p>
                <p className="text-[10px] text-muted-foreground">Handover physical cash directly to driver</p>
              </div>
            </Button>

            <div className="flex items-center justify-center gap-1.5 pt-1 text-[11px] text-muted-foreground">
              <ShieldCheck className="w-3.5 h-3.5 text-primary" />
              <span>Simulated payment test environment — No real money transferred</span>
            </div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { MapPin, LocateFixed, Loader2, X, Search } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';

export interface LocationPoint {
  address: string;
  lat: number;
  lng: number;
}

interface LocationInputProps {
  label: string;
  placeholder?: string;
  value: LocationPoint | null;
  onChange: (point: LocationPoint | null) => void;
  showCurrentLocationButton?: boolean;
  pinColor?: string;
}

export default function LocationInput({
  label,
  placeholder = 'Enter landmark or address',
  value,
  onChange,
  showCurrentLocationButton = false,
  pinColor = 'text-primary',
}: LocationInputProps) {
  const [query, setQuery] = useState(value?.address || '');
  const [loadingLoc, setLoadingLoc] = useState(false);
  const [suggestions, setSuggestions] = useState<LocationPoint[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const debounceRef = useRef<any>(null);

  useEffect(() => {
    setQuery(value?.address || '');
  }, [value?.address]);

  // Common landmarks for quick fallback autocompletion
  const POPULAR_LOCATIONS: LocationPoint[] = [
    { address: 'City Central Hospital, Wright Town, Jabalpur', lat: 23.1685, lng: 79.9339 },
    { address: 'Medical College & Hospital, Garha, Jabalpur', lat: 23.1492, lng: 79.8837 },
    { address: 'Victoria District Hospital, Omti, Jabalpur', lat: 23.1722, lng: 79.9405 },
    { address: 'Railway Station Platform 1, Jabalpur', lat: 23.1601, lng: 79.9572 },
    { address: 'Dumna Airport Terminal, Jabalpur', lat: 23.1784, lng: 80.0526 },
    { address: 'Civic Centre Market, Marhatal, Jabalpur', lat: 23.1678, lng: 79.9328 },
    { address: 'Bhedaghat Dhuandhar Fall Rd, Jabalpur', lat: 23.1311, lng: 79.8005 },
  ];

  const handleSearch = (text: string) => {
    setQuery(text);
    if (!text.trim()) {
      setSuggestions([]);
      setShowSuggestions(false);
      onChange(null);
      return;
    }

    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(async () => {
      // 1. Local landmark matches
      const localMatches = POPULAR_LOCATIONS.filter((l) =>
        l.address.toLowerCase().includes(text.toLowerCase())
      );

      // 2. Query OpenStreetMap Nominatim for live suggestions
      try {
        const res = await fetch(
          `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(
            text
          )}&countrycodes=in&limit=5`
        );
        if (res.ok) {
          const data = await res.json();
          const osmMatches = (data || []).map((item: any) => ({
            address: item.display_name,
            lat: parseFloat(item.lat),
            lng: parseFloat(item.lon),
          }));
          const combined = [...localMatches, ...osmMatches].slice(0, 6);
          setSuggestions(combined);
          setShowSuggestions(combined.length > 0);
          return;
        }
      } catch {
        // Fallback to local
      }

      setSuggestions(localMatches);
      setShowSuggestions(localMatches.length > 0);
    }, 350);
  };

  const handleSelect = (item: LocationPoint) => {
    setQuery(item.address);
    onChange(item);
    setShowSuggestions(false);
  };

  const handleDetectLocation = () => {
    if (!navigator.geolocation) {
      toast.error('Geolocation is not supported by your browser');
      return;
    }

    setLoadingLoc(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          // Reverse geocode via OSM Nominatim
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`
          );
          if (res.ok) {
            const data = await res.json();
            const point: LocationPoint = {
              address: data.display_name || `${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,
              lat: latitude,
              lng: longitude,
            };
            setQuery(point.address);
            onChange(point);
            toast.success('Current location detected!');
            setLoadingLoc(false);
            return;
          }
        } catch {}

        const fallbackPoint: LocationPoint = {
          address: `Current GPS (${latitude.toFixed(4)}, ${longitude.toFixed(4)})`,
          lat: latitude,
          lng: longitude,
        };
        setQuery(fallbackPoint.address);
        onChange(fallbackPoint);
        setLoadingLoc(false);
      },
      (err) => {
        setLoadingLoc(false);
        toast.error('Unable to fetch GPS position. Please enter address manually.');
      },
      { timeout: 10000, enableHighAccuracy: true }
    );
  };

  return (
    <div className="relative space-y-1.5">
      <div className="flex items-center justify-between">
        <label className="text-xs font-semibold text-foreground flex items-center gap-1.5">
          <MapPin className={cn('w-3.5 h-3.5', pinColor)} />
          {label}
        </label>
        {showCurrentLocationButton && (
          <button
            type="button"
            onClick={handleDetectLocation}
            disabled={loadingLoc}
            className="text-[11px] text-primary hover:underline font-medium flex items-center gap-1 transition-colors"
          >
            {loadingLoc ? (
              <Loader2 className="w-3 h-3 animate-spin" />
            ) : (
              <LocateFixed className="w-3 h-3" />
            )}
            Use Current Location
          </button>
        )}
      </div>

      <div className="relative">
        <Input
          type="text"
          value={query}
          onChange={(e) => handleSearch(e.target.value)}
          onFocus={() => {
            if (suggestions.length > 0) setShowSuggestions(true);
          }}
          placeholder={placeholder}
          className="h-10 text-sm pr-8 bg-background border-border/80 rounded-xl focus-visible:ring-primary/20"
        />

        {query && (
          <button
            type="button"
            onClick={() => {
              setQuery('');
              onChange(null);
              setSuggestions([]);
              setShowSuggestions(false);
            }}
            className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
          >
            <X className="w-4 h-4" />
          </button>
        )}
      </div>

      {/* Autocomplete Dropdown */}
      {showSuggestions && suggestions.length > 0 && (
        <div className="absolute left-0 right-0 top-full mt-1 bg-popover/95 backdrop-blur-md border border-border/80 shadow-xl rounded-xl z-50 overflow-hidden divide-y divide-border/50 max-h-56 overflow-y-auto">
          {suggestions.map((s, idx) => (
            <button
              key={idx}
              type="button"
              onClick={() => handleSelect(s)}
              className="w-full text-left px-3.5 py-2.5 hover:bg-muted/60 transition-colors flex items-start gap-2.5 text-xs text-foreground"
            >
              <MapPin className="w-3.5 h-3.5 text-primary shrink-0 mt-0.5" />
              <span className="line-clamp-2">{s.address}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Star, Loader2, HeartHandshake } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

interface RatingModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  rideId: string;
  driverName?: string;
  onSuccess?: () => void;
}

export default function RatingModal({
  open,
  onOpenChange,
  rideId,
  driverName = 'Driver',
  onSuccess,
}: RatingModalProps) {
  const [rating, setRating] = useState<number>(5);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [comment, setComment] = useState<string>('');
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!rideId) return;
    setSubmitting(true);
    try {
      await api.rateRide(rideId, { stars: rating, comment });
      toast.success('Thank you for your rating!');
      onOpenChange(false);
      if (onSuccess) onSuccess();
    } catch (err: any) {
      toast.error(err.message || 'Failed to submit rating');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md rounded-2xl p-6">
        <DialogHeader className="text-center">
          <div className="w-12 h-12 rounded-full bg-primary/10 text-primary mx-auto flex items-center justify-center mb-2">
            <HeartHandshake className="w-6 h-6" />
          </div>
          <DialogTitle className="text-xl font-bold text-foreground">
            Rate Your Experience
          </DialogTitle>
          <DialogDescription className="text-xs text-muted-foreground">
            How was your ride with <span className="font-semibold text-foreground">{driverName}</span>?
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-2">
          {/* Star selector */}
          <div className="flex items-center justify-center gap-2">
            {[1, 2, 3, 4, 5].map((star) => {
              const active = hoverRating ? hoverRating >= star : rating >= star;
              return (
                <button
                  key={star}
                  type="button"
                  onMouseEnter={() => setHoverRating(star)}
                  onMouseLeave={() => setHoverRating(0)}
                  onClick={() => setRating(star)}
                  className="p-1.5 focus:outline-none transition-transform hover:scale-110 active:scale-95"
                >
                  <Star
                    className={cn(
                      'w-8 h-8 transition-colors',
                      active ? 'fill-amber-500 text-amber-500' : 'text-muted-foreground/40'
                    )}
                  />
                </button>
              );
            })}
          </div>

          <div className="text-center">
            <span className="text-xs font-semibold text-amber-600 dark:text-amber-400">
              {rating === 5 && 'Excellent service!'}
              {rating === 4 && 'Good trip'}
              {rating === 3 && 'Average'}
              {rating === 2 && 'Needs improvement'}
              {rating === 1 && 'Poor experience'}
            </span>
          </div>

          {/* Feedback comment */}
          <div>
            <label className="text-xs font-semibold text-foreground mb-1 block">
              Leave a note (optional)
            </label>
            <Textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder="Cleanliness, punctuality, polite driver..."
              rows={3}
              className="resize-none rounded-xl text-xs"
            />
          </div>

          {/* Actions */}
          <div className="flex gap-2.5">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="flex-1 rounded-xl text-xs"
            >
              Skip
            </Button>
            <Button
              type="button"
              onClick={handleSubmit}
              disabled={submitting}
              className="flex-1 rounded-xl text-xs font-semibold"
            >
              {submitting ? <Loader2 className="w-4 h-4 animate-spin mr-1.5" /> : null}
              Submit Feedback
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Map, MapControls, MapMarker, MapRoute, MarkerContent, MarkerTooltip } from '@/components/ui/map';
import { Navigation, MapPin, Car, Ambulance, Bike, Zap, Crosshair } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import { MarkerSmoother } from '@/utils/markerInterpolation';

export interface LatLng {
  lat: number;
  lng: number;
}

interface RideMapProps {
  pickup?: LatLng | null;
  drop?: LatLng | null;
  riderLocation?: LatLng | null;
  vehicleType?: string;
  isEmergency?: boolean;
  className?: string;
  zoom?: number;
}

export default function RideMap({
  pickup,
  drop,
  riderLocation,
  vehicleType = 'car',
  isEmergency = false,
  className = 'h-full min-h-[400px]',
  zoom = 13,
}: RideMapProps) {
  // Spec 05 §4: 60fps LERP smoothing for the live driver marker.
  // Raw socket GPS (1-3s cadence) feeds MarkerSmoother; the marker renders
  // the interpolated position so it glides instead of jumping.
  const smootherRef = useRef<MarkerSmoother | null>(null);
  const [smoothRider, setSmoothRider] = useState<LatLng | null>(null);

  useEffect(() => {
    if (!riderLocation?.lat || !riderLocation?.lng) return;
    if (!smootherRef.current) {
      smootherRef.current = new MarkerSmoother(
        { lat: riderLocation.lat, lng: riderLocation.lng },
        ([lat, lng]) => setSmoothRider({ lat, lng })
      );
      setSmoothRider({ lat: riderLocation.lat, lng: riderLocation.lng });
    } else {
      smootherRef.current.setNextTarget({ lat: riderLocation.lat, lng: riderLocation.lng }, 1500);
    }
  }, [riderLocation?.lat, riderLocation?.lng]);

  useEffect(() => () => smootherRef.current?.destroy(), []);

  const liveRider = smoothRider || riderLocation;

  // Determine center of map: rider position > pickup > drop > default Jabalpur coordinates
  const center: [number, number] = useMemo(() => {
    if (liveRider?.lng && liveRider?.lat) {
      return [liveRider.lng, liveRider.lat];
    }
    if (pickup?.lng && pickup?.lat) {
      return [pickup.lng, pickup.lat];
    }
    if (drop?.lng && drop?.lat) {
      return [drop.lng, drop.lat];
    }
    return [79.9864, 23.1815]; // Default center
  }, [pickup, drop, liveRider]);

  // Build a route line between pickup and drop, or rider and pickup
  const routeCoordinates = useMemo(() => {
    const coords: [number, number][] = [];
    if (liveRider?.lng && liveRider?.lat) {
      coords.push([liveRider.lng, liveRider.lat]);
    }
    if (pickup?.lng && pickup?.lat) {
      coords.push([pickup.lng, pickup.lat]);
    }
    if (drop?.lng && drop?.lat) {
      coords.push([drop.lng, drop.lat]);
    }
    return coords.length >= 2 ? coords : [];
  }, [pickup, drop, riderLocation]);

  const VehicleIcon = isEmergency || vehicleType === 'ambulance' ? Ambulance : vehicleType === 'bike' ? Bike : Car;

  return (
    <div className={cn('relative w-full h-full rounded-2xl overflow-hidden border border-border/80 shadow-inner bg-muted/20', className)}>
      <Map center={center} zoom={zoom} className="w-full h-full">
        <MapControls position="bottom-right" />

        {/* Route Polyline */}
        {routeCoordinates.length >= 2 && (
          <MapRoute
            id="ride-route"
            coordinates={routeCoordinates}
            color={isEmergency ? '#ef4444' : '#0f766e'}
            width={4}
            opacity={0.85}
          />
        )}

        {/* Pickup Marker */}
        {pickup?.lat && pickup?.lng && (
          <MapMarker longitude={pickup.lng} latitude={pickup.lat}>
            <MarkerContent>
              <div className="flex flex-col items-center">
                <div className="w-8 h-8 rounded-full bg-emerald-600 text-white shadow-lg border-2 border-white flex items-center justify-center font-bold text-xs ring-4 ring-emerald-500/20">
                  P
                </div>
                <div className="w-1.5 h-2 bg-emerald-600 rounded-b-sm" />
              </div>
            </MarkerContent>
            <MarkerTooltip>
              <span className="text-xs font-semibold text-emerald-600">Pickup Location</span>
            </MarkerTooltip>
          </MapMarker>
        )}

        {/* Drop Marker */}
        {drop?.lat && drop?.lng && (
          <MapMarker longitude={drop.lng} latitude={drop.lat}>
            <MarkerContent>
              <div className="flex flex-col items-center">
                <div className="w-8 h-8 rounded-full bg-rose-600 text-white shadow-lg border-2 border-white flex items-center justify-center font-bold text-xs ring-4 ring-rose-500/20">
                  D
                </div>
                <div className="w-1.5 h-2 bg-rose-600 rounded-b-sm" />
              </div>
            </MarkerContent>
            <MarkerTooltip>
              <span className="text-xs font-semibold text-rose-600">Dropoff Destination</span>
            </MarkerTooltip>
          </MapMarker>
        )}

        {/* Live Rider Marker (LERP-smoothed) */}
        {liveRider?.lat && liveRider?.lng && (
          <MapMarker longitude={liveRider.lng} latitude={liveRider.lat}>
            <MarkerContent>
              <div className="relative flex items-center justify-center">
                {/* Pulsing ring animation */}
                <span className="animate-ping absolute inline-flex h-9 w-9 rounded-full bg-primary/40 opacity-75" />
                <div className="relative w-9 h-9 rounded-full bg-primary text-primary-foreground shadow-xl border-2 border-background flex items-center justify-center">
                  <VehicleIcon className="w-5 h-5" />
                </div>
              </div>
            </MarkerContent>
            <MarkerTooltip>
              <div className="text-xs">
                <p className="font-semibold text-foreground">Driver Live Location</p>
                <p className="text-[10px] text-muted-foreground">Moving toward destination</p>
              </div>
            </MarkerTooltip>
          </MapMarker>
        )}
      </Map>

      {/* Floating Status Badges overlay on map */}
      <div className="absolute top-3 left-3 z-10 flex flex-wrap gap-2 pointer-events-none">
        {isEmergency && (
          <Badge variant="destructive" className="shadow-md text-xs font-semibold animate-pulse">
            🚨 Emergency Priority Dispatch
          </Badge>
        )}
        {pickup && (
          <Badge variant="secondary" className="shadow-sm backdrop-blur-md bg-background/90 text-[11px]">
            📍 Route Loaded
          </Badge>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Loader2, AlertCircle, RefreshCw, X, CheckCircle2, Clock, Navigation, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import RiderInfoCard from './RiderInfoCard';
import DemoPaymentSheet from './DemoPaymentSheet';
import RatingModal from './RatingModal';

interface RideStatusPanelProps {
  ride: any;
  onCancelRide: (reason?: string) => void;
  onRetrySearch?: () => void;
  onRideCompletedPayment?: (payment: any) => void;
  onRefreshRide?: () => void;
}

export default function RideStatusPanel({
  ride,
  onCancelRide,
  onRetrySearch,
  onRideCompletedPayment,
  onRefreshRide,
}: RideStatusPanelProps) {
  const [ratingOpen, setRatingOpen] = useState(false);
  const [elapsedSeconds, setElapsedSeconds] = useState(0);

  // Trip duration timer for in_progress state
  useEffect(() => {
    let interval: any;
    if (ride?.status === 'in_progress') {
      const startTime = ride.startedAt ? new Date(ride.startedAt).getTime() : Date.now();
      setElapsedSeconds(Math.floor((Date.now() - startTime) / 1000));
      interval = setInterval(() => {
        setElapsedSeconds(Math.floor((Date.now() - startTime) / 1000));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [ride?.status, ride?.startedAt]);

  if (!ride) return null;

  const status = ride.status;
  const rider = ride.riderDetails || (ride.riderId?.name ? ride.riderId : null);

  const formatTimer = (totalSeconds: number) => {
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  return (
    <div className="space-y-4">
      <AnimatePresence mode="wait">
        {/* State 1: SEARCHING FOR DRIVER */}
        {status === 'searching' && (
          <motion.div
            key="searching"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="rounded-2xl border border-border/80 bg-card p-5 text-center space-y-4 shadow-sm"
          >
            <div className="relative w-20 h-20 mx-auto flex items-center justify-center">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary/20" />
              <div className="w-16 h-16 rounded-full bg-primary/10 border-2 border-primary flex items-center justify-center text-primary shadow-md">
                <Loader2 className="w-8 h-8 animate-spin" />
              </div>
            </div>

            <div>
              <h3 className="font-bold text-base text-foreground">
                Searching for nearby {ride.vehicleType?.toUpperCase()}...
              </h3>
              <p className="text-xs text-muted-foreground mt-1 max-w-xs mx-auto">
                Notifying online verified drivers within pickup radius. Please wait a moment.
              </p>
            </div>

            <div className="flex justify-center gap-2 pt-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => onCancelRide('Cancelled during driver search')}
                className="text-xs rounded-xl h-9 text-destructive border-destructive/30 hover:bg-destructive/10"
              >
                Cancel Search
              </Button>
            </div>
          </motion.div>
        )}

        {/* State 2: DRIVER ACCEPTED & ARRIVING */}
        {(status === 'accepted' || status === 'rider_arriving') && (
          <motion.div
            key="arriving"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-3"
          >
            <div className="flex items-center justify-between px-1">
              <div className="flex items-center gap-2">
                <span className="relative flex h-3 w-3">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
                  <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500" />
                </span>
                <span className="font-bold text-sm text-foreground">Driver En Route</span>
              </div>
              <Badge variant="outline" className="text-xs bg-emerald-500/10 text-emerald-600 border-emerald-500/30">
                Arriving in ~{ride.durationMin || 4} mins
              </Badge>
            </div>

            {rider && (
              <RiderInfoCard
                rider={rider}
                statusText="Arriving at Pickup"
                onCancel={() => onCancelRide('Cancelled by passenger before arrival')}
                canCancel={true}
              />
            )}
          </motion.div>
        )}

        {/* State 3: DRIVER ARRIVED */}
        {status === 'arrived' && (
          <motion.div
            key="arrived"
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-3"
          >
            <div className="rounded-2xl bg-emerald-500/10 border border-emerald-500/30 p-4 flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center shrink-0 shadow-md">
                <CheckCircle2 className="w-5 h-5" />
              </div>
              <div>
                <h4 className="font-bold text-sm text-emerald-950 dark:text-emerald-300">
                  Driver Has Arrived!
                </h4>
                <p className="text-xs text-emerald-700 dark:text-emerald-400">
                  Your vehicle is waiting at the pickup location.
                </p>
              </div>
            </div>

            {rider && (
              <RiderInfoCard
                rider={rider}
                statusText="Waiting at Pickup"
                canCancel={false}
              />
            )}
          </motion.div>
        )}

        {/* State 4: TRIP IN PROGRESS */}
        {status === 'in_progress' && (
          <motion.div
            key="in_progress"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="space-y-3"
          >
            <div className="rounded-2xl border border-primary/30 bg-primary/5 p-4 space-y-3">
              <div className="flex items-center justify-between">
                <Badge variant="default" className="gap-1.5 text-xs font-semibold px-2.5 py-0.5">
                  <Navigation className="w-3.5 h-3.5" />
                  Trip In Progress
                </Badge>
                <div className="flex items-center gap-1.5 font-mono font-bold text-sm text-primary">
                  <Clock className="w-4 h-4" />
                  <span>{formatTimer(elapsedSeconds)}</span>
                </div>
              </div>

              <div className="text-xs space-y-1">
                <p className="text-muted-foreground">Heading to Destination:</p>
                <p className="font-semibold text-foreground truncate">{ride.drop?.address}</p>
              </div>
            </div>

            {rider && (
              <RiderInfoCard
                rider={rider}
                statusText="Trip Active"
                canCancel={false}
              />
            )}
          </motion.div>
        )}

        {/* State 5: COMPLETED -> DEMO PAYMENT SHEET */}
        {status === 'completed' && (
          <motion.div
            key="completed"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="space-y-3"
          >
            {ride.payment?.status === 'paid' ? (
              <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-5 text-center space-y-3">
                <CheckCircle2 className="w-12 h-12 text-emerald-600 mx-auto" />
                <h3 className="font-bold text-lg text-foreground">Ride Completed & Paid</h3>
                <p className="text-xs text-muted-foreground">
                  Simulated payment completed. Txn Ref: {ride.payment?.transactionRef || 'DEMO-TXN'}
                </p>

                <Button
                  onClick={() => setRatingOpen(true)}
                  className="w-full rounded-xl text-xs font-semibold h-10 gap-2"
                >
                  Rate Your Driver
                </Button>
              </div>
            ) : (
              <DemoPaymentSheet
                rideId={String(ride._id)}
                amount={ride.fare?.total || 0}
                onPaymentComplete={(pay) => {
                  if (onRideCompletedPayment) onRideCompletedPayment(pay);
                  setRatingOpen(true);
                }}
              />
            )}
          </motion.div>
        )}

        {/* State 6: NO RIDERS FOUND */}
        {status === 'no_riders_found' && (
          <motion.div
            key="no_riders"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="rounded-2xl border border-border/80 bg-card p-5 text-center space-y-4 shadow-sm"
          >
            <div className="w-12 h-12 rounded-full bg-amber-500/10 text-amber-600 mx-auto flex items-center justify-center">
              <AlertCircle className="w-6 h-6" />
            </div>

            <div>
              <h3 className="font-bold text-base text-foreground">No Drivers Available Nearby</h3>
              <p className="text-xs text-muted-foreground mt-1 max-w-xs mx-auto">
                All drivers for this vehicle type are currently busy. You can retry with an expanded search or choose another vehicle.
              </p>
            </div>

            <div className="flex gap-2 justify-center pt-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => onCancelRide('No drivers available')}
                className="text-xs rounded-xl"
              >
                Cancel
              </Button>
              {onRetrySearch && (
                <Button
                  size="sm"
                  onClick={onRetrySearch}
                  className="text-xs rounded-xl gap-1.5"
                >
                  <RefreshCw className="w-3.5 h-3.5" />
                  Retry Search
                </Button>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Rating Dialog */}
      <RatingModal
        open={ratingOpen}
        onOpenChange={setRatingOpen}
        rideId={String(ride._id)}
        driverName={rider?.name || 'Driver'}
        onSuccess={() => {
          if (onRefreshRide) onRefreshRide();
        }}
      />
    </div>
  );
}

