              className={`w-11 h-11 sm:w-12 sm:h-12 rounded-full border-0 transition-all ${
                isLowLightEnhanced
                  ? 'bg-amber-500/20 text-amber-300 hover:bg-amber-500/30 ring-2 ring-amber-400/50'
