import { createContext, useContext, useState, useEffect, useRef, useCallback } from 'react';
import { toast } from 'sonner';
import { getSocket } from '@/lib/socket';
import { useAuth } from '@/context/AuthContext';
import {
  playRingtone,
  playRingbackTone,
  playConnectSound,
  playEndSound,
  playBusySound,
  triggerVibration,
  stopVibration,
} from '@/lib/audioCallSounds';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const AudioCallContext = createContext<Unmodelled>(null);

const ICE_SERVERS = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun2.l.google.com:19302' },
    { urls: 'stun:stun3.l.google.com:19302' },
  ],
};

const CALL_TIMEOUT_SECONDS = 30;

export function AudioCallProvider({ children }: Unmodelled) {
  const { user } = useAuth();

  // Call States: 'idle' | 'calling' | 'ringing' | 'connecting' | 'connected' | 'ended' | 'busy' | 'timeout'
  const [callState, setCallState] = useState('idle');
  const [activePeer, setActivePeer] = useState<Unmodelled>(null); // { id, name, avatar, role, phone, appointmentId }
  const [isCaller, setIsCaller] = useState(false);
  const [currentCallLogId, setCurrentCallLogId] = useState<Unmodelled>(null);

  // Audio Controls
  const [isMuted, setIsMuted] = useState(false);
  const [isSpeakerOn, setIsSpeakerOn] = useState(true);
  const [audioDevices, setAudioDevices] = useState<ApiRow[]>([]);
  const [selectedOutputId, setSelectedOutputId] = useState('default');

  // Stats & Timers
  const [callDuration, setCallDuration] = useState(0);
  const [callQuality, setCallQuality] = useState('good'); // 'good' | 'fair' | 'poor' | 'reconnecting'
  const [isMinimized, setIsMinimized] = useState(false);

  // Call Recording & Clinical Notes
  const [isRecording, setIsRecording] = useState(false);
  const [recordingDuration, setRecordingDuration] = useState(0);
  const [clinicalNotes, setClinicalNotes] = useState('');

  // References
  const peerConnectionRef: Unmodelled = useRef<Unmodelled>(null);
  const localStreamRef: Unmodelled = useRef<Unmodelled>(null);
  const remoteStreamRef: Unmodelled = useRef<Unmodelled>(null);
  const remoteAudioElemRef: Unmodelled = useRef<Unmodelled>(null);
  const callTimerRef = useRef<Unmodelled>(null);
  const recordingTimerRef = useRef<Unmodelled>(null);
  const timeoutTimerRef = useRef<Unmodelled>(null);
  const qualityIntervalRef = useRef<Unmodelled>(null);
  const stopToneRef = useRef<Unmodelled>(null);
  const mediaRecorderRef: Unmodelled = useRef<Unmodelled>(null);
  const recordedChunksRef = useRef<Unmodelled[]>([]);
  const recordingAudioCtxRef: Unmodelled = useRef<Unmodelled>(null);

  // Create remote audio element on mount
  useEffect(() => {
    if (!remoteAudioElemRef.current) {
      const audio = document.createElement('audio');
      audio.autoplay = true;
      (audio as Unmodelled).playsInline = true;
      remoteAudioElemRef.current = audio;
    }
  }, []);

  // Fetch available audio output devices (bluetooth, wired, speaker)
  const refreshAudioDevices = useCallback(async () => {
    if (typeof navigator !== 'undefined' && navigator.mediaDevices?.enumerateDevices) {
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const outputs = devices.filter((d) => d.kind === 'audiooutput');
        setAudioDevices(outputs);
      } catch (e: any) {
        console.warn('Audio devices enumeration error:', e);
      }
    }
  }, []);

  useEffect(() => {
    refreshAudioDevices();
    if (navigator.mediaDevices?.addEventListener) {
      navigator.mediaDevices.addEventListener('devicechange', refreshAudioDevices);
      return () => {
        navigator.mediaDevices.removeEventListener('devicechange', refreshAudioDevices);
      };
    }
  }, [refreshAudioDevices]);

  // Clean up all media, connections, timers, and tones
  const cleanupMediaAndPeer = useCallback(() => {
    if (stopToneRef.current) {
      stopToneRef.current();
      stopToneRef.current = null;
    }
    stopVibration();

    if (callTimerRef.current) {
      clearInterval(callTimerRef.current);
      callTimerRef.current = null;
    }
    if (recordingTimerRef.current) {
      clearInterval(recordingTimerRef.current);
      recordingTimerRef.current = null;
    }
    if (timeoutTimerRef.current) {
      clearTimeout(timeoutTimerRef.current);
      timeoutTimerRef.current = null;
    }
    if (qualityIntervalRef.current) {
      clearInterval(qualityIntervalRef.current);
      qualityIntervalRef.current = null;
    }

    // Stop recording if active
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      try {
        mediaRecorderRef.current.stop();
      } catch (e: any) {}
    }

    if (recordingAudioCtxRef.current && recordingAudioCtxRef.current.state !== 'closed') {
      try {
        recordingAudioCtxRef.current.close();
      } catch (e: any) {}
    }

    // Stop local audio tracks
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach((track: Unmodelled) => track.stop());
      localStreamRef.current = null;
    }

    // Stop remote audio element
    if (remoteAudioElemRef.current) {
      remoteAudioElemRef.current.srcObject = null;
    }
    remoteStreamRef.current = null;

    // Close WebRTC peer connection
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close();
      peerConnectionRef.current = null;
    }
  }, []);

  // Set selected audio output (Earpiece / Speaker / Headset)
  const setAudioOutput = useCallback(async (deviceId: Unmodelled) => {
    setSelectedOutputId(deviceId);
    if (remoteAudioElemRef.current && typeof remoteAudioElemRef.current.setSinkId === 'function') {
      try {
        await remoteAudioElemRef.current.setSinkId(deviceId);
        toast.success(`Audio output changed`);
      } catch (err: any) {
        console.warn('setSinkId error:', err);
      }
    }
  }, []);

  // Toggle speaker phone
  const toggleSpeaker = useCallback(() => {
    setIsSpeakerOn((prev) => {
      const next: Unmodelled = !prev;
      if (remoteAudioElemRef.current) {
        remoteAudioElemRef.current.volume = next ? 1.0 : 0.4;
      }
      return next;
    });
  }, []);

  // Toggle mic mute
  const toggleMute = useCallback(() => {
    if (localStreamRef.current) {
      const audioTrack = localStreamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setIsMuted(!audioTrack.enabled);
        toast.info(!audioTrack.enabled ? 'Microphone Muted' : 'Microphone Unmuted');
      }
    }
  }, []);

  // ── Call Log Backend Helpers ──
  const logInitiate = async (receiverId: Unmodelled, appointmentId: Unmodelled) => {
    try {
      const res = await fetch('/api/calls/initiate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ receiverId, appointmentId }),
      });
      const json = await res.json();
      if (json.success && json.call?._id) {
        setCurrentCallLogId(json.call._id);
        return json.call._id;
      }
    } catch (e: any) {
      console.warn('Failed to log call initiate:', e);
    }
    return null;
  };

  const updateCallStatus = async (callId: Unmodelled, status: Unmodelled, duration = 0, notes = '') => {
    if (!callId) return;
    try {
      await fetch(`/api/calls/${callId}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ status, duration, notes }),
      });
    } catch (e: any) {
      console.warn('Failed to update call status:', e);
    }
  };

  const saveClinicalNotes = useCallback(async (notesText: Unmodelled) => {
    const textToSave = notesText != null ? notesText : clinicalNotes;
    if (!currentCallLogId) {
      toast.error('No active call record found');
      return;
    }
    try {
      await updateCallStatus(currentCallLogId, 'completed', callDuration, textToSave);
      toast.success('Clinical consultation notes saved to audio call record');
    } catch (e: any) {
      toast.error('Failed to save clinical notes');
    }
  }, [currentCallLogId, clinicalNotes, callDuration]);

  const uploadRecordingBlob = async (callId: Unmodelled, blob: Unmodelled, duration: Unmodelled) => {
    if (!callId || !blob) return;
    try {
      const formData = new FormData();
      formData.append('audio', blob, `recording-${callId}.webm`);
      formData.append('duration', String(duration));
      await fetch(`/api/calls/${callId}/recording`, {
        method: 'POST',
        credentials: 'include',
        body: formData,
      });
      toast.success('Call audio recording saved to history');
    } catch (e: any) {
      console.warn('Failed to upload call recording:', e);
    }
  };

  // Acquire clean audio stream with Echo Cancellation, Noise Suppression, and AGC
  const getMicrophoneStream = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          sampleRate: 48000,
        },
        video: false, // Strict audio only
      });
      localStreamRef.current = stream;
      setIsMuted(false);
      return stream;
    } catch (err: any) {
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        toast.error('Microphone permission was denied. Please allow mic access in your browser.');
      } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
        toast.error('No microphone detected on your device.');
      } else {
        toast.error(`Microphone error: ${err.message}`);
      }
      throw err;
    }
  };

  // Start combined call recording (mixes both local doctor voice & remote patient voice)
  const startRecording = useCallback(() => {
    if (callState !== 'connected') {
      toast.error('You can only record an active connected call');
      return;
    }

    try {
      const AudioCtx = window.AudioContext || (window as Unmodelled).webkitAudioContext;
      const ctx = new AudioCtx();
      recordingAudioCtxRef.current = ctx;

      const dest = ctx.createMediaStreamDestination();

      if (localStreamRef.current && localStreamRef.current.getAudioTracks().length > 0) {
        const localSource = ctx.createMediaStreamSource(localStreamRef.current);
        localSource.connect(dest);
      }

      if (remoteStreamRef.current && remoteStreamRef.current.getAudioTracks().length > 0) {
        const remoteSource = ctx.createMediaStreamSource(remoteStreamRef.current);
        remoteSource.connect(dest);
      }

      const recorder = new MediaRecorder(dest.stream, {
        mimeType: MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
          ? 'audio/webm;codecs=opus'
          : 'audio/webm',
      });

      recordedChunksRef.current = [];
      recorder.ondataavailable = (e) => {
        if (e.data && e.data.size > 0) {
          recordedChunksRef.current.push(e.data);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(recordedChunksRef.current, { type: 'audio/webm' });
        if (blob.size > 0 && currentCallLogId) {
          uploadRecordingBlob(currentCallLogId, blob, recordingDuration);
        }
      };

      recorder.start(1000);
      mediaRecorderRef.current = recorder;
      setIsRecording(true);
      setRecordingDuration(0);

      recordingTimerRef.current = setInterval(() => {
        setRecordingDuration((prev) => prev + 1);
      }, 1000);

      toast.info('Call recording started');
    } catch (e: any) {
      console.warn('Recording initiation failed:', e);
      toast.error('Could not start call recording');
    }
  }, [callState, currentCallLogId, recordingDuration]);

  const stopRecording = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (recordingTimerRef.current) {
        clearInterval(recordingTimerRef.current);
        recordingTimerRef.current = null;
      }
      toast.success('Call recording finished');
    }
  }, []);

  const toggleRecording = useCallback(() => {
    if (isRecording) {
      stopRecording();
    } else {
      startRecording();
    }
  }, [isRecording, startRecording, stopRecording]);

  // Create WebRTC Peer Connection with event listeners
  const createPeerConnection = useCallback((peerUserId: Unmodelled, isOriginator: Unmodelled) => {
    const pc = new RTCPeerConnection(ICE_SERVERS);
    peerConnectionRef.current = pc;

    // ICE Candidate handler -> sends to peer via Socket.IO
    pc.onicecandidate = (event) => {
      if (event.candidate) {
        const s = getSocket();
        s.emit('call:ice', {
          to: peerUserId,
          candidate: event.candidate,
        });
      }
    };

    // Remote Audio Stream Received
    pc.ontrack = (event) => {
      const [stream] = event.streams;
      remoteStreamRef.current = stream;
      if (remoteAudioElemRef.current) {
        remoteAudioElemRef.current.srcObject = stream;
        remoteAudioElemRef.current.play().catch(() => {});
      }
    };

    // Monitor Connection State & Network Quality
    pc.oniceconnectionstatechange = () => {
      const state = pc.iceConnectionState;
      if (state === 'connected' || state === 'completed') {
        setCallQuality('good');
      } else if (state === 'disconnected') {
        setCallQuality('poor');
        toast.warning('Network unstable, trying to reconnect audio...');
      } else if (state === 'failed') {
        setCallQuality('reconnecting');
        // Trigger ICE restart on network switch (Wi-Fi <-> 4G/5G)
        if (isOriginator) {
          pc.restartIce();
        }
      }
    };

    // Periodic WebRTC stats check
    if (qualityIntervalRef.current) clearInterval(qualityIntervalRef.current);
    qualityIntervalRef.current = setInterval(async () => {
      if (pc && pc.connectionState === 'connected') {
        try {
          const stats = await pc.getStats();
          stats.forEach((report) => {
            if (report.type === 'candidate-pair' && report.state === 'succeeded') {
              const rtt = report.currentRoundTripTime;
              if (rtt != null) {
                if (rtt < 0.15) setCallQuality('good');
                else if (rtt < 0.35) setCallQuality('fair');
                else setCallQuality('poor');
              }
            }
          });
        } catch (e: any) {}
      }
    }, 4000);

    return pc;
  }, []);

  // ── INITIATE OUTGOING AUDIO CALL ──
  const initiateCall = useCallback(async (recipient: Unmodelled, appointmentId = null) => {
    if (!recipient || !recipient.id && !recipient._id) {
      toast.error('Recipient information is missing');
      return;
    }
    const recipientId = String(recipient.id || recipient._id);

    if (callState !== 'idle') {
      toast.error('You already have an active call in progress');
      return;
    }

    try {
      // 1. Get local mic stream
      const stream = await getMicrophoneStream();

      // 2. Setup state
      setActivePeer({
        id: recipientId,
        name: recipient.name || 'Patient',
        avatar: recipient.avatar || '',
        role: recipient.role || 'patient',
        phone: recipient.phone || '',
        appointmentId,
      });
      setIsCaller(true);
      setCallState('calling');
      setIsMinimized(false);
      setCallDuration(0);

      // 3. Play ringback tone
      stopToneRef.current = playRingbackTone();

      // 4. Log in database
      const logId = await logInitiate(recipientId, appointmentId);

      // 5. Send Socket.IO invite
      const s = getSocket();
      s.emit('call:invite', {
        to: recipientId,
        caller: {
          id: String(user?._id),
          name: user?.name || 'Doctor',
          avatar: user?.avatar || '',
          role: user?.role || 'doctor',
          phone: user?.phone || '',
        },
        callLogId: logId,
        appointmentId,
        timestamp: Date.now(),
      });

      // 6. Timeout after 30s if no answer
      timeoutTimerRef.current = setTimeout(() => {
        toast.warning('No answer from patient');
        s.emit('call:timeout', { to: recipientId, callLogId: logId });
        updateCallStatus(logId, 'missed', 0, 'No answer / timeout');
        playEndSound();
        setCallState('timeout');
        setTimeout(() => {
          cleanupMediaAndPeer();
          setCallState('idle');
          setActivePeer(null);
        }, 2000);
      }, CALL_TIMEOUT_SECONDS * 1000);
    } catch (err: any) {
      cleanupMediaAndPeer();
      setCallState('idle');
      setActivePeer(null);
    }
  }, [callState, user, cleanupMediaAndPeer]);

  // ── ACCEPT INCOMING CALL ──
  const acceptCall = useCallback(async () => {
    if (!activePeer) return;

    if (timeoutTimerRef.current) {
      clearTimeout(timeoutTimerRef.current);
      timeoutTimerRef.current = null;
    }
    if (stopToneRef.current) {
      stopToneRef.current();
      stopToneRef.current = null;
    }
    stopVibration();

    try {
      setCallState('connecting');

      // 1. Acquire mic stream
      const stream = await getMicrophoneStream();

      // 2. Create WebRTC Peer Connection
      const pc = createPeerConnection(activePeer.id, false);

      // Add local audio tracks to connection
      stream.getAudioTracks().forEach((track) => pc.addTrack(track, stream));

      // 3. Notify caller that call was accepted
      const s = getSocket();
      s.emit('call:accept', {
        to: activePeer.id,
        callLogId: currentCallLogId,
      });

      // Update call log
      if (currentCallLogId) {
        updateCallStatus(currentCallLogId, 'completed');
      }
    } catch (err: any) {
      toast.error('Failed to connect audio call');
      rejectCall();
    }
  }, [activePeer, currentCallLogId, createPeerConnection]);

  // ── REJECT INCOMING CALL ──
  const rejectCall = useCallback(() => {
    if (activePeer) {
      const s = getSocket();
      s.emit('call:reject', {
        to: activePeer.id,
        callLogId: currentCallLogId,
        reason: 'Declined by recipient',
      });
      if (currentCallLogId) {
        updateCallStatus(currentCallLogId, 'rejected', 0);
      }
    }
    playEndSound();
    cleanupMediaAndPeer();
    setCallState('ended');
    setTimeout(() => {
      setCallState('idle');
      setActivePeer(null);
      setCurrentCallLogId(null);
    }, 1200);
  }, [activePeer, currentCallLogId, cleanupMediaAndPeer]);

  // ── END ACTIVE OR OUTGOING CALL ──
  const endCall = useCallback(() => {
    if (activePeer) {
      const s = getSocket();
      if (callState === 'calling' || callState === 'ringing') {
        s.emit('call:cancel', { to: activePeer.id, callLogId: currentCallLogId });
        if (currentCallLogId) {
          updateCallStatus(currentCallLogId, 'cancelled', 0);
        }
      } else {
        s.emit('call:end', { to: activePeer.id, callLogId: currentCallLogId, duration: callDuration });
        if (currentCallLogId) {
          updateCallStatus(currentCallLogId, 'completed', callDuration);
        }
      }
    }

    playEndSound();
    cleanupMediaAndPeer();
    setCallState('ended');
    setTimeout(() => {
      setCallState('idle');
      setActivePeer(null);
      setCurrentCallLogId(null);
      setCallDuration(0);
      setIsRecording(false);
      setIsMinimized(false);
    }, 1200);
  }, [activePeer, callState, currentCallLogId, callDuration, cleanupMediaAndPeer]);

  // Toggle minimize/floating mode
  const toggleMinimize = useCallback(() => {
    setIsMinimized((prev) => !prev);
  }, []);

  // ── Socket.IO Signaling Listener ──
  useEffect(() => {
    const s = getSocket();
    if (!s) return;

    // Incoming Call Invite
    const handleCallInvite = (data: Unmodelled) => {
      const callerId = String(data.caller?.id || data.from);

      // If user is already in another call, reply busy immediately
      if (callState !== 'idle') {
        s.emit('call:busy', { to: callerId, reason: 'Line Busy' });
        return;
      }

      setActivePeer({
        id: callerId,
        name: data.caller?.name || 'Caller',
        avatar: data.caller?.avatar || '',
        role: data.caller?.role || 'patient',
        phone: data.caller?.phone || '',
        appointmentId: data.appointmentId || null,
      });
      setCurrentCallLogId(data.callLogId || null);
      setIsCaller(false);
      setCallState('ringing');
      setIsMinimized(false);

      // Play ringing chime + vibrate device
      stopToneRef.current = playRingtone();
      triggerVibration();

      // Recipient auto-timeout if not answered within 30s
      if (timeoutTimerRef.current) clearTimeout(timeoutTimerRef.current);
      timeoutTimerRef.current = setTimeout(() => {
        playEndSound();
        cleanupMediaAndPeer();
        setCallState('missed');
        setTimeout(() => {
          setCallState('idle');
          setActivePeer(null);
        }, 1500);
      }, CALL_TIMEOUT_SECONDS * 1000);

      // Inform caller that phone is ringing
      s.emit('call:ringing', { to: callerId });
    };

    // Caller receives Ringing acknowledgment
    const handleCallRinging = () => {
      if (callState === 'calling') {
        setCallState('ringing');
      }
    };

    // Recipient accepted call -> Caller creates Offer SDP and starts audio exchange
    const handleCallAccept = async (data: Unmodelled) => {
      if (timeoutTimerRef.current) clearTimeout(timeoutTimerRef.current);
      if (stopToneRef.current) {
        stopToneRef.current();
        stopToneRef.current = null;
      }

      setCallState('connecting');

      try {
        const pc: Unmodelled = createPeerConnection(activePeer?.id, true);

        if (localStreamRef.current) {
          localStreamRef.current.getTracks().forEach((track: Unmodelled) => pc.addTrack(track, localStreamRef.current));
        }

        const offer = await pc.createOffer({
          offerToReceiveAudio: true,
          offerToReceiveVideo: false,
        });
        await pc.setLocalDescription(offer);

        s.emit('call:offer', {
          to: activePeer?.id,
          offer,
        });
      } catch (e: any) {
        console.warn('Error creating WebRTC offer:', e);
      }
    };

    // Recipient receives Offer SDP -> sets remote description & responds with Answer SDP
    const handleCallOffer = async (data: Unmodelled) => {
      try {
        let pc = peerConnectionRef.current;
        if (!pc) {
          pc = createPeerConnection(activePeer?.id, false);
          if (localStreamRef.current) {
            localStreamRef.current.getTracks().forEach((track: Unmodelled) => pc.addTrack(track, localStreamRef.current));
          }
        }

        await pc.setRemoteDescription(new RTCSessionDescription(data.offer));
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);

        s.emit('call:answer', {
          to: activePeer?.id,
          answer,
        });

        // Connected!
        playConnectSound();
        setCallState('connected');

        // Start call duration timer
        if (callTimerRef.current) clearInterval(callTimerRef.current);
        callTimerRef.current = setInterval(() => {
          setCallDuration((prev) => prev + 1);
        }, 1000);
      } catch (e: any) {
        console.warn('Error handling WebRTC offer:', e);
      }
    };

    // Caller receives Answer SDP -> sets remote description & audio is officially flowing
    const handleCallAnswer = async (data: Unmodelled) => {
      try {
        const pc = peerConnectionRef.current;
        if (pc) {
          await pc.setRemoteDescription(new RTCSessionDescription(data.answer));

          playConnectSound();
          setCallState('connected');

          if (callTimerRef.current) clearInterval(callTimerRef.current);
          callTimerRef.current = setInterval(() => {
            setCallDuration((prev) => prev + 1);
          }, 1000);
        }
      } catch (e: any) {
        console.warn('Error setting WebRTC answer:', e);
      }
    };

    // Candidate exchange (ICE)
    const handleCallIce = async (data: Unmodelled) => {
      try {
        const pc = peerConnectionRef.current;
        if (pc && data.candidate) {
          await pc.addIceCandidate(new RTCIceCandidate(data.candidate));
        }
      } catch (e: any) {
        console.warn('Error adding ICE candidate:', e);
      }
    };

    // Call Rejected
    const handleCallReject = () => {
      toast.error('Call declined');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('rejected');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 1500);
    };

    // Call Cancelled before answer
    const handleCallCancel = () => {
      toast.info('Caller hung up');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('ended');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 1500);
    };

    // Call Ended by peer
    const handleCallEnd = () => {
      toast.info('Call ended');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('ended');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
        setCallDuration(0);
        setIsMinimized(false);
      }, 1500);
    };

    // Line Busy
    const handleCallBusy = () => {
      toast.warning('Patient is currently on another call');
      playBusySound();
      cleanupMediaAndPeer();
      setCallState('busy');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 2000);
    };

    // Timeout
    const handleCallTimeout = () => {
      toast.warning('No answer');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('timeout');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 2000);
    };

    s.on('call:invite', handleCallInvite);
    s.on('call:ringing', handleCallRinging);
    s.on('call:accept', handleCallAccept);
    s.on('call:offer', handleCallOffer);
    s.on('call:answer', handleCallAnswer);
    s.on('call:ice', handleCallIce);
    s.on('call:reject', handleCallReject);
    s.on('call:cancel', handleCallCancel);
    s.on('call:end', handleCallEnd);
    s.on('call:busy', handleCallBusy);
    s.on('call:timeout', handleCallTimeout);

    return () => {
      s.off('call:invite', handleCallInvite);
      s.off('call:ringing', handleCallRinging);
      s.off('call:accept', handleCallAccept);
      s.off('call:offer', handleCallOffer);
      s.off('call:answer', handleCallAnswer);
      s.off('call:ice', handleCallIce);
      s.off('call:reject', handleCallReject);
      s.off('call:cancel', handleCallCancel);
      s.off('call:end', handleCallEnd);
      s.off('call:busy', handleCallBusy);
      s.off('call:timeout', handleCallTimeout);
    };
  }, [callState, activePeer, createPeerConnection, cleanupMediaAndPeer]);

  return (
    <AudioCallContext.Provider
      value={{
        callState,
        activePeer,
        isCaller,
        isMuted,
        isSpeakerOn,
        audioDevices,
        selectedOutputId,
        callDuration,
        callQuality,
        isRecording,
        recordingDuration,
        isMinimized,
        localStream: localStreamRef.current,
        remoteStream: remoteStreamRef.current,
        initiateCall,
        acceptCall,
        rejectCall,
        endCall,
        clinicalNotes,
        setClinicalNotes,
        saveClinicalNotes,
        toggleMute,
        toggleSpeaker,
        setAudioOutput,
        toggleRecording,
        toggleMinimize,
      }}
    >
      {children}
    </AudioCallContext.Provider>
  );
}

export function useAudioCall() {
  const context = useContext(AudioCallContext);
  if (!context) {
    throw new Error('useAudioCall must be used within an AudioCallProvider');
  }
  return context;
}

import React, { createContext, useContext, ReactNode } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { loginUser, registerUser, logoutUser, updateUser as updateUserAction, setUser, selectCurrentUser, selectAuthLoading, selectIsAuthenticated, completeTwoFactorLogin as completeTwoFactorLoginThunk } from '@/store/slices/authSlice';
import { mergeSettings, readStoredSettings } from '@/lib/settings';
import type { Unmodelled } from '@/lib/apiTypes';

export interface AuthUser {
  _id?: string;
  id?: string;
  name?: string;
  email?: string;
  phone?: string;
  role?: string;
  avatar?: string;
  isVerified?: boolean;
  settings?: any;
  [key: string]: any;
}

export interface AuthContextType {
  user: AuthUser | null;
  login: (email: string, password?: string, role?: string) => Promise<any>;
  register: (body: any) => Promise<any>;
  logout: () => void;
  loading: boolean;
  updateUser: (updates: any) => void;
  isAuthenticated: boolean;
  completeOtpLogin: (data: { user: any }) => Promise<void>;
  completeGoogleLogin: (userData: any) => void;
  [key: string]: any;
}

const AuthContext = createContext<AuthContextType | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const dispatch = useDispatch<any>();
  const user = useSelector(selectCurrentUser) as AuthUser | null;
  const loading = useSelector(selectAuthLoading) as boolean;
  const isAuthenticated = useSelector(selectIsAuthenticated) as boolean;

  const login = async (email: string, password?: string, role?: string) => {
    const result = await dispatch(loginUser({ email, password, role }));
    return result.payload;
  };

  const register = async (body: any) => {
    const result = await dispatch(registerUser(body));
    return result.payload;
  };

  // AUTH-B-03: second leg of a 2FA login (ticket + TOTP / backup code -> session).
  const completeTwoFactorLogin = async (payload: { twoFactorTicket: string; token?: string; backupCode?: string }) => {
    const result = await dispatch(completeTwoFactorLoginThunk(payload as Unmodelled));
    return result.payload;
  };

  const logout = () => {
    dispatch(logoutUser());
  };

  const updateUser = (updates: any) => {
    dispatch(updateUserAction(updates));
  };

  const completeOtpLogin = async ({ user: userData }: { user: any }) => {
    dispatch(setUser({
      ...userData,
      settings: mergeSettings(readStoredSettings(), userData?.settings),
    }));
  };

  const completeGoogleLogin = (userData: any) => {
    dispatch(setUser({
      ...userData,
      settings: mergeSettings(readStoredSettings(), userData?.settings),
    }));
  };

  return (
    <AuthContext.Provider value={{ user, login, register, logout, loading, updateUser, isAuthenticated, completeOtpLogin, completeGoogleLogin, completeTwoFactorLogin }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = (): AuthContextType => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be inside AuthProvider');
  return ctx;
};

import { createContext, useContext } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  addItem as addItemAction,
  updateQty as updateQtyAction,
  removeItem as removeItemAction,
  clearCart as clearCartAction,
  selectCart,
  selectCartEntries,
  selectCartTotalItems,
  selectCartStores,
} from '@/store/slices/cartSlice';
import type { Unmodelled } from '@/lib/apiTypes';

const CartContext = createContext<Unmodelled>(null);

export function CartProvider({ children }: Unmodelled) {
  const dispatch = useDispatch();
  const cart = useSelector(selectCart);
  const entries = useSelector(selectCartEntries);
  const totalItems = useSelector(selectCartTotalItems);
  const stores = useSelector(selectCartStores);

  const addItem = (item: Unmodelled, storeId: Unmodelled) => dispatch(addItemAction({ item, storeId }));
  const updateQty = (key: Unmodelled, qty: Unmodelled) => dispatch(updateQtyAction({ key, qty }));
  const removeItem = (key: Unmodelled) => dispatch(removeItemAction(key));
  const clearCart = () => dispatch(clearCartAction());

  return (
    <CartContext.Provider value={{ cart, addItem, updateQty, removeItem, clearCart, entries, totalItems, stores }}>
      {children}
    </CartContext.Provider>
  );
}

export function useCart() {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error('useCart must be used within CartProvider');
  return ctx;
}

import { createContext, useContext, useEffect, useCallback } from 'react';
import { emergencyOverlayActive } from '@/lib/emergencyState';
import { useDispatch, useSelector } from 'react-redux';
import { useAuth } from '@/context/AuthContext';
import { fetchNotifications, selectNotificationCount, addNotification } from '@/store/slices/notificationsSlice';
import { getSocket, joinRoom, disconnectSocket } from '@/lib/socket';
import type { Unmodelled } from '@/lib/apiTypes';

const NotificationContext = createContext<Unmodelled>(null);

export function NotificationProvider({ children }: Unmodelled) {
  const dispatch = useDispatch();
  const count = useSelector(selectNotificationCount);
  const { user } = useAuth();

  const refreshCount = useCallback(async () => {
    if (!user) return;
    (dispatch as Unmodelled)(fetchNotifications());
  }, [user, dispatch]);

  useEffect(() => {
    if (user) {
      (dispatch as Unmodelled)(fetchNotifications());
    }
  }, [user, dispatch]);

  useEffect(() => {
    if (!user) {
      disconnectSocket();
      return;
    }

    const socket = getSocket();
    if (!socket.connected) socket.connect(); // logout ke baad disconnect hua tha
    // Shared socket — room join har (re)connect par dobara hota hai
    const cleanupJoin = joinRoom('join', user.id);

    const onNotification = (notification: Unmodelled) => {
      if (emergencyOverlayActive?.current) return;
      dispatch(addNotification(notification));
    };
    socket.on('notification', onNotification);

    return () => {
      socket.off('notification', onNotification);
      cleanupJoin();
    };
    // Sirf user.id par depend karo — user object har profile/settings update par
    // naya reference banata hai, jisse socket needless reconnect hota tha.
  }, [user?.id, dispatch]);

  return (
    <NotificationContext.Provider value={{ count, refreshCount }}>
      {children}
    </NotificationContext.Provider>
  );
}

export function useNotificationCount() {
  const context = useContext(NotificationContext);
  return context || { count: 0, refreshCount: () => {} };
}

import { createContext, useCallback, useContext, useEffect, useReducer, useState, type ReactNode } from 'react';
import { api } from '@/lib/api';

export interface Pharmacy {
  id?: string;
  _id?: string;
  name?: string;
  priority?: number;
  facilityId?: string;
}

export interface PreferredPharmacyValue {
  pharmacies: Pharmacy[];
  autoRetryEnabled: boolean;
  initialized: boolean;
  error: string | null;
  addPharmacy: (pharmacy: Pharmacy) => Promise<void>;
  removePharmacy: (id: string | undefined) => Promise<void>;
  reorderPharmacies: (fromIndex: number, toIndex: number) => Promise<void>;
  setAutoRetry: (enabled: boolean) => void;
  setPharmacies: (list: Pharmacy[]) => void;
}

const STORAGE_KEY = 'findmedi_preferred_pharmacies';
const LEGACY_STORAGE_KEY = 'mediCore_preferred_pharmacies';
const DEFAULT_PHARMACIES = [
  { id: 's1', name: 'MedPlus Pharmacy', priority: 1 },
  { id: 's2', name: 'HealthFirst Medicals', priority: 2 },
  { id: 's4', name: 'Apollo Pharmacy', priority: 3 },
];

function loadPrefs() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY) || localStorage.getItem(LEGACY_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

interface PrefsState {
  pharmacies: Pharmacy[];
  autoRetryEnabled: boolean;
  initialized: boolean;
}

interface PrefsAction {
  type: string;
  payload?: any;
}

const initialState: PrefsState = {
  pharmacies: [],
  autoRetryEnabled: false,
  initialized: false,
};

function prefsReducer(state: PrefsState, action: PrefsAction): PrefsState {
  switch (action.type) {
    case 'INIT':
      return { ...state, ...action.payload, initialized: true };
    case 'SET_PHARMACIES': {
      const updated: Pharmacy[] = action.payload.map((p: any, i: number) => ({ ...p, priority: i + 1 }));
      return { ...state, pharmacies: updated };
    }
    case 'ADD_PHARMACY':
      if (state.pharmacies.some(p => p._id === action.payload._id || p.id === action.payload.id)) return state;
      return { ...state, pharmacies: [...state.pharmacies, { ...action.payload, priority: state.pharmacies.length + 1 }] };
    case 'REMOVE_PHARMACY':
      return { ...state, pharmacies: state.pharmacies.filter(p => p._id !== action.payload && p.id !== action.payload).map((p, i) => ({ ...p, priority: i + 1 })) };
    case 'REORDER': {
      const { fromIndex, toIndex } = action.payload;
      const list = [...state.pharmacies];
      const [moved] = list.splice(fromIndex, 1);
      list.splice(toIndex, 0, moved);
      return { ...state, pharmacies: list.map((p, i) => ({ ...p, priority: i + 1 })) };
    }
    case 'SET_AUTO_RETRY':
      return { ...state, autoRetryEnabled: action.payload };
    default:
      return state;
  }
}

const PreferredPharmacyContext = createContext<PreferredPharmacyValue | null>(null);

export function PreferredPharmacyProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(prefsReducer, initialState);

  const [error, setError] = useState<string | null>(null);

  const loadFromBackend = useCallback(async () => {
    try {
      setError(null);
      const res = await api.getPreferredPharmacies();
      if (res?.pharmacies?.length) {
        const mapped = res.pharmacies.map((p: any) => ({ id: p._id, _id: p._id, name: p.name, priority: p.priority, facilityId: p.pharmacyId }));
        dispatch({ type: 'INIT', payload: { pharmacies: mapped, autoRetryEnabled: false } });
        localStorage.setItem(STORAGE_KEY, JSON.stringify({ pharmacies: mapped, autoRetryEnabled: false }));
        return true;
      }
    } catch {
      setError('Failed to load preferred pharmacies');
      return false;
    }
  }, []);

  useEffect(() => {
    (async () => {
      const loaded = await loadFromBackend();
      if (!loaded) {
        const stored = loadPrefs();
        if (stored) {
          dispatch({ type: 'INIT', payload: stored });
        } else {
          dispatch({
            type: 'INIT',
            payload: {
              pharmacies: DEFAULT_PHARMACIES.map((p, i) => ({ ...p, priority: i + 1 })),
              autoRetryEnabled: false,
            },
          });
        }
      }
    })();
  }, [loadFromBackend]);

  useEffect(() => {
    if (state.initialized) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ pharmacies: state.pharmacies, autoRetryEnabled: state.autoRetryEnabled }));
    }
  }, [state.pharmacies, state.autoRetryEnabled, state.initialized]);

  const addPharmacy = useCallback(async (pharmacy: Pharmacy) => {
    try {
      const res = await api.addPreferredPharmacy({ pharmacyId: pharmacy.facilityId || pharmacy.id, name: pharmacy.name });
      if (res?._id) {
        dispatch({ type: 'ADD_PHARMACY', payload: { ...pharmacy, _id: res._id } });
      }
    } catch { dispatch({ type: 'ADD_PHARMACY', payload: pharmacy }); }
  }, []);

  const removePharmacy = useCallback(async (id: string | undefined) => {
    const idToRemove = id;
    try {
      await api.deletePreferredPharmacy(idToRemove);
    } catch { /* fallback */ }
    dispatch({ type: 'REMOVE_PHARMACY', payload: idToRemove });
  }, []);

  const reorderPharmacies = useCallback(async (fromIndex: number, toIndex: number) => {
    dispatch({ type: 'REORDER', payload: { fromIndex, toIndex } });
    try {
      const ids = state.pharmacies.map(p => p._id || p.id);
      const list = [...ids];
      const [moved] = list.splice(fromIndex, 1);
      list.splice(toIndex, 0, moved);
      await api.reorderPreferredPharmacies({ orderedIds: list });
    } catch { /* best effort */ }
  }, [state.pharmacies]);

  const setAutoRetry = useCallback((enabled: boolean) => dispatch({ type: 'SET_AUTO_RETRY', payload: enabled }), []);

  const setPharmacies = useCallback((list: Pharmacy[]) => dispatch({ type: 'SET_PHARMACIES', payload: list }), []);

  return (
    <PreferredPharmacyContext.Provider value={{
      pharmacies: state.pharmacies,
      autoRetryEnabled: state.autoRetryEnabled,
      initialized: state.initialized,
      error,
      addPharmacy,
      removePharmacy,
      reorderPharmacies,
      setAutoRetry,
      setPharmacies,
    }}>
      {children}
    </PreferredPharmacyContext.Provider>
  );
}

export function usePreferredPharmacies() {
  const ctx = useContext(PreferredPharmacyContext);
  if (!ctx) throw new Error('usePreferredPharmacies must be inside PreferredPharmacyProvider');
  return ctx;
}

import { createContext, useContext, useState, useEffect, useRef, useCallback, type ReactNode } from 'react';
import { toast } from 'sonner';
import { getSocket } from '@/lib/socket';
import { useAuth } from '@/context/AuthContext';
import {
  playRingtone,
  playRingbackTone,
  playConnectSound,
  playEndSound,
  playBusySound,
  triggerVibration,
  stopVibration,
} from '@/lib/audioCallSounds';

export interface VideoPeer {
  id?: string;
  name?: string;
  avatar?: string;
  role?: string;
  phone?: string;
  appointmentId?: string | null;
}

/**
 * Shape of the value exposed by `VideoCallProvider`. Declared here (rather than
 * inferring it from `createContext(null)`) so `useVideoCall()` returns a real
 * object type instead of `never`, which was cascading "Property does not exist
 * on type 'never'" errors into every consuming component.
 *
 * Media objects and imperative callbacks stay deliberately permissive (`any`)
 * — the underlying state in this legacy context is largely untyped and typing
 * it fully is a separate, larger effort.
 */
export interface VideoCallValue {
  callState: string;
  activePeer: VideoPeer | null;
  isCaller: boolean;
  isAudioMuted: boolean;
  isVideoMuted: boolean;
  isRemoteVideoMuted: boolean;
  isRemoteAudioMuted: boolean;
  isSpeakerOn: boolean;
  isLowLightEnhanced: boolean;
  isScreenSharing: boolean;
  inCallMessages: any[];
  clinicalNotes: string;
  availableCameras: any[];
  selectedCameraId: string;
  facingMode: string;
  audioOutputDevices: any[];
  selectedOutputId: string;
  callDuration: number;
  networkQuality: string;
  resolutionLabel: string;
  isMinimized: boolean;
  isFullScreen: boolean;
  localStream: MediaStream | null;
  remoteStream: MediaStream | null;
  remoteVideoElemRef: any;
  localVideoElemRef: any;
  initiateVideoCall: (...args: any[]) => any;
  acceptVideoCall: (...args: any[]) => any;
  rejectVideoCall: (...args: any[]) => any;
  endVideoCall: (...args: any[]) => any;
  toggleAudioMute: (...args: any[]) => any;
  toggleVideoMute: (...args: any[]) => any;
  switchCamera: (...args: any[]) => any;
  flipFacingMode: (...args: any[]) => any;
  toggleSpeaker: (...args: any[]) => any;
  setAudioOutput: (...args: any[]) => any;
  toggleLowLightEnhancer: (...args: any[]) => any;
  toggleScreenShare: (...args: any[]) => any;
  sendInCallMessage: (...args: any[]) => any;
  setClinicalNotes: (...args: any[]) => any;
  saveClinicalNotes: (...args: any[]) => any;
  captureSnapshot: (...args: any[]) => any;
  togglePiP: (...args: any[]) => any;
  toggleMinimize: (...args: any[]) => any;
  toggleFullScreen: (...args: any[]) => any;
}

/** In-call chat payload — also used for messages arriving over the socket. */
export interface InCallMessage {
  senderId?: string;
  senderName?: string;
  text?: string;
  timestamp?: number;
  [key: string]: unknown;
}

/** Loose shape of the `videocall:*` socket payloads this context listens to. */
interface VideoCallSignalEvent {
  caller?: { id?: string; name?: string; avatar?: string; role?: string; phone?: string };
  from?: string;
  to?: string;
  callLogId?: string;
  appointmentId?: string;
  offer?: RTCSessionDescriptionInit;
  answer?: RTCSessionDescriptionInit;
  candidate?: RTCIceCandidateInit;
  kind?: string;
  enabled?: boolean;
  message?: InCallMessage;
  [key: string]: unknown;
}

/** `catch` variables are `unknown` under `useUnknownInCatchVariables`; these unwrap them. */
function errName(e: unknown): string {
  return typeof e === 'object' && e !== null && 'name' in e
    ? String((e as { name: unknown }).name)
    : '';
}

function errMessage(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

const VideoCallContext = createContext<VideoCallValue | null>(null);

const ICE_SERVERS = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun2.l.google.com:19302' },
    { urls: 'stun:stun3.l.google.com:19302' },
  ],
};

const CALL_TIMEOUT_SECONDS = 35;

export function VideoCallProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();

  // Call States: 'idle' | 'calling' | 'ringing' | 'connecting' | 'connected' | 'ended' | 'busy' | 'timeout'
  const [callState, setCallState] = useState<string>('idle');
  const [activePeer, setActivePeer] = useState<VideoPeer | null>(null); // { id, name, avatar, role, phone, appointmentId }
  const [isCaller, setIsCaller] = useState(false);
  const [currentCallLogId, setCurrentCallLogId] = useState<string | null>(null);

  // Audio/Video Hardware States
  const [isAudioMuted, setIsAudioMuted] = useState(false);
  const [isVideoMuted, setIsVideoMuted] = useState(false);
  const [isRemoteVideoMuted, setIsRemoteVideoMuted] = useState(false);
  const [isRemoteAudioMuted, setIsRemoteAudioMuted] = useState(false);
  const [isSpeakerOn, setIsSpeakerOn] = useState(true);
  const [isLowLightEnhanced, setIsLowLightEnhanced] = useState(false);

  // Hardware Devices
  const [availableCameras, setAvailableCameras] = useState<MediaDeviceInfo[]>([]);
  const [selectedCameraId, setSelectedCameraId] = useState('');
  const [facingMode, setFacingMode] = useState<string>('user'); // 'user' | 'environment'
  const [audioOutputDevices, setAudioOutputDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedOutputId, setSelectedOutputId] = useState('default');

  // Telemedicine & Medical Features
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [inCallMessages, setInCallMessages] = useState<InCallMessage[]>([]);
  const [clinicalNotes, setClinicalNotes] = useState('');

  // Stats & Display
  const [callDuration, setCallDuration] = useState(0);
  const [networkQuality, setNetworkQuality] = useState<string>('1080p-fullhd'); // '1080p-fullhd' | 'good' | 'fair' | 'poor' | 'reconnecting'
  const [resolutionLabel, setResolutionLabel] = useState<string>('1080p Full HD');
  const [isMinimized, setIsMinimized] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);

  // References
  const peerConnectionRef = useRef<RTCPeerConnection | null>(null);
  const localStreamRef = useRef<MediaStream | null>(null);
  const remoteStreamRef = useRef<MediaStream | null>(null);
  const remoteVideoElemRef = useRef<HTMLVideoElement | null>(null);
  const localVideoElemRef = useRef<HTMLVideoElement | null>(null);
  const callTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const timeoutTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const qualityIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const stopToneRef = useRef<(() => void) | null>(null);

  // Enumerate cameras and audio outputs
  const refreshMediaDevices = useCallback(async () => {
    if (typeof navigator !== 'undefined' && navigator.mediaDevices?.enumerateDevices) {
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoInputs = devices.filter((d) => d.kind === 'videoinput');
        const audioOutputs = devices.filter((d) => d.kind === 'audiooutput');

        setAvailableCameras(videoInputs);
        setAudioOutputDevices(audioOutputs);

        if (videoInputs.length > 0 && !selectedCameraId) {
          setSelectedCameraId(videoInputs[0].deviceId);
        }
      } catch (e: any) {
        console.warn('Media devices enumeration error:', e);
      }
    }
  }, [selectedCameraId]);

  useEffect(() => {
    refreshMediaDevices();
    if (navigator.mediaDevices?.addEventListener) {
      navigator.mediaDevices.addEventListener('devicechange', refreshMediaDevices);
      return () => {
        navigator.mediaDevices.removeEventListener('devicechange', refreshMediaDevices);
      };
    }
  }, [refreshMediaDevices]);

  // Clean up all media, WebRTC peer, intervals, and tones
  const cleanupMediaAndPeer = useCallback(() => {
    if (stopToneRef.current) {
      stopToneRef.current();
      stopToneRef.current = null;
    }
    stopVibration();

    if (callTimerRef.current) {
      clearInterval(callTimerRef.current);
      callTimerRef.current = null;
    }
    if (timeoutTimerRef.current) {
      clearTimeout(timeoutTimerRef.current);
      timeoutTimerRef.current = null;
    }
    if (qualityIntervalRef.current) {
      clearInterval(qualityIntervalRef.current);
      qualityIntervalRef.current = null;
    }

    // Stop local video & audio tracks
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach((track) => track.stop());
      localStreamRef.current = null;
    }

    // Detach elements
    if (remoteVideoElemRef.current) {
      remoteVideoElemRef.current.srcObject = null;
    }
    if (localVideoElemRef.current) {
      localVideoElemRef.current.srcObject = null;
    }

    remoteStreamRef.current = null;

    // Close WebRTC peer connection
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close();
      peerConnectionRef.current = null;
    }
  }, []);

  // ── Acquire Full HD 1080p Video + High-Quality Audio Stream ──
  const getCameraAndMicStream = async (
    customCameraId: string | null = null,
    customFacingMode: string | null = null,
  ): Promise<MediaStream> => {
    const targetFacing = customFacingMode || facingMode;
    const targetCameraId = customCameraId || selectedCameraId;

    // Full HD 1080p Constraints
    const constraints1080p: MediaStreamConstraints = {
      video: targetCameraId
        ? {
            deviceId: { exact: targetCameraId },
            width: { ideal: 1920, min: 1280 },
            height: { ideal: 1080, min: 720 },
            frameRate: { ideal: 30, max: 60 },
          }
        : {
            facingMode: targetFacing,
            width: { ideal: 1920, min: 1280 },
            height: { ideal: 1080, min: 720 },
            frameRate: { ideal: 30, max: 60 },
          },
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
        sampleRate: 48000,
      },
    };

    try {
      const stream = await navigator.mediaDevices.getUserMedia(constraints1080p);
      localStreamRef.current = stream;
      setResolutionLabel('1080p Full HD');
      setIsAudioMuted(false);
      setIsVideoMuted(false);

      if (localVideoElemRef.current) {
        localVideoElemRef.current.srcObject = stream;
      }
      return stream;
    } catch (err1080p: any) {
      console.warn('1080p constraint fallback to standard HD:', err1080p);
      // Fallback to standard HD 720p / default
      try {
        const fallbackConstraints = {
          video: targetCameraId
            ? { deviceId: { exact: targetCameraId } }
            : { facingMode: targetFacing },
          audio: {
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: true,
          },
        };
        const fallbackStream = await navigator.mediaDevices.getUserMedia(fallbackConstraints);
        localStreamRef.current = fallbackStream;
        setResolutionLabel('720p HD (Adaptive)');
        setIsAudioMuted(false);
        setIsVideoMuted(false);

        if (localVideoElemRef.current) {
          localVideoElemRef.current.srcObject = fallbackStream;
        }
        return fallbackStream;
      } catch (fallbackErr: any) {
        const name = errName(fallbackErr);
        if (name === 'NotAllowedError' || name === 'PermissionDeniedError') {
          toast.error('Camera & Microphone permission denied. Please allow access.');
        } else if (name === 'NotFoundError') {
          toast.error('No camera or microphone found on your device.');
        } else {
          toast.error(`Media access failed: ${errMessage(fallbackErr)}`);
        }
        throw fallbackErr;
      }
    }
  };

  // ── Switch Camera (Front/Rear or Specific Device) ──
  const switchCamera = useCallback(async (deviceId: string) => {
    setSelectedCameraId(deviceId);
    const localStream = localStreamRef.current;
    if (!localStream) return;

    try {
      // Acquire new video track
      const newStream = await navigator.mediaDevices.getUserMedia({
        video: {
          deviceId: { exact: deviceId },
          width: { ideal: 1920, min: 1280 },
          height: { ideal: 1080, min: 720 },
        },
      });
      const newVideoTrack = newStream.getVideoTracks()[0];

      // Replace video track in WebRTC peer connection
      if (peerConnectionRef.current) {
        const sender = peerConnectionRef.current.getSenders().find((s) => s.track && s.track.kind === 'video');
        if (sender) {
          await sender.replaceTrack(newVideoTrack);
        }
      }

      // Stop old video track
      const oldVideoTrack = localStream.getVideoTracks()[0];
      if (oldVideoTrack) {
        oldVideoTrack.stop();
        localStream.removeTrack(oldVideoTrack);
      }

      // Replace in local stream
      localStream.addTrack(newVideoTrack);

      if (localVideoElemRef.current) {
        localVideoElemRef.current.srcObject = localStream;
      }
      toast.success('Camera switched');
    } catch (e: any) {
      console.warn('Switch camera error:', e);
      toast.error('Could not switch camera');
    }
  }, []);

  // Flip front / rear camera for mobile / tablet devices
  const flipFacingMode = useCallback(async () => {
    const nextFacing = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(nextFacing);

    const localStream = localStreamRef.current;
    if (!localStream) return;
    try {
      const newStream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: nextFacing,
          width: { ideal: 1920, min: 1280 },
          height: { ideal: 1080, min: 720 },
        },
      });
      const newVideoTrack = newStream.getVideoTracks()[0];

      if (peerConnectionRef.current) {
        const sender = peerConnectionRef.current.getSenders().find((s) => s.track && s.track.kind === 'video');
        if (sender) {
          await sender.replaceTrack(newVideoTrack);
        }
      }

      const oldVideoTrack = localStream.getVideoTracks()[0];
      if (oldVideoTrack) {
        oldVideoTrack.stop();
        localStream.removeTrack(oldVideoTrack);
      }

      localStream.addTrack(newVideoTrack);

      if (localVideoElemRef.current) {
        localVideoElemRef.current.srcObject = localStream;
      }
      toast.info(`Camera flipped to ${nextFacing === 'user' ? 'Front' : 'Rear'}`);
    } catch (e: any) {
      console.warn('Flip facing mode error:', e);
      toast.error('Could not flip camera');
    }
  }, [facingMode]);

  // ── Toggle Microphone ──
  const toggleAudioMute = useCallback(() => {
    if (localStreamRef.current) {
      const audioTrack = localStreamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        const muted = !audioTrack.enabled;
        setIsAudioMuted(muted);

        // Notify peer about mic status
        const s = getSocket();
        if (activePeer?.id) {
          s.emit('videocall:track_state', {
            to: activePeer.id,
            kind: 'audio',
            enabled: !muted,
          });
        }
        toast.info(muted ? 'Microphone Muted' : 'Microphone Unmuted');
      }
    }
  }, [activePeer]);

  // ── Toggle Camera On / Off ──
  const toggleVideoMute = useCallback(() => {
    if (localStreamRef.current) {
      const videoTrack = localStreamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        const videoDisabled = !videoTrack.enabled;
        setIsVideoMuted(videoDisabled);

        // Notify peer about video status
        const s = getSocket();
        if (activePeer?.id) {
          s.emit('videocall:track_state', {
            to: activePeer.id,
            kind: 'video',
            enabled: !videoDisabled,
          });
        }
        toast.info(videoDisabled ? 'Camera turned OFF' : 'Camera turned ON');
      }
    }
  }, [activePeer]);

  // ── Speaker Toggle & Audio Output Selection ──
  const toggleSpeaker = useCallback(() => {
    setIsSpeakerOn((prev) => {
      const next = !prev;
      if (remoteVideoElemRef.current) {
        remoteVideoElemRef.current.volume = next ? 1.0 : 0.4;
      }
      return next;
    });
  }, []);

  const setAudioOutput = useCallback(async (deviceId: string) => {
    setSelectedOutputId(deviceId);
    if (remoteVideoElemRef.current && typeof remoteVideoElemRef.current.setSinkId === 'function') {
      try {
        await remoteVideoElemRef.current.setSinkId(deviceId);
        toast.success('Audio output device updated');
      } catch (e: any) {
        console.warn('setSinkId error:', e);
      }
    }
  }, []);

  // ── Low-Light Video Enhancer Filter ──
  const toggleLowLightEnhancer = useCallback(() => {
    setIsLowLightEnhanced((prev) => {
      const next = !prev;
      toast.info(next ? 'Low-Light Enhancement enabled' : 'Normal Lighting mode');
      return next;
    });
  }, []);

  // ── Picture-in-Picture & Minimized Dock ──
  const togglePiP = useCallback(async () => {
    if (!remoteVideoElemRef.current) return;
    try {
      if (document.pictureInPictureElement) {
        await document.exitPictureInPicture();
      } else if (remoteVideoElemRef.current.requestPictureInPicture) {
        await remoteVideoElemRef.current.requestPictureInPicture();
      }
    } catch (e: any) {
      console.warn('PiP error:', e);
      // Fallback to in-app minimized dock
      setIsMinimized((prev) => !prev);
    }
  }, []);

  const toggleMinimize = useCallback(() => {
    setIsMinimized((prev) => !prev);
  }, []);

  const toggleFullScreen = useCallback(() => {
    setIsFullScreen((prev) => !prev);
  }, []);

  // ── Screen Sharing (Display Media) ──
  const toggleScreenShare = useCallback(async () => {
    const localStream = localStreamRef.current;
    if (!localStream) return;

    if (isScreenSharing) {
      // Revert back to webcam
      try {
        const camStream = await navigator.mediaDevices.getUserMedia({
          video: {
            width: { ideal: 1920, min: 1280 },
            height: { ideal: 1080, min: 720 },
          },
        });
        const camVideoTrack = camStream.getVideoTracks()[0];

        if (peerConnectionRef.current) {
          const sender = peerConnectionRef.current.getSenders().find((s) => s.track && s.track.kind === 'video');
          if (sender) await sender.replaceTrack(camVideoTrack);
        }

        const oldTrack = localStream.getVideoTracks()[0];
        if (oldTrack) {
          oldTrack.stop();
          localStream.removeTrack(oldTrack);
        }

        localStream.addTrack(camVideoTrack);

        if (localVideoElemRef.current) {
          localVideoElemRef.current.srcObject = localStream;
        }

        setIsScreenSharing(false);
        const s = getSocket();
        if (activePeer?.id) s.emit('videocall:screen_share', { to: activePeer.id, isSharing: false });
        toast.info('Screen sharing stopped — webcam restored');
      } catch (e: any) {
        console.warn('Revert webcam error:', e);
      }
    } else {
      // Start Screen Share
      try {
        const displayStream = await navigator.mediaDevices.getDisplayMedia({
          video: { cursor: 'always' } as MediaTrackConstraints,
          audio: false,
        });
        const screenTrack = displayStream.getVideoTracks()[0];

        if (peerConnectionRef.current) {
          const sender = peerConnectionRef.current.getSenders().find((s) => s.track && s.track.kind === 'video');
          if (sender) await sender.replaceTrack(screenTrack);
        }

        const oldTrack = localStream.getVideoTracks()[0];

        if (oldTrack) {
          oldTrack.stop();
          localStream.removeTrack(oldTrack);
        }
        localStream.addTrack(screenTrack);

        if (localVideoElemRef.current) {
          localVideoElemRef.current.srcObject = localStream;
        }

        setIsScreenSharing(true);
        const s = getSocket();
        if (activePeer?.id) s.emit('videocall:screen_share', { to: activePeer.id, isSharing: true });
        toast.success('Sharing screen with patient');

        // Handle user stopping share via browser native banner
        screenTrack.onended = async () => {
          try {
            const camStream = await navigator.mediaDevices.getUserMedia({
              video: { width: { ideal: 1920, min: 1280 }, height: { ideal: 1080, min: 720 } },
            });
            const camVideoTrack = camStream.getVideoTracks()[0];

            if (peerConnectionRef.current) {
              const sender = peerConnectionRef.current.getSenders().find((s) => s.track && s.track.kind === 'video');
              if (sender) await sender.replaceTrack(camVideoTrack);
            }

            localStream.removeTrack(screenTrack);
            localStream.addTrack(camVideoTrack);

            if (localVideoElemRef.current) {
              localVideoElemRef.current.srcObject = localStream;
            }
            setIsScreenSharing(false);
            if (activePeer?.id) s.emit('videocall:screen_share', { to: activePeer.id, isSharing: false });
            toast.info('Screen share ended');
          } catch (err: any) {}
        };
      } catch (err: any) {
        if (errName(err) !== 'NotAllowedError') {
          toast.error('Screen sharing could not be started');
        }
      }
    }
  }, [isScreenSharing, activePeer]);

  // ── In-Call Chat Messaging ──
  const sendInCallMessage = useCallback((text: string) => {
    if (!text || !text.trim() || !activePeer?.id) return;
    const msg = {
      senderId: String(user?._id),
      senderName: user?.name || 'Doctor',
      text: text.trim(),
      timestamp: Date.now(),
    };

    setInCallMessages((prev) => [...prev, msg]);

    const s = getSocket();
    s.emit('videocall:message', {
      to: activePeer.id,
      message: msg,
    });
  }, [activePeer, user]);

  // ── Save Clinical Consultation Notes ──
  const saveClinicalNotes = useCallback(async (notesText?: string) => {
    const textToSave = notesText != null ? notesText : clinicalNotes;
    if (!currentCallLogId) {
      toast.error('No active call record found');
      return;
    }
    try {
      await updateCallStatus(currentCallLogId, 'completed', callDuration, textToSave);
      toast.success('Clinical consultation notes saved to call record');
    } catch (e: any) {
      toast.error('Failed to save clinical notes');
    }
  }, [currentCallLogId, clinicalNotes, callDuration]);

  // ── Capture High-Res Medical Snapshot ──
  const captureSnapshot = useCallback(() => {
    const videoElem = remoteVideoElemRef.current;
    if (!videoElem || !videoElem.videoWidth) {
      toast.error('Remote video not available for snapshot');
      return;
    }

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoElem.videoWidth;
      canvas.height = videoElem.videoHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('2D canvas context unavailable');
      ctx.drawImage(videoElem, 0, 0, canvas.width, canvas.height);

      const dataUrl = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `clinical-snapshot-${activePeer?.name?.replace(/\s+/g, '_') || 'patient'}-${Date.now()}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast.success('High-resolution clinical snapshot captured and downloaded');
    } catch (e: any) {
      toast.error('Failed to capture snapshot');
    }
  }, [activePeer]);

  // ── Backend Call Log Helpers ──
  const logInitiate = async (receiverId: string, appointmentId: string | null) => {
    try {
      const res = await fetch('/api/calls/initiate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ receiverId, appointmentId, callType: 'video' }),
      });
      const json = await res.json();
      if (json.success && json.call?._id) {
        setCurrentCallLogId(json.call._id);
        return json.call._id;
      }
    } catch (e: any) {
      console.warn('Failed to log video call initiate:', e);
    }
    return null;
  };

  const updateCallStatus = async (
    callId: string | null,
    status: string,
    duration = 0,
    notes = '',
  ) => {
    if (!callId) return;
    try {
      await fetch(`/api/calls/${callId}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ status, duration, notes }),
      });
    } catch (e: any) {
      console.warn('Failed to update call status:', e);
    }
  };

  // ── WebRTC PeerConnection Setup ──
  const createPeerConnection = useCallback(
    (peerUserId: string | undefined, isOriginator: boolean): RTCPeerConnection => {
    const pc = new RTCPeerConnection(ICE_SERVERS);
    peerConnectionRef.current = pc;

    // Send ICE candidate to peer via dedicated videocall:ice event
    pc.onicecandidate = (event) => {
      if (event.candidate) {
        const s = getSocket();
        s.emit('videocall:ice', {
          to: peerUserId,
          candidate: event.candidate,
        });
      }
    };

    // Remote Audio/Video Track Received
    pc.ontrack = (event) => {
      const [stream] = event.streams;
      remoteStreamRef.current = stream;
      if (remoteVideoElemRef.current) {
        remoteVideoElemRef.current.srcObject = stream;
        remoteVideoElemRef.current.play().catch(() => {});
      }
    };

    // Network connection state & ICE monitor
    pc.oniceconnectionstatechange = () => {
      const state = pc.iceConnectionState;
      if (state === 'connected' || state === 'completed') {
        setNetworkQuality('1080p-fullhd');
      } else if (state === 'disconnected') {
        setNetworkQuality('poor');
        toast.warning('Network unstable, adapting video quality...');
      } else if (state === 'failed') {
        setNetworkQuality('reconnecting');
        if (isOriginator) {
          pc.restartIce();
        }
      }
    };

    // Periodic WebRTC quality check (Adaptive Bitrate & Latency)
    if (qualityIntervalRef.current) clearInterval(qualityIntervalRef.current);
    qualityIntervalRef.current = setInterval(async () => {
      if (pc && pc.connectionState === 'connected') {
        try {
          const stats = await pc.getStats();
          stats.forEach((report) => {
            // `RTCStats` is a minimal base type; candidate-pair fields are not on it.
            const pair = report as RTCStats & {
              state?: string;
              currentRoundTripTime?: number;
            };
            if (report.type === 'candidate-pair' && pair.state === 'succeeded') {
              const rtt = pair.currentRoundTripTime;
              if (rtt != null) {
                if (rtt < 0.12) {
                  setNetworkQuality('1080p-fullhd');
                  setResolutionLabel('1080p Full HD');
                } else if (rtt < 0.28) {
                  setNetworkQuality('good');
                  setResolutionLabel('720p HD');
                } else if (rtt < 0.5) {
                  setNetworkQuality('fair');
                  setResolutionLabel('480p Adaptive');
                } else {
                  setNetworkQuality('poor');
                  setResolutionLabel('Low Bandwidth');
                }
              }
            }
          });
        } catch (e: any) {}
      }
    }, 3500);

    return pc;
    },
    [],
  );

  // ── INITIATE OUTGOING VIDEO CALL ──
  const initiateVideoCall = useCallback(
    async (recipient: Partial<VideoPeer> & { _id?: string }, appointmentId: string | null = null) => {
    if (!recipient || (!recipient.id && !recipient._id)) {
      toast.error('Recipient information missing');
      return;
    }
    const recipientId = String(recipient.id || recipient._id);

    if (callState !== 'idle') {
      toast.error('You already have an active call in progress');
      return;
    }

    try {
      // 1. Acquire Full HD Camera & Mic
      const stream = await getCameraAndMicStream();

      // 2. Setup call state
      setActivePeer({
        id: recipientId,
        name: recipient.name || 'Patient',
        avatar: recipient.avatar || '',
        role: recipient.role || 'patient',
        phone: recipient.phone || '',
        appointmentId,
      });
      setIsCaller(true);
      setCallState('calling');
      setIsMinimized(false);
      setCallDuration(0);

      // 3. Play ringback tone
      stopToneRef.current = playRingbackTone();

      // 4. Log in database
      const logId = await logInitiate(recipientId, appointmentId);

      // 5. Send Socket.IO invite on dedicated videocall:invite event
      const s = getSocket();
      s.emit('videocall:invite', {
        to: recipientId,
        caller: {
          id: String(user?._id),
          name: user?.name || 'Doctor',
          avatar: user?.avatar || '',
          role: user?.role || 'doctor',
          phone: user?.phone || '',
        },
        callLogId: logId,
        appointmentId,
        timestamp: Date.now(),
      });

      // 6. Timeout after 35s if no answer
      timeoutTimerRef.current = setTimeout(() => {
        toast.warning('No answer from patient');
        s.emit('videocall:timeout', { to: recipientId, callLogId: logId });
        updateCallStatus(logId, 'missed', 0, 'No answer / timeout');
        playEndSound();
        setCallState('timeout');
        setTimeout(() => {
          cleanupMediaAndPeer();
          setCallState('idle');
          setActivePeer(null);
        }, 2000);
      }, CALL_TIMEOUT_SECONDS * 1000);
    } catch (err: any) {
      cleanupMediaAndPeer();
      setCallState('idle');
      setActivePeer(null);
    }
    },
    [callState, user, cleanupMediaAndPeer],
  );

  // ── ACCEPT INCOMING VIDEO CALL ──
  const acceptVideoCall = useCallback(async () => {
    if (!activePeer) return;

    if (timeoutTimerRef.current) {
      clearTimeout(timeoutTimerRef.current);
      timeoutTimerRef.current = null;
    }
    if (stopToneRef.current) {
      stopToneRef.current();
      stopToneRef.current = null;
    }
    stopVibration();

    try {
      setCallState('connecting');

      // 1. Acquire Full HD stream
      const stream = await getCameraAndMicStream();

      // 2. Create WebRTC Peer Connection
      const pc = createPeerConnection(activePeer.id, false);

      // Add local audio and video tracks
      stream.getTracks().forEach((track) => pc.addTrack(track, stream));

      // 3. Notify caller on dedicated videocall:accept
      const s = getSocket();
      s.emit('videocall:accept', {
        to: activePeer.id,
        callLogId: currentCallLogId,
      });

      if (currentCallLogId) {
        updateCallStatus(currentCallLogId, 'completed');
      }
    } catch (err: any) {
      toast.error('Failed to start camera for video call');
      rejectVideoCall();
    }
  }, [activePeer, currentCallLogId, createPeerConnection]);

  // ── REJECT INCOMING VIDEO CALL ──
  const rejectVideoCall = useCallback(() => {
    if (activePeer) {
      const s = getSocket();
      s.emit('videocall:reject', {
        to: activePeer.id,
        callLogId: currentCallLogId,
        reason: 'Declined by recipient',
      });
      if (currentCallLogId) {
        updateCallStatus(currentCallLogId, 'rejected', 0);
      }
    }
    playEndSound();
    cleanupMediaAndPeer();
    setCallState('ended');
    setTimeout(() => {
      setCallState('idle');
      setActivePeer(null);
      setCurrentCallLogId(null);
    }, 1200);
  }, [activePeer, currentCallLogId, cleanupMediaAndPeer]);

  // ── END ACTIVE VIDEO CALL ──
  const endVideoCall = useCallback(() => {
    if (activePeer) {
      const s = getSocket();
      if (callState === 'calling' || callState === 'ringing') {
        s.emit('videocall:cancel', { to: activePeer.id, callLogId: currentCallLogId });
        if (currentCallLogId) {
          updateCallStatus(currentCallLogId, 'cancelled', 0);
        }
      } else {
        s.emit('videocall:end', { to: activePeer.id, callLogId: currentCallLogId, duration: callDuration });
        if (currentCallLogId) {
          updateCallStatus(currentCallLogId, 'completed', callDuration);
        }
      }
    }

    playEndSound();
    cleanupMediaAndPeer();
    setCallState('ended');
    setTimeout(() => {
      setCallState('idle');
      setActivePeer(null);
      setCurrentCallLogId(null);
      setCallDuration(0);
      setIsMinimized(false);
      setIsFullScreen(false);
    }, 1200);
  }, [activePeer, callState, currentCallLogId, callDuration, cleanupMediaAndPeer]);

  // ── Dedicated Socket.IO Video Call Signaling Listeners ──
  useEffect(() => {
    const s = getSocket();
    if (!s) return;

    // Incoming Video Call Invite
    const handleVideoInvite = (data: VideoCallSignalEvent) => {
      const callerId = String(data.caller?.id || data.from);

      // If user is already on a call, emit busy
      if (callState !== 'idle') {
        s.emit('videocall:busy', { to: callerId, reason: 'Line Busy' });
        return;
      }

      setActivePeer({
        id: callerId,
        name: data.caller?.name || 'Patient',
        avatar: data.caller?.avatar || '',
        role: data.caller?.role || 'patient',
        phone: data.caller?.phone || '',
        appointmentId: data.appointmentId || null,
      });
      setCurrentCallLogId(data.callLogId || null);
      setIsCaller(false);
      setCallState('ringing');
      setIsMinimized(false);

      stopToneRef.current = playRingtone();
      triggerVibration();

      if (timeoutTimerRef.current) clearTimeout(timeoutTimerRef.current);
      timeoutTimerRef.current = setTimeout(() => {
        playEndSound();
        cleanupMediaAndPeer();
        setCallState('missed');
        setTimeout(() => {
          setCallState('idle');
          setActivePeer(null);
        }, 1500);
      }, CALL_TIMEOUT_SECONDS * 1000);

      s.emit('videocall:ringing', { to: callerId });
    };

    const handleVideoRinging = () => {
      if (callState === 'calling') {
        setCallState('ringing');
      }
    };

    // Caller initiates WebRTC offer once peer accepts
    const handleVideoAccept = async () => {
      if (timeoutTimerRef.current) clearTimeout(timeoutTimerRef.current);
      if (stopToneRef.current) {
        stopToneRef.current();
        stopToneRef.current = null;
      }

      setCallState('connecting');

      try {
        const pc = createPeerConnection(activePeer?.id, true);

        const ls = localStreamRef.current;
        if (ls) {
          ls.getTracks().forEach((track) => pc.addTrack(track, ls));
        }

        const offer = await pc.createOffer({
          offerToReceiveAudio: true,
          offerToReceiveVideo: true,
        });
        await pc.setLocalDescription(offer);

        s.emit('videocall:offer', {
          to: activePeer?.id,
          offer,
        });
      } catch (e: any) {
        console.warn('Error creating WebRTC video offer:', e);
      }
    };

    // Recipient receives video offer -> responds with video answer
    const handleVideoOffer = async (data: VideoCallSignalEvent) => {
      try {
        let pc = peerConnectionRef.current;
        if (!pc) {
          pc = createPeerConnection(activePeer?.id, false);
          const ls = localStreamRef.current;
          if (ls) {
            ls.getTracks().forEach((track) => pc!.addTrack(track, ls));
          }
        }

        await pc.setRemoteDescription(new RTCSessionDescription(data.offer!));
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);

        s.emit('videocall:answer', {
          to: activePeer?.id,
          answer,
        });

        playConnectSound();
        setCallState('connected');

        if (callTimerRef.current) clearInterval(callTimerRef.current);
        callTimerRef.current = setInterval(() => {
          setCallDuration((prev) => prev + 1);
        }, 1000);
      } catch (e: any) {
        console.warn('Error handling WebRTC video offer:', e);
      }
    };

    // Caller receives video answer -> media flowing
    const handleVideoAnswer = async (data: VideoCallSignalEvent) => {
      try {
        const pc = peerConnectionRef.current;
        if (pc) {
          await pc.setRemoteDescription(new RTCSessionDescription(data.answer!));

          playConnectSound();
          setCallState('connected');

          if (callTimerRef.current) clearInterval(callTimerRef.current);
          callTimerRef.current = setInterval(() => {
            setCallDuration((prev) => prev + 1);
          }, 1000);
        }
      } catch (e: any) {
        console.warn('Error setting WebRTC video answer:', e);
      }
    };

    const handleVideoIce = async (data: VideoCallSignalEvent) => {
      try {
        const pc = peerConnectionRef.current;
        if (pc && data.candidate) {
          await pc.addIceCandidate(new RTCIceCandidate(data.candidate));
        }
      } catch (e: any) {
        console.warn('Error adding video ICE candidate:', e);
      }
    };

    const handleTrackState = (data: VideoCallSignalEvent) => {
      if (data.kind === 'video') {
        setIsRemoteVideoMuted(!data.enabled);
      } else if (data.kind === 'audio') {
        setIsRemoteAudioMuted(!data.enabled);
      }
    };

    const handleVideoReject = () => {
      toast.error('Video call declined');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('rejected');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 1500);
    };

    const handleVideoCancel = () => {
      toast.info('Caller hung up');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('ended');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 1500);
    };

    const handleVideoEnd = () => {
      toast.info('Video consultation ended');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('ended');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
        setCallDuration(0);
        setIsMinimized(false);
      }, 1500);
    };

    const handleVideoBusy = () => {
      toast.warning('Patient is currently on another call');
      playBusySound();
      cleanupMediaAndPeer();
      setCallState('busy');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 2000);
    };

    const handleVideoTimeout = () => {
      toast.warning('No answer');
      playEndSound();
      cleanupMediaAndPeer();
      setCallState('timeout');
      setTimeout(() => {
        setCallState('idle');
        setActivePeer(null);
      }, 2000);
    };

    const handleIncomingMessage = (data: VideoCallSignalEvent) => {
      if (data?.message) {
        setInCallMessages((prev) => [...prev, data.message!]);
        toast.info(
          `Message from ${data.message.senderName || 'Patient'}: ${data.message.text?.slice(0, 30) ?? ''}...`,
        );
      }
    };

    s.on('videocall:invite', handleVideoInvite);
    s.on('videocall:ringing', handleVideoRinging);
    s.on('videocall:accept', handleVideoAccept);
    s.on('videocall:offer', handleVideoOffer);
    s.on('videocall:answer', handleVideoAnswer);
    s.on('videocall:ice', handleVideoIce);
    s.on('videocall:track_state', handleTrackState);
    s.on('videocall:message', handleIncomingMessage);
    s.on('videocall:reject', handleVideoReject);
    s.on('videocall:cancel', handleVideoCancel);
    s.on('videocall:end', handleVideoEnd);
    s.on('videocall:busy', handleVideoBusy);
    s.on('videocall:timeout', handleVideoTimeout);

    return () => {
      s.off('videocall:invite', handleVideoInvite);
      s.off('videocall:ringing', handleVideoRinging);
      s.off('videocall:accept', handleVideoAccept);
      s.off('videocall:offer', handleVideoOffer);
      s.off('videocall:answer', handleVideoAnswer);
      s.off('videocall:ice', handleVideoIce);
      s.off('videocall:track_state', handleTrackState);
      s.off('videocall:message', handleIncomingMessage);
      s.off('videocall:reject', handleVideoReject);
      s.off('videocall:cancel', handleVideoCancel);
      s.off('videocall:end', handleVideoEnd);
      s.off('videocall:busy', handleVideoBusy);
      s.off('videocall:timeout', handleVideoTimeout);
    };
  }, [callState, activePeer, createPeerConnection, cleanupMediaAndPeer]);

  return (
    <VideoCallContext.Provider
      value={{
        callState,
        activePeer,
        isCaller,
        isAudioMuted,
        isVideoMuted,
        isRemoteVideoMuted,
        isRemoteAudioMuted,
        isSpeakerOn,
        isLowLightEnhanced,
        isScreenSharing,
        inCallMessages,
        clinicalNotes,
        availableCameras,
        selectedCameraId,
        facingMode,
        audioOutputDevices,
        selectedOutputId,
        callDuration,
        networkQuality,
        resolutionLabel,
        isMinimized,
        isFullScreen,
        localStream: localStreamRef.current,
        remoteStream: remoteStreamRef.current,
        remoteVideoElemRef,
        localVideoElemRef,
        initiateVideoCall,
        acceptVideoCall,
        rejectVideoCall,
        endVideoCall,
        toggleAudioMute,
        toggleVideoMute,
        switchCamera,
        flipFacingMode,
        toggleSpeaker,
        setAudioOutput,
        toggleLowLightEnhancer,
        toggleScreenShare,
        sendInCallMessage,
        setClinicalNotes,
        saveClinicalNotes,
        captureSnapshot,
        togglePiP,
        toggleMinimize,
        toggleFullScreen,
      }}
    >
      {children}
    </VideoCallContext.Provider>
  );
}

export function useVideoCall() {
  const context = useContext(VideoCallContext);
  if (!context) {
    throw new Error('useVideoCall must be used within a VideoCallProvider');
  }
  return context;
}

import { useEffect, useRef } from 'react';
import { api } from '@/lib/api';

export function useAmbulanceGps(active: boolean) {
  const last = useRef(0);
  const wake = useRef<any>(null);

  useEffect(() => {
    if (!active || !('geolocation' in navigator)) return;

    (async () => { try { wake.current = await (navigator as any).wakeLock?.request('screen'); } catch {} })();

    const id = navigator.geolocation.watchPosition(
      (pos) => {
        const now = Date.now();
        if (now - last.current < 5000) return;
        last.current = now;
        api.put('/ambulance/me/location', { lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy }).catch(() => {});
      },
      (err) => console.warn('[GPS]', err.message),
      { enableHighAccuracy: true, maximumAge: 3000, timeout: 15000 },
    );

    return () => { navigator.geolocation.clearWatch(id); try { wake.current?.release?.(); } catch {} };
  }, [active]);
}

import { useEffect, useRef, useState } from 'react';
import { getSocket } from '@/lib/socket';
import { api } from '@/lib/api';

export function useDoctorEmergencyGps(isDutyActive: boolean, activeRequestId?: string | null) {
  const [gpsStatus, setGpsStatus] = useState<string>('Standby');
  const [lastCoords, setLastCoords] = useState<{ lat: number; lng: number } | null>(null);
  const watchIdRef = useRef<number | null>(null);

  useEffect(() => {
    if (!isDutyActive) {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
      setGpsStatus('Offline');
      return;
    }

    if (!navigator.geolocation) {
      setGpsStatus('GPS Unsupported');
      return;
    }

    setGpsStatus('Acquiring GPS...');

    watchIdRef.current = navigator.geolocation.watchPosition(
      async (pos) => {
        const { latitude: lat, longitude: lng, accuracy, heading, speed } = pos.coords;
        setLastCoords({ lat, lng });
        setGpsStatus(`Locked (±${Math.round(accuracy)}m)`);

        try {
          const socket = getSocket();
          // 1. Broadcast beacon via Socket to server
          if (socket?.connected) {
            socket.emit('doctor:emergency_location', {
              lat,
              lng,
              accuracy,
              heading: heading || 0,
              speed: speed || 0,
              activeRequestId: activeRequestId || null,
            });

            // 2. If actively en route to patient, send direct telemetry update
            if (activeRequestId) {
              socket.emit('stream_doctor_location', {
                requestId: activeRequestId,
                lat,
                lng,
                heading: heading || 0,
                speed: speed || 0,
              });
            }
          }

          // 3. Fallback REST telemetry update if actively en route
          if (activeRequestId) {
            api.put(`/emergency-doctor/${activeRequestId}/telemetry`, {
              coordinates: [lng, lat],
              heading: heading || 0,
              speed: speed || 0,
            }).catch(() => {});
          }
        } catch (err: any) {
          console.debug('Telemetry ping skipped:', err);
        }
      },
      (err) => {
        setGpsStatus(`GPS Notice: ${err.message}`);
      },
      {
        enableHighAccuracy: true,
        maximumAge: 5000,
        timeout: 10000,
      }
    );

    return () => {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    };
  }, [isDutyActive, activeRequestId]);

  return { gpsStatus, lastCoords };
}

/**
 * Centralized appointment mode categorization helper
 *
 * 1. Online: chat, video, audio, voice, call, telemedicine
 * 2. Home Visit: home_visit, home
 * 3. In-Clinic / Hospital Offline: physical in-person facility consultation
 */

export function isOnlineAppointment(appt: any): boolean {
  if (!appt) return false;
  const mode = (appt.appointmentMode || '').toLowerCase();
  const type = (appt.type || '').toLowerCase();
  const intakeMode = (
    appt.preConsultationDetails?.appointmentMode ||
    appt.preConsultationDetails?.mode ||
    ''
  ).toLowerCase();

  return (
    mode === 'chat' ||
    mode === 'video' ||
    mode === 'voice' ||
    mode === 'audio' ||
    mode === 'call' ||
    type.includes('chat') ||
    type.includes('video') ||
    type.includes('voice') ||
    type.includes('audio') ||
    type.includes('call') ||
    type === 'telemedicine' ||
    intakeMode === 'chat' ||
    intakeMode === 'video' ||
    intakeMode === 'voice' ||
    intakeMode === 'audio' ||
    intakeMode === 'call'
  );
}

export function isHomeVisitAppointment(appt: any): boolean {
  if (!appt) return false;
  const mode = (appt.appointmentMode || '').toLowerCase();
  const type = (appt.type || '').toLowerCase();
  const intakeMode = (
    appt.preConsultationDetails?.appointmentMode ||
    appt.preConsultationDetails?.mode ||
    ''
  ).toLowerCase();

  return (
    mode === 'home_visit' ||
    mode === 'home' ||
    type === 'home_visit' ||
    type === 'home' ||
    intakeMode === 'home_visit' ||
    intakeMode === 'home'
  );
}

export function isOfflineClinicAppointment(appt: any): boolean {
  if (!appt) return false;
  return !isOnlineAppointment(appt) && !isHomeVisitAppointment(appt);
}

export function isOfflineAppointment(appt: any): boolean {
  if (!appt) return false;
  return !isOnlineAppointment(appt);
}

