    case 'MedicalWebPage':
      return JSON.stringify(
        {
          '@context': baseContext,
          '@type': 'MedicalWebPage',
          headline: entityData.title || 'Healthcare Guidance',
          url: entityData.url || 'https://findmedi.in/health',
          reviewedBy: {
