          publisher: {
            '@type': 'Organization',
            name: 'FindMedi Health Platform',
            url: 'https://findmedi.in',
          },
        },
        null,
        2
      );

    case 'FAQPage':
      return JSON.stringify(
        {
          '@context': baseContext,
          '@type': 'FAQPage',
          mainEntity: (entityData.faqs || []).map((faq: { question: string; answer: string }) => ({
            '@type': 'Question',
