export function maskPatientPii(patient: PatientData = {}): PatientData {
  if (!patient || typeof patient !== 'object') return {};

  const maskName = (name?: string) => {
    if (!name || typeof name !== 'string') return '';
    const parts = name.trim().split(/\s+/);
    if (parts.length === 1) {
      const p = parts[0];
      return p.length <= 2 ? p : `${p.slice(0, 2)}***`;
    }
    return parts
      .map((part, idx) => (idx === 0 ? part : `${part.charAt(0)}***`))
      .join(' ');
  };

  const maskPhone = (phone?: string) => {
    if (!phone || typeof phone !== 'string') return '';
    const cleaned = phone.replace(/[^\d+]/g, '');
    if (cleaned.length < 8) return '****';
    const last3 = cleaned.slice(-3);
    const prefix = cleaned.startsWith('+') ? cleaned.slice(0, 3) : cleaned.slice(0, 2);
    return `${prefix}*****${last3}`;
  };

  const maskEmail = (email?: string) => {
    if (!email || typeof email !== 'string' || !email.includes('@')) return '';
    const [user, domain] = email.split('@');
    if (user.length <= 2) return `*@${domain}`;
    return `${user.charAt(0)}***${user.charAt(user.length - 1)}@${domain}`;
  };

  const maskAddress = (addr?: string) => {
    if (!addr || typeof addr !== 'string') return '';
    const parts = addr.split(',').map((s) => s.trim()).filter(Boolean);
    if (parts.length <= 1) return '***';
    const cityOrPin = parts[parts.length - 1];
    return `***, ${cityOrPin}`;
  };

  return {
    ...patient,
    name: maskName(patient.name),
    phone: maskPhone(patient.phone),
    email: maskEmail(patient.email),
    address: maskAddress(patient.address),
    isMasked: true,
  };
}

export interface BreakGlassValidationResult {
  valid: boolean;
  errors: string[];
  requiresDualApproval: boolean;
  maxDurationMinutes: number;
}

export function validateBreakGlassRequest(request: {
  requesterId?: string;
  reasonCode?: string;
  justification?: string;
  caseOrTicketId?: string;
  durationMinutes?: number;
  isSensitiveCategory?: boolean;
  approverIds?: string[];
} = {}): BreakGlassValidationResult {
  const errors: string[] = [];
  const {
    requesterId,
    reasonCode,
    justification,
    caseOrTicketId,
    durationMinutes,
    isSensitiveCategory,
    approverIds = [],
  } = request;

  if (!requesterId) {
    errors.push('Requester ID is mandatory.');
  }

  const validReasons = BREAK_GLASS_POLICY.reasons.map((r) => r.code);
  if (!reasonCode || !validReasons.includes(reasonCode)) {
    errors.push(`Invalid reason code. Must be one of: ${validReasons.join(', ')}.`);
  }

  if (!justification || typeof justification !== 'string' || justification.trim().length < BREAK_GLASS_POLICY.minJustificationLength) {
    errors.push(`Justification must be at least ${BREAK_GLASS_POLICY.minJustificationLength} characters explaining the emergency.`);
  }

  if (!caseOrTicketId || typeof caseOrTicketId !== 'string' || !caseOrTicketId.trim()) {
    errors.push('Legal case number, FIR ID, or customer dispute ticket ID is mandatory.');
  }

  const duration = Number(durationMinutes);
  if (!duration || duration <= 0 || duration > BREAK_GLASS_POLICY.maxDurationMinutes) {
    errors.push(`Duration must be between 1 and ${BREAK_GLASS_POLICY.maxDurationMinutes} minutes.`);
  }

  const matchedReason = BREAK_GLASS_POLICY.reasons.find((r) => r.code === reasonCode);
  const requiresDual = isSensitiveCategory || (matchedReason && matchedReason.requiresDualApproval);

  if (requiresDual) {
    if (!Array.isArray(approverIds) || approverIds.length < 2) {
      errors.push('Dual approval required: At least 2 independent authorized approvers must sign off for sensitive or high-risk records.');
    }
    if (approverIds.includes(requesterId!)) {
      errors.push('Self-approval prohibited: Requester cannot act as one of the approvers.');
    }
  } else {
    if (!Array.isArray(approverIds) || approverIds.length < 1) {
      errors.push('At least 1 authorized approver sign-off is required.');
    }
    if (approverIds.includes(requesterId!)) {
      errors.push('Self-approval prohibited: Requester cannot act as an approver.');
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    requiresDualApproval: !!requiresDual,
    maxDurationMinutes: BREAK_GLASS_POLICY.maxDurationMinutes,
  };
}

// Document 17 (rolesmd/18.md) — the ONLY way to send analytics from the client.
// Repo convention (eslint note, not a plugin rule): NEVER call
// `posthog.capture` / `posthog.identify` directly anywhere else — always go
// through `track()` / `identifyUser()` here so the event allowlist, the PII
// detector and the consent gate apply. Direct SDK calls bypass PHI scrubbing
// and will be rejected in review.
//
// Pipeline: allowlist schema (zod, unknown props stripped) → PII detector
// (phone/email/Aadhaar/PAN/Card patterns rejected) → consent gate (localStorage)
// → posthog with pseudonymous distinct_id (hashed, no raw PII).
/* eslint-disable no-restricted-syntax -- this module is the single sanctioned
   posthog.capture/identify call-site; ban direct SDK use everywhere else. */
import posthog from 'posthog-js';
import { z } from 'zod';

export const CONSENT_KEY = 'fm_analytics_consent';
const SESSION_KEY = 'fm_analytics_session';

// --- Sensitive Categories Mask (Count-only in 3rd-party analytics) -----------
export const SENSITIVE_CATEGORIES_MASK = [
  'mental_health',
  'psychiatry',
  'psychology',
  'sexual_health',
  'de_addiction',
  'rehabilitation',
  'oncology',
  'fertility',
  'ivf',
  'hiv_std',
  'palliative',
  'maternity_termination',
];

export function isSensitiveCategory(categoryCode?: string): boolean {
  if (!categoryCode) return false;
  return SENSITIVE_CATEGORIES_MASK.includes(categoryCode.toLowerCase().trim());
}

// --- PII detector -----------------------------------------------------------
const PHONE_RE = /(?:^|[\s,;])(?:\+?91[\s-]?)?[6-9]\d{9}(?:$|[\s,;])/;
const EMAIL_RE = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;
// Aadhaar: 12 digits starting 2-9, spaced or contiguous. PAN: 5 letters 4 digits 1 letter.
const AADHAAR_RE = /\b[2-9]\d{3}[\s-]?\d{4}[\s-]?\d{4}\b/;
const PAN_RE = /\b[A-Z]{5}[0-9]{4}[A-Z]\b/;
const CARD_RE = /\b(?:\d{4}[ -]?){3}\d{4}\b/;

export function looksLikePii(value: unknown): boolean {
  if (typeof value !== 'string') return false;
  if (value.length > 250) return true; // free text never belongs in analytics
  return (
    PHONE_RE.test(value) ||
    EMAIL_RE.test(value) ||
    AADHAAR_RE.test(value.replace(/[\s-]/g, '')) ||
    PAN_RE.test(value) ||
    CARD_RE.test(value)
  );
}

// --- Pseudonymous identity (HMAC stub) --------------------------------------
// distinct_id = salted hash of the user id. Raw userId/phone/email never
// leaves the browser. cyrb53-style sync hash: unlinkability is what analytics
// needs, not secrecy (mirrors services/featureFlags pseudonymize).
export function hashDistinctId(userId: string): string {
  const raw = `findmedi-analytics|${String(userId || '')}`;
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < raw.length; i += 1) {
    const ch = raw.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return `fm-${(h2 >>> 0).toString(16).padStart(8, '0')}${(h1 >>> 0).toString(16).padStart(8, '0')}`;
}

function getSessionId(): string {
  try {
    let sid = sessionStorage.getItem(SESSION_KEY);
    if (!sid) {
      sid = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
      sessionStorage.setItem(SESSION_KEY, sid);
    }
    return sid;
  } catch {
    return 'noscript';
  }
}

// --- Consent gate ------------------------------------------------------------
export function hasAnalyticsConsent(): boolean {
  try {
    return localStorage.getItem(CONSENT_KEY) === 'granted';
  } catch {
    return false;
  }
}

export function setAnalyticsConsent(granted: boolean): void {
  try {
    localStorage.setItem(CONSENT_KEY, granted ? 'granted' : 'denied');
  } catch {
    // storage unavailable — consent stays denied (fail closed)
  }
}

