  </Sentry.ErrorBoundary>
);

// ─── Vite HMR boundary for the root App ────────────────────────────────────
if ((import.meta as any).hot) {
  (import.meta as any).hot.accept("./App", (newModule: any) => {
    if (newModule?.default) {
      root.render(<newModule.default />);
    }
  });
}

