                  </span>
                </summary>
                <div className="px-6 pb-5 pt-0">
                  <div className="h-px bg-gradient-to-r from-primary/30 via-secondary/30 to-transparent mb-4" />
                  <p className="text-sm text-muted-foreground leading-relaxed">{f.a}</p>
                </div>
              </details>
            ))}
          </div>
        </div>

        {/* Crisis */}
        <div className="bg-gradient-to-br from-red-500/10 to-rose-500/5 border border-red-500/20 rounded-2xl p-6 md:p-8">
          <div className="flex flex-col md:flex-row gap-4 md:items-center">
            <div className="flex-1">
              <h3 className="text-lg font-bold mb-1 text-foreground">In crisis? You are not alone.</h3>
              <p className="text-sm text-muted-foreground">If you or someone you know is in immediate distress, reach out to a 24/7 helpline. Therapy is ongoing care and emergencies need urgent support.</p>
            </div>
            <Button onClick={() => navigate("/mind/resources")} className="bg-red-500 hover:bg-red-400 text-white rounded-xl px-6 h-10 font-medium shrink-0">
              Get crisis help <MessageCircle className="ml-1.5 h-4 w-4" />
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
};

