          </div>
        </div>
        <Footer />
      </div>
    );
  }

  if (!counsellor) {
    return (
      <div className="min-h-screen bg-background text-foreground theme-findmedi">
        <Navigation />
        <div className="text-center py-20">
          <h3 className="text-lg font-semibold">Counsellor not found</h3>
