function CounsellorAssignments({ patients = [] }: Unmodelled) {
  const { toast } = useToast();
  const [assignments, setAssignments] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ userId: "", title: "", description: "", category: "other", dueDate: "" });

  const load = useCallback(async () => {
    try {
      const { data } = await api.get("/api/assignments");
      setAssignments(Array.isArray(data) ? data : []);
    } catch { setAssignments([]); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  async function save() {
    if (!form.userId || !form.title.trim()) {
      toast({ variant: "destructive", title: "Patient and title required" });
      return;
    }
    try {
      await api.post("/api/assignments", {
        userId: form.userId,
        title: form.title.trim(),
        description: form.description,
        category: form.category,
        dueDate: form.dueDate || undefined,
      });
      toast({ title: "Assignment created" });
      setShowForm(false);
      setForm({ userId: "", title: "", description: "", category: "other", dueDate: "" });
      load();
    } catch (e: any) { toast({ variant: "destructive", title: "Failed to save assignment", description: e?.response?.data?.error || e.message }); }
  }

  return (
    <Card className="glass-card" data-assignments-card>
      <CardHeader>
        <CardTitle className="flex items-center justify-between gap-2">
          <span className="flex items-center gap-2">
