                          const unavailable = (selectedCounsellor.unavailableDates || []).includes(date.value);
                          const isWeekend = date.weekday === "SAT" || date.weekday === "SUN";
                          const isToday = new Date().toISOString().slice(0, 10) === date.value;
                          return (
                            <button
                              key={date.value}
                              type="button"
                              disabled={unavailable}
