                return (
                  <button
                    key={date.value}
                    type="button"
                    onClick={() => setBooking(prev => ({ ...prev, date: date.value }))}
                    className={`relative rounded-xl border py-2.5 text-center transition-all duration-200 ${
                      booking.date === date.value
