  // Settings State
  const [settings, setSettings] = useState({
    theme: 'system',
    language: 'en',
    fontSize: 'medium',
    enterToSend: true,
    chatHistory: true,
    memory: true,
    notifications: true,
    voice: 'default',
    mic: 'default',
    speaker: 'default',
