function renderStars(rating: number, size = 'w-4 h-4') {
  return [1, 2, 3, 4, 5].map((s) => (
    <Star
      key={s}
      className={cn(
        size,
        s <= Math.round(rating)
          ? 'text-yellow-400 fill-yellow-400'
          : 'text-slate-300 fill-slate-200 dark:text-slate-600 dark:fill-slate-700'
      )}
    />
  ));
}

