import PatientBanner from '@/components/clinical/PatientBanner';
import type { Unmodelled } from '@/lib/apiTypes';

const statusCls: Unmodelled = {
  Paid:    'bg-success/10 text-success',
  Pending: 'bg-warning/10 text-warning',
  Overdue: 'bg-destructive/10 text-destructive',
  Partial: 'bg-info/10 text-info',
};
const STATUSES = ['All','Paid','Pending','Overdue','Partial'];
const empty = { patient:'', doctor:'', service:'', amount:'', discount:'', paid:'0', status:'Pending', date:'', dueDate:'' };

export default function Billing() {
  const qc: Unmodelled = useQueryClient();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState(empty);
  // File 22 P0-1: over-policy discount approval — server returns 409 with the
  // request id; the biller retries the same invoice once it is approved.
  const [approval, setApproval] = useState<{ id: string; roles: string[] } | null>(null);
  const [selectedBill, setSelectedBill] = useState<any | null>(null);
  // File 22 P1-14: split collection legs.
  const [legs, setLegs] = useState([{ mode: 'Cash', amount: '', txnRef: '' }]);

  const { data, isLoading } = useQuery({
    queryKey: ['billing', search, statusFilter],
    queryFn: () => api.getBilling({ ...(search && { search }), ...(statusFilter !== 'All' && { status: statusFilter }) }),
    select: (res) => ({ bills: res?.data || [], summary: res?.summary || { total: 0, paid: 0 } }),
  });
  const { bills, summary } = data || { bills:[], summary:{total:0,paid:0} };

  const createMut = useMutation({
    mutationFn: api.createBill,
    onSuccess: () => { qc.invalidateQueries(['billing']); setModal(false); setForm(empty); setApproval(null); },
    onError: (err: any) => {
      const data = err?.response?.data;
      if (data?.code === 'NEEDS_APPROVAL' && data?.approvalId) {
        setApproval({ id: data.approvalId, roles: data.approverRoles || [] });
        toast.warning(`Discount needs approval (${(data.approverRoles || []).join('/')}). Request ${data.approvalId} raised — submit again once approved.`);
      } else {
        toast.error(data?.message || err?.message || 'Could not create invoice');
      }
    },
  });
  const deleteMut = useMutation({ mutationFn: api.deleteBill, onSuccess: () => qc.invalidateQueries(['billing']) });
  const markPaidMut = useMutation({ mutationFn: ({ id, amount  }: Unmodelled) => api.updateBill(id, { status:'Paid', paid: amount }), onSuccess: () => qc.invalidateQueries(['billing']) });

  const set = (k: Unmodelled, v: Unmodelled) => setForm(f => ({ ...f, [k]: v }));
  const submit = (e: Unmodelled) => {
    e.preventDefault();
    createMut.mutate({
      ...form, amount: Number(form.amount), discount: Number(form.discount) || 0, paid: Number(form.paid),
      ...(approval ? { approvalId: approval.id } : {}),
    });
  };
  const downloadInvoice = async (bill: Unmodelled) => {
    try {
      await downloadInvoicePdf(bill._id, `${bill.invoiceId || 'invoice'}.pdf`);
    } catch (error: any) {
      toast.error(error.message || 'Unable to download invoice');
    }
  };

  const outstanding = (summary.total ?? 0) - (summary.paid ?? 0);

  return (
    <div>
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Billing</h1>
          <p className="page-subtitle">Invoice management & revenue tracking</p>
        </div>
        <Button className="gap-2 w-full sm:w-auto" onClick={() => setModal(true)}><Plus className="w-4 h-4" /> New Invoice</Button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-5 mb-8">
        <div className="bg-card rounded-xl border p-5 shadow-sm flex items-center gap-4">
          <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
            <IndianRupee className="w-6 h-6 text-primary" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide">Total Invoiced</p>
            <p className="text-2xl font-bold font-heading text-card-foreground">₹{(summary.total ?? 0).toLocaleString()}</p>
          </div>
        </div>
        <div className="bg-card rounded-xl border p-5 shadow-sm flex items-center gap-4">
          <div className="w-12 h-12 rounded-xl bg-success/10 flex items-center justify-center flex-shrink-0">
            <CheckCircle className="w-6 h-6 text-success" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide">Collected</p>
            <p className="text-2xl font-bold font-heading text-success">₹{(summary.paid ?? 0).toLocaleString()}</p>
          </div>
        </div>
        <div className="bg-card rounded-xl border p-5 shadow-sm flex items-center gap-4">
          <div className="w-12 h-12 rounded-xl bg-warning/10 flex items-center justify-center flex-shrink-0">
            <AlertCircle className="w-6 h-6 text-warning" />
          </div>
          <div>
            <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide">Outstanding</p>
            <p className="text-2xl font-bold font-heading text-warning">₹{outstanding.toLocaleString()}</p>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-5">
        <div className="relative flex-1 min-w-[200px] max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search invoices…" className="pl-10" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <div className="flex gap-2 flex-wrap">
          {STATUSES.map(s => (
            <button key={s} onClick={() => setStatusFilter(s)}
              className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${statusFilter === s ? 'bg-primary text-primary-foreground border-primary' : 'border-border text-muted-foreground hover:border-primary/40'}`}>
              {s}
            </button>
          ))}
        </div>
      </div>

      {/* Table */}
      {/* File 22 P0-2: flag chips for the selected bill's patient */}
      {selectedBill && <PatientBanner patientId={selectedBill.patientId || ''} />}
      {/* File 22 P1-14: split collection for the selected bill */}
      {selectedBill && selectedBill.status !== 'Paid' && selectedBill.status !== 'Cancelled' ? (
        <div className="rounded-xl border p-3 space-y-2">
          <p className="text-sm font-semibold">Collect — {selectedBill.invoiceId} (balance ₹{Number(selectedBill.balance ?? selectedBill.amount ?? 0).toLocaleString('en-IN')})</p>
          {legs.map((l, i) => (
            <div key={i} className="flex gap-2">
              <select className="h-9 rounded-md border px-2 text-sm" value={l.mode} onChange={(e) => setLegs(legs.map((x, j) => j === i ? { ...x, mode: e.target.value } : x))}>
                {['Cash', 'Card', 'UPI', 'Cheque', 'Insurance', 'Online', 'Other'].map((m) => <option key={m}>{m}</option>)}
              </select>
              <Input className="w-32" type="number" placeholder="Amount" value={l.amount} onChange={(e) => setLegs(legs.map((x, j) => j === i ? { ...x, amount: e.target.value } : x))} />
              <Input className="w-40" placeholder="Txn ref (optional)" value={l.txnRef} onChange={(e) => setLegs(legs.map((x, j) => j === i ? { ...x, txnRef: e.target.value } : x))} />
              {legs.length > 1 ? <Button size="sm" variant="ghost" onClick={() => setLegs(legs.filter((_, j) => j !== i))}>×</Button> : null}
            </div>
          ))}
          <div className="flex gap-2">
            {legs.length < 6 ? <Button size="sm" variant="outline" onClick={() => setLegs([...legs, { mode: 'UPI', amount: '', txnRef: '' }])}>+ leg</Button> : null}
            <Button size="sm" onClick={async () => {
              try {
                await api.collectBill(selectedBill._id, legs.filter((l) => Number(l.amount) > 0).map((l) => ({ mode: l.mode, amount: Number(l.amount), txnRef: l.txnRef })));
                toast.success('Collection recorded');
                setLegs([{ mode: 'Cash', amount: '', txnRef: '' }]);
                setSelectedBill(null);
                qc.invalidateQueries(['billing']);
              } catch (err: any) { toast.error(err?.response?.data?.message || 'Collection failed'); }
            }}>Collect ₹{legs.reduce((s, l) => s + (Number(l.amount) || 0), 0).toLocaleString('en-IN')}</Button>
            <Button size="sm" variant="outline" onClick={async () => {
              const reason = window.prompt('Cancel reason:');
              if (!reason) return;
              try {
                await api.cancelBill(selectedBill._id, reason);
                toast.success('Bill cancelled');
                setSelectedBill(null);
                qc.invalidateQueries(['billing']);
              } catch (err: any) {
                const d = err?.response?.data;
                toast.error(d?.code === 'NEEDS_APPROVAL' ? `Paid bill — approval ${d.approvalId} raised for ${d.approverRoles?.join('/')}` : (d?.message || 'Cancel failed'));
              }
            }}>Cancel bill</Button>
            {/* File 22 P0-left: share a payment link for remote collection */}
            <Button size="sm" variant="outline" onClick={async () => {
              try {
                const r: any = await api.post('/checkout/payment-links', {
                  amount: Number(selectedBill.balance ?? selectedBill.amount ?? 0),
                  description: `Bill ${selectedBill.invoiceId}`,
                });
                if (r.url) { window.open(r.url, '_blank'); toast.success('Payment link opened'); }
                else if (r.params) { toast.info('PayU params ready — POST to gateway URL'); }
                else toast.success('Payment link created');
              } catch (err: any) { toast.error(err?.response?.data?.message || 'Payment link failed'); }
            }}>Payment link</Button>
          </div>
        </div>
      ) : null}
      <div className="bg-card rounded-xl border shadow-sm overflow-hidden">
        {isLoading ? (
          <div className="p-4 space-y-3">
            {[...Array(5)].map((_, i) => <div key={i} className="h-4 bg-muted rounded animate-pulse" />)}
          </div>
        ) : (
          /* Page owns search + status chips, so showSearch off; no server paging. */
          <DataGrid
            columns={[
              { key: 'invoiceId', label: 'Invoice', sortable: false, render: (v: Unmodelled) => <span className="text-xs font-mono text-muted-foreground">{v}</span> },
              { key: 'patient', label: 'Patient', sortable: false, render: (v: Unmodelled) => <span className="text-sm font-medium text-card-foreground">{v}</span> },
              { key: 'doctor', label: 'Doctor', sortable: false, render: (v: Unmodelled) => <span className="text-sm text-muted-foreground">{v}</span> },
              { key: 'service', label: 'Service', sortable: false, render: (v: Unmodelled) => <span className="text-sm text-muted-foreground max-w-[180px] truncate block">{v}</span> },
              { key: 'amount', label: 'Amount', sortable: false, render: (v: Unmodelled) => <span className="text-sm font-semibold text-card-foreground">₹{v?.toLocaleString()}</span> },
              { key: 'paid', label: 'Paid', sortable: false, render: (v: Unmodelled) => <span className="text-sm text-success font-medium">₹{v?.toLocaleString()}</span> },
              { key: 'status', label: 'Status', sortable: false, render: (v: Unmodelled) => <span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${statusCls[v] ?? 'bg-muted text-muted-foreground'}`}>{v}</span> },
              { key: 'dueDate', label: 'Due Date', sortable: false, render: (v: Unmodelled) => <span className="text-xs text-muted-foreground">{v}</span> },
              {
                key: '_actions', label: '', sortable: false,
                render: (_v: Unmodelled, b: Unmodelled) => (
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity">
                    <button onClick={() => downloadInvoice(b)}
                      className="p-1.5 rounded-lg text-muted-foreground hover:text-primary hover:bg-primary/10 transition-colors" title="Download Invoice">
                      <Download className="w-4 h-4" />
                    </button>
                    {b.status !== 'Paid' && (
                      <button onClick={() => markPaidMut.mutate({ id: b._id, amount: b.amount })}
                        className="p-1.5 rounded-lg text-muted-foreground hover:text-success hover:bg-success/10 transition-colors" title="Mark Paid">
                        <CheckCircle className="w-4 h-4" />
                      </button>
                    )}
                    <button onClick={() => { if (confirm('Delete invoice?')) deleteMut.mutate(b._id); }}
                      className="p-1.5 rounded-lg text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ),
              },
            ]}
            rows={bills}
            rowKey="_id"
            empty="No invoices found"
            showSearch={false}
            manualPagination
            onRowClick={(b: Unmodelled) => setSelectedBill(selectedBill?._id === b._id ? null : b)}
            rowClassName={(b: Unmodelled) => (selectedBill?._id === b._id ? 'bg-muted/40' : '')}
          />
        )}
      </div>

      {/* New Invoice Modal */}
      {modal && (
        <div className="fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-card border rounded-2xl shadow-2xl w-full max-w-lg p-6 animate-fade-in max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-5">
              <h2 className="font-heading text-xl font-bold">New Invoice</h2>
              <button onClick={() => setModal(false)} className="p-1 rounded-lg hover:bg-muted"><X className="w-5 h-5 text-muted-foreground" /></button>
            </div>
            <form onSubmit={submit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-sm font-medium mb-1.5 block">Patient</label><Input value={form.patient} onChange={e=>set('patient',e.target.value)} placeholder="Patient name" required /></div>
                <div><label className="text-sm font-medium mb-1.5 block">Doctor</label><Input value={form.doctor} onChange={e=>set('doctor',e.target.value)} placeholder="Dr. Name" required /></div>
                <div className="col-span-2"><label className="text-sm font-medium mb-1.5 block">Service</label><Input value={form.service} onChange={e=>set('service',e.target.value)} placeholder="e.g. Cardiology Consultation" required /></div>
                <div><label className="text-sm font-medium mb-1.5 block">Amount (Rs)</label><Input type="number" value={form.amount} onChange={e=>set('amount',e.target.value)} placeholder="500" required /></div>
                <div><label className="text-sm font-medium mb-1.5 block">Discount (Rs)</label><Input type="number" value={form.discount} onChange={e=>set('discount',e.target.value)} placeholder="0" /></div>
                <div><label className="text-sm font-medium mb-1.5 block">Amount Paid (Rs)</label><Input type="number" value={form.paid} onChange={e=>set('paid',e.target.value)} placeholder="0" /></div>
                <div><label className="text-sm font-medium mb-1.5 block">Invoice Date</label><Input type="date" value={form.date} onChange={e=>set('date',e.target.value)} required /></div>
                <div><label className="text-sm font-medium mb-1.5 block">Due Date</label><Input type="date" value={form.dueDate} onChange={e=>set('dueDate',e.target.value)} /></div>
                <div>
                  <label className="text-sm font-medium mb-1.5 block">Status</label>
                  <select value={form.status} onChange={e=>set('status',e.target.value)} className="w-full h-10 px-3 rounded-md border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring">
                    {['Pending','Paid','Partial','Overdue'].map(s => <option key={s}>{s}</option>)}
                  </select>
                </div>
              </div>
              {approval && (
                <div className="rounded-lg border border-warning/40 bg-warning/10 p-3 text-sm">
                  Approval <span className="font-mono font-semibold">{approval.id}</span> pending
                  {approval.roles.length ? <> ({approval.roles.join('/')})</> : null} —{' '}
                  <a href="/hospital/approvals" className="underline">open approvals</a>, then submit again.
                  <button type="button" className="ml-2 underline" onClick={() => setApproval(null)}>clear</button>
                </div>
              )}
              {createMut.error && <p className="text-sm text-destructive">{createMut.error.message}</p>}
              <div className="flex gap-3 pt-2">
                <Button type="button" variant="outline" className="flex-1" onClick={() => setModal(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={createMut.isPending}>{createMut.isPending ? 'Creating…' : 'Create Invoice'}</Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Search, Plus, Clock, X, Droplets, CheckCircle, AlertTriangle, Heart, Activity, User, FileText, FlaskConical, AlertOctagon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';
import type { Unmodelled } from '@/lib/apiTypes';

const bbApi: Unmodelled = {
  getUnits: (p: Unmodelled) => api.getBloodUnits(p),
  addUnit: (b: Unmodelled) => api.addBloodUnit(b),
  getRequests: (p: Unmodelled) => api.getBloodRequests(p),
  createRequest: (b: Unmodelled) => api.createBloodRequest(b),
  crossMatch: (id: Unmodelled, b: Unmodelled) => api.crossMatchBlood(id, b),
  issueUnits: (id: Unmodelled, b: Unmodelled) => api.issueBloodUnits(id, b),
  startTransfusion: (id: Unmodelled, b: Unmodelled) => api.startTransfusion(id, b),
  completeTransfusion: (id: Unmodelled, b: Unmodelled) => api.completeTransfusion(id, b),
  reportReaction: (id: Unmodelled, b: Unmodelled) => api.reportReaction(id, b),
  getStats: () => api.getBloodBankStats(),
  getScreenings: () => api.donorScreenings({}),
  createScreening: (b: Unmodelled) => api.createDonorScreening(b),
};

const bloodGroups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];

const compatibleDonors: Unmodelled = {
  'A+': ['A+', 'A-', 'O+', 'O-'],
  'A-': ['A-', 'O-'],
  'B+': ['B+', 'B-', 'O+', 'O-'],
  'B-': ['B-', 'O-'],
  'AB+': ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'],
  'AB-': ['A-', 'B-', 'AB-', 'O-'],
  'O+': ['O+', 'O-'],
  'O-': ['O-'],
};

export default function BloodBank() {
  const qc: Unmodelled = useQueryClient();
  const [tab, setTab] = useState('inventory');
  const [search, setSearch] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const [showCrossMatch, setShowCrossMatch] = useState<Unmodelled>(null);
  const [crossMatchData, setCrossMatchData] = useState({ patientGroup: '', donorUnitId: '', compatibility: 'Compatible', crossMatchResult: 'Compatible', technician: '' });
  const [showTransfusion, setShowTransfusion] = useState<Unmodelled>(null);
  const [transfusionData, setTransfusionData] = useState({ preBp: '', prePulse: '', preTemp: '', startTime: '', nurseName: '' });
  const [showReaction, setShowReaction] = useState<Unmodelled>(null);
  const [reactionData, setReactionData] = useState({ reactionType: 'Fever', severity: 'Mild', symptoms: '', actionTaken: '', stopped: false });
  const [newUnit, setNewUnit] = useState({ bloodGroup: 'O+', donorName: '', donationDate: '', expiryDate: '', volume: 450, components: ['Whole Blood'], hiv: 'Negative', hbsag: 'Negative', hcv: 'Negative', malaria: 'Negative', vdrl: 'Negative' });
  const [newReq, setNewReq] = useState({ patientName: '', patientId: '', bloodGroup: 'O+', unitsRequired: 1, reason: '', priority: 'Routine' });
  // File 22 P1-21: donor screening form.
  const [screen, setScreen] = useState({ donorName: '', phone: '', bloodGroup: 'O+', age: '', weightKg: '', hb: '', lastDonationAt: '' });

  const { data: unitsData }: Unmodelled = useQuery({ queryKey: ['blood-units', search], queryFn: () => bbApi.getUnits({ search }) });
  const { data: reqsData }: Unmodelled = useQuery({ queryKey: ['blood-requests', search], queryFn: () => bbApi.getRequests({ search }) });
  const { data: stats }: Unmodelled = useQuery({ queryKey: ['blood-stats'], queryFn: bbApi.getStats });
  const { data: screenData }: Unmodelled = useQuery({ queryKey: ['donor-screenings'], queryFn: bbApi.getScreenings });
  const units = unitsData?.units || [];
  const requests = reqsData?.requests || [];
  const screenings = (screenData as any)?.screenings || [];

  const addUnitMut = useMutation({ mutationFn: bbApi.addUnit, onSuccess: () => { qc.invalidateQueries(['blood-units']); setShowAdd(false); } });
  const createReqMut = useMutation({ mutationFn: bbApi.createRequest, onSuccess: () => { qc.invalidateQueries(['blood-requests']); setShowAdd(false); } });
  const crossMatchMut = useMutation({ mutationFn: ({ id, ...b  }: Unmodelled) => bbApi.crossMatch(id, b), onSuccess: () => { qc.invalidateQueries(['blood-requests']); setShowCrossMatch(null); } });
  const issueMut = useMutation({ mutationFn: ({ id, ...b  }: Unmodelled) => bbApi.issueUnits(id, b), onSuccess: () => qc.invalidateQueries(['blood-requests', 'blood-units']) });
  const startTransMut = useMutation({ mutationFn: ({ id, ...b  }: Unmodelled) => bbApi.startTransfusion(id, b), onSuccess: () => { qc.invalidateQueries(['blood-requests']); setShowTransfusion(null); } });
  const completeTransMut = useMutation({ mutationFn: ({ id, ...b  }: Unmodelled) => bbApi.completeTransfusion(id, b), onSuccess: () => qc.invalidateQueries(['blood-requests']) });
  const reactionMut = useMutation({ mutationFn: ({ id, ...b  }: Unmodelled) => bbApi.reportReaction(id, b), onSuccess: () => { qc.invalidateQueries(['blood-requests']); setShowReaction(null); } });
  const screenMut = useMutation({ mutationFn: (v: Unmodelled) => bbApi.createScreening(v), onSuccess: (r: any) => { qc.invalidateQueries(['donor-screenings']); setScreen({ donorName: '', phone: '', bloodGroup: 'O+', age: '', weightKg: '', hb: '', lastDonationAt: '' }); } });

  const getCompatibleUnits = (bloodGroup: Unmodelled) => {
    const compatible = compatibleDonors[bloodGroup] || [];
    return units.filter((u: Unmodelled) => compatible.includes(u.bloodGroup) && u.status === 'Available');
  };

  return (
    <div>
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <h1 className="page-title">Blood Bank</h1>
        <p className="page-subtitle">{stats?.available || 0} units available · {stats?.pending || 0} pending · {stats?.crossMatching || 0} cross-matching</p>
      </div>

      <div className="grid grid-cols-6 gap-4 mb-6">
        {[
          { l: 'Total Units', v: stats?.total || 0, c: 'text-foreground', ic: Droplets },
          { l: 'Available', v: stats?.available || 0, c: 'text-success', ic: CheckCircle },
          { l: 'Cross-Matching', v: stats?.crossMatching || 0, c: 'text-warning', ic: FlaskConical },
          { l: 'Pending Req', v: stats?.pending || 0, c: 'text-warning', ic: AlertTriangle },
          { l: 'Issued', v: stats?.issued || 0, c: 'text-info', ic: FileText },
          { l: 'Expired', v: stats?.expired || 0, c: 'text-destructive', ic: AlertOctagon },
        ].map(s => (
          <div key={s.l} className="bg-card rounded-xl border p-3 text-center">
            <s.ic className={`w-4 h-4 mx-auto mb-1 ${s.c}`} />
            <p className={`text-xl font-bold ${s.c}`}>{s.v}</p>
            <p className="text-[10px] text-muted-foreground">{s.l}</p>
          </div>
        ))}
      </div>

      <div className="flex gap-2 mb-6 border-b pb-3">
        {['inventory', 'requests', 'donors'].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${tab === t ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`}>
            {t === 'inventory' ? 'Blood Inventory' : t === 'requests' ? 'Requests & Transfusions' : 'Donor Screening'}
          </button>
        ))}
      </div>

      {tab === 'inventory' && (
        <>
          <div className="flex gap-3 mb-6">
            <div className="relative flex-1 max-w-sm"><Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" /><Input placeholder="Search..." className="pl-10" value={search} onChange={e => setSearch(e.target.value)} /></div>
            <Button onClick={() => setShowAdd(true)}><Plus className="w-4 h-4 mr-1" /> Add Unit</Button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {units.map((u: Unmodelled) => (
              <div key={u._id} className={`bg-card rounded-xl border p-4 ${u.status === 'Available' ? 'border-success/30' : u.status === 'Expired' ? 'border-destructive/30' : 'border-warning/30'}`}>
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2"><Droplets className="w-4 h-4 text-destructive" /><span className="font-heading font-bold text-lg text-foreground">{u.bloodGroup}</span></div>
                  <span className={`text-xs px-2 py-0.5 rounded-full ${u.status === 'Available' ? 'bg-success/10 text-success' : u.status === 'Expired' ? 'bg-destructive/10 text-destructive' : 'bg-muted text-muted-foreground'}`}>{u.status}</span>
                </div>
                <div className="text-xs text-muted-foreground space-y-1">
                  <p>Unit: {u.unitId} · {u.volume}ml</p>
                  <p>Donor: {u.donorName || 'Unknown'} · Exp: {u.expiryDate ? new Date(u.expiryDate).toLocaleDateString() : 'N/A'}</p>
                  <p>Components: {u.components?.join(', ')}</p>
                  <div className="flex gap-1 mt-1">
                    {u.hiv === 'Positive' && <span className="text-[10px] bg-destructive/10 text-destructive px-1 rounded">HIV+</span>}
                    {u.hbsag === 'Positive' && <span className="text-[10px] bg-warning/10 text-warning px-1 rounded">HBsAg+</span>}
                    {u.hcv === 'Positive' && <span className="text-[10px] bg-warning/10 text-warning px-1 rounded">HCV+</span>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {tab === 'requests' && (
        <div className="space-y-4">
          <div className="flex gap-3 mb-6">
            <Button onClick={() => setShowAdd(true)}><Plus className="w-4 h-4 mr-1" /> New Request</Button>
          </div>
          {requests.map((r: Unmodelled) => (
            <div key={r._id} className={`bg-card rounded-xl border p-4 ${r.status === 'Reaction' ? 'border-destructive/50 bg-destructive/5' : r.status === 'Transfusing' ? 'border-primary/50 bg-primary/5' : ''}`}>
              <div className="flex items-start justify-between mb-3">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <Droplets className="w-4 h-4 text-destructive" />
                    <span className="font-semibold text-foreground">{r.requestId}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full ${r.priority === 'Emergency' ? 'bg-destructive/10 text-destructive' : r.priority === 'Urgent' ? 'bg-warning/10 text-warning' : 'bg-muted text-muted-foreground'}`}>{r.priority}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full ${r.status === 'Pending' ? 'bg-warning/10 text-warning' : r.status === 'Cross-Matching' ? 'bg-purple-500/10 text-purple-600' : r.status === 'Issued' ? 'bg-info/10 text-info' : r.status === 'Transfusing' ? 'bg-primary/10 text-primary' : r.status === 'Completed' ? 'bg-success/10 text-success' : 'bg-destructive/10 text-destructive'}`}>{r.status}</span>
                  </div>
                  <p className="text-sm font-medium">{r.patientName} · {r.bloodGroup} · {r.unitsRequired} unit(s)</p>
                  <p className="text-xs text-muted-foreground">Dr. {r.doctorName} · {r.reason || 'No reason'}</p>
                </div>
                <span className="text-xs text-muted-foreground"><Clock className="w-3 h-3 inline mr-1" />{r.createdAt ? new Date(r.createdAt).toLocaleDateString() : ''}</span>
              </div>

              {/* Cross-Match Result */}
              {r.crossMatchResult && (
                <div className={`text-xs mb-2 p-2 rounded ${r.crossMatchResult === 'Compatible' ? 'bg-success/5 text-success' : 'bg-destructive/5 text-destructive'}`}>
                  <FlaskConical className="w-3 h-3 inline mr-1" />
                  Cross-Match: {r.crossMatchResult} · Patient: {r.patientBloodGroup} → Donor: {r.donorBloodGroup}
                  {r.crossMatchTechnician && ` · By: ${r.crossMatchTechnician}`}
                </div>
              )}

              {/* Transfusion Status */}
              {r.transfusionStartTime && (
                <div className="text-xs text-info mb-2 p-2 bg-info/5 rounded">
                  <Heart className="w-3 h-3 inline mr-1" />
                  Transfusion started: {new Date(r.transfusionStartTime).toLocaleTimeString()} · Nurse: {r.transfusionNurse}
                </div>
              )}
              {r.transfusionCompleteTime && (
                <div className="text-xs text-success mb-2 p-2 bg-success/5 rounded">
                  <CheckCircle className="w-3 h-3 inline mr-1" />
                  Transfusion completed: {new Date(r.transfusionCompleteTime).toLocaleTimeString()}
                </div>
              )}

              {/* Reaction Alert */}
              {r.reactionReported && (
                <div className="text-xs text-destructive mb-2 p-2 bg-destructive/5 rounded flex items-center gap-1">
                  <AlertOctagon className="w-3 h-3" />
                  <strong>Reaction:</strong> {r.reactionType} ({r.reactionSeverity}) · {r.reactionSymptoms}
                  {r.reactionStopped && ' · Transfusion STOPPED'}
                </div>
              )}

              <div className="flex gap-2 flex-wrap">
                {r.status === 'Pending' && (
                  <>
                    <Button size="sm" variant="outline" onClick={() => {
                      setCrossMatchData({ patientGroup: r.bloodGroup, donorUnitId: '', compatibility: 'Compatible', crossMatchResult: 'Compatible', technician: '' });
                      setShowCrossMatch(r);
                    }}>
                      <FlaskConical className="w-3 h-3 mr-1" /> Cross-Match
                    </Button>
                    <Button size="sm" variant="outline" onClick={() => {
                      const ids = prompt('Unit IDs to issue (comma separated):');
                      if (ids) issueMut.mutate({ id: r._id, unitIds: ids.split(',').map(s => s.trim()) });
                    }}>
                      <CheckCircle className="w-3 h-3 mr-1" /> Issue Units
                    </Button>
                  </>
                )}
                {r.status === 'Issued' && (
                  <Button size="sm" variant="outline" onClick={() => {
                    setTransfusionData({ preBp: '', prePulse: '', preTemp: '', startTime: new Date().toISOString().slice(0, 16), nurseName: '' });
                    setShowTransfusion(r);
                  }}>
                    <Heart className="w-3 h-3 mr-1" /> Start Transfusion
                  </Button>
                )}
                {r.status === 'Transfusing' && (
                  <>
                    <Button size="sm" variant="outline" onClick={() => {
                      const endTime = prompt('Completion time:', new Date().toLocaleTimeString());
                      if (endTime) completeTransMut.mutate({ id: r._id, endTime, vitals: prompt('Post-transfusion vitals:') || '' });
                    }}>
                      <CheckCircle className="w-3 h-3 mr-1" /> Complete Transfusion
                    </Button>
                    <Button size="sm" variant="destructive" onClick={() => {
                      setReactionData({ reactionType: 'Fever', severity: 'Mild', symptoms: '', actionTaken: '', stopped: false });
                      setShowReaction(r);
                    }}>
                      <AlertOctagon className="w-3 h-3 mr-1" /> Report Reaction
                    </Button>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* File 22 P1-21: donor screening tab */}
      {tab === 'donors' && (
        <div className="grid lg:grid-cols-[320px_1fr] gap-4">
          <div className="bg-card rounded-xl border p-4 space-y-2">
            <h3 className="font-semibold text-sm">Screen donor</h3>
            <Input placeholder="Donor name" value={screen.donorName} onChange={(e) => setScreen({ ...screen, donorName: e.target.value })} />
            <div className="grid grid-cols-2 gap-2">
              <Input placeholder="Phone" value={screen.phone} onChange={(e) => setScreen({ ...screen, phone: e.target.value })} />
              <select aria-label="Blood group" className="h-10 rounded-md border px-2 text-sm" value={screen.bloodGroup} onChange={(e) => setScreen({ ...screen, bloodGroup: e.target.value })}>
                {bloodGroups.map((g) => <option key={g}>{g}</option>)}
              </select>
              <Input placeholder="Age" value={screen.age} onChange={(e) => setScreen({ ...screen, age: e.target.value })} />
              <Input placeholder="Weight kg" value={screen.weightKg} onChange={(e) => setScreen({ ...screen, weightKg: e.target.value })} />
              <Input placeholder="Hb" value={screen.hb} onChange={(e) => setScreen({ ...screen, hb: e.target.value })} />
              <Input type="date" aria-label="Last donation" value={screen.lastDonationAt} onChange={(e) => setScreen({ ...screen, lastDonationAt: e.target.value })} />
            </div>
            <Button className="w-full" disabled={!screen.donorName} onClick={() => screenMut.mutate({
              ...screen,
              age: screen.age ? Number(screen.age) : undefined,
              weightKg: screen.weightKg ? Number(screen.weightKg) : undefined,
              hb: screen.hb ? Number(screen.hb) : undefined,
              lastDonationAt: screen.lastDonationAt || undefined,
            })}>Screen</Button>
            {(screenMut.data as any)?.eligible === false ? (
              <p className="text-sm text-destructive">Deferred: {(screenMut.data as any)?.deferralReason}</p>
            ) : null}
          </div>
          <div className="space-y-2 max-h-[560px] overflow-auto">
            {screenings.map((s: any) => (
              <div key={s._id} className="flex items-center justify-between rounded-xl border p-3 text-sm">
                <span><b>{s.donorName}</b> · {s.bloodGroup} · {s.phone}</span>
                {s.eligible
                  ? <span className="text-xs font-bold text-success">ELIGIBLE</span>
                  : <span className="text-xs font-bold text-destructive" title={s.deferralReason}>DEFERRED</span>}
              </div>
            ))}
            {screenings.length === 0 ? <p className="text-sm text-muted-foreground">No screenings yet.</p> : null}
          </div>
        </div>
      )}

      {/* Cross-Match Modal */}
      {showCrossMatch && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setShowCrossMatch(null)}>
          <div className="bg-card rounded-2xl border shadow-xl max-w-md w-full p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-heading text-lg font-bold">Cross-Matching</h3>
              <button onClick={() => setShowCrossMatch(null)}><X className="w-5 h-5" /></button>
            </div>
            <p className="text-sm text-muted-foreground mb-4">{showCrossMatch.patientName} · Required: {showCrossMatch.bloodGroup}</p>
            <div className="space-y-4">
              <div><label className="text-xs text-muted-foreground mb-1 block">Patient Blood Group</label><Input value={crossMatchData.patientGroup} onChange={e => setCrossMatchData(d => ({ ...d, patientGroup: e.target.value }))} /></div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Compatible Units Available</label>
                <div className="text-sm text-success mb-2">{getCompatibleUnits(crossMatchData.patientGroup).length} units available</div>
                <select value={crossMatchData.donorUnitId} onChange={e => setCrossMatchData(d => ({ ...d, donorUnitId: e.target.value }))} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                  <option value="">Select donor unit...</option>
                  {getCompatibleUnits(crossMatchData.patientGroup).map((u: Unmodelled) => (
                    <option key={u._id} value={u._id}>{u.bloodGroup} - {u.unitId} (Exp: {u.expiryDate ? new Date(u.expiryDate).toLocaleDateString() : 'N/A'})</option>
                  ))}
                </select>
              </div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Cross-Match Result</label>
                <div className="flex gap-2">
                  {['Compatible', 'Incompatible'].map(r => (
                    <button key={r} onClick={() => setCrossMatchData(d => ({ ...d, crossMatchResult: r }))}
                      className={`px-3 py-1.5 rounded-lg text-xs font-medium ${crossMatchData.crossMatchResult === r ? (r === 'Compatible' ? 'bg-success text-white' : 'bg-destructive text-white') : 'bg-muted text-muted-foreground'}`}>
                      {r}
                    </button>
                  ))}
                </div>
              </div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Technician Name</label><Input value={crossMatchData.technician} onChange={e => setCrossMatchData(d => ({ ...d, technician: e.target.value }))} /></div>
              <Button className="w-full" onClick={() => crossMatchMut.mutate({ id: showCrossMatch._id, ...crossMatchData })}>
                Save Cross-Match Result
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Start Transfusion Modal */}
      {showTransfusion && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setShowTransfusion(null)}>
          <div className="bg-card rounded-2xl border shadow-xl max-w-md w-full p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-heading text-lg font-bold">Start Transfusion</h3>
              <button onClick={() => setShowTransfusion(null)}><X className="w-5 h-5" /></button>
            </div>
            <p className="text-sm text-muted-foreground mb-4">{showTransfusion.patientName} · Pre-transfusion vitals</p>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs text-muted-foreground mb-1 block">BP</label><Input value={transfusionData.preBp} onChange={e => setTransfusionData(d => ({ ...d, preBp: e.target.value }))} placeholder="120/80" /></div>
                <div><label className="text-xs text-muted-foreground mb-1 block">Pulse</label><Input type="number" value={transfusionData.prePulse} onChange={e => setTransfusionData(d => ({ ...d, prePulse: e.target.value }))} placeholder="72" /></div>
                <div><label className="text-xs text-muted-foreground mb-1 block">Temperature (°F)</label><Input type="number" value={transfusionData.preTemp} onChange={e => setTransfusionData(d => ({ ...d, preTemp: e.target.value }))} placeholder="98.6" /></div>
                <div><label className="text-xs text-muted-foreground mb-1 block">Start Time</label><Input type="datetime-local" value={transfusionData.startTime} onChange={e => setTransfusionData(d => ({ ...d, startTime: e.target.value }))} /></div>
              </div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Nurse Name</label><Input value={transfusionData.nurseName} onChange={e => setTransfusionData(d => ({ ...d, nurseName: e.target.value }))} /></div>
              <Button className="w-full" onClick={() => startTransMut.mutate({ id: showTransfusion._id, ...transfusionData })}>
                Start Transfusion
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Reaction Report Modal */}
      {showReaction && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setShowReaction(null)}>
          <div className="bg-card rounded-2xl border shadow-xl max-w-md w-full p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-heading text-lg font-bold text-destructive">Report Transfusion Reaction</h3>
              <button onClick={() => setShowReaction(null)}><X className="w-5 h-5" /></button>
            </div>
            <p className="text-sm text-muted-foreground mb-4">{showReaction.patientName}</p>
            <div className="space-y-4">
              <div><label className="text-xs text-muted-foreground mb-1 block">Reaction Type</label>
                <select value={reactionData.reactionType} onChange={e => setReactionData(d => ({ ...d, reactionType: e.target.value }))} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                  <option>Fever</option><option>Allergic</option><option>Hemolytic</option><option>Bacterial</option><option>Anaphylactic</option><option>Other</option>
                </select>
              </div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Severity</label>
                <div className="flex gap-2">
                  {['Mild', 'Moderate', 'Severe'].map(s => (
                    <button key={s} onClick={() => setReactionData(d => ({ ...d, severity: s }))}
                      className={`px-3 py-1.5 rounded-lg text-xs font-medium ${reactionData.severity === s ? (s === 'Severe' ? 'bg-destructive text-white' : s === 'Moderate' ? 'bg-warning text-white' : 'bg-muted text-foreground') : 'bg-muted text-muted-foreground'}`}>
                      {s}
                    </button>
                  ))}
                </div>
              </div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Symptoms</label>
                <textarea value={reactionData.symptoms} onChange={e => setReactionData(d => ({ ...d, symptoms: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-input bg-background text-sm resize-none h-16" placeholder="Fever, chills, rash, dyspnea..." />
              </div>
              <div><label className="text-xs text-muted-foreground mb-1 block">Action Taken</label>
                <textarea value={reactionData.actionTaken} onChange={e => setReactionData(d => ({ ...d, actionTaken: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-input bg-background text-sm resize-none h-16" placeholder="Stopped transfusion, antihistamines, doctor notified..." />
              </div>
              <label className="flex items-center gap-2 text-sm">
                <input type="checkbox" checked={reactionData.stopped} onChange={e => setReactionData(d => ({ ...d, stopped: e.target.checked }))} className="w-4 h-4" />
                Transfusion Stopped
              </label>
              <Button className="w-full" variant="destructive" onClick={() => reactionMut.mutate({ id: showReaction._id, ...reactionData })}>
                Report Reaction
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Add Unit Modal */}
      {showAdd && tab === 'inventory' && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setShowAdd(false)}>
          <div className="bg-card rounded-2xl border shadow-xl max-w-lg w-full p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-6"><h2 className="font-heading text-xl font-bold">Add Blood Unit</h2><button onClick={() => setShowAdd(false)}><X className="w-5 h-5" /></button></div>
            <div className="grid grid-cols-2 gap-4">
              <div><label className="text-sm font-medium mb-1 block">Blood Group</label><select value={newUnit.bloodGroup} onChange={e => setNewUnit({ ...newUnit, bloodGroup: e.target.value })} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">{bloodGroups.map(g => <option key={g} value={g}>{g}</option>)}</select></div>
              <div><label className="text-sm font-medium mb-1 block">Volume (ml)</label><Input type="number" value={newUnit.volume} onChange={e => setNewUnit({ ...newUnit, volume: parseInt(e.target.value) })} /></div>
              <div><label className="text-sm font-medium mb-1 block">Donor Name</label><Input value={newUnit.donorName} onChange={e => setNewUnit({ ...newUnit, donorName: e.target.value })} /></div>
              <div><label className="text-sm font-medium mb-1 block">Donation Date</label><Input type="date" value={newUnit.donationDate} onChange={e => setNewUnit({ ...newUnit, donationDate: e.target.value })} /></div>
              <div><label className="text-sm font-medium mb-1 block">Expiry Date</label><Input type="date" value={newUnit.expiryDate} onChange={e => setNewUnit({ ...newUnit, expiryDate: e.target.value })} /></div>
            </div>
            <Button className="w-full mt-6" onClick={() => addUnitMut.mutate((newUnit as Unmodelled))} disabled={addUnitMut.isPending || !newUnit.donationDate || !newUnit.expiryDate}>Add Unit</Button>
          </div>
        </div>
      )}

      {/* New Request Modal */}
      {showAdd && tab === 'requests' && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setShowAdd(false)}>
          <div className="bg-card rounded-2xl border shadow-xl max-w-lg w-full p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-6"><h2 className="font-heading text-xl font-bold">Blood Request</h2><button onClick={() => setShowAdd(false)}><X className="w-5 h-5" /></button></div>
            <div className="space-y-4">
              <div><label className="text-sm font-medium mb-1 block">Patient Name</label><Input value={newReq.patientName} onChange={e => setNewReq({ ...newReq, patientName: e.target.value })} /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-sm font-medium mb-1 block">Blood Group</label><select value={newReq.bloodGroup} onChange={e => setNewReq({ ...newReq, bloodGroup: e.target.value })} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">{bloodGroups.map(g => <option key={g} value={g}>{g}</option>)}</select></div>
                <div><label className="text-sm font-medium mb-1 block">Units</label><Input type="number" value={newReq.unitsRequired} onChange={e => setNewReq({ ...newReq, unitsRequired: parseInt(e.target.value) })} /></div>
                <div><label className="text-sm font-medium mb-1 block">Priority</label><select value={newReq.priority} onChange={e => setNewReq({ ...newReq, priority: e.target.value })} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">{['Routine', 'Urgent', 'Emergency'].map(p => <option key={p} value={p}>{p}</option>)}</select></div>
              </div>
              <div><label className="text-sm font-medium mb-1 block">Reason</label><Input value={newReq.reason} onChange={e => setNewReq({ ...newReq, reason: e.target.value })} /></div>
              <Button className="w-full" onClick={() => createReqMut.mutate((newReq as Unmodelled))} disabled={createReqMut.isPending || !newReq.patientName}>Create Request</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

