              {/* Walk-in Accepted */}
              {doctor.walk_in_accepted !== undefined && (
                <div className="flex items-center justify-between p-2.5 rounded-xl bg-muted/30 border border-border/60 mb-2">
                  <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                    <DoorOpen className="w-3.5 h-3.5 text-primary shrink-0" />
                    Walk-in Accepted
                  </span>
                  <span className={cn('text-xs font-semibold', doctor.walk_in_accepted ? 'text-success' : 'text-muted-foreground')}>
                    {doctor.walk_in_accepted ? 'Yes' : 'No'}
                  </span>
                </div>
              )}

              {/* Next Available Slot */}
              {doctor.next_available_slot && (
                <div className="flex items-center gap-2 px-2.5 py-2 rounded-xl bg-primary/5 border border-primary/20 mb-3 text-xs">
                  <Clock className="w-3.5 h-3.5 text-primary shrink-0" />
                  <span className="text-muted-foreground">Next available: <span className="font-semibold text-foreground">{doctor.next_available_slot}</span></span>
                </div>
              )}

              <Button className="w-full rounded-xl h-11 font-semibold shadow-lg shadow-primary/25 mb-3 gap-2" onClick={() => setShowBookingModal(true)}>
                <CalendarDays className="w-4 h-4" /> Book Appointment
              </Button>

              {/* Call Clinic / Hospital Reception */}
              {doctor.clinic_reception_phone && (
                <Button variant="outline" className="w-full rounded-xl h-10 gap-2" asChild>
                  <a href={`tel:${doctor.clinic_reception_phone}`}>
                    <Phone className="w-4 h-4" />
                    Call Clinic
                  </a>
                </Button>
              )}

              {!user && (
                <p className="text-xs text-muted-foreground text-center mt-3">
                  You need to <Link to="/login" className="text-primary underline">sign in</Link> to manage your appointments
                </p>
              )}
            </div>

            <BookingModal
              open={showBookingModal}
              onOpenChange={setShowBookingModal}
              doctor={doctor}
              facility={doctor.clinicProfile}
            />
          </motion.div>

        </div>

      <ReviewDialog 
        open={showReviewDialog} 
        onOpenChange={setShowReviewDialog}
        entityType="doctor"
        entityId={id}
        entityName={doctor?.name}
        onReviewSubmitted={(review: ApiRecord) => {
          setReviews(prev => [review, ...(Array.isArray(prev) ? prev : [])]);
        }}
      />
    </div>
    </motion.div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Star, MapPin, Stethoscope, UserRound, CalendarDays, IndianRupee, Award, Users, SlidersHorizontal, X, Building2, Clock, Shield, Syringe, BedDouble, Languages, GraduationCap, CircleDot, ChevronDown, ChevronUp, Ambulance, Eye, Heart, Bone, Baby, Activity, Brain, BadgeCheck, Phone, Mail, ArrowRight, Navigation, Globe, FlaskConical, AlertCircle, CheckCircle, CreditCard, Smartphone, Landmark, Wallet, ChevronRight, Sparkles, HeartHandshake, HeartPulse } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { Dialog, DialogTrigger, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { api } from '@/lib/api';
import { cn } from '@/lib/utils';
import { matchesDoctorSpecialty, canonicalName } from '@/lib/specialtyFilter';
import { useCategories } from '@/hooks/useCategories';
import { toast } from 'sonner';
import BookingModal from '@/components/BookingModal';

import { getSpecialtyVisual } from '@/data/specialtyVisuals';
import { useSpecialtyTiles, type SpecialtyNode } from '@/hooks/useSpecialtyBrowse';

const QUALIFICATIONS = ['MBBS', 'MD', 'MS', 'DM', 'MCh', 'DNB'];
const LANGUAGES = ['Hindi', 'English', 'Marathi', 'Gujarati', 'Tamil', 'Telugu', 'Kannada', 'Bengali', 'Punjabi', 'Spanish', 'French', 'Korean', 'Japanese', 'Mandarin', 'German', 'Portuguese'];
const EXPERIENCE_RANGES = [
  { label: '0\u20135 years', min: 0, max: 5 },
  { label: '5\u201310 years', min: 5, max: 10 },
  { label: '10+ years', min: 10, max: 999 },
];

/**
 * Clinic-doctor payload from the plain-JS api client. Every read goes through
 * the display helpers below, so one permissive alias beats ~40 unchecked
 * property reads (repo-wide typing of the api layer is the separate typecheck
 * burn-down — same convention as components/maps/ServiceLocationMap.tsx).
 */
type ClinicDoctor = { [key: string]: any };

function getExpYears(exp: unknown): number {
  if (!exp) return 0;
  const m = String(exp).match(/(\d+)/);
  return m ? parseInt(m[1]) : 0;
}

function getClinicName(doc: ClinicDoctor | null | undefined): string {
  if (!doc) return '';
  return doc.clinicProfile?.clinic_name || doc.facilityId?.name || doc.location?.split(',')?.[0] || 'Clinic';
}

function getClinicAddress(doc: ClinicDoctor | null | undefined): string {
  if (!doc) return '';
  return doc.clinicProfile?.clinic_address || doc.facilityId?.address || doc.location || doc.area || doc.address || doc.city || '';
}

export default function ClinicDoctors() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [doctors, setDoctors] = useState<ClinicDoctor[]>([]);
  const [allDoctors, setAllDoctors] = useState<ClinicDoctor[]>([]);
  const [search, setSearch] = useState(searchParams.get('search') || '');
  const [loading, setLoading] = useState(true);
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [showBooking, setShowBooking] = useState(false);
  const [selectedDoctor, setSelectedDoctor] = useState<ClinicDoctor | null>(null);
  const [savedIds, setSavedIds] = useState<string[]>(() => {
    try { return JSON.parse(localStorage.getItem('fav_doctor_ids') || '[]'); } catch { return []; }
  });
  const toggleSavedDoctor = async (docId: string, e?: { stopPropagation: () => void }) => {
    if (e) e.stopPropagation();
    const nowSaved = !savedIds.includes(docId);
    const next = nowSaved ? [...savedIds, docId] : savedIds.filter(id => id !== docId);
    setSavedIds(next);
    try {
      if (nowSaved) {
        await api.dispatch(() => Promise.resolve({}), '/patient/favorites', { method: 'POST', body: JSON.stringify({ targetId: docId, targetType: 'doctor' }) });
      } else {
        await api.dispatch(() => Promise.resolve({}), `/patient/favorites/${docId}`, { method: 'DELETE' });
      }
      toast.success(nowSaved ? 'Saved' : 'Removed from Saved');
    } catch {
      setSavedIds(savedIds);
      toast.error('Failed to update favorite');
    }
  };

  const [specFilter, setSpecFilter] = useState(searchParams.get('specialty') || searchParams.get('specialization') || 'All');
  const [clinicFilter, setClinicFilter] = useState(searchParams.get('clinic') || searchParams.get('hospital') || '');
  const [locationFilter, setLocationFilter] = useState('');
  const [availabilityFilter, setAvailabilityFilter] = useState('');
  const [genderFilter, setGenderFilter] = useState('');
  const [expFilter, setExpFilter] = useState('');
  const [feeRange, setFeeRange] = useState([0, 2000]);
  const [ratingFilter, setRatingFilter] = useState(0);

  const [sortBy, setSortBy] = useState('relevance');
  const [consultantType, setConsultantType] = useState('');
  const [loadError, setLoadError] = useState('');

  const [qualificationFilter, setQualificationFilter] = useState<string[]>([]);
  const [languageFilter, setLanguageFilter] = useState<string[]>([]);
  const [surgeryFilter, setSurgeryFilter] = useState('');
  const [admissionFilter, setAdmissionFilter] = useState('');
  const [insuranceFilter, setInsuranceFilter] = useState('');
  const [emergencyFilter, setEmergencyFilter] = useState('');

  const { categories: specialtyCategories } = useCategories('specialty', []);
  const specialtyTree = useSpecialtyTiles();
  const specialtyChips = useMemo(() => {
    // Tree tiles (icon + Hindi name + sub-chips) are the only source; the
    // backend taxonomy stays authoritative.
    const leafSource = specialtyTree.tiles.map((t) => {
      const visual = getSpecialtyVisual(t.code);
      return {
        code: t.code,
        name: t.name,
        nameHi: t.meta?.nameHi || '',
        sensitive: !!t.sensitive,
        children: (t.children || []).slice(0, 3),
        icon: visual.icon,
        color: visual.color,
        textColor: visual.textColor,
      };
    });
    const presentation = new Map(leafSource.map((s) => [s.name.toLowerCase(), s]));
    const generic = { icon: Stethoscope, color: 'from-slate-500/20 to-slate-500/5', textColor: 'text-slate-500', nameHi: '', sensitive: false, children: [], code: '' };
    const byCanonical = new Map();
    for (const s of leafSource) {
      const canonical = canonicalName(s.name, specialtyCategories);
      if (canonical && !byCanonical.has(canonical)) byCanonical.set(canonical, s);
    }
    const canonical = specialtyCategories.map((c: { name: string }) => ({
      name: c.name,
      ...(byCanonical.get(c.name) || presentation.get(c.name.toLowerCase()) || generic),
    }));
    const uncovered = leafSource.filter((s) => !canonicalName(s.name, specialtyCategories));
    return [...canonical, ...uncovered];
  }, [specialtyCategories, specialtyTree.tiles]);

const loadDoctors = async () => {
    setLoading(true);
    setLoadError('');
    try {
      const params: Record<string, string> = { doctor_type: 'clinic' };
      if (search) params.search = search;
      const selectedSpecialty = specialtyChips.find((specialty) => specialty.name === specFilter)
        || specialtyChips.flatMap((specialty) => specialty.children || []).find((specialty) => specialty.name === specFilter);
      if (selectedSpecialty?.code) params.specialtyCode = selectedSpecialty.code;
      const condition = searchParams.get('condition');
      const procedure = searchParams.get('procedure');
      const fallbackSpecialtyCode = searchParams.get('fallbackSpecialtyCode');
      if (condition) params.condition = condition;
      if (procedure) params.procedure = procedure;
      if (fallbackSpecialtyCode) params.fallbackSpecialtyCode = fallbackSpecialtyCode;
      const data = await api.getDoctors(params).catch(() => { throw new Error('Failed to load doctors'); });
      const docList = Array.isArray(data) ? data : (data?.doctors || data?.data || []);
      setAllDoctors(Array.isArray(docList) ? docList : []);
    } catch (e: any) { setLoadError(e instanceof Error ? e.message : 'Failed to load doctors'); setAllDoctors([]); }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadDoctors(); }, [search, specFilter, searchParams, specialtyChips]);

  const insuranceProviders = useMemo(() => {
    const providers = new Set<string>();
    (Array.isArray(allDoctors) ? allDoctors : []).forEach((d: ClinicDoctor) => {
      (d.clinicProfile?.clinic_insurance || d.insurance_accepted || []).forEach((i: unknown) => {
        if (typeof i === 'string') providers.add(i);
        else if ((i as { provider?: string })?.provider) providers.add((i as { provider: string }).provider);
      });
    });
    return [...providers].sort();
  }, [allDoctors]);

  useEffect(() => {
    let filtered = Array.isArray(allDoctors) ? [...allDoctors] : [];

    if (specFilter !== 'All') {
      const selectedSpecialty = specialtyChips.find((specialty) => specialty.name === specFilter)
        || specialtyChips.flatMap((specialty) => specialty.children || []).find((specialty) => specialty.name === specFilter);
      filtered = filtered.filter((doctor) => matchesDoctorSpecialty(doctor, selectedSpecialty, specFilter, specialtyCategories));
    }
    if (clinicFilter) filtered = filtered.filter(d => getClinicName(d) === clinicFilter);
    if (locationFilter && locationFilter !== 'All') filtered = filtered.filter(d => getClinicAddress(d).toLowerCase().includes(locationFilter.toLowerCase()));
    if (availabilityFilter === 'today') filtered = filtered.filter(d => d.available === true && d.next_available_slot?.toLowerCase().includes('today'));
    else if (availabilityFilter === 'tomorrow') filtered = filtered.filter(d => d.available === true && d.next_available_slot?.toLowerCase().includes('tomorrow'));
    else if (availabilityFilter === 'available') filtered = filtered.filter(d => d.available === true);
    if (genderFilter) filtered = filtered.filter(d => d.gender === genderFilter);

    if (expFilter) {
      const r = EXPERIENCE_RANGES.find(e => e.label === expFilter);
      if (r) filtered = filtered.filter(d => { const y = getExpYears(d.experience); return y >= r.min && y < r.max; });
    }

    filtered = filtered.filter(d => {
      const fee = d.consultation_fees || d.fees || 0;
      return fee >= feeRange[0] && fee <= feeRange[1];
    });

    if (ratingFilter > 0) filtered = filtered.filter(d => (d.rating || 0) >= ratingFilter);

    if (consultantType) filtered = filtered.filter(d => d.consultantType === consultantType);
    if (qualificationFilter.length > 0) {
      filtered = filtered.filter(d => qualificationFilter.some(q => (d.qualifications || '').includes(q)));
    }
    if (languageFilter.length > 0) {
      filtered = filtered.filter(d => languageFilter.some(l => d.languages?.includes(l)));
    }
    if (surgeryFilter === 'yes') filtered = filtered.filter(d => d.surgery_available === true);
    else if (surgeryFilter === 'no') filtered = filtered.filter(d => d.surgery_available !== true);
    if (admissionFilter === 'yes') filtered = filtered.filter(d => d.admission_available === true);
    else if (admissionFilter === 'no') filtered = filtered.filter(d => d.admission_available !== true);
    if (insuranceFilter) filtered = filtered.filter(d => {
      const ins = d.clinicProfile?.clinic_insurance || d.insurance_accepted || [];
      return (ins as unknown[]).some(i => (typeof i === 'string' ? i : (i as { provider?: string })?.provider || i) === insuranceFilter);
    });
    if (emergencyFilter === 'yes') filtered = filtered.filter(d => d.emergency_consultation === true);
    else if (emergencyFilter === 'no') filtered = filtered.filter(d => d.emergency_consultation !== true);

    if (sortBy === 'rating') filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    else if (sortBy === 'experience') filtered.sort((a, b) => getExpYears(b.experience) - getExpYears(a.experience));
    else if (sortBy === 'fee') filtered.sort((a, b) => (a.consultation_fees || a.fees || 0) - (b.consultation_fees || b.fees || 0));

    setDoctors(filtered);
  }, [allDoctors, specFilter, clinicFilter, locationFilter, availabilityFilter, genderFilter, expFilter, feeRange, ratingFilter, consultantType, qualificationFilter, languageFilter, surgeryFilter, admissionFilter, insuranceFilter, emergencyFilter, sortBy, specialtyCategories, specialtyChips]);

  const renderStars = (rating: number) => (
    <div className="flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map(s => (
        <Star key={s} className={`w-3.5 h-3.5 ${s <= Math.round(rating) ? 'text-warning fill-warning' : 'text-muted-foreground/30'}`} />
      ))}
    </div>
  );

  const activeFilterCount = [
    specFilter !== 'All', !!clinicFilter, !!locationFilter, !!availabilityFilter,
    !!genderFilter, !!expFilter, feeRange[0] > 0 || feeRange[1] < 2000, ratingFilter > 0,
  ].filter(Boolean).length;

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="font-heading text-3xl font-bold text-foreground">Find a Clinic Doctor</h1>
          <p className="text-muted-foreground mt-1">Search clinic doctors by name, specialization, or clinic</p>
        </div>

        {/* Search */}
        <div className="relative mb-6">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)}
            placeholder="Search by clinic doctor name or specialization..."
            className="pl-12 h-12 text-base rounded-2xl" />
        </div>

        {/* Specializations - 7 per row cards */}
        <div className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-heading text-xl font-bold text-foreground flex items-center gap-2">
              <Stethoscope className="w-5 h-5 text-primary" />
              Browse by Specialties
            </h2>
            {!showAdvanced && specialtyChips.length > 7 && (
              <Button variant="ghost" size="sm" onClick={() => setShowAdvanced(true)} className="gap-1 text-primary">
                More <ChevronDown className="w-3.5 h-3.5" />
              </Button>
            )}
            {showAdvanced && specialtyChips.length > 7 && (
              <Button variant="ghost" size="sm" onClick={() => setShowAdvanced(false)} className="gap-1 text-primary">
                Less <ChevronUp className="w-3.5 h-3.5" />
              </Button>
            )}
          </div>
          <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-7 gap-3">
            {specialtyChips.slice(0, showAdvanced ? undefined : 7).map((spec) => {
              const Icon = spec.icon;
              const isActive = specFilter === spec.name;
              const subChips = (spec.children || []).slice(0, 4) as SpecialtyNode[];
              return (
                <button
                  key={spec.code || spec.name}
                  onClick={() => setSpecFilter(spec.name)}
                  className={`flex flex-col items-center justify-center gap-2 p-4 rounded-2xl border transition-all ${
                    isActive
                      ? 'border-primary bg-primary/5 shadow-md shadow-primary/10'
                      : 'border-border/60 bg-card hover:border-primary/30 hover:shadow-sm'
                  }`}
                >
                  <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${spec.color} flex items-center justify-center`}>
                    <Icon className={`w-6 h-6 ${spec.textColor}`} />
                  </div>
                  <span className={`text-xs font-medium text-center leading-tight ${spec.sensitive ? 'text-muted-foreground' : isActive ? 'text-primary' : 'text-foreground'}`}>
                    {spec.name === 'All' ? 'All Departments' : spec.name}{spec.sensitive && ' 🔒'}
                  </span>
                  {spec.nameHi && <span className="text-[9px] text-muted-foreground">{spec.nameHi}</span>}
                  <span className="text-[10px] text-muted-foreground">
                    {allDoctors.filter((doctor) => matchesDoctorSpecialty(doctor, spec, spec.name, specialtyCategories)).length}
                  </span>
                  {subChips.length > 0 && (
                    <span className="flex flex-wrap justify-center gap-1" onClick={(event) => event.stopPropagation()}>
                      {subChips.map((child) => <span key={child.code} role="button" tabIndex={0} className="rounded-full bg-muted px-1.5 py-0.5 text-[9px] text-muted-foreground hover:text-primary" onClick={() => setSpecFilter(child.name)} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); setSpecFilter(child.name); } }}>{child.name}</span>)}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* ═══════ FILTERS BAR ═══════ */}
        <div className="mb-6 space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            {/* Main Filters */}
            <select value={clinicFilter} onChange={e => setClinicFilter(e.target.value)}
              className="h-9 px-3 rounded-xl border border-border bg-background text-sm max-w-[180px]">
              <option value="">All Clinics</option>
              {[...new Set(allDoctors.map(getClinicName).filter(Boolean))].map(n => (
                <option key={n} value={n}>{n}</option>
              ))}
            </select>

            <select value={locationFilter} onChange={e => setLocationFilter(e.target.value)}
              className="h-9 px-3 rounded-xl border border-border bg-background text-sm">
              <option value="">All Locations</option>
              {[...new Set(allDoctors.map(d => {
                const addr = getClinicAddress(d);
                const parts = addr.split(',').map(p => p.trim()).filter(Boolean);
                return parts[parts.length - 1] || parts[0] || '';
              }).filter(Boolean))].map(n => (
                <option key={n} value={n}>{n}</option>
              ))}
            </select>

            <select value={availabilityFilter} onChange={e => setAvailabilityFilter(e.target.value)}
              className="h-9 px-3 rounded-xl border border-border bg-background text-sm">
              <option value="">Availability</option>
              <option value="available">Available Now</option>
              <option value="today">Today</option>
              <option value="tomorrow">Tomorrow</option>
            </select>

            <select value={genderFilter} onChange={e => setGenderFilter(e.target.value)}
              className="h-9 px-3 rounded-xl border border-border bg-background text-sm">
              <option value="">Gender</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
            </select>

            <select value={expFilter} onChange={e => setExpFilter(e.target.value)}
              className="h-9 px-3 rounded-xl border border-border bg-background text-sm">
              <option value="">Experience</option>
              {EXPERIENCE_RANGES.map(r => (
                <option key={r.label} value={r.label}>{r.label}</option>
              ))}
            </select>

            {/* Fee range */}
            <div className="flex items-center gap-1.5 h-9 px-3 rounded-xl border border-border bg-background text-sm">
              <IndianRupee className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
              <input type="range" min={0} max={2000} step={100} value={feeRange[0]}
                onChange={e => setFeeRange([parseInt(e.target.value), feeRange[1]])}
                className="w-16 h-1 accent-primary" />
              <span className="text-xs text-muted-foreground w-12 text-right">{feeRange[0]}</span>
              <span className="text-xs text-muted-foreground">-</span>
              <input type="range" min={0} max={2000} step={100} value={feeRange[1]}
                onChange={e => setFeeRange([feeRange[0], parseInt(e.target.value)])}
                className="w-16 h-1 accent-primary" />
              <span className="text-xs text-muted-foreground w-12">{feeRange[1]}</span>
            </div>

            {/* Rating */}
            <div className="flex gap-1">
              {[4, 3].map(r => (
                <Button key={r} variant={ratingFilter === r ? 'default' : 'outline'} size="sm"
                  onClick={() => setRatingFilter(ratingFilter === r ? 0 : r)}
                  className="h-9 text-xs px-3">
                  <Star className="w-3.5 h-3.5 mr-1" /> {r}\u2605 & above
                </Button>
              ))}
            </div>

            {/* Sort */}
            <select value={sortBy} onChange={e => setSortBy(e.target.value)}
              className="h-9 px-3 rounded-xl border border-border bg-background text-sm">
              <option value="relevance">Sort: Relevance</option>
              <option value="rating">Rating (High-Low)</option>
              <option value="experience">Experience (High-Low)</option>
              <option value="fee">Fee (Low-High)</option>
            </select>

            {/* More Filters Toggle */}
            <Button variant="outline" size="sm" onClick={() => setShowAdvanced(!showAdvanced)}
              className="h-9 gap-2">
              <SlidersHorizontal className="w-4 h-4" />
              {showAdvanced ? 'Hide Advanced' : 'More Filters'}
            </Button>

            {/* Clear All */}
            {activeFilterCount > 0 && (
              <Button variant="ghost" size="sm" onClick={() => {
                setSpecFilter('All'); setClinicFilter(''); setLocationFilter('');
                setAvailabilityFilter(''); setGenderFilter(''); setExpFilter('');
                setFeeRange([0, 2000]); setRatingFilter(0); setSortBy('relevance');
                setConsultantType(''); setQualificationFilter([]);
                setLanguageFilter([]); setSurgeryFilter(''); setAdmissionFilter('');
                setInsuranceFilter(''); setEmergencyFilter('');
              }} className="text-red-500 hover:text-red-600 h-9 text-xs">
                <X className="w-3.5 h-3.5 mr-1" /> Clear All
              </Button>
            )}
          </div>

          {/* ═══════ ADVANCED FILTERS DRAWER ═══════ */}
          <AnimatePresence>
            {showAdvanced && (
              <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                <Card className="p-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    {/* Consultant Type */}
                    <div>
                      <label className="text-xs font-semibold text-muted-foreground mb-2 block">Consultant Type</label>
                      <div className="flex flex-wrap gap-1.5">
                        {[{v:'fulltime',l:'Full-Time'},{v:'visiting',l:'Visiting'}].map(ct => (
                          <Button key={ct.v} variant={consultantType === ct.v ? 'default' : 'outline'} size="sm"
                            onClick={() => setConsultantType(consultantType === ct.v ? '' : ct.v)}
                            className="text-[11px] h-7">
                            <CircleDot className="w-3 h-3 mr-1" /> {ct.l}
                          </Button>
                        ))}
