const COLORS = ['hsl(174,62%,38%)','hsl(210,80%,55%)','hsl(38,92%,50%)','hsl(152,60%,42%)','hsl(210,12%,50%)'];

/**
 * Local shapes for the plain-JS API layer. `src/lib/api.js` has no types, so the
 * dashboard declares exactly the fields it reads instead of indexing `any`
 * (repo-wide typing of the api client is the separate typecheck burn-down).
 */
interface DashboardStats {
  totalPatients?: number;
  totalDoctors?: number;
  todayAppointments?: number;
  revenue?: number;
  revenueMTD?: number;
}

interface DepartmentDatum {
  name?: string;
  value?: number;
}

interface AppointmentRow {
  _id?: string;
  status?: string;
  patient?: string;
  patientName?: string;
  doctor?: string;
  doctorName?: string;
  time?: string;
  timeSlot?: string;
  date?: string;
  bookingDate?: string;
}

interface RefundRow {
  _id?: string;
  status?: string;
  patient?: string;
  patientName?: string;
  reason?: string;
  description?: string;
  refund_amount?: number;
  amount?: number;
  date?: string;
  createdAt?: string;
}

interface DashboardPayload {
  stats?: DashboardStats;
  weeklyAppointments?: Array<{ day?: string; count?: number }>;
  revenueData?: Array<{ month?: string; revenue?: number }>;
  departmentData?: DepartmentDatum[];
  recentAppointments?: AppointmentRow[];
  refunds?: RefundRow[];
}

interface AppointmentListResponse {
  data?: AppointmentRow[];
  appointments?: AppointmentRow[];
}

interface RefundListResponse {
  payments?: RefundRow[];
  data?: RefundRow[];
}

/** Live OPD/ER/OT/IPD counters shown in the operations strip. */
interface OperationsSnapshot {
  bedsFree: number | null;
  bedsTotal: number | null;
  erActive: number | null;
  pendingVerif: number | null;
  staffOnLeave: number | null;
  pendingLab: number | null;
  activeOT: number | null;
  activeAmbulance: number | null;
  ipdCount: number | null;
}

/** Zeroed fallback so the render path never has to null-check the payload. */
const EMPTY_DASHBOARD: DashboardPayload = {
  stats: { totalPatients: 0, totalDoctors: 0, todayAppointments: 0, revenue: 0 },
  weeklyAppointments: [],
  revenueData: [],
  departmentData: [],
  recentAppointments: [],
  refunds: [],
};

const statusCls: Record<string, string> = { Confirmed:'bg-success/10 text-success', Pending:'bg-warning/10 text-warning', Cancelled:'bg-destructive/10 text-destructive', Completed:'bg-info/10 text-info' };
const tooltipStyle = { borderRadius:'0.75rem', border:'1px solid hsl(200,20%,90%)', fontSize:12 };

/** Axios errors carry the server message under `response.data.message`. */
type ApiError = Error & { response?: { data?: { message?: string } } };

/**
 * FE-B-05: route every failure through `userFacingError`.
 *
 * This used to be `apiError?.response?.data?.message || apiError?.message || ''`,
 * which put raw backend text — including 5xx internals like
 * `Cast to ObjectId failed for value "..."` — straight into the operations strip
 * on the home dashboard, i.e. the first thing every user sees after login.
 *
 * An empty string is returned for a cancelled request (react-query aborts) so the
 * strip stays quiet during navigation.
 */
function apiErrorMessage(error: unknown): string {
  if (!error) return '';
  const status: Unmodelled = (error as Unmodelled)?.response?.status;
  // Aborted/ignored queries must not produce a banner.
  if (status === undefined && (error as Error)?.name === 'CanceledError') return '';
  return userFacingError(error);
}

function OperationsStrip() {
  const navigate = useNavigate();
  const [ops, setOps] = useState<OperationsSnapshot>({
    bedsFree: null, bedsTotal: null, erActive: null, pendingVerif: null, staffOnLeave: null,
    pendingLab: null, activeOT: null, activeAmbulance: null, ipdCount: null
  });

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const [bedStats, erStats, leavePending, labStats, otStats, ambulanceStats, ipdStats] = await Promise.all([
          api.getBedStats().catch(() => null),
          api.getEmergencyStats().catch(() => null),
          api.getPendingLeaveRequests().catch(() => null),
          api.get('/diagnostic/stats').catch(() => null),
          api.get('/ot/stats').catch(() => null),
          api.get('/ambulances/stats').catch(() => null),
          api.get('/ipd/stats').catch(() => null),
        ]);
        if (!alive) return;
        setOps({
          bedsFree: bedStats?.available ?? bedStats?.free ?? null,
          bedsTotal: bedStats?.total ?? null,
          erActive: erStats?.active ?? erStats?.count ?? null,
          pendingVerif: null,
          staffOnLeave: Array.isArray(leavePending) ? leavePending.length : leavePending?.count ?? null,
          pendingLab: labStats?.pending ?? null,
          activeOT: otStats?.active ?? otStats?.todayCount ?? null,
          activeAmbulance: ambulanceStats?.onMission ?? ambulanceStats?.active ?? null,
          ipdCount: ipdStats?.activeAdmissions ?? ipdStats?.count ?? null,
        });

        api.get('/prescriptions/verification-queue').then((v) => {
          if (!alive) return;
          const n = Array.isArray(v) ? v.length : v?.queue?.length ?? v?.count ?? null;
          setOps((o) => ({ ...o, pendingVerif: n }));
        }).catch(() => {});
      } catch {}
    })();
    return () => { alive = false; };
  }, []);

  const items = [
    { label: 'Beds Free/Total', value: ops.bedsFree != null && ops.bedsTotal != null ? `${ops.bedsFree}/${ops.bedsTotal}` : '—', path: '/admin/beds' },
    { label: 'ER Active', value: ops.erActive ?? '—', path: '/admin/emergency', highlight: (ops.erActive ?? 0) > 0 },
    { label: 'OT Surgeries Today', value: ops.activeOT ?? '—', path: '/ot' },
    { label: 'Active IPD Patients', value: ops.ipdCount ?? '—', path: '/ipd' },
    { label: 'Pending Lab Tests', value: ops.pendingLab ?? '—', path: '/lab', highlight: (ops.pendingLab ?? 0) > 0 },
    { label: 'Pending Rx Verification', value: ops.pendingVerif ?? '—', path: '/admin/prescription-verification', highlight: (ops.pendingVerif ?? 0) > 0 },
    { label: 'Ambulances on Mission', value: ops.activeAmbulance ?? '—', path: '/admin/ambulances' },
    { label: 'Staff On Leave', value: ops.staffOnLeave ?? '—', path: '/admin/leave-requests' },
  ];

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-8 gap-3 mb-8">
      {items.map((it) => (
        <button 
          key={it.label} 
          onClick={() => navigate(it.path)} 
          className={`rounded-2xl border p-3 text-left hover:border-primary/40 hover:shadow-md transition-all ${it.highlight ? 'bg-red-50/50 dark:bg-red-950/20 border-red-200 dark:border-red-900/50' : 'bg-card'}`}
        >
          <p className={`text-xl font-bold ${it.highlight ? 'text-red-600 dark:text-red-400' : 'text-foreground'}`}>{it.value}</p>
          <p className="text-[10px] text-muted-foreground font-medium uppercase tracking-wider mt-1 line-clamp-1" title={it.label}>{it.label}</p>
        </button>
      ))}
    </div>
  );
}

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  // File 22 P0-7: hospital admins land on Dashboard V2 (classic stays one click away).
  if (user && user.role === 'hospital_admin') return <Navigate to="/dashboard/v2" replace />;
  const settings = useSettings();
  const [apptTab, setApptTab] = useState('pending');
  const queryClient = useQueryClient();
  const { data, isLoading, isError, error, refetch } = useQuery({ queryKey:['dashboard'], queryFn: api.dashboardStats, refetchInterval: 60000 });
  const { data: apptsData } = useQuery({ queryKey:['admin-appointments'], queryFn: () => api.getAppointments({ limit: 200, page: 1 }).catch(() => null), refetchInterval: 60000 });
  const { data: refundsData } = useQuery({ queryKey:['refunds'], queryFn: () => api.getRefunds().catch(() => ({ payments: [] })) });
  useAppointmentRealtime(() => { queryClient.invalidateQueries({ queryKey: ['dashboard'] }); queryClient.invalidateQueries({ queryKey: ['admin-appointments'] }); });

  useEffect(() => {
    const socket = getSocket();
    if (!socket) return;
    const onNewAppointment = () => {
      refetch();
      queryClient.invalidateQueries({ queryKey: ['admin-appointments'] });
    };
    const onEmergency = () => {
      toast.error('New Emergency Case Registered in Triage!', { duration: 8000 });
      refetch();
    };
    socket.on('appointment:created', onNewAppointment);
    socket.on('appointment:statusChange', onNewAppointment);
    socket.on('emergency:alert', onEmergency);
    return () => {
      socket.off('appointment:created', onNewAppointment);
      socket.off('appointment:statusChange', onNewAppointment);
      socket.off('emergency:alert', onEmergency);
    };
  }, [refetch, queryClient]);

  if (isLoading) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[0,1,2,3].map((i) => (
          <div key={i} className="rounded-2xl border p-5 animate-pulse">
            <div className="h-4 w-24 bg-muted rounded mb-3" />
            <div className="h-8 w-16 bg-muted rounded" />
          </div>
        ))}
      </div>
    );
  }
  const isNoHospital = apiErrorMessage(error).includes('No hospital linked');
  if (isError || !data) {
    return (
      <div className="rounded-2xl border p-8 text-center space-y-3">
        {isNoHospital ? (
          <>
            <p className="font-heading text-lg font-bold">Hospital link pending hai</p>
            <p className="text-sm text-muted-foreground">Aapke admin account se abhi koi hospital juda nahi hai. Onboarding team se hospital link karwao, phir dashboard yahin dikhega.</p>
          </>
        ) : (
          <p className="font-semibold">Dashboard load nahi hua{apiErrorMessage(error) ? `: ${apiErrorMessage(error)}` : ""}</p>
        )}
        <Button onClick={() => refetch()}>Retry</Button>
      </div>
    );
  }

  const payload = { ...EMPTY_DASHBOARD, ...(data as DashboardPayload) };
  const {
    stats,
    weeklyAppointments = [],
    revenueData = [],
    departmentData = [],
    recentAppointments: fallbackRecent = [],
  } = payload;
  const appointmentPayload = apptsData as AppointmentListResponse | AppointmentRow[] | null | undefined;
  const rawAppts = (Array.isArray(appointmentPayload)
    ? appointmentPayload
    : appointmentPayload?.data || appointmentPayload?.appointments || fallbackRecent) as AppointmentRow[];
  const appointmentsList: AppointmentRow[] = Array.isArray(rawAppts) ? rawAppts : [];

  const todayStr = getISTDateString();
  const statusOf = (row: AppointmentRow) => String(row.status || '').toLowerCase();
  const pendingAppts = appointmentsList.filter((a) => statusOf(a) === 'pending');
  const upcomingAppts = appointmentsList.filter((a) => {
    const s = statusOf(a);
    return s === 'confirmed' || s === 'approved' || s === 'upcoming';
  });
  const todayAppts = appointmentsList.filter((a) => {
    const s = statusOf(a);
    if (['cancelled', 'completed'].includes(s)) return false;
    const d = a.date || a.bookingDate || '';
    return !d || d.startsWith(todayStr);
  });
  const completedAppts = appointmentsList.filter((a) => statusOf(a) === 'completed');

  const displayedAppts = apptTab === 'pending' ? pendingAppts
    : apptTab === 'upcoming' ? upcomingAppts
    : apptTab === 'today' ? todayAppts
    : completedAppts;

  const refundPayload = refundsData as RefundListResponse | RefundRow[] | null | undefined;
  const refunds: RefundRow[] = Array.isArray(refundPayload)
    ? refundPayload
    : refundPayload?.payments || refundPayload?.data || [];
  const totalRefundAmount = refunds.reduce((sum, r) => sum + (r.refund_amount || r.amount || 0), 0);

  // Apply appearance settings when dashboard mounts or settings change
  useEffect(() => {
    if (typeof document !== 'undefined') {
      applyUserSettings(settings);
    }
  }, [settings]);

  return (
    <div>
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Dashboard</h1>
          <p className="page-subtitle">Welcome back, <span className="font-semibold text-foreground">{user?.name}</span>! Here's your hospital overview.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button onClick={() => navigate('/appointments')} className="rounded-xl gap-1.5 text-xs font-semibold shadow-sm">
            <CalendarDays className="w-3.5 h-3.5" /> Manage All Appointments
          </Button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5 mb-8">
