  createBooking: (b: Unmodelled) => api.createLabBooking(b),
  updateBooking: (id: Unmodelled, b: Unmodelled) => api.updateLabBooking(id, b),
  getEquipment: (p: Unmodelled) => api.getLabEquipment(p),
