};

import { TABS, CATEGORIES, DEPARTMENTS, REPORT_TIMES, StatusBadge, SectionHeader } from '@/components/diagnostic/DiagnosticShared';
import type { Unmodelled } from '@/lib/apiTypes';

export default function DiagnosticDashboard() {
  const qc = useQueryClient();
  const [tab, setTab] = useState('overview');
  const [search, setSearch] = useState('');
  const [showModal, setShowModal] = useState<Unmodelled>(null);
  const [toast, setToast] = useState<Unmodelled>(null);
  const [dispatchForm, setDispatchForm] = useState({ dropAddress: '', deliveryFee: '40', deliveryPartnerId: '', notes: '' });

  // Tests
  const [testForm, setTestForm] = useState({ name: '', category: 'Blood Test', department: 'Pathology', price: '', mrp: '', reportTime: '24 hrs', prescriptionReq: false, homeCollection: false, homeCollectionFee: '50', popular: false, nablAccredited: false, description: '', preparation: '' });
  const [editTestId, setEditTestId] = useState<Unmodelled>(null);

  // Bookings
  const [bookingFilter, setBookingFilter] = useState('All');
  const [bookingForm, setBookingForm] = useState({ patientName: '', patientPhone: '', visitType: 'Walk-in', bookingDate: '', timeSlot: '' });

  // Equipment
  const [equipForm, setEquipForm] = useState({ name: '', type: 'MRI', model: '', serialNumber: '', manufacturer: '', installationDate: '', nextMaintenanceDate: '', status: 'Operational', location: '', notes: '' });
  const [editEquipId, setEditEquipId] = useState<Unmodelled>(null);

  // Packages
  const [pkgForm, setPkgForm] = useState({ name: '', category: 'Basic', description: '', testNames: '', originalPrice: '', packagePrice: '', popular: false, homeCollectionAvailable: false, reportTime: '24-48 hrs' });
  const [editPkgId, setEditPkgId] = useState<Unmodelled>(null);

  // Staff
  const [newStaff, setNewStaff] = useState({ name: '', role: 'Lab Technician', email: '', phone: '', licenseNumber: '', experience: '' });
  const [assignmentForm, setAssignmentForm] = useState({ bookingId: '', phlebotomistId: '' });

  // Prescription Queue (derived from lab orders/bookings with Rx flag)
  const [billFilter, setBillFilter] = useState('All');

  // Reports
  const [reportPeriod, setReportPeriod] = useState('7d');
  const [reportForm, setReportForm] = useState({ orderId: '' });
  const [appointmentForm, setAppointmentForm] = useState({ patientName: '', patientPhone: '', bookingDate: '', timeSlot: '', testName: '' });

  // Settings
  const [centerSettings, setCenterSettings] = useState({ name: 'FindMedi Diagnostic Center', type: 'Pathology Lab', address: '123 Healthcare Ave, New York', phone: '+1 234-567-8900', email: 'lab@findmedi.com', licenseNo: 'LAB-LIC-001', nablCertified: true, nablCertNo: 'NABL-MC-2024-001', aerbCertified: false, timings: '7:00 AM - 9:00 PM', homeCollectionAvailable: true, emergencySupport: false, acceptRefunds: true, reportDeliveryModes: ['Email', 'SMS', 'Portal', 'Courier'] });

  const showToast = (msg: Unmodelled, type = 'success') => { setToast({ msg, type }); setTimeout(() => setToast(null), 3000); };
  const exportBillingCsv = () => {
    const rows = (filteredBills.length ? filteredBills : bookings).map((b: Unmodelled) => ({
      invoice: b.invoiceId || b.bookingId || b._id,
      patient: b.patientName || '',
      tests: (b.tests || []).length,
      amount: b.totalAmount || 0,
      payment: b.paymentStatus || '',
      date: b.date || b.bookingDate || '',
    }));
    if (!rows.length) return showToast('No billing rows to export', 'error');
    const csv = ['Invoice,Patient,Tests,Amount,Payment,Date', ...rows.map((r: Unmodelled) => [r.invoice, r.patient, r.tests, r.amount, r.payment, r.date].map(v => `"${String(v).replaceAll('"', '""')}"`).join(','))].join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `lab-billing-${new Date().toISOString().slice(0, 10)}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    showToast('Billing CSV exported');
