                    {equipment.filter((e: Unmodelled) => e.status !== 'Operational').map((e: Unmodelled) => (
                      <div key={e._id} className="flex items-center justify-between text-sm">
                        <span className="font-medium">{e.name}</span>
                        <StatusBadge status={e.status} />
