  const [fetchingActive, setFetchingActive] = useState<boolean>(true);
  // File 04 — full-screen Assigned overlay dismissal (reset per ride)
  const [assignedDismissed, setAssignedDismissed] = useState<boolean>(false);

  useEffect(() => {
    setAssignedDismissed(false);
  }, [activeRide?._id]);

  // Global City Synchronization (from Navbar)
  const [selectedCity, setSelectedCity] = useState<string>(
    () => localStorage.getItem('findmedi_city') || localStorage.getItem('mediCore_city') || 'Jabalpur'
  );

  useEffect(() => {
    const onCityChange = (e: any) => {
      const newCity = e.detail || localStorage.getItem('findmedi_city') || localStorage.getItem('mediCore_city');
      if (newCity && newCity !== selectedCity) {
        setSelectedCity(newCity);
      }
    };
    window.addEventListener('cityChange', onCityChange);
    window.addEventListener('storage', onCityChange);
    return () => {
      window.removeEventListener('cityChange', onCityChange);
      window.removeEventListener('storage', onCityChange);
    };
  }, [selectedCity]);

  // 1. Initial Load: Check for active ride or deep-linked rideId
  useEffect(() => {
    if (!user) {
      // Guest visitors can browse freely — skip active ride fetch
      setFetchingActive(false);
      return;
    }

    const loadInitialRide = async () => {
      try {
        if (rideIdParam) {
          const res = await api.getRide(rideIdParam);
          if (res.ride && !['completed', 'cancelled_by_user', 'cancelled_by_rider'].includes(res.ride.status)) {
            setActiveRide(res.ride);
            setPickup(res.ride.pickup);
            setDrop(res.ride.drop);
            setVehicleType(res.ride.vehicleType);
            setIsEmergency(res.ride.isEmergency);
            setFetchingActive(false);
            return;
          }
        }

        // Fetch user's active ride if any
        const res = await api.getActiveRide();
        if (res.ride) {
          setActiveRide(res.ride);
          setPickup(res.ride.pickup);
          setDrop(res.ride.drop);
          setVehicleType(res.ride.vehicleType);
          setIsEmergency(res.ride.isEmergency);
        }
      } catch (err: any) {
        // No active ride
      } finally {
        setFetchingActive(false);
      }
    };

    loadInitialRide();
  }, [user, rideIdParam]);

  // 2. Real-time Socket Listener for active ride updates & live tracking
  useEffect(() => {
    if (!activeRide?._id) return;

    const socket = getSocket();
    const cleanupRoom = joinRideRoom(String(activeRide._id));

    const handleRideStatusUpdate = (payload: any) => {
      if (String(payload.rideId) === String(activeRide._id)) {
        setActiveRide((prev: any) => ({
          ...prev,
          status: payload.status,
          riderDetails: payload.rider || prev?.riderDetails,
          payment: payload.payment || prev?.payment,
        }));
        if (payload.rider?.currentLocation) {
          setRiderLocation({
            lat: payload.rider.currentLocation.lat,
            lng: payload.rider.currentLocation.lng,
          });
        }
      }
    };

    const handleLocationUpdate = (payload: any) => {
      if (String(payload.rideId) === String(activeRide._id)) {
        setRiderLocation({ lat: payload.lat, lng: payload.lng });
      }
    };

    const handlePaymentReceived = (payload: any) => {
      if (String(payload.rideId) === String(activeRide._id)) {
        setActiveRide((prev: any) => ({
          ...prev,
          payment: payload.payment || { status: 'paid' },
        }));
      }
    };

    const handleRideSearchUpdate = (payload: any) => {
      if (String(payload.rideId || payload.requestId) === String(activeRide._id)) {
        setActiveRide((prev: any) => ({
          ...prev,
          currentDispatchRadius: payload.radiusKm,
        }));
      }
    };

    const handleNoResponders = (payload: any) => {
      if (String(payload.rideId || payload.requestId) === String(activeRide._id)) {
        setActiveRide((prev: any) => ({
          ...prev,
          status: 'no_riders_found',
        }));
      }
    };

    // File 03/04 — generic instant wave engine resolves via ride:assigned
    // (legacy sequential path resolves via ride_status_update accepted).
    const handleInstantAssigned = (payload: any) => {
      if (String(payload.rideId || payload.requestId) === String(activeRide._id)) {
        setActiveRide((prev: any) => ({
          ...prev,
          status: 'accepted',
          riderId: payload.providerId || payload.riderId || prev?.riderId,
          riderDetails: payload.providerDetails || prev?.riderDetails,
        }));
      }
    };

    socket.on('ride_status_update', handleRideStatusUpdate);
    socket.on('ride:search_update', handleRideSearchUpdate);
    socket.on('ride:assigned', handleInstantAssigned);
    socket.on('ride:no_responders_found', handleNoResponders);
    socket.on('ride_location_update', handleLocationUpdate);
    socket.on('payment_received', handlePaymentReceived);

    return () => {
      socket.off('ride_status_update', handleRideStatusUpdate);
      socket.off('ride:search_update', handleRideSearchUpdate);
      socket.off('ride:assigned', handleInstantAssigned);
      socket.off('ride:no_responders_found', handleNoResponders);
      socket.off('ride_location_update', handleLocationUpdate);
      socket.off('payment_received', handlePaymentReceived);
      cleanupRoom();
    };
  }, [activeRide?._id]);

  // 3. Fetch Fare Estimates whenever pickup, drop, or emergency toggle changes
  useEffect(() => {
    if (!pickup || !drop) {
      setEstimates({});
      return;
    }

    const fetchEstimate = async () => {
      setLoadingEstimate(true);
      try {
        const res = await api.estimateRide({
          pickup,
          drop,
          isEmergency: vehicleType === 'ambulance' && isEmergency,
        });
        setEstimates(res.estimates || {});
        setDistanceKm(res.distanceKm || 0);
      } catch (err: any) {
        console.warn('Failed to fetch estimate:', err.message);
      } finally {
        setLoadingEstimate(false);
      }
    };

    fetchEstimate();
  }, [pickup?.lat, pickup?.lng, drop?.lat, drop?.lng, isEmergency, vehicleType]);

  // Handle Book Now
  const handleBookNow = async () => {
    if (!user) {
      toast.error('Please sign in to book a ride');
      navigate('/login?redirect=/find-vehicle');
      return;
    }

    if (!pickup || !drop) {
      toast.error('Please specify both pickup and destination locations');
      return;
    }

    setBookingLoading(true);
    try {
      const res = await api.bookRide({
        pickup,
        drop,
        vehicleType,
        isEmergency: vehicleType === 'ambulance' && isEmergency,
        distanceKm,
      });

      if (res.ride) {
        setActiveRide(res.ride);
        toast.success(res.message || 'Ride booked! Matching with nearby drivers...');
      }
    } catch (err: any) {
      toast.error(err.message || 'Unable to book ride. Please try again.');
    } finally {
      setBookingLoading(false);
    }
  };

  // Handle Cancel Ride
  const handleCancelRide = async (reason = 'Cancelled by user') => {
    if (!activeRide?._id) return;
    try {
      await api.cancelRide(String(activeRide._id), reason);
      toast.info('Ride request cancelled');
      setActiveRide(null);
      setRiderLocation(null);
    } catch (err: any) {
      toast.error(err.message || 'Failed to cancel ride');
    }
  };

  const selectedEstimate = estimates[vehicleType];

  if (fetchingActive) {
    return (
      <div className="min-h-[calc(100vh-4rem)] flex items-center justify-center bg-background">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="w-8 h-8 animate-spin text-primary" />
          <p className="text-xs text-muted-foreground">Loading vehicle transport...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[1440px] mx-auto px-3 sm:px-4 lg:px-6 py-4 sm:py-6">
      <div className="mb-4 flex items-center justify-between">
        <div>
          <h1 className="text-2xl sm:text-3xl font-heading font-extrabold text-foreground flex items-center gap-2">
            <span className="p-1.5 rounded-xl bg-primary/10 text-primary">🚗</span>
            Find & Book a Vehicle
            {selectedCity && selectedCity !== 'All' && (
              <Badge variant="outline" className="text-xs font-semibold text-primary border-primary/30 bg-primary/5 ml-1">
                📍 {selectedCity}
              </Badge>
            )}
          </h1>
          <p className="text-xs sm:text-sm text-muted-foreground mt-0.5">
            Instant on-demand patient pickup, hospital visits, ambulances, and personal rides in {selectedCity && selectedCity !== 'All' ? selectedCity : 'your area'}.
          </p>
        </div>

        <Button
          variant="outline"
          size="sm"
          onClick={() => navigate('/patient/rides')}
          className="rounded-xl text-xs gap-1.5 h-9"
        >
          My Rides
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* LEFT PANEL (~40%): Booking / Active Ride controller */}
        <div className="lg:col-span-5 space-y-4">
          {activeRide ? (
            /* ACTIVE RIDE CONTROLLER */
            <div className="space-y-4">
              <div className="flex items-center justify-between px-1">
                <Badge variant="outline" className="text-xs font-mono font-bold">
                  {activeRide.bookingNumber}
                </Badge>
                {activeRide.status === 'completed' && activeRide.payment?.status === 'paid' && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setActiveRide(null);
                      setPickup(null);
                      setDrop(null);
                    }}
                    className="text-xs h-7 text-primary"
                  >
                    Book Another Ride
                  </Button>
                )}
              </div>

              <RideStatusPanel
                ride={activeRide}
                onCancelRide={handleCancelRide}
                onRetrySearch={handleBookNow}
                onRideCompletedPayment={(payment) => {
                  setActiveRide((prev: any) => ({ ...prev, payment }));
                }}
                onRefreshRide={async () => {
                  const res = await api.getRide(activeRide._id);
                  if (res.ride) setActiveRide(res.ride);
                }}
              />
            </div>
          ) : (
            /* NEW BOOKING FORM */
            <div className="rounded-2xl border border-border/80 bg-card p-4 sm:p-5 shadow-sm space-y-4">
              {/* Pickup & Drop Inputs */}
              <div className="space-y-3">
                <LocationInput
                  label="Pickup Location"
                  placeholder="Enter hospital, clinic, or street"
                  value={pickup}
                  onChange={setPickup}
                  showCurrentLocationButton={true}
                  pinColor="text-emerald-600"
                />

                <LocationInput
                  label="Dropoff Destination"
                  placeholder="Enter destination address or landmark"
                  value={drop}
                  onChange={setDrop}
                  pinColor="text-rose-600"
                />
              </div>

              {/* Vehicle Type Selector */}
              <div className="space-y-2 pt-1">
                <label className="text-xs font-semibold text-foreground block">
                  Select Vehicle Type
                </label>
                <VehicleTypeSelector
                  selected={vehicleType}
                  onSelect={setVehicleType}
                  estimates={estimates}
                  isEmergency={isEmergency}
                />
              </div>

              {/* Emergency Ambulance Toggle */}
              {vehicleType === 'ambulance' && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className="rounded-xl border border-red-500/30 bg-red-500/10 p-3 flex items-start gap-2.5"
                >
                  <Checkbox
                    id="emergency-toggle"
                    checked={isEmergency}
                    onCheckedChange={(checked) => setIsEmergency(Boolean(checked))}
                    className="mt-0.5 data-[state=checked]:bg-red-600 data-[state=checked]:border-red-600"
                  />
                  <div className="grid gap-0.5 leading-none">
                    <label
                      htmlFor="emergency-toggle"
                      className="text-xs font-bold text-red-700 dark:text-red-400 cursor-pointer"
                    >
                      🚨 This is an Emergency (Priority Dispatch)
                    </label>
                    <p className="text-[11px] text-muted-foreground">
                      Simultaneously notifies all nearby ambulance drivers with urgent audio alert and priority dispatch.
                    </p>
                  </div>
                </motion.div>
              )}

              {/* Fare & ETA Breakdown */}
              {selectedEstimate && (
                <FareEstimateCard
                  vehicleType={vehicleType}
                  distanceKm={distanceKm}
                  durationMin={selectedEstimate.durationMin || 15}
                  etaMin={selectedEstimate.etaMin || 4}
                  fare={selectedEstimate.fare || { base: 0, distanceCharge: 0, surge: 0, total: 0 }}
                  isEmergency={isEmergency}
                />
              )}

              {/* Book Now Action */}
              <Button
                type="button"
                onClick={handleBookNow}
                disabled={!pickup || !drop || bookingLoading || loadingEstimate}
                className="w-full h-12 rounded-xl text-sm font-bold shadow-md gap-2"
              >
                {bookingLoading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Connecting to Drivers...
                  </>
                ) : (
                  <>
                    <Car className="w-4 h-4" />
                    Book {vehicleType.replace('_', ' ').toUpperCase()} Now
                  </>
                )}
              </Button>
            </div>
          )}
        </div>

        {/* RIGHT PANEL (~60%): Interactive Map */}
        <div className="lg:col-span-7 sticky top-20">
          <div className="h-[460px] sm:h-[560px] lg:h-[620px] w-full">
            <RideMap
              pickup={pickup ? { lat: pickup.lat, lng: pickup.lng } : null}
              drop={drop ? { lat: drop.lat, lng: drop.lng } : null}
              riderLocation={riderLocation}
              vehicleType={vehicleType}
              isEmergency={vehicleType === 'ambulance' && isEmergency}
            />
          </div>
        </div>
      </div>

      {/* FULL-SCREEN Instant Searching Overlay for searching rides */}
      {activeRide?.status === 'searching' && (
        <InstantSearchingScreen
          type={activeRide.vehicleType === 'ambulance' ? 'ambulance' : 'ride'}
          radiusKm={activeRide.currentDispatchRadius || 5}
          onCancel={() => handleCancelRide('Cancelled by user during search')}
          requestDetails={activeRide}
        />
      )}

      {/* FULL-SCREEN No Responders Found Overlay */}
      {activeRide?.status === 'no_riders_found' && (
        <InstantNoRespondersScreen
          type={activeRide.vehicleType === 'ambulance' ? 'ambulance' : 'ride'}
          onRetry={handleBookNow}
          onDismiss={() => {
            setActiveRide(null);
            setPickup(null);
            setDrop(null);
          }}
          message="All nearby drivers and emergency ambulances are currently committed. You can retry with a wider search or request 108 emergency services."
        />
      )}

      {/* FULL-SCREEN Assigned Overlay (File 04) — trip panel stays underneath */}
      {activeRide?.status === 'accepted' && !assignedDismissed && (
        <InstantAssignedScreen
          type={activeRide.vehicleType === 'ambulance' ? 'ambulance' : 'ride'}
          assignedDetails={{
            providerDetails: activeRide.riderDetails,
            distanceKm: activeRide.riderDetails?.distanceKm,
          }}
          requestDetails={activeRide}
          onViewDetails={() => setAssignedDismissed(true)}
          onDismiss={() => setAssignedDismissed(true)}
        />
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Activity, ArrowRight, CheckCircle, KeyRound, Mail, ArrowLeft, RefreshCw, Eye, EyeOff } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';
import type { Unmodelled } from '@/lib/apiTypes';

export default function ForgotPassword() {
  const navigate = useNavigate();
  const [step, setStep] = useState('email');
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [message, setMessage] = useState('');

  const passwordStrength = (() => {
    if (!password) return { score: 0, label: '', color: 'bg-border' };
    let score = 0;
    if (password.length >= 10) score += 1;
    if (password.length >= 12) score += 1;
    if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score += 1;
    if (/\d/.test(password)) score += 1;
    if (/[^a-zA-Z0-9]/.test(password)) score += 1;
    const labels = ['', 'Weak', 'Fair', 'Good', 'Strong', 'Very Strong'];
    const colors = ['', 'bg-red-500', 'bg-orange-500', 'bg-yellow-500', 'bg-lime-500', 'bg-green-500'];
    return { score, label: labels[score], color: colors[score] };
  })();
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [resendLoading, setResendLoading] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);

  useEffect(() => {
    if (resendCooldown <= 0) return;
    const timer = setTimeout(() => setResendCooldown(s => Math.max(0, s - 1)), 1000);
    return () => clearTimeout(timer);
  }, [resendCooldown]);

  const requestReset = async (e: Unmodelled) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);
    try {
      const data = await api.forgotPassword({ email });
      setMessage(data.message || 'Password reset OTP sent to your email.');
      setStep('reset');
    } catch (err: any) {
      setError(err.message || 'Unable to send password reset OTP');
    } finally {
      setLoading(false);
    }
  };

  const resetPassword = async (e: Unmodelled) => {
    e.preventDefault();
    setError('');
    setMessage('');

    if (otp.length !== 6) {
      setError('Enter the 6-digit reset OTP');
      return;
    }
    if (password.length < 12) {
      setError('Password must be at least 12 characters');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);
    try {
      const data = await api.resetPassword({ email, otp, password });
      setMessage(data.message || 'Password updated successfully.');
      setStep('done');
    } catch (err: any) {
      setError(err.message || 'Unable to reset password');
    } finally {
      setLoading(false);
    }
  };

  const handleResendOTP = async () => {
    setResendLoading(true);
    setError('');
    setMessage('');
    try {
      await api.forgotPassword({ email });
      setMessage('A fresh reset OTP has been sent to your email.');
      setResendCooldown(60);
    } catch (err: any) {
      setError(err.message || 'Failed to resend OTP');
    } finally {
      setResendLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-6">
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.35 }}
        className="w-full max-w-md"
      >
        <div className="mb-8 flex items-center gap-3">
          <div className="w-12 h-12 flex items-center justify-center rounded-xl overflow-hidden shadow-sm">
            <img src="/logo.png" alt="FindMedi Logo" className="w-full h-full object-cover" />
          </div>
          <h1 className="font-heading text-xl font-bold text-foreground">FindMedi</h1>
        </div>

        <div className="bg-card border border-border/60 rounded-2xl p-8 shadow-xl">
          <div className="w-14 h-14 rounded-2xl bg-primary/10 flex items-center justify-center mb-5">
            {step === 'done' ? <CheckCircle className="w-7 h-7 text-success" /> : <KeyRound className="w-7 h-7 text-primary" />}
          </div>

          <h2 className="font-heading text-2xl font-bold text-foreground mb-2">
            {step === 'done' ? 'Password Updated' : 'Forgot Password'}
          </h2>
          <p className="text-sm text-muted-foreground mb-6">
            {step === 'email'
              ? 'Enter your account email to receive a reset OTP.'
              : step === 'reset'
                ? 'Enter the OTP from your email and choose a new password.'
                : 'Your new password is ready to use.'}
          </p>

          {step === 'email' && (
            <form onSubmit={requestReset} className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Email</label>
                <Input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Enter your email" required />
              </div>
              <Button type="submit" className="w-full gap-2" disabled={loading}>
                {loading ? <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <Mail className="w-4 h-4" />}
                Send Reset OTP
              </Button>
            </form>
          )}

          {step === 'reset' && (
            <form onSubmit={resetPassword} className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Reset OTP</label>
                <div className="flex gap-2">
                  <Input inputMode="numeric" maxLength={6} value={otp} onChange={e => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))} placeholder="6-digit OTP" required className="flex-1" />
                  <Button type="button" variant="outline" size="icon" onClick={handleResendOTP} disabled={resendCooldown > 0 || resendLoading} className="shrink-0">
                    <RefreshCw className={`h-4 w-4 ${resendLoading ? 'animate-spin' : ''}`} />
                  </Button>
                </div>
                {resendCooldown > 0 && <p className="text-xs text-muted-foreground mt-1">Resend in {resendCooldown}s</p>}
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">New Password</label>
                <div className="relative">
                  <Input type={showPassword ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} placeholder="Create a new password" required className="pr-10" />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors">
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
                {password && (
                  <div className="mt-2 space-y-1">
                    <div className="flex gap-1">
                      {[1,2,3,4,5].map(i => (
                        <div key={i} className={`h-1.5 flex-1 rounded-full ${i <= passwordStrength.score ? passwordStrength.color : 'bg-border'}`} />
                      ))}
                    </div>
                    <p className="text-xs text-muted-foreground">{passwordStrength.label}</p>
                  </div>
                )}
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Confirm Password</label>
                <div className="relative">
                  <Input type={showConfirm ? 'text' : 'password'} value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Confirm new password" required className="pr-10" />
                  <button type="button" onClick={() => setShowConfirm(!showConfirm)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors">
                    {showConfirm ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>
              <Button type="submit" className="w-full gap-2" disabled={loading}>
                {loading ? <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <ArrowRight className="w-4 h-4" />}
                Update Password
              </Button>
              <button type="button" onClick={() => setStep('email')} className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mx-auto">
                <ArrowLeft className="w-4 h-4" /> Back to email
              </button>
            </form>
          )}

          {message && <p className="mt-4 text-sm text-success bg-success/10 px-3 py-2 rounded-lg">{message}</p>}
          {error && <p className="mt-4 text-sm text-destructive bg-destructive/10 px-3 py-2 rounded-lg">{error}</p>}

          {step === 'done' ? (
            <div className="mt-6 space-y-3">
              <p className="text-sm text-muted-foreground text-center">Your password has been reset successfully. Sign in with your new password.</p>
              <Button onClick={() => navigate('/login')} className="w-full gap-2" size="lg">
                <Activity className="w-4 h-4" /> Sign In Now
              </Button>
            </div>
          ) : (
            <p className="text-sm text-muted-foreground text-center mt-6">
              <Link to="/login" className="text-primary font-medium hover:underline">Back to login</Link>
            </p>
          )}
        </div>
      </motion.div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import FormRenderer from '@/components/forms/FormRenderer';
import { saveDraft, loadDraft, clearDraft, queueWrite, syncNow, pendingWrites } from '@/lib/offlineQueue';

/**
 * File 14 §14.1 + file 15 §15.5 — form fill: pick a published template,
 * fill (autosaved draft locally), submit; offline failures queue and sync.
 */
export default function FormsFill() {
  const [templates, setTemplates] = useState<any[]>([]);
  const [sel, setSel] = useState<any>(null);
  const [values, setValues] = useState<Record<string, any>>({});
  const [pending, setPending] = useState(0);
  const [locale, setLocale] = useState<'en' | 'hi'>('en');

  useEffect(() => {
    (async () => {
      try {
        const r: any = await (api as any).getFormTemplates({});
        setTemplates((r?.templates || []).filter((t: any) => t.status === 'Published'));
      } catch { toast.error('Failed to load templates'); }
      setPending((await pendingWrites().catch(() => [] as any[])).length);
    })();
  }, []);

  useEffect(() => {
    if (!sel) return;
    setValues(loadDraft(`form:${sel.key}:v${sel.version}`) || {});
  }, [sel]);

  const change = (v: Record<string, any>) => {
    setValues(v);
    if (sel) saveDraft(`form:${sel.key}:v${sel.version}`, v);
  };

  const submit = async () => {
    if (!sel) return;
    const payload = { templateKey: sel.key, values };
    try {
      await (api as any).submitFormResponse(payload);
      clearDraft(`form:${sel.key}:v${sel.version}`);
      toast.success('Submitted');
      setValues({});
    } catch {
      await queueWrite('/forms/responses', 'POST', payload);
      setPending((await pendingWrites().catch(() => [] as any[])).length);
      toast.success('Offline — queued, will sync');
    }
  };

  const sync = async () => {
    const r = await syncNow(async (w) => {
      const res = await fetch(w.url, {
        method: w.method,
        headers: { 'Content-Type': 'application/json', 'Idempotency-Key': w.idempotencyKey },
        body: JSON.stringify(w.body),
        credentials: 'include',
      });
      if (!res.ok) throw new Error(`sync ${res.status}`);
    }).catch(() => ({ synced: 0, pending: 0 }));
    setPending(r.pending);
    toast.success(`Synced ${r.synced}, ${r.pending} pending`);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <h1 className="text-2xl font-heading font-bold mr-auto">Forms</h1>
        <div className="flex items-center gap-1 border rounded-md p-0.5 text-xs">
          <button
            type="button"
            className={`px-2 py-0.5 rounded transition-colors ${locale === 'en' ? 'bg-primary text-primary-foreground font-medium' : 'text-muted-foreground hover:text-foreground'}`}
            onClick={() => setLocale('en')}
          >
            EN
          </button>
          <button
            type="button"
            className={`px-2 py-0.5 rounded transition-colors ${locale === 'hi' ? 'bg-primary text-primary-foreground font-medium' : 'text-muted-foreground hover:text-foreground'}`}
            onClick={() => setLocale('hi')}
          >
            हिन्दी
          </button>
        </div>
        {pending > 0 && <Button size="sm" variant="outline" onClick={sync}>Sync now ({pending})</Button>}
      </div>
      {!sel ? (
        <div className="grid sm:grid-cols-2 gap-3">
          {templates.map((t: any) => (
            <Card key={t._id}>
              <CardContent className="p-4 flex items-center gap-2">
                <div>
                  <p className="font-bold">{locale === 'hi' && t.titleHi ? t.titleHi : t.title}</p>
                  <p className="text-xs text-muted-foreground">v{t.version} · {t.category}</p>
                </div>
                <span className="flex-1" />
                <Button size="sm" onClick={() => setSel(t)}>{locale === 'hi' ? 'खोलें' : 'Open'}</Button>
              </CardContent>
            </Card>
          ))}
          {templates.length === 0 && <p className="text-sm text-muted-foreground">No published templates.</p>}
        </div>
      ) : (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <span>{locale === 'hi' && sel.titleHi ? sel.titleHi : sel.title}</span>
              <span className="flex-1" />
              <Button size="sm" variant="ghost" onClick={() => setSel(null)}>Back</Button>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <FormRenderer
              template={sel}
              values={values}
              onChange={change}
              onSubmit={submit}
              submitLabel={locale === 'hi' ? 'प्रस्तुत करें' : 'Submit response'}
              locale={locale}
            />
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Search, UserPlus, Ticket, Receipt, MonitorPlay } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import PatientBanner from '@/components/clinical/PatientBanner';
import type { Unmodelled } from '@/lib/apiTypes';

/**
 * File 09 §5.1 — front-desk stub: quick patient search (UHID/phone/name),
 * links to registration, tokens, OPD billing counter and queue display.
 */
export default function FrontDesk() {
  const [q, setQ] = useState('');
  const [rows, setRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedId, setSelectedId] = useState('');
  const [enquiries, setEnquiries] = useState<any[]>([]);
  const [enq, setEnq] = useState({ name: '', phone: '', interest: '' });
  // File 22 P1-12: duplicates + ABHA + visitor pass.
  const [dups, setDups] = useState<any[]>([]);
  const [abha, setAbha] = useState('');
  const [visitor, setVisitor] = useState({ visitorName: '', phone: '', relation: '' });
  // File 22 P0-left: check-in + bill collection.
  const [checkInDept, setCheckInDept] = useState('');
  const [selectedBillId, setSelectedBillId] = useState('');

  const loadEnquiries = async () => {
    try {
      const r: any = await api.enquiries({ status: 'Open' });
      setEnquiries(r?.enquiries || []);
    } catch { /* optional */ }
  };

  const loadDups = async () => {
    try {
      const r: any = await api.patientDuplicates();
      setDups(r?.groups || []);
    } catch { /* optional */ }
  };

  const search = async () => {
    if (!q.trim()) return;
    setLoading(true);
    try {
      const res: any = await (api as any).getPatients({ search: q, limit: 10 });
      setRows(res?.data || res?.patients || []);
    } catch { setRows([]); }
    setLoading(false);
    loadEnquiries();
  };

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-2xl font-heading font-bold">Front Desk</h1>
        <p className="text-sm text-muted-foreground">Registration · tokens · OPD billing · queue display.</p>
      </div>
      <Card>
        <CardHeader><CardTitle className="text-base flex items-center gap-2"><Search className="w-4 h-4" />Quick patient search</CardTitle></CardHeader>
        <CardContent className="space-y-3">
          <div className="flex gap-2">
            <Input placeholder="UHID / phone / name" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && search()} />
            <Button onClick={search} disabled={loading}>Search</Button>
          </div>
          {rows.map((p: any) => (
            <div key={p._id || p.id} onClick={() => setSelectedId(p._id || p.id || '')}
              className={`text-sm rounded-lg border p-2.5 cursor-pointer ${selectedId === (p._id || p.id) ? 'border-primary' : 'border-border/50'}`}>
              <span className="font-medium">{p.name}</span>
              <span className="text-muted-foreground"> · {p.uhid || p.phone || ''}</span>
            </div>
          ))}
          {/* File 22 P0-2: flag chips for the selected patient */}
          {selectedId && <PatientBanner patientId={selectedId} />}
          {/* File 22 P0-left: quick check-in (token) + bill collection for the selected patient */}
          {selectedId ? (
            <div className="flex flex-wrap gap-2 rounded-lg border border-border/50 p-2.5">
              <Input className="w-44 h-8 text-xs" placeholder="Department (e.g. General Medicine)" value={checkInDept} onChange={(e) => setCheckInDept(e.target.value)} />
              <Button size="sm" onClick={async () => {
                try {
                  const sel = rows.find((p: any) => (p._id || p.id) === selectedId);
                  await api.post('/tokens/generate', {
                    patientId: sel?.userId || sel?._id, patientName: sel?.name,
                    uhid: sel?.uhid, department: checkInDept || 'General',
                  });
                  setCheckInDept('');
                  toast.success('Token generated');
                } catch (err: any) { toast.error(err?.response?.data?.message || 'Token failed'); }
              }}>Check in</Button>
              <Button size="sm" variant="outline" onClick={async () => {
                try {
                  const r: any = await (api as Unmodelled).getBills({ patientId: selectedId, status: 'Unpaid', limit: 1 });
                  const bill = (r?.data || r?.bills || [])[0];
                  if (bill) { setSelectedBillId(bill._id); toast.info(`Bill ${bill.invoiceId} — balance ₹${bill.balance ?? bill.amount}`); }
                  else toast.success('No unpaid bills');
                } catch { toast.error('Billing lookup failed'); }
              }}>Collect bill</Button>
            </div>
          ) : null}
          {/* File 22 P1-12: ABHA link + visitor pass for the selected patient */}
          {selectedId ? (
            <div className="flex flex-wrap gap-2 rounded-lg border border-border/50 p-2.5">
              <Input className="w-44 h-8 text-xs" placeholder="user@sbx (ABHA)" value={abha} onChange={(e) => setAbha(e.target.value)} />
              <Button size="sm" variant="outline" onClick={async () => {
                try { await api.linkAbha(selectedId, abha); setAbha(''); search(); } catch { /* invalid format */ }
              }}>Link ABHA</Button>
              <Input className="w-32 h-8 text-xs" placeholder="Visitor name" value={visitor.visitorName} onChange={(e) => setVisitor({ ...visitor, visitorName: e.target.value })} />
              <Input className="w-28 h-8 text-xs" placeholder="Phone" value={visitor.phone} onChange={(e) => setVisitor({ ...visitor, phone: e.target.value })} />
              <Input className="w-28 h-8 text-xs" placeholder="Relation" value={visitor.relation} onChange={(e) => setVisitor({ ...visitor, relation: e.target.value })} />
              <Button size="sm" variant="outline" onClick={async () => {
                try {
                  const sel = rows.find((p: any) => (p._id || p.id) === selectedId);
                  await api.safetyCreate('visitor-passes', { patientId: sel?.userId || undefined, ...visitor });
                  setVisitor({ visitorName: '', phone: '', relation: '' });
                } catch { /* validation */ }
              }}>Issue pass</Button>
            </div>
          ) : null}
          {q && !loading && rows.length === 0 && <p className="text-sm text-muted-foreground">No match — register as new patient.</p>}
        </CardContent>
      </Card>
      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { to: '/patient-registration', icon: UserPlus, label: 'New registration' },
          { to: '/opd-token', icon: Ticket, label: 'Tokens & queue' },
          { to: '/billing', icon: Receipt, label: 'OPD billing counter' },
          { to: '/display/queue', icon: MonitorPlay, label: 'Queue display (TV)' },
        ].map((c) => (
          <Link key={c.to} to={c.to}>
            <Card className="hover:border-primary/40 transition-colors">
              <CardContent className="p-4 flex items-center gap-3">
                <c.icon className="w-5 h-5 text-primary" />
                <span className="text-sm font-medium">{c.label}</span>
              </CardContent>
            </Card>
          </Link>
        ))}
      </div>
      {/* File 22 P0-6: walk-in enquiry log */}
      <Card>
        <CardHeader><CardTitle className="text-base">Open enquiries ({enquiries.length})</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          <div className="flex flex-wrap gap-2">
            <Input className="w-40" placeholder="Name" value={enq.name} onChange={(e) => setEnq({ ...enq, name: e.target.value })} />
            <Input className="w-36" placeholder="Phone" value={enq.phone} onChange={(e) => setEnq({ ...enq, phone: e.target.value })} />
            <Input className="w-48" placeholder="Interested in…" value={enq.interest} onChange={(e) => setEnq({ ...enq, interest: e.target.value })} />
            <Button onClick={async () => {
              try { await api.createEnquiry(enq); setEnq({ name: '', phone: '', interest: '' }); loadEnquiries(); }
              catch { /* toast? keep silent-fail minimal */ }
            }}>Log enquiry</Button>
          </div>
          {enquiries.slice(0, 8).map((e: any) => (
            <div key={e._id} className="flex items-center justify-between gap-2 text-sm rounded-lg border border-border/50 p-2">
              <span><b>{e.name}</b> <span className="text-muted-foreground">· {e.phone} · {e.interest}</span></span>
              <Button size="sm" variant="outline" onClick={async () => { await api.patchEnquiry(e._id, { status: 'Dropped' }); loadEnquiries(); }}>Drop</Button>
            </div>
          ))}
        </CardContent>
      </Card>
      {/* File 22 P1-12: duplicate groups + merge */}
      <Card>
        <CardHeader><CardTitle className="text-base flex items-center gap-2">Duplicates
          <Button size="sm" variant="outline" onClick={loadDups}>Scan</Button>
        </CardTitle></CardHeader>
        <CardContent className="space-y-2">
          {dups.slice(0, 10).map((g: any, i: number) => (
            <div key={i} className="rounded-lg border border-border/50 p-2 text-sm">
              <p className="font-mono text-xs text-muted-foreground">{g.key}</p>
              {g.patients.map((p: any) => (
                <div key={p._id} className="flex items-center justify-between gap-2 py-0.5">
                  <span>{p.name} <span className="text-muted-foreground">· {p.uhid || ''}</span></span>
                  {g.patients[0]._id !== p._id ? (
                    <Button size="sm" variant="outline" onClick={async () => {
                      if (!window.confirm(`Merge ${p.name} into ${g.patients[0].name}? This re-points records and cannot be undone.`)) return;
                      try { await api.mergePatients(g.patients[0]._id, p._id); loadDups(); } catch { /* conflict */ }
                    }}>Merge into first</Button>
                  ) : <span className="text-xs text-muted-foreground">survivor</span>}
                </div>
              ))}
            </div>
          ))}
          {dups.length === 0 ? <p className="text-sm text-muted-foreground">No duplicates found (or not scanned yet).</p> : null}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { HeartPulse, Lock, ArrowRight, X, ExternalLink, ShieldCheck } from 'lucide-react';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { HEALTHCARE_CATALOGUE, type CatalogueItem, type CatalogueSection } from '@/data/healthcareCatalogue';

export default function HealthcarePage() {
  const navigate = useNavigate();
  const [hospitalsCount, setHospitalsCount] = useState<number>(0);
  const [doctorsCount, setDoctorsCount] = useState<number>(0);
  const [activeItem, setActiveItem] = useState<CatalogueItem | null>(null);

  useEffect(() => {
    api.getHospitals({ status: 'approved' })
      .then((data: any) => {
        const list = Array.isArray(data) ? data : (data?.data || data?.hospitals || []);
        if (Array.isArray(list)) setHospitalsCount(list.length);
      })
      .catch(() => {});

    api.getDoctors({ doctor_type: 'clinic' })
      .then((data: any) => {
        const docList = Array.isArray(data) ? data : (data?.doctors || data?.data || []);
        if (Array.isArray(docList)) setDoctorsCount(docList.length);
      })
      .catch(() => {});
  }, []);

  const go = (route?: string, label?: string) => {
    if (!route) {
      toast.info(`${label || 'Ye section'} abhi launch ho raha hai`);
      return;
    }
    if (route.startsWith('tel:') || route.startsWith('http')) {
      window.location.href = route;
      return;
    }
    navigate(route);
  };

  const handleCardClick = (item: CatalogueItem) => {
    if (item.subs && item.subs.length > 0) {
      setActiveItem(item);
    } else {
      go(item.route, item.name);
    }
  };

  const itemCount = (item: CatalogueItem) => {
    if (item.countKey === 'hospitals' && hospitalsCount > 0) return `${hospitalsCount} hospital${hospitalsCount === 1 ? '' : 's'}`;
    if (item.countKey === 'doctors' && doctorsCount > 0) return `${doctorsCount} doctor${doctorsCount === 1 ? '' : 's'}`;
    return `${item.subs.length} subcategor${item.subs.length === 1 ? 'y' : 'ies'}`;
  };

  return (
    <div className="min-h-screen bg-background text-foreground pb-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        {/* ── Page Header ── */}
        <div className="flex items-center gap-3.5 mb-8">
          <div className="w-12 h-12 rounded-2xl bg-teal-500/10 border border-teal-500/20 flex items-center justify-center text-teal-600 shadow-xs">
            <HeartPulse className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-2xl sm:text-3xl font-heading font-bold text-foreground">
              Healthcare Categories & Services
            </h1>
