                  <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${activeItem.color} flex items-center justify-center shrink-0 shadow-xs`}>
                    {React.createElement(activeItem.icon, { className: `w-6 h-6 ${activeItem.textColor}` })}
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="font-heading text-lg font-bold text-foreground">
                        {activeItem.name}
                      </h3>
                      {activeItem.tier && (
                        <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-primary/10 text-primary border border-primary/20">
                          Tier {activeItem.tier}
                        </span>
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {activeItem.summary}
                    </p>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => setActiveItem(null)}
                  className="p-1.5 rounded-lg border border-border/80 hover:bg-muted text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
                  aria-label="Close"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {/* Subcategories List */}
              <div className="p-5 overflow-y-auto space-y-3 flex-1">
                <div className="flex items-center justify-between text-xs text-muted-foreground font-medium mb-1">
                  <span>Available Subcategories & Bookable Services ({activeItem.subs.length})</span>
                  {activeItem.regulatedBy && (
                    <span className="flex items-center gap-1 text-[11px] text-teal-600 font-semibold">
                      <ShieldCheck className="w-3.5 h-3.5" />
                      Regulated: {activeItem.regulatedBy}
                    </span>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                  {activeItem.subs.map((sub, idx) => (
                    <button
                      key={sub.label}
                      type="button"
                      onClick={() => {
                        const target = sub.route ?? activeItem.route;
                        setActiveItem(null);
                        go(target, sub.label);
                      }}
                      className="flex items-center justify-between p-3 rounded-xl border border-border/70 bg-background hover:bg-primary/5 hover:border-primary/50 text-left transition-all group cursor-pointer"
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <span className="w-6 h-6 rounded-lg bg-muted flex items-center justify-center text-xs font-semibold text-muted-foreground group-hover:bg-primary group-hover:text-primary-foreground transition-colors shrink-0">
                          {idx + 1}
                        </span>
                        <span className="text-xs font-semibold text-foreground truncate group-hover:text-primary transition-colors">
                          {sub.label}
                        </span>
                      </div>
                      <ExternalLink className="w-3.5 h-3.5 text-muted-foreground group-hover:text-primary shrink-0 ml-2 transition-transform group-hover:translate-x-0.5" />
                    </button>
                  ))}
                </div>
              </div>

              {/* Modal Footer */}
              <div className="p-4 border-t border-border/70 bg-muted/20 flex items-center justify-between gap-3">
                <button
                  type="button"
                  onClick={() => setActiveItem(null)}
                  className="px-4 py-2 rounded-xl text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
                >
                  Close
                </button>
                {activeItem.route && (
                  <button
                    type="button"
                    onClick={() => {
                      const target = activeItem.route;
                      setActiveItem(null);
                      go(target, activeItem.name);
                    }}
                    className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-primary text-primary-foreground text-xs font-semibold hover:opacity-90 transition-opacity cursor-pointer shadow-xs"
                  >
                    <span>View All in {activeItem.name.split('(')[0].trim()}</span>
                    <ArrowRight className="w-3.5 h-3.5" />
                  </button>
                )}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { AlertTriangle, BedDouble, Users, Wallet, CheckCircle, TrendingUp, TrendingDown, ListVideo, EyeOff, Shield } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { api } from '@/lib/api';

/**
 * File 09 §02 — hospital admin dashboard v2: live ops strip (single call),
 * money (billed/collected/outstanding), alerts action center, bed heatmap,
 * revenue split, TPA pipeline, staff on duty. Every tile degrades
 * independently (per-tile error flags from the backend).
 */
const inr = (n: any) => `₹${Number(n || 0).toLocaleString('en-IN')}`;

export default function HospitalDashboardV2() {
  const [ops, setOps] = useState<any>(null);
  const [rev, setRev] = useState<any>(null);
  const [alerts, setAlerts] = useState<any[]>([]);
  const [beds, setBeds] = useState<any>(null);
  const [staff, setStaff] = useState<any>(null);
  const [tpa, setTpa] = useState<any>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  // File 22 P0-7: range + compare + live queue + per-user widget prefs.
  const [range, setRange] = useState('7');
  const [compare, setCompare] = useState(true);
  const [overview, setOverview] = useState<any>(null);
  const [queue, setQueue] = useState<any>(null);
  const [hidden, setHidden] = useState<string[]>(() => {
    try { return JSON.parse(localStorage.getItem('dashv2-hidden') || '[]'); } catch { return []; }
  });

  const toggleWidget = (k: string) => {
    setHidden((h) => {
      const next = h.includes(k) ? h.filter((x) => x !== k) : [...h, k];
      try { localStorage.setItem('dashv2-hidden', JSON.stringify(next)); } catch { /* noop */ }
      return next;
    });
  };

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [o, r, b, s, t] = await Promise.all([
          (api as any).getOpsTiles().catch((e: any) => ({ _err: String(e?.message || e) })),
          (api as any).getRevenueSplit().catch((e: any) => ({ _err: String(e?.message || e) })),
          (api as any).getBedHeatmap().catch((e: any) => ({ _err: String(e?.message || e) })),
          (api as any).getStaffOnDuty().catch((e: any) => ({ _err: String(e?.message || e) })),
          (api as any).getTpaPipeline().catch((e: any) => ({ _err: String(e?.message || e) })),
        ]);
        if (cancelled) return;
        const errs: Record<string, string> = {};
        if (o?._err) errs.ops = o._err; else setOps(o?.data || o);
        if (r?._err) errs.rev = r._err; else setRev(r);
        if (b?._err) errs.beds = b._err; else setBeds(b);
        if (s?._err) errs.staff = s._err; else setStaff(s);
        if (t?._err) errs.tpa = t._err; else setTpa(t);
        setErrors(errs);
        const a: any = await (api as any).getDashAlerts().catch(() => null);
        if (!cancelled && a) setAlerts(a?.alerts || []);
      } catch { /* tiles degrade independently */ }
    })();
    return () => { cancelled = true; };
  }, []);

  // Overview (range + compare) + live queue, refreshed with range/compare.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const to = new Date().toISOString().slice(0, 10);
      const from = new Date(Date.now() - (Number(range) - 1) * 86400000).toISOString().slice(0, 10);
      const [ov, q] = await Promise.all([
        api.getDashOverview({ from, to, compare: compare ? '1' : '0' }).catch(() => null),
        api.getDashQueue().catch(() => null),
      ]);
      if (cancelled) return;
      if (ov) setOverview(ov);
      if (q) setQueue(q);
    })();
    const t = setInterval(async () => {
      const q = await api.getDashQueue().catch(() => null);
      if (!cancelled && q) setQueue(q);
    }, 60000);
    return () => { cancelled = true; clearInterval(t); };
  }, [range, compare]);

  const ack = async (id: string) => {
    try {
      await (api as any).ackDashAlert(id, {});
      setAlerts((p) => p.filter((a) => String(a._id || a.id) !== String(id)));
    } catch { /* noop */ }
  };

  const money = ops?.money || {};

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-heading font-bold">Hospital Overview</h1>
          <p className="text-sm text-muted-foreground">Live ops · money · alerts — one round-trip per section.</p>
        </div>
        <div className="flex items-center gap-2">
          <select aria-label="Range" className="h-9 rounded-md border px-2 text-sm" value={range} onChange={(e) => setRange(e.target.value)}>
            <option value="1">Today</option>
            <option value="7">7 days</option>
            <option value="30">30 days</option>
          </select>
          <label className="flex items-center gap-1 text-xs"><input type="checkbox" checked={compare} onChange={(e) => setCompare(e.target.checked)} /> compare</label>
          <Link to="/dashboard/overview"><Button variant="outline" size="sm">Overview</Button></Link>
          <Link to="/dashboard/queue"><Button variant="outline" size="sm">Live queue</Button></Link>
        </div>
      </div>

      {/* P0-7: KPI overview with compare deltas + collection sparkline */}
      {!hidden.includes('kpis') && overview ? (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center justify-between">
              Period {overview.from} → {overview.to}
              <Button size="sm" variant="ghost" onClick={() => toggleWidget('kpis')}><EyeOff size={13} /> hide</Button>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-3">
              {[
                { k: 'collected', label: 'Collected', money: true },
                { k: 'billed', label: 'Billed', money: true },
                { k: 'appointments', label: 'Appointments', money: false },
                { k: 'admissions', label: 'Admissions', money: false },
              ].map(({ k, label, money: isMoney }) => {
                const v = overview.kpis?.[k];
                if (!v) return null;
                const up = (v.deltaPct ?? 0) >= 0;
                return (
                  <div key={k} className="rounded-lg border p-3">
                    <p className="text-xs text-muted-foreground">{label}</p>
                    <p className="text-lg font-bold">{isMoney ? inr(v.value) : (v.value ?? 0).toLocaleString('en-IN')}</p>
                    {compare && v.deltaPct != null ? (
                      <p className={`flex items-center gap-1 text-xs font-semibold ${up ? 'text-green-700' : 'text-red-700'}`}>
                        {up ? <TrendingUp size={13} /> : <TrendingDown size={13} />}{Math.abs(v.deltaPct)}% vs prev
                      </p>
                    ) : null}
                  </div>
                );
              })}
            </div>
            <div className="h-36">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={overview.spark || []}>
                  <XAxis dataKey="date" tick={{ fontSize: 10 }} tickFormatter={(d: string) => d.slice(5)} />
                  <YAxis tick={{ fontSize: 10 }} />
                  <Tooltip formatter={(v: any) => [`₹${Number(v).toLocaleString('en-IN')}`, 'collected']} />
                  <Area type="monotone" dataKey="paid" stroke="hsl(174,62%,38%)" fill="hsl(174,62%,38%,0.25)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      ) : null}
      {hidden.includes('kpis') ? (
        <Button size="sm" variant="outline" onClick={() => toggleWidget('kpis')}>Show KPI overview</Button>
      ) : null}

      {/* P0-7: live OPD queue */}
      {!hidden.includes('queue') && queue ? (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center justify-between">
              <span className="flex items-center gap-2"><ListVideo size={15} /> Live OPD queue ({queue.total}) · longest wait {queue.longestMin}m</span>
              <Button size="sm" variant="ghost" onClick={() => toggleWidget('queue')}><EyeOff size={13} /> hide</Button>
            </CardTitle>
          </CardHeader>
          <CardContent className="flex flex-wrap gap-2">
            {(queue.departments || []).map((d: any) => (
              <span key={d.dept} className="rounded-md border px-2.5 py-1 text-xs">
                <b>{d.dept}</b> · {d.waiting} waiting · longest {d.longestMin}m
              </span>
            ))}
            {!(queue.departments || []).length ? <p className="text-sm text-muted-foreground">Queue empty.</p> : null}
          </CardContent>
        </Card>
      ) : null}
      {hidden.includes('queue') ? (
        <Button size="sm" variant="outline" onClick={() => toggleWidget('queue')}>Show live queue</Button>
      ) : null}

      {/* Money row */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { label: 'Billed', value: inr(money.billed), icon: Wallet },
          { label: 'Collected', value: inr(money.collectedToday ?? money.collected), icon: CheckCircle },
          { label: 'Outstanding', value: inr(money.outstanding), icon: AlertTriangle },
          { label: 'Occupancy', value: `${ops?.beds?.occupancyPct ?? '—'}%`, icon: BedDouble },
        ].map((k) => (
          <Card key={k.label}>
            <CardContent className="p-4 flex items-center gap-3">
              <k.icon className="w-5 h-5 text-primary shrink-0" />
              <div><p className="text-xs text-muted-foreground">{k.label}</p><p className="text-lg font-bold">{k.value}</p></div>
            </CardContent>
          </Card>
        ))}
      </div>
      {errors.ops && <p className="text-xs text-destructive">Ops tiles failed: {errors.ops} <button className="underline" onClick={() => window.location.reload()}>retry</button></p>}

      <div className="grid lg:grid-cols-2 gap-4">
        {/* Alerts */}
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><AlertTriangle className="w-4 h-4" />Action center ({alerts.length})</CardTitle></CardHeader>
          <CardContent className="space-y-2 max-h-80 overflow-auto">
            {alerts.slice(0, 20).map((a: any) => (
              <div key={a._id || a.id} className="flex items-center gap-2 text-sm rounded-lg border border-border/50 p-2.5">
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${a.severity === 'critical' ? 'bg-destructive/10 text-destructive' : 'bg-warning/10 text-warning'}`}>{a.severity}</span>
                <span className="flex-1 min-w-0 truncate">{a.message || a.type}</span>
                <Button size="sm" variant="outline" onClick={() => ack(a._id || a.id)}>Ack</Button>
              </div>
            ))}
            {alerts.length === 0 && <p className="text-sm text-muted-foreground">All clear 🎉</p>}
          </CardContent>
        </Card>

        {/* Beds */}
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><BedDouble className="w-4 h-4" />Beds {beds ? `(ALOS ${beds.alosDays}d)` : ''}</CardTitle></CardHeader>
          <CardContent className="space-y-1.5 max-h-80 overflow-auto">
            {(beds?.wards || []).map((w: any, i: number) => (
              <div key={i} className="flex items-center gap-2 text-xs">
                <span className="w-24 truncate font-medium">{w._id?.ward || 'Ward'}</span>
                <span className="text-muted-foreground">{w._id?.status}: <b className="text-foreground">{w.count}</b></span>
              </div>
            ))}
            {!(beds?.wards || []).length && <p className="text-sm text-muted-foreground">{errors.beds || 'No bed data.'}</p>}
          </CardContent>
        </Card>

        {/* Revenue */}
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><Wallet className="w-4 h-4" />Revenue by source</CardTitle></CardHeader>
          <CardContent className="space-y-1.5">
            {(rev?.bySource || []).map((r: any, i: number) => (
              <div key={i} className="flex justify-between text-sm">
                <span className="capitalize">{r._id || 'Other'}</span>
                <span className="font-bold">{inr(r.collected)} <span className="text-muted-foreground font-normal">/ {inr(r.billed)}</span></span>
              </div>
            ))}
            {!(rev?.bySource || []).length && <p className="text-sm text-muted-foreground">{errors.rev || 'No revenue data.'}</p>}
          </CardContent>
        </Card>

        {/* Staff + TPA */}
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><Users className="w-4 h-4" />Staff</CardTitle></CardHeader>
          <CardContent className="space-y-2 text-sm">
            <p>On leave today: <b>{staff?.onLeave ?? (errors.staff || '—')}</b></p>
            <div className="flex flex-wrap gap-1.5">
              {(staff?.byRole || []).map((r: any, i: number) => (
                <span key={i} className="text-[11px] bg-muted px-2 py-0.5 rounded-md">{r._id}: {r.count}</span>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* File 22 P0-left: insurance pipeline funnel */}
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><Shield className="w-4 h-4" />Insurance pipeline</CardTitle></CardHeader>
          <CardContent className="space-y-2 text-sm">
            <p className="text-xs font-semibold uppercase text-muted-foreground">Pre-auth</p>
            <div className="flex flex-wrap gap-1.5">
              {(tpa?.preauth || []).map((p: any, i: number) => (
                <span key={i} className="text-[11px] bg-muted px-2 py-0.5 rounded-md">{p._id}: {p.count} ({inr(p.amount || 0)})</span>
              ))}
              {!(tpa?.preauth || []).length && <span className="text-xs text-muted-foreground">No pre-auths</span>}
            </div>
            <p className="text-xs font-semibold uppercase text-muted-foreground pt-1">Claims</p>
            <div className="flex flex-wrap gap-1.5">
              {(tpa?.claims || []).map((c: any, i: number) => (
                <span key={i} className="text-[11px] bg-muted px-2 py-0.5 rounded-md">{c._id}: {c.count} ({inr(c.amount || 0)})</span>
              ))}
              {!(tpa?.claims || []).length && <span className="text-xs text-muted-foreground">No claims</span>}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Building2, Search, Heart, Brain, Bone, Baby, Eye, Stethoscope, Activity, Users, ChevronDown, ChevronUp, SlidersHorizontal, X, Star, Ambulance, BedDouble, Shield, Calendar, Car, CreditCard, Building, CheckCircle2, Navigation, HeartPulse } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { api } from '@/lib/api';
import HospitalCard from '@/components/HospitalCard';
import { matchesSpecialty } from '@/lib/specialtyFilter';

import { getSpecialtyVisual } from '@/data/specialtyVisuals';
import { useSpecialtyTiles } from '@/hooks/useSpecialtyBrowse';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

// Backend tree (/categories/specialties?tree=1) is the single source of truth;
// the page shows a loading/empty state instead of a local fallback copy.


// Show first 14 by default (2 rows of 7)
const INITIAL_VISIBLE = 14;

export default function HospitalDirectory() {
  const [searchParams] = useSearchParams();
  const [hospitals, setHospitals] = useState<ApiRow[]>([]);
  const [allHospitals, setAllHospitals] = useState<Unmodelled>([]);
  const [search, setSearch] = useState(searchParams.get('q') || searchParams.get('search') || '');
  const [cityFilter, setCityFilter] = useState(
    () => searchParams.get('city') || localStorage.getItem('findmedi_city') || localStorage.getItem('mediCore_city') || ''
  );
  const [specFilter, setSpecFilter] = useState(searchParams.get('specialty') || '');
  const [loading, setLoading] = useState(true);
  const [selectedDept, setSelectedDept] = useState('');
  const [showAllSpecialties, setShowAllSpecialties] = useState(false);
  const [showZeroSpecialties, setShowZeroSpecialties] = useState(false);
  const specialtyTree = useSpecialtyTiles();

  // Synchronize with global navbar city selection
  useEffect(() => {
    const onCityChange = (e: any) => {
      const newCity = e.detail || localStorage.getItem('findmedi_city') || localStorage.getItem('mediCore_city');
      if (newCity && newCity !== cityFilter) {
        setCityFilter(newCity);
      }
    };
    window.addEventListener('cityChange', onCityChange);
    window.addEventListener('storage', onCityChange);
    return () => {
      window.removeEventListener('cityChange', onCityChange);
      window.removeEventListener('storage', onCityChange);
    };
  }, [cityFilter]);

  // Advanced filters
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const [sortBy, setSortBy] = useState('relevance');
  const [filterHospitalType, setFilterHospitalType] = useState<string[]>(() => {
    const t = searchParams.get('type');
    if (t === 'government') return ['Government'];
    if (t === 'private') return ['Private'];
    return [];
  });
  const [filterEmergency, setFilterEmergency] = useState(false);
  const [filterMinRating, setFilterMinRating] = useState(0);
  const [filterInsurance, setFilterInsurance] = useState(false);
  const [filterBedAvailable, setFilterBedAvailable] = useState(false);
  const [filterCategory, setFilterCategory] = useState<string[]>([]);
  const [filterAccreditation, setFilterAccreditation] = useState<Unmodelled[]>([]);
  const [filterBedSize, setFilterBedSize] = useState('');
  const [filterAmbulance, setFilterAmbulance] = useState(false);
  const [filterEstablished, setFilterEstablished] = useState('');
  const [filterFacilities, setFilterFacilities] = useState<Unmodelled[]>([]);
  const [filterDoctorsRange, setFilterDoctorsRange] = useState('');
  const [filterPayment, setFilterPayment] = useState<Unmodelled[]>([]);
  const [filterInsuranceProvider, setFilterInsuranceProvider] = useState('');

  // Healthcare catalogue se aaye query params (?type= ?category= ?emergency= ?specialty= ?q=)
  useEffect(() => {
    const type = searchParams.get('type');
    const category = searchParams.get('category');
    const emergency = searchParams.get('emergency');
    const q = searchParams.get('q') || searchParams.get('search') || '';
    const specialty = searchParams.get('specialty') || '';
    setFilterHospitalType(type ? [type] : []);
    setFilterCategory(category ? [category] : []);
    setFilterEmergency(Boolean(emergency));
    setSearch(q);
    setSpecFilter(specialty);
  }, [searchParams]);

  const getType = (h: Unmodelled) => {
    const t = h.hospitalType || h.type || '';
    if (t.toLowerCase().includes('government')) return 'Government';
    if (t.toLowerCase().includes('private')) return 'Private';
    return t;
  };

  const getCategory = (h: Unmodelled) => {
    const t = h.hospitalType || h.type || '';
    if (t.toLowerCase().includes('multi')) return 'Multi-Specialty';
    if (t.toLowerCase().includes('single')) return 'Single-Specialty';
    if (t.toLowerCase().includes('super')) return 'Super-Specialty';
    return '';
  };

  const loadHospitals = async () => {
    setLoading(true);
    try {
      const params: Unmodelled = { status: 'approved' };
      if (search) params.search = search;
      if (cityFilter && cityFilter !== 'All') params.city = cityFilter;
      if (specFilter && specFilter !== 'All') params.specialty = specFilter;
      const data = await api.getHospitals(params);
      const list = Array.isArray(data) ? data : (data?.data || data?.hospitals || []);
      setAllHospitals(list);
    } catch (e: any) { console.error(e); }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadHospitals(); }, [search, cityFilter, specFilter]);

  const insuranceProviders = useMemo(() => {
    const providers = new Set();
    const list = Array.isArray(allHospitals) ? allHospitals : (allHospitals?.data || allHospitals?.hospitals || []);
    list.forEach((h: Unmodelled) => (h?.insuranceAccepted || []).forEach((i: Unmodelled) => providers.add(i?.provider || i)));
    return [...providers].sort();
  }, [allHospitals]);

  // Unified filter + sort effect
  useEffect(() => {
    const list = Array.isArray(allHospitals) ? allHospitals : (allHospitals?.data || allHospitals?.hospitals || []);
    let filtered = [...list];

    // Department
    if (selectedDept) {
      filtered = filtered.filter(h => h.specialties?.includes(selectedDept));
    }

    // Hospital Type (Government / Private)
    if (filterHospitalType.length > 0) {
      filtered = filtered.filter(h => filterHospitalType.includes(getType(h)));
    }

    // Emergency 24x7
    if (filterEmergency) {
      filtered = filtered.filter(h => h.emergency24x7);
    }

    // Rating
    if (filterMinRating > 0) {
      filtered = filtered.filter(h => (h.rating || 0) >= filterMinRating);
    }

    // Insurance/Cashless
    if (filterInsurance) {
      filtered = filtered.filter(h => h.insuranceAccepted?.length > 0);
    }

    // Bed Availability
    if (filterBedAvailable) {
      filtered = filtered.filter(h => (h.bedAvailability || 0) > 0);
    }

    // Category (Multi / Single / Super-Specialty)
    if (filterCategory.length > 0) {
      filtered = filtered.filter(h => filterCategory.includes(getCategory(h)));
    }

    // Accreditation
    if (filterAccreditation.length > 0) {
      filtered = filtered.filter(h => h.accreditations?.some((a: Unmodelled) => filterAccreditation.includes(a)));
    }

    // Bed Size (uses bedAvailability / available beds as proxy for total beds)
    if (filterBedSize) {
      if (filterBedSize === 'small') filtered = filtered.filter(h => (h.bedAvailability || 0) < 50);
      else if (filterBedSize === 'medium') filtered = filtered.filter(h => (h.bedAvailability || 0) >= 50 && (h.bedAvailability || 0) <= 200);
      else if (filterBedSize === 'large') filtered = filtered.filter(h => (h.bedAvailability || 0) > 200);
    }

    // Ambulance
    if (filterAmbulance) {
      filtered = filtered.filter(h => h.ambulanceService === true);
    }

    // Established Year
    if (filterEstablished) {
      const currentYear = new Date().getFullYear();
      if (filterEstablished === 'old') filtered = filtered.filter(h => (h.establishedYear || 0) < currentYear - 20);
      else if (filterEstablished === 'new') filtered = filtered.filter(h => (h.establishedYear || 0) >= currentYear - 10);
    }

    // Facilities
    if (filterFacilities.length > 0) {
      filtered = filtered.filter(h => filterFacilities.every(f => h.facilities?.includes(f)));
    }

    // Doctors Range
    if (filterDoctorsRange) {
      if (filterDoctorsRange === '50+') filtered = filtered.filter(h => (h.totalDoctors || 0) >= 50);
      else if (filterDoctorsRange === '100+') filtered = filtered.filter(h => (h.totalDoctors || 0) >= 100);
      else if (filterDoctorsRange === '200+') filtered = filtered.filter(h => (h.totalDoctors || 0) >= 200);
    }

    // Payment Mode
    if (filterPayment.length > 0) {
      filtered = filtered.filter(h => filterPayment.some(p => h.payment_modes?.includes(p)));
    }

    // Insurance Provider
    if (filterInsuranceProvider) {
      filtered = filtered.filter(h => h.insuranceAccepted?.some((i: Unmodelled) => (i.provider || i).toLowerCase().includes(filterInsuranceProvider.toLowerCase())));
    }

    // Sort
    if (sortBy === 'rating') {
      filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    } else if (sortBy === 'established') {
      filtered.sort((a, b) => (b.establishedYear || 0) - (a.establishedYear || 0));
    } else if (sortBy === 'distance') {
      filtered.sort((a, b) => (a.distance || Infinity) - (b.distance || Infinity));
    }

    setHospitals(filtered);
  }, [selectedDept, allHospitals, filterHospitalType, filterEmergency, filterMinRating, filterInsurance, filterBedAvailable, filterCategory, filterAccreditation, filterBedSize, filterAmbulance, filterEstablished, filterFacilities, filterDoctorsRange, filterPayment, filterInsuranceProvider, sortBy]);

  useEffect(() => {
