                            className={`relative flex items-center gap-2.5 p-3 rounded-xl border text-left transition-all ${active ? 'border-primary bg-primary/5 shadow-sm' : 'border-border/60 bg-card hover:border-primary/40'}`}>
                            <div className={`w-9 h-9 rounded-xl flex items-center justify-center ${active ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>
                              <Icon className="w-4 h-4" />
                            </div>
                            <span className="text-xs font-semibold text-foreground">{m.label}</span>
                            {active && <CheckCircle className="w-3.5 h-3.5 text-primary absolute top-1.5 right-1.5" />}
                          </button>
                        );
                      })}
                    </div>
                    <Button className="w-full rounded-xl h-10 font-semibold" onClick={() => setTestPaymentStep('billing')}>
                      Next <ChevronRight className="w-4 h-4 ml-1" />
                    </Button>
                  </div>
                )}
                {testBookingStep === 5 && testPaymentStep === 'billing' && (
                  <div className="space-y-1">
                    <p className="text-xs text-center text-muted-foreground pb-2">Review bill and complete payment</p>
                    <BillCheckout
                      amount={cartTotal + (testCollectionMode === 'home' ? 50 : 0)}
                      serviceType="test"
                      provider={hospital?.name || 'Lab'}
                      details={{ collectionMode: testCollectionMode === 'home' ? 'Home Collection' : 'Lab Visit', slot: `${testSelectedDate}, ${testSelectedSlot}` }}
                      lineItems={cartItems.map(t => ({ name: t.name, price: t.price, qty: t.qty, rx: t.rx }))}
                      homeCollectionFee={testCollectionMode === 'home' ? 50 : 0}
                      discount={0}
                    />
                  </div>
                )}
                {testBookingStep === 6 && (
                  <div className="space-y-5">
                    <div className="text-center pt-2">
                      <div className="w-20 h-20 rounded-full bg-gradient-to-br from-emerald-400/20 to-emerald-400/5 flex items-center justify-center mx-auto mb-4 ring-4 ring-emerald-500/10">
                        <CheckCircle2 className="w-10 h-10 text-emerald-500" />
                      </div>
                      <h3 className="font-heading font-bold text-xl text-foreground">Booking Confirmed!</h3>
                      {testPaymentResult?.invoice_id && (
                        <p className="text-xs text-muted-foreground mt-1">Invoice: {testPaymentResult.invoice_id}</p>
                      )}
                    </div>
                    <div className="bg-muted/20 rounded-xl border border-border/30 p-4 space-y-2 text-sm">
                      {testPaymentResult?.transaction_id && (
                        <div className="flex justify-between"><span className="text-muted-foreground">Transaction</span><span className="font-mono font-semibold text-foreground">{testPaymentResult.transaction_id}</span></div>
                      )}
                      <div className="flex justify-between"><span className="text-muted-foreground">Amount Paid</span><span className="font-bold text-foreground">₹{cartTotal + (testCollectionMode === 'home' ? 50 : 0)}</span></div>
                      <div className="flex justify-between"><span className="text-muted-foreground">Method</span><span className="capitalize text-foreground">{testPaymentMethod}</span></div>
                      <div className="flex justify-between"><span className="text-muted-foreground">Date</span><span className="text-foreground">{testSelectedDate}</span></div>
                    </div>
                    {testPaymentResult?.transaction_id && (
                      <div className="flex gap-3">
                        <Button size="sm" variant="outline" className="flex-1 gap-1.5 rounded-xl h-10 text-xs"
                          onClick={() => downloadPaymentInvoice(testPaymentResult.transaction_id, `invoice-${testPaymentResult.invoice_id || 'test'}.pdf`)}>
                          <FileDown className="w-4 h-4" /> Download Invoice
                        </Button>
                        <Button size="sm" variant="outline" className="flex-1 gap-1.5 rounded-xl h-10 text-xs"
                          onClick={() => downloadBillPdf(testPaymentResult.transaction_id, `bill-${testPaymentResult.invoice_id || 'test'}.pdf`)}>
                          <FileDown className="w-4 h-4" /> Download Bill
                        </Button>
                      </div>
                    )}
                  </div>
                )}
              </div>
              <div className="px-5 py-4 border-t border-border/30 shrink-0 bg-muted/10">
                {testBookingStep === 1 && (
                  <div className="flex gap-3">
                    <Button variant="outline" className="flex-1 rounded-xl h-11 text-sm" onClick={() => { setShowTestBooking(false); setTestBookingStep(1); setTestSelectedDate(''); setTestSelectedSlot(''); }}>Cancel</Button>
                    <Button className="flex-1 rounded-xl h-11 text-sm gap-1.5" onClick={() => setTestBookingStep(2)}>Continue <ChevronRight className="w-4 h-4" /></Button>
                  </div>
                )}
                {testBookingStep === 2 && <Button className="w-full rounded-xl h-11 text-sm gap-1.5" onClick={() => setTestBookingStep(3)}>Continue <ChevronRight className="w-4 h-4" /></Button>}
                {testBookingStep === 3 && <Button className="w-full rounded-xl h-11 text-sm gap-1.5" onClick={() => setTestBookingStep(4)} disabled={!testSelectedDate || !testSelectedSlot}>Continue <ChevronRight className="w-4 h-4" /></Button>}
                {testBookingStep === 4 && <Button className="w-full rounded-xl h-11 text-sm gap-1.5" onClick={() => setTestBookingStep(5)}>Proceed to Pay <ChevronRight className="w-4 h-4" /></Button>}
                {testBookingStep === 5 && (
                  <Button className="w-full rounded-xl h-11 text-sm gap-1.5 bg-primary" onClick={handleTestPayment} disabled={testPaymentLoading}>
                    {testPaymentLoading ? 'Processing...' : `Pay ₹${cartTotal + (testCollectionMode === 'home' ? 50 : 0)}`} <ChevronRight className="w-4 h-4 ml-1" />
                  </Button>
                )}
                {testBookingStep === 6 && <Button className="w-full rounded-xl h-11 text-sm gap-1.5 bg-gradient-to-r from-emerald-500 to-emerald-600" onClick={() => { setShowTestBooking(false); setTestCart({}); setTestBookingStep(1); setTestSelectedDate(''); setTestSelectedSlot(''); setTestPaymentResult(null); }}>Done <CheckCircle2 className="w-4 h-4" /></Button>}
              </div>
              <ReviewDialog open={showReviewDialog} 
        onOpenChange={setShowReviewDialog}
        entityType="hospital"
        entityId={id}
        entityName={hospital?.name}
        onReviewSubmitted={(review: Unmodelled) => {
          setReviews(prev => [review, ...(Array.isArray(prev) ? prev : [])]);
        }}
      />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

import { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
   FlaskConical, Search, Clock, Home, Lock, ShoppingCart,
   ChevronRight, Heart, Sparkles, Plus, Minus, Activity,
     ArrowLeft, MapPin, Phone, Star, BadgeCheck,
    Building2, X, CreditCard, Wallet, CheckCircle,
    Calendar, Sun, Moon, MapPinHouse, ChevronLeft,
     Banknote, Shield, ShieldCheck, Camera, FileText, FileDown
  } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { api, downloadPaymentInvoice, downloadBillPdf } from '@/lib/api';
import { bookTestLab, isBookingConflictError } from '@/lib/testBooking';
import { useAuth } from '@/context/AuthContext';
import { userFacingError } from '@/lib/errorCopy';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const DEPARTMENTS = [
  { id:'all', name:'All Departments', icon:FlaskConical, color:'from-primary/20 to-primary/5', textColor:'text-primary', hoverColor:'hover:border-primary/40' },
  { id:'Pathology', name:'Pathology', icon:FlaskConical, color:'from-blue-500/20 to-blue-500/5', textColor:'text-blue-500', hoverColor:'hover:border-blue-500/40' },
  { id:'Radiology', name:'Radiology', icon:Activity, color:'from-purple-500/20 to-purple-500/5', textColor:'text-purple-500', hoverColor:'hover:border-purple-500/40' },
  { id:'Cardiology', name:'Cardiology', icon:Heart, color:'from-red-500/20 to-red-500/5', textColor:'text-red-500', hoverColor:'hover:border-red-500/40' },
  { id:'Health Packages', name:'Health Packages', icon:Sparkles, color:'from-emerald-400/25 to-emerald-400/5', textColor:'text-emerald-500', hoverColor:'hover:border-emerald-500/40' },
];

const TIME_SLOTS = ['09:00-10:00','10:00-11:00','11:00-12:00','12:00-13:00','14:00-15:00','15:00-16:00','16:00-17:00','17:00-18:00'];

const PAYMENT_METHODS = [
  { id:'cod', label:'Cash on Delivery', icon:Banknote },
  { id:'upi', label:'UPI / GPay / PhonePe', icon:Wallet },
  { id:'card', label:'Debit / Credit Card', icon:CreditCard },
];

const FASTING_TESTS = ['Blood Glucose (Fasting)', 'Lipid Profile'];

const STEP_LABELS = ['Prescription', 'Collection', 'Slot', 'Summary', 'Payment', 'Done'];

export default function HospitalTestBooking() {
  const { entityId, hospitalId } = useParams();
  const activeId = entityId || hospitalId;
  const navigate = useNavigate();
  const [testSearch, setTestSearch] = useState('');
  const [deptFilter, setDeptFilter] = useState('all');
  const [priceFilter, setPriceFilter] = useState('all');
  const [rxFilter, setRxFilter] = useState('all');
  const [collectionFilter, setCollectionFilter] = useState('all');
  const [sortFilter, setSortFilter] = useState('popularity');
  const [testCart, setTestCart] = useState<ApiRow>({});
  const [showBooking, setShowBooking] = useState(false);
  const [bookingStep, setBookingStep] = useState(1);
  const [collectionMode, setCollectionMode] = useState('lab');
  const [selectedDate, setSelectedDate] = useState('');
  const [selectedSlot, setSelectedSlot] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('upi');
  const [bookingId, setBookingId] = useState('');
  const [paymentResult, setPaymentResult] = useState<Unmodelled>(null);
  const [hospital, setHospital] = useState<Unmodelled>(null);
  const { user } = useAuth();
  const [tests, setTests] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [_bookingConfirmed, setBookingConfirmed] = useState(false);
  const [_bookingLoading, setBookingLoading] = useState(false);
  const [prescriptionFile, setPrescriptionFile] = useState<Unmodelled>(null);
  const [prescriptionPreview, setPrescriptionPreview] = useState('');

  // Generate next 6 days for date selection
  const getNextDays = () => {
    const days = [];
    const today = new Date();
    const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

    for (let i = 0; i < 6; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      days.push({
        display: `${dayNames[date.getDay()]} ${date.getDate()}`,
        value: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`,
        dayName: dayNames[date.getDay()],
        dayNum: date.getDate(),
        month: monthNames[date.getMonth()]
      });
    }
    return days;
  };

  const availableDates = getNextDays();

  useEffect(() => {
    window.scrollTo(0, 0);
    const load = async () => {
      setLoading(true);
      try {
        let entityData = null;
        let entityType = 'hospital';
        const [hospitalRes, facilityRes] = await Promise.allSettled([
          api.getHospital(activeId),
          api.getFacility(activeId),
        ]);
        if (hospitalRes.status === 'fulfilled') {
          entityData = hospitalRes.value?.hospital || hospitalRes.value;
          entityType = 'hospital';
        } else if (facilityRes.status === 'fulfilled') {
          const f = facilityRes.value?.facility || facilityRes.value;
          if (f) {
            entityData = f;
            entityType = f.type || 'facility';
          }
        }
        setHospital(entityData);

        // Link can point at a doctor's _id (Find Clinic → Book Test). Resolve the
        // doctor → their clinic (facilityId, clinicProfile or doctor fields).
        let testScopeId = entityData?._id || '';
        if (!testScopeId && !entityData) {
          try {
            const doc = await api.getDoctor(activeId);
            if (doc) {
              const cp = doc.clinicProfile || {};
              const docFacilityId = doc.facilityId?._id || doc.facilityId;
              testScopeId = docFacilityId || doc.hospitalId || doc._id || '';
              entityType = 'clinic';
              setHospital({
                _id: docFacilityId || doc._id,
                name: cp.clinic_name || doc.facilityId?.name || doc.name || 'Clinic',
                address: cp.clinic_address || doc.facilityId?.address || doc.location || '',
                city: cp.clinic_city || (cp.clinic_address || doc.location || '').split(',').pop()?.trim() || '',
                rating: doc.rating || 0,
                verified: doc.approved || false,
              });
            }
          } catch { /* id is not a doctor either */ }
        }
        if (!testScopeId && entityType === 'hospital') testScopeId = activeId;

        const params = testScopeId ? { hospitalId: testScopeId } : {};
        const testsRes = await api.getTests(params).catch(() => []);
        const list = Array.isArray(testsRes) ? testsRes : testsRes?.tests || [];
        const mapped = list.map((t: Unmodelled) => ({
          id: t._id,
          _id: t._id,
          name: t.name,
          dept: t.category || t.department || 'Pathology',
          category: t.category,
          department: t.department,
          price: t.price,
          mrp: t.mrp || t.price,
          reportTime: t.reportTime || '24 hrs',
          homeCollection: t.homeCollection || false,
          rx: t.prescriptionReq || false,
          prescriptionReq: t.prescriptionReq || false,
          popular: t.popular || false,
        }));
        setTests(mapped);
      } catch (e: any) { console.error(e); }
      setLoading(false);
    };
    load();
  }, [activeId]);

  const addToCart = (testId: Unmodelled) => setTestCart(p => ({ ...p, [testId]: (p[testId] || 0) + 1 }));
  const removeFromCart = (testId: Unmodelled) => setTestCart(p => {
    const next: Unmodelled = { ...p };
    if (next[testId] <= 1) delete next[testId];
    else next[testId]--;
    return next;
  });

  // Handle prescription file upload from camera
  const handleCameraUpload = (e: Unmodelled) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('image/')) {
      toast.error('Please capture an image');
      return;
    }

    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image size should not exceed 5MB');
      return;
    }

    setPrescriptionFile(file);

    // Create preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setPrescriptionPreview(reader.result as Unmodelled);
    };
    reader.readAsDataURL(file);

    toast.success('Prescription captured successfully');
  };

  // Handle prescription file upload from gallery/files
  const handleFileUpload = (e: Unmodelled) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'application/pdf'];
    if (!validTypes.includes(file.type)) {
      toast.error('Please upload JPG, PNG, or PDF file only');
      return;
    }

    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      toast.error('File size should not exceed 5MB');
      return;
    }

    setPrescriptionFile(file);

    // Create preview for images
    if (file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPrescriptionPreview(reader.result as Unmodelled);
      };
      reader.readAsDataURL(file);
    } else {
      setPrescriptionPreview('');
    }

    toast.success('Prescription uploaded successfully');
  };

  // Remove uploaded prescription
  const removePrescription = () => {
    setPrescriptionFile(null);
    setPrescriptionPreview('');
    toast.success('Prescription removed');
  };

  const filtered = tests.filter(t => {
    if (deptFilter !== 'all' && t.dept !== deptFilter) return false;
    if (testSearch && !t.name.toLowerCase().includes(testSearch.toLowerCase())) return false;
    if (priceFilter !== 'all') {
      if (priceFilter === '0-500' && t.price >= 500) return false;
      if (priceFilter === '500-2000' && (t.price < 500 || t.price > 2000)) return false;
      if (priceFilter === '2000+' && t.price <= 2000) return false;
    }
    if (rxFilter !== 'all') {
      if (rxFilter === 'direct' && t.rx) return false;
      if (rxFilter === 'rx' && !t.rx) return false;
    }
    if (collectionFilter !== 'all') {
      if (collectionFilter === 'home' && !t.homeCollection) return false;
      if (collectionFilter === 'lab' && t.homeCollection) return false; 
    }
    return true;
  });

  if (sortFilter === 'price-low') {
    filtered.sort((a, b) => a.price - b.price);
  } else if (sortFilter === 'price-high') {
    filtered.sort((a, b) => b.price - a.price);
  } else if (sortFilter === 'popularity') {
    filtered.sort((a, b) => (b.popular ? 1 : 0) - (a.popular ? 1 : 0));
  }

  const cartItems = Object.entries(testCart).map(([tid, qty]: Unmodelled) => {
    const test = tests.find(t => t.id === tid);
    return { ...(test as Unmodelled), qty };
  }).filter(Boolean);

  const cartTotal = cartItems.reduce((s: Unmodelled, t: Unmodelled) => s + t.price * t.qty, 0);
  const cartCount = cartItems.reduce((s: Unmodelled, t: Unmodelled) => s + t.qty, 0);
  const hasRx = cartItems.some(t => t.rx);
  const hasFasting = cartItems.some(t => FASTING_TESTS.some(f => t.name.includes(f)));

  const openBooking = () => { setBookingStep(1); setShowBooking(true); setBookingConfirmed(false); };
  const closeBooking = () => setShowBooking(false);
  const nextStep = () => setBookingStep(p => Math.min(p + 1, 6));
  const prevStep = () => setBookingStep(p => Math.max(p - 1, 1));

  const confirmBooking = async () => {
    if (!user) { toast.error('Please login to book'); navigate('/login'); return; }
    setBookingLoading(true);
    const total = cartTotal + (collectionMode === 'home' ? 50 : 0);
    let bookingId = '';
    try {
      const { bookingId: bid, result } = await bookTestLab(
        {
          bookingId: 'LB' + crypto.randomUUID(),
          patientId: user.id,
          patientName: user.name,
          patientEmail: user.email,
          patientPhone: user.phone || '',
          hospitalId: activeId,
          tests: cartItems.map(t => t.name),
          testIds: cartItems.map(t => t.id),
          totalAmount: total,
          bookingDate: selectedDate ? new Date(selectedDate) : new Date(),
          timeSlot: selectedSlot,
          visitType: collectionMode === 'home' ? 'Home Collection' : 'Walk-in',
          homeCollectionFee: collectionMode === 'home' ? 50 : 0,
          homeCollectionAddress: collectionMode === 'home' ? (user.address || '') : '',
          prescriptionUrl: prescriptionFile ? 'uploaded' : '',
          status: 'Pending',
          paymentStatus: 'Pending',
        },
        {
          amount: total,
          method: paymentMethod === 'cod' ? 'cash' : paymentMethod,
          description: `Lab Test - ${cartItems.map(t => t.name).join(', ')}`,
          provider: displayHospital?.name || 'Lab',
          lineItems: cartItems.map(t => ({ name: t.name, price: t.price, qty: t.qty })),
        }
      );
      bookingId = bid;
      setPaymentResult(result);
      setBookingId(bookingId || 'MED' + crypto.randomUUID());
      setBookingConfirmed(true);
      setBookingStep(6);
      toast.success('Booking confirmed!');
    } catch (e: any) {
      const msg = userFacingError(e, { fallback: '' });
      if (isBookingConflictError(msg)) {
        setBookingId(bookingId || 'MED' + crypto.randomUUID());
        setBookingConfirmed(true);
        setBookingStep(6);
        toast.success('Booking already confirmed!');
        return;
      }
      console.error('Booking error:', e);
      toast.error(msg || 'Failed to confirm booking');
    }
    setBookingLoading(false);
  };

  const closeComplete = () => {
    setShowBooking(false);
    setTestCart({});
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  const displayHospital = hospital || { _id: activeId, name: hospital?.name || 'Healthcare Provider', rating: 0, address: '', verified: false };

  const StepContent = ({ step }: Unmodelled) => {
    switch (step) {
      case 1:
        return (
          <motion.div key="s1" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="space-y-5">
            <div className="text-center pb-1">
              <h3 className="font-heading font-bold text-lg text-foreground">Prescription Check</h3>
              <p className="text-xs text-muted-foreground mt-0.5">Verify if prescription is needed for selected tests</p>
            </div>
            {hasRx ? (
              <>
                <div className="bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/20 rounded-xl p-4">
                  <div className="flex items-start gap-3">
                    <div className="w-9 h-9 rounded-full bg-amber-100 dark:bg-amber-500/20 flex items-center justify-center shrink-0">
                      <Lock className="w-4 h-4 text-amber-600 dark:text-amber-400" />
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-amber-800 dark:text-amber-300">Prescription Required</p>
                      <p className="text-xs text-amber-600 dark:text-amber-400/80 mt-0.5">Upload your prescription to proceed with Rx tests</p>
                    </div>
                  </div>
                </div>

                {/* Show uploaded prescription preview */}
                {prescriptionFile ? (
                  <div className="bg-gradient-to-br from-emerald-50 to-emerald-50/50 dark:from-emerald-500/10 dark:to-emerald-500/5 rounded-xl p-4 border border-emerald-200 dark:border-emerald-500/20">
                    <div className="flex items-start gap-3">
                      <div className="w-10 h-10 rounded-xl bg-emerald-100 dark:bg-emerald-500/20 flex items-center justify-center shrink-0">
                        <CheckCircle className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-semibold text-emerald-800 dark:text-emerald-300">Prescription Uploaded</p>
                        <p className="text-xs text-emerald-600 dark:text-emerald-400/80 mt-0.5 truncate">{prescriptionFile.name}</p>
                        {prescriptionPreview && (
                          <div className="mt-3 rounded-lg overflow-hidden border border-emerald-200 dark:border-emerald-500/20">
                            <img src={prescriptionPreview} alt="Prescription preview" className="w-full h-32 object-contain bg-white dark:bg-gray-900" />
                          </div>
                        )}
                        {!prescriptionPreview && prescriptionFile.type === 'application/pdf' && (
                          <div className="mt-3 rounded-lg overflow-hidden border border-emerald-200 dark:border-emerald-500/20 bg-white dark:bg-gray-900 p-4 flex items-center justify-center gap-2">
                            <FileText className="w-6 h-6 text-emerald-600" />
                            <span className="text-xs text-emerald-600">PDF Document</span>
                          </div>
                        )}
                      </div>
                      <button onClick={removePrescription} className="w-8 h-8 rounded-lg bg-red-100 dark:bg-red-500/20 hover:bg-red-200 dark:hover:bg-red-500/30 flex items-center justify-center transition-colors shrink-0">
                        <X className="w-4 h-4 text-red-600 dark:text-red-400" />
                      </button>
                    </div>
                  </div>
                ) : (
                  <>
                    {/* Upload buttons */}
                    <div className="grid grid-cols-2 gap-3">
                      {/* Camera Button - Opens camera directly */}
                      <input
                        type="file"
                        id="prescription-camera"
                        accept="image/*"
                        capture="environment"
                        onChange={handleCameraUpload}
                        className="hidden"
                      />
                      <label
                        htmlFor="prescription-camera"
                        className="flex flex-col items-center gap-3 p-5 rounded-xl border-2 border-dashed border-border/60 bg-card hover:border-primary/40 hover:bg-primary/5 transition-all group cursor-pointer"
