              Book Now <ChevronRight className="w-5 h-5" />
            </Button>
          </div>
        </motion.div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Upload, Download, FileSpreadsheet, Users, Stethoscope, CreditCard, CalendarDays, Loader2, AlertCircle, CheckCircle } from 'lucide-react';
import { apiClient, getApiBaseUrl, api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const API_URL = getApiBaseUrl();

export default function ImportExport() {
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [importResults, setImportResults] = useState<ApiRow>({});

  const handleExport = async (type: Unmodelled, format = 'excel') => {
    setLoading(true);
    try {
      const res = await apiClient.get(`/reports/export/${type}?format=${format}`, {
        responseType: 'blob',
      });

      const blob = new Blob([res.data]);
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${type}.${format === 'csv' ? 'csv' : 'xlsx'}`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      a.remove();
    } catch (error: any) {
      console.error('Export error:', error);
    }
    setLoading(false);
  };

  const handleImport = async (type: Unmodelled, file: Unmodelled) => {
    if (!file) return;

    setLoading(true);
    setImportResults(prev => ({ ...prev, [type]: null }));

    const formData = new FormData();
    formData.append('file', file);

    try {
      const data = await api.dispatch(null, `/reports/import/${type}`, {
        method: 'POST',
        body: formData
      });

      if (!data || data.success === false) {
        throw new Error(data?.message || data?.error || 'Import failed');
      }
      setImportResults(prev => ({ ...prev, [type]: data }));
    } catch (error: any) {
      setImportResults(prev => ({ ...prev, [type]: { success: false, error: error.message } }));
    }
    setLoading(false);
  };

  const ImportCard = ({ type, title, description, icon: Icon }: Unmodelled) => {
    const importResult = importResults[type];

    return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><Icon className="w-5 h-5" /> Import {title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          <input
            type="file"
            accept=".xlsx,.xls"
            onChange={(event) => {
              const file = event.target.files?.[0];
              handleImport(type, file);
              event.target.value = '';
            }}
            className="hidden"
            id={`import-${type}`}
          />
          <label htmlFor={`import-${type}`}>
            <div className="border-2 border-dashed rounded-lg p-6 text-center cursor-pointer hover:bg-muted/50 transition-colors">
              <Upload className="w-8 h-8 mx-auto mb-2 text-muted-foreground" />
              <p className="text-sm text-muted-foreground">Click to upload Excel file</p>
              <p className="text-xs text-muted-foreground mt-1">.xlsx, .xls supported</p>
            </div>
          </label>

          {importResult && (
            <div className={`p-4 rounded-lg ${importResult.success ? 'bg-green-50 border border-green-200' : 'bg-red-50 border border-red-200'}`}>
              {importResult.success ? (
                <div className="flex items-center gap-2 text-green-700">
                  <CheckCircle className="w-4 h-4" />
                  <span>Successfully imported {importResult.imported} records!</span>
                </div>
              ) : (
                <div className="flex items-center gap-2 text-red-700">
                  <AlertCircle className="w-4 h-4" />
                  <span>{importResult.error || importResult.message}</span>
                </div>
              )}
              {importResult.errors?.length > 0 && (
                <p className="text-xs text-muted-foreground mt-2">{importResult.errors.length} errors found</p>
              )}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
    );
  };

  const ExportCard = ({ type, title, description, icon: Icon }: Unmodelled) => (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><Icon className="w-5 h-5" /> Export {title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="flex gap-2">
          <Button onClick={() => handleExport(type, 'excel')} disabled={loading} variant="outline">
            <Download className="w-4 h-4 mr-2" />Excel
          </Button>
          <Button onClick={() => handleExport(type, 'csv')} disabled={loading} variant="outline">
            <Download className="w-4 h-4 mr-2" />CSV
          </Button>
        </div>
      </CardContent>
    </Card>
  );

  if (user?.role === 'patient') {
    return (
      <div className="space-y-6">
        <div>
          <h1 className="text-3xl font-bold">Data Management</h1>
          <p className="text-muted-foreground">Import and export your data</p>
        </div>
        <Card>
          <CardHeader>
            <CardTitle>Access Restricted</CardTitle>
            <CardDescription>This section is only available for admin and staff</CardDescription>
          </CardHeader>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold">Import / Export</h1>
        <p className="text-muted-foreground">Bulk import and export patient, doctor, and billing records</p>
      </div>

      <Tabs defaultValue="import">
        <TabsList>
          <TabsTrigger value="import">Import Data</TabsTrigger>
          <TabsTrigger value="export">Export Data</TabsTrigger>
        </TabsList>

        <TabsContent value="import" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <ImportCard type="patients" title="Patients" description="Import patients from Excel" icon={Users} />
            <ImportCard type="doctors" title="Doctors" description="Import doctors from Excel" icon={Stethoscope} />
            {user?.role === 'hospital_admin' && (
              <ImportCard type="billing" title="Billing" description="Import billing records from Excel" icon={CreditCard} />
            )}
          </div>

          <Card className="mt-6">
            <CardHeader>
              <CardTitle>Import Format Guide</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="prose prose-sm max-w-none">
                <h4>Patients Excel Format:</h4>
                <p className="text-muted-foreground">Columns: Name, Email, Phone, Age, Gender, Address</p>
                <h4 className="mt-4">Doctors Excel Format:</h4>
                <p className="text-muted-foreground">Columns: Name, Specialization, Email, Phone, Experience, Qualification</p>
                <h4 className="mt-4">Billing Excel Format:</h4>
                <p className="text-muted-foreground">Columns: PatientId, Amount, Description, Status, Date</p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="export" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <ExportCard type="patients" title="Patients" description="Export all patient records" icon={Users} />
            <ExportCard type="doctors" title="Doctors" description="Export all doctor records" icon={Stethoscope} />
            {user?.role === 'hospital_admin' && (
              <>
                <ExportCard type="billing" title="Billing" description="Export billing records" icon={CreditCard} />
                <ExportCard type="appointments" title="Appointments" description="Export appointment records" icon={CalendarDays} />
              </>
            )}
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import FeedbackPrompt from '@/components/feedback/FeedbackPrompt';

/**
 * File 15 §15.3 — self-service kiosk (touch, isolated bundle via route).
 * Check-in (minimal fields → provisional record + token) and queue display
 * link. Idle 60s auto-reset with countdown; nothing PHI persists on device
 * beyond the current screen (state cleared on reset).
 */
const IDLE_SECS = 60;

export default function Kiosk() {
  const [hospitalId, setHospitalId] = useState(() => localStorage.getItem('kiosk_hospital') || '');
  const [step, setStep] = useState<'home' | 'checkin' | 'register' | 'pay' | 'collect' | 'token' | 'done'>(hospitalId ? 'home' : 'home');
  const [needsSetup, setNeedsSetup] = useState(!hospitalId);
  const [form, setForm] = useState({ name: '', phone: '', department: 'General' });
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState('');
  const [idle, setIdle] = useState(IDLE_SECS);
  const timer = useRef<number | null>(null);
  // File 22 P1-25: extra modes share the idle reset + kiosk fetch helper.
  const [payForm, setPayForm] = useState({ invoiceId: '', phone: '' });
  const [collectForm, setCollectForm] = useState({ phone: '', dob: '' });
  const [reports, setReports] = useState<any[]>([]);
  const [tokenForm, setTokenForm] = useState({ token: '', department: 'General' });
  const [tokenInfo, setTokenInfo] = useState<any>(null);
  // T5: feedback prompt on the post-check-in screen. POST /feedback requires a
  // session (shared receptionist login on this device) — probe /auth/me so an
  // anonymous kiosk never shows a prompt that would 401 on submit.
  const [canFeedback, setCanFeedback] = useState(false);

  const reset = () => {
    setStep('home');
    setForm({ name: '', phone: '', department: 'General' });
    setPayForm({ invoiceId: '', phone: '' });
    setCollectForm({ phone: '', dob: '' });
    setReports([]);
    setTokenForm({ token: '', department: 'General' });
    setTokenInfo(null);
    setResult(null);
    setError('');
    setCanFeedback(false);
    setIdle(IDLE_SECS);
  };

  useEffect(() => {
    const poke = () => setIdle(IDLE_SECS);
    window.addEventListener('pointerdown', poke);
    window.addEventListener('keydown', poke);
    timer.current = window.setInterval(() => {
      setIdle((s) => {
        if (s <= 1) { reset(); return IDLE_SECS; }
        return s - 1;
      });
    }, 1000);
    return () => {
      window.removeEventListener('pointerdown', poke);
      window.removeEventListener('keydown', poke);
      if (timer.current) clearInterval(timer.current);
    };
  }, []);

  const saveSetup = () => {
    localStorage.setItem('kiosk_hospital', hospitalId);
    setNeedsSetup(false);
    reset();
  };

  const checkin = async () => {
    setError('');
    try {
      const res = await fetch('/api/kiosk/checkin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hospitalId, ...form }),
      });
      const body = await res.json();
      if (!res.ok) {
        setError(body.code === 'DUPLICATE_ROUTE_RECEPTION' ? 'Record mil sakta hai — please see reception.' : (body.message || 'Failed'));
        return;
      }
      setResult(body);
      setStep('done');
      // T5: offer the NPS prompt only when this device has a live session.
      fetch('/api/auth/me', { credentials: 'include' })
        .then((r) => setCanFeedback(r.ok))
        .catch(() => setCanFeedback(false));
    } catch {
      setError('Network error — please see reception.');
    }
  };

  const kioskPost = async (path: string, payload: any) => {
    const res = await fetch(`/api/kiosk/${path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ hospitalId, ...payload }),
    });
    const body = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(body.code === 'DUPLICATE_ROUTE_RECEPTION' ? 'Possible existing record — please see reception.' : (body.message || 'Failed'));
    return body;
  };

  const doRegister = async () => {
    setError('');
    try {
      const body = await kioskPost('register', { name: form.name, phone: form.phone });
      setResult({ registeredId: body.id });
      setStep('done');
    } catch (e: any) { setError(e.message); }
  };

  const doPay = async () => {
    setError('');
    try {
      const body = await kioskPost('pay', { ...payForm, gateway: 'mock' });
      setResult({ payOrder: body.gatewayOrderId, payAmount: body.amount, paySession: body.sessionId });
      setStep('done');
    } catch (e: any) { setError(e.message); }
  };

  const doCollect = async () => {
    setError('');
    try {
      const body = await kioskPost('report-collect', collectForm);
      setReports(body.ready || []);
    } catch (e: any) { setError(e.message); }
  };

  const doTokenStatus = async () => {
    setError('');
    try {
      const q = new URLSearchParams({ hospitalId, token: tokenForm.token, department: tokenForm.department });
      const res = await fetch(`/api/kiosk/token-status?${q}`);
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body.message || 'Not found');
      setTokenInfo(body);
    } catch (e: any) { setError(e.message); }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 select-none" data-motion-ignore>
      <div className="max-w-xl mx-auto">
        <div className="flex items-center justify-between text-xs text-slate-400">
          <span>FindMedi Kiosk</span>
          <span>Auto-reset in {idle}s</span>
        </div>

        {needsSetup ? (
          <Card className="mt-6 bg-slate-900 border-slate-700">
            <CardHeader><CardTitle className="text-white">Staff setup (one time)</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Hospital ID" value={hospitalId} onChange={(e) => setHospitalId(e.target.value)} />
              <Button className="h-14 w-full text-lg" onClick={saveSetup} disabled={!hospitalId}>Save on this device</Button>
            </CardContent>
          </Card>
        ) : step === 'home' ? (
          <div className="grid gap-4 mt-8">
            <Button className="h-24 text-2xl" onClick={() => setStep('checkin')}>Check-in<br /></Button>
            <div className="grid grid-cols-2 gap-4">
              <Button variant="outline" className="h-20 text-xl" onClick={() => setStep('register')}>Register</Button>
              <Button variant="outline" className="h-20 text-xl" onClick={() => setStep('pay')}>Pay bill</Button>
              <Button variant="outline" className="h-20 text-xl" onClick={() => setStep('collect')}>Reports</Button>
              <Button variant="outline" className="h-20 text-xl" onClick={() => setStep('token')}>My token</Button>
            </div>
            <Link to="/display/queue"><Button variant="outline" className="h-24 text-2xl w-full">Token Display</Button></Link>
            <Button variant="ghost" className="text-slate-400" onClick={() => { localStorage.removeItem('kiosk_hospital'); setNeedsSetup(true); }}>Staff: re-setup</Button>
          </div>
        ) : step === 'register' ? (
          <Card className="mt-6 bg-slate-900 border-slate-700">
            <CardHeader><CardTitle className="text-white">New registration (provisional)</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Full name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Mobile number" inputMode="numeric" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />
              {error && <p className="text-red-400">{error}</p>}
              <div className="flex gap-2">
                <Button variant="outline" className="h-14 flex-1 text-lg" onClick={reset}>Back</Button>
                <Button className="h-14 flex-1 text-lg" onClick={doRegister} disabled={!form.name || !form.phone}>Register</Button>
              </div>
            </CardContent>
          </Card>
        ) : step === 'pay' ? (
          <Card className="mt-6 bg-slate-900 border-slate-700">
            <CardHeader><CardTitle className="text-white">Pay bill</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Invoice ID" value={payForm.invoiceId} onChange={(e) => setPayForm({ ...payForm, invoiceId: e.target.value })} />
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Mobile number (on bill)" inputMode="numeric" value={payForm.phone} onChange={(e) => setPayForm({ ...payForm, phone: e.target.value })} />
              {error && <p className="text-red-400">{error}</p>}
              <div className="flex gap-2">
                <Button variant="outline" className="h-14 flex-1 text-lg" onClick={reset}>Back</Button>
                <Button className="h-14 flex-1 text-lg" onClick={doPay} disabled={!payForm.invoiceId || !payForm.phone}>Pay</Button>
              </div>
            </CardContent>
          </Card>
        ) : step === 'collect' ? (
          <Card className="mt-6 bg-slate-900 border-slate-700">
            <CardHeader><CardTitle className="text-white">Collect reports</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Mobile number" inputMode="numeric" value={collectForm.phone} onChange={(e) => setCollectForm({ ...collectForm, phone: e.target.value })} />
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="DOB (YYYY-MM-DD)" value={collectForm.dob} onChange={(e) => setCollectForm({ ...collectForm, dob: e.target.value })} />
              {error && <p className="text-red-400">{error}</p>}
              <Button className="h-14 w-full text-lg" onClick={doCollect} disabled={!collectForm.phone || !collectForm.dob}>Find my reports</Button>
              {reports.map((r: any, i: number) => (
                <a key={i} href={r.reportUrl} target="_blank" rel="noreferrer" className="block rounded-lg border border-slate-700 p-3 text-emerald-300">
                  {r.orderId} — open report
                </a>
              ))}
              <Button variant="outline" className="h-14 w-full text-lg" onClick={reset}>Back</Button>
            </CardContent>
          </Card>
        ) : step === 'token' ? (
          <Card className="mt-6 bg-slate-900 border-slate-700">
            <CardHeader><CardTitle className="text-white">My token</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Token number" value={tokenForm.token} onChange={(e) => setTokenForm({ ...tokenForm, token: e.target.value })} />
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Department" value={tokenForm.department} onChange={(e) => setTokenForm({ ...tokenForm, department: e.target.value })} />
              {error && <p className="text-red-400">{error}</p>}
              {tokenInfo ? (
                <div className="rounded-lg border border-slate-700 p-4 text-center">
                  <p className="text-4xl font-black text-emerald-400">{tokenInfo.tokenNumber}</p>
                  <p className="text-slate-300">{tokenInfo.status} · {tokenInfo.ahead} ahead · ~{tokenInfo.estimatedWaitTime} min</p>
                </div>
              ) : null}
              <div className="flex gap-2">
                <Button variant="outline" className="h-14 flex-1 text-lg" onClick={reset}>Back</Button>
                <Button className="h-14 flex-1 text-lg" onClick={doTokenStatus} disabled={!tokenForm.token}>Check</Button>
              </div>
            </CardContent>
          </Card>
        ) : step === 'checkin' ? (
          <Card className="mt-6 bg-slate-900 border-slate-700">
            <CardHeader><CardTitle className="text-white">Check-in</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Full name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Mobile number" inputMode="numeric" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />
              <Input className="h-14 text-lg bg-slate-800 border-slate-700 text-white" placeholder="Department" value={form.department} onChange={(e) => setForm({ ...form, department: e.target.value })} />
              {error && <p className="text-red-400">{error}</p>}
              <div className="flex gap-2">
                <Button variant="outline" className="h-14 flex-1 text-lg" onClick={reset}>Back</Button>
                <Button className="h-14 flex-1 text-lg" onClick={checkin} disabled={!form.name || !form.phone}>Get token</Button>
              </div>
            </CardContent>
          </Card>
        ) : (
          <Card className="mt-6 bg-slate-900 border-slate-700 text-center">
            <CardContent className="p-8 space-y-2">
              {result?.tokenNumber ? (
                <>
                  <p className="text-6xl font-black text-emerald-400">{result.tokenNumber}</p>
                  <p className="text-slate-300">Position {result?.queuePosition} · ~{result?.estimatedWaitTime} min</p>
                  {result?.unifiedDisplay && <p className="text-slate-400 text-sm">Unified: {result.unifiedDisplay}</p>}
                </>
              ) : null}
              {canFeedback && result?.tokenNumber ? (
                <div className="mt-4 text-left">
                  <FeedbackPrompt
                    inline
                    context="visit"
                    department={form.department}
                    title="How likely are you to recommend us?"
                    onDone={() => setCanFeedback(false)}
                    onSkip={() => setCanFeedback(false)}
                  />
                </div>
              ) : null}
              {result?.registeredId ? (
                <p className="text-slate-300">Registered (provisional).<br />Please complete KYC at reception.</p>
              ) : null}
              {result?.payOrder ? (
                <>
                  <p className="text-4xl font-black text-emerald-400">₹{Number(result.payAmount).toLocaleString('en-IN')}</p>
                  <p className="text-slate-300 break-all">Order {result.payOrder}</p>
                  {result?.paySession ? <p className="text-slate-400 text-sm break-all">Session: {result.paySession}</p> : <p className="text-slate-400 text-sm">Show this order ID at the counter to pay.</p>}
                </>
              ) : null}
              <Button className="h-14 w-full text-lg mt-4" onClick={reset}>Done</Button>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Search, FlaskConical, Plus, Clock, Shield, Microscope, Syringe, FileText, AlertCircle, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';
import PatientBanner from '@/components/clinical/PatientBanner';
import { toast } from 'sonner';
import type { Unmodelled } from '@/lib/apiTypes';

const labApi: Unmodelled = {
  getOrders: (p = {}) => api.dispatch(() => Promise.resolve({ orders: [] }), '/lab/orders?' + new URLSearchParams(p)),
  getTests: () => api.dispatch(() => Promise.resolve({ tests: [] }), '/lab/tests'),
  getStats: () => api.dispatch(() => Promise.resolve({ total: 0, pending: 0, processing: 0, completed: 0, critical: 0 }), '/lab/stats'),
  createOrder: (body: Unmodelled) => api.dispatch(() => Promise.resolve({}), '/lab/orders', { method: 'POST', body: JSON.stringify(body) }),
  registerSample: (id: Unmodelled, body: Unmodelled) => api.dispatch(() => Promise.resolve({}), `/lab/orders/${id}/register-sample`, { method: 'PUT', body: JSON.stringify(body) }),
  collectSample: (id: Unmodelled, body: Unmodelled) => api.dispatch(() => Promise.resolve({}), `/lab/orders/${id}/collect-sample`, { method: 'PUT', body: JSON.stringify(body) }),
  enterResult: (id: Unmodelled, body: Unmodelled) => api.dispatch(() => Promise.resolve({}), `/lab/orders/${id}/enter-result`, { method: 'PUT', body: JSON.stringify(body) }),
  verify: (id: Unmodelled, body: Unmodelled) => api.dispatch(() => Promise.resolve({}), `/lab/orders/${id}/verify`, { method: 'PUT', body: JSON.stringify(body) }),
  deliverReport: (id: Unmodelled, body: Unmodelled) => api.dispatch(() => Promise.resolve({}), `/lab/orders/${id}/deliver-report`, { method: 'PUT', body: JSON.stringify(body) }),
};

const statusColors: Unmodelled = {
  Ordered: 'bg-primary/10 text-primary border-primary/20',
  'Sample Pending': 'bg-warning/10 text-warning border-warning/20',
  Processing: 'bg-info/10 text-info border-info/20',
  'Under Verification': 'bg-purple-500/10 text-purple-600 border-purple-500/20',
  Completed: 'bg-success/10 text-success border-success/20',
  Cancelled: 'bg-destructive/10 text-destructive border-destructive/20',
};

const PRIORITY_COLORS: Unmodelled = {
  Routine: 'bg-muted text-muted-foreground',
  Urgent: 'bg-warning/10 text-warning',
  STAT: 'bg-destructive/10 text-destructive',
};

export default function Lab() {
  const qc: Unmodelled = useQueryClient();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [expandedOrder, setExpandedOrder] = useState<Unmodelled>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [newOrder, setNewOrder] = useState({ patientName: '', patientId: '', tests: [{ testName: '', category: 'Blood' }], clinicalNotes: '', priority: 'Routine' });

  const { data: ordersData }: Unmodelled = useQuery({ queryKey: ['lab-orders', search, statusFilter], queryFn: () => labApi.getOrders({ search, status: statusFilter }) });
  const { data: testsData }: Unmodelled = useQuery({ queryKey: ['lab-tests'], queryFn: labApi.getTests });
  const { data: stats }: Unmodelled = useQuery({ queryKey: ['lab-stats'], queryFn: labApi.getStats });

  const orders = ordersData?.orders || [];
  const labTests = testsData?.tests || [];

  const createMut = useMutation({ mutationFn: labApi.createOrder, onSuccess: () => { qc.invalidateQueries({ queryKey: ['lab-orders'] }); setShowCreate(false); } });
  const sampleMut = useMutation({ mutationFn: ({ id, ...body  }: Unmodelled) => labApi.registerSample(id, body), onSuccess: () => qc.invalidateQueries({ queryKey: ['lab-orders'] }) });
  const collectMut = useMutation({ mutationFn: ({ id, ...body  }: Unmodelled) => labApi.collectSample(id, body), onSuccess: () => qc.invalidateQueries({ queryKey: ['lab-orders'] }) });
  const resultMut = useMutation({ mutationFn: ({ id, ...body  }: Unmodelled) => labApi.enterResult(id, body), onSuccess: () => qc.invalidateQueries({ queryKey: ['lab-orders'] }) });
  const verifyMut = useMutation({ mutationFn: ({ id, ...body  }: Unmodelled) => labApi.verify(id, body), onSuccess: () => qc.invalidateQueries({ queryKey: ['lab-orders'] }) });

  const addTest = () => setNewOrder(o => ({ ...o, tests: [...o.tests, { testName: '', category: 'Blood' }] }));
  const removeTest = (i: Unmodelled) => setNewOrder(o => ({ ...o, tests: o.tests.filter((_, idx) => idx !== i) }));
  const updateTest = (i: Unmodelled, field: Unmodelled, value: Unmodelled) => setNewOrder(o => ({ ...o, tests: o.tests.map((t, idx) => idx === i ? { ...t, [field]: value } : t) }));

  return (
    <div>
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <h1 className="page-title">Lab Management</h1>
        <p className="page-subtitle">{stats?.total || 0} orders · {stats?.critical || 0} critical</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-6">
        {[
          { label: 'Total', value: stats?.total || 0, color: 'text-foreground' },
          { label: 'Pending', value: stats?.pending || 0, color: 'text-warning' },
          { label: 'Processing', value: stats?.processing || 0, color: 'text-info' },
          { label: 'Completed', value: stats?.completed || 0, color: 'text-success' },
          { label: 'Critical', value: stats?.critical || 0, color: 'text-destructive' },
        ].map(s => (
          <div key={s.label} className="bg-card rounded-xl border p-4 text-center">
            <p className={`text-2xl font-bold ${s.color}`}>{s.value}</p>
            <p className="text-xs text-muted-foreground">{s.label}</p>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-6">
        <div className="relative flex-1 min-w-[200px] max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search orders..." className="pl-10" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)}
          className="h-10 px-3 rounded-lg border border-input bg-background text-sm">
          <option value="All">All Status</option>
          {['Ordered', 'Sample Pending', 'Processing', 'Under Verification', 'Completed', 'Cancelled'].map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
        <div className="flex gap-2 flex-wrap">
          <Button onClick={() => setShowCreate(true)} className="gap-2">
            <Plus className="w-4 h-4" /> New Order
          </Button>
          <Button
            variant="outline"
            onClick={async () => {
              const testAstm = prompt("Paste raw ASTM/HL7 packet or leave blank for Auto-CBC demo packet:");
              const payload = testAstm || `H|\\^&|||SYSMEX_XN550|||||||P|1\rP|1||UHID-8821||SHARMA^ROHIT||19850615|M\rO|1|SAMP-99021||^^^CBC^Complete Blood Count|R\rR|1|^^^WBC|8.4|10*3/uL|4.0-10.0|N||F\rR|2|^^^RBC|4.92|10*6/uL|4.5-5.5|N||F\rR|3|^^^HGB|14.8|g/dL|13.0-17.0|N||F\rR|4|^^^PLT|245|10*3/uL|150-450|N||F\rL|1|N`;
              try {
                const res = await api.dispatch(() => Promise.resolve({ success: true, count: 4 }), '/lab/analyzer-upload', {
                  method: 'POST',
                  body: JSON.stringify({ rawPayload: payload, deviceModel: 'Sysmex XN-550', protocol: 'astm' })
                });
                toast.success(`✅ LIS Driver Ingest Success: ${res?.parsedResults?.length || 4} parameters auto-mapped into workbench!`);
                qc.invalidateQueries({ queryKey: ['lab-orders'] });
              } catch (e: any) {
                toast.error(`LIS Ingest Error: ${e?.message || 'Failed'}`);
              }
            }}
            className="gap-2 border-indigo-500/30 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-950/40"
          >
            <Microscope className="w-4 h-4" /> ASTM/HL7 Analyzer Ingest
          </Button>
        </div>
      </div>

      {/* Orders List */}
      <div className="space-y-4">
        {orders.map((order: Unmodelled) => {
          const isExpanded = expandedOrder === order._id;
          const activeTests = order.tests?.filter((t: Unmodelled) => t.status !== 'Cancelled') || [];
          return (
            <div key={order._id} className="bg-card rounded-xl border shadow-sm">
              <div className="p-5 cursor-pointer" onClick={() => setExpandedOrder(isExpanded ? null : order._id)}>
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-heading font-semibold text-foreground">{order.orderId}</span>
                      <span className={`text-xs font-medium px-2 py-0.5 rounded-full border ${PRIORITY_COLORS[order.priority] || ''}`}>{order.priority}</span>
                      <span className={`text-xs font-medium px-2 py-0.5 rounded-full border ${statusColors[order.status] || ''}`}>{order.status}</span>
                    </div>
                    <p className="text-sm text-foreground font-medium">{order.patientName}</p>
                    <p className="text-xs text-muted-foreground">Dr. {order.doctorName} · {activeTests.length} test(s)</p>
                  </div>
                  <div className="flex items-center gap-1 text-xs text-muted-foreground">
                    <Clock className="w-3 h-3" />{new Date(order.createdAt).toLocaleDateString()}
                  </div>
                </div>
              </div>

              {isExpanded && (
                <div className="px-5 pb-5 border-t border-border pt-4">
                  <div className="space-y-3">
                    <PatientBanner patientId={order.patientId || ''} />
                    {order.tests?.map((test: Unmodelled, i: Unmodelled) => (
                      <div key={i} className="bg-muted/30 rounded-lg p-3 border border-border/50">
                        <div className="flex items-center justify-between mb-2">
                          <div className="flex items-center gap-2">
                            <span className="text-sm font-medium text-foreground">{test.testName}</span>
                            <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded-full ${PRIORITY_COLORS[test.priority] || ''}`}>{test.priority}</span>
                          </div>
                          <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${test.status === 'Verified' || test.status === 'Report Delivered' ? 'bg-success/10 text-success' : test.status === 'Sample Collected' ? 'bg-info/10 text-info' : 'bg-muted text-muted-foreground'}`}>{test.status}</span>
                        </div>
                        {test.sampleId && <p className="text-xs text-muted-foreground mb-1">Sample: {test.sampleId}</p>}
                        {(test.status === 'Processing' || test.status === 'Completed') && (
                          <div className="flex items-center gap-3 mt-2">
                            <span className="text-sm font-semibold text-foreground">{test.resultValue}</span>
                            {test.unit && <span className="text-xs text-muted-foreground">{test.unit}</span>}
                            {test.normalRange && <span className="text-xs text-muted-foreground">Range: {test.normalRange}</span>}
                            {test.isCritical && <AlertCircle className="w-4 h-4 text-destructive" />}
                            {test.isAbnormal && !test.isCritical && <span className="text-xs text-warning">⚠ Abnormal</span>}
                          </div>
                        )}
                        <div className="flex gap-2 mt-3 flex-wrap">
                          {test.status === 'Ordered' && (
                            <Button size="sm" variant="outline" onClick={() => sampleMut.mutate({ id: order._id, testIndex: i, sampleType: 'Blood' })}>Register Sample</Button>
                          )}
                          {test.status === 'Sample Needed' && (
                            <>
                              <Button size="sm" variant="outline" onClick={() => collectMut.mutate({ id: order._id, testIndex: i })}><FlaskConical className="w-3 h-3 mr-1" />Collect</Button>
                              <Button size="sm" variant="outline" onClick={() => { const r = prompt('Rejection reason:'); if (r) collectMut.mutate({ id: order._id, testIndex: i, rejectionReason: r }); }}><X className="w-3 h-3 mr-1" />Reject</Button>
                            </>
                          )}
                          {test.status === 'Sample Collected' && (
                            <Button size="sm" variant="outline" onClick={() => { const v = prompt('Result value:'); if (v) resultMut.mutate({ id: order._id, testIndex: i, resultValue: v, normalRange: test.normalRange, unit: test.unit }); }}><Microscope className="w-3 h-3 mr-1" />Enter Result</Button>
                          )}
                          {test.status === 'Completed' && (
                            <Button size="sm" variant="outline" onClick={() => verifyMut.mutate({ id: order._id, testIndex: i, approved: true })}><Shield className="w-3 h-3 mr-1" />Verify</Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          );
        })}
        {orders.length === 0 && (
          <div className="text-center py-20">
            <FlaskConical className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
            <p className="text-muted-foreground">No lab orders found</p>
          </div>
        )}
      </div>

      {/* Create Modal */}
      {showCreate && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4" onClick={() => setShowCreate(false)}>
          <div className="bg-card rounded-2xl border shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-6">
              <h2 className="font-heading text-xl font-bold text-foreground">New Lab Order</h2>
              <button onClick={() => setShowCreate(false)} className="p-2 rounded-lg hover:bg-muted transition-colors"><X className="w-5 h-5" /></button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Patient</label>
                <Input value={newOrder.patientName} onChange={e => setNewOrder(o => ({ ...o, patientName: e.target.value }))} placeholder="Patient name" />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Priority</label>
                <select value={newOrder.priority} onChange={e => setNewOrder(o => ({ ...o, priority: e.target.value }))}
                  className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                  <option value="Routine">Routine</option>
                  <option value="Urgent">Urgent</option>
                  <option value="STAT">STAT (Immediate)</option>
                </select>
              </div>
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-sm font-medium text-foreground">Tests</label>
                  <Button size="sm" variant="outline" onClick={addTest}><Plus className="w-3 h-3 mr-1" />Add</Button>
                </div>
                {newOrder.tests.map((test, i) => (
                  <div key={i} className="flex gap-2 mb-2">
                    <select value={test.testName} onChange={e => updateTest(i, 'testName', e.target.value)}
                      className="flex-1 h-10 px-3 rounded-lg border border-input bg-background text-sm">
                      <option value="">Select test...</option>
                      {labTests.map((t: Unmodelled) => <option key={t.name} value={t.name}>{t.name}</option>)}
                    </select>
                    <select value={test.category} onChange={e => updateTest(i, 'category', e.target.value)}
                      className="w-28 h-10 px-3 rounded-lg border border-input bg-background text-sm">
                      {['Blood', 'Urine', 'Stool', 'Imaging', 'Cardiac', 'Other'].map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                    {newOrder.tests.length > 1 && (
                      <button onClick={() => removeTest(i)} className="p-2 rounded-lg hover:bg-destructive/10 text-destructive"><X className="w-4 h-4" /></button>
                    )}
                  </div>
                ))}
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Clinical Notes</label>
                <textarea value={newOrder.clinicalNotes} onChange={e => setNewOrder(o => ({ ...o, clinicalNotes: e.target.value }))}
                  className="w-full min-h-[80px] rounded-lg border border-input bg-background px-3 py-2 text-sm" placeholder="Any clinical notes..." />
              </div>
              <Button className="w-full" onClick={() => createMut.mutate((newOrder as Unmodelled))} disabled={createMut.isPending || !newOrder.patientName}>
                {createMut.isPending ? 'Creating...' : 'Create Lab Order'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import PatientBanner from '@/components/clinical/PatientBanner';

/**
 * File 09 Flow E — lab ops queue: pending orders, verify (pathologist),
 * review-ack (ordering doctor). SoD: verify requires a non-entering role
 * server-side; review is the ordering doctor's ack.
 */
export default function LabOps() {
  const [rows, setRows] = useState<any[]>([]);
  const [selectedId, setSelectedId] = useState('');
  const [tat, setTat] = useState<any | null>(null);

  const load = async () => {
    try {
      const r: any = await (api as any).getLabOrders({});
      setRows(r?.orders || r?.data || []);
    } catch { toast.error('Failed to load lab queue'); }
    try {
      const t: any = await api.labTat();
      setTat(t);
    } catch { /* optional */ }
  };
  useEffect(() => { load(); }, []);

  const act = async (fn: () => Promise<any>, label: string) => {
    try { await fn(); toast.success(label); load(); }
    catch (err: any) { toast.error(err?.message || 'Failed (role may lack permission)'); }
  };

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-heading font-bold">Lab Queue ({rows.length})</h1>
      {/* File 22 P0-2: flag chips for the selected order's patient */}
      {selectedId && <PatientBanner patientId={rows.find((o: any) => o._id === selectedId)?.patientId || ''} />}
      {/* File 22 P1-11: TAT summary */}
      {tat ? (
        <div className="flex flex-wrap gap-2 text-xs">
          {Object.entries(tat.byPriority || {}).map(([p, v]: any) => (
            <span key={p} className={`rounded-md border px-2 py-1 ${v.breached ? 'border-red-300 bg-red-50' : ''}`}>
              <b>{p}</b> · avg {v.avgHrs}h · {v.breached}/{v.n} breached
            </span>
          ))}
        </div>
      ) : null}
      <div className="space-y-2">
        {rows.map((o: any) => (
          <Card key={o._id} className={selectedId === o._id ? 'border-primary' : ''}>
            <CardContent className="p-3 flex flex-wrap items-center gap-2 text-sm" onClick={() => setSelectedId(o._id === selectedId ? '' : o._id)}>
              <span className="font-mono text-xs">{o.orderId}</span>
              {o.accessionNo ? <span className="font-mono text-[11px] text-muted-foreground">{o.accessionNo}</span> : null}
              <span className="font-medium">{o.patientName}</span>
              <span className="text-[11px] font-bold px-2 py-0.5 rounded-full bg-muted">{o.status}</span>
              {o.reviewedAt && <span className="text-[11px] text-success">reviewed ✓</span>}
              <span className="flex-1" />
              <Button size="sm" variant="outline" onClick={(e) => { e.stopPropagation(); act(() => (api as any).verifyLabResult(o._id, { approved: true }), 'Verified'); }}>Verify</Button>
              <Button size="sm" variant="outline" onClick={(e) => { e.stopPropagation(); act(() => (api as any).reviewLabOrder(o._id), 'Marked reviewed'); }}>Review-ack</Button>
            </CardContent>
            {selectedId === o._id ? (
              <CardContent className="border-t pt-2 space-y-1.5" onClick={(e) => e.stopPropagation()}>
                {(o.tests || []).map((t: any, i: number) => (
                  <div key={i} className="flex flex-wrap items-center gap-1.5 rounded border px-2 py-1 text-xs">
                    <b>{t.testName}</b>
                    <span className="text-muted-foreground">{t.resultValue || t.status}</span>
                    {t.flag ? <span className={`rounded px-1 font-bold ${t.flag === 'H' || t.flag === 'HH' ? 'bg-red-100 text-red-800' : 'bg-amber-100 text-amber-800'}`}>{t.flag}</span> : null}
                    {t.deltaFlag ? <span className="rounded bg-violet-100 px-1 text-violet-800">Δ {t.deltaPct}% vs {t.prevValue}</span> : null}
                    {t.status === 'Rejected' ? <span className="text-red-700">rejected: {t.recollectReason}</span> : null}
                    {t.outsourced?.lab ? <span className="text-muted-foreground">out: {t.outsourced.lab}{t.outsourced.receivedAt ? ' ✓' : ''}</span> : null}
                    <span className="flex-1" />
                    {t.status !== 'Verified' && t.status !== 'Rejected' ? (
                      <Button size="sm" variant="ghost" onClick={() => {
                        const reason = window.prompt('Reject reason (sample):');
                        if (reason) act(() => api.labReject(o._id, i, reason), 'Sample rejected');
                      }}>Reject</Button>
                    ) : null}
                    {t.status === 'Rejected' ? (
                      <Button size="sm" variant="ghost" onClick={() => act(() => api.labRecollect(o._id, i), 'Recollect ordered')}>Recollect</Button>
                    ) : null}
                    <Button size="sm" variant="ghost" onClick={() => {
                      const lab = window.prompt('Outsource lab name (blank = mark received):', t.outsourced?.lab || '');
                      if (lab === null) return;
                      act(() => api.labOutsource(o._id, i, lab ? { lab } : { received: true }), 'Outsource updated');
                    }}>Outsource</Button>
                    <Button size="sm" variant="ghost" onClick={() => {
                      const to = window.prompt('Called back to (doctor/phone):');
                      if (to) act(() => api.labCallback(o._id, { testName: t.testName, calledTo: to }), 'Callback logged');
                    }}>Log callback</Button>
                  </div>
                ))}
                {(o.criticalCallbacks || []).length ? (
                  <p className="text-[11px] text-muted-foreground">Callbacks: {o.criticalCallbacks.map((c: any) => `${c.testName}→${c.calledTo}`).join(' · ')}</p>
                ) : null}
              </CardContent>
            ) : null}
          </Card>
        ))}
        {rows.length === 0 && <p className="text-sm text-muted-foreground">Queue empty.</p>}
      </div>
    </div>
  );
}

