const isDemoEmail = (emailStr?: string) => {
  if (!emailStr) return false;
  const e = emailStr.toLowerCase().trim();
  return (
    e.endsWith('@findmedi.com') ||
    e.endsWith('@mindsupport.seed') ||
    e.endsWith('@medicore.com') ||
    e.endsWith('@findmedi.local') ||
    e.startsWith('demo-') ||
    e.startsWith('demo_') ||
    e === 'mahendrapra0077@gmail.com'
  );
};

export default function Login() {
  const navigate = useNavigate();
  const { user, loading: authLoading, login, completeGoogleLogin, completeTwoFactorLogin } = useAuth();
  // AUTH-UI: start with NO role selected. An empty role is omitted from the
  // payload entirely (see handleLogin), so the server logs the account in
  // without a `user.role !== role` mismatch - which is what made the 7 roles
  // that had no tile unloginable before this page became data-driven.
  const [role, setRole] = useState('');
  // Live list from GET /auth/login-roles; falls back to the bundled metadata.
  const [roleKeys, setRoleKeys] = useState<string[] | null>(null);
  const [demoCategory, setDemoCategory] = useState<'all' | 'counsellor' | 'psychiatrist' | 'assistant' | 'lawyer' | 'rider'>('all');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  // AUTH-B-03: pending 2FA step (set when the server answers with a ticket).
  const [twoFactorTicket, setTwoFactorTicket] = useState<string | null>(null);
  const [twoFactorCode, setTwoFactorCode] = useState('');

  // AUTH-UI: fetch the authoritative role list. Must run before the early
  // returns below (React hook ordering), and failures must not block login -
  // the bundled fallback keeps the grid usable when the API is down.
  useEffect(() => {
    let alive = true;
    api.loginRoles()
      .then((data: any) => {
        const keys = Array.isArray(data?.roles) ? data.roles.filter(Boolean) : null;
        if (alive && keys && keys.length) setRoleKeys(keys);
      })
      .catch(() => { /* offline / 5xx -> keep bundled fallback */ });
    return () => { alive = false; };
  }, []);

  const roleTiles = buildRoles(roleKeys ?? FALLBACK_ROLE_KEYS);

  // Wait for /auth/me hydration before redirecting. Otherwise a stale user in
  // memory during session validation can bounce between /login and /dashboard.
  // AUTH-F-06: a temp-password session goes to /set-password instead - every
  // data endpoint will 403 PASSWORD_RESET_REQUIRED until the flag is cleared.
  if (authLoading) return <div className="min-h-screen" role="status" aria-label="Checking session" />;
  if (user) return <Navigate to={(user.mustResetPassword && !isDemoEmail(user.email)) ? '/set-password' : '/dashboard'} replace />;

  const pickRole = (r: string) => {
    setRole(r);
    setEmail('');
    setPassword('');
    setError('');
    // Auto sync demo category if matches
    if (['counsellor', 'psychiatrist', 'assistant', 'lawyer', 'rider'].includes(r)) {
      setDemoCategory(r as any);
    }
  };

  const handleGoogleCredential = async (idToken: any, accessToken: any = null) => {
    setError('');
    setGoogleLoading(true);
    try {
      // AUTH-UI: omit `role` entirely when no tile is selected. Sending ''
      // would 400 against the zod enum, and sending a role the account does not
      // have 403s - so an unselected role means "log in as whatever this is".
      const data = await api.googleAuth({ idToken, accessToken, ...(role ? { role } : {}) });
      if (data.exists && data.token && data.user) {
        setAuthTokens(data.token);
        completeGoogleLogin(data.user);
        // AUTH-F-06: google sessions for temp-password accounts land on the
        // forced-rotation page too (the old login-time check never ran here).
        navigate((data.user.mustResetPassword && !isDemoEmail(data.user.email)) ? '/set-password' : '/dashboard', { replace: true });
        return;
      }

      const g = data.googleUser || {};
      const signupData = {
        role: role || 'patient',
        name: g.name || '',
        email: g.email || '',
        avatar: g.picture || '',
        isGoogle: true,
      };
      localStorage.setItem('google_signup', JSON.stringify(signupData));
      navigate('/signup', { state: signupData });
    } catch (err: any) {
      setError(err?.message || 'Google sign-in failed');
    } finally {
      setGoogleLoading(false);
    }
  };

  const GOOGLE_CLIENT_ID = (import.meta as any).env?.VITE_GOOGLE_CLIENT_ID;

  const handleGoogleLogin = () => {
    if (!GOOGLE_CLIENT_ID) {
      setError('Google Sign-In is not configured. Contact the administrator.');
      return;
    }

    const winGoogle = (window as any).google;

    if (winGoogle?.accounts?.oauth2) {
      try {
        const tokenClient = winGoogle.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: 'email profile openid',
          callback: (tokenResponse: any) => {
            if (tokenResponse?.access_token) {
              handleGoogleCredential(null, tokenResponse.access_token);
            }
          },
          error_callback: (err: any) => {
            console.error('Google OAuth popup error:', err);
            setError('Google sign-in was cancelled or closed.');
          },
        });
        tokenClient.requestAccessToken({ prompt: 'select_account' });
        return;
      } catch (oauthErr: any) {
        console.warn('initTokenClient failed, falling back to ID prompt:', oauthErr);
      }
    }

    if (winGoogle?.accounts?.id) {
      winGoogle.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: (response: any) => handleGoogleCredential(response.credential),
      });
      winGoogle.accounts.id.prompt();
    } else {
      setError('Google Sign-In script is loading. Please try again in a moment.');
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const result = await login(email, password, role || undefined);
      // AUTH-B-03: 2FA-enrolled accounts get a ticket, not a session.
      if (result?.requiresTwoFactor) {
        setTwoFactorTicket(result.twoFactorTicket);
        setTwoFactorCode('');
        return;
      }
      // AUTH-F-06: temp-password accounts must rotate before anything else (except demo accounts).
      if (result?.mustResetPassword && !isDemoEmail(email)) {
        navigate('/set-password', { replace: true });
        return;
      }
      navigate('/dashboard');
    } catch (err: any) {
      if (err?.requiresVerification || err?.message?.toLowerCase().includes('verify your email')) {
        const params = new URLSearchParams({ email });
        if (err.otpError || err.emailDeliveryFailed) params.set('delivery', 'failed');
        navigate(`/verify-otp?${params.toString()}`);
      } else if (err?.approvalPending || err?.approvalRejected) {
        navigate(
          `/pending-approval?email=${encodeURIComponent(email)}&role=${encodeURIComponent(role)}&status=${
            err.approvalRejected ? 'rejected' : 'pending'
          }`
        );
      } else {
        setError(err?.message || 'Login failed');
      }
    } finally {
      setLoading(false);
    }
  };

  // AUTH-B-03: second leg of the 2FA login (ticket + code -> real session).
  const handleTwoFactorSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const code = twoFactorCode.trim();
    if (!/^\d{6}$/.test(code)) {
      setError('Enter the 6-digit code from your authenticator app.');
      return;
    }
    setError('');
    setLoading(true);
    try {
      await completeTwoFactorLogin({ twoFactorTicket: twoFactorTicket!, token: code });
      navigate('/dashboard');
    } catch (err: any) {
      setError(err?.message || 'Invalid 2FA code');
    } finally {
      setLoading(false);
    }
  };

  if (twoFactorTicket) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="w-full max-w-md p-6 bg-card rounded-2xl border border-border shadow-sm"
        >
          <div className="w-12 h-12 flex items-center justify-center rounded-xl bg-primary/10 text-primary mb-4">
            <Shield className="w-6 h-6" />
          </div>
          <h2 className="font-heading text-2xl font-bold text-foreground mb-1">Two-factor verification</h2>
          <p className="text-muted-foreground text-sm mb-6">
            Enter the 6-digit code from your authenticator app to finish signing in.
          </p>
          <form onSubmit={handleTwoFactorSubmit} className="space-y-4">
            <Input
              type="text"
              inputMode="numeric"
              autoComplete="one-time-code"
              maxLength={6}
              placeholder="123456"
              value={twoFactorCode}
              onChange={(e) => setTwoFactorCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
              className="text-center text-2xl tracking-[0.4em]"
              aria-label="Two-factor code"
            />
            {error && <p className="text-sm text-destructive">{error}</p>}
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? 'Verifying...' : 'Verify and continue'}
            </Button>
            <button
              type="button"
              onClick={() => {
                setTwoFactorTicket(null);
                setTwoFactorCode('');
                setError('');
                setPassword('');
              }}
              className="w-full text-xs text-muted-foreground hover:text-foreground"
            >
              Use a different account
            </button>
          </form>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex">
      {/* Left Panel */}
      <div className="hidden lg:flex lg:w-1/2 bg-sidebar items-center justify-center p-12 relative overflow-hidden">
        <div
          className="absolute inset-0 opacity-10"
          style={{
            backgroundImage:
              'radial-gradient(circle at 25% 25%, hsl(174,62%,48%) 0%, transparent 50%), radial-gradient(circle at 75% 75%, hsl(210,80%,55%) 0%, transparent 50%)',
          }}
        />
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7 }}
          className="relative z-10 text-center max-w-md"
        >
          <div className="w-24 h-24 flex items-center justify-center mx-auto mb-6 rounded-2xl overflow-hidden shadow-lg">
            <img src="/logo.png" alt="FindMedi Logo" className="w-full h-full object-cover" />
          </div>
          <h1 className="font-heading text-4xl font-bold text-sidebar-primary-foreground mb-4">FindMedi</h1>
          <p className="text-sidebar-foreground/70 text-lg leading-relaxed mb-10">
            Complete hospital management solution. Manage patients, doctors, appointments, and billing — all in one place.
          </p>
        </motion.div>
      </div>

      {/* Right Panel */}
      <div className="flex-1 flex items-center justify-center p-4 sm:p-8">
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5 }}
          className="w-full max-w-md"
        >
          <div className="lg:hidden flex items-center gap-3 mb-8">
            <div className="w-12 h-12 flex items-center justify-center rounded-xl overflow-hidden shadow-sm">
              <img src="/logo.png" alt="FindMedi Logo" className="w-full h-full object-cover" />
            </div>
            <h1 className="font-heading text-xl font-bold text-foreground">FindMedi</h1>
          </div>

          <h2 className="font-heading text-2xl font-bold text-foreground mb-1">Welcome back</h2>
          <p className="text-muted-foreground mb-6">Select your role and sign in to continue</p>

          {/* Join Platform */}
          <div className="mb-5 p-3 bg-gradient-to-r from-primary/5 to-primary/10 rounded-xl border border-primary/20">
            <p className="text-xs font-medium text-foreground mb-2">Are you a healthcare provider?</p>
            <Link to="/join-platform">
              <Button
                variant="outline"
                className="w-full gap-2 rounded-xl border-primary/30 text-primary hover:bg-primary/5 text-xs h-9"
              >
                <Building2 className="w-3.5 h-3.5" /> Join Platform
                <ArrowRight className="w-3.5 h-3.5" />
              </Button>
            </Link>
          </div>

          {/* Role Selection */}
          <div className="grid grid-cols-4 gap-2 mb-6">
            {roleTiles.map(({ key, label, desc, icon: Icon, color, bg }) => (
              <button
                key={key}
                type="button"
                onClick={() => pickRole(key)}
                aria-pressed={role === key}
                className={`p-2 rounded-lg border text-center transition-all ${
                  role === key
                    ? 'border-primary bg-accent shadow-sm'
                    : 'border-border hover:border-primary/30 hover:bg-muted/50'
                }`}
              >
                <div className={`w-6 h-6 rounded-md ${bg} flex items-center justify-center mx-auto mb-1`}>
                  <Icon className={`w-3 h-3 ${color}`} />
                </div>
                <p className={`text-[11px] font-semibold leading-tight ${role === key ? 'text-primary' : 'text-foreground'}`}>
                  {label}
                </p>
                <p className="text-[8px] text-muted-foreground mt-0.5 leading-tight">{desc}</p>
              </button>
            ))}
          </div>

          <form onSubmit={handleLogin} className="space-y-3">
            <div>
              <label className="text-sm font-medium text-foreground mb-1 block">Email</label>
              <Input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Enter your email"
                required
                className="h-10"
              />
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-1 block">Password</label>
              <div className="relative">
                <Input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  required
                  className="h-10 pr-10"
                />
                <button
                  type="button"
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                >
                  {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>
            <div className="text-right -mt-1">
              <Link to="/forgot-password" className="text-xs text-primary font-medium hover:underline">
                Forgot password?
              </Link>
            </div>
            {error && <p className="text-sm text-destructive bg-destructive/10 px-3 py-2 rounded-lg">{error}</p>}
            <Button type="submit" className="w-full gap-2" disabled={loading}>
              {loading ? (
                <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
              ) : null}
              {loading ? 'Signing in...' : 'Sign In'}
              {!loading && <ArrowRight className="w-4 h-4" />}
            </Button>
          </form>

          {(() => {
            const hash = typeof window !== 'undefined' ? window.location.hash || '' : '';
            const qIndex = hash.indexOf('?');
            const qs = qIndex >= 0 ? hash.slice(qIndex + 1) : '';
            const ref = new URLSearchParams(qs).get('ref');
            return ref ? (
              <p className="text-xs text-center text-muted-foreground mt-3">
                Naya account? <Link to={`/signup?ref=${ref}`} className="text-primary underline">Signup karo</Link> apna referral bonus paane ke liye.
              </p>
            ) : null;
          })()}

          <p className="text-sm text-muted-foreground text-center mt-5">
            Don&apos;t have an account?{' '}
            <Link to="/signup" className="text-primary font-medium hover:underline">
              Sign Up
            </Link>
          </p>

          <div className="relative mt-4">
            <div className="absolute inset-0 flex items-center">
              <span className="w-full border-t" />
            </div>
            <div className="relative flex justify-center text-xs uppercase">
              <span className="bg-background px-2 text-muted-foreground">or</span>
            </div>
          </div>
          <Button
            type="button"
            variant="outline"
            className="w-full gap-2 mt-4"
            onClick={handleGoogleLogin}
            disabled={googleLoading}
          >
            <svg viewBox="0 0 24 24" className="w-4 h-4">
              <path
                fill="currentColor"
                d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z"
              />
              <path
                fill="currentColor"
                d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              />
              <path
                fill="currentColor"
                d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
              />
              <path
                fill="currentColor"
                d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              />
            </svg>
            {googleLoading ? 'Connecting...' : 'Continue with Google'}
          </Button>

          {import.meta.env.DEV && (
              <div className="mt-4 p-3 bg-muted/50 rounded-xl border border-border/50">
            <div className="flex items-center justify-between mb-2">
              <p className="text-xs font-semibold text-foreground">⚡ Quick Demo Login:</p>
              <span className="text-[10px] text-muted-foreground font-mono">Password: password</span>
            </div>

            {/* Category Pills */}
            <div className="flex gap-1 overflow-x-auto pb-1 mb-2.5 scrollbar-none">
              {[
                { id: 'all', label: 'All' },
                { id: 'counsellor', label: '🧠 Counsellors (5)' },
                { id: 'psychiatrist', label: '🩺 Psychiatrists (5)' },
                { id: 'assistant', label: '🧑‍⚕️ Assistants (5)' },
                { id: 'lawyer', label: '⚖️ Lawyers (5)' },
                { id: 'rider', label: '🚗 Riders (5)' },
              ].map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setDemoCategory(tab.id as any)}
                  className={`text-[10px] px-2 py-0.5 rounded-full font-medium whitespace-nowrap transition-colors ${
                    demoCategory === tab.id
                      ? 'bg-primary text-primary-foreground shadow-xs'
                      : 'bg-background/80 text-muted-foreground hover:bg-background border border-border/60'
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Grid of Accounts */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-1.5 max-h-72 overflow-y-auto pr-1">
              {demoAccounts
                .filter((acc) => demoCategory === 'all' ? acc.category === 'core' : acc.category === demoCategory)
                .map(({ key, label, desc, icon: Icon, color, bg, email: demoEmail, pass }) => (
                  <button
                    key={`${key}-${demoEmail}`}
                    type="button"
                    onClick={() => {
                      setRole(key);
                      setEmail(demoEmail);
                      setPassword(pass);
                      setError('');
                    }}
                    className={`p-2 rounded-lg border text-left transition-all cursor-pointer ${
                      email === demoEmail
                        ? 'border-primary bg-primary/10 shadow-xs ring-1 ring-primary/30'
                        : 'border-border/80 bg-background/80 hover:border-primary/40 hover:bg-background'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <div className={`w-6 h-6 rounded-md ${bg} flex items-center justify-center shrink-0`}>
                        <Icon className={`w-3.5 h-3.5 ${color}`} />
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="text-[11px] font-semibold leading-tight text-foreground truncate">{label}</p>
                        <p className="text-[8.5px] text-muted-foreground leading-tight truncate mt-0.5">{desc}</p>
                      </div>
                    </div>
                  </button>
                ))}
            </div>
            {demoCategory === 'all' && (
              <p className="text-xs text-center text-foreground font-medium mt-2 border-t border-border/40 pt-1.5">
                Tip: Click <b>🧠 Counsellors</b>, <b>🩺 Psychiatrists</b>, <b>🧑‍⚕️ Assistants</b>, <b>⚖️ Lawyers</b> or <b>🚗 Riders</b> tabs above to see all 5 test accounts each.
              </p>
            )}
          </div>
            )}
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * File 09 §06.7 — mortuary: body receipt with chamber tag, ID-verified
 * release, unclaimed flag (no release > configurable days — shown at 7d).
 */
export default function MortuaryPage() {
  const [rows, setRows] = useState<any[]>([]);
  const [form, setForm] = useState({ patientName: '', timeOfDeath: '', causeText: '' });
  const [rel, setRel] = useState({ id: '', releasedTo: '' });

  const load = async () => {
    try {
      const r: any = await (api as any).getMortuary({});
      setRows(r?.records || []);
    } catch { toast.error('Failed to load mortuary'); }
  };
  useEffect(() => { load(); }, []);

  const receive = async () => {
    try {
      await (api as any).receiveBody(form);
      toast.success('Body received & tagged');
      setForm({ patientName: '', timeOfDeath: '', causeText: '' });
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  const release = async () => {
    try {
      await (api as any).releaseBody(rel.id, { releasedTo: rel.releasedTo });
      toast.success('Released with ID verification');
      setRel({ id: '', releasedTo: '' });
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  const unclaimed = (r: any) => !r.releasedAt && Date.now() - new Date(r.createdAt).getTime() > 7 * 864e5;

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-heading font-bold">Mortuary</h1>
      <div className="grid md:grid-cols-2 gap-4">
        <Card>
          <CardHeader><CardTitle className="text-base">Body receipt</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <Input placeholder="Deceased name" value={form.patientName} onChange={(e) => setForm({ ...form, patientName: e.target.value })} />
            <Input type="datetime-local" aria-label="Time of death" value={form.timeOfDeath} onChange={(e) => setForm({ ...form, timeOfDeath: e.target.value })} />
            <Input placeholder="Cause (text)" value={form.causeText} onChange={(e) => setForm({ ...form, causeText: e.target.value })} />
            <Button onClick={receive} disabled={!form.patientName || !form.timeOfDeath}>Receive & tag</Button>
          </CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">Release (ID verified)</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <Input placeholder="Record ID" value={rel.id} onChange={(e) => setRel({ ...rel, id: e.target.value })} />
            <Input placeholder="Released to (name + relation)" value={rel.releasedTo} onChange={(e) => setRel({ ...rel, releasedTo: e.target.value })} />
            <Button onClick={release} disabled={!rel.id || !rel.releasedTo}>Release</Button>
          </CardContent>
        </Card>
      </div>
      <div className="space-y-2">
        {rows.map((r: any) => (
          <Card key={r._id} className={unclaimed(r) ? 'border-warning' : ''}>
            <CardContent className="p-3 flex flex-wrap items-center gap-2 text-sm">
              <span className="font-mono text-xs">{r.mortuaryTagNo}</span>
              <span className="font-medium">{r.patientName}</span>
              {unclaimed(r) && <span className="text-[11px] font-bold px-2 py-0.5 rounded-full bg-warning/10 text-warning">UNCLAIMED 7d+</span>}
              <span className="flex-1" />
              <span className="text-xs text-muted-foreground">{r.releasedAt ? `Released to ${r.releasedTo}` : 'In chamber'}</span>
            </CardContent>
          </Card>
        ))}
        {rows.length === 0 && <p className="text-sm text-muted-foreground">Chambers empty.</p>}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Bell, Calendar, CreditCard, FileText, Check, Trash2, AlertCircle, Trash } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/context/AuthContext';
import { useNotificationCount } from '@/context/NotificationContext';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const typeIcons: Unmodelled = { reminder: Calendar, payment: CreditCard, appointment: Calendar, records: FileText, system: AlertCircle };
const typeColors: Unmodelled = { reminder: 'bg-warning/10 text-warning', payment: 'bg-success/10 text-success', appointment: 'bg-info/10 text-info', records: 'bg-primary/10 text-primary', system: 'bg-purple-500/10 text-purple-600' };

export default function Notifications() {
  const { user } = useAuth();
  const { refreshCount } = useNotificationCount();
  const [notifications, setNotifications] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);

  const loadNotifications = async () => {
    setLoading(true);
    try {
      const data = await api.getNotifications({});
      const list = data?.data || data?.notifications || data || [];
      const userId = (user?._id || user?.id)?.toString();
      let filtered = list;
      if (user?.role !== 'hospital_admin') {
        filtered = list.filter((n: Unmodelled) => n.userId === userId);
      }
      setNotifications(filtered);
    } catch (e: any) { 
      console.error(e);
      setNotifications([]);
    }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadNotifications(); }, [user?._id, user?.id, user?.role]);

  const handleMarkRead = async (id: Unmodelled) => {
    try { 
      await api.markNotificationRead(id); 
      loadNotifications();
      refreshCount();
    } catch (e: any) { console.error(e); }
  };

  const handleMarkAllRead = async () => {
    try {
      await api.markAllRead();
      loadNotifications();
      refreshCount();
    } catch (e: any) { console.error(e); }
  };

  const handleDelete = async (id: Unmodelled) => {
    try { 
      await api.deleteNotification(id); 
      loadNotifications();
      refreshCount();
    } catch (e: any) { console.error(e); }
  };

  const handleClearAll = async () => {
    if (!confirm('Are you sure you want to delete all notifications?')) return;
    try {
      await api.clearAllNotifications();
      loadNotifications();
      refreshCount();
    } catch (e: any) { console.error(e); }
  };

  const unreadCount = notifications.filter(n => !n.read).length;

  if (loading) return <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Notifications</h1>
          <p className="text-muted-foreground">
            {unreadCount > 0 ? `You have ${unreadCount} unread notification${unreadCount > 1 ? 's' : ''}` : 'All caught up!'}
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
          {unreadCount > 0 && (
            <Button variant="outline" size="sm" className="gap-2 w-full sm:w-auto" onClick={handleMarkAllRead}>
              <Check className="w-4 h-4" /> Mark all read
            </Button>
          )}
          {notifications.length > 0 && (
            <Button variant="outline" size="sm" className="gap-2 w-full sm:w-auto text-destructive hover:bg-destructive/10" onClick={handleClearAll}>
              <Trash className="w-4 h-4" /> Clear all
            </Button>
          )}
        </div>
      </div>

      {notifications.length === 0 ? (
        <div className="text-center py-12">
          <Bell className="w-12 h-12 text-muted-foreground mx-auto mb-3" />
          <p className="text-muted-foreground">No notifications yet</p>
        </div>
      ) : (
        <div className="space-y-3">
          {notifications.map((n, i) => {
            const TypeIcon = typeIcons[n.type] || Bell;
            return (
              <motion.div key={n._id} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.05 }}
                className={`bg-card rounded-2xl border p-4 flex items-start gap-4 transition-all ${n.read ? 'border-border/60 opacity-70' : 'border-primary/30 bg-primary/5'}`}>
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${typeColors[n.type] || 'bg-muted text-muted-foreground'}`}>
                  <TypeIcon className="w-5 h-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between gap-2">
                    <h3 className={`font-medium text-sm ${n.read ? 'text-muted-foreground' : 'text-foreground'}`}>{n.title}</h3>
                    {!n.read && <div className="w-2 h-2 rounded-full bg-primary flex-shrink-0 mt-1.5" />}
                  </div>
                  <p className="text-sm text-muted-foreground mt-0.5">{n.message}</p>
                  <p className="text-xs text-muted-foreground/60 mt-1">{n.date}</p>
                </div>
                <div className="flex items-center gap-1 flex-shrink-0">
                  {!n.read && (
                    <Button variant="ghost" size="sm" onClick={() => handleMarkRead(n._id)} className="h-8 w-8 p-0">
                      <Check className="w-4 h-4" />
                    </Button>
                  )}
                  <Button variant="ghost" size="sm" onClick={() => handleDelete(n._id)} className="h-8 w-8 p-0 text-muted-foreground hover:text-destructive">
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useNavigate, useSearchParams, Navigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowRight, RefreshCw, CheckCircle, AlertCircle, ArrowLeft, ShieldCheck, MailCheck, TimerReset, LockKeyhole } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import type { Unmodelled } from '@/lib/apiTypes';

const OTP_LENGTH = 6;
const sanitizeOtp = (value: Unmodelled) => value.replace(/\D/g, '').slice(0, OTP_LENGTH);

export default function OTPVerification() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user, completeOtpLogin } = useAuth();
  const email = searchParams.get('email') || user?.email || '';
  const deliveryState = searchParams.get('delivery');
  const sentTo = searchParams.get('sentTo') || email;
  const otpInputRef: Unmodelled = useRef<Unmodelled>(null);

  const [otp, setOtp] = useState('');
  const [isOtpFocused, setIsOtpFocused] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [deliveryProblem, setDeliveryProblem] = useState(deliveryState === 'failed');
  const [notice, setNotice] = useState(deliveryState === 'failed'
    ? 'We could not confirm that the verification email was sent. Please resend the code.'
    : 'Enter the 6-digit code sent to your email.');
  const [resendLoading, setResendLoading] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);

  useEffect(() => {
    if (resendCooldown <= 0) return undefined;
    const timer = setTimeout(() => setResendCooldown((seconds) => Math.max(0, seconds - 1)), 1000);
    return () => clearTimeout(timer);
  }, [resendCooldown]);

  // If already logged in and verified, redirect
  if (user?.isVerified) {
    return <Navigate to="/dashboard" replace />;
  }

  if (!email) {
    return <Navigate to="/login" replace />;
  }

  const handleOtpChange = (value: Unmodelled) => {
    setOtp(sanitizeOtp(value));
    if (error) setError('');
  };

  const handlePaste = (e: Unmodelled) => {
    e.preventDefault();
    const pastedData = sanitizeOtp(e.clipboardData.getData('text'));
    if (!pastedData) return;

    setOtp(pastedData);
    if (error) setError('');
  };

  const handleSubmit = async (e: Unmodelled) => {
    e.preventDefault();
    if (otp.length !== OTP_LENGTH) {
      setError('Please enter the complete 6-digit OTP');
      otpInputRef.current?.focus();
      return;
    }

    setLoading(true);
    setError('');
    setNotice('');
    try {
      // Verify OTP on backend
      const data = await api.verifyOTP({ email, otp });
      if (data?.approvalPending) {
        navigate(`/pending-approval?email=${encodeURIComponent(email)}&role=${encodeURIComponent(data?.user?.role || 'account')}&status=pending`);
        return;
      }

      if (data?.token && data?.user) {
        completeOtpLogin({ token: data.token, user: data.user } as Unmodelled);
      }

      navigate('/dashboard');
    } catch (err: any) {
      setError(err.message || 'Invalid OTP. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleResendOTP = async () => {
    setResendLoading(true);
    setError('');
    setNotice('');
    try {
      const data = await api.resendOTP({ email });
      setDeliveryProblem(false);
      setNotice(data?.simulated
        ? 'Email simulation is enabled on this server. Configure Brevo to send real emails.'
        : `A fresh verification code was sent to ${data?.sentTo || email}.`);
      setResendCooldown(60);
    } catch (err: any) {
      setDeliveryProblem(true);
      if (err.waitSeconds) setResendCooldown(err.waitSeconds);
      setError(err.message || 'Failed to resend OTP');
    } finally {
      setResendLoading(false);
    }
  };

  return (
    <div data-motion-ignore className="relative flex min-h-screen items-center justify-center overflow-hidden bg-background p-4">
      <div className="absolute inset-0 bg-[linear-gradient(135deg,hsl(var(--background))_0%,hsl(var(--muted)/0.78)_48%,hsl(var(--accent)/0.7)_100%)]" />
      <div className="absolute inset-0 opacity-[0.18] [background-image:linear-gradient(hsl(var(--foreground)/0.18)_1px,transparent_1px),linear-gradient(90deg,hsl(var(--foreground)/0.18)_1px,transparent_1px)] [background-size:42px_42px]" />
      <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-primary/10 to-transparent" />

      <button
        type="button"
        onClick={() => navigate('/login')}
        className="absolute left-4 top-4 z-10 inline-flex h-10 w-10 items-center justify-center rounded-full border border-border/70 bg-card/90 text-muted-foreground shadow-sm backdrop-blur transition-colors hover:text-foreground sm:left-6 sm:top-6"
        aria-label="Back to sign in"
      >
        <ArrowLeft className="h-4 w-4" />
      </button>

      <motion.div
        initial={{ opacity: 0, y: 18, scale: 0.96 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        transition={{ duration: 0.32, ease: [0.22, 1, 0.36, 1] }}
        className="relative w-full max-w-[440px]"
      >
        <div className="overflow-hidden rounded-[2rem] border border-border/70 bg-card/95 shadow-2xl shadow-primary/15 backdrop-blur-xl">
          <div className="h-1.5 bg-gradient-to-r from-primary via-info to-success" />
          <div className="relative overflow-hidden border-b border-border/60 bg-muted/30 px-6 py-6 text-center">
            <div className="absolute inset-x-0 top-0 h-24 bg-gradient-to-b from-primary/10 to-transparent" />
            <div className="relative mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary text-primary-foreground shadow-xl shadow-primary/25">
              <ShieldCheck className="h-8 w-8" />
            </div>
            <p className="relative font-heading text-xl font-bold text-foreground">FindMedi Verification</p>
            <p className="relative mt-1 text-xs font-medium uppercase tracking-[0.28em] text-primary">Secure email OTP</p>
          </div>

          <div className="p-6 sm:p-8">
            <div className="mb-6 text-center">
              <h1 className="font-heading text-3xl font-bold text-foreground">Enter OTP</h1>
              <p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">
                We sent a 6-digit code to <span className="font-semibold text-foreground">{sentTo}</span>.
              </p>
              <div className="mt-4 flex items-center justify-center gap-2 text-xs text-muted-foreground">
                <span className="inline-flex items-center gap-1.5 rounded-full border border-border/70 bg-background/70 px-3 py-1">
                  <MailCheck className="h-3.5 w-3.5 text-primary" />
                  Email sent
                </span>
                <span className="inline-flex items-center gap-1.5 rounded-full border border-border/70 bg-background/70 px-3 py-1">
                  <TimerReset className="h-3.5 w-3.5 text-primary" />
                  10 min
                </span>
              </div>
            </div>

            {(notice || deliveryProblem) && !error && (
              <div className={`mb-5 flex gap-3 rounded-2xl border px-4 py-3 text-sm ${
                deliveryProblem
                  ? 'border-warning/25 bg-warning/10 text-warning'
                  : 'border-primary/20 bg-primary/10 text-primary'
              }`}>
                {deliveryProblem ? <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0" /> : <CheckCircle className="mt-0.5 h-4 w-4 flex-shrink-0" />}
                <p>{notice}</p>
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-6">
              <div>
                <label htmlFor="otp-code" className="sr-only">
                  Enter 6-digit OTP
                </label>
                <div
                  className="relative"
                  onClick={() => otpInputRef.current?.focus()}
                >
                  <input
                    ref={otpInputRef}
                    id="otp-code"
                    type="text"
                    inputMode="numeric"
                    autoComplete="one-time-code"
                    pattern="[0-9]*"
                    maxLength={OTP_LENGTH}
                    value={otp}
                    onChange={(e) => handleOtpChange(e.target.value)}
                    onPaste={handlePaste}
                    onFocus={() => setIsOtpFocused(true)}
                    onBlur={() => setIsOtpFocused(false)}
                    className="absolute inset-0 z-10 h-full w-full cursor-text border-0 bg-transparent text-transparent caret-transparent outline-none"
                    aria-describedby="otp-help"
                    aria-label="Enter 6-digit verification code"
                    autoFocus
                  />
                  <div className="grid grid-cols-6 gap-2.5">
                    {Array.from({ length: OTP_LENGTH }).map((_, index) => {
                      const digit = otp[index] || '';
                      const activeSlot = Math.min(otp.length, OTP_LENGTH - 1);
                      const isActive = isOtpFocused && index === activeSlot && otp.length < OTP_LENGTH;

                      return (
                        <motion.div
                          key={index}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 0.05 * index }}
                          className={`pointer-events-none flex aspect-square min-h-12 items-center justify-center rounded-2xl border-2 text-xl font-bold transition-all sm:min-h-14 sm:text-2xl ${
                            digit
                              ? 'border-primary/60 bg-gradient-to-br from-primary/15 to-info/10 text-foreground shadow-lg shadow-primary/10'
                              : isActive
                                ? 'border-primary bg-background text-foreground ring-4 ring-primary/15'
                                : 'border-border bg-background/70 text-muted-foreground'
                          }`}
                        >
                          {digit || (isActive ? <span className="h-7 w-0.5 animate-pulse rounded-full bg-primary" /> : '')}
                        </motion.div>
                      );
                    })}
                  </div>
                </div>
                <p id="otp-help" className="mt-3 flex items-center justify-center gap-1.5 text-center text-xs text-muted-foreground">
                  <LockKeyhole className="h-3.5 w-3.5 text-primary" />
                  Type or paste the OTP in the six boxes.
                </p>
              </div>

              {error && (
                <motion.div
                  initial={{ opacity: 0, y: -4 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex gap-3 rounded-2xl border border-destructive/20 bg-destructive/10 p-4 text-sm text-destructive"
                >
                  <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0" />
                  <p>{error}</p>
                </motion.div>
              )}

              <Button
                type="submit"
                className="h-12 w-full gap-2 rounded-xl shadow-lg shadow-primary/20"
                size="lg"
                disabled={loading || otp.length !== OTP_LENGTH}
              >
                {loading ? (
                  <span className="h-5 w-5 rounded-full border-2 border-white border-t-transparent animate-spin" />
                ) : (
                  <CheckCircle className="h-5 w-5" />
                )}
                {loading ? 'Verifying...' : 'Verify Email'}
                {!loading && <ArrowRight className="h-4 w-4" />}
              </Button>
            </form>

            <div className="mt-6 rounded-2xl border border-border/60 bg-muted/25 p-4 text-center">
              <p className="text-xs text-muted-foreground">Didn&apos;t receive the OTP?</p>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleResendOTP}
                disabled={resendCooldown > 0 || resendLoading}
                className="mt-3 gap-2 rounded-full px-4"
              >
                <RefreshCw className={`h-4 w-4 ${resendLoading ? 'animate-spin' : ''}`} />
                {resendCooldown > 0 ? `Resend in ${resendCooldown}s` : 'Resend OTP'}
              </Button>
            </div>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * File 09 §04.9 — oncology: protocol master, BSA-based cycle scheduling,
 * administration with cytotoxic log.
 */
export default function OncologyPage() {
  const [protocols, setProtocols] = useState<any[]>([]);
  const [cycles, setCycles] = useState<any[]>([]);
  const [name, setName] = useState('');
  const [sched, setSched] = useState({ protocolId: '', patientId: '', cycleNo: '1', bsa: '' });

  const load = async () => {
    try {
      const [p, c] = await Promise.all([
        (api as any).getChemoProtocols(), (api as any).getChemoCycles({}),
      ]);
      setProtocols(p?.protocols || []);
      setCycles(c?.cycles || []);
    } catch { toast.error('Failed to load oncology'); }
  };
  useEffect(() => { load(); }, []);

  const createProtocol = async () => {
    try {
      await (api as any).createChemoProtocol({ name, totalCycles: 6, cycleDays: 21, drugs: [] });
      toast.success('Protocol created');
      setName('');
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  const schedule = async () => {
    try {
      await (api as any).scheduleChemo({ ...sched, cycleNo: Number(sched.cycleNo), bsa: Number(sched.bsa) || 0 });
      toast.success('Cycle scheduled (BSA doses computed)');
      setSched({ protocolId: '', patientId: '', cycleNo: '1', bsa: '' });
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  const administer = async (id: string) => {
    try {
      await (api as any).administerChemo(id, { cytotoxicLog: '' });
      toast.success('Cycle administered');
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-heading font-bold">Oncology</h1>
      <div className="grid md:grid-cols-2 gap-4">
        <Card>
          <CardHeader><CardTitle className="text-base">Protocols ({protocols.length})</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <div className="flex gap-2">
              <Input placeholder="Regimen name" value={name} onChange={(e) => setName(e.target.value)} />
              <Button onClick={createProtocol} disabled={!name}>Add</Button>
            </div>
            {protocols.map((p: any) => (
              <p key={p._id} className="text-sm">{p.name} <span className="text-muted-foreground">· {p.totalCycles} cycles × {p.cycleDays}d</span></p>
            ))}
          </CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">Schedule cycle (BSA dosing)</CardTitle></CardHeader>
          <CardContent className="grid grid-cols-2 gap-2">
            <select aria-label="Protocol" className="h-10 rounded-md border border-input bg-background px-3 text-sm col-span-2" value={sched.protocolId} onChange={(e) => setSched({ ...sched, protocolId: e.target.value })}>
              <option value="">Select protocol</option>
              {protocols.map((p: any) => <option key={p._id} value={p._id}>{p.name}</option>)}
            </select>
            <Input placeholder="Patient ID" value={sched.patientId} onChange={(e) => setSched({ ...sched, patientId: e.target.value })} />
            <Input placeholder="Cycle no." type="number" value={sched.cycleNo} onChange={(e) => setSched({ ...sched, cycleNo: e.target.value })} />
            <Input placeholder="BSA m²" value={sched.bsa} onChange={(e) => setSched({ ...sched, bsa: e.target.value })} />
            <Button onClick={schedule} disabled={!sched.protocolId || !sched.patientId}>Schedule</Button>
          </CardContent>
        </Card>
      </div>
      <Card>
        <CardHeader><CardTitle className="text-base">Cycles ({cycles.length})</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          {cycles.map((c: any) => (
            <div key={c._id} className="flex items-center gap-2 text-sm rounded-lg border border-border/50 p-2.5">
              <span className="font-mono text-xs">C{c.cycleNo}</span>
              <span className="text-[11px] px-2 py-0.5 rounded-full bg-muted">{c.status}</span>
              <span className="text-xs text-muted-foreground">BSA {c.bsa} · {(c.doses || []).length} drugs</span>
              <span className="flex-1" />
              {c.status === 'Scheduled' && <Button size="sm" variant="outline" onClick={() => administer(c._id)}>Administer</Button>}
            </div>
          ))}
          {cycles.length === 0 && <p className="text-sm text-muted-foreground">No cycles scheduled.</p>}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { CheckCircle2, Package, MapPin, Phone, Mail, Clock, Store, BadgeCheck, Truck, ShoppingBag, ArrowRight, Home, FileText, Printer, Share2, AlertTriangle, RotateCcw, Bell } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { useCart } from '@/context/CartContext';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';


export default function OrderConfirmation() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const orderIds = searchParams.get('orderIds')?.split(',') || [];
  const storeIds  = searchParams.get('stores')?.split(',') || [];
  const hasRx     = searchParams.get('rx') === 'true';
  const flowType  = searchParams.get('type') || 'medicine';
  const { entries, stores }: Unmodelled = useCart();
  const { user } = useAuth();
  const [snapshotStores] = useState<Unmodelled>(null);
  const [snapshotTotal] = useState(0);
  const [countdown] = useState(30);
  const [storeNames, setStoreNames] = useState<ApiRow>({});

  const getStore = (storeId: Unmodelled) => {
    const name = storeNames[storeId];
    return name ? { id: storeId, name } : { id: storeId, name: 'Store' };
  };

  useEffect(() => {
    const load = async () => {
      if (storeIds.length > 0) {
        try {
          const facilities = await api.getFacilities({ type: 'pharmacy' });
          const list = Array.isArray(facilities) ? facilities : (facilities?.facilities || facilities?.data || []);
          const map: Unmodelled = {};
          list.forEach((f: Unmodelled) => { map[f._id] = f.name; map[f.id] = f.name; });
          storeIds.forEach(sid => {
            if (sid) {
              const found = list.find((f: Unmodelled) => f._id === sid || f.id === sid);
              if (found) map[sid] = found.name;
            }
          });
          setStoreNames(map);
        } catch { /* empty */ }
      }
    };
    load();
  }, [storeIds]);

  const displayStores = snapshotStores ?? stores;
  const displayTotal = snapshotStores !== null ? snapshotTotal : entries.reduce((s: Unmodelled, e: Unmodelled) => s + e.item.price * e.qty, 0);

  return (
    <div className="min-h-screen bg-gradient-to-b from-emerald-50/50 to-background dark:from-emerald-950/10 dark:to-background">
      <div className="max-w-2xl mx-auto px-4 sm:px-6 py-12 text-center">
        {/* Success Animation */}
        <div className="w-20 h-20 rounded-full bg-emerald-100 dark:bg-emerald-500/20 flex items-center justify-center mx-auto mb-6 animate-bounce">
          <CheckCircle2 className="w-10 h-10 text-emerald-600" />
        </div>

        <h1 className="font-heading text-3xl font-bold text-foreground mb-2">Order Placed Successfully!</h1>
        <p className="text-muted-foreground mb-2">Thank you for your order. Your medicines are on their way.</p>

        {/* Per-store order IDs */}
        <div className="flex flex-wrap justify-center gap-2 mb-8">
          {displayStores.map((st: Unmodelled, i: Unmodelled) => {
            const store = getStore(st.storeId);
            return (
              <Badge key={st.storeId} className="text-sm px-4 py-1.5 bg-primary/10 text-primary border-primary/20 font-mono">
                <FileText className="w-3.5 h-3.5 mr-1.5" /> {orderIds[i] || `ORD${i + 1}`} — {store?.name}
              </Badge>
            );
          })}
        </div>

        {/* Notification Simulation */}
        <div className="bg-blue-50 dark:bg-blue-500/10 border border-blue-200 dark:border-blue-500/20 rounded-2xl p-4 mb-6 text-left flex items-center gap-3">
          <Bell className="w-5 h-5 text-blue-600 shrink-0 animate-pulse" />
          <div className="text-xs text-blue-700 dark:text-blue-300">
            <p className="font-semibold">Confirmation sent</p>
            <p>Email to <strong>{user?.email || 'your email'}</strong> &bull; SMS to <strong>{user?.phone || 'your phone'}</strong></p>
          </div>
        </div>

        {/* Delivery Countdown */}
        <div className="bg-card rounded-2xl border border-border/60 p-6 mb-6 text-left">
          <div className="flex items-center gap-3 mb-4">
            <Truck className="w-6 h-6 text-primary" />
            <div>
              <p className="font-semibold text-foreground">Estimated Delivery</p>
              <p className="text-sm text-muted-foreground">
                {countdown > 0
                  ? `Your order will be delivered in approximately ${countdown} minutes`
                  : 'Your order has been delivered!'}
              </p>
            </div>
          </div>
          <div className="h-2 bg-muted rounded-full overflow-hidden">
            <div className="h-full bg-primary rounded-full transition-all duration-1000" style={{ width: `${((30 - countdown) / 30) * 100}%` }} />
          </div>
        </div>

        {/* Store-wise Items */}
        <div className="bg-card rounded-2xl border border-border/60 p-5 mb-6 text-left">
          <h3 className="font-heading font-semibold text-foreground mb-4 flex items-center gap-2">
            <Package className="w-4 h-4 text-primary" /> Order Items
          </h3>
          {displayStores.map((st: Unmodelled, i: Unmodelled) => {
            const store = getStore(st.storeId);
            return (
              <div key={st.storeId} className={cn('pb-3', i < displayStores.length - 1 && 'mb-3 border-b border-border/30')}>
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <Store className="w-3.5 h-3.5 text-primary" />
                    <span className="text-sm font-medium text-foreground">{store?.name}</span>
                  </div>
                  <Badge className="text-[10px] bg-primary/10 text-primary font-mono">{orderIds[i]}</Badge>
                </div>
                {st.items.map((e: Unmodelled) => (
                  <div key={e.key} className="flex items-center justify-between py-1.5 text-sm">
                    <span className="text-muted-foreground">{e.item.name} x{e.qty}</span>
                    <span className="font-medium text-foreground">₹{e.item.price * e.qty}</span>
                  </div>
                ))}
                <div className="flex justify-between mt-2 pt-2 border-t border-border/20">
                  <span className="text-sm text-muted-foreground">Subtotal</span>
                  <span className="text-sm font-semibold text-foreground">₹{st.subtotal}</span>
                </div>
              </div>
            );
          })}
          <Separator className="my-3" />
          <div className="flex justify-between text-base font-bold">
            <span>Total Paid</span>
            <span className="text-primary">₹{displayTotal}</span>
          </div>
        </div>

        {/* Partial Fulfillment Refund Notice */}
        {searchParams.get('refunded') === 'true' && (
          <div className="bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/20 rounded-2xl p-5 mb-6 text-left">
            <div className="flex items-start gap-3">
              <RotateCcw className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
              <div>
                <p className="text-sm font-semibold text-amber-700 dark:text-amber-400">Partial Refund Processed</p>
                <p className="text-xs text-amber-600 dark:text-amber-300 mt-1">
                  Some prescription-required items could not be processed due to prescription issues. 
                  Refund of <strong>₹{searchParams.get('refundAmount') || '0'}</strong> has been initiated for the following items:
                </p>
                <ul className="mt-2 space-y-1">
                  {searchParams.get('refundItems')?.split(',').map((item, i) => (
                    <li key={i} className="text-xs text-amber-600 dark:text-amber-300 flex items-center gap-1.5">
                      <AlertTriangle className="w-3 h-3 shrink-0" /> {item.trim()}
                    </li>
                  ))}
                </ul>
                <p className="text-xs text-muted-foreground mt-2">Refund will be credited within 3-5 business days to your original payment method.</p>
              </div>
            </div>
          </div>
        )}

        {/* Delivery Address */}
        <div className="bg-card rounded-2xl border border-border/60 p-5 mb-6 text-left">
          <div className="flex items-start gap-3">
            <MapPin className="w-5 h-5 text-primary mt-0.5 shrink-0" />
            <div>
              <h4 className="font-semibold text-sm text-foreground">Delivery Address</h4>
              <p className="text-sm text-muted-foreground mt-1">123, Health Avenue, Block C, Downtown, New York, NY 10001</p>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex flex-col sm:flex-row gap-3 mb-8 justify-center">
          {displayStores.map((st: Unmodelled, i: Unmodelled) => {
            const tid = orderIds[i];
            return (
              <Button key={st.storeId} className="gap-2 rounded-xl flex-1" onClick={() =>               navigate(`/order-tracking/${tid}?rx=${hasRx}&storeId=${st.storeId}&type=${flowType}`)}>
                <Truck className="w-4 h-4" /> Track {storeIds.length > 1 ? `Order ${i + 1}` : 'Order'}
              </Button>
            );
          })}
          <Button variant="outline" className="gap-2 rounded-xl flex-1" onClick={() => navigate('/buy-medicine')}>
            <ShoppingBag className="w-4 h-4" /> Continue Shopping
          </Button>
          <Button variant="outline" className="gap-2 rounded-xl flex-1" onClick={() => window.print()}>
            <Printer className="w-4 h-4" /> Print Invoice
          </Button>
        </div>

        <p className="text-xs text-muted-foreground">
          A confirmation email and SMS has been sent to your registered contact.
        </p>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import {
  Package, CheckCircle2, Clock, Truck, Home, Store, BadgeCheck,
  Phone, MapPin, ArrowLeft, ChevronDown, ChevronUp, FileText,
  RotateCcw, XCircle, MessageSquare, AlertCircle, ShoppingCart,
  Star, FlaskConical, Activity, Calendar, Bell, User, Microscope,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import { useCart } from '@/context/CartContext';
import { FLOW_TYPE, TRACKING_STAGES } from '@/hooks/useBookingFlow';
import { api, getApiBaseUrl } from '@/lib/api';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

// ─── Icon map (string key → Lucide component) ─────────────────────────────────
const ICON_MAP: Unmodelled = {
  Package, CheckCircle2, Clock, Truck, Home, Store, FlaskConical,
  Activity, FileText, Calendar, Bell, User, Microscope,
};



// ─── Type-specific display metadata ──────────────────────────────────────────
const FLOW_META = {
  [FLOW_TYPE.MEDICINE]: {
    title:       'Track Order',
    entityLabel: 'Pharmacy',
    doneLabel:   'Delivered',
    successMsg:  'Your medicines have been delivered!',
    doneGradient:'from-emerald-50/50 to-background dark:from-emerald-950/10',
  },
  [FLOW_TYPE.TEST]: {
    title:       'Track Lab Booking',
    entityLabel: 'Lab',
    doneLabel:   'Report Ready',
    successMsg:  'Your lab report is ready! Download below.',
    doneGradient:'from-violet-50/50 to-background dark:from-violet-950/10',
  },
  [FLOW_TYPE.APPOINTMENT]: {
    title:       'Track Appointment',
    entityLabel: 'Clinic',
    doneLabel:   'Completed',
    successMsg:  'Your appointment has been completed.',
    doneGradient:'from-sky-50/50 to-background dark:from-sky-950/10',
  },
};

// ─── Progress speed per flow type (ms per stage advance) ─────────────────────
const ADVANCE_INTERVAL = {
  [FLOW_TYPE.MEDICINE]:    5000,
  [FLOW_TYPE.TEST]:        6000,
  [FLOW_TYPE.APPOINTMENT]: 7000,
};

export default function OrderTracking() {
  const { orderId } = useParams();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { addItem }: Unmodelled = useCart();

  const hasRx   = searchParams.get('rx')      === 'true';
  const storeId = searchParams.get('storeId') || 's1';
  const rawType = searchParams.get('type')    || FLOW_TYPE.MEDICINE;

  // Normalise type — fall back to medicine if unknown
  const flowType = Object.values(FLOW_TYPE).includes(rawType) ? rawType : FLOW_TYPE.MEDICINE;
  const meta     = FLOW_META[flowType];

  const [orderData, setOrderData] = useState<Unmodelled>(null);
  const [_loadingOrder, setLoadingOrder] = useState(true);

  useEffect(() => {
    if (!orderId) { setLoadingOrder(false); return; }
    const load = async () => {
      try {
        const res = await api.getOrder(orderId);
        const ord = res?.order || res;
        if (ord) setOrderData(ord);
      } catch (e: any) { console.error('Failed to load order:', e); } finally { setLoadingOrder(false); }
    };
    load();
  }, [orderId]);

  const [storeNameMap, setStoreNameMap] = useState<ApiRow>({});
  useEffect(() => {
    const load = async () => {
      try {
        const res = await api.getFacilities({ type: 'pharmacy' });
        const list = Array.isArray(res) ? res : (res?.facilities || res?.data || []);
        const map: Unmodelled = {};
        list.forEach((f: Unmodelled) => { map[f._id] = f.name; map[f.id] = f.name; });
        if (storeId) {
          const found = list.find((f: Unmodelled) => f._id === storeId || f.id === storeId);
          if (found) map[storeId] = found.name;
        }
        setStoreNameMap(map);
      } catch (e: any) { console.error('Failed to load facilities:', e); }
    };
    load();
  }, [storeId]);

  // Build the stage list for this flow + rx combination
  const STAGES = TRACKING_STAGES[flowType](hasRx).map((s, i) => {
    const now = new Date();
    const offset = (TRACKING_STAGES[flowType](hasRx).length - 1 - i) * 8; // minutes ago
    const d = new Date(now.getTime() - offset * 60000);
    return {
      ...s,
      time: d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
    };
  });

  const storeName = storeNameMap[storeId] || orderData?.storeName || 'Store';
  const store = { id: storeId, name: storeName, photo: '', verified: true, phone: orderData?.phone || '', type: 'pharmacy' };

  const [currentStage,    setCurrentStage]    = useState(0);
  const [showActions,     setShowActions]     = useState(false);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [reviewRating, setReviewRating] = useState(0);
  const [reviewComment, setReviewComment] = useState('');
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [returnReason,    setReturnReason]    = useState('');
  const [showReportModal, setShowReportModal] = useState(false);

  // Auto-advance stages
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentStage(p => {
        if (p >= STAGES.length - 2) { clearInterval(timer); return p; }
        return p + 1;
      });
    }, ADVANCE_INTERVAL[flowType]);
    return () => clearInterval(timer);

  }, [flowType, STAGES.length]);

  const canCancel  = currentStage <= Math.min(2, STAGES.length - 4);
  const isDone     = currentStage >= STAGES.length - 1;
  const doneLabel  = meta.doneLabel;

  const handleReorder = async () => {
    if (!orderId) { toast.error('No order to reorder'); return; }
    try {
      const res = await api.getOrder(orderId);
      const ord = res?.order || res;
      if (ord?.items) {
        ord.items.forEach((item: Unmodelled) => addItem(item, ord.facilityId || ord.storeId || storeId));
        toast.success('Previous order items added to cart');
        navigate('/cart');
      } else {
        toast.error('Could not load order items');
      }
    } catch {
      toast.error('Failed to load order');
    }
  };

  const handleCancelOrder = async () => {
    setShowCancelConfirm(false);
    try {
      if (orderId) await api.updatePharmacyOrder(orderId, { status: 'Cancelled' });
      toast.success('Order cancelled. Refund will be processed within 3-5 business days.');
    } catch (e: any) { console.error('Cancel order failed:', e); toast.error('Failed to cancel order. Please try again.'); }
  };

  const handleSubmitReview = async () => {
    if (reviewRating === 0) { toast.error('Please select a rating'); return; }
    try {
      await api.createReview({ rating: reviewRating, comment: reviewComment || '', targetId: storeId, targetType: 'pharmacy' });
      toast.success(`Thank you! Your ${reviewRating}-star review has been submitted.`);
    } catch (e: any) { console.error('Submit review failed:', e); toast.error('Failed to submit review. Please try again.'); }
    setShowReviewModal(false);
    setReviewRating(0);
    setReviewComment('');
  };

  const handleSubmitReturn = async () => {
    if (!returnReason) { toast.error('Please select a return reason'); return; }
    try {
      await api.createPharmacyReturn({ orderId, reason: returnReason, status: 'Requested' });
      toast.success(`Return request submitted. We'll contact you within 24 hours.`);
    } catch (e: any) { console.error('Return request failed:', e); toast.error('Failed to submit return request. Please try again.'); }
    setShowReturnModal(false);
    setReturnReason('');
  };

  // ─── Stage icon resolution ──────────────────────────────────────────────────
  const resolveIcon = (iconKey: Unmodelled) => ICON_MAP[iconKey] || Package;

  // ─── Progress percentage ───────────────────────────────────────────────────
  const progressPct = STAGES.length > 1
    ? Math.round((currentStage / (STAGES.length - 1)) * 100)
    : 100;

  return (
    <div className={cn('min-h-screen bg-gradient-to-b pb-12', isDone ? meta.doneGradient : 'from-background to-background')}>
      <div className="max-w-3xl mx-auto px-4 sm:px-6 py-8">
        <button
          onClick={() => navigate(-1)}
          className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground mb-6 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" /> Back
        </button>

        {/* Header */}
        <div className="mb-8">
          <h1 className="font-heading text-3xl font-bold text-foreground">{meta.title}</h1>
          <div className="flex items-center gap-3 mt-2 flex-wrap">
            <Badge className="text-sm font-mono bg-primary/10 text-primary border-primary/20">
              <FileText className="w-3.5 h-3.5 mr-1.5" />
              {orderId || `ORD${crypto.randomUUID()}`}
            </Badge>
            <Badge className={cn(
              'text-xs',
              isDone ? 'bg-emerald-500/10 text-emerald-600 border-emerald-200' : 'bg-blue-500/10 text-blue-600 border-blue-200'
            )}>
              {isDone ? doneLabel : `${progressPct}% complete`}
            </Badge>
          </div>
        </div>

        {/* Progress bar */}
        <div className="mb-6">
          <div className="h-1.5 bg-muted rounded-full overflow-hidden">
            <div
              className="h-full bg-primary rounded-full transition-all duration-700"
              style={{ width: `${progressPct}%` }}
            />
          </div>
        </div>

        {/* Entity / provider card */}
        <div className="bg-card rounded-2xl border border-border/60 p-5 mb-6 flex items-center gap-4">
          <div className="w-12 h-12 rounded-xl bg-muted/50 overflow-hidden border border-border/40 shrink-0">
            <img src={store.photo} alt="" className="w-full h-full object-cover" />
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-1.5">
              <h3 className="font-heading font-semibold text-foreground">{store.name}</h3>
              {store.verified && <BadgeCheck className="w-4 h-4 text-primary shrink-0" />}
            </div>
