    setLabReport({
      ...labReport,
      results: [...labReport.results, { testParameter: '', value: '', unit: '', referenceRange: '', flag: 'Normal' }]
    });
  };

  const removeLabResult = (index: number) => {
    if (labReport.results.length <= 1) return;
    setLabReport({
      ...labReport,
      results: labReport.results.filter((_, i) => i !== index)
    });
  };

  const buildReportPayload = (type: Unmodelled) => {
    if (type === 'prescription') {
      return {
        patient: {
          name: prescription.patientName,
          age: prescription.patientAge,
          gender: prescription.patientGender,
          phone: prescription.patientPhone,
          email: prescription.patientEmail,
          address: prescription.patientAddress
        },
        doctorName: prescription.doctorName || user?.name,
        doctorSpecialization: prescription.doctorSpecialization,
        chiefComplaints: prescription.chiefComplaints,
        diagnosis: prescription.diagnosis,
        advice: prescription.advice,
        followUp: prescription.followUp,
        medications: prescription.medications
      };
    }
    if (type === 'lab') {
      const formattedResults = labReport.tests?.length
        ? labReport.tests.map(t => ({
            testParameter: t.name,
            value: t.result,
            unit: t.unit,
            referenceRange: t.referenceRange,
            flag: 'Normal'
          }))
        : labReport.results;

      return {
        patient: {
          name: labReport.patientName,
          age: labReport.patientAge,
          gender: labReport.patientGender,
          phone: labReport.patientPhone,
          email: labReport.patientEmail
        },
        doctorName: labReport.doctorName || user?.name,
        doctorSpecialization: labReport.doctorSpecialization,
        reportId: labReport.reportId,
        testDate: labReport.testDate,
        reportDate: labReport.reportDate,
        testName: labReport.testName,
        sampleType: labReport.sampleType,
        results: formattedResults,
        tests: labReport.tests,
        notes: labReport.notes,
        impression: labReport.impression
      };
    }
    return {
      patient: {
        name: discharge.patientName,
        age: discharge.patientAge,
        gender: discharge.patientGender,
        phone: discharge.patientPhone,
        email: discharge.patientEmail,
        address: discharge.patientAddress
      },
      doctorName: discharge.doctorName || user?.name,
      doctorSpecialization: discharge.doctorSpecialization,
      admissionId: discharge.admissionId,
      admissionDate: discharge.admissionDate,
      dischargeDate: discharge.dischargeDate,
      admissionDiagnosis: discharge.admissionDiagnosis || discharge.diagnosis,
      dischargeDiagnosis: discharge.diagnosis,
      treatmentSummary: discharge.treatment,
      conditionAtDischarge: discharge.conditionAtDischarge,
      hospitalCourse: discharge.hospitalCourse,
      dischargeMedications: discharge.medications,
      dietInstructions: discharge.dietInstructions,
      activityRestrictions: discharge.activityRestrictions,
      followUpInstructions: discharge.followUpInstructions || discharge.dischargeAdvice
    };
  };

  const generatePDF = async (type: Unmodelled) => {
    setLoading(true);
    setStatusMessage('');
    setErrorMessage('');
    try {
      const endpoint = type === 'prescription' ? '/reports/generate-prescription'
        : type === 'lab' ? '/reports/generate-lab-report'
        : '/reports/generate-discharge-summary';
      const payload = buildReportPayload(type);

      const res = await apiClient.post(endpoint, payload, { responseType: 'blob' });
      const blob = new Blob([res.data], { type: 'application/pdf' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${type}-${Date.now()}.pdf`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      a.remove();
      setStatusMessage('PDF downloaded successfully.');
    } catch (error: any) {
      console.error('Error generating PDF:', error);
      setErrorMessage(error.message || 'Error generating PDF');
    }
    setLoading(false);
  };

  const sendViaEmail = async (type: Unmodelled) => {
    setLoading(true);
    setStatusMessage('');
    setErrorMessage('');
    try {
      const reportPayload = buildReportPayload(type);
      if (!reportPayload.patient?.email) {
        throw new Error('Patient email is required before sending.');
      }

      const endpoint = type === 'prescription' ? '/reports/email/prescription'
        : type === 'lab' ? '/reports/email/lab-result'
        : '/reports/email/discharge-summary';
      const payload = type === 'prescription' ? {
        patient: reportPayload.patient,
        prescription: reportPayload
      } : type === 'lab' ? {
        patient: reportPayload.patient,
        report: reportPayload
      } : {
        patient: reportPayload.patient,
        summary: reportPayload
      };

      const data = await api.dispatch(null, endpoint, { method: 'POST', body: JSON.stringify(payload) });
      if (data?.success === false) {
        throw new Error(data.message || data.error || 'Email send failed');
      }

      setStatusMessage('Report emailed successfully.');
    } catch (error: any) {
      console.error('Error sending email:', error);
      setErrorMessage(error.message || 'Error sending email');
    }
    setLoading(false);
  };

  if (user?.role === 'patient') {
    return (
      <div className="space-y-6">
        <div>
          <h1 className="text-3xl font-bold">Reports</h1>
          <p className="text-muted-foreground">View and download your medical reports</p>
        </div>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><FileText className="w-5 h-5" /> Medical Reports</CardTitle>
            <CardDescription>Your prescriptions, lab reports, and discharge summaries</CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">Contact your doctor to generate new reports. Existing reports can be found in your medical records.</p>
          </CardContent>
        </Card>
      </div>
    );
