    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { CreditCard, Wallet, Banknote, Building, CheckCircle2, XCircle, Loader2, ArrowLeft, Shield, Lock, Smartphone, Copy, Check, FileDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import { api, downloadPaymentInvoice, downloadBillPdf } from '@/lib/api';
import BillCheckout from '@/components/BillCheckout';
import { userFacingError } from '@/lib/errorCopy';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const UPI_APPS = ['Google Pay', 'PhonePe', 'Paytm', 'BHIM', 'CRED'];

const PAYMENT_METHODS: Unmodelled = {
  upi: { label:'UPI', icon: Smartphone },
  card: { label:'Debit / Credit Card', icon: CreditCard },
  netbanking: { label:'Net Banking', icon: Building },
  wallet: { label:'FindMedi Wallet', icon: Wallet },
};

export default function PaymentGateway() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  const requestedTotal = parseInt(searchParams.get('total') || '0');
  const method = searchParams.get('method') || 'upi';
  const orderIds = searchParams.get('orderIds')?.split(',') || [];
  const storeIds = searchParams.get('stores')?.split(',') || [];

  const [step, setStep] = useState('form');
  const [cardNumber, setCardNumber] = useState('');
  const [cardExpiry, setCardExpiry] = useState('');
  const [cardCvv, setCardCvv] = useState('');
  const [selectedBank, setSelectedBank] = useState('');
  const [upiId, setUpiId] = useState('');
  const [copied, setCopied] = useState(false);
  const [saveCard, setSaveCard] = useState(false);
  const [agreed, setAgreed] = useState(false);
  const [_paying, setPaying] = useState(false);
  const [storeNames, setStoreNames] = useState<ApiRow>({});
  const [order, setOrder] = useState<Unmodelled>(null);
  const [orderLoading, setOrderLoading] = useState(true);
  const [payResult, setPayResult] = useState<Unmodelled>(null);
  const total = Number(order?.total ?? requestedTotal);
  useEffect(() => {
    if (storeIds.length === 0) return;
    const load = async () => {
      try {
        const res = await api.getFacilities({ type: 'pharmacy' });
        const list = Array.isArray(res) ? res : (res?.facilities || res?.data || []);
        const map: Unmodelled = {};
        list.forEach((f: Unmodelled) => { map[f._id] = f.name; map[f.id] = f.name; });
        storeIds.forEach(sid => {
          if (sid) {
            const found = list.find((f: Unmodelled) => f._id === sid || f.id === sid);
            if (found) map[sid] = found.name;
          }
        });
        setStoreNames(map);
      } catch { /* empty */ }
    };
    load();
  }, [storeIds]);

  useEffect(() => {
    if (!orderIds[0]) { setOrderLoading(false); return; }
    const load = async () => {
      try {
        const res = await api.get(`/api/pharmacy/orders?orderId=${orderIds[0]}`);
        const data = typeof res === 'object' && res !== null ? res : { orders: [] };
        const ordersArr = Array.isArray(data) ? data : (data.orders || []);
        setOrder(ordersArr[0] || null);
      } catch { /* empty */ }
      setOrderLoading(false);
    };
    load();
  }, [orderIds[0]]);

  const getStoreName = (sid: Unmodelled) => storeNames[sid] || sid;

  const methodInfo = PAYMENT_METHODS[method] || PAYMENT_METHODS.upi;
  const MethodIcon = methodInfo.icon;
  const upiQrUpiId = 'findmedi@upi';

  const handlePay = async () => {
    if (!order || !orderIds[0]) {
      setStep('failed');
      return;
    }
    setPaying(true);
    setStep('processing');
    try {
      const res = await api.payTransaction({
        serviceType: 'medicine',
        referenceId: orderIds[0],
        // Billing validates the pre-coupon server price, then reapplies the
        // persisted coupon from its own canonical record.
        amount: Number(order?.payableBeforeDiscount || order?.total || total),
        couponCode: order?.couponCode || undefined,
        method: method === 'wallet' ? 'card' : method,
        description: `Medicine Order - ${storeIds.map(sid => getStoreName(sid)).join(', ')}`,
        provider: storeNames[storeIds[0]] || storeIds[0],
        lineItems: (order?.items || []).map((i: Unmodelled) => ({ name: i.medicineName, price: i.price, qty: i.qty })),
      }, { headers: { 'Idempotency-Key': globalThis.crypto?.randomUUID?.() || `${orderIds[0]}-${Date.now()}` } });
      setPayResult(res);
      setStep('success');
    } catch (e: any) {
      const msg = userFacingError(e, { fallback: '' });
      const status = e.response?.status;
      if (status === 200 && msg.includes('already be completed')) {
        setStep('success');
        return;
      }
      setStep('failed');
    }
    setPaying(false);
  };

  const handleProceed = () => {
    const params = new URLSearchParams(searchParams.toString());
    params.delete('total');
    params.delete('method');
    navigate(`/order-confirmation?${params}`);
  };

  const handleRetry = () => setStep('form');

  const formatCardNumber = (v: Unmodelled) => v.replace(/\D/g, '').replace(/(.{4})/g, '$1 ').trim().slice(0, 19);

  return (
    <div className="min-h-screen bg-gradient-to-b from-primary/5 to-background dark:from-primary/10">
      <div className="max-w-lg mx-auto px-4 sm:px-6 py-8">
        <button onClick={() => navigate(-1)} className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground mb-6 transition-colors">
          <ArrowLeft className="w-4 h-4" /> Back
