  );
}

import { useState, type FormEvent } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Users, ArrowRight, CheckCircle, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';

/**
 * 2.md 9 — staff invitation redemption (`/#/provider-staff-setup?code=...`).
 *
 * The CODE is the entire credential: single-use, 48h, opaque. Email and role
 * live on the invite row server-side, so this page never asks which listing or
 * which role — it only collects the password for the account being created
 * (or joins the invite to an existing account when the mailbox is already
 * registered).
 */

interface SetupResult {
  message?: string;
  accountExists?: boolean;
  role?: string;
  requiresTwoFactor?: boolean;
}

export default function ProviderStaffSetup() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const code = searchParams.get('code') || '';

  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState<SetupResult | null>(null);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');

    if (!code) {
      setError('Invalid or missing invitation link. Ask the provider owner to send a new one.');
      return;
    }
    if (password.length < 12) {
      setError('Password must be at least 12 characters');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);
    try {
      const res = (await api.post('/auth/provider-staff-setup', {
        code,
        password,
        ...(name.trim() ? { name: name.trim() } : {}),
      })) as unknown as SetupResult;
      setDone(res);
    } catch (err: any) {
      setError(err instanceof Error ? err.message : 'This invitation link is invalid, already used, or has expired.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-8">
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-16 h-16 rounded-2xl bg-primary flex items-center justify-center mx-auto mb-4 shadow-lg shadow-primary/20">
            <Users className="w-8 h-8 text-primary-foreground" />
          </div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Join the Listing Team</h1>
          <p className="text-muted-foreground mt-1">Set your password to access this provider's console</p>
        </div>

        <div className="bg-card rounded-2xl border border-border p-6">
          {done ? (
            <div className="text-center py-4">
              <CheckCircle className="w-16 h-16 text-success mx-auto mb-4" />
              <h2 className="font-heading text-xl font-bold text-foreground mb-2">
                {done.accountExists ? 'You are on the team' : 'Account created'}
              </h2>
              <p className="text-muted-foreground text-sm mb-2">{done.message}</p>
              {done.role && (
                <p className="text-xs text-muted-foreground mb-1">
                  Role: <span className="font-medium text-foreground">{done.role}</span>
                </p>
              )}
              {done.requiresTwoFactor && (
                <p className="text-xs text-amber-600 inline-flex items-center gap-1 justify-center mb-4">
                  <AlertCircle className="w-3.5 h-3.5" /> This role requires two-factor authentication at login.
                </p>
              )}
              <Button className="w-full gap-2 mt-2" size="lg" onClick={() => navigate('/login')}>
                Go to Login <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Your name</label>
                <Input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Name shown to your team (optional)"
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Create Password</label>
                <Input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="At least 12 characters"
                  required
                />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Confirm Password</label>
                <Input
                  type="password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="Confirm your password"
                  required
                />
              </div>
              {!code && (
                <p className="text-xs text-destructive bg-destructive/10 px-3 py-2 rounded-lg">
                  This page needs the invitation link you were emailed. Ask the provider owner for a new invitation.
                </p>
              )}
              {error && <p className="text-sm text-destructive bg-destructive/10 px-3 py-2 rounded-lg">{error}</p>}
              <Button type="submit" className="w-full gap-2" size="lg" disabled={loading}>
                {loading ? (
                  <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                ) : null}
                {loading ? 'Setting up...' : 'Set Password & Join'}
                {!loading && <ArrowRight className="w-4 h-4" />}
              </Button>
            </form>
          )}
        </div>
      </motion.div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { api } from '@/lib/api';

/**
 * File 09 §9.4 — queue display screen (TV mode). Public, no login, no PHI:
 * token numbers + status only (`GET /tokens/display`). Auto-refresh 10s.
 */
export default function QueueDisplay() {
  const [params] = useSearchParams();
  const department = params.get('department') || '';
  const doctorId = params.get('doctorId') || '';
  const [tokens, setTokens] = useState<any[]>([]);
  const [muted, setMuted] = useState(false);
  const [stale, setStale] = useState(false);
  const lastSpoken = useRef('');

  const speak = (text: string) => {
    if (muted || !('speechSynthesis' in window)) return;
    try {
      window.speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = 'en-IN';
      u.rate = 0.95;
      window.speechSynthesis.speak(u);
      setTimeout(() => { if (!muted) window.speechSynthesis.speak(u); }, 5000);
    } catch { /* voice unavailable — chime-only fallback */ }
  };

  useEffect(() => {
    let cancelled = false;
    let fails = 0;
    const load = async () => {
      try {
        const res: any = await (api as any).getQueueDisplay({
          ...(department ? { department } : {}),
          ...(doctorId ? { doctorId } : {}),
        });
        if (cancelled) return;
        fails = 0;
        setStale(false);
        const next = res?.tokens || [];
        const now = next.filter((t: any) => t.status === 'Called' || t.status === 'In Consultation');
        const key = now.map((t: any) => t.tokenNumber).join(',');
        if (key && key !== lastSpoken.current) {
          lastSpoken.current = key;
          const first = now[0];
          speak(`Token ${first.tokenNumber}, please proceed to ${first.roomNumber ? `Room ${first.roomNumber}` : (department || 'the counter')}`);
        }
        setTokens(next);
      } catch {
        fails += 1;
        if (fails >= 3) setStale(true);
      }
    };
    load();
    const t = setInterval(load, 10000);
    return () => { cancelled = true; clearInterval(t); };
  }, [department, doctorId, muted]);

  const nowServing = tokens.filter((t) => t.status === 'Called' || t.status === 'In Consultation');

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6" data-motion-ignore>
      <div className="max-w-5xl mx-auto">
        <div className="flex items-center gap-3">
          <h1 className="text-3xl font-bold mr-auto">Now Serving{department ? ` — ${department}` : ''}</h1>
          {stale && <span className="text-amber-400 text-sm">Reconnecting…</span>}
          <button onClick={() => setMuted(!muted)} className="text-sm text-slate-300 underline">{muted ? 'Unmute' : 'Mute'}</button>
        </div>
        <div className="grid sm:grid-cols-3 gap-4 mt-6">
          {nowServing.slice(0, 3).map((t) => (
            <div key={t._id || t.tokenNumber} className="rounded-2xl bg-emerald-600 p-6 text-center">
              <p className="text-5xl font-black tracking-tight">{t.tokenNumber}</p>
              <p className="mt-1 text-sm opacity-90">{t.status}{t.roomNumber ? ` · Room ${t.roomNumber}` : ''}</p>
            </div>
          ))}
          {nowServing.length === 0 && (
            <p className="text-slate-400">No token in service right now.</p>
          )}
        </div>
        <h2 className="text-xl font-bold mt-8 mb-3">Waiting ({tokens.length})</h2>
        <div className="flex flex-wrap gap-2">
          {tokens.filter((t) => t.status === 'Waiting').slice(0, 20).map((t) => (
            <span key={t._id || t.tokenNumber} className="rounded-lg bg-slate-800 px-4 py-2 text-lg font-bold">
              {t.tokenNumber}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

