function Notice({ notice }: { notice: NoticeState | null }) {
  if (!notice) return null;
  const Icon = notice.type === 'error' ? AlertCircle : CheckCircle;
  const cls = notice.type === 'error'
    ? 'border-destructive/30 bg-destructive/10 text-destructive'
    : 'border-success/30 bg-success/10 text-success';

  return (
    <div className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium ${cls}`}>
      <Icon className="w-4 h-4" />
      {notice.text}
    </div>
  );
}

function TwoFactorSection() {
  const { user } = useAuth();
  const [step, setStep] = useState('idle');
  const [secret, setSecret] = useState('');
  const [otpAuthUrl, setOtpAuthUrl] = useState('');
  const [code, setCode] = useState('');
  const [backupCodes, setBackupCodes] = useState<ApiRow[]>([]);
  const [disablePassword, setDisablePassword] = useState('');
  const [copied, setCopied] = useState(false);

  const { data: status, refetch: refetchStatus } = useQuery({
    queryKey: ['2fa-status'],
    queryFn: () => api.get2FAStatus(),
    enabled: !!user,
  });

  const isEnabled = status?.enabled || false;

  const setupMut = useMutation({
    mutationFn: () => api.setup2FA(),
    onSuccess: (data) => {
      setSecret(data.secret);
      setOtpAuthUrl(data.otpAuthUrl);
      setStep('verify');
    },
    onError: (err) => toast.error(err.message || 'Failed to setup 2FA'),
  });

  const verifyMut = useMutation({
    mutationFn: () => api.verify2FA({ token: code }),
    onSuccess: (data) => {
      setBackupCodes(data.backupCodes || []);
      setStep('backup-codes');
      refetchStatus();
    },
    onError: (err) => toast.error(err.message || 'Invalid code'),
  });

  const disableMut = useMutation({
    mutationFn: () => api.disable2FA({ password: disablePassword }),
    onSuccess: () => {
      setDisablePassword('');
      setStep('idle');
      refetchStatus();
      toast.success('2FA disabled successfully');
    },
    onError: (err) => toast.error(err.message || 'Failed to disable 2FA'),
  });

  const handleCopyCodes = useCallback(() => {
    navigator.clipboard?.writeText(backupCodes.join('\n'));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }, [backupCodes]);

  if (!isEnabled && step === 'idle') {
    return (
      <div className="bg-card rounded-xl border p-4">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-foreground">Two-Factor Authentication</p>
            <p className="text-xs text-muted-foreground mt-0.5">Add an extra layer of security to your account</p>
          </div>
          <Button size="sm" onClick={() => setupMut.mutate()} disabled={setupMut.isPending}>
            <Smartphone className="w-3.5 h-3.5 mr-1.5" />
            {setupMut.isPending ? 'Setting up...' : 'Enable 2FA'}
          </Button>
        </div>
      </div>
    );
  }

  if (step === 'verify') {
    return (
      <div className="bg-card rounded-xl border p-4 space-y-3">
        <p className="text-sm font-medium text-foreground">Scan QR Code</p>
        <p className="text-xs text-muted-foreground">Scan this code with your authenticator app (Google Authenticator, Authy, etc.)</p>
        {otpAuthUrl && (
          <div className="flex justify-center py-2">
            <QrCode className="w-32 h-32 text-primary" />
          </div>
        )}
        <div className="flex items-center gap-2 bg-muted/50 rounded-lg px-3 py-2">
          <code className="text-xs flex-1 break-all font-mono">{secret}</code>
          <Button variant="ghost" size="sm" onClick={() => { navigator.clipboard?.writeText(secret); toast.success('Secret copied'); }}>
            <Copy className="w-3.5 h-3.5" />
          </Button>
        </div>
        <div className="flex gap-2">
          <Input value={code} onChange={e => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))} placeholder="Enter 6-digit code" className="text-center text-lg tracking-widest" maxLength={6} />
          <Button onClick={() => verifyMut.mutate()} disabled={code.length !== 6 || verifyMut.isPending}>
            {verifyMut.isPending ? 'Verifying...' : 'Verify'}
          </Button>
        </div>
        <Button variant="ghost" size="sm" onClick={() => { setStep('idle'); setSecret(''); setOtpAuthUrl(''); }}>
          Cancel
        </Button>
      </div>
    );
  }

  if (step === 'backup-codes') {
    return (
      <div className="bg-card rounded-xl border p-4 space-y-3">
        <p className="text-sm font-medium text-foreground">Backup Codes</p>
        <p className="text-xs text-muted-foreground">Save these one-time backup codes in a secure place. You won't be able to see them again.</p>
        <div className="bg-muted/50 rounded-lg p-3 font-mono text-sm space-y-1">
          {backupCodes.map((code: Unmodelled, i) => (
            <div key={i} className="flex items-center gap-2">
              <KeyRound className="w-3 h-3 text-muted-foreground" />
              <span>{code}</span>
            </div>
          ))}
        </div>
        <div className="flex gap-2">
          <Button size="sm" variant="outline" onClick={handleCopyCodes} className="gap-1">
            {copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
            {copied ? 'Copied!' : 'Copy Codes'}
          </Button>
          <Button size="sm" onClick={() => { setStep('idle'); setBackupCodes([]); toast.success('2FA enabled successfully'); }}>
            Done
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-card rounded-xl border p-4">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-medium text-foreground">Two-Factor Authentication</p>
          <p className="text-xs text-muted-foreground mt-0.5">Your account is protected with 2FA</p>
        </div>
        <Dialog>
          <DialogTrigger asChild>
            <Button variant="outline" size="sm" className="gap-1 text-destructive">
              Disable
            </Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Disable Two-Factor Authentication</DialogTitle>
              <DialogDescription>Enter your password to disable 2FA.</DialogDescription>
            </DialogHeader>
            <div className="space-y-3 py-2">
              <Input type="password" value={disablePassword} onChange={e => setDisablePassword(e.target.value)} placeholder="Enter your password" />
              <Button className="w-full" variant="destructive" onClick={() => disableMut.mutate()} disabled={!disablePassword || disableMut.isPending}>
                {disableMut.isPending ? 'Disabling...' : 'Disable 2FA'}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  );
}

export default function Settings() {
  const { user, updateUser } = useAuth();
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [tab, setTab] = useState('profile');
  const [profile, setProfile] = useState(() => buildProfile(user));
  const updateSetting = useUpdateSetting();
  const loadUserSettings = useLoadUserSettings();
  const reduxSettings = useSettings();
  const authSettings = user?.settings || {};
  const settings = reduxSettings;
  const [password, setPassword] = useState({ currentPassword: '', newPassword: '', confirmPassword: '' });
  const [notice, setNotice] = useState<NoticeState | null>(null);
  const language = settings.language || 'en';
  const tr = (key: string) => t(key, language);

  useEffect(() => {
    setProfile(buildProfile(user));
  }, [user]);

  // Sync auth user settings into Redux when user changes
  useEffect(() => {
    if (authSettings && Object.keys(authSettings).length > 0) {
      loadUserSettings(authSettings);
      applyUserSettings(authSettings);
    }
  }, [user, loadUserSettings, authSettings]);

  useEffect(() => {
    applyUserSettings(settings);
  }, [settings]);

  const initials = useMemo(() => (user?.name || 'U').split(' ').filter(Boolean).map(part => part[0]).join('').slice(0, 2).toUpperCase(), [user?.name]);

  const saveMut = useMutation({
    mutationFn: (payload: any) => api.updateProfile(payload),
    onSuccess: (data) => {
      updateUser(data);
      if (data?.settings) {
        loadUserSettings(data.settings);
        applyUserSettings(data.settings);
      }
      setNotice({ type: 'success', text: t('settings.saved', data.settings?.language || language) });
    },
    onError: (error) => setNotice({ type: 'error', text: error.message || tr('settings.saveError') }),
  });

  const passwordMut = useMutation({
    mutationFn: (payload: { currentPassword: string; newPassword: string }) => api.changePassword(payload),
    onSuccess: () => {
      setPassword({ currentPassword: '', newPassword: '', confirmPassword: '' });
      setNotice({ type: 'success', text: tr('settings.passwordSaved') });
    },
    onError: (error) => setNotice({ type: 'error', text: error.message || tr('settings.passwordError') }),
  });

  const avatarMut = useMutation({
    mutationFn: (file: File) => api.uploadAvatar(file),
    onSuccess: (data) => {
      const avatar = data?.user?.avatar || data?.avatar || '';
      if (data?.user) updateUser(data.user);
      else updateUser({ avatar });
      setProfile((current) => ({ ...current, avatar }));
      setNotice({ type: 'success', text: tr('settings.photoUploadSuccess') });
    },
    onError: (error) => setNotice({ type: 'error', text: error.message || tr('settings.photoUploadError') }),
  });

  const updateProfile = (key: string, value: any) => setProfile((current) => ({ ...current, [key]: value }));
  const saveSetting = (key: string, value: any) => updateSetting({ key, value });

  const handleAvatarSelect = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;

    setNotice(null);
    if (!['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type)) {
      setNotice({ type: 'error', text: tr('settings.photoTypeError') });
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setNotice({ type: 'error', text: tr('settings.photoSizeError') });
      return;
    }

    avatarMut.mutate(file);
  };

  const saveAccount = () => {
    setNotice(null);
    saveMut.mutate({ ...profile, settings });
  };

  const savePassword = () => {
    setNotice(null);
    if (password.newPassword.length < 12) {
      setNotice({ type: 'error', text: tr('settings.passwordLength') });
      return;
    }
    if (password.newPassword !== password.confirmPassword) {
      setNotice({ type: 'error', text: tr('settings.passwordMismatch') });
      return;
    }
    passwordMut.mutate({
      currentPassword: password.currentPassword,
      newPassword: password.newPassword,
    });
  };

  const downloadMyData = () => {
    const blob = new Blob([JSON.stringify({ account: user, profile, settings }, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'findmedi-account-data.json';
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  return (
    <div>
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">{tr('settings.title')}</h1>
          <p className="page-subtitle">{tr('settings.subtitle')}</p>
        </div>
      </div>

