        <div className="lg:w-64 flex-shrink-0">
          <div className="bg-card rounded-xl border shadow-sm p-2 flex lg:flex-col gap-1 overflow-x-auto">
            {tabs.map(({ key, labelKey, icon: Icon }) => (
              <button
                key={key}
