import { useState } from 'react';
import { useParams } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import SignaturePad from '@/components/forms/SignaturePad';

/**
 * File 14 §14.5 — document signing: L1 drawn capture (patient/relative/
 * witness, multi-party order enforced server-side) with stepper.
 */
const STEPS = ['Patient / Relative', 'Witness', 'Doctor (step-up)'];

export default function SignDocument() {
  const { kind = 'consent', id = '' } = useParams();
  const [step, setStep] = useState(0);
  const [name, setName] = useState('');
  const [relation, setRelation] = useState('');
  const [intent, setIntent] = useState('');
  const [done, setDone] = useState<string[]>([]);

  const signL1 = async (image: string) => {
    void image;
    try {
      const role = step === 0 ? 'patient' : 'witness';
      await (api as any).signL1({
        docKind: kind, docId: id, signerRole: role,
        signerName: name, relation: step === 0 ? relation : '', language: 'en',
      });
      toast.success(`${role} signed`);
      setDone((d) => [...d, role]);
      setStep((s) => Math.min(s + 1, 2));
      setName(''); setRelation('');
    } catch (err: any) { toast.error(err?.message || 'Sign failed'); }
  };

  const signL2 = async () => {
    try {
      await (api as any).signL2({ docKind: kind, docId: id, intent, language: 'en' });
      toast.success('Doctor e-signed (step-up verified)');
      setDone((d) => [...d, 'doctor']);
    } catch (err: any) { toast.error(err?.message || 'Step-up required'); }
  };

  return (
    <div className="max-w-xl mx-auto space-y-4">
      <h1 className="text-2xl font-heading font-bold">Sign document</h1>
      <div className="h-1.5 rounded-full bg-muted overflow-hidden">
        <div className="h-full bg-primary transition-all" style={{ width: `${((done.length) / 3) * 100}%` }} />
      </div>
      <p className="text-sm text-muted-foreground">Step {step + 1} of 3: {STEPS[step]}</p>

      {step < 2 && (
        <Card>
          <CardHeader><CardTitle className="text-base">{STEPS[step]}</CardTitle></CardHeader>
          <CardContent className="space-y-3">
            <Input placeholder="Full name" value={name} onChange={(e) => setName(e.target.value)} />
            {step === 0 && <Input placeholder="Relation (self/spouse/son/...)" value={relation} onChange={(e) => setRelation(e.target.value)} />}
            <SignaturePad onDone={signL1} />
          </CardContent>
        </Card>
      )}

      {step === 2 && (
        <Card>
          <CardHeader><CardTitle className="text-base">Doctor e-sign (step-up)</CardTitle></CardHeader>
          <CardContent className="space-y-3">
            <Input placeholder='Typed intent, e.g. "I certify consent was informed"' value={intent} onChange={(e) => setIntent(e.target.value)} />
            <Button onClick={signL2} disabled={!intent}>E-sign with step-up</Button>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, Navigate, Link, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Activity, ArrowRight, Shield, Eye, EyeOff, CheckCircle2, User, Phone, Calendar, Sparkles, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { setAuthTokens } from '@/lib/axios';
import type { Unmodelled } from '@/lib/apiTypes';

export default function Signup() {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, completeGoogleLogin } = useAuth();

  const [isGoogle, setIsGoogle] = useState(false);
  const [googleAvatar, setGoogleAvatar] = useState('');
  const [role, setRole] = useState('patient');

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [phone, setPhone] = useState('');
  const [gender, setGender] = useState('Male');
  const [dateOfBirth, setDateOfBirth] = useState('');
  const [bloodGroup, setBloodGroup] = useState('');
  const [emergencyName, setEmergencyName] = useState('');
  const [emergencyPhone, setEmergencyPhone] = useState('');
  const [referralCode, setReferralCode] = useState('');

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  // AUTH-B-01: verified Google id_token kept across the two-step signup.
  const [googleIdToken, setGoogleIdToken] = useState('');

  const passwordStrength = (() => {
    if (!password) return { score: 0, label: '', color: 'bg-border' };
    let score = 0;
    if (password.length >= 10) score += 1;
    if (password.length >= 12) score += 1;
    if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score += 1;
    if (/\d/.test(password)) score += 1;
    if (/[^a-zA-Z0-9]/.test(password)) score += 1;
    const labels = ['', 'Weak', 'Fair', 'Good', 'Strong', 'Very Strong'];
    const colors = ['', 'bg-red-500', 'bg-orange-500', 'bg-yellow-500', 'bg-lime-500', 'bg-green-500'];
    return { score, label: labels[score], color: colors[score] };
  })();

  // Load Google data from location state or localStorage
  useEffect(() => {
    const stateData = location.state;
    const stored = localStorage.getItem('google_signup');
    let data = stateData;

    if (!data && stored) {
      try {
        data = JSON.parse(stored);
      } catch { /* empty */ }
    }

    if (data && data.isGoogle) {
      setIsGoogle(true);
      if (data.name) setName(data.name);
      if (data.email) setEmail(data.email);
      if (data.avatar) setGoogleAvatar(data.avatar);
      if (data.role) setRole(data.role);
      if (data.googleIdToken) setGoogleIdToken(data.googleIdToken);
    }

    // Referral code auto-detect (?ref=CODE) — HashRouter puts query in location.hash
    const hash = window.location.hash || '';
    const qIndex = hash.indexOf('?');
    const qs = qIndex >= 0 ? hash.slice(qIndex + 1) : window.location.search.slice(1);
    const refFromUrl = new URLSearchParams(qs).get('ref') || new URLSearchParams(qs).get('referralCode');
    if (refFromUrl) {
      setReferralCode(refFromUrl.toUpperCase());
    }
  }, [location.state]);

  if (user) return <Navigate to="/dashboard" replace />;

  const GOOGLE_CLIENT_ID = import.meta.env.VITE_GOOGLE_CLIENT_ID;

  // Handle Google Account selection
  const handleGoogleCredential = async (idToken: Unmodelled, accessToken?: Unmodelled) => {
    setError('');
    setGoogleLoading(true);
    try {
      const data = await api.googleAuth({ idToken, accessToken, role: 'patient' });
      if (data.exists && data.token && data.user) {
        setAuthTokens(data.token);
        completeGoogleLogin(data.user);
        // AUTH-F-06: temp-password accounts rotate first.
        navigate(data.user.mustResetPassword ? '/set-password' : '/dashboard', { replace: true });
        return;
      }

      // New Google User -> Set Google mode and pre-fill details for Step 2
      const g = data.googleUser || {};
      setIsGoogle(true);
      setName(g.name || '');
      setEmail(g.email || '');
      setGoogleAvatar(g.picture || '');
      setGoogleIdToken(idToken || '');
      setRole('patient');

      const signupData = {
        role: 'patient',
        name: g.name || '',
        email: g.email || '',
        avatar: g.picture || '',
        isGoogle: true,
        // AUTH-B-01: step 2 (google-register) now REQUIRES a verified Google
        // id_token — without it the server refuses to look up / create the
        // account. Keep it alive for the duration of the two-step signup.
        googleIdToken: idToken || '',
      };
      localStorage.setItem('google_signup', JSON.stringify(signupData));
    } catch (err: any) {
      setError(err.message || 'Google sign-in failed');
    } finally {
      setGoogleLoading(false);
    }
  };

  const handleGoogleLogin = () => {
    if (!GOOGLE_CLIENT_ID) {
      setError('Google Sign-In is not configured. Contact the administrator.');
      return;
    }

    if (window.google?.accounts?.oauth2) {
      try {
        const tokenClient = window.google.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: 'email profile openid',
          callback: (tokenResponse: Unmodelled) => {
            if (tokenResponse?.access_token) {
              // AUTH-B-01: the OAuth2 code path returns an id_token as well when
              // the `openid` scope is requested — keep it for the signup step 2.
              handleGoogleCredential(tokenResponse.id_token || null, tokenResponse.access_token);
            }
          },
          error_callback: (err: Unmodelled) => {
            console.error('Google OAuth error:', err);
            setError('Google sign-in was cancelled.');
          },
        });
        tokenClient.requestAccessToken({ prompt: 'select_account' });
        return;
      } catch (oauthErr: any) {
        console.warn('initTokenClient fallback:', oauthErr);
      }
    }

    if (window.google?.accounts?.id) {
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: (response: Unmodelled) => handleGoogleCredential(response.credential),
      });
      window.google.accounts.id.prompt();
    } else {
      setError('Google Sign-In script is loading. Please try again in a moment.');
    }
  };

  const handleResetGoogle = () => {
    setIsGoogle(false);
    setGoogleAvatar('');
    setGoogleIdToken('');
    localStorage.removeItem('google_signup');
  };

  const handleSignup = async (e: Unmodelled) => {
    e.preventDefault();
    setError('');

    if (!phone || phone.trim().length < 7) {
      setError('Please enter a valid phone number');
      return;
    }
    if (!gender || !dateOfBirth) {
      setError('Gender and date of birth are required');
      return;
    }
    if (!bloodGroup) {
      setError('Blood group is required');
      return;
    }
    if (!emergencyName || emergencyPhone.trim().length < 10) {
      setError('Primary emergency contact (name + 10-digit mobile) is required');
      return;
    }
    if (!agreed) {
      setError('Terms & DPDP consent is required');
      return;
    }

    setLoading(true);

    try {
      // Step 2 for Google Users: Direct account completion without password
      if (isGoogle) {
        if (!googleIdToken) {
          setError('Your Google session expired. Please sign in with Google again to continue.');
          setLoading(false);
          return;
        }
        const data = await api.googleRegister({
          name: name.trim(),
          phone: phone.trim(),
          gender,
          dateOfBirth,
          avatar: googleAvatar,
          googleIdToken,
        });

        localStorage.removeItem('google_signup');

        if (data.token && data.user) {
          setAuthTokens(data.token);
          completeGoogleLogin(data.user);
          navigate(data.user.mustResetPassword ? '/set-password' : '/dashboard', { replace: true });
          return;
        }
      } else {
        // Standard Registration with Password
        if (password !== confirmPassword) {
          setError('Passwords do not match');
          setLoading(false);
          return;
        }
        if (password.length < 12) {
          setError('Password must be at least 12 characters');
          setLoading(false);
          return;
        }

        const data = await api.register({
          name,
          email,
          password,
          role: 'patient',
          phone,
          gender,
          dateOfBirth,
          referralCode: referralCode || undefined,
        });

        const params = new URLSearchParams({ email, role: 'patient' });
        if (data?.emailDeliveryFailed || data?.otpWarning) params.set('delivery', 'failed');
        if (data?.sentTo) params.set('sentTo', data.sentTo);
        navigate(`/verify-otp?${params.toString()}`);
      }
    } catch (err: any) {
      setError(err.message || 'Signup failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background flex">
      {/* Left Hero Panel */}
      <div className="hidden lg:flex lg:w-1/2 bg-sidebar items-center justify-center p-12 relative overflow-hidden">
        <div className="absolute inset-0 opacity-10" style={{ backgroundImage: 'radial-gradient(circle at 25% 25%, hsl(174,62%,48%) 0%, transparent 50%), radial-gradient(circle at 75% 75%, hsl(210,80%,55%) 0%, transparent 50%)' }} />
        <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.7 }} className="relative z-10 text-center max-w-md">
          <div className="w-20 h-20 rounded-2xl bg-sidebar-primary flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-sidebar-primary/30">
            <Activity className="w-10 h-10 text-sidebar-primary-foreground" />
          </div>
          <h1 className="font-heading text-4xl font-bold text-sidebar-primary-foreground mb-4">Join FindMedi</h1>
          <p className="text-sidebar-foreground/70 text-lg leading-relaxed mb-10">
            Fast, secure, and hassle-free healthcare platform. Manage appointments, digital records, and consultations in one place.
          </p>
          <div className="flex items-center justify-center gap-6 text-sidebar-foreground/60 text-sm">
            <span className="flex items-center gap-1.5"><CheckCircle2 className="w-4 h-4 text-emerald-400" /> Instant Sign-in</span>
            <span className="flex items-center gap-1.5"><CheckCircle2 className="w-4 h-4 text-emerald-400" /> Google Verified</span>
            <span className="flex items-center gap-1.5"><CheckCircle2 className="w-4 h-4 text-emerald-400" /> 100% Secure</span>
          </div>
        </motion.div>
      </div>

      {/* Right Form Panel */}
      <div className="flex-1 flex items-center justify-center p-4 sm:p-8">
        <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.5 }} className="w-full max-w-md">
          <div className="lg:hidden flex items-center gap-3 mb-6">
            <div className="w-10 h-10 rounded-xl bg-primary flex items-center justify-center">
              <Activity className="w-5 h-5 text-primary-foreground" />
            </div>
            <h1 className="font-heading text-xl font-bold text-foreground">FindMedi</h1>
          </div>

          <div className="mb-6">
            <div className="flex items-center justify-between">
              <h2 className="font-heading text-2xl font-bold text-foreground">
                {isGoogle ? 'Complete Your Profile' : 'Create Account'}
              </h2>
              {isGoogle && (
                <span className="text-xs px-2.5 py-1 rounded-full font-semibold bg-emerald-500/10 text-emerald-600 border border-emerald-500/20">
                  Step 2 of 2
                </span>
              )}
            </div>
            <p className="text-muted-foreground text-sm mt-1">
              {isGoogle
                ? 'Google details fetched. Fill in your details below to finish setup.'
                : 'Fill in your details or continue with Google to get started.'}
            </p>
          </div>

          {/* Google Connected Banner (When in Google Mode) */}
          <AnimatePresence>
            {isGoogle && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="mb-5 p-3.5 rounded-xl border border-emerald-500/30 bg-emerald-500/5 flex items-center justify-between gap-3 shadow-sm"
              >
                <div className="flex items-center gap-3 min-w-0">
                  {googleAvatar ? (
                    <img src={googleAvatar} alt="Google Avatar" className="w-10 h-10 rounded-full border border-emerald-500/30 object-cover shrink-0" />
                  ) : (
                    <div className="w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center text-emerald-600 font-bold shrink-0">
                      G
                    </div>
                  )}
                  <div className="min-w-0">
                    <p className="text-xs font-semibold text-foreground truncate flex items-center gap-1.5">
                      {name || 'Google User'}
                      <span className="text-[10px] bg-emerald-500/20 text-emerald-700 dark:text-emerald-300 px-1.5 py-0.2 rounded font-medium">Verified</span>
                    </p>
                    <p className="text-xs text-muted-foreground truncate">{email}</p>
                  </div>
                </div>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={handleGoogleLogin}
                  className="text-xs h-8 text-muted-foreground hover:text-foreground shrink-0"
