}

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

import InsuranceTpaDeskDashboard from './hospital/InsuranceTpaDeskDashboard';

/**
 * File 09 §9.6 — TPA desk: insurers, pre-auth lifecycle, claims settle,
 * pipeline funnel. Document checklist lives on the insurer master.
 */
export default function TpaDesk() {
  const [deskView, setDeskView] = useState<'interactive' | 'master'>('master');
  const [insurers, setInsurers] = useState<any[]>([]);
  const [preauths, setPreauths] = useState<any[]>([]);
  const [form, setForm] = useState({ admissionId: '', insurerId: '', estimate: '' });
  // File 22 P1-15: claim-side actions by claim id.
  const [claimId, setClaimId] = useState('');
  const [query, setQuery] = useState('');
  const [rent, setRent] = useState({ eligiblePerDay: '', actualPerDay: '', days: '' });
  const [pmjay, setPmjay] = useState<any[]>([]);
  const [pmForm, setPmForm] = useState({ code: '', name: '', rate: '' });

  const load = async () => {
    try {
      const [i, p, m] = await Promise.all([(api as any).getInsurers(), (api as any).getPreAuths({}), api.pmjayList({})]);
      setInsurers(i?.insurers || []);
      setPreauths(p?.preauths || []);
      setPmjay(m?.packages || []);
    } catch { toast.error('Failed to load TPA desk'); }
  };
  useEffect(() => { load(); }, []);

  const create = async () => {
    try {
      await (api as any).createPreAuth({ ...form, estimate: Number(form.estimate) || 0 });
      toast.success('Pre-auth drafted');
      setForm({ admissionId: '', insurerId: '', estimate: '' });
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  const move = async (id: string, status: string) => {
    try {
      await (api as any).setPreAuthStatus(id, { status });
      toast.success(`Pre-auth → ${status}`);
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-heading font-bold text-slate-900">TPA Desk</h1>
          <p className="text-sm text-slate-500">Live insurer gateway, real-time pre-authorization, enhancements, and PM-JAY package manager</p>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl gap-1">
          <Button
            size="sm"
            variant={deskView === 'interactive' ? 'default' : 'ghost'}
            className={deskView === 'interactive' ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-sm' : ''}
            onClick={() => setDeskView('interactive')}
          >
            Pre-Auth & Claims Queue
          </Button>
          <Button
            size="sm"
            variant={deskView === 'master' ? 'default' : 'ghost'}
            className={deskView === 'master' ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-sm' : ''}
            onClick={() => setDeskView('master')}
          >
            Insurer Master & PM-JAY
          </Button>
        </div>
      </div>

      {deskView === 'interactive' ? (
        <InsuranceTpaDeskDashboard />
      ) : (
        <>
      <Card>
        <CardHeader><CardTitle className="text-base">New pre-auth ({insurers.length} insurers empanelled)</CardTitle></CardHeader>
        <CardContent className="grid sm:grid-cols-4 gap-2">
          <Input placeholder="Admission ID" value={form.admissionId} onChange={(e) => setForm({ ...form, admissionId: e.target.value })} />
          <select aria-label="Insurer" className="h-10 rounded-md border border-input bg-background px-3 text-sm" value={form.insurerId} onChange={(e) => setForm({ ...form, insurerId: e.target.value })}>
            <option value="">Select insurer</option>
            {insurers.map((i: any) => <option key={i._id} value={i._id}>{i.name} ({i.type})</option>)}
          </select>
          <Input placeholder="Estimate ₹" type="number" value={form.estimate} onChange={(e) => setForm({ ...form, estimate: e.target.value })} />
          <Button onClick={create} disabled={!form.admissionId || !form.insurerId}>Create</Button>
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle className="text-base">Pre-auth queue ({preauths.length})</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          {preauths.map((p: any) => (
            <div key={p._id} className="flex flex-wrap items-center gap-2 text-sm rounded-lg border border-border/50 p-2.5">
              <span className="font-mono text-xs">{String(p._id).slice(-6)}</span>
              <span className="text-xs font-bold px-2 py-0.5 rounded-full bg-muted">{p.status}</span>
              <span className="text-xs text-muted-foreground">est ₹{p.estimate} · approved ₹{p.approvedAmount || 0}</span>
              <span className="flex-1" />
              {['Submitted', 'Approved', 'Rejected'].map((s) => (
                <Button key={s} size="sm" variant="outline" onClick={() => move(p._id, s)}>{s}</Button>
              ))}
            </div>
          ))}
          {preauths.length === 0 && <p className="text-sm text-muted-foreground">Queue empty.</p>}
        </CardContent>
      </Card>
      {/* File 22 P1-15: claim actions + PM-JAY map */}
      <div className="grid lg:grid-cols-2 gap-4">
        <Card>
          <CardHeader><CardTitle className="text-base">Claim actions</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <Input placeholder="Claim ID" value={claimId} onChange={(e) => setClaimId(e.target.value)} />
            <div className="flex gap-2">
              <Input placeholder="Query text" value={query} onChange={(e) => setQuery(e.target.value)} />
              <Button size="sm" variant="outline" disabled={!claimId || !query} onClick={async () => {
                try { await api.tpaQuery(claimId, { text: query }); toast.success('Query posted'); setQuery(''); }
                catch { toast.error('Failed'); }
              }}>Post query</Button>
            </div>
            <div className="flex gap-2">
              <Input className="w-28" placeholder="Eligible/day" value={rent.eligiblePerDay} onChange={(e) => setRent({ ...rent, eligiblePerDay: e.target.value })} />
              <Input className="w-28" placeholder="Actual/day" value={rent.actualPerDay} onChange={(e) => setRent({ ...rent, actualPerDay: e.target.value })} />
              <Input className="w-20" placeholder="Days" value={rent.days} onChange={(e) => setRent({ ...rent, days: e.target.value })} />
              <Button size="sm" variant="outline" disabled={!claimId} onClick={async () => {
                try {
                  const r: any = await api.tpaRoomRent(claimId, { eligiblePerDay: Number(rent.eligiblePerDay), actualPerDay: Number(rent.actualPerDay), days: Number(rent.days) });
                  toast.success(`Deduction ₹${r?.deduction}`);
                } catch { toast.error('Failed'); }
              }}>Room-rent cut</Button>
            </div>
            <Button size="sm" variant="outline" disabled={!claimId} onClick={async () => {
              const grounds = window.prompt('Appeal grounds:');
              if (!grounds) return;
              try { await api.tpaAppeal(claimId, grounds); toast.success('Appeal filed as child claim'); }
              catch (e: any) { toast.error(e?.response?.data?.message || 'Appeal failed'); }
            }}>Appeal (Rejected/Partial only)</Button>
          </CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">PM-JAY packages ({pmjay.length})</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <div className="flex gap-2">
              <Input className="w-24" placeholder="Code" value={pmForm.code} onChange={(e) => setPmForm({ ...pmForm, code: e.target.value })} />
              <Input placeholder="Name" value={pmForm.name} onChange={(e) => setPmForm({ ...pmForm, name: e.target.value })} />
              <Input className="w-28" placeholder="Rate" value={pmForm.rate} onChange={(e) => setPmForm({ ...pmForm, rate: e.target.value })} />
              <Button size="sm" variant="outline" onClick={async () => {
                try { await api.pmjayUpsert({ ...pmForm, rate: Number(pmForm.rate) }); setPmForm({ code: '', name: '', rate: '' }); load(); }
                catch { toast.error('Failed'); }
              }}>Save</Button>
            </div>
            <div className="max-h-48 space-y-1 overflow-auto">
              {pmjay.slice(0, 30).map((p: any) => (
                <p key={p._id} className="flex justify-between rounded border px-2 py-1 font-mono text-[11px]">
                  <span>{p.code} · {p.name}</span><b>₹{(p.rate || 0).toLocaleString('en-IN')}</b>
                </p>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
      </>
      )}
    </div>
  );
}

import { useState } from 'react';
import { motion } from 'framer-motion';
import {
  Search, FileText, CreditCard, Smartphone, Landmark, Wallet,
  CheckCircle, Clock, AlertCircle, RotateCcw, Download, Calendar,
  User, Hospital, Stethoscope, TestTube, Pill, IndianRupee, Loader2,
  ExternalLink, Copy, Check
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { api, downloadPaymentInvoice, downloadBillPdf } from '@/lib/api';
import { userFacingError } from '@/lib/errorCopy';
import type { Unmodelled } from '@/lib/apiTypes';

const methodIcons: Unmodelled = {
  card: CreditCard, upi: Smartphone, netbanking: Landmark,
  cash: Wallet, wallet: Smartphone, online: CreditCard
};

const statusConfig: Unmodelled = {
  completed: { label: 'Paid', color: 'bg-emerald-500/10 text-emerald-600', icon: CheckCircle },
  pending: { label: 'Pending', color: 'bg-amber-500/10 text-amber-600', icon: Clock },
  failed: { label: 'Failed', color: 'bg-red-500/10 text-red-600', icon: AlertCircle },
  refunded: { label: 'Refunded', color: 'bg-blue-500/10 text-blue-600', icon: RotateCcw },
};

const serviceTypeLabels: Unmodelled = {
  appointment: 'Appointment', test: 'Lab Test', medicine: 'Medicine',
  ipd: 'IPD', ot: 'Operation Theatre', radiology: 'Radiology',
  physio: 'Physiotherapy', diet: 'Diet', mentalhealth: 'Mental Health'
};

function formatDate(d: Unmodelled) {
  if (!d) return '-';
  const dt = new Date(d);
  return dt.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

function copyToClipboard(text: Unmodelled) {
  navigator.clipboard.writeText(text);
}

export default function VerifyTransaction() {
  const [searchId, setSearchId] = useState('');
  const [result, setResult] = useState<Unmodelled>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleVerify = async () => {
    if (!searchId.trim()) {
      toast.error('Please enter a Transaction ID, Invoice ID, or any valid ID');
      return;
    }
    setLoading(true);
    setResult(null);
    try {
      const res = await api.verifyTransaction(searchId.trim());
      setResult(res);
      toast.success('Transaction verified successfully');
    } catch (e: any) {
      const msg = userFacingError(e, { fallback: 'Transaction not found' });
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadInvoice = async () => {
    if (!result?.payment?.transaction_id) return;
    try {
      await downloadPaymentInvoice(result.payment.transaction_id, `${result.payment.transaction_id}.pdf`);
    } catch (error: any) {
      toast.error(error.message || 'Unable to download invoice');
    }
  };

  const handleDownloadBill = async () => {
    if (!result?.payment?.transaction_id) return;
    try {
      await downloadBillPdf(result.payment.transaction_id, `${result.payment.transaction_id}-bill.pdf`);
    } catch (error: any) {
      toast.error(error.message || 'Unable to download bill');
    }
  };

  const handleCopy = (text: Unmodelled) => {
    copyToClipboard(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const payment = result?.payment;
  const reference = result?.reference;
  const patient = result?.patient;
  const hospital = result?.hospital;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Verify Transaction</h1>
        <p className="text-muted-foreground text-sm">Enter any valid ID to verify a transaction</p>
      </div>

      {/* Search */}
      <div className="flex flex-col sm:flex-row gap-3">
        <Input
          placeholder="Enter Transaction ID / Invoice ID / Bill ID / Appointment ID / Booking ID / Order ID / Payment ID"
          value={searchId}
          onChange={e => setSearchId(e.target.value)}
          className="flex-1"
          onKeyDown={e => { if (e.key === 'Enter') handleVerify(); }}
        />
        <Button onClick={handleVerify} disabled={loading} className="sm:w-auto w-full">
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
          Verify
        </Button>
      </div>

      {/* Results */}
      {!result && !loading && (
        <div className="text-center py-16 bg-card rounded-2xl border border-border/60">
          <FileText className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
          <p className="text-muted-foreground">Enter an ID above and click Verify to see transaction details</p>
        </div>
      )}

      {loading && (
        <div className="flex justify-center py-16">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
        </div>
      )}

      {result && payment && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-6"
        >
          {/* Main Details */}
          <div className="bg-card rounded-2xl border border-border/60 p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-heading text-lg font-semibold text-foreground">Transaction Details</h2>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={handleDownloadInvoice}>
                  <Download className="w-4 h-4 mr-1" /> Invoice
                </Button>
                <Button variant="outline" size="sm" onClick={handleDownloadBill}>
                  <Download className="w-4 h-4 mr-1" /> Bill
                </Button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Left Column */}
              <div className="space-y-4">
                <div className="flex items-start justify-between">
                  <div>
                    <label className="text-xs text-muted-foreground uppercase tracking-wider">Transaction ID</label>
                    <p className="font-mono text-sm mt-1 break-all">{payment.transaction_id || '-'}</p>
                  </div>
                  {payment.transaction_id && (
                    <Button variant="ghost" size="sm" onClick={() => handleCopy(payment.transaction_id)}>
                      {copied ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
                    </Button>
                  )}
                </div>

                <div>
                  <label className="text-xs text-muted-foreground uppercase tracking-wider">Invoice ID</label>
                  <p className="font-mono text-sm mt-1 break-all">{payment.invoice_id || '-'}</p>
                </div>

                <div>
                  <label className="text-xs text-muted-foreground uppercase tracking-wider">Amount</label>
                  <p className="text-2xl font-bold text-foreground mt-1">₹{payment.amount?.toLocaleString('en-IN') || '0'}</p>
                </div>

                <div>
                  <label className="text-xs text-muted-foreground uppercase tracking-wider">Payment Method</label>
                  <div className="flex items-center gap-2 mt-1">
                    {(() => {
                      const Icon = methodIcons[payment.method] || CreditCard;
                      return <Icon className="w-5 h-5 text-primary" />;
                    })()}
                    <span className="capitalize">{payment.method || 'Unknown'}</span>
                  </div>
                </div>

                <div>
                  <label className="text-xs text-muted-foreground uppercase tracking-wider">Status</label>
                  <div className="mt-1">
                    {(() => {
                      const cfg = statusConfig[payment.status] || statusConfig.pending;
                      const Icon = cfg.icon;
                      return (
                        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium ${cfg.color}`}>
