import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Send, Loader2, Megaphone, Clock, User, AlertTriangle, Info, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const priorityStyles: Unmodelled = {
  urgent: 'bg-red-100 text-red-700 border-red-200 dark:bg-red-500/10',
  high: 'bg-orange-100 text-orange-700 border-orange-200 dark:bg-orange-500/10',
  normal: 'bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-500/10',
  low: 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-500/10',
};

const priorityIcons: Unmodelled = { urgent: AlertCircle, high: AlertTriangle, normal: Info, low: Info };

export default function AdminAnnouncements() {
  const [announcements, setAnnouncements] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [title, setTitle] = useState('');
  const [message, setMessage] = useState('');
  const [priority, setPriority] = useState('normal');
  const [targetRoles, setTargetRoles] = useState(['all']);

  const load = async () => {
    try {
      const data = await api.getAnnouncements();
      setAnnouncements(Array.isArray(data) ? data : []);
    } catch { toast.error('Failed to load announcements'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const toggleRole = (role: Unmodelled) => {
    setTargetRoles(prev =>
      prev.includes(role) ? prev.filter(r => r !== role) : [...prev.filter(r => r !== 'all'), role]
    );
  };

  const handleSend = async () => {
    if (!title.trim() || !message.trim()) return toast.error('Title and message are required');
    setSending(true);
    try {
      await api.createAnnouncement({ title, message, priority, targetRoles });
      toast.success('Announcement sent successfully');
      setTitle(''); setMessage(''); setPriority('normal'); setTargetRoles(['all']);
      await load();
    } catch (e: any) { toast.error(e.message || 'Failed to send'); }
    setSending(false);
  };

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin text-primary" /></div>;

  return (
    <div className="max-w-3xl mx-auto space-y-8 py-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Staff Announcements</h1>
        <p className="text-muted-foreground">Send broadcast messages to doctors, nurses, and hospital staff</p>
      </div>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Send className="w-5 h-5" /> New Announcement</CardTitle></CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2"><Label>Title</Label><Input value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Staff Meeting Tomorrow" /></div>
          <div className="space-y-2"><Label>Message</Label><Textarea rows={4} value={message} onChange={e => setMessage(e.target.value)} placeholder="Type your announcement here..." /></div>
          <div className="flex gap-4 flex-wrap">
            <div className="space-y-2">
              <Label>Priority</Label>
              <div className="flex gap-1.5">
                {['low', 'normal', 'high', 'urgent'].map(p => (
                  <button key={p} onClick={() => setPriority(p)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-colors ${priority === p ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                    {p}
                  </button>
                ))}
              </div>
            </div>
            <div className="space-y-2">
              <Label>Send To</Label>
              <div className="flex gap-1.5 flex-wrap">
                {['all', 'superadmin', 'hospital_admin', 'doctor', 'clinic_doctor', 'patient', 'lab_owner', 'pharmacy_owner'].map(role => (
                  <button key={role} onClick={() => toggleRole(role)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-colors ${targetRoles.includes(role) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                    {role === 'all' ? 'Everyone' : role + 's'}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <Button onClick={handleSend} disabled={sending} className="gap-2 w-full">
            {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
            {sending ? 'Sending...' : 'Send Announcement'}
          </Button>
        </CardContent>
      </Card>

      <div className="space-y-4">
        <h2 className="font-heading text-lg font-semibold text-foreground">Announcement History</h2>
        {announcements.length === 0 ? (
          <div className="text-center py-16 bg-card rounded-2xl border border-dashed">
            <Megaphone className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
            <p className="text-muted-foreground">No announcements sent yet</p>
          </div>
        ) : (
          announcements.map((a, i) => {
            const PrioIcon = priorityIcons[a.priority] || Info;
            return (
              <motion.div key={a._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all">
                <div className="flex items-start gap-3">
                  <div className={`p-2 rounded-xl ${priorityStyles[a.priority] || 'bg-muted'}`}>
                    <PrioIcon className="w-5 h-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="font-heading font-semibold text-foreground">{a.title}</h3>
                      <Badge variant="outline" className={`text-[10px] ${priorityStyles[a.priority]}`}>{a.priority}</Badge>
                    </div>
                    <p className="text-sm text-foreground mt-1.5">{a.message}</p>
                    <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1"><User className="w-3 h-3" /> {a.createdBy?.name || 'hospital_admin'}</span>
                      <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {new Date(a.createdAt).toLocaleDateString()}</span>
                      <span>To: {(a.targetRoles || ['all']).join(', ')}</span>
                    </div>
                  </div>
                </div>
              </motion.div>
            );
          })
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Users,
  ShieldCheck,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Clock,
  Search,
  Filter,
  BarChart3,
  Calendar,
  DollarSign,
  TrendingUp,
  MapPin,
} from 'lucide-react';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import { Input } from '../../components/ui/input';
import { DataGrid } from '../../components/ui/System';
import { api } from '../../lib/api';
import { toast } from 'sonner';
import type { Unmodelled } from '@/lib/apiTypes';

export default function AdminAssistants() {
  const [activeTab, setActiveTab] = useState<'approvals' | 'all' | 'bookings' | 'analytics'>('approvals');

  const [pending, setPending] = useState<any[]>([]);
  const [allAssistants, setAllAssistants] = useState<any[]>([]);
  const [bookings, setBookings] = useState<any[]>([]);
  const [analytics, setAnalytics] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  const fetchData = async () => {
    try {
      setLoading(true);
      if (activeTab === 'approvals') {
        const res = await api.getPendingAssistants();
        setPending(res?.assistants || []);
      } else if (activeTab === 'all') {
        const res = await api.getAdminAssistants({ search: search || undefined });
        setAllAssistants(res?.assistants || []);
      } else if (activeTab === 'bookings') {
        const res = await api.getAdminAssistantBookings();
        setBookings(res?.bookings || []);
      } else if (activeTab === 'analytics') {
        const res = await api.getAssistantAnalytics();
        setAnalytics(res);
      }
    } catch (err: any) {
      console.error('Failed to fetch admin assistant data', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  const handleApprove = async (id: string) => {
    try {
      await api.approveAssistant(id);
      toast.error('Assistant verified and approved successfully!');
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Approve failed');
    }
  };

  const handleReject = async (id: string) => {
    const reason = prompt('Please enter rejection reason:');
    if (!reason) return;
    try {
      await api.rejectAssistant(id, reason);
      toast.error('Assistant rejected.');
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Reject failed');
    }
  };

  const handleSuspend = async (id: string, suspend: boolean) => {
    const reason = suspend ? prompt('Reason for suspension:') || 'Policy violation' : undefined;
    try {
      await api.suspendAssistant(id, suspend, reason);
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Action failed');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-black text-slate-900 dark:text-slate-100 flex items-center gap-2">
              <Users className="w-7 h-7 text-teal-600" />
              Hospital Assistant Management
            </h1>
            <p className="text-xs text-slate-500 mt-1">
              Admin panel for assistant verification, profile monitoring, bookings oversight, and revenue analytics.
            </p>
          </div>
        </div>

        {/* Tab Selection */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 text-xs">
          {[
            { id: 'approvals', label: `Pending Approvals (${pending.length})`, icon: ShieldCheck },
            { id: 'all', label: 'All Assistants', icon: Users },
            { id: 'bookings', label: 'All Bookings', icon: Calendar },
            { id: 'analytics', label: 'Analytics & Revenue', icon: BarChart3 },
          ].map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl font-bold transition-all whitespace-nowrap ${
                  isActive
                    ? 'bg-teal-600 text-white shadow-sm'
                    : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-100'
                }`}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* ── 1. APPROVALS QUEUE ──────────────────────────────────── */}
        {activeTab === 'approvals' && (
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm space-y-4">
            <h3 className="font-bold text-base text-slate-900 dark:text-slate-100">
              Assistant Verification Queue
            </h3>

            {loading ? (
              <div className="py-12 text-center text-xs text-slate-400">Loading queue...</div>
            ) : pending.length === 0 ? (
              <div className="py-12 text-center text-xs text-slate-500">
                <CheckCircle2 className="w-8 h-8 text-emerald-500 mx-auto mb-2" />
                All pending assistant applications have been reviewed!
              </div>
            ) : (
              <div className="space-y-4">
                {pending.map((ast) => (
                  <div
                    key={ast._id}
                    className="p-5 rounded-2xl border border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-800/30 flex flex-col md:flex-row items-start md:items-center justify-between gap-4"
                  >
                    <div className="space-y-1.5 flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-bold text-sm text-slate-900 dark:text-slate-100">
                          {ast.userId?.name || 'Applicant'}
                        </span>
                        <Badge variant="outline" className="text-[10px]">
                          {ast.govtIdType}: {ast.govtIdNumber}
                        </Badge>
                        <span className="text-xs text-slate-400">• {ast.userId?.email}</span>
                      </div>

                      <div className="text-xs text-slate-600 dark:text-slate-400">
                        {ast.experienceYears} Years Exp • Hospitals:{' '}
                        <strong>{(ast.hospitalsCovered || []).join(', ')}</strong> • Rate: ₹{ast.pricePerHour}/hr
                      </div>

                      {ast.bio && (
                        <p className="text-xs text-slate-500 italic bg-white dark:bg-slate-900 p-2.5 rounded-lg border">
                          "{ast.bio}"
                        </p>
                      )}
                    </div>

                    <div className="flex items-center gap-2 self-end md:self-center flex-shrink-0">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => handleReject(ast._id)}
                        className="text-xs text-rose-600 hover:text-rose-700 hover:bg-rose-50 border-rose-200"
                      >
                        Reject
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        onClick={() => handleApprove(ast._id)}
                        className="text-xs bg-teal-600 hover:bg-teal-700 text-white font-bold"
                      >
                        Approve & Verify
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ── 2. ALL ASSISTANTS ───────────────────────────────────── */}
        {activeTab === 'all' && (
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm space-y-4">
            <div className="flex items-center justify-between gap-4">
              <h3 className="font-bold text-base text-slate-900 dark:text-slate-100">
                All Platform Assistants ({allAssistants.length})
              </h3>
              <Input
                type="text"
                placeholder="Search assistant by name or email..."
                aria-label="Search assistants"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="max-w-xs text-xs h-9"
              />
            </div>

            {/* Search already hit the API (getAdminAssistants({search})). */}
            <DataGrid
              columns={[
                {
                  key: 'name', label: 'Name & Contact', sortable: false,
                  render: (_v: Unmodelled, a: Unmodelled) => (
                    <>
                      <div className="font-bold text-slate-900 dark:text-slate-100">{a.userId?.name}</div>
                      <div className="text-[10px] text-slate-400">{a.userId?.email}</div>
                    </>
                  ),
                },
                { key: 'hospitalsCovered', label: 'Hospitals', sortable: false, render: (v: Unmodelled) => (v || []).slice(0, 2).join(', ') },
                { key: 'experienceYears', label: 'Experience', sortable: false, render: (v: Unmodelled) => `${v || 1} yrs` },
                { key: 'pricePerHour', label: 'Rate', sortable: false, render: (v: Unmodelled) => <span className="font-bold text-teal-600">₹{v}/hr</span> },
                { key: 'assistantStatus', label: 'Status', sortable: false, render: (v: Unmodelled) => <Badge variant={v === 'active' ? 'default' : 'secondary'} className="text-[10px]">{v}</Badge> },
                {
                  key: '_actions', label: 'Action', sortable: false,
                  render: (_v: Unmodelled, a: Unmodelled) => (
                    a.assistantStatus === 'active' ? (
                      <Button type="button" variant="ghost" size="sm" onClick={() => handleSuspend(a._id, true)} className="text-xs text-rose-600 hover:text-rose-700 h-7">Suspend</Button>
                    ) : a.assistantStatus === 'suspended' ? (
                      <Button type="button" variant="ghost" size="sm" onClick={() => handleSuspend(a._id, false)} className="text-xs text-emerald-600 hover:text-emerald-700 h-7">Reinstate</Button>
                    ) : null
                  ),
                },
              ]}
              rows={allAssistants}
              rowKey="_id"
              empty="No assistants found"
              showSearch={false}
              manualPagination
            />
          </div>
        )}

        {/* ── 3. ALL BOOKINGS ─────────────────────────────────────── */}
        {activeTab === 'bookings' && (
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm space-y-4">
            <h3 className="font-bold text-base text-slate-900 dark:text-slate-100">
              Live & Historical Assistant Shifts ({bookings.length})
            </h3>

            <DataGrid
              columns={[
                { key: 'bookingNumber', label: 'Shift #', sortable: false, render: (v: Unmodelled, b: Unmodelled) => <span className="font-mono font-bold">#{v || String(b._id).slice(-6).toUpperCase()}</span> },
                { key: 'patientId', label: 'Patient', sortable: false, render: (v: Unmodelled) => v?.name || 'Patient' },
                { key: 'assistantId', label: 'Assistant', sortable: false, render: (v: Unmodelled) => v?.name || 'Unassigned' },
                { key: 'hospital', label: 'Hospital', sortable: false },
                { key: 'cost', label: 'Fee', sortable: false, render: (v: Unmodelled) => <span className="font-bold text-teal-600">₹{v?.total || 0}</span> },
                { key: 'status', label: 'Status', sortable: false, render: (v: Unmodelled) => <Badge className="text-[10px]">{v?.replace('_', ' ').toUpperCase()}</Badge> },
              ]}
              rows={bookings}
              rowKey="_id"
              empty="No assistant shifts yet"
              showSearch={false}
              manualPagination
            />
          </div>
        )}

        {/* ── 4. ANALYTICS & REVENUE ──────────────────────────────── */}
        {activeTab === 'analytics' && analytics && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
              <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border shadow-sm">
                <span className="text-xs text-slate-500">Gross Shift Revenue</span>
                <div className="text-2xl font-black text-slate-900 dark:text-slate-100 mt-1">
                  ₹{analytics.financials?.grossBookingsRevenue?.toLocaleString('en-IN') || 0}
                </div>
              </div>

              <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border shadow-sm">
                <span className="text-xs text-slate-500">Platform Commission (10%)</span>
                <div className="text-2xl font-black text-teal-600 mt-1">
                  ₹{analytics.financials?.platformCommission10Pct?.toLocaleString('en-IN') || 0}
                </div>
              </div>

              <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border shadow-sm">
                <span className="text-xs text-slate-500">Total Bookings</span>
                <div className="text-2xl font-black text-slate-900 dark:text-slate-100 mt-1">
                  {analytics.bookings?.total || 0}
                </div>
                <span className="text-[10px] text-emerald-600 font-bold">
                  {analytics.bookings?.completionRate || 100}% Completed
                </span>
              </div>

              <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border shadow-sm">
                <span className="text-xs text-slate-500">Active Attendants</span>
                <div className="text-2xl font-black text-slate-900 dark:text-slate-100 mt-1">
                  {analytics.assistants?.active || 0}
                </div>
                <span className="text-[10px] text-amber-500 font-bold">
                  {analytics.assistants?.pending || 0} Pending
                </span>
              </div>
            </div>
          </div>
        )}

        <div className="rounded-2xl border p-4 mt-4">
          <p className="font-semibold text-sm mb-2">Ward Duty Timeline</p>
          <p className="text-xs text-muted-foreground">Morning → Afternoon → Night roster blocks per ward. Detailed timeline view coming from duty-roster API.</p>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Bed, Plus, Search, Trash2, Edit, Save, X, Eye, Wifi, Snowflake } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import type { Unmodelled } from '@/lib/apiTypes';

const WARDS = ['General', 'Semi-Private', 'Private', 'ICU', 'NICU', 'PICU', 'Emergency'];
const BED_TYPES = ['General', 'Semi-Private', 'Private', 'ICU', 'NICU', 'PICU'];

export default function AdminBedManagement() {
  const [beds, setBeds] = useState<any[]>([]);
  const [stats, setStats] = useState({ total: 0, available: 0, occupied: 0, maintenance: 0 });
  const [search, setSearch] = useState('');
  const [wardFilter, setWardFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [view, setView] = useState('cards');
  const [editId, setEditId] = useState<Unmodelled>(null);
  const [form, setForm] = useState({ bedNumber: '', ward: 'General', bedType: 'General', dailyRate: '', floor: '', isAC: false });

  const loadBeds = useCallback(async () => {
    setLoading(true);
    try {
      const params: any = {};
      if (wardFilter) params.ward = wardFilter;
      if (statusFilter) params.status = statusFilter;
      const [data, statsData] = await Promise.all([
        api.getBeds(params),
        api.getBedStats(),
      ]);
      setBeds(Array.isArray(data) ? data : (data?.beds || data?.data || []));
      setStats(statsData || {});
    } catch { toast.error('Failed to load beds'); }
    setLoading(false);
  }, [wardFilter, statusFilter]);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadBeds(); }, [wardFilter, statusFilter]);

  const resetForm = () => {
    setForm({ bedNumber: '', ward: 'General', bedType: 'General', dailyRate: '', floor: '', isAC: false });
    setEditId(null);
    setShowForm(false);
  };

  const handleSave = async () => {
    try {
      if (editId) {
        await api.updateBed(editId, form);
      } else {
        await api.createBed(form);
      }
      resetForm();
      loadBeds();
    } catch { toast.error(editId ? 'Failed to update bed' : 'Failed to create bed'); }
  };

  const handleEdit = (bed: Unmodelled) => {
    setForm({
      bedNumber: bed.bedNumber,
      ward: bed.ward,
      bedType: bed.bedType,
      dailyRate: bed.dailyRate?.toString() || '',
      floor: bed.floor || '',
      isAC: bed.isAC || false,
    });
    setEditId(bed._id);
    setShowForm(true);
  };

  const handleDelete = async (id: Unmodelled) => {
    if (!confirm('Permanently delete this bed?')) return;
    try { await api.deleteBed(id); loadBeds(); } catch { toast.error('Failed to delete bed'); }
  };

  const filtered = beds.filter(b => !search || b.bedNumber.toLowerCase().includes(search.toLowerCase()) || b.ward.toLowerCase().includes(search.toLowerCase()));

  const statusColor: Unmodelled = { Available: 'bg-emerald-500/10 text-emerald-600', Occupied: 'bg-red-500/10 text-red-600', 'Under Cleaning': 'bg-amber-500/10 text-amber-600', Maintenance: 'bg-gray-500/10 text-gray-600' };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Bed & Ward Management</h1>
          <p className="text-muted-foreground">Manage hospital beds, wards and availability</p>
        </div>
        <Button className="gap-2 w-full sm:w-auto" onClick={() => { resetForm(); setShowForm(true); }}><Plus className="w-4 h-4" /> Add Bed</Button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Beds', value: stats.total, color: 'text-foreground' },
          { label: 'Available', value: stats.available, color: 'text-emerald-600' },
          { label: 'Occupied', value: stats.occupied, color: 'text-red-600' },
          { label: 'Maintenance', value: stats.maintenance, color: 'text-amber-600' },
        ].map((s, i) => (
          <div key={i} className="bg-card rounded-2xl border border-border/60 p-4 text-center">
            <p className="text-2xl font-bold mb-1">{s.value}</p>
            <p className="text-sm text-muted-foreground">{s.label}</p>
          </div>
        ))}
      </div>

      <div className="rounded-2xl border p-4 flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-muted-foreground">Ward layout map (2D floor-plan) — General / ICU / Emergency blocks</p>
        <div className="flex gap-2">
          <Button variant={view === 'plan' ? 'default' : 'outline'} size="sm" onClick={() => setView(view === 'plan' ? 'cards' : 'plan')}>{view === 'plan' ? 'Card View' : 'Floor-plan View'}</Button>
          <Button variant="outline" size="sm" onClick={() => window.location.hash = '#/patient-registration'}>Admit Patient to Bed</Button>
        </div>
      </div>

      {view === 'plan' && !loading && (
        <div className="space-y-4">
          {Object.entries(
            filtered.reduce((acc, b) => {
              const f = b.floor || 'Ground';
              (acc[f] = acc[f] || []).push(b);
              return acc;
            }, {})
          ).map(([floor, list]: Unmodelled) => (
            <div key={floor} className="rounded-2xl border border-border/60 p-4">
              <p className="text-sm font-bold mb-3">Floor: {floor} <span className="text-muted-foreground font-normal">({list.length} beds · {list.filter((b: Unmodelled) => b.status === 'Available').length} free)</span></p>
              <div className="space-y-3">
                {Object.entries(
                  list.reduce((acc: Unmodelled, b: Unmodelled) => {
                    (acc[b.ward || 'General'] = acc[b.ward || 'General'] || []).push(b);
                    return acc;
                  }, {})
                ).map(([ward, beds]: Unmodelled) => (
                  <div key={ward}>
                    <p className="text-xs font-semibold text-muted-foreground mb-1.5">{ward}</p>
                    <div className="flex flex-wrap gap-1.5">
                      {beds.map((b: Unmodelled) => (
                        <span key={b._id} title={`${b.bedNumber} — ${b.status}`}
                          className={`w-9 h-9 rounded-lg flex items-center justify-center text-[10px] font-bold border ${b.status === 'Available' ? 'bg-emerald-500/15 text-emerald-700 border-emerald-500/30' : b.status === 'Occupied' ? 'bg-red-500/15 text-red-700 border-red-500/30' : 'bg-amber-500/15 text-amber-700 border-amber-500/30'}`}>
                          {String(b.bedNumber).slice(-3)}
                        </span>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
          {filtered.length === 0 && <p className="text-center py-8 text-muted-foreground text-sm">No beds to map.</p>}
        </div>
      )}

      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search bed number or ward..." className="pl-10" />
        </div>
        <select value={wardFilter} onChange={e => setWardFilter(e.target.value)} className="bg-card border border-border/60 rounded-xl px-3 py-2 text-sm">
          <option value="">All Wards</option>
          {WARDS.map(w => <option key={w} value={w}>{w}</option>)}
        </select>
        <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="bg-card border border-border/60 rounded-xl px-3 py-2 text-sm">
          <option value="">All Status</option>
          {['Available', 'Occupied', 'Under Cleaning', 'Maintenance'].map(s => <option key={s} value={s}>{s}</option>)}
        </select>
      </div>

      {loading ? (
        <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>
      ) : view === 'plan' ? null : filtered.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">No beds found. Add a bed to get started.</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {filtered.map((bed, i) => (
            <motion.div key={bed._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
              className="bg-card rounded-2xl border border-border/60 p-4 hover:shadow-lg transition-all"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-2">
                  <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                    <Bed className="w-5 h-5 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-heading font-semibold text-foreground">{bed.bedNumber}</h3>
                    <p className="text-xs text-muted-foreground">{bed.ward} - {bed.bedType}</p>
                  </div>
                </div>
                <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${statusColor[bed.status] || 'bg-gray-500/10 text-gray-600'}`}>
                  {bed.status}
                </span>
              </div>

              <div className="space-y-1.5 text-xs text-muted-foreground mb-3">
                <div className="flex justify-between">
                  <span>Daily Rate</span>
                  <span className="font-semibold text-foreground">₹{bed.dailyRate}</span>
                </div>
                {bed.floor && (
                  <div className="flex justify-between">
                    <span>Floor</span>
                    <span className="font-semibold text-foreground">{bed.floor}</span>
                  </div>
                )}
                <div className="flex justify-between">
                  <span>AC</span>
                  <span className="font-semibold text-foreground">{bed.isAC ? 'Yes' : 'No'}</span>
                </div>
                {bed.currentPatientName && (
                  <div className="flex justify-between">
                    <span>Patient</span>
                    <span className="font-semibold text-foreground truncate ml-2">{bed.currentPatientName}</span>
                  </div>
                )}
              </div>

              <div className="flex items-center gap-1.5 pt-2 border-t border-border/30 mb-2">
                <span className="text-[11px] text-muted-foreground">Status:</span>
                <select
                  value={bed.status}
                  onChange={async (e) => {
                    const newStatus = e.target.value;
                    try {
                      await api.updateBed(bed._id, { status: newStatus });
                      toast.success(`Bed ${bed.bedNumber} marked as ${newStatus}${newStatus === 'Under Cleaning' ? ' (Housekeeping dispatched)' : ''}`);
                      loadBeds();
                    } catch {
                      toast.error('Failed to change bed status');
                    }
                  }}
                  className="text-xs font-semibold bg-background border border-border/60 rounded px-2 py-0.5 flex-1"
                >
                  <option value="Available">Available</option>
                  <option value="Occupied">Occupied</option>
                  <option value="Under Cleaning">Under Cleaning</option>
                  <option value="Maintenance">Maintenance</option>
                </select>
              </div>

              <div className="flex gap-2 pt-1 border-t border-border/30">
                <Button variant="outline" size="sm" className="flex-1 gap-1 text-xs h-8" onClick={() => handleEdit(bed)}>
                  <Edit className="w-3 h-3" /> Edit
                </Button>
                <Button variant="outline" size="sm" className="flex-1 gap-1 text-xs h-8 text-destructive hover:text-destructive" onClick={() => handleDelete(bed._id)}>
                  <Trash2 className="w-3 h-3" /> Remove
                </Button>
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4" onClick={(e) => { if (e.target === e.currentTarget) resetForm(); }}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-card rounded-2xl border border-border/60 p-6 w-full max-w-md shadow-xl">
            <div className="flex items-center justify-between mb-5">
              <h2 className="font-heading text-lg font-bold text-foreground">{editId ? 'Edit Bed' : 'Add New Bed'}</h2>
              <button onClick={resetForm} className="p-1 hover:bg-muted rounded-lg"><X className="w-5 h-5" /></button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">Bed Number *</label>
                <Input value={form.bedNumber} onChange={e => setForm({ ...form, bedNumber: e.target.value })} placeholder="e.g. G-01, ICU-03" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-foreground mb-1">Ward *</label>
                  <select value={form.ward} onChange={e => setForm({ ...form, ward: e.target.value })} className="w-full bg-card border border-border/60 rounded-xl px-3 py-2 text-sm">
                    {WARDS.map(w => <option key={w} value={w}>{w}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-foreground mb-1">Bed Type *</label>
                  <select value={form.bedType} onChange={e => setForm({ ...form, bedType: e.target.value })} className="w-full bg-card border border-border/60 rounded-xl px-3 py-2 text-sm">
                    {BED_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-foreground mb-1">Daily Rate (₹) *</label>
                  <Input value={form.dailyRate} onChange={e => setForm({ ...form, dailyRate: e.target.value })} placeholder="e.g. 1500" type="number" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-foreground mb-1">Floor</label>
                  <Input value={form.floor} onChange={e => setForm({ ...form, floor: e.target.value })} placeholder="e.g. 2nd Floor" />
                </div>
              </div>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.isAC} onChange={e => setForm({ ...form, isAC: e.target.checked })} className="rounded border-border/60" />
                <span className="text-sm text-foreground">AC Room</span>
                <Snowflake className="w-3.5 h-3.5 text-blue-500" />
              </label>
              <Button className="w-full gap-2" onClick={handleSave} disabled={!form.bedNumber || !form.dailyRate}>
                <Save className="w-4 h-4" /> {editId ? 'Update Bed' : 'Add Bed'}
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  Save, Loader2, Building2, Phone, Mail, MapPin, Clock, Image, Plus, X,
  CheckCircle2, Globe, Shield, FileText, MessageSquare, Video, AlertTriangle,
  Ambulance, ShieldCheck, CheckSquare, Home,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { Unmodelled } from '@/lib/apiTypes';

const DAY_LABELS: Unmodelled = { monday:'Monday', tuesday:'Tuesday', wednesday:'Wednesday', thursday:'Thursday', friday:'Friday', saturday:'Saturday', sunday:'Sunday' };

export default function AdminClinicSettings() {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    state: '',
    pincode: '',
    licenseNumber: '',
    description: '',
    website: '',
    logo: '',
    image: '',
    establishedYear: '',
    specialties: [],
    accreditations: [],
    timing: { monday:'9:00 AM - 6:00 PM', tuesday:'9:00 AM - 6:00 PM', wednesday:'9:00 AM - 6:00 PM', thursday:'9:00 AM - 6:00 PM', friday:'9:00 AM - 6:00 PM', saturday:'9:00 AM - 2:00 PM', sunday:'Closed' },
    amenities: { parking: false, acWaitingArea: false, wheelchairAccess: false, cardPayment: false, inHousePharmacy: false, drinkingWater: false, wifi: false, homeVisit: false },
    insurance: [],
    socialLinks: { facebook: '', instagram: '', youtube: '' },
    appointmentModes: ['chat', 'video', 'offline'],
    emergencySupport: false,
    emergency24x7: false,
    ambulanceService: false,
    refundOnMissedOrCancelled: true,
  });

  useEffect(() => {
    const load = async () => {
      try {
        const f = await api.getMyFacility();
        setForm({
          name: f.name || '',
          email: f.email || '',
          phone: f.phone || '',
          address: f.address || '',
          city: f.city || '',
          state: f.state || '',
          pincode: f.pincode || '',
          licenseNumber: f.licenseNumber || '',
          description: f.description || '',
          website: f.details?.website || f.website || '',
          logo: f.logo || '',
          image: f.image || '',
          establishedYear: f.establishedYear || '',
          specialties: f.specialties || [],
          accreditations: f.accreditations || [],
          timing: f.timing || { monday:'9:00 AM - 6:00 PM', tuesday:'9:00 AM - 6:00 PM', wednesday:'9:00 AM - 6:00 PM', thursday:'9:00 AM - 6:00 PM', friday:'9:00 AM - 6:00 PM', saturday:'9:00 AM - 2:00 PM', sunday:'Closed' },
          amenities: f.amenities || { parking: false, acWaitingArea: false, wheelchairAccess: false, cardPayment: false, inHousePharmacy: false, drinkingWater: false, wifi: false, homeVisit: false },
          insurance: f.details?.insurance || [],
          socialLinks: f.socialLinks || { facebook: '', instagram: '', youtube: '' },
          appointmentModes: f.appointmentModes || ['chat', 'video', 'offline'],
          emergencySupport: Boolean(f.emergencySupport || f.emergency24x7),
          emergency24x7: Boolean(f.emergency24x7 || f.emergencySupport),
          ambulanceService: Boolean(f.ambulanceService),
          refundOnMissedOrCancelled: f.refundOnMissedOrCancelled !== false,
        });
      } catch (e: any) {
        console.error(e);
        toast.error('Failed to load clinic data');
      }
      setLoading(false);
    };
    load();
  }, []);

  const update = (k: Unmodelled, v: Unmodelled) => setForm(p => ({ ...p, [k]: v }));

  const toggleMode = (mode: Unmodelled) => {
    const current = form.appointmentModes || [];
    if (current.includes(mode)) {
      if (current.length === 1) {
        toast.warning('At least one consultation mode must remain enabled');
        return;
      }
      update('appointmentModes', current.filter(m => m !== mode));
    } else {
      update('appointmentModes', [...current, mode]);
    }
  };

  const addSpecialty = () => {
    const v = prompt('Enter specialty (e.g. General Medicine, Pediatrics):');
    if (v) update('specialties', [...form.specialties, v.trim()]);
  };

  const addAccreditation = () => {
    const v = prompt('Enter accreditation (e.g. NABH, ISO):');
    if (v) update('accreditations', [...form.accreditations, v.trim().toUpperCase()]);
  };

  const addInsurance = () => {
    const v = prompt('Enter insurance provider name:');
    if (v) update('insurance', [...form.insurance, v.trim()]);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const f = await api.getMyFacility();
      await api.updateFacility(f._id, {
        ...form,
        establishedYear: form.establishedYear ? Number(form.establishedYear) : undefined,
        emergency24x7: form.emergencySupport,
        emergencySupport: form.emergencySupport,
        details: { ...(f.details || {}), website: form.website, insurance: form.insurance },
      });
      toast.success('Clinic settings updated successfully');
    } catch (e: any) {
      toast.error(e.message || 'Failed to update settings');
    }
    setSaving(false);
  };

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin text-primary" /></div>;

  return (
    <div className="max-w-3xl mx-auto space-y-8 py-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Clinic Settings</h1>
          <p className="text-muted-foreground text-sm">Manage your clinic profile, consultation modes, emergency policies, and services</p>
        </div>
        <Button size="default" onClick={handleSave} disabled={saving} className="gap-2 shrink-0">
          {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
          {saving ? 'Saving...' : 'Save Settings'}
        </Button>
      </div>

      {/* Modes of Appointment */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CheckSquare className="w-5 h-5 text-primary" /> Modes of Appointment You Provide
          </CardTitle>
          <CardDescription>Select all consultation modes your clinic offers to patients</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
            <div
              onClick={() => toggleMode('offline')}
              className={`p-3.5 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3 select-none ${
                form.appointmentModes?.includes('offline') ? 'border-violet-500 bg-violet-500/5' : 'border-border/60 hover:border-border'
              }`}
            >
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${form.appointmentModes?.includes('offline') ? 'bg-violet-500 text-white' : 'bg-muted text-muted-foreground'}`}>
                <Building2 className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <span className="font-semibold text-sm text-foreground block">In Clinic</span>
                <span className="text-[11px] text-muted-foreground">Physical clinic visit</span>
              </div>
              <input type="checkbox" checked={form.appointmentModes?.includes('offline')} readOnly className="rounded text-primary mt-1 pointer-events-none" />
            </div>

            <div
              onClick={() => toggleMode('home_visit')}
              className={`p-3.5 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3 select-none ${
                (form.appointmentModes?.includes('home_visit') || form.appointmentModes?.includes('home')) ? 'border-amber-500 bg-amber-500/5' : 'border-border/60 hover:border-border'
              }`}
            >
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${(form.appointmentModes?.includes('home_visit') || form.appointmentModes?.includes('home')) ? 'bg-amber-500 text-white' : 'bg-muted text-muted-foreground'}`}>
                <Home className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <span className="font-semibold text-sm text-foreground block">Home Visit</span>
                <span className="text-[11px] text-muted-foreground">Doctor at patient home</span>
              </div>
              <input type="checkbox" checked={(form.appointmentModes?.includes('home_visit') || form.appointmentModes?.includes('home'))} readOnly className="rounded text-primary mt-1 pointer-events-none" />
            </div>

            <div
              onClick={() => toggleMode('video')}
              className={`p-3.5 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3 select-none ${
                form.appointmentModes?.includes('video') ? 'border-emerald-500 bg-emerald-500/5' : 'border-border/60 hover:border-border'
              }`}
            >
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${form.appointmentModes?.includes('video') ? 'bg-emerald-500 text-white' : 'bg-muted text-muted-foreground'}`}>
                <Video className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <span className="font-semibold text-sm text-foreground block">Video Call</span>
                <span className="text-[11px] text-muted-foreground">Virtual video consult</span>
              </div>
              <input type="checkbox" checked={form.appointmentModes?.includes('video')} readOnly className="rounded text-primary mt-1 pointer-events-none" />
            </div>

            <div
              onClick={() => toggleMode('audio')}
              className={`p-3.5 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3 select-none ${
                form.appointmentModes?.includes('audio') ? 'border-teal-500 bg-teal-500/5' : 'border-border/60 hover:border-border'
              }`}
            >
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${form.appointmentModes?.includes('audio') ? 'bg-teal-500 text-white' : 'bg-muted text-muted-foreground'}`}>
                <Phone className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <span className="font-semibold text-sm text-foreground block">Audio Call</span>
                <span className="text-[11px] text-muted-foreground">Direct voice consult</span>
              </div>
              <input type="checkbox" checked={form.appointmentModes?.includes('audio')} readOnly className="rounded text-primary mt-1 pointer-events-none" />
            </div>

            <div
              onClick={() => toggleMode('chat')}
              className={`p-3.5 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3 select-none ${
                form.appointmentModes?.includes('chat') ? 'border-blue-500 bg-blue-500/5' : 'border-border/60 hover:border-border'
              }`}
            >
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${form.appointmentModes?.includes('chat') ? 'bg-blue-500 text-white' : 'bg-muted text-muted-foreground'}`}>
                <MessageSquare className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <span className="font-semibold text-sm text-foreground block">Online Chat</span>
                <span className="text-[11px] text-muted-foreground">Digital messaging</span>
              </div>
              <input type="checkbox" checked={form.appointmentModes?.includes('chat')} readOnly className="rounded text-primary mt-1 pointer-events-none" />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Emergency & Refund Policies */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ShieldCheck className="w-5 h-5 text-primary" /> Emergency Support &amp; Refund Policy
          </CardTitle>
          <CardDescription>Configure emergency availability, ambulance services, and cancellation refund guarantee</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Emergency Support Toggle */}
          <label className="flex items-start gap-3 p-3.5 rounded-xl border border-border/60 hover:bg-muted/30 cursor-pointer transition-colors">
            <input
              type="checkbox"
              checked={form.emergencySupport}
              onChange={e => {
                update('emergencySupport', e.target.checked);
                update('emergency24x7', e.target.checked);
              }}
              className="w-4 h-4 rounded border-border text-primary focus:ring-primary mt-0.5 cursor-pointer"
            />
            <div>
              <span className="font-semibold text-sm text-foreground flex items-center gap-1.5">
                <AlertTriangle className="w-4 h-4 text-destructive" /> Are you provide emergency support?
              </span>
              <p className="text-xs text-muted-foreground mt-0.5">
                Displays the 24x7 Emergency Care badge on your clinic profile and enables emergency queue handling.
              </p>
            </div>
          </label>

          {/* Ambulance Service Toggle */}
          <label className="flex items-start gap-3 p-3.5 rounded-xl border border-border/60 hover:bg-muted/30 cursor-pointer transition-colors">
            <input
              type="checkbox"
              checked={form.ambulanceService}
              onChange={e => update('ambulanceService', e.target.checked)}
              className="w-4 h-4 rounded border-border text-primary focus:ring-primary mt-0.5 cursor-pointer"
            />
            <div>
              <span className="font-semibold text-sm text-foreground flex items-center gap-1.5">
                <Ambulance className="w-4 h-4 text-blue-600" /> Are you provide ambulance service?
              </span>
              <p className="text-xs text-muted-foreground mt-0.5">
                Lists your clinic with active emergency ambulance support for nearby patients.
              </p>
            </div>
          </label>

          {/* Refund Support Toggle */}
          <label className="flex items-start gap-3 p-3.5 rounded-xl border border-border/60 hover:bg-muted/30 cursor-pointer transition-colors">
            <input
              type="checkbox"
              checked={form.refundOnMissedOrCancelled}
              onChange={e => update('refundOnMissedOrCancelled', e.target.checked)}
              className="w-4 h-4 rounded border-border text-primary focus:ring-primary mt-0.5 cursor-pointer"
            />
            <div>
              <span className="font-semibold text-sm text-foreground flex items-center gap-1.5">
                <ShieldCheck className="w-4 h-4 text-emerald-600" /> Are you support refund when the appointment is missed and cancelled by patient?
              </span>
              <p className="text-xs text-muted-foreground mt-0.5">
                Enables the 100% Refund Guarantee badge on your clinic profile and streamlines automatic refunds.
              </p>
            </div>
          </label>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Building2 className="w-5 h-5" /> Basic Information</CardTitle><CardDescription>Clinic name, contact details, and description</CardDescription></CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><Label>Clinic Name</Label><Input value={form.name} onChange={e => update('name', e.target.value)} placeholder="Enter clinic name" /></div>
            <div className="space-y-2"><Label>Established Year</Label><Input type="number" value={form.establishedYear} onChange={e => update('establishedYear', e.target.value)} placeholder="e.g. 2010" /></div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><Label><Phone className="w-3 h-3 inline mr-1" /> Phone</Label><Input value={form.phone} onChange={e => update('phone', e.target.value)} placeholder="+1 234 567 8900" /></div>
            <div className="space-y-2"><Label><Mail className="w-3 h-3 inline mr-1" /> Email</Label><Input value={form.email} onChange={e => update('email', e.target.value)} placeholder="clinic@email.com" /></div>
          </div>
          <div className="space-y-2"><Label><MapPin className="w-3 h-3 inline mr-1" /> Address</Label><Input value={form.address} onChange={e => update('address', e.target.value)} placeholder="Full address" /></div>
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2"><Label>City</Label><Input value={form.city} onChange={e => update('city', e.target.value)} placeholder="Enter city" /></div>
            <div className="space-y-2"><Label>State</Label><Input value={form.state} onChange={e => update('state', e.target.value)} placeholder="Enter state" /></div>
            <div className="space-y-2"><Label>Pincode</Label><Input value={form.pincode} onChange={e => update('pincode', e.target.value)} placeholder="Pincode" /></div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><Label><FileText className="w-3 h-3 inline mr-1" /> License Number</Label><Input value={form.licenseNumber} onChange={e => update('licenseNumber', e.target.value)} placeholder="License / registration number" /></div>
            <div className="space-y-2"><Label><Globe className="w-3 h-3 inline mr-1" /> Website</Label><Input value={form.website} onChange={e => update('website', e.target.value)} placeholder="https://" /></div>
          </div>
          <div className="space-y-2"><Label>Description</Label><Textarea rows={3} value={form.description} onChange={e => update('description', e.target.value)} placeholder="Brief description about your clinic" /></div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Image className="w-5 h-5" /> Images & Logo</CardTitle></CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2"><Label>Logo URL</Label><Input value={form.logo} onChange={e => update('logo', e.target.value)} placeholder="https://..." /></div>
          <div className="space-y-2"><Label>Cover Image URL</Label><Input value={form.image} onChange={e => update('image', e.target.value)} placeholder="https://..." /></div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Clock className="w-5 h-5" /> Working Hours</CardTitle><CardDescription>Set per-day opening hours</CardDescription></CardHeader>
        <CardContent className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {Object.keys(DAY_LABELS).map(day => (
            <div key={day} className="space-y-1">
              <Label className="text-xs capitalize">{DAY_LABELS[day]}</Label>
              <Input value={(form as Unmodelled).timing?.[day] || ''} onChange={e => update('timing', { ...form.timing, [day]: e.target.value })} placeholder="9AM-6PM" className="h-8 text-xs" />
            </div>
          ))}
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><CheckCircle2 className="w-5 h-5" /> Specialties & Accreditations</CardTitle></CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2">
            <div className="flex items-center justify-between"><Label>Specialties</Label><Button variant="outline" size="sm" onClick={addSpecialty}><Plus className="w-3 h-3 mr-1" /> Add</Button></div>
            <div className="flex flex-wrap gap-2">
              {form.specialties?.map((s, i) => (
                <span key={i} className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium bg-blue-50 text-blue-700 border border-blue-200">
                  {s}
