                  <Button
                    size="sm"
                    className="flex-1 text-xs bg-red-600 hover:bg-red-700 text-white"
                    onClick={() => {
                      toast.success(`ICU/Emergency Bed Request dispatched for ${selectedCase.patientName || 'Patient'}`);
