    ambulanceService: false,
    refundOnMissedOrCancelled: true,
    icuTotal: 0,
    icuAvailable: 0,
    refundRule: '100_4h',
    autoRefund: true,
    ipdGenWard: '',
    ipdSemiPrivate: '',
    ipdIcu: '',
    opdFeeFloor: '500',
