import { useState, useEffect } from 'react';
import { Save, Loader2, Building2, Phone, Mail, MapPin, Clock, Image, Plus, X, CheckCircle2, Globe, Pill, Truck, CreditCard } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function AdminPharmacySettings() {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState<ApiRow>({});

  useEffect(() => {
    const load = async () => {
      try {
        const f = await api.getMyFacility();
        setForm({
          name: f.name || '',
          email: f.email || '',
          phone: f.phone || '',
          address: f.address || '',
          city: f.city || '',
          state: f.state || '',
          description: f.description || '',
          logo: f.logo || '',
          image: f.image || '',
          establishedYear: f.establishedYear || '',
pincode: f.pincode || '',
           licenseNumber: f.licenseNumber || '',
           website: f.details?.website || f.website || '',
          workingHours: f.workingHours || '8:00 AM - 10:00 PM',
          accreditations: f.accreditations || [],
          amenities: f.amenities || { parking: false, acWaitingArea: false, wheelchairAccess: false, cardPayment: false, homeDelivery: false, prescriptionUpload: false },
          socialLinks: f.socialLinks || { facebook: '', instagram: '', youtube: '' },
          // §9 pharmacy ops master lives under details.pharmacyOps (free object, no schema change).
          pharmacyOps: {
            nightDelivery: false, returnRules: 'intact_48h', deliveryBase: '', freeFloor: '',
            nightSurcharge: '', maxGeofenceKm: '5', drugLicense20: '', drugLicense21: '', drugLicenseExpiry: '',
            pharmacistName: '', pharmacistRegNo: '', pharmacistCouncil: '',
            bankHolder: '', bankAccount: '', bankIfsc: '', gstin: '',
            ...(f.details?.pharmacyOps || {}),
          },
        });
      } catch (e: any) { console.error(e); toast.error('Failed to load pharmacy data'); }
      setLoading(false);
    };
    load();
  }, []);

  const update = (k: Unmodelled, v: Unmodelled) => setForm(p => ({ ...p, [k]: v }));

  const addAccreditation = () => {
    const v = prompt('Enter accreditation:');
    if (v) update('accreditations', [...form.accreditations, v.trim().toUpperCase()]);
  };

  const setOps = (k: Unmodelled, v: Unmodelled) => setForm(p => ({ ...p, pharmacyOps: { ...p.pharmacyOps, [k]: v } }));

  const handleSave = async () => {
    setSaving(true);
    try {
      const f = await api.getMyFacility();
      const { pharmacyOps, ...rest } = form;
      await api.updateFacility(f._id, {
        ...rest,
        establishedYear: form.establishedYear ? Number(form.establishedYear) : undefined,
        details: { ...(f.details || {}), pharmacyOps: {
          ...pharmacyOps,
          deliveryBase: Number(pharmacyOps.deliveryBase) || 0,
          freeFloor: Number(pharmacyOps.freeFloor) || 0,
          nightSurcharge: Number(pharmacyOps.nightSurcharge) || 0,
          maxGeofenceKm: Number(pharmacyOps.maxGeofenceKm) || 0,
        } },
      });
      toast.success('Pharmacy settings updated successfully');
    } catch (e: any) { toast.error(e.message || 'Failed to update'); }
    setSaving(false);
  };

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin text-primary" /></div>;

  return (
    <div className="max-w-3xl mx-auto space-y-8 py-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Pharmacy Settings</h1>
        <p className="text-muted-foreground">Manage your pharmacy profile, license, and delivery info</p>
      </div>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Building2 className="w-5 h-5" /> Basic Information</CardTitle></CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><Label>Pharmacy Name</Label><Input value={form.name} onChange={e => update('name', e.target.value)} placeholder="Enter pharmacy name" /></div>
            <div className="space-y-2"><Label>Established Year</Label><Input type="number" value={form.establishedYear} onChange={e => update('establishedYear', e.target.value)} placeholder="e.g. 2015" /></div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><Label><Phone className="w-3 h-3 inline mr-1" /> Phone</Label><Input value={form.phone} onChange={e => update('phone', e.target.value)} placeholder="+1 234 567 8900" /></div>
            <div className="space-y-2"><Label><Mail className="w-3 h-3 inline mr-1" /> Email</Label><Input value={form.email} onChange={e => update('email', e.target.value)} placeholder="pharmacy@email.com" /></div>
          </div>
          <div className="space-y-2"><Label><MapPin className="w-3 h-3 inline mr-1" /> Address</Label><Input value={form.address} onChange={e => update('address', e.target.value)} placeholder="Full address" /></div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><Label>City</Label><Input value={form.city} onChange={e => update('city', e.target.value)} placeholder="Enter city" /></div>
            <div className="space-y-2"><Label>State</Label><Input value={form.state} onChange={e => update('state', e.target.value)} placeholder="Enter state" /></div>
          </div>
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2"><Label>Pincode</Label><Input value={form.pincode} onChange={e => update('pincode', e.target.value)} placeholder="e.g. 400001" /></div>
            <div className="space-y-2"><Label>License Number</Label><Input value={form.licenseNumber} onChange={e => update('licenseNumber', e.target.value)} placeholder="e.g. MP-PH-2023-00781" /></div>
            <div className="space-y-2"><Label><Globe className="w-3 h-3 inline mr-1" /> Website</Label><Input value={form.website} onChange={e => update('website', e.target.value)} placeholder="https://pharmacy.com" /></div>
          </div>
          <div className="space-y-2"><Label>Description</Label><Textarea rows={3} value={form.description} onChange={e => update('description', e.target.value)} placeholder="Brief description about your pharmacy" /></div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Image className="w-5 h-5" /> Images & Logo</CardTitle></CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2"><Label>Logo URL</Label><Input value={form.logo} onChange={e => update('logo', e.target.value)} placeholder="https://..." /></div>
          <div className="space-y-2"><Label>Cover Image URL</Label><Input value={form.image} onChange={e => update('image', e.target.value)} placeholder="https://..." /></div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Pill className="w-5 h-5" /> Accreditations</CardTitle></CardHeader>
        <CardContent className="space-y-3">
          <div className="space-y-2">
            <div className="flex items-center justify-between"><Label>Accreditations</Label><Button variant="outline" size="sm" onClick={addAccreditation}><Plus className="w-3 h-3 mr-1" /> Add</Button></div>
            <div className="flex flex-wrap gap-2">
              {form.accreditations?.map((a: Unmodelled, i: Unmodelled) => (
                <span key={i} className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200">
                  <CheckCircle2 className="w-3 h-3" /> {a}
                  <button onClick={() => update('accreditations', form.accreditations.filter((_: Unmodelled, j: Unmodelled) => j !== i))}><X className="w-3 h-3 ml-1 hover:text-destructive" /></button>
                </span>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Clock className="w-5 h-5" /> Working Hours</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          <Label>Hours</Label>
          <Input value={form.workingHours} onChange={e => update('workingHours', e.target.value)} placeholder="e.g. 8:00 AM - 10:00 PM" />
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Truck className="w-5 h-5" /> Amenities & Delivery</CardTitle></CardHeader>
        <CardContent className="grid grid-cols-2 gap-4">
          {Object.entries({ parking: 'Parking', acWaitingArea: 'AC Waiting Area', wheelchairAccess: 'Wheelchair Access', cardPayment: 'Card/UPI Payment', homeDelivery: 'Home Delivery', prescriptionUpload: 'Prescription Upload' }).map(([k, lbl]) => (
            <label key={k} className="flex items-center gap-2 text-sm">
              <input type="checkbox" checked={form.amenities?.[k] || false} onChange={e => update('amenities', { ...form.amenities, [k]: e.target.checked })} className="rounded border-border" />
              {lbl}
            </label>
          ))}
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Globe className="w-5 h-5" /> Social Links</CardTitle></CardHeader>
        <CardContent className="space-y-3">
          {['facebook', 'instagram', 'youtube'].map(s => (
            <div key={s} className="space-y-1">
              <Label className="capitalize">{s}</Label>
              <Input value={form.socialLinks?.[s] || ''} onChange={e => update('socialLinks', { ...form.socialLinks, [s]: e.target.value })} placeholder={`https://${s}.com/...`} />
            </div>
          ))}
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="flex items-center gap-2"><Truck className="w-5 h-5" /> Operations Master (§9)</CardTitle></CardHeader>
        <CardContent className="space-y-4">
