              {selectedRx.clinicalNotes && (
                <div className="mb-6">
                  <p className="text-xs text-muted-foreground mb-1">Clinical Notes</p>
                  <div className="p-3 bg-muted/20 rounded-xl text-sm">{selectedRx.clinicalNotes}</div>
