                      <ShieldCheck className="w-4 h-4 mr-1" /> Verify
                    </Button>
                    <Button size="sm" variant={actionType === 'reject' ? 'default' : 'outline'}
                      className={actionType === 'reject' ? 'bg-destructive hover:bg-destructive/90' : ''}
                      onClick={() => setActionType('reject')}>
                      <ShieldX className="w-4 h-4 mr-1" /> Reject
                    </Button>
                  </div>
                  <Textarea
                    value={verifyNotes}
                    onChange={e => setVerifyNotes(e.target.value)}
                    placeholder={actionType === 'verify' ? 'Add verification notes (optional)...' : 'Enter rejection reason...'}
                    className="w-full"
                    rows={3}
                  />
                </div>
              )}

              <div className="flex gap-3">
                <Button variant="outline" className="flex-1" onClick={() => setSelectedRx(null)}>Close</Button>
                {selectedRx.verificationStatus === 'pending' && (
                  <Button
                    className={actionType === 'verify' ? 'bg-success hover:bg-success/90' : 'bg-destructive hover:bg-destructive/90'}
                    onClick={handleVerify}
                  >
                    {actionType === 'verify' ? <><ShieldCheck className="w-4 h-4 mr-1" /> Verify Prescription</> : <><ShieldX className="w-4 h-4 mr-1" /> Reject Prescription</>}
                  </Button>
                )}
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Search, Clock, ArrowLeft, CalendarClock, AlertTriangle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import ClinicSchedule from '@/pages/clinic/ClinicSchedule';
import ScheduleChangeRequestModal from '@/components/ScheduleChangeRequestModal';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function AdminScheduleManage() {
  const [doctors, setDoctors] = useState<ApiRow[]>([]);
  const [search, setSearch] = useState('');
  const [specialization, setSpecialization] = useState('All');
  const [loading, setLoading] = useState(true);
  // Selected doctor for editing schedule (null = show list view)
  const [selectedDoctor, setSelectedDoctor] = useState<Unmodelled>(null);
  // Pending schedule change requests keyed by doctorId
  const [pendingRequests, setPendingRequests] = useState<ApiRow>({});
  // Modal state
  const [modalRequest, setModalRequest] = useState<Unmodelled>(null);
  const [modalDoctor, setModalDoctor] = useState<Unmodelled>(null);

  // Load doctors
  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const data = await api.getDoctors({ search, includeAll: 'true' });
        setDoctors(data?.data || data || []);
      } catch (e: any) {
        console.error(e);
      }
      setLoading(false);
    };
    const t = setTimeout(load, 300); // debounce search
    return () => clearTimeout(t);
  }, [search]);

  // Load pending schedule change requests
  useEffect(() => {
    const loadPending = async () => {
      try {
        const res = await api.getPendingScheduleChangeRequests();
        const requests = res?.requests || res || [];
        const map: Unmodelled = {};
        requests.forEach((r: Unmodelled) => {
          // Use the populated doctorId._id or the stored doctorId — normalize to string
          const docId = r.doctorId?._id || r.doctorId;
          if (docId) map[String(docId)] = r;
        });
        setPendingRequests(map);
      } catch (e: any) {
        console.error(e);
      }
    };
    loadPending();
  }, []);

  // If a doctor is selected, render the schedule editor (reuse ClinicSchedule in admin mode)
  if (selectedDoctor) {
    return <ClinicSchedule {...({ adminMode: true, doctorId: selectedDoctor._id } as Unmodelled)} />;
  }

  // Derive unique specializations for filter dropdown
  const specs = ['All', ...Array.from(new Set(doctors.map(d => d.specialization).filter(Boolean)))];

  const filtered = specialization === 'All'
    ? doctors
    : doctors.filter(d => d.specialization === specialization);

  const handleCardClick = (doc: Unmodelled) => {
    // If there's a pending request for this doctor, open the modal instead
    const pending = pendingRequests[String(doc._id)];
    if (pending) {
      // Prefer the populated doctor snapshot from the request (always fresh), fallback to list doc
      const reqDoctor = pending.doctorId && typeof pending.doctorId === 'object' ? pending.doctorId : doc;
      setModalDoctor({ ...doc, ...reqDoctor });
      setModalRequest(pending);
    } else {
      setSelectedDoctor(doc);
    }
  };

  const handleDecision = (requestId: Unmodelled, decision: Unmodelled) => {
    // Remove from pending map
    setPendingRequests(prev => {
      const next: Unmodelled = { ...prev };
      // Remove by matching requestId value
      Object.keys(next).forEach(k => {
        if (String(next[k]._id) === String(requestId)) delete next[k];
      });
      return next;
    });
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Manage Doctor Schedules</h1>
        <p className="text-muted-foreground">Click any doctor to edit their working hours, time slots, breaks & booking rules</p>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search doctor name or specialization..." className="pl-10" />
        </div>
        <select value={specialization} onChange={e => setSpecialization(e.target.value)}
          className="px-3 py-2 rounded-lg border border-border bg-background text-sm sm:min-w-[200px]">
          {specs.map(s => <option key={s} value={s}>{s}</option>)}
        </select>
      </div>

      {/* Doctor Cards Grid */}
      {loading ? (
        <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          <CalendarClock className="w-12 h-12 mx-auto mb-3 text-muted-foreground/30" />
          <p>No doctors found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((doc, i) => {
            const hasPending = !!pendingRequests[String(doc._id)];
            return (
              <motion.button
                key={doc._id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.04 }}
                onClick={() => handleCardClick(doc)}
                className={`text-left bg-card rounded-2xl border p-5 hover:shadow-lg transition-all cursor-pointer group ${
                  hasPending ? 'border-amber-400/60 hover:border-amber-400' : 'border-border/60 hover:border-primary/40'
                }`}
              >
                <div className="flex items-start gap-3 mb-4">
                  <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center text-primary-foreground font-bold text-lg flex-shrink-0 overflow-hidden">
                    {doc.profile_photo
                      ? <img src={doc.profile_photo} alt="" className="w-full h-full object-cover" />
                      : doc.initials || doc.name?.split(' ').map((n: Unmodelled) => n[0]).join('').slice(0, 2)}
                  </div>
                  <div className="min-w-0 flex-1">
                    <h3 className="font-heading font-semibold text-foreground truncate">{doc.name}</h3>
                    <p className="text-sm text-primary font-medium">{doc.specialization}</p>
                  </div>
                  <Badge variant={doc.available ? 'default' : 'secondary'} className="text-[10px]">
                    {doc.available ? 'Available' : 'Off'}
                  </Badge>
                </div>

                <div className="grid grid-cols-2 gap-2 text-xs">
                  <div className="bg-muted/30 rounded-lg p-2">
                    <p className="text-muted-foreground text-[10px]">Slot Duration</p>
                    <p className="font-semibold text-foreground">{doc.slotDuration || 15} min</p>
                  </div>
                  <div className="bg-muted/30 rounded-lg p-2">
                    <p className="text-muted-foreground text-[10px]">Working Hours</p>
                    <p className="font-semibold text-foreground">
                      {doc.workingHours ? `${doc.workingHours.start}–${doc.workingHours.end}` : '9–5'}
                    </p>
                  </div>
                  <div className="bg-muted/30 rounded-lg p-2">
                    <p className="text-muted-foreground text-[10px]">Total Slots</p>
                    <p className="font-semibold text-foreground">{doc.time_slots?.length || 0}</p>
                  </div>
                  <div className="bg-muted/30 rounded-lg p-2">
                    <p className="text-muted-foreground text-[10px]">Booking Window</p>
                    <p className="font-semibold text-foreground">
                      {doc.bookingWindow ? `${doc.bookingWindow.value} ${doc.bookingWindow.unit}` : '2 weeks'}
                    </p>
                  </div>
                </div>

                <div className="mt-4 flex items-center justify-between">
                  <span className="text-[11px] text-muted-foreground flex items-center gap-1">
                    <Clock className="w-3 h-3" /> {doc.experience || 'N/A'}
                  </span>
                  {hasPending ? (
                    <span className="text-xs font-medium text-amber-600 dark:text-amber-400 flex items-center gap-1">
                      <AlertTriangle className="w-3 h-3" /> Review Request →
                    </span>
                  ) : (
                    <span className="text-xs font-medium text-primary group-hover:underline flex items-center gap-1">
                      Edit Schedule →
                    </span>
                  )}
                </div>

                {/* Pending request badge */}
                {hasPending && (
                  <div className="mt-3 flex items-center gap-2 px-3 py-1.5 rounded-lg bg-amber-50 dark:bg-amber-500/10 border border-amber-200 dark:border-amber-500/20">
                    <AlertTriangle className="w-3.5 h-3.5 text-amber-500 shrink-0" />
                    <span className="text-[11px] font-medium text-amber-700 dark:text-amber-400 truncate">
                      Request for Change — click to review
                    </span>
                  </div>
                )}
              </motion.button>
            );
          })}
        </div>
      )}

      {/* Schedule Change Request Modal */}
      {modalRequest && modalDoctor && (
        <ScheduleChangeRequestModal
          request={modalRequest}
          doctor={modalDoctor}
          onClose={() => { setModalRequest(null); setModalDoctor(null); }}
          onDecision={handleDecision}
        />
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Car,
  ShieldCheck,
  CheckCircle2,
  XCircle,
  Clock,
  Search,
  Filter,
  Eye,
  TrendingUp,
  IndianRupee,
  AlertTriangle,
  FileText,
  Users,
  Loader2,
  Ambulance,
  Bike,
  Truck,
  Zap,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { DataGrid } from '@/components/ui/System';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { Unmodelled } from '@/lib/apiTypes';

export default function AdminVehicleRides() {
  const [activeTab, setActiveTab] = useState<'pending' | 'riders' | 'vehicles' | 'rides' | 'analytics'>('pending');

  const [pendingRiders, setPendingRiders] = useState<any[]>([]);
  const [allRiders, setAllRiders] = useState<any[]>([]);
  const [allVehicles, setAllVehicles] = useState<any[]>([]);
  const [allRides, setAllRides] = useState<any[]>([]);
  const [analytics, setAnalytics] = useState<any>(null);
  const [loading, setLoading] = useState<boolean>(true);

  // Review modal state
  const [selectedRider, setSelectedRider] = useState<any>(null);
  const [rejectReason, setRejectReason] = useState<string>('');
  const [rejectModalOpen, setRejectModalOpen] = useState<boolean>(false);
  const [processingId, setProcessingId] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, [activeTab]);

  const loadData = async () => {
    setLoading(true);
    try {
      if (activeTab === 'pending') {
        const res = await api.getPendingRiders();
        setPendingRiders(res.riders || []);
      } else if (activeTab === 'riders') {
        const res = await api.getAdminRiders();
        setAllRiders(res.riders || []);
      } else if (activeTab === 'vehicles') {
        const res = await api.getAdminVehicles();
        setAllVehicles(res.vehicles || []);
      } else if (activeTab === 'rides') {
        const res = await api.getAdminRides();
        setAllRides(res.rides || []);
      } else if (activeTab === 'analytics') {
        const res = await api.getRideAnalytics();
        setAnalytics(res || null);
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to load vehicle admin data');
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (riderId: string) => {
    setProcessingId(riderId);
    try {
      await api.approveRider(riderId);
      toast.success('Rider approved! Driver account activated.');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to approve rider');
    } finally {
      setProcessingId(null);
    }
  };

  const handleReject = async () => {
    if (!selectedRider?._id) return;
    setProcessingId(selectedRider._id);
    try {
      await api.rejectRider(selectedRider._id, rejectReason || 'Documents insufficient or invalid');
      toast.info('Rider application rejected');
      setRejectModalOpen(false);
      setSelectedRider(null);
      setRejectReason('');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to reject rider');
    } finally {
      setProcessingId(null);
    }
  };

  const handleSuspendToggle = async (riderId: string, currentlyActive: boolean) => {
    try {
      await api.suspendRider(riderId, currentlyActive);
      toast.success(`Rider ${currentlyActive ? 'suspended' : 'reactivated'}`);
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update rider status');
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-16">
      <div>
        <h1 className="text-2xl sm:text-3xl font-heading font-extrabold text-foreground flex items-center gap-2">
          <span className="p-1.5 rounded-xl bg-primary/10 text-primary">🚗</span>
          Vehicle & Ride Management
        </h1>
        <p className="text-xs sm:text-sm text-muted-foreground mt-0.5">
          Driver onboarding verification, registered vehicle tracking, live ride oversight, and fleet analytics.
        </p>
      </div>

      <div className="rounded-2xl border p-4 flex flex-wrap items-center justify-between gap-3">
        <p className="text-xs text-muted-foreground">Live GPS map: textual lat/long + ETA shown per ride. Open in Maps for turn-by-turn.</p>
        <a href="https://www.google.com/maps" target="_blank" rel="noreferrer" className="text-xs font-semibold rounded-lg border px-3 py-1.5">Open Live Map</a>
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-1.5 border-b border-border/80 pb-1 overflow-x-auto">
        {[
          { id: 'pending', label: 'Rider Approvals', icon: ShieldCheck, badge: pendingRiders.length },
          { id: 'riders', label: 'All Drivers', icon: Users },
          { id: 'vehicles', label: 'Registered Vehicles', icon: Car },
          { id: 'rides', label: 'Rides Oversight', icon: Clock },
          { id: 'analytics', label: 'Fleet Analytics', icon: TrendingUp },
        ].map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-colors ${
                isActive
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
              }`}
            >
              <Icon className="w-4 h-4" />
              <span>{tab.label}</span>
              {tab.badge ? (
                <span className="px-1.5 py-0.2 rounded-full text-[10px] font-bold bg-destructive text-destructive-foreground">
                  {tab.badge}
                </span>
              ) : null}
            </button>
          );
        })}
      </div>

      {/* TAB 1: PENDING RIDER APPROVALS */}
      {activeTab === 'pending' && (
        <div className="space-y-4">
          {loading ? (
            <div className="py-16 text-center text-xs text-muted-foreground">
              <Loader2 className="w-6 h-6 animate-spin mx-auto text-primary mb-2" />
              Loading pending driver applications...
            </div>
          ) : pendingRiders.length === 0 ? (
            <div className="rounded-2xl border border-border/80 bg-card p-12 text-center space-y-2">
              <CheckCircle2 className="w-10 h-10 text-emerald-600 mx-auto" />
              <p className="font-bold text-sm text-foreground">All driver applications reviewed</p>
              <p className="text-xs text-muted-foreground">No drivers waiting in approval queue.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {pendingRiders.map((rider) => {
                const user = rider.userId || {};
                const vehicle = rider.vehicleId || {};

                return (
                  <div
                    key={rider._id}
                    className="rounded-2xl border border-border/80 bg-card p-5 shadow-sm space-y-4"
                  >
                    <div className="flex items-start justify-between">
                      <div>
                        <h4 className="font-bold text-base text-foreground">{user.name || 'Applicant'}</h4>
                        <p className="text-xs text-muted-foreground font-mono">{user.email} · {user.phone}</p>
                      </div>
                      <Badge variant="outline" className="text-[10px] uppercase font-bold text-amber-600 bg-amber-500/10 border-amber-500/30">
                        Pending Approval
                      </Badge>
                    </div>

                    <div className="grid grid-cols-2 gap-2 text-xs bg-muted/30 p-3 rounded-xl border">
                      <div>
                        <p className="text-[10px] text-muted-foreground">Vehicle</p>
                        <p className="font-semibold text-foreground capitalize">
                          {vehicle.type?.replace('_', ' ')} · {vehicle.brand} {vehicle.model}
                        </p>
                      </div>
                      <div>
                        <p className="text-[10px] text-muted-foreground">RC Number</p>
                        <p className="font-mono font-bold text-primary">{vehicle.rcNumber || 'N/A'}</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-muted-foreground">Driving License</p>
                        <p className="font-mono font-semibold text-foreground">
                          {rider.drivingLicenseNumber || 'N/A'}
                        </p>
                      </div>
                      <div>
                        <p className="text-[10px] text-muted-foreground">Govt ID ({rider.govtIdType})</p>
                        <p className="font-mono font-semibold text-foreground">
                          {rider.govtIdNumber || 'N/A'}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center justify-end gap-2 pt-1">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                          setSelectedRider(rider);
                          setRejectModalOpen(true);
                        }}
                        className="rounded-xl text-xs h-9 text-destructive border-destructive/30 hover:bg-destructive/10"
                      >
                        Reject
                      </Button>
                      <Button
                        size="sm"
                        onClick={() => handleApprove(rider._id)}
                        disabled={processingId === rider._id}
                        className="rounded-xl text-xs h-9 font-bold bg-emerald-600 hover:bg-emerald-700 text-white gap-1.5"
                      >
                        {processingId === rider._id ? (
                          <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        ) : (
                          <CheckCircle2 className="w-3.5 h-3.5" />
                        )}
                        Approve & Verify
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* TAB 2: ALL DRIVERS */}
      {activeTab === 'riders' && (
        <div className="rounded-2xl border border-border/80 bg-card overflow-hidden shadow-sm">
          <DataGrid
            columns={[
              {
                key: 'driver', label: 'Driver', sortable: false,
                render: (_v: Unmodelled, r: Unmodelled) => (
                  <>
                    <span className="font-medium text-foreground">{r.userId?.name || 'Driver'}</span>
                    <div className="text-[10px] text-muted-foreground">{r.userId?.phone}</div>
                  </>
                ),
              },
              { key: 'vehicle', label: 'Vehicle', sortable: false, render: (_v: Unmodelled, r: Unmodelled) => <span className="capitalize">{r.vehicleId?.type?.replace('_', ' ')} · {r.vehicleId?.rcNumber}</span> },
              { key: 'riderStatus', label: 'Status', sortable: false, render: (v: Unmodelled) => <Badge variant={v === 'active' ? 'default' : 'secondary'} className="text-[10px]">{v}</Badge> },
              { key: 'isOnline', label: 'Online', sortable: false, render: (v: Unmodelled) => <span className={`font-mono font-bold ${v ? 'text-emerald-600' : 'text-muted-foreground'}`}>{v ? 'Online' : 'Offline'}</span> },
              { key: 'rating', label: 'Rating', sortable: false, render: (v: Unmodelled) => <>⭐ {v?.avg || '5.0'}</> },
              { key: 'totalEarnings', label: 'Total Earned', sortable: false, render: (v: Unmodelled) => <span className="font-bold text-emerald-600">₹{v || 0}</span> },
              {
                key: '_actions', label: 'Action', sortable: false,
                render: (_v: Unmodelled, r: Unmodelled) => (
                  <Button variant="outline" size="sm" onClick={() => handleSuspendToggle(r._id, r.riderStatus === 'active')} className="text-[11px] h-7 rounded-lg">
                    {r.riderStatus === 'active' ? 'Suspend' : 'Activate'}
                  </Button>
                ),
              },
            ]}
            rows={allRiders}
            rowKey="_id"
            empty="No drivers registered yet"
            showSearch={false}
            manualPagination
          />
        </div>
      )}

      {/* TAB 3: REGISTERED VEHICLES */}
      {activeTab === 'vehicles' && (
        <div className="rounded-2xl border border-border/80 bg-card overflow-hidden shadow-sm">
          <DataGrid
            columns={[
              { key: 'rcNumber', label: 'RC Number', sortable: false, render: (v: Unmodelled) => <span className="font-mono font-bold text-primary">{v}</span> },
              { key: 'type', label: 'Type', sortable: false, render: (v: Unmodelled) => <span className="capitalize">{v?.replace('_', ' ')}</span> },
              { key: 'brand', label: 'Brand & Model', sortable: false, render: (_v: Unmodelled, v: Unmodelled) => <span className="font-medium text-foreground">{v.brand} {v.model}</span> },
              { key: 'fuelType', label: 'Fuel', sortable: false, render: (v: Unmodelled) => v || 'Petrol' },
              { key: 'capacity', label: 'Capacity', sortable: false, render: (v: Unmodelled) => `${v || 4} seats` },
              { key: 'isDocumentVerified', label: 'Doc Verified', sortable: false, render: (v: Unmodelled) => <Badge variant={v ? 'default' : 'secondary'}>{v ? 'Verified' : 'Pending'}</Badge> },
            ]}
            rows={allVehicles}
            rowKey="_id"
            empty="No vehicles registered yet"
            showSearch={false}
            manualPagination
          />
        </div>
      )}

      {/* TAB 4: RIDES OVERSIGHT */}
      {activeTab === 'rides' && (
        <div className="rounded-2xl border border-border/80 bg-card overflow-hidden shadow-sm">
          <DataGrid
            columns={[
              { key: 'bookingNumber', label: 'Booking #', sortable: false, render: (v: Unmodelled) => <span className="font-mono font-bold">{v}</span> },
              { key: 'createdAt', label: 'Date', sortable: false, render: (v: Unmodelled) => <span className="font-mono text-muted-foreground">{v ? new Date(v).toLocaleDateString('en-IN') : '—'}</span> },
              {
                key: 'vehicleType', label: 'Vehicle', sortable: false,
                render: (v: Unmodelled, r: Unmodelled) => (
                  <>
                    <span className="capitalize">{v?.replace('_', ' ')}</span>
                    {r.isEmergency && <span className="text-[9px] font-bold text-red-600 ml-1">EMERGENCY</span>}
                  </>
                ),
              },
              { key: 'passenger', label: 'Passenger', sortable: false, render: (_v: Unmodelled, r: Unmodelled) => r.userId?.name || 'Customer' },
              { key: 'riderId', label: 'Driver', sortable: false, render: (v: Unmodelled) => v?.name || '—' },
              { key: 'fare', label: 'Total Fare', sortable: false, render: (v: Unmodelled) => <span className="font-bold">₹{v?.total || 0}</span> },
              { key: 'status', label: 'Status', sortable: false, render: (v: Unmodelled) => <Badge variant={v === 'completed' ? 'default' : 'secondary'}>{v?.replace(/_/g, ' ')}</Badge> },
            ]}
            rows={allRides}
            rowKey="_id"
            empty="No rides recorded yet"
            showSearch={false}
            manualPagination
          />
        </div>
      )}

      {/* TAB 5: FLEET ANALYTICS */}
      {activeTab === 'analytics' && analytics && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
            <div className="p-4 rounded-2xl border bg-card shadow-sm">
              <p className="text-xs text-muted-foreground">Total Rides</p>
              <p className="text-2xl font-bold text-foreground mt-1">{analytics.totalRides || 0}</p>
            </div>
            <div className="p-4 rounded-2xl border bg-card shadow-sm">
              <p className="text-xs text-muted-foreground">Total Revenue</p>
              <p className="text-2xl font-bold text-emerald-600 mt-1">₹{analytics.totalRevenue || 0}</p>
            </div>
            <div className="p-4 rounded-2xl border bg-card shadow-sm">
              <p className="text-xs text-muted-foreground">Platform Commission (10%)</p>
              <p className="text-2xl font-bold text-primary mt-1">₹{analytics.platformRevenue || 0}</p>
            </div>
            <div className="p-4 rounded-2xl border bg-card shadow-sm">
              <p className="text-xs text-muted-foreground">Cancellation Rate</p>
              <p className="text-2xl font-bold text-destructive mt-1">{analytics.cancellationRate || 0}%</p>
            </div>
          </div>
        </div>
      )}

      {/* REJECT MODAL */}
      <Dialog open={rejectModalOpen} onOpenChange={setRejectModalOpen}>
        <DialogContent className="sm:max-w-md rounded-2xl p-6">
          <DialogHeader>
            <DialogTitle className="text-lg font-bold text-foreground">Reject Driver Application</DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              Provide a clear reason for the rejection so the driver can fix and re-upload documents.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-2">
            <Textarea
              value={rejectReason}
              onChange={(e) => setRejectReason(e.target.value)}
              placeholder="e.g. Expired driving license or blurry RC image..."
              rows={3}
              className="text-xs rounded-xl resize-none"
            />

            <div className="flex gap-2 justify-end pt-2">
              <Button variant="outline" onClick={() => setRejectModalOpen(false)} className="rounded-xl text-xs">
                Cancel
              </Button>
              <Button onClick={handleReject} className="rounded-xl text-xs font-bold bg-destructive text-destructive-foreground">
                Confirm Rejection
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useEffect, useState, useRef } from 'react';
