import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { 
  MapPin, Clock, CalendarDays, Activity, Search, 
  Map, User, Siren, ShieldCheck, ChevronRight
} from 'lucide-react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { userFacingError } from '@/lib/errorCopy';

const inr = (n: number) => `₹${Number(n || 0).toLocaleString('en-IN')}`;

export default function AmbulanceJobs() {
  const [jobs, setJobs] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all'); // all, completed, cancelled, active
  const LIMIT = 20;

  const load = async (p: number) => {
    setLoading(true);
    try {
      const r: any = await api.get(`/ambulance/me/jobs?page=${p}&limit=${LIMIT}`);
      setJobs(r.jobs || r.data || []);
      setTotal(r.total || r.count || 0);
      setPage(r.page || p);
    } catch (e: any) {
      toast.error(userFacingError(e, { fallback: 'Failed to load jobs' }));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(1); }, []);

  const filteredJobs = jobs.filter(j => {
    if (filter !== 'all' && j.status !== filter) return false;
    if (search) {
      const term = search.toLowerCase();
      const patient = (j.patientDetails?.name || '').toLowerCase();
      const address = (j.location?.address || '').toLowerCase();
      const id = (j._id || '').toLowerCase();
      return patient.includes(term) || address.includes(term) || id.includes(term);
    }
    return true;
  });

  const getStatusColor = (status: string) => {
    switch (status?.toLowerCase()) {
      case 'completed': return 'bg-emerald-500/10 text-emerald-600 border-emerald-200';
      case 'cancelled': return 'bg-rose-500/10 text-rose-600 border-rose-200';
      case 'active':
      case 'en_route':
      case 'arrived': return 'bg-blue-500/10 text-blue-600 border-blue-200 animate-pulse';
      default: return 'bg-gray-500/10 text-gray-600 border-gray-200';
    }
  };

  const maxPage = Math.max(1, Math.ceil(total / LIMIT));

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6 pb-20">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-foreground flex items-center gap-2">
            <Activity className="w-6 h-6 text-rose-500" />
            Job History
          </h2>
          <p className="text-sm text-muted-foreground mt-1">Review your past emergency dispatches and transfers.</p>
        </div>
        <Badge variant="outline" className="text-sm px-3 py-1">
          Total Jobs: {total}
        </Badge>
      </div>

      <div className="flex flex-col sm:flex-row gap-3 items-center">
        <div className="relative w-full sm:w-80 shrink-0">
          <Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input 
            placeholder="Search Patient, Address or ID..." 
            className="pl-9 bg-card"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-2 w-full overflow-x-auto pb-2 sm:pb-0 hide-scrollbar">
          {['all', 'completed', 'active', 'cancelled'].map(f => (
            <Button 
              key={f} 
              variant={filter === f ? 'default' : 'outline'} 
              size="sm" 
              className="capitalize shrink-0"
              onClick={() => setFilter(f)}
            >
              {f}
            </Button>
          ))}
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <div className="w-8 h-8 border-4 border-rose-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : filteredJobs.length === 0 ? (
        <Card className="flex flex-col items-center justify-center py-16 px-4 text-center border-dashed bg-muted/30">
          <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mb-4">
            <Siren className="w-8 h-8 text-muted-foreground/50" />
          </div>
          <h3 className="text-lg font-bold">No jobs found</h3>
          <p className="text-sm text-muted-foreground mt-1 max-w-sm">
            {search || filter !== 'all' ? 'Try adjusting your search filters.' : 'You have not completed any ambulance jobs yet.'}
          </p>
        </Card>
      ) : (
        <div className="space-y-4">
          {filteredJobs.map((j, i) => (
            <motion.div 
              key={j._id} 
              initial={{ opacity: 0, y: 12 }} 
              animate={{ opacity: 1, y: 0 }} 
              transition={{ delay: Math.min(i * 0.04, 0.4) }}
            >
              <Card className="hover:border-rose-500/30 hover:shadow-md transition-all group overflow-hidden">
                <CardContent className="p-0">
                  <div className="p-4 flex flex-col md:flex-row justify-between gap-4">
                    <div className="space-y-3 flex-1">
                      <div className="flex items-center gap-2">
                        <Badge variant="outline" className={`capitalize ${getStatusColor(j.status)}`}>
                          {j.status?.replace('_', ' ')}
                        </Badge>
                        <span className="text-xs font-semibold px-2 py-0.5 rounded bg-primary/10 text-primary">
                          {j.category || j.type || 'Emergency Dispatch'}
                        </span>
                        <span className="text-xs text-muted-foreground ml-auto md:ml-2">ID: {j._id?.slice(-6).toUpperCase()}</span>
                      </div>

                      <div className="grid sm:grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                          <p className="text-sm font-semibold flex items-center gap-2">
                            <User className="w-4 h-4 text-muted-foreground" />
                            {j.patientDetails?.name || 'Unknown Patient'}
                          </p>
                          <p className="text-xs text-muted-foreground flex items-start gap-2">
                            <MapPin className="w-4 h-4 mt-0.5 shrink-0" />
                            <span className="line-clamp-2">{j.location?.address || j.pickupLocation || 'Pickup location unavailable'}</span>
                          </p>
                        </div>
                        <div className="space-y-1.5">
                          <p className="text-xs text-muted-foreground flex items-center gap-2">
                            <CalendarDays className="w-4 h-4 shrink-0" />
                            {new Date(j.createdAt || j.date).toLocaleDateString('en-IN', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' })}
                          </p>
                          <p className="text-xs text-muted-foreground flex items-center gap-2">
                            <Clock className="w-4 h-4 shrink-0" />
                            {new Date(j.createdAt || j.date).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    </div>

                    <div className="flex flex-row md:flex-col items-center md:items-end justify-between md:justify-center border-t md:border-t-0 md:border-l border-border pt-4 md:pt-0 md:pl-4 min-w-[120px]">
                      <div className="text-left md:text-right">
                        <p className="text-xs text-muted-foreground uppercase font-semibold">Earnings</p>
                        <p className="text-lg font-black text-foreground">{inr(j.fare || j.amount || 0)}</p>
                      </div>
                      <Button variant="ghost" size="sm" className="hidden md:flex mt-2 text-rose-600 hover:text-rose-700 hover:bg-rose-50">
                        Details <ChevronRight className="w-4 h-4 ml-1" />
                      </Button>
                    </div>
                  </div>

                  {j.hospitalDestination && (
                    <div className="bg-muted/50 p-3 px-4 border-t border-border flex items-center gap-2 text-xs">
                      <ShieldCheck className="w-4 h-4 text-emerald-600" />
                      <span className="font-semibold">Dropoff:</span> {j.hospitalDestination}
                    </div>
                  )}
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      )}

      {!loading && maxPage > 1 && (
        <div className="flex items-center justify-between pt-4 border-t border-border">
          <Button size="sm" variant="outline" disabled={page <= 1} onClick={() => load(page - 1)}>← Previous</Button>
          <span className="text-sm font-medium text-muted-foreground">Page {page} of {maxPage}</span>
          <Button size="sm" variant="outline" disabled={page >= maxPage} onClick={() => load(page + 1)}>Next →</Button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Ambulance as AmbulanceIcon, ArrowRight, CheckCircle, Clock } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';
import { userFacingError } from '@/lib/errorCopy';
import type { Unmodelled } from '@/lib/apiTypes';

export default function AmbulanceSetup() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  // FE-B-06: the invite carries an OPAQUE single-use `code`, not a JWT.
  const code = searchParams.get('code');

  const [step, setStep] = useState('loading');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // FE-B-06: remove the code from the URL as soon as it is read.
  //
  // It stays in `location.hash` / history for the lifetime of the tab otherwise,
  // so it ends up in browser history, in any "copy link" the user makes, and in
  // a Referer header if the page ever loads a third-party resource. The SPA has
  // already captured it in `code` by this point, so replacing the entry is free.
  useEffect(() => {
    if (!code) {
      setError('This setup link is missing its code. Ask your hospital admin for a new invite.');
      setStep('error');
      return;
    }

    try {
      const clean = window.location.pathname + window.location.search;
      window.history.replaceState(null, document.title, clean);
    } catch {
      // history API unavailable — the code is already captured in memory.
    }

    // NOTE: there is deliberately no client-side JWT decode any more. The old page
    // did `JSON.parse(atob(token.split('.')[1]))` to prefill the email, which made
    // the setup credential a self-describing bearer token: anyone who saw the URL
    // (a shared screenshot, a proxy log, a Referer header) could decode the account
    // email without redeeming anything. The opaque code carries no claims, so there
    // is nothing to decode — and the email was never needed here.
    setStep('setup');
  }, [code]);

  const handleSetup = async (e: Unmodelled) => {
    e.preventDefault();
    setError('');
    if (password.length < 12) {
      setError('Password must be at least 12 characters');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    setLoading(true);
    try {
      await api.post('/auth/ambulance-setup', { code, password });
      setStep('done');
    } catch (err: any) {
      // FE-B-05: never render a raw backend message.
      setError(userFacingError(err));
      // An invalid/used/expired code cannot succeed on a retry — move to a terminal
      // state so the driver is not invited to keep trying.
      if (err?.response?.status === 400) {
        setStep('error');
      }
    } finally {
      setLoading(false);
    }
  };

  if (step === 'error') {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-8">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md text-center">
          <div className="bg-card rounded-2xl border border-border p-8 space-y-4">
            <Clock className="w-10 h-10 text-muted-foreground mx-auto" />
            <h2 className="text-lg font-semibold">This link can no longer be used</h2>
            <p className="text-sm text-muted-foreground">
              {error || 'Setup links are valid for 15 minutes and work only once.'}
            </p>
            <Button variant="outline" onClick={() => navigate('/login')} className="w-full">
              Go to login
            </Button>
          </div>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-8">
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-16 h-16 rounded-2xl bg-red-600 flex items-center justify-center mx-auto mb-4">
            <AmbulanceIcon className="w-8 h-8 text-white" />
          </div>
          <h1 className="text-2xl font-bold">Ambulance Account Setup</h1>
          <p className="text-muted-foreground mt-1">Password set karein, phir login karein</p>
          {/* FE-B-06: state the one-time / short-lived nature up front. A driver who
              knows the link dies in 15 minutes will not forward it to someone else. */}
          <p className="text-xs text-muted-foreground mt-2">
            This link works once and expires after 15 minutes.
          </p>
        </div>
        <div className="bg-card rounded-2xl border border-border p-6">
          {step === 'setup' && (
            <form onSubmit={handleSetup} className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-1.5 block">Create Password</label>
                <Input type="password" value={password} onChange={e => setPassword(e.target.value)} required autoComplete="new-password" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Confirm Password</label>
                <Input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required autoComplete="new-password" />
              </div>
              {error && <p className="text-sm text-destructive bg-destructive/10 px-3 py-2 rounded-lg">{error}</p>}
              <Button type="submit" className="w-full gap-2" size="lg" disabled={loading}>
                {loading ? 'Setting up...' : 'Set Password & Continue'} {!loading && <ArrowRight className="w-4 h-4" />}
              </Button>
            </form>
          )}
          {step === 'done' && (
            <div className="text-center py-4">
              <CheckCircle className="w-16 h-16 text-green-600 mx-auto mb-4" />
              <h2 className="text-xl font-bold mb-2">Account Ready!</h2>
              <Button className="w-full gap-2" size="lg" onClick={() => navigate('/login')}>Go to Login <ArrowRight className="w-4 h-4" /></Button>
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
}

/**
 * Document 17 — Analytics Event Taxonomy (PHI-free) Test Suite
 * Validating:
 * 1. PII detection (phones, emails, Aadhaar, PAN, cards, long text)
 * 2. Pseudonymous HMAC identity generation (hashDistinctId)
 * 3. Consent gating and minor exclusion rules
 * 4. Sensitive medical category masking (count-only / sensitive_masked)
 * 5. Event allowlist validation and funnels
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import posthog from 'posthog-js';
import {
  track,
  identifyUser,
  looksLikePii,
  hashDistinctId,
  hasAnalyticsConsent,
  setAnalyticsConsent,
  isSensitiveCategory,
  SENSITIVE_CATEGORIES_MASK,
  ANALYTICS_FUNNELS,
  GLOBAL_ANALYTICS_PROPERTIES,
} from '@/lib/analytics';

// Mock posthog-js
vi.mock('posthog-js', () => ({
  default: {
    capture: vi.fn(),
    identify: vi.fn(),
  },
}));

describe('Document 17 — Analytics Event Taxonomy & PHI Shielding', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    localStorage.clear();
  });

  describe('1. Zero-PHI and PII Detection Engine', () => {
    it('detects and flags phone numbers, emails, Aadhaar, PAN, and cards', () => {
      expect(looksLikePii('+91 9876543210')).toBe(true);
      expect(looksLikePii('9876543210')).toBe(true);
      expect(looksLikePii('patient@domain.com')).toBe(true);
      expect(looksLikePii('2345 6789 0123')).toBe(true); // Aadhaar
      expect(looksLikePii('ABCDE1234F')).toBe(true); // PAN
      expect(looksLikePii('4111 2222 3333 4444')).toBe(true); // Card
      expect(looksLikePii('a'.repeat(300))).toBe(true); // Long free text
    });

    it('allows clean coarse analytical properties', () => {
      expect(looksLikePii('dental')).toBe(false);
      expect(looksLikePii('BHO')).toBe(false);
      expect(looksLikePii('web')).toBe(false);
      expect(looksLikePii('inperson')).toBe(false);
    });

    it('generates pseudonymous distinct IDs without leaking raw user IDs', () => {
      const id1 = hashDistinctId('user_abc123');
      const id2 = hashDistinctId('user_abc123');
      const id3 = hashDistinctId('user_xyz999');

      expect(id1).toMatch(/^fm-[a-f0-9]{16}$/);
      expect(id1).toBe(id2); // deterministic
      expect(id1).not.toBe(id3); // distinct
      expect(id1).not.toContain('user_abc123');
    });
  });

  describe('2. Consent Gating & Minor Shielding', () => {
    it('rejects tracking when consent is not granted', () => {
      setAnalyticsConsent(false);
      const res = track('search_performed', { city_code: 'BHO' });
      expect(res.ok).toBe(false);
      expect(res.reason).toBe('no_consent');
      expect(posthog.capture).not.toHaveBeenCalled();
    });

    it('strictly shields minors (<18) from behavioural tracking even with consent', () => {
      setAnalyticsConsent(true);
      const res = track('booking_started', { provider_type: 'dental' }, { isMinor: true });
      expect(res.ok).toBe(false);
      expect(res.reason).toBe('minors_excluded');
      expect(posthog.capture).not.toHaveBeenCalled();
    });

    it('blocks identifyUser for minors', () => {
      setAnalyticsConsent(true);
      identifyUser('minor_patient_123', { isMinor: true });
      expect(posthog.identify).not.toHaveBeenCalled();
    });
  });

  describe('3. Event Allowlist & Sensitive Category Masking', () => {
    beforeEach(() => {
      setAnalyticsConsent(true);
    });

    it('rejects un-cataloged events', () => {
      const res = track('arbitrary_non_existent_event', { city_code: 'BHO' });
      expect(res.ok).toBe(false);
      expect(res.reason).toBe('unknown_event');
      expect(posthog.capture).not.toHaveBeenCalled();
    });

    it('rejects events containing PII properties', () => {
      const res = track('search_performed', {
        query_type: 'typed',
        phone: '9876543210',
      });
      expect(res.ok).toBe(false);
      expect(res.reason).toBe('pii_detected');
      expect(posthog.capture).not.toHaveBeenCalled();
    });

    it('masks sensitive medical categories to count-only (sensitive_masked)', () => {
      expect(isSensitiveCategory('mental_health')).toBe(true);
      expect(isSensitiveCategory('oncology')).toBe(true);
      expect(isSensitiveCategory('dental')).toBe(false);

      const res = track('search_performed', {
        category_code: 'mental_health',
        city_code: 'BHO',
      });

      expect(res.ok).toBe(true);
      expect(posthog.capture).toHaveBeenCalledWith('search_performed', expect.objectContaining({
        category_code: 'sensitive_masked',
        city_code: 'BHO',
        schema_version: '1.0',
      }));
    });

    it('passes clean regular categories without masking', () => {
      const res = track('booking_started', {
        provider_type: 'dental',
        mode: 'inperson',
      }, { userId: 'patient_42' });

      expect(res.ok).toBe(true);
      expect(posthog.capture).toHaveBeenCalledWith('booking_started', expect.objectContaining({
        provider_type: 'dental',
        mode: 'inperson',
        distinct_id: expect.stringMatching(/^fm-/),
      }));
    });
  });

  describe('4. Canonical Funnels & Global Properties', () => {
    it('defines canonical funnels across customer and provider journeys', () => {
      expect(ANALYTICS_FUNNELS.length).toBeGreaterThanOrEqual(4);
      const funnelNames = ANALYTICS_FUNNELS.map((f) => f.name);
      expect(funnelNames).toContain('Discovery to Booking');
      expect(funnelNames).toContain('Join to Live Provider');
      expect(funnelNames).toContain('Pharmacy and Lab Orders');
    });

    it('defines all 11 global context properties', () => {
      expect(GLOBAL_ANALYTICS_PROPERTIES).toContain('schema_version');
      expect(GLOBAL_ANALYTICS_PROPERTIES).toContain('distinct_id');
      expect(GLOBAL_ANALYTICS_PROPERTIES).toContain('consent_analytics');
      expect(GLOBAL_ANALYTICS_PROPERTIES).toContain('city_code');
    });
  });
});

