                          <Circle className="w-4 h-4 text-slate-400" />
                        )}
                        <span className={t.isDone ? 'line-through text-slate-400' : 'text-slate-700 dark:text-slate-200'}>
                          {t.label}
                        </span>
                      </span>
                      {t.doneAt && (
                        <span className="text-[10px] text-slate-400">
                          {new Date(t.doneAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              {/* Vitals chart (logged bedside) */}
              {detailVitals.length > 0 && (
                <div>
                  <h4 className="font-bold text-slate-700 dark:text-slate-300 mb-2">Vitals Chart:</h4>
                  {(() => {
                    const points = [...detailVitals]
                      .filter((v: any) => v?.values && (v.values.pulse != null || v.values.spo2 != null || v.values.systolic != null))
                      .sort((a: any, b: any) => new Date(a.recordedAt).getTime() - new Date(b.recordedAt).getTime())
                      .map((v: any) => ({
                        t: v.recordedAt ? new Date(v.recordedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '',
                        pulse: v.values?.pulse ?? null,
                        spo2: v.values?.spo2 ?? null,
                        sys: v.values?.systolic ?? null,
                      }));
                    if (points.length < 2) return null;
                    return (
                      <div className="h-44 rounded-2xl border border-rose-200 dark:border-rose-900/50 bg-white/60 dark:bg-slate-900/40 p-2 mb-2">
                        <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={points} margin={{ top: 4, right: 8, bottom: 0, left: -18 }}>
                            <CartesianGrid strokeDasharray="3 3" opacity={0.4} />
                            <XAxis dataKey="t" tick={{ fontSize: 10 }} />
                            <YAxis tick={{ fontSize: 10 }} domain={['auto', 'auto']} />
                            <Tooltip />
                            <Area type="monotone" dataKey="pulse" name="Pulse (bpm)" stroke="#f43f5e" fill="#f43f5e" fillOpacity={0.15} connectNulls />
                            <Area type="monotone" dataKey="spo2" name="SpO2 (%)" stroke="#0ea5e9" fill="#0ea5e9" fillOpacity={0.15} connectNulls />
                            <Area type="monotone" dataKey="sys" name="Sys BP" stroke="#8b5cf6" fill="#8b5cf6" fillOpacity={0.1} connectNulls />
                          </AreaChart>
                        </ResponsiveContainer>
                      </div>
                    );
                  })()}
                  <h4 className="font-bold text-slate-700 dark:text-slate-300 mb-2">Vitals Logged During Shift:</h4>
                  <div className="space-y-1.5 max-h-40 overflow-y-auto">
                    {detailVitals.map((v: any) => (
                      <div
                        key={v._id || `${v.vitalType}-${v.recordedAt}`}
                        className="p-2 rounded-xl border bg-rose-50/50 dark:bg-rose-950/20 border-rose-200 dark:border-rose-900/50 text-xs flex items-center justify-between"
                      >
                        <span className="font-bold text-rose-700 dark:text-rose-300 uppercase">
                          {String(v.vitalType).replace('_', ' ')}
                        </span>
                        <span className="text-slate-600 dark:text-slate-300 font-mono">
                          {v.values?.systolic ? `${v.values.systolic}/${v.values.diastolic ?? '-'} ` : ''}
                          {v.values?.pulse ? `♥ ${v.values.pulse} ` : ''}
                          {v.values?.spo2 ? `O₂ ${v.values.spo2}% ` : ''}
                          {v.values?.tempValue ? `${v.values.tempValue}°${v.values.tempUnit || 'F'} ` : ''}
                          {v.values?.sugarValue ? `Sugar ${v.values.sugarValue} ` : ''}
                          {v.values?.weightKg ? `${v.values.weightKg}kg` : ''}
                        </span>
                        <span className="text-[10px] text-slate-400">
                          {v.recordedAt ? new Date(v.recordedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="flex justify-end gap-2 pt-3 border-t border-slate-100 dark:border-slate-800">
              <Button
                type="button"
                size="sm"
                onClick={() => handleDownloadReceipt(historyDetailBooking._id, historyDetailBooking.bookingNumber)}
                className="text-xs bg-teal-600 hover:bg-teal-700 text-white font-bold rounded-xl"
              >
                <Download className="w-3.5 h-3.5 mr-1" />
                Download PDF Receipt
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* ── MODAL: EMERGENCY SOS ─────────────────────────────────────────── */}
      {showSosModal && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-rose-300 dark:border-rose-800 p-6 max-w-md w-full shadow-2xl space-y-4">
            <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800">
              <h3 className="font-black text-base text-rose-600 flex items-center gap-2">
                <HeartPulse className="w-5 h-5 animate-pulse" />
                Emergency Attendant Hotlines
              </h3>
              <button
                type="button"
                onClick={() => setShowSosModal(false)}
                className="text-slate-400 hover:text-slate-600"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">
              If a patient faces medical collapse, cardiac arrest, or security issues inside the hospital, alert campus emergency staff immediately:
            </p>

            <button
              type="button"
              onClick={async () => {
                try {
                  await api.createEmergency({
                    patientName: user?.name ? `Assistant (${user?.name})` : 'Hospital Assistant Attendant',
                    condition: 'Assistant raised Emergency SOS from bedside console',
                    severity: 'Critical',
                    phone: (user?.phone as string) || '9876543210'
                  });
                  toast.success("🚨 Platform SOS raised — campus emergency team notified.");
                  setShowSosModal(false);
                } catch (e: any) {
                  toast.error(e.message || "Failed to raise SOS");
                }
              }}
              className="w-full p-3 rounded-2xl bg-rose-600 text-white font-bold text-xs hover:bg-rose-700 transition-colors"
            >
              🚨 Raise Platform SOS (notify emergency team)
            </button>

            <div className="space-y-2.5 text-xs">
              <a
                href="tel:108"
                className="p-3 rounded-2xl bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-900 flex items-center justify-between hover:bg-rose-100 transition-colors"
              >
                <div>
                  <span className="font-bold text-rose-800 dark:text-rose-200 block">National Ambulance Emergency</span>
                  <span className="text-[11px] text-rose-600">Dial 108 (24x7 Free)</span>
                </div>
                <Phone className="w-4 h-4 text-rose-600" />
              </a>

              <a
                href="tel:112"
                className="p-3 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border flex items-center justify-between hover:bg-slate-100"
              >
                <div>
                  <span className="font-bold text-slate-800 dark:text-slate-200 block">Police & Campus Security</span>
                  <span className="text-[11px] text-slate-500">Dial 112 Unified Emergency</span>
                </div>
                <Phone className="w-4 h-4 text-teal-600" />
              </a>

              <div className="p-3 rounded-2xl bg-slate-50 dark:bg-slate-800/60 border">
                <span className="font-bold text-slate-800 dark:text-slate-200 block">FindMedi Care Support Team</span>
                <span className="text-[11px] text-slate-500">care@findmedi.com • Hotline: +91 98765 43210</span>
              </div>
            </div>

            <Button
              type="button"
              onClick={() => setShowSosModal(false)}
              className="w-full text-xs font-bold bg-slate-900 text-white rounded-xl h-10 mt-2"
            >
              Close Alert
            </Button>
          </div>
        </div>
      )}

      {/* ── MODAL: INCIDENT REPORT FORM ───────────────────────────────────── */}
      {showIncidentModal && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 max-w-lg w-full shadow-2xl space-y-4">
            <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800">
              <h3 className="font-black text-base text-slate-900 dark:text-slate-100 flex items-center gap-2">
                <AlertTriangle className="w-5 h-5 text-amber-500" />
                Hospital & Patient Incident Report
              </h3>
              <button
                type="button"
                onClick={() => setShowIncidentModal(false)}
                className="text-slate-400 hover:text-slate-600"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <p className="text-xs text-slate-500 dark:text-slate-400">
              Record safety, medical deterioration, bedside hazards, or patient conduct incidents. Reports are immediately logged for compliance and hospital QA review.
            </p>

            <form
              onSubmit={async (e) => {
                e.preventDefault();
                if (!incidentForm.description.trim()) {
                  toast.error('Please describe the incident details');
                  return;
                }
                try {
                  setSubmittingIncident(true);
                  await api.createSupportTicket({
                    subject: `[Incident Report] ${incidentForm.severity.toUpperCase()} - ${incidentForm.category} at ${incidentForm.hospital || 'Hospital'}`,
                    message: `Incident Type: ${incidentForm.category}\nSeverity: ${incidentForm.severity}\nHospital: ${incidentForm.hospital}\nPatient UHID / Ref: ${incidentForm.patientUhId || 'N/A'}\nReported by Assistant: ${user?.name || ''} (${user?.phone || ''})\n\nIncident Narrative:\n${incidentForm.description}`,
                    category: 'IncidentReport',
                    priority: incidentForm.severity === 'Critical' ? 'Urgent' : incidentForm.severity === 'High' ? 'High' : 'Normal',
                  });
                  toast.success('Incident logged successfully and sent to hospital safety desk');
                  setShowIncidentModal(false);
                  setIncidentForm({
                    hospital: '',
                    category: 'clinical_emergency',
                    severity: 'Medium',
                    description: '',
                    patientUhId: '',
                  });
                } catch (err: any) {
                  toast.error(err.message || 'Failed to submit incident report');
                } finally {
                  setSubmittingIncident(false);
                }
              }}
              className="space-y-3.5 text-xs"
            >
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="font-bold text-slate-700 dark:text-slate-300 block mb-1">
                    Hospital Campus
                  </label>
                  <input
                    type="text"
                    required
                    value={incidentForm.hospital}
                    onChange={(e) => setIncidentForm({ ...incidentForm, hospital: e.target.value })}
                    placeholder="e.g. Metro Hospital OPD"
                    className="w-full p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-medium"
                  />
                </div>
                <div>
                  <label className="font-bold text-slate-700 dark:text-slate-300 block mb-1">
                    Severity Level
                  </label>
                  <select
                    value={incidentForm.severity}
                    onChange={(e) => setIncidentForm({ ...incidentForm, severity: e.target.value })}
                    className="w-full p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-semibold"
                  >
                    <option value="Low">Low (Informational / Minor Delay)</option>
                    <option value="Medium">Medium (Protocol Non-compliance)</option>
                    <option value="High">High (Patient Safety Risk / Fall)</option>
                    <option value="Critical">Critical (Cardiac / Medical Collapse / Violence)</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="font-bold text-slate-700 dark:text-slate-300 block mb-1">
                  Incident Category
                </label>
                <select
                  value={incidentForm.category}
                  onChange={(e) => setIncidentForm({ ...incidentForm, category: e.target.value })}
                  className="w-full p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs"
                >
                  <option value="clinical_emergency">Patient Clinical Deterioration / Fall</option>
                  <option value="medication_error">Medication Dispensing Issue</option>
                  <option value="security_behavior">Harassment / Security / Aggression</option>
                  <option value="equipment_hazard">Hospital Stretcher / Wheelchair Defect</option>
                  <option value="other_complaint">Other Operational Incident</option>
                </select>
              </div>

              <div>
                <label className="font-bold text-slate-700 dark:text-slate-300 block mb-1">
                  Patient UHID or Booking Reference (Optional)
                </label>
                <input
                  type="text"
                  value={incidentForm.patientUhId}
                  onChange={(e) => setIncidentForm({ ...incidentForm, patientUhId: e.target.value })}
                  placeholder="e.g. UHID-98234 or Booking Number"
                  className="w-full p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs font-medium"
                />
              </div>

              <div>
                <label className="font-bold text-slate-700 dark:text-slate-300 block mb-1">
                  Incident Description & Immediate Action Taken *
                </label>
                <textarea
                  rows={3}
                  required
                  value={incidentForm.description}
                  onChange={(e) => setIncidentForm({ ...incidentForm, description: e.target.value })}
                  placeholder="Detail what occurred, timestamp, witnesses, nursing station alerted, etc..."
                  className="w-full p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-xs"
                />
              </div>

              <div className="flex items-center justify-end gap-2.5 pt-2 border-t border-slate-100 dark:border-slate-800">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setShowIncidentModal(false)}
                  className="rounded-xl text-xs font-bold"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={submittingIncident}
                  className="rounded-xl text-xs font-bold bg-amber-600 hover:bg-amber-700 text-white"
                >
                  {submittingIncident ? 'Submitting...' : 'Submit Official Report'}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* FULL-SCREEN Incoming Request Call modal (120s / 2-minute timer with ringtone) */}
      {activeIncomingCall && (
        <ProviderIncomingCall
          key={activeIncomingCall._id}
          data={{
            requestId: activeIncomingCall._id,
            providerType: 'assistant',
            hospitalName: activeIncomingCall.hospital,
            category: activeIncomingCall.durationType || 'Shift Request',
            title: `Hospital Shift: ${activeIncomingCall.hospital}`,
            subtitle: `Patient requested hospital assistance (${activeIncomingCall.durationType?.toUpperCase()}).${activeIncomingCall.taskDescription ? ` Task: ${activeIncomingCall.taskDescription}` : ''} Review details and respond within 2 minutes.`,
            patient: {
              name: activeIncomingCall.patientId?.name || 'Verified Patient',
              phone: activeIncomingCall.patientId?.phone || activeIncomingCall.emergencyPhone || 'Via FindMedi App',
              knownAllergies: Array.isArray(activeIncomingCall.patientAllergies)
                ? activeIncomingCall.patientAllergies.join(', ')
                : undefined,
            },
            location: {
              address: activeIncomingCall.hospital,
            },
            amount: getAssistantNet(activeIncomingCall),
            windowSeconds: 120,
            scheduledTime: activeIncomingCall.scheduledDate
              ? `${new Date(activeIncomingCall.scheduledDate).toLocaleDateString()} at ${activeIncomingCall.startTime || 'Scheduled time'}`
              : undefined,
            specialInstructions: activeIncomingCall.specialInstructions,
            serviceBadges: activeIncomingCall.serviceCategories || ['Hospital Assistance'],
          }}
          onAccept={async (bookingId) => {
            // Wave-based bookings (assistant:alert) vote via instant dispatch;
            // traditional new_booking_request accepts use the assistant booking API.
            if (activeIncomingCall?.isInstantWave) {
              try {
                await api.post(`/instant/assistant/${bookingId}/accept`, {});
                toast.success('Vote cast — waiting for dispatch confirmation…');
              } catch (err: any) {
                toast.error(userFacingError(err, { fallback: 'Could not accept booking' }));
              }
              setActiveIncomingCall(null);
              return;
            }
            await handleAcceptRequest(bookingId);
            setActiveIncomingCall(null);
          }}
          onReject={async (bookingId) => {
            setDeclineTargetId(bookingId);
            setActiveIncomingCall(null);
          }}
          onTimeout={(bookingId) => {
            setActiveIncomingCall(null);
            setIncomingRequests((prev) => prev.filter((r) => r._id !== bookingId));
          }}
        />
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Lock, TriangleAlert, UserRound, Building2, BellPlus, Loader2, ArrowLeft, ClipboardList, FlaskConical, Pill, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { getSpecialtyVisual } from '@/data/specialtyVisuals';
import { useSpecialtyDetail, useBrowseSpecialtyCounts, SPECIALTIES_STALE_TIME } from '@/hooks/useSpecialtyBrowse';
import { api } from '@/lib/api';

// Browse-by-specialties drill-down (A-5.2): children incl. cross-lists,
// condition/procedure chips and honest provider counts. Zero-state switches
// scope city + all-India, then offers the unmet-demand keeper instead of a
// dead end.
// SITE-I18N 3.2: fully keyed chrome, and in hi the Hindi name becomes the
// primary heading (the English one dangles below as the alias line).

export default function SpecialtyDetailPage() {
  const { code = '' } = useParams();
  const { t, i18n } = useTranslation();
  const isHi = (i18n.language || 'en').toLowerCase().startsWith('hi');
  const detail = useSpecialtyDetail(code);
  const [metroCity, setMetroCity] = useState('');
  const [scope, setScope] = useState<'city' | 'all'>(metroCity ? 'city' : 'all');
  const [scopeNote, setScopeNote] = useState('');
  const [activeTab, setActiveTab] = useState<'overview' | 'conditions' | 'procedures' | 'tests' | 'articles'>('overview');
  const [articles, setArticles] = useState<any[]>([]);
  const [articlesLoading, setArticlesLoading] = useState(false);

  useEffect(() => {
    let c = '';
    try { c = localStorage.getItem('findmedi_city') || ''; } catch { c = ''; }
    if (c) {
      setMetroCity(c);
      setScope('city');
    }
  }, []);

  useEffect(() => {
    const specialtyCode = detail.data?.specialty?.code;
    if (activeTab !== 'articles' || !specialtyCode) return;
    let cancelled = false;
    setArticlesLoading(true);
    api.get(`/platform-content?contentType=article&specialtyCode=${encodeURIComponent(specialtyCode)}`)
      .then((response: any) => { if (!cancelled) setArticles(response?.contents || []); })
      .catch(() => { if (!cancelled) setArticles([]); })
      .finally(() => { if (!cancelled) setArticlesLoading(false); });
    return () => { cancelled = true; };
  }, [activeTab, detail.data?.specialty?.code]);

  const specialty = detail.data?.specialty || null;
  const children = detail.data?.children || detail.data?.specialty?.children || [];

  const counts = useBrowseSpecialtyCounts(code, scope === 'city' ? { city: metroCity } : {}, {
    staleTime: SPECIALTIES_STALE_TIME,
    enabled: !!code && !!detail.isSuccess,
  });

  if (detail.isLoading) {
    return (
      <div className="max-w-5xl mx-auto px-4 py-16 flex items-center justify-center gap-2 text-muted-foreground">
        <Loader2 className="w-5 h-5 animate-spin" /> {t('specialties.loading')}
      </div>
    );
  }

  if (!specialty) {
    return (
      <div className="max-w-5xl mx-auto px-4 py-16 text-center">
        <h1 className="font-heading text-2xl font-bold">{t('specialties.not_found')}</h1>
        <p className="text-muted-foreground mt-2">{t('specialties.not_found_hint')}</p>
        <Link to="/browse-specialties" className="inline-flex items-center gap-2 mt-4 text-primary underline underline-offset-2">
          <ArrowLeft className="w-4 h-4" /> {t('specialties.all_specialties')}
        </Link>
      </div>
    );
  }

  const visual = getSpecialtyVisual(specialty.code);
  const Icon = visual.icon;
  const providerCount = counts.data?.doctors ?? null;
  const facilityCount = counts.data?.hospitals ?? null;
  const zero = counts.isSuccess && providerCount === 0;

  const providersHref = `/clinic-doctors?specialty=${encodeURIComponent(specialty.name)}`;
  const hospitalsHref = `/hospitals?specialty=${encodeURIComponent(specialty.name)}`;
  const termHref = (kind: 'condition' | 'procedure', term: string) =>
    `/clinic-doctors?specialty=${encodeURIComponent(specialty.name)}&${kind}=${encodeURIComponent(term)}&fallbackSpecialtyCode=${encodeURIComponent(specialty.code)}`;

  const notifyMe = async () => {
    try {
      await api.postSearchUnmetDemand({ query: specialty.name, category: 'specialty', city: scope === 'city' ? metroCity : 'All' });
      setScopeNote(t('specialties.notify_thanks'));
    } catch {
      setScopeNote(t('specialties.notify_error'));
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <Link to="/browse-specialties" className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-primary mb-6">
        <ArrowLeft className="w-4 h-4" /> {t('specialties.all_specialties')}
      </Link>

      <div className="flex items-start gap-4 mb-6">
        <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${visual.color} flex items-center justify-center shrink-0`}>
          <Icon className={`w-6 h-6 ${visual.textColor}`} />
        </div>
        <div>
          <h1 className={`font-heading text-2xl font-bold ${specialty.sensitive ? 'text-muted-foreground' : ''}`}>
            {(isHi && specialty.meta?.nameHi) ? specialty.meta.nameHi : specialty.name}
            {specialty.sensitive && <Lock className="inline w-4 h-4 ml-2 -mt-1 text-muted-foreground" />}
            {specialty.claimsRestricted && <TriangleAlert className="inline w-4 h-4 ml-2 -mt-1 text-amber-500" />}
          </h1>
          {isHi && specialty.name && specialty.name !== specialty.meta?.nameHi && (
            <p className="text-muted-foreground">{specialty.name}</p>
          )}
          {!isHi && specialty.meta?.nameHi && <p className="text-muted-foreground">{specialty.meta.nameHi}</p>}
          {!!(specialty.aliases || []).length && (
            <p className="text-xs text-muted-foreground mt-1 max-w-prose">{(specialty.aliases || []).slice(0, 6).join(' A- ')}</p>
          )}
        </div>
      </div>

      {(specialty.claimsRestricted || specialty.sensitive) && (
        <p className="mb-6 text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded-xl px-4 py-2">
          {specialty.claimsRestricted
            ? t('specialties.claims_notice')
            : t('specialties.sensitive_notice')}
        </p>
      )}

      <div className="flex flex-wrap items-center gap-2 mb-6">
        <Button asChild size="sm" className="gap-2">
          <Link to={providersHref}><UserRound className="w-4 h-4" /> {t('specialties.find_specialists')}</Link>
        </Button>
        <Button asChild size="sm" variant="outline" className="gap-2">
          <Link to={hospitalsHref}><Building2 className="w-4 h-4" /> {t('specialties.find_facilities')}</Link>
        </Button>
        <span className="text-sm text-muted-foreground">
          {counts.isLoading
            ? t('specialties.counting')
            : providerCount !== null
              ? zero
                ? t('specialties.no_providers')
                : t('specialties.count_summary', { n: providerCount, fac: facilityCount || 0 })
              : ''}
        </span>
      </div>

      {zero && (
        <p className="mb-6 text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded-xl px-4 py-2 flex items-center justify-between gap-3">
          <span>
            {scope === 'city' && metroCity
              ? t('specialties.zero_city', {
                name: specialty.name,
                city: metroCity,
                extra: facilityCount === 0 ? t('specialties.zero_city_extra') : '',
              })
              : t('specialties.zero_all')}
          </span>
          <span className="flex gap-2">
            {scope === 'city' && metroCity && (
              <Button size="sm" variant="outline" onClick={() => setScope('all')}>{t('specialties.show_all_india')}</Button>
            )}
            <Button size="sm" variant="outline" className="gap-1" onClick={notifyMe}>
              <BellPlus className="w-3.5 h-3.5" /> {t('specialties.notify_me')}
            </Button>
          </span>
        </p>
      )}
      {scopeNote && <p className="mb-6 text-xs text-emerald-700">{scopeNote}</p>}

      <div className="border-b border-border/60 mb-6">
        <nav className="flex gap-1" role="tablist" aria-label={t('specialties.tabs_label')}>
          <button
            role="tab"
            aria-selected={activeTab === 'overview'}
            onClick={() => setActiveTab('overview')}
            className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'overview' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`}
          >
            {t('specialties.tab_overview')}
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'conditions'}
            onClick={() => setActiveTab('conditions')}
            className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'conditions' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`}
          >
            <ClipboardList className="w-3.5 h-3.5 inline mr-1.5" /> {t('specialties.tab_conditions')}
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'procedures'}
            onClick={() => setActiveTab('procedures')}
            className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'procedures' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`}
          >
            <Pill className="w-3.5 h-3.5 inline mr-1.5" /> {t('specialties.tab_procedures')}
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'tests'}
            onClick={() => setActiveTab('tests')}
            className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'tests' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`}
          >
            <FlaskConical className="w-3.5 h-3.5 inline mr-1.5" /> {t('specialties.tab_tests_packages')}
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'articles'}
            onClick={() => setActiveTab('articles')}
            className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'articles' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`}
          >
            <FileText className="w-3.5 h-3.5 inline mr-1.5" /> {t('specialties.tab_articles', 'Articles')}
          </button>
        </nav>
      </div>

      {activeTab === 'overview' && (
        <>
          {(children || []).length > 0 && (
            <section className="mb-10">
              <h2 className="font-heading text-lg font-bold mb-3">{t('specialties.sub_specialties', { n: children.length })}</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {children.map((sub) => {
                  const subVisual = getSpecialtyVisual(sub.code);
                  const SubIcon = subVisual?.icon;
                  return (
                    <Link
                      key={sub.code}
                      to={`/browse-specialties/${sub.code}`}
                      className="rounded-xl border border-border/60 bg-card p-3 hover:border-primary/30 transition-colors"
                    >
                      <div className="flex items-center gap-2">
                        {SubIcon && (
                          <span className={`w-8 h-8 rounded-lg bg-gradient-to-br ${subVisual.color} flex items-center justify-center`}>
                            <SubIcon className={`w-3.5 h-3.5 ${subVisual.textColor}`} />
                          </span>
                        )}
                        <div>
                          <h3 className={`text-sm font-semibold ${sub.sensitive ? 'text-muted-foreground' : ''}`}>
                            {(isHi && sub.meta?.nameHi) ? sub.meta.nameHi : sub.name}
                            {sub.claimsRestricted && <TriangleAlert className="inline w-3 h-3 ml-1.5 -mt-0.5 text-amber-500" />}
                          </h3>
                          {!isHi && sub.meta?.nameHi && <p className="text-[11px] text-muted-foreground">{sub.meta.nameHi}</p>}
                        </div>
                      </div>
                      <p className="mt-2 text-[11px] text-primary underline underline-offset-2 inline-flex items-center gap-1">
                        <UserRound className="w-3 h-3" /> {t('specialties.find_sub_specialists', { name: sub.name })}
                      </p>
                    </Link>
                  );
                })}
              </div>
            </section>
          )}
        </>
      )}

      {activeTab === 'conditions' && (
        <section className="mb-8">
          <h2 className="font-heading text-lg font-bold mb-3">{t('specialties.conditions_treated')}</h2>
          {(specialty.meta?.conditions || []).length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {(specialty.meta?.conditions || []).map((c: string) => (
                specialty.sensitive
                  ? <span key={c} className="text-xs bg-secondary text-secondary-foreground rounded-full px-3 py-1.5 border border-border/60">{c}</span>
                  : <Link key={c} to={termHref('condition', c)} className="text-xs bg-secondary text-secondary-foreground rounded-full px-3 py-1.5 border border-border/60 hover:border-primary/50">{c}</Link>
              ))}
            </div>
          ) : (
            <p className="text-muted-foreground text-sm">{t('specialties.no_conditions')}</p>
          )}
        </section>
      )}

      {activeTab === 'procedures' && (
        <section className="mb-8">
          <h2 className="font-heading text-lg font-bold mb-3">{t('specialties.common_procedures')}</h2>
          {(specialty.meta?.procedures || []).length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {(specialty.meta?.procedures || []).map((p: string) => (
                specialty.sensitive
                  ? <span key={p} className="text-xs bg-secondary text-secondary-foreground rounded-full px-3 py-1.5 border border-border/60">{p}</span>
                  : <Link key={p} to={termHref('procedure', p)} className="text-xs bg-secondary text-secondary-foreground rounded-full px-3 py-1.5 border border-border/60 hover:border-primary/50">{p}</Link>
              ))}
            </div>
          ) : (
            <p className="text-muted-foreground text-sm">{t('specialties.no_procedures')}</p>
          )}
        </section>
      )}

      {activeTab === 'tests' && (
        <section className="mb-8">
          <h2 className="font-heading text-lg font-bold mb-3">{t('specialties.tab_tests_packages')}</h2>
          <p className="text-muted-foreground text-sm mb-4">{t('specialties.tests_packages_desc')}</p>
          <div className="flex flex-wrap gap-3">
            <Button asChild variant="outline" className="gap-2">
              <Link to={`/lab-tests?specialty=${encodeURIComponent(specialty.name)}`}><FlaskConical className="w-4 h-4" /> {t('specialties.browse_lab_tests')}</Link>
            </Button>
            <Button asChild variant="outline" className="gap-2">
              <Link to={`/health-packages?specialty=${encodeURIComponent(specialty.name)}`}><ClipboardList className="w-4 h-4" /> {t('specialties.browse_packages')}</Link>
            </Button>
          </div>
        </section>
      )}

      {activeTab === 'articles' && (
        <section className="mb-8" aria-live="polite">
          <h2 className="font-heading text-lg font-bold mb-3">{t('specialties.tab_articles', 'Articles')}</h2>
          {articlesLoading ? (
            <p className="text-muted-foreground text-sm">{t('specialties.loading')}</p>
          ) : articles.length ? (
            <div className="grid gap-3 sm:grid-cols-2">
              {articles.map((article) => (
                <article key={article.key} className="rounded-xl border border-border/60 bg-card p-4">
                  <h3 className="font-semibold">{article.title}</h3>
                  {article.summary && <p className="mt-2 text-sm text-muted-foreground">{article.summary}</p>}
                  {article.body && <p className="mt-3 text-sm whitespace-pre-line">{article.body}</p>}
                  <p className="mt-3 text-xs text-muted-foreground">{t('specialties.medically_reviewed', 'Medically reviewed')}</p>
                </article>
              ))}
            </div>
          ) : (
            <p className="text-muted-foreground text-sm">{t('specialties.no_articles', 'No reviewed articles are published for this specialty yet.')}</p>
          )}
        </section>
      )}

      {!counts.isLoading && scope === 'city' && metroCity && (
        <p className="text-xs text-muted-foreground flex items-center gap-1 mb-6">{t('specialties.counted_in', { city: metroCity })}</p>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { motion } from 'framer-motion';
import { Link, useLocation } from 'react-router-dom';
import {
  CheckCircle, XCircle, Plus, X, Send,
  ChevronLeft, ChevronRight, FileText, Clock,
  RefreshCw, MapPin, Building2, Globe, History,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/context/AuthContext';
import { api, resolveFileUrl } from '@/lib/api';
import { toast } from 'sonner';
import { getISTDateString } from '@/lib/dateUtils';
import AppointmentDetailsModal from '@/components/AppointmentDetailsModal';
import TodayAppointmentsSection from '@/components/TodayAppointmentsSection';
import AppointmentHistorySection from '@/components/AppointmentHistorySection';
import WalkInPatientForm from '@/components/WalkInPatientForm';
import ApproveAppointmentSection from '@/components/ApproveAppointmentSection';
import {
  AlertDialog, AlertDialogTrigger, AlertDialogContent, AlertDialogHeader,
  AlertDialogTitle, AlertDialogDescription, AlertDialogAction, AlertDialogCancel, AlertDialogFooter,
} from '@/components/ui/alert-dialog';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { useAppointmentRealtime } from '@/lib/useAppointmentRealtime';
import { isOfflineAppointment } from '@/lib/appointmentModes';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const timeSlots = ['9:00 AM', '9:30 AM', '10:00 AM', '10:30 AM', '11:00 AM', '11:30 AM', '2:00 PM', '2:30 PM', '3:00 PM', '3:30 PM', '4:00 PM', '4:30 PM'];

const prescriptionInitialState = {
  patientName: '', age: '', gender: '', phone: '', email: '', address: '',
  doctorName: '', specialization: '',
  chiefComplaints: '', diagnosis: '',
  medications: [{ name: '', dosage: '', frequency: '', instructions: '' }],
  advice: '', followUp: '',
};

export default function ClinicAppointments() {
  const { user } = useAuth();
  const location = useLocation();
  const mode = location.pathname.endsWith('/approve')
    ? 'approve'
    : location.pathname.endsWith('/history')
    ? 'history'
    : 'approved';
  const [appointments, setAppointments] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [calDate, setCalDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(getISTDateString());

  // Modals
  const [rescheduleId, setRescheduleId] = useState<Unmodelled>(null);
  const [newDate, setNewDate] = useState('');
  const [newTime, setNewTime] = useState('');
  const [bookedSlots, setBookedSlots] = useState<Unmodelled[]>([]);
  const [dateDisabledSlots, setDateDisabledSlots] = useState<Unmodelled[]>([]);
  const [completeId, setCompleteId] = useState<Unmodelled>(null);
  const [billAmount, setBillAmount] = useState(500);
  const [billModal, setBillModal] = useState(false);
  const [detailsApt, setDetailsApt] = useState<Unmodelled>(null);
  const [showWalkInModal, setShowWalkInModal] = useState(false);

  // Prescription modal state
  const [showPrescriptionModal, setShowPrescriptionModal] = useState(false);
  const [prescriptionData, setPrescriptionData] = useState(prescriptionInitialState);

  const getDaysInMonth = (date: Unmodelled) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDay = (date: Unmodelled) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();

  const loadAppointments = useCallback(async (searchParams = {}) => {
    setLoading(true);
    try {
      const data = await api.getAppointments({ status: 'All', limit: 100, ...searchParams });
      const raw = data?.appointments || data?.data || data || [];
      setAppointments(raw);
    } catch (e: any) {
      console.error(e);
      // Transient network errors interceptor me already retry ho jaate hain —
      // sirf genuine server errors par hi user ko batana chahiye.
      if (e?.status && e.status >= 400 && e.status < 600) toast.error('Failed to load appointments');
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadAppointments(); }, [loadAppointments]);

  // Realtime — naye bookings/status changes turant dikhein (30s polling fallback bhi hai)
  useAppointmentRealtime(loadAppointments);

  // Auto-refresh — naye bookings (walk-in/online) bina manual reload ke dikhein
  useEffect(() => {
    const timer = setInterval(() => {
      if (document.visibilityState === 'visible') loadAppointments();
    }, 30000);
    return () => clearInterval(timer);
  }, [loadAppointments]);


  // Fetch booked slots for reschedule
  useEffect(() => {
    if (!rescheduleId || !newDate) {
      setBookedSlots([]); setDateDisabledSlots([]); return;
    }
    const apt = appointments.find(a => a._id === rescheduleId);
    const doctorId = apt?.doctorId?._id;
    if (!doctorId) return;
    api.getBookedSlots({ doctorId, date: newDate })
      .then(res => {
        if (res && typeof res === 'object' && !Array.isArray(res)) {
          setBookedSlots(res.fullSlots || Object.keys(res.counts || {}));
          setDateDisabledSlots(res.dateDisabled || []);
        } else {
          setBookedSlots(Array.isArray(res) ? res : []);
          setDateDisabledSlots([]);
        }
      })
      .catch(err => console.error('Failed to fetch booked slots:', err));
  }, [rescheduleId, newDate, appointments]);

  const today = getISTDateString();
  const offlineAppointments = useMemo(() => appointments.filter(isOfflineAppointment), [appointments]);
  const pendingAppointments = offlineAppointments.filter(a => (a.status || '').toLowerCase() === 'pending');
  const approvedAppointments = offlineAppointments.filter(a => {
    const s = (a.status || '').toLowerCase();
    return s === 'confirmed' || s === 'approved' || s === 'scheduled';
  });
  const upcomingAppointments = approvedAppointments.filter(a => a.date > today);
  const todayAppointments = offlineAppointments.filter(a => a.date === today);
  const onlinePendingCount = appointments.filter(a => {
    const s = (a.status || '').toLowerCase();
    if (s !== 'pending') return false;
    const m = (a.appointmentMode || '').toLowerCase();
    const t = (a.type || '').toLowerCase();
    return m === 'voice' || m === 'audio' || m === 'video' || m === 'chat' ||
           t.includes('voice') || t.includes('audio') || t.includes('video') || t.includes('chat') || t.includes('online');
  }).length;

  const handleStatus = async (id: Unmodelled, status: Unmodelled, extra = {}) => {
    try { await api.updateAppointment(id, { status, ...extra }); loadAppointments(); } catch (e: any) { console.error(e); toast.error('Failed to update appointment'); }
  };

  const handleReschedule = async () => {
    if (!newDate || !newTime || !rescheduleId) return;
    try {
      await api.updateAppointment(rescheduleId, { date: newDate, time: newTime, status: 'Confirmed' });
      toast.success('Appointment rescheduled');
      setRescheduleId(null); setNewDate(''); setNewTime('');
      loadAppointments();
    } catch (e: any) { console.error(e); toast.error('Failed to reschedule appointment'); }
  };

  const openPrescriptionModal = useCallback((apt: Unmodelled) => {
    setCompleteId(apt._id);
    setPrescriptionData({
      ...prescriptionInitialState,
      patientName: apt.patient,
      doctorName: (user?.name as string),
      specialization: user?.specialization || '',    });
    setShowPrescriptionModal(true);
  }, [user?.name, user?.specialization]);

  // Listen for "Write Prescription" from TodayAppointmentsSection
  useEffect(() => {
    const handler = (e: Unmodelled) => openPrescriptionModal(e.detail);
    window.addEventListener('open-prescription', handler);
    return () => window.removeEventListener('open-prescription', handler);
  }, [openPrescriptionModal]);

  const addMedication = () => {
    setPrescriptionData({ ...prescriptionData, medications: [...prescriptionData.medications, { name: '', dosage: '', frequency: '', instructions: '' }] });
  };
  const removeMedication = (index: Unmodelled) => {
    setPrescriptionData({ ...prescriptionData, medications: prescriptionData.medications.filter((_, i) => i !== index) });
  };
  const updateMedication = (index: Unmodelled, field: Unmodelled, value: Unmodelled) => {
    const meds: Unmodelled = [...prescriptionData.medications]; meds[index][field] = value;
    setPrescriptionData({ ...prescriptionData, medications: meds });
  };

  const handleGeneratePrescription = async () => {
    const apt = appointments.find(a => a._id === completeId);
    if (!apt) return toast.error('Appointment not found');
    if (!prescriptionData.diagnosis) return toast.error('Please enter a diagnosis');
    try {
      const meds = prescriptionData.medications.filter(m => m.name.trim());
      await api.createRecord({
        patient: prescriptionData.patientName,
        patientId: apt.patientId?._id || apt.patientId,
        doctor: prescriptionData.doctorName,
        diagnosis: prescriptionData.diagnosis,
        prescription: prescriptionData.medications.map(m => `${m.name} - ${m.dosage} - ${m.frequency} ${m.instructions ? `(${m.instructions})` : ''}`).join('\n'),
        type: 'prescription',
        notes: `Chief Complaints: ${prescriptionData.chiefComplaints}\nAdvice: ${prescriptionData.advice}\nFollow-up: ${prescriptionData.followUp}`,
        data: {
          patient: { name: prescriptionData.patientName, age: prescriptionData.age, gender: prescriptionData.gender, phone: prescriptionData.phone, email: prescriptionData.email, address: prescriptionData.address },
          doctor: { name: prescriptionData.doctorName, specialization: prescriptionData.specialization },
          chiefComplaints: prescriptionData.chiefComplaints,
          diagnosis: prescriptionData.diagnosis,
          medications: meds,
          advice: prescriptionData.advice,
          followUp: prescriptionData.followUp,
          date: getISTDateString(),
        },
      });
      await api.createNotification({ title: 'New Prescription', message: `Dr. ${user?.name} has generated your prescription`, type: 'records', userId: apt.patientId || apt.patient });
      toast.success('Prescription generated');
      setShowPrescriptionModal(false);
      loadAppointments();
    } catch (e: any) { console.error(e); toast.error('Failed to generate prescription'); }
  };

  const handleGenerateBill = async () => {
    if (!completeId) return toast.error('No appointment selected');
    const apt = appointments.find(a => a._id === completeId);
    if (!apt) return toast.error('Appointment not found');
    try {
      await api.createBill({
        patient: apt.patient,
        patientId: apt.patientId?._id || apt.patientId,
        doctor: user?.name,
        service: `${apt.type} - ${apt.department || 'Clinic'}`,
        amount: billAmount,
        date: getISTDateString(),
        status: 'Confirmed',
      });
      await api.createNotification({
        title: 'New Invoice',
        message: `Invoice of ₹${billAmount} generated for ${apt.patient}`,
        type: 'payment',
        userId: apt.patientId || apt.patient,
      });
      await api.updateAppointment(completeId, { status: 'Completed' });
      setBillModal(false);
      setCompleteId(null);
      loadAppointments();
    } catch (e: any) { console.error(e); }
  };

  const handleDownloadPrescription = async (apt: Unmodelled) => {
    try {
      const pid = apt.patientId?._id || apt.patientId;
      const res = await api.getPatientRecords(pid);
      const recs = res?.records || res?.data || res || [];
      const rx = recs.find((r: Unmodelled) => r.type === 'prescription');
      if (!rx) { toast.info('No prescription record found'); return; }
      toast.success('Opening prescription…');
      const att = rx.attachments?.[0];
      if (att?.url) {
        window.open(resolveFileUrl(att.url), '_blank');
      } else {
        toast.message(`Prescription: ${rx.diagnosis || 'N/A'}`, {
          description: (rx.prescription || '').slice(0, 120),
        });
      }
    } catch (e: any) { console.error(e); toast.error('Failed to load prescription'); }
  };

  // Calendar widget (shared by both views)
  const CalendarWidget = (
    <div className="bg-card rounded-[24px] border border-border/60 p-5 shadow-sm">
      {/* ── Today summary banner ── */}
      {(() => {
        const todayAppts = appointments.filter(a => a.date === today);
        const confirmed = todayAppts.filter(a => (a.status || '').toLowerCase() === 'confirmed').length;
        const completed = todayAppts.filter(a => (a.status || '').toLowerCase() === 'completed').length;
        const pending = todayAppts.filter(a => (a.status || '').toLowerCase() === 'pending').length;
        const todayDateObj = new Date(`${today}T00:00:00`);
        const dayName = todayDateObj.toLocaleDateString('en-US', { weekday: 'long' });
        const dateLabel = todayDateObj.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' });
        return (
          <div className="mb-4 p-3.5 rounded-2xl bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border border-primary/20">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-[10px] font-bold uppercase tracking-wider text-primary/70">Today</p>
                <p className="font-heading text-base font-bold text-foreground leading-tight">{dayName}</p>
                <p className="text-xs text-muted-foreground">{dateLabel}</p>
              </div>
              <div className="text-right">
                <p className="font-heading text-2xl font-bold text-primary leading-none">{todayAppts.length}</p>
                <p className="text-[10px] text-muted-foreground mt-0.5">Appointments</p>
              </div>
            </div>
            {(confirmed > 0 || completed > 0 || pending > 0) && (
              <div className="flex flex-wrap gap-1.5 mt-2.5">
                {confirmed > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full bg-success/10 text-success">
                    <span className="w-1.5 h-1.5 rounded-full bg-success" /> Confirmed {confirmed}
                  </span>
                )}
                {completed > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full bg-info/10 text-info">
                    <span className="w-1.5 h-1.5 rounded-full bg-info" /> Done {completed}
                  </span>
                )}
                {pending > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-600">
                    <span className="w-1.5 h-1.5 rounded-full bg-amber-500" /> Pending {pending}
                  </span>
                )}
              </div>
            )}
          </div>
        );
      })()}

      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <h3 className="font-heading text-base font-semibold text-foreground">
            {mode === 'approve' ? 'Pending Requests' : 'Appointments Overview'}
          </h3>
          {mode === 'approve' && pendingAppointments.length > 0 && (
            <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-500/15 text-amber-600">{pendingAppointments.length} pending</span>
          )}
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() - 1))} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-muted text-muted-foreground" aria-label="Previous month"><ChevronLeft className="w-4 h-4" /></button>
          <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() + 1))} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-muted text-muted-foreground" aria-label="Next month"><ChevronRight className="w-4 h-4" /></button>
        </div>
      </div>
      <p className="text-sm font-semibold text-foreground mb-3">
        {calDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
      </p>
      <div className="grid grid-cols-7 gap-y-2 gap-x-1 text-center">
        {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d} className="text-[10px] uppercase font-bold text-muted-foreground/50 pb-1">{d}</div>)}
        {Array.from({ length: getFirstDay(calDate) }).map((_, i) => <div key={`e-${i}`} />)}
        {Array.from({ length: getDaysInMonth(calDate) }).map((_, i) => {
          const day = i + 1;
          const dateStr = `${calDate.getFullYear()}-${String(calDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
          const isSelected = dateStr === selectedDate;
          const isToday = dateStr === today;
          const hasAppts = mode === 'approve'
            ? pendingAppointments.some(a => a.date === dateStr)
            : appointments.some(a => a.date === dateStr);
          const count = mode === 'approve'
            ? pendingAppointments.filter(a => a.date === dateStr).length
            : 0;
          return (
            <button key={day} onClick={() => setSelectedDate(dateStr)}
              className={`relative w-9 h-9 mx-auto flex items-center justify-center rounded-xl text-sm font-medium transition-all
                ${isSelected ? 'bg-primary text-primary-foreground shadow-sm' : isToday ? 'bg-primary/10 text-primary font-bold ring-1 ring-primary/30' : 'text-foreground hover:bg-muted/70'}`}
            >
              {day}
              {mode === 'approve'
                ? (count > 0 && (
                    <span className="absolute -top-1 -right-1 min-w-4 h-4 px-0.5 flex items-center justify-center rounded-full bg-amber-500 text-white text-[9px] font-bold">
                      {count > 9 ? '9+' : count}
                    </span>
                  ))
                : (hasAppts && !isSelected && <span className="absolute bottom-1.5 w-1 h-1 rounded-full bg-primary" />)}
            </button>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="space-y-6 md:h-full md:flex md:flex-col">
      {/* ── Top Header Row: Left (Channel Tabs) & Right (3 Offline Sub-Tabs) ── */}
      <div className="flex flex-wrap items-center justify-between gap-3 shrink-0">
        {/* Left: 2 Channels Tabs */}
        <div className="flex items-center gap-2 bg-card p-1.5 rounded-2xl border border-border/80 shadow-sm w-fit shrink-0">
          <Link to={
            mode === 'approve' ? '/clinic/appointments/approve'
            : mode === 'history' ? '/clinic/appointments/history'
            : '/clinic/appointments'
          }>
            <button className="flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all bg-primary text-primary-foreground shadow-md">
              <Building2 className="w-4 h-4" />
              Offline Appointments
              {pendingAppointments.length > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-white/20 text-white">
                  {pendingAppointments.length}
                </span>
              )}
            </button>
          </Link>
          <Link to={
            mode === 'approve' ? '/clinic/online-appointments?tab=approve'
            : mode === 'history' ? '/clinic/online-appointments?tab=history'
            : '/clinic/online-appointments?tab=approved'
          }>
            <button className="flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all text-muted-foreground hover:text-foreground hover:bg-muted/50">
              <Globe className="w-4 h-4 text-muted-foreground" />
              Online Appointments
              {onlinePendingCount > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-amber-500 text-white">
                  {onlinePendingCount}
                </span>
              )}
            </button>
          </Link>
        </div>

        {/* Right: 3 Sub-Tabs (Approve Offline, Approved Offline, Offline History) */}
        <div className="flex items-center bg-muted/60 p-1 rounded-full border border-border/60 gap-1 shadow-sm w-fit flex-wrap">
          <Link to="/clinic/appointments/approve">
            <button className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-all ${
              mode === 'approve' ? 'bg-amber-500 text-white shadow-md' : 'text-muted-foreground hover:text-foreground'
            }`}>
              <Clock className="w-3.5 h-3.5" />
              Approve Offline Appointments
              {pendingAppointments.length > 0 && (
                <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-bold ${
                  mode === 'approve' ? 'bg-white/25 text-white' : 'bg-amber-500 text-white'
                }`}>
                  {pendingAppointments.length}
                </span>
              )}
            </button>
          </Link>
          <Link to="/clinic/appointments">
            <button className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-all ${
              mode === 'approved' ? 'bg-primary text-primary-foreground shadow-md' : 'text-muted-foreground hover:text-foreground'
            }`}>
              <CheckCircle className="w-3.5 h-3.5" />
              Approved Offline Appointments
              {approvedAppointments.length > 0 && (
                <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-bold ${
                  mode === 'approved' ? 'bg-white/20 text-white' : 'bg-primary/20 text-primary'
                }`}>
                  {approvedAppointments.length}
                </span>
              )}
            </button>
          </Link>
          <Link to="/clinic/appointments/history">
            <button className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-all ${
              mode === 'history' ? 'bg-emerald-600 text-white shadow-md' : 'text-muted-foreground hover:text-foreground'
            }`}>
              <History className="w-3.5 h-3.5" />
              Offline Appointment History
            </button>
          </Link>
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
        <h1 className="font-heading text-2xl font-bold text-foreground flex items-center gap-2 shrink-0">
          {mode === 'approve'
            ? <><Clock className="w-6 h-6 text-amber-500" /> Approve Offline Appointments</>
            : mode === 'history'
            ? <><History className="w-6 h-6 text-emerald-600 dark:text-emerald-400" /> Offline Appointment History</>
            : <><CheckCircle className="w-6 h-6 text-primary" /> Approved Offline Appointments</>
          }
          {mode === 'approve' && pendingAppointments.length > 0 && (
            <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-amber-500/15 text-amber-600">{pendingAppointments.length} pending</span>
          )}
          {mode === 'approved' && approvedAppointments.length > 0 && (
            <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-primary/10 text-primary">{approvedAppointments.length} confirmed</span>
          )}
        </h1>

        {mode === 'approved' && (
          <Button onClick={() => setShowWalkInModal(true)} size="sm" className="h-9 rounded-xl gap-1 text-xs px-3 ml-auto shadow-sm">
            <Plus className="w-3.5 h-3.5" /> Walk-in
          </Button>
        )}
      </div>

      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="bg-card rounded-2xl border border-border/60 p-5 animate-pulse">
              <div className="flex items-start justify-between mb-3"><div className="h-5 bg-muted rounded w-3/4" /><div className="h-4 bg-muted rounded w-16" /></div>
              <div className="space-y-1.5 mb-4"><div className="h-4 bg-muted rounded w-1/2" /><div className="h-4 bg-muted rounded w-1/3" /></div>
              <div className="space-y-1.5 mb-3"><div className="h-3 bg-muted rounded w-full" /><div className="h-3 bg-muted rounded w-3/4" /><div className="h-3 bg-muted rounded w-1/2" /></div>
              <div className="flex gap-2 pt-2"><div className="h-8 bg-muted rounded flex-1" /><div className="h-8 bg-muted rounded flex-1" /></div>
            </div>
          ))}
        </div>
      ) : mode === 'history' ? (
        <AppointmentHistorySection appointments={offlineAppointments} />
      ) : mode === 'approve' ? (
        <ApproveAppointmentSection
          appointments={offlineAppointments}
          allAppointments={appointments}
          onConfirm={(a: Unmodelled) => handleStatus(a._id, 'Confirmed')}
          onReject={(a: Unmodelled, reason: Unmodelled) => handleStatus(a._id, 'Cancelled', { notes: reason })}
        />
      ) : (
        <TodayAppointmentsSection
          appointments={approvedAppointments}
          selectedDate={selectedDate}
          calendar={CalendarWidget}
          onRefresh={loadAppointments}
          user={user}
          onViewDetails={(a: Unmodelled) => setDetailsApt(a)}
        />
      )}

      {/* ════════ Reschedule Modal ════════ */}
      {rescheduleId && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setRescheduleId(null)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-card rounded-2xl border border-border w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">Reschedule Appointment</h3>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">New Date</label>
                <Input type="date" value={newDate} onChange={e => setNewDate(e.target.value)} min={getISTDateString()} />
              </div>
              {newDate && (
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">New Time</label>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                    {timeSlots.map(t => {
                      const isBooked = bookedSlots.includes(t);
                      const isDisabled = dateDisabledSlots.includes(t);
                      const isUnavailable = isBooked || isDisabled;
                      return (
                        <button key={t} onClick={() => !isUnavailable && setNewTime(t)} disabled={isUnavailable}
                          className={`px-2 py-1.5 rounded-lg text-xs font-medium transition-colors ${newTime === t ? 'bg-primary text-primary-foreground' : isUnavailable ? 'bg-muted/40 text-muted-foreground cursor-not-allowed' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                          {t}{isBooked && <span className="ml-1 text-[9px]">(full)</span>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
            <div className="flex gap-3 mt-4">
              <Button variant="outline" className="flex-1" onClick={() => setRescheduleId(null)}>Cancel</Button>
              <Button className="flex-1" onClick={handleReschedule} disabled={!newDate || !newTime}>Confirm</Button>
            </div>
          </motion.div>
        </div>
      )}

      {/* ════════ Prescription Modal ════════ */}
      {showPrescriptionModal && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setShowPrescriptionModal(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="bg-card rounded-2xl border border-border w-full max-w-2xl p-6 max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">Create New Prescription</h3>
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div><label className="text-sm font-medium text-foreground mb-1.5 block">Patient Name</label><Input value={prescriptionData.patientName} onChange={e => setPrescriptionData({ ...prescriptionData, patientName: e.target.value })} placeholder="Enter patient name" /></div>
                <div className="grid grid-cols-2 gap-2">
                  <div><label className="text-sm font-medium text-foreground mb-1.5 block">Age</label><Input type="number" value={prescriptionData.age} onChange={e => setPrescriptionData({ ...prescriptionData, age: e.target.value })} placeholder="Age" /></div>
                  <div><label className="text-sm font-medium text-foreground mb-1.5 block">Gender</label><select value={prescriptionData.gender} onChange={e => setPrescriptionData({ ...prescriptionData, gender: e.target.value })} className="w-full px-3 py-2 rounded-lg border border-border bg-background text-foreground text-sm"><option value="">Select</option><option value="Male">Male</option><option value="Female">Female</option><option value="Other">Other</option></select></div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div><label className="text-sm font-medium text-foreground mb-1.5 block">Phone</label><Input value={prescriptionData.phone} onChange={e => setPrescriptionData({ ...prescriptionData, phone: e.target.value })} placeholder="Phone number" /></div>
                <div><label className="text-sm font-medium text-foreground mb-1.5 block">Email</label><Input type="email" value={prescriptionData.email} onChange={e => setPrescriptionData({ ...prescriptionData, email: e.target.value })} placeholder="Email" /></div>
              </div>
              <div><label className="text-sm font-medium text-foreground mb-1.5 block">Chief Complaints</label><Input value={prescriptionData.chiefComplaints} onChange={e => setPrescriptionData({ ...prescriptionData, chiefComplaints: e.target.value })} placeholder="Enter chief complaints" /></div>
              <div><label className="text-sm font-medium text-foreground mb-1.5 block">Diagnosis</label><Input value={prescriptionData.diagnosis} onChange={e => setPrescriptionData({ ...prescriptionData, diagnosis: e.target.value })} placeholder="Enter diagnosis" /></div>
              <div>
                <div className="flex items-center justify-between mb-2"><label className="text-sm font-medium text-foreground">Medications</label><Button type="button" size="sm" variant="outline" className="gap-1" onClick={addMedication}><Plus className="w-3 h-3" /> Add Medication</Button></div>
                {prescriptionData.medications.map((med, idx) => (
                  <div key={idx} className="flex gap-2 mb-2 items-start">
                    <Input value={med.name} onChange={e => updateMedication(idx, 'name', e.target.value)} placeholder="Medicine name" className="flex-1" />
                    <Input value={med.dosage} onChange={e => updateMedication(idx, 'dosage', e.target.value)} placeholder="Dosage" className="w-24" />
                    <Input value={med.frequency} onChange={e => updateMedication(idx, 'frequency', e.target.value)} placeholder="Frequency" className="w-28" />
                    <Input value={med.instructions} onChange={e => updateMedication(idx, 'instructions', e.target.value)} placeholder="Instructions" className="flex-1" />
                    <Button variant="ghost" size="icon" className="text-destructive" onClick={() => removeMedication(idx)}><X className="w-4 h-4" /></Button>
                  </div>
                ))}
              </div>
              <div><label className="text-sm font-medium text-foreground mb-1.5 block">Advice</label><Input value={prescriptionData.advice} onChange={e => setPrescriptionData({ ...prescriptionData, advice: e.target.value })} placeholder="Advice for patient" /></div>
              <div><label className="text-sm font-medium text-foreground mb-1.5 block">Follow-up</label><Input value={prescriptionData.followUp} onChange={e => setPrescriptionData({ ...prescriptionData, followUp: e.target.value })} placeholder="Follow-up date" /></div>
            </div>
            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setShowPrescriptionModal(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleGeneratePrescription} disabled={!prescriptionData.diagnosis}><Send className="w-4 h-4" /> Generate & Send</Button>
            </div>
          </motion.div>
        </div>
      )}

      {/* ════════ Complete & Bill Modal ════════ */}
      {billModal && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setBillModal(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">Complete & Generate Bill</h3>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Service</label>
                <Input value={appointments.find(a => a._id === completeId)?.type || 'Consultation'} disabled />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Amount (Rs)</label>
                <Input type="number" value={billAmount} onChange={e => setBillAmount(Number(e.target.value))} min={0} />
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setBillModal(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleGenerateBill}><Send className="w-4 h-4" /> Generate Bill</Button>
            </div>
          </motion.div>
        </div>
      )}

      {/* ════════ Walk-in Patient Modal ════════ */}
      <Dialog open={showWalkInModal} onOpenChange={setShowWalkInModal}>
        <DialogContent className="max-w-md p-6">
          <WalkInPatientForm
            timeSlots={timeSlots}
            onPatientCreated={() => { loadAppointments(); setShowWalkInModal(false); }}
          />
        </DialogContent>
      </Dialog>

      {/* ════════ Appointment Details Modal ════════ */}
      {detailsApt && (
        <AppointmentDetailsModal apt={detailsApt} onClose={() => setDetailsApt(null)} />
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { IndianRupee, Search, Download, Plus, X, Send, CreditCard, CheckCircle, AlertCircle, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { DataGrid } from '@/components/ui/System';
import { useAuth } from '@/context/AuthContext';
import { api, downloadInvoicePdf } from '@/lib/api';
import { toast } from 'sonner';
import { getISTDateString } from '@/lib/dateUtils';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const statusColors: Unmodelled = {
  Paid: 'bg-success/10 text-success',
  Pending: 'bg-warning/10 text-warning',
  Overdue: 'bg-destructive/10 text-destructive',
  Partial: 'bg-info/10 text-info',
};
const STATUSES = ['All', 'Paid', 'Pending', 'Overdue', 'Partial'];
const emptyForm = {
  patient: '', doctor: '', service: 'Consultation', amount: '', paid: '0',
  status: 'Pending', date: getISTDateString(), dueDate: '',
};

export default function ClinicBilling() {
  const { user } = useAuth();
  const [bills, setBills] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);

  const loadBills = async () => {
    setLoading(true);
    try {
      const data = await api.getBilling();
      const arr = data?.data || data?.bills || data || [];
      setBills(arr.filter((b: Unmodelled) => b.doctor?.toLowerCase().includes(user?.name?.toLowerCase())));
    } catch (e: any) { console.error(e); }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadBills(); }, [user?.name]);

  const filtered = bills.filter(b => {
    const ms = !search || b.patient?.toLowerCase().includes(search.toLowerCase()) || b.invoiceId?.toLowerCase().includes(search.toLowerCase());
    const ms2 = statusFilter === 'All' || b.status === statusFilter;
    return ms && ms2;
  });

  const set = (k: Unmodelled, v: Unmodelled) => setForm(f => ({ ...f, [k]: v }));

  const handleCreate = async () => {
    if (!form.patient || !form.amount) return;
    setSaving(true);
    try {
      await api.createBill({
        patient: form.patient,
        doctor: form.doctor || user?.name,
        service: form.service,
        amount: Number(form.amount),
        paid: Number(form.paid) || 0,
        status: form.status,
        date: form.date || getISTDateString(),
        dueDate: form.dueDate,
      });
      setShowForm(false);
      setForm(emptyForm);
      toast.success('Invoice created');
      loadBills();
    } catch (e: any) { toast.error(e.message || 'Failed to create invoice'); }
    setSaving(false);
  };

  const handleMarkPaid = async (bill: Unmodelled) => {
    try {
      await api.updateBill(bill._id, { status: 'Paid', paid: bill.amount });
      toast.success('Invoice marked as paid');
      loadBills();
    } catch (e: any) { toast.error(e.message || 'Failed to update invoice'); }
  };

  const handleDelete = async (id: Unmodelled) => {
    if (!confirm('Delete this invoice?')) return;
    try {
      await api.deleteBill(id);
      toast.success('Invoice deleted');
      loadBills();
    } catch (e: any) { toast.error(e.message || 'Failed to delete invoice'); }
  };

  const handleDownload = async (bill: Unmodelled) => {
    try {
      await downloadInvoicePdf(bill._id, `invoice-${bill.invoiceId || 'download'}.pdf`);
    } catch (e: any) { toast.error(e.message || 'Unable to download invoice'); }
  };

  const totalBilled = bills.reduce((s, b) => s + (b.amount || 0), 0);
  const totalPaid = bills.reduce((s, b) => s + (b.paid || 0), 0);
  const pendingAmount = totalBilled - totalPaid;
  const totalInvoices = bills.length;
  const paidCount = bills.filter(b => b.status === 'Paid').length;
  const pendingCount = bills.filter(b => b.status === 'Pending' || b.status === 'Overdue' || b.status === 'Partial').length;

  if (loading) return <div className="flex justify-center py-20"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Billing & Payments</h1>
          <p className="text-muted-foreground">{filtered.length} invoices</p>
        </div>
        <Button className="gap-2" onClick={() => { setForm(emptyForm); setShowForm(true); }}><Plus className="w-4 h-4" /> New Invoice</Button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-success/20 to-success/5 rounded-2xl border border-success/20 p-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-success/10 flex items-center justify-center shrink-0">
              <CheckCircle className="w-5 h-5 text-success" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Total Collected</p>
              <p className="font-heading text-2xl font-bold text-success">₹{totalPaid.toLocaleString()}</p>
            </div>
          </div>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-primary/20 to-primary/5 rounded-2xl border border-primary/20 p-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
              <IndianRupee className="w-5 h-5 text-primary" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Total Billed</p>
              <p className="font-heading text-2xl font-bold text-foreground">₹{totalBilled.toLocaleString()}</p>
            </div>
          </div>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-warning/20 to-warning/5 rounded-2xl border border-warning/20 p-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-warning/10 flex items-center justify-center shrink-0">
              <AlertCircle className="w-5 h-5 text-warning" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Pending</p>
              <p className="font-heading text-2xl font-bold text-warning">₹{pendingAmount.toLocaleString()}</p>
            </div>
          </div>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-info/20 to-info/5 rounded-2xl border border-info/20 p-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-info/10 flex items-center justify-center shrink-0">
              <CreditCard className="w-5 h-5 text-info" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Invoices</p>
              <p className="font-heading text-2xl font-bold text-foreground">{totalInvoices}</p>
              <p className="text-[10px] text-muted-foreground">{paidCount} paid · {pendingCount} pending</p>
            </div>
          </div>
        </motion.div>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patient or invoice..." aria-label="Search invoices" className="pl-10" />
        </div>
        <div className="flex gap-2 flex-wrap">
          {STATUSES.map(s => (
            <button key={s} onClick={() => setStatusFilter(s)}
              className={`px-3 py-2 rounded-lg text-sm font-medium transition-all ${statusFilter === s ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>{s}</button>
          ))}
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <CreditCard className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No invoices yet</p>
          <p className="text-sm text-muted-foreground/70">Create your first invoice to get started</p>
        </div>
      ) : (
        <div className="bg-card rounded-2xl border border-border/60 overflow-hidden">
          {/* Search + status chips above already narrowed this list. The `group`
              row class keeps the action icons hover-revealed as before. */}
          <DataGrid
            columns={[
