/* ─── Main Page ───────────────────────────────────── */
export default function ClinicEarnings() {
  const { user } = useAuth();
  const [bills, setBills] = useState<ApiRow[]>([]);
  const [payments, setPayments] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [, setRefreshing] = useState(false);

  const load = async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);

    try {
      const res = await api.getTransactions({ limit: 500 });
      const list = res?.data || res?.payments || res || [];
      setBills(list
        .filter((t: Unmodelled) => t.status === 'completed' || t.status === 'pending')
        .map(txToEarningsBill));
      setPayments(list.filter((t: Unmodelled) => t.status === 'completed'));
      if (isRefresh) toast.success('Earnings data refreshed');
    } catch (e: any) {
      toast.error(e.message || 'Failed to load earnings');
    }

    setLoading(false);
    setRefreshing(false);
  };

  useEffect(() => { load(); }, [user?.name]);

  if (loading) return (
    <div className="p-1">
      <EarningsSkeleton />
    </div>
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.4 }}
    >
      <EarningsAnalytics
        bills={bills}
        payments={payments}
        title="My Earnings"
      />
    </motion.div>
  );
}

