import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * Doc 12 §2/§3 — clinic-as-business overview: visits, collection,
 * outstanding, repeat/no-show %, today's roster, camps hosted.
 */
export default function ClinicOverview() {
  const [ov, setOv] = useState<any>(null);
  const [roster, setRoster] = useState<any[]>([]);
  const [camps, setCamps] = useState<any[]>([]);
  const [recalls, setRecalls] = useState<any[]>([]);

  const loadRecalls = async () => {
    try {
      const d: any = await (api as any).getRecallDues();
      setRecalls(d?.dues || []);
    } catch { /* optional section */ }
  };

  useEffect(() => {
    (async () => {
      try {
        const [o, r, c] = await Promise.all([
          (api as any).getClinicOverview({}),
          (api as any).getClinicRosterToday().catch(() => null),
          (api as any).getClinicCamps().catch(() => null),
        ]);
        setOv(o);
        if (r) setRoster(r?.roster || []);
        if (c) setCamps(c?.camps || []);
        loadRecalls();
      } catch { toast.error('Failed to load clinic overview'); }
    })();
  }, []);

  const sendAll = async () => {
    try {
      const ids = recalls.map((d: any) => String(d.patientId)).filter(Boolean);
      if (!ids.length) return;
      const r: any = await (api as any).sendRecalls({ patientIds: ids });
      toast.success(`Sent ${r.sent}, opt-out skipped ${r.skippedOptOut}, dupes ${r.skippedDup}`);
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  if (!ov) return <p className="text-sm text-muted-foreground p-4">Loading overview…</p>;

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-heading font-bold">Clinic Overview</h1>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          ['Visits', ov.visits], ['Completed', ov.completed],
          [`No-show ${ov.noShowPct}%`, ov.noShow],
          [`Repeat ${ov.repeatPct}%`, `₹${Number(ov.collected || 0).toLocaleString('en-IN')}`],
        ].map(([label, value]) => (
          <Card key={label}>
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground">{label}</p>
              <p className="text-xl font-bold">{String(value)}</p>
            </CardContent>
          </Card>
        ))}
      </div>
      <div className="grid lg:grid-cols-2 gap-4">
        <Card>
          <CardHeader><CardTitle className="text-base">Money</CardTitle></CardHeader>
          <CardContent className="text-sm space-y-1">
            <p className="flex justify-between"><span>Billed</span><b>₹{Number(ov.billed || 0).toLocaleString('en-IN')}</b></p>
            <p className="flex justify-between"><span>Outstanding</span><b>₹{Number(ov.outstanding || 0).toLocaleString('en-IN')}</b></p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-base">Today's roster</CardTitle></CardHeader>
          <CardContent className="space-y-1 text-sm">
            {roster.map((d: any, i: number) => (
              <p key={i} className="flex justify-between"><span>{d.name} · {d.specialization}</span><span>waiting: <b>{d.waiting}</b></span></p>
            ))}
            {roster.length === 0 && <p className="text-muted-foreground">No doctors on roster.</p>}
          </CardContent>
        </Card>
        <Card className="lg:col-span-2">
          <CardHeader><CardTitle className="text-base flex items-center gap-2">
            Recalls due ({recalls.length})
            <span className="flex-1" />
            {recalls.length > 0 && <Button size="sm" onClick={sendAll}>Message all (deduped)</Button>}
          </CardTitle></CardHeader>
          <CardContent className="space-y-1 text-sm max-h-48 overflow-auto">
            {recalls.slice(0, 20).map((d: any, i: number) => (
              <p key={i} className="flex justify-between"><span>{d.name} · {d.kind}</span><span className="text-muted-foreground">{d.dueAt ? new Date(d.dueAt).toLocaleDateString('en-IN') : ''}</span></p>
            ))}
            {recalls.length === 0 && <p className="text-muted-foreground">No recalls due.</p>}
          </CardContent>
        </Card>
        <Card className="lg:col-span-2">
          <CardHeader><CardTitle className="text-base">Camps hosted ({camps.length})</CardTitle></CardHeader>
          <CardContent className="space-y-1 text-sm">
            {camps.slice(0, 10).map((c: any) => (
              <p key={c._id} className="flex justify-between"><span>{c.title}</span><span className="text-muted-foreground">{c.status} · regs {c.registrations || 0}</span></p>
            ))}
            {camps.length === 0 && <p className="text-muted-foreground">No camps yet.</p>}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Package, Plus, Pencil, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';
import type { Unmodelled } from '@/lib/apiTypes';

/** File 22 P2-39: clinic treatment packages. */
export default function ClinicPackages() {
  const [rows, setRows] = useState<any[]>([]);
  const [form, setForm] = useState({ name: '', category: '', price: '', mrp: '', description: '', validDays: '30', includedServices: '' });

  const load = async () => {
    try {
      const r: any = await api.get('/clinic-packages');
      setRows(r.packages || []);
    } catch { setRows([]); }
  };
  useEffect(() => { load(); }, []);

  const add = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await api.post('/clinic-packages', {
        ...form,
        price: Number(form.price) || 0,
        mrp: Number(form.mrp) || 0,
        validDays: Number(form.validDays) || 30,
        includedServices: form.includedServices.split(',').map((s: string) => s.trim()).filter(Boolean),
      });
      toast.success('Package added');
      setForm({ name: '', category: '', price: '', mrp: '', description: '', validDays: '30', includedServices: '' });
      load();
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Save failed'); }
  };

  const remove = async (id: string) => {
    try { await (api as Unmodelled).delete(`/clinic-packages/${id}`); toast.success('Deleted'); load(); }
    catch (err: any) { toast.error(err?.response?.data?.message || 'Delete failed'); }
  };

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Package size={18} /> Clinic packages</h1>
      <Card>
        <CardHeader><CardTitle className="text-sm">Create package</CardTitle></CardHeader>
        <CardContent>
          <form onSubmit={add} className="flex flex-wrap gap-2">
            <Input placeholder="Package name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />
            <Input placeholder="Category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} />
            <Input type="number" placeholder="Price" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} required />
            <Input type="number" placeholder="MRP" value={form.mrp} onChange={(e) => setForm({ ...form, mrp: e.target.value })} />
            <Input placeholder="Valid days" value={form.validDays} onChange={(e) => setForm({ ...form, validDays: e.target.value })} />
            <Input placeholder="Services (comma-sep)" value={form.includedServices} onChange={(e) => setForm({ ...form, includedServices: e.target.value })} />
            <Button size="sm" type="submit"><Plus size={14} /> Add</Button>
          </form>
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle className="text-sm">Packages ({rows.length})</CardTitle></CardHeader>
        <CardContent className="space-y-1.5">
          {rows.map((r) => (
            <div key={r._id} className="flex items-center justify-between rounded border p-2 text-xs">
              <span><b>{r.name}</b> · {r.category || '—'} · ₹{r.price} {r.mrp ? `(MRP ₹${r.mrp})` : ''} · {r.validDays}d</span>
              <span className="flex gap-1">
                <StatusPill status={r.active ? 'active' : 'inactive'} />
                <Button size="sm" variant="ghost" onClick={() => remove(r._id)}><Trash2 size={12} /></Button>
              </span>
            </div>
          ))}
          {rows.length === 0 ? <EmptyState title="No packages" hint="Create your first treatment package." /> : null}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User, Calendar, FileText, Search, Users, TrendingUp } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/context/AuthContext';
import { api, resolveFileUrl, isValidFileUrl } from '@/lib/api';
import { subSlotFor } from '@/lib/timeSlots';
import { CompletedCard } from '@/components/TodayAppointmentsSection';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function ClinicPatients() {
  const { user } = useAuth();
  const [appointments, setAppointments] = useState<ApiRow[]>([]);
  const [records, setRecords] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  const loadData = async () => {
    setLoading(true);
    try {
      const [a, r] = await Promise.all([api.getAppointments(), api.getRecords()]);
      const appts = a?.data || a || [];
      const myAppts = appts?.filter((apt: Unmodelled) => apt.doctor?.toLowerCase().includes(user?.name?.toLowerCase())) || [];
      setAppointments(myAppts);
      setRecords(r?.data || r?.records || r || []);
    } catch (e: any) { console.error(e); }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadData(); }, [user?.name]);

  // All patients who have appointments (actual visits)
  const uniquePatients = [...new Map(appointments.map(a => [a.patient, a])).values()];

  const filteredPatients = uniquePatients.filter(p => !search || p.patient?.toLowerCase().includes(search.toLowerCase()));

  const getPatientAppointments = (name: Unmodelled) => appointments.filter(a => a.patient === name);
  const getVisitCount = (name: Unmodelled) => getPatientAppointments(name).length;
  const getRecordCount = (name: Unmodelled) => records.filter(r => r.patient === name).length;

  if (loading) return <div className="flex justify-center py-20"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">My Patients</h1>
          <p className="text-muted-foreground">{filteredPatients.length} patients</p>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <Users className="w-6 h-6 mx-auto text-primary mb-1" />
          <p className="text-2xl font-bold text-foreground">{uniquePatients.length}</p>
          <p className="text-xs text-muted-foreground">Patients</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <Calendar className="w-6 h-6 mx-auto text-success mb-1" />
          <p className="text-2xl font-bold text-foreground">{appointments.length}</p>
          <p className="text-xs text-muted-foreground">Total Visits</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <TrendingUp className="w-6 h-6 mx-auto text-warning mb-1" />
          <p className="text-2xl font-bold text-foreground">{appointments.filter(a => a.status === 'Completed').length}</p>
          <p className="text-xs text-muted-foreground">Completed</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <FileText className="w-6 h-6 mx-auto text-info mb-1" />
          <p className="text-2xl font-bold text-foreground">{records.length}</p>
          <p className="text-xs text-muted-foreground">Records</p>
        </div>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patients..." className="pl-10" />
      </div>

      {/* Patient Cards (completed appointment card) — shown on top */}
      {filteredPatients.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <Users className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No patients yet</p>
          <p className="text-sm text-muted-foreground/70">Patients with appointments will appear here</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredPatients.map((apt, i) => {
            const visitCount = getVisitCount(apt.patient);
            const recordCount = getRecordCount(apt.patient);
            const latestAppt = appointments
              .filter(a => a.patient === apt.patient)
              .sort((a, b) => (+new Date(b.createdAt || 0)) - (+new Date(a.createdAt || 0)))[0];

            return (
              <motion.div
                key={apt._id || apt.patient + i}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.03 }}
                className="scroll-mt-4 flex flex-col"
              >
                <CompletedCard
                  apt={latestAppt || apt}
                  subSlotFor={subSlotFor}
                  onViewFile={(url: Unmodelled) => {
                    if (!isValidFileUrl(url)) { toast.error('File unavailable — upload was not completed. Ask the patient to re-upload it.'); return; }
                    window.open(resolveFileUrl(url), '_blank');
                  }}
                  stats={{ visits: visitCount, records: recordCount }}
                />
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
