      </div>

      {/* Time Slots Grid — with per-date disable */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-4 gap-3">
          <div className="flex items-center gap-3 flex-wrap">
            <h2 className="font-heading text-lg font-semibold text-foreground flex items-center gap-2">
              <Clock className="w-5 h-5 text-primary" /> Time Slots
            </h2>
            {/* Date picker + selected date right next to the heading */}
            <div className="flex items-center gap-2">
              <Input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} className="w-auto h-8 text-xs" />
              <span className="text-sm font-semibold text-foreground whitespace-nowrap">
                {(() => {
                  const d = new Date(selectedDate + 'T00:00:00');
                  const dd = String(d.getDate()).padStart(2, '0');
                  const mm = String(d.getMonth() + 1).padStart(2, '0');
                  const yy = d.getFullYear();
                  return `${dd}-${mm}-${yy}`;
                })()}
              </span>
              {selectedDateDisabled.length > 0 && (
                <Badge variant="destructive" className="text-[10px] px-2 py-0.5">
                  {selectedDateDisabled.length} disabled
                </Badge>
              )}
              {selectedDateDisabled.length > 0 && (
                <Button size="sm" variant="ghost" onClick={clearDateDisabled} className="text-destructive h-7 px-2 text-xs">
                  <X className="w-3 h-3" /> Clear
                </Button>
              )}
            </div>
          </div>
          <span className="text-xs text-muted-foreground">{allSlots.length} slots total</span>
        </div>

        {allSlots.length > 0 ? (
          <>
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">
              {allSlots.map(slot => {
                const isReserved = bookedSlots.includes(slot);
                const isDisabled = selectedDateDisabled.includes(slot);
                // Reserved slots are read-only — no toggle, no click
                if (isReserved) {
                  return (
                    <div key={slot}
                      className="px-3 py-2 rounded-lg text-sm font-semibold text-center bg-gray-900 text-white border border-gray-800 shadow-sm opacity-90 cursor-not-allowed">
                      <span className="block">{rangeFor(slot)}</span>
                      <span className="block text-[9px] font-normal opacity-80">Slot Reserved</span>
                    </div>
                  );
                }
                return (
                  <button key={slot} onClick={() => toggleDateSlot(slot)}
                    className={`px-3 py-2 rounded-lg text-sm font-semibold transition-all cursor-pointer hover:opacity-80 ${
                      isDisabled
                        ? 'bg-red-100 text-red-600 border border-red-300 shadow-sm'
                        : 'bg-primary text-primary-foreground shadow-md'
                    }`}>
                    {rangeFor(slot)}
                  </button>
                );
              })}
            </div>
            <p className="text-[11px] text-muted-foreground mt-3 flex items-center gap-3 flex-wrap">
              <span className="flex items-center gap-1.5">
                <span className="inline-block w-3 h-3 rounded bg-primary" /> Available
              </span>
              <span className="flex items-center gap-1.5">
                <span className="inline-block w-3 h-3 rounded bg-red-100 border border-red-300" /> Disabled for this date only
              </span>
              <span className="flex items-center gap-1.5">
                <span className="inline-block w-3 h-3 rounded bg-gray-900" /> Slot Reserved (already booked)
              </span>
            </p>
          </>
        ) : (
          <p className="text-sm text-muted-foreground text-center py-4">Set working hours and duration above to auto-generate slots</p>
        )}
      </div>

      {/* Weekly Schedule */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <h2 className="font-heading text-lg font-semibold text-foreground mb-4 flex items-center gap-2">
          <Calendar className="w-5 h-5 text-primary" /> Weekly Working Days
        </h2>
        <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-7 gap-3">
          {days.map(day => (
            <button key={day} onClick={() => toggleDay(day)}
              className={`p-4 rounded-xl text-center transition-all border-2 ${schedule[day] ? 'border-primary bg-primary/10 text-primary' : 'border-border bg-muted text-muted-foreground'}`}>
              <p className="font-semibold capitalize text-sm">{day}</p>
              <p className="text-xs mt-1 opacity-70">{schedule[day] ? 'Available' : 'Off'}</p>
            </button>
          ))}
        </div>
      </div>

      {/* Leaves / Holidays */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <h2 className="font-heading text-lg font-semibold text-foreground mb-4 flex items-center gap-2">
          <Settings className="w-5 h-5 text-primary" /> Holidays & Time-off
        </h2>
        <div className="flex flex-col sm:flex-row gap-3 mb-4">
          <Input type="date" value={newLeave} onChange={e => setNewLeave(e.target.value)} className="sm:max-w-xs" />
          <Button onClick={addLeave} className="gap-2 w-full sm:w-auto"><Plus className="w-4 h-4" /> Add</Button>
        </div>
        {leaves.length === 0 ? (
          <p className="text-sm text-muted-foreground">No holidays marked</p>
        ) : (
          <div className="flex flex-wrap gap-2">
            {leaves.map(leave => (
              <span key={leave} className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-destructive/10 text-destructive text-sm font-medium">
                {leave}
                <button onClick={() => removeLeave(leave)} className="hover:text-destructive/70"><X className="w-3 h-3" /></button>
              </span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User, Mail, Phone, Shield, Plus, X, Save, Edit2, CheckCircle, Users, Stethoscope } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const staffRoles = ['Receptionist', 'Nurse', 'Lab Technician', 'Pharmacist', 'Accountant', 'Helper'];

export default function ClinicStaff() {
  const [staff, setStaff] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Unmodelled>(null);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [role, setRole] = useState('Receptionist');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const res = await api.getClinicStaff();
        const list = Array.isArray(res) ? res : res?.staff || [];
        setStaff(list);
      } catch { setStaff([]); }
      setLoading(false);
    };
    load();
  }, []);

  const handleSave = async () => {
    if (!name) return;
    setSaving(true);
    try {
      if (editing) {
        const updated = { name, email, phone, role };
        await api.updateClinicStaff(editing._id, updated);
        setStaff(staff.map(s => s._id === editing._id ? { ...s, ...updated } : s));
        toast.success('Staff updated');
      } else {
        const res = await api.createClinicStaff({ name, email, phone, role });
        const newMember = res?.staff || res || { _id: `st_${crypto.randomUUID()}`, name, email, phone, role, status: 'active' };
        setStaff([newMember, ...staff]);
        toast.success('Staff added');
      }
      setShowForm(false);
      setEditing(null);
      setName(''); setEmail(''); setPhone(''); setRole('Receptionist');
    } catch (e: any) { toast.error(e.message || 'Failed to save'); }
    setSaving(false);
  };

  const handleDelete = async (id: Unmodelled) => {
    try {
      await api.deleteClinicStaff(id);
      setStaff(staff.filter(s => s._id !== id));
      toast.success('Staff removed');
    } catch (e: any) { toast.error(e.message || 'Failed to delete'); }
  };

  const openEdit = (member: Unmodelled) => {
    setEditing(member);
    setName(member.name);
    setEmail(member.email || '');
    setPhone(member.phone || '');
    setRole(member.role);
    setShowForm(true);
  };

  const openNew = () => {
    setEditing(null);
    setName(''); setEmail(''); setPhone(''); setRole('Receptionist');
    setShowForm(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Staff Management</h1>
          <p className="text-muted-foreground">{staff.length} staff member(s)</p>
        </div>
        <Button className="gap-2" onClick={openNew}><Plus className="w-4 h-4" /> Add Staff</Button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <Users className="w-6 h-6 mx-auto text-primary mb-1" />
          <p className="text-2xl font-bold">{staff.length}</p>
          <p className="text-xs text-muted-foreground">Total Staff</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <Shield className="w-6 h-6 mx-auto text-info mb-1" />
          <p className="text-2xl font-bold">{staff.filter(s => s.role === 'Receptionist').length}</p>
          <p className="text-xs text-muted-foreground">Receptionists</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <Stethoscope className="w-6 h-6 mx-auto text-success mb-1" />
          <p className="text-2xl font-bold">{staff.filter(s => s.role === 'Nurse').length}</p>
          <p className="text-xs text-muted-foreground">Nurses</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <User className="w-6 h-6 mx-auto text-warning mb-1" />
          <p className="text-2xl font-bold">{staff.filter(s => s.role === 'Lab Technician').length}</p>
          <p className="text-xs text-muted-foreground">Lab Techs</p>
        </div>
      </div>

      {loading ? (
        <div className="text-center py-20"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto" /></div>
      ) : staff.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <Users className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No staff members yet</p>
          <p className="text-sm text-muted-foreground/70">Add your clinic staff (receptionist, nurse, etc.)</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {staff.map((member, i) => (
            <motion.div key={member._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
              className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all group">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-primary/20 to-primary/10 flex items-center justify-center">
                    <User className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-heading font-semibold text-foreground">{member.name}</h3>
                    <Badge variant="secondary" className="mt-1 text-xs">{member.role}</Badge>
                  </div>
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <Button variant="ghost" size="icon" className="w-8 h-8" onClick={() => openEdit(member)}>
                    <Edit2 className="w-4 h-4" />
                  </Button>
                  <Button variant="ghost" size="icon" className="w-8 h-8 text-destructive" onClick={() => handleDelete(member._id)}>
                    <X className="w-4 h-4" />
                  </Button>
                </div>
              </div>
              {(member.email || member.phone) && (
                <div className="mt-3 space-y-1 text-sm text-muted-foreground">
                  {member.email && <div className="flex items-center gap-1"><Mail className="w-3.5 h-3.5" /> {member.email}</div>}
                  {member.phone && <div className="flex items-center gap-1"><Phone className="w-3.5 h-3.5" /> {member.phone}</div>}
                </div>
              )}
            </motion.div>
          ))}
        </div>
      )}

      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setShowForm(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">{editing ? 'Edit Staff' : 'Add Staff Member'}</h3>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-1.5 block">Name *</label>
                <Input value={name} onChange={e => setName(e.target.value)} placeholder="Full name" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Email</label>
                <Input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Email" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Phone</label>
                <Input value={phone} onChange={e => setPhone(e.target.value)} placeholder="Phone number" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Role *</label>
                <div className="grid grid-cols-2 gap-2">
                  {staffRoles.map(r => (
                    <button key={r} onClick={() => setRole(r)}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors ${role === r ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      {r}
                    </button>
                  ))}
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleSave} disabled={!name || saving}>
                <Save className="w-4 h-4" /> {editing ? 'Update' : 'Add Staff'}
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

