                  (slug === 'reports' && (activeTab === 'reports' || activeTab === 'reports:read')) ||
                  (slug === 'records' && (activeTab === 'records' || activeTab === 'records:read'));
                const emoji = getSectionEmoji(sec);
                const displayLabel = isDashboard
