    const status = str(c, ['status', 'caseStatus'], 'Scheduled');
    return {
      id: str(c, ['caseNo', 'surgeryNo', '_id', 'id'], 'OT'),
      name: `${str(c, ['patientName', 'patient', 'name'], 'Patient')} · ${str(c, ['procedure', 'surgery', 'operation'], 'Procedure')}`,
