            name: `${str(l, ['employeeName', 'staffName', 'name'], 'Staff')} · ${str(l, ['leaveType', 'type'], 'Leave')}`.trim(),
            meta: `${str(l, ['fromDate', 'from'], '')} → ${str(l, ['toDate', 'to'], '')}`,
