export default function DoctorAppointments() {
  const { user } = useAuth();
  const location = useLocation();
  const view = location.pathname.endsWith('/approve')
    ? 'approve'
    : location.pathname.endsWith('/history')
    ? 'history'
    : 'approved';
  const [approvedSubTab, setApprovedSubTab] = useState(location.pathname.endsWith('/upcoming') ? 'upcoming' : 'today');
  const [appointments, setAppointments] = useState<ApiRow[]>([]);
  const [calDate, setCalDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(getISTDateString());
  const [loading, setLoading] = useState(true);

  // Modals
  const [rescheduleId, setRescheduleId] = useState<Unmodelled>(null);
  const [newDate, setNewDate] = useState('');
  const [newTime, setNewTime] = useState('');
  const [bulkShiftHours, setBulkShiftHours] = useState(1);

  const handleBulkReschedule = async () => {
    try {
      const morning = appointments.filter((a) => a.date === selectedDate);
      await Promise.all(morning.map((a) => api.updateAppointment(a._id, { time: `${bulkShiftHours}h shifted` })));
      toast.success(`${morning.length} slots shifted by ${bulkShiftHours}h (emergency delay)`);
    } catch { toast.error('Bulk reschedule failed'); }
  };
  const [bookedSlots, setBookedSlots] = useState<Unmodelled[]>([]);
  const [dateDisabledSlots, setDateDisabledSlots] = useState<Unmodelled[]>([]);
  const [completeId, setCompleteId] = useState<Unmodelled>(null);
  const [reportType, setReportType] = useState('Prescription');
  const [billModal, setBillModal] = useState<Unmodelled>(null);
  const [billAmount, setBillAmount] = useState(500);
  const [showWalkInModal, setShowWalkInModal] = useState(false);
  const [detailsApt, setDetailsApt] = useState<Unmodelled>(null);

  const [prescriptionData, setPrescriptionData] = useState(initialPrescriptionData);
  const [labReportData, setLabReportData] = useState(initialLabReportData);
  const [dischargeData, setDischargeData] = useState(initialDischargeData);
  const [showReportModal, setShowReportModal] = useState(false);

  const getDaysInMonth = (date: Unmodelled) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDay = (date: Unmodelled) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();

  const loadAppointments = useCallback(async (searchParams = {}) => {
    setLoading(true);
    try {
      const data = await api.getAppointments({ status: 'All', limit: 100, ...searchParams });
      const raw = data?.appointments || data?.data || data || [];
      setAppointments(raw);
    } catch (e: any) {
      console.error(e);
      // Transient network errors interceptor me already retry ho jaate hain —
      // sirf genuine server errors par hi user ko batana chahiye.
      if (e?.status && e.status >= 400 && e.status < 600) toast.error('Failed to load appointments');
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadAppointments(); }, [loadAppointments]);

  // Realtime — naye bookings/status changes turant dikhein (30s polling fallback bhi hai)
  useAppointmentRealtime(loadAppointments);

  // Auto-refresh — naye bookings (walk-in/online) bina manual reload ke dikhein
  useEffect(() => {
    const timer = setInterval(() => {
      if (document.visibilityState === 'visible') loadAppointments();
    }, 30000);
    return () => clearInterval(timer);
  }, [loadAppointments]);

  // Fetch real slot availability when reschedule modal date changes
  useEffect(() => {
    if (!rescheduleId || !newDate) {
      setBookedSlots([]); setDateDisabledSlots([]); return;
    }
    const apt = appointments.find(a => a._id === rescheduleId);
    const doctorId = apt?.doctorId?._id;
    if (!doctorId) return;
    api.getBookedSlots({ doctorId, date: newDate })
      .then(res => {
        if (res && typeof res === 'object' && !Array.isArray(res)) {
          setBookedSlots(res.fullSlots || Object.keys(res.counts || {}));
          setDateDisabledSlots(res.dateDisabled || []);
        } else {
          setBookedSlots(Array.isArray(res) ? res : []);
          setDateDisabledSlots([]);
        }
      })
      .catch(err => console.error('Failed to fetch booked slots:', err));
  }, [rescheduleId, newDate, appointments]);

  const today = getISTDateString();
  const offlineAppointments = useMemo(() => appointments.filter(isOfflineAppointment), [appointments]);
  const pendingAppointments = offlineAppointments.filter(a => (a.status || '').toLowerCase() === 'pending');
  const approvedAppointments = offlineAppointments.filter(a => {
    const s = (a.status || '').toLowerCase();
    return s === 'confirmed' || s === 'approved' || s === 'scheduled';
  });
  const upcomingAppointments = approvedAppointments.filter(a => a.date > today);
  const todayAppointments = offlineAppointments.filter(a => a.date === today);
  const dayAppointments = offlineAppointments.filter(a => a.date === selectedDate);
  const approveAppointments = dayAppointments.filter(a => (a.status || '').toLowerCase() === 'pending');
  const onlinePendingCount = appointments.filter(a => {
    const s = (a.status || '').toLowerCase();
    if (s !== 'pending') return false;
    const m = (a.appointmentMode || '').toLowerCase();
    const t = (a.type || '').toLowerCase();
    return m === 'voice' || m === 'audio' || m === 'video' || m === 'chat' ||
           t.includes('voice') || t.includes('audio') || t.includes('video') || t.includes('chat') || t.includes('online');
  }).length;

  const handleStatus = async (id: Unmodelled, status: Unmodelled, extra = {}) => {
    try { await api.updateAppointment(id, { status, ...extra }); loadAppointments(); } catch (e: any) { console.error(e); toast.error('Failed to update appointment'); }
  };

  const handleReschedule = async () => {
    if (!newDate || !newTime || !rescheduleId) return;
    try {
      await api.updateAppointment(rescheduleId, { date: newDate, time: newTime, status: 'Confirmed' });
      toast.success('Appointment rescheduled');
      setRescheduleId(null); setNewDate(''); setNewTime('');
      loadAppointments();
    } catch (e: any) { console.error(e); toast.error('Failed to reschedule appointment'); }
  };

  const openReportModal = useCallback((apt: Unmodelled, type: Unmodelled) => {
    setCompleteId(apt._id);
    setReportType(type);
    if (type === 'Prescription') {
      setPrescriptionData({ ...initialPrescriptionData, patientName: apt.patient, doctorName: (user?.name as string), specialization: user?.specialization || '' });
    } else if (type === 'Lab Report') {
      setLabReportData({ ...initialLabReportData, patientName: apt.patient, doctorName: (user?.name as string), specialization: user?.specialization || '', testDate: getISTDateString(), reportDate: getISTDateString(), reportId: `LAB-${crypto.randomUUID()}` });
    } else {
      setDischargeData({ ...initialDischargeData, patientName: apt.patient, doctorName: (user?.name as string), specialization: user?.specialization || '', admissionDate: apt.date || getISTDateString(), dischargeDate: getISTDateString() });
    }
    setShowReportModal(true);
  }, [user?.name, user?.specialization]);

  // Listen for "Write Prescription" from TodayAppointmentsSection
  useEffect(() => {
    const handler = (e: Unmodelled) => openReportModal(e.detail, 'Prescription');
    window.addEventListener('open-prescription', handler);
    return () => window.removeEventListener('open-prescription', handler);
  }, [openReportModal]);

  const addMedication = (type: Unmodelled) => {
    if (type === 'Prescription') {
      setPrescriptionData({ ...prescriptionData, medications: [...prescriptionData.medications, { name: '', dosage: '', frequency: '', instructions: '' }] });
    } else {
      setDischargeData({ ...dischargeData, medications: [...dischargeData.medications, { name: '', dosage: '', frequency: '' }] });
    }
  };

  const removeMedication = (type: Unmodelled, index: Unmodelled) => {
    if (type === 'Prescription') {
      setPrescriptionData({ ...prescriptionData, medications: prescriptionData.medications.filter((_, i) => i !== index) });
    } else {
      setDischargeData({ ...dischargeData, medications: dischargeData.medications.filter((_, i) => i !== index) });
    }
  };

  const updateMedication = (type: Unmodelled, index: Unmodelled, field: Unmodelled, value: Unmodelled) => {
    if (type === 'Prescription') {
      const meds: Unmodelled = [...prescriptionData.medications]; meds[index][field] = value;
      setPrescriptionData({ ...prescriptionData, medications: meds });
    } else {
