                <div>
                  <Label className="text-xs font-bold text-foreground">Diagnosis *</Label>
                  <Input 
                    placeholder="E.g. Viral Pharyngitis" 
                    value={diagnosis} 
                    onChange={e => setDiagnosis(e.target.value)} 
                    className="mt-1.5 text-sm"
                  />
                </div>

                <div>
                  <div className="flex items-center justify-between mb-2">
                    <Label className="text-xs font-bold text-foreground">Medications</Label>
                    <Button type="button" size="sm" variant="outline" className="h-6 text-[10px] gap-1 px-2" onClick={() => setMedications([...medications, { name: '', dosage: '', frequency: '', instructions: '' }])}>
                      <Plus className="w-3 h-3" /> Add
                    </Button>
                  </div>

                  <div className="space-y-3">
                    {medications.map((med, i) => (
                      <div key={i} className="bg-muted/20 p-3 rounded-xl border border-border/60 relative">
                        {medications.length > 1 && (
                          <button onClick={() => removeMedication(i)} className="absolute -top-2 -right-2 text-destructive bg-background rounded-full hover:scale-110 transition-transform">
                            <XCircle className="w-5 h-5" />
                          </button>
                        )}
                        <Input placeholder="Medicine Name" value={med.name} onChange={e => updateMedication(i, 'name', e.target.value)} className="mb-2 text-sm h-8" />
                        <div className="grid grid-cols-2 gap-2 mb-2">
                          <Input placeholder="Dosage (e.g. 500mg)" value={med.dosage} onChange={e => updateMedication(i, 'dosage', e.target.value)} className="text-sm h-8" />
                          <Input placeholder="Freq (e.g. 1-0-1)" value={med.frequency} onChange={e => updateMedication(i, 'frequency', e.target.value)} className="text-sm h-8" />
                        </div>
                        <Input placeholder="Instructions (e.g. After meals)" value={med.instructions} onChange={e => updateMedication(i, 'instructions', e.target.value)} className="text-sm h-8" />
                      </div>
                    ))}
                  </div>
                </div>

                <div>
                  <Label className="text-xs font-bold text-foreground">Advice / Instructions</Label>
                  <Input 
                    placeholder="Drink plenty of fluids..." 
                    value={advice} 
                    onChange={e => setAdvice(e.target.value)} 
                    className="mt-1.5 text-sm"
                  />
                </div>

                <div>
                  <Label className="text-xs font-bold text-foreground">Follow-up</Label>
                  <Input 
                    placeholder="e.g. After 5 days" 
                    value={followUp} 
                    onChange={e => setFollowUp(e.target.value)} 
                    className="mt-1.5 text-sm"
                  />
                </div>

                <div className="pt-4 border-t border-border/40">
                  <Button 
                    className="w-full gap-2 font-bold" 
                    onClick={handleSavePrescription}
                    disabled={savingPrescription}
                  >
                    {savingPrescription ? (
                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    ) : (
                      <Save className="w-4 h-4" />
                    )}
                    Complete Call & Save Prescription
                  </Button>
                  <p className="text-[10px] text-center text-muted-foreground mt-2">
                    This will mark the appointment as Completed.
                  </p>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Phone, PhoneIncoming, PhoneOutgoing, PhoneMissed, Clock,
  Disc, Search, RefreshCw, Trash2, User, Play, Pause,
  Download, MessageCircle, Plus, Calendar, ShieldCheck,
  CheckCircle2, AlertCircle, ArrowUpRight, ArrowDownLeft, XCircle
} from 'lucide-react';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription
} from '@/components/ui/dialog';
import { api, resolveFileUrl } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { useAudioCall } from '@/context/AudioCallContext';
import { formatDisplayDate } from '@/lib/dateUtils';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

function formatDuration(secs: Unmodelled) {
  if (!secs || secs <= 0) return '00:00';
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  if (m === 0) return `${s}s`;
  return `${m}m ${s.toString().padStart(2, '0')}s`;
}

function getInitials(name: Unmodelled) {
  return name?.split(' ').map((n: Unmodelled) => n[0]).join('').slice(0, 2).toUpperCase() || 'PT';
}

export default function DoctorCalls() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const { initiateCall, callState } = useAudioCall();

  const [calls, setCalls] = useState<ApiRow[]>([]);
  const [stats, setStats] = useState({
    totalCalls: 0,
    missedCalls: 0,
    incomingCalls: 0,
    outgoingCalls: 0,
    recordedCalls: 0,
    totalSeconds: 0,
  });
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [activeTab, setActiveTab] = useState('all'); // 'all' | 'missed' | 'incoming' | 'outgoing' | 'recorded'
  const [searchQuery, setSearchQuery] = useState('');

  // Quick Dial Modal
  const [showDialModal, setShowDialModal] = useState(false);
  const [contacts, setContacts] = useState<ApiRow[]>([]);
  const [contactSearch, setContactSearch] = useState('');
  const [loadingContacts, setLoadingContacts] = useState(false);

  // Audio Recording Player State
  const [playingRecordingId, setPlayingRecordingId] = useState<Unmodelled>(null);

  // Fetch Call Logs & Stats
  const loadData = useCallback(async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);

    try {
      const [callsRes, statsRes] = await Promise.all([
        api.getCalls({ tab: activeTab, limit: 100 }),
        api.getCallStats(),
      ]);

      if (callsRes?.success) {
        setCalls(callsRes.data || []);
      }
      if (statsRes?.success) {
        setStats(statsRes.stats || {});
      }
    } catch (err: any) {
      console.warn('Failed to load call logs:', err);
      toast.error('Could not load call history');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [activeTab]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Load Contacts Directory for Quick Dial
  const openDialModal = async () => {
    setShowDialModal(true);
    setLoadingContacts(true);
    try {
      const res = await api.getCallContacts();
      if (res?.success) {
        setContacts(res.contacts || []);
      }
    } catch (e: any) {
      console.warn('Error fetching contacts:', e);
    } finally {
      setLoadingContacts(false);
    }
  };

  // Filtered Calls list
  const filteredCalls = useMemo(() => {
    if (!searchQuery.trim()) return calls;
    const q = searchQuery.toLowerCase();
    return calls.filter((c) => {
      const isCaller = String(c.caller?._id || c.caller) === String(user?._id);
      const peer = isCaller ? c.receiver : c.caller;
      return (
        (peer?.name || '').toLowerCase().includes(q) ||
        (peer?.phone || '').toLowerCase().includes(q) ||
        (peer?.email || '').toLowerCase().includes(q)
      );
    });
  }, [calls, searchQuery, user]);

  // Filtered Contacts in Quick Dial modal
  const filteredContacts = useMemo(() => {
    if (!contactSearch.trim()) return contacts;
    const q = contactSearch.toLowerCase();
    return contacts.filter((c) =>
      (c.name || '').toLowerCase().includes(q) ||
      (c.phone || '').toLowerCase().includes(q) ||
      (c.email || '').toLowerCase().includes(q)
    );
  }, [contacts, contactSearch]);

  // Delete single call
  const handleDeleteCall = async (callId: Unmodelled) => {
    try {
      await api.deleteCallLog(callId);
      setCalls((prev) => prev.filter((c) => c._id !== callId));
      toast.success('Call log deleted');
    } catch (e: any) {
      toast.error('Failed to delete call log');
    }
  };

  // Clear all call logs
  const handleClearAll = async () => {
    if (!window.confirm('Are you sure you want to clear your call history?')) return;
    try {
      await api.clearAllCallLogs();
      setCalls([]);
      setStats((s) => ({ ...s, totalCalls: 0, missedCalls: 0, incomingCalls: 0, outgoingCalls: 0, totalSeconds: 0 }));
      toast.success('Call history cleared');
    } catch (e: any) {
      toast.error('Failed to clear call history');
    }
  };

  // Initiate call to contact
  const handleStartCall = (peer: Unmodelled) => {
    if (!peer) return;
    setShowDialModal(false);
    initiateCall(peer);
  };

  const isPatient = user?.role === 'patient';

  // Navigate to chat
  const handleOpenChat = (peerId: Unmodelled) => {
    const isClinic = user?.role === 'clinic_doctor';
    const chatPath = isPatient ? '/patient/chat' : isClinic ? '/clinic/chat' : '/doctor/chat';
    navigate(chatPath, { state: { targetUserId: peerId } });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-12">
      {/* ── Top Header ── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-card/60 backdrop-blur-sm p-6 rounded-3xl border border-border/70 shadow-sm">
        <div className="space-y-1">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 text-xs font-semibold border border-emerald-500/20">
            <ShieldCheck className="w-3.5 h-3.5" />
            <span>Encrypted 1-to-1 Audio Hub</span>
          </div>
          <h1 className="text-2xl md:text-3xl font-bold font-heading tracking-tight text-foreground">
            {isPatient ? 'Audio Calls & Doctor Consultations' : 'Audio Calls & Consultation Logs'}
          </h1>
          <p className="text-sm text-muted-foreground">
            {isPatient
              ? 'Make crystal-clear WebRTC audio calls to your doctors, review missed calls, and listen to recordings.'
              : 'Make crystal-clear WebRTC audio calls to patients, review missed calls, and listen to recordings.'}
          </p>
        </div>

        <div className="flex items-center gap-2.5">
          <Button
            variant="outline"
            size="sm"
            onClick={() => loadData(true)}
            disabled={refreshing}
            className="rounded-xl h-10 gap-1.5 text-xs"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${refreshing ? 'animate-spin' : ''}`} />
