          </Button>

          {calls.length > 0 && (
            <Button
              variant="outline"
              size="sm"
              onClick={handleClearAll}
              className="rounded-xl h-10 gap-1.5 text-xs text-muted-foreground hover:text-destructive hover:border-destructive/40"
            >
              <Trash2 className="w-3.5 h-3.5" />
