            >
              🚑 Escalate to ALS
            </button>
            <button
              onClick={() => setActiveEmergencyConsultId(null)}
              className="h-10 rounded-xl border border-white/20 text-slate-300 text-xs font-bold hover:bg-white/10"
            >
              Dismiss
            </button>
          </div>
        </div>
      )}
      {consultVideoOpen && activeEmergencyConsultId && (
        <EmergencyVideoRoom
          room={activeEmergencyConsultId}
          onClose={() => setConsultVideoOpen(false)}
        />
      )}
    </div>
  );
}

