/* ─── Main Page ───────────────────────────────────── */
export default function DoctorEarnings() {
  const { user } = useAuth();
  const [bills, setBills] = useState<ApiRow[]>([]);
  const [payments, setPayments] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const load = async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);

    try {
      const results = await Promise.allSettled([
        api.getBilling(),
        api.getPayments ? api.getPayments({}) : Promise.resolve([]),
      ]);
      const [b, p] = results.map(res => res.status === 'fulfilled' ? res.value : []);
      const ba = b?.data || b?.bills || b || [];
      setBills(ba.filter((bill: Unmodelled) =>
        bill.doctor?.toLowerCase().includes(user?.name?.toLowerCase()) ||
        bill.doctorId?.name?.toLowerCase().includes(user?.name?.toLowerCase())
      ));
      setPayments(p?.payments || p?.data || p || []);
      if (results.some(r => r.status === 'rejected')) {
        toast.error('Failed to load some earnings data');
      }
      if (isRefresh) toast.success('Earnings data refreshed');
    } catch (e: any) {
      toast.error(e.message || 'Failed to load earnings');
    }

    setLoading(false);
    setRefreshing(false);
  };

  useEffect(() => { load(); }, [user?.name]);

  if (loading) return (
    <div className="p-1">
      <EarningsSkeleton />
    </div>
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.4 }}
    >
      <EarningsAnalytics
        bills={bills}
        payments={payments}
        title="My Earnings"
      />
    </motion.div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { AlertTriangle, User, Clock, MessageSquare, CheckCircle, XCircle, Activity, Phone } from 'lucide-react';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { toast } from 'sonner';
