              />
            </div>
          </div>

          {/* Appointments Scrollable List */}
          <div className="space-y-3 max-h-[640px] overflow-y-auto pr-1">
            {loading ? (
              <div className="p-8 text-center text-xs text-muted-foreground flex flex-col items-center gap-2">
                <RefreshCw className="w-5 h-5 animate-spin text-primary" />
                Loading approved appointments...
              </div>
            ) : filteredAppointments.length === 0 ? (
              <div className="p-8 text-center rounded-2xl border border-dashed border-border/70 bg-card/40 space-y-2">
                <MapPin className="w-8 h-8 mx-auto text-muted-foreground/40" />
                <p className="text-sm font-semibold text-foreground">
                  {activeTab === 'pending' ? 'No pending home visit requests' : 'No home visits found'}
                </p>
                <p className="text-xs text-muted-foreground max-w-xs mx-auto">
                  {activeTab === 'pending'
                    ? 'New patient home visit requests awaiting your approval will appear here.'
                    : 'Patients who booked home visit appointments will appear here.'}
                </p>
              </div>
            ) : (
              filteredAppointments.map((appt) => {
                const isSelected = selectedApptId === appt._id;
                const status = (appt.status || '').toLowerCase();
                const isArrived = status === 'in queue' || status === 'serving' || (appt.patientLocation?.transitStatus === 'arrived');
                const intake = appt.preConsultationDetails;

                return (
                  <motion.div
                    key={appt._id}
                    layout
                    onClick={() => setSelectedApptId(appt._id)}
                    className={`group relative p-4 rounded-2xl border transition-all cursor-pointer ${
                      isSelected
                        ? 'bg-card border-primary ring-1 ring-primary shadow-md'
                        : 'bg-card/70 border-border/60 hover:border-border hover:shadow-sm'
                    }`}
                  >
                    {/* Header Row: Token + Time + Status Badge */}
                    <div className="flex items-center justify-between gap-2 mb-2.5">
                      <div className="flex items-center gap-2">
                        <span className="px-2.5 py-0.5 rounded-lg bg-primary/10 text-primary font-mono font-bold text-xs">
                          {appt.tokenNumber || 'Token #--'}
                        </span>
                        <span className="text-xs text-muted-foreground flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {appt.time}
                        </span>
                      </div>

                      <Badge
                        variant="outline"
                        className={`text-[10px] uppercase font-semibold px-2 py-0.5 ${
                          status === 'pending'
                            ? 'bg-amber-500/10 text-amber-600 border-amber-500/30'
                            : status === 'completed'
                            ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/30'
                            : isArrived
                            ? 'bg-blue-500/10 text-blue-600 border-blue-500/30'
                            : 'bg-indigo-500/10 text-indigo-600 border-indigo-500/30'
                        }`}
                      >
                        {status === 'pending'
                          ? 'Pending Approval'
                          : status === 'completed'
                          ? 'Completed'
                          : isArrived
                          ? 'Arrived / In Queue'
                          : 'On The Way'}
                      </Badge>
                    </div>

                    {/* Patient Name + Phone */}
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0">
                        <h3 className="font-heading font-bold text-sm text-foreground truncate">
                          {appt.patient || appt.patientId?.name || 'Patient'}
                        </h3>
                        <p className="text-xs text-muted-foreground mt-0.5">
                          {appt.patientId?.phone || appt.phone || 'No phone provided'}
                        </p>
                      </div>

                      {/* Quick Intake Indicator Badge */}
                      {intake?.chiefComplaint && (
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={(e) => {
                            e.stopPropagation();
                            setIntakeAppt(appt);
                          }}
                          className="h-7 px-2 gap-1 text-[11px] text-violet-600 dark:text-violet-400 bg-violet-500/10 hover:bg-violet-500/20 rounded-lg shrink-0"
                          title="View Quick Intake Details"
                        >
                          <FileText className="w-3 h-3" />
                          Intake
                        </Button>
                      )}
                    </div>

                    {/* Chief Complaint Preview if available */}
                    {intake?.chiefComplaint && (
                      <div className="mt-2 text-xs bg-muted/40 p-2 rounded-xl border border-border/40 text-foreground/80 line-clamp-1">
                        <span className="font-semibold text-foreground">Complaint:</span> {intake.chiefComplaint}
                        {intake.symptomsDuration && ` (${intake.symptomsDuration})`}
                      </div>
                    )}

                    {/* Footer Actions Row */}
                    <div className="mt-3 pt-2.5 border-t border-border/40 flex items-center justify-between gap-2 flex-wrap">
                      <div className="flex items-center gap-1">
                        {/* Audio Call */}
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleCallPatient(appt);
                          }}
                          className="h-7 px-2 text-xs gap-1 rounded-lg text-emerald-600 hover:bg-emerald-500/10 border-emerald-500/30"
                          title="1-to-1 Audio Call"
                        >
                          <Phone className="w-3 h-3" /> Call
                        </Button>

                        {/* Chat */}
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOpenChat(appt);
                          }}
                          className="h-7 px-2 text-xs gap-1 rounded-lg text-muted-foreground hover:text-foreground"
                          title="Send Message"
                        >
                          <MessageCircle className="w-3 h-3" /> Chat
                        </Button>
                      </div>

                      {/* Pending: Accept / Reject Buttons */}
                      {status === 'pending' ? (
                        <div className="flex items-center gap-1.5">
                          <Button
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleStatus(appt._id, 'Confirmed');
                            }}
                            className="h-7 px-2.5 text-xs gap-1 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-medium shadow-sm"
                          >
                            <CheckCircle2 className="w-3 h-3" /> Accept
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleStatus(appt._id, 'Cancelled');
                            }}
                            className="h-7 px-2 text-xs gap-1 rounded-lg text-destructive border-destructive/30 hover:bg-destructive/10"
                          >
                            <X className="w-3 h-3" /> Reject
                          </Button>
                        </div>
                      ) : status !== 'completed' && (
                        <div>
                          {!isArrived ? (
                            <Button
                              size="sm"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleUpdateTransit(appt._id, 'arrived');
                              }}
                              disabled={updatingTransit}
                              className="h-7 px-2.5 text-xs gap-1 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-medium"
                            >
                              <Check className="w-3 h-3" /> Mark Arrived
                            </Button>
                          ) : (
                            <span className="text-[11px] font-medium text-emerald-600 flex items-center gap-1">
                              <CheckCircle2 className="w-3.5 h-3.5" /> In Waiting Room
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                  </motion.div>
                );
              })
            )}
          </div>
        </div>

        {/* ── RIGHT COLUMN: INTERACTIVE LIVE TRACKING MAP (7 cols) ── */}
        <div className="lg:col-span-7 flex flex-col space-y-4">
          <div className="bg-card rounded-3xl border border-border/60 p-5 shadow-sm overflow-hidden flex flex-col h-full min-h-[600px] relative">
            {/* Top Map Bar: Selected Patient Transit HUD */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4 pb-3.5 border-b border-border/50">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center text-primary border border-primary/20 shadow-sm shrink-0">
                  <Navigation className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="font-heading font-bold text-sm sm:text-base text-foreground flex items-center gap-2">
                    {selectedAppt?.patient || 'Select a Patient'}
                    {selectedAppt?.tokenNumber && (
                      <span className="text-xs font-mono font-bold px-2 py-0.2 rounded bg-muted">
                        {selectedAppt.tokenNumber}
                      </span>
                    )}
                  </h3>
                  <p className="text-xs text-muted-foreground truncate max-w-sm">
                    {patientLocationData?.address || 'Patient location not specified'}
                  </p>
                </div>
              </div>

              {/* Transit Distance & ETA Pill */}
              {patientLocationData && (
                <div className="flex items-center gap-2 shrink-0">
                  <div className="px-3 py-1 rounded-xl bg-muted/60 border border-border/60 text-xs flex items-center gap-2 font-mono">
                    <span className="text-primary font-bold">{patientLocationData.distanceKm} km</span>
                    <span className="text-muted-foreground">•</span>
                    <span className="text-emerald-600 dark:text-emerald-400 font-bold">~{patientLocationData.etaMinutes} min</span>
                  </div>

                  <a
                    href={`https://www.google.com/maps/dir/?api=1&destination=${clinicCoordinates[1]},${clinicCoordinates[0]}`}
                    target="_blank"
                    rel="noreferrer"
                    className="p-2 rounded-xl border border-border/60 hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                    title="Open Navigation in Google Maps"
                  >
                    <ExternalLink className="w-4 h-4" />
                  </a>
                </div>
              )}
            </div>

            {/* Interactive Map Container */}
            <div className="relative flex-1 w-full rounded-2xl overflow-hidden border border-border/60 bg-muted/20 min-h-[460px]">
              {selectedAppt ? (
                <Map
                  center={mapCenter}
                  zoom={13.2}
                  className="w-full h-full min-h-[460px]"
                >
                  <MapControls position="bottom-right" showZoom showLocate showFullscreen />

                  {/* Route connecting patient to clinic */}
                  {routeCoordinates.length > 0 && (
                    <MapRoute
                      id={`route-${selectedAppt._id}`}
                      coordinates={routeCoordinates}
                      color="#3b82f6"
                      width={4}
                      opacity={0.85}
                    />
                  )}

                  {/* 1. Clinic / Hospital Marker */}
                  <MapMarker
                    longitude={clinicCoordinates[0]}
                    latitude={clinicCoordinates[1]}
                  >
                    <MarkerContent>
                      <div className="relative flex flex-col items-center group cursor-pointer">
                        <div className="w-9 h-9 rounded-2xl bg-emerald-600 text-white flex items-center justify-center shadow-lg ring-4 ring-emerald-500/20">
                          <Stethoscope className="w-5 h-5" />
                        </div>
                        <span className="mt-1 px-2 py-0.5 rounded-md bg-card/90 border border-border/80 text-[10px] font-bold text-foreground shadow-sm whitespace-nowrap">
                          {user?.name || 'Clinic Hub'}
                        </span>
                      </div>
                    </MarkerContent>
                  </MapMarker>

                  {/* 2. Patient Marker */}
                  {patientLocationData && (
                    <MapMarker
                      longitude={patientLocationData.coordinates[0]}
                      latitude={patientLocationData.coordinates[1]}
                    >
                      <MarkerContent>
                        <div className="relative flex flex-col items-center group cursor-pointer">
                          {/* Animated radar ring if traveling */}
                          {patientLocationData.transitStatus === 'on_the_way' && (
                            <span className="absolute -inset-1 rounded-full bg-blue-500/30 animate-ping" />
                          )}
                          <div className="relative w-9 h-9 rounded-2xl bg-blue-600 text-white flex items-center justify-center shadow-lg ring-4 ring-blue-500/20">
                            <User className="w-5 h-5" />
                          </div>
                          <span className="mt-1 px-2 py-0.5 rounded-md bg-card/90 border border-border/80 text-[10px] font-bold text-foreground shadow-sm whitespace-nowrap">
                            {selectedAppt.patient} (~{patientLocationData.etaMinutes}m)
                          </span>
                        </div>
                      </MarkerContent>
                    </MapMarker>
                  )}
                </Map>
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-muted-foreground text-xs">
                  Select an appointment on the left to activate patient tracking
                </div>
              )}

              {/* Floating Bottom Status Bar on Map */}
              {selectedAppt && patientLocationData && (
                <div className="absolute bottom-3 left-3 right-16 z-20 p-3 rounded-2xl bg-card/90 backdrop-blur-md border border-border/70 shadow-lg flex items-center justify-between gap-3 text-xs">
                  <div className="flex items-center gap-2.5">
                    <span className={`w-2.5 h-2.5 rounded-full ${
                      patientLocationData.transitStatus === 'arrived'
                        ? 'bg-emerald-500'
                        : 'bg-amber-500 animate-pulse'
                    }`} />
                    <div>
                      <p className="font-semibold text-foreground">
                        {patientLocationData.transitStatus === 'arrived'
                          ? 'Patient has arrived at clinic waiting area'
                          : `Patient is on the way (${patientLocationData.distanceKm} km away)`}
                      </p>
                      <p className="text-[11px] text-muted-foreground">
                        Estimated arrival: {new Date(Date.now() + patientLocationData.etaMinutes * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    {patientLocationData.transitStatus !== 'arrived' && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleUpdateTransit(selectedAppt._id, 'arrived')}
                        className="h-8 px-2.5 text-xs gap-1 bg-card hover:bg-muted"
                      >
                        <Check className="w-3.5 h-3.5 text-emerald-500" />
                        Mark Arrived
                      </Button>
                    )}

                    <Button
                      size="sm"
                      onClick={() => handleCheckIn(selectedAppt._id)}
                      className="h-8 px-3 text-xs gap-1 bg-primary text-primary-foreground font-semibold"
                    >
                      <CheckCircle2 className="w-3.5 h-3.5" />
                      Queue Check-in
                    </Button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* ── QUICK INTAKE FORM MODAL ── */}
      <Dialog open={!!intakeAppt} onOpenChange={(open) => !open && setIntakeAppt(null)}>
        <DialogContent className="max-w-lg rounded-3xl p-6">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-lg font-bold">
              <FileText className="w-5 h-5 text-violet-500" />
              <span>Pre-Consultation Intake Record</span>
            </DialogTitle>
            <DialogDescription className="text-xs">
              Medical intake submitted by {intakeAppt?.patient} before arriving at the clinic.
            </DialogDescription>
          </DialogHeader>

          {intakeAppt?.preConsultationDetails && (
            <div className="space-y-4 pt-2 text-xs">
              {/* Chief Complaint */}
              <div className="p-3.5 rounded-2xl bg-muted/40 border border-border/50">
                <p className="text-[11px] font-semibold text-muted-foreground uppercase">Chief Complaint</p>
                <p className="text-sm font-bold text-foreground mt-0.5">
                  {intakeAppt.preConsultationDetails.chiefComplaint || 'None specified'}
                </p>
                {intakeAppt.preConsultationDetails.symptomsDuration && (
                  <p className="text-xs text-muted-foreground mt-1">
                    Duration: <span className="font-semibold text-foreground">{intakeAppt.preConsultationDetails.symptomsDuration}</span>
                  </p>
                )}
              </div>

              {/* Current Medications & Allergies */}
              <div className="grid grid-cols-2 gap-3">
                <div className="p-3 rounded-2xl bg-card border border-border/60">
                  <p className="text-[11px] font-semibold text-muted-foreground flex items-center gap-1">
                    <Pill className="w-3.5 h-3.5 text-blue-500" /> Current Medications
                  </p>
                  <p className="text-xs text-foreground mt-1 font-medium">
                    {intakeAppt.preConsultationDetails.currentMedications || 'None'}
                  </p>
                </div>

                <div className="p-3 rounded-2xl bg-card border border-border/60">
                  <p className="text-[11px] font-semibold text-muted-foreground flex items-center gap-1">
                    <AlertCircle className="w-3.5 h-3.5 text-rose-500" /> Known Allergies
                  </p>
                  <p className="text-xs text-foreground mt-1 font-medium">
                    {intakeAppt.preConsultationDetails.allergies || 'No known allergies'}
                  </p>
                </div>
              </div>

              {/* Medical History */}
              <div className="p-3.5 rounded-2xl bg-card border border-border/60">
                <p className="text-[11px] font-semibold text-muted-foreground uppercase">Past Medical History</p>
                <p className="text-xs text-foreground mt-1 leading-relaxed">
                  {intakeAppt.preConsultationDetails.pastMedicalHistory || 'No prior medical conditions reported.'}
                </p>
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setIntakeAppt(null)}
                  className="rounded-xl text-xs h-9 px-4"
                >
                  Close
                </Button>
                <Button
                  size="sm"
                  onClick={() => {
                    const appt = intakeAppt;
                    setIntakeAppt(null);
                    handleCallPatient(appt);
                  }}
                  className="rounded-xl text-xs h-9 px-4 gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white"
                >
                  <Phone className="w-3.5 h-3.5" /> Call Patient
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, Send, Plus, X, AlertCircle, CheckCircle, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { getISTDateString } from '@/lib/dateUtils';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const leaveStatusColors: Unmodelled = {
  Pending: 'bg-warning/10 text-warning border-warning/20',
  Approved: 'bg-success/10 text-success border-success/20',
  Rejected: 'bg-destructive/10 text-destructive border-destructive/20',
};

const leaveTypes = [
  'Sick Leave',
  'Casual Leave',
  'Earned Leave',
  'Personal Leave',
  'Maternity/Paternity Leave',
  'Other',
];

export default function DoctorLeaveRequests() {
  const [leaves, setLeaves] = useState<ApiRow[]>([]);
  const [balance, setBalance] = useState<Unmodelled>(null);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const [leaveType, setLeaveType] = useState('Sick Leave');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [reason, setReason] = useState('');

  const loadData = async () => {
    setLoading(true);
    try {
      const leavesRes = await api.getLeaveRequests();
      setLeaves(leavesRes?.leaves || []);
      setBalance(leavesRes?.balance || null);
    } catch (e: any) { console.error(e); }
    setLoading(false);
  };

  useEffect(() => { loadData(); }, []);

  const handleSubmit = async () => {
    if (!startDate || !endDate || !reason) return;
    setSubmitting(true);
    try {
      const created = await api.createLeaveRequest({
        leaveType, startDate, endDate, reason,
      });
      setLeaves(prev => [created, ...prev]);
      setShowForm(false);
      setLeaveType('Sick Leave');
      setStartDate('');
      setEndDate('');
      setReason('');
      toast.success('Leave request submitted');
    } catch {
      toast.error('Failed to submit leave request');
    }
    setSubmitting(false);
  };

  if (loading) return (
    <div className="flex justify-center py-20">
      <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
    </div>
  );

  const pendingCount = leaves.filter(l => l.status === 'Pending').length;
  const approvedCount = leaves.filter(l => l.status === 'Approved').length;
  const rejectedCount = leaves.filter(l => l.status === 'Rejected').length;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Leave / Time-off Requests</h1>
          <p className="text-muted-foreground">Submit leave requests for admin approval</p>
        </div>
        <Button className="gap-2" onClick={() => setShowForm(true)}>
          <Plus className="w-4 h-4" /> New Request
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-warning">{pendingCount}</p>
          <p className="text-xs text-muted-foreground">Pending</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-success">{approvedCount}</p>
          <p className="text-xs text-muted-foreground">Approved</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-destructive">{rejectedCount}</p>
          <p className="text-xs text-muted-foreground">Rejected</p>
        </div>
      </div>

      {/* Leave Balance Info */}
      {balance && (
        <div className="bg-gradient-to-r from-primary/5 to-primary/10 rounded-2xl border border-primary/20 p-5">
          <h3 className="font-heading font-semibold text-foreground mb-3">Leave Balance</h3>
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 text-sm">
            {Object.entries(balance).filter(([k]) => k !== 'maternity').map(([key, val]: Unmodelled) => {
              const remaining = val.total - val.used;
              const labels: Unmodelled = { sick: 'Sick Leave', casual: 'Casual Leave', earned: 'Earned Leave', personal: 'Personal Leave' };
              return (
                <div key={key} className="bg-card rounded-lg p-3 text-center border border-border/40">
                  <p className={`text-lg font-bold ${remaining > 0 ? 'text-primary' : 'text-destructive'}`}>{remaining}</p>
                  <p className="text-xs text-muted-foreground">{labels[key] || key}</p>
                  <p className="text-[10px] text-muted-foreground/60">{val.used} used of {val.total}</p>
                </div>
              );
            })}
            <div className="bg-card rounded-lg p-3 text-center border border-border/40">
              <p className="text-lg font-bold text-primary">{leaves.length}</p>
              <p className="text-xs text-muted-foreground">Total Applied</p>
            </div>
          </div>
        </div>
      )}

      {/* Leave Requests List */}
      {leaves.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <Calendar className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No leave requests yet</p>
          <p className="text-sm text-muted-foreground/70">Submit a leave request for admin approval</p>
        </div>
      ) : (
        <div className="space-y-4">
          {leaves.map((lv, i) => {
            const colors = leaveStatusColors[lv.status] || leaveStatusColors.Pending;
            return (
              <motion.div key={lv._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all">
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-4">
                    <div className={`w-12 h-12 rounded-xl ${colors} flex items-center justify-center bg-opacity-20`}>
                      {lv.status === 'Approved' ? <CheckCircle className="w-6 h-6 text-success" /> :
                       lv.status === 'Rejected' ? <X className="w-6 h-6 text-destructive" /> :
                       <AlertCircle className="w-6 h-6 text-warning" />}
                    </div>
                    <div>
                      <h3 className="font-heading font-semibold text-foreground">{lv.leaveType}</h3>
                      <div className="flex items-center gap-3 mt-1 text-sm text-muted-foreground">
                        <span className="flex items-center gap-1">
                          <Calendar className="w-3.5 h-3.5" /> {lv.startDate} → {lv.endDate}
                        </span>
                        <span className="flex items-center gap-1">
                          <Clock className="w-3.5 h-3.5" /> Applied: {lv.createdAt ? new Date(lv.createdAt).toLocaleDateString() : ''}
                        </span>
                      </div>
                      {lv.reason && <p className="text-sm text-foreground mt-2">{lv.reason}</p>}
                      {lv.adminNotes && (
                        <div className="mt-2 p-2 bg-muted/30 rounded-lg text-sm">
                          <span className="text-muted-foreground">Admin: </span>
                          <span className="text-foreground">{lv.adminNotes}</span>
                        </div>
                      )}
                    </div>
                  </div>
                  <Badge className={`${colors} px-3 py-1`}>{lv.status}</Badge>
                </div>
              </motion.div>
            );
          })}
        </div>
      )}

      {/* New Leave Request Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setShowForm(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-lg p-6" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">New Leave Request</h3>

            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Leave Type</label>
                <div className="grid grid-cols-2 gap-2">
                  {leaveTypes.map(t => (
                    <button key={t} onClick={() => setLeaveType(t)}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors ${leaveType === t ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      {t}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Start Date *</label>
                  <Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)}
                    min={getISTDateString()} />
                </div>
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">End Date *</label>
                  <Input type="date" value={endDate} onChange={e => setEndDate(e.target.value)}
                    min={startDate || getISTDateString()} />
                </div>
              </div>

              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Reason *</label>
                <textarea value={reason} onChange={e => setReason(e.target.value)}
                  placeholder="Please provide a reason for your leave..."
                  className="w-full px-3 py-2 rounded-lg border border-border bg-background text-foreground text-sm resize-none h-24" />
              </div>

              {startDate && endDate && (
                <div className="bg-muted/30 rounded-xl p-3 text-sm">
                  <span className="text-muted-foreground">Total days: </span>
                  <span className="font-medium text-foreground">
                    {Math.max(1, Math.ceil(((+new Date(endDate)) - (+new Date(startDate))) / (1000 * 60 * 60 * 24)) + 1)}
                  </span>
                </div>
              )}
            </div>

            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleSubmit} disabled={!startDate || !endDate || !reason || submitting}>
                <Send className="w-4 h-4" /> {submitting ? 'Submitting...' : 'Submit for Approval'}
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { motion } from 'framer-motion';
import { Link, useLocation, useSearchParams } from 'react-router-dom';
import {
  CalendarDays, CheckCircle, XCircle, FileText, IndianRupee, Plus,
  CalendarClock, FileCheck, ChevronLeft, ChevronRight, RefreshCw,
  Video, MessageSquare, Clock, CheckCircle2, Building2, Globe, History,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { getISTDateString, formatDisplayDate } from '@/lib/dateUtils';
import TodayAppointmentsSection from '@/components/TodayAppointmentsSection';
import AppointmentHistorySection from '@/components/AppointmentHistorySection';
import ApproveAppointmentSection from '@/components/ApproveAppointmentSection';
import UpcomingAppointmentsSection from '@/components/UpcomingAppointmentsSection';
import AppointmentDetailsModal from '@/components/AppointmentDetailsModal';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { useAppointmentRealtime } from '@/lib/useAppointmentRealtime';

const initialPrescriptionData = {
  patientName: '', age: '', gender: '', phone: '', email: '', address: '',
  doctorName: '', specialization: '',
  chiefComplaints: '', diagnosis: '',
  medications: [{ name: '', dosage: '', frequency: '', instructions: '' }],
  advice: '', followUp: '',
};

import { isOnlineAppointment, isOfflineAppointment } from '@/lib/appointmentModes';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function DoctorOnlineAppointments() {
  const { user } = useAuth();
  const location = useLocation();
  const [searchParams, setSearchParams] = useSearchParams();
  const isClinic = location.pathname.startsWith('/clinic') || user?.role === 'clinic_doctor';
  const tabParam = searchParams.get('tab');
  const normalizeTab = (t: Unmodelled) => {
    if (t === 'approve' || t === 'pending') return 'approve';
    if (t === 'history' || t === 'complete') return 'history';
    if (t === 'approved' || t === 'today' || t === 'upcoming') return 'approved';
    return 'approve';
  };
  const [activeTab, setActiveTab] = useState(normalizeTab(tabParam));
  const [approvedSubTab, setApprovedSubTab] = useState(tabParam === 'upcoming' ? 'upcoming' : 'today');

  useEffect(() => {
    const t = searchParams.get('tab');
    if (t) {
      setActiveTab(normalizeTab(t));
      if (t === 'upcoming' || t === 'today') setApprovedSubTab(t);
    }
  }, [searchParams]);

  const handleTabChange = (t: Unmodelled) => {
    setActiveTab(t);
    setSearchParams({ tab: t });
  };
  const [appointments, setAppointments] = useState<ApiRow[]>([]);
  const [allAppointments, setAllAppointments] = useState<ApiRow[]>([]);
  const [calDate, setCalDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(getISTDateString());
  const [loading, setLoading] = useState(true);
  const [detailsApt, setDetailsApt] = useState<Unmodelled>(null);

  // Prescription modal states
  const [completeId, setCompleteId] = useState<Unmodelled>(null);
  const [prescriptionData, setPrescriptionData] = useState(initialPrescriptionData);
  const [showPrescriptionModal, setShowPrescriptionModal] = useState(false);

  const getDaysInMonth = (date: Unmodelled) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDay = (date: Unmodelled) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();

  const loadAppointments = useCallback(async (searchParams = {}) => {
    setLoading(true);
    try {
      const data = await api.getAppointments({ status: 'All', limit: 200, ...searchParams });
      const all = data?.appointments || data?.data || data || [];
      setAllAppointments(all);
      setAppointments(all.filter(isOnlineAppointment));
    } catch (e: any) {
      const status = e?.status || e?.response?.status;
      if (status && status !== 503) toast.error('Failed to load online appointments');
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadAppointments(); }, [loadAppointments]);
  useAppointmentRealtime(loadAppointments);

  useEffect(() => {
    const timer = setInterval(() => {
      if (document.visibilityState === 'visible') loadAppointments();
    }, 30000);
    return () => clearInterval(timer);
  }, [loadAppointments]);

  const today = getISTDateString();
  const pendingAppointments = appointments.filter(a => (a.status || '').toLowerCase() === 'pending');
  const approvedAppointments = appointments.filter(a => {
    const s = (a.status || '').toLowerCase();
    return s === 'confirmed' || s === 'approved' || s === 'scheduled';
  });
  const upcomingAppointments = approvedAppointments.filter(a => a.date > today);
  const todayAppointments = approvedAppointments.filter(a => a.date === today);
  const completeAppointments = appointments.filter(a => {
    const s = (a.status || '').toLowerCase();
    return s === 'completed' || s === 'cancelled' || s === 'missed' || s === 'absent';
  });
  const offlinePendingCount = useMemo(() => {
    return allAppointments.filter(a => isOfflineAppointment(a) && (a.status || '').toLowerCase() === 'pending').length;
  }, [allAppointments]);

  const handleStatus = async (id: Unmodelled, status: Unmodelled, extra = {}) => {
    try {
      await api.updateAppointment(id, { status, ...extra });
      toast.success('Appointment updated');
      loadAppointments();
    } catch (e: any) {
      console.error(e);
      toast.error('Failed to update appointment');
    }
  };

  const openPrescription = useCallback((apt: Unmodelled) => {
    setCompleteId(apt._id);
    setPrescriptionData({
      ...initialPrescriptionData,
      patientName: apt.patient,
      doctorName: (user?.name as string),
      specialization: user?.specialization || '',
    });
    setShowPrescriptionModal(true);
  }, [user?.name, user?.specialization]);

  useEffect(() => {
    const handler = (e: Unmodelled) => openPrescription(e.detail);
    window.addEventListener('open-prescription', handler);
    return () => window.removeEventListener('open-prescription', handler);
  }, [openPrescription]);

  const addMedication = () => {
    setPrescriptionData({
      ...prescriptionData,
      medications: [...prescriptionData.medications, { name: '', dosage: '', frequency: '', instructions: '' }],
    });
  };

  const removeMedication = (index: Unmodelled) => {
    setPrescriptionData({
      ...prescriptionData,
      medications: prescriptionData.medications.filter((_, i) => i !== index),
    });
  };

  const updateMedication = (index: Unmodelled, field: Unmodelled, value: Unmodelled) => {
    const meds: Unmodelled = [...prescriptionData.medications];
    meds[index][field] = value;
    setPrescriptionData({ ...prescriptionData, medications: meds });
  };

  const handleGeneratePrescription = async () => {
    const apt = appointments.find(a => a._id === completeId);
    if (!apt) return toast.error('Appointment not found');
    if (!prescriptionData.diagnosis) return toast.error('Please enter a diagnosis');
    try {
      const meds = prescriptionData.medications.filter(m => m.name.trim());
      await api.createRecord({
        patient: prescriptionData.patientName,
        patientId: apt.patientId?._id || apt.patientId,
        doctor: prescriptionData.doctorName,
        diagnosis: prescriptionData.diagnosis,
        prescription: meds.map(m => `${m.name} - ${m.dosage} - ${m.frequency} ${m.instructions ? '(' + m.instructions + ')' : ''}`).join('\n'),
        type: 'prescription',
        notes: `Chief Complaints: ${prescriptionData.chiefComplaints}\nAdvice: ${prescriptionData.advice}\nFollow-up: ${prescriptionData.followUp}`,
        data: {
          patient: { name: prescriptionData.patientName, age: prescriptionData.age, gender: prescriptionData.gender, phone: prescriptionData.phone, email: prescriptionData.email, address: prescriptionData.address },
          doctor: { name: prescriptionData.doctorName, specialization: prescriptionData.specialization },
          chiefComplaints: prescriptionData.chiefComplaints,
          diagnosis: prescriptionData.diagnosis,
          medications: meds,
          advice: prescriptionData.advice,
          followUp: prescriptionData.followUp,
          date: getISTDateString(),
        },
      });
      await api.createNotification({
        title: 'New Online Prescription',
        message: `Dr. ${user?.name} has generated your prescription`,
        type: 'records',
        userId: apt.patientId || apt.patient,
      });
      toast.success('Prescription generated successfully');
      setShowPrescriptionModal(false);
      loadAppointments();
    } catch (e: any) {
      console.error(e);
      toast.error('Failed to generate prescription');
    }
  };

  // Calendar widget
  const CalendarWidget = (
    <div className="bg-card rounded-[24px] border border-border/60 p-5 shadow-sm">
      {(() => {
        const todayAppts = appointments.filter(a => a.date === today);
        const confirmed = todayAppts.filter(a => (a.status || '').toLowerCase() === 'confirmed').length;
        const completed = todayAppts.filter(a => (a.status || '').toLowerCase() === 'completed').length;
        const pending = todayAppts.filter(a => (a.status || '').toLowerCase() === 'pending').length;
        const todayDateObj = new Date(`${today}T00:00:00`);
        const dayName = todayDateObj.toLocaleDateString('en-US', { weekday: 'long' });
        const dateLabel = todayDateObj.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' });
        return (
          <div className="mb-4 p-3.5 rounded-2xl bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border border-primary/20">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-[10px] font-bold uppercase tracking-wider text-primary/70">Online Consultations</p>
                <p className="font-heading text-base font-bold text-foreground leading-tight">{dayName}</p>
                <p className="text-xs text-muted-foreground">{dateLabel}</p>
              </div>
              <div className="text-right">
                <p className="font-heading text-2xl font-bold text-primary leading-none">{todayAppts.length}</p>
                <p className="text-[10px] text-muted-foreground mt-0.5">Today Online</p>
              </div>
            </div>
            {(confirmed > 0 || completed > 0 || pending > 0) && (
              <div className="flex flex-wrap gap-1.5 mt-2.5">
                {confirmed > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full bg-success/10 text-success">
                    <span className="w-1.5 h-1.5 rounded-full bg-success" /> Confirmed {confirmed}
                  </span>
                )}
                {completed > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-600">
                    <span className="w-1.5 h-1.5 rounded-full bg-blue-500" /> Done {completed}
                  </span>
                )}
                {pending > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-600">
                    <span className="w-1.5 h-1.5 rounded-full bg-amber-500" /> Pending {pending}
                  </span>
                )}
              </div>
            )}
          </div>
        );
      })()}

        <div className="flex items-center gap-2 mb-3 px-1">
          <div className="w-1.5 h-6 rounded-full bg-primary" />
          <h2 className="text-xl font-bold text-foreground">
          {activeTab === 'pending' ? 'Pending Requests' : activeTab === 'complete' ? 'Completed History' : 'Online Appointments'}
          </h2>
        </div>
      <div className="flex items-center justify-between mb-3">
        <h3 className="font-heading text-base font-semibold text-foreground">
          {activeTab === 'pending' ? 'Pending Requests' : activeTab === 'complete' ? 'Completed History' : 'Online Appointments'}
        </h3>
        <div className="flex items-center gap-1">
          <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() - 1))} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-muted text-muted-foreground" aria-label="Previous month"><ChevronLeft className="w-4 h-4" /></button>
          <button onClick={() => setCalDate(new Date(calDate.getFullYear(), calDate.getMonth() + 1))} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-muted text-muted-foreground" aria-label="Next month"><ChevronRight className="w-4 h-4" /></button>
        </div>
      </div>
      <p className="text-sm font-semibold text-foreground mb-3">
        {calDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
      </p>
      <div className="grid grid-cols-7 gap-y-2 gap-x-1 text-center">
        {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d} className="text-[10px] uppercase font-bold text-muted-foreground/50 pb-1">{d}</div>)}
        {Array.from({ length: getFirstDay(calDate) }).map((_, i) => <div key={'e-' + i} />)}
        {Array.from({ length: getDaysInMonth(calDate) }).map((_, i) => {
          const day = i + 1;
          const dateStr = `${calDate.getFullYear()}-${String(calDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
          const isSelected = dateStr === selectedDate;
          const isToday = dateStr === today;
          const hasAppts = activeTab === 'pending'
            ? pendingAppointments.some(a => a.date === dateStr)
            : appointments.some(a => a.date === dateStr);
          const count = activeTab === 'pending'
            ? pendingAppointments.filter(a => a.date === dateStr).length
            : 0;
          return (
            <button key={day} onClick={() => setSelectedDate(dateStr)}
              className={`relative w-9 h-9 mx-auto flex items-center justify-center rounded-xl text-sm font-medium transition-all ${isSelected ? 'bg-primary text-primary-foreground shadow-sm' : isToday ? 'bg-primary/10 text-primary font-bold ring-1 ring-primary/30' : 'text-foreground hover:bg-muted/70'}`}
            >
              {day}
              {activeTab === 'pending'
                ? (count > 0 && (
                    <span className="absolute -top-1 -right-1 min-w-4 h-4 px-0.5 flex items-center justify-center rounded-full bg-amber-500 text-white text-[9px] font-bold">
                      {count > 9 ? '9+' : count}
                    </span>
                  ))
                : (hasAppts && !isSelected && <span className="absolute bottom-1.5 w-1 h-1 rounded-full bg-primary" />)}
            </button>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="space-y-6 md:h-full md:flex md:flex-col">
      {/* ── Top Header Row: Left (Channel Tabs) & Right (3 Online Sub-Tabs) ── */}
      <div className="flex flex-wrap items-center justify-between gap-3 shrink-0">
        {/* Left: 2 Channels Tabs */}
        <div className="flex items-center gap-2 bg-card p-1.5 rounded-2xl border border-border/80 shadow-sm w-fit shrink-0">
          <Link to={
            activeTab === 'approve'
              ? (isClinic ? '/clinic/appointments/approve' : '/doctor/appointments/approve')
              : activeTab === 'history'
              ? (isClinic ? '/clinic/appointments/history' : '/doctor/appointments/history')
              : (isClinic ? '/clinic/appointments' : '/doctor/appointments')
          }>
            <button className="flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all text-muted-foreground hover:text-foreground hover:bg-muted/50">
              <Building2 className="w-4 h-4 text-muted-foreground" />
              Offline Appointments
              {offlinePendingCount > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-amber-500 text-white">
                  {offlinePendingCount}
                </span>
              )}
            </button>
          </Link>
          <Link to={isClinic ? `/clinic/online-appointments?tab=${activeTab}` : `/doctor/online-appointments?tab=${activeTab}`}>
            <button className="flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all bg-primary text-primary-foreground shadow-md">
              <Globe className="w-4 h-4" />
              Online Appointments
              {pendingAppointments.length > 0 && (
                <span className="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-white/20 text-white">
                  {pendingAppointments.length}
                </span>
              )}
            </button>
          </Link>
        </div>

        {/* Right: 3 Sub-Tabs (Approve Online, Approved Online, Online Appointment History) */}
        <div className="flex items-center bg-muted/60 p-1 rounded-full border border-border/60 gap-1 shadow-sm w-fit flex-wrap">
          <button
            onClick={() => handleTabChange('approve')}
            className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-all ${
              activeTab === 'approve'
                ? 'bg-amber-500 text-white shadow-md'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            <Clock className="w-3.5 h-3.5" />
            Approve Online Appointments
            {pendingAppointments.length > 0 && (
              <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-bold ${activeTab === 'approve' ? 'bg-white/20 text-white' : 'bg-amber-500 text-white'}`}>
                {pendingAppointments.length}
              </span>
            )}
          </button>

          <button
            onClick={() => handleTabChange('approved')}
            className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-all ${
              activeTab === 'approved'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            <CheckCircle className="w-3.5 h-3.5" />
            Approved Online Appointments
            {approvedAppointments.length > 0 && (
              <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-bold ${activeTab === 'approved' ? 'bg-white/20 text-white' : 'bg-primary/20 text-primary'}`}>
                {approvedAppointments.length}
              </span>
            )}
          </button>

          <button
            onClick={() => handleTabChange('history')}
            className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-semibold transition-all ${
              activeTab === 'history'
                ? 'bg-emerald-600 text-white shadow-md'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            <History className="w-3.5 h-3.5" />
            Online Appointment History
            {completeAppointments.length > 0 && (
              <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-bold ${activeTab === 'history' ? 'bg-white/20 text-white' : 'bg-emerald-500/20 text-emerald-600'}`}>
                {completeAppointments.length}
              </span>
            )}
          </button>
        </div>
      </div>

      {/* Top Bar with Title */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-blue-500/20 to-emerald-500/20 flex items-center justify-center border border-blue-500/30 shadow-sm">
            <Video className="w-5 h-5 text-blue-600" />
          </div>
          <div>
            <h1 className="font-heading text-xl font-bold text-foreground flex items-center gap-2">
              {activeTab === 'approve'
                ? 'Approve Online Appointments'
                : activeTab === 'history'
                ? 'Online Appointment History'
                : 'Approved Online Appointments'
              }
              {activeTab === 'approve' && pendingAppointments.length > 0 && (
                <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-amber-500/15 text-amber-600">
                  {pendingAppointments.length} pending
                </span>
              )}
              {activeTab === 'approved' && approvedAppointments.length > 0 && (
                <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-primary/10 text-primary">
                  {approvedAppointments.length} confirmed
                </span>
              )}
            </h1>
            <p className="text-xs text-muted-foreground">
              {activeTab === 'approve'
                ? 'Review & approve incoming chat, voice & video call requests'
                : activeTab === 'approved'
                ? "Manage scheduled consultations & active online sessions"
                : 'Completed online consultation history & past records'}
            </p>
          </div>
        </div>
      </div>

      {/* Main Content Render based on Active Tab */}
      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {Array.from({ length: 6 }).map((_, i) => (
