import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Search, Users } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/context/AuthContext';
import { api, resolveFileUrl, isValidFileUrl } from '@/lib/api';
import { subSlotFor } from '@/lib/timeSlots';
import { CompletedCard } from '@/components/TodayAppointmentsSection';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function DoctorPatients() {
  const { user } = useAuth();
  const [appointments, setAppointments] = useState<ApiRow[]>([]);
  const [records, setRecords] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  const loadData = async () => {
    setLoading(true);
    try {
      const [a, r] = await Promise.all([
        api.getAppointments(),
        api.getRecords(),
      ]);

      const appts = a?.data || a || [];
      const myAppointments = appts?.filter((apt: Unmodelled) =>
        apt.doctor?.toLowerCase().includes(user?.name?.toLowerCase()) ||
        apt.doctorId?.name?.toLowerCase().includes(user?.name?.toLowerCase())
      ) || [];

      setAppointments(myAppointments);
      setRecords(r?.data || r?.records || r || []);
    } catch (e: any) { toast.error(e.message); }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadData(); }, [user?.name]);

  // All patients who have appointments (actual visits)
  const uniquePatients = [...new Map(appointments.map(a => [a.patient, a])).values()];

  const filteredPatients = uniquePatients.filter(p =>
    !search || p.patient?.toLowerCase().includes(search.toLowerCase())
  );

  const getPatientAppointments = (patientName: Unmodelled) => appointments.filter(a => a.patient === patientName);
  const getVisitCount = (patientName: Unmodelled) => getPatientAppointments(patientName).length;
  const getPatientRecordCount = (patientName: Unmodelled) => records.filter(r => r.patient === patientName).length;

  if (loading) return (
    <div className="flex justify-center py-20">
      <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">My Patients</h1>
          <p className="text-muted-foreground">{filteredPatients.length} patients</p>
        </div>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search patients..."
          className="pl-10"
        />
      </div>

      {/* Patient Cards (completed appointment card) — shown on top */}
      {filteredPatients.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <Users className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No patients yet</p>
          <p className="text-sm text-muted-foreground/70">Patients with appointments will appear here</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredPatients.map((apt, i) => {
            const visitCount = getVisitCount(apt.patient);
            const recordCount = getPatientRecordCount(apt.patient);
            const latestAppt = appointments
              .filter(a => a.patient === apt.patient)
              .sort((a, b) => (+new Date(b.createdAt || 0)) - (+new Date(a.createdAt || 0)))[0];

            return (
              <motion.div
                key={apt._id || apt.patient + i}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.03 }}
                className="scroll-mt-4 flex flex-col"
              >
                <CompletedCard
                  apt={latestAppt || apt}
                  subSlotFor={subSlotFor}
                  onViewFile={(url: Unmodelled) => {
                    if (!isValidFileUrl(url)) { toast.error('File unavailable — upload was not completed. Ask the patient to re-upload it.'); return; }
                    window.open(resolveFileUrl(url), '_blank');
                  }}
                  stats={{ visits: visitCount, records: recordCount }}
                />
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import DoctorRecordsDashboard from '@/components/DoctorRecordsDashboard';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function DoctorPrescriptions() {
  const { user } = useAuth();
  const [records, setRecords] = useState<ApiRow[]>([]);
  const [bills, setBills] = useState<ApiRow[]>([]);
  const [invoices, setInvoices] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);

  const loadAll = useCallback(async () => {
    setLoading(true);
    try {
      const docName = user?.name?.toLowerCase();
      const docId = user?.id || user?._id;

      // 1. Prescriptions (records)
      const recData = await api.getRecords();
      const recArr = recData?.data || recData?.records || recData || [];
      const prescriptions = recArr.filter((r: Unmodelled) => {
        const matchesId = docId && (r.doctorId === docId || r.doctor_id === docId || r.createdBy === docId);
        const matchesName = docName && (r.doctor?.toLowerCase().includes(docName) || r.doctorName?.toLowerCase().includes(docName));
        const isPrescription = r.type?.toLowerCase() === 'prescription';
        return (matchesId || matchesName) && isPrescription;
      });
      setRecords(prescriptions);

      // 2. Bills & Invoices (billing)
      const billData = await api.getBilling();
      const billArr = billData?.data || billData?.bills || billData || [];
      const myBills = billArr.filter((b: Unmodelled) => {
        const matchesId = docId && (b.doctorId === docId || b.doctor_id === docId || b.createdBy === docId);
        const matchesName = docName && (b.doctor?.toLowerCase().includes(docName) || b.doctorName?.toLowerCase().includes(docName));
        return matchesId || matchesName;
      });

      // Split bills vs invoices by billType / data.type
      const billList: Unmodelled[] = [];
      const invoiceList: Unmodelled[] = [];

      myBills.forEach((b: Unmodelled) => {
        const bt = (b.billType || b.data?.type || '').toLowerCase();
        if (bt === 'invoice' || b.data?.isInvoice) {
          invoiceList.push(b);
        } else if (bt === 'bill' || b.data?.isBill) {
          billList.push(b);
        } else {
          // Default: treat items-based records as invoices, simple ones as bills
          const hasItems = (b.data?.items?.length || b.services?.length || 0) > 0;
          if (hasItems && b.service?.toLowerCase().includes('invoice')) invoiceList.push(b);
          else if (b.status === 'Paid' && hasItems) invoiceList.push(b);
          else billList.push(b);
        }
      });

      setBills(billList);
      setInvoices(invoiceList);
    } catch (e: any) {
      toast.error(e.message || 'Failed to load records');
    }
    setLoading(false);
  }, [user?.name]);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadAll(); }, [user?.name]);

  return (
    <DoctorRecordsDashboard
      records={records}
      bills={bills}
      invoices={invoices}
      onRefresh={loadAll}
      loading={loading}
    />
  );
}

