import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * Doc 11 §5 P0 — my OPD queue: waiting tokens for me, call-next, skip,
 * no-show. Fixes D10.
 */
export default function DoctorQueue() {
  const [tokens, setTokens] = useState<any[]>([]);
  const [duty, setDuty] = useState('On duty');
  const [q, setQ] = useState('');
  const [found, setFound] = useState<any[]>([]);
  const [oncall, setOncall] = useState<any[]>([]);
  const [cme, setCme] = useState<any>(null);

  const load = async () => {
    try {
      const r: any = await (api as any).getDoctorDashboard();
      setTokens(r?.data?.queue || []);
      setCme(r?.data?.cme || null);
      const o: any = await (api as any).getOnCall().catch(() => null);
      if (o) setOncall(o?.entries || []);
    } catch { toast.error('Failed to load queue'); }
  };
  useEffect(() => { load(); }, []);

  const setDutyStatus = async (status: string) => {
    try {
      await (api as any).setDutyStatus({ status });
      setDuty(status);
      toast.success(`Duty: ${status}`);
    } catch { toast.error('Failed to update duty'); }
  };

  const searchPatient = async () => {
    if (!q.trim()) return;
    try {
      const r: any = await (api as any).getPatients({ search: q, limit: 5 });
      const list = r?.data || r?.patients || [];
      const withEnc = await Promise.all(list.map(async (p: any) => {
        try {
          const e: any = await (api as any).getLatestEncounter(p._id || p.id);
          return { ...p, encounterId: e?.id || null };
        } catch { return { ...p, encounterId: null }; }
      }));
      setFound(withEnc);
    } catch { setFound([]); }
  };

  const act = async (fn: () => Promise<any>, label: string) => {
    try { await fn(); toast.success(label); load(); }
    catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center gap-2">
        <h1 className="text-2xl font-heading font-bold mr-auto">My OPD Queue ({tokens.length})</h1>
        {['On duty', 'On call', 'Off'].map((s) => (
          <Button key={s} size="sm" variant={duty === s ? 'default' : 'outline'} onClick={() => setDutyStatus(s)}>{s}</Button>
        ))}
        <Button onClick={() => act(() => (api as any).callNextToken({}), 'Next token called')}>Call next</Button>
      </div>
      <Card>
        <CardContent className="p-3 space-y-2">
          <div className="flex gap-2">
            <Input placeholder="Search patient (UHID / name / phone)" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && searchPatient()} />
            <Button variant="outline" onClick={searchPatient}>Search</Button>
          </div>
          {found.map((p: any) => (
            <div key={p._id || p.id} className="flex items-center gap-2 text-sm">
              <span className="font-medium">{p.name}</span>
              {p.encounterId && <Link to={`/doctor/workspace/${p.encounterId}`}><Button size="sm" variant="outline">Open workspace</Button></Link>}
            </div>
          ))}
        </CardContent>
      </Card>
      <div className="space-y-2">
        {tokens.map((t: any) => (
          <Card key={t._id || t.tokenNumber}>
            <CardContent className="p-3 flex items-center gap-2 text-sm">
              <span className="text-lg font-black">{t.tokenNumber}</span>
              <span className="text-muted-foreground">#{t.queuePosition}</span>
              <span className="flex-1" />
              <Button size="sm" variant="outline" onClick={() => act(() => (api as any).callToken(t._id), 'Called')}>Call</Button>
              <Button size="sm" variant="outline" onClick={() => act(() => (api as any).skipToken(t._id), 'Skipped')}>Skip</Button>
              <Button size="sm" variant="outline" onClick={() => act(() => (api as any).noShowToken(t._id), 'Marked no-show')}>No-show</Button>
            </CardContent>
          </Card>
        ))}
        {tokens.length === 0 && <p className="text-sm text-muted-foreground">Queue empty.</p>}
      </div>
      <div className="grid sm:grid-cols-2 gap-3">
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div>
              <p className="text-xs text-muted-foreground">CME credits</p>
              <p className="text-lg font-bold">{cme ? `${cme.credits} (${cme.entries})` : '—'}</p>
            </div>
            <span className="flex-1" />
            <Link to="/doctor/earnings/statement"><Button size="sm" variant="outline">Earnings statement</Button></Link>
          </CardContent>
        </Card>
        {oncall.length > 0 && (
          <Card>
            <CardHeader><CardTitle className="text-base">On-call (this month)</CardTitle></CardHeader>
          <CardContent className="space-y-1 text-sm">
            {oncall.map((e: any, i: number) => (
              <p key={i}>{e.date} · {e.shift} {e.onCall ? '(on-call)' : ''}</p>
            ))}
          </CardContent>
        </Card>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { RotateCcw, Search, Filter, CalendarDays, UserRound, ArrowUpRight, Ban, CheckCircle2 } from 'lucide-react';
import { api } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { toast } from 'sonner';
import { getISTDateString, formatDisplayDate } from '@/lib/dateUtils';
import { motion, AnimatePresence } from 'framer-motion';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function DoctorRefunds() {
  const [refunds, setRefunds] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [selected, setSelected] = useState<Unmodelled>(null);

  const load = async () => {
    setLoading(true);
    try {
      const res = await api.getRefunds({ limit: 500, page: 1 });
      setRefunds(res?.payments || res?.data || res || []);
    } catch {
      toast.error('Failed to load refunds');
    }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleAction = async (id: Unmodelled, action: Unmodelled) => {
    try {
      // Assuming a generic update endpoint or we simulate it if backend lacks it
      await api.put(`/payments/refund/${id}/status`, { status: action });
      toast.success(`Refund marked as ${action}`);
      setSelected(null);
      load();
    } catch {
      toast.error('Failed to update refund status');
    }
  };

  const filtered = refunds.filter(r => {
    const patientName = (r.patient || r.patientName || '').toLowerCase();
    const matchesSearch = patientName.includes(search.toLowerCase()) || (r._id || '').includes(search);
    const matchesFilter = filter === 'All' || r.status === filter;
    return matchesSearch && matchesFilter;
  });

  const totalRefunded = refunds.filter(r => r.status === 'Refunded').reduce((acc, r) => acc + (r.refund_amount || r.amount || 0), 0);
  const pendingCount = refunds.filter(r => r.status === 'Pending').length;

  if (loading) return <div className="flex items-center justify-center h-[50vh]"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold flex items-center gap-2"><RotateCcw className="w-6 h-6 text-primary" /> Refunds & Cancellations</h1>
          <p className="text-sm text-muted-foreground mt-1">Manage refund requests from patient cancellations.</p>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Total Refunded</p>
            <p className="text-2xl font-bold text-destructive">₹{totalRefunded.toLocaleString()}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Pending Requests</p>
            <p className="text-2xl font-bold text-warning">{pendingCount}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">This Month</p>
            <p className="text-2xl font-bold text-foreground">
              {refunds.filter(r => new Date(r.createdAt || r.date).getMonth() === new Date().getMonth()).length}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Total Requests</p>
            <p className="text-2xl font-bold text-foreground">{refunds.length}</p>
          </CardContent>
        </Card>
      </div>

      <div className="bg-card rounded-xl border p-4">
        <div className="flex flex-col sm:flex-row gap-4 mb-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by patient name or ID..." className="pl-10" />
          </div>
          <div className="flex gap-2">
            {['All', 'Pending', 'Refunded', 'Rejected'].map(f => (
              <Button key={f} variant={filter === f ? 'default' : 'outline'} size="sm" onClick={() => setFilter(f)} className="rounded-xl">
                {f}
              </Button>
            ))}
          </div>
        </div>

        {filtered.length === 0 ? (
          <div className="text-center py-12">
            <RotateCcw className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
            <p className="text-muted-foreground font-medium">No refund requests found</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map(r => (
              <div key={r._id} onClick={() => setSelected(r)} className="rounded-xl border hover:border-primary/50 p-4 flex items-center justify-between cursor-pointer transition-colors bg-background">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center ${r.status === 'Refunded' ? 'bg-destructive/10 text-destructive' : r.status === 'Rejected' ? 'bg-muted text-muted-foreground' : 'bg-warning/10 text-warning'}`}>
                    <RotateCcw className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="font-semibold text-sm">{r.patient || r.patientName || 'Unknown Patient'}</p>
                    <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1"><CalendarDays className="w-3 h-3" /> {formatDisplayDate(r.createdAt || r.date)}</span>
                      <span>•</span>
                      <span className="truncate max-w-[200px]">{r.reason || r.description || 'Cancellation'}</span>
                    </div>
                  </div>
                </div>
                <div className="text-right flex flex-col items-end gap-1.5">
                  <p className="font-bold text-foreground">₹{(r.refund_amount || r.amount || 0).toLocaleString()}</p>
                  <Badge variant="outline" className={
                    r.status === 'Refunded' ? 'bg-destructive/10 text-destructive border-transparent' : 
                    r.status === 'Rejected' ? 'bg-muted text-muted-foreground border-transparent' : 
                    'bg-warning/10 text-warning border-transparent'
                  }>
                    {r.status || 'Pending'}
                  </Badge>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <AnimatePresence>
        {selected && (
          <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setSelected(null)}>
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }} 
              animate={{ opacity: 1, scale: 1 }} 
              exit={{ opacity: 0, scale: 0.95 }}
              className="bg-card w-full max-w-lg rounded-2xl border shadow-xl p-6" 
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-start justify-between mb-6">
                <div>
                  <h3 className="font-heading font-bold text-xl">Refund Request</h3>
                  <p className="text-xs text-muted-foreground">ID: {selected._id}</p>
                </div>
                <Badge className={
                  selected.status === 'Refunded' ? 'bg-destructive/10 text-destructive' : 
                  selected.status === 'Rejected' ? 'bg-muted text-muted-foreground' : 
                  'bg-warning/10 text-warning'
                }>
                  {selected.status || 'Pending'}
                </Badge>
              </div>

              <div className="space-y-4 mb-6">
                <div className="flex justify-between items-center p-3 bg-muted/30 rounded-xl">
                  <span className="text-sm text-muted-foreground">Amount</span>
                  <span className="text-lg font-bold">₹{(selected.refund_amount || selected.amount || 0).toLocaleString()}</span>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Patient</p>
                    <p className="text-sm font-medium">{selected.patient || selected.patientName}</p>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Date</p>
                    <p className="text-sm font-medium">{formatDisplayDate(selected.createdAt || selected.date)}</p>
                  </div>
                </div>

                <div>
                  <p className="text-xs text-muted-foreground mb-1">Reason for Cancellation</p>
                  <p className="text-sm p-3 bg-muted/30 rounded-xl">{selected.reason || selected.description || 'No reason provided by patient.'}</p>
                </div>
              </div>

              {selected.status === 'Pending' ? (
                <div className="flex gap-3">
                  <Button className="flex-1 gap-2 bg-success hover:bg-success/90" onClick={() => handleAction(selected._id, 'Refunded')}>
                    <CheckCircle2 className="w-4 h-4" /> Approve Refund
                  </Button>
                  <Button variant="outline" className="flex-1 gap-2 text-destructive hover:bg-destructive hover:text-white" onClick={() => handleAction(selected._id, 'Rejected')}>
                    <Ban className="w-4 h-4" /> Reject
                  </Button>
                </div>
              ) : (
                <Button className="w-full" variant="outline" onClick={() => setSelected(null)}>Close</Button>
              )}
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Star, Calendar, MessageSquare, Send, Reply } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function DoctorReviews() {
  const { user } = useAuth();
  const [reviews, setReviews] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [replyingId, setReplyingId] = useState<Unmodelled>(null);
  const [replyText, setReplyText] = useState<ApiRow>({});

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const data = await api.getReviews();
        setReviews(data.filter((r: Unmodelled) => r.doctorName === user?.name));
      } catch (e: any) { console.error(e); }
      setLoading(false);
    };
    load();
  }, [user?.name]);

  const handleReply = async (reviewId: Unmodelled) => {
    if (!replyText[reviewId]?.trim()) return;
    try {
      const updated = await api.replyToReview(reviewId, { reply: replyText[reviewId] });
      setReviews(prev => prev.map(r => r._id === reviewId ? updated : r));
      setReplyingId(null);
      setReplyText(prev => ({ ...prev, [reviewId]: '' }));
      toast.success('Reply posted');
    } catch {
      toast.error('Failed to post reply');
    }
  };

  const avgRating = reviews.length > 0 ? (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1) : '0';
  const ratingDist = [5,4,3,2,1].map(r => ({ rating: r, count: reviews.filter(rv => rv.rating === r).length, pct: reviews.length > 0 ? (reviews.filter(rv => rv.rating === r).length / reviews.length * 100) : 0 }));

  if (loading) return <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">My Reviews</h1>
        <p className="text-muted-foreground">See what patients are saying about you</p>
      </div>

      {/* Rating Summary */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <div className="flex flex-col sm:flex-row items-center gap-6">
          <div className="text-center">
            <p className="font-heading text-5xl font-extrabold text-foreground">{avgRating}</p>
            <div className="flex items-center gap-0.5 mt-1">
              {[1,2,3,4,5].map(s => <Star key={s} className={`w-5 h-5 ${s <= Math.round(avgRating as Unmodelled) ? 'text-warning fill-warning' : 'text-muted'}`} />)}
            </div>
            <p className="text-sm text-muted-foreground mt-1">{reviews.length} reviews</p>
          </div>
          <div className="flex-1 w-full space-y-1.5">
            {ratingDist.map(d => (
              <div key={d.rating} className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground w-3">{d.rating}</span>
                <Star className="w-3 h-3 text-warning fill-warning" />
                <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                  <div className="h-full bg-warning rounded-full transition-all" style={{ width: `${d.pct}%` }} />
                </div>
                <span className="text-xs text-muted-foreground w-6 text-right">{d.count}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Reviews List */}
      {reviews.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">No reviews yet</div>
      ) : (
        <div className="space-y-4">
          {reviews.map((rv, i) => (
            <motion.div key={rv._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
              className="bg-card rounded-2xl border border-border/60 p-5">
              <div className="flex items-start justify-between mb-2">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary font-bold">
                    {rv.patientName?.charAt(0)}
                  </div>
                  <div>
                    <p className="font-medium text-foreground">{rv.patientName}</p>
                    <div className="flex items-center gap-0.5">
                      {[1,2,3,4,5].map(s => <Star key={s} className={`w-3.5 h-3.5 ${s <= rv.rating ? 'text-warning fill-warning' : 'text-muted'}`} />)}
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-1 text-xs text-muted-foreground">
                  <Calendar className="w-3.5 h-3.5" />{rv.date}
                </div>
              </div>
              {rv.comment && (
                <div className="flex items-start gap-2 mt-3">
                  <MessageSquare className="w-4 h-4 text-muted-foreground mt-0.5 flex-shrink-0" />
                  <p className="text-sm text-muted-foreground">{rv.comment}</p>
                </div>
              )}
              {/* Doctor Reply */}
              {rv.reply && (
                <div className="mt-3 ml-6 p-3 bg-primary/5 rounded-xl border border-primary/10">
                  <div className="flex items-center gap-2 mb-1">
                    <Reply className="w-3.5 h-3.5 text-primary" />
                    <span className="text-xs font-semibold text-primary">Your Reply</span>
                    {rv.repliedAt && (
                      <span className="text-xs text-muted-foreground">{new Date(rv.repliedAt).toLocaleDateString()}</span>
                    )}
                  </div>
                  <p className="text-sm text-foreground">{rv.reply}</p>
                </div>
              )}
              {/* Reply Button / Form */}
              {!rv.reply && replyingId !== rv._id && (
                <Button variant="ghost" size="sm" className="mt-3 gap-1.5 text-muted-foreground" onClick={() => { setReplyingId(rv._id); setReplyText(prev => ({ ...prev, [rv._id]: '' })); }}>
                  <Reply className="w-3.5 h-3.5" /> Reply
                </Button>
              )}
              {replyingId === rv._id && (
                <div className="mt-3 flex gap-2">
                  <textarea value={replyText[rv._id] || ''} onChange={e => setReplyText(prev => ({ ...prev, [rv._id]: e.target.value }))}
                    placeholder="Write your reply..."
                    className="flex-1 px-3 py-2 rounded-lg border border-border bg-background text-foreground text-sm resize-none h-20" />
                  <div className="flex flex-col gap-2">
                    <Button size="sm" className="gap-1" onClick={() => handleReply(rv._id)} disabled={!replyText[rv._id]?.trim()}>
                      <Send className="w-3.5 h-3.5" /> Post
                    </Button>
                    <Button variant="ghost" size="sm" onClick={() => setReplyingId(null)}>Cancel</Button>
                  </div>
                </div>
              )}
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Clock, Calendar, Settings, Info } from 'lucide-react';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import type { Unmodelled } from '@/lib/apiTypes';

const allTimeSlots = [
  '08:00 AM', '08:30 AM', '09:00 AM', '09:30 AM', '10:00 AM', '10:30 AM',
  '11:00 AM', '11:30 AM', '12:00 PM', '12:30 PM', '02:00 PM', '02:30 PM',
  '03:00 PM', '03:30 PM', '04:00 PM', '04:30 PM', '05:00 PM', '05:30 PM'
];

const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

export default function DoctorSchedule() {
  const { user } = useAuth();
  const [doctor, setDoctor] = useState<Unmodelled>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const doctors = (await api.getDoctors())?.data || [];
        const myDoc = doctors.find((d: Unmodelled) => d.email === user?.email) || doctors.find((d: Unmodelled) => d.name?.includes(user?.name)) || null;
        if (myDoc) {
          setDoctor(myDoc);
        }
      } catch (e: any) { toast.error(e.message); }
      setLoading(false);
    };
    load();
  }, [user?.email, user?.name]);

  if (loading) return <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  if (!doctor) return (
    <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
      <Calendar className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
      <p className="text-muted-foreground text-lg">Schedule not available</p>
      <p className="text-sm text-muted-foreground/70">Contact admin to set your schedule</p>
    </div>
  );

  const selectedSlots = doctor.time_slots || [];
  const schedule = doctor.weekly_schedule || {};
  const leaves = doctor.leaves || [];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">My Schedule</h1>
        <p className="text-muted-foreground">Your schedule is managed by the hospital administration</p>
      </div>

      {/* Read-only notice */}
      <div className="bg-info/10 border border-info/20 rounded-2xl p-4 flex items-start gap-3">
        <Info className="w-5 h-5 text-info mt-0.5 shrink-0" />
        <div>
          <p className="font-medium text-foreground">Schedule managed by Admin</p>
          <p className="text-sm text-muted-foreground mt-0.5">This is a view-only schedule. Please contact the hospital administration for any changes.</p>
        </div>
      </div>

      {/* Time Slots */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <h2 className="font-heading text-lg font-semibold text-foreground mb-4 flex items-center gap-2">
          <Clock className="w-5 h-5 text-primary" /> Available Time Slots
        </h2>
        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">
          {allTimeSlots.map(slot => {
            const active = selectedSlots.includes(slot);
            return (
              <div key={slot}
                className={`px-3 py-2 rounded-lg text-sm font-medium text-center transition-all ${active ? 'bg-primary text-primary-foreground shadow-md' : 'bg-muted/50 text-muted-foreground'}`}>
                {slot}
              </div>
            );
          })}
        </div>
        <p className="text-xs text-muted-foreground mt-3">{selectedSlots.length} time slots available</p>
      </div>

      {/* Weekly Schedule */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <h2 className="font-heading text-lg font-semibold text-foreground mb-4 flex items-center gap-2">
          <Calendar className="w-5 h-5 text-primary" /> Weekly Schedule
        </h2>
        <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-7 gap-3">
          {days.map(day => (
            <div key={day}
              className={`p-4 rounded-xl text-center transition-all border-2 ${schedule[day] ? 'border-primary bg-primary/10 text-primary' : 'border-border bg-muted/50 text-muted-foreground'}`}>
              <p className="font-semibold capitalize text-sm">{day}</p>
              <p className="text-xs mt-1 opacity-70">{schedule[day] ? 'Available' : 'Off'}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Leaves */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
