export default function DoctorVideoCallRoom() {
  const { appointmentId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();

  const [loading, setLoading] = useState(true);
  const [appointment, setAppointment] = useState<Unmodelled>(null);
  const [patient, setPatient] = useState<Unmodelled>(null);

  // Call Controls State
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOn, setIsVideoOn] = useState(true);
  const [isSpeakerOn, setIsSpeakerOn] = useState(true);
  const [callDuration, setCallDuration] = useState(0);

  // Tabs State (info | prescription | history)
  const [activeTab, setActiveTab] = useState('info');

  // Prescription State
  const [diagnosis, setDiagnosis] = useState('');
  const [chiefComplaints, setChiefComplaints] = useState('');
  const [medications, setMedications] = useState([{ name: '', dosage: '', frequency: '', instructions: '' }]);
  const [advice, setAdvice] = useState('');
  const [followUp, setFollowUp] = useState('');
  const [savingPrescription, setSavingPrescription] = useState(false);

  // Fetch Appointment Details
  useEffect(() => {
    const fetchDetails = async () => {
      try {
        setLoading(true);
        const data = await api.getAppointments({ status: 'All', limit: 200 });
        const all = data?.appointments || data?.data || data || [];
        const apt = all.find((a: Unmodelled) => a._id === appointmentId);

        if (!apt) {
          toast.error('Appointment not found');
          navigate(-1);
          return;
        }
        setAppointment(apt);
        setPatient(apt.patientId || {});

        if (apt.preConsultationDetails) {
          setChiefComplaints(
            apt.preConsultationDetails.chiefComplaint === 'Other' 
            ? apt.preConsultationDetails.chiefComplaintOther 
            : apt.preConsultationDetails.chiefComplaint || ''
          );
        }
      } catch (err: any) {
        toast.error('Failed to load appointment details');
      } finally {
        setLoading(false);
      }
    };
    if (appointmentId) fetchDetails();
  }, [appointmentId, navigate]);

  // Timer
  useEffect(() => {
    const timer = setInterval(() => {
      setCallDuration(prev => prev + 1);
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const formatTime = (secs: Unmodelled) => {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  const handleEndCall = async () => {
    toast.success('Video Call ended successfully');
    navigate(-1);
  };

  const handleSavePrescription = async () => {
    if (!diagnosis) return toast.error('Please enter a diagnosis');
    const validMeds = medications.filter(m => m.name.trim());

    setSavingPrescription(true);
    try {
      await api.createRecord({
        patient: appointment.patient,
        patientId: patient?._id || appointment.patientId,
        doctor: user?.name,
        diagnosis: diagnosis,
        prescription: validMeds.map(m => `${m.name} - ${m.dosage} - ${m.frequency} ${m.instructions ? '(' + m.instructions + ')' : ''}`).join('\n'),
        type: 'prescription',
        notes: `Chief Complaints: ${chiefComplaints}\nAdvice: ${advice}\nFollow-up: ${followUp}`,
        data: {
          patient: { 
            name: appointment.patient, 
            age: patient?.dateOfBirth ? Math.floor((+new Date() - +new Date(patient.dateOfBirth)) / 31557600000) : '', 
            gender: patient?.gender, 
            phone: patient?.phone 
          },
          doctor: { name: user?.name, specialization: user?.specialization },
          chiefComplaints,
          diagnosis,
          medications: validMeds,
          advice,
          followUp,
          date: getISTDateString(),
        },
      });

      if (appointment.status !== 'Completed') {
        await api.updateAppointment(appointment._id, { status: 'Completed' });
      }

      toast.success('Prescription saved and sent to patient');
      handleEndCall();
    } catch (e: any) {
      toast.error('Failed to save prescription');
      console.error(e);
    } finally {
      setSavingPrescription(false);
    }
  };

  const updateMedication = (index: Unmodelled, field: Unmodelled, value: Unmodelled) => {
    const meds: Unmodelled = [...medications];
    meds[index][field] = value;
    setMedications(meds);
  };

  const removeMedication = (index: Unmodelled) => {
    setMedications(medications.filter((_, i) => i !== index));
  };

  if (loading) {
    return (
      <div className="fixed inset-0 bg-background flex items-center justify-center z-50">
        <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-background z-50 flex flex-col md:flex-row overflow-hidden">
      {/* ════════ LEFT PANEL: Active Video Stage ════════ */}
      <div className="flex-1 bg-zinc-950 flex flex-col relative text-white">
        {/* Top bar inside call */}
        <div className="absolute top-0 inset-x-0 p-6 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent z-20">
          <Button variant="ghost" className="text-white hover:bg-white/10 backdrop-blur-md" onClick={() => navigate(-1)}>
            <ChevronLeft className="w-5 h-5 mr-1" /> Leave quietly
          </Button>
          <div className="flex items-center gap-2 bg-black/60 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 shadow-xl">
            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
            <span className="font-mono text-sm tracking-wider font-medium">{formatTime(callDuration)}</span>
          </div>
        </div>

        {/* Central Video Feed (Mock for Patient) */}
        <div className="flex-1 relative w-full h-full bg-zinc-900 overflow-hidden flex items-center justify-center">
           {/* Fallback avatar if simulated video feed is off or loading */}
           <div className="absolute inset-0 flex flex-col items-center justify-center opacity-30 pointer-events-none">
             <User className="w-32 h-32 text-white/50 mb-4" />
             <p className="text-xl font-bold tracking-wider text-white/70">Connecting to Patient...</p>
           </div>

           {/* Simulated Patient Video Feed */}
           <div className="w-full h-full object-cover bg-gradient-to-tr from-indigo-900/40 to-cyan-900/40 relative z-10 flex items-center justify-center">
             <div className="w-32 h-32 rounded-full bg-zinc-800 flex items-center justify-center text-5xl font-bold text-white shadow-2xl border-4 border-white/10">
               {patient?.avatar ? (
                 <img src={patient.avatar} alt={appointment?.patient} className="w-full h-full object-cover rounded-full" />
               ) : (
                 (appointment?.patient || '?').slice(0, 2).toUpperCase()
               )}
             </div>
           </div>

           {/* Patient Name Overlay */}
           <div className="absolute bottom-36 left-6 z-20 bg-black/50 backdrop-blur-md px-4 py-2 rounded-lg border border-white/10">
             <p className="font-semibold">{appointment?.patient}</p>
           </div>

           {/* Picture in Picture (Mock for Doctor Local Camera) */}
           <motion.div 
             drag
             dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
             dragElastic={0.1}
