          {[
            { id: 'all', label: 'All Video Calls' },
            { id: 'incoming', label: 'Incoming' },
            { id: 'outgoing', label: 'Outgoing' },
            { id: 'missed', label: 'Missed' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-3.5 py-1.5 text-xs font-medium rounded-lg transition-all whitespace-nowrap ${
                activeTab === tab.id
                  ? 'bg-card text-foreground shadow-sm font-semibold'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="relative w-full sm:w-72">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search by patient name or phone..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 h-9 text-xs rounded-xl bg-card border-border/70"
          />
        </div>
      </div>

      {/* ── VIDEO CALL LOGS TABLE ── */}
      <div className="rounded-2xl border border-border/80 bg-card overflow-hidden shadow-sm">
        {loading ? (
          <div className="p-12 text-center text-muted-foreground flex flex-col items-center gap-2">
            <RefreshCw className="w-6 h-6 animate-spin text-cyan-500" />
            <span className="text-xs">Loading video consultations...</span>
          </div>
        ) : filteredCalls.length === 0 ? (
          <div className="p-16 text-center text-muted-foreground flex flex-col items-center">
            <div className="w-14 h-14 rounded-2xl bg-cyan-500/10 text-cyan-500 flex items-center justify-center mb-3">
              <VideoOff className="w-7 h-7" />
            </div>
            <h4 className="text-base font-semibold text-foreground">No video calls recorded</h4>
            <p className="text-xs text-muted-foreground max-w-sm mt-1 mb-4">
              Start a high-definition 1080p video consultation directly with your scheduled patients.
            </p>
            <Button size="sm" onClick={openDialModal} className="h-9 px-4 gap-2 text-xs">
              <Plus className="w-3.5 h-3.5" /> Start New Video Call
            </Button>
          </div>
        ) : (
          <DataGrid
            columns={callColumns}
            rows={callRows}
            rowKey="_id"
            empty="No video calls recorded"
            showSearch={false}
            manualPagination
            rowClassName={() => 'border-border/40 hover:bg-muted/30 transition-colors'}
          />
        )}
      </div>

      {/* ── QUICK DIAL MODAL ── */}
      <Dialog open={showDialModal} onOpenChange={setShowDialModal}>
        <DialogContent className="max-w-md rounded-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-lg">
              <Video className="w-5 h-5 text-cyan-500" /> Start 1-to-1 Video Call
            </DialogTitle>
            <DialogDescription className="text-xs">
              {isPatient
                ? 'Select a doctor from your care team to initiate an instant 1080p Full HD video call.'
                : 'Select a patient from your consultation queue to initiate an instant 1080p Full HD video call.'}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 pt-2">
            <div className="relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder={isPatient ? 'Search doctors by name or specialty...' : 'Search patients by name or phone...'}
                value={contactSearch}
                onChange={(e) => setContactSearch(e.target.value)}
                className="pl-9 text-xs h-9"
              />
            </div>

            <div className="max-h-72 overflow-y-auto divide-y divide-border/50 border rounded-xl">
              {loadingContacts ? (
                <div className="p-8 text-center text-xs text-muted-foreground flex flex-col items-center gap-2">
                  <RefreshCw className="w-5 h-5 animate-spin text-cyan-500" />
                  Loading directory...
                </div>
              ) : filteredContacts.length === 0 ? (
                <div className="p-8 text-center text-xs text-muted-foreground">
                  No {isPatient ? 'doctors' : 'patients'} found.
                </div>
              ) : (
                filteredContacts.map((contact) => (
                  <div
                    key={contact._id}
                    className="p-3 flex items-center justify-between hover:bg-muted/40 transition-colors"
                  >
                    <div className="flex items-center gap-2.5">
                      {contact.avatar ? (
                        <img
                          src={contact.avatar}
                          alt={contact.name}
                          className="w-9 h-9 rounded-full object-cover"
                        />
                      ) : (
                        <div className="w-9 h-9 rounded-full bg-cyan-500/10 text-cyan-600 dark:text-cyan-400 flex items-center justify-center font-bold text-xs">
                          {getInitials(contact.name)}
                        </div>
                      )}
                      <div>
                        <div className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                          {contact.name}
                          {contact.isOnline && (
                            <span className="w-2 h-2 rounded-full bg-emerald-500" title="Online" />
                          )}
                        </div>
                        <div className="text-[11px] text-muted-foreground">{contact.specialization || contact.phone || 'No phone'}</div>
                      </div>
                    </div>

                    <Button
                      size="sm"
                      onClick={() => {
                        setShowDialModal(false);
                        initiateVideoCall(contact);
                      }}
                      className="h-8 px-3 gap-1.5 text-xs bg-cyan-600 hover:bg-cyan-700 text-white font-medium rounded-lg"
                    >
                      <Video className="w-3.5 h-3.5" /> Call
                    </Button>
                  </div>
                ))
              )}
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * Doc 11 P1 — earnings statement: completed visits, facility commission
 * terms, payout batches + TDS note. Per-service breakup needs per-visit
 * fee attribution (not yet stored — shown as pending).
 */
export default function EarningsStatement() {
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    (async () => {
      try {
        const r: any = await (api as any).getEarningsStatement({});
        setData(r);
      } catch { toast.error('Failed to load statement'); }
    })();
  }, []);

  if (!data) return <p className="text-sm text-muted-foreground p-4">Loading statement…</p>;

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-heading font-bold">Earnings Statement</h1>
      <div className="grid sm:grid-cols-3 gap-3">
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Completed visits</p><p className="text-xl font-bold">{data.completedVisits}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Commission</p><p className="text-xl font-bold">{data.commission ? `${data.commission.percent}%${data.commission.cap ? ` (cap ₹${data.commission.cap})` : ''}` : '—'}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Schedule</p><p className="text-xl font-bold capitalize">{data.commission?.schedule || '—'}</p></CardContent></Card>
      </div>
      <Card>
        <CardHeader><CardTitle className="text-base">Payout batches</CardTitle></CardHeader>
        <CardContent className="space-y-1.5 text-sm">
          {(data.payouts || []).map((p: any, i: number) => (
            <p key={i} className="flex justify-between">
              <span>{p.period?.[0] ? new Date(p.period[0]).toLocaleDateString('en-IN') : ''} → {p.period?.[1] ? new Date(p.period[1]).toLocaleDateString('en-IN') : ''} · {p.status}</span>
              <b>₹{Number(p.net || 0).toLocaleString('en-IN')}</b>
            </p>
          ))}
          {!(data.payouts || []).length && <p className="text-muted-foreground">No payouts yet.</p>}
        </CardContent>
      </Card>
      <p className="text-xs text-muted-foreground">{data.note}</p>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import PatientBanner from '@/components/clinical/PatientBanner';
import DdiCheckBanner from '@/components/clinical/DdiCheckBanner';

/**
 * Doc 11 §4 — EMR workspace: patient banner (allergies red), timeline,
 * orders, prescriptions, charges, scribe draft. Sign/finalize stays in the
 * prescription flow (e-sign + QR there).
 */
type Tab = 'timeline' | 'orders' | 'prescriptions' | 'billing';

export default function EmrWorkspace() {
  const { encounterId } = useParams();
  const [data, setData] = useState<any>(null);
  const [tab, setTab] = useState<Tab>('timeline');
  const [draft, setDraft] = useState<any>(null);
  const [note, setNote] = useState({ diagnosis: '', diagnosisIcd: '', soap: '' });
  const [isDdiBlocked, setIsDdiBlocked] = useState(false);
  const [prescribedDrugs, setPrescribedDrugs] = useState<string[]>([]);
  const [newDrugInput, setNewDrugInput] = useState('');

  const load = async () => {
    try {
      const r: any = await (api as any).getWorkspace(encounterId);
      setData(r);
    } catch { toast.error('Failed to load workspace'); }
  };
  useEffect(() => { load(); }, [encounterId]);

  const scribe = async () => {
    try {
      const r: any = await (api as any).scribeDraft({ encounterId });
      setDraft(r?.draft || null);
      toast.success('Draft composed — review before signing');
    } catch { toast.error('Scribe failed'); }
  };

  if (!data) return <p className="text-sm text-muted-foreground p-4">Loading workspace…</p>;
  const p = data.patient || {};
  const allergies = (p.allergies || []).map((a: any) => a.allergen || a);
  const activeRxDrugs = (data.prescriptions || []).flatMap((pr: any) => (pr.medicines || []).map((m: any) => m.medicineName || m.name)).filter(Boolean);
  const allCurrentDrugs = Array.from(new Set([...activeRxDrugs, ...prescribedDrugs]));

  return (
    <div className="space-y-4">
      {/* Patient banner */}
      <PatientBanner patientId={p._id || p.id || ''} />
      <Card className="border-l-4 border-l-primary">
        <CardContent className="p-4 flex flex-wrap items-center gap-x-4 gap-y-1 text-sm">
          <span className="text-lg font-bold">{p.name}</span>
          <span className="text-muted-foreground">{p.gender} · UHID {(data.encounter as any)?.uhid || '—'}</span>
          {p.bloodGroup && <span className="font-bold text-red-600">{p.bloodGroup}</span>}
          {allergies.length > 0 && (
            <span className="font-bold text-red-700 bg-red-100 px-2 py-0.5 rounded">⚠ Allergy: {allergies.join(', ')}</span>
          )}
          <span className="flex-1" />
          <Link to="/doctor/patients"><Button size="sm" variant="outline">All patients</Button></Link>
          <Button size="sm" variant="outline" onClick={scribe}>Dictate / Scribe draft</Button>
          {(data.encounter as any)?.status === 'Open' && (
            <Button
              size="sm"
              disabled={isDdiBlocked}
              title={isDdiBlocked ? 'Major drug interaction detected. Document clinical override to proceed.' : undefined}
              onClick={async () => {
                if (isDdiBlocked) {
                  toast.error('Major drug interaction detected — please record clinical override before signing');
                  return;
                }
                try {
                  await (api as any).signWorkspace(encounterId);
                  toast.success('Visit signed & closed');
                  load();
                } catch { toast.error('Sign failed'); }
              }}
            >
              Sign & finalize
            </Button>
          )}
        </CardContent>
      </Card>

      {draft && (
        <Card className="border-dashed">
          <CardHeader><CardTitle className="text-base">SOAP draft (review required)</CardTitle></CardHeader>
          <CardContent className="space-y-1 text-sm">
            <p><b>S:</b> {draft.subjective}</p>
            <p><b>O:</b> {draft.objective}</p>
            <p><b>A:</b> {draft.assessment}</p>
            <p><b>P:</b> {draft.plan}</p>
            <p className="text-xs text-muted-foreground">{draft.disclaimer}</p>
          </CardContent>
        </Card>
      )}

      <div className="flex gap-1 bg-muted/50 rounded-lg p-1 w-fit">
        {(['timeline', 'orders', 'prescriptions', 'billing'] as Tab[]).map((t) => (
          <button key={t} onClick={() => setTab(t)} className={`px-3 py-1.5 rounded-md text-sm font-medium capitalize ${tab === t ? 'bg-background shadow-sm' : 'text-muted-foreground'}`}>{t}</button>
        ))}
      </div>

      {tab === 'timeline' && (
        <div className="space-y-2">
          <Card>
            <CardContent className="p-3 space-y-2">
              <div className="grid sm:grid-cols-2 gap-2">
                <Input placeholder="Diagnosis" value={note.diagnosis} onChange={(e) => setNote({ ...note, diagnosis: e.target.value })} />
                <Input placeholder="ICD-10 (e.g. J06.9)" value={note.diagnosisIcd} onChange={(e) => setNote({ ...note, diagnosisIcd: e.target.value })} />
              </div>
              <Input placeholder="SOAP note" value={note.soap} onChange={(e) => setNote({ ...note, soap: e.target.value })} />
              <Button
                size="sm"
                disabled={!note.diagnosis && !note.soap}
                onClick={async () => {
                  try {
                    await (api as any).saveWorkspaceNote(encounterId, note);
                    toast.success('Note filed');
                    setNote({ diagnosis: '', diagnosisIcd: '', soap: '' });
                    load();
                  } catch { toast.error('Save failed'); }
                }}
              >
                File consult note
              </Button>
            </CardContent>
          </Card>
          {(data.timeline || []).map((r: any) => (
            <Card key={r._id}><CardContent className="p-3 text-sm">
              <p className="font-medium">{r.diagnosis || r.type}</p>
              <p className="text-xs text-muted-foreground">{r.createdAt ? new Date(r.createdAt).toLocaleDateString('en-IN') : ''} · {r.doctor}</p>
            </CardContent></Card>
          ))}
          {!(data.timeline || []).length && <p className="text-sm text-muted-foreground">No prior records.</p>}
        </div>
      )}
      {tab === 'orders' && (
        <div className="space-y-2">
          {(data.orders || []).map((o: any) => (
            <Card key={o._id}><CardContent className="p-3 text-sm flex gap-2">
              <span className="font-bold capitalize">{o.kind}</span>
              <span className="text-[11px] px-2 py-0.5 rounded-full bg-muted">{o.status}</span>
              <span className="text-muted-foreground">{o.priority}</span>
            </CardContent></Card>
          ))}
          {!(data.orders || []).length && <p className="text-sm text-muted-foreground">No orders in this encounter.</p>}
        </div>
      )}
      {tab === 'prescriptions' && (
        <div className="space-y-3">
          <Card className="border-border/70 shadow-sm">
            <CardHeader className="p-3 border-b bg-muted/20">
              <CardTitle className="text-sm font-semibold flex items-center justify-between">
                <span>Active Prescriptions in Encounter</span>
                <span className="text-xs text-muted-foreground font-normal">Real-time DDI screening enabled</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="p-3 space-y-3">
              <div className="flex gap-2">
                <Input
                  placeholder="Type drug name (e.g. Warfarin 5mg, Aspirin 75mg, Metformin 500mg)"
                  value={newDrugInput}
                  onChange={(e) => setNewDrugInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && newDrugInput.trim()) {
                      e.preventDefault();
                      setPrescribedDrugs((prev) => [...prev, newDrugInput.trim()]);
                      setNewDrugInput('');
                    }
                  }}
                  className="text-xs"
                />
                <Button
                  size="sm"
                  type="button"
                  onClick={() => {
                    if (newDrugInput.trim()) {
                      setPrescribedDrugs((prev) => [...prev, newDrugInput.trim()]);
                      setNewDrugInput('');
                    }
                  }}
                  className="text-xs"
                >
                  Add Drug
                </Button>
              </div>

              {prescribedDrugs.length > 0 && (
                <div className="flex flex-wrap gap-1.5 pt-1">
                  {prescribedDrugs.map((d, i) => (
                    <span key={i} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-primary/10 text-primary text-xs font-medium border border-primary/20">
                      {d}
                      <button
                        type="button"
                        className="text-primary hover:text-red-600 transition-colors"
                        onClick={() => setPrescribedDrugs((prev) => prev.filter((_, idx) => idx !== i))}
                        aria-label={`Remove ${d}`}
                      >
                        ×
                      </button>
                    </span>
                  ))}
                </div>
              )}

              {allCurrentDrugs.length >= 2 && (
                <DdiCheckBanner
                  drugs={allCurrentDrugs}
                  onMajorStateChange={setIsDdiBlocked}
                  prescriptionId={(data.encounter as any)?._id}
                />
              )}
            </CardContent>
          </Card>

          {(data.prescriptions || []).map((x: any) => (
            <Card key={x._id}><CardContent className="p-3 text-sm">
              <p className="font-medium">{(x.medicines || []).map((m: any) => m.medicineName).join(', ')}</p>
              <p className="text-xs text-muted-foreground">{x.diagnosis} {x.diagnosisIcd ? `(${x.diagnosisIcd})` : ''}</p>
            </CardContent></Card>
          ))}
          {!(data.prescriptions || []).length && !prescribedDrugs.length && <p className="text-sm text-muted-foreground">No prescriptions.</p>}
        </div>
      )}
      {tab === 'billing' && (
        <Card><CardContent className="p-3 text-sm space-y-1">
          {(data.charges || []).map((c: any) => (
            <p key={c._id} className="flex justify-between"><span>{c.description}</span><b>₹{c.amount}</b></p>
          ))}
          <p className="flex justify-between font-bold border-t pt-1">
            <span>Total</span><span>₹{(data.charges || []).reduce((s: number, c: any) => s + (c.amount || 0), 0)}</span>
          </p>
        </CardContent></Card>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * Doc 11 §5 P1 — consult/referral inbox (second-opinion requests addressed
 * to me). Fixes D11 (visibility; decisions stay in the second-opinion flow).
 */
export default function ReferralsInbox() {
  const [rows, setRows] = useState<any[]>([]);

  useEffect(() => {
    (async () => {
      try {
        const r: any = await (api as any).getSecondOpinionInbox();
        setRows(r?.requests || r?.data || []);
      } catch { toast.error('Failed to load referrals'); }
    })();
  }, []);

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-heading font-bold">Referrals ({rows.length})</h1>
      <div className="space-y-2">
        {rows.map((q: any) => (
          <Card key={q._id}>
            <CardContent className="p-3 text-sm">
              <p className="font-medium">{q.subject || q.reason || 'Consult request'}</p>
              <p className="text-xs text-muted-foreground mt-0.5">
                Status: {q.status} · {q.createdAt ? new Date(q.createdAt).toLocaleDateString('en-IN') : ''}
              </p>
            </CardContent>
          </Card>
        ))}
        {rows.length === 0 && <p className="text-sm text-muted-foreground">No pending referrals.</p>}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

/**
 * Doc 11 §5 P0 — results inbox: critical first, explicit ack (audited
 * server-side). Fixes D5 (server-filtered to my orders) and D9.
 */
export default function ResultsInbox() {
  const [rows, setRows] = useState<any[]>([]);

  const load = async () => {
    try {
      const r: any = await (api as any).getReviewInbox();
      const list = r?.orders || [];
      const rank = (o: any) => ((o.tests || []).some((t: any) => t.isCritical) ? 0 : 1);
      setRows([...list].sort((a, b) => rank(a) - rank(b)));
    } catch { toast.error('Failed to load results inbox'); }
  };
  useEffect(() => { load(); }, []);

  const ack = async (id: string) => {
    try {
      await (api as any).reviewLabOrder(id);
      toast.success('Marked reviewed');
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-heading font-bold">Results Inbox ({rows.length})</h1>
      <div className="space-y-2">
        {rows.map((o: any) => {
          const critical = (o.tests || []).some((t: any) => t.isCritical);
          return (
            <Card key={o._id} className={critical ? 'border-destructive' : ''}>
              <CardContent className="p-3 flex flex-wrap items-center gap-2 text-sm">
                <span className="font-mono text-xs">{o.orderId}</span>
                <span className="font-medium">{o.patientName}</span>
                <span className="text-xs text-muted-foreground">{(o.tests || []).map((t: any) => t.testName).join(', ')}</span>
                {critical && <span className="text-[11px] font-bold px-2 py-0.5 rounded-full bg-destructive/10 text-destructive">CRITICAL — must ack</span>}
                <span className="flex-1" />
                <Button size="sm" onClick={() => ack(o._id)}>Acknowledge</Button>
              </CardContent>
            </Card>
          );
        })}
        {rows.length === 0 && <p className="text-sm text-muted-foreground">Inbox clear 🎉</p>}
      </div>
    </div>
  );
}

