    </div>
  );
}

import { useEffect, useState } from 'react';
import { Check, X, Clock } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';

/** File 13 §13.2: my approvals inbox + delegation manager. */
export default function ApprovalsInbox() {
  const [rows, setRows] = useState<any[]>([]);
  const [delegations, setDelegations] = useState<any[]>([]);
  const [comment, setComment] = useState('');
  const [form, setForm] = useState({ toUser: '', from: '', to: '' });

  const load = async () => {
    try {
      const r: any = await api.approvalRequests({ mine: '1' });
      setRows(r?.requests || []);
      const d: any = await api.approvalDelegations();
      setDelegations(d?.delegations || []);
    } catch { toast.error('Failed to load approvals'); }
  };
  useEffect(() => { load(); }, []);

  const decide = async (id: string, decision: 'approved' | 'rejected') => {
    try {
      const r: any = await api.approvalDecide(id, { decision, comment });
      toast.success(`Request ${r?.status}`);
      setComment('');
      load();
    } catch (e: any) { toast.error(e?.message || 'Decision failed'); }
  };

  const delegate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await api.createDelegation({ ...form });
      toast.success('Delegation saved');
      setForm({ toUser: '', from: '', to: '' });
      load();
    } catch (err: any) { toast.error(err?.message || 'Save failed'); }
  };

  return (
    <div className="grid gap-4 p-4 lg:grid-cols-[1fr_320px]">
      <Card>
        <CardHeader><CardTitle className="text-sm">My approvals ({rows.length})</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          {rows.map((r) => (
            <div key={r._id} className="rounded-md border p-3">
              <div className="flex items-center justify-between">
                <p className="font-semibold text-sm">{r.title} <StatusPill status={r.status} /></p>
                <span className="text-xs text-muted-foreground">₹{r.amount}</span>
              </div>
              <div className="mt-1 flex flex-wrap gap-1">
                {(r.steps || []).map((s: any, i: number) => (
                  <span key={i} className={`rounded border px-1.5 py-0.5 text-[11px] ${s.status === 'approved' ? 'border-green-300 bg-green-50' : s.status === 'rejected' ? 'border-red-300 bg-red-50' : 'border-border'}`}>
                    {s.role}: {s.status}
                  </span>
                ))}
              </div>
              <div className="mt-2 flex gap-2">
                <Input className="h-8 text-xs" placeholder="comment (required for reject)" value={comment} onChange={(e) => setComment(e.target.value)} />
                <Button size="sm" onClick={() => decide(r._id, 'approved')}><Check size={14} /> Approve</Button>
                <Button size="sm" variant="destructive" onClick={() => decide(r._id, 'rejected')}><X size={14} /> Reject</Button>
              </div>
            </div>
          ))}
          {rows.length === 0 ? <EmptyState title="Inbox zero" hint="Pending requests where you are an eligible approver (delegations honoured) appear here." /> : null}
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle className="flex items-center gap-1 text-sm"><Clock size={14} /> Delegations</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          {delegations.map((d) => (
            <p key={d._id} className="rounded border px-2 py-1 text-xs">{String(d.fromUser).slice(-6)} → {String(d.toUser).slice(-6)} · {String(d.from).slice(0, 10)} → {String(d.to).slice(0, 10)}</p>
          ))}
          <form onSubmit={delegate} className="space-y-2 border-t pt-2">
            <Input placeholder="to user id" value={form.toUser} onChange={(e) => setForm({ ...form, toUser: e.target.value })} required />
            <div className="flex gap-2">
              <Input type="date" value={form.from} onChange={(e) => setForm({ ...form, from: e.target.value })} required />
              <Input type="date" value={form.to} onChange={(e) => setForm({ ...form, to: e.target.value })} required />
            </div>
            <Button size="sm" type="submit">Save delegation</Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { BedDouble } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { BedTile } from '@/components/clinical/StatusAtoms';

/** File 13 §13.6 + File 19 §19.5: ward bed board (filter + occupancy). */
const STATUSES = ['Available', 'Occupied', 'Under Cleaning', 'Maintenance', 'Reserved', 'Blocked', 'Isolation'];

export default function BedBoard() {
  const [beds, setBeds] = useState<any[]>([]);
  const [q, setQ] = useState('');
  const [status, setStatus] = useState('');
  const [selected, setSelected] = useState<any | null>(null);
  const [nextStatus, setNextStatus] = useState('');
  const [saving, setSaving] = useState(false);
  const { user } = useAuth();
  const canEdit = ['superadmin', 'hospital_admin'].includes(user?.role || '');

  const load = async () => {
    try {
      const res: any = await api.get('/beds');
      const list = res?.beds || (Array.isArray(res) ? res : []);
      setBeds(list);
    } catch { toast.error('Failed to load beds'); }
  };
  useEffect(() => { load(); }, []);

  const saveStatus = async () => {
    if (!selected || !nextStatus || nextStatus === selected.status) return;
    setSaving(true);
    try {
      await api.updateBed(selected._id, { status: nextStatus });
      toast.success(`${selected.bedNumber} → ${nextStatus}`);
      setSelected(null);
      await load();
    } catch (e: any) {
      toast.error(e?.message || 'Failed to update status');
    } finally { setSaving(false); }
  };

  const filtered = beds.filter((b) =>
    (!status || b.status === status)
    && (!q || `${b.bedNumber} ${b.ward} ${b.currentPatientName || ''}`.toLowerCase().includes(q.toLowerCase())));

  const byWard: Record<string, any[]> = {};
  for (const b of filtered) {
    const w = b.ward || 'General';
    byWard[w] = byWard[w] || [];
    byWard[w].push(b);
  }
  const occ = beds.length ? Math.round((beds.filter((b) => b.status === 'Occupied').length / beds.length) * 100) : 0;

  return (
    <div className="space-y-3 p-4">
      <div className="flex flex-wrap items-center gap-2">
        <h1 className="flex items-center gap-2 text-lg font-bold"><BedDouble size={18} /> Bed board</h1>
        <span className="rounded-full bg-muted px-2.5 py-0.5 text-xs font-semibold">{occ}% occupied · {beds.length} beds</span>
        <div className="flex-1" />
        <Input className="w-52" placeholder="Search bed / ward / patient…" value={q} onChange={(e) => setQ(e.target.value)} />
        <select className="rounded-md border px-2 py-2 text-sm" value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="">All statuses</option>
          {STATUSES.map((s) => <option key={s}>{s}</option>)}
        </select>
      </div>
      {canEdit && selected && (
        <Card>
          <CardContent className="p-3 flex flex-wrap items-center gap-2 text-sm">
            <span className="font-semibold">{selected.bedNumber}</span>
            <span className="text-muted-foreground">({selected.status} →)</span>
            <select
              className="rounded-md border px-2 py-1.5 text-sm"
              value={nextStatus || selected.status}
              onChange={(e) => setNextStatus(e.target.value)}
            >
              {STATUSES.map((s) => <option key={s}>{s}</option>)}
            </select>
            <Button size="sm" onClick={saveStatus} disabled={saving || !nextStatus || nextStatus === selected.status}>
              {saving ? 'Saving…' : 'Set status'}
            </Button>
            <Button size="sm" variant="ghost" onClick={() => { setSelected(null); setNextStatus(''); }}>Cancel</Button>
            <span className="text-xs text-muted-foreground">Reserved = planned admission · Blocked = out of service · Isolation = precaution</span>
          </CardContent>
        </Card>
      )}
      {Object.entries(byWard).map(([ward, list]) => (
        <Card key={ward}>
          <CardHeader><CardTitle className="text-sm">{ward} ({list.length})</CardTitle></CardHeader>
          <CardContent className="flex flex-wrap gap-2">
            {list.map((b) => (
              <BedTile
                key={b._id || b.bedNumber}
                bed={b}
                selected={selected?._id === b._id}
                onClick={canEdit ? () => { setSelected(selected?._id === b._id ? null : b); setNextStatus(''); } : undefined}
              />
            ))}
          </CardContent>
        </Card>
      ))}
      {filtered.length === 0 ? <p className="text-sm text-muted-foreground">No beds match.</p> : null}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { ScanLine, CloudOff, Cloud, ShieldCheck, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { BarcodeScanner } from '@/components/ui/System';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { encryptAndStore, decryptAndLoad, clearEncrypted } from '@/lib/encryptedStorage';

/**
 * File 22 P2-32: nurse bedside station — one screen, three scan targets
 * (MAR dose, lab sample, blood unit). Offline scans are encrypted at rest
 * (AES-GCM via encryptedStorage, key derived from the session PIN/passphrase)
 * and replayed when connectivity returns, so a ward round is never blocked
 * by a dead wifi bar.
 */

type ScanKind = 'mar' | 'sample' | 'blood';
interface QueuedScan {
  kind: ScanKind;
  code: string;
  at: string;
}

const KINDS: { key: ScanKind; label: string; hint: string }[] = [
  { key: 'mar', label: 'MAR dose', hint: 'scan medication Administration Record code' },
  { key: 'sample', label: 'Lab sample', hint: 'scan sample accession / barcode' },
  { key: 'blood', label: 'Blood unit', hint: 'scan blood unit number' },
];

export default function BedsideScan() {
  const [kind, setKind] = useState<ScanKind>('mar');
  const [queue, setQueue] = useState<QueuedScan[]>([]);
  const [passphrase, setPassphrase] = useState('');
  const [unlocked, setUnlocked] = useState(false);
  const [online, setOnline] = useState(typeof navigator === 'undefined' || navigator.onLine);
  const [lastResult, setLastResult] = useState<any>(null);

  const QUEUE_KEY = 'bedside-passphrase';

  useEffect(() => {
    const up = () => setOnline(true);
    const down = () => setOnline(false);
    window.addEventListener('online', up);
    window.addEventListener('offline', down);
    return () => {
      window.removeEventListener('online', up);
      window.removeEventListener('offline', down);
    };
  }, []);

  const persist = async (next: QueuedScan[], pass: string) => {
    if (!pass) return;
    try { await encryptAndStore(pass, { scans: next }); } catch { /* quota */ }
  };

  const unlock = async () => {
    if (passphrase.length < 4) { toast.error('Passphrase must be at least 4 characters'); return; }
    try {
      const stored = await decryptAndLoad(passphrase);
      if (stored?.scans) setQueue(stored.scans);
      setUnlocked(true);
      sessionStorage.setItem(QUEUE_KEY, '1');
      toast.success('Offline vault unlocked');
    } catch { toast.error('Wrong passphrase (or corrupt vault)'); }
  };

  const submitOnline = async (code: string): Promise<boolean> => {
    try {
      const r: any = await api.post('/nursing/scan', { kind, code });
      setLastResult({ code, ok: true, at: new Date().toLocaleTimeString(), entity: r?.entity });
      return true;
    } catch {
      return false;
    }
  };

  const onScan = async (code: string) => {
    if (!unlocked) { toast.error('Unlock the offline vault first'); return; }
    const ok = online ? await submitOnline(code) : false;
    if (ok) { toast.success(`${kind} scan accepted`); return; }
    const next = [...queue, { kind, code, at: new Date().toISOString() }];
    setQueue(next);
    await persist(next, passphrase);
    toast.warning('Offline — scan encrypted and queued');
  };

  const flush = async () => {
    if (!queue.length) return;
    const remaining: QueuedScan[] = [];
    for (const s of queue) {
      const ok = await submitOnline(s.code).catch(() => false);
      if (!ok) remaining.push(s);
    }
    setQueue(remaining);
    await persist(remaining, passphrase);
    toast.success(remaining.length ? `${queue.length - remaining.length} sent, ${remaining.length} still queued` : 'All queued scans sent');
  };

  const wipe = async () => {
    if (!window.confirm('Erase the encrypted offline vault on this device?')) return;
    clearEncrypted();
    setQueue([]);
    setUnlocked(false);
    sessionStorage.removeItem(QUEUE_KEY);
    toast.success('Vault wiped');
  };

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-2xl font-heading font-bold flex items-center gap-2">
          <ScanLine className="w-5 h-5" />Bedside scan
        </h1>
        <p className="text-sm text-muted-foreground">MAR / sample / blood unit — offline-first with an encrypted vault.</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center justify-between">
            <span className="flex items-center gap-2">
              <ShieldCheck className="w-4 h-4" />Offline vault
            </span>
            <span className={`flex items-center gap-1 text-xs font-semibold ${online ? 'text-green-700' : 'text-amber-600'}`}>
              {online ? <Cloud className="w-3.5 h-3.5" /> : <CloudOff className="w-3.5 h-3.5" />}
              {online ? 'online' : 'offline'}
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {!unlocked ? (
            <div className="flex gap-2">
              <Input type="password" className="w-64" placeholder="vault passphrase"
                value={passphrase} onChange={(e) => setPassphrase(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && unlock()} />
              <Button onClick={unlock}>Unlock</Button>
            </div>
          ) : (
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-sm text-muted-foreground">{queue.length} queued scan(s)</span>
              <Button size="sm" variant="outline" onClick={flush} disabled={!queue.length || !online}>
                <Cloud className="w-3.5 h-3.5 mr-1" />Replay queue
              </Button>
              <Button size="sm" variant="ghost" onClick={wipe}><Trash2 className="w-3.5 h-3.5" /></Button>
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Scan target</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex flex-wrap gap-2">
            {KINDS.map((k) => (
              <button key={k.key} onClick={() => setKind(k.key)}
                className={`rounded-lg border px-3 py-2 text-sm font-medium transition-colors ${
                  kind === k.key ? 'border-primary bg-primary/10' : 'border-border/50 hover:border-primary/40'
                }`}>{k.label}</button>
            ))}
          </div>
          <BarcodeScanner onScan={onScan} label={KINDS.find((k) => k.key === kind)?.hint || 'scan code'} />
          {lastResult ? (
            <p className="text-sm text-green-700">
              Last accepted: {lastResult.code} at {lastResult.at}
              {lastResult.entity?.patientName ? ` · ${lastResult.entity.patientName}` : ''}
              {lastResult.entity?.status ? ` · ${lastResult.entity.status}` : ''}
            </p>
          ) : null}
          <div className="space-y-1.5">
            {queue.map((s, i) => (
              <div key={`${s.code}-${i}`} className="flex items-center justify-between rounded-lg border border-border/50 p-2 text-sm">
                <span><b className="uppercase text-xs text-muted-foreground">{s.kind}</b> {s.code}</span>
                <span className="text-xs text-muted-foreground">{new Date(s.at).toLocaleTimeString()}</span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

