        <CardContent className="p-4 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-muted-foreground">Pre-Weight (kg)</label>
            <Input
              type="number"
              step="0.1"
              value={calcPreWeight}
              onChange={(e) => setCalcPreWeight(e.target.value)}
              className="bg-background text-xs"
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-muted-foreground">Target Dry Weight (kg)</label>
            <Input
              type="number"
              step="0.1"
              value={calcDryWeight}
              onChange={(e) => setCalcDryWeight(e.target.value)}
              className="bg-background text-xs"
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-muted-foreground">Saline Rinseback (L)</label>
            <Input
              type="number"
              step="0.1"
              value={calcRinseback}
              onChange={(e) => setCalcRinseback(e.target.value)}
              className="bg-background text-xs"
            />
          </div>
          <div className="p-2.5 rounded-lg bg-cyan-600 text-white flex flex-col justify-center items-center">
            <span className="text-[10px] uppercase tracking-wider font-semibold opacity-90">Calculated UF Target</span>
            <span className="text-xl font-bold font-mono">{ufGoalCalculated} Liters</span>
          </div>
        </CardContent>
      </Card>

      {/* Kt/V Adequacy Calculator + Session History Trend */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card className="border-emerald-500/20 shadow-sm">
          <CardHeader className="p-4 border-b border-emerald-500/10">
            <CardTitle className="text-sm font-semibold flex items-center gap-2 text-emerald-700 dark:text-emerald-400">
              <Activity className="h-4 w-4" />
              Dialysis Adequacy — spKt/V (Daugirdas II) & URR
            </CardTitle>
            <CardDescription className="text-xs">
              KDOQI target spKt/V ≥ 1.4, minimum ≥ 1.2; URR ≥ 65%.
            </CardDescription>
          </CardHeader>
          <CardContent className="p-4 grid grid-cols-2 md:grid-cols-5 gap-3 items-end">
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground">Pre BUN (mg/dL)</label>
              <Input type="number" value={ktvPreBun} onChange={(e) => setKtvPreBun(e.target.value)} className="bg-background text-xs" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground">Post BUN (mg/dL)</label>
              <Input type="number" value={ktvPostBun} onChange={(e) => setKtvPostBun(e.target.value)} className="bg-background text-xs" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground">Hours</label>
              <Input type="number" value={ktvHours} onChange={(e) => setKtvHours(e.target.value)} className="bg-background text-xs" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground">UF (L)</label>
              <Input type="number" value={ktvUf} onChange={(e) => setKtvUf(e.target.value)} className="bg-background text-xs" />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-semibold text-muted-foreground">Post Wt (kg)</label>
              <Input type="number" value={ktvWeight} onChange={(e) => setKtvWeight(e.target.value)} className="bg-background text-xs" />
            </div>
            <div className="col-span-2 md:col-span-5 flex items-center justify-between gap-3">
              <div className={`p-2.5 rounded-lg flex-1 border ${ktvResult ? (ktvResult.isAdequate ? 'bg-emerald-50 dark:bg-emerald-950/40 border-emerald-200 dark:border-emerald-900' : 'bg-red-50 dark:bg-red-950/40 border-red-200 dark:border-red-900') : 'bg-muted/50 border-border'}`}>
                <div className="text-sm font-semibold">
                  {ktvResult ? `spKt/V: ${ktvResult.spKtV} — URR: ${ktvResult.urrPct}%` : 'Enter pre/post BUN to calculate'}
                </div>
                {ktvResult && (
                  <div className={`text-xs ${ktvResult.isAdequate ? 'text-emerald-700 dark:text-emerald-400' : 'text-red-700 dark:text-red-400'}`}>
                    {ktvResult.clinicalInterpretation}
                  </div>
                )}
              </div>
              <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white" disabled={ktvLoading} onClick={calcKtV}>
                {ktvLoading ? '…' : 'Calculate'}
              </Button>
            </div>
          </CardContent>
        </Card>

        <Card className="shadow-sm">
          <CardHeader className="p-4 border-b">
            <CardTitle className="text-sm font-semibold flex items-center gap-2">
              <HeartPulse className="h-4 w-4 text-cyan-600" />
              Recent Session History ({sessions.length})
            </CardTitle>
            <CardDescription className="text-xs">Pre/post weights, UF achieved and isolation flags from recorded sessions.</CardDescription>
          </CardHeader>
          <CardContent className="p-4 max-h-72 overflow-y-auto">
            {sessions.length === 0 ? (
              <div className="text-sm text-muted-foreground text-center py-8">No sessions recorded yet.</div>
            ) : (
              <table className="w-full text-xs">
                <thead>
                  <tr className="text-left text-muted-foreground border-b">
                    <th className="py-1.5 pr-2">Date</th>
                    <th className="py-1.5 pr-2">Machine</th>
                    <th className="py-1.5 pr-2">Pre→Post (kg)</th>
                    <th className="py-1.5 pr-2">UF (L)</th>
                    <th className="py-1.5 pr-2">Isolation</th>
                  </tr>
                </thead>
                <tbody>
                  {sessions.map((s) => (
                    <tr key={s._id} className="border-b last:border-0">
                      <td className="py-1.5 pr-2 font-mono">{String(s.date).slice(0, 10)}</td>
                      <td className="py-1.5 pr-2">{s.machineId || '—'}</td>
                      <td className="py-1.5 pr-2 font-mono">{s.preWeightKg} → {s.postWeightKg}</td>
                      <td className="py-1.5 pr-2 font-mono">{s.ufLitres ?? '—'}</td>
                      <td className="py-1.5 pr-2">
                        {s.isolation && s.isolation !== 'none' ? (
                          <Badge variant="outline" className="bg-amber-500/10 text-amber-600 border-amber-500/30 text-[10px]">{s.isolation.toUpperCase()}</Badge>
                        ) : (
                          <Badge variant="outline" className="bg-emerald-500/10 text-emerald-600 border-emerald-500/30 text-[10px]">NONE</Badge>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Modal: Record Session */}
      <Dialog open={isNewSessionOpen} onOpenChange={setIsNewSessionOpen}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Droplets className="h-5 w-5 text-cyan-600" />
              Record Hemodialysis Session
            </DialogTitle>
          </DialogHeader>
          <div className="grid grid-cols-2 gap-3 py-2 text-xs">
            <div className="col-span-2 space-y-1">
              <label className="font-semibold text-muted-foreground">Patient User ID / UHID *</label>
              <Input
                placeholder="Patient ObjectId or UHID"
                value={form.patientId}
                onChange={(e) => setForm({ ...form, patientId: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Machine Bay</label>
              <Input
                value={form.machineId}
                onChange={(e) => setForm({ ...form, machineId: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Session Date</label>
              <Input
                type="date"
                value={form.date}
                onChange={(e) => setForm({ ...form, date: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Pre-Weight (kg) *</label>
              <Input
                type="number"
                step="0.1"
                value={form.preWeightKg}
                onChange={(e) => setForm({ ...form, preWeightKg: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Post-Weight (kg) *</label>
              <Input
                type="number"
                step="0.1"
                value={form.postWeightKg}
                onChange={(e) => setForm({ ...form, postWeightKg: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Pre BP (Systolic/Diastolic)</label>
              <div className="flex gap-1">
                <Input
                  placeholder="140"
                  value={form.preSystolic}
                  onChange={(e) => setForm({ ...form, preSystolic: e.target.value })}
                />
                <Input
                  placeholder="90"
                  value={form.preDiastolic}
                  onChange={(e) => setForm({ ...form, preDiastolic: e.target.value })}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Post BP (Systolic/Diastolic)</label>
              <div className="flex gap-1">
                <Input
                  placeholder="120"
                  value={form.postSystolic}
                  onChange={(e) => setForm({ ...form, postSystolic: e.target.value })}
                />
                <Input
                  placeholder="80"
                  value={form.postDiastolic}
                  onChange={(e) => setForm({ ...form, postDiastolic: e.target.value })}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">UF Removed (L)</label>
              <Input
                type="number"
                step="0.1"
                value={form.ufLitres}
                onChange={(e) => setForm({ ...form, ufLitres: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="font-semibold text-muted-foreground">Dialyzer Reuse Count</label>
              <Input
                type="number"
                value={form.dialyserReuseCount}
                onChange={(e) => setForm({ ...form, dialyserReuseCount: e.target.value })}
              />
            </div>
            <div className="col-span-2 space-y-1">
              <label className="font-semibold text-muted-foreground">Serology / Infection Isolation</label>
              <Select
                value={form.isolation}
                onValueChange={(val: any) => setForm({ ...form, isolation: val })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Standard Non-Infectious Bay</SelectItem>
                  <SelectItem value="hbv">Hepatitis B (HBV) Isolation</SelectItem>
                  <SelectItem value="hcv">Hepatitis C (HCV) Isolation</SelectItem>
                  <SelectItem value="hbv_hcv">Combined HBV + HCV</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsNewSessionOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSaveSession} className="bg-cyan-600 hover:bg-cyan-700 text-white">
              Save Clinical Record
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Building2, FileSignature, Star, Landmark } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api, downloadGstr } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';

/** File 16 §16.4/§16.5/§16.6: corporates, contracts, vendor scorecards. */
export default function EnterpriseHub() {
  const [tab, setTab] = useState<'corp' | 'contracts' | 'vendors' | 'accounts'>('corp');
  const [accounts, setAccounts] = useState<any[]>([]);
  const [vbills, setVbills] = useState<any[]>([]);
  const [vbForm, setVbForm] = useState({ supplierId: '', billNo: '', item: '', poQty: '', grnQty: '', billQty: '', rate: '', gstRate: '' });
  const [gstrMonth, setGstrMonth] = useState(new Date().toISOString().slice(0, 7));
  const [corps, setCorps] = useState<any[]>([]);
  const [contracts, setContracts] = useState<any[]>([]);
  const [scores, setScores] = useState<any[]>([]);
  const [corpForm, setCorpForm] = useState({ name: '', creditLimit: '' });
  const [elig, setElig] = useState<any | null>(null);
  const [eligQ, setEligQ] = useState({ id: '', employeeId: '', amount: '' });
  const [ctForm, setCtForm] = useState({ kind: 'rate', counterparty: '', value: '', startDate: '', endDate: '' });
  const [scoreQ, setScoreQ] = useState({ supplierId: '', period: '' });

  const load = async () => {
    try {
      const [c, k, s, a, v]: any[] = await Promise.all([
        api.listCorporates(), api.listContracts({}), api.vendorScorecards({}),
        api.coa(), api.vendorBills(),
      ]);
      setCorps(c?.corporates || []);
      setContracts(k?.contracts || []);
      setScores(s?.scorecards || []);
      setAccounts(a?.accounts || []);
      setVbills(v?.bills || []);
    } catch { toast.error('Failed to load enterprise data'); }
  };
  useEffect(() => { load(); }, []);

  const addCorp = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await api.createCorporate({ name: corpForm.name, creditLimit: Number(corpForm.creditLimit) || 0 });
      setCorpForm({ name: '', creditLimit: '' });
      toast.success('Corporate added');
      load();
    } catch { toast.error('Save failed'); }
  };

  const checkElig = async () => {
    try {
      const r: any = await api.corporateEligibility(eligQ.id, { employeeId: eligQ.employeeId, amount: eligQ.amount });
      setElig(r);
    } catch (e: any) { toast.error(e?.message || 'Check failed'); }
  };

  const addContract = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await api.createContract({ ...ctForm, value: Number(ctForm.value) || 0 });
      toast.success('Contract saved');
      load();
    } catch { toast.error('Save failed'); }
  };

  const compute = async () => {
    try {
      const r: any = await api.computeScorecard(scoreQ.supplierId, scoreQ.period);
      toast.success(`Score: ${r?.score ?? 'n/a (no POs in period)'}`);
      load();
    } catch (e: any) { toast.error(e?.message || 'Compute failed'); }
  };

  return (
    <div className="space-y-3 p-4">
      <div className="flex gap-1">
        {([['corp', 'Corporates', Building2], ['contracts', 'Contracts', FileSignature], ['vendors', 'Vendors', Star], ['accounts', 'Accounts', Landmark]] as const).map(([k, label, Icon]) => (
          <Button key={k} size="sm" variant={tab === k ? 'default' : 'outline'} onClick={() => setTab(k)}><Icon size={14} /> {label}</Button>
        ))}
      </div>

      {tab === 'corp' ? (
        <div className="grid gap-3 lg:grid-cols-2">
          <Card><CardHeader><CardTitle className="text-sm">Corporates ({corps.length})</CardTitle></CardHeader>
            <CardContent className="space-y-1.5">
              {corps.map((c) => (
                <div key={c._id} className="flex items-center justify-between rounded border p-2 text-xs">
                  <span><b>{c.name}</b> · limit ₹{(c.creditLimit || 0).toLocaleString('en-IN')} · used ₹{(c.creditUsed || 0).toLocaleString('en-IN')}</span>
                  <StatusPill status={c.active ? 'active' : 'inactive'} />
                </div>
              ))}
              <form onSubmit={addCorp} className="flex gap-1 border-t pt-2">
                <Input className="h-8 text-xs" placeholder="name" value={corpForm.name} onChange={(e) => setCorpForm({ ...corpForm, name: e.target.value })} required />
                <Input className="h-8 w-32 text-xs" placeholder="credit limit" value={corpForm.creditLimit} onChange={(e) => setCorpForm({ ...corpForm, creditLimit: e.target.value })} />
                <Button size="sm" type="submit">Add</Button>
              </form>
            </CardContent></Card>
          <Card><CardHeader><CardTitle className="text-sm">Eligibility check</CardTitle></CardHeader>
            <CardContent className="space-y-1.5">
              <Input className="h-8 text-xs" placeholder="corporate id" value={eligQ.id} onChange={(e) => setEligQ({ ...eligQ, id: e.target.value })} />
              <div className="flex gap-1">
                <Input className="h-8 text-xs" placeholder="employee id" value={eligQ.employeeId} onChange={(e) => setEligQ({ ...eligQ, employeeId: e.target.value })} />
                <Input className="h-8 text-xs" placeholder="amount" value={eligQ.amount} onChange={(e) => setEligQ({ ...eligQ, amount: e.target.value })} />
              </div>
              <Button size="sm" onClick={checkElig}>Check</Button>
              {elig ? <p className="text-sm">Eligible: <b>{elig.eligible ? 'YES' : 'NO'}</b> · headroom ₹{(elig.headroom || 0).toLocaleString('en-IN')}</p> : null}
            </CardContent></Card>
        </div>
      ) : null}

      {tab === 'contracts' ? (
        <Card><CardHeader><CardTitle className="text-sm">Contracts ({contracts.length})</CardTitle></CardHeader>
          <CardContent className="space-y-1.5">
            {contracts.map((c) => (
              <div key={c._id} className="flex items-center justify-between rounded border p-2 text-xs">
                <span><b>{c.kind}</b> · {c.counterparty} · ₹{(c.value || 0).toLocaleString('en-IN')} · ends {String(c.endDate).slice(0, 10)}</span>
                <StatusPill status={c.status} />
              </div>
            ))}
            <form onSubmit={addContract} className="flex flex-wrap gap-1 border-t pt-2">
              <select className="rounded-md border px-2 py-1.5 text-xs" value={ctForm.kind} onChange={(e) => setCtForm({ ...ctForm, kind: e.target.value })}>
                <option>rate</option><option>amc</option><option>service</option><option>lease</option>
              </select>
              <Input className="h-8 w-40 text-xs" placeholder="counterparty" value={ctForm.counterparty} onChange={(e) => setCtForm({ ...ctForm, counterparty: e.target.value })} required />
              <Input className="h-8 w-28 text-xs" placeholder="value" value={ctForm.value} onChange={(e) => setCtForm({ ...ctForm, value: e.target.value })} />
              <Input className="h-8 w-36 text-xs" type="date" value={ctForm.startDate} onChange={(e) => setCtForm({ ...ctForm, startDate: e.target.value })} required />
              <Input className="h-8 w-36 text-xs" type="date" value={ctForm.endDate} onChange={(e) => setCtForm({ ...ctForm, endDate: e.target.value })} required />
              <Button size="sm" type="submit">Save</Button>
            </form>
          </CardContent></Card>
      ) : null}

      {tab === 'vendors' ? (
        <Card><CardHeader><CardTitle className="text-sm">Vendor scorecards ({scores.length})</CardTitle></CardHeader>
          <CardContent className="space-y-1.5">
            {scores.map((s) => (
              <p key={s._id} className="rounded border p-2 text-xs">supplier {String(s.supplierId).slice(-6)} · {s.period} · on-time {s.onTimePct ?? '—'}% · fill {s.fillRatePct ?? '—'}% · <b>score {s.score ?? '—'}</b></p>
            ))}
            <div className="flex gap-1 border-t pt-2">
              <Input className="h-8 text-xs" placeholder="supplier id" value={scoreQ.supplierId} onChange={(e) => setScoreQ({ ...scoreQ, supplierId: e.target.value })} />
              <Input className="h-8 w-32 text-xs" placeholder="YYYY-MM" value={scoreQ.period} onChange={(e) => setScoreQ({ ...scoreQ, period: e.target.value })} />
              <Button size="sm" onClick={compute}>Compute</Button>
            </div>
          </CardContent></Card>
      ) : null}

      {tab === 'accounts' ? (
        <div className="grid gap-3 lg:grid-cols-2">
          <Card><CardHeader><CardTitle className="flex items-center gap-2 text-sm">Chart of accounts ({accounts.length})
            <Button size="sm" variant="outline" onClick={async () => { await api.seedCoa(); load(); }}>Seed</Button>
          </CardTitle></CardHeader>
            <CardContent className="max-h-72 space-y-1 overflow-auto">
              {accounts.map((a) => (
                <p key={a._id} className="flex justify-between rounded border px-2 py-1 font-mono text-[11px]">
                  <span>{a.code} · {a.name}</span><span className="text-muted-foreground">{a.group}</span>
                </p>
              ))}
            </CardContent></Card>
          <div className="space-y-3">
            <Card><CardHeader><CardTitle className="text-sm">Vendor bills ({vbills.length})</CardTitle></CardHeader>
              <CardContent className="space-y-1.5">
                {vbills.slice(0, 10).map((b) => (
                  <div key={b._id} className="flex items-center justify-between rounded border p-2 text-xs">
                    <span><b>{b.billNo}</b> · ₹{(b.grandTotal || 0).toLocaleString('en-IN')} · <StatusPill status={b.matchStatus} /> · {b.status}</span>
                    {b.status === 'Draft' && b.matchStatus !== 'Unmatched' ? (
                      <Button size="sm" variant="outline" onClick={async () => { await api.postVendorBill(b._id); load(); }}>Post</Button>
                    ) : null}
                  </div>
                ))}
                <div className="grid grid-cols-4 gap-1 border-t pt-2">
                  <Input className="h-8 text-xs" placeholder="supplier id" value={vbForm.supplierId} onChange={(e) => setVbForm({ ...vbForm, supplierId: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="bill no" value={vbForm.billNo} onChange={(e) => setVbForm({ ...vbForm, billNo: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="item" value={vbForm.item} onChange={(e) => setVbForm({ ...vbForm, item: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="rate" value={vbForm.rate} onChange={(e) => setVbForm({ ...vbForm, rate: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="po qty" value={vbForm.poQty} onChange={(e) => setVbForm({ ...vbForm, poQty: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="grn qty" value={vbForm.grnQty} onChange={(e) => setVbForm({ ...vbForm, grnQty: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="bill qty" value={vbForm.billQty} onChange={(e) => setVbForm({ ...vbForm, billQty: e.target.value })} />
                  <Input className="h-8 text-xs" placeholder="gst %" value={vbForm.gstRate} onChange={(e) => setVbForm({ ...vbForm, gstRate: e.target.value })} />
                </div>
                <Button size="sm" onClick={async () => {
                  try {
                    await api.createVendorBill({
                      supplierId: vbForm.supplierId, billNo: vbForm.billNo,
                      lines: [{ item: vbForm.item, poQty: Number(vbForm.poQty), grnQty: Number(vbForm.grnQty), billQty: Number(vbForm.billQty), rate: Number(vbForm.rate), gstRate: Number(vbForm.gstRate) }],
                    });
                    toast.success('Vendor bill booked (3-way matched)');
                    load();
                  } catch (e: any) { toast.error(e?.response?.data?.message || 'Save failed'); }
                }}>Book bill</Button>
              </CardContent></Card>
            <Card><CardHeader><CardTitle className="text-sm">GSTR export</CardTitle></CardHeader>
              <CardContent className="flex gap-1">
                <Input className="h-8 w-32 text-xs" value={gstrMonth} onChange={(e) => setGstrMonth(e.target.value)} />
                <Button size="sm" variant="outline" onClick={async () => {
                  try { await downloadGstr(gstrMonth); }
                  catch { toast.error('Export failed'); }
                }}>Download CSV</Button>
              </CardContent></Card>
          </div>
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useState } from 'react';
import type { Unmodelled } from '@/lib/apiTypes';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import {
  MessageSquare,
  TrendingUp,
  Smile,
  Frown,
  Meh,
  Star,
  RefreshCw,
  Send,
  Filter,
} from 'lucide-react';

interface FeedbackItem {
  _id: string;
  context?: string;
  department?: string;
  npsScore?: number;
  rating?: number;
  comment?: string;
  status?: string;
  response?: {
    note?: string;
    at?: string;
  };
  createdAt: string;
}

interface FeedbackSummary {
  totalResponses: number;
  nps: number | null;
  promoters: number;
  detractors: number;
  passives: number;
  avgCsat: number | null;
  byDepartment?: Record<string, { count: number; sumRating: number; ratedCount: number }>;
}

export default function FeedbackDashboard() {
  const [feedbackList, setFeedbackList] = useState<FeedbackItem[]>([]);
  const [summary, setSummary] = useState<FeedbackSummary>({
    totalResponses: 0,
    nps: 0,
    promoters: 0,
    detractors: 0,
    passives: 0,
    avgCsat: 0,
  });
  const [loading, setLoading] = useState(false);
  const [departmentFilter, setDepartmentFilter] = useState('ALL');
  const [contextFilter, setContextFilter] = useState('ALL');

  // Responding Dialog
  const [selectedItem, setSelectedItem] = useState<FeedbackItem | null>(null);
  const [responseNote, setResponseNote] = useState('');
  const [responseStatus, setResponseStatus] = useState<'in_review' | 'resolved'>('resolved');
  const [submitting, setSubmitting] = useState(false);

  const loadData = async () => {
    try {
      setLoading(true);
      const [listRes, sumRes]: any = await Promise.all([
        (api as Unmodelled).get('/feedback', {
          params: {
            context: contextFilter !== 'ALL' ? contextFilter : undefined,
          },
        }),
        (api as Unmodelled).get('/feedback/summary', {
          params: {
            dept: departmentFilter !== 'ALL' ? departmentFilter : undefined,
          },
        }),
      ]);

      setFeedbackList(listRes.data?.feedback || []);
      setSummary(sumRes.data || {
        totalResponses: 0,
        nps: 0,
        promoters: 0,
        detractors: 0,
        passives: 0,
        avgCsat: 0,
      });
    } catch (err: any) {
      toast.error(err.message || 'Failed to load feedback data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [departmentFilter, contextFilter]);

  const handleRespond = async () => {
    if (!selectedItem || !responseNote.trim()) return;
    try {
      setSubmitting(true);
      await api.put(`/feedback/${selectedItem._id}/respond`, {
        note: responseNote.trim(),
        status: responseStatus,
      });
      toast.success('Response recorded successfully');
      setSelectedItem(null);
      setResponseNote('');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to record response');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2">
            <MessageSquare className="w-8 h-8 text-primary" />
            Patient Feedback & Net Promoter Score (NPS)
          </h1>
          <p className="text-muted-foreground">
            Monitor real-time patient experience, CSAT satisfaction, and respond directly to detractors.
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={loadData} disabled={loading}>
            <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center justify-between">
              Net Promoter Score (NPS)
              <TrendingUp className="w-4 h-4 text-emerald-500" />
            </CardDescription>
            <CardTitle className="text-3xl font-extrabold">
              {summary.nps !== null ? `${summary.nps > 0 ? '+' : ''}${summary.nps}` : 'N/A'}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-xs text-muted-foreground">
              %Promoters ({summary.promoters}) − %Detractors ({summary.detractors})
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center justify-between">
              Average CSAT Rating
              <Star className="w-4 h-4 text-amber-500 fill-amber-500" />
            </CardDescription>
            <CardTitle className="text-3xl font-extrabold">
              {summary.avgCsat ? `${summary.avgCsat} / 5` : 'N/A'}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-xs text-muted-foreground">Across all rated hospital encounters</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center justify-between">
              Total Responses
              <Smile className="w-4 h-4 text-primary" />
            </CardDescription>
            <CardTitle className="text-3xl font-extrabold">
              {summary.totalResponses}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-xs text-muted-foreground">
              {summary.passives} Passives (Score 7-8)
            </p>
          </CardContent>
        </Card>

        <Card className={summary.detractors > 0 ? 'border-destructive/40 bg-destructive/5' : ''}>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center justify-between">
              Detractors Requiring Follow-up
              <Frown className="w-4 h-4 text-destructive" />
            </CardDescription>
            <CardTitle className="text-3xl font-extrabold text-destructive">
              {summary.detractors}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-xs text-muted-foreground">Scores ≤ 6 flagged for management action</p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-6 flex flex-wrap gap-4 items-center">
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-muted-foreground" />
            <span className="text-sm font-medium">Filters:</span>
          </div>

          <Select value={contextFilter} onValueChange={setContextFilter}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Encounter Context" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All Contexts</SelectItem>
              <SelectItem value="visit">Outpatient Visit</SelectItem>
              <SelectItem value="admission">Inpatient Stay</SelectItem>
              <SelectItem value="pharmacy">Pharmacy</SelectItem>
              <SelectItem value="lab">Laboratory</SelectItem>
              <SelectItem value="teleconsult">Teleconsult</SelectItem>
            </SelectContent>
          </Select>

          <Select value={departmentFilter} onValueChange={setDepartmentFilter}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Department" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ALL">All Departments</SelectItem>
              <SelectItem value="Cardiology">Cardiology</SelectItem>
              <SelectItem value="Emergency">Emergency</SelectItem>
              <SelectItem value="General Medicine">General Medicine</SelectItem>
              <SelectItem value="Paediatrics">Paediatrics</SelectItem>
              <SelectItem value="Orthopaedics">Orthopaedics</SelectItem>
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {/* Feedback Feed Table */}
      <Card>
        <CardHeader>
          <CardTitle>Feedback Ledger & Responses</CardTitle>
          <CardDescription>
            Audit trail of patient ratings and operational responses
          </CardDescription>
        </CardHeader>
        <CardContent>
          {feedbackList.length === 0 ? (
            <div className="py-12 text-center text-muted-foreground">
              No feedback records found matching the current filters.
            </div>
          ) : (
            <div className="space-y-4">
              {feedbackList.map((item) => {
                const isDetractor = item.npsScore !== undefined && item.npsScore <= 6;
                const isPromoter = item.npsScore !== undefined && item.npsScore >= 9;
                return (
                  <div
                    key={item._id}
                    className="p-4 rounded-lg border flex flex-col md:flex-row justify-between gap-4 items-start md:items-center bg-card hover:bg-muted/30 transition-colors"
                  >
                    <div className="space-y-1 max-w-xl">
                      <div className="flex items-center gap-2">
                        {item.npsScore !== undefined && (
                          <Badge
                            variant={isPromoter ? 'default' : isDetractor ? 'destructive' : 'secondary'}
                          >
                            NPS {item.npsScore}
                          </Badge>
                        )}
                        {item.rating && (
                          <Badge variant="outline" className="flex items-center gap-1">
                            <Star className="w-3 h-3 text-amber-500 fill-amber-500" />
                            {item.rating} / 5
                          </Badge>
                        )}
                        <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                          {item.department || 'General'}
                        </span>
                        <span className="text-xs text-muted-foreground">
                          • {new Date(item.createdAt).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-sm font-medium text-foreground">
                        {item.comment ? `"${item.comment}"` : <span className="italic text-muted-foreground">No written comment provided</span>}
                      </p>
                      {item.response?.note && (
                        <div className="text-xs bg-muted p-2 rounded mt-2 text-muted-foreground border-l-2 border-primary">
                          <strong>Admin Response:</strong> {item.response.note}
                        </div>
                      )}
                    </div>

                    <div className="flex items-center gap-2 self-end md:self-center">
                      {item.status === 'resolved' ? (
                        <Badge variant="outline" className="text-emerald-600 border-emerald-300">
                          Resolved
                        </Badge>
                      ) : (
                        <Button
                          size="sm"
                          variant={isDetractor ? 'destructive' : 'outline'}
                          onClick={() => {
                            setSelectedItem(item);
                            setResponseNote(item.response?.note || '');
                          }}
                        >
                          <Send className="w-3.5 h-3.5 mr-1" />
                          Respond
                        </Button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Response Dialog */}
      <Dialog open={!!selectedItem} onOpenChange={(open) => !open && setSelectedItem(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Respond to Patient Feedback</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="p-3 bg-muted rounded-md text-sm">
              <div className="font-semibold text-xs text-muted-foreground uppercase mb-1">
                Patient Feedback ({selectedItem?.department})
              </div>
              "{selectedItem?.comment || 'No comment'}"
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Internal Response / Resolution Note</label>
              <Textarea
                placeholder="Explain resolution, follow-up call outcomes, or apology note..."
                value={responseNote}
                onChange={(e) => setResponseNote(e.target.value)}
                rows={4}
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Status</label>
              <Select
                value={responseStatus}
                onValueChange={(val: 'in_review' | 'resolved') => setResponseStatus(val)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="in_review">In Review</SelectItem>
                  <SelectItem value="resolved">Resolved</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setSelectedItem(null)}>
              Cancel
            </Button>
            <Button onClick={handleRespond} disabled={submitting || !responseNote.trim()}>
              Save Response
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import FormRenderer from '@/components/forms/FormRenderer';
import {
  FileText,
  Plus,
  Trash2,
  Save,
  Eye,
  Settings2,
  Type,
  Hash,
  Calendar,
  List,
  CheckSquare,
  Activity,
  PenTool,
  Upload,
  Table as TableIcon,
  Sparkles,
} from 'lucide-react';

interface FormField {
  id: string;
  label: string;
  labelHi?: string;
  type: string;
  required: boolean;
  options?: string[];
  placeholder?: string;
  placeholderHi?: string;
  min?: number;
  max?: number;
}

interface FormSection {
  id: string;
  title: string;
  titleHi?: string;
  description?: string;
  fields: FormField[];
}

export default function FormBuilderStudio() {
  const [templateKey, setTemplateKey] = useState('clinical-admission-assessment');
  const [templateTitle, setTemplateTitle] = useState('Clinical Specialty Assessment');
  const [templateTitleHi, setTemplateTitleHi] = useState('नैदानिक विशेषता मूल्यांकन');
  const [category, setCategory] = useState('Clinical');
  const [sections, setSections] = useState<FormSection[]>([
    {
      id: 'sec-general',
      title: 'Primary Assessment & Chief Complaints',
      titleHi: 'प्राथमिक मूल्यांकन एवं मुख्य शिकायतें',
      fields: [
        { id: 'chief_complaint', label: 'Chief Complaint', labelHi: 'मुख्य शिकायत', type: 'textarea', required: true, placeholder: 'Enter symptoms...', placeholderHi: 'लक्षण दर्ज करें...' },
        { id: 'onset_date', label: 'Onset Date', labelHi: 'आरंभ तिथि', type: 'date', required: true },
        { id: 'pain_score', label: 'Pain Score (0 to 10)', labelHi: 'दर्द का स्तर (0-10)', type: 'scale', min: 0, max: 10, required: false },
      ],
    },
    {
      id: 'sec-vitals',
      title: 'Initial Vitals & Triage',
      titleHi: 'प्रारंभिक महत्वपूर्ण संकेत एवं ट्राइएज',
      fields: [
        { id: 'vitals', label: 'Baseline Vitals Profile', labelHi: 'महत्वपूर्ण संकेत प्रोफ़ाइल', type: 'vitals', required: true },
        { id: 'consciousness_level', label: 'AVPU Consciousness Level', labelHi: 'चेतना का स्तर', type: 'select', options: ['Alert', 'Voice', 'Pain', 'Unresponsive'], required: true },
      ],
    },
  ]);

  const [activeSectionIdx, setActiveSectionIdx] = useState(0);
  const [previewMode, setPreviewMode] = useState(false);
  const [previewLocale, setPreviewLocale] = useState<'en' | 'hi'>('en');
  const [previewValues, setPreviewValues] = useState<Record<string, any>>({});

  const fieldTypesList = [
    { type: 'text', label: 'Short Text', icon: Type },
    { type: 'textarea', label: 'Long Notes', icon: FileText },
    { type: 'number', label: 'Number', icon: Hash },
    { type: 'date', label: 'Date', icon: Calendar },
    { type: 'select', label: 'Dropdown Select', icon: List },
    { type: 'yesno', label: 'Yes / No Toggle', icon: CheckSquare },
    { type: 'vitals', label: 'Vitals Battery (BP/HR/SpO2)', icon: Activity },
    { type: 'signature', label: 'Digital Signature', icon: PenTool },
    { type: 'file', label: 'File Attachment', icon: Upload },
    { type: 'scale', label: 'Numeric Scale (0-10)', icon: Hash },
  ];

  const [dropIdx, setDropIdx] = useState<number | null>(null);

  const handleAddField = (type: string, label: string, insertAt?: number) => {
    const fieldId = `field_${Date.now()}`;
    const newField: FormField = {
      id: fieldId,
      label,
      type,
      required: false,
      options: type === 'select' ? ['Normal', 'Mild', 'Moderate', 'Severe'] : undefined,
      placeholder: `Enter ${label.toLowerCase()}...`,
    };

    setSections((prev) => {
      const copy = prev.map((s, i) => (i === activeSectionIdx ? { ...s, fields: [...s.fields] } : s));
      const arr = copy[activeSectionIdx].fields;
      const at = insertAt == null || insertAt < 0 || insertAt > arr.length ? arr.length : insertAt;
      arr.splice(at, 0, newField);
      return copy;
    });
    toast.success(`Added ${label} field`);
  };

  // Drag-drop reorder: move field from `from` to sit before index `to`.
  const moveField = (from: number, to: number) => {
    if (from === to || from + 1 === to) return;
    setSections((prev) => {
      const copy = prev.map((s, i) => (i === activeSectionIdx ? { ...s, fields: [...s.fields] } : s));
      const arr = copy[activeSectionIdx].fields;
      const [moved] = arr.splice(from, 1);
      const target = to > from ? to - 1 : to;
      arr.splice(Math.max(0, Math.min(target, arr.length)), 0, moved);
      return copy;
    });
    toast.success('Field reordered');
  };

  const handleCanvasDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const newFieldData = e.dataTransfer.getData('application/x-newfield');
    const moveIdxRaw = e.dataTransfer.getData('application/x-movefield');
    const target = (e.target as HTMLElement).closest('[data-field-idx]');
    const at = target ? Number(target.getAttribute('data-field-idx')) : sections[activeSectionIdx]?.fields.length ?? 0;
    if (newFieldData) {
      const sep = newFieldData.indexOf('::');
      handleAddField(newFieldData.slice(0, sep), newFieldData.slice(sep + 2), at);
    } else if (moveIdxRaw) {
      moveField(Number(moveIdxRaw), at);
    }
    setDropIdx(null);
  };

  const handleRemoveField = (fieldIdx: number) => {
    setSections((prev) => {
      const copy = [...prev];
      copy[activeSectionIdx].fields.splice(fieldIdx, 1);
      return copy;
    });
  };

  const handleAddSection = () => {
    const newSec: FormSection = {
      id: `sec_${Date.now()}`,
      title: `Section ${sections.length + 1}`,
      fields: [],
    };
    setSections([...sections, newSec]);
    setActiveSectionIdx(sections.length);
  };

  const handleSaveTemplate = async () => {
    if (!templateKey || !templateTitle) {
      toast.error('Template key and title required');
      return;
    }
    const payload = {
      key: templateKey.toLowerCase().replace(/\s+/g, '-'),
      title: templateTitle,
      titleHi: templateTitleHi,
      category,
      definition: {
        sections: sections.map((s) => ({
          id: s.id,
          title: s.title,
          titleHi: s.titleHi,
          description: s.description,
          fields: s.fields,
        })),
      },
    };

    try {
      await api.post('/forms/templates', payload);
      toast.success('Clinical template schema published successfully');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save form schema');
    }
  };

  return (
    <div className="container mx-auto p-4 md:p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b pb-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2">
              <Sparkles className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
              Dynamic Clinical Form Builder Studio
            </h1>
            <Badge variant="outline" className="bg-indigo-500/10 text-indigo-600 border-indigo-500/20">
              Module #98
            </Badge>
          </div>
          <p className="text-sm text-muted-foreground mt-1">
            Build specialized specialty forms, scoring engines, and structured EMR documentation without code deploys.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={() => setPreviewMode(!previewMode)}
            className="flex items-center gap-2"
          >
            <Eye className="h-4 w-4" />
            {previewMode ? 'Exit Preview' : 'Interactive Preview'}
          </Button>
          <Button onClick={handleSaveTemplate} className="bg-indigo-600 hover:bg-indigo-700 text-white flex items-center gap-2">
            <Save className="h-4 w-4" />
            Publish Schema
          </Button>
        </div>
      </div>

      {previewMode ? (
        /* Preview Tab */
        <Card className="border-border/60 shadow-sm max-w-3xl mx-auto">
          <CardHeader className="bg-muted/20 border-b p-4 flex flex-row items-center justify-between">
            <div>
              <CardTitle className="text-lg">{previewLocale === 'hi' && templateTitleHi ? templateTitleHi : templateTitle}</CardTitle>
              <CardDescription>Live dynamic preview rendering via FormRenderer engine.</CardDescription>
            </div>
            <div className="flex items-center gap-1 border rounded-md p-0.5 text-xs bg-background">
              <button
                type="button"
                className={`px-2 py-0.5 rounded transition-colors ${previewLocale === 'en' ? 'bg-primary text-primary-foreground font-medium' : 'text-muted-foreground hover:text-foreground'}`}
                onClick={() => setPreviewLocale('en')}
              >
                EN
              </button>
              <button
                type="button"
                className={`px-2 py-0.5 rounded transition-colors ${previewLocale === 'hi' ? 'bg-primary text-primary-foreground font-medium' : 'text-muted-foreground hover:text-foreground'}`}
                onClick={() => setPreviewLocale('hi')}
              >
                हिन्दी
              </button>
            </div>
          </CardHeader>
          <CardContent className="p-6">
            <FormRenderer
              template={{
                definition: { sections },
              }}
              values={previewValues}
              onChange={setPreviewValues}
              onSubmit={() => toast.success('Preview submission captured')}
              locale={previewLocale}
            />
          </CardContent>
        </Card>
      ) : (
        /* Design Studio Workspace */
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Left Toolbox */}
          <div className="space-y-4">
            <Card className="border-border/60 shadow-sm">
              <CardHeader className="p-4 bg-muted/20 border-b">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Settings2 className="h-4 w-4 text-primary" />
                  Clinical Widgets
                </CardTitle>
              </CardHeader>
              <CardContent className="p-3 space-y-2">
                {fieldTypesList.map((ft) => {
                  const Icon = ft.icon;
                  return (
                    <Button
                      key={ft.type}
                      variant="outline"
                      size="sm"
                      draggable
                      onDragStart={(e) => {
                        e.dataTransfer.setData('application/x-newfield', `${ft.type}::${ft.label}`);
                        e.dataTransfer.effectAllowed = 'copy';
                      }}
                      onClick={() => handleAddField(ft.type, ft.label)}
                      className="w-full justify-start text-xs h-8 gap-2 hover:bg-indigo-50 dark:hover:bg-indigo-950/30 hover:text-indigo-600 cursor-grab active:cursor-grabbing"
                      title="Click to insert, or drag onto the canvas"
                    >
                      <Icon className="h-3.5 w-3.5 text-muted-foreground" />
                      {ft.label}
                    </Button>
                  );
                })}
              </CardContent>
            </Card>

            <Card className="border-border/60 shadow-sm">
              <CardHeader className="p-4 bg-muted/20 border-b">
                <CardTitle className="text-sm font-semibold">Metadata & Key</CardTitle>
              </CardHeader>
