import { api } from '@/lib/api';
import { CountUp } from '@/components/clinical/SharedStates';

/**
 * File 17 §17.2/§17.3/§17.4: KPI compute (nulls shown as —, never faked),
 * daily metrics, AI panel (discharge draft, no-show, forecast, log).
 */
const KPI_LABELS: Record<string, string> = {
  bed_occupancy: 'Bed occupancy %', avg_los: 'Avg LOS (days)', collection_ratio: 'Collection %',
  denial_rate: 'Denial %', opd_wait_p50: 'OPD wait p50', left_without_seen: 'LWBS %',
  lab_tat_breach: 'Lab TAT breach %', ot_utilization: 'OT utilization %',
  readmit_30: '30-day readmit %', recall_conversion: 'Recall conversion %',
  avg_bill_value: 'Avg bill (₹)', noshow_pct: 'No-show %', cancel_pct: 'Cancelled %',
  discharge_before_noon_pct: 'Discharge by noon %', rx_verify_backlog: 'Rx verify backlog',
  pharmacy_pending_count: 'Pharmacy load', lab_verify_backlog: 'Lab verify backlog',
  ot_completed_30d: 'OT done (30d)',
};

export default function KpiDashboard() {
  const [kpis, setKpis] = useState<Record<string, number | null>>({});
  const [days, setDays] = useState<any[]>([]);
  const [invs, setInvs] = useState<any[]>([]);
  const [draft, setDraft] = useState('');
  const [draftFields, setDraftFields] = useState({ diagnosis: '', procedures: '', course: '', meds: '', followUp: '' });
  const [ns, setNs] = useState<any | null>(null);
  const [nsForm, setNsForm] = useState({ pastNoShows: '1', pastVisits: '5', leadDays: '3', hour: '10' });
  const [fc, setFc] = useState<any | null>(null);
  const [fcCounts, setFcCounts] = useState('22,25,21,28');

  const load = async () => {
    try {
      const [k, d, a]: any[] = await Promise.all([api.kpiCompute(), api.dailyMetrics(), api.aiInvocations()]);
      setKpis(k?.kpis || {});
      setDays(d?.days || []);
      setInvs(a?.invocations || []);
    } catch { toast.error('Failed to load KPIs'); }
  };
  useEffect(() => { load(); }, []);

  const doDraft = async () => {
    try {
      const r: any = await api.aiDischargeDraft(draftFields);
      setDraft(r?.draft || '');
      toast.success(`Draft ready (${r?.provider}, redacted: ${r?.redacted ? 'yes' : 'no'})`);
      load();
    } catch (e: any) { toast.error(e?.message || 'Draft failed (AI disabled?)'); }
  };

  const doNs = async () => {
    try {
      const r: any = await api.aiNoshow({
        pastNoShows: Number(nsForm.pastNoShows), pastVisits: Number(nsForm.pastVisits),
        leadDays: Number(nsForm.leadDays), hour: Number(nsForm.hour),
      });
      setNs(r);
    } catch { toast.error('Score failed'); }
  };

  const doFc = async () => {
    try {
      const counts = fcCounts.split(',').map((s) => Number(s.trim())).filter((n) => !Number.isNaN(n));
      const r: any = await api.aiForecast(counts);
      setFc(r);
    } catch { toast.error('Forecast failed'); }
  };

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Gauge size={18} /> KPIs & intelligence</h1>
      <div className="grid gap-2 md:grid-cols-5">
        {Object.entries(KPI_LABELS).map(([k, label]) => (
          <Card key={k}><CardContent className="p-3">
            <p className="text-[11px] text-muted-foreground">{label}</p>
            <p className="text-xl font-bold">{kpis[k] == null ? <span className="text-muted-foreground">—</span> : <CountUp value={kpis[k] as number} />}</p>
          </CardContent></Card>
        ))}
      </div>
      {days.length > 0 ? (
        <Card><CardHeader><CardTitle className="text-sm">Daily metrics</CardTitle></CardHeader>
          <CardContent className="flex gap-3 overflow-x-auto text-xs">
            {days.slice(0, 10).map((d) => (
              <div key={d.day} className="min-w-32 rounded border p-2">
                <p className="font-semibold">{d.day}</p>
                <p>billed ₹{(d.metrics?.billed || 0).toLocaleString('en-IN')}</p>
                <p>collected ₹{(d.metrics?.collected || 0).toLocaleString('en-IN')}</p>
                <p>admissions {d.metrics?.admissions ?? 0}</p>
              </div>
            ))}
          </CardContent></Card>
      ) : null}
      <div className="grid gap-3 lg:grid-cols-3">
        <Card><CardHeader><CardTitle className="flex items-center gap-1 text-sm"><Brain size={14} /> Discharge draft</CardTitle></CardHeader>
          <CardContent className="space-y-1.5">
            {Object.keys(draftFields).map((f) => (
              <Input key={f} className="h-8 text-xs" placeholder={f} value={(draftFields as any)[f]} onChange={(e) => setDraftFields({ ...draftFields, [f]: e.target.value })} />
            ))}
            <Button size="sm" onClick={doDraft}>Draft (stub provider, logged)</Button>
            {draft ? <pre className="max-h-48 overflow-auto whitespace-pre-wrap rounded border bg-muted/40 p-2 text-xs">{draft}</pre> : null}
          </CardContent></Card>
        <Card><CardHeader><CardTitle className="flex items-center gap-1 text-sm"><TrendingUp size={14} /> No-show + forecast</CardTitle></CardHeader>
          <CardContent className="space-y-1.5">
            <div className="flex gap-1">
              {Object.keys(nsForm).map((f) => (
                <Input key={f} className="h-8 text-xs" placeholder={f} value={(nsForm as any)[f]} onChange={(e) => setNsForm({ ...nsForm, [f]: e.target.value })} />
              ))}
            </div>
            <Button size="sm" onClick={doNs}>Score</Button>
            {ns ? <p className="text-sm">No-show risk: <b>{ns.score}/100</b></p> : null}
            <div className="flex gap-1 border-t pt-2">
              <Input className="h-8 font-mono text-xs" value={fcCounts} onChange={(e) => setFcCounts(e.target.value)} />
              <Button size="sm" onClick={doFc}>Forecast</Button>
            </div>
            {fc ? <p className="text-sm">Forecast: <b>{fc.forecast}</b> <span className="text-muted-foreground">({fc.basis})</span></p> : null}
          </CardContent></Card>
        <Card><CardHeader><CardTitle className="text-sm">AI invocations ({invs.length})</CardTitle></CardHeader>
          <CardContent className="max-h-64 space-y-1 overflow-auto">
            {invs.map((a) => (
              <p key={a._id} className="rounded border px-2 py-1 font-mono text-[11px]">{a.feature} · {a.provider} · {a.ok ? 'ok' : `ERR ${a.error}`} · {String(a.createdAt).slice(0, 16)}</p>
            ))}
            {invs.length === 0 ? <p className="text-xs text-muted-foreground">No invocations yet.</p> : null}
          </CardContent></Card>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { Cpu, Send, Radio, FlaskConical, CheckCircle2, AlertTriangle } from 'lucide-react';

const ANALYZERS = [
  { id: 'biochem-xl-640', model: 'Erba Lachema XL-640', dept: 'Biochemistry', protocol: 'ASTM' },
  { id: 'hematology-xn-1000', model: 'Sysmex XN-1000', dept: 'Hematology', protocol: 'HL7' },
  { id: 'immunoassay-access-2', model: 'Bio-Rad Access 2', dept: 'Immunoassay', protocol: 'HL7' },
];

/**
 * Device Integration Module: LIS analyzer emulator — generates real-format
 * ASTM/HL7 packets from named analyzers, previews parser output, then pushes
 * the packet through the actual ingest pipeline (bidirectional bridge test).
 */
export default function LabAnalyzerEmulatorPage() {
  const [analyzer, setAnalyzer] = useState(ANALYZERS[0].id);
  const [sampleId, setSampleId] = useState('');
  const [emulated, setEmulated] = useState<any>(null);
  const [genLoading, setGenLoading] = useState(false);
  const [sendLoading, setSendLoading] = useState(false);
  const [ingestResult, setIngestResult] = useState<any>(null);

  const profile = ANALYZERS.find((a) => a.id === analyzer)!;

  const generate = async () => {
    try {
      setGenLoading(true);
      setIngestResult(null);
      const r: any = await api.post('/lab/ingest/emulate', { analyzer, sampleId: sampleId || undefined });
      setEmulated(r);
      toast.success(`Packet generated for ${r.analyzerModel} (${r.protocol}) — ${r.preview?.results?.length ?? 0} results parsed`);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Emulation failed');
    } finally { setGenLoading(false); }
  };

  const sendToIngest = async () => {
    if (!emulated) return;
    try {
      setSendLoading(true);
      const r: any = emulated.protocol === 'HL7'
        ? await api.post('/lab/ingest/hl7', { message: emulated.rawPacket })
        : await api.post('/lab/ingest/astm', { frame: emulated.rawPacket });
      setIngestResult(r);
      toast.success(r?.message || `Ingested: ${r?.applied ?? r?.matched ?? 0} applied, ${r?.critical ?? 0} critical`);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Ingest failed');
    } finally { setSendLoading(false); }
  };

  return (
    <div className="container mx-auto p-4 md:p-6 space-y-6">
      <div className="border-b pb-4">
        <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
          <Cpu className="h-6 w-6 text-primary" />
          LIS Analyzer Emulator
          <Badge variant="outline">Device Integration · ASTM / HL7</Badge>
        </h1>
        <p className="text-sm text-muted-foreground mt-1">
          Simulate a benchtop analyzer: generate a protocol-correct packet, preview parsing, then push it through the real ingest pipeline.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Analyzer selection */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <FlaskConical className="h-4 w-4 text-primary" /> Analyzer
            </CardTitle>
            <CardDescription className="text-xs">Pick an instrument profile.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-2">
            {ANALYZERS.map((a) => (
              <button
                key={a.id}
                onClick={() => setAnalyzer(a.id)}
                className={`w-full text-left rounded-lg border p-3 text-xs transition-colors ${analyzer === a.id ? 'border-primary bg-primary/10' : 'hover:bg-muted/50'}`}
              >
                <div className="flex items-center justify-between">
                  <span className="font-semibold">{a.model}</span>
                  <Badge variant="outline" className="text-[10px]">{a.protocol}</Badge>
                </div>
                <div className="text-muted-foreground mt-0.5">{a.dept} · {a.id}</div>
              </button>
            ))}
            <div className="space-y-1 pt-2">
              <label className="text-xs font-semibold text-muted-foreground">Sample / Accession ID (optional)</label>
              <Input value={sampleId} onChange={(e) => setSampleId(e.target.value)} placeholder="auto-generated if blank" className="text-xs font-mono" />
            </div>
            <Button className="w-full" disabled={genLoading} onClick={generate}>
              <Radio className="h-4 w-4 mr-2" /> {genLoading ? 'Generating…' : 'Generate packet'}
            </Button>
          </CardContent>
        </Card>

        {/* Raw packet */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Radio className="h-4 w-4 text-primary" /> Raw wire packet
              {emulated && <Badge variant="outline" className="text-[10px]">{emulated.protocol}</Badge>}
            </CardTitle>
            <CardDescription className="text-xs">
              {emulated ? `${emulated.analyzerModel} · sample ${emulated.sampleId}` : 'Generate to see the packet.'}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <pre className="max-h-64 overflow-auto rounded-lg bg-black/90 text-green-400 p-3 text-[11px] font-mono whitespace-pre-wrap break-all">
              {emulated?.rawPacket?.replace(/\r/g, '␍\n') || '— no packet yet —'}
            </pre>
            <div className="flex items-center gap-2">
              <Button size="sm" disabled={!emulated || sendLoading} onClick={sendToIngest}>
                <Send className="h-3.5 w-3.5 mr-1" /> {sendLoading ? 'Sending…' : `Send to ${emulated?.ingestEndpoint || 'ingest'}`}
              </Button>
              {ingestResult && (
                <span className="text-xs text-emerald-600 flex items-center gap-1">
                  <CheckCircle2 className="h-3.5 w-3.5" /> applied {ingestResult.applied ?? ingestResult.matched ?? 0}
                </span>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Parsed preview */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-primary" /> Parser preview
            </CardTitle>
            <CardDescription className="text-xs">
              {emulated ? `${emulated.preview?.results?.length ?? 0} result(s) via ${emulated.preview?.protocol}` : 'Parsed output appears here.'}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {!emulated?.preview?.results?.length ? (
              <p className="text-sm text-muted-foreground text-center py-8">No parsed results yet.</p>
            ) : (
              <table className="w-full text-xs">
                <thead>
                  <tr className="text-left text-muted-foreground border-b">
                    <th className="py-1.5 pr-2">Test</th>
                    <th className="py-1.5 pr-2">Value</th>
                    <th className="py-1.5 pr-2">Ref</th>
                    <th className="py-1.5">Flag</th>
                  </tr>
                </thead>
                <tbody>
                  {emulated.preview.results.map((r: any, i: number) => (
                    <tr key={i} className="border-b last:border-0">
                      <td className="py-1.5 pr-2 font-mono">{r.testCode}</td>
                      <td className="py-1.5 pr-2">{r.value} <span className="text-muted-foreground">{r.units}</span></td>
                      <td className="py-1.5 pr-2 text-muted-foreground">{r.referenceRange}</td>
                      <td className="py-1.5">
                        <Badge variant="outline" className={`text-[10px] ${r.flag === 'N' ? 'text-emerald-600 border-emerald-500/30' : 'text-red-600 border-red-500/30'}`}>
                          {r.flag === 'N' ? <CheckCircle2 className="h-3 w-3 inline mr-0.5" /> : <AlertTriangle className="h-3 w-3 inline mr-0.5" />}
                          {r.flag}
                        </Badge>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

