  const handleAdvanceStatus = async (id: string, nextStatus: string) => {
    try {
      await api.put(`/linen/requests/${id}/status`, { status: nextStatus });
      toast.success(`Load progressed to ${nextStatus.toUpperCase()}`);
      loadData();
