import { useEffect, useState } from 'react';
import { Award, Hammer, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';

/** File 22 P2-30: NABH chapters + assessments, CAPA board, registers. */
export default function QualityBoard() {
  const [tab, setTab] = useState<'nabh' | 'capa' | 'registers'>('nabh');
  const [chapters, setChapters] = useState<any[]>([]);
  const [kpis, setKpis] = useState<Record<string, any>>({});
  const [scores, setScores] = useState<Record<string, string>>({});
  const [capas, setCapas] = useState<any[]>([]);
  const [finding, setFinding] = useState('');
  const [mtp, setMtp] = useState<any[]>([]);
  const [mtpForm, setMtpForm] = useState({ patientName: '', gestationalAgeWeeks: '', indication: 'other' });

  const load = async () => {
    try {
      const [c, k, cp, m]: any[] = await Promise.all([
        api.nabhChapters(), api.kpiCompute(), api.capaList({}), api.mtpList(),
      ]);
      setChapters(c?.chapters || []);
      setKpis(k?.kpis || {});
      setCapas(cp?.capa || []);
      setMtp(m?.entries || []);
    } catch { toast.error('Failed to load quality board'); }
  };
  useEffect(() => { load(); }, []);

  const seed = async () => {
    try { await api.seedNabh(); toast.success('Chapters seeded'); load(); }
    catch { toast.error('Seed failed'); }
  };

  const assess = async (code: string) => {
    try {
      const r: any = await api.nabhAssess({ chapter: code, scores });
      toast.success(`Scored ${r?.scorePct}%`);
      setScores({});
      load();
    } catch (e: any) { toast.error(e?.message || 'Assess failed'); }
  };

  const addCapa = async () => {
    if (!finding.trim()) return;
    try { await api.capaCreate({ finding }); setFinding(''); toast.success('CAPA opened'); load(); }
    catch { toast.error('Create failed'); }
  };

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Award size={18} /> Quality board</h1>
      <div className="flex gap-1">
        {([['nabh', 'NABH', Award], ['capa', 'CAPA', Hammer], ['registers', 'Registers', FileText]] as const).map(([k, label, Icon]) => (
          <Button key={k} size="sm" variant={tab === k ? 'default' : 'outline'} onClick={() => setTab(k)}><Icon size={14} /> {label}</Button>
        ))}
        <div className="flex-1" />
        <Button size="sm" variant="outline" onClick={seed}>Seed chapters</Button>
      </div>

      {tab === 'nabh' ? (
        <div className="grid gap-3 lg:grid-cols-2">
          {chapters.map((c) => (
            <Card key={c.code}>
              <CardHeader><CardTitle className="text-sm">{c.code} — {c.title}</CardTitle></CardHeader>
              <CardContent className="space-y-1.5">
                {(c.objectives || []).map((o: any) => (
                  <div key={o.code} className="flex items-center justify-between gap-2 rounded border px-2 py-1 text-xs">
                    <span><b className="font-mono">{o.code}</b> {o.label}</span>
                    <span className="flex items-center gap-1">
                      {o.autoKpi ? <span className="rounded bg-muted px-1.5 py-0.5 font-mono">auto: {kpis[o.autoKpi] ?? '—'}</span> : null}
                      <select aria-label={o.code} className="rounded border px-1 py-0.5 text-xs"
                        value={scores[o.code] || ''} onChange={(e) => setScores({ ...scores, [o.code]: e.target.value })}>
                        <option value="">—</option>
                        <option>compliant</option><option>partial</option><option>non_compliant</option><option>na</option>
                      </select>
                    </span>
                  </div>
                ))}
                <Button size="sm" onClick={() => assess(c.code)}>Save assessment</Button>
              </CardContent>
            </Card>
          ))}
          {chapters.length === 0 ? <EmptyState title="No chapters" hint="Seed the 8 NABH chapters first." /> : null}
        </div>
      ) : null}

      {tab === 'capa' ? (
        <Card>
          <CardHeader><CardTitle className="text-sm">CAPA ({capas.length})</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <div className="flex gap-1">
              <Input className="h-8 text-xs" placeholder="Finding…" value={finding} onChange={(e) => setFinding(e.target.value)} />
              <Button size="sm" onClick={addCapa}>Open</Button>
            </div>
            {capas.map((c) => (
              <div key={c._id} className="flex items-center justify-between gap-2 rounded border p-2 text-xs">
                <span className="truncate"><b>{c.source}</b> · {c.finding}</span>
                <span className="flex shrink-0 items-center gap-1">
                  <StatusPill status={c.status} />
                  {c.status !== 'Closed' ? (
                    <Button size="sm" variant="outline" onClick={async () => {
                      const eff = window.prompt('Effectiveness review (required to close):');
                      if (!eff) return;
                      await api.capaPatch(c._id, { status: 'Closed', effectiveness: eff });
                      load();
                    }}>Close</Button>
                  ) : null}
                </span>
              </div>
            ))}
          </CardContent>
        </Card>
      ) : null}

      {tab === 'registers' ? (
        <div className="grid gap-3 lg:grid-cols-2">
          <Card>
            <CardHeader><CardTitle className="text-sm">MTP register ({mtp.length})</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              <div className="flex flex-wrap gap-1">
                <Input className="h-8 w-40 text-xs" placeholder="Patient name" value={mtpForm.patientName} onChange={(e) => setMtpForm({ ...mtpForm, patientName: e.target.value })} />
                <Input className="h-8 w-24 text-xs" placeholder="Weeks" value={mtpForm.gestationalAgeWeeks} onChange={(e) => setMtpForm({ ...mtpForm, gestationalAgeWeeks: e.target.value })} />
                <select aria-label="Indication" className="rounded-md border px-2 text-xs" value={mtpForm.indication} onChange={(e) => setMtpForm({ ...mtpForm, indication: e.target.value })}>
                  <option>A</option><option>B</option><option>C</option><option>failure-contraception</option><option>other</option>
                </select>
                <Button size="sm" onClick={async () => {
                  try {
                    await api.mtpCreate({ ...mtpForm, gestationalAgeWeeks: Number(mtpForm.gestationalAgeWeeks), consentTaken: true });
                    toast.success('Registered (consent recorded)');
                    setMtpForm({ patientName: '', gestationalAgeWeeks: '', indication: 'other' });
                    load();
                  } catch (e: any) { toast.error(e?.response?.data?.message || 'Save failed'); }
                }}>Register + consent</Button>
              </div>
              {mtp.slice(0, 20).map((m: any) => (
                <p key={m._id} className="rounded border px-2 py-1 text-xs">{m.patientName} · {m.gestationalAgeWeeks}w · {m.indication}</p>
              ))}
            </CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="text-sm">PCPNDT Form F</CardTitle></CardHeader>
            <CardContent>
              <p className="text-xs text-muted-foreground">Filed from the radiology desk via <span className="font-mono">POST /api/quality/pcpndt</span> (patient + declaration). Entries are tenant-scoped and audited.</p>
            </CardContent>
          </Card>
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { Ticket, Clock, Users, AlertTriangle, TrendingUp, CheckCircle2 } from 'lucide-react';

interface QueueTicket {
  _id: string;
  tokenNumber: number;
  patientName?: string;
  department?: string;
  doctorName?: string;
  priority: string;
  status: string;
  createdAt: string;
  waitingMinutes: number;
}

interface QueueStats {
  totalWaiting: number;
  avgWaitMinutes: number;
  priorityCount: number;
  overdueCount: number;
}

export default function QueueAgingDashboard() {
  const [tickets, setTickets] = useState<QueueTicket[]>([]);
  const [stats, setStats] = useState<QueueStats | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => { loadQueue(); }, []);

  const loadQueue = async () => {
    try {
      const res = await api.get('/queues');
      const data = res.data;
      const allTickets = data.tickets || data || [];

      // Calculate waiting time and aging
      const now = Date.now();
      const enriched = allTickets.map((t: any) => ({
        ...t,
        waitingMinutes: t.createdAt ? Math.floor((now - new Date(t.createdAt).getTime()) / 60000) : 0,
      }));

      setTickets(enriched);
      setStats({
        totalWaiting: enriched.length,
        avgWaitMinutes: enriched.length > 0
          ? Math.floor(enriched.reduce((s: number, t: any) => s + t.waitingMinutes, 0) / enriched.length)
          : 0,
        priorityCount: enriched.filter((t: any) => t.priority === 'High' || t.priority === 'Emergency').length,
        overdueCount: enriched.filter((t: any) => t.waitingMinutes > 30).length,
      });
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Failed to load queue');
    } finally {
      setLoading(false);
    }
  };

  const getAgingColor = (minutes: number) => {
    if (minutes > 45) return 'text-red-600';
    if (minutes > 30) return 'text-orange-600';
    if (minutes > 15) return 'text-yellow-600';
    return 'text-green-600';
  };

  const getAgingBadge = (minutes: number) => {
    if (minutes > 45) return <Badge className="bg-red-100 text-red-800">Critical</Badge>;
    if (minutes > 30) return <Badge className="bg-orange-100 text-orange-800">Overdue</Badge>;
    if (minutes > 15) return <Badge className="bg-yellow-100 text-yellow-800">Warning</Badge>;
    return <Badge className="bg-green-100 text-green-800">OK</Badge>;
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <Ticket className="w-6 h-6 text-blue-600" />
          Queue Aging Dashboard
        </h1>
        <p className="text-muted-foreground mt-1">Real-time queue wait times and priority aging</p>
      </div>

      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {[
            { label: 'Total Waiting', value: stats.totalWaiting, icon: Users, color: 'text-blue-600' },
            { label: 'Avg Wait (min)', value: stats.avgWaitMinutes, icon: Clock, color: 'text-yellow-600' },
            { label: 'Priority Cases', value: stats.priorityCount, icon: AlertTriangle, color: 'text-orange-600' },
            { label: 'Overdue (>30m)', value: stats.overdueCount, icon: TrendingUp, color: 'text-red-600' },
          ].map((s) => (
            <Card key={s.label}>
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">{s.label}</p>
                    <p className="text-2xl font-bold">{s.value}</p>
                  </div>
                  <s.icon className={`w-8 h-8 ${s.color}`} />
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Live Queue</CardTitle>
          <CardDescription>Tickets sorted by wait time (longest waiting first)</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <p className="text-muted-foreground">Loading queue...</p>
          ) : tickets.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <CheckCircle2 className="w-12 h-12 mx-auto mb-4 text-green-500" />
              <p>No patients waiting</p>
            </div>
          ) : (
            <div className="space-y-2">
              {tickets
                .sort((a, b) => b.waitingMinutes - a.waitingMinutes)
                .map((t) => (
                  <div key={t._id} className="p-3 border rounded-lg flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="text-center">
                        <p className="text-lg font-bold">#{t.tokenNumber}</p>
                      </div>
                      <div>
                        <p className="font-medium">{t.patientName || 'Patient'}</p>
                        <p className="text-sm text-muted-foreground">
                          {t.department || 'OPD'} {t.doctorName ? `· Dr. ${t.doctorName}` : ''}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className={`font-medium ${getAgingColor(t.waitingMinutes)}`}>
                        {t.waitingMinutes}m
                      </span>
                      {getAgingBadge(t.waitingMinutes)}
                      {t.priority === 'Emergency' && (
                        <Badge className="bg-red-100 text-red-800">Emergency</Badge>
                      )}
                    </div>
                  </div>
                ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { IndianRupee, Radar } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { CountUp, EmptyState } from '@/components/clinical/SharedStates';

/** File 16 §16.1: RCM pipeline stages + open gaps + detect + daily metrics. */
export default function RcmDashboard() {
  const [stages, setStages] = useState<any[]>([]);
  const [gaps, setGaps] = useState<any[]>([]);
  const [metrics, setMetrics] = useState<any[]>([]);
  const [kind, setKind] = useState('');
  const [reconOut, setReconOut] = useState<any | null>(null);

  const load = async () => {
    try {
      const [p, m]: any[] = await Promise.all([api.rcmPipeline(), api.rcmMetrics()]);
      setStages(p?.stages || []);
      setGaps(p?.gaps || []);
      setMetrics(m?.metrics || []);
    } catch { toast.error('Failed to load RCM'); }
  };
  useEffect(() => { load(); }, []);

  const detect = async () => {
    try {
      const r: any = await api.rcmDetect();
      toast.success(`${r?.opened || 0} gaps opened`);
      load();
    } catch (e: any) { toast.error(e?.message || 'Detect failed'); }
  };

  const close = async (id: string) => {
    try {
      await api.rcmCloseGap(id);
      toast.success('Gap closed');
      load();
    } catch { toast.error('Close failed'); }
  };

  const shown = kind ? gaps.filter((g) => g.kind === kind) : gaps;
  const atRisk = gaps.reduce((a, g) => a + Number(g.amount || 0), 0);

  return (
    <div className="space-y-3 p-4">
      <div className="flex items-center gap-2">
        <h1 className="flex items-center gap-2 text-lg font-bold"><IndianRupee size={18} /> Revenue cycle</h1>
        <span className="rounded-full bg-red-50 px-2.5 py-0.5 text-xs font-semibold text-red-800">₹<CountUp value={atRisk} /> at risk</span>
        <div className="flex-1" />
        <Button size="sm" variant="outline" onClick={async () => {
          try {
            const r: any = await api.checkoutReconcile('razorpay');
            const c: any = await api.checkoutReconcile('cashfree');
            setReconOut({ razorpay: r, cashfree: c });
            toast.success(`Reconciled: ${(r?.settled || 0) + (c?.settled || 0)} settled`);
          } catch (e: any) { toast.error(e?.message || 'Reconcile failed'); }
        }}>Reconcile gateways</Button>
        <Button size="sm" onClick={detect}><Radar size={14} /> Run detectors</Button>
