      ) : null}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Landmark, Upload, Wand2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';

/**
 * File 16 §16.3: bank recon workbench — accounts, statement paste-import,
 * two-pane automatch review, manual match, rules, guarded close.
 */
export default function ReconWorkbench() {
  const [accounts, setAccounts] = useState<any[]>([]);
  const [impId, setImpId] = useState('');
  const [txns, setTxns] = useState<any[]>([]);
  const [rules, setRules] = useState<any[]>([]);
  const [paste, setPaste] = useState('');
  const [accId, setAccId] = useState('');
  const [onlyUnmatched, setOnlyUnmatched] = useState(true);
  const [manual, setManual] = useState({ txn: '', targetId: '' });

  const load = async () => {
    try {
      const [a, r]: any[] = await Promise.all([api.reconAccounts(), api.reconRules()]);
      setAccounts(a?.accounts || []);
      setRules(r?.rules || []);
      if (a?.accounts?.[0] && !accId) setAccId(a.accounts[0]._id);
    } catch { toast.error('Failed to load recon'); }
  };
  useEffect(() => { load(); }, []);

  const loadTxns = async (id: string) => {
    try {
      const r: any = await api.importTxns(id, onlyUnmatched ? { matched: '0' } : {});
      setTxns(r?.txns || []);
    } catch { toast.error('Failed to load txns'); }
  };

  // Paste CSV: date,narration,utr,debit,credit (one row per line).
  const doImport = async () => {
    const rows = paste.split('\n').map((l) => l.trim()).filter(Boolean).map((l) => {
      const [date, narration, utr, debit, credit] = l.split(',').map((s) => s.trim());
      return { date, narration, utr, debit: Number(debit) || 0, credit: Number(credit) || 0 };
    }).filter((r) => r.date && (r.debit || r.credit));
    if (!rows.length || !accId) { toast.error('Pick an account and paste valid rows'); return; }
    try {
      const r: any = await api.importStatement({ bankAccountId: accId, fileName: 'paste.csv', rows });
      setImpId(r?.id);
      toast.success(`${r?.rows} rows imported`);
      loadTxns(r?.id);
    } catch (e: any) { toast.error(e?.message || 'Import failed'); }
  };

  const automatch = async () => {
    if (!impId) return;
    try {
      const r: any = await api.automatchImport(impId);
      toast.success(`${r?.matched}/${r?.scanned} matched`);
      loadTxns(impId);
    } catch (e: any) { toast.error(e?.message || 'Automatch failed'); }
  };

  // CSV file upload: parses date,narration,utr,debit,credit with optional header row.
  const handleCsvFile = async (file: File) => {
    if (!accId) { toast.error('Pick an account first'); return; }
    try {
      const text = await file.text();
      const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
      if (!lines.length) { toast.error('File is empty'); return; }
      // Skip header row if first line is not a date
      const hasHeader = !/^\d{4}[-/]\d{1,2}[-/]\d{1,2}/.test(lines[0].split(',')[0].trim());
      const dataLines = hasHeader ? lines.slice(1) : lines;
      const rows = dataLines.map((l) => {
        const parts = l.split(',').map((s) => s.trim().replace(/^"|"$/g, ''));
        const [date, narration, utr, debit, credit] = parts;
        return { date, narration, utr, debit: Number(debit) || 0, credit: Number(credit) || 0 };
      }).filter((r) => r.date && (r.debit || r.credit));
      if (!rows.length) { toast.error('No valid rows found (date + debit/credit required)'); return; }
      const r: any = await api.importStatement({ bankAccountId: accId, fileName: file.name, rows });
      setImpId(r?.id);
      toast.success(`${r?.rows ?? rows.length} rows imported from ${file.name}`);
      loadTxns(r?.id);
    } catch (e: any) { toast.error(e?.message || 'CSV import failed'); }
  };

  const matchManual = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await api.matchTxn(manual.txn, { targetModel: 'Payment', targetId: manual.targetId });
      toast.success('Matched');
      setManual({ txn: '', targetId: '' });
      if (impId) loadTxns(impId);
    } catch (e: any) { toast.error(e?.message || 'Match failed'); }
  };

  const close = async () => {
    if (!impId) return;
    try {
      await api.closeRecon(impId);
      toast.success('Import closed');
    } catch (e: any) { toast.error(e?.message || 'Close blocked — unmatched remain?'); }
  };

  return (
    <div className="grid gap-4 p-4 lg:grid-cols-[340px_1fr]">
      <div className="space-y-3">
        <Card><CardHeader><CardTitle className="flex items-center gap-1 text-sm"><Landmark size={14} /> Import statement</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <select className="w-full rounded-md border px-2 py-2 text-sm" value={accId} onChange={(e) => setAccId(e.target.value)}>
              {accounts.map((a) => <option key={a._id} value={a._id}>{a.bankName} ··{String(a.accountNo).slice(-4)}</option>)}
            </select>
            <textarea className="h-32 w-full rounded-md border p-2 font-mono text-xs" placeholder="2026-10-01,NEFT salary,UTR123,0,45000" value={paste} onChange={(e) => setPaste(e.target.value)} />
            <div className="flex flex-wrap gap-2">
              <Button size="sm" onClick={doImport}><Upload size={14} /> Import rows</Button>
              <label className="inline-flex cursor-pointer items-center gap-1 rounded-md border px-3 py-1.5 text-xs font-medium hover:bg-muted">
                <Upload size={14} /> Upload CSV
                <input
                  type="file"
                  accept=".csv,text/csv,text/plain"
                  className="hidden"
                  onChange={(e) => {
                    const f = e.target.files?.[0];
                    if (f) handleCsvFile(f);
                    e.target.value = '';
                  }}
                />
              </label>
            </div>
            <p className="text-[10px] text-muted-foreground">
              Columns: date, narration, UTR, debit, credit (header row optional).
              Auto-match tiers: UTR exact → amount ±1 / date ±3d fuzzy → narration rules.
            </p>
          </CardContent></Card>
        <Card><CardHeader><CardTitle className="text-sm">Manual match</CardTitle></CardHeader>
          <CardContent>
            <form onSubmit={matchManual} className="space-y-1.5">
              <Input className="h-8 text-xs" placeholder="txn id" value={manual.txn} onChange={(e) => setManual({ ...manual, txn: e.target.value })} required />
              <Input className="h-8 text-xs" placeholder="payment id" value={manual.targetId} onChange={(e) => setManual({ ...manual, targetId: e.target.value })} required />
              <Button size="sm" type="submit">Match</Button>
            </form>
          </CardContent></Card>
        <Card><CardHeader><CardTitle className="text-sm">Narration rules ({rules.length})</CardTitle></CardHeader>
          <CardContent className="space-y-1">
            {rules.map((r) => <p key={r._id} className="rounded border px-2 py-1 font-mono text-[11px]">{r.pattern} → {r.targetModel}</p>)}
          </CardContent></Card>
      </div>
      <Card>
        <CardHeader><CardTitle className="flex flex-wrap items-center gap-2 text-sm">
          Transactions ({txns.length})
          <Button size="sm" variant="outline" onClick={() => impId && loadTxns(impId)}>Reload</Button>
          <Button size="sm" onClick={automatch}><Wand2 size={14} /> Auto-match</Button>
          <label className="flex items-center gap-1 text-xs font-normal"><input type="checkbox" checked={onlyUnmatched} onChange={(e) => setOnlyUnmatched(e.target.checked)} /> unmatched only</label>
          <div className="flex-1" />
          <Button size="sm" variant="secondary" onClick={close}>Close import</Button>
        </CardTitle></CardHeader>
        <CardContent className="max-h-[560px] space-y-1 overflow-y-auto">
          {txns.map((t) => (
            <div key={t._id} className="flex items-center justify-between gap-2 rounded-md border p-2 text-xs">
              <span className="truncate">{String(t.date).slice(0, 10)} · {t.narration} <span className="font-mono text-muted-foreground">{t.utr}</span></span>
              <span className="flex shrink-0 items-center gap-2">
                {t.credit ? <b className="text-green-700">+{t.credit}</b> : null}{t.debit ? <b className="text-red-700">-{t.debit}</b> : null}
                <StatusPill status={t.matchId ? 'matched' : 'open'} />
              </span>
            </div>
          ))}
          {txns.length === 0 ? <p className="text-sm text-muted-foreground">Import a statement to begin.</p> : null}
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import {
  Briefcase, Users, UserCheck, Plus, Search, Calendar, Building2,
  CheckCircle2, AlertTriangle, ArrowRight, FileText, Star,
} from 'lucide-react';

interface JobOpening {
  _id: string;
  title: string;
  department: string;
  designation?: string;
  openings: number;
  status: string;
  postedDate: string;
  employmentType: string;
}

interface Candidate {
  _id: string;
  name: string;
  email: string;
  phone: string;
  stage: string;
  jobOpeningId?: { title: string; department: string };
  createdAt: string;
}

interface Stats {
  openJobs: number;
  totalCandidates: number;
  shortlisted: number;
  hired: number;
  pendingOnboarding: number;
}

const STAGE_COLORS: Record<string, string> = {
  Applied: 'bg-blue-100 text-blue-800',
  Screening: 'bg-yellow-100 text-yellow-800',
  Shortlisted: 'bg-purple-100 text-purple-800',
  'Interview Scheduled': 'bg-indigo-100 text-indigo-800',
  Interviewed: 'bg-cyan-100 text-cyan-800',
  'Offer Released': 'bg-orange-100 text-orange-800',
  'Offer Accepted': 'bg-green-100 text-green-800',
  Hired: 'bg-green-100 text-green-800',
  Rejected: 'bg-red-100 text-red-800',
};

export default function RecruitmentPage() {
  const [tab, setTab] = useState<'jobs' | 'candidates' | 'onboarding'>('jobs');
  const [jobs, setJobs] = useState<JobOpening[]>([]);
  const [candidates, setCandidates] = useState<Candidate[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');

  const [jobModalOpen, setJobModalOpen] = useState(false);
  const [jobForm, setJobForm] = useState({ title: '', department: '', designation: '', employmentType: 'Full-time', openings: 1 });

  const [candidateModalOpen, setCandidateModalOpen] = useState(false);
  const [candidateForm, setCandidateForm] = useState({ jobOpeningId: '', name: '', email: '', phone: '' });

  useEffect(() => { loadData(); }, [tab]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [statsRes, jobsRes, candRes] = await Promise.all([
        api.get('/recruitment/stats'),
        api.get('/recruitment/jobs'),
        api.get('/recruitment/candidates'),
      ]);
      setStats(statsRes.data);
      setJobs(jobsRes.data.jobs || []);
      setCandidates(candRes.data.candidates || []);
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Failed to load recruitment data');
    } finally {
      setLoading(false);
    }
  };

  const createJob = async () => {
    try {
      await api.post('/recruitment/jobs', jobForm);
      toast.success('Job opening created');
      setJobModalOpen(false);
      setJobForm({ title: '', department: '', designation: '', employmentType: 'Full-time', openings: 1 });
      loadData();
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Failed to create job');
    }
  };

  const createCandidate = async () => {
    try {
      await api.post('/recruitment/candidates', candidateForm);
      toast.success('Candidate added');
      setCandidateModalOpen(false);
      setCandidateForm({ jobOpeningId: '', name: '', email: '', phone: '' });
      loadData();
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Failed to add candidate');
    }
  };

  const updateStage = async (id: string, stage: string) => {
    try {
      await api.patch(`/recruitment/candidates/${id}/stage`, { stage });
      toast.success(`Stage updated to ${stage}`);
      loadData();
    } catch (err: any) {
      toast.error(err?.response?.data?.message || 'Failed to update stage');
    }
  };

  const filteredCandidates = candidates.filter((c) =>
    !search || c.name.toLowerCase().includes(search.toLowerCase()) || c.email.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Briefcase className="w-6 h-6 text-blue-600" />
            Recruitment & Onboarding
          </h1>
          <p className="text-muted-foreground mt-1">Job openings, applicant tracking, onboarding tasks</p>
        </div>
        <div className="flex gap-2">
          <Button onClick={() => setJobModalOpen(true)} size="sm">
            <Plus className="w-4 h-4 mr-1" /> New Job
          </Button>
          <Button onClick={() => setCandidateModalOpen(true)} size="sm" variant="outline">
            <Users className="w-4 h-4 mr-1" /> Add Candidate
          </Button>
        </div>
      </div>

      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          {[
            { label: 'Open Jobs', value: stats.openJobs, icon: Briefcase, color: 'text-blue-600' },
            { label: 'Total Candidates', value: stats.totalCandidates, icon: Users, color: 'text-purple-600' },
            { label: 'Shortlisted', value: stats.shortlisted, icon: Star, color: 'text-yellow-600' },
            { label: 'Hired', value: stats.hired, icon: UserCheck, color: 'text-green-600' },
            { label: 'Pending Onboarding', value: stats.pendingOnboarding, icon: Calendar, color: 'text-orange-600' },
          ].map((s) => (
            <Card key={s.label}>
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">{s.label}</p>
                    <p className="text-2xl font-bold">{s.value}</p>
                  </div>
                  <s.icon className={`w-8 h-8 ${s.color}`} />
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <div className="flex gap-2 border-b">
        {(['jobs', 'candidates', 'onboarding'] as const).map((t) => (
          <Button
            key={t}
            variant={tab === t ? 'default' : 'ghost'}
            onClick={() => setTab(t)}
            className="capitalize"
          >
            {t}
          </Button>
        ))}
      </div>

      {tab === 'jobs' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {jobs.map((job) => (
            <Card key={job._id}>
              <CardHeader className="pb-2">
                <CardTitle className="text-base">{job.title}</CardTitle>
                <CardDescription>{job.department} · {job.designation || job.employmentType}</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex items-center justify-between">
                  <Badge variant={job.status === 'Open' ? 'default' : 'secondary'}>{job.status}</Badge>
                  <span className="text-sm text-muted-foreground">{job.openings} openings</span>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {tab === 'candidates' && (
        <div className="space-y-4">
          <Input
            placeholder="Search candidates..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="max-w-md"
          />
          <div className="space-y-2">
            {filteredCandidates.map((c) => (
              <Card key={c._id}>
                <CardContent className="p-4 flex items-center justify-between">
                  <div>
                    <p className="font-medium">{c.name}</p>
                    <p className="text-sm text-muted-foreground">{c.email} · {c.phone}</p>
                    {c.jobOpeningId && (
                      <p className="text-xs text-muted-foreground">{c.jobOpeningId.title}</p>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge className={STAGE_COLORS[c.stage] || ''}>{c.stage}</Badge>
                    <Select value={c.stage} onValueChange={(v) => updateStage(c._id, v)}>
                      <SelectTrigger className="w-40">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {Object.keys(STAGE_COLORS).map((s) => (
                          <SelectItem key={s} value={s}>{s}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      )}

      {tab === 'onboarding' && (
        <Card>
          <CardContent className="p-8 text-center text-muted-foreground">
            <CheckCircle2 className="w-12 h-12 mx-auto mb-4 text-green-500" />
            <p>Onboarding tasks are managed per candidate after hire.</p>
            <p className="text-sm mt-2">Move candidates to "Hired" stage to create onboarding tasks.</p>
          </CardContent>
        </Card>
      )}

      {/* Job Creation Dialog */}
      <Dialog open={jobModalOpen} onOpenChange={setJobModalOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Create Job Opening</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <Input placeholder="Job Title" value={jobForm.title} onChange={(e) => setJobForm({ ...jobForm, title: e.target.value })} />
            <Input placeholder="Department" value={jobForm.department} onChange={(e) => setJobForm({ ...jobForm, department: e.target.value })} />
            <Input placeholder="Designation" value={jobForm.designation} onChange={(e) => setJobForm({ ...jobForm, designation: e.target.value })} />
            <Select value={jobForm.employmentType} onValueChange={(v) => setJobForm({ ...jobForm, employmentType: v })}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                {['Full-time', 'Part-time', 'Contract', 'Intern', 'Visiting'].map((t) => (
                  <SelectItem key={t} value={t}>{t}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Input type="number" placeholder="Openings" value={jobForm.openings} onChange={(e) => setJobForm({ ...jobForm, openings: parseInt(e.target.value) || 1 })} />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setJobModalOpen(false)}>Cancel</Button>
            <Button onClick={createJob} disabled={!jobForm.title || !jobForm.department}>Create</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Candidate Dialog */}
      <Dialog open={candidateModalOpen} onOpenChange={setCandidateModalOpen}>
        <DialogContent>
          <DialogHeader><DialogTitle>Add Candidate</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <Select value={candidateForm.jobOpeningId} onValueChange={(v) => setCandidateForm({ ...candidateForm, jobOpeningId: v })}>
              <SelectTrigger><SelectValue placeholder="Select Job" /></SelectTrigger>
              <SelectContent>
                {jobs.filter((j) => j.status === 'Open').map((j) => (
                  <SelectItem key={j._id} value={j._id}>{j.title} - {j.department}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Input placeholder="Full Name" value={candidateForm.name} onChange={(e) => setCandidateForm({ ...candidateForm, name: e.target.value })} />
            <Input placeholder="Email" type="email" value={candidateForm.email} onChange={(e) => setCandidateForm({ ...candidateForm, email: e.target.value })} />
            <Input placeholder="Phone" value={candidateForm.phone} onChange={(e) => setCandidateForm({ ...candidateForm, phone: e.target.value })} />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setCandidateModalOpen(false)}>Cancel</Button>
            <Button onClick={createCandidate} disabled={!candidateForm.name || !candidateForm.email || !candidateForm.phone || !candidateForm.jobOpeningId}>Add</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

