import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import type { Unmodelled } from '@/lib/apiTypes';

/** File 17 §17.1: report studio — catalogue, whitelisted runs, views, schedules. */
export default function ReportStudioPage() {
  const [catalogue, setCatalogue] = useState<any[]>([]);
  const [key, setKey] = useState('unpaid-bills');
  const [out, setOut] = useState<any | null>(null);
  const [views, setViews] = useState<any[]>([]);
  const [schedules, setSchedules] = useState<any[]>([]);
  const [sched, setSched] = useState({ cron: '0 8 * * *', recipients: '' });

  const load = async () => {
    try {
      const [c, v, s]: any[] = await Promise.all([api.studioCatalogue(), api.studioViews(), api.studioSchedules()]);
      setCatalogue(c?.reports || []);
      setViews(v?.views || []);
      setSchedules(s?.schedules || []);
      const first = (c?.reports || []).find((r: any) => r.allowed);
      if (first) setKey(first.key);
    } catch { toast.error('Failed to load studio'); }
  };
  useEffect(() => { load(); }, []);

  const run = async () => {
    try {
      const r: any = await api.runStudioReport(key, {});
      setOut(r);
    } catch (e: any) { toast.error(e?.message || 'Run failed'); }
  };

  // File 22 P2-36: async run with polling (queued → done/failed).
  const [asyncId, setAsyncId] = useState('');
  const [asyncState, setAsyncState] = useState('');
  const runAsync = async () => {
    try {
      const r: any = await api.runStudioAsync(key, {});
      setAsyncId(r?.id || '');
      setAsyncState('queued');
      toast.success('Queued — polling for completion');
      for (let i = 0; i < 20; i += 1) {
        await new Promise((t) => setTimeout(t, 1500));
        const s: any = await api.studioRunStatus(r.id);
        setAsyncState(s?.run?.status || '');
        if (['done', 'failed'].includes(s?.run?.status)) {
          if (s?.run?.status === 'done') {
            setOut({ rows: s.run.result?.rows || [], columns: s.run.result?.columns || [], scanned: s.run.rowCount, ms: s.run.ms });
            toast.success(`Done: ${s.run.rowCount} rows`);
          } else toast.error(s?.run?.error || 'Run failed');
          break;
        }
      }
    } catch (e: any) { toast.error(e?.message || 'Queue failed'); }
  };

  const saveView = async () => {
    const name = window.prompt('View name:');
    if (!name) return;
    try {
      await api.createStudioView({ reportKey: key, name, filters: {}, columns: out?.columns || [] });
      toast.success('View saved');
      load();
    } catch { toast.error('Save failed'); }
  };

  const schedule = async () => {
    try {
      await api.createStudioSchedule({ reportKey: key, cron: sched.cron, recipients: sched.recipients.split(',').map((s) => s.trim()).filter(Boolean) });
      toast.success('Scheduled');
      load();
    } catch (e: any) { toast.error(e?.message || 'Schedule failed (bad cron?)'); }
  };

  return (
    <div className="grid gap-4 p-4 lg:grid-cols-[300px_1fr]">
      <div className="space-y-3">
        <Card><CardHeader><CardTitle className="flex items-center gap-1 text-sm"><FileBarChart size={14} /> Catalogue</CardTitle></CardHeader>
          <CardContent className="space-y-1">
            {catalogue.map((r) => (
              <button key={r.key} disabled={!r.allowed} onClick={() => { setKey(r.key); setOut(null); }}
                className={`w-full rounded-md border px-2 py-1.5 text-left text-xs ${key === r.key ? 'border-primary' : ''} ${r.allowed ? 'hover:bg-muted' : 'opacity-40'}`}>
                <span className="font-semibold">{r.name}</span> <span className="text-muted-foreground">· {r.category}</span>
              </button>
            ))}
          </CardContent></Card>
        <Card><CardHeader><CardTitle className="flex items-center gap-1 text-sm"><CalendarClock size={14} /> Schedules ({schedules.length})</CardTitle></CardHeader>
          <CardContent className="space-y-1">
            {schedules.map((s) => <p key={s._id} className="rounded border px-2 py-1 font-mono text-[11px]">{s.reportKey} · {s.cron}</p>)}
            <div className="flex gap-1 border-t pt-2">
              <Input className="h-8 font-mono text-xs" value={sched.cron} onChange={(e) => setSched({ ...sched, cron: e.target.value })} />
              <Button size="sm" onClick={schedule}>Schedule</Button>
            </div>
          </CardContent></Card>
      </div>
      <Card>
        <CardHeader>        <CardTitle className="flex items-center gap-2 text-sm">{key}
          <Button size="sm" onClick={run}>Run</Button>
          <Button size="sm" variant="outline" onClick={runAsync}>Run async{asyncState ? ` (${asyncState})` : ''}</Button>
          <Button size="sm" variant="outline" onClick={saveView}><Save size={14} /> Save view</Button>
          <span className="text-xs font-normal text-muted-foreground">{out ? `${out.rows?.length} rows (scanned ${out.scanned}, ${out.ms}ms)` : ''}</span>
        </CardTitle></CardHeader>
        <CardContent>
          {out ? (
            <div className="max-h-[560px] overflow-auto rounded-md border">
              {/* Whitelisted report output: dynamic columns, capped at 200 rows. */}
              <DataGrid
                columns={(out.columns || []).map((c: string) => ({
                  key: c,
                  label: c,
                  sortable: false,
                  render: (v: Unmodelled) => <span className="block max-w-48 truncate">{String(v ?? '')}</span>,
                }))}
                rows={(out.rows || []).slice(0, 200).map((r: any, i: number) => ({ ...r, __id: `r-${i}` }))}
                rowKey="__id"
                empty="No rows"
                showSearch={false}
                manualPagination
              />
            </div>
          ) : <p className="text-sm text-muted-foreground">Pick a report and Run. Views ({views.length}) reuse saved columns.</p>}
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { FlaskConical, Play } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';

/**
 * File 13 §13.5: rule list + condition builder (DNF) + test-fire/backtest.
 * Actions: alert | task | webhook-log.
 */
const OPS = ['=', '!=', '>', '>=', '<', '<=', 'between', 'in', 'contains', 'is_set', 'is_empty'];

export default function RulesStudio() {
  const [rules, setRules] = useState<any[]>([]);
  const [datasets, setDatasets] = useState<Record<string, any>>({});
  const [form, setForm] = useState({ key: '', name: '', dataset: 'bills_unpaid', field: 'balance', op: '>', value: '0', action: 'alert' });
  const [testOut, setTestOut] = useState<any | null>(null);

  const load = async () => {
    try {
      const r: any = await api.listRules();
      setRules(r?.rules || []);
      const d: any = await api.ruleDatasets();
      setDatasets(d?.datasets || {});
    } catch { toast.error('Failed to load rules'); }
  };
  useEffect(() => { load(); }, []);

  const create = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const num = Number(form.value);
      await api.createRule({
        key: form.key, name: form.name || form.key, dataset: form.dataset,
        groups: [[{ field: form.field, op: form.op, value: Number.isNaN(num) ? form.value : num }]],
        actions: { type: form.action, severity: 'warning', roleQueue: 'receptionist', priority: 'P1' },
      });
      toast.success('Rule created');
      setForm({ ...form, key: '', name: '' });
      load();
    } catch (err: any) { toast.error(err?.message || 'Create failed'); }
  };

  const test = async (id: string) => {
    try {
      const r: any = await api.testRule(id);
      setTestOut(r);
    } catch (e: any) { toast.error(e?.message || 'Test failed'); }
  };

  const toggle = async (r: any) => {
    try {
      await api.patchRule(r._id, { enabled: !r.enabled });
      load();
    } catch { toast.error('Toggle failed'); }
  };

  const seed = async () => {
    try {
      const r: any = await api.seedClinicalRules();
      toast.success(`Seeded: ${(r?.created || []).join(', ') || 'already present'}`);
      load();
    } catch (e: any) { toast.error(e?.message || 'Seed failed'); }
  };

  return (
    <div className="grid gap-4 p-4 lg:grid-cols-[1fr_340px]">
      <Card>
        <CardHeader><CardTitle className="text-sm">Rules ({rules.length})</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          <Button size="sm" variant="outline" onClick={seed}>Seed clinical rules (lab-critical + triggers)</Button>
          {rules.map((r) => (
            <div key={r._id} className="flex items-center justify-between rounded-md border p-2.5 text-sm">
              <div>
                <p className="font-semibold">{r.name} <span className="font-mono text-xs text-muted-foreground">{r.key}</span></p>
                <p className="text-xs text-muted-foreground">{r.dataset} · cooldown {r.cooldownMinutes}m · <StatusPill status={r.enabled ? 'active' : 'disabled'} /></p>
              </div>
              <div className="flex gap-1">
                <Button size="sm" variant="outline" onClick={() => test(r._id)}><FlaskConical size={14} /> Test</Button>
                <Button size="sm" variant="outline" onClick={() => toggle(r)}>{r.enabled ? 'Disable' : 'Enable'}</Button>
              </div>
            </div>
          ))}
          {rules.length === 0 ? <EmptyState title="No rules" hint="Create your first rule — e.g. unpaid bills over ₹10,000 raise an alert." /> : null}
          {testOut ? (
            <div className="rounded-md border bg-muted/40 p-2 text-xs">
              Scanned {testOut.scanned}, matched {testOut.matched}.
              <pre className="mt-1 max-h-40 overflow-auto">{JSON.stringify(testOut.sample, null, 1)}</pre>
            </div>
          ) : null}
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle className="flex items-center gap-1 text-sm"><Play size={14} /> New rule</CardTitle></CardHeader>
        <CardContent>
          <form onSubmit={create} className="space-y-2">
            <Input placeholder="key (e.g. ar-over-10k)" value={form.key} onChange={(e) => setForm({ ...form, key: e.target.value })} required />
            <Input placeholder="name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
            <select className="w-full rounded-md border px-2 py-2 text-sm" value={form.dataset} onChange={(e) => setForm({ ...form, dataset: e.target.value, field: datasets[e.target.value]?.fields?.[0] || '' })}>
              {Object.entries(datasets).map(([k, v]: any) => <option key={k} value={k}>{v.label}</option>)}
            </select>
            <div className="flex gap-1">
              <Input placeholder="field" value={form.field} onChange={(e) => setForm({ ...form, field: e.target.value })} />
              <select className="rounded-md border px-2 text-sm" value={form.op} onChange={(e) => setForm({ ...form, op: e.target.value })}>
                {OPS.map((o) => <option key={o}>{o}</option>)}
              </select>
              <Input placeholder="value" value={form.value} onChange={(e) => setForm({ ...form, value: e.target.value })} />
            </div>
            <select className="w-full rounded-md border px-2 py-2 text-sm" value={form.action} onChange={(e) => setForm({ ...form, action: e.target.value })}>
              <option value="alert">alert</option>
              <option value="task">task</option>
              <option value="webhook-log">webhook-log</option>
            </select>
            <Button size="sm" type="submit">Create rule</Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { ShieldAlert, FileWarning, Siren, Pill, Trash2, BadgeCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';

/**
 * File 22 P0-5: safety & compliance desk — visitor passes, MLC cases,
 * incidents (+RCA), ADR reports, BMW logs, credentials (+expiry watch).
 */
const TABS = [
  { key: 'visitor-passes', label: 'Visitors', icon: BadgeCheck, coll: 'visitorpasses' },
  { key: 'mlc', label: 'MLC', icon: FileWarning, coll: 'mlccases' },
  { key: 'incidents', label: 'Incidents', icon: Siren, coll: 'incidents' },
  { key: 'adr', label: 'ADR', icon: Pill, coll: 'adrreports' },
  { key: 'bmw', label: 'BMW', icon: Trash2, coll: 'bmwlogs' },
  { key: 'credentials', label: 'Credentials', icon: ShieldAlert, coll: 'credentials' },
] as const;

export default function SafetyDesk() {
  const [tab, setTab] = useState<(typeof TABS)[number]['key']>('incidents');
  const [rows, setRows] = useState<any[]>([]);
  const [expiring, setExpiring] = useState<any[]>([]);
  const [form, setForm] = useState('');

  const coll = TABS.find((t) => t.key === tab)!.coll;

  const load = async () => {
    try {
      const r: any = await (api as any).get('/safety/' + tab);
      setRows(r?.[coll] || []);
      if (tab === 'credentials') {
        const e: any = await (api as any).get('/safety/credentials/expiring?days=60');
        setExpiring(e?.expiring || []);
      }
    } catch { toast.error('Failed to load ' + tab); }
  };
  useEffect(() => { load(); setForm(''); }, [tab]);

  const create = async (e: React.FormEvent) => {
    e.preventDefault();
    let body: any = {};
    try { body = JSON.parse(form || '{}'); }
    catch { toast.error('Body must be JSON'); return; }
    try {
      await (api as any).post('/safety/' + tab, body);
      toast.success('Recorded');
      setForm('');
      load();
    } catch (err: any) { toast.error(err?.response?.data?.message || err?.message || 'Save failed'); }
  };

  const close = async (id: string) => {
    try {
      await (api as any).patch('/safety/' + tab + '/' + id, { status: 'Closed', closedAt: new Date().toISOString() });
      toast.success('Closed');
      load();
    } catch { toast.error('Close failed'); }
  };

  const titleOf = (r: any) => r.visitorName || r.mlcNo || `${r.type || ''} · ${r.severity || ''}`.trim() || r.drug || r.date || `${r.type || ''} ${r.number || ''}`.trim() || r._id;

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><ShieldAlert size={18} /> Safety & compliance desk</h1>
      <div className="flex flex-wrap gap-1">
        {TABS.map(({ key, label, icon: Icon }) => (
          <Button key={key} size="sm" variant={tab === key ? 'default' : 'outline'} onClick={() => setTab(key)}>
            <Icon size={14} /> {label}
          </Button>
        ))}
      </div>
      {tab === 'credentials' && expiring.length > 0 ? (
        <Card className="border-amber-300">
          <CardHeader><CardTitle className="text-sm text-amber-800">Expiring within 60 days ({expiring.length})</CardTitle></CardHeader>
          <CardContent className="flex flex-wrap gap-1">
            {expiring.map((c) => (
              <span key={c._id} className="rounded border border-amber-300 bg-amber-50 px-2 py-1 text-xs">
                {c.type} · {c.number} · till {String(c.validTill).slice(0, 10)}
              </span>
            ))}
          </CardContent>
        </Card>
      ) : null}
      <div className="grid gap-3 lg:grid-cols-[1fr_340px]">
        <Card>
          <CardHeader><CardTitle className="text-sm">{tab} ({rows.length})</CardTitle></CardHeader>
          <CardContent className="max-h-[520px] space-y-1.5 overflow-auto">
            {rows.map((r) => (
              <div key={r._id} className="flex items-center justify-between gap-2 rounded-md border p-2 text-xs">
                <span className="truncate"><b>{titleOf(r)}</b> <span className="text-muted-foreground">{r.description || r.history || r.reaction || r.manifestNo || ''}</span></span>
                <span className="flex shrink-0 items-center gap-1">
                  {r.status ? <StatusPill status={r.status} /> : null}
                  {r.status && r.status !== 'Closed' ? <Button size="sm" variant="outline" onClick={() => close(r._id)}>Close</Button> : null}
                </span>
              </div>
            ))}
            {rows.length === 0 ? <EmptyState title="No records" hint="File the first record with the JSON form on the right." /> : null}
          </CardContent>
        </Card>
        <Card>
          <CardHeader><CardTitle className="text-sm">New {tab} (JSON)</CardTitle></CardHeader>
          <CardContent>
            <form onSubmit={create} className="space-y-2">
              <textarea
                className="h-44 w-full rounded-md border p-2 font-mono text-xs"
                placeholder='{"visitorName":"…","phone":"…"}'
                value={form}
                onChange={(e) => setForm(e.target.value)}
              />
              <Button size="sm" type="submit">Save record</Button>
              <p className="text-[11px] text-muted-foreground">
                Keys: visitors — visitorName/phone/relation/admissionId · MLC — mlcNo/patientId/injuryType/history ·
                incidents — type/severity/location/description · ADR — patientId/drug/reaction/severity ·
                BMW — date/wardId/yellowKg/redKg/whiteKg/blueKg/manifestNo · credentials — staffId/type/number/validTill.
              </p>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import {
  ShieldCheck,
  FileCheck2,
  QrCode,
  CheckCircle,
  XCircle,
  Clock,
  AlertTriangle,
  RefreshCw,
  Plus,
  Compass,
} from 'lucide-react';

interface GatePassItem {
  _id: string;
  passNo: string;
  type: string;
  description: string;
  itemCount: number;
  vehicleNo?: string;
  carrierName?: string;
  destination?: string;
  status: 'requested' | 'approved' | 'rejected' | 'used' | 'expired';
  validUntil?: string;
  createdAt: string;
}

interface SecurityRoundItem {
  _id: string;
  roundNo: string;
  status: 'open' | 'closed';
  startedAt: string;
  endedAt?: string;
  incident?: string;
  checkpoints: Array<{ name: string; ok: boolean; note?: string; at?: string }>;
}

export default function SecurityDeskPage() {
  const [passes, setPasses] = useState<GatePassItem[]>([]);
  const [rounds, setRounds] = useState<SecurityRoundItem[]>([]);
  const [loading, setLoading] = useState(false);

  // Dialogs
  const [isNewPassOpen, setIsNewPassOpen] = useState(false);
  const [isNewRoundOpen, setIsNewRoundOpen] = useState(false);
  const [decidePass, setDecidePass] = useState<{ pass: GatePassItem; action: 'approve' | 'reject' } | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');

  // Pass Form
  const [passForm, setPassForm] = useState({
    type: 'returnable',
    description: 'Medical monitor sent for calibration',
    itemCount: 1,
    vehicleNo: 'MH-12-AB-1234',
    carrierName: 'Ramesh Logistics',
    destination: 'MedTech Labs, Pune',
  });

  // Round Checkpoints
  const [newCheckpoints, setNewCheckpoints] = useState<string>('Main Gate, Emergency Triage, Pharmacy Store, Oxygen Plant, Server Room');

  const loadData = async () => {
    try {
      setLoading(true);
      const [passRes, roundRes]: any = await Promise.all([
        api.get('/security/gate-passes'),
        api.get('/security/rounds'),
      ]);
      setPasses(passRes.data?.passes || []);
      setRounds(roundRes.data?.rounds || []);
    } catch (err: any) {
      toast.error(err.message || 'Failed to load security ledger');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreatePass = async () => {
    try {
      await api.post('/security/gate-passes', {
        type: passForm.type,
        description: passForm.description,
        itemCount: Number(passForm.itemCount),
        vehicleNo: passForm.vehicleNo,
        carrierName: passForm.carrierName,
        destination: passForm.destination,
      });
      toast.success('Gate pass requested successfully');
      setIsNewPassOpen(false);
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to request gate pass');
    }
  };

  const handleDecidePass = async () => {
    if (!decidePass) return;
    try {
      await api.put(`/security/gate-passes/${decidePass.pass._id}/decide`, {
        action: decidePass.action,
        reason: rejectionReason,
      });
      toast.success(`Gate pass ${decidePass.action}d`);
      setDecidePass(null);
      setRejectionReason('');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update pass');
    }
  };

  const handleMarkUsed = async (id: string) => {
    try {
      await api.put(`/security/gate-passes/${id}/use`);
      toast.success('Pass verified and marked USED at gate');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to mark pass as used');
    }
  };

  const handleStartRound = async () => {
    const names = newCheckpoints
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
    if (names.length === 0) {
      toast.error('Add at least one checkpoint');
      return;
    }
    try {
      await api.post('/security/rounds', {
        checkpoints: names.map((name) => ({ name })),
      });
      toast.success('Guard security round started');
      setIsNewRoundOpen(false);
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to start round');
    }
  };

  const handleToggleCheckpoint = async (roundId: string, index: number, currentOk: boolean) => {
    try {
      await api.put(`/security/rounds/${roundId}/checkpoints/${index}`, {
        ok: !currentOk,
        note: !currentOk ? 'Verified secure & operational' : 'Requires re-inspection',
      });
      toast.success('Checkpoint recorded');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update checkpoint');
    }
  };

  const handleCloseRound = async (roundId: string) => {
    try {
      await api.put(`/security/rounds/${roundId}/close`, {
        incident: 'Round completed normally with all perimeter checkpoints logged.',
      });
      toast.success('Security patrol round closed');
      loadData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to close round');
    }
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2">
            <ShieldCheck className="w-8 h-8 text-primary" />
            Security Desk & Gate Control
          </h1>
          <p className="text-muted-foreground">
            Material gate passes, perimeter patrol rounds, and guard checkpoint auditing.
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={loadData} disabled={loading}>
            <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
