import { useState } from 'react';
import { Activity } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import PatientBanner from '@/components/clinical/PatientBanner';

/** File 22 P1-13: OPD vitals station — find patient, record vitals for them. */
export default function VitalsStation() {
  const [q, setQ] = useState('');
  const [rows, setRows] = useState<any[]>([]);
  const [sel, setSel] = useState<any | null>(null);
  const [v, setV] = useState({ systolic: '', diastolic: '', pulse: '', tempValue: '', spo2: '', sugarValue: '' });

  const search = async () => {
    try {
      const r: any = await (api as any).getPatients({ search: q, limit: 10 });
      setRows(r?.data || r?.patients || []);
    } catch { setRows([]); }
  };

  const save = async (vitalType: string, values: any) => {
    if (!sel) return;
    try {
      // Patient rows carry userId when linked; else fall back to record id.
      const r: any = await (api as any).post('/vitals/station', {
        patientUserId: sel.userId || sel._id, vitalType, values,
      });
      toast.success(`Recorded (${r?.flag || 'normal'})`);
    } catch (e: any) { toast.error(e?.response?.data?.message || 'Save failed'); }
  };

  const num = (s: string) => (s === '' ? undefined : Number(s));

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Activity size={18} /> Vitals station</h1>
      <Card>
        <CardHeader><CardTitle className="text-sm">Find patient</CardTitle></CardHeader>
        <CardContent className="space-y-2">
          <div className="flex gap-2">
            <Input placeholder="UHID / phone / name" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && search()} />
            <Button onClick={search}>Search</Button>
          </div>
          {rows.map((p: any) => (
            <button key={p._id} onClick={() => setSel(p)}
              className={`w-full rounded border px-2 py-1.5 text-left text-sm ${sel?._id === p._id ? 'border-primary' : ''}`}>
              <b>{p.name}</b> <span className="text-muted-foreground">· {p.uhid || p.phone}</span>
            </button>
          ))}
          {sel ? <PatientBanner patientId={sel._id} /> : null}
        </CardContent>
      </Card>
      {sel ? (
        <div className="grid gap-3 md:grid-cols-2">
          <Card><CardHeader><CardTitle className="text-sm">BP + Pulse</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              <div className="flex gap-2">
                <Input placeholder="Sys" value={v.systolic} onChange={(e) => setV({ ...v, systolic: e.target.value })} />
                <Input placeholder="Dia" value={v.diastolic} onChange={(e) => setV({ ...v, diastolic: e.target.value })} />
                <Input placeholder="Pulse" value={v.pulse} onChange={(e) => setV({ ...v, pulse: e.target.value })} />
              </div>
              <Button size="sm" onClick={() => save('bp', { systolic: num(v.systolic), diastolic: num(v.diastolic) })}>Save BP</Button>
              <Button size="sm" variant="outline" onClick={() => save('pulse', { pulse: num(v.pulse) })}>Save pulse</Button>
            </CardContent></Card>
          <Card><CardHeader><CardTitle className="text-sm">Temp + SpO2 + Sugar</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              <div className="flex gap-2">
                <Input placeholder="Temp F" value={v.tempValue} onChange={(e) => setV({ ...v, tempValue: e.target.value })} />
                <Input placeholder="SpO2 %" value={v.spo2} onChange={(e) => setV({ ...v, spo2: e.target.value })} />
                <Input placeholder="Sugar" value={v.sugarValue} onChange={(e) => setV({ ...v, sugarValue: e.target.value })} />
              </div>
              <div className="flex gap-2">
                <Button size="sm" onClick={() => save('temperature', { tempValue: num(v.tempValue), tempUnit: 'F' })}>Save temp</Button>
                <Button size="sm" variant="outline" onClick={() => save('spo2', { spo2: num(v.spo2) })}>Save SpO2</Button>
                <Button size="sm" variant="outline" onClick={() => save('blood_sugar', { sugarValue: num(v.sugarValue), sugarContext: 'random' })}>Save sugar</Button>
              </div>
            </CardContent></Card>
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { RefreshCw, Plus, Trash2, Webhook } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from 'sonner';
import { api } from '@/lib/api';

/**
 * File 22 P1-26: webhook delivery log + subscription management.
 * Every outbound delivery shows status/attempts/last error with a manual
 * retry (scheduler also retries on backoff, this is the operator shortcut).
 */
export default function WebhookStudio() {
  const [subs, setSubs] = useState<any[]>([]);
  const [deliveries, setDeliveries] = useState<any[]>([]);
  const [status, setStatus] = useState('');
  const [form, setForm] = useState({ url: '', events: '' });
  const [lastSecret, setLastSecret] = useState('');
  const [busy, setBusy] = useState(false);

  const load = async () => {
    try {
      const [s, d]: any[] = await Promise.all([
        api.webhookSubs({}),
        api.webhookDeliveries(status ? { status } : {}),
      ]);
      setSubs(s?.subs || []);
      setDeliveries(d?.deliveries || []);
    } catch { toast.error('Failed to load webhooks'); }
  };
  useEffect(() => { load(); }, [status]);

  const addSub = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!/^https?:\/\//.test(form.url)) { toast.error('Valid http(s) URL required'); return; }
    setBusy(true);
    try {
      const r: any = await api.createWebhookSub({
        url: form.url,
        events: form.events.split(',').map((x) => x.trim()).filter(Boolean),
      });
      setLastSecret(r?.secret || '');
      setForm({ url: '', events: '' });
      toast.success('Subscription created — copy the secret now (shown once)');
      load();
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Create failed'); }
    setBusy(false);
  };

  const removeSub = async (id: string) => {
    if (!window.confirm('Delete this webhook subscription?')) return;
    try { await api.deleteWebhookSub(id); load(); } catch { toast.error('Delete failed'); }
  };

  const retry = async (id: string) => {
    try {
      await api.retryWebhookDelivery(id);
      toast.success('Retry queued');
      load();
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Retry failed'); }
  };

  const statusColor = (s: string) => (s === 'delivered' ? 'text-green-700'
    : s === 'failed' ? 'text-red-700' : 'text-amber-600');

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-2xl font-heading font-bold">Webhook Studio</h1>
        <p className="text-sm text-muted-foreground">Signed deliveries (HMAC + timestamp), retry log, subscription secrets.</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Plus className="w-4 h-4" />Add subscription
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <form onSubmit={addSub} className="flex flex-wrap gap-2">
            <Input className="w-72" placeholder="https://example.com/hooks/findmedi"
              value={form.url} onChange={(e) => setForm({ ...form, url: e.target.value })} />
            <Input className="w-64" placeholder="events (comma, e.g. claim.updated)"
              value={form.events} onChange={(e) => setForm({ ...form, events: e.target.value })} />
            <Button type="submit" disabled={busy}>Add</Button>
          </form>
          {lastSecret ? (
            <p className="text-xs rounded-lg border border-amber-300 bg-amber-50 dark:bg-amber-950 p-2 font-mono break-all">
              Signing secret (copy now, never shown again): {lastSecret}
            </p>
          ) : null}
          <div className="space-y-2">
            {subs.map((s) => (
              <div key={s._id} className="flex items-center justify-between gap-2 rounded-lg border border-border/50 p-2 text-sm">
                <span className="font-mono text-xs break-all">{s.url}</span>
                <span className="flex items-center gap-2 shrink-0">
                  <span className="text-xs text-muted-foreground">{(s.events || []).join(', ') || 'all events'}</span>
                  <span className={`text-xs ${s.active ? 'text-green-700' : 'text-muted-foreground'}`}>
                    {s.active ? 'active' : 'paused'}
                  </span>
                  <Button size="sm" variant="ghost" onClick={() => removeSub(s._id)}><Trash2 className="w-3.5 h-3.5" /></Button>
                </span>
              </div>
            ))}
            {subs.length === 0 ? <p className="text-sm text-muted-foreground">No subscriptions yet.</p> : null}
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center justify-between">
            <span className="flex items-center gap-2"><Webhook className="w-4 h-4" />Delivery log ({deliveries.length})</span>
            <span className="flex items-center gap-2">
              <select value={status} onChange={(e) => setStatus(e.target.value)}
                className="h-8 rounded-md border border-border/60 bg-background px-2 text-xs">
                <option value="">All statuses</option>
                <option value="pending">pending</option>
                <option value="delivered">delivered</option>
                <option value="failed">failed</option>
              </select>
              <Button size="sm" variant="outline" onClick={load}><RefreshCw className="w-3.5 h-3.5" />Refresh</Button>
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-2">
          {deliveries.map((d) => (
            <div key={d._id} className="rounded-lg border border-border/50 p-2.5 text-sm">
              <div className="flex items-center justify-between gap-2">
                <span className="font-medium">{d.event}</span>
                <span className="flex items-center gap-2">
                  <span className={`text-xs font-semibold ${statusColor(d.status)}`}>{d.status}</span>
                  <span className="text-xs text-muted-foreground">{d.attempts || 0} attempt(s)</span>
                  {d.status !== 'delivered' ? (
                    <Button size="sm" variant="outline" onClick={() => retry(d._id)}>Retry</Button>
                  ) : null}
                </span>
              </div>
              <p className="text-xs text-muted-foreground">
                {d.nextRetryAt ? `next retry ${new Date(d.nextRetryAt).toLocaleString()}` : ''}
                {d.nextRetryAt ? ' · ' : ''}
                {new Date(d.createdAt).toLocaleString()}
              </p>
              {d.lastError ? <p className="text-xs text-red-600 mt-1">{String(d.lastError).slice(0, 200)}</p> : null}
            </div>
          ))}
          {deliveries.length === 0 ? <p className="text-sm text-muted-foreground">No deliveries yet.</p> : null}
        </CardContent>
      </Card>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  ReactFlow, Background, Controls, MiniMap, addEdge, useNodesState, useEdgesState,
  type Node, type Edge, type Connection,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { Play, Plus, CheckCircle, AlertTriangle, Inbox } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { SlaRing } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';

/**
 * File 13 §13.1: visual workflow designer (xyflow) + instance viewer + inbox.
 * Graph edits save as a NEW version (never mutate published); publish
 * validates (single start, no orphans, all paths reach end).
 */
let seq = 0;
const nid = () => `s${Date.now() % 100000}_${seq++}`;

export default function WorkflowStudio() {
  const [defs, setDefs] = useState<any[]>([]);
  const [sel, setSel] = useState<any | null>(null);
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const [meta, setMeta] = useState({ key: 'discharge', name: '', entityModel: 'Admission' });
  const [inbox, setInbox] = useState<any[]>([]);
  const [instance, setInstance] = useState<any | null>(null);
  const [eventName, setEventName] = useState('');

  const load = async () => {
    try {
      const r: any = await api.wfDefinitions();
      setDefs(r?.definitions || []);
      const ib: any = await api.wfInbox();
      setInbox(ib?.inbox || []);
    } catch { toast.error('Failed to load workflows'); }
  };
  useEffect(() => { load(); }, []);

  const openDef = (d: any) => {
    setSel(d);
    setMeta({ key: d.key, name: d.name, entityModel: d.entityModel || '' });
    setNodes((d.states || []).map((s: any, i: number) => ({
      id: s.id, position: { x: 80 + (i % 4) * 180, y: 80 + Math.floor(i / 4) * 140 },
      data: { label: `${s.id}${s.label ? ` — ${s.label}` : ''} [${s.type}]${s.slaMinutes ? ` ⏱${s.slaMinutes}m` : ''}` },
      style: {
        border: '2px solid', borderColor: s.type === 'start' ? 'hsl(var(--status-ok))' : s.type === 'end' ? 'hsl(var(--status-bad))' : 'hsl(var(--border))',
        borderRadius: 8, padding: 10, background: 'hsl(var(--card))', fontSize: 12,
      },
    })));
    setEdges((d.transitions || []).map((t: any, i: number) => ({
      id: t.id || `e${i}`, source: t.from, target: t.to, label: t.event, animated: true,
    })));
  };

  const onConnect = useCallback((c: Connection) => {
    const event = window.prompt('Event name for this transition:', 'approve');
    if (!event) return;
    setEdges((eds) => addEdge({ ...c, label: event, animated: true }, eds));
  }, [setEdges]);

  const addState = (type: string) => {
    const id = window.prompt('State id:', nid());
    if (!id) return;
    const sla = type === 'task' ? Number(window.prompt('SLA minutes (0 = none):', '60') || 0) : 0;
    setNodes((ns) => [...ns, {
      id, position: { x: 120 + ns.length * 40, y: 320 },
      data: { label: `${id} [${type}]${sla ? ` ⏱${sla}m` : ''}` },
      style: { border: '2px solid hsl(var(--border))', borderRadius: 8, padding: 10, background: 'hsl(var(--card))', fontSize: 12 },
      slaMinutes: sla, nodeType: type,
    }]);
  };

  const graph = useMemo(() => {
    const parse = (label: string) => {
      const m = String(label).match(/^(.*?)\s*\[(start|task|parallel|join|end)\]/);
      return { id: m ? m[1].trim().split(' — ')[0] : label, type: (m ? m[2] : 'task') as string };
    };
    const states = nodes.map((n: any) => {
      const p = parse(String(n.data?.label));
      const slaM = String(n.data?.label).match(/⏱(\d+)m/);
      return { id: n.id, label: p.id === String(n.data?.label) ? '' : p.id, type: p.type, slaMinutes: slaM ? Number(slaM[1]) : (n.slaMinutes || 0) };
    });
    const transitions = edges.map((e, i) => ({ id: e.id || `e${i}`, from: e.source, to: e.target, event: String(e.label || 'go') }));
    return { states, transitions };
  }, [nodes, edges]);

  const saveNew = async () => {
    try {
      const r: any = await api.wfCreateDefinition({ ...meta, ...graph });
      toast.success(`Saved as version ${r?.version}`);
      load();
    } catch (e: any) { toast.error(e?.message || 'Save failed (validation errors?)'); }
  };

  const publish = async () => {
    if (!sel) return;
    try {
      await api.wfPublish(sel._id || sel.id);
      toast.success('Published');
      load();
    } catch (e: any) { toast.error(e?.message || 'Publish failed'); }
  };

  const startInstance = async () => {
    try {
      const r: any = await api.wfStartInstance({ defKey: meta.key, entityRef: {} });
      toast.success('Instance started');
      viewInstance(r?.id);
    } catch (e: any) { toast.error(e?.message || 'Start failed'); }
  };

  const viewInstance = async (id: string) => {
    try {
      const r: any = await api.wfInstance(id);
      setInstance(r);
    } catch { toast.error('Instance not found'); }
  };

  const fire = async () => {
    if (!instance?.instance?._id || !eventName) return;
    try {
      await api.wfFireEvent(instance.instance._id, { event: eventName, version: instance.instance.version });
      toast.success('Event fired');
      setEventName('');
      viewInstance(instance.instance._id);
    } catch (e: any) { toast.error(e?.message || 'Transition rejected'); }
  };

  return (
    <div className="grid gap-4 p-4 lg:grid-cols-[280px_1fr]">
      <div className="space-y-3">
        <Card><CardHeader><CardTitle className="text-sm">Definitions</CardTitle></CardHeader>
          <CardContent className="space-y-1">
            {defs.map((d) => (
              <button key={d._id + d.version} onClick={() => openDef(d)}
                className={`w-full rounded-md border px-2 py-1.5 text-left text-xs hover:bg-muted ${sel?._id === d._id ? 'border-primary' : ''}`}>
                <span className="font-semibold">{d.key}</span> <span className="text-muted-foreground">v{d.version} · {d.status}</span>
              </button>
            ))}
            {defs.length === 0 ? <EmptyState title="No workflows yet" /> : null}
          </CardContent></Card>
        <Card><CardHeader><CardTitle className="flex items-center gap-1 text-sm"><Inbox size={14} /> SLA inbox</CardTitle></CardHeader>
          <CardContent className="space-y-1">
            {inbox.map((i) => (
              <button key={i._id} onClick={() => viewInstance(i._id)} className="w-full rounded-md border px-2 py-1.5 text-left text-xs hover:bg-muted">
                <span className="font-semibold">{i.defKey}</span> · {i.state}
              </button>
            ))}
            {inbox.length === 0 ? <p className="text-xs text-muted-foreground">No overdue instances.</p> : null}
          </CardContent></Card>
      </div>

      <div className="space-y-3">
        <Card>
          <CardHeader><CardTitle className="text-sm">Designer {sel ? `— ${sel.key} v${sel.version} (${sel.status})` : '(pick or create)'}</CardTitle></CardHeader>
          <CardContent className="space-y-2">
            <div className="flex flex-wrap gap-2">
              <Input className="w-40" placeholder="key" value={meta.key} onChange={(e) => setMeta({ ...meta, key: e.target.value })} />
              <Input className="w-56" placeholder="name" value={meta.name} onChange={(e) => setMeta({ ...meta, name: e.target.value })} />
              <Button size="sm" variant="outline" onClick={() => addState('task')}><Plus size={14} /> task</Button>
              <Button size="sm" variant="outline" onClick={() => addState('start')}>start</Button>
              <Button size="sm" variant="outline" onClick={() => addState('end')}>end</Button>
              <Button size="sm" variant="outline" onClick={() => addState('parallel')}>parallel</Button>
              <Button size="sm" variant="outline" onClick={() => addState('join')}>join</Button>
              <Button size="sm" onClick={saveNew}><CheckCircle size={14} /> Save new version</Button>
              {sel?.status === 'Draft' ? <Button size="sm" variant="secondary" onClick={publish}>Publish</Button> : null}
              <Button size="sm" variant="secondary" onClick={startInstance}><Play size={14} /> Start instance</Button>
            </div>
            <div className="h-[380px] rounded-md border">
              <ReactFlow nodes={nodes} edges={edges} onNodesChange={onNodesChange} onEdgesChange={onEdgesChange} onConnect={onConnect} fitView>
                <Background /><Controls /><MiniMap />
              </ReactFlow>
            </div>
            <p className="text-xs text-muted-foreground">Drag between nodes to add a transition (you'll be asked for the event name). Click a node + Del to remove.</p>
          </CardContent>
        </Card>

        {instance ? (
          <Card>
            <CardHeader><CardTitle className="text-sm">Instance {instance.instance?._id} — {instance.instance?.state} ({instance.instance?.status})</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              <div className="flex flex-wrap gap-1">
                {(instance.definition?.transitions || []).filter((t: any) => (instance.instance?.activeStates || [instance.instance?.state]).includes(t.from))
                  .map((t: any) => (
                    <Button key={t.id || t.event} size="sm" variant="outline" onClick={() => { setEventName(t.event); }}>
                      {t.event} →
                    </Button>
                  ))}
              </div>
              <div className="flex gap-2">
                <Input className="w-48" placeholder="event" value={eventName} onChange={(e) => setEventName(e.target.value)} />
                <Button size="sm" onClick={fire}>Fire</Button>
              </div>
              {(instance.instance?.timers || []).map((t: any, i: number) => (
                <div key={i}><SlaRing dueAt={t.dueAt} label={`state ${t.state}`} /></div>
              ))}
              <div className="max-h-40 space-y-1 overflow-y-auto text-xs">
                {(instance.instance?.history || []).slice().reverse().map((h: any, i: number) => (
                  <p key={i} className="rounded border px-2 py-1">{h.from} —[{h.event}]→ {h.to} <span className="text-muted-foreground">{h.note}</span></p>
                ))}
              </div>
            </CardContent>
          </Card>
        ) : null}
        {sel && !instance ? (
          <p className="flex items-center gap-1 text-xs text-amber-700"><AlertTriangle size={13} /> Published versions are immutable — edits always save as a new version.</p>
        ) : null}
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState, type FormEvent } from 'react';
import {
  CheckCircle2,
  Circle,
  Loader2,
  ListChecks,
  Users,
  UserPlus,
  Mail,
  Clock,
  ShieldCheck,
  X,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { api } from '@/lib/api';
import { toast } from 'sonner';

/**
 * 2.md 7 + 2.md 9 — the applicant-facing side of "approved but not yet live".
 *
 * Two sections, both read-only unless the viewer owns the listing:
 *   1. The six-item ACTIVATION CHECKLIST (GET /join/:id/activation) — what is
 *      still between this application and a fully-live listing.
 *   2. The TEAM panel (GET /provider-staff) — invite the owner's own staff to
 *      the console. Only rendered once the application has materialised a
 *      listing (providerId), because invites are provider-scoped.
 *
 * Everything here degrades to a quiet error line: a failed checklist read must
 * never break the status list it is embedded in.
 */

interface ActivationItem {
  key: string;
  label: string;
  done: boolean;
  hint?: string;
}

interface ChecklistDto {
  items: ActivationItem[];
  doneCount: number;
  total: number;
  ratio: number;
  complete: boolean;
  approved: boolean;
  checkedAt?: string;
}

interface StaffRow {
  userId: string;
  name: string;
  email: string;
  role: string;
  addedAt?: string;
  twoFactorEnabled?: boolean;
}

interface InviteRow {
  _id: string;
  email: string;
  template: string;
  role: string;
  expiresAt?: string;
  twoFactorRequired?: boolean;
}

interface TemplateRow {
  key: string;
  role: string;
  label: string;
  description?: string;
  twoFactorRequired?: boolean;
}

interface StaffDto {
  provider: { _id: string; name: string; status: string };
  staff: StaffRow[];
  invites: InviteRow[];
  templates: TemplateRow[];
}

export default function ActivationPanel({
  applicationId,
  providerId,
}: {
  applicationId: string;
  providerId?: string | null;
}) {
  const [checklist, setChecklist] = useState<ChecklistDto | null>(null);
  const [checkError, setCheckError] = useState('');
  const [staff, setStaff] = useState<StaffDto | null>(null);
  const [staffError, setStaffError] = useState('');

  const [template, setTemplate] = useState('');
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [sending, setSending] = useState(false);
  const [revoking, setRevoking] = useState('');

  const loadStaff = useCallback(async () => {
    if (!providerId) return;
    try {
      const data = (await api.get(`/provider-staff?providerId=${encodeURIComponent(providerId)}`)) as unknown as StaffDto;
      setStaff(data);
      setStaffError('');
      if (!template && data.templates?.length) setTemplate(data.templates[0].key);
    } catch {
      setStaffError('Could not load the team panel.');
    }
  }, [providerId, template]);

  useEffect(() => {
    let live = true;
    (async () => {
      try {
        const data = (await api.get(`/join/${applicationId}/activation`)) as unknown as ChecklistDto;
        if (live) setChecklist(data);
      } catch {
        if (live) setCheckError('Could not load the activation checklist.');
      }
    })();
    return () => { live = false; };
  }, [applicationId]);

  useEffect(() => {
    if (providerId) loadStaff();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [providerId]);

  const invite = async (e: FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;
    setSending(true);
    try {
      await api.post('/provider-staff/invite', {
        template,
        email: email.trim(),
        ...(name.trim() ? { name: name.trim() } : {}),
        ...(providerId ? { providerId } : {}),
      });
      toast.success('Invitation sent — the single-use link is in their inbox.');
      setEmail('');
      setName('');
      await loadStaff();
    } catch (err: any) {
      toast.error(err instanceof Error ? err.message : 'Could not send the invitation');
    } finally {
      setSending(false);
    }
  };

  const revoke = async (inviteId: string) => {
    setRevoking(inviteId);
    try {
      await api.del(`/provider-staff/invites/${inviteId}${providerId ? `?providerId=${encodeURIComponent(providerId)}` : ''}`);
      toast.success('Invitation revoked');
      await loadStaff();
    } catch (err: any) {
      toast.error(err instanceof Error ? err.message : 'Could not revoke the invitation');
    } finally {
      setRevoking('');
    }
  };

  return (
    <div className="mt-4 grid gap-4 lg:grid-cols-2">
      {/* ── 2.md 7: activation checklist ─────────────────────────────── */}
      <div className="rounded-xl border bg-muted/30 p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ListChecks className="w-4 h-4 text-primary" />
            <h3 className="text-sm font-semibold">Go-live checklist</h3>
          </div>
          {checklist && (
            <span className="text-xs font-mono px-2 py-0.5 rounded-full bg-primary/10 text-primary">
              {checklist.doneCount}/{checklist.total}
            </span>
          )}
        </div>

        {checkError && <p className="text-xs text-muted-foreground">{checkError}</p>}
        {!checklist && !checkError && (
          <div className="py-4 flex justify-center">
            <Loader2 className="w-5 h-5 animate-spin text-primary" />
          </div>
        )}

        {checklist && (
          <>
            {checklist.complete && (
              <div className="text-xs bg-emerald-500/10 border border-emerald-500/20 text-emerald-700 dark:text-emerald-300 rounded-lg p-2.5">
                All activation items are complete — this listing is fully live.
              </div>
            )}
            <ul className="space-y-2">
              {checklist.items.map((item) => (
                <li key={item.key} className="flex items-start gap-2">
                  {item.done ? (
                    <CheckCircle2 className="w-4 h-4 mt-0.5 text-emerald-500 shrink-0" />
                  ) : (
                    <Circle className="w-4 h-4 mt-0.5 text-muted-foreground/50 shrink-0" />
                  )}
                  <div className="min-w-0">
                    <p className={`text-xs font-medium ${item.done ? 'text-foreground' : 'text-muted-foreground'}`}>
                      {item.label}
                    </p>
                    {item.hint && <p className="text-[11px] text-muted-foreground/80 truncate">{item.hint}</p>}
                  </div>
                </li>
              ))}
            </ul>
          </>
        )}
      </div>

      {/* ── 2.md 9: team + invitations (provider-scoped) ──────────────── */}
      {providerId ? (
        <div className="rounded-xl border bg-muted/30 p-4 space-y-3">
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4 text-primary" />
            <h3 className="text-sm font-semibold">Listing team</h3>
          </div>

          {staffError && <p className="text-xs text-muted-foreground">{staffError}</p>}
          {!staff && !staffError && (
            <div className="py-4 flex justify-center">
              <Loader2 className="w-5 h-5 animate-spin text-primary" />
            </div>
          )}

          {staff && (
            <>
              <ul className="space-y-1.5">
                {staff.staff.map((row) => (
                  <li key={String(row.userId)} className="flex items-center justify-between gap-2 text-xs">
                    <span className="min-w-0">
                      <span className="font-medium text-foreground">{row.name || row.email}</span>
                      <span className="text-muted-foreground"> · {row.role}</span>
                    </span>
                    {row.twoFactorEnabled && (
                      <span className="inline-flex items-center gap-1 text-[10px] text-emerald-600 shrink-0">
                        <ShieldCheck className="w-3 h-3" /> 2FA
                      </span>
                    )}
                  </li>
                ))}
                {staff.staff.length === 0 && (
                  <li className="text-xs text-muted-foreground">No staff on this listing yet — you are the only owner.</li>
                )}
              </ul>

              {staff.invites.length > 0 && (
                <div className="space-y-1.5 pt-2 border-t">
                  <p className="text-[11px] uppercase tracking-wide text-muted-foreground">Pending invitations</p>
                  {staff.invites.map((row) => (
                    <div key={row._id} className="flex items-center justify-between gap-2 text-xs">
                      <span className="min-w-0 inline-flex items-center gap-1 text-muted-foreground">
                        <Mail className="w-3 h-3 shrink-0" />
                        <span className="truncate">{row.email} · {row.template}</span>
                        {row.expiresAt && (
                          <span className="inline-flex items-center gap-0.5 text-[10px] shrink-0">
                            <Clock className="w-3 h-3" />
                            {new Date(row.expiresAt).toLocaleDateString()}
                          </span>
                        )}
                      </span>
                      <button
                        type="button"
                        onClick={() => revoke(row._id)}
                        disabled={revoking === row._id}
                        className="inline-flex items-center gap-1 text-[11px] text-destructive hover:underline disabled:opacity-50 shrink-0"
                      >
                        <X className="w-3 h-3" /> Revoke
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <form onSubmit={invite} className="pt-2 border-t space-y-2">
                <p className="text-[11px] uppercase tracking-wide text-muted-foreground inline-flex items-center gap-1">
                  <UserPlus className="w-3 h-3" /> Invite staff
                </p>
                <select
                  value={template}
                  onChange={(e) => setTemplate(e.target.value)}
                  className="w-full text-xs border rounded-md bg-background px-2 py-1.5"
                >
                  {staff.templates.map((t) => (
                    <option key={t.key} value={t.key}>
                      {t.label} → {t.role}{t.twoFactorRequired ? ' (2FA required)' : ''}
                    </option>
                  ))}
                </select>
                <Input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="colleague@clinic.in"
                  className="h-8 text-xs"
                />
                <Input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Name (optional)"
                  className="h-8 text-xs"
                />
                <Button type="submit" size="sm" className="w-full gap-1" disabled={sending}>
                  {sending ? <Loader2 className="w-3 h-3 animate-spin" /> : <UserPlus className="w-3 h-3" />}
                  Send invitation
                </Button>
                <p className="text-[10px] text-muted-foreground">
                  The single-use link expires in 48 hours and is only shown in the email.
                </p>
              </form>
            </>
          )}
        </div>
      ) : null}
    </div>
  );
}

