const LEGACY_TYPE_MAP: Record<string, string> = {
  hospital: 'hospital',
  clinic: 'clinic',
  diagnostic: 'diagnostic',
  pharmacy: 'pharmacy',
  delivery: 'delivery',
  rider: 'rider',
  assistant: 'assistant',
  lawyer: 'lawyer',
  counsellor: 'counsellor',
  psychiatrist: 'psychiatrist',
