                    className={`rounded-full px-2.5 py-1 text-[11px] font-medium transition-all ${
                      isActive
                        ? 'bg-primary text-primary-foreground shadow-sm'
                        : isPast
                        ? 'bg-muted text-foreground hover:bg-muted/80'
                        : 'text-muted-foreground opacity-60'
                    }`}
                  >
                    {isPast ? '✓ ' : `${i + 1}. `}
                    {s.label}
                  </button>
