  const [bills, setBills] = useState<ApiRow[]>([]);
  const [tests, setTests] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [showForm, setShowForm] = useState(false);
  const [patientName, setPatientName] = useState('');
  const [selectedTests, setSelectedTests] = useState<ApiRow[]>([]);
  const [discount, setDiscount] = useState(0);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    Promise.all([
      api.getLabBookings({ status: 'Completed' }).then(res => {
        const bookings = res.bookings || [];
        setBills(bookings.map((b: Unmodelled, i: Unmodelled) => ({
          _id: b._id || `bill_${i}`,
          invoiceId: b.invoiceId || `INV-TST-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}${String(new Date().getHours()).padStart(2, '0')}${String(new Date().getMinutes()).padStart(2, '0')}${crypto.randomUUID()}`,
          patient: b.patient || b.patientName || 'Unknown',
          tests: b.tests || [],
          amount: b.amount || 0,
          discount: b.discount || 0,
          total: b.total || b.amount || 0,
          date: b.date || b.createdAt?.split('T')[0] || '',
          status: b.status || 'Completed',
        })));
      }),
      api.getLabTests().then(res => setTests(res.tests || [])),
    ]).catch(console.error).finally(() => setLoading(false));
  }, []);

  const subTotal = selectedTests.reduce((s, tid) => {
    const t = tests.find(tt => tt._id === tid);
    return s + (t?.price || 0);
  }, 0);
  const total = subTotal - (subTotal * (discount || 0) / 100);

  const filtered = bills.filter(b => {
    const ms = !search || b.patient?.toLowerCase().includes(search.toLowerCase()) || b.invoiceId?.toLowerCase().includes(search.toLowerCase());
    const ms2 = statusFilter === 'All' || b.status === statusFilter;
    return ms && ms2;
  });

  const handleCreate = async () => {
    if (!patientName || selectedTests.length === 0) return;
    setSaving(true);
    try {
      const newBooking = await api.createLabBooking({
        patient: patientName,
        tests: selectedTests,
        amount: subTotal,
        discount: Number(discount),
        total: Math.round(total),
        status: 'Pending',
      });
      setBills(prev => [{
        _id: newBooking._id || `bill_${crypto.randomUUID()}`,
        invoiceId: newBooking.invoiceId || `INV-TST-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}${String(new Date().getHours()).padStart(2, '0')}${String(new Date().getMinutes()).padStart(2, '0')}${crypto.randomUUID()}`,
        patient: patientName,
        tests: selectedTests,
        amount: subTotal,
        discount: Number(discount),
        total: Math.round(total),
        date: getISTDateString(),
        status: 'Pending',
      }, ...prev]);
      setShowForm(false);
      setPatientName(''); setSelectedTests([]); setDiscount(0);
    } catch (e: any) { console.error(e); }
    setSaving(false);
  };

  const markPaid = async (id: Unmodelled) => {
    try {
      await api.updateLabBooking(id, { status: 'Paid' });
      setBills(prev => prev.map(b => b._id === id ? { ...b, status: 'Paid' } : b));
    } catch (e: any) { console.error(e); }
  };

  const totalCollected = bills.filter(b => b.status === 'Paid').reduce((s, b) => s + (b.total || b.amount), 0);
  const totalPending = bills.filter(b => b.status === 'Pending').reduce((s, b) => s + (b.total || b.amount), 0);
  const totalOverdue = bills.filter(b => b.status === 'Overdue').reduce((s, b) => s + (b.total || b.amount), 0);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Billing & Payments</h1>
          <p className="text-muted-foreground">{bills.length} invoices</p>
        </div>
        <Button className="gap-2" onClick={() => setShowForm(true)}><Plus className="w-4 h-4" /> New Invoice</Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-success/20 to-success/5 rounded-2xl border border-success/20 p-6">
          <p className="text-sm text-muted-foreground">Total Collected</p>
          <p className="font-heading text-3xl font-bold text-success">₹{totalCollected.toLocaleString()}</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-warning/20 to-warning/5 rounded-2xl border border-warning/20 p-6">
          <p className="text-sm text-muted-foreground">Pending</p>
          <p className="font-heading text-3xl font-bold text-warning">₹{totalPending.toLocaleString()}</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-gradient-to-br from-destructive/20 to-destructive/5 rounded-2xl border border-destructive/20 p-6">
          <p className="text-sm text-muted-foreground">Overdue</p>
          <p className="font-heading text-3xl font-bold text-destructive">₹{totalOverdue.toLocaleString()}</p>
        </motion.div>
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patient or invoice..." aria-label="Search invoices" className="pl-10" />
        </div>
        <div className="flex gap-2">
          {['All', 'Paid', 'Pending', 'Overdue'].map(s => (
            <button key={s} onClick={() => setStatusFilter(s)}
              className={`px-3 py-2 rounded-lg text-sm font-medium transition-all ${statusFilter === s ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>{s}</button>
          ))}
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <CreditCard className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No invoices yet</p>
        </div>
      ) : (
        <div className="bg-card rounded-2xl border border-border/60 overflow-hidden">
          {/* The search box and status chips above already narrowed this list. */}
          <DataGrid
            columns={[
              { key: 'invoiceId', label: 'Invoice', render: (v: Unmodelled) => <span className="text-sm font-mono text-primary">{v}</span> },
              { key: 'patient', label: 'Patient', render: (v: Unmodelled) => <span className="text-sm font-medium">{v}</span> },
              { key: 'tests', label: 'Tests', render: (v: Unmodelled) => <span className="text-sm text-muted-foreground">{v?.length || 0} test(s)</span> },
              { key: 'date', label: 'Date', render: (v: Unmodelled) => <span className="text-sm text-muted-foreground">{v}</span> },
              { key: 'total', label: 'Amount', render: (v: Unmodelled, b: Unmodelled) => <span className="text-sm font-semibold">₹{v || b.amount}</span> },
              { key: 'status', label: 'Status', render: (v: Unmodelled) => <Badge className={statusColors[v] || 'bg-muted'}>{v}</Badge> },
              {
                key: '_actions', label: 'Action', sortable: false,
                render: (_v: Unmodelled, b: Unmodelled) => (
                  b.status !== 'Paid' && (
                    <Button size="sm" variant="outline" onClick={() => markPaid(b._id)} className="gap-1 text-success border-success/30">
                      <CheckCircle className="w-3.5 h-3.5" /> Mark Paid
                    </Button>
                  )
                ),
              },
            ]}
            rows={filtered}
            rowKey="_id"
            empty="No invoices yet"
            showSearch={false}
            manualPagination
          />
        </div>
      )}

      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setShowForm(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-lg p-6" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">New Invoice</h3>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-1.5 block">Patient Name *</label>
                <Input value={patientName} onChange={e => setPatientName(e.target.value)} placeholder="Patient name" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Select Tests * ({selectedTests.length})</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                  {tests.map(t => (
                    <button key={t._id} onClick={() => setSelectedTests(prev => prev.includes(t._id) ? prev.filter(id => id !== t._id) : [...prev, t._id])}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors text-left flex items-center gap-2 ${selectedTests.includes(t._id) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      <span className="truncate">{t.name}</span>
                      <span className="ml-auto text-xs opacity-70">₹{t.price}</span>
                    </button>
                  ))}
                </div>
              </div>
              {selectedTests.length > 0 && (
                <div className="bg-muted/50 rounded-lg p-3 space-y-1 text-sm">
                  <div className="flex justify-between"><span>Subtotal</span><span>₹{subTotal}</span></div>
                  <div className="flex justify-between"><span>Discount ({discount}%)</span><span className="text-destructive">-₹{Math.round(subTotal * discount / 100)}</span></div>
                  <div className="flex justify-between font-bold text-foreground border-t border-border pt-1"><span>Total</span><span>₹{Math.round(total)}</span></div>
                </div>
              )}
              <div>
                <label className="text-sm font-medium mb-1.5 block">Discount %</label>
                <Input type="number" value={discount} onChange={e => setDiscount(Number(e.target.value))} min={0} max={100} />
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleCreate} disabled={!patientName || selectedTests.length === 0 || saving}>
                <Send className="w-4 h-4" /> Create Invoice
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { Switch } from '@/components/ui/switch';
import { Activity, CalendarDays, Clock, MapPin, User, AlertCircle, TrendingUp, DollarSign, Beaker, FileText, Microscope, RotateCcw, Globe, Save, Building2, Users, CheckCircle, CalendarClock, ChevronRight, UserPlus, Boxes, FileBarChart, PackageCheck, FlaskConical } from 'lucide-react';
import { useAuth } from '@/context/AuthContext';
import { Link, useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import LicenseExpiryReminder from '@/components/LicenseExpiryReminder';
import { getISTDateString } from '@/lib/dateUtils';
import type { Unmodelled } from '@/lib/apiTypes';

const statusColors: Unmodelled = {
  Pending: { bg: 'bg-warning/10', text: 'text-warning' },
  Confirmed: { bg: 'bg-success/10', text: 'text-success' },
  Completed: { bg: 'bg-primary/10', text: 'text-primary' },
  Cancelled: { bg: 'bg-destructive/10', text: 'text-destructive' },
};

export default function LabCenterDashboard() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [stats, setStats] = useState<any>(null);
  const [bookings, setBookings] = useState<any>([]);
  const [refunds, setRefunds] = useState<any>([]);
  const [tat, setTat] = useState<any>(null);
  const [rejection, setRejection] = useState<any>(null);
  const [invStats, setInvStats] = useState<any>(null);
  const [equipment, setEquipment] = useState<any>([]);
  const [qc, setQc] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [bookingTab, setBookingTab] = useState('pending');
  const [platformSettings, setPlatformSettings] = useState({
    autoConfirmBookings: true,
    patientSelfBooking: false,
    reportAutoPublish: true,
    smsNotifications: true,
    emergencyStat: false,
    acceptRefunds: true,
    homeCollectionFee: '50',
    freePickupThreshold: '500',
    statFee: '200',
    collectionRadius: '10 km',
    autoRelease: false,
    bankAccount: '',
    bankIfsc: '',
    gstin: '',
  });
  const mounted = useRef(true);

  useEffect(() => {
    try {
      const saved = localStorage.getItem('lab_platform_settings');
      if (saved) setPlatformSettings(JSON.parse(saved));
    } catch {}
  }, []);

  const handleSavePlatformSettings = () => {
    localStorage.setItem('lab_platform_settings', JSON.stringify(platformSettings));
    toast.success('Lab platform settings updated successfully');
  };

  useEffect(() => {
    mounted.current = true;
    const load = async () => {
      setLoading(true);
      try {
        const monthAgo = new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);
        const todayIso = new Date().toISOString().slice(0, 10);
        const results = await Promise.allSettled([
          api.getLabStats(),
          api.getLabBookings({}),
          api.getRefunds(),
          api.labTat(),
          api.generateReport({ reportType: 'Lab Rejection Rate', dateFrom: monthAgo, dateTo: todayIso }),
          api.getInventoryStats(),
          api.getLabEquipment({}),
          api.getLabTests(),
        ]);
        if (!mounted.current) return;
        const [s, b, rf, t, rej, inv, eq, tests] = results.map(res => res.status === 'fulfilled' ? res.value : null);
        setStats(s);
        setBookings(b?.bookings || []);
        setRefunds((rf?.payments || rf?.data || []).slice(0, 5));
        setTat(t);
        setRejection(rej);
        setInvStats(inv);
        setEquipment(eq?.equipment || []);
        const firstTest = tests?.tests?.[0]?.name;
        if (firstTest) {
          api.qcChart({ testName: firstTest })
            .then((data: any) => { if (mounted.current) setQc(data); })
            .catch(() => {});
        }
        const failed = results.filter(r => r.status === 'rejected');
        if (failed.length > 0) toast.error(`Failed to load ${failed.length} data source(s)`);
      } catch (e: any) { console.error(e); toast.error('Failed to load dashboard data'); }
      if (mounted.current) setLoading(false);
    };
    load();
    return () => { mounted.current = false; };
  }, []);

  const today = getISTDateString();
  const todayBookings = bookings.filter((b: Unmodelled) => (b.bookingDate || '').startsWith(today));
  const pendingBookings = bookings.filter((b: Unmodelled) => b.status === 'Pending');
  const upcomingBookings = bookings.filter((b: Unmodelled) => b.status === 'Confirmed' || (b.bookingDate && b.bookingDate > today && b.status !== 'Completed' && b.status !== 'Cancelled'));
  const completedBookings = bookings.filter((b: Unmodelled) => b.status === 'Completed');
  const pendingReports = stats?.pending ?? pendingBookings.length;
  const totalEarned = bookings.filter((b: Unmodelled) => b.status === 'Completed').reduce((s: Unmodelled, b: Unmodelled) => s + Number(b.amount || 0), 0);
  const completedTests = bookings.filter((b: Unmodelled) => b.status === 'Completed').reduce((s: Unmodelled, b: Unmodelled) => s + (b.tests?.length || 0), 0);
  const totalRefunded = refunds.reduce((s: Unmodelled, r: Unmodelled) => s + (r.refund_amount || r.amount || 0), 0);
  const pendingRefunds = refunds.filter((r: Unmodelled) => r.status === 'Pending' || r.status === 'pending').length;

  const tatPriorities = ['STAT', 'Urgent', 'Routine'];
  const tatAvgHrs = tatPriorities.reduce((max, p) => {
    const v = tat?.byPriority?.[p]?.avgHrs;
    return v != null ? Math.max(max, Number(v)) : max;
  }, 0);
  const tatBreached = Number(tat?.breached || 0);
  const rejectionRate = rejection?.data?.rejectionRate;
  const homeCollectionsToday = bookings.filter((b: Unmodelled) =>
    b.visitType === 'Home Collection' && String(b.bookingDate || '').startsWith(today)
    && !['Cancelled', 'Failed', 'Completed'].includes(b.status)).length;
  const monthFromNow = Date.now() + 30 * 86400000;
  const calibrationDueList = equipment.filter((e: Unmodelled) => {
    if (!e.calibrationDue) return false;
    const due = new Date(e.calibrationDue).getTime();
    return !Number.isNaN(due) && due <= monthFromNow;
  });
  const lowStockItems = Number(invStats?.lowStock || 0);
  const inventoryValue = Number(invStats?.inventoryValue || 0);
  const qcViolations = Number(qc?.violations || 0);

  const displayedBookings = bookingTab === 'pending' ? pendingBookings
    : bookingTab === 'upcoming' ? upcomingBookings
    : bookingTab === 'today' ? todayBookings
    : completedBookings;

  if (loading) return <div className="flex justify-center py-20"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <LicenseExpiryReminder />
      <div className="bg-gradient-to-r from-primary to-primary/80 rounded-3xl p-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="font-heading text-2xl font-bold flex items-center gap-3">
              Lab Center Dashboard 
              <span className="text-[10px] font-black tracking-widest px-2 py-0.5 bg-white/20 rounded-full border border-white/40">NABL ACCREDITED</span>
            </h1>
            <p className="opacity-90">Welcome, {user?.name || 'Lab Admin'}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-success/10 flex items-center justify-center">
              <CalendarDays className="w-5 h-5 text-success" />
            </div>
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{stats?.total ?? bookings.length}</p>
          <p className="text-sm text-muted-foreground">Total Bookings</p>
        </motion.div>

        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-warning/10 flex items-center justify-center">
              <FileText className="w-5 h-5 text-warning" />
            </div>
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{pendingReports}</p>
          <p className="text-sm text-muted-foreground">Pending Approvals</p>
        </motion.div>

        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
              <DollarSign className="w-5 h-5 text-primary" />
            </div>
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">₹{totalEarned.toLocaleString()}</p>
          <p className="text-sm text-muted-foreground">Revenue</p>
        </motion.div>

        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-info/10 flex items-center justify-center">
              <Beaker className="w-5 h-5 text-info" />
            </div>
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{completedTests}</p>
          <p className="text-sm text-muted-foreground">Completed Tests</p>
        </motion.div>
      </div>

      {/* Operational & Quality Metrics (Audit Fixes) */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-card rounded-2xl border p-4 hover:border-primary/40 hover:shadow-sm transition-all flex flex-col justify-between">
          <div className="flex justify-between items-center mb-2">
            <div className="w-8 h-8 rounded-lg bg-emerald-500/10 flex items-center justify-center">
              <Clock className="w-4 h-4 text-emerald-500" />
            </div>
            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${tatBreached > 0 ? 'bg-red-500/10 text-red-600' : 'bg-emerald-500/10 text-emerald-600'}`}>
              {tatBreached > 0 ? `${tatBreached} breached` : 'On Target'}
            </span>
          </div>
          <div>
            <p className="text-xl font-bold text-foreground">{tatAvgHrs ? `${tatAvgHrs} hrs` : '—'}</p>
            <p className="text-[10px] text-muted-foreground uppercase font-semibold">Avg Turnaround Time (TAT)</p>
          </div>
        </div>

        <div className="bg-card rounded-2xl border p-4 hover:border-primary/40 hover:shadow-sm transition-all flex flex-col justify-between">
          <div className="flex justify-between items-center mb-2">
            <div className="w-8 h-8 rounded-lg bg-orange-500/10 flex items-center justify-center">
              <AlertCircle className="w-4 h-4 text-orange-500" />
            </div>
            <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-muted text-muted-foreground">30 days</span>
          </div>
          <div>
            <p className="text-xl font-bold text-orange-500">{rejectionRate != null ? `${rejectionRate}%` : '—'}</p>
            <p className="text-[10px] text-muted-foreground uppercase font-semibold">Sample Rejection Rate</p>
            {rejection?.data && (
              <p className="text-[10px] text-muted-foreground">{rejection.data.rejectedSamples} of {rejection.data.receivedSamples} received</p>
            )}
          </div>
        </div>

        <div className="bg-card rounded-2xl border p-4 hover:border-primary/40 hover:shadow-sm cursor-pointer transition-all flex flex-col justify-between" onClick={() => navigate('/lab-business/samples')}>
          <div className="flex justify-between items-center mb-2">
            <div className="w-8 h-8 rounded-lg bg-violet-500/10 flex items-center justify-center">
              <MapPin className="w-4 h-4 text-violet-500" />
            </div>
            <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-violet-500/10 text-violet-600">Live</span>
          </div>
          <div>
            <p className="text-xl font-bold text-foreground">{homeCollectionsToday}</p>
            <p className="text-[10px] text-muted-foreground uppercase font-semibold">Home Collections Today</p>
          </div>
        </div>

        <div className={`rounded-2xl border p-4 cursor-pointer transition-all flex flex-col justify-between ${calibrationDueList.length > 0 ? 'border-red-200 dark:border-red-900/50 bg-red-50/30 dark:bg-red-950/20' : 'bg-card border-border/60'}`} onClick={() => navigate('/lab-business/equipment')}>
          <div className="flex justify-between items-center mb-2">
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${calibrationDueList.length > 0 ? 'bg-red-500/20' : 'bg-success/10'}`}>
              <Activity className={`w-4 h-4 ${calibrationDueList.length > 0 ? 'text-red-600 dark:text-red-400' : 'text-success'}`} />
            </div>
            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${calibrationDueList.length > 0 ? 'bg-red-500 text-white animate-pulse' : 'bg-success/10 text-success'}`}>
              {calibrationDueList.length > 0 ? 'Action Required' : 'All Clear'}
            </span>
          </div>
