import { getISTDateString } from '@/lib/dateUtils';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const statusColors: Unmodelled = {
  Operational: 'bg-success/10 text-success',
  Maintenance: 'bg-warning/10 text-warning',
  Down: 'bg-destructive/10 text-destructive',
};

const equipmentTypes = ['MRI', 'CT', 'X-Ray', 'Ultrasound', 'ECG', 'Blood Analyzer', 'Centrifuge', 'Spectrophotometer', 'PCR Machine', 'Hematology Analyzer'];

const defaultEquipment = [
  { id: 'eq_1', name: 'Siemens Magnetom MRI', type: 'MRI', status: 'Operational', purchaseDate: '2024-03-15', lastMaintenance: '2026-06-01', nextMaintenance: '2026-09-01' },
  { id: 'eq_2', name: 'GE CT Scanner 128-slice', type: 'CT', status: 'Maintenance', purchaseDate: '2023-11-20', lastMaintenance: '2026-07-10', nextMaintenance: '2026-07-25' },
  { id: 'eq_3', name: 'Philips Digital X-Ray', type: 'X-Ray', status: 'Operational', purchaseDate: '2025-01-10', lastMaintenance: '2026-05-15', nextMaintenance: '2026-08-15' },
  { id: 'eq_4', name: 'Samsung Ultrasound WS80A', type: 'Ultrasound', status: 'Down', purchaseDate: '2022-08-05', lastMaintenance: '2026-04-20', nextMaintenance: '2026-07-20' },
  { id: 'eq_5', name: 'Abbott Blood Analyzer', type: 'Blood Analyzer', status: 'Operational', purchaseDate: '2024-06-01', lastMaintenance: '2026-06-28', nextMaintenance: '2026-09-28' },
];

export default function LabEquipment() {
  const [equipment, setEquipment] = useState<ApiRow[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [newEq, setNewEq] = useState({ name: '', type: 'MRI', purchaseDate: '' });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.getLabEquipment({}).then(res => {
      if (res.equipment && res.equipment.length > 0) setEquipment(res.equipment);
      else setEquipment(defaultEquipment);
    }).catch(() => setEquipment(defaultEquipment)).finally(() => setLoading(false));
  }, []);

  const handleAdd = async () => {
    if (!newEq.name || !newEq.purchaseDate) return;
    try {
      const eq = await api.createLabEquipment({
        name: newEq.name,
        type: newEq.type,
        status: 'Operational',
        purchaseDate: newEq.purchaseDate,
        lastMaintenance: getISTDateString(),
        nextMaintenance: '',
      });
      setEquipment(prev => [eq, ...prev]);
      setNewEq({ name: '', type: 'MRI', purchaseDate: '' });
      setShowModal(false);
    } catch (e: any) { console.error(e); }
  };

  const updateStatus = async (id: Unmodelled, status: Unmodelled) => {
    const updates = { status, lastMaintenance: status === 'Maintenance' ? getISTDateString() : undefined };
    setEquipment(prev => prev.map(eq => eq.id === id ? { ...eq, ...updates } : eq));
    try { await api.updateLabEquipment(id, updates); } catch (e: any) { console.error(e); }
  };

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <Loader2 className="w-8 h-8 animate-spin text-primary" />
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Equipment</h1>
          <p className="text-muted-foreground">{equipment.length} equipment items</p>
        </div>
        <Button className="gap-2" onClick={() => setShowModal(true)}><Plus className="w-4 h-4" /> Add Equipment</Button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-success/10 flex items-center justify-center mb-2">
            <CheckCircle className="w-5 h-5 text-success" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{equipment.filter(e => e.status === 'Operational').length}</p>
          <p className="text-sm text-muted-foreground">Operational</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-warning/10 flex items-center justify-center mb-2">
            <Wrench className="w-5 h-5 text-warning" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{equipment.filter(e => e.status === 'Maintenance').length}</p>
          <p className="text-sm text-muted-foreground">Maintenance</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-destructive/10 flex items-center justify-center mb-2">
            <AlertTriangle className="w-5 h-5 text-destructive" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{equipment.filter(e => e.status === 'Down').length}</p>
          <p className="text-sm text-muted-foreground">Down</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center mb-2">
            <Activity className="w-5 h-5 text-primary" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{equipment.filter(e => e.status === 'Operational' || e.status === 'Maintenance').length}</p>
          <p className="text-sm text-muted-foreground">In Service</p>
        </motion.div>
      </div>

      {equipment.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <Wrench className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No equipment registered</p>
          <p className="text-sm text-muted-foreground/70">Add your diagnostic and imaging equipment</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {equipment.map((eq, i) => (
            <motion.div key={eq.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}
              className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all group">
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary/20 to-primary/10 flex items-center justify-center">
                    <Wrench className="w-5 h-5 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-heading font-semibold text-foreground">{eq.name}</h3>
                    <Badge variant="outline" className="text-xs mt-0.5">{eq.type}</Badge>
                  </div>
                </div>
                <Badge className={`${statusColors[eq.status]} border-0`}>{eq.status}</Badge>
              </div>
              <div className="space-y-1.5 text-xs text-muted-foreground mb-4">
                <div className="flex items-center gap-1.5"><CalendarDays className="w-3 h-3" /> Purchased: {eq.purchaseDate}</div>
                <div className="flex items-center gap-1.5"><Wrench className="w-3 h-3" /> Last: {eq.lastMaintenance}</div>
                {eq.nextMaintenance && <div className="flex items-center gap-1.5"><AlertTriangle className="w-3 h-3" /> Next: {eq.nextMaintenance}</div>}
              </div>
              <div className="flex gap-2">
                {eq.status === 'Operational' && (
                  <Button size="sm" variant="outline" className="flex-1 gap-1 text-warning border-warning/30 hover:bg-warning/10" onClick={() => updateStatus(eq.id, 'Maintenance')}>
                    <Wrench className="w-3.5 h-3.5" /> Mark Maintenance
                  </Button>
                )}
                {eq.status === 'Maintenance' && (
                  <Button size="sm" className="flex-1 gap-1" onClick={() => updateStatus(eq.id, 'Operational')}>
                    <CheckCircle className="w-3.5 h-3.5" /> Mark Operational
                  </Button>
                )}
                {eq.status === 'Down' && (
                  <Button size="sm" className="flex-1 gap-1" onClick={() => updateStatus(eq.id, 'Maintenance')}>
                    <Wrench className="w-3.5 h-3.5" /> Send to Maintenance
                  </Button>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setShowModal(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-heading text-lg font-bold text-foreground">Add Equipment</h3>
              <button onClick={() => setShowModal(false)} className="p-2 rounded-lg hover:bg-muted transition-colors"><X className="w-5 h-5" /></button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Equipment Name *</label>
                <Input value={newEq.name} onChange={e => setNewEq(o => ({ ...o, name: e.target.value }))} placeholder="e.g. Siemens MRI 3T" />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Type *</label>
                <div className="grid grid-cols-2 gap-2">
                  {equipmentTypes.map(t => (
                    <button key={t} onClick={() => setNewEq(o => ({ ...o, type: t }))}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors ${newEq.type === t ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      {t}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Purchase Date *</label>
                <input type="date" value={newEq.purchaseDate} onChange={e => setNewEq(o => ({ ...o, purchaseDate: e.target.value }))}
                  className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm" />
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setShowModal(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleAdd} disabled={!newEq.name || !newEq.purchaseDate}>
                <Save className="w-4 h-4" /> Add Equipment
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Truck, Loader2, PackageCheck, IndianRupee, ArrowRight, Send, ClipboardList, Search, CheckCircle2, Boxes, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const STATUSES = ['Dispatch Pending', 'Dispatched', 'Received by Reference Lab', 'Processing', 'Result Received', 'Review Pending', 'Finalized'];

const STATUS_CLS: any = {
  'Dispatch Pending': 'bg-warning/10 text-warning',
  Dispatched: 'bg-info/10 text-info',
  'Received by Reference Lab': 'bg-primary/10 text-primary',
  Processing: 'bg-violet-500/10 text-violet-600',
  'Result Received': 'bg-success/10 text-success',
  'Review Pending': 'bg-warning/10 text-warning',
  Finalized: 'bg-success/10 text-success',
};

const modalClass = 'fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4';

export default function LabOutsourceDesk() {
  const qc = useQueryClient();
  const [search, setSearch] = useState('');
  const [labFilter, setLabFilter] = useState('');
  const [statusTarget, setStatusTarget] = useState<any | null>(null);
  const [nextStatus, setNextStatus] = useState('');
  const [resultTarget, setResultTarget] = useState<any | null>(null);
  const [resultForm, setResultForm] = useState<any>({ resultValue: '', normalRange: '', unit: '', externalReportNo: '', externalResultUrl: '', outsourceCost: '', vendorInvoiceNo: '' });

  const { data, isLoading } = useQuery({
    queryKey: ['lab-outsourced'],
    queryFn: () => api.getOutsourcedLab({}),
  });

  const rows: any[] = data?.outsourced || [];

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ['lab-outsourced'] });
    qc.invalidateQueries({ queryKey: ['lab-orders'] });
    qc.invalidateQueries({ queryKey: ['lab-worklist'] });
    qc.invalidateQueries({ queryKey: ['lab-stats'] });
  };

  const statusMut = useMutation({
    mutationFn: ({ id, idx, status }: any) => api.updateOutsourceStatus(id, idx, { status }),
    onSuccess: () => { toast.success('Outsource status advanced'); invalidate(); setStatusTarget(null); },
    onError: (e: any) => toast.error(e?.message || 'Status update failed'),
  });
  const resultMut = useMutation({
    mutationFn: ({ id, idx, body }: any) => api.uploadOutsourceResult(id, idx, body),
    onSuccess: () => { toast.success('Reference-lab result recorded'); invalidate(); setResultTarget(null); },
    onError: (e: any) => toast.error(e?.message || 'Result save failed'),
  });

  const labs = useMemo(() => [...new Set(rows.map((r: any) => r.lab).filter(Boolean))], [rows]);
  const q = search.trim().toLowerCase();
  const filtered = rows.filter((r: any) => {
    if (labFilter && r.lab !== labFilter) return false;
    if (!q) return true;
    return `${r.orderNo} ${r.patientName} ${r.testName} ${r.lab} ${r.courierName || ''} ${r.trackingNo || ''}`.toLowerCase().includes(q);
  });

  const cost = rows.reduce((s: number, r: any) => s + Number(r.outsourceCost || 0), 0);
  const cards = [
    { label: 'Outsourced lines', value: rows.length, icon: Truck, cls: 'text-primary' },
    { label: 'Awaiting dispatch', value: rows.filter((r: any) => !r.status || r.status === 'Dispatch Pending').length, icon: Boxes, cls: 'text-warning' },
    { label: 'With reference lab', value: rows.filter((r: any) => ['Dispatched', 'Received by Reference Lab', 'Processing'].includes(r.status)).length, icon: Send, cls: 'text-info' },
    { label: 'Results to review', value: rows.filter((r: any) => ['Result Received', 'Review Pending'].includes(r.status)).length, icon: ClipboardList, cls: 'text-violet-500' },
    { label: 'Finalized', value: rows.filter((r: any) => r.status === 'Finalized').length, icon: CheckCircle2, cls: 'text-success' },
    { label: 'Outsource spend', value: `₹${cost.toLocaleString()}`, icon: IndianRupee, cls: 'text-success' },
  ];

  const openStatus = (r: any) => {
    const idx = STATUSES.indexOf(r.status || 'Dispatch Pending');
    const options = STATUSES.slice(Math.max(0, idx + 1));
    setNextStatus(options[0] || '');
    setStatusTarget(r);
  };

  const openResult = (r: any) => {
    setResultForm({ resultValue: '', normalRange: '', unit: '', externalReportNo: '', externalResultUrl: '', outsourceCost: '', vendorInvoiceNo: '' });
    setResultTarget(r);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col lg:flex-row lg:items-end gap-3">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Outsource Desk</h1>
          <p className="text-muted-foreground">Reference-lab dispatch, courier tracking and result landing</p>
        </div>
        <div className="flex flex-1 flex-wrap gap-2 lg:justify-end">
          <div className="relative w-full sm:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search order, test, courier..." className="pl-10" />
          </div>
          <select value={labFilter} onChange={e => setLabFilter(e.target.value)}
            className="h-10 px-3 rounded-lg border border-input bg-background text-sm">
            <option value="">All reference labs</option>
            {labs.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-4">
        {cards.map((c, i) => (
          <motion.div key={c.label} whileHover={{ scale: 1.02 }} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}
            className="bg-card rounded-2xl border border-border/60 p-4">
            <c.icon className={`w-6 h-6 mb-2 ${c.cls}`} />
            <p className="text-2xl font-bold text-foreground">{c.value}</p>
            <p className="text-[11px] text-muted-foreground uppercase font-semibold">{c.label}</p>
          </motion.div>
        ))}
      </div>

      <div className="bg-card rounded-2xl border border-border/60 overflow-hidden">
        <div className="flex items-center gap-2 px-5 py-4 border-b border-border/60">
          <Truck className="w-4 h-4 text-primary" />
          <p className="text-sm font-semibold text-foreground">Outsourced test lines</p>
          <span className="ml-auto text-xs text-muted-foreground">{filtered.length} line(s)</span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-muted/40 text-xs uppercase text-muted-foreground">
              <tr>
                <th className="text-left px-5 py-3">Order / patient</th>
                <th className="text-left px-5 py-3">Test</th>
                <th className="text-left px-5 py-3">Reference lab</th>
                <th className="text-left px-5 py-3">Courier</th>
                <th className="text-left px-5 py-3">Status</th>
                <th className="text-right px-5 py-3">Cost</th>
                <th className="text-right px-5 py-3">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/50">
              {filtered.map((r: any) => (
                <tr key={`${r.orderId}-${r.testIndex}`} className="hover:bg-muted/30">
                  <td className="px-5 py-3">
                    <p className="font-mono text-xs font-semibold text-foreground">{r.orderNo}</p>
                    <p className="text-[11px] text-muted-foreground">{r.patientName} · {r.priority}</p>
                  </td>
                  <td className="px-5 py-3">
                    <p className="text-foreground">{r.testName}</p>
                    <p className="text-[11px] text-muted-foreground">{r.section || 'Unsectioned'} · {r.testStatus}</p>
                  </td>
                  <td className="px-5 py-3 text-foreground">{r.lab}</td>
                  <td className="px-5 py-3 text-xs text-muted-foreground">
                    {r.courierName || '—'}<br />{r.trackingNo || ''}
                  </td>
                  <td className="px-5 py-3">
                    <Badge className={`${STATUS_CLS[r.status] || 'bg-muted text-muted-foreground'} border-0 text-[10px]`}>{r.status || 'Dispatch Pending'}</Badge>
                    {r.sentAt && <p className="text-[11px] text-muted-foreground mt-1">sent {new Date(r.sentAt).toLocaleDateString()}</p>}
                  </td>
                  <td className="px-5 py-3 text-right font-medium text-foreground">
                    {r.outsourceCost ? `₹${Number(r.outsourceCost).toLocaleString()}` : '—'}
                  </td>
                  <td className="px-5 py-3">
                    <div className="flex justify-end gap-2">
                      <Button size="sm" variant="outline" className="gap-1 text-xs" onClick={() => openStatus(r)}>
                        Advance <ArrowRight className="w-3.5 h-3.5" />
                      </Button>
                      <Button size="sm" variant="outline" className="gap-1 text-xs" onClick={() => openResult(r)}>
                        <Upload className="w-3.5 h-3.5" /> Result
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-5 py-12 text-center text-muted-foreground">
                    <Truck className="w-10 h-10 mx-auto mb-2 opacity-30" />
                    No outsourced tests match this filter
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {statusTarget && (
        <div className={modalClass} onClick={() => setStatusTarget(null)}>
          <div className="bg-card rounded-2xl border p-6 max-w-md w-full shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center"><ArrowRight className="w-5 h-5 text-primary" /></div>
              <div>
                <h3 className="font-semibold text-foreground">Advance outsource status</h3>
                <p className="text-xs text-muted-foreground">{statusTarget.testName} · {statusTarget.orderNo}</p>
              </div>
            </div>
            <div className="space-y-3">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">New status</label>
                <select value={nextStatus} onChange={e => setNextStatus(e.target.value)}
                  className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                  {STATUSES.slice(Math.max(0, STATUSES.indexOf(statusTarget.status || 'Dispatch Pending') + 1)).map(s => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
                <p className="text-[11px] text-muted-foreground mt-1.5">
                  Current: {statusTarget.status || 'Dispatch Pending'} · chain only moves forward
                </p>
              </div>
              <div className="flex gap-3">
                <Button variant="outline" className="flex-1" onClick={() => setStatusTarget(null)}>Cancel</Button>
                <Button className="flex-1" disabled={!nextStatus || statusMut.isPending}
                  onClick={() => statusMut.mutate({ id: statusTarget.orderId, idx: statusTarget.testIndex, status: nextStatus })}>
                  {statusMut.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Update'}
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {resultTarget && (
        <div className={modalClass} onClick={() => setResultTarget(null)}>
          <div className="bg-card rounded-2xl border p-6 max-w-lg w-full shadow-2xl max-h-[85vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-xl bg-success/10 flex items-center justify-center"><PackageCheck className="w-5 h-5 text-success" /></div>
              <div>
                <h3 className="font-semibold text-foreground">Land reference-lab result</h3>
                <p className="text-xs text-muted-foreground">{resultTarget.testName} · {resultTarget.orderNo}</p>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-2">
                <label className="text-sm font-medium text-foreground mb-1.5 block">Result value</label>
                <textarea rows={3} value={resultForm.resultValue} onChange={e => setResultForm((f: any) => ({ ...f, resultValue: e.target.value }))}
                  className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm" placeholder="e.g. 7.2 mmol/L" />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Normal range</label>
                <Input value={resultForm.normalRange} onChange={e => setResultForm((f: any) => ({ ...f, normalRange: e.target.value }))} placeholder="4.0 - 6.0" />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Unit</label>
                <Input value={resultForm.unit} onChange={e => setResultForm((f: any) => ({ ...f, unit: e.target.value }))} placeholder="mmol/L" />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">External report no.</label>
                <Input value={resultForm.externalReportNo} onChange={e => setResultForm((f: any) => ({ ...f, externalReportNo: e.target.value }))} />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">External result URL</label>
                <Input value={resultForm.externalResultUrl} onChange={e => setResultForm((f: any) => ({ ...f, externalResultUrl: e.target.value }))} />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Outsource cost (₹)</label>
                <Input type="number" value={resultForm.outsourceCost} onChange={e => setResultForm((f: any) => ({ ...f, outsourceCost: e.target.value }))} />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Vendor invoice no.</label>
                <Input value={resultForm.vendorInvoiceNo} onChange={e => setResultForm((f: any) => ({ ...f, vendorInvoiceNo: e.target.value }))} />
              </div>
            </div>
            <p className="text-[11px] text-muted-foreground mt-2">
              Recorded results land as "Result Pending" and still need in-house verification.
            </p>
            <div className="flex gap-3 mt-4">
              <Button variant="outline" className="flex-1" onClick={() => setResultTarget(null)}>Cancel</Button>
              <Button className="flex-1" disabled={resultMut.isPending || !resultForm.resultValue.trim()}
                onClick={() => {
                  const body: any = {
                    resultValue: resultForm.resultValue.trim(),
                    externalReportNo: resultForm.externalReportNo,
                    externalResultUrl: resultForm.externalResultUrl,
                  };
                  if (resultForm.normalRange) body.normalRange = resultForm.normalRange;
                  if (resultForm.unit) body.unit = resultForm.unit;
                  if (resultForm.outsourceCost !== '') body.outsourceCost = Number(resultForm.outsourceCost);
                  if (resultForm.vendorInvoiceNo) body.vendorInvoiceNo = resultForm.vendorInvoiceNo;
                  resultMut.mutate({ id: resultTarget.orderId, idx: resultTarget.testIndex, body });
                }}>
                {resultMut.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Save result'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Package, Plus, X, Save, Gift, Percent, Beaker, IndianRupee } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function LabPackages() {
  const [packages, setPackages] = useState<ApiRow[]>([]);
  const [tests, setTests] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Unmodelled>(null);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [selectedTests, setSelectedTests] = useState<ApiRow[]>([]);
  const [discount, setDiscount] = useState(0);
  const [price, setPrice] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const load = async () => {
      try {
        const [pkgRes, testRes] = await Promise.all([
          api.getLabPackages({}),
          api.getLabTests(),
        ]);
        setPackages(pkgRes.packages || []);
        setTests(testRes.tests || []);
      } catch (e: any) { console.error(e); }
      setLoading(false);
    };
    load();
  }, []);

  const totalOriginal = selectedTests.reduce((sum, tid) => {
    const t = tests.find(tt => tt._id === tid);
    return sum + (t?.price || 0);
  }, 0);

  const handleSave = async () => {
    if (!name || selectedTests.length === 0 || !price) return;
    setSaving(true);
    try {
      const pkg = { name, description, tests: selectedTests, discount: Number(discount), price: Number(price) };
      if (editing) {
        const updated = await api.updateLabPackage(editing._id, pkg);
        setPackages(prev => prev.map(p => p._id === editing._id ? updated : p));
      } else {
        const created = await api.createLabPackage(pkg);
        setPackages(prev => [created, ...prev]);
      }
      setShowForm(false);
      setEditing(null);
      setName(''); setDescription(''); setSelectedTests([]); setDiscount(0); setPrice('');
    } catch (e: any) { console.error(e); }
    setSaving(false);
  };

  const openEdit = (pkg: Unmodelled) => {
    setEditing(pkg);
    setName(pkg.name); setDescription(pkg.description || ''); setSelectedTests(pkg.tests); setDiscount(pkg.discount); setPrice(String(pkg.price));
    setShowForm(true);
  };

  const toggleTest = (tid: Unmodelled) => {
    setSelectedTests(prev => prev.includes(tid) ? prev.filter(t => t !== tid) : [...prev, tid]);
  };

  if (loading) {
    return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Health Packages</h1>
          <p className="text-muted-foreground">{packages.length} package(s)</p>
        </div>
        <Button className="gap-2" onClick={() => { setEditing(null); setName(''); setDescription(''); setSelectedTests([]); setDiscount(0); setPrice(''); setShowForm(true); }}><Plus className="w-4 h-4" /> Create Package</Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {packages.map((pkg, i) => {
          const orig = pkg.tests.reduce((s: Unmodelled, tid: Unmodelled) => { const t = tests.find(tt => tt._id === tid); return s + (t?.price || 0); }, 0);
          return (
            <motion.div key={pkg._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
              className="bg-card rounded-2xl border border-border/60 p-6 hover:shadow-lg transition-all group relative overflow-hidden">
              <div className="absolute top-0 right-0 bg-primary/10 px-3 py-1 rounded-bl-2xl">
                <span className="text-xs font-bold text-primary">{pkg.discount}% OFF</span>
              </div>
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-purple-500/20 to-purple-500/10 flex items-center justify-center mb-4">
                <Gift className="w-6 h-6 text-purple-500" />
              </div>
              <h3 className="font-heading font-semibold text-lg text-foreground">{pkg.name}</h3>
              <p className="text-sm text-muted-foreground mt-1">{pkg.description}</p>
              <div className="flex items-center gap-2 mt-3">
                <Beaker className="w-4 h-4 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">{pkg.tests.length} test(s)</span>
              </div>
              <div className="flex items-center gap-2 mt-3">
                <span className="text-sm line-through text-muted-foreground">₹{orig.toLocaleString()}</span>
                <span className="text-xl font-bold text-foreground">₹{pkg.price.toLocaleString()}</span>
              </div>
              <div className="flex gap-1 mt-4 flex-wrap">
                {pkg.tests.map((tid: Unmodelled) => {
                  const t = tests.find(tt => tt._id === tid);
                  return t ? <Badge key={tid} variant="outline" className="text-xs">{t.name}</Badge> : null;
                })}
              </div>
              <div className="absolute top-2 left-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <Button variant="ghost" size="icon" className="w-7 h-7" onClick={() => openEdit(pkg)}>
                  <Plus className="w-3.5 h-3.5" />
                </Button>
              </div>
            </motion.div>
          );
        })}
      </div>

      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setShowForm(false)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">{editing ? 'Edit Package' : 'Create Package'}</h3>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium mb-1.5 block">Package Name *</label>
                <Input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Full Body Checkup" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Description</label>
                <Input value={description} onChange={e => setDescription(e.target.value)} placeholder="Brief description" />
              </div>
              <div>
                <label className="text-sm font-medium mb-1.5 block">Select Tests * ({selectedTests.length} selected)</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                  {tests.map(t => (
                    <button key={t._id} onClick={() => toggleTest(t._id)}
                      className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors text-left flex items-center gap-2 ${selectedTests.includes(t._id) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      <Beaker className="w-3.5 h-3.5 flex-shrink-0" />
                      <span className="truncate">{t.name}</span>
                      <span className="ml-auto text-xs opacity-70">₹{t.price}</span>
                    </button>
                  ))}
                </div>
              </div>
              {totalOriginal > 0 && (
                <p className="text-sm text-muted-foreground">Original total: ₹{totalOriginal.toLocaleString()}</p>
              )}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium mb-1.5 block flex items-center gap-1"><Percent className="w-3.5 h-3.5" /> Discount %</label>
                  <Input type="number" value={discount} onChange={e => setDiscount(Number(e.target.value))} min={0} max={100} />
                </div>
                <div>
                  <label className="text-sm font-medium mb-1.5 block flex items-center gap-1"><IndianRupee className="w-3.5 h-3.5" /> Package Price *</label>
                  <Input type="number" value={price} onChange={e => setPrice(e.target.value)} placeholder="2999" min={0} />
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <Button variant="outline" className="flex-1" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button className="flex-1 gap-2" onClick={handleSave} disabled={!name || selectedTests.length === 0 || !price || saving}>
                <Save className="w-4 h-4" /> {editing ? 'Update' : 'Create'}
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Activity, FlaskConical, Loader2, Plus, AlertTriangle, CheckCircle2, Gauge, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const LEVELS = ['L1', 'L2', 'L3'];

export default function LabQualityQc() {
  const qc = useQueryClient();
  const [form, setForm] = useState<any>({ analyzer: '', testName: '', controlLevel: 'L1', mean: '', sd: '', value: '' });
  const [chartSel, setChartSel] = useState({ testName: '', analyzer: '' });

  const { data: testsData } = useQuery({ queryKey: ['lab-tests'], queryFn: () => api.getLabTests() });
  const { data: equipmentData } = useQuery({ queryKey: ['lab-equipment'], queryFn: () => api.getLabEquipment({}) });

  const tests: any[] = testsData?.tests || testsData?.items || (Array.isArray(testsData) ? testsData : []);
  const equipment: any[] = equipmentData?.equipment || [];

  const { data: chart, isLoading: chartLoading, isFetching: chartFetching } = useQuery({
    queryKey: ['qc-chart', chartSel.testName, chartSel.analyzer],
    queryFn: () => api.qcChart({ testName: chartSel.testName, ...(chartSel.analyzer ? { analyzer: chartSel.analyzer } : {}) }),
    enabled: Boolean(chartSel.testName),
  });

  const createMut = useMutation({
    mutationFn: () => api.qcCreate({
      analyzer: form.analyzer || '',
      testName: form.testName,
      controlLevel: form.controlLevel,
      mean: Number(form.mean),
      sd: Number(form.sd),
      value: Number(form.value),
    }),
    onSuccess: () => {
      toast.success('QC run recorded');
      qc.invalidateQueries({ queryKey: ['qc-chart'] });
      setChartSel({ testName: form.testName, analyzer: form.analyzer });
      setForm((f: any) => ({ ...f, value: '' }));
    },
    onError: (e: any) => toast.error(e?.message || 'QC run failed to save'),
  });

  const points: any[] = chart?.points || [];
  const geom = useMemo(() => {
    if (!points.length) return null;
    const mean = points[points.length - 1].mean;
    const sd = points[points.length - 1].sd;
    if (!(sd > 0)) return { mean, sd: 0, min: mean - 1, max: mean + 1 };
    const min = Math.min(...points.map(p => p.value), mean - 3.5 * sd);
    const max = Math.max(...points.map(p => p.value), mean + 3.5 * sd);
    return { mean, sd, min, max };
  }, [points]);

  const W = 720;
  const H = 260;
  const y = (v: number) => {
    if (!geom) return H / 2;
    const pad = 16;
    return pad + ((geom.max - v) / (geom.max - geom.min || 1)) * (H - pad * 2);
  };
  const x = (i: number) => points.length <= 1 ? W / 2 : 40 + (i / (points.length - 1)) * (W - 70);

  const flagged = points.filter(p => (p.flags || []).length);
  const valid = form.testName && Number(form.mean) > 0 && Number(form.sd) >= 0 && form.value !== '' && !Number.isNaN(Number(form.value));

  const cards = [
    { label: 'Runs charted', value: points.length, icon: History, cls: 'text-primary' },
    { label: 'Westgard violations', value: chart?.violations ?? 0, icon: AlertTriangle, cls: 'text-destructive' },
    { label: 'Mean', value: geom ? geom.mean : '—', icon: Gauge, cls: 'text-info' },
    { label: 'SD', value: geom && geom.sd ? geom.sd : '—', icon: Activity, cls: 'text-warning' },
  ];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Quality Control</h1>
        <p className="text-muted-foreground">Record control runs and monitor Levey-Jennings / Westgard rules</p>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {cards.map((c, i) => (
          <motion.div key={c.label} whileHover={{ scale: 1.02 }} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
            className="bg-card rounded-2xl border border-border/60 p-4">
            <c.icon className={`w-6 h-6 mb-2 ${c.cls}`} />
            <p className="text-2xl font-bold text-foreground">{c.value}</p>
            <p className="text-[11px] text-muted-foreground uppercase font-semibold">{c.label}</p>
          </motion.div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-card rounded-2xl border border-border/60 p-6 lg:col-span-1">
          <div className="flex items-center gap-2 mb-4">
            <FlaskConical className="w-5 h-5 text-primary" />
            <h2 className="font-heading font-semibold text-foreground">Record a QC run</h2>
          </div>
          <div className="space-y-3">
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">Test</label>
              <select value={form.testName} onChange={e => setForm((f: any) => ({ ...f, testName: e.target.value }))}
                className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                <option value="">Select test...</option>
                {tests.map((t: any) => <option key={t._id || t.name} value={t.name}>{t.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">Analyzer</label>
              <select value={form.analyzer} onChange={e => setForm((f: any) => ({ ...f, analyzer: e.target.value }))}
                className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                <option value="">No analyzer / manual</option>
                {equipment.map((eq: any) => <option key={eq._id} value={eq.name}>{eq.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">Control level</label>
              <div className="grid grid-cols-3 gap-2">
                {LEVELS.map(l => (
                  <Button key={l} size="sm" variant={form.controlLevel === l ? 'default' : 'outline'}
                    onClick={() => setForm((f: any) => ({ ...f, controlLevel: l }))}>{l}</Button>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Mean</label>
                <Input type="number" step="any" value={form.mean} onChange={e => setForm((f: any) => ({ ...f, mean: e.target.value }))} placeholder="100" />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">SD</label>
                <Input type="number" step="any" value={form.sd} onChange={e => setForm((f: any) => ({ ...f, sd: e.target.value }))} placeholder="2" />
              </div>
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">Observed value</label>
              <Input type="number" step="any" value={form.value} onChange={e => setForm((f: any) => ({ ...f, value: e.target.value }))} placeholder="103.4" />
            </div>
            <Button className="w-full gap-1.5" disabled={!valid || createMut.isPending} onClick={() => createMut.mutate()}>
              {createMut.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
              Record run
            </Button>
            <p className="text-[11px] text-muted-foreground">
              Westgard flags (1-2s, 1-3s, R-4s) are computed by the lab service on read.
            </p>
          </div>
        </div>

        <div className="bg-card rounded-2xl border border-border/60 p-6 lg:col-span-2">
          <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-4">
            <div className="flex items-center gap-2">
              <Activity className="w-5 h-5 text-primary" />
              <h2 className="font-heading font-semibold text-foreground">Levey-Jennings chart</h2>
            </div>
            <div className="flex gap-2 sm:ml-auto">
              <select value={chartSel.testName} onChange={e => setChartSel(s => ({ ...s, testName: e.target.value }))}
                className="h-9 px-3 rounded-lg border border-input bg-background text-xs">
                <option value="">Select test...</option>
                {tests.map((t: any) => <option key={t._id || t.name} value={t.name}>{t.name}</option>)}
              </select>
              <select value={chartSel.analyzer} onChange={e => setChartSel(s => ({ ...s, analyzer: e.target.value }))}
                className="h-9 px-3 rounded-lg border border-input bg-background text-xs">
                <option value="">All analyzers</option>
                {equipment.map((eq: any) => <option key={eq._id} value={eq.name}>{eq.name}</option>)}
              </select>
            </div>
          </div>

          {!chartSel.testName ? (
            <div className="py-16 text-center text-muted-foreground">
              <FlaskConical className="w-12 h-12 mx-auto mb-3 opacity-30" />
              Pick a test to plot its control history
            </div>
          ) : chartLoading || chartFetching ? (
            <div className="py-16 flex justify-center"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>
          ) : !points.length ? (
            <div className="py-16 text-center text-muted-foreground">
              <CheckCircle2 className="w-12 h-12 mx-auto mb-3 opacity-30" />
              No QC runs recorded for this test yet
            </div>
          ) : (
            <>
              <div className="overflow-x-auto">
                <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-64" role="img" aria-label="Levey-Jennings chart">
                  {[3, 2, 1, 0, -1, -2, -3].map(k => {
                    const val = geom!.mean + k * geom!.sd;
                    const yy = y(val);
                    const lineColor = Math.abs(k) === 3 ? 'stroke-destructive/40' : Math.abs(k) === 2 ? 'stroke-warning/40' : k === 0 ? 'stroke-primary/70' : 'stroke-border';
                    return (
                      <g key={k}>
                        <line x1={36} x2={W - 20} y1={yy} y2={yy} stroke="currentColor" strokeWidth={k === 0 ? 1.5 : 1}
                          className={lineColor} strokeDasharray={Math.abs(k) === 3 || Math.abs(k) === 2 ? '5 4' : k === 0 ? '' : '2 4'} />
                        <text x={8} y={yy + 3} fontSize="9" fill="currentColor" className="text-muted-foreground">
                          {k === 0 ? 'μ' : k > 0 ? `+${k}sd` : `${k}sd`}
                        </text>
                      </g>
                    );
                  })}
                  <polyline fill="none" stroke="currentColor" strokeWidth="1.5" className="text-muted-foreground/60"
                    points={points.map((p, i) => `${x(i)},${y(p.value)}`).join(' ')} />
                  {points.map((p, i) => {
                    const bad = (p.flags || []).length > 0;
                    return (
                      <circle key={i} cx={x(i)} cy={y(p.value)} r={bad ? 5.5 : 4}
                        fill={bad ? 'hsl(var(--destructive))' : 'hsl(var(--primary))'}
                        stroke="hsl(var(--card))" strokeWidth="1.5">
                        <title>{`${new Date(p.at).toLocaleString()} · ${p.value} (${(p.flags || []).join(', ') || 'in control'})`}</title>
                      </circle>
                    );
                  })}
                  {points.map((p, i) => (p.flags || []).length ? (
                    <text key={`f${i}`} x={x(i)} y={y(p.value) - 10} fontSize="9" textAnchor="middle" className="fill-destructive">
                      {(p.flags || []).join('/')}
                    </text>
                  ) : null)}
                </svg>
              </div>

              <div className="flex items-center gap-4 text-xs text-muted-foreground mt-2">
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-primary inline-block" /> In control</span>
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-destructive inline-block" /> Westgard flag</span>
                <span className="ml-auto">{flagged.length} flagged of {points.length} run(s)</span>
              </div>

              <div className="overflow-x-auto rounded-xl border border-border/60 mt-4">
                <table className="w-full text-sm">
                  <thead className="bg-muted/40 text-xs uppercase text-muted-foreground">
                    <tr>
                      <th className="text-left px-4 py-2.5">#</th>
                      <th className="text-left px-4 py-2.5">Run at</th>
                      <th className="text-right px-4 py-2.5">Value</th>
                      <th className="text-right px-4 py-2.5">Mean</th>
                      <th className="text-right px-4 py-2.5">SD</th>
                      <th className="text-right px-4 py-2.5">Z</th>
                      <th className="text-left px-4 py-2.5">Flags</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/50">
                    {[...points].reverse().map((p, i) => {
                      const z = p.sd > 0 ? ((p.value - p.mean) / p.sd) : 0;
                      const bad = (p.flags || []).length > 0;
                      return (
                        <tr key={i} className="hover:bg-muted/30">
                          <td className="px-4 py-2 font-mono text-xs text-muted-foreground">{points.length - i}</td>
                          <td className="px-4 py-2 text-foreground">{new Date(p.at).toLocaleString()}</td>
                          <td className="px-4 py-2 text-right font-medium text-foreground">{p.value}</td>
                          <td className="px-4 py-2 text-right text-muted-foreground">{p.mean}</td>
                          <td className="px-4 py-2 text-right text-muted-foreground">{p.sd}</td>
                          <td className="px-4 py-2 text-right font-mono">{z.toFixed(2)}</td>
                          <td className="px-4 py-2">
                            {bad ? (
                              <Badge className="bg-destructive/10 text-destructive border-0 text-[10px]">{(p.flags || []).join(', ')}</Badge>
                            ) : (
                              <Badge className="bg-success/10 text-success border-0 text-[10px]">In control</Badge>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Inbox, ScanLine, CheckCircle2, XCircle, RotateCcw, AlertTriangle, Search, Loader2, PackageCheck, FlaskConical, Link2Off } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const REJECTION_REASONS = [
  'Hemolyzed', 'Insufficient Quantity', 'Wrong Container', 'Wrong Sample',
  'Clotted Sample', 'Leaking Container', 'Label Mismatch', 'Contamination',
  'Improper Transport', 'Incorrect Storage', 'Other',
];

const CONDITIONS = ['Good', 'Slightly Hemolyzed', 'Hemolyzed', 'Clotted', 'Lipemic', 'Icteric', 'Leaking', 'Insufficient Quantity', 'Label Mismatch'];

const PRIORITY_COLORS: any = {
  Routine: 'bg-muted text-muted-foreground',
  Urgent: 'bg-warning/10 text-warning',
  STAT: 'bg-destructive/10 text-destructive',
};

const modalClass = 'fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4';

export default function LabReceivingDashboard() {
  const qc = useQueryClient();
  const [scan, setScan] = useState('');
  const [dialog, setDialog] = useState<any | null>(null);
  const [form, setForm] = useState<any>({ sampleNo: '', condition: 'Good', notes: '', section: '', reason: '', detail: '', testIndex: '' });
  const [busy, setBusy] = useState(false);

  const { data: receivingData, isLoading } = useQuery({
    queryKey: ['lab-receiving'],
    queryFn: () => api.getLabReceiving({}),
  });
  const { data: ordersData } = useQuery({ queryKey: ['lab-orders'], queryFn: () => api.getLabOrders({}) });
  const { data: sectionsData } = useQuery({ queryKey: ['lab-sections'], queryFn: () => api.getLabSections() });

  const incoming: any[] = receivingData?.orders || [];
  const allOrders: any[] = ordersData?.orders || [];
  const sections: any[] = sectionsData?.sections || [];

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ['lab-receiving'] });
    qc.invalidateQueries({ queryKey: ['lab-orders'] });
    qc.invalidateQueries({ queryKey: ['lab-stats'] });
  };

  const receiveMut = useMutation({
    mutationFn: ({ id, body }: any) => api.receiveLabOrder(id, body),
    onSuccess: () => { toast.success('Sample received at intake'); invalidate(); setDialog(null); },
    onError: (e: any) => toast.error(e?.message || 'Receive failed'),
  });
  const acceptMut = useMutation({
    mutationFn: ({ id, idx, body }: any) => api.acceptLabSample(id, idx, body),
    onSuccess: () => { invalidate(); },
    onError: (e: any) => toast.error(e?.message || 'Accept failed'),
  });
  const rejectMut = useMutation({
    mutationFn: ({ id, idx, body }: any) => api.rejectLabSample(id, idx, body),
    onSuccess: () => { toast.success('Sample rejected — recollection required'); invalidate(); setDialog(null); },
    onError: (e: any) => toast.error(e?.message || 'Reject failed'),
  });
  const recollectMut = useMutation({
    mutationFn: ({ id, idx }: any) => api.recollectLabSample(id, idx),
    onSuccess: () => { invalidate(); },
    onError: (e: any) => toast.error(e?.message || 'Recollection failed'),
  });

  const open = (type: string, order: any) => {
    setForm({ sampleNo: order?.sampleIds?.[0] || '', condition: 'Good', notes: '', section: sections[0]?.section || 'Biochemistry', reason: 'Hemolyzed', detail: '', testIndex: String(order?.pendingTests?.[0]?.testIndex ?? 0) });
    setDialog({ type, order });
  };

  const runAccept = async (order: any) => {
    setBusy(true);
    try {
      for (const t of order.pendingTests || []) {
        await acceptMut.mutateAsync({ id: order._id, idx: t.testIndex, body: { section: form.section } });
      }
      toast.success(`Accepted ${order.pendingTests?.length || 0} sample line(s) into ${form.section}`);
      setDialog(null);
    } catch (e: any) {
      toast.error(e?.message || 'Accept failed');
    }
    setBusy(false);
  };

  const runReject = async (order: any) => {
    setBusy(true);
    try {
      const idx = form.testIndex === '' ? (order.pendingTests || []).map((t: any) => t.testIndex) : [Number(form.testIndex)];
      for (const i of idx) {
        await rejectMut.mutateAsync({ id: order._id, idx: i, body: { reason: form.reason, detail: form.detail } });
      }
      setDialog(null);
    } catch (e: any) {
      toast.error(e?.message || 'Reject failed');
    }
    setBusy(false);
  };

  const runRecollect = async (order: any) => {
    setBusy(true);
    try {
      const rejected = (order.tests || []).map((t: any, i: number) => ({ t, i })).filter((r: any) => r.t.status === 'Rejected');
      for (const r of rejected) {
        await recollectMut.mutateAsync({ id: order._id, idx: r.i });
      }
      toast.success(`Recollection requested for ${rejected.length} line(s)`);
      invalidate();
      setDialog(null);
    } catch (e: any) {
      toast.error(e?.message || 'Recollection failed');
    }
    setBusy(false);
  };

  const q = scan.trim().toLowerCase();
  const filtered = incoming.filter((o: any) => {
    if (!q) return true;
    const hay = [
      o.orderId, o.patientName, o.accessionNo,
      ...(o.sampleIds || []),
      ...(o.pendingTests || []).map((t: any) => `${t.sampleNo || ''} ${t.sampleId || ''} ${t.testName || ''}`),
    ].join(' ').toLowerCase();
    return hay.includes(q);
  });

  const allTests = allOrders.flatMap((o: any) => o.tests || []);
  const acceptedCount = allTests.filter((t: any) => t.receivedAt).length;
  const rejectedCount = allTests.filter((t: any) => t.status === 'Rejected').length;
  const recollectCount = allTests.filter((t: any) => Number(t.recollectCount || 0) > 0).length;
  const unmatched = incoming.filter((o: any) => !(o.sampleIds || []).length && !(o.pendingTests || []).some((t: any) => t.sampleNo || t.sampleId)).length;
  const urgentCount = incoming.filter((o: any) => o.priority === 'Urgent' || o.priority === 'STAT').length;
  const awaitingReceipt = incoming.reduce((a: number, o: any) => a + (o.pendingTests?.length || 0), 0);

  const cards = [
    { label: 'Incoming', value: receivingData?.total ?? incoming.length, icon: Inbox, cls: 'bg-primary/10 text-primary' },
    { label: 'Awaiting Receipt', value: awaitingReceipt, icon: ScanLine, cls: 'bg-warning/10 text-warning' },
    { label: 'Accepted', value: acceptedCount, icon: CheckCircle2, cls: 'bg-success/10 text-success' },
    { label: 'Rejected', value: rejectedCount, icon: XCircle, cls: 'bg-destructive/10 text-destructive' },
    { label: 'Recollection Required', value: recollectCount, icon: RotateCcw, cls: 'bg-orange-500/10 text-orange-600' },
    { label: 'Urgent / STAT', value: urgentCount, icon: AlertTriangle, cls: 'bg-red-500/10 text-red-600' },
    { label: 'Unmatched', value: unmatched, icon: Link2Off, cls: 'bg-violet-500/10 text-violet-600' },
  ];

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-3">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Sample Receiving</h1>
          <p className="text-muted-foreground">Scan or type a barcode / sample number to filter the intake bench</p>
        </div>
        <div className="relative w-full sm:w-80">
          <ScanLine className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input autoFocus value={scan} onChange={(e) => setScan(e.target.value)}
            placeholder="Scan barcode / sample no / order no" className="pl-9 font-mono" />
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-7 gap-4">
        {cards.map((c, i) => (
          <motion.div key={c.label} whileHover={{ scale: 1.02 }} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}
            className="bg-card rounded-2xl border border-border/60 p-4">
            <div className={`w-9 h-9 rounded-xl flex items-center justify-center mb-2 ${c.cls}`}>
              <c.icon className="w-4.5 h-4.5" />
            </div>
            <p className="font-heading text-2xl font-bold text-foreground">{c.value}</p>
            <p className="text-[11px] text-muted-foreground uppercase font-semibold">{c.label}</p>
          </motion.div>
        ))}
      </div>

      <div className="bg-card rounded-2xl border border-border/60 overflow-hidden">
        <div className="flex items-center gap-2 px-5 py-4 border-b border-border/60">
          <Search className="w-4 h-4 text-muted-foreground" />
          <p className="text-sm font-semibold text-foreground">Collected orders awaiting receipt</p>
          <span className="ml-auto text-xs text-muted-foreground">{filtered.length} of {incoming.length}</span>
        </div>
        {filtered.length === 0 ? (
          <div className="text-center py-16">
            <PackageCheck className="w-12 h-12 mx-auto text-muted-foreground/30 mb-3" />
            <p className="text-muted-foreground">Intake bench is clear</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-muted/40 text-xs uppercase text-muted-foreground">
                <tr>
                  <th className="text-left px-5 py-3">Order</th>
                  <th className="text-left px-5 py-3">Patient</th>
                  <th className="text-left px-5 py-3">Pending samples</th>
                  <th className="text-left px-5 py-3">Priority</th>
                  <th className="text-left px-5 py-3">Received</th>
                  <th className="text-right px-5 py-3">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/50">
                {filtered.map((o: any) => {
                  const rejected = (o.tests || []).filter((t: any) => t.status === 'Rejected');
                  const hasRecollect = rejected.length > 0;
                  return (
                    <tr key={o._id} className="hover:bg-muted/30">
                      <td className="px-5 py-3">
                        <p className="font-mono text-xs font-semibold text-foreground">{o.orderId}</p>
                        <p className="text-[11px] text-muted-foreground">{o.doctorName || '—'}</p>
                      </td>
                      <td className="px-5 py-3 font-medium text-foreground">{o.patientName}</td>
                      <td className="px-5 py-3">
                        <div className="flex flex-wrap gap-1.5">
                          {(o.pendingTests || []).map((t: any) => (
                            <span key={t.testIndex} className="text-[11px] px-2 py-0.5 rounded-full bg-muted text-muted-foreground font-mono">
                              {t.sampleNo || t.sampleId || t.testName}
                            </span>
                          ))}
                          {(o.pendingTests || []).length === 0 && <span className="text-xs text-success">All received</span>}
                        </div>
                      </td>
                      <td className="px-5 py-3">
                        <Badge className={`${PRIORITY_COLORS[o.priority] || ''} border-0 text-[10px]`}>{o.priority}</Badge>
                      </td>
                      <td className="px-5 py-3 text-xs text-muted-foreground">{o.createdAt ? new Date(o.createdAt).toLocaleString() : '—'}</td>
                      <td className="px-5 py-3">
                        <div className="flex justify-end gap-2">
                          {(o.pendingTests || []).length > 0 && (
                            <>
                              <Button size="sm" className="gap-1 text-xs" onClick={() => open('receive', o)}>
                                <PackageCheck className="w-3.5 h-3.5" /> Receive
                              </Button>
                              <Button size="sm" variant="outline" className="gap-1 text-xs" onClick={() => open('accept', o)}>
                                <CheckCircle2 className="w-3.5 h-3.5" /> Accept
                              </Button>
                              <Button size="sm" variant="outline" className="gap-1 text-xs text-destructive hover:bg-destructive/10" onClick={() => open('reject', o)}>
                                <XCircle className="w-3.5 h-3.5" /> Reject
                              </Button>
                            </>
                          )}
                          {hasRecollect && (
                            <Button size="sm" variant="outline" className="gap-1 text-xs text-orange-600 hover:bg-orange-500/10"
                              onClick={() => open('recollect', o)} disabled={recollectMut.isPending}>
                              <RotateCcw className="w-3.5 h-3.5" /> Recollect
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {dialog && (
        <div className={modalClass} onClick={() => setDialog(null)}>
          <motion.div initial={{ scale: 0.96, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}
            className="bg-card rounded-2xl border border-border/60 p-6 max-w-lg w-full shadow-2xl"
            onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-5">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                {dialog.type === 'receive' && <PackageCheck className="w-5 h-5 text-primary" />}
                {dialog.type === 'accept' && <CheckCircle2 className="w-5 h-5 text-success" />}
                {dialog.type === 'reject' && <XCircle className="w-5 h-5 text-destructive" />}
                {dialog.type === 'recollect' && <RotateCcw className="w-5 h-5 text-orange-600" />}
              </div>
              <div>
                <h3 className="font-semibold text-foreground capitalize">{dialog.type === 'recollect' ? 'Request Recollection' : `${dialog.type} sample`}</h3>
                <p className="text-xs text-muted-foreground font-mono">{dialog.order.orderId} · {dialog.order.patientName}</p>
              </div>
            </div>

            {dialog.type === 'receive' && (
              <div className="space-y-4">
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Sample / Barcode No.</label>
                  <Input value={form.sampleNo} onChange={(e) => setForm((f: any) => ({ ...f, sampleNo: e.target.value }))} placeholder="Scan or type sample number" className="font-mono" />
                </div>
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Sample condition</label>
                  <select value={form.condition} onChange={(e) => setForm((f: any) => ({ ...f, condition: e.target.value }))}
                    className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                    {CONDITIONS.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Notes</label>
                  <textarea value={form.notes} onChange={(e) => setForm((f: any) => ({ ...f, notes: e.target.value }))} rows={3}
                    className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm" placeholder="Intake observations..." />
                </div>
                <Button className="w-full gap-2" disabled={receiveMut.isPending}
                  onClick={() => receiveMut.mutate({ id: dialog.order._id, body: { sampleNo: form.sampleNo, condition: form.condition, notes: form.notes } })}>
                  {receiveMut.isPending ? 'Receiving...' : 'Confirm Receipt'}
                </Button>
              </div>
            )}

            {dialog.type === 'accept' && (
              <div className="space-y-4">
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Section</label>
                  <select value={form.section} onChange={(e) => setForm((f: any) => ({ ...f, section: e.target.value }))}
                    className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                    {sections.length === 0 && <option value="">No sections available</option>}
                    {sections.map((s: any) => <option key={s.section} value={s.section}>{s.section} ({s.pending} pending)</option>)}
                  </select>
                </div>
                <p className="text-xs text-muted-foreground">
                  {(dialog.order.pendingTests || []).length} sample line(s) will be accepted and routed to {form.section || 'the selected section'}.
                </p>
                <Button className="w-full gap-2" disabled={busy || acceptMut.isPending} onClick={() => runAccept(dialog.order)}>
                  {busy ? 'Accepting...' : 'Accept into section'}
                </Button>
              </div>
            )}

            {dialog.type === 'reject' && (
              <div className="space-y-4">
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Sample line</label>
                  <select value={form.testIndex} onChange={(e) => setForm((f: any) => ({ ...f, testIndex: e.target.value }))}
                    className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                    <option value="">All pending lines</option>
                    {(dialog.order.pendingTests || []).map((t: any) => (
                      <option key={t.testIndex} value={String(t.testIndex)}>{t.testName} ({t.sampleNo || t.sampleId || 'no sample no'})</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Rejection reason</label>
                  <select value={form.reason} onChange={(e) => setForm((f: any) => ({ ...f, reason: e.target.value }))}
                    className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                    {REJECTION_REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-sm font-medium text-foreground mb-1.5 block">Notes</label>
                  <textarea value={form.detail} onChange={(e) => setForm((f: any) => ({ ...f, detail: e.target.value }))} rows={3}
                    className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm" placeholder="What went wrong with the sample..." />
                </div>
                <Button variant="destructive" className="w-full gap-2" disabled={busy} onClick={() => runReject(dialog.order)}>
                  <XCircle className="w-4 h-4" /> {busy ? 'Rejecting...' : 'Reject sample'}
                </Button>
              </div>
            )}

            {dialog.type === 'recollect' && (
              <div className="space-y-4">
                <div className="p-3 rounded-xl bg-orange-500/10 border border-orange-500/20 text-sm text-orange-700 dark:text-orange-300">
                  {(dialog.order.tests || []).filter((t: any) => t.status === 'Rejected').map((t: any) => (
                    <p key={t.testName} className="flex items-center gap-2">
                      <FlaskConical className="w-3.5 h-3.5" /> {t.testName} — {t.rejectionReason || 'Rejected'} {t.recollectReason ? `(${t.recollectReason})` : ''}
                    </p>
                  ))}
                </div>
                <p className="text-xs text-muted-foreground">Rejected lines go back to “Sample Needed” so the phlebotomist can redraw.</p>
                <Button className="w-full gap-2" disabled={busy} onClick={() => runRecollect(dialog.order)}>
                  <RotateCcw className="w-4 h-4" /> {busy ? 'Requesting...' : 'Request recollection'}
                </Button>
              </div>
            )}

            <Button variant="outline" className="w-full mt-3" onClick={() => setDialog(null)}>Cancel</Button>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { FileText, Upload, CheckCircle, Send, Search, Download, Calendar, User, AlertCircle, History, RotateCcw, Loader2, GitBranch, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api, getApiBaseUrl } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const statusColors: Unmodelled = {
  'Pending Upload': 'bg-warning/10 text-warning',
  'Uploaded': 'bg-info/10 text-info',
  'Delivered': 'bg-success/10 text-success',
};

const modalClass = 'fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4';

function CorrectionsTab() {
  const qc = useQueryClient();
  const [search, setSearch] = useState('');
  const [selectedId, setSelectedId] = useState<any>(null);
  const [dlg, setDlg] = useState<any>(null);
  const [form, setForm] = useState<any>({ reason: '', testIndex: '', resultValue: '', notes: '' });

  const { data: ordersData, isLoading } = useQuery({
    queryKey: ['lab-orders'],
    queryFn: () => api.getLabOrders({}),
  });
  const orders: any[] = ordersData?.orders || [];

  const { data: versionsData, isLoading: versionsLoading } = useQuery({
    queryKey: ['lab-versions', selectedId],
    queryFn: () => api.getReportVersions(selectedId),
    enabled: Boolean(selectedId),
  });

  const correctMut = useMutation({
    mutationFn: ({ id, body }: any) => api.correctLabReport(id, body),
    onSuccess: (_d, vars: any) => {
      toast.success(`Report corrected · now version ${(versionsData?.reportVersion || 1) + 1}`);
      qc.invalidateQueries({ queryKey: ['lab-versions'] });
      qc.invalidateQueries({ queryKey: ['lab-orders'] });
      setDlg(null);
      setForm({ reason: '', testIndex: '', resultValue: '', notes: '' });
      setSelectedId(vars.id);
    },
    onError: (e: any) => toast.error(e?.message || 'Correction failed'),
  });

  const q = search.trim().toLowerCase();
  const filtered = orders.filter((o: any) =>
    !q || `${o.orderId} ${o.patientName} ${(o.tests || []).map((t: any) => t.testName).join(' ')}`.toLowerCase().includes(q));
  const selected: any = orders.find((o: any) => o._id === selectedId) || null;
  const versions: any[] = versionsData?.versions || [];

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-center gap-3">
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search order / patient / test..." className="pl-10" />
        </div>
        <p className="text-xs text-muted-foreground sm:ml-auto">
          {orders.filter((o: any) => Number(o.reportVersion || 1) > 1).length} corrected report(s) · {orders.length} order(s)
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-6">
        <div className="bg-card rounded-2xl border border-border/60 overflow-hidden lg:col-span-2">
