                    }
                    correctMut.mutate({ id: dlg._id, body });
                  }}>
                  {correctMut.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Submit correction'}
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default function LabReports() {
  const [reports, setReports] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [tab, setTab] = useState('deliveries');

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      const data = await api.getLabBookings();
      const list = Array.isArray(data) ? data : (data?.bookings || data?.data || []);
      setReports(list || []);
    } catch (e: any) {
      console.error(e);
      setReports([]);
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async (id: Unmodelled) => {
    try {
      await api.updateLabBooking(id, { reportStatus: 'Uploaded', notes: 'Report uploaded', notified: false });
      setReports(prev => prev.map(r => r._id === id ? { ...r, reportStatus: 'Uploaded', notes: 'Report uploaded', notified: false } : r));
    } catch (e: any) { console.error(e); }
  };

  const handleDownload = async (id: Unmodelled) => {
    try {
      await api.updateLabBooking(id, { notified: true });
      window.open(getApiBaseUrl() + '/lab/bookings/' + id + '/report', '_blank');
    } catch (e: any) { console.error(e); }
  };

  const handleNotify = async (id: Unmodelled) => {
    try {
      await api.updateLabBooking(id, { reportStatus: 'Delivered', notified: true });
      setReports(prev => prev.map(r => r._id === id ? { ...r, reportStatus: 'Delivered', notified: true } : r));
      await api.createNotification({ title: 'Report Ready', message: 'Your lab report is ready for download', type: 'records' });
    } catch (e: any) { console.error(e); }
  };

  const dispatch = async (id: Unmodelled) => {
    const fee = prompt('Delivery fee for this report (₹)', '40');
    const res = await api.dispatchLabReport(id, { deliveryFee: Number(fee) || 0 }).catch(() => null);
    if (!res?.task) return;
    setReports(prev => prev.map(r => r._id === id ? { ...r, reportStatus: 'Uploaded', reportDeliveryMode: 'Courier', reportDeliveryTaskId: res.task._id, courierStatus: res.task.status } : r));
  };

  const courierChip = (r: Unmodelled) => {
    const s = r.courierStatus || (r.reportDeliveryTaskId ? 'Assigned' : null);
    if (!s) return null;
    return <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-violet-500/10 text-violet-600">{s}</span>;
  };

  const filtered = reports.filter(r => {
    const ms = !search || (r.patient || '').toLowerCase().includes(search.toLowerCase());
    const mf = filter === 'All' || r.status === filter;
    return ms && mf;
  });

  if (loading) {
    return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>;
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Report Upload & Management</h1>
        <p className="text-muted-foreground">{reports.filter(r => r.status === 'Pending Upload').length} pending uploads</p>
      </div>

      <div className="flex gap-2 flex-wrap">
        {[['deliveries', 'Delivery & Notifications', Upload], ['corrections', 'Corrections & Versions', History]].map(([key, label, Icon]: any) => (
          <button key={key} onClick={() => setTab(key)}
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors flex items-center gap-2 ${tab === key ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
            <Icon className="w-4 h-4" /> {label}
          </button>
        ))}
      </div>

      {tab === 'corrections' ? <CorrectionsTab /> : (
      <div className="space-y-6">
      <div className="flex gap-2 flex-wrap">
        {['All', 'Pending Upload', 'Uploaded', 'Delivered'].map(f => (
          <button key={f} onClick={() => setFilter(f)}
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${filter === f ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
            {f} ({f === 'All' ? reports.length : reports.filter(r => r.status === f).length})
          </button>
        ))}
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search patient..." className="pl-10" />
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <FileText className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No reports found</p>
        </div>
      ) : (
        <div className="space-y-4">
          {filtered.map((r, i) => (
            <motion.div key={r._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
              className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all">
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-4">
                  <div className={`w-12 h-12 rounded-xl ${statusColors[r.status] || 'bg-muted'} flex items-center justify-center`}>
                    <FileText className="w-6 h-6" />
                  </div>
                  <div>
                    <h3 className="font-heading font-semibold text-foreground">{r.patient}</h3>
                    <div className="flex flex-wrap gap-1.5 mt-1">
                      {r.tests?.map((t: Unmodelled, j: Unmodelled) => <Badge key={j} variant="secondary" className="text-[10px]">{t}</Badge>)}
                    </div>
                    <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
                      <Calendar className="w-3 h-3" /> {r.date}
                    </div>
                  </div>
                </div>
                <div className="flex flex-col items-end gap-2">
                  <Badge className={statusColors[r.status] || 'bg-muted'}>{r.status}</Badge>
                  {courierChip(r)}
                  {r.status === 'Uploaded' && !r.notified && (
                    <span className="flex items-center gap-1 text-xs text-warning"><AlertCircle className="w-3 h-3" /> Not notified</span>
                  )}
                </div>
              </div>
              <div className="flex gap-2 mt-4 pt-3 border-t border-border/40">
                {(r.reportStatus || r.status) === 'Pending Upload' && (
                  <Button size="sm" className="flex-1 gap-1" onClick={() => handleUpload(r._id)}>
                    <Upload className="w-4 h-4" /> Upload Report
                  </Button>
                )}
                {(r.reportStatus || r.status) === 'Uploaded' && !r.notified && (
                  <Button size="sm" className="flex-1 gap-1 bg-success hover:bg-success/90" onClick={() => handleNotify(r._id)}>
                    <Send className="w-4 h-4" /> Notify Patient
                  </Button>
                )}
                {(r.reportStatus || r.status) === 'Uploaded' && r.notified && (
                  <Button size="sm" variant="outline" className="flex-1 gap-1" disabled>
                    <CheckCircle className="w-4 h-4" /> Notified
                  </Button>
                )}
                {(r.reportStatus || r.status) === 'Uploaded' && (
                  <Button size="sm" variant="outline" className="gap-1" onClick={() => dispatch(r._id)}>
                    Send by Delivery Boy
                  </Button>
                )}
                {((r.reportStatus || r.status) === 'Uploaded' || (r.reportStatus || r.status) === 'Delivered') && (
                  <Button size="sm" variant="outline" className="gap-1" onClick={() => handleDownload(r._id)}>
                    <Download className="w-4 h-4" /> Download
                  </Button>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      )}
      </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Beaker, TrendingUp, Clock, IndianRupee, BarChart3, Activity, Loader2, FileBarChart, Play, AlertTriangle, FileText, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const REPORT_TYPES = [
  'Lab Statistics',
  'Lab Turnaround Time',
  'Lab Rejection Rate',
  'Lab Outsourcing',
  'Lab Section Workload',
];

const iso = (d: Date) => d.toISOString().slice(0, 10);

function flatten(value: any, prefix = ''): Array<[string, any]> {
  const rows: Array<[string, any]> = [];
  if (value === null || value === undefined) return rows;
  if (Array.isArray(value)) {
    rows.push([prefix || 'Items', `${value.length} record(s)`]);
    return rows;
  }
  if (typeof value === 'object') {
    for (const [k, v] of Object.entries(value)) {
      const key = prefix ? `${prefix} · ${k}` : k;
      if (v !== null && typeof v === 'object' && !Array.isArray(v)) rows.push(...flatten(v, key));
      else rows.push([key, Array.isArray(v) ? `${v.length} record(s)` : String(v)]);
    }
    return rows;
  }
  rows.push([prefix || 'Value', String(value)]);
  return rows;
}

export default function LabReportsAnalytics() {
  const today = new Date();
  const [range, setRange] = useState({ from: iso(new Date(today.getTime() - 30 * 86400000)), to: iso(today) });
  const [reportType, setReportType] = useState(REPORT_TYPES[0]);

  const { data: stats, isLoading: statsLoading } = useQuery({ queryKey: ['lab-stats'], queryFn: () => api.getLabStats() });
  const { data: tat } = useQuery({ queryKey: ['lab-tat'], queryFn: () => api.labTat() });
  const { data: ordersData } = useQuery({ queryKey: ['lab-orders'], queryFn: () => api.getLabOrders({}) });

  const genMut = useMutation({
    mutationFn: () => api.generateReport({ reportType, dateFrom: range.from, dateTo: range.to }),
    onSuccess: () => toast.success('Report generated'),
    onError: (e: any) => toast.error(e?.message || 'Report generation failed'),
  });

  const allOrders: any[] = ordersData?.orders || [];

  const popularTests = Object.values(
    allOrders.reduce((acc: any, o: any) => {
      for (const t of o.tests || []) {
        const key = t.testName || 'Unknown';
        acc[key] = acc[key] || { name: key, count: 0, revenue: 0 };
        acc[key].count += 1;
        acc[key].revenue += Number(t.price || 0);
      }
      return acc;
    }, {}),
  ) as Array<{ name: string; count: number; revenue: number }>;
  popularTests.sort((a, b) => b.count - a.count);

  const totalRevenue = allOrders.reduce((s: number, o: any) => s + Number(o.totalAmount || 0), 0);
  const maxRev = popularTests[0]?.count || 1;
  const tatRows = tat?.byPriority || { STAT: {}, Urgent: {}, Routine: {} };
  const avgTat = ['STAT', 'Urgent', 'Routine'].reduce((n, p) => {
    const v = tatRows[p]?.avgHrs;
    return v == null ? n : Math.max(n, Number(v));
  }, 0);

  const report: any = genMut.data;
  const reportRows: Array<[string, any]> = report?.data ? flatten(report.data) : [];
  const reportTable: Array<Record<string, any>> = (() => {
    if (!report?.data) return [];
    const arrKey = Object.keys(report.data).find(k => Array.isArray((report.data as any)[k]) && (report.data as any)[k].length && typeof (report.data as any)[k][0] === 'object');
    return arrKey ? (report.data as any)[arrKey] : [];
  })();

  const cards = [
    { label: 'Total Tests Conducted', value: stats?.total ?? 0, icon: Beaker, cls: 'from-primary/20 to-primary/5 border-primary/20', iconCls: 'text-primary' },
    { label: 'Completed', value: stats?.completed ?? 0, icon: TrendingUp, cls: 'from-success/20 to-success/5 border-success/20', iconCls: 'text-success' },
    { label: 'Pending / Processing', value: `${stats?.pending ?? 0} / ${stats?.processing ?? 0}`, icon: Activity, cls: 'from-info/20 to-info/5 border-info/20', iconCls: 'text-info' },
    { label: 'Avg TAT (worst SLA group)', value: avgTat ? `${avgTat} hrs` : '—', icon: Clock, cls: 'from-warning/20 to-warning/5 border-warning/20', iconCls: 'text-warning' },
    { label: 'Revenue (booked)', value: `₹${totalRevenue.toLocaleString()}`, icon: IndianRupee, cls: 'from-success/20 to-success/5 border-success/20', iconCls: 'text-success' },
    { label: 'Rejected Today', value: stats?.rejectedToday ?? 0, icon: AlertTriangle, cls: 'from-destructive/20 to-destructive/5 border-destructive/20', iconCls: 'text-destructive' },
  ];

  if (statsLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-3">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Reports & Analytics</h1>
          <p className="text-muted-foreground">Lab performance metrics, TAT and generated reports</p>
        </div>
        <div className="flex flex-wrap items-end gap-2">
          <div>
            <label className="text-[11px] text-muted-foreground uppercase font-semibold">From</label>
            <Input type="date" value={range.from} onChange={e => setRange(r => ({ ...r, from: e.target.value }))} className="h-9 text-xs" />
          </div>
          <div>
            <label className="text-[11px] text-muted-foreground uppercase font-semibold">To</label>
            <Input type="date" value={range.to} onChange={e => setRange(r => ({ ...r, to: e.target.value }))} className="h-9 text-xs" />
          </div>
          <select value={reportType} onChange={e => setReportType(e.target.value)}
            className="h-9 px-3 rounded-lg border border-input bg-background text-xs">
            {REPORT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <Button size="sm" className="gap-1.5" disabled={genMut.isPending} onClick={() => genMut.mutate()}>
            {genMut.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
            Generate
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-4">
        {cards.map((c, i) => (
          <motion.div key={c.label} whileHover={{ scale: 1.02 }} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}
            className={`bg-gradient-to-br rounded-2xl border p-5 ${c.cls}`}>
            <c.icon className={`w-7 h-7 mb-2 ${c.iconCls}`} />
            <p className="text-2xl font-bold text-foreground">{c.value}</p>
            <p className="text-xs text-muted-foreground">{c.label}</p>
          </motion.div>
        ))}
      </div>

      {report && (
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }}
          className="bg-card rounded-2xl border border-primary/30 p-6">
          <div className="flex items-center gap-2 mb-1">
            <FileBarChart className="w-5 h-5 text-primary" />
            <h2 className="font-heading font-semibold text-foreground">{report.reportType}</h2>
            <Badge className="bg-primary/10 text-primary border-0 text-[10px] ml-auto">
              {report.createdAt ? new Date(report.createdAt).toLocaleString() : 'just now'}
            </Badge>
          </div>
          <p className="text-sm text-muted-foreground mb-4">{report.summary}</p>

          {reportTable.length > 0 ? (
            <div className="overflow-x-auto rounded-xl border border-border/60">
              <table className="w-full text-sm">
                <thead className="bg-muted/40 text-xs uppercase text-muted-foreground">
                  <tr>
                    {Object.keys(reportTable[0]).map(k => (
                      <th key={k} className="text-left px-4 py-2.5">{k.replace(/([A-Z])/g, ' $1').replace(/^./, s => s.toUpperCase())}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/50">
                  {reportTable.map((row, i) => (
                    <tr key={i} className="hover:bg-muted/30">
                      {Object.keys(reportTable[0]).map(k => (
                        <td key={k} className="px-4 py-2.5 text-foreground">{typeof row[k] === 'object' && row[k] !== null ? JSON.stringify(row[k]) : String(row[k] ?? '—')}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-2">
              {reportRows.map(([k, v]) => (
                <div key={k} className="flex items-center justify-between gap-4 border-b border-border/40 py-1.5">
                  <span className="text-xs text-muted-foreground">{k}</span>
                  <span className="text-sm font-medium text-foreground">{v}</span>
                </div>
              ))}
            </div>
          )}
        </motion.div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
          className="bg-card rounded-2xl border border-border/60 p-6">
          <div className="flex items-center gap-2 mb-4">
            <Clock className="w-5 h-5 text-primary" />
            <h2 className="font-heading font-semibold text-foreground">Turnaround time vs SLA</h2>
          </div>
          <div className="space-y-4">
            {(['STAT', 'Urgent', 'Routine'] as const).map((p, i) => {
              const row = tatRows[p] || { n: 0, avgHrs: null };
              const sla = tat?.slaHours?.[p] ?? 0;
              const pct = sla ? Math.min(100, ((Number(row.avgHrs) || 0) / sla) * 100) : 0;
              const breach = Number(row.avgHrs) > sla;
              return (
                <div key={p}>
                  <div className="flex justify-between text-sm mb-1">
                    <span className="font-medium text-foreground">{p} <span className="text-muted-foreground font-normal">· {row.n} test(s)</span></span>
                    <span className={breach ? 'text-destructive font-semibold' : 'text-muted-foreground'}>
                      {row.avgHrs ?? '–'} hrs / {sla} hrs SLA
                    </span>
                  </div>
                  <div className="h-2.5 bg-muted rounded-full overflow-hidden">
                    <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ delay: i * 0.06, duration: 0.5 }}
                      className={`h-full rounded-full ${breach ? 'bg-destructive' : 'bg-success'}`} />
                  </div>
                </div>
              );
            })}
            <p className="text-xs text-muted-foreground pt-1">
              {tat?.breached ?? 0} test line(s) breached SLA{tat?.slaHours ? ` (STAT <=${tat.slaHours.STAT}h · Urgent <=${tat.slaHours.Urgent}h · Routine <=${tat.slaHours.Routine}h)` : ''}
            </p>
          </div>
        </motion.div>

        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
          className="bg-card rounded-2xl border border-border/60 p-6">
          <div className="flex items-center gap-2 mb-4">
            <BarChart3 className="w-5 h-5 text-primary" />
            <h2 className="font-heading font-semibold text-foreground">Most performed tests</h2>
            <span className="ml-auto text-xs text-muted-foreground">{popularTests.length} unique</span>
          </div>
          <div className="space-y-3 max-h-72 overflow-y-auto pr-1">
            {popularTests.slice(0, 10).map((test, i) => (
              <div key={test.name} className="flex items-center gap-3">
                <span className="text-xs text-muted-foreground w-5 font-mono">{i + 1}</span>
                <div className="flex-1">
                  <div className="flex justify-between text-sm mb-1">
                    <span className="font-medium text-foreground">{test.name}</span>
                    <span className="text-muted-foreground">{test.count}</span>
                  </div>
                  <div className="h-2 bg-muted rounded-full overflow-hidden">
                    <motion.div initial={{ width: 0 }} animate={{ width: `${(test.count / maxRev) * 100}%` }} transition={{ delay: i * 0.05, duration: 0.5 }}
                      className="h-full bg-primary rounded-full" />
                  </div>
                  {test.revenue > 0 && (
                    <div className="flex justify-between text-xs text-muted-foreground mt-0.5">
                      <span>{test.count} line(s)</span>
                      <span>₹{test.revenue.toLocaleString()}</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {popularTests.length === 0 && (
              <p className="text-sm text-muted-foreground text-center py-8">No test lines yet</p>
            )}
          </div>
        </motion.div>
      </div>

      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <div className="flex items-center gap-2 mb-4">
          <FileText className="w-5 h-5 text-primary" />
          <h2 className="font-heading font-semibold text-foreground">Quick report types</h2>
        </div>
        <div className="flex flex-wrap gap-2">
          {REPORT_TYPES.map(t => (
            <Button key={t} size="sm" variant={reportType === t ? 'default' : 'outline'} className="gap-1.5 text-xs"
              onClick={() => { setReportType(t); genMut.mutate(); }} disabled={genMut.isPending}>
              <Download className="w-3.5 h-3.5" /> {t}
            </Button>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Star, Calendar, MessageSquare, Trash2 } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function LabReviews() {
  const { user } = useAuth();
  const [reviews, setReviews] = useState<ApiRow[]>([]);

  useEffect(() => {
    const fetchReviews = async () => {
      try {
        const hospitalId = user?.facilityId || user?.hospitalId || user?.id || user?._id;
        const data = await api.getReviews({ hospitalId });
        setReviews(data?.length > 0 ? data : []);
      } catch (error: any) {
        console.error(error);
        setReviews([]);
        toast.error('Failed to load reviews');
      }
    };
    fetchReviews();
  }, [user]);

  const handleDelete = async (id: Unmodelled) => {
    try {
      await api.deleteReview(id);
      setReviews(prev => prev.filter(r => r._id !== id));
      toast.success('Review deleted');
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete review');
    }
  };

  const avgRating = reviews.length > 0 ? (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1) : '0';
  const ratingDist = [5, 4, 3, 2, 1].map(r => ({
    rating: r,
    count: reviews.filter(rv => rv.rating === r).length,
    pct: reviews.length > 0 ? (reviews.filter(rv => rv.rating === r).length / reviews.length * 100) : 0,
  }));

  if (reviews.length === 0) {
    return (
      <div className="space-y-6">
        <div><h1 className="font-heading text-2xl font-bold text-foreground">Reviews & Ratings</h1><p className="text-muted-foreground">Patient feedback about your lab</p></div>
        <div className="text-center py-20 text-muted-foreground">No reviews yet</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Reviews & Ratings</h1>
        <p className="text-muted-foreground">Patient feedback about your lab services</p>
      </div>

      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <div className="flex flex-col sm:flex-row items-center gap-6">
          <div className="text-center">
            <p className="font-heading text-5xl font-extrabold text-foreground">{avgRating}</p>
            <div className="flex items-center gap-0.5 mt-1">
              {[1, 2, 3, 4, 5].map(s => (
                <Star key={s} className={`w-5 h-5 ${s <= Math.round(Number(avgRating)) ? 'text-warning fill-warning' : 'text-muted'}`} />
              ))}
            </div>
            <p className="text-sm text-muted-foreground mt-1">{reviews.length} reviews</p>
          </div>
          <div className="flex-1 w-full space-y-1.5">
            {ratingDist.map(d => (
              <div key={d.rating} className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground w-3">{d.rating}</span>
                <Star className="w-3 h-3 text-warning fill-warning" />
                <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                  <div className="h-full bg-warning rounded-full transition-all" style={{ width: `${d.pct}%` }} />
                </div>
                <span className="text-xs text-muted-foreground w-6 text-right">{d.count}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {reviews.map((rv, i) => (
          <motion.div key={rv._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
            className="bg-card rounded-2xl border border-border/60 p-5">
            <div className="flex items-start justify-between mb-2">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary font-bold">
                  {rv.patientName?.charAt(0)}
                </div>
                <div>
                  <p className="font-medium text-foreground">{rv.patientName}</p>
                  <div className="flex items-center gap-0.5">
                    {[1, 2, 3, 4, 5].map(s => (
                      <Star key={s} className={`w-3.5 h-3.5 ${s <= rv.rating ? 'text-warning fill-warning' : 'text-muted'}`} />
                    ))}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={() => handleDelete(rv._id)} className="text-muted-foreground hover:text-destructive transition-colors">
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
                <div className="flex items-center gap-1 text-xs text-muted-foreground">
                  <Calendar className="w-3.5 h-3.5" />{rv.date}
                </div>
              </div>
            </div>
            {rv.comment && (
              <div className="flex items-start gap-2 mt-3">
                <MessageSquare className="w-4 h-4 text-muted-foreground mt-0.5 flex-shrink-0" />
                <p className="text-sm text-muted-foreground">{rv.comment}</p>
              </div>
            )}
          </motion.div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { MapPin, User, ClipboardList, CheckCircle, Truck, Search, FlaskConical, CalendarDays, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

// Statuses must match the LabBooking model enum — earlier this page used a
// private vocabulary (Requested/Assigned/Collected/Received at Lab) that the
// backend dropped, so every assignment silently no-opped.
const statusColors: Unmodelled = {
  Pending: 'bg-primary/10 text-primary',
  Confirmed: 'bg-warning/10 text-warning',
  'Sample Collected': 'bg-info/10 text-info',
  Processing: 'bg-success/10 text-success',
  Completed: 'bg-success/10 text-success',
};

const nextStatus: Unmodelled = { Pending: 'Confirmed', Confirmed: 'Sample Collected', 'Sample Collected': 'Processing' };

const mapBooking = (b: Unmodelled, i: Unmodelled) => ({
  id: b._id || `col_${i}`,
  patient: b.patientName || b.patient || 'Unknown',
  address: b.homeCollectionAddress || b.address || '',
  tests: b.tests || [],
  status: b.status || 'Pending',
  phlebotomist: b.phlebotomist || '',
  requestedDate: (b.bookingDate ? String(b.bookingDate).split('T')[0] : '') || b.createdAt?.split('T')[0] || '',
  time: b.timeSlot || b.time || '',
});

export default function LabSampleCollection() {
  const [collections, setCollections] = useState<ApiRow[]>([]);
  const [phlebotomists, setPhlebotomists] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [assigning, setAssigning] = useState<Unmodelled>(null);

  useEffect(() => {
    Promise.all([
      api.getLabBookings({}),
      api.getLabPhlebotomists().catch(() => ({ phlebotomists: [] })),
    ])
      .then(([res, staff]) => {
        setCollections((res.bookings || []).map(mapBooking));
        setPhlebotomists((staff.phlebotomists || []).map((p: Unmodelled) => p.name).filter(Boolean));
      })
      .catch((e) => { console.error(e); toast.error('Failed to load collections'); })
      .finally(() => setLoading(false));
  }, []);

  const assignPhlebotomist = async (id: Unmodelled, name: Unmodelled) => {
    try {
      await api.updateLabBooking(id, { phlebotomist: name, status: 'Confirmed' });
      setCollections(prev => prev.map(c => c.id === id ? { ...c, phlebotomist: name, status: 'Confirmed' } : c));
      toast.success(`Assigned to ${name}`);
    } catch (e: any) { console.error(e); toast.error('Assignment failed'); }
    setAssigning(null);
  };

  const advanceStatus = async (id: Unmodelled) => {
    try {
      const c = collections.find(c => c.id === id);
      const next = nextStatus[c?.status] || c?.status;
      await api.updateLabBooking(id, { status: next });
      setCollections(prev => prev.map(c => c.id === id ? { ...c, status: next } : c));
      toast.success(`Status updated to ${next}`);
    } catch (e: any) { console.error(e); toast.error('Status update failed'); }
  };

  const filtered = collections.filter(c =>
    c.patient.toLowerCase().includes(search.toLowerCase()) ||
    c.address.toLowerCase().includes(search.toLowerCase()) ||
    c.tests.some((t: Unmodelled) => t.toLowerCase().includes(search.toLowerCase()))
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Sample Collection</h1>
        <p className="text-muted-foreground">Manage home collection requests</p>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center mb-2">
            <ClipboardList className="w-5 h-5 text-primary" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{collections.filter(c => c.status === 'Pending').length}</p>
          <p className="text-sm text-muted-foreground">Awaiting Assignment</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-warning/10 flex items-center justify-center mb-2">
            <User className="w-5 h-5 text-warning" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{collections.filter(c => c.status === 'Confirmed').length}</p>
          <p className="text-sm text-muted-foreground">Assigned</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-info/10 flex items-center justify-center mb-2">
            <CheckCircle className="w-5 h-5 text-info" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{collections.filter(c => c.status === 'Sample Collected').length}</p>
          <p className="text-sm text-muted-foreground">Collected Today</p>
        </motion.div>
        <motion.div whileHover={{ scale: 1.02 }} className="bg-card rounded-2xl border border-border/60 p-5">
          <div className="w-10 h-10 rounded-xl bg-success/10 flex items-center justify-center mb-2">
            <Truck className="w-5 h-5 text-success" />
          </div>
          <p className="font-heading text-2xl font-bold text-foreground">{collections.filter(c => c.status === 'Processing').length}</p>
          <p className="text-sm text-muted-foreground">Received at Lab</p>
        </motion.div>
      </div>

      <div className="relative flex-1 min-w-[200px] max-w-sm">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input placeholder="Search patient, address, or test..." className="pl-10" value={search} onChange={e => setSearch(e.target.value)} />
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20">
          <FlaskConical className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
          <p className="text-muted-foreground">No collection requests found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filtered.map((c, i) => (
            <motion.div key={c.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
              className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h3 className="font-heading font-semibold text-foreground">{c.patient}</h3>
                  <p className="text-xs text-muted-foreground flex items-center gap-1 mt-1">
                    <MapPin className="w-3 h-3" /> {c.address || 'Address not set'}
                  </p>
                </div>
                <Badge className={`${statusColors[c.status]} border-0`}>{c.status}</Badge>
              </div>
              <div className="flex flex-wrap gap-1.5 mb-3">
                {c.tests.map((t: Unmodelled) => (
                  <span key={t} className="text-xs px-2 py-0.5 rounded-full bg-muted text-muted-foreground">{t}</span>
                ))}
              </div>
              <div className="flex items-center gap-3 text-xs text-muted-foreground mb-4">
                <span className="flex items-center gap-1"><CalendarDays className="w-3 h-3" /> {c.requestedDate}</span>
                <span className="flex items-center gap-1"><User className="w-3 h-3" /> {c.phlebotomist || 'Unassigned'}</span>
              </div>
              <div className="flex gap-2">
                {c.status === 'Pending' && (
                  <div className="flex gap-2 w-full">
                    <Button size="sm" variant="outline" className="flex-1" onClick={() => setAssigning(assigning === c.id ? null : c.id)}>
                      Assign Phlebotomist
                    </Button>
                  </div>
                )}
                {c.status === 'Confirmed' && (
                  <Button size="sm" className="flex-1 gap-1" onClick={() => advanceStatus(c.id)}>
                    <CheckCircle className="w-3.5 h-3.5" /> Mark Collected
                  </Button>
                )}
                {c.status === 'Sample Collected' && (
                  <Button size="sm" className="flex-1 gap-1" onClick={() => advanceStatus(c.id)}>
                    <Truck className="w-3.5 h-3.5" /> Receive at Lab
                  </Button>
                )}
                {c.status === 'Processing' && (
                  <span className="flex-1 text-center text-xs text-success font-medium py-2">Received ✓</span>
                )}
              </div>
              {assigning === c.id && (
                <div className="mt-3 pt-3 border-t border-border/40">
                  <p className="text-xs font-medium text-foreground mb-2">Select Phlebotomist</p>
                  {phlebotomists.length === 0 ? (
                    <p className="text-xs text-muted-foreground">No active phlebotomists found — invite users with the Phlebotomist role.</p>
                  ) : (
                    <div className="flex flex-wrap gap-2">
                      {phlebotomists.map((p: Unmodelled)  => (
                        <button key={p} onClick={() => assignPhlebotomist(c.id, p)}
                          className="px-3 py-1.5 text-xs font-medium rounded-lg bg-muted text-muted-foreground hover:bg-primary hover:text-primary-foreground transition-colors">
                          {p}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Search, TestTube, Loader2, ScanLine, CheckCircle2, AlertTriangle, FlaskConical, Truck, Clock, XCircle, PackageCheck } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const STATUS_CLS: any = {
  Ordered: 'bg-muted text-muted-foreground',
  'Sample Needed': 'bg-warning/10 text-warning',
  'Sample Collected': 'bg-info/10 text-info',
  Rejected: 'bg-destructive/10 text-destructive',
  Received: 'bg-primary/10 text-primary',
  Processing: 'bg-info/10 text-info',
  'Under Verification': 'bg-warning/10 text-warning',
  Verified: 'bg-success/10 text-success',
  'Report Delivered': 'bg-success/10 text-success',
};

const timeline = (t: any) => [
  { label: 'Collected', at: t.sampleCollectedAt, icon: TestTube },
  { label: 'Received', at: t.receivedAt, icon: PackageCheck },
  { label: 'Result entered', at: t.resultEnteredAt, icon: FlaskConical },
  { label: 'Verified', at: t.verifiedAt, icon: CheckCircle2 },
];

export default function LabSampleTracking() {
  const [search, setSearch] = useState('');
  const [scan, setScan] = useState('');
  const [selected, setSelected] = useState<any | null>(null);

  const { data: worklist, isLoading } = useQuery({
    queryKey: ['lab-worklist'],
    queryFn: () => api.getLabWorklist({ limit: 200 }),
  });
  const { data: ordersData } = useQuery({ queryKey: ['lab-orders'], queryFn: () => api.getLabOrders({}) });
  const { data: receiving } = useQuery({ queryKey: ['lab-receiving'], queryFn: () => api.getLabReceiving({}) });

  const rows: any[] = worklist?.rows || worklist?.items || (Array.isArray(worklist) ? worklist : []);
  const orders: any[] = ordersData?.orders || [];
  const pendingReceipt = receiving?.total ?? rows.filter(r => !r.receivedAt).length;

  const orderById = useMemo(() => orders.reduce((m: any, o: any) => { m[o._id] = o; return m; }, {}), [orders]);

  const q = search.trim().toLowerCase();
  const filtered = rows.filter((r: any) => {
    if (!q) return true;
    return `${r.sampleId} ${r.sampleNo} ${r.orderNo} ${r.patientName} ${r.testName} ${r.section} ${r.status}`.toLowerCase().includes(q);
  });

  const counts = {
    total: rows.length,
    pending: rows.filter((r: any) => !r.receivedAt && r.status !== 'Rejected').length,
    processing: rows.filter((r: any) => ['Received', 'Processing', 'Under Verification'].includes(r.status)).length,
    rejected: rows.filter((r: any) => r.status === 'Rejected').length,
    verified: rows.filter((r: any) => ['Verified', 'Report Delivered'].includes(r.status)).length,
    outsourced: rows.filter((r: any) => r.outsourced).length,
  };

  const cards = [
    { label: 'Samples tracked', value: counts.total, icon: TestTube, cls: 'text-primary' },
    { label: 'Awaiting receipt', value: counts.pending, icon: Clock, cls: 'text-warning' },
    { label: 'In process', value: counts.processing, icon: FlaskConical, cls: 'text-info' },
    { label: 'Rejected', value: counts.rejected, icon: XCircle, cls: 'text-destructive' },
    { label: 'Verified', value: counts.verified, icon: CheckCircle2, cls: 'text-success' },
    { label: 'Outsourced', value: counts.outsourced, icon: Truck, cls: 'text-violet-500' },
  ];

  const openOrder = (row: any) => {
    const order = orderById[row.orderId];
    if (!order) return;
    const test = (order.tests || [])[row.testIndex];
    if (!test) return;
    setSelected({ order, test, testIndex: row.testIndex });
  };

  const handleScan = (e: React.FormEvent) => {
    e.preventDefault();
    const code = scan.trim().toLowerCase();
    if (!code) return;
    const hit = rows.find((r: any) =>
      [r.sampleId, r.sampleNo, r.orderNo].filter(Boolean).some((v: any) => String(v).toLowerCase() === code));
    if (hit) { openOrder(hit); setScan(''); }
    else toast.error('No sample matches that barcode');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col lg:flex-row lg:items-end gap-3">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Sample Tracking</h1>
          <p className="text-muted-foreground">Chain of custody from collection to verification</p>
        </div>
        <div className="flex flex-1 flex-wrap gap-2 lg:justify-end">
          <form onSubmit={handleScan} className="relative w-full sm:w-72">
            <ScanLine className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input value={scan} onChange={e => setScan(e.target.value)} placeholder="Scan barcode / sample ID..." className="pl-10" />
          </form>
          <div className="relative w-full sm:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Filter by sample, order, patient..." className="pl-10" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-4">
        {cards.map((c, i) => (
          <motion.div key={c.label} whileHover={{ scale: 1.02 }} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}
            className="bg-card rounded-2xl border border-border/60 p-4">
            <c.icon className={`w-6 h-6 mb-2 ${c.cls}`} />
            <p className="text-2xl font-bold text-foreground">{c.value}</p>
            <p className="text-[11px] text-muted-foreground uppercase font-semibold">{c.label}</p>
          </motion.div>
        ))}
      </div>

      <div className="bg-card rounded-2xl border border-border/60 overflow-hidden">
        <div className="flex items-center gap-2 px-5 py-4 border-b border-border/60">
          <TestTube className="w-4 h-4 text-primary" />
          <p className="text-sm font-semibold text-foreground">Sample register</p>
          <span className="ml-auto text-xs text-muted-foreground">
            {filtered.length} of {rows.length} sample line(s) · {pendingReceipt} awaiting receipt
          </span>
        </div>
        <div className="overflow-x-auto max-h-[540px] overflow-y-auto">
          <table className="w-full text-sm">
            <thead className="bg-muted/40 text-xs uppercase text-muted-foreground sticky top-0">
              <tr>
                <th className="text-left px-5 py-3">Sample</th>
                <th className="text-left px-5 py-3">Order</th>
                <th className="text-left px-5 py-3">Patient</th>
                <th className="text-left px-5 py-3">Test</th>
                <th className="text-left px-5 py-3">Section</th>
                <th className="text-left px-5 py-3">Status</th>
                <th className="text-left px-5 py-3">Received</th>
                <th className="text-right px-5 py-3">Detail</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/50">
              {filtered.map((r: any) => (
                <tr key={`${r.orderId}-${r.testIndex}`} className="hover:bg-muted/30">
                  <td className="px-5 py-3">
                    <p className="font-mono text-xs font-semibold text-foreground">{r.sampleId || '—'}</p>
                    <p className="text-[11px] text-muted-foreground">{r.sampleNo || 'no barcode'}</p>
                  </td>
                  <td className="px-5 py-3 font-mono text-xs text-foreground">{r.orderNo}</td>
                  <td className="px-5 py-3 font-medium text-foreground">{r.patientName}</td>
                  <td className="px-5 py-3 text-foreground">{r.testName}</td>
                  <td className="px-5 py-3 text-xs text-muted-foreground">{r.section || 'Unsectioned'}</td>
                  <td className="px-5 py-3">
                    <Badge className={`${STATUS_CLS[r.status] || 'bg-muted text-muted-foreground'} border-0 text-[10px]`}>{r.status}</Badge>
                    {r.outsourced && <Badge className="bg-violet-500/10 text-violet-600 border-0 text-[10px] ml-1">Outsourced</Badge>}
                  </td>
                  <td className="px-5 py-3 text-xs text-muted-foreground">
                    {r.receivedAt ? new Date(r.receivedAt).toLocaleString() : <span className="text-warning">Not received</span>}
                  </td>
                  <td className="px-5 py-3 text-right">
                    <Button size="sm" variant="outline" className="text-xs" onClick={() => openOrder(r)}>Open</Button>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={8} className="px-5 py-12 text-center text-muted-foreground">
                    <AlertTriangle className="w-10 h-10 mx-auto mb-2 opacity-30" />
                    No samples match this filter
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selected && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setSelected(null)}>
          <div className="bg-card rounded-2xl border p-6 max-w-2xl w-full shadow-2xl max-h-[85vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <div className="flex items-start gap-3 mb-5">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                <TestTube className="w-5 h-5 text-primary" />
              </div>
              <div className="flex-1">
                <h3 className="font-semibold text-foreground">{selected.test.testName}</h3>
                <p className="text-xs text-muted-foreground">
                  {selected.order.orderId} · {selected.order.patientName} · {selected.order.priority} · {selected.order.status}
                </p>
              </div>
              <Button size="sm" variant="outline" onClick={() => setSelected(null)}>Close</Button>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-5">
              <div className="rounded-xl border border-border/60 p-3">
                <p className="text-[11px] uppercase text-muted-foreground font-semibold">Sample ID</p>
                <p className="text-sm font-mono font-semibold text-foreground">{selected.test.sampleId || '—'}</p>
              </div>
              <div className="rounded-xl border border-border/60 p-3">
                <p className="text-[11px] uppercase text-muted-foreground font-semibold">Sample No</p>
                <p className="text-sm font-mono font-semibold text-foreground">{selected.test.sampleNo || '—'}</p>
              </div>
              <div className="rounded-xl border border-border/60 p-3">
                <p className="text-[11px] uppercase text-muted-foreground font-semibold">Section</p>
                <p className="text-sm font-semibold text-foreground">{selected.test.section || 'Unsectioned'}</p>
              </div>
              <div className="rounded-xl border border-border/60 p-3">
                <p className="text-[11px] uppercase text-muted-foreground font-semibold">Status</p>
                <Badge className={`${STATUS_CLS[selected.test.status] || 'bg-muted text-muted-foreground'} border-0 text-[10px] mt-1`}>{selected.test.status}</Badge>
              </div>
              <div className="rounded-xl border border-border/60 p-3">
                <p className="text-[11px] uppercase text-muted-foreground font-semibold">Recollected</p>
                <p className="text-sm font-semibold text-foreground">{selected.test.recollectCount || 0}×</p>
              </div>
              <div className="rounded-xl border border-border/60 p-3">
                <p className="text-[11px] uppercase text-muted-foreground font-semibold">Rejected</p>
                <p className="text-sm font-semibold text-foreground">{selected.test.rejectionReason || 'No'}</p>
              </div>
            </div>

            <p className="text-xs uppercase text-muted-foreground font-semibold mb-3">Chain of custody</p>
            <ol className="space-y-3 mb-5">
              {timeline(selected.test).map(s => (
                <li key={s.label} className="flex items-center gap-3">
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${s.at ? 'bg-success/10' : 'bg-muted'}`}>
                    <s.icon className={`w-4 h-4 ${s.at ? 'text-success' : 'text-muted-foreground'}`} />
                  </div>
                  <div className="flex-1">
                    <p className={`text-sm font-medium ${s.at ? 'text-foreground' : 'text-muted-foreground'}`}>{s.label}</p>
                    <p className="text-[11px] text-muted-foreground">{s.at ? new Date(s.at).toLocaleString() : 'pending'}</p>
                  </div>
                </li>
              ))}
            </ol>

            {selected.test.outsourced?.lab && (
              <div className="rounded-xl border border-violet-500/30 bg-violet-500/5 p-3 mb-5">
                <p className="text-xs font-semibold text-violet-600 mb-1">Outsourced to {selected.test.outsourced.lab}</p>
                <p className="text-xs text-muted-foreground">
                  Status: {selected.test.outsourced.status || 'Dispatched'}
                  {selected.test.outsourced.courierName ? ` · Courier ${selected.test.outsourced.courierName}` : ''}
                  {selected.test.outsourced.trackingNo ? ` · ${selected.test.outsourced.trackingNo}` : ''}
                </p>
              </div>
            )}

            <div className="flex justify-end gap-2">
              <Button size="sm" variant="outline" asChild>
                <a href={`/lab/ops?order=${selected.order._id}`}>Open in receiving</a>
              </Button>
              <Button size="sm" onClick={() => setSelected(null)}>Done</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link, useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Microscope, ClipboardList, Clock, CheckCircle2, XCircle, ExternalLink, Loader2, Timer, AlertTriangle, Layers } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { api } from '@/lib/api';

const SECTION_LIST = ['Biochemistry', 'Hematology', 'Clinical Pathology', 'Microbiology', 'Histopathology', 'Cytology', 'Serology', 'Molecular'];

const STATUS_COLORS: any = {
  Ordered: 'bg-muted text-muted-foreground',
  'Sample Needed': 'bg-warning/10 text-warning',
  'Sample Collected': 'bg-info/10 text-info',
  Processing: 'bg-info/10 text-info',
  'Result Pending': 'bg-warning/10 text-warning',
  Completed: 'bg-purple-500/10 text-purple-600',
  Verified: 'bg-success/10 text-success',
  'Report Delivered': 'bg-success/10 text-success',
  Rejected: 'bg-destructive/10 text-destructive',
  Recollect: 'bg-orange-500/10 text-orange-600',
};

const PRIORITY_COLORS: any = {
  Routine: 'bg-muted text-muted-foreground',
  Urgent: 'bg-warning/10 text-warning',
  STAT: 'bg-destructive/10 text-destructive',
};

const CULTURE_STAGES: any = {
  Ordered: 'Awaiting specimen',
  'Sample Needed': 'Awaiting specimen',
  'Sample Collected': 'Plated / inoculated',
  Processing: 'Culture in progress',
  'Result Pending': 'Read & ID pending',
  Completed: 'Culture complete',
  Verified: 'Report released',
  'Report Delivered': 'Report released',
  Rejected: 'Specimen rejected',
};

const HISTO_STAGES: any = {
  Ordered: 'Awaiting grossing',
  'Sample Needed': 'Awaiting grossing',
  'Sample Collected': 'Grossing',
  Processing: 'Processing / embedding',
  'Result Pending': 'Blocks & slides ready',
  Completed: 'Slides stained',
  Verified: 'Slides signed out',
  'Report Delivered': 'Slides signed out',
  Rejected: 'Specimen rejected',
};

interface LabSectionWorkbenchProps {
  section?: string;
}

export default function LabSectionWorkbench(props: LabSectionWorkbenchProps) {
  const { section: routeSection } = useParams<{ section?: string }>();
  const section = props.section || (routeSection ? decodeURIComponent(routeSection) : 'Biochemistry');
  const [tab, setTab] = useState<'overview' | 'worklist'>('worklist');
  const [statusFilter, setStatusFilter] = useState('All');

  const { data: worklistData, isLoading } = useQuery({
    queryKey: ['lab-worklist', section],
    queryFn: () => api.getLabWorklist({ section, limit: 200 }),
  });
  const { data: sectionsData } = useQuery({ queryKey: ['lab-sections'], queryFn: () => api.getLabSections() });
  const { data: tat } = useQuery({ queryKey: ['lab-tat'], queryFn: () => api.labTat() });

  const rows: any[] = worklistData?.worklist || [];
  const sections: any[] = sectionsData?.sections || [];
  const mine = sections.find((s: any) => s.section === section) || { section, tests: 0, pending: 0, verified: 0, rejected: 0 };
  const slaHours: any = tat?.slaHours || { STAT: 2, Urgent: 6, Routine: 24 };

  const filtered = rows.filter((r: any) => statusFilter === 'All' || r.status === statusFilter);

  const dueInfo = (r: any) => {
    if (!r.receivedAt) return { label: '—', overdue: false };
    const sla = slaHours[r.priority] || slaHours.Routine || 24;
    const due = new Date(r.receivedAt).getTime() + sla * 3600000;
    const left = due - Date.now();
    if (left < 0) return { label: `overdue ${Math.max(1, Math.round(-left / 3600000))}h`, overdue: true };
    if (left < 3600000) return { label: `due in ${Math.max(1, Math.round(left / 60000))}m`, overdue: false };
    return { label: `due in ${Math.round(left / 3600000)}h`, overdue: false };
  };

  const statusCounts = rows.reduce((acc: any, r: any) => { acc[r.status] = (acc[r.status] || 0) + 1; return acc; }, {});

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground flex items-center gap-2">
            <Microscope className="w-6 h-6 text-primary" /> {section} Workbench
          </h1>
          <p className="text-muted-foreground">Section worklist, TAT tracking and bench actions</p>
        </div>
        <div className="flex gap-1 p-1 bg-muted/50 rounded-2xl border border-border/50 self-start">
          {(['overview', 'worklist'] as const).map(t => (
            <button key={t} onClick={() => setTab(t)}
              className={`px-4 py-1.5 rounded-xl text-xs font-semibold transition-all capitalize ${tab === t ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap gap-1.5">
        {SECTION_LIST.map(s => (
          <span key={s}
            className={`px-3 py-1 rounded-full text-xs font-semibold border ${s === section ? 'bg-primary text-primary-foreground border-primary' : 'bg-muted text-muted-foreground border-border/60'}`}>
            {s}
          </span>
        ))}
      </div>

      {tab === 'overview' ? (
        <div className="space-y-6">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {[
              { label: 'Tests in section', value: mine.tests, icon: Layers, cls: 'bg-primary/10 text-primary' },
              { label: 'Pending', value: mine.pending, icon: Clock, cls: 'bg-warning/10 text-warning' },
              { label: 'Verified', value: mine.verified, icon: CheckCircle2, cls: 'bg-success/10 text-success' },
              { label: 'Rejected', value: mine.rejected, icon: XCircle, cls: 'bg-destructive/10 text-destructive' },
            ].map((c, i) => (
              <motion.div key={c.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                className="bg-card rounded-2xl border border-border/60 p-5">
                <div className={`w-9 h-9 rounded-xl flex items-center justify-center mb-2 ${c.cls}`}>
                  <c.icon className="w-4.5 h-4.5" />
                </div>
                <p className="font-heading text-2xl font-bold text-foreground">{c.value}</p>
                <p className="text-[11px] text-muted-foreground uppercase font-semibold">{c.label}</p>
              </motion.div>
            ))}
          </div>

          <div className="bg-card rounded-2xl border border-border/60 p-6">
            <div className="flex items-center gap-2 mb-4">
              <ClipboardList className="w-5 h-5 text-primary" />
              <h2 className="font-heading font-semibold text-foreground">Live status split</h2>
            </div>
            {Object.keys(statusCounts).length === 0 ? (
              <p className="text-sm text-muted-foreground">No test lines in this section yet.</p>
            ) : (
              <div className="space-y-3">
                {Object.entries(statusCounts).map(([st, n]: any) => {
                  const pct = rows.length ? Math.round((n / rows.length) * 100) : 0;
                  return (
                    <div key={st}>
                      <div className="flex justify-between text-sm mb-1">
                        <span className="font-medium text-foreground">{st}</span>
                        <span className="text-muted-foreground">{n} ({pct}%)</span>
                      </div>
                      <div className="h-2 bg-muted rounded-full overflow-hidden">
                        <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ duration: 0.5 }}
                          className="h-full bg-primary rounded-full" />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className="bg-card rounded-2xl border border-border/60 p-6">
            <div className="flex items-center gap-2 mb-4">
              <Timer className="w-5 h-5 text-primary" />
              <h2 className="font-heading font-semibold text-foreground">TAT targets</h2>
            </div>
            <div className="flex flex-wrap gap-2 text-xs">
              {Object.entries(slaHours).map(([p, h]: any) => (
                <span key={p} className="rounded-md border border-border/60 px-2.5 py-1.5">
                  <b>{p}</b> · {h}h SLA
                </span>
              ))}
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex flex-wrap gap-1.5">
            {['All', ...Object.keys(statusCounts)].map(f => (
              <button key={f} onClick={() => setStatusFilter(f)}
                className={`px-3 py-1.5 rounded-xl text-xs font-medium transition-colors ${statusFilter === f ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                {f} <span className="opacity-70">({f === 'All' ? rows.length : statusCounts[f]})</span>
              </button>
            ))}
          </div>

          <div className="bg-card rounded-2xl border border-border/60 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-muted/40 text-xs uppercase text-muted-foreground">
                  <tr>
                    <th className="text-left px-4 py-3">Patient / Order</th>
                    <th className="text-left px-4 py-3">Test</th>
                    <th className="text-left px-4 py-3">Priority</th>
                    <th className="text-left px-4 py-3">Status</th>
                    <th className="text-left px-4 py-3">Received</th>
                    <th className="text-left px-4 py-3">TAT</th>
                    {section === 'Microbiology' && <th className="text-left px-4 py-3">Culture</th>}
                    {section === 'Histopathology' && <th className="text-left px-4 py-3">Grossing / Blocks / Slides</th>}
                    <th className="text-right px-4 py-3">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/50">
                  {filtered.map((r: any, i: number) => {
                    const due = dueInfo(r);
                    return (
                      <tr key={`${r.orderId}-${r.testIndex}-${i}`} className="hover:bg-muted/30">
                        <td className="px-4 py-3">
                          <p className="font-medium text-foreground">{r.patientName}</p>
                          <p className="text-[11px] text-muted-foreground font-mono">{r.orderNo} {r.sampleNo ? `· ${r.sampleNo}` : ''}</p>
                        </td>
                        <td className="px-4 py-3">
                          <p className="text-foreground">{r.testName}</p>
                          <p className="text-[11px] text-muted-foreground">{r.doctorName || '—'}</p>
                        </td>
                        <td className="px-4 py-3">
                          <Badge className={`${PRIORITY_COLORS[r.priority] || ''} border-0 text-[10px]`}>{r.priority}</Badge>
                        </td>
                        <td className="px-4 py-3">
                          <Badge className={`${STATUS_COLORS[r.status] || 'bg-muted text-muted-foreground'} border-0 text-[10px]`}>{r.status}</Badge>
                          {r.outsourced && <Badge className="ml-1 border-0 text-[10px] bg-violet-500/10 text-violet-600">Outsourced</Badge>}
                        </td>
                        <td className="px-4 py-3 text-xs text-muted-foreground">
                          {r.receivedAt ? new Date(r.receivedAt).toLocaleString() : 'Not received'}
                        </td>
                        <td className="px-4 py-3">
                          <span className={`text-xs font-semibold ${due.overdue ? 'text-destructive' : 'text-muted-foreground'}`}>
                            {due.overdue && <AlertTriangle className="w-3 h-3 inline mr-1" />}
                            {due.label}
                          </span>
                        </td>
                        {section === 'Microbiology' && (
                          <td className="px-4 py-3 text-xs text-muted-foreground">{CULTURE_STAGES[r.status] || '—'}</td>
                        )}
                        {section === 'Histopathology' && (
                          <td className="px-4 py-3 text-xs text-muted-foreground">{HISTO_STAGES[r.status] || '—'}</td>
                        )}
                        <td className="px-4 py-3 text-right">
                          <Button size="sm" variant="outline" className="gap-1 text-xs" asChild>
                            <Link to="/lab">
                              <ExternalLink className="w-3.5 h-3.5" /> Open
                            </Link>
                          </Button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            {filtered.length === 0 && (
              <div className="text-center py-14">
                <ClipboardList className="w-12 h-12 mx-auto text-muted-foreground/30 mb-3" />
                <p className="text-muted-foreground">No worklist items for {section}</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User, Mail, Phone, Shield, Plus, X, Save, Edit2, Users, Stethoscope, Microscope, Eye, Syringe } from 'lucide-react';
import { Button } from '@/components/ui/button';
