export default function LabStaff() {
  const [staffList, setStaffList] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState<Unmodelled>(null);
  const [deleteTarget, setDeleteTarget] = useState<Unmodelled>(null);
  const [form, setForm] = useState({ name:'', role:'', email:'', phone:'', department:'', qualification:'', status:'Active', joinDate:'' });

  useEffect(() => {
    fetchStaff();
  }, []);

  const fetchStaff = async () => {
    try {
      setLoading(true);
      const data = await api.getStaff();
      setStaffList(Array.isArray(data) ? data : (data?.staff || []));
    } catch (error: any) {
      console.error(error);
      setStaffList([]);
      toast.error('Failed to load staff list');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: Unmodelled) => {
    e.preventDefault();
    if (!form.name || !form.role) { toast.error('Name and Role are required'); return; }

    try {
      if (editId) {
        await api.updateStaff(editId, form);
        toast.success('Staff updated');
      } else {
        await api.createStaff(form);
        toast.success('Staff added');
      }
      fetchStaff();
      setShowForm(false); 
      setEditId(null); 
      setForm({ name:'', role:'', email:'', phone:'', department:'', qualification:'', status:'Active', joinDate:'' });
    } catch (error: any) {
      toast.error(error.message || 'An error occurred while saving staff');
    }
  };

  const handleEdit = (staff: Unmodelled) => { 
    setForm(staff); 
    setEditId(staff._id || staff.id); 
    setShowForm(true); 
  };

  const handleDelete = async (id: Unmodelled) => {
    try {
      await api.deleteStaff(id);
      toast.success('Staff removed');
      fetchStaff();
    } catch (error: any) {
      toast.error(error.message || 'Failed to remove staff');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Staff Management</h1>
          <p className="text-muted-foreground mt-1">{staffList.length} team members</p>
        </div>
        <Button onClick={() => { setEditId(null); setForm({ name:'', role:'', email:'', phone:'', department:'', qualification:'', status:'Active', joinDate:'' }); setShowForm(true); }}>
          <Plus className="w-4 h-4 mr-2" /> Add Staff
        </Button>
      </div>

      {showForm && (
        <Card className="rounded-2xl border-border/50">
          <CardContent className="p-6">
            <h2 className="font-heading font-bold text-lg mb-4">{editId ? 'Edit Staff' : 'Add New Staff'}</h2>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[ {key:'name', label:'Full Name'}, {key:'role', label:'Role'}, {key:'email', label:'Email', type:'email'}, {key:'phone', label:'Phone'}, {key:'department', label:'Department'}, {key:'qualification', label:'Qualification'}, {key:'joinDate', label:'Join Date', type:'date'} ].map(f => (
                <div key={f.key}>
                  <label className="text-sm font-medium mb-1 block">{f.label}</label>
                  <Input type={f.type || 'text'} value={(form as Unmodelled)[f.key]} onChange={e => setForm({...form, [f.key]: e.target.value})} required={f.key === 'name' || f.key === 'role'} />
                </div>
              ))}
              <div>
                <label className="text-sm font-medium mb-1 block">Status</label>
                <select value={form.status} onChange={e => setForm({...form, status: e.target.value})} className="w-full h-10 px-3 rounded-xl border border-input bg-background text-sm">{['Active', 'On Leave', 'Inactive'].map(s => <option key={s} value={s}>{s}</option>)}</select>
              </div>
              <div className="md:col-span-2 lg:col-span-3 flex gap-3 pt-2">
                <Button type="submit"><Save className="w-4 h-4 mr-1" /> {editId ? 'Update' : 'Add'} Staff</Button>
                <Button type="button" variant="outline" onClick={() => { setShowForm(false); setEditId(null); }}>Cancel</Button>
              </div>
            </form>
          </CardContent>
        </Card>
      )}

      {!loading && staffList.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          <Users className="w-12 h-12 mx-auto mb-3 opacity-40" />
          <p className="font-medium">No staff members yet</p>
          <p className="text-sm mt-1">Click "Add Staff" to add your first team member</p>
        </div>
      ) : (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {staffList.map(staff => (
          <motion.div key={staff._id || staff.id} layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="bg-card rounded-2xl border border-border/50 overflow-hidden hover:shadow-lg transition-all">
            <div className="bg-gradient-to-r from-primary/10 to-primary/5 p-5 flex items-center gap-4">
              <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center shrink-0">
                <span className="text-primary-foreground font-bold text-lg">{staff.name.split(' ').map((n: Unmodelled)=>n[0]).join('').slice(0,2)}</span>
              </div>
              <div className="min-w-0">
                <p className="font-semibold text-foreground truncate">{staff.name}</p>
                <p className="text-sm text-primary">{staff.role}</p>
              </div>
            </div>
            <div className="p-4 space-y-3">
              <div className="flex items-center gap-2 text-sm text-muted-foreground"><Mail className="w-3.5 h-3.5" /> {staff.email}</div>
              <div className="flex items-center gap-2 text-sm text-muted-foreground"><Phone className="w-3.5 h-3.5" /> {staff.phone}</div>
              <div className="flex items-center gap-2 text-sm text-muted-foreground"><Shield className="w-3.5 h-3.5" /> {staff.department}</div>
              <div className="flex items-center gap-2 text-sm text-muted-foreground"><User className="w-3.5 h-3.5" /> {staff.qualification}</div>
              <div className="flex items-center justify-between pt-3 border-t">
                <Badge variant="outline" className={staff.status === 'Active' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : staff.status === 'On Leave' ? 'bg-amber-50 text-amber-600 border-amber-200' : 'bg-muted text-muted-foreground'}>{staff.status}</Badge>
                <div className="flex gap-2">
                  <Button variant="ghost" size="sm" onClick={() => handleEdit(staff)}><Edit2 className="w-3.5 h-3.5" /></Button>
                  <Button variant="ghost" size="sm" className="text-destructive" onClick={() => setDeleteTarget(staff._id || staff.id)}><X className="w-3.5 h-3.5" /></Button>
                </div>
              </div>
            </div>
          </motion.div>
        ))}
      </div>
      )}

      <AlertDialog open={!!deleteTarget} onOpenChange={(open) => { if (!open) setDeleteTarget(null); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Staff Member</AlertDialogTitle>
            <AlertDialogDescription>Are you sure you want to remove this staff member? This action cannot be undone.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={() => { if (deleteTarget) handleDelete(deleteTarget); setDeleteTarget(null); }}>Remove</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { TestTube, Search, FlaskConical, Heart, Activity } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const categories = ['Blood', 'Urine', 'Imaging', 'Cardiac', 'Other'];

const categoryIcons: Unmodelled = { Blood: FlaskConical, Urine: TestTube, Imaging: Activity, Cardiac: Heart, Other: TestTube };

export default function LabTestCatalog() {
  const [tests, setTests] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [catFilter, setCatFilter] = useState('All');

  useEffect(() => {
    const load = async () => {
      try {
        const res = await api.getLabTests();
        setTests(res.tests || []);
      } catch (e: any) { console.error(e); }
      setLoading(false);
    };
    load();
  }, []);

  const filtered = tests.filter(t => {
    const ms = !search || t.name.toLowerCase().includes(search.toLowerCase());
    const mc = catFilter === 'All' || t.category === catFilter;
    return ms && mc;
  });

  if (loading) {
    return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div><h1 className="font-heading text-2xl font-bold text-foreground">Test Catalog</h1>
          <p className="text-muted-foreground">{filtered.length} tests</p></div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {categories.map(c => (
          <div key={c} className="bg-card rounded-xl border border-border/60 p-4 text-center">
            <p className="text-2xl font-bold">{tests.filter(t => t.category === c).length}</p>
            <p className="text-xs text-muted-foreground">{c} Tests</p>
          </div>
        ))}
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search tests..." className="pl-10" />
        </div>
        <div className="flex gap-2 flex-wrap">
          {['All', ...categories].map(c => (
            <button key={c} onClick={() => setCatFilter(c)}
              className={`px-3 py-2 rounded-lg text-sm font-medium transition-all ${catFilter === c ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>{c}</button>
          ))}
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <TestTube className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No tests found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((test, i) => {
            const Icon = categoryIcons[test.category] || TestTube;
            return (
              <motion.div key={test._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
                className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all group">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center"><Icon className="w-6 h-6 text-primary" /></div>
                    <div>
                      <h3 className="font-heading font-semibold text-foreground text-sm">{test.name}</h3>
                      <div className="flex items-center gap-2 mt-1">
                        <Badge variant="secondary" className="text-[10px]">{test.category}</Badge>
                        {test.homeCollection && <Badge variant="outline" className="text-[10px] text-success">Home</Badge>}
                      </div>
                    </div>
                  </div>
                </div>
                <div className="flex items-center justify-between mt-4">
                  <div>
                    <p className="text-lg font-bold text-foreground">₹{test.price}</p>
                    {test.discount > 0 && <p className="text-xs text-success">{test.discount}% off • ₹{test.price - (test.price * test.discount / 100)}</p>}
                  </div>
                  <div className="text-right text-xs text-muted-foreground">
                    <p>{test.reportTime || 'N/A'}</p>
                    {test.prescriptionReq && <p className="text-warning">Rx required</p>}
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Microscope, CheckCircle2, AlertTriangle, Search,
  FileCheck, ShieldCheck, RotateCcw, Printer, ChevronRight, AlertCircle, History, XCircle, PhoneCall, Loader2,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const VERIFICATION_PENDING = ['Verification Pending', 'Under Verification', 'Result Pending'];

const modalClass = 'fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4';

const fmt = (v?: string | null) => (v === undefined || v === null || v === '' ? '—' : String(v));
const timeAgo = (iso?: string | null) => {
  if (!iso) return '—';
  const mins = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return 'Just now';
  if (mins < 60) return `${mins} min ago`;
  if (mins < 1440) return `${Math.floor(mins / 60)}h ago`;
  return new Date(iso).toLocaleDateString();
};

export const PathologistVerificationDashboard: React.FC = () => {
  const qc = useQueryClient();
  const [search, setSearch] = useState<string>('');
  const [selectedDept, setSelectedDept] = useState<string>('All');
  const [queueFilter, setQueueFilter] = useState<'All' | 'Critical' | 'Corrected'>('All');
  const [selectedId, setSelectedId] = useState<string>('');
  const [notesMap, setNotesMap] = useState<Record<string, string>>({});
  const [correctDlg, setCorrectDlg] = useState<any | null>(null);
  const [correctForm, setCorrectForm] = useState<any>({ reason: '', testIndex: '', resultValue: '', notes: '' });
  const [versionsOrder, setVersionsOrder] = useState<any | null>(null);
  const [callbackDlg, setCallbackDlg] = useState<any | null>(null);
  const [callbackForm, setCallbackForm] = useState<any>({ testName: '', calledTo: '', notes: '' });
  const [returnDlg, setReturnDlg] = useState<any | null>(null);
  const [returnForm, setReturnForm] = useState<any>({ testIndex: '', notes: '' });

  const { data: ordersData, isLoading } = useQuery({
    queryKey: ['lab-orders', 'verification'],
    queryFn: () => api.getLabOrders({}),
  });
  const { data: versionsData, isFetching: versionsLoading } = useQuery({
    queryKey: ['lab-versions', versionsOrder?._id],
    queryFn: () => api.getReportVersions(versionsOrder._id),
    enabled: Boolean(versionsOrder?._id),
  });

  const allOrders: any[] = useMemo(() => ordersData?.orders || [], [ordersData]);

  const pending = allOrders.filter((o: any) =>
    VERIFICATION_PENDING.includes(o.status) ||
    (o.status !== 'Cancelled' && o.status !== 'Finalized' && o.status !== 'Report Delivered' &&
      (o.tests || []).some((t: any) => t.status === 'Completed')))
    .sort((a: any, b: any) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());

  const criticalOrders = allOrders.filter((o: any) =>
    (o.tests || []).some((t: any) => t.isCritical && !['Verified', 'Report Delivered'].includes(t.status)));
  const correctedOrders = allOrders.filter((o: any) => Number(o.reportVersion || 1) > 1 || (o.reportVersions || []).length > 0);

  const depts = useMemo(() => {
    const set = new Set<string>();
    pending.forEach((o: any) => (o.tests || []).forEach((t: any) => { if (t.section) set.add(t.section); }));
    return ['All', ...Array.from(set)];
  }, [pending]);

  const filtered = pending.filter(r => {
    const hay = `${r.patientName} ${r.orderId} ${(r.tests || []).map((t: any) => t.testName).join(' ')}`.toLowerCase();
    const matchSearch = hay.includes(search.toLowerCase());
    const matchDept = selectedDept === 'All' || (r.tests || []).some((t: any) => t.section === selectedDept);
    const matchFilter = queueFilter === 'All'
      || (queueFilter === 'Critical' && criticalOrders.some(c => c._id === r._id))
      || (queueFilter === 'Corrected' && correctedOrders.some(c => c._id === r._id));
    return matchSearch && matchDept && matchFilter;
  });

  const activeResult = filtered.find(r => r._id === selectedId) || filtered[0] || null;

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ['lab-orders'] });
    qc.invalidateQueries({ queryKey: ['lab-stats'] });
    qc.invalidateQueries({ queryKey: ['lab-versions'] });
  };

  const verifyMut = useMutation({
    mutationFn: ({ id, body }: any) => api.verifyLabResult(id, body),
    onSuccess: () => { invalidate(); },
    onError: (e: any) => toast.error(e?.message || 'Verification failed (separation of duties may apply)'),
  });
  const finalizeMut = useMutation({
    mutationFn: (id: string) => api.finalizeLabOrder(id),
    onSuccess: () => { toast.success('Report finalized & released'); invalidate(); },
    onError: (e: any) => toast.error(e?.message || 'Finalize failed'),
  });
  const correctMut = useMutation({
    mutationFn: ({ id, body }: any) => api.correctLabReport(id, body),
    onSuccess: () => { toast.success('Correction recorded — report version incremented'); setCorrectDlg(null); invalidate(); },
    onError: (e: any) => toast.error(e?.message || 'Correction failed'),
  });
  const callbackMut = useMutation({
    mutationFn: ({ id, body }: any) => api.labCallback(id, body),
    onSuccess: () => { toast.success('Critical callback logged'); setCallbackDlg(null); invalidate(); },
    onError: (e: any) => toast.error(e?.message || 'Callback log failed'),
  });

  const signOffAll = async (order: any) => {
    const notes = notesMap[order._id] || '';
    const targets = (order.tests || []).map((t: any, i: number) => ({ t, i })).filter((r: any) => r.t.status === 'Completed');
    if (!targets.length) { toast.error('No results awaiting verification on this order'); return; }
    for (const r of targets) {
      await verifyMut.mutateAsync({ id: order._id, body: { testIndex: r.i, approved: true, notes } });
    }
    toast.success(`Signed off ${targets.length} result(s) for ${order.orderId}`);
    setSelectedId('');
  };

  const returnForCorrection = async () => {
    const idx = returnForm.testIndex === '' ? null : Number(returnForm.testIndex);
    const targets = idx === null
      ? (returnDlg.tests || []).map((t: any, i: number) => ({ t, i })).filter((r: any) => r.t.status === 'Completed')
      : [{ i: idx }];
    for (const r of targets) {
      await verifyMut.mutateAsync({ id: returnDlg._id, body: { testIndex: r.i, approved: false, notes: returnForm.notes } });
    }
    toast.error(`Returned ${targets.length} result(s) to the workbench for correction`);
    setReturnDlg(null);
    setSelectedId('');
    invalidate();
  };

  const openCorrect = (order: any) => {
    setCorrectForm({ reason: '', testIndex: '', resultValue: (order.tests || [])[0]?.resultValue || '', notes: '' });
    setCorrectDlg(order);
  };

  const signedToday = allOrders.reduce((n, o: any) =>
    n + (o.tests || []).filter((t: any) => t.verifiedAt && new Date(t.verifiedAt).toDateString() === new Date().toDateString()).length, 0);

  const tatSamples = allOrders.flatMap((o: any) => (o.tests || [])
    .filter((t: any) => t.verifiedAt && t.resultEnteredAt)
    .map((t: any) => (new Date(t.verifiedAt).getTime() - new Date(t.resultEnteredAt).getTime()) / 60000));
  const avgTat = tatSamples.length
    ? `${Math.round(tatSamples.reduce((a, b) => a + b, 0) / tatSamples.length)} mins`
    : '—';

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-emerald-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 p-6 space-y-6">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-white dark:bg-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 rounded-2xl bg-emerald-600/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-2xl">
            <Microscope className="w-7 h-7" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Pathologist Verification & Sign-Off Desk</h1>
              <span className="px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300">LIMS Medical Desk</span>
            </div>
            <p className="text-sm text-slate-500 dark:text-slate-400">
              Review, delta checks, panic escalation & authorized digital signatures
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-300 text-xs font-bold border border-amber-200 dark:border-amber-800">
            <AlertCircle className="w-4 h-4 text-amber-500" />
            {criticalOrders.length} Critical {criticalOrders.length === 1 ? 'Result' : 'Results'} Pending
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <p className="text-xs font-semibold text-slate-500 uppercase">Awaiting Sign-Off</p>
          <p className="text-2xl font-black text-slate-900 dark:text-white mt-1">{pending.length}</p>
          <span className="text-xs text-slate-400">Orders in queue</span>
        </div>
        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <p className="text-xs font-semibold text-slate-500 uppercase">Panic / Critical Flags</p>
          <p className="text-2xl font-black text-rose-600 mt-1">{criticalOrders.length}</p>
          <span className="text-xs text-rose-500 font-medium">Immediate call required</span>
        </div>
        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <p className="text-xs font-semibold text-slate-500 uppercase">Signed Today</p>
          <p className="text-2xl font-black text-emerald-600 mt-1">{signedToday}</p>
          <span className="text-xs text-slate-400">Results released</span>
        </div>
        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <p className="text-xs font-semibold text-slate-500 uppercase">Avg Verification TAT</p>
