                }} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                  <option value="">Report text only</option>
                  {(correctDlg.tests || []).map((t: any, i: number) => <option key={i} value={String(i)}>{t.testName}</option>)}
                </select>
