                          <span className="text-muted-foreground ml-auto">{c.verifiedAt ? new Date(c.verifiedAt).toLocaleString() : ''}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

