          <LawyerSettingsTab
            handleSaveSettings={handleSaveSettings}
            acceptsUrgent={acceptsUrgent}
            setAcceptsUrgent={setAcceptsUrgent}
            editEmergencyStandby={editEmergencyStandby}
            setEditEmergencyStandby={setEditEmergencyStandby}
            editRefundPolicy={editRefundPolicy}
            setEditRefundPolicy={setEditRefundPolicy}
            editFeeSchedule={editFeeSchedule}
            setEditFeeSchedule={setEditFeeSchedule}
            editPracticingCourts={editPracticingCourts}
            setEditPracticingCourts={setEditPracticingCourts}
            courtInput={courtInput}
            setCourtInput={setCourtInput}
            editPrivilegeLocked={editPrivilegeLocked}
            setEditPrivilegeLocked={setEditPrivilegeLocked}
            bankHolder={bankHolder}
            setBankHolder={setBankHolder}
            bankAccount={bankAccount}
            setBankAccount={setBankAccount}
            bankIfsc={bankIfsc}
            setBankIfsc={setBankIfsc}
            bankUpi={bankUpi}
            setBankUpi={setBankUpi}
            bankGstin={bankGstin}
            setBankGstin={setBankGstin}
            profile={profile}
            savingSettings={savingSettings}
          />
        )}

      {/* FULL-SCREEN Incoming Legal Consultation Call modal (120s / 2-minute timer with ringtone) */}
      {activeIncomingCall && (
        <ProviderIncomingCall
          key={activeIncomingCall._id}
          data={{
            requestId: activeIncomingCall._id,
            providerType: 'lawyer',
            category: activeIncomingCall.category || 'medical_negligence',
            title: `Legal Consultation: ${activeIncomingCall.category?.replace(/_/g, ' ') || 'Healthcare Issue'}`,
            subtitle: `Client requesting consultation (${activeIncomingCall.consultationMode?.replace('_', ' ') || 'Direct Session'}). Respond within 2 minutes.${activeIncomingCall.firNumber ? ` FIR: ${activeIncomingCall.firNumber}` : ''}${activeIncomingCall.policeStationName ? ` @ ${activeIncomingCall.policeStationName}` : ''}`,
            patient: {
              name: activeIncomingCall.userId?.name || 'Client',
              phone: activeIncomingCall.userId?.phone || 'Direct App Connect',
            },
            location: {
              address: activeIncomingCall.userId?.city
                ? `Client City: ${activeIncomingCall.userId.city}`
                : 'Direct Consultation (Audio / Video / Chamber)',
            },
            amount: activeIncomingCall.fee || 500,
            windowSeconds: 120,
            specialInstructions: activeIncomingCall.caseDescription,
            serviceBadges: [
              activeIncomingCall.consultationMode?.replace('_', ' ') || 'Consultation',
              activeIncomingCall.urgency === 'urgent' ? '⚡ Urgent' : 'Scheduled',
            ],
          }}
          acceptedWaiting={acceptedWaiting || String(acceptingId) === String(activeIncomingCall._id)}
          onAccept={async (bookingId) => {
            // Wave-based bookings (lawyer:alert) vote via instant dispatch;
            // traditional new_booking_request accepts use the lawyer booking API.
            if (activeIncomingCall?.isInstantWave) {
              try {
                await api.post(`/instant/lawyer/${bookingId}/accept`, {});
                toast.success('Vote cast — waiting for dispatch confirmation…');
                setAcceptedWaiting(true);
                setTimeout(() => {
                  setActiveIncomingCall(null);
                  setAcceptedWaiting(false);
                }, 1100);
              } catch (err: any) {
                toast.error(userFacingError(err, { fallback: 'Could not accept request' }));
              }
              return;
            }
            const accepted = await handleAcceptRequest(bookingId);
            if (accepted) {
              setAcceptedWaiting(true);
              setTimeout(() => {
                setActiveIncomingCall(null);
                setAcceptedWaiting(false);
              }, 1100);
            }
          }}
          onReject={async (bookingId) => {
            await handleDeclineRequest(bookingId);
            setActiveIncomingCall(null);
            setAcceptedWaiting(false);
          }}
          onTimeout={(bookingId) => {
            toast.info('Request timed out — it stays in your Requests tab.');
            setActiveIncomingCall(null);
            setAcceptedWaiting(false);
            setIncomingRequests((prev) => prev.filter((r) => String(r._id) !== String(bookingId)));
          }}
        />
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Activity, Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { EmptyState } from '@/components/clinical/SharedStates';

/** File 22 P2-40: Growth charts — weight/height/BMI tracking with WHO percentiles. */
export default function GrowthCharts() {
  const [patientId, setPatientId] = useState('');
  const [chart, setChart] = useState<any>(null);
  const [form, setForm] = useState({ date: '', weightKg: '', heightCm: '', headCircCm: '' });

  const load = async (pid: string) => {
    if (!pid) return;
    try {
      const r: any = await api.get(`/growth-charts/patient/${pid}`);
      setChart(r.chart);
    } catch { setChart(null); }
  };
  useEffect(() => { load(patientId); }, [patientId]);

  const addPoint = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!patientId) return toast.error('Enter patient ID first');
    try {
      await api.post(`/growth-charts/patient/${patientId}`, {
        sex: chart?.sex || 'male',
        birthDate: chart?.birthDate || new Date(),
        points: [{ ...form, weightKg: Number(form.weightKg) || 0, heightCm: Number(form.heightCm) || 0, headCircCm: Number(form.headCircCm) || 0 }],
      });
      toast.success('Measurement added');
      setForm({ date: '', weightKg: '', heightCm: '', headCircCm: '' });
      load(patientId);
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Save failed'); }
  };

  const points = chart?.points || [];

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Activity size={18} /> Growth charts</h1>
      <Input placeholder="Patient ID" value={patientId} onChange={(e) => setPatientId(e.target.value)} />
      <Card>
        <CardHeader><CardTitle className="text-sm">Add measurement</CardTitle></CardHeader>
        <CardContent>
          <form onSubmit={addPoint} className="flex flex-wrap gap-2">
            <Input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
            <Input type="number" placeholder="Weight (kg)" value={form.weightKg} onChange={(e) => setForm({ ...form, weightKg: e.target.value })} />
            <Input type="number" placeholder="Height (cm)" value={form.heightCm} onChange={(e) => setForm({ ...form, heightCm: e.target.value })} />
            <Input type="number" placeholder="Head circ (cm)" value={form.headCircCm} onChange={(e) => setForm({ ...form, headCircCm: e.target.value })} />
            <Button size="sm" type="submit"><Plus size={14} /> Add</Button>
          </form>
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle className="text-sm">Measurements ({points.length})</CardTitle></CardHeader>
        <CardContent className="space-y-1.5">
          {points.map((p: any, i: number) => (
            <div key={i} className="flex items-center justify-between rounded border p-2 text-xs">
              <span>{p.date?.slice(0, 10)}</span>
              <span>Wt: {p.weightKg || '—'}kg · Ht: {p.heightCm || '—'}cm · HC: {p.headCircCm || '—'}cm</span>
            </div>
          ))}
          {points.length === 0 ? <EmptyState title="No measurements" hint="Add the first measurement for this patient." /> : null}
        </CardContent>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Stethoscope, Plus, CheckCircle2, AlertTriangle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { StatusPill } from '@/components/clinical/StatusAtoms';
import { EmptyState } from '@/components/clinical/SharedStates';

/** File 22 P2-40: Newborn screening — metabolic panel tracker. */
export default function NewbornScreening() {
  const [patientId, setPatientId] = useState('');
  const [data, setData] = useState<any>(null);
  const [result, setResult] = useState({ testName: '', result: '', flagged: false });

  const load = async (pid: string) => {
    if (!pid) return;
    try {
      const r: any = await api.get(`/newborn-screening/patient/${pid}`);
      setData(r.screenings?.[0] || null);
    } catch { setData(null); }
  };
  useEffect(() => { load(patientId); }, [patientId]);

  const start = async () => {
    if (!patientId) return;
    try {
      await api.post(`/newborn-screening/patient/${patientId}`, {});
      toast.success('Screening panel created');
      load(patientId);
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Failed'); }
  };

  const saveResult = async () => {
    try {
      await api.post(`/newborn-screening/patient/${patientId}/result`, result);
      toast.success('Result saved');
      setResult({ testName: '', result: '', flagged: false });
      load(patientId);
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Failed'); }
  };

  const tests = data?.tests || [];

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Stethoscope size={18} /> Newborn screening</h1>
      <div className="flex gap-2">
        <Input placeholder="Patient ID" value={patientId} onChange={(e) => setPatientId(e.target.value)} />
        {!data ? <Button size="sm" onClick={start}><Plus size={14} /> Start screening</Button> : null}
      </div>
      {data ? (
        <>
          <Card>
            <CardHeader><CardTitle className="text-sm">Panel ({tests.length} tests)</CardTitle></CardHeader>
            <CardContent className="space-y-1.5">
              {tests.map((t: any) => (
                <div key={t.name} className="flex items-center justify-between rounded border p-2 text-xs">
                  <span><b>{t.name}</b></span>
                  <span className="flex items-center gap-2">
                    {t.result ? <span>{t.result}</span> : <span className="text-muted-foreground">pending</span>}
                    <StatusPill status={t.flagged ? 'critical' : t.result ? 'done' : 'pending'} />
                  </span>
                </div>
              ))}
            </CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="text-sm">Add result</CardTitle></CardHeader>
            <CardContent>
              <div className="flex flex-wrap gap-2">
                <Input placeholder="Test name" value={result.testName} onChange={(e) => setResult({ ...result, testName: e.target.value })} />
                <Input placeholder="Result" value={result.result} onChange={(e) => setResult({ ...result, result: e.target.value })} />
                <label className="flex items-center gap-1 text-xs">
                  <input type="checkbox" checked={result.flagged} onChange={(e) => setResult({ ...result, flagged: e.target.checked })} />
                  Flagged
                </label>
                <Button size="sm" onClick={saveResult}><Plus size={14} /> Save</Button>
              </div>
            </CardContent>
          </Card>
          {data.status === 'flagged' ? (
            <div className="rounded-lg border border-red-300 bg-red-50 p-3 text-sm text-red-900">
              <AlertTriangle size={14} className="mr-1 inline" />
              Screening flagged — refer to specialist
            </div>
          ) : null}
        </>
      ) : (
        <EmptyState title="No screening" hint="Start a newborn screening panel." />
      )}
    </div>
  );
}

