import { EmptyState } from '@/components/clinical/SharedStates';

/** File 22 P2-40: Vaccination alerts — IAP schedule tracker. */
export default function VaccinationAlerts() {
  const [patientId, setPatientId] = useState('');
  const [rows, setRows] = useState<any[]>([]);
  const [birthDate, setBirthDate] = useState('');

  const load = async (pid: string) => {
    if (!pid) return;
    try {
      const r: any = await api.get(`/vaccinations/patient/${pid}`);
      setRows(r.vaccinations || []);
    } catch { setRows([]); }
  };
  useEffect(() => { load(patientId); }, [patientId]);

  const generate = async () => {
    if (!patientId || !birthDate) return toast.error('Patient ID + birth date required');
    try {
      const r: any = await api.post(`/vaccinations/schedule/${patientId}`, { birthDate });
      toast.success(`${r.created} vaccines scheduled`);
      load(patientId);
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Failed'); }
  };

  const administer = async (id: string) => {
    try {
      await api.post(`/vaccinations/administer/${id}`);
      toast.success('Marked administered');
      load(patientId);
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Failed'); }
  };

  const pending = rows.filter((r) => r.status === 'pending');
  const overdue = rows.filter((r) => r.status === 'pending' && new Date(r.dueDate) < new Date());

  return (
    <div className="space-y-3 p-4">
      <h1 className="flex items-center gap-2 text-lg font-bold"><Syringe size={18} /> Vaccination alerts</h1>
      <div className="flex flex-wrap gap-2">
        <Input placeholder="Patient ID" value={patientId} onChange={(e) => setPatientId(e.target.value)} />
        <Input type="date" placeholder="Birth date" value={birthDate} onChange={(e) => setBirthDate(e.target.value)} />
        <Button size="sm" onClick={generate}><Plus size={14} /> Generate schedule</Button>
      </div>
      {overdue.length > 0 ? (
        <div className="rounded-lg border border-red-300 bg-red-50 p-3 text-sm text-red-900">
          <AlertCircle size={14} className="mr-1 inline" />
          {overdue.length} vaccine(s) overdue
        </div>
      ) : null}
      <Card>
        <CardHeader><CardTitle className="text-sm">Schedule ({rows.length})</CardTitle></CardHeader>
        <CardContent className="space-y-1.5">
          {rows.map((r) => (
            <div key={r._id} className="flex items-center justify-between rounded border p-2 text-xs">
              <span><b>{r.vaccineName}</b> · Dose {r.doseNumber} · Due {r.dueDate?.slice(0, 10)}</span>
              <span className="flex items-center gap-1">
                <StatusPill status={r.status === 'administered' ? 'done' : r.status === 'pending' ? 'pending' : r.status} />
                {r.status === 'pending' ? (
                  <Button size="sm" variant="ghost" onClick={() => administer(r._id)}><CheckCircle2 size={12} /></Button>
                ) : null}
              </span>
            </div>
          ))}
          {rows.length === 0 ? <EmptyState title="No vaccinations" hint="Generate a schedule for this patient." /> : null}
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * R1 — Emergency card (shared by PatientDashboardV2, Timeline, PrivacyCentre).
 * Discreet mode (prop-drilled) masks identity/PHI-ish details.
 */
import React from 'react';
import { Link } from 'react-router-dom';

export function mask(value: string, discreet: boolean): string {
  if (!discreet) return value;
  if (value.length <= 2) return '••';
  return `${value.slice(0, 1)}•••${value.slice(-1)}`;
}

export default function EmergencyCard({
  discreet = false,
  compact = false,
  bloodGroup = '',
  contactName = '',
  contactPhone = '',
}: {
  discreet?: boolean;
  compact?: boolean;
  bloodGroup?: string;
  contactName?: string;
  contactPhone?: string;
}) {
  // No placeholder identity: empty props render an explicit "not set" state
  // with a CTA instead of someone else's name and number.
  const hasContact = contactName.trim() !== '' || contactPhone.trim() !== '';
  return (
    <section
      data-testid="emergency-card"
      className="rounded-xl border border-destructive/30 bg-destructive/5 p-4"
    >
      <div className="flex items-center justify-between">
        <h2 className="font-semibold text-destructive">🚨 Emergency / SOS</h2>
        {!compact && (
          <Link to="/patient/addresses" className="text-xs underline">
            Manage contacts
          </Link>
        )}
      </div>
      <div className="mt-3 grid sm:grid-cols-3 gap-2 text-sm">
        <div className="rounded-lg bg-background border p-2">
          <p className="text-xs text-muted-foreground">Blood group</p>
          <p className="font-semibold">{discreet ? '••' : (bloodGroup || 'Not set')}</p>
        </div>
        <div className="rounded-lg bg-background border p-2">
          <p className="text-xs text-muted-foreground">Emergency contact</p>
          <p className="font-semibold">{hasContact ? mask(contactName || '—', discreet) : 'Not set'}</p>
        </div>
        <div className="rounded-lg bg-background border p-2">
          <p className="text-xs text-muted-foreground">Phone</p>
          <p className="font-semibold">{discreet ? '••••••' : (contactPhone || '—')}</p>
        </div>
      </div>
      {!hasContact && !compact && (
        <p className="mt-2 text-xs text-muted-foreground">
          Add an emergency contact from <Link to="/patient/addresses" className="underline">Manage contacts</Link> so responders can reach them.
        </p>
      )}
      <div className="mt-3 flex flex-wrap gap-2">
        <a href="tel:108" className="rounded-lg bg-destructive text-white px-4 py-2 text-sm font-semibold">
          Call 108
        </a>
        <a href="tel:14416" className="rounded-lg border px-4 py-2 text-sm">
          Tele-MANAS 14416
        </a>
      </div>
      {!compact && <FirstResponders />}
    </section>
  );
