}

function formatShortDate(d: Unmodelled) {
  if (!d) return '';
  const dt = new Date(d);
  return dt.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
}

export default function PatientBookingHistory({ initialType }: { initialType?: string } = {}) {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [bookings, setBookings] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [typeFilter, setTypeFilter] = useState(initialType || 'All');
  const [dateRange, setDateRange] = useState('All Time');
  const [showDateDropdown, setShowDateDropdown] = useState(false);
  const [cancelId, setCancelId] = useState<Unmodelled>(null);
  const [rescheduleId, setRescheduleId] = useState<Unmodelled>(null);
  const [newDate, setNewDate] = useState('');
  const [newTime, setNewTime] = useState('');

  const showActions = initialType === 'appointment';

  const handleCancel = async () => {
    if (!cancelId) return;
    try {
      await api.updateAppointment(cancelId, { status: 'Cancelled' });
      toast.success('Appointment cancelled');
      setCancelId(null);
      loadData();
    } catch (e: any) { toast.error('Failed to cancel appointment'); }
  };

  const handleReschedule = async () => {
    if (!newDate || !newTime || !rescheduleId) return;
    try {
      await api.updateAppointment(rescheduleId, { date: newDate, time: newTime, status: 'Confirmed' });
      toast.success('Appointment rescheduled');
      setRescheduleId(null); setNewDate(''); setNewTime('');
      loadData();
    } catch (e: any) { toast.error('Failed to reschedule appointment'); }
  };

  const loadData = async () => {
    setLoading(true);
    try {
      const [appointmentsRes, labBookingsRes, pharmacyOrdersRes] = await Promise.all([
        (typeFilter === 'All' || typeFilter === 'appointment') 
          ? api.getMyAppointments({}).catch(() => []) 
          : Promise.resolve([]),
        (typeFilter === 'All' || typeFilter === 'test') 
          ? api.getLabBookings({ patientId: user?.id }).catch(() => ({ data: [] })) 
          : Promise.resolve({ data: [] }),
        (typeFilter === 'All' || typeFilter === 'medicine') 
          ? api.getPharmacyOrders({ patientId: user?.id }).catch(() => ({ data: [] })) 
          : Promise.resolve({ data: [] }),
      ]);

      const appointments = (Array.isArray(appointmentsRes) ? appointmentsRes : appointmentsRes?.data || []).map((a: Unmodelled) => ({
        ...a,
        type: 'appointment',
        displayDate: a.createdAt || a.date,
      }));

      const labBookings = (labBookingsRes?.data || []).map((l: Unmodelled) => ({
        ...l,
        type: 'test',
        displayDate: l.createdAt || l.bookingDate,
      }));

      const pharmacyOrders = (pharmacyOrdersRes?.data || []).map((p: Unmodelled) => ({
        ...p,
        type: 'medicine',
        displayDate: p.createdAt || p.orderDate,
      }));

      // Sort by createdAt descending (newest first)
      const merged = [...appointments, ...labBookings, ...pharmacyOrders].sort(
        (a, b) => (+new Date(b.displayDate)) - (+new Date(a.displayDate))
      );

      setBookings(merged);
    } catch (e: any) {
      console.error(e);
      toast.error('Failed to load booking history');
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, [typeFilter, user?.id]);

  // Reload when user navigates back to this page (after booking)
  useEffect(() => {
    const handleFocus = () => loadData();
    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [typeFilter]);

  const getDateRangeFilter = () => {
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    if (dateRange === 'This Month') return { $gte: startOfMonth };
    if (dateRange === 'Last Month') {
      const start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      const end = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
      return { $gte: start, $lte: end };
    }
    if (dateRange === 'Last 3 Months') {
      return { $gte: new Date(now.getFullYear(), now.getMonth() - 3, 1) };
    }
    return null;
  };

  const filtered = bookings.filter(b => {
    const dr = getDateRangeFilter();
    if (dr) {
      const d = new Date(b.displayDate);
      if (dr.$gte && d < dr.$gte) return false;
      if (dr.$lte && d > dr.$lte) return false;
    }
    return true;
  });

  const totalBookings = filtered.length;
  const confirmedCount = filtered.filter(b => b.status === 'Confirmed').length;
  const pendingCount = filtered.filter(b => b.status === 'Pending' || b.status === 'In Queue').length;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">{typeFilter === 'appointment' ? 'My Appointments' : 'Booking History'}</h1>
        <p className="text-muted-foreground text-sm">{typeFilter === 'appointment' ? 'View and manage your appointments' : 'Your appointments, lab tests, and medicine orders'}</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}
          className="bg-card rounded-3xl border border-border/50 p-5 shadow-sm hover:shadow-md transition-all">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center shadow-sm">
              <CalendarDays className="w-5.5 h-5.5 text-primary" />
            </div>
            <p className="text-sm font-medium text-muted-foreground">Total Bookings</p>
          </div>
          <p className="font-heading text-3xl font-bold text-foreground tracking-tight">{totalBookings}</p>
        </motion.div>
        <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}
          className="bg-card rounded-3xl border border-border/50 p-5 shadow-sm hover:shadow-md transition-all">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-emerald-500/20 to-emerald-500/5 flex items-center justify-center shadow-sm">
              <CheckCircle className="w-5.5 h-5.5 text-emerald-500" />
            </div>
            <p className="text-sm font-medium text-muted-foreground">Confirmed</p>
          </div>
          <p className="font-heading text-3xl font-bold text-emerald-600 tracking-tight">{confirmedCount}</p>
        </motion.div>
        <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}
          className="bg-card rounded-3xl border border-border/50 p-5 shadow-sm hover:shadow-md transition-all">
          <div className="flex items-center gap-3 mb-3">
            <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-amber-500/20 to-amber-500/5 flex items-center justify-center shadow-sm">
              <Clock className="w-5.5 h-5.5 text-amber-500" />
            </div>
            <p className="text-sm font-medium text-muted-foreground">Pending</p>
          </div>
          <p className="font-heading text-3xl font-bold text-amber-600 tracking-tight">{pendingCount}</p>
        </motion.div>
      </div>

      {/* Filters */}
      <div className="flex flex-col gap-3">
        {/* Row 1: Type */}
        {!initialType && (
          <div className="flex gap-1.5 flex-wrap">
            {typeFilters.map(f => (
              <button key={f} onClick={() => setTypeFilter(f)}
                className={`px-3.5 py-2 rounded-lg text-xs font-medium transition-all ${typeFilter === f ? 'bg-primary text-primary-foreground shadow-sm' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                {f === 'All' ? 'All' : f === 'appointment' ? 'Appointments' : f === 'test' ? 'Lab Tests' : 'Medicines'}
              </button>
            ))}
          </div>
        )}

        {/* Row 2: Date range */}
        <div className="relative inline-block self-start">
          <button onClick={() => setShowDateDropdown(!showDateDropdown)}
            className="flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs font-medium bg-muted text-muted-foreground hover:bg-muted/80 transition-all">
            <Calendar className="w-3.5 h-3.5" />
            {dateRange}
            <ChevronDown className="w-3 h-3" />
          </button>
          {showDateDropdown && (
            <div className="absolute top-full left-0 mt-1 bg-card border border-border/60 rounded-xl shadow-lg z-10 py-1 min-w-[140px]">
              {dateRanges.map(r => (
                <button key={r} onClick={() => { setDateRange(r); setShowDateDropdown(false); }}
                  className={`w-full text-left px-4 py-2 text-xs font-medium transition-colors hover:bg-muted ${dateRange === r ? 'text-primary' : 'text-muted-foreground'}`}>
                  {r}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* List */}
      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 bg-card rounded-2xl border border-border/60">
          <Calendar className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
          <p className="text-muted-foreground font-medium">No bookings yet</p>
          <p className="text-xs text-muted-foreground/60 mt-1">Your appointments, lab tests, and medicine orders will appear here</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {filtered.map((booking, i) => {
            const isAppt = booking.type === 'appointment';
            const isTest = booking.type === 'test';
            const isMed = booking.type === 'medicine';

            const StatusIcon = statusConfig[booking.status]?.icon || Clock;
            const TypeIcon = isAppt ? Stethoscope : isTest ? Beaker : Pill;
            const typeLabel = isAppt ? 'Appointment' : isTest ? 'Lab Test' : 'Medicine';
            const typeBadgeColor = isAppt ? 'bg-blue-500/10 text-blue-600' : isTest ? 'bg-purple-500/10 text-purple-600' : 'bg-rose-500/10 text-rose-600';

            // Build title
            let title = '';
            if (isAppt) {
              const docName = booking.doctor || booking.doctorId?.name || 'Doctor';
              title = docName.match(/^dr\.?\s/i) ? docName : `Dr. ${docName}`;
            }
            if (isTest) {
              const tests = booking.tests || [];
              title = tests.length > 1 ? `${tests[0]} +${tests.length - 1} more (${tests.length} tests)` : tests[0] || 'Lab Test';
            }
            if (isMed) {
              const items = booking.items || [];
              title = items.length > 0 ? `${items.length} items` : 'Medicine Order';
            }

            // Subtitle
            let subtitle = '';
            if (isAppt) subtitle = booking.department || booking.doctorId?.specialization || 'Consultation';
            if (isTest) subtitle = booking.visitType || 'Lab Visit';
            if (isMed) subtitle = booking.deliveryMode === 'delivery' ? 'Home Delivery' : 'Store Pickup';

            // Detail
            let detail = '';
            if (isAppt) detail = `${formatShortDate(booking.date)}${booking.time ? ` • ${booking.time}` : ''}`;
            if (isTest) detail = `${formatShortDate(booking.bookingDate)}${booking.timeSlot ? ` • ${booking.timeSlot}` : ''}`;
            if (isMed) detail = `${formatShortDate(booking.orderDate || booking.createdAt)}`;

            return (
              <motion.div key={booking._id} initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
                className="bg-card rounded-2xl border border-border/60 overflow-hidden hover:shadow-lg transition-all">
                <div className="p-5">
                  {/* Top row */}
                  <div className="flex items-start gap-3 mb-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${typeBadgeColor}`}>
                      <TypeIcon className="w-5 h-5" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 mb-0.5 flex-wrap">
                        <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold ${typeBadgeColor}`}>
                          <TypeIcon className="w-3 h-3" />
                          {typeLabel}
                        </span>
                        <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold ${statusConfig[booking.status]?.color || 'bg-gray-500/10 text-gray-600'}`}>
                          <StatusIcon className="w-3 h-3" />
                          {statusConfig[booking.status]?.label || booking.status}
                        </span>
                      </div>
                      <p className="font-heading font-semibold text-foreground text-sm leading-tight mt-1">{title}</p>
                      {subtitle && <p className="text-xs text-muted-foreground mt-0.5">{subtitle}</p>}
                    </div>
                  </div>

                  {/* Date + detail */}
                  <div className="ml-[52px] space-y-0.5 mb-3">
                    {detail && <p className="text-xs text-muted-foreground">{detail}</p>}
                    {booking.tokenNumber && <p className="text-xs text-muted-foreground">Token: {booking.tokenNumber}</p>}
                  </div>

                  {/* Divider */}
                  <div className="border-t border-border/40 my-3" />

                  {/* Bottom: action buttons */}
                  <div className="flex items-end justify-end gap-2">
                    {showActions && isAppt && (booking.status === 'Confirmed' || booking.status === 'Pending') ? (
                      <>
                        <Button size="sm" variant="outline" className="gap-1.5 rounded-xl h-9 text-xs text-destructive hover:text-destructive"
                          onClick={(e) => { e.stopPropagation(); setCancelId(booking._id); }}>
                          <XCircle className="w-3.5 h-3.5" /> Cancel
                        </Button>
                        <Button size="sm" variant="outline" className="gap-1.5 rounded-xl h-9 text-xs"
                          onClick={(e) => { e.stopPropagation(); setRescheduleId(booking._id); }}>
                          <RefreshCw className="w-3.5 h-3.5" /> Reschedule
                        </Button>
                      </>
                    ) : !showActions && isTest ? (
                      <Button size="sm" variant="outline" className="gap-1.5 rounded-xl h-9 text-xs"
                        onClick={(e) => { e.stopPropagation(); navigate('/patient/bookings'); }}>
                        <ExternalLink className="w-3.5 h-3.5" /> Track Booking
                      </Button>
                    ) : !showActions && isMed ? (
                      <Button size="sm" variant="outline" className="gap-1.5 rounded-xl h-9 text-xs"
                        onClick={(e) => { e.stopPropagation(); booking._id && navigate(`/order-tracking/${booking._id}`); }}>
                        <ExternalLink className="w-3.5 h-3.5" /> Track Order
                      </Button>
                    ) : null}
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      )}

      {/* Cancel Confirmation Modal */}
      {showActions && cancelId && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setCancelId(null)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-sm p-6" onClick={e => e.stopPropagation()}>
            <div className="text-center">
              <XCircle className="w-12 h-12 text-destructive mx-auto mb-4" />
              <h3 className="font-heading text-lg font-bold text-foreground mb-2">Cancel Appointment?</h3>
              <p className="text-sm text-muted-foreground mb-6">This action cannot be undone. Are you sure you want to cancel this appointment?</p>
            </div>
            <div className="flex gap-3">
              <Button variant="outline" className="flex-1" onClick={() => setCancelId(null)}>Keep Appointment</Button>
              <Button className="flex-1 bg-destructive hover:bg-destructive/90" onClick={handleCancel}>Yes, Cancel</Button>
            </div>
          </motion.div>
        </div>
      )}

      {/* Reschedule Modal */}
      {showActions && rescheduleId && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setRescheduleId(null)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
            <h3 className="font-heading text-lg font-bold text-foreground mb-4">Reschedule Appointment</h3>
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">New Date</label>
                <Input type="date" value={newDate} onChange={e => setNewDate(e.target.value)} min={getISTDateString()} />
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">New Time</label>
                <div className="grid grid-cols-4 gap-2">
                  {timeSlots.map(t => (
                    <button key={t} onClick={() => setNewTime(t)}
                      className={`px-2 py-1.5 rounded-lg text-xs font-medium transition-colors ${newTime === t ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      {t}
                    </button>
                  ))}
                </div>
              </div>
            </div>
            <p className="text-xs text-muted-foreground mt-3 bg-warning/10 p-2 rounded-lg">
              <AlertCircle className="w-3 h-3 inline mr-1" /> All slots shown may not reflect real-time availability. The clinic will confirm after review.
            </p>
            <div className="flex gap-3 mt-4">
              <Button variant="outline" className="flex-1" onClick={() => setRescheduleId(null)}>Cancel</Button>
              <Button className="flex-1" onClick={handleReschedule} disabled={!newDate || !newTime}>Confirm</Button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  CalendarDays, FlaskConical, Clock, CheckCircle2, XCircle,
  AlertCircle, Loader2, Search, ChevronRight, Syringe, FileText,
  Eye, MapPin, Phone, IndianRupee, Activity, Stethoscope, MessageCircle, PhoneCall
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { useAppointmentRealtime } from '@/lib/useAppointmentRealtime';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const BOOKING_STATUS: Unmodelled = {
  Scheduled: { label: 'Scheduled', color: 'bg-blue-500/10 text-blue-600 border-blue-500/30', icon: Clock },
  Confirmed: { label: 'Confirmed', color: 'bg-blue-500/10 text-blue-600 border-blue-500/30', icon: CheckCircle2 },
  'Sample Collected': { label: 'Sample Collected', color: 'bg-purple-500/10 text-purple-600 border-purple-500/30', icon: Syringe },
  'Report Ready': { label: 'Report Ready', color: 'bg-emerald-500/10 text-emerald-600 border-emerald-500/30', icon: FileText },
  Completed: { label: 'Completed', color: 'bg-success/10 text-success border-success/30', icon: CheckCircle2 },
  Cancelled: { label: 'Cancelled', color: 'bg-destructive/10 text-destructive border-destructive/30', icon: XCircle },
  Pending: { label: 'Pending', color: 'bg-amber-500/10 text-amber-600 border-amber-500/30', icon: Clock },
  Processing: { label: 'Processing', color: 'bg-amber-500/10 text-amber-600 border-amber-500/30', icon: Loader2 },
  'In Queue': { label: 'In Queue', color: 'bg-purple-500/10 text-purple-600 border-purple-500/30', icon: Clock },
  Serving: { label: 'Serving', color: 'bg-indigo-500/10 text-indigo-600 border-indigo-500/30', icon: Activity },
  Missed: { label: 'Missed', color: 'bg-orange-500/10 text-orange-600 border-orange-500/30', icon: AlertCircle },
};

const STATUS_FILTERS = ['All', 'Scheduled', 'Pending', 'Confirmed', 'Completed', 'Cancelled'];

function normalizeBooking(item: Unmodelled, type: Unmodelled) {
  if (type === 'appointment') {
    return {
      id: item._id,
      type: 'appointment',
      source: item.doctor || item.doctorId?.name || 'Doctor',
      date: item.date ? item.date.split('T')[0] : '',
      tests: [],
      amount: item.fees || item.consultation_fees || 0,
      status: item.status || 'Confirmed',
      slot: item.timeSlot || item.time || '',
      address: item.hospitalId?.name || item.hospitalId?.address || '',
      phone: item.hospitalId?.phone || item.doctorId?.phone || '',
      _raw: item,
    };
  }
  return {
    id: item._id,
    type: 'test',
    source: item.facilityId?.name || item.labName || 'Lab',
    date: item.bookingDate ? item.bookingDate.split('T')[0] : '',
    tests: item.tests || [],
    amount: item.totalAmount || item.discountedAmount || 0,
    status: item.status || 'Pending',
    slot: item.timeSlot || '',
    address: item.homeCollectionAddress || '',
    phone: item.patientPhone || '',
    _raw: item,
  };
}

export default function PatientBookings() {
  const navigate = useNavigate();
  const [bookings, setBookings] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<Unmodelled>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [typeFilter, setTypeFilter] = useState('All');
  const [intakeModal, setIntakeModal] = useState<Unmodelled>(null);
  const [intakeData, setIntakeData] = useState({
    chiefComplaint: '', symptomsDuration: '', pastMedicalHistory: '', currentMedications: '', allergies: ''
  });
  const [submittingIntake, setSubmittingIntake] = useState(false);

  const loadBookings = useCallback(async (isRetry = false) => {
    if (!isRetry) setLoading(true);
    try {
      const [appts, labBks] = await Promise.all([
        api.getMyAppointments(),
        api.getLabBookings({})
      ]);
      const normalized = [
        ...((appts?.data || appts || [])).map((a: Unmodelled) => normalizeBooking(a, 'appointment')),
        ...((labBks?.bookings || labBks?.data || [])).map((b: Unmodelled) => normalizeBooking(b, 'test')),
      ];
      setBookings(normalized);
      setLoadError(null); // clear any previous error on success
    } catch (e: any) {
      // Transient errors (503 / network) ko error screen me convert mat karo —
      // axios interceptor already GET retry karta hai, aur realtime hook +
      // manual retry se data aa jayega. Sirf genuine server error (4xx, auth
      // failures) par hi error dikhao.
      const status = e?.status || e?.response?.status;
      if (status === 503 || !status) {
        // transient — keep last good data, don't overwrite with error screen
        setLoadError((prev: Unmodelled) => prev); // no change
      } else {
        setLoadError('Failed to load bookings');
      }
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadBookings(); }, [loadBookings]);

  // Realtime — doctor/clinic status change hone par turant dikhein
  useAppointmentRealtime(loadBookings);

  const filtered = bookings.filter(b => {
    if (statusFilter !== 'All' && b.status !== statusFilter) return false;
    if (typeFilter !== 'All' && b.type !== typeFilter) return false;
    if (search) {
      const q = search.toLowerCase();
      if (!b.source.toLowerCase().includes(q) && !b.tests.some((t: Unmodelled) => t.toLowerCase().includes(q))) return false;
    }
    return true;
  });

  const activeBookings = filtered.filter(b => !['Completed', 'Cancelled'].includes(b.status));
  const pastBookings = filtered.filter(b => ['Completed', 'Cancelled'].includes(b.status));

  const handleCancel = async (booking: Unmodelled) => {
    try {
      if (booking.type === 'appointment') {
        await api.updateAppointment(booking.id, { status: 'Cancelled' });
      } else {
        await api.updateLabBooking(booking.id, { status: 'Cancelled' });
      }
      setBookings(prev => prev.map(b => b.id === booking.id ? { ...b, status: 'Cancelled' } : b));
      toast.success('Booking cancelled');
    } catch {
      toast.error('Failed to cancel booking');
    }
  };

  const handleOpenIntake = (booking: Unmodelled) => {
    setIntakeModal(booking);
    if (booking._raw?.preConsultationDetails) {
      setIntakeData({
        chiefComplaint: booking._raw.preConsultationDetails.chiefComplaint || '',
        symptomsDuration: booking._raw.preConsultationDetails.symptomsDuration || '',
        pastMedicalHistory: booking._raw.preConsultationDetails.pastMedicalHistory || '',
        currentMedications: booking._raw.preConsultationDetails.currentMedications || '',
        allergies: booking._raw.preConsultationDetails.allergies || ''
      });
    } else {
      setIntakeData({ chiefComplaint: '', symptomsDuration: '', pastMedicalHistory: '', currentMedications: '', allergies: '' });
    }
  };

  const handleIntakeSubmit = async (e: Unmodelled) => {
    e.preventDefault();
    if (!intakeModal) return;
    setSubmittingIntake(true);
    try {
      const res = await api.submitIntakeForm(intakeModal.id, intakeData);
      setBookings(prev => prev.map(b => b.id === intakeModal.id ? { ...b, _raw: { ...b._raw, preConsultationDetails: res.preConsultationDetails } } : b));
      toast.success('Intake form saved successfully');
      setIntakeModal(null);
    } catch {
      toast.error('Failed to save intake form');
    }
    setSubmittingIntake(false);
  };

  if (loading) return <div className="flex justify-center py-16"><Loader2 className="w-8 h-8 animate-spin text-primary" /></div>;
  if (loadError) return <div className="text-center py-16"><AlertCircle className="w-16 h-16 text-destructive/50 mx-auto mb-4" /><h3 className="text-lg font-semibold mb-1">Failed to load bookings</h3><p className="text-muted-foreground mb-4">{loadError}</p><Button variant="outline" onClick={() => window.location.reload()}>Retry</Button></div>;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">My Bookings & Appointments</h1>
        <p className="text-muted-foreground">Track your appointments and lab test bookings</p>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by clinic, test or doctor..." className="pl-10 h-11 text-sm rounded-xl bg-background border-border/50" />
        </div>
        <select value={typeFilter} onChange={e => setTypeFilter(e.target.value)}
          className="h-11 px-4 rounded-xl text-sm bg-background border border-border/50 text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20">
          <option value="All">All</option>
          <option value="appointment">Appointments</option>
          <option value="test">Lab Tests</option>
        </select>
      </div>

      {/* Status Pills */}
      <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none">
        {STATUS_FILTERS.map(s => (
          <button key={s} onClick={() => setStatusFilter(s)}
            className={cn(
              'px-4 py-2 rounded-xl text-xs font-medium whitespace-nowrap transition-all shrink-0 border',
              statusFilter === s
                ? 'bg-primary text-primary-foreground border-primary shadow-md shadow-primary/20'
                : 'bg-background text-muted-foreground hover:text-foreground border-border/50'
            )}>
            {s === 'All' ? 'All' : s}
          </button>
        ))}
      </div>

      {/* Active Bookings */}
      {activeBookings.length > 0 && (
        <div>
          <h2 className="font-heading font-semibold text-foreground text-sm mb-3 flex items-center gap-2">
            <Activity className="w-4 h-4 text-primary" />
            Active ({activeBookings.length})
          </h2>
          <div className="space-y-4">
            {activeBookings.map((booking, i) => (
              <BookingCard key={booking.id} booking={booking} index={i} onCancel={handleCancel} onOpenIntake={handleOpenIntake} />
            ))}
          </div>
        </div>
      )}

      {/* Past Bookings */}
      {pastBookings.length > 0 && (
        <div>
          <h2 className="font-heading font-semibold text-foreground text-sm mb-3 flex items-center gap-2">
            <Clock className="w-4 h-4 text-muted-foreground" />
            Past ({pastBookings.length})
          </h2>
          <div className="space-y-4">
            {pastBookings.map((booking, i) => (
              <BookingCard key={booking.id} booking={booking} index={i} onCancel={handleCancel} onOpenIntake={handleOpenIntake} />
            ))}
          </div>
        </div>
      )}

      {!loading && filtered.length === 0 && (
        <div className="text-center py-16 bg-card rounded-2xl border border-border/50">
          <CalendarDays className="w-12 h-12 text-muted-foreground/20 mx-auto mb-3" />
          <h3 className="text-sm font-semibold text-foreground mb-1">No bookings found</h3>
          <p className="text-xs text-muted-foreground">Try a different filter or search term</p>
          <Button variant="outline" size="sm" className="mt-4 rounded-xl" onClick={() => navigate('/diagnostic-centers')}>
            <FlaskConical className="w-3.5 h-3.5 mr-1.5" /> Book a Test
          </Button>
        </div>
      )}

      {/* Intake Form Modal */}
      <Dialog open={!!intakeModal} onOpenChange={(val) => !val && setIntakeModal(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Pre-Consultation Form</DialogTitle>
            <DialogDescription>
              Fill out your details before seeing the doctor to save time during your appointment.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleIntakeSubmit} className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Chief Complaint / Main Symptom</Label>
              <Input required value={intakeData.chiefComplaint} onChange={e => setIntakeData({...intakeData, chiefComplaint: e.target.value})} placeholder="e.g. Headache, Fever" />
            </div>
            <div className="space-y-2">
              <Label>Duration of Symptoms</Label>
              <Input value={intakeData.symptomsDuration} onChange={e => setIntakeData({...intakeData, symptomsDuration: e.target.value})} placeholder="e.g. 3 days" />
            </div>
            <div className="space-y-2">
              <Label>Past Medical History (Optional)</Label>
              <Textarea value={intakeData.pastMedicalHistory} onChange={e => setIntakeData({...intakeData, pastMedicalHistory: e.target.value})} placeholder="Any chronic conditions (e.g. Diabetes, Asthma)" className="resize-none" rows={2} />
            </div>
            <div className="space-y-2">
              <Label>Current Medications (Optional)</Label>
              <Input value={intakeData.currentMedications} onChange={e => setIntakeData({...intakeData, currentMedications: e.target.value})} placeholder="e.g. Paracetamol" />
            </div>
            <div className="space-y-2">
              <Label>Allergies (Optional)</Label>
              <Input value={intakeData.allergies} onChange={e => setIntakeData({...intakeData, allergies: e.target.value})} placeholder="Any food or drug allergies" />
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setIntakeModal(null)}>Cancel</Button>
              <Button type="submit" disabled={submittingIntake}>
                {submittingIntake && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                Save Details
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

const TEST_STATUS_FLOW = ['Pending', 'Confirmed', 'Sample Collected', 'Report Ready', 'Completed'];
const APPOINTMENT_STATUS_FLOW = ['Pending', 'Confirmed', 'In Queue', 'Serving', 'Completed'];

function getStep(status: Unmodelled, flow: Unmodelled) {
  return flow.indexOf(status);
}

function BookingCard({ booking, index, onCancel, onOpenIntake }: Unmodelled) {
  const navigate = useNavigate();
  const statusInfo = BOOKING_STATUS[booking.status] || BOOKING_STATUS.Pending;
  const StatusIcon = statusInfo.icon;
  const STATUS_FLOW = booking.type === 'appointment' ? APPOINTMENT_STATUS_FLOW : TEST_STATUS_FLOW;
  const currentStep = getStep(booking.status, STATUS_FLOW);

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.05 }}
      className="bg-card rounded-2xl border border-border/50 overflow-hidden hover:shadow-lg hover:border-primary/20 transition-all"
    >
      <div className="p-5">
        {/* Header */}
        <div className="flex items-start justify-between gap-3 mb-4">
          <div className="flex items-start gap-3 min-w-0">
            <div className={cn(
              'w-10 h-10 rounded-xl flex items-center justify-center shrink-0',
              booking.type === 'test' ? 'bg-primary/10' : 'bg-amber-500/10'
            )}>
              {booking.type === 'test'
                ? <FlaskConical className="w-5 h-5 text-primary" />
                : <CalendarDays className="w-5 h-5 text-amber-600" />
              }
            </div>
            <div className="min-w-0">
              <h3 className="font-heading font-semibold text-sm text-foreground truncate">{booking.source}</h3>
              <p className="text-xs text-muted-foreground mt-0.5">
                {booking.date} &bull; {booking.slot}
              </p>
              {booking.tests.length > 0 && (
                <p className="text-xs text-muted-foreground mt-1 line-clamp-1">
                  {booking.tests.join(', ')}
                </p>
              )}
            </div>
          </div>
          <span className={cn('inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-semibold border shrink-0', statusInfo.color)}>
            <StatusIcon className="w-3 h-3" />
            {statusInfo.label}
          </span>
        </div>

        {/* Status Timeline */}
        {booking.status !== 'Cancelled' && (
          <div className="flex items-center gap-1 mb-4 px-1">
            {STATUS_FLOW.map((step, i) => {
              const stepInfo = BOOKING_STATUS[step];
              const StepIcon = stepInfo.icon;
              const isActive = i <= currentStep;
              const isCurrent = i === currentStep;
              return (
                <div key={step} className="flex items-center flex-1 last:flex-none">
                  <div className={cn(
                    'flex items-center gap-1.5 text-[10px] font-medium',
                    isActive ? (isCurrent ? 'text-primary' : 'text-success') : 'text-muted-foreground/40'
                  )}>
                    <div className={cn(
                      'w-6 h-6 rounded-full flex items-center justify-center border-2 transition-all',
                      isActive
                        ? (isCurrent ? 'border-primary bg-primary/10' : 'border-success bg-success/10')
                        : 'border-muted-foreground/20 bg-muted/30'
                    )}>
                      <StepIcon className={cn('w-3 h-3', isActive ? (isCurrent ? 'text-primary' : 'text-success') : 'text-muted-foreground/40')} />
                    </div>
                    <span className="hidden sm:inline whitespace-nowrap">{stepInfo.label}</span>
                  </div>
                  {i < STATUS_FLOW.length - 1 && (
                    <div className={cn(
                      'flex-1 h-0.5 mx-1.5 rounded-full',
                      i < currentStep ? 'bg-success/40' : 'bg-muted/50'
                    )} />
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* Actions */}
        <div className="flex items-center justify-between pt-3 border-t border-border/30">
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <IndianRupee className="w-3 h-3" />
            <span className="font-semibold text-foreground">₹{booking.amount}</span>
          </div>
          <div className="flex gap-2">
            {(booking.status === 'Scheduled' || booking.status === 'Confirmed' || booking.status === 'Pending') && booking.type === 'appointment' && (
              <Button size="sm" variant="outline" className="text-xs h-8 text-primary border-primary/30 hover:bg-primary/10"
                onClick={() => onOpenIntake(booking)}>
                <FileText className="w-3 h-3 mr-1" />
                {booking._raw?.preConsultationDetails?.filledAt ? 'Edit Intake' : 'Fill Intake'}
              </Button>
            )}
            {(booking.status === 'Scheduled' || booking.status === 'Confirmed' || booking.status === 'Pending') && (
              <Button variant="ghost" size="sm" className="text-xs h-8 text-destructive hover:text-destructive"
                onClick={() => onCancel(booking)}>
                <XCircle className="w-3 h-3 mr-1" /> Cancel
              </Button>
            )}
            {booking.status === 'Report Ready' && (
              <Button size="sm" className="text-xs h-8 gap-1" onClick={() => navigate('/patient/reports')}>
                <FileText className="w-3 h-3" /> View Report
              </Button>
            )}
            {booking.phone ? (
              <div className="flex gap-1">
                <Button variant="outline" size="sm" className="text-xs h-8 gap-1.5 hover:bg-success/10 hover:text-success hover:border-success/30 transition-all group relative"
                  onClick={() => { window.location.href = `tel:${booking.phone}`; }}
                  title={`Call ${booking.phone}`}>
                  <PhoneCall className="w-3.5 h-3.5 group-hover:animate-bounce" />
                  <span>Call</span>
                </Button>
                <Button variant="outline" size="sm" className="text-xs h-8 gap-1.5 hover:bg-primary/10 hover:text-primary hover:border-primary/30 transition-all group relative"
                  onClick={() => { window.open(`https://wa.me/${booking.phone.replace(/[^0-9]/g, '')}`, '_blank'); }}
                  title={`WhatsApp ${booking.phone}`}>
                  <MessageCircle className="w-3.5 h-3.5 group-hover:scale-110 transition-transform" />
                </Button>
              </div>
            ) : (
              <Button variant="outline" size="sm" className="text-xs h-8 gap-1.5" disabled>
                <Phone className="w-3 h-3" /> Contact
              </Button>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Heart,
  Calendar,
  Clock,
  Pill,
  Activity,
  Plus,
  CheckCircle2,
  AlertTriangle,
  FileText,
  User,
  Share2,
  TrendingUp,
  Download,
  Pause,
  Play,
  X,
  Stethoscope,
  ChevronRight,
  ExternalLink,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { useNavigate } from 'react-router-dom';
import { api } from '@/lib/api';

const CONDITIONS = [
  'Diabetes',
  'Hypertension',
  'Thyroid',
  'Asthma',
  'Heart Disease',
  'Arthritis',
  'COPD',
  'Other',
];

export default function PatientCarePlan() {
  const navigate = useNavigate();
  const [carePlans, setCarePlans] = useState<any[]>([]);
  const [selectedPlan, setSelectedPlan] = useState<any>(null);
  const [todayChecklist, setTodayChecklist] = useState<any>(null);
  const [doctors, setDoctors] = useState<any[]>([]);
  const [existingReminders, setExistingReminders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);

  // Form State
  const [planName, setPlanName] = useState('');
  const [condition, setCondition] = useState('Diabetes');
  const [customCondition, setCustomCondition] = useState('');
  const [linkedDoctorId, setLinkedDoctorId] = useState('');
  const [selectedReminders, setSelectedReminders] = useState<string[]>([]);
  const [trackedVitals, setTrackedVitals] = useState<string[]>(['blood_sugar', 'weight']);
  const [sugarMin, setSugarMin] = useState('80');
  const [sugarMax, setSugarMax] = useState('130');
  const [bpSysMax, setBpSysMax] = useState('135');
  const [followUpDays, setFollowUpDays] = useState('30');
  const [shareWithDoctor, setShareWithDoctor] = useState(true);
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const selectedPlanRef = useRef<any>(null);
  selectedPlanRef.current = selectedPlan;

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [plansRes, docsRes, remsRes] = await Promise.allSettled([
        api.getCarePlans(),
        api.getDoctors(),
        api.getMedicineReminders(),
      ]);

      if (plansRes.status === 'fulfilled') {
        const plans = plansRes.value.carePlans || [];
        setCarePlans(plans);
        if (plans.length > 0 && !selectedPlanRef.current) {
          loadPlanDetails(plans[0]._id);
        }
      }
      if (docsRes.status === 'fulfilled') {
        const dList = docsRes.value.doctors || docsRes.value.data || docsRes.value || [];
        setDoctors(Array.isArray(dList) ? dList : []);
      }
      if (remsRes.status === 'fulfilled') {
        setExistingReminders(remsRes.value.reminders || []);
      }
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to load care plans');
    } finally {
      setLoading(false);
    }
  }, []);

  const loadPlanDetails = async (id: string) => {
    try {
      const [detailRes, todayRes] = await Promise.allSettled([
        api.getCarePlan(id),
        api.getCarePlanToday(id),
      ]);
      if (detailRes.status === 'fulfilled') {
        setSelectedPlan(detailRes.value.carePlan);
      } else {
        toast.error('Care plan details load nahi ho payi');
      }
      if (todayRes.status === 'fulfilled') {
        setTodayChecklist(todayRes.value);
      }
    } catch (err: any) {
      console.error(err);
    }
  };

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleCreatePlan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!planName.trim()) {
      return toast.error('Please provide a Care Plan name');
    }

    try {
      setSubmitting(true);
      const vitalsArray = trackedVitals.map(v => {
        const item: any = { vitalType: v };
        if (v === 'blood_sugar') {
          item.personalizedTarget = { min: Number(sugarMin) || 70, max: Number(sugarMax) || 140 };
          item.targetDescription = `Target: ${sugarMin}–${sugarMax} mg/dL`;
        } else if (v === 'bp') {
          item.personalizedTarget = { min: 90, max: Number(bpSysMax) || 135 };
          item.targetDescription = `Target Systolic < ${bpSysMax} mmHg`;
        }
        return item;
      });

      const payload = {
        planName,
        condition,
        customCondition,
        linkedDoctorId: linkedDoctorId || null,
        medicineReminderIds: selectedReminders,
        vitalsTracked: vitalsArray,
        followUpIntervalDays: Number(followUpDays) || 30,
        shareWithDoctor,
        notes,
      };

      const res = await api.createCarePlan(payload);
      toast.success('Care Plan created successfully');
      setShowCreateModal(false);
      loadData();
      if (res.carePlan) {
        loadPlanDetails(res.carePlan._id);
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to create care plan');
    } finally {
      setSubmitting(false);
    }
  };

  const handleToggleStatus = async (plan: any) => {
    const nextStatus = plan.status === 'active' ? 'paused' : 'active';
    try {
      await api.updateCarePlanStatus(plan._id, nextStatus);
      toast.success(`Plan marked as ${nextStatus}`);
      loadData();
      if (selectedPlan?._id === plan._id) {
        loadPlanDetails(plan._id);
      }
    } catch {
      toast.error('Failed to update plan status');
    }
  };

  const handleToggleConsent = async (plan: any) => {
    const nextConsent = !plan.shareWithDoctor;
    try {
      await api.updateCarePlanConsent(plan._id, nextConsent);
      toast.success(`Doctor sharing ${nextConsent ? 'enabled' : 'disabled'}`);
      loadData();
      if (selectedPlan?._id === plan._id) {
        setSelectedPlan({ ...selectedPlan, shareWithDoctor: nextConsent });
      }
    } catch {
      toast.error('Failed to update consent');
    }
  };

  const handleCheckDose = async (item: any) => {
    try {
      await api.respondMedicineDose(item.reminderId, {
        status: 'taken',
        scheduledAt: item.scheduledAt,
      });
      toast.success(`Recorded dose as taken for ${item.medicineName}`);
      if (selectedPlan) {
        loadPlanDetails(selectedPlan._id);
      }
    } catch {
      toast.error('Failed to record dose');
    }
  };

  const handlePrintReport = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-teal-600 via-emerald-600 to-cyan-600 p-6 sm:p-8 text-white shadow-xl">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="space-y-2">
            <div className="inline-flex items-center gap-2 rounded-full bg-white/20 px-3 py-1 text-xs font-semibold backdrop-blur-md">
              <Heart className="h-3.5 w-3.5" />
              Chronic Disease Management
            </div>
            <h1 className="font-heading text-2xl sm:text-3xl font-bold tracking-tight">
              Chronic Disease Care Plans
            </h1>
            <p className="max-w-xl text-sm text-white/80">
              Bundle your medicines, home vitals tracking, and regular follow-up visits under a single comprehensive care plan for your condition.
            </p>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <Button
              onClick={() => setShowCreateModal(true)}
              className="gap-2 rounded-2xl bg-white text-teal-700 hover:bg-white/90 font-bold shadow-lg shadow-black/10"
            >
              <Plus className="h-4 w-4" />
              Create Care Plan
            </Button>
          </div>
        </div>
      </div>

      {loading ? (
        <div className="flex h-48 items-center justify-center rounded-3xl border border-dashed text-muted-foreground">
          Loading care plans...
        </div>
      ) : carePlans.length === 0 ? (
        /* Empty State */
        <div className="flex flex-col items-center justify-center rounded-3xl border border-dashed border-border/80 bg-muted/20 p-12 text-center">
          <div className="h-16 w-16 rounded-2xl bg-teal-500/10 flex items-center justify-center text-teal-600 mb-4">
            <Heart className="h-8 w-8" />
          </div>
          <h3 className="font-heading font-bold text-lg text-foreground">
            No Care Plans created yet
          </h3>
          <p className="mt-1 max-w-md text-sm text-muted-foreground">
            Care Plans help you manage chronic conditions like Diabetes or Hypertension with linked medicine reminders, home vitals checks, and doctor visibility — all in one place.
          </p>
          <Button onClick={() => setShowCreateModal(true)} className="mt-5 gap-2 rounded-2xl font-bold">
            <Plus className="h-4 w-4" />
            Create Your First Care Plan
          </Button>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Column: Plan Selector & Switcher */}
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="font-heading text-lg font-bold text-foreground">
                Your Care Plans
              </h2>
              <span className="rounded-full bg-teal-500/10 px-2.5 py-0.5 text-xs font-semibold text-teal-600">
                {carePlans.length} Active
              </span>
            </div>

            <div className="space-y-3">
              {carePlans.map((plan) => {
                const isSelected = selectedPlan?._id === plan._id;
                const isPaused = plan.status === 'paused';
                return (
                  <div
                    key={plan._id}
                    onClick={() => loadPlanDetails(plan._id)}
                    className={`cursor-pointer rounded-3xl border p-5 transition-all shadow-sm ${
                      isSelected
                        ? 'border-teal-500 bg-teal-500/5 ring-2 ring-teal-500/20'
                        : 'border-border/80 bg-card hover:border-teal-500/40'
                    }`}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div>
                        <h3 className="font-heading font-bold text-base text-foreground">
                          {plan.planName}
                        </h3>
                        <span className="inline-block mt-0.5 text-xs font-semibold text-teal-600 dark:text-teal-400">
                          {plan.condition}
                        </span>
                      </div>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full capitalize ${
                        isPaused
                          ? 'bg-amber-500/10 text-amber-600'
                          : 'bg-emerald-500/10 text-emerald-600'
                      }`}>
                        {plan.status}
                      </span>
                    </div>

                    <div className="mt-3 flex items-center justify-between text-xs text-muted-foreground border-t pt-2.5">
                      <span>{plan.medicineReminderIds?.length || 0} Meds · {plan.vitalsTracked?.length || 0} Vitals</span>
                      <span className="font-medium text-foreground flex items-center gap-1">
                        View Details <ChevronRight className="h-3 w-3" />
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>

            <Button
              variant="outline"
              onClick={() => setShowCreateModal(true)}
              className="w-full rounded-2xl gap-2 border-dashed border-border/80"
            >
              <Plus className="h-4 w-4" />
              Create Another Care Plan
            </Button>
          </div>

          {/* Right Column: Selected Plan's "Today" View & Combined Trends */}
          {selectedPlan && (
            <div className="lg:col-span-2 space-y-6">
              {/* Plan Header Card */}
              <div className="rounded-3xl border border-border/80 bg-card p-6 shadow-sm">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                  <div>
                    <div className="flex items-center gap-2">
                      <h2 className="font-heading text-2xl font-bold text-foreground">
                        {selectedPlan.planName}
                      </h2>
                      <span className="text-xs font-bold px-2.5 py-0.5 rounded-full bg-teal-500/10 text-teal-600">
                        {selectedPlan.condition}
                      </span>
                    </div>
                    {selectedPlan.linkedDoctorId && (
                      <p className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                        <Stethoscope className="h-3.5 w-3.5 text-primary" />
                        Linked Doctor: <strong className="text-foreground">{selectedPlan.linkedDoctorId.name}</strong> ({selectedPlan.linkedDoctorId.specialization})
                      </p>
                    )}
                  </div>

                  <div className="flex flex-wrap items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleToggleConsent(selectedPlan)}
                      className={`rounded-xl text-xs font-semibold gap-1.5 ${
                        selectedPlan.shareWithDoctor
                          ? 'border-emerald-500/30 text-emerald-600 bg-emerald-500/5'
                          : 'text-muted-foreground'
                      }`}
                    >
                      <Share2 className="h-3.5 w-3.5" />
                      {selectedPlan.shareWithDoctor ? 'Sharing with Doctor (Consented)' : 'Doctor Sharing Off'}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleToggleStatus(selectedPlan)}
                      className="rounded-xl text-xs gap-1.5"
                    >
                      {selectedPlan.status === 'active' ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
                      {selectedPlan.status === 'active' ? 'Pause Plan' : 'Resume Plan'}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handlePrintReport}
                      className="rounded-xl text-xs gap-1.5"
                    >
                      <Download className="h-3.5 w-3.5" />
                      Export Report
                    </Button>
                  </div>
                </div>

                {/* Insight Banner */}
                {selectedPlan.correlationInsight && (
                  <div className="mt-4 rounded-2xl border border-teal-500/30 bg-teal-500/10 p-3.5 text-xs text-teal-800 dark:text-teal-200 flex items-start gap-2.5">
                    <TrendingUp className="h-4 w-4 text-teal-600 flex-shrink-0 mt-0.5" />
                    <div>
                      <strong className="font-semibold block">Health Insight</strong>
                      {selectedPlan.correlationInsight}
                    </div>
                  </div>
                )}
              </div>

              {/* Combined "Today" Checklist */}
              <div className="rounded-3xl border border-border/80 bg-card p-6 shadow-sm space-y-5">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="font-heading font-bold text-lg text-foreground">
                      Today's Plan Checklist
                    </h3>
                    <p className="text-xs text-muted-foreground">
                      Complete your medicine doses and vitals checks for today in one place.
                    </p>
                  </div>
                  <div className="flex items-center gap-1.5 text-xs font-semibold text-muted-foreground">
                    <Calendar className="h-4 w-4 text-primary" />
                    {new Date().toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' })}
                  </div>
                </div>

                {/* Medicines Checklist */}
                <div>
                  <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-2 flex items-center gap-1.5">
                    <Pill className="h-3.5 w-3.5 text-blue-500" />
                    Prescribed Medicines Due Today
                  </h4>
