}

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  ShieldCheck, FileText, CheckCircle2, Clock, AlertCircle, Building2,
  Download, ArrowRight, ExternalLink, Plus, Sparkles
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';

const fmtDate = (iso: any) => {
  if (!iso) return '—';
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? '—' : d.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
};
const fmtINR = (n: any) => (n === null || n === undefined || n === '' ? '—' : `₹${Number(n).toLocaleString('en-IN')}`);

export default function PatientInsurance() {
  interface PolicyRow {
    id: string;
    type: string;
    insurer: string;
    policyNo: string;
    status: string;
    insuredMembers: string;
    validTill: string;
    tpa: string;
  }
  interface ClaimRow {
    id: string;
    procedure: string;
    status: string;
    claimRef: string;
    date: string;
    amountApproved: string;
    amountClaimed: string;
  }
  const [policies, setPolicies] = useState<PolicyRow[]>([]);
  const [claims, setClaims] = useState<ClaimRow[]>([]);
  const [loading, setLoading] = useState(true);

  // Live data only (GET /patient/insurance/policies + GET /insurance,
  // both session-scoped). Empty lists render empty states, never fixtures.
  useEffect(() => {
    let cancelled = false;
    Promise.allSettled([api.getMyInsurancePolicies(), api.getMyInsuranceClaims()])
      .then(([pol, clm]) => {
        if (cancelled) return;
        const prow = pol.status === 'fulfilled' ? pol.value : null;
        const crows = clm.status === 'fulfilled' ? clm.value : null;
        const livePolicies = Array.isArray(prow?.policies) ? prow.policies : [];
        const liveClaims = Array.isArray(crows?.claims) ? crows.claims : [];
        setPolicies(livePolicies.map((r: any) => ({
          id: String(r._id || r.id),
          type: r.scheme || 'Health Insurance',
          insurer: r.insurer || '—',
          policyNo: r.policyNumber || '—',
          status: r.status || 'active',
          insuredMembers: Array.isArray(r.memberIds) && r.memberIds.length ? r.memberIds.join(', ') : 'Self',
          validTill: fmtDate(r.validTo),
          tpa: r.tpa || '—',
        })));
        setClaims(liveClaims.map((c: any) => ({
          id: String(c._id || c.claimId || c.id),
          procedure: c.claimId ? `Claim ${c.claimId}` : 'Insurance Claim',
          status: c.claimStatus || c.status || 'Filed',
          hospital: '',
          claimRef: c.claimId || '',
          date: fmtDate(c.createdAt || c.updatedAt),
          amountApproved: fmtINR(c.approvedAmount),
          amountClaimed: fmtINR(c.claimAmount),
        })));
      })
      .catch(() => {
        if (!cancelled) {
          setPolicies([]);
          setClaims([]);
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 py-6 space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-border/40">
        <div>
          <h1 className="font-heading text-2xl font-bold text-foreground">Insurance Policies & Cashless Claims</h1>
          <p className="text-xs text-muted-foreground mt-0.5">
            Store health insurance cards, link PM-JAY/CGHS schemes, and track real-time hospital cashless pre-authorizations.
          </p>
        </div>

        <Button
          size="sm"
          onClick={() => toast.info('Opening add policy dialog...')}
          className="rounded-xl text-xs font-semibold gap-1.5"
        >
          <Plus className="w-3.5 h-3.5" /> Link New Policy / TPA Card
        </Button>
      </div>

      {/* Active Policies Grid */}
      <div className="space-y-3">
        <h2 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Active Health Coverage</h2>
        {loading && <p className="text-xs text-muted-foreground py-6 text-center">Loading your policies…</p>}
        {!loading && policies.length === 0 && (
          <div className="p-8 rounded-3xl border border-border/60 bg-card text-center space-y-2">
            <p className="font-bold text-sm text-foreground">No policies linked yet</p>
            <p className="text-xs text-muted-foreground">Link your health insurance card or PM-JAY/CGHS scheme to track cashless claims here.</p>
          </div>
        )}
        <div className="grid md:grid-cols-2 gap-4">
          {policies.map((p) => (
            <div
              key={p.id}
              className="p-5 rounded-3xl border border-border/60 bg-card space-y-4 shadow-xs relative overflow-hidden"
            >
              <div className="flex items-start justify-between gap-2">
                <div className="space-y-1">
                  <Badge variant="outline" className="bg-primary/10 text-primary border-primary/20 text-[10px] font-bold">
                    {p.type}
                  </Badge>
                  <h3 className="font-heading text-base font-bold text-foreground leading-tight">{p.insurer}</h3>
                  <p className="text-xs text-muted-foreground font-mono">{p.policyNo}</p>
                </div>
                <div className="text-right">
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${p.status === 'active' ? 'bg-emerald-500/10 text-emerald-600' : 'bg-muted text-muted-foreground'}`}>
                    {p.status === 'active' ? 'Active' : 'Expired'}
                  </span>
                </div>
              </div>

              <div className="p-3 rounded-2xl bg-muted/30 border border-border/40 text-xs space-y-1">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Covered:</span>
                  <strong className="text-foreground truncate max-w-[200px]">{p.insuredMembers}</strong>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Valid Until:</span>
                  <strong className="text-foreground">{p.validTill}</strong>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">TPA / Desk:</span>
                  <strong className="text-foreground">{p.tpa}</strong>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Cashless Claim Tracker */}
      <div className="space-y-3 pt-4">
        <div className="flex items-center justify-between">
          <h2 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Hospital Cashless Claim Tracker</h2>
          <Button
            variant="outline"
            size="sm"
            onClick={() => toast.info('Connecting to TPA cashless desk executive...')}
            className="h-7 text-xs rounded-lg gap-1"
          >
            <Clock className="w-3 h-3" /> Request Pre-Auth Assistance
          </Button>
        </div>

        <div className="rounded-3xl border border-border/60 bg-card overflow-hidden shadow-xs divide-y divide-border/40">
          {!loading && claims.length === 0 && (
            <p className="text-xs text-muted-foreground py-8 text-center">No cashless claims yet — your hospital claims will appear here.</p>
          )}
          {claims.map((c) => (
            <div key={c.id} className="p-4 sm:p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
              <div className="space-y-1">
                <div className="flex items-center gap-2">
                  <h3 className="font-bold text-sm text-foreground">{c.procedure}</h3>
                  <Badge variant="outline" className="bg-emerald-500/10 text-emerald-600 border-emerald-500/20 text-[10px] font-bold">
                    {c.status}
                  </Badge>
                </div>
                <p className="text-xs text-muted-foreground flex items-center gap-1">
                  <Building2 className="w-3.5 h-3.5 text-primary" /> Ref: {c.claimRef}
                </p>
                <p className="text-[11px] text-muted-foreground">Filed: {c.date}</p>
              </div>

              <div className="text-right sm:shrink-0 space-y-0.5">
                <span className="text-xs text-muted-foreground block">Approved Cashless Amount</span>
                <span className="text-base font-extrabold text-foreground">{c.amountApproved}</span>
                <span className="text-[10px] text-muted-foreground block">Claimed: {c.amountClaimed}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Scale,
  Calendar,
  Clock,
  CheckCircle2,
  FileText,
  Star,
  Download,
  RotateCcw,
  ArrowRight,
  Filter,
  Eye,
  ShieldCheck,
  CreditCard,
  Briefcase,
  Layers,
  FileArchive,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import { DataGrid } from '../../components/ui/System';
import { InstantSearchingScreen, InstantNoRespondersScreen, InstantAssignedScreen } from '../../components/instant';
import { api } from '../../lib/api';
import { toast } from 'sonner';
import type { Unmodelled } from '@/lib/apiTypes';

export default function PatientLawyers() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'cases' | 'bookings' | 'documents' | 'favorites'>('cases');

  const [activeBooking, setActiveBooking] = useState<any>(null);
  const [bookings, setBookings] = useState<any[]>([]);
  const [cases, setCases] = useState<any[]>([]);
  const [documents, setDocuments] = useState<any[]>([]);
  const [favorites, setFavorites] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const [statusFilter, setStatusFilter] = useState('all');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [expandedCaseId, setExpandedCaseId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [activeRes, bookingsRes, casesRes, docsRes, favRes] = await Promise.all([
        api.getActiveLawyerBooking().catch(() => ({ activeBooking: null })),
        (api as Unmodelled).getMyLawyerBookings({
          status: statusFilter !== 'all' ? statusFilter : undefined,
          category: categoryFilter !== 'all' ? categoryFilter : undefined,
        }).catch(() => ({ bookings: [] })),
        api.getMyLawyerCases().catch(() => ({ cases: [] })),
        (api as Unmodelled).getLawyerDocumentsVault().catch(() => ({ documents: [] })),
        api.getFavoriteLawyers().catch(() => ({ favorites: [] })),
      ]);

      setActiveBooking(activeRes?.activeBooking || null);
      setBookings(bookingsRes?.bookings || []);
      setCases(casesRes?.cases || []);
      setDocuments(docsRes?.documents || []);
      setFavorites(favRes?.favorites || []);
    } catch (err: any) {
      console.error('Failed to fetch legal console data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [statusFilter, categoryFilter]);

  // Real-time Socket listener for lawyer booking updates & instant wave
  useEffect(() => {
    if (!activeBooking?._id) return;
    const bookingId = String(activeBooking._id);
    let socket: any;

    (async () => {
      try {
        const { getSocket, joinLawyerBookingRoom } = await import('../../lib/socket');
        socket = getSocket();
        const cleanupRoom = joinLawyerBookingRoom(bookingId);

        const handleSearchUpdate = (data: any) => {
          if (String(data.bookingId || data.requestId) === bookingId) {
            setActiveBooking((prev: any) => ({
              ...prev,
              currentSearchRadiusKm: data.radiusKm,
            }));
          }
        };

        const handleAssigned = (data: any) => {
          if (String(data.bookingId || data.requestId) === bookingId) {
            setActiveBooking((prev: any) => ({
              ...prev,
              status: 'confirmed',
              lawyerId: data.providerId || data.lawyerId,
              assignedDetails: data,
            }));
            fetchData();
          }
        };

        const handleNoResponders = (data: any) => {
          if (String(data.bookingId || data.requestId) === bookingId) {
            setActiveBooking((prev: any) => ({
              ...prev,
              status: 'no_responders_found',
            }));
          }
        };

        const handleGeneralUpdate = () => {
          fetchData();
        };

        socket.on('lawyer:search_update', handleSearchUpdate);
        socket.on('lawyer:assigned', handleAssigned);
        socket.on('lawyer:no_responders_found', handleNoResponders);
        socket.on('lawyer_booking_updated', handleGeneralUpdate);

        return () => {
          cleanupRoom?.();
          socket.off('lawyer:search_update', handleSearchUpdate);
          socket.off('lawyer:assigned', handleAssigned);
          socket.off('lawyer:no_responders_found', handleNoResponders);
          socket.off('lawyer_booking_updated', handleGeneralUpdate);
        };
      } catch (err: any) {
        console.warn('Socket connection error in PatientLawyers:', err);
      }
    })();
  }, [activeBooking?._id]);

  const totalSpent = bookings
    .filter((b) => b.payment?.status === 'paid')
    .reduce((sum, b) => sum + (b.fee || 0), 0);

  const ongoingCasesCount = cases.filter((c) => c.status !== 'closed').length;

  const handleDownloadReceipt = (bookingId: string, bookingNumber?: string) => {
    api.downloadLawyerReceipt(
      bookingId,
      `Legal-Receipt-${bookingNumber || bookingId}.pdf`
    );
  };

  const handleCloseCase = async (threadId: string) => {
    if (!confirm('Are you sure you want to mark this legal case matter as closed?')) return;
    try {
      await (api as Unmodelled).closeLawyerCaseThread(threadId);
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to close case');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto space-y-7">
        {/* Header & Book Button */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-black text-slate-900 dark:text-slate-100 flex items-center gap-2">
              <Scale className="w-7 h-7 text-slate-900 dark:text-slate-100" />
              My Legal Help & Lawyer Consultations
            </h1>
            <p className="text-xs text-slate-500 mt-1">
              Track active hospital case proceedings, medical negligence filings, review consultation notes, and access fee receipts.
            </p>
          </div>

          <Button
            type="button"
            onClick={() => navigate('/find-lawyer')}
            className="bg-slate-900 hover:bg-black text-white font-bold text-xs rounded-xl shadow-md gap-1.5"
          >
            <Scale className="w-4 h-4" /> Book New Legal Consultation
          </Button>
        </div>

        {/* Top Banner: Active / In-Progress Consultation */}
        {activeBooking && (
          <div className="p-5 rounded-3xl bg-slate-900 text-white shadow-xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3.5">
              <div className="w-12 h-12 rounded-2xl bg-white/20 backdrop-blur-md flex items-center justify-center font-bold text-lg shrink-0">
                <span className="w-3.5 h-3.5 bg-emerald-400 rounded-full animate-ping" />
              </div>
              <div>
                <span className="text-[10px] font-extrabold uppercase px-2 py-0.5 rounded bg-white/20 tracking-wider">
                  {activeBooking.status.replace(/_/g, ' ')}
                </span>
                <h3 className="text-base font-bold mt-0.5">
                  Consultation in {activeBooking.category?.replace(/_/g, ' ')}
                </h3>
                <p className="text-xs text-slate-100">
                  Adv. {activeBooking.lawyerId?.userId?.name || 'Advocate'} • {activeBooking.consultationMode?.replace('_', ' ')}
                </p>
              </div>
            </div>

            <Button
              type="button"
              onClick={() => navigate(`/find-lawyer?bookingId=${activeBooking._id}`)}
              className="bg-white text-slate-900 hover:bg-slate-100 font-bold text-xs rounded-xl shadow-md gap-1 self-stretch sm:self-auto"
            >
              Open Consultation Window <ArrowRight className="w-4 h-4" />
            </Button>
          </div>
        )}

        {/* Quick Stats Widget */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-sm flex items-center gap-3.5">
            <div className="w-11 h-11 rounded-xl bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-slate-100 flex items-center justify-center font-bold">
              <Scale className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-black text-slate-900 dark:text-slate-100">
                {bookings.length}
              </div>
              <div className="text-xs text-slate-500">Total Consultations</div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-sm flex items-center gap-3.5">
            <div className="w-11 h-11 rounded-xl bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 flex items-center justify-center font-bold">
              <CreditCard className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-black text-slate-900 dark:text-slate-100">
                ₹{totalSpent.toLocaleString()}
              </div>
              <div className="text-xs text-slate-500">Total Legal Fees Settled</div>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-sm flex items-center gap-3.5">
            <div className="w-11 h-11 rounded-xl bg-slate-100 dark:bg-white/10 text-slate-800 dark:text-slate-200 flex items-center justify-center font-bold">
              <Layers className="w-5 h-5" />
            </div>
            <div>
              <div className="text-xl font-black text-slate-900 dark:text-slate-100">
                {ongoingCasesCount}
              </div>
              <div className="text-xs text-slate-500">Active Case Threads</div>
            </div>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex border-b border-slate-200 dark:border-slate-800 text-xs font-bold gap-6">
          <button
            type="button"
            onClick={() => setActiveTab('cases')}
            className={`pb-3 border-b-2 transition-colors flex items-center gap-1.5 ${
              activeTab === 'cases'
                ? 'border-slate-900 dark:border-white text-slate-900 dark:text-slate-100'
                : 'border-transparent text-slate-500 hover:text-slate-700'
            }`}
          >
            <Layers className="w-4 h-4" />
            My Case Matters ({cases.length})
          </button>

          <button
            type="button"
            onClick={() => setActiveTab('bookings')}
            className={`pb-3 border-b-2 transition-colors flex items-center gap-1.5 ${
              activeTab === 'bookings'
                ? 'border-slate-900 dark:border-white text-slate-900 dark:text-slate-100'
                : 'border-transparent text-slate-500 hover:text-slate-700'
            }`}
          >
            <Calendar className="w-4 h-4" />
            All Consultations ({bookings.length})
          </button>

          <button
