            onClick={() => setActiveTab('documents')}
            className={`pb-3 border-b-2 transition-colors flex items-center gap-1.5 ${
              activeTab === 'documents'
                ? 'border-slate-900 dark:border-white text-slate-900 dark:text-slate-100'
