                              <div className="flex items-center gap-2">
                                <span className="font-bold text-slate-700 dark:text-slate-300">
                                  ₹{sess.fee}
                                </span>
                                <Badge variant="outline" className="text-[10px]">
                                  {sess.payment?.status || 'unpaid'}
                                </Badge>
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="sm"
