                      <div className="mt-2 space-y-1">
                        {rx.medicines?.slice(0, 3).map((med: Unmodelled, idx: Unmodelled) => (
                          <div key={idx} className="flex items-center justify-between text-xs">
                            <div className="flex items-center gap-1.5 min-w-0">
