                      {med.dispensedAt && (
                        <p className="text-xs text-emerald-600 mt-1.5 ml-6 flex items-center gap-1">
                          <CheckCircle2 className="w-3 h-3" />
                          Dispensed on {new Date(med.dispensedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
                        </p>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex gap-2">
                <Button variant="outline" className="flex-1 rounded-xl" onClick={() => window.print()}>🖨️ Print</Button>
                <Button variant="outline" className="flex-1 rounded-xl" onClick={() => setSelectedRx(null)}>Close</Button>
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { useState, useRef } from 'react';
import { motion } from 'framer-motion';
import { Save, User, Camera, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import type { Unmodelled } from '@/lib/apiTypes';

const formatDate = (d: Unmodelled) => {
  if (!d) return '';
  try { return d.includes('T') ? d.split('T')[0] : String(d).slice(0, 10); } catch { return ''; }
};

export default function PatientProfile() {
  const { user, updateUser } = useAuth();
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  const [form, setForm] = useState({
    name: user?.name || '', email: user?.email || '', phone: user?.phone || '',
    address: user?.address || '', gender: user?.gender || '',
    dateOfBirth: formatDate(user?.dateOfBirth), bloodGroup: user?.bloodGroup || '',
    allergies: user?.allergies?.map((a: Unmodelled) => a.allergen).join(', ') || '',
  });
  const [saving, setSaving] = useState(false);

  const handleAvatarSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type)) {
      toast.error('Only JPEG, PNG, WEBP, and GIF images are allowed');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image size must be less than 5MB');
      return;
    }

    setUploadingAvatar(true);
    try {
      const data: any = await api.uploadAvatar(file);
      const avatar = data?.user?.avatar || data?.avatar || '';
      if (data?.user) updateUser(data.user);
      else updateUser({ avatar });
      toast.success('Profile photo updated successfully');
    } catch (err: any) {
      toast.error(err?.message || 'Failed to upload photo');
    } finally {
      setUploadingAvatar(false);
      if (e.target) e.target.value = '';
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await api.updateProfile(form);
      toast.success('Profile updated');
    } catch { toast.error('Failed to update profile'); }
    setSaving(false);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Profile Settings</h1>
        <p className="text-muted-foreground">Manage your personal information and medical history</p>
      </div>

      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
        className="bg-card rounded-xl border p-6 space-y-5 max-w-2xl">
        <input
          ref={fileInputRef}
          type="file"
          accept="image/jpeg,image/png,image/webp,image/gif"
          className="hidden"
          onChange={handleAvatarSelect}
        />
        <div className="flex items-center gap-4 pb-5 border-b">
          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
            <div className="w-16 h-16 rounded-full bg-primary/10 overflow-hidden flex items-center justify-center text-2xl font-bold text-primary border-2 border-primary/20">
              {uploadingAvatar ? (
                <Loader2 className="w-6 h-6 animate-spin text-primary" />
              ) : user?.avatar ? (
                <img src={user.avatar} alt={user?.name || 'User'} className="w-full h-full object-cover" />
              ) : (
                user?.name?.charAt(0) || 'U'
              )}
            </div>
            <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-card border-2 border-background rounded-full flex items-center justify-center shadow-sm">
              <Camera className="w-3.5 h-3.5 text-foreground" />
            </div>
          </div>
          <div>
            <p className="font-semibold text-lg">{user?.name}</p>
            <p className="text-sm text-muted-foreground">{user?.email} · {user?.phone}</p>
            {user?.uhid && <p className="text-xs text-primary font-mono">UHID: {user.uhid}</p>}
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploadingAvatar}
              className="text-xs text-primary hover:underline font-medium mt-1 block"
            >
              {uploadingAvatar ? 'Uploading...' : 'Change Photo'}
            </button>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          {[
            { key: 'name', label: 'Full Name' },
            { key: 'email', label: 'Email' },
            { key: 'phone', label: 'Phone' },
            { key: 'address', label: 'Address' },
            { key: 'gender', label: 'Gender' },
            { key: 'dateOfBirth', label: 'Date of Birth', type: 'date' },
            { key: 'bloodGroup', label: 'Blood Group' },
          ].map(f => (
            <div key={f.key}>
              <label className="text-sm font-medium mb-1 block">{f.label}</label>
              <Input type={f.type || 'text'} value={(form as Unmodelled)[f.key]} onChange={e => setForm({ ...form, [f.key]: e.target.value })} />
            </div>
          ))}
        </div>

        <div>
          <label className="text-sm font-medium mb-1 block">Allergies (comma separated)</label>
          <Input value={form.allergies} onChange={e => setForm({ ...form, allergies: e.target.value })} placeholder="e.g. Penicillin, Peanuts, Sulfa" />
          <p className="text-xs text-muted-foreground mt-1">This helps doctors and pharmacists avoid prescribing medicines you're allergic to.</p>
        </div>

        <Button className="w-full mt-6" onClick={handleSave} disabled={saving}>
          <Save className="w-4 h-4 mr-1" /> {saving ? 'Saving...' : 'Save Profile'}
        </Button>
      </motion.div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User, Calendar, Activity, Heart, Thermometer, FileText, Pipette, Clock, Search, AlertCircle, Pill, FlaskConical, Receipt, Wallet, Eye, Download, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { useAuth } from '@/context/AuthContext';
import { api, resolveFileUrl } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const categoryConfig: Unmodelled = {
  prescription:     { icon: Pill,         color: 'text-success',     bg: 'bg-success/10',     label: 'Prescriptions' },
  lab_report:       { icon: FlaskConical, color: 'text-warning',     bg: 'bg-warning/10',     label: 'Lab Reports' },
  discharge_summary:{ icon: FileText,     color: 'text-info',        bg: 'bg-info/10',        label: 'Discharge Summaries' },
  bill_invoice:     { icon: Receipt,       color: 'text-primary',     bg: 'bg-primary/10',     label: 'Bill Invoices' },
  payment_invoice:  { icon: Wallet,        color: 'text-success',     bg: 'bg-success/10',     label: 'Payment Invoices' },
};

const CATEGORIES = ['All', 'prescription', 'lab_report', 'discharge_summary', 'bill_invoice', 'payment_invoice'];

export default function PatientRecords() {
  const { user } = useAuth();
  const [appointments, setAppointments] = useState<ApiRow[]>([]);
  const [records, setRecords] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [viewRecord, setViewRecord] = useState<Unmodelled>(null);

  const loadData = async () => {
    setLoading(true);
    try {
      const [a, r] = await Promise.all([
        api.getAppointments(),
        api.getRecords(),
      ]);
      setAppointments(Array.isArray(a) ? a : (a?.appointments || a?.data || []));
      const recordsArray = Array.isArray(r) ? r : (r?.records || r?.data || []);
      setRecords(recordsArray);
    } catch (e: any) { console.error(e); toast.error('Failed to load records'); }
    setLoading(false);
  };

  useEffect(() => { loadData(); }, []);

  const filteredAppointments = appointments.filter(a => 
    search === '' || 
    a.doctor?.toLowerCase().includes(search.toLowerCase()) ||
    a.date?.includes(search)
  );

  const getPatientRecords = (date: Unmodelled) => records.filter(r => r.date === date);

  const getCategoryCounts = (recs: Unmodelled) => {
    const counts: Unmodelled = {};
    Object.keys(categoryConfig).forEach(key => counts[key] = 0);
    recs.forEach((r: Unmodelled) => {
      const type = (r.type || '').toLowerCase().replace(/\s+/g, '_');
      if (counts[type] !== undefined) counts[type]++;
    });
    return counts;
  };

  const calcAge = (dob: Unmodelled) => { if (!dob) return '--'; const a = Math.floor((+new Date() - +new Date(dob)) / 31557600000); return a >= 0 ? a : '--'; };
  const allergiesList = user?.allergies?.map((a: Unmodelled) => a.allergen || a).filter(Boolean).join(', ') || 'None';

  if (loading) return (
    <div className="flex justify-center py-20">
      <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Medical History</h1>
        <p className="text-muted-foreground">Your complete medical journey</p>
      </div>

      {/* Patient Summary Card */}
      <div className="bg-gradient-to-br from-primary/5 via-card to-card rounded-3xl border border-border/60 p-6">
        <div className="flex items-start gap-6">
          <div className="w-20 h-20 rounded-2xl bg-primary/20 flex items-center justify-center">
            <User className="w-10 h-10 text-primary" />
          </div>
          <div className="flex-1">
            <h2 className="font-heading text-2xl font-bold text-foreground">{user?.name || 'Patient'}</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
              <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">Age: <span className="text-foreground font-medium">{calcAge(user?.dateOfBirth)}</span></span>
              </div>
              <div className="flex items-center gap-2">
                <User className="w-4 h-4 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">Gender: <span className="text-foreground font-medium">{user?.gender || '--'}</span></span>
              </div>
              <div className="flex items-center gap-2">
                <Pipette className="w-4 h-4 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">Blood: <span className="text-foreground font-medium">{user?.bloodGroup || '--'}</span></span>
              </div>
              <div className="flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">Allergies: <span className="text-foreground font-medium">{allergiesList}</span></span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Search */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input 
          value={search} 
          onChange={e => setSearch(e.target.value)} 
          placeholder="Search by doctor or date..." 
          className="pl-10" 
        />
      </div>

      {/* Category filters */}
      <div className="flex gap-2 flex-wrap mb-6">
        {CATEGORIES.map(c => (
          <button key={c} onClick={() => setCategoryFilter(c)}
            className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${categoryFilter === c ? 'bg-primary text-primary-foreground border-primary' : 'border-border text-muted-foreground hover:border-primary/40'}`}>
            {c === 'All' ? 'All' : (categoryConfig[c]?.label || c)}
          </button>
        ))}
      </div>

      {/* Visit History Timeline */}
      <div className="bg-card rounded-2xl border border-border/60 p-6">
        <h3 className="font-heading text-lg font-semibold text-foreground mb-6 flex items-center gap-2">
          <Clock className="w-5 h-5 text-primary" /> Visit History
        </h3>

        {filteredAppointments.length === 0 ? (
          <div className="text-center py-12 text-muted-foreground">
            <Calendar className="w-12 h-12 mx-auto mb-2 opacity-30" />
            <p>No visits yet</p>
          </div>
        ) : (
          <div className="relative">
            {/* Timeline line */}
            <div className="absolute left-4 top-0 bottom-0 w-0.5 bg-border" />

            <div className="space-y-6">
              {filteredAppointments.map((apt, i) => {
                const visitRecords = getPatientRecords(apt.date);
                const hasRecords = visitRecords.length > 0;

                return (
              <motion.div 
                key={apt._id || i} 
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: i * 0.05 }}
                className="relative pl-12"
              >
                {/* Category counts for this visit */}
                {(() => {
                  const visitRecs = getPatientRecords(apt.date);
                  if (categoryFilter !== 'All') {
                    const filtered = visitRecs.filter(r => {
                      const type = (r.type || '').toLowerCase().replace(/\s+/g, '_');
                      return type === categoryFilter;
                    });
                    if (filtered.length === 0) return null;
                  }
                  const counts = getCategoryCounts(visitRecs);
                  const hasAny = Object.values(counts).some((v: Unmodelled) => v > 0);
                  if (!hasAny) return null;
                  return (
                    <div className="flex gap-2 mb-3 flex-wrap">
                      {Object.entries(categoryConfig).map(([key, cfg]: Unmodelled) => {
                        const Icon = cfg.icon;
                        return (
                          <div key={key} className={`flex items-center gap-1 px-2 py-0.5 rounded-md ${cfg.bg} ${counts[key] > 0 ? '' : 'opacity-40'}`}>
                            <Icon className={`w-3 h-3 ${cfg.color}`} />
                            <span className={`text-[10px] font-medium ${cfg.color}`}>{counts[key]}</span>
                          </div>
                        );
                      })}
                    </div>
                  );
                })()}
                    {/* Timeline dot */}
                    <div className={`absolute left-0 w-8 h-8 rounded-full flex items-center justify-center ${
                      apt.status === 'Confirmed' 
                        ? 'bg-success/20 text-success' 
                        : apt.status === 'Completed'
                        ? 'bg-primary/20 text-primary'
                        : 'bg-warning/20 text-warning'
                    }`}>
                      {hasRecords ? <FileText className="w-4 h-4" /> : <Calendar className="w-4 h-4" />}
                    </div>

                    {/* Visit card */}
                    <div className="bg-muted/30 rounded-xl border border-border/40 p-4 hover:bg-muted/50 transition-colors">
                      <div className="flex items-start justify-between mb-3">
                        <div>
                          <div className="flex items-center gap-2 mb-1">
                            <span className="font-medium text-foreground">{apt.date}</span>
                          </div>
                          <p className="text-sm text-muted-foreground">
                            {apt.time} • {apt.department}
                          </p>
                        </div>
                        <div className="text-right">
                          <p className="font-medium text-foreground">{apt.doctor}</p>
                          <p className="text-xs text-muted-foreground">Department</p>
                        </div>
                      </div>

                        {/* Diagnosis from records */}
                        {hasRecords && visitRecords
                          .filter(r => categoryFilter === 'All' || (r.type || '').toLowerCase().replace(/\s+/g, '_') === categoryFilter)
                          .map((rec, j) => {
                            const typeKey = (rec.type || '').toLowerCase().replace(/\s+/g, '_');
                            const cfg = categoryConfig[typeKey] || { icon: FileText, color: 'text-muted-foreground', bg: 'bg-muted/50' };
                            const Icon = cfg.icon;
                            return (
                              <div key={rec._id || j} className="mt-2 p-2 rounded-lg bg-muted/40 border border-border/50">
                                <div className="flex items-center gap-2 mb-1">
                                  <div className={`w-5 h-5 rounded ${cfg.bg} flex items-center justify-center`}>
                                    <Icon className={`w-3 h-3 ${cfg.color}`} />
                                  </div>
                                  <span className="text-xs font-semibold text-foreground">{rec.diagnosis || rec.type}</span>
                                  <span className="text-[10px] text-muted-foreground ml-auto">{rec.date}</span>
                                </div>
                                {rec.prescription && <p className="text-xs text-muted-foreground line-clamp-2 ml-7">Rx: {rec.prescription}</p>}
                                  <div className="flex gap-1 ml-7 mt-1">
                                    {(rec.attachments?.length > 0 || rec.data?.fileUrl || rec.data?.uploadedFile?.url || rec.fileUrl) && (
                                      <Button variant="ghost" size="sm" className="h-6 text-xs gap-1" onClick={() => window.open(resolveFileUrl(rec.attachments?.[0]?.url || rec.data?.fileUrl || rec.data?.uploadedFile?.url || rec.fileUrl || ''), '_blank')}>
                                        <FileText className="w-3 h-3" /> View Document
                                      </Button>
                                    )}
                                    <Button variant="ghost" size="sm" className="h-6 text-xs gap-1" onClick={() => setViewRecord(rec)}>
                                      <Eye className="w-3 h-3" /> Details
                                    </Button>
                                  </div>
                              </div>
                            );
                          })}

                      {/* Show symptoms if no records */}
                      {!hasRecords && apt.symptoms && (
                        <div className="mt-2 pt-2 border-t border-border/40">
                          <p className="text-xs text-muted-foreground">
                            <span className="font-medium">Symptoms:</span> {apt.symptoms}
                          </p>
                        </div>
                      )}
                    </div>
                  </motion.div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-foreground">{appointments.length}</p>
          <p className="text-xs text-muted-foreground">Total Visits</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-success">{appointments.filter(a => a.status === 'Completed').length}</p>
          <p className="text-xs text-muted-foreground">Completed</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-primary">{records.length}</p>
          <p className="text-xs text-muted-foreground">Records</p>
        </div>
        <div className="bg-card rounded-xl border border-border/60 p-4 text-center">
          <p className="text-2xl font-bold text-info">{appointments.filter(a => a.status === 'Confirmed').length}</p>
          <p className="text-xs text-muted-foreground">Upcoming</p>
        </div>
      </div>

      {/* Record Detail Modal */}
      {viewRecord && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setViewRecord(null)}>
          <div className="bg-card rounded-2xl border border-border w-full max-w-lg p-6 max-h-[80vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-heading text-lg font-bold text-foreground">{viewRecord.diagnosis || viewRecord.type}</h3>
              <button onClick={() => setViewRecord(null)}><X className="w-5 h-5" /></button>
            </div>
            <div className="space-y-3">
              <p className="text-sm text-muted-foreground">Type: <span className="text-foreground font-medium">{viewRecord.type}</span></p>
              <p className="text-sm text-muted-foreground">Date: <span className="text-foreground font-medium">{viewRecord.date}</span></p>
              {viewRecord.diagnosis && <p className="text-sm text-muted-foreground">Diagnosis: <span className="text-foreground font-medium">{viewRecord.diagnosis}</span></p>}
              {viewRecord.prescription && (
                <div>
                  <p className="text-sm font-medium text-foreground mb-1">Prescription:</p>
                  <pre className="text-sm bg-muted/30 rounded-lg p-3 whitespace-pre-wrap">{viewRecord.prescription}</pre>
                </div>
              )}
              {viewRecord.notes && (
                <div>
                  <p className="text-sm font-medium text-foreground mb-1">Notes:</p>
                  <p className="text-sm bg-muted/30 rounded-lg p-3">{viewRecord.notes}</p>
                </div>
              )}
              {viewRecord.data?.medications?.length > 0 && (
                <div>
                  <p className="text-sm font-medium text-foreground mb-1">Medications:</p>
                  <div className="space-y-1">
                    {viewRecord.data.medications.map((m: Unmodelled, i: Unmodelled) => (
                      <p key={i} className="text-sm bg-muted/30 rounded-lg p-2">{m.name} - {m.dosage} - {m.frequency}{m.instructions ? ` (${m.instructions})` : ''}</p>
                    ))}
                  </div>
                </div>
              )}
              {viewRecord.data?.tests?.length > 0 && (
                <div>
                  <p className="text-sm font-medium text-foreground mb-1">Test Results:</p>
                  <div className="space-y-1">
                    {viewRecord.data.tests.map((t: Unmodelled, i: Unmodelled) => (
                      <p key={i} className="text-sm bg-muted/30 rounded-lg p-2">{t.name}: {t.result} {t.unit} (Ref: {t.referenceRange})</p>
                    ))}
                  </div>
                </div>
              )}
              {(viewRecord.attachments?.length > 0 || viewRecord.data?.fileUrl || viewRecord.data?.uploadedFile?.url || viewRecord.fileUrl) && (
                <Button className="w-full gap-2" onClick={() => window.open(resolveFileUrl(viewRecord.attachments?.[0]?.url || viewRecord.data?.fileUrl || viewRecord.data?.uploadedFile?.url || viewRecord.fileUrl || ''), '_blank')}>
                  <Download className="w-4 h-4" /> Download Document
                </Button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardContent } from '@/components/ui/card';
import ReferralCodeCard from '@/components/referral/ReferralCodeCard';
import ReferralHistoryList from '@/components/referral/ReferralHistoryList';
import { userFacingError } from '@/lib/errorCopy';

export default function PatientReferral() {
  const [code, setCode] = useState('');
  const [stats, setStats] = useState<any>({ totalReferred: 0, qualified: 0, pending: 0 });
  const [history, setHistory] = useState<any[]>([]);

  useEffect(() => {
    (async () => {
      try {
        const c: any = await api.get('/referral/my-code').catch(() => ({}));
        setCode(c?.code || c?.referral?.code || '');
        const s: any = await api.get('/referral/stats').catch(() => ({}));
        setStats(s || {});
        const h: any = await api.get('/referral/my-history').catch(() => []);
        setHistory(Array.isArray(h) ? h : []);
      } catch (e: any) {
        toast.error(userFacingError(e, { fallback: 'Referral load failed' }));
      }
    })();
  }, []);

  return (
    <div className="max-w-2xl mx-auto p-4 space-y-4 pb-16">
      <ReferralCodeCard code={code} />
      <div className="grid grid-cols-3 gap-2">
        {[
          { label: 'Total Referred', value: stats.totalReferred || 0 },
          { label: 'Qualified', value: stats.qualified || stats.rewarded || 0 },
          { label: 'Pending', value: stats.pending || 0 },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="p-3 text-center">
              <p className="text-2xl font-black tabular-nums">{s.value}</p>
              <p className="text-[11px] text-muted-foreground">{s.label}</p>
            </CardContent>
          </Card>
        ))}
      </div>
      <Card>
        <CardContent className="p-4 space-y-1 text-sm">
          <p className="font-bold">How it works</p>
          <p className="text-xs text-muted-foreground">1. Share code → 2. Friend signs up → 3. Dono ko reward (first qualifying action ke baad)</p>
        </CardContent>
      </Card>
      <ReferralHistoryList items={history} />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { RotateCcw, Search, Calendar, Clock, IndianRupee, AlertCircle, Loader2, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const statusFilters = ['All', 'Pending', 'Processing', 'Refunded', 'Failed'];

const statusConfig: Unmodelled = {
  Pending: { label: 'Pending', color: 'bg-amber-500/10 text-amber-600 border-amber-500/20', icon: Clock },
  Processing: { label: 'Processing', color: 'bg-blue-500/10 text-blue-600 border-blue-500/20', icon: Loader2 },
  Refunded: { label: 'Refunded', color: 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20', icon: RotateCcw },
  Failed: { label: 'Failed', color: 'bg-red-500/10 text-red-600 border-red-500/20', icon: AlertCircle },
};

export default function PatientRefunds() {
  const [refunds, setRefunds] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');

  useEffect(() => {
    // Placeholder - content will be added later
    setLoading(false);
  }, []);

  const filtered = refunds.filter(r => {
    const ms = !search || (r.refundId || '').toLowerCase().includes(search.toLowerCase());
    const mf = filter === 'All' || r.status === filter;
    return ms && mf;
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">My Refunds</h1>
        <p className="text-muted-foreground text-sm">{refunds.length} total refund requests</p>
      </div>

      {/* Stats Cards */}
      {refunds.length > 0 && (
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
          className="grid grid-cols-2 sm:grid-cols-5 gap-3">
          {statusFilters.map((s) => {
            const count = s === 'All' ? refunds.length : refunds.filter(r => r.status === s).length;
            const cfg = statusConfig[s] || { icon: FileText, color: 'text-muted-foreground bg-muted/30' };
            const StatusIcon = cfg.icon;
            const colorParts = cfg.color.split(' ');
            if (s === 'All') {
              return (
                <div key={s} className="bg-card rounded-2xl border border-border/50 p-4 shadow-sm">
                  <div className="flex items-center gap-2.5 mb-2">
                    <div className="w-8 h-8 rounded-xl bg-primary/10 flex items-center justify-center">
                      <RotateCcw className="w-4 h-4 text-primary" />
