import { toast } from 'sonner';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const ratingLevels = [
  { label: 'All', value: 0 },
  { label: '★★★★★', value: 5 },
  { label: '★★★★☆', value: 4 },
  { label: '★★★☆☆', value: 3 },
  { label: '★★☆☆☆', value: 2 },
  { label: '★☆☆☆☆', value: 1 },
];

function getInitials(name: Unmodelled) {
  if (!name) return '?';
  return name.split(' ').map((w: Unmodelled) => w[0]).join('').toUpperCase().slice(0, 2);
}

const avatarColors = [
  'bg-sky-500', 'bg-violet-500', 'bg-emerald-500', 'bg-amber-500',
  'bg-rose-500', 'bg-cyan-500', 'bg-indigo-500', 'bg-teal-500',
];

function getAvatarColor(name: Unmodelled) {
  if (!name) return avatarColors[0];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return avatarColors[Math.abs(hash) % avatarColors.length];
}

function formatDate(dateStr: Unmodelled) {
  if (!dateStr) return '';
  try {
    return new Date(dateStr).toLocaleDateString('en-IN', {
      year: 'numeric', month: 'short', day: 'numeric',
    });
  } catch { return dateStr; }
}

export default function PatientReviews() {
  const { user } = useAuth();
  const [reviews, setReviews] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [ratingFilter, setRatingFilter] = useState(0);

  const loadData = async () => {
    setLoading(true);
    try {
      const r = await api.getReviews();
      const reviewsList = r?.reviews || r?.data || r || [];
      const uid = String(user?.id || user?._id || "");
      setReviews(Array.isArray(reviewsList) ? reviewsList.filter(rv => rv.patientName === user?.name || (uid && String(rv.patientId || rv.patient_id || "") === uid)) : []);
    } catch (e: any) { console.error(e); }
    setLoading(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadData(); }, [user?.name]);

  const handleDelete = async (id: Unmodelled) => {
    try { await api.deleteReview(id); loadData(); toast.success('Review deleted'); } catch { toast.error('Failed to delete'); }
  };

  const filteredReviews = useMemo(() => {
    return reviews.filter((rv) => {
      const matchSearch = !search || (rv.doctorName || '').toLowerCase().includes(search.toLowerCase());
      const matchRating = ratingFilter === 0 || rv.rating === ratingFilter;
      return matchSearch && matchRating;
    });
  }, [reviews, search, ratingFilter]);

  const clearFilters = () => { setSearch(''); setRatingFilter(0); };
  const hasFilters = search || ratingFilter > 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">My Reviews</h1>
        <p className="text-muted-foreground">Your reviews across doctors and hospitals</p>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
        <div className="relative w-full sm:w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search by doctor name..."
            className="w-full h-10 pl-9 pr-3 rounded-xl border border-border bg-background text-sm outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-all"
          />
        </div>
        <div className="flex items-center gap-1.5 flex-wrap">
          <Filter className="w-4 h-4 text-muted-foreground shrink-0" />
          {ratingLevels.map((r) => (
            <button
              key={r.value}
              onClick={() => setRatingFilter(ratingFilter === r.value ? 0 : r.value)}
              className={`px-2.5 py-1.5 rounded-lg text-xs font-medium border transition-all ${
                ratingFilter === r.value
                  ? 'bg-primary/10 border-primary/30 text-primary'
                  : 'bg-card border-border/60 text-muted-foreground hover:border-primary/30 hover:text-foreground'
              }`}
            >
              {r.label}
            </button>
          ))}
        </div>
        {hasFilters && (
          <button onClick={clearFilters} className="flex items-center gap-1 text-xs text-muted-foreground hover:text-destructive transition-colors shrink-0">
            <X className="w-3.5 h-3.5" /> Clear
          </button>
        )}
      </div>

      {/* Content */}
      {loading ? (
        <div className="flex justify-center py-16">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
        </div>
      ) : filteredReviews.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          {hasFilters ? 'No reviews match your filters.' : "You haven't written any reviews yet."}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredReviews.map((rv, i) => (
            <motion.div
              key={rv._id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.04 }}
              className="group relative bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg hover:border-primary/20 transition-all duration-200"
            >
              {/* Delete button */}
              <button
                onClick={() => handleDelete(rv._id)}
                className="absolute top-3.5 right-3.5 opacity-0 group-hover:opacity-100 transition-opacity p-1.5 rounded-lg text-muted-foreground hover:text-destructive hover:bg-destructive/10"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>

              {/* Doctor avatar + name + stars */}
              <div className="flex items-start gap-3.5 mb-3.5">
                <div className={`w-10 h-10 rounded-xl ${getAvatarColor(rv.doctorName)} flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm`}>
                  {getInitials(rv.doctorName)}
                </div>
                <div className="min-w-0 flex-1">
                  <h3 className="font-semibold text-foreground truncate pr-6">{rv.doctorName || 'Unknown Doctor'}</h3>
                  <div className="flex items-center gap-1 mt-0.5">
                    {[1, 2, 3, 4, 5].map((s) => (
                      <Star key={s} className={`w-3.5 h-3.5 ${s <= rv.rating ? 'text-amber-500 fill-amber-500' : 'text-muted stroke-muted'}`} />
                    ))}
                    <span className="text-[11px] text-muted-foreground ml-1 font-medium">{rv.rating}.0</span>
                  </div>
                </div>
              </div>

              {/* Comment */}
              {rv.comment && (
                <p className="text-sm text-foreground/85 leading-relaxed mb-3.5 line-clamp-3">
                  &ldquo;{rv.comment}&rdquo;
                </p>
              )}

              {/* Footer */}
              <div className="flex items-center justify-between text-xs text-muted-foreground pt-3 border-t border-border/40">
                <div className="flex items-center gap-2">
                  <Calendar className="w-3.5 h-3.5" />
                  <span>{formatDate(rv.date || rv.createdAt)}</span>
                </div>
                {rv.facilityName && (
                  <div className="flex items-center gap-1.5">
                    <Stethoscope className="w-3.5 h-3.5" />
                    <span className="truncate max-w-[140px]">{rv.facilityName}</span>
                  </div>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import PointsHero from '@/components/loyalty/PointsHero';
import RewardCard from '@/components/loyalty/RewardCard';
import MyRedemptionsList from '@/components/loyalty/MyRedemptionsList';
import LoyaltyLedgerList from '@/components/loyalty/LoyaltyLedgerList';
import { userFacingError } from '@/lib/errorCopy';

export default function PatientRewards() {
  const [summary, setSummary] = useState<any>({ pointsBalance: 0, lifetimePoints: 0, tier: 'Bronze' });
  const [catalog, setCatalog] = useState<any[]>([]);
  const [redemptions, setRedemptions] = useState<any[]>([]);
  const [ledger, setLedger] = useState<any[]>([]);
  const [tab, setTab] = useState<'catalog' | 'codes' | 'history'>('catalog');
  const [redeeming, setRedeeming] = useState<string | null>(null);

  const load = async () => {
    try {
      const [s, c, r, l]: any[] = await Promise.all([
        api.get('/loyalty/summary').catch(() => ({ pointsBalance: 0, lifetimePoints: 0, tier: 'Bronze' })),
        api.get('/loyalty/catalog').catch(() => []),
        api.get('/loyalty/my-redemptions').catch(() => []),
        api.get('/loyalty/ledger').catch(() => []),
      ]);
      setSummary(s || { pointsBalance: 0, lifetimePoints: 0, tier: 'Bronze' });
      setCatalog(Array.isArray(c) ? c : c?.items || []);
      setRedemptions(Array.isArray(r) ? r : r?.items || []);
      setLedger(Array.isArray(l) ? l : l?.items || []);
    } catch (e: any) {
      toast.error(userFacingError(e, { fallback: 'Rewards load failed' }));
    }
  };

  useEffect(() => { load(); }, []);

  const redeem = async (id: string) => {
    if (!confirm('Points kharch honge, confirm?')) return;
    setRedeeming(id);
    try {
      const res: any = await api.post(`/loyalty/redeem/${id}`, {});
      toast.success(`Congratulations! Code: ${res.code}`);
      load();
    } catch (e: any) {
      toast.error(userFacingError(e, { fallback: 'Redeem failed' }));
    } finally {
      setRedeeming(null);
    }
  };

  return (
    <div className="max-w-3xl mx-auto p-4 space-y-4 pb-16">
      <PointsHero balance={summary.pointsBalance || 0} lifetime={summary.lifetimePoints || 0} tier={summary.tier || 'Bronze'} />
      <div className="flex gap-2">
        {(['catalog', 'codes', 'history'] as const).map((t) => (
          <Button key={t} size="sm" variant={tab === t ? 'default' : 'outline'} onClick={() => setTab(t)} className="rounded-full capitalize">
            {t === 'catalog' ? 'Rewards' : t === 'codes' ? 'My Codes' : 'History'}
          </Button>
        ))}
      </div>
      {tab === 'catalog' && (
        <div className="grid sm:grid-cols-2 gap-3">
          {catalog.map((item: any) => {
            const unlocked = (summary.pointsBalance || 0) >= (item.pointsRequired || 0);
            return <RewardCard key={item._id} item={item} unlocked={unlocked} pointsNeeded={Math.max(0, (item.pointsRequired || 0) - (summary.pointsBalance || 0))} onRedeem={redeem} redeeming={redeeming === item._id} />;
          })}
          {!catalog.length && <p className="text-sm text-muted-foreground">Koi reward active nahi hai.</p>}
        </div>
      )}
      {tab === 'codes' && <MyRedemptionsList items={redemptions} />}
      {tab === 'history' && <LoyaltyLedgerList items={ledger} />}
    </div>
  );
}

