import { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Activity, TestTube, Heart, Droplets, Thermometer, Calendar, CheckCircle, Loader2, IndianRupee, FileDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/context/AuthContext';
import { api, downloadPaymentInvoice, downloadBillPdf } from '@/lib/api';
import { bookTestLab } from '@/lib/testBooking';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const serviceIcons: Unmodelled = {
  bp_check: Thermometer,
  blood_sugar: Droplets,
  fbc: Activity,
  xray: TestTube,
  ecg: Heart,
  urine_test: Droplets,
  lipid_profile: Activity,
  thyroid: TestTube,
};

const categoryColors: Unmodelled = {
  Basic: 'bg-blue-500/10 text-blue-500 border-blue-500/20',
  Lab: 'bg-green-500/10 text-green-500 border-green-500/20',
  Imaging: 'bg-purple-500/10 text-purple-500 border-purple-500/20',
  Cardiac: 'bg-red-500/10 text-red-500 border-red-500/20',
};

const statusColors: Unmodelled = {
  Paid: 'bg-success/10 text-success',
  Pending: 'bg-warning/10 text-warning',
  Overdue: 'bg-destructive/10 text-destructive',
  Partial: 'bg-info/10 text-info',
};

const splitServiceNames = (service = '') => service
  .split(',')
  .map(item => item.trim())
  .filter(Boolean);

const isPatientBill = (bill: Unmodelled, user: Unmodelled) => {
  const userId = String(user?.id || user?._id || '');
  const patientId = bill?.patientId?._id || bill?.patientId;
  if (userId && patientId && String(patientId) === userId) return true;
  if (user?.name && (bill?.patient === user.name || bill?.patientId?.name === user.name)) return true;
  return false;
};

const isLabBill = (bill: Unmodelled, catalog: Unmodelled) => {
  if (bill?.source === 'lab') return true;
  if (Array.isArray(bill?.services) && bill.services.length > 0) return true;
  if (String(bill?.doctor || '').toLowerCase() === 'lab services') return true;
  const serviceText = String(bill?.service || '').toLowerCase();
  return catalog.some((service: Unmodelled) => serviceText.includes(String(service.name || '').toLowerCase()));
};

const buildLabBookings = (bills: Unmodelled, catalog: Unmodelled, user: Unmodelled) => (bills || [])
  .filter((bill: Unmodelled) => isPatientBill(bill, user))
  .filter((bill: Unmodelled) => isLabBill(bill, catalog))
  .map((bill: Unmodelled) => {
    const serviceNames = splitServiceNames(bill.service);
    const services = Array.isArray(bill.services) && bill.services.length > 0
      ? bill.services
      : serviceNames.map((name) => {
        const match = catalog.find((service: Unmodelled) => service.name === name);
        return match || { name, price: 0, category: 'Lab' };
      });

    return {
      id: bill._id || bill.invoiceId || bill.service,
      invoiceId: bill.invoiceId,
      date: bill.date,
      status: bill.status || 'Pending',
      amount: Number(bill.amount) || services.reduce((sum: Unmodelled, service: Unmodelled) => sum + (Number(service.price) || 0), 0),
      paid: Number(bill.paid) || 0,
      services,
    };
  });

export default function PatientServices() {
  const { user } = useAuth();
  const [services, setServices] = useState<ApiRow[]>([]);
  const [selectedServices, setSelectedServices] = useState<ApiRow[]>([]);
  const [bookedServices, setBookedServices] = useState<ApiRow[]>([]);
  const [lastBooking, setLastBooking] = useState<Unmodelled>(null);
  const [loading, setLoading] = useState(true);
  const [booking, setBooking] = useState(false);
  const [success, setSuccess] = useState(false);

  const loadServices = useCallback(async () => {
    setLoading(true);
    try {
      const [data, billingData] = await Promise.all([
        api.getLabServices(),
        api.getBilling(),
      ]);
      const servicesList = data?.services || data?.data || data || [];
      setServices(servicesList);
      const bills = billingData?.bills || billingData?.data || [];
      setBookedServices(buildLabBookings(bills, servicesList, user));
    } catch (e: any) { console.error(e); }
    setLoading(false);
  }, [user]);

  useEffect(() => {
    if (user) loadServices();
  }, [user, loadServices]);

  const toggleService = (service: Unmodelled) => {
    setSelectedServices(prev => {
      const exists = prev.find(s => s.id === service.id);
      if (exists) {
        return prev.filter(s => s.id !== service.id);
      }
      return [...prev, service];
    });
  };

  const totalAmount = selectedServices.reduce((sum, s) => sum + s.price, 0);

  const handleBook = async () => {
    if (selectedServices.length === 0) return;
    setBooking(true);
    try {
      const { booking, result } = await bookTestLab(
        {
          patientId: user?.id,
          patientName: user?.name || 'Patient',
          tests: selectedServices.map(s => s.name),
          testIds: selectedServices.map(s => s.id),
          totalAmount,
          visitType: 'Walk-in',
          status: 'Pending',
        },
        {
          amount: totalAmount,
          method: 'upi',
          description: `Lab Test - ${selectedServices.map(s => s.name).join(', ')}`,
          provider: 'Lab Services',
          lineItems: selectedServices.map(s => ({ name: s.name, price: s.price, qty: 1 })),
        }
      );
      const bookingInfo = buildLabBookings([{ ...booking, status: 'Paid', invoiceId: result.invoice_id, transactionId: result.transaction_id }], services, user)[0];
      if (bookingInfo) {
        setBookedServices(current => [bookingInfo, ...current.filter(item => item.id !== bookingInfo.id)]);
        setLastBooking(bookingInfo);
      }
      setSuccess(true);
      setSelectedServices([]);
    } catch (e: any) { console.error(e); toast?.error?.(e.message || 'Booking failed'); }
    setBooking(false);
  };

  if (loading) return (
    <div className="flex justify-center py-20">
      <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
    </div>
  );

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Lab Services</h1>
        <p className="text-muted-foreground">Book lab tests and diagnostics</p>
      </div>

      {success && lastBooking && (
        <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} className="bg-success/10 border border-success/20 rounded-2xl p-5">
          <div className="flex items-start gap-3">
            <div className="w-10 h-10 rounded-xl bg-success/15 flex items-center justify-center flex-shrink-0">
              <CheckCircle className="w-5 h-5 text-success" />
            </div>
            <div className="min-w-0">
              <h2 className="font-heading font-semibold text-foreground">Lab services booked</h2>
              <p className="text-sm text-muted-foreground mt-1">
                {lastBooking.services.map((service: Unmodelled) => service.name).join(', ')}
              </p>
              <p className="text-xs text-muted-foreground mt-1">Invoice {lastBooking.invoiceId || 'created'} is available in billing.</p>
              {lastBooking.transactionId && (
                <div className="flex gap-2 mt-3">
                  <Button size="sm" variant="outline" className="gap-1.5 rounded-xl h-8 text-xs"
                    onClick={() => downloadPaymentInvoice(lastBooking.transactionId, `invoice-${lastBooking.invoiceId || 'service'}.pdf`)}>
                    <FileDown className="w-3.5 h-3.5" /> Invoice
                  </Button>
                  <Button size="sm" variant="outline" className="gap-1.5 rounded-xl h-8 text-xs"
                    onClick={() => downloadBillPdf(lastBooking.transactionId, `bill-${lastBooking.invoiceId || 'service'}.pdf`)}>
                    <FileDown className="w-3.5 h-3.5" /> Bill
                  </Button>
                </div>
              )}
            </div>
          </div>
        </motion.div>
      )}

      {/* Selected Services Summary */}
      {selectedServices.length > 0 && (
        <div className="bg-card rounded-2xl border border-primary/30 p-5">
          <div className="flex items-center justify-between mb-4">
            <div>
              <p className="font-medium text-foreground">Selected Services ({selectedServices.length})</p>
              <p className="text-sm text-muted-foreground">Total: ₹{totalAmount}</p>
            </div>
            <Button onClick={handleBook} disabled={booking} className="gap-2">
              {booking ? <Loader2 className="w-4 h-4 animate-spin" /> : <Calendar className="w-4 h-4" />}
              {booking ? 'Booking...' : 'Book Now'}
            </Button>
          </div>
          <div className="flex flex-wrap gap-2">
            {selectedServices.map(s => (
              <span key={s.id} className="px-3 py-1 bg-primary/10 text-primary rounded-full text-sm">
                {s.name} - ₹{s.price}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Booked Services */}
      <div className="bg-card rounded-2xl border border-border/60 p-5">
