/**
 * 6.md §4 persona step ("What brings you here?"). Shown once on the patient
 * dashboard when no persona is stored; skippable (generic adult defaults).
 * Persists via PUT /patient/persona (closed vocabulary, audited). Changes
 * dashboard DEFAULTS only in later turns — never permissions.
 */
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '@/lib/api';

const OPTIONS = [
  { id: 'adult', emoji: '🧑' },
  { id: 'parent', emoji: '👶' },
  { id: 'elderly', emoji: '🧓' },
  { id: 'caregiver', emoji: '🤝' },
  { id: 'fitness', emoji: '💪' },
  { id: 'chronic', emoji: '📋' },
  { id: 'maternity', emoji: '🤰' },
];

export default function PersonaStep() {
  const { t } = useTranslation();
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    let cancelled = false;
    api.get('/patient/persona')
      .then((res: any) => {
        if (!cancelled && !res?.persona) setVisible(true);
      })
      .catch(() => {
        /* offline — stay hidden rather than nag */
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (!visible) return null;

  const choose = async (id: string | null) => {
    if (id) {
      try {
        await api.put('/patient/persona', { persona: id });
      } catch { /* offline — choice stands for this session */ }
    }
    setVisible(false);
  };

  return (
    <section data-testid="persona-step" className="rounded-2xl border bg-card p-4 shadow-sm space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-sm">{t('personaStep.title')}</h2>
          <p className="text-xs text-muted-foreground">{t('personaStep.subtitle')}</p>
        </div>
        <button
          type="button"
          onClick={() => choose(null)}
          className="text-xs text-muted-foreground hover:text-foreground underline"
        >
          {t('personaStep.skip')}
        </button>
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
        {OPTIONS.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => choose(o.id)}
            className="rounded-xl border bg-background p-3 text-left hover:border-primary/50 hover:bg-muted/50 transition-colors"
          >
            <div className="text-xl">{o.emoji}</div>
            <div className="text-xs font-semibold mt-1">{t(`personaStep.options.${o.id}.label`)}</div>
            <div className="text-[11px] text-muted-foreground">{t(`personaStep.options.${o.id}.hint`)}</div>
          </button>
        ))}
      </div>
    </section>
  );
}

/**
 * R1 — Privacy centre page (also embeddable).
 * Consents + access-log section. Discreet mode is prop-drilled from
 * PatientDashboardV2; when routed directly it manages its own toggle backed
 * by localStorage.
 */
import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '@/lib/api';
import { mask } from './EmergencyCard';

interface Consent {
  id: string;
  purpose: string;
  granted: boolean;
  updatedAt: string;
}

interface AccessEntry {
  id: string;
  actor: string;
  action: string;
  at: string;
}

const LS_DISCREET = 'findmedi:discreet';
const LS_CONSENTS = 'findmedi:consent-prefs';

const DEFAULT_CONSENTS: Consent[] = [
  { id: 'care', purpose: 'Share records with treating doctors', granted: true, updatedAt: '' },
  { id: 'family', purpose: 'Share with family members', granted: false, updatedAt: '' },
  { id: 'research', purpose: 'Anonymised research use', granted: false, updatedAt: '' },
  { id: 'marketing', purpose: 'Health tips & offers', granted: true, updatedAt: '' },
];

export default function PrivacyCentre({
  discreet: discreetProp,
  onToggleDiscreet,
}: {
  discreet?: boolean;
  onToggleDiscreet?: (v: boolean) => void;
}) {
  const [internal, setInternal] = useState<boolean>(() => {
    try { return window.localStorage.getItem(LS_DISCREET) === '1'; } catch { return false; }
  });
  const discreet = discreetProp ?? internal;
  const setDiscreet = (v: boolean) => {
    if (onToggleDiscreet) onToggleDiscreet(v);
    else {
      setInternal(v);
      try { window.localStorage.setItem(LS_DISCREET, v ? '1' : '0'); } catch { /* ignore */ }
    }
  };

  const [consents, setConsents] = useState<Consent[]>(DEFAULT_CONSENTS);

  // Preference flags live on the server (PUT /patient/privacy → settings.
// consentPrefs); localStorage is only the offline fallback. Care GRANTS
  // themselves are recorded in consultation/ABHA flows, not here.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const prefs = await api.get('/patient/privacy') as unknown as { consentPrefs?: Record<string, boolean> };
        if (cancelled) return;
        const server = prefs?.consentPrefs;
        if (server && typeof server === 'object') {
          setConsents(DEFAULT_CONSENTS.map((c) => (typeof server[c.id] === 'boolean' ? { ...c, granted: server[c.id] } : c)));
          return;
        }
      } catch { /* fall through to local prefs */ }
      if (cancelled) return;
      try {
        const raw = window.localStorage.getItem(LS_CONSENTS);
        if (raw) {
          const saved = JSON.parse(raw) as Record<string, boolean>;
          setConsents(DEFAULT_CONSENTS.map((c) => (typeof saved[c.id] === 'boolean' ? { ...c, granted: saved[c.id] } : c)));
        }
      } catch { /* ignore corrupt prefs */ }
    })();
    return () => {
      cancelled = true;
    };
  }, []);
  const [accessLog, setAccessLog] = useState<AccessEntry[]>([]);

  // Live data only: care-grant ledger (GET /patient/consents) + the
  // patient-visible audit trail (GET /patient/access-log). The old
  // /consents/mine endpoints never existed — calls to them 404'd and the
  // page fell back to fixture rows. No fixtures anymore: empty = empty.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [cRes, aRes] = await Promise.allSettled([
          api.get('/patient/consents'),
          api.get('/patient/access-log'),
        ]);
        if (cancelled) return;
        if (cRes.status === 'fulfilled' && Array.isArray((cRes.value as any)?.consents)) {
          // Server ledger wins when it has rows; local prefs stay otherwise.
          const rows = (cRes.value as any).consents;
          if (rows.length > 0) {
            setConsents(rows.map((r: any) => ({
              id: String(r._id || r.purpose),
              purpose: String(r.purpose || r.title || 'Data sharing consent'),
              granted: r.effectiveStatus === 'GRANTED' || r.status === 'GRANTED',
              updatedAt: String(r.updatedAt || r.createdAt || ''),
            })));
          }
        }
        if (aRes.status === 'fulfilled' && Array.isArray(aRes.value as any)) {
          const rows = (aRes.value as any).map((e: any, i: number) => ({
            id: String(e._id || `a${i}`),
            actor: String(e.userId || e.actor || 'System'),
            action: String(e.action || 'Record access'),
            at: String(e.timestamp || e.at || '').slice(0, 10),
          }));
          setAccessLog(rows);
        }
      } catch { /* offline — prefs + empty log stand */ }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const toggleConsent = async (id: string) => {
    const next = consents.map((c) => (c.id === id ? { ...c, granted: !c.granted } : c));
    setConsents(next);
    const prefs: Record<string, boolean> = {};
    next.forEach((c) => { prefs[c.id] = c.granted; });
    try {
      window.localStorage.setItem(LS_CONSENTS, JSON.stringify(prefs));
    } catch { /* ignore */ }
    try {
      await api.put('/patient/privacy', { consentPrefs: prefs });
    } catch { /* offline — local prefs stand until next sync */ }
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-6 space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Privacy Centre</h1>
        <Link to="/patient/home-v2" className="text-sm underline">← Dashboard v2</Link>
      </div>

      <section data-testid="discreet-toggle" className="rounded-xl border p-4 flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-sm">Discreet mode 🕶️</h2>
          <p className="text-xs text-muted-foreground">Masks names, amounts and details on shared screens.</p>
        </div>
        <button
          type="button" role="switch" aria-checked={discreet} onClick={() => setDiscreet(!discreet)}
          className={`relative w-12 h-6 rounded-full transition-colors ${discreet ? 'bg-primary' : 'bg-muted'}`}
        >
          <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow transition-all ${discreet ? 'left-6' : 'left-0.5'}`} />
        </button>
      </section>

      <section data-testid="consents" className="rounded-xl border p-4">
        <h2 className="font-semibold text-sm">Consents</h2>
        <div className="mt-3 space-y-2">
          {consents.map((c) => (
            <label key={c.id} className="flex items-center justify-between gap-3 text-sm rounded-lg border p-2">
              <span>{discreet ? mask(c.purpose, true) : c.purpose}</span>
              <input type="checkbox" checked={c.granted} onChange={() => toggleConsent(c.id)} className="w-4 h-4" />
            </label>
          ))}
        </div>
      </section>

      <section data-testid="access-log" className="rounded-xl border p-4">
        <h2 className="font-semibold text-sm">Who accessed my data</h2>
        <div className="mt-3 space-y-2">
          {accessLog.map((a) => (
            <div key={a.id} className="flex items-center justify-between text-sm rounded-lg border p-2">
              <span>{discreet ? mask(a.actor, true) : a.actor} — <span className="text-muted-foreground">{a.action}</span></span>
              <span className="text-xs text-muted-foreground">{a.at}</span>
            </div>
          ))}
          {accessLog.length === 0 && <p className="text-sm text-muted-foreground">No access recorded yet.</p>}
        </div>
      </section>
    </div>
  );
}

// subcatogary.md P1-3: Patient Second Opinion Create & History UI
import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { FileText, Stethoscope, HelpCircle, Send, CheckCircle2, AlertCircle, Clock, X, ChevronRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { useSpecialtyTiles } from '@/hooks/useSpecialtyBrowse';

export default function SecondOpinion() {
  // Specialty codes come from the live taxonomy (43 top-level tiles).
  const { tiles, isLoading: specialtiesLoading } = useSpecialtyTiles();
  const specialtyOptions = tiles.map(t => ({ code: t.code, name: t.name }));

  const [tab, setTab] = useState<'create' | 'history'>('create');
  const [records, setRecords] = useState<any[]>([]);
  const [selectedRecordIds, setSelectedRecordIds] = useState<string[]>([]);
  const [doctors, setDoctors] = useState<any[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState('');
  const [selectedSpecialty, setSelectedSpecialty] = useState('');
  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState<any[]>([]);
  const [loadingHistory, setLoadingHistory] = useState(false);

  useEffect(() => {
    // Load patient's medical records
    api.getRecords()
      .then((res: any) => {
        const list = Array.isArray(res) ? res : (res?.records || res?.data || []);
        setRecords(list);
      })
      .catch(() => {});

    // Load available doctors
    api.getDoctors({ limit: 50 })
      .then((res: any) => {
        const list = Array.isArray(res) ? res : (res?.data || res?.doctors || []);
        setDoctors(list);
      })
      .catch(() => {});
  }, []);

  const loadHistory = () => {
    setLoadingHistory(true);
    api.getMySecondOpinions()
      .then((res: any) => {
        setHistory(res?.requests || []);
      })
      .catch(() => toast.error('Failed to load second opinion history'))
      .finally(() => setLoadingHistory(false));
  };

  useEffect(() => {
    if (tab === 'history') loadHistory();
  }, [tab]);

  const toggleRecord = (id: string) => {
    setSelectedRecordIds(prev =>
      prev.includes(id) ? prev.filter(r => r !== id) : [...prev, id]
    );
  };

  const filteredDoctors = doctors.filter(d => {
    if (!selectedSpecialty) return true;
    return (d.specialtyCode === selectedSpecialty) ||
      (d.specialization && d.specialization.toLowerCase().includes(selectedSpecialty.toLowerCase()));
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDoctorId) {
      toast.error('Please select a specialist doctor');
      return;
    }
    if (selectedRecordIds.length === 0) {
      toast.error('Please select at least one medical record to share');
      return;
    }
    if (question.trim().length < 10) {
      toast.error('Question must be at least 10 characters long');
      return;
    }

    setLoading(true);
    try {
      await api.createSecondOpinion({
        doctorId: selectedDoctorId,
        recordIds: selectedRecordIds,
        question: question.trim(),
      });
      toast.success('Second opinion request submitted successfully!');
      setQuestion('');
      setSelectedRecordIds([]);
      setSelectedDoctorId('');
      setTab('history');
    } catch (err: any) {
      toast.error(err?.message || 'Failed to submit request');
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (id: string) => {
    if (!confirm('Are you sure you want to cancel this request?')) return;
    try {
      await api.cancelSecondOpinion(id);
      toast.success('Request cancelled');
      loadHistory();
    } catch (err: any) {
      toast.error(err?.message || 'Failed to cancel request');
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground">Specialist Second Opinion</h1>
          <p className="text-sm text-muted-foreground">Share medical records and get expert medical reviews from verified specialists</p>
        </div>
        <div className="flex bg-muted rounded-xl p-1 shrink-0">
          <button
            onClick={() => setTab('create')}
            className={`px-4 py-1.5 text-xs font-medium rounded-lg transition-all ${
              tab === 'create' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            New Request
          </button>
          <button
            onClick={() => setTab('history')}
            className={`px-4 py-1.5 text-xs font-medium rounded-lg transition-all ${
              tab === 'history' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            My Requests
          </button>
        </div>
      </div>

      {tab === 'create' ? (
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Step 1: Filter & Choose Doctor */}
          <div className="bg-card rounded-2xl border border-border/60 p-5 space-y-4">
            <h2 className="text-sm font-semibold flex items-center gap-2 text-foreground">
              <Stethoscope className="w-4 h-4 text-primary" /> 1. Select Specialist Doctor
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="text-xs text-muted-foreground block mb-1">Filter by Specialty</label>
                <select
                  value={selectedSpecialty}
                  onChange={e => setSelectedSpecialty(e.target.value)}
                  disabled={specialtiesLoading}
                  className="w-full bg-background border border-border/60 rounded-xl px-3 py-2 text-sm"
                >
                  <option value="">{specialtiesLoading ? 'Loading specialties\u2026' : `All Specialties (${specialtyOptions.length})`}</option>
                  {specialtyOptions.map(s => (
                    <option key={s.code} value={s.code}>{s.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="text-xs text-muted-foreground block mb-1">Doctor *</label>
                <select
                  value={selectedDoctorId}
                  onChange={e => setSelectedDoctorId(e.target.value)}
                  className="w-full bg-background border border-border/60 rounded-xl px-3 py-2 text-sm"
                  required
                >
                  <option value="">Choose a doctor...</option>
                  {filteredDoctors.map(d => (
                    <option key={d._id} value={d._id}>
                      Dr. {d.name} ({d.specialization || d.specialtyCode})
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Step 2: Select Records */}
          <div className="bg-card rounded-2xl border border-border/60 p-5 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold flex items-center gap-2 text-foreground">
                <FileText className="w-4 h-4 text-primary" /> 2. Select Medical Records to Share *
              </h2>
              <span className="text-xs text-muted-foreground">
                {selectedRecordIds.length} record(s) selected
              </span>
            </div>

            {records.length === 0 ? (
              <div className="p-6 text-center text-muted-foreground bg-muted/40 rounded-xl text-xs">
                No medical records found in your account. Please upload or link a prescription/report first.
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-60 overflow-y-auto pr-1">
                {records.map(r => {
                  const isSelected = selectedRecordIds.includes(r._id);
                  return (
                    <div
                      key={r._id}
                      onClick={() => toggleRecord(r._id)}
                      className={`p-3 rounded-xl border text-xs cursor-pointer transition-all flex items-start gap-2.5 ${
                        isSelected
                          ? 'border-primary bg-primary/5 text-foreground'
                          : 'border-border/60 bg-background text-muted-foreground hover:border-primary/40'
                      }`}
                    >
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => {}}
                        className="mt-0.5 rounded border-border"
                      />
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-foreground truncate">{r.title || r.diagnosis || r.type || 'Medical Record'}</p>
                        <p className="text-[11px] text-muted-foreground">
                          {r.type} • {r.date ? new Date(r.date).toLocaleDateString('en-IN') : 'Recent'}
                        </p>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Step 3: Question / Reason */}
          <div className="bg-card rounded-2xl border border-border/60 p-5 space-y-3">
            <h2 className="text-sm font-semibold flex items-center gap-2 text-foreground">
              <HelpCircle className="w-4 h-4 text-primary" /> 3. Your Specific Question or Concern *
            </h2>
            <textarea
              value={question}
              onChange={e => setQuestion(e.target.value)}
              placeholder="Describe your current diagnosis, symptoms, or what specific guidance you are seeking from the specialist..."
              rows={4}
              className="w-full bg-background border border-border/60 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20"
              required
            />
            <p className="text-[11px] text-muted-foreground">
              ABDM Consent Notice: Your chosen medical records will be temporarily shared under a 30-day time-bounded consent token solely for this consultation review.
            </p>
          </div>

          <Button type="submit" disabled={loading} className="w-full sm:w-auto gap-2">
            <Send className="w-4 h-4" />
            {loading ? 'Submitting...' : 'Submit Second Opinion Request'}
          </Button>
        </form>
      ) : (
        <div className="space-y-3">
          {loadingHistory ? (
            <div className="flex justify-center py-12">
              <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
          ) : history.length === 0 ? (
            <div className="bg-card rounded-2xl border border-border/60 p-12 text-center text-muted-foreground">
              <HelpCircle className="w-10 h-10 mx-auto mb-2 opacity-40" />
              <p className="font-medium text-foreground">No second opinion requests yet</p>
              <p className="text-xs mt-1">Submit a request to get expert advice from leading specialists</p>
            </div>
          ) : (
            history.map(req => (
              <div key={req.id} className="bg-card rounded-2xl border border-border/60 p-4 space-y-3">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-semibold text-sm text-foreground">
                        Dr. {req.doctor?.name || 'Specialist'}
                      </span>
                      {req.doctor?.specialization && (
                        <span className="text-xs text-muted-foreground">({req.doctor.specialization})</span>
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Requested on {new Date(req.createdAt).toLocaleDateString('en-IN')} • {req.recordIds?.length || 0} record(s) shared
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className={`px-2 py-0.5 text-[10px] font-semibold rounded-full ${
                      req.status === 'ANSWERED' ? 'bg-emerald-500/10 text-emerald-600' :
                      req.status === 'REQUESTED' ? 'bg-amber-500/10 text-amber-600' :
                      'bg-muted text-muted-foreground'
                    }`}>
                      {req.status}
                    </span>
                    {req.status === 'REQUESTED' && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleCancel(req.id)}
                        className="text-xs text-destructive hover:bg-destructive/10 h-7 px-2"
                      >
                        Cancel
                      </Button>
                    )}
                  </div>
                </div>

                <div className="bg-muted/40 rounded-xl p-3 text-xs text-foreground">
                  <span className="font-medium text-muted-foreground block mb-0.5">Your Question:</span>
                  {req.question}
                </div>

                {req.answer?.text && (
                  <div className="bg-emerald-500/5 border border-emerald-500/20 rounded-xl p-3 text-xs text-foreground space-y-1">
                    <span className="font-semibold text-emerald-600 flex items-center gap-1">
                      <CheckCircle2 className="w-3.5 h-3.5" /> Specialist's Opinion:
                    </span>
                    <p className="whitespace-pre-wrap">{req.answer.text}</p>
                    {req.answer.answeredAt && (
                      <span className="text-[10px] text-muted-foreground block mt-1">
                        Answered on {new Date(req.answer.answeredAt).toLocaleString('en-IN')}
                      </span>
                    )}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { toast } from 'sonner';
import { api, apiClient } from '@/lib/api';
import {
  FileText,
  AlertTriangle,
  Download,
  Search,
  RefreshCw,
  ShieldCheck,
  CheckCircle,
  FileCheck,
  PlusCircle,
  Scale,
  ClipboardList,
} from 'lucide-react';

interface H1Entry {
  _id: string;
  prescriptionNo: string;
  patientName: string;
  prescriberName: string;
  medicineName: string;
  rxSchedule: string;
  quantity: number;
  dispensedByName: string;
  dispensedAt: string;
}

interface H1Gap {
  prescriptionId: string;
  prescriptionNo: string;
  medicineId: string;
  medicineName: string;
}

interface ReconcileRow {
  medicineId: string;
  medicineName: string;
  rxSchedule: string;
  openingQty: number;
  purchasesQty: number;
  dispensedQty: number;
  adjustedQty: number;
  expectedClosing: number;
  physicalQty: number;
  variance: number;
  lastCountedAt: string | null;
  lastCountedByName: string;
  witnessByName: string;
}

interface AdjustmentRow {
  _id: string;
  medicineName: string;
  batch: string;
  qty: number;
  type: string;
  reason: string;
  witnessByName: string;
  recordedByName: string;
  at: string;
}

export default function H1RegisterPage() {
  const [entries, setEntries] = useState<H1Entry[]>([]);
  const [gaps, setGaps] = useState<H1Gap[]>([]);
  const [reconcileRows, setReconcileRows] = useState<ReconcileRow[]>([]);
  const [adjustments, setAdjustments] = useState<AdjustmentRow[]>([]);
  const [varianceCount, setVarianceCount] = useState(0);
  const [staffUsers, setStaffUsers] = useState<any[]>([]);

  const [loading, setLoading] = useState(false);
  const [scheduleFilter, setScheduleFilter] = useState('ALL');
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState('register');

  // Modals state
  const [showAdjModal, setShowAdjModal] = useState(false);
  const [showCountModal, setShowCountModal] = useState(false);
  const [submittingModal, setSubmittingModal] = useState(false);

  const [adjForm, setAdjForm] = useState({
    medicineId: '',
    medicineName: '',
    batch: '',
    qty: 1,
    type: 'wastage',
    reason: '',
    witnessBy: '',
  });

  const [countForm, setCountForm] = useState({
    medicineId: '',
    medicineName: '',
    batch: '',
    countedQty: 0,
    witnessBy: '',
    notes: '',
  });

  const loadData = async () => {
    try {
      setLoading(true);
      const [entriesRes, gapsRes, reconRes, adjRes, staffRes]: any = await Promise.all([
        // NOTE: api.get(path) takes no options — params must be in the URL,
        // otherwise the schedule filter is silently ignored.
        api.get(`/pharmacy/h1-register${scheduleFilter !== 'ALL' ? `?rxSchedule=${encodeURIComponent(scheduleFilter)}` : ''}`),
        api.get('/pharmacy/h1-register/gaps'),
        api.get('/pharmacy/narcotic-register/reconcile'),
        api.get('/pharmacy/narcotic-register/adjustments'),
        api.get('/staff').catch(() => ({ data: [] })),
      ]);

      setEntries(entriesRes.data?.rows || entriesRes.rows || []);
      setGaps(gapsRes.data?.gaps || gapsRes.gaps || []);
      setReconcileRows(reconRes.data?.rows || reconRes.rows || []);
      setVarianceCount(reconRes.data?.varianceCount ?? reconRes.varianceCount ?? 0);
      setAdjustments(adjRes.data?.adjustments || adjRes.adjustments || []);
      const usersList = staffRes.data?.staff || staffRes.data || staffRes || [];
      setStaffUsers(Array.isArray(usersList) ? usersList : []);
    } catch (err: any) {
      toast.error(err.message || 'Failed to load H1 register ledger');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [scheduleFilter]);

  // Authenticated blob download: window.open() sends no auth headers, so the
  // export endpoints would 401. apiClient carries the session; the blob URL
  // triggers a real file download instead of a dead tab.
  const downloadExport = async (path: string, filename: string, doneMsg: string) => {
    try {
      const response = await apiClient.get(path, { responseType: 'blob' });
      const contentType = response.headers?.['content-type'];
      const blob = new Blob([response.data], {
        type: typeof contentType === 'string' ? contentType : 'application/octet-stream',
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 10_000);
      toast.success(doneMsg);
    } catch {
      toast.error('Export download failed');
    }
  };

  const scheduleQuery = scheduleFilter !== 'ALL' ? `?rxSchedule=${encodeURIComponent(scheduleFilter)}` : '';

  const handleExportCsv = async () => {
    await downloadExport(
      `/pharmacy/h1-register/export${scheduleQuery}`,
      `h1-register-${scheduleFilter}.csv`,
      'Inspector-ready CSV export generated',
    );
  };

  const handleExportPdf = async () => {
    await downloadExport(
      `/pharmacy/h1-register/pdf${scheduleQuery}`,
      `h1-register-${scheduleFilter}.pdf`,
      'Statutory Inspector PDF generated',
    );
  };

  const submitAdjustment = async () => {
    if (!adjForm.medicineId || !adjForm.witnessBy || !adjForm.reason) {
      toast.error('Please fill all required fields and select an authorized witness');
      return;
    }
    setSubmittingModal(true);
    try {
      await api.post('/pharmacy/narcotic-register/adjustments', adjForm);
      toast.success('Narcotic stock adjustment recorded with dual witness signature');
      setShowAdjModal(false);
      setAdjForm({ medicineId: '', medicineName: '', batch: '', qty: 1, type: 'wastage', reason: '', witnessBy: '' });
      loadData();
    } catch (err: any) {
      toast.error(err.response?.data?.message || err.message || 'Failed to record adjustment');
    } finally {
      setSubmittingModal(false);
    }
  };

  const submitPhysicalCount = async () => {
    if (!countForm.medicineId || !countForm.witnessBy) {
      toast.error('Please select medicine and an authorized witness');
      return;
    }
    setSubmittingModal(true);
    try {
      await api.post('/pharmacy/narcotic-register/counts', countForm);
      toast.success('Physical audit count logged with dual verification');
      setShowCountModal(false);
      setCountForm({ medicineId: '', medicineName: '', batch: '', countedQty: 0, witnessBy: '', notes: '' });
      loadData();
    } catch (err: any) {
      toast.error(err.response?.data?.message || err.message || 'Failed to record count');
    } finally {
      setSubmittingModal(false);
    }
  };

  const filteredEntries = entries.filter((e) => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      e.patientName?.toLowerCase().includes(q) ||
      e.medicineName?.toLowerCase().includes(q) ||
      e.prescriptionNo?.toLowerCase().includes(q) ||
      e.prescriberName?.toLowerCase().includes(q)
    );
  });

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2">
            <FileText className="w-8 h-8 text-primary" />
            Pharmacy H1 / Narcotic Statutory Register
          </h1>
          <p className="text-muted-foreground">
            Statutory compliance and stock reconciliation ledger for Schedule H, H1, X and NDPS substances.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" size="sm" onClick={loadData} disabled={loading}>
            <RefreshCw className={`w-4 h-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
          <Button variant="outline" size="sm" onClick={handleExportPdf}>
            <Download className="w-4 h-4 mr-2" />
            Export Inspector PDF
          </Button>
          <Button size="sm" onClick={handleExportCsv}>
