import { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import {
  Pill, ShoppingCart, DollarSign, AlertTriangle,
  Package, RotateCcw, Globe, Save, Building2, Users, CheckCircle, AlertCircle,
  Clock, CalendarClock, CalendarDays, ChevronRight, Truck, Shield
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import StatCard from '@/components/StatCard';
import LicenseExpiryReminder from '@/components/LicenseExpiryReminder';
import { Switch } from '@/components/ui/switch';
import { DataGrid } from '@/components/ui/System';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const statusColors: Unmodelled = {
  Completed: 'bg-success/10 text-success',
  Processing: 'bg-info/10 text-info',
  Pending: 'bg-warning/10 text-warning',
  Cancelled: 'bg-destructive/10 text-destructive',
};

export default function PharmacyBusinessDashboard() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [stats, setStats] = useState<Unmodelled>(null);
  const [orders, setOrders] = useState<ApiRow[]>([]);
  const [orderTab, setOrderTab] = useState('pending');
  const [lowStock, setLowStock] = useState<ApiRow[]>([]);
  const [refunds, setRefunds] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [platformSettings, setPlatformSettings] = useState({
    autoConfirmOrders: true,
    customerSelfRegistration: false,
    prescriptionValidation: true,
    deliveryIntegration: true,
    emergencySupport: false,
    acceptRefunds: true,
  });

  useEffect(() => {
    try {
      const saved = localStorage.getItem('pharmacy_platform_settings');
      if (saved) setPlatformSettings(JSON.parse(saved));
    } catch {}
  }, []);

  const handleSavePlatformSettings = () => {
    localStorage.setItem('pharmacy_platform_settings', JSON.stringify(platformSettings));
    toast.success('Platform and pharmacy settings updated successfully');
  };
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    const load = async () => {
      setLoading(true);
      try {
        const results = await Promise.allSettled([
          api.getPharmacyStats(),
          api.getPharmacyOrders({}),
          api.getPharmacyMedicines({ lowStock: 'true' }),
          api.getPharmacyReturns({}),
        ]);
        if (!mounted.current) return;
        const [s, o, m, rf] = results.map(res => res.status === 'fulfilled' ? res.value : null);
        setStats(s);
        const orderList = o?.orders || [];
        setOrders(orderList);
        setLowStock((m?.medicines || []).slice(0, 5));
        setRefunds((rf?.returns || rf?.data || []).slice(0, 5));
        const failed = results.filter(r => r.status === 'rejected');
        if (failed.length > 0) toast.error(`Failed to load ${failed.length} data source(s)`);
      } catch (e: any) { console.error(e); toast.error('Failed to load dashboard data'); }
      if (mounted.current) setLoading(false);
    };
    load();
    return () => { mounted.current = false; };
  }, []);

  const totalRefunded = refunds.reduce((s, r) => s + (r.total || r.refundAmount || 0), 0);
  const pendingRefunds = refunds.filter(r => r.status === 'Pending' || r.status === 'pending').length;

  const todayStr = new Date().toISOString().slice(0, 10);
  const pendingOrders = orders.filter(o => (o.status || '').toLowerCase() === 'pending');
  const processingOrders = orders.filter(o => (o.status || '').toLowerCase() === 'processing' || (o.status || '').toLowerCase() === 'ready');
  const todayOrders = orders.filter(o => (o.createdAt || o.date || '').startsWith(todayStr));
  const completedOrders = orders.filter(o => (o.status || '').toLowerCase() === 'completed' || (o.status || '').toLowerCase() === 'delivered');

  const displayedOrders = orderTab === 'pending' ? pendingOrders
    : orderTab === 'processing' ? processingOrders
    : orderTab === 'today' ? todayOrders
    : completedOrders;

  const orderRows = displayedOrders.slice(0, 5).map((order, i) => ({
    ...order,
    _id: order._id || order.id || `row-${i}`,
    orderId: order.orderId || order._id?.slice(-6),
    customer: order.patientName || order.customer || '—',
    total: order.total || order.amount || 0,
  }));

  const orderColumns = [
    {
      key: 'orderId',
