                  <p className="font-semibold text-foreground">{o.title}</p>
                  <Badge variant={o.discountType === 'percentage' ? 'default' : 'secondary'} className="text-[10px]">{o.discountType === 'percentage' ? `${o.discountValue}% OFF` : `₹${o.discountValue} OFF`}</Badge>
                </div>
              </div>
              <div className="flex gap-1">
                <Button variant="ghost" size="icon" className="w-8 h-8" onClick={() => openEdit(o)}><Edit2 className="w-4 h-4" /></Button>
                <Button variant="ghost" size="icon" className="w-8 h-8 text-destructive" onClick={() => handleDelete(o._id)}><Trash2 className="w-4 h-4" /></Button>
              </div>
            </div>
            {o.description && <p className="text-xs text-muted-foreground mt-2">{o.description}</p>}
            <div className="flex items-center gap-4 mt-3 text-xs text-muted-foreground">
              {o.minPurchase > 0 && <span>Min: ₹{o.minPurchase}</span>}
              {o.validUntil && <span>Valid till: {new Date(o.validUntil).toLocaleDateString()}</span>}
            </div>
          </div>
        ))}
        {offers.length === 0 && !loading && <div className="col-span-full py-12 text-center text-muted-foreground">No offers yet</div>}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40" onClick={() => setShowModal(false)}>
          <div className="bg-card rounded-2xl shadow-xl border p-6 w-full max-w-lg mx-4" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-heading text-lg font-bold text-foreground">{editItem ? 'Edit Offer' : 'New Offer'}</h2>
              <Button variant="ghost" size="icon" onClick={() => setShowModal(false)}><X className="w-4 h-4" /></Button>
            </div>
            <div className="space-y-3">
              <Input placeholder="Offer title" value={form.title} onChange={e => setForm(p => ({...p, title:e.target.value}))} />
              <Input placeholder="Description (optional)" value={form.description} onChange={e => setForm(p => ({...p, description:e.target.value}))} />
              <div className="grid grid-cols-2 gap-3">
                <select value={form.discountType} onChange={e => setForm(p => ({...p, discountType:e.target.value}))} className="h-10 rounded-lg border border-border bg-background text-sm px-3">
                  <option value="percentage">Percentage</option>
                  <option value="fixed">Fixed (Rs)</option>
                </select>
                <Input type="number" placeholder="Discount value" value={form.discountValue} onChange={e => setForm(p => ({...p, discountValue:e.target.value}))} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <Input type="date" placeholder="Valid from" value={form.validFrom} onChange={e => setForm(p => ({...p, validFrom:e.target.value}))} />
                <Input type="date" placeholder="Valid until" value={form.validUntil} onChange={e => setForm(p => ({...p, validUntil:e.target.value}))} />
              </div>
              <Input type="number" placeholder="Minimum purchase (0 = no minimum)" value={form.minPurchase} onChange={e => setForm(p => ({...p, minPurchase:e.target.value}))} />
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <Button variant="outline" onClick={() => setShowModal(false)}>Cancel</Button>
              <Button onClick={handleSave}>{editItem ? 'Update' : 'Create'}</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Search, ShoppingCart } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { DataGrid } from '@/components/ui/System';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const statusColors: Unmodelled = {
  Pending: 'bg-warning/10 text-warning', Processing: 'bg-info/10 text-info',
  Completed: 'bg-success/10 text-success', Cancelled: 'bg-destructive/10 text-destructive',
};

export default function PharmacyOrders() {
  const [orders, setOrders] = useState<ApiRow[]>([]);
  const [status, setStatus] = useState('All');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<Unmodelled>(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try { const res = await api.getPharmacyOrders({ status: status === 'All' ? '' : status, search }); setOrders(res.orders || []); }
      catch (e: any) { console.error(e); }
      setLoading(false);
    };
    load();
  }, [status, search]);

  const columns = [
    { key: 'orderId', label: 'Order ID', render: (v: Unmodelled, r: Unmodelled) => <span className="font-medium text-foreground">{v || r._id?.slice(-6)}</span> },
    { key: 'customer', label: 'Customer', render: (v: Unmodelled, r: Unmodelled) => <span className="text-muted-foreground">{r.patientName || v || '—'}</span> },
    { key: 'items', label: 'Items', render: (v: Unmodelled) => <span className="text-muted-foreground">{v ?? '—'}</span> },
    { key: 'total', label: 'Total', render: (v: Unmodelled) => <span className="font-medium text-foreground">₹{(v || 0).toLocaleString()}</span> },
    { key: 'status', label: 'Status', render: (v: Unmodelled) => <Badge className={statusColors[v]}>{v}</Badge> },
  ];

  // The API already applies the status + search filters, so the rows handed in
  // ARE the result set — the grid must not re-filter or re-page them.
  const rows = orders.map(o => ({
    ...o,
    orderId: o.orderId || o._id?.slice(-6),
    customer: o.patientName || o.customer || '',
    items: o.items?.length || o.totalItems || null,
    total: o.total || o.amount || 0,
  }));

  return (
    <div>
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-6">
        <h1 className="font-heading text-xl font-bold text-foreground">Orders</h1>
        <div className="flex items-center gap-3 w-full sm:w-auto">
          <Button variant="outline" size="sm" onClick={() => {
            const csvRows = [["OrderID", "Customer", "Items", "Total", "Status"], ...rows.map((o: Unmodelled) => [o.orderId, o.customer, o.items ?? "", o.total, o.status || ""])];
            const csv = csvRows.map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
            const blob = new Blob([csv], { type: "text/csv" });
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = "pharmacy-orders.csv";
            a.click();
          }}>Export CSV</Button>
          <select value={status} onChange={e => setStatus(e.target.value)} aria-label="Filter by status" className="h-10 rounded-lg border border-border bg-background text-sm px-3">
            <option value="All">All Status</option>
            <option value="Pending">Pending</option>
            <option value="Processing">Processing</option>
            <option value="Completed">Completed</option>
            <option value="Cancelled">Cancelled</option>
          </select>
          <div className="relative flex-1 sm:w-56">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search orders..." aria-label="Search orders" className="pl-9" />
          </div>
        </div>
      </div>

      <DataGrid
        columns={columns}
        rows={rows}
        rowKey="_id"
        onRowClick={setSelected}
        empty={loading ? 'Loading…' : 'No orders found'}
        showSearch={false}
        manualPagination
      />

      {selected && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40" onClick={() => setSelected(null)}>
          <div className="bg-card rounded-2xl shadow-xl border p-6 w-full max-w-lg mx-4" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-heading text-lg font-bold text-foreground">{selected.orderId || 'Order Details'}</h2>
              <Button variant="ghost" size="icon" aria-label="Close" onClick={() => setSelected(null)}><ShoppingCart className="w-4 h-4" /></Button>
            </div>
            <div className="space-y-3 text-sm">
              <div className="grid grid-cols-2 gap-2"><span className="text-muted-foreground">Customer:</span><span className="text-foreground font-medium">{selected.patientName || selected.customer || '—'}</span></div>
              <div className="grid grid-cols-2 gap-2"><span className="text-muted-foreground">Status:</span><Badge className={statusColors[selected.status]}>{selected.status}</Badge></div>
              <div className="grid grid-cols-2 gap-2"><span className="text-muted-foreground">Total:</span><span className="text-foreground font-medium">₹{(selected.total || selected.amount || 0).toLocaleString()}</span></div>
              <div className="grid grid-cols-2 gap-2"><span className="text-muted-foreground">Items:</span><span className="text-foreground">{selected.items?.length || selected.totalItems || '—'}</span></div>
              {selected.notes && <div className="grid grid-cols-2 gap-2"><span className="text-muted-foreground">Notes:</span><span className="text-foreground">{selected.notes}</span></div>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  FileText, User, Search, CheckCircle, XCircle, Calendar, Eye, Clock,
  Pill, AlertTriangle, Activity, Timer, ArrowRight
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { api, resolveFileUrl } from '@/lib/api';
import { toast } from 'sonner';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

// SLA helpers
function minutesSince(iso: Unmodelled) {
  if (!iso) return null;
  const diff = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (diff < 1) return 'Just now';
  if (diff < 60) return `${diff}m ago`;
  return `${Math.floor(diff / 60)}h ${diff % 60}m ago`;
}
function urgencyLevel(iso: Unmodelled) {
  if (!iso) return null;
  const mins = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins > 20) return 'critical';
  if (mins > 10) return 'urgent';
  return null;
}

const statusColors: Unmodelled = {
  Active: 'bg-warning/10 text-warning',
  Dispensed: 'bg-success/10 text-success',
  'Partially Dispensed': 'bg-info/10 text-info',
  Cancelled: 'bg-destructive/10 text-destructive',
};

const statusBadge = (status: Unmodelled) => {
  const colors = statusColors[status] || statusColors.Active;
  return <Badge className={colors}>{status}</Badge>;
};

const medicineStatusBadge = (isDispensed: Unmodelled) => (
  <Badge className={isDispensed ? 'bg-success/10 text-success' : 'bg-warning/10 text-warning'}>
    {isDispensed ? 'Dispensed' : 'Pending'}
  </Badge>
);

export default function PharmacyPrescriptionQueue() {
  const [queue, setQueue] = useState<ApiRow[]>([]);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [selectedRx, setSelectedRx] = useState<Unmodelled>(null);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const load = async () => {
    try {
      const res = await api.getPharmacyPrescriptions({});
      setQueue(res.prescriptions || []);
    } catch (e: any) { console.error(e); }
  };

  useEffect(() => { load(); }, []);

  const filtered = queue.filter(r => {
    const ms = !search || (r.patientName || '').toLowerCase().includes(search.toLowerCase())
      || (r.prescriptionId || '').toLowerCase().includes(search.toLowerCase())
      || (r.doctorName || '').toLowerCase().includes(search.toLowerCase());
    const mf = filter === 'All' || r.status === filter;
    return ms && mf;
  });

  const handleDispense = async (rxId: Unmodelled, medicineIndex: Unmodelled) => {
    setError('');
    setSuccessMsg('');
    try {
      const updated = await api.dispensePharmacyMedicine(rxId, { medicineIndex });
      setQueue(prev => prev.map(r => r._id === rxId ? updated : r));
      if (selectedRx?._id === rxId) setSelectedRx(updated);
      setSuccessMsg('Medicine dispensed successfully');
      setTimeout(() => setSuccessMsg(''), 3000);
    } catch (e: any) {
      setError(e.message || 'Failed to dispense medicine');
      setTimeout(() => setError(''), 3000);
    }
  };

  const handleCancel = async (id: Unmodelled) => {
    setError('');
    setSuccessMsg('');
    try {
      await api.dispensePharmacyMedicine(id, { cancel: true });
      setQueue(prev => prev.map(r => r._id === id ? { ...r, status: 'Cancelled' } : r));
      setSuccessMsg('Prescription cancelled');
      setTimeout(() => setSuccessMsg(''), 3000);
    } catch (e: any) { console.error(e); }
  };

  const totalActive    = queue.filter(r => r.status === 'Active').length;
  const totalDispensed = queue.filter(r => r.status === 'Dispensed').length;
  const totalCancelled = queue.filter(r => r.status === 'Cancelled').length;
  const totalPartial   = queue.filter(r => r.status === 'Partially Dispensed').length;
  const avgMins = 12; // mock average

  const handleNotifyNextProvider = (rx: Unmodelled) => {
    toast.info(`🔄 Notifying next preferred pharmacy for ${rx.patientName}'s prescription...`, { duration: 5000 });
    setTimeout(() => toast.success(`✅ Next provider (HealthFirst Medicals) notified.`, { duration: 4000 }), 1500);
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="font-heading text-2xl font-bold text-foreground">Prescription Queue</h1>
        <p className="text-muted-foreground mt-0.5">
          {totalActive > 0 && <span className="text-warning font-medium">{totalActive} active</span>}
          {totalActive > 0 && totalPartial > 0 && <span>, </span>}
          {totalPartial > 0 && <span className="text-info font-medium">{totalPartial} partially dispensed</span>}
          {totalActive === 0 && totalPartial === 0 && <span>No pending prescriptions</span>}
        </p>
      </div>

      {/* Stats bar */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { label: 'Active',        value: totalActive,    color: 'text-amber-600',   icon: Clock       },
          { label: 'Dispensed',     value: totalDispensed, color: 'text-emerald-600', icon: CheckCircle },
          { label: 'Cancelled',     value: totalCancelled, color: 'text-red-500',     icon: XCircle     },
          { label: 'Avg Time',      value: `${avgMins}m`,  color: 'text-primary',     icon: Timer       },
        ].map(({ label, value, color, icon: Icon }) => (
          <div key={label} className="bg-card rounded-xl border border-border/60 p-4 flex items-center gap-3">
            <Icon className={`w-5 h-5 ${color}`} />
            <div>
              <p className={`text-xl font-bold font-heading ${color}`}>{value}</p>
              <p className="text-xs text-muted-foreground">{label}</p>
            </div>
          </div>
        ))}
      </div>

      {error && (
        <div className="p-4 rounded-xl bg-destructive/10 border border-destructive/20 text-destructive text-sm flex items-center gap-2">
          <AlertTriangle className="w-4 h-4" /> {error}
        </div>
      )}
      {successMsg && (
        <div className="p-4 rounded-xl bg-success/10 border border-success/20 text-success text-sm flex items-center gap-2">
          <CheckCircle className="w-4 h-4" /> {successMsg}
        </div>
      )}

      <div className="flex gap-2 flex-wrap">
        {['All', 'Active', 'Partially Dispensed', 'Dispensed', 'Cancelled'].map(f => (
          <button key={f} onClick={() => setFilter(f)}
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-colors ${filter === f ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
            {f} ({f === 'All' ? queue.length : queue.filter(r => r.status === f).length})
          </button>
        ))}
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input value={search} onChange={e => setSearch(e.target.value)}
          placeholder="Search by patient name, prescription ID, or doctor..." className="pl-10" />
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
          <FileText className="w-16 h-16 mx-auto text-muted-foreground/30 mb-4" />
          <p className="text-muted-foreground text-lg">No prescriptions found</p>
        </div>
      ) : (
        <div className="space-y-4">
          {filtered.map((rx, i) => {
            const dispensed = rx.medicines?.filter((m: Unmodelled) => m.isDispensed).length || 0;
            const total = rx.medicines?.length || 0;
            return (
              <motion.div key={rx._id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}
                className="bg-card rounded-2xl border border-border/60 p-5 hover:shadow-lg transition-all">
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-4">
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${rx.isEmergency ? 'bg-destructive/10' : 'bg-warning/10'}`}>
                      {rx.isEmergency
                        ? <AlertTriangle className="w-6 h-6 text-destructive" />
                        : <FileText className="w-6 h-6 text-warning" />
                      }
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <h3 className="font-heading font-semibold text-foreground">{rx.patientName}</h3>
                        <span className="text-xs text-muted-foreground font-mono">#{rx.prescriptionId}</span>
                      </div>
                      <p className="text-sm text-muted-foreground">Dr. {rx.doctorName}</p>
                      <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
                        <Calendar className="w-3 h-3" /> {new Date(rx.createdAt).toLocaleDateString()}
                        <Clock className="w-3 h-3 ml-1" /> {new Date(rx.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        {rx.status === 'Active' && rx.createdAt && (() => {
                          const u = urgencyLevel(rx.createdAt);
                          return u === 'critical'
                            ? <Badge className="text-[10px] bg-red-500/10 text-red-600 border-red-200 animate-pulse ml-1"><AlertTriangle className="w-2.5 h-2.5 mr-0.5" />Overdue {minutesSince(rx.createdAt)}</Badge>
                            : u === 'urgent'
                            ? <Badge className="text-[10px] bg-amber-500/10 text-amber-600 border-amber-200 ml-1"><Timer className="w-2.5 h-2.5 mr-0.5" />Urgent {minutesSince(rx.createdAt)}</Badge>
                            : null;
                        })()}
                      </div>
                      {rx.diagnosis && (
                        <p className="text-xs text-muted-foreground/70 mt-1 italic">{rx.diagnosis}</p>
