    onSuccess: () => { toast.success('Study completed'); invalidate(); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to complete study')),
  });
  const forwardMut = useMutation({
    mutationFn: ({ id, status }: any) => radApi.setOrderStatus(id, { status }),
