  });
  const reportMut = useMutation({
    mutationFn: ({ id, ...b }: any) => radApi.submitReport(id, b),
    onSuccess: () => { toast.success('Report signed'); invalidate(); setReportingOrder(null); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to submit report')),
  });
  const contrastMut = useMutation({
    mutationFn: ({ id, ...b }: any) => radApi.setContrast(id, b),
    onSuccess: () => { toast.success('Contrast recorded'); invalidate(); setContrastOrder(null); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to record contrast')),
  });

  const isMri = modalityType === 'MRI';
  const isCt = modalityType === 'CT Scan';
  const isXray = modalityType === 'X-Ray';

  const worklist = all.filter((o: any) => {
    const okStatus = statusFilter === 'All' || o.status === statusFilter;
    const s = search.toLowerCase();
    const okSearch = !s || [o.patientName, o.orderId, o.bodyPart, o.studyNumber].some((v: any) => String(v || '').toLowerCase().includes(s));
    return okStatus && okSearch && o.status !== 'Cancelled';
  });

  const waiting = all.filter((o: any) => ['Scheduled', 'Appointment Confirmed', 'Patient Arrived'].includes(o.status)).length;
  const prepPending = all.filter((o: any) => ['Preparation Pending', 'On Hold'].includes(o.status)).length;
  const inProgress = all.filter((o: any) => o.status === 'In Progress').length;
  const completed = all.filter((o: any) => ['Completed', 'Study Completed'].includes(o.status)).length;
  const reportsPending = all.filter((o: any) => ['Completed', 'Study Completed', 'Reporting Pending'].includes(o.status)).length;
  const urgent = all.filter((o: any) => ['Urgent', 'STAT'].includes(o.priority) && !['Reported', 'Report Finalized', 'Report Released', 'Delivered'].includes(o.status)).length;
  const screeningPending = all.filter((o: any) => !o.safetyScreening?.isScreened && !['Completed', 'Study Completed', 'Reported', 'Report Finalized', 'Report Released', 'Delivered', 'Cancelled'].includes(o.status)).length;

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">{modalityType} Dashboard</h1>
          <p className="page-subtitle">{machines.length} machine(s) · {worklist.length} studies in worklist</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" onClick={() => nav('/radiology/preparation')}><FlaskConical className="w-4 h-4 mr-1" /> Preparation Queue</Button>
          <Button variant="outline" onClick={() => nav('/radiology/scheduling')}>Scheduling</Button>
          <Button variant="outline" onClick={() => nav('/radiology/modalities')}>Machines</Button>
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4">
        <StatCard label="Waiting" value={waiting} tone="text-cyan-600" />
        <StatCard label="Prep Pending" value={prepPending} tone="text-amber-600" onClick={() => nav('/radiology/preparation')} />
        <StatCard label="In Progress" value={inProgress} tone="text-info" />
        <StatCard label="Completed" value={completed} tone="text-success" />
        <StatCard label="Reports Pending" value={reportsPending} tone="text-purple-600" onClick={() => nav('/radiology/reports')} />
        <StatCard label="Urgent" value={urgent} tone="text-destructive" />
      </div>

      {isMri && (
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/5 p-4 flex flex-col sm:flex-row sm:items-center gap-3">
          <ShieldAlert className="w-5 h-5 text-amber-600 shrink-0" />
          <div className="flex-1">
            <p className="text-sm font-semibold">MRI Safety Screening</p>
            <p className="text-xs text-muted-foreground">{screeningPending} studies still need implant / metal screening and radiologist clearance before scanning.</p>
          </div>
          <Button size="sm" variant="outline" className="border-amber-500/40 text-amber-600" onClick={() => nav('/radiology/preparation')}>
            Open screening prep <ArrowRight className="w-3 h-3 ml-1" />
          </Button>
        </div>
      )}

      {isCt && (
        <div className="rounded-xl border border-orange-500/30 bg-orange-500/5 p-4 flex flex-col sm:flex-row sm:items-center gap-3">
          <Syringe className="w-5 h-5 text-orange-600 shrink-0" />
          <div className="flex-1">
            <p className="text-sm font-semibold">Contrast Administration</p>
            <p className="text-xs text-muted-foreground">{all.filter((o: any) => o.contrast?.agent).length} studies with a recorded contrast dose · {screeningPending} awaiting renal / allergy screening.</p>
          </div>
          <Button size="sm" variant="outline" className="border-orange-500/40 text-orange-600" onClick={() => setContrastOrder(worklist.find((o: any) => o.status === 'In Progress') || worklist[0] || null)}>
            Record contrast
          </Button>
        </div>
      )}

      <div className="bg-card rounded-xl border shadow-sm">
        <div className="p-4 border-b flex flex-wrap gap-3 items-center justify-between">
          <h2 className="font-heading font-semibold">{modalityType} Worklist</h2>
          <div className="flex gap-3 flex-wrap">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input placeholder="Search patient / order..." className="pl-10 w-56" value={search} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value)} />
            </div>
            <select value={statusFilter} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setStatusFilter(e.target.value)}
              className="h-10 px-3 rounded-lg border border-input bg-background text-sm">
              <option value="All">All Status</option>
              {['Patient Arrived', 'Preparation Pending', 'Ready for Imaging', 'In Progress', 'Completed', 'Study Completed', 'Reporting Pending', 'Reported'].map((s: string) => (
                <option key={s} value={s}>{s}</option>
              ))}
            </select>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-muted-foreground border-b">
                <th className="p-3 font-medium">Patient</th>
                <th className="p-3 font-medium">Order</th>
                <th className="p-3 font-medium">{isXray ? 'Body Part / Projection' : 'Study'}</th>
                <th className="p-3 font-medium">Priority</th>
                <th className="p-3 font-medium">Scheduled</th>
                <th className="p-3 font-medium">Status</th>
                <th className="p-3 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {worklist.map((o: any) => (
                <tr key={o._id} className="border-b last:border-0 hover:bg-muted/30">
                  <td className="p-3">
                    <p className="font-medium">{patientNameOf(o.patientId || o)}</p>
                    <p className="text-[11px] text-muted-foreground">{o.patientId?.phone || ''}</p>
                  </td>
                  <td className="p-3">
                    <p>{o.orderId}</p>
                    <p className="text-[11px] text-muted-foreground">{o.studyNumber || ''}</p>
                  </td>
                  <td className="p-3">
                    <p className="font-medium">{o.bodyPart}</p>
                    {isXray && <p className="text-[11px] text-muted-foreground">Projection: {o.bodyPart}</p>}
                    {isCt && o.contrast?.agent && <p className="text-[11px] text-orange-600">Contrast: {o.contrast.agent} {o.contrast.volumeMl}ml</p>}
                    {isMri && (
                      <p className={`text-[11px] ${o.safetyScreening?.clearedForScan ? 'text-emerald-600' : 'text-amber-600'}`}>
                        {o.safetyScreening?.clearedForScan ? 'Screened & cleared' : 'Screening pending'}
                      </p>
                    )}
                  </td>
                  <td className="p-3"><PriorityBadge value={o.priority} /></td>
                  <td className="p-3 text-xs text-muted-foreground">{toDateTimeLocal(o.scheduledAt) ? new Date(o.scheduledAt).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : '-'}</td>
                  <td className="p-3"><StatusBadge value={o.status} /></td>
                  <td className="p-3">
                    <div className="flex gap-1 justify-end flex-wrap">
                      {(isMri || isCt) && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setScreeningOrder(o)}>
                          <ShieldAlert className="w-3 h-3 mr-1" /> Safety
                        </Button>
                      )}
                      {isCt && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => { setContrastOrder(o); setContrast((c: any) => ({ ...c, givenAt: '' })); }}>
                          <Syringe className="w-3 h-3 mr-1" /> Contrast
                        </Button>
                      )}
                      {STATUSES_TO_START.includes(o.status) && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => startMut.mutate(o._id)}>
                          <Play className="w-3 h-3 mr-1" /> Start
                        </Button>
                      )}
                      {o.status === 'In Progress' && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => completeMut.mutate(o._id)}>
                          <CheckCircle2 className="w-3 h-3 mr-1" /> Complete
                        </Button>
                      )}
                      {['Completed', 'Study Completed'].includes(o.status) && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => forwardMut.mutate({ id: o._id, status: 'Reporting Pending' })}>
                          <ArrowRight className="w-3 h-3 mr-1" /> Forward for Report
                        </Button>
                      )}
                      {o.status === 'Reporting Pending' && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setReportingOrder(o)}>
                          <FileText className="w-3 h-3 mr-1" /> Report
                        </Button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
              {worklist.length === 0 && (
                <tr><td colSpan={7} className="p-12 text-center text-muted-foreground">
                  <Camera className="w-10 h-10 mx-auto mb-2 opacity-30" />No studies in the {modalityType} worklist
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-card rounded-xl border shadow-sm">
          <div className="p-4 border-b flex items-center gap-2">
            <Layers className="w-4 h-4 text-primary" />
            <h2 className="font-heading font-semibold">{modalityType} Preparation Rules</h2>
          </div>
          <div className="p-4">
            {prepRules.length === 0 ? (
              <p className="text-sm text-muted-foreground">No prep rules configured for {modalityType} machines. Add them in Modality Master.</p>
            ) : (
              <ul className="space-y-2 text-sm">
                {Array.from(new Set(prepRules)).map((r: string, i: number) => (
                  <li key={i} className="flex gap-2"><CheckCircle2 className="w-4 h-4 text-emerald-500 mt-0.5 shrink-0" /><span>{r}</span></li>
                ))}
              </ul>
            )}
          </div>
        </div>
        <div className="bg-card rounded-xl border shadow-sm">
          <div className="p-4 border-b flex items-center gap-2">
            <FileText className="w-4 h-4 text-primary" />
            <h2 className="font-heading font-semibold">Configured for {modalityType}</h2>
          </div>
          <div className="p-4 space-y-3 text-sm">
            {machines.map((m: any) => (
              <div key={m._id} className="rounded-lg border p-3">
                <div className="flex items-center justify-between">
                  <p className="font-medium">{m.name} <span className="text-[11px] text-muted-foreground">({m.code})</span></p>
                  <StatusBadge value={m.status} />
                </div>
                <p className="text-xs text-muted-foreground mt-1">{m.roomNumber || '-'} · {m.slotDurationMinutes || 30}m slots · ₹{m.price ?? 0}</p>
              </div>
            ))}
            {supportedStudies.length > 0 && (
              <div>
                <p className="text-xs font-semibold text-muted-foreground mb-1">Supported studies</p>
                <div className="flex flex-wrap gap-1">
                  {Array.from(new Set(supportedStudies)).map((s: string, i: number) => (
                    <span key={i} className="text-[11px] px-2 py-0.5 rounded-full bg-muted"><ModalityBadge value={modalityType} /> {s}</span>
                  ))}
                </div>
              </div>
            )}
            {reportTemplates.length > 0 && (
              <div>
                <p className="text-xs font-semibold text-muted-foreground mb-1">Report templates</p>
                <div className="flex flex-wrap gap-1">
                  {Array.from(new Set(reportTemplates)).map((s: string, i: number) => (
                    <span key={i} className="text-[11px] px-2 py-0.5 rounded-full bg-purple-500/10 text-purple-600">{s}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {screeningOrder && (
        <RadiologySafetyScreeningModal
          order={screeningOrder}
          onClose={() => setScreeningOrder(null)}
          onSave={(b: any) => screeningMut.mutate({ id: screeningOrder._id, ...b })}
        />
      )}

      {reportingOrder && (
        <RadiologyReportingModal
          order={reportingOrder}
          onClose={() => setReportingOrder(null)}
          onSubmit={(b: any) => reportMut.mutate({ id: reportingOrder._id, ...b })}
        />
      )}

      <Modal open={Boolean(contrastOrder)} onClose={() => setContrastOrder(null)} title="Record Contrast Administration">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          contrastMut.mutate({
            id: contrastOrder._id,
            agent: contrast.agent,
            volumeMl: Number(contrast.volumeMl) || 0,
            route: contrast.route,
            givenAt: contrast.givenAt ? new Date(contrast.givenAt).toISOString() : new Date().toISOString(),
            reaction: contrast.reaction,
          });
        }} className="space-y-4 text-sm">
          <p className="text-xs text-muted-foreground">{contrastOrder?.orderId} · {contrastOrder?.patientName} · {contrastOrder?.bodyPart}</p>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Contrast agent"><Input value={contrast.agent} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setContrast((c: any) => ({ ...c, agent: e.target.value }))} /></Field>
            <Field label="Volume (mL)"><Input type="number" min={0} value={contrast.volumeMl} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setContrast((c: any) => ({ ...c, volumeMl: e.target.value }))} /></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Route">
              <select value={contrast.route} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setContrast((c: any) => ({ ...c, route: e.target.value }))} className="w-full h-10 px-3 rounded-lg border border-input bg-background text-sm">
                {['IV', 'Oral', 'Rectal', 'Intrathecal'].map((r: string) => <option key={r} value={r}>{r}</option>)}
              </select>
            </Field>
            <Field label="Given at"><Input type="datetime-local" value={contrast.givenAt} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setContrast((c: any) => ({ ...c, givenAt: e.target.value }))} /></Field>
          </div>
          <Field label="Reaction / notes"><Input value={contrast.reaction} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setContrast((c: any) => ({ ...c, reaction: e.target.value }))} placeholder="None observed" /></Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => setContrastOrder(null)}>Cancel</Button>
            <Button type="submit" disabled={contrastMut.isPending}><Syringe className="w-4 h-4 mr-1" /> Save Record</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Plus, Pencil, Trash2, Settings2, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { radApi } from '@/lib/api';
import {
  Modal, Field, StatusBadge, errMessage, inputCls, selectCls, textareaCls,
  parseList, listToText, RAD_MODALITY_TYPES,
} from '@/components/radiology/radShared';

const WEEK_DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const emptyForm = {
  name: '', code: '', modalityType: 'X-Ray', roomNumber: '', machineModel: '', manufacturer: '',
  dicomAETitle: '', dicomPort: '4242', slotDurationMinutes: '30', status: 'Available',
  requiresContrastScreening: false, requiresImplantCheck: false,
  supportedStudies: '', prepRules: '', reportTemplates: '',
  price: '0', insuranceRate: '0',
  workingHoursOpen: '08:00', workingHoursClose: '20:00',
  workingDays: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] as string[],
  maintenanceScheduleDays: '90', dailyCapacity: '20', assignedStaff: '',
};

export default function ModalityMaster() {
  const qc = useQueryClient();
  const [search, setSearch] = useState('');
  const [showInactive, setShowInactive] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [showDialog, setShowDialog] = useState(false);
  const [form, setForm] = useState<any>({ ...emptyForm });

  const modsQ = useQuery({ queryKey: ['radiology', 'modalities'], queryFn: () => radApi.getModalities() });
  const all: any[] = modsQ.data?.modalities || [];

  const set = (k: string, v: any) => setForm((f: any) => ({ ...f, [k]: v }));

  const invalidate = () => qc.invalidateQueries({ queryKey: ['radiology'] });

  const saveMut = useMutation({
    mutationFn: (b: any) => (editing ? radApi.updateModality(editing._id, b) : radApi.createModality(b)),
    onSuccess: () => {
      toast.success(editing ? 'Modality updated' : 'Modality created');
      invalidate();
      setShowDialog(false);
      setEditing(null);
    },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to save modality')),
  });
  const deleteMut = useMutation({
    mutationFn: (id: string) => radApi.deleteModality(id),
    onSuccess: () => { toast.success('Modality deactivated'); invalidate(); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to deactivate')),
  });

  const openCreate = () => { setEditing(null); setForm({ ...emptyForm }); setShowDialog(true); };
  const openEdit = (m: any) => {
    setEditing(m);
    setForm({
      name: m.name || '', code: m.code || '', modalityType: m.modalityType || 'X-Ray',
      roomNumber: m.roomNumber || '', machineModel: m.machineModel || '', manufacturer: m.manufacturer || '',
      dicomAETitle: m.dicomAETitle || '', dicomPort: String(m.dicomPort ?? 4242),
      slotDurationMinutes: String(m.slotDurationMinutes ?? 30), status: m.status || 'Available',
      requiresContrastScreening: Boolean(m.requiresContrastScreening), requiresImplantCheck: Boolean(m.requiresImplantCheck),
      supportedStudies: listToText(m.supportedStudies), prepRules: listToText(m.prepRules),
      reportTemplates: listToText(m.reportTemplates),
      price: String(m.price ?? 0), insuranceRate: String(m.insuranceRate ?? 0),
      workingHoursOpen: m.workingHours?.open || '08:00', workingHoursClose: m.workingHours?.close || '20:00',
      workingDays: m.workingHours?.days?.length ? [...m.workingHours.days] : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
      maintenanceScheduleDays: String(m.maintenanceScheduleDays ?? 90), dailyCapacity: String(m.dailyCapacity ?? 20),
      assignedStaff: listToText(m.assignedStaff),
    });
    setShowDialog(true);
  };

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    saveMut.mutate({
      name: form.name,
      code: form.code,
      modalityType: form.modalityType,
      roomNumber: form.roomNumber,
      machineModel: form.machineModel,
      manufacturer: form.manufacturer,
      dicomAETitle: form.dicomAETitle,
      dicomPort: Number(form.dicomPort) || undefined,
      slotDurationMinutes: Number(form.slotDurationMinutes) || 30,
      status: form.status,
      requiresContrastScreening: form.requiresContrastScreening,
      requiresImplantCheck: form.requiresImplantCheck,
      supportedStudies: parseList(form.supportedStudies),
      prepRules: parseList(form.prepRules),
      reportTemplates: parseList(form.reportTemplates),
      price: Number(form.price) || 0,
      insuranceRate: Number(form.insuranceRate) || 0,
      workingHours: { open: form.workingHoursOpen, close: form.workingHoursClose, days: form.workingDays },
      maintenanceScheduleDays: Number(form.maintenanceScheduleDays) || 90,
      dailyCapacity: Number(form.dailyCapacity) || 20,
      assignedStaff: parseList(form.assignedStaff),
    });
  };

  const filtered = all.filter((m: any) => {
    if (!showInactive && m.status === 'Inactive') return false;
    if (!search) return true;
    const s = search.toLowerCase();
    return [m.name, m.code, m.modalityType, m.roomNumber, m.machineModel].some((v: any) => String(v || '').toLowerCase().includes(s));
  });

  const flag = (on: boolean) => (
    <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${on ? 'bg-emerald-500/10 text-emerald-600' : 'bg-muted text-muted-foreground'}`}>{on ? 'ON' : 'OFF'}</span>
  );

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Modality Master</h1>
          <p className="page-subtitle">{filtered.length} machines & rooms configured</p>
        </div>
        <Button onClick={openCreate}><Plus className="w-4 h-4 mr-1" /> Add Modality</Button>
      </div>

      <div className="flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search name, code, room..." className="pl-10" value={search} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value)} />
        </div>
        <label className="flex items-center gap-2 text-sm cursor-pointer">
          <input type="checkbox" checked={showInactive} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setShowInactive(e.target.checked)} className="rounded" />
          Show inactive
        </label>
      </div>

      <div className="bg-card rounded-xl border shadow-sm overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs text-muted-foreground border-b">
              <th className="p-3 font-medium">Machine</th>
              <th className="p-3 font-medium">Type</th>
              <th className="p-3 font-medium">Room</th>
              <th className="p-3 font-medium">Model</th>
              <th className="p-3 font-medium">Status</th>
              <th className="p-3 font-medium text-right">Price</th>
              <th className="p-3 font-medium text-right">Slot</th>
              <th className="p-3 font-medium text-center">Flags</th>
              <th className="p-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((m: any) => (
              <tr key={m._id} className="border-b last:border-0 hover:bg-muted/30">
                <td className="p-3">
                  <p className="font-medium">{m.name}</p>
                  <p className="text-[11px] text-muted-foreground">{m.code}{m.manufacturer ? ` · ${m.manufacturer}` : ''}</p>
                </td>
                <td className="p-3">{m.modalityType}</td>
                <td className="p-3">{m.roomNumber || '-'}</td>
                <td className="p-3">{m.machineModel || '-'}</td>
                <td className="p-3"><StatusBadge value={m.status} /></td>
                <td className="p-3 text-right">₹{m.price ?? 0}{m.insuranceRate ? <span className="text-[11px] text-muted-foreground"> ({m.insuranceRate}% ins)</span> : null}</td>
                <td className="p-3 text-right">{m.slotDurationMinutes || 30}m</td>
                <td className="p-3">
                  <div className="flex gap-1 justify-center flex-wrap">
                    <span title="Requires contrast screening" className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-muted">C {flag(m.requiresContrastScreening)}</span>
                    <span title="Requires implant check" className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-muted">I {flag(m.requiresImplantCheck)}</span>
                  </div>
                </td>
                <td className="p-3">
                  <div className="flex gap-1 justify-end">
                    <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => openEdit(m)}><Pencil className="w-3 h-3 mr-1" /> Edit</Button>
                    {m.status !== 'Inactive' && (
                      <Button size="sm" variant="outline" className="h-7 text-xs text-destructive"
                        onClick={() => { if (window.confirm(`Deactivate ${m.name}? This is a soft delete.`)) deleteMut.mutate(m._id); }}>
                        <Trash2 className="w-3 h-3 mr-1" /> Deactivate
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={9} className="p-10 text-center text-muted-foreground">No modalities found</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <Modal open={showDialog} onClose={() => setShowDialog(false)} title={editing ? 'Edit Modality' : 'Add Modality'} wide>
        <form onSubmit={onSubmit} className="space-y-4 text-sm">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <Field label="Name *"><Input required value={form.name} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('name', e.target.value)} placeholder="Siemens Magnetom 3T" /></Field>
            <Field label="Code *"><Input required value={form.code} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('code', e.target.value.toUpperCase())} placeholder="MRI-01" /></Field>
            <Field label="Modality Type *">
              <select required value={form.modalityType} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => set('modalityType', e.target.value)} className={selectCls}>
                {RAD_MODALITY_TYPES.map((m: string) => <option key={m} value={m}>{m}</option>)}
              </select>
            </Field>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <Field label="Room"><Input value={form.roomNumber} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('roomNumber', e.target.value)} placeholder="Room 12" /></Field>
            <Field label="Machine Model"><Input value={form.machineModel} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('machineModel', e.target.value)} /></Field>
            <Field label="Manufacturer"><Input value={form.manufacturer} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('manufacturer', e.target.value)} /></Field>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
            <Field label="DICOM AE Title"><Input value={form.dicomAETitle} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('dicomAETitle', e.target.value)} /></Field>
            <Field label="DICOM Port"><Input type="number" value={form.dicomPort} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('dicomPort', e.target.value)} /></Field>
            <Field label="Slot minutes"><Input type="number" min={5} max={480} value={form.slotDurationMinutes} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('slotDurationMinutes', e.target.value)} /></Field>
            <Field label="Daily capacity"><Input type="number" min={1} value={form.dailyCapacity} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('dailyCapacity', e.target.value)} /></Field>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
            <Field label="Status">
              <select value={form.status} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => set('status', e.target.value)} className={selectCls}>
                {['Available', 'In Use', 'Under Maintenance', 'Out of Service'].map((s: string) => <option key={s} value={s}>{s}</option>)}
              </select>
            </Field>
            <Field label="Price (₹)"><Input type="number" min={0} value={form.price} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('price', e.target.value)} /></Field>
            <Field label="Insurance rate (%)"><Input type="number" min={0} max={100} value={form.insuranceRate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('insuranceRate', e.target.value)} /></Field>
            <Field label="Service every (days)"><Input type="number" min={1} value={form.maintenanceScheduleDays} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('maintenanceScheduleDays', e.target.value)} /></Field>
          </div>
          <div className="grid grid-cols-2 gap-4 p-3 rounded-lg border bg-muted/20">
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={form.requiresContrastScreening} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('requiresContrastScreening', e.target.checked)} className="rounded" />
              <span className="text-xs font-medium">Requires contrast screening</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={form.requiresImplantCheck} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('requiresImplantCheck', e.target.checked)} className="rounded" />
              <span className="text-xs font-medium">Requires implant check</span>
            </label>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <Field label="Working hours — open"><Input type="time" value={form.workingHoursOpen} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('workingHoursOpen', e.target.value)} /></Field>
            <Field label="Working hours — close"><Input type="time" value={form.workingHoursClose} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('workingHoursClose', e.target.value)} /></Field>
            <Field label="Assigned staff IDs" hint="Comma-separated user IDs">
              <Input value={form.assignedStaff} onChange={(e: React.ChangeEvent<HTMLInputElement>) => set('assignedStaff', e.target.value)} placeholder="id1, id2" />
            </Field>
          </div>
          <Field label="Working days">
            <div className="flex gap-1.5 flex-wrap">
              {WEEK_DAYS.map((d: string) => (
                <button key={d} type="button"
                  onClick={() => set('workingDays', form.workingDays.includes(d) ? form.workingDays.filter((x: string) => x !== d) : [...form.workingDays, d])}
                  className={`px-3 h-8 rounded-lg text-xs font-medium border ${form.workingDays.includes(d) ? 'bg-primary text-primary-foreground border-primary' : 'bg-background text-muted-foreground'}`}>
                  {d}
                </button>
              ))}
            </div>
          </Field>
          <Field label="Supported studies" hint="Comma-separated, e.g. Brain, Spine, Knee MR">
            <textarea className={textareaCls} value={form.supportedStudies} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => set('supportedStudies', e.target.value)} />
          </Field>
          <Field label="Preparation rules" hint="Comma or newline separated">
            <textarea className={textareaCls} value={form.prepRules} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => set('prepRules', e.target.value)} />
          </Field>
          <Field label="Report templates" hint="Comma-separated template names">
            <textarea className={textareaCls} value={form.reportTemplates} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => set('reportTemplates', e.target.value)} />
          </Field>
          <div className="flex gap-2 justify-end pt-2 sticky bottom-0 bg-card">
            <Button type="button" variant="ghost" onClick={() => setShowDialog(false)}>Cancel</Button>
            <Button type="submit" disabled={saveMut.isPending}><Settings2 className="w-4 h-4 mr-1" />{saveMut.isPending ? 'Saving...' : editing ? 'Save Changes' : 'Create Modality'}</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useState } from 'react';
import type { Unmodelled } from '@/lib/apiTypes';
import { useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Activity, Camera, Eye, Link2, RefreshCw, Search, Server, Wifi, WifiOff,
  CheckCircle2, AlertTriangle, Unlink, Upload,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { radApi } from '@/lib/api';
import PacsDicomViewer from '@/components/radiology/PacsDicomViewer';
import {
  Modal, Field, StatCard, StatusBadge, ModalityBadge, errMessage, patientNameOf, fmtDateTime,
} from '@/components/radiology/radShared';

const STUDY_CANDIDATE_MAX = 25;

export default function PacsDashboard() {
  const qc = useQueryClient();
  const nav = useNavigate();
  const [tab, setTab] = useState<'studies' | 'worklist'>('studies');
  const [search, setSearch] = useState('');
  const [linkTarget, setLinkTarget] = useState<any>(null);
  const [studyUid, setStudyUid] = useState('');
  const [viewerOrder, setViewerOrder] = useState<any>(null);

  const pingQ = useQuery({ queryKey: ['radiology', 'dicom', 'ping'], queryFn: () => radApi.dicomPing(), retry: false });
  const ordersQ = useQuery({ queryKey: ['radiology', 'orders', 'pacs'], queryFn: () => radApi.getOrders({}) });
  const worklistQ = useQuery({
    queryKey: ['radiology', 'dicom', 'worklist'],
    queryFn: () => radApi.dicomWorklist({}),
    retry: false,
    enabled: tab === 'worklist',
  });

  const orders: any[] = ordersQ.data?.orders || [];
  const candidates = orders
    .filter((o: any) => o.status !== 'Cancelled')
    .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .slice(0, STUDY_CANDIDATE_MAX);

  const studiesQ = useQuery({
    queryKey: ['radiology', 'dicom', 'studies', candidates.map((o: any) => String(o._id)).join(',')],
    queryFn: async () => {
      const results = await Promise.all(candidates.map(async (o: any) => {
        try {
          const r: any = await radApi.dicomStudies(o._id);
          return { order: o, study: r, error: null };
        } catch (e: any) {
          return { order: o, study: null, error: errMessage(e) };
        }
      }));
      return results;
    },
    enabled: candidates.length > 0,
  });

  const rows: any[] = (studiesQ.data || []).map((r: any) => {
    const s = r.study || {};
    const ds = r.order?.dicomStudy || {};
    const studyUidVal = s.studyUid || ds.studyUid || r.order?.studyUid || '';
    const transferStatus = s.transferStatus || ds.transferStatus || '';
    return {
      orderId: String(r.order._id),
      orderNumber: r.order.orderId,
      patientName: r.order.patientName,
      modality: r.order.modality,
      bodyPart: r.order.bodyPart,
      status: r.order.status,
      studyNumber: s.studyNumber || r.order.studyNumber || '',
      studyUid: studyUidVal,
      seriesCount: s.seriesCount ?? ds.seriesCount ?? 0,
      imageCount: s.imageCount ?? (r.order.imageUrls || []).length,
      transferStatus,
      storageStatus: s.storageStatus || ds.storageStatus || '',
      linkedAt: s.linkedAt || ds.linkedAt || null,
      imageUrls: r.order.imageUrls || [],
      order: r.order,
      error: r.error,
    };
  });

  const filtered = rows.filter((r: any) => {
    if (!search) return true;
    const s = search.toLowerCase();
    return [r.patientName, r.orderNumber, r.studyNumber, r.studyUid, r.modality].some((v: any) => String(v || '').toLowerCase().includes(s));
  });

  const pendingTransfer = filtered.filter((r: any) => ['Pending', 'Transferring'].includes(r.transferStatus)).length;
  const failed = filtered.filter((r: any) => r.transferStatus === 'Failed').length;
  const unlinked = filtered.filter((r: any) => !r.studyUid).length;
  const reachable = Boolean(pingQ.data?.reachable);

  const invalidate = () => qc.invalidateQueries({ queryKey: ['radiology'] });

  const linkMut = useMutation({
    mutationFn: (b: any) => radApi.dicomLink(b),
    onSuccess: () => { toast.success('Study linked to order'); invalidate(); setLinkTarget(null); setStudyUid(''); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to link study')),
  });
  const retryMut = useMutation({
    mutationFn: (b: any) => radApi.dicomRetry(b),
    onSuccess: () => { toast.success('Transfer retry queued'); invalidate(); },
    onError: (e: any) => toast.error(errMessage(e, 'Retry failed')),
  });
  const viewerMut = useMutation({
    mutationFn: (studyUidVal: string) => (radApi as Unmodelled).dicomViewerUrl(studyUidVal),
    onSuccess: (res: any) => {
      if (res?.url) window.open(res.url, '_blank');
      else toast.error('No viewer URL returned');
    },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to build viewer URL')),
  });

  const worklist: any[] = worklistQ.data?.studies || [];

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">PACS / DICOM Dashboard</h1>
          <p className="page-subtitle">Study transfer monitoring, PACS worklist mirror and viewer links</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" onClick={() => nav('/radiology/reports')}><Upload className="w-4 h-4 mr-1" /> Report Center</Button>
          <Button variant="outline" onClick={() => { qc.invalidateQueries({ queryKey: ['radiology', 'dicom'] }); toast.success('Refreshed'); }}>
            <RefreshCw className="w-4 h-4 mr-1" /> Refresh
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
        <StatCard label="Studies" value={filtered.length} tone="text-foreground" />
        <StatCard label="Pending Transfer" value={pendingTransfer} tone="text-amber-600" />
        <StatCard label="Failed" value={failed} tone="text-destructive" />
        <StatCard label="Unlinked" value={unlinked} tone="text-warning" />
        <div className="bg-card rounded-xl border p-4 flex items-center gap-3">
          {reachable ? <Wifi className="w-6 h-6 text-emerald-500" /> : <WifiOff className="w-6 h-6 text-destructive" />}
          <div>
            <p className={`text-sm font-bold ${reachable ? 'text-emerald-600' : 'text-destructive'}`}>{reachable ? 'PACS Online' : 'PACS Offline'}</p>
            <p className="text-[11px] text-muted-foreground">{pingQ.data?.host || 'unknown'}:{pingQ.data?.port || '-'}</p>
          </div>
        </div>
      </div>

      {!reachable && (
        <div className="rounded-lg border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive flex items-center gap-2">
          <AlertTriangle className="w-4 h-4" /> PACS (Orthanc) is not reachable — transfers and worklist mirror will fail until connectivity is restored.
        </div>
      )}

      <div className="flex gap-2 border-b pb-2">
        {(['studies', 'worklist'] as const).map((t: string) => (
          <button key={t} onClick={() => setTab(t as any)}
            className={`px-4 h-9 rounded-lg text-sm font-medium capitalize ${tab === t ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`}>
            {t === 'studies' ? 'RIS Studies' : 'PACS Worklist Mirror'}
          </button>
        ))}
      </div>

      {tab === 'studies' && (
        <>
          <div className="relative max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input className="pl-10" placeholder="Search patient / order / UID..." value={search} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value)} />
          </div>
          <div className="bg-card rounded-xl border shadow-sm overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs text-muted-foreground border-b">
                  <th className="p-3 font-medium">Study</th>
                  <th className="p-3 font-medium">Patient</th>
                  <th className="p-3 font-medium">Study UID</th>
                  <th className="p-3 font-medium text-right">Series / Images</th>
                  <th className="p-3 font-medium">Transfer</th>
                  <th className="p-3 font-medium">Storage</th>
                  <th className="p-3 font-medium text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((r: any) => (
                  <tr key={r.orderId} className="border-b last:border-0 hover:bg-muted/30">
                    <td className="p-3">
                      <p className="font-medium">{r.orderNumber}</p>
                      <p className="text-[11px] text-muted-foreground"><ModalityBadge value={r.modality} /> {r.bodyPart}</p>
                      <p className="text-[11px] text-muted-foreground">{r.studyNumber}</p>
                    </td>
                    <td className="p-3">
                      <p>{r.patientName}</p>
                      <p className="text-[11px] text-muted-foreground">{r.status}</p>
                    </td>
                    <td className="p-3">
                      {r.studyUid ? (
                        <p className="font-mono text-[11px] max-w-[200px] truncate" title={r.studyUid}>{r.studyUid}</p>
                      ) : (
                        <span className="text-[11px] text-amber-600 font-semibold inline-flex items-center gap-1"><Unlink className="w-3 h-3" /> Not linked</span>
                      )}
                      {r.linkedAt && <p className="text-[10px] text-muted-foreground">Linked {fmtDateTime(r.linkedAt)}</p>}
                    </td>
                    <td className="p-3 text-right">{r.seriesCount} / {r.imageCount}</td>
                    <td className="p-3">{r.transferStatus ? <StatusBadge value={r.transferStatus} /> : <span className="text-[11px] text-muted-foreground">-</span>}</td>
                    <td className="p-3">{r.storageStatus || '-'}</td>
                    <td className="p-3">
                      <div className="flex gap-1 justify-end flex-wrap">
                        {r.transferStatus === 'Failed' && (
                          <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => retryMut.mutate({ orderId: r.orderId })} disabled={retryMut.isPending}>
                            <RefreshCw className="w-3 h-3 mr-1" /> Retry
                          </Button>
                        )}
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => { setLinkTarget(r.order); setStudyUid(r.studyUid || ''); }}>
                          <Link2 className="w-3 h-3 mr-1" /> {r.studyUid ? 'Re-link' : 'Link'}
                        </Button>
                        <Button size="sm" variant="outline" className="h-7 text-xs" disabled={!r.studyUid || viewerMut.isPending} onClick={() => viewerMut.mutate(r.studyUid)}>
                          <Eye className="w-3 h-3 mr-1" /> Viewer URL
                        </Button>
                        <Button size="sm" variant="outline" className="h-7 text-xs bg-cyan-500/10 text-cyan-600" onClick={() => setViewerOrder(r)}>
                          <Camera className="w-3 h-3 mr-1" /> Open
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filtered.length === 0 && (
                  <tr><td colSpan={7} className="p-12 text-center text-muted-foreground"><Server className="w-10 h-10 mx-auto mb-2 opacity-30" />No studies found</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}

      {tab === 'worklist' && (
        <div className="bg-card rounded-xl border shadow-sm overflow-x-auto">
          <div className="p-4 border-b flex items-center justify-between">
            <h2 className="font-heading font-semibold">C-FIND Worklist (from PACS)</h2>
            <Button size="sm" variant="outline" onClick={() => worklistQ.refetch()}><RefreshCw className="w-3.5 h-3.5 mr-1" /> Query</Button>
          </div>
          {worklistQ.isLoading && <div className="flex justify-center py-12"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>}
          {worklistQ.isError && (
            <div className="p-6 text-sm text-destructive">{errMessage(worklistQ.error, 'Worklist query failed')} — is the PACS reachable?</div>
          )}
          {worklistQ.data && worklist.length === 0 && <div className="p-10 text-center text-muted-foreground">No studies returned by the PACS worklist</div>}
          {worklist.length > 0 && (
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs text-muted-foreground border-b">
                  {Object.keys(worklist[0] || {}).map((k: string) => (
                    <th key={k} className="p-3 font-medium whitespace-nowrap">{k}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {worklist.map((w: any, i: number) => (
                  <tr key={i} className="border-b last:border-0">
                    {Object.keys(worklist[0] || {}).map((k: string) => (
                      <td key={k} className="p-3 whitespace-nowrap">{typeof w[k] === 'object' && w[k] !== null ? JSON.stringify(w[k]) : String(w[k] ?? '-')}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      <Modal open={Boolean(linkTarget)} onClose={() => { setLinkTarget(null); setStudyUid(''); }} title="Link PACS Study to Order">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          linkMut.mutate({ orderId: String(linkTarget._id), studyUid: studyUid.trim() });
        }} className="space-y-4 text-sm">
          <p className="text-xs text-muted-foreground">{linkTarget?.orderId} · {linkTarget?.patientName} · {linkTarget?.modality} ({linkTarget?.bodyPart})</p>
          <Field label="Study Instance UID *" hint="Paste the StudyInstanceUID from the PACS / modality console">
            <Input required value={studyUid} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setStudyUid(e.target.value)} placeholder="1.2.840.113619.2.55.3..." className="font-mono" />
          </Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => { setLinkTarget(null); setStudyUid(''); }}>Cancel</Button>
            <Button type="submit" disabled={linkMut.isPending || !studyUid.trim()}><Link2 className="w-4 h-4 mr-1" /> Link Study</Button>
          </div>
        </form>
      </Modal>

      {viewerOrder && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur z-50 flex items-center justify-center p-4">
          <div className="max-w-6xl w-full">
            <PacsDicomViewer
              orderId={viewerOrder.orderNumber}
              patientName={viewerOrder.patientName}
              modality={viewerOrder.modality}
              bodyPart={viewerOrder.bodyPart}
              imageUrl={viewerOrder.imageUrls?.[0] || undefined}
              onClose={() => setViewerOrder(null)}
            />
          </div>
        </div>
      )}

      {filtered.length > 0 && (
        <div className="bg-card rounded-xl border shadow-sm p-4">
          <p className="text-xs font-semibold text-muted-foreground flex items-center gap-1.5 mb-2"><Activity className="w-3.5 h-3.5" /> Transfer log (latest state per study)</p>
          <ul className="space-y-1 text-xs">
            {filtered.slice(0, 8).map((r: any) => (
              <li key={r.orderId} className="flex flex-wrap items-center gap-2 bg-muted/30 rounded px-2 py-1">
                <CheckCircle2 className={`w-3 h-3 ${r.transferStatus === 'Completed' ? 'text-emerald-500' : 'text-muted-foreground'}`} />
                <span className="font-medium">{r.orderNumber}</span>
                <span className="text-muted-foreground">→ {r.studyUid ? 'PACS linked' : 'no study'}</span>
                <span className="text-muted-foreground">· {r.transferStatus || 'never transferred'}</span>
                {r.linkedAt && <span className="text-muted-foreground">· {fmtDateTime(r.linkedAt)}</span>}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import type { Unmodelled } from '@/lib/apiTypes';
import { useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  CheckCircle2, ChevronDown, ChevronRight, ClipboardList, Plus, ShieldAlert,
  Siren, ThumbsUp, Trash2, X,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { radApi } from '@/lib/api';
import {
  Modal, Field, StatusBadge, ModalityBadge, PriorityBadge, errMessage, textareaCls,
  patientNameOf, prepChecklistFor, fmtDateTime,
} from '@/components/radiology/radShared';

export default function PreparationQueue() {
  const qc = useQueryClient();
  const nav = useNavigate();
  const [expanded, setExpanded] = useState<string | null>(null);
  const [holdTarget, setHoldTarget] = useState<any>(null);
  const [holdReason, setHoldReason] = useState('');
  const [escalateTarget, setEscalateTarget] = useState<any>(null);
  const [escalateNote, setEscalateNote] = useState('');
  const [missingDraft, setMissingDraft] = useState<Record<string, string>>({});

  const queueQ = useQuery({ queryKey: ['radiology', 'preparation'], queryFn: () => radApi.getPreparation() });
  const orders: any[] = queueQ.data?.orders || [];

  const invalidate = () => qc.invalidateQueries({ queryKey: ['radiology'] });

  const prepMut = useMutation({
    mutationFn: ({ id, ...b }: any) => radApi.updatePreparation(id, b),
    onSuccess: () => { invalidate(); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to update preparation')),
  });

  const mergedChecklist = (o: any): { item: string; done: boolean }[] => {
    const stored: any[] = o.preparation?.checklist || [];
    const defaults = prepChecklistFor(o.modality);
    const items: { item: string; done: boolean }[] = [];
    for (const d of defaults) {
      const hit = stored.find((s: any) => s.item === d);
      items.push({ item: d, done: Boolean(hit?.done) });
    }
    for (const s of stored) {
      if (!items.some((i: Unmodelled) => i.item === s.item)) items.push({ item: s.item, done: Boolean(s.done) });
    }
    return items;
  };

  const toggleItem = (o: any, item: string, done: boolean) => {
    const list = mergedChecklist(o).map((i: any) => (i.item === item ? { item: i.item, done } : { item: i.item, done: i.done }));
    prepMut.mutate({ id: o._id, checklist: list });
  };

  const addMissing = (o: any, text: string) => {
    const t = text.trim();
    if (!t) return;
    const next = [...(o.preparation?.missingInfo || []), t];
    prepMut.mutate({ id: o._id, missingInfo: next });
    setMissingDraft((d: any) => ({ ...d, [o._id]: '' }));
  };

  const removeMissing = (o: any, idx: number) => {
    const next = (o.preparation?.missingInfo || []).filter((_: any, i: number) => i !== idx);
    prepMut.mutate({ id: o._id, missingInfo: next });
  };

  const setConsent = (o: any, consentTaken: boolean) => prepMut.mutate({ id: o._id, consentTaken });

  const markReady = (o: any) => {
    const list = mergedChecklist(o);
    const allDone = list.every((i: any) => i.done);
    if (!allDone) { toast.error('Complete every checklist item before marking ready'); return; }
    prepMut.mutate({ id: o._id, ready: true, hold: false });
    toast.success(`${o.patientName} marked Ready for Imaging`);
  };

  const stats = {
    total: orders.length,
    hold: orders.filter((o: any) => o.preparation?.hold).length,
    consent: orders.filter((o: any) => o.preparation?.consentTaken).length,
    missing: orders.filter((o: any) => (o.preparation?.missingInfo || []).length > 0).length,
  };

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Preparation & Clearance Queue</h1>
          <p className="page-subtitle">{stats.total} patients awaiting pre-imaging preparation</p>
        </div>
        <Button variant="outline" onClick={() => nav('/radiology/scheduling')}>Scheduling Calendar</Button>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { l: 'In Queue', v: stats.total, c: 'text-foreground' },
          { l: 'On Hold', v: stats.hold, c: 'text-destructive' },
          { l: 'Consent Taken', v: stats.consent, c: 'text-success' },
          { l: 'Missing Info', v: stats.missing, c: 'text-warning' },
        ].map((s: any) => (
          <div key={s.l} className="bg-card rounded-xl border p-4 text-center">
            <p className={`text-2xl font-bold ${s.c}`}>{s.v}</p>
            <p className="text-xs text-muted-foreground">{s.l}</p>
          </div>
        ))}
      </div>

      <div className="space-y-3">
        {orders.map((o: any) => {
          const isOpen = expanded === o._id;
          const list = mergedChecklist(o);
          const doneCount = list.filter((i: any) => i.done).length;
          const missing: string[] = o.preparation?.missingInfo || [];
          return (
            <div key={o._id} className="bg-card rounded-xl border shadow-sm">
              <div className="p-4 cursor-pointer flex items-center gap-3" onClick={() => setExpanded(isOpen ? null : o._id)}>
                {isOpen ? <ChevronDown className="w-4 h-4 text-muted-foreground" /> : <ChevronRight className="w-4 h-4 text-muted-foreground" />}
                <ModalityBadge value={o.modality} />
                <div className="flex-1 min-w-0">
                  <p className="font-medium">{patientNameOf(o.patientId || o)}</p>
                  <p className="text-xs text-muted-foreground truncate">{o.orderId} · {o.bodyPart} · {fmtDateTime(o.createdAt)}</p>
                </div>
                <PriorityBadge value={o.priority} />
                <span className="text-xs font-semibold text-muted-foreground">{doneCount}/{list.length}</span>
                {o.preparation?.hold && <span className="text-[11px] font-bold px-2 py-1 rounded-full bg-destructive/10 text-destructive">On Hold</span>}
                {o.preparation?.consentTaken && <span className="text-[11px] font-bold px-2 py-1 rounded-full bg-emerald-500/10 text-emerald-600">Consent</span>}
                {String(o.preparation?.holdReason || '').startsWith('Escalated') && (
                  <span className="text-[11px] font-bold px-2 py-1 rounded-full bg-amber-500/10 text-amber-600 inline-flex items-center"><Siren className="w-3 h-3 mr-0.5" />Escalated</span>
                )}
                <StatusBadge value={o.status} />
              </div>

              {isOpen && (
                <div className="px-4 pb-4 border-t pt-4 space-y-4">
                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                    <div className="rounded-lg border p-3">
                      <p className="text-xs font-semibold text-muted-foreground mb-2 flex items-center gap-1.5"><ClipboardList className="w-3.5 h-3.5" /> {o.modality} checklist</p>
                      <ul className="space-y-2">
                        {list.map((i: any) => (
                          <li key={i.item} className="flex items-center gap-2 text-sm">
                            <input type="checkbox" checked={i.done} disabled={prepMut.isPending}
                              onChange={(e: React.ChangeEvent<HTMLInputElement>) => toggleItem(o, i.item, e.target.checked)}
                              className="rounded text-emerald-600 w-4 h-4" />
                            <span className={i.done ? 'line-through text-muted-foreground' : ''}>{i.item}</span>
                          </li>
                        ))}
                      </ul>
                      <div className="mt-3 h-1.5 rounded-full bg-muted overflow-hidden">
                        <div className="h-full bg-emerald-500 transition-all" style={{ width: `${Math.round((doneCount / (list.length || 1)) * 100)}%` }} />
                      </div>
                    </div>

                    <div className="space-y-3">
                      <div className="rounded-lg border p-3">
                        <p className="text-xs font-semibold text-muted-foreground mb-2">Consent</p>
                        <label className="flex items-center gap-2 text-sm cursor-pointer">
                          <input type="checkbox" checked={Boolean(o.preparation?.consentTaken)} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setConsent(o, e.target.checked)} className="rounded text-emerald-600 w-4 h-4" />
                          Informed consent taken
                        </label>
                      </div>
                      <div className="rounded-lg border p-3">
                        <p className="text-xs font-semibold text-muted-foreground mb-2">Missing information</p>
                        <ul className="space-y-1 mb-2">
                          {missing.map((m: string, i: number) => (
                            <li key={i} className="flex items-center justify-between text-sm bg-amber-500/10 rounded px-2 py-1">
                              <span>{m}</span>
                              <button onClick={() => removeMissing(o, i)} type="button"><X className="w-3.5 h-3.5 text-muted-foreground hover:text-destructive" /></button>
                            </li>
                          ))}
                        </ul>
                        <div className="flex gap-2">
                          <Input placeholder="Add missing item..." className="h-9" value={missingDraft[o._id] || ''}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setMissingDraft((d: any) => ({ ...d, [o._id]: e.target.value }))} />
                          <Button size="sm" variant="outline" className="h-9" onClick={() => addMissing(o, missingDraft[o._id] || '')}><Plus className="w-3.5 h-3.5" /></Button>
                        </div>
                      </div>
                      {o.preparation?.hold && (
                        <div className="rounded-lg border border-destructive/40 bg-destructive/5 p-3">
                          <p className="text-xs font-semibold text-destructive mb-1">Hold reason</p>
                          <p className="text-sm">{o.preparation.holdReason || 'No reason recorded'}</p>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex gap-2 flex-wrap justify-end">
                    <Button size="sm" variant="outline" className="text-amber-600" onClick={() => { setEscalateTarget(o); setEscalateNote(''); }}>
                      <Siren className="w-3.5 h-3.5 mr-1" /> Escalate
                    </Button>
                    <Button size="sm" variant="outline" className="text-destructive" onClick={() => { setHoldTarget(o); setHoldReason(''); }}>
                      <ShieldAlert className="w-3.5 h-3.5 mr-1" /> Hold
                    </Button>
                    <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white" onClick={() => markReady(o)} disabled={prepMut.isPending}>
                      <ThumbsUp className="w-3.5 h-3.5 mr-1" /> Mark Ready for Imaging
                    </Button>
                  </div>
                </div>
              )}
            </div>
          );
        })}
        {!queueQ.isLoading && orders.length === 0 && (
          <div className="text-center py-20 bg-card rounded-2xl border border-dashed">
            <CheckCircle2 className="w-12 h-12 text-emerald-500/40 mx-auto mb-3" />
            <p className="text-muted-foreground">Preparation queue is clear</p>
          </div>
        )}
        {queueQ.isLoading && <div className="flex justify-center py-16"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>}
      </div>

      <Modal open={Boolean(holdTarget)} onClose={() => setHoldTarget(null)} title="Put Study On Hold">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          prepMut.mutate({ id: holdTarget._id, hold: true, holdReason });
          toast.success('Study placed on hold');
          setHoldTarget(null);
        }} className="space-y-4 text-sm">
          <p className="text-xs text-muted-foreground">{holdTarget?.orderId} · {holdTarget?.patientName}</p>
          <Field label="Reason *">
            <textarea required className={textareaCls} value={holdReason} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setHoldReason(e.target.value)} placeholder="e.g. Patient not fasting, renal report missing..." />
          </Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => setHoldTarget(null)}>Cancel</Button>
            <Button type="submit" variant="destructive">Place Hold</Button>
          </div>
        </form>
      </Modal>

      <Modal open={Boolean(escalateTarget)} onClose={() => setEscalateTarget(null)} title="Escalate to Radiologist">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          prepMut.mutate({ id: escalateTarget._id, hold: true, holdReason: `Escalated: ${escalateNote}` });
          toast.success('Escalation noted — study held for radiologist review');
          setEscalateTarget(null);
        }} className="space-y-4 text-sm">
          <p className="text-xs text-muted-foreground">{escalateTarget?.orderId} · {escalateTarget?.patientName} · {escalateTarget?.modality}</p>
          <Field label="Escalation note *">
            <textarea required className={textareaCls} value={escalateNote} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setEscalateNote(e.target.value)} placeholder="e.g. eGFR 24 — clarify contrast plan with radiologist" />
          </Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => setEscalateTarget(null)}>Cancel</Button>
            <Button type="submit" className="bg-amber-600 hover:bg-amber-700 text-white"><Siren className="w-4 h-4 mr-1" /> Escalate</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import {
  Activity, AlertTriangle, ArrowRight, CalendarClock, CalendarX, Camera, Clock,
  FileWarning, Wrench, Users, Siren, XCircle, BarChart3,
} from 'lucide-react';
import { radApi } from '@/lib/api';
import {
  RAD_LINKS, StatCard, StatusBadge, ModalityBadge, fmtDateTime, isToday,
  dayStart, dayEnd, errMessage,
} from '@/components/radiology/radShared';

const TAT_BREACH_HOURS = 24;

const REPORTED_STATUSES = ['Reported', 'Report Finalized', 'Report Released', 'Delivered'];

export default function RadiologyDashboard() {
  const nav = useNavigate();

  const ordersQ = useQuery({ queryKey: ['radiology', 'dashboard', 'orders'], queryFn: () => radApi.getOrders({}) });
  const apptsQ = useQuery({
    queryKey: ['radiology', 'dashboard', 'appointments'],
    queryFn: () => radApi.getAppointments({ from: dayStart().toISOString(), to: dayEnd().toISOString() }),
  });
  const modsQ = useQuery({ queryKey: ['radiology', 'modalities'], queryFn: () => radApi.getModalities() });
  const critQ = useQuery({ queryKey: ['radiology', 'critical'], queryFn: () => radApi.getCritical(), retry: false });

  const orders: any[] = ordersQ.data?.orders || [];
  const appointments: any[] = apptsQ.data?.appointments || [];
  const modalities: any[] = (modsQ.data?.modalities || []).filter((m: any) => m.status !== 'Inactive');
  const critical: any[] = critQ.data?.critical || [];

  const now = Date.now();
  const todaysStudies = orders.filter((o: any) => isToday(o.createdAt)).length;
  const awaitingScheduling = orders.filter((o: any) => ['Ordered', 'Authorization Pending', 'Payment Pending', 'Scheduling Pending'].includes(o.status)).length;
  const patientsWaiting = orders.filter((o: any) => ['Patient Arrived', 'Preparation Pending'].includes(o.status)).length;
  const inProgress = orders.filter((o: any) => o.status === 'In Progress').length;
  const reportsPending = orders.filter((o: any) => ['Completed', 'Study Completed', 'Reporting Pending'].includes(o.status)).length;
  const urgent = orders.filter((o: any) => ['Urgent', 'STAT'].includes(o.priority) && !REPORTED_STATUSES.includes(o.status) && o.status !== 'Cancelled').length;
  const cancelledToday = orders.filter((o: any) => o.status === 'Cancelled' && isToday(o.updatedAt || o.createdAt)).length;
  const noShowToday = appointments.filter((a: any) => a.status === 'No Show' && isToday(a.scheduledStart)).length;
  const tatBreaches = orders.filter((o: any) => {
    if (REPORTED_STATUSES.includes(o.status) || o.status === 'Cancelled') return false;
    if (!o.createdAt) return false;
    return (now - new Date(o.createdAt).getTime()) / 3600000 > TAT_BREACH_HOURS;
  });

  const byModality: Record<string, number> = {};
  for (const o of orders) {
    if (o.status === 'Cancelled') continue;
    byModality[o.modality || 'Unknown'] = (byModality[o.modality || 'Unknown'] || 0) + 1;
  }
  const modalityRows = Object.entries(byModality).sort((a: [string, number], b: [string, number]) => b[1] - a[1]);

  const equipment = {
    available: modalities.filter((m: any) => m.status === 'Available').length,
    inUse: modalities.filter((m: any) => m.status === 'In Use').length,
    maintenance: modalities.filter((m: any) => m.status === 'Under Maintenance').length,
    outOfService: modalities.filter((m: any) => m.status === 'Out of Service').length,
  };
  const maintenanceMachines = modalities.filter((m: any) => m.status === 'Under Maintenance' || m.status === 'Out of Service');

  const alerts: { level: 'danger' | 'warning' | 'info'; text: string; path?: string }[] = [];
  if (urgent > 0) alerts.push({ level: 'danger', text: `${urgent} urgent / STAT orders still not reported`, path: '/radiology/reports' });
  for (const c of critical.slice(0, 5)) {
    alerts.push({ level: 'danger', text: `Critical finding pending acknowledgement — ${c.patientName} (${c.modality} ${c.bodyPart})`, path: '/radiology/critical' });
  }
  for (const b of tatBreaches.slice(0, 5)) {
    alerts.push({ level: 'warning', text: `TAT breach: ${b.patientName} — ${b.modality} (${b.bodyPart}) ordered ${fmtDateTime(b.createdAt)}`, path: '/radiology/reports' });
  }
  for (const m of maintenanceMachines) {
    alerts.push({ level: 'warning', text: `Equipment ${m.name || m.code} is ${m.status} (service every ${m.maintenanceScheduleDays || '-'} days)`, path: '/radiology/modalities' });
  }
  const payPending = orders.filter((o: any) => o.status === 'Payment Pending').length;
  if (payPending > 0) alerts.push({ level: 'info', text: `${payPending} orders waiting on payment before scheduling`, path: '/radiology/reception' });
  if (awaitingScheduling > 0) alerts.push({ level: 'info', text: `${awaitingScheduling} orders awaiting scheduling`, path: '/radiology/scheduling' });

  const alertTone = (level: string) => (level === 'danger' ? 'border-destructive/40 bg-destructive/5' : level === 'warning' ? 'border-amber-500/40 bg-amber-500/5' : 'border-info/40 bg-info/5');

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Radiology Admin Dashboard</h1>
          <p className="page-subtitle">Operations overview across imaging, scheduling and reporting</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <button onClick={() => nav('/radiology/scheduling')} className="inline-flex items-center h-9 px-3 rounded-lg border text-sm font-medium hover:bg-muted">
            <CalendarClock className="w-4 h-4 mr-1.5" /> Scheduling
          </button>
          <button onClick={() => nav('/radiology/reception')} className="inline-flex items-center h-9 px-3 rounded-lg border text-sm font-medium hover:bg-muted">
            <Users className="w-4 h-4 mr-1.5" /> Reception
          </button>
          <button onClick={() => nav('/radiology/pacs')} className="inline-flex items-center h-9 px-3 rounded-lg border text-sm font-medium hover:bg-muted">
            <Camera className="w-4 h-4 mr-1.5" /> PACS
          </button>
        </div>
      </div>

      {ordersQ.isError && <div className="rounded-lg border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive">{errMessage(ordersQ.error, 'Failed to load radiology data')}</div>}

      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
        <StatCard label="Today's Studies" value={todaysStudies} tone="text-foreground" onClick={() => nav('/radiology')} />
        <StatCard label="Awaiting Scheduling" value={awaitingScheduling} tone="text-amber-600" onClick={() => nav('/radiology/scheduling')} />
        <StatCard label="Patients Waiting" value={patientsWaiting} tone="text-cyan-600" onClick={() => nav('/radiology/reception')} />
        <StatCard label="Studies In Progress" value={inProgress} tone="text-info" />
        <StatCard label="Reports Pending" value={reportsPending} tone="text-purple-600" onClick={() => nav('/radiology/reports')} />
        <StatCard label="Urgent / STAT" value={urgent} tone="text-warning" onClick={() => nav('/radiology/critical')} />
        <StatCard label="Cancelled" value={cancelledToday} tone="text-destructive" />
        <StatCard label="No-show (today)" value={noShowToday} tone="text-destructive" />
        <StatCard label={`TAT Breaches (>${TAT_BREACH_HOURS}h)`} value={tatBreaches.length} tone="text-destructive" onClick={() => nav('/radiology/mis')} />
        <StatCard label="Total Orders" value={orders.length} tone="text-foreground" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <BarChart3 className="w-4 h-4 text-primary" />
              <h2 className="font-heading font-semibold">Modality-wise Studies</h2>
            </div>
            <div className="p-4">
              {modalityRows.length === 0 ? (
                <p className="text-sm text-muted-foreground py-6 text-center">No active studies</p>
              ) : (
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-xs text-muted-foreground border-b">
                      <th className="pb-2 font-medium">Modality</th>
                      <th className="pb-2 font-medium text-right">Orders</th>
                      <th className="pb-2 font-medium text-right">Share</th>
                    </tr>
                  </thead>
                  <tbody>
                    {modalityRows.map(([m, c]: [string, number]) => {
                      const total = modalityRows.reduce((s: number, r: [string, number]) => s + r[1], 0) || 1;
                      return (
                        <tr key={m} className="border-b last:border-0">
                          <td className="py-2"><ModalityBadge value={m} /></td>
                          <td className="py-2 text-right font-semibold">{c}</td>
                          <td className="py-2 text-right text-muted-foreground">{Math.round((c / total) * 100)}%</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )}
            </div>
            <p className="px-4 pb-4 text-[11px] text-muted-foreground">Revenue figures are available under MIS Reports → Radiology Revenue.</p>
          </div>

          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <Wrench className="w-4 h-4 text-primary" />
              <h2 className="font-heading font-semibold">Equipment Status</h2>
            </div>
            <div className="p-4 space-y-4">
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                <StatCard label="Available" value={equipment.available} tone="text-emerald-600" />
                <StatCard label="In Use" value={equipment.inUse} tone="text-info" />
                <StatCard label="Maintenance" value={equipment.maintenance} tone="text-amber-600" />
                <StatCard label="Out of Service" value={equipment.outOfService} tone="text-destructive" />
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-xs text-muted-foreground border-b">
                      <th className="pb-2 font-medium">Machine</th>
                      <th className="pb-2 font-medium">Code</th>
                      <th className="pb-2 font-medium">Type</th>
                      <th className="pb-2 font-medium">Room</th>
                      <th className="pb-2 font-medium">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {modalities.map((m: any) => (
                      <tr key={m._id} className="border-b last:border-0">
                        <td className="py-2 font-medium">{m.name}</td>
                        <td className="py-2 text-muted-foreground">{m.code}</td>
                        <td className="py-2">{m.modalityType}</td>
                        <td className="py-2">{m.roomNumber || '-'}</td>
                        <td className="py-2"><StatusBadge value={m.status} /></td>
                      </tr>
                    ))}
                    {modalities.length === 0 && (
                      <tr><td colSpan={5} className="py-6 text-center text-muted-foreground">No modalities configured</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
              <button onClick={() => nav('/radiology/modalities')} className="text-xs font-medium text-primary inline-flex items-center">
                Manage Modality Master <ArrowRight className="w-3 h-3 ml-1" />
              </button>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
