        <select value={typeFilter} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => { setTypeFilter(e.target.value); setMachineFilter(''); }} className={selectCls + ' w-auto'}>
          <option value="All">All Modalities</option>
