                        {rows.map((a: any) => (
                          <tr key={a._id} className="border-b last:border-0 hover:bg-muted/30">
                            <td className="py-2 pr-3 whitespace-nowrap">
                              <p className="font-semibold">{new Date(a.scheduledStart).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                              <p className="text-[11px] text-muted-foreground">{a.slotMinutes}m</p>
                            </td>
                            <td className="py-2 pr-3">
                              <p className="font-medium">{patientNameOf(a.patientId || a)}</p>
                              <p className="text-[11px] text-muted-foreground">{a.appointmentNo}</p>
                            </td>
                            <td className="py-2 pr-3"><ModalityBadge value={a.modalityType} /></td>
                            <td className="py-2 pr-3">
                              <p>{a.machineId?.name || '-'}</p>
                              <p className="text-[11px] text-muted-foreground inline-flex items-center"><MapPin className="w-3 h-3 mr-0.5" />{a.room || a.machineId?.roomNumber || '-'}</p>
                            </td>
                            <td className="py-2 pr-3"><StatusBadge value={a.slotType} /></td>
                            <td className="py-2 pr-3"><StatusBadge value={a.status} /></td>
                            <td className="py-2">
                              <div className="flex gap-1 justify-end flex-wrap">
                                {ACTIVE_APPT.includes(a.status) && (
                                  <>
                                    <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => { setResched(a); setReschedAt(toDateTimeLocal(a.scheduledStart)); }}>
                                      <RefreshCw className="w-3 h-3 mr-1" /> Reschedule
                                    </Button>
                                    {a.status !== 'Arrived' && (
                                      <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => checkinMut.mutate(a._id)}>
                                        <UserCheck className="w-3 h-3 mr-1" /> Check-in
                                      </Button>
                                    )}
                                    <Button size="sm" variant="outline" className="h-7 text-xs text-destructive" onClick={() => setCancelTarget(a)}>
                                      <Ban className="w-3 h-3 mr-1" /> Cancel
                                    </Button>
                                  </>
                                )}
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <Clock className="w-4 h-4 text-primary" />
              <h2 className="font-heading font-semibold">Machine Availability</h2>
            </div>
            <div className="p-4 space-y-3 max-h-[520px] overflow-y-auto">
              {availQ.isLoading && <p className="text-sm text-muted-foreground">Loading availability...</p>}
              {availability.map((m: any) => (
                <div key={m.machineId} className="rounded-lg border p-3">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-medium">{m.name || m.code || 'Machine'}</p>
                    <StatusBadge value={m.status} />
                  </div>
                  <p className="text-[11px] text-muted-foreground">{m.modalityType} · {m.room || '-'} · {m.slotDurationMinutes || 30} min slots</p>
                  {m.busy?.length ? (
                    <ul className="mt-2 space-y-1">
                      {m.busy.map((b: any, i: number) => (
                        <li key={i} className="text-[11px] flex items-center justify-between bg-muted/50 rounded px-2 py-1">
                          <span>{new Date(b.start).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {new Date(b.end).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                          <span className="text-muted-foreground">{b.appointmentNo} · {b.slotType}</span>
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <p className="mt-2 text-[11px] text-emerald-600 font-medium">Fully free this day</p>
                  )}
                </div>
              ))}
              {!availQ.isLoading && availability.length === 0 && <p className="text-sm text-muted-foreground">No machines for the selected filters</p>}
            </div>
          </div>
        </div>
      </div>

      <Modal open={showBook} onClose={() => setShowBook(false)} title={book.slotType === 'Maintenance Block' ? 'Block Machine Slot' : 'Book Imaging Appointment'}>
        <form onSubmit={onBookSubmit} className="space-y-4 text-sm">
          <Field label="Link to order (Scheduling Pending)" hint="Selecting an order fills patient + modality automatically">
            <select value={book.radiologyOrderId} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => pickOrder(e.target.value)} className={selectCls}>
              <option value="">— No linked order (walk-in) —</option>
              {schedulableOrders.map((o: any) => (
                <option key={o._id} value={o._id}>{o.orderId} · {o.patientName} · {o.modality} ({o.bodyPart})</option>
              ))}
            </select>
          </Field>
          <Field label="Patient ID *">
            <Input required value={book.patientId} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setBook((b: any) => ({ ...b, patientId: e.target.value }))} placeholder="Patient user id" />
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Modality Type *">
              <select required value={book.modalityType} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setBook((b: any) => ({ ...b, modalityType: e.target.value }))} className={selectCls}>
                {RAD_MODALITY_TYPES.map((m: string) => <option key={m} value={m}>{m}</option>)}
              </select>
            </Field>
            <Field label="Machine">
              <select value={book.machineId} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => pickMachine(e.target.value)} className={selectCls}>
                <option value="">— None —</option>
                {machines.filter((m: any) => m.modalityType === book.modalityType).map((m: any) => (
                  <option key={m._id} value={m._id}>{m.name} ({m.code})</option>
                ))}
              </select>
            </Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Start *">
              <Input required type="datetime-local" value={book.scheduledStart} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setBook((b: any) => ({ ...b, scheduledStart: e.target.value }))} />
            </Field>
            <Field label="Slot minutes (from machine)">
              <Input type="number" min={5} max={480} value={book.slotMinutes} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setBook((b: any) => ({ ...b, slotMinutes: e.target.value }))} />
            </Field>
          </div>
          <div className="flex gap-4">
            <label className="flex items-center gap-2 text-xs font-medium cursor-pointer">
              <input type="checkbox" checked={book.slotType === 'Emergency'} disabled={book.slotType === 'Maintenance Block'}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setBook((b: any) => ({ ...b, slotType: e.target.checked ? 'Emergency' : 'Regular' }))} className="rounded" />
              Emergency slot
            </label>
            <label className="flex items-center gap-2 text-xs font-medium cursor-pointer">
              <input type="checkbox" checked={book.slotType === 'Maintenance Block'}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setBook((b: any) => ({ ...b, slotType: e.target.checked ? 'Maintenance Block' : 'Regular' }))} className="rounded" />
              Maintenance block
            </label>
          </div>
          <Field label="Notes">
            <textarea className={textareaCls} value={book.notes} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setBook((b: any) => ({ ...b, notes: e.target.value }))} />
          </Field>
          <div className="flex gap-2 justify-end pt-2">
            <Button type="button" variant="ghost" onClick={() => setShowBook(false)}>Cancel</Button>
            <Button type="submit" disabled={bookMut.isPending}>
              {bookMut.isPending ? 'Booking...' : <><Check className="w-4 h-4 mr-1" /> Confirm Booking</>}
            </Button>
          </div>
        </form>
      </Modal>

      <Modal open={Boolean(resched)} onClose={() => setResched(null)} title="Reschedule Appointment">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          reschedMut.mutate({ id: resched._id, scheduledStart: new Date(reschedAt).toISOString(), reason: 'Rescheduled from calendar' });
        }} className="space-y-4 text-sm">
          <p className="text-sm text-muted-foreground">{resched?.appointmentNo} · {resched ? patientNameOf(resched.patientId || resched) : ''}</p>
          <Field label="New start *">
            <Input required type="datetime-local" value={reschedAt} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setReschedAt(e.target.value)} />
          </Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => setResched(null)}>Cancel</Button>
            <Button type="submit" disabled={reschedMut.isPending}>Reschedule</Button>
          </div>
        </form>
      </Modal>

      <Modal open={Boolean(cancelTarget)} onClose={() => { setCancelTarget(null); setCancelReason(''); }} title="Cancel Appointment">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          cancelMut.mutate({ id: cancelTarget._id, status: 'Cancelled', reason: cancelReason });
        }} className="space-y-4 text-sm">
          <p className="text-sm text-muted-foreground">{cancelTarget?.appointmentNo} · {cancelTarget ? patientNameOf(cancelTarget.patientId || cancelTarget) : ''}</p>
          <Field label="Reason *">
            <Input required value={cancelReason} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCancelReason(e.target.value)} placeholder="e.g. Patient requested, machine down..." />
          </Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => { setCancelTarget(null); setCancelReason(''); }}>Keep</Button>
            <Button type="submit" variant="destructive" disabled={cancelMut.isPending}>Cancel Appointment</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  CalendarCheck, IndianRupee, Plus, UserCheck, Users, FileCheck2, ClipboardList,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { radApi } from '@/lib/api';
import {
  Modal, Field, StatCard, StatusBadge, ModalityBadge, PriorityBadge,
  errMessage, inputCls, selectCls, textareaCls, dayStart, dayEnd,
  patientNameOf, toDateTimeLocal, RAD_MODALITY_TYPES,
} from '@/components/radiology/radShared';

const READY_REPORT_STATUSES = ['Reported', 'Report Finalized', 'Report Released'];

export default function ReceptionConsole() {
  const qc = useQueryClient();
  const nav = useNavigate();
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState<any>({
    patientId: '', patientName: '', modality: 'X-Ray', bodyPart: '', clinicalHistory: '', priority: 'Routine',
  });

  const apptsQ = useQuery({
    queryKey: ['radiology', 'reception', 'appointments'],
    queryFn: () => radApi.getAppointments({ from: dayStart().toISOString(), to: dayEnd().toISOString() }),
  });
  const ordersQ = useQuery({ queryKey: ['radiology', 'reception', 'orders'], queryFn: () => radApi.getOrders({}) });

  const appointments: any[] = apptsQ.data?.appointments || [];
  const orders: any[] = ordersQ.data?.orders || [];

  const waiting = appointments.filter((a: any) => a.status === 'Arrived');
  const payPending = orders.filter((o: any) => o.status === 'Payment Pending');
  const reportsReady = orders.filter((o: any) => READY_REPORT_STATUSES.includes(o.status));
  const todaysAppts = appointments;

  const byModality: Record<string, number> = {};
  for (const a of appointments) byModality[a.modalityType || 'Unknown'] = (byModality[a.modalityType || 'Unknown'] || 0) + 1;
  const modalityCounts = Object.entries(byModality).sort((a: [string, number], b: [string, number]) => b[1] - a[1]);

  const invalidate = () => qc.invalidateQueries({ queryKey: ['radiology'] });

  const checkinMut = useMutation({
    mutationFn: (id: string) => radApi.checkinAppointment(id),
    onSuccess: () => { toast.success('Patient checked in'); invalidate(); },
    onError: (e: any) => toast.error(errMessage(e, 'Check-in failed')),
  });
  const createMut = useMutation({
    mutationFn: (b: any) => radApi.createOrder(b),
    onSuccess: () => { toast.success('Walk-in order created'); invalidate(); setShowCreate(false); setForm({ patientId: '', patientName: '', modality: 'X-Ray', bodyPart: '', clinicalHistory: '', priority: 'Routine' }); },
    onError: (e: any) => toast.error(errMessage(e, 'Failed to create order')),
  });

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Radiology Reception Console</h1>
          <p className="page-subtitle">{new Date().toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" onClick={() => nav('/radiology/scheduling')}>Scheduling</Button>
          <Button onClick={() => setShowCreate(true)}><Plus className="w-4 h-4 mr-1" /> Walk-in Order</Button>
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
        <StatCard label="Today's Appointments" value={todaysAppts.length} tone="text-foreground" />
        <StatCard label="Waiting (Arrived)" value={waiting.length} tone="text-cyan-600" />
        <StatCard label="Payment Pending" value={payPending.length} tone="text-amber-600" />
        <StatCard label="Reports Ready" value={reportsReady.length} tone="text-purple-600" onClick={() => nav('/radiology/reports')} />
        <StatCard label="No Show" value={appointments.filter((a: any) => a.status === 'No Show').length} tone="text-destructive" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-card rounded-xl border shadow-sm">
          <div className="p-4 border-b flex items-center gap-2">
            <CalendarCheck className="w-4 h-4 text-primary" />
            <h2 className="font-heading font-semibold">Today's Appointments</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs text-muted-foreground border-b">
                  <th className="p-3 font-medium">Time</th>
                  <th className="p-3 font-medium">Patient</th>
                  <th className="p-3 font-medium">Modality</th>
                  <th className="p-3 font-medium">Status</th>
                  <th className="p-3 font-medium text-right">Action</th>
                </tr>
              </thead>
              <tbody>
                {appointments.map((a: any) => (
                  <tr key={a._id} className="border-b last:border-0 hover:bg-muted/30">
                    <td className="p-3 whitespace-nowrap font-medium">
                      {new Date(a.scheduledStart).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      <p className="text-[11px] text-muted-foreground">{a.appointmentNo}</p>
                    </td>
                    <td className="p-3">{patientNameOf(a.patientId || a)}</td>
                    <td className="p-3"><ModalityBadge value={a.modalityType} /></td>
                    <td className="p-3"><StatusBadge value={a.status} /></td>
                    <td className="p-3 text-right">
                      {!['Arrived', 'Cancelled', 'No Show', 'Completed'].includes(a.status) && (
                        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => checkinMut.mutate(a._id)} disabled={checkinMut.isPending}>
                          <UserCheck className="w-3 h-3 mr-1" /> Check-in
                        </Button>
                      )}
                    </td>
                  </tr>
                ))}
                {appointments.length === 0 && (
                  <tr><td colSpan={5} className="p-10 text-center text-muted-foreground">No appointments booked for today</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <Users className="w-4 h-4 text-primary" />
              <h2 className="font-heading font-semibold">Modality-wise Bookings</h2>
            </div>
            <div className="p-4 space-y-2 text-sm">
              {modalityCounts.map(([m, c]: [string, number]) => (
                <div key={m} className="flex items-center justify-between">
                  <ModalityBadge value={m} />
                  <span className="font-semibold">{c}</span>
                </div>
              ))}
              {modalityCounts.length === 0 && <p className="text-muted-foreground">No bookings yet</p>}
            </div>
          </div>

          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <Users className="w-4 h-4 text-cyan-500" />
              <h2 className="font-heading font-semibold">Waiting List</h2>
              <span className="ml-auto text-xs text-muted-foreground">{waiting.length} arrived</span>
            </div>
            <div className="p-4 space-y-2 text-sm">
              {waiting.map((a: any) => (
                <div key={a._id} className="rounded-lg border p-2.5 flex items-center justify-between">
                  <div>
                    <p className="font-medium">{patientNameOf(a.patientId || a)}</p>
                    <p className="text-[11px] text-muted-foreground">{a.modalityType} · {a.room || a.machineId?.code || '-'}</p>
                  </div>
                  <StatusBadge value={a.status} />
                </div>
              ))}
              {waiting.length === 0 && <p className="text-muted-foreground">Nobody waiting</p>}
            </div>
          </div>

          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <IndianRupee className="w-4 h-4 text-amber-500" />
              <h2 className="font-heading font-semibold">Payments Pending</h2>
            </div>
            <div className="p-4 space-y-2 text-sm">
              {payPending.map((o: any) => (
                <div key={o._id} className="rounded-lg border p-2.5">
                  <div className="flex items-center justify-between">
                    <p className="font-medium">{o.patientName}</p>
                    <PriorityBadge value={o.priority} />
                  </div>
                  <p className="text-[11px] text-muted-foreground">{o.orderId} · {o.modality} ({o.bodyPart})</p>
                </div>
              ))}
              {payPending.length === 0 && <p className="text-muted-foreground">No orders waiting on payment</p>}
            </div>
          </div>

          <div className="bg-card rounded-xl border shadow-sm">
            <div className="p-4 border-b flex items-center gap-2">
              <FileCheck2 className="w-4 h-4 text-purple-500" />
              <h2 className="font-heading font-semibold">Reports Ready</h2>
            </div>
            <div className="p-4 space-y-2 text-sm">
              {reportsReady.slice(0, 6).map((o: any) => (
                <div key={o._id} className="flex items-center justify-between">
                  <div>
                    <p className="font-medium">{o.patientName}</p>
                    <p className="text-[11px] text-muted-foreground">{o.modality} · {o.reportNumber || o.orderId}</p>
                  </div>
                  <StatusBadge value={o.status} />
                </div>
              ))}
              {reportsReady.length === 0 && <p className="text-muted-foreground">No reports waiting for delivery</p>}
              {reportsReady.length > 0 && (
                <Button size="sm" variant="outline" className="w-full" onClick={() => nav('/radiology/reports')}>
                  <ClipboardList className="w-3.5 h-3.5 mr-1" /> Open Report Center
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>

      <Modal open={showCreate} onClose={() => setShowCreate(false)} title="Walk-in Radiology Order">
        <form onSubmit={(e: React.FormEvent) => {
          e.preventDefault();
          createMut.mutate(form);
        }} className="space-y-4 text-sm">
          <div className="grid grid-cols-2 gap-3">
            <Field label="Patient ID *"><Input required value={form.patientId} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm((f: any) => ({ ...f, patientId: e.target.value }))} placeholder="Patient user id" /></Field>
            <Field label="Patient Name *"><Input required value={form.patientName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm((f: any) => ({ ...f, patientName: e.target.value }))} /></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Modality *">
              <select required value={form.modality} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setForm((f: any) => ({ ...f, modality: e.target.value }))} className={selectCls}>
                {RAD_MODALITY_TYPES.map((m: string) => <option key={m} value={m}>{m}</option>)}
              </select>
            </Field>
            <Field label="Priority">
              <select value={form.priority} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setForm((f: any) => ({ ...f, priority: e.target.value }))} className={selectCls}>
                {['Routine', 'Urgent', 'STAT'].map((p: string) => <option key={p} value={p}>{p}</option>)}
              </select>
            </Field>
          </div>
          <Field label="Body Part *"><Input required value={form.bodyPart} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm((f: any) => ({ ...f, bodyPart: e.target.value }))} placeholder="e.g. Chest, Abdomen, Knee" /></Field>
          <Field label="Clinical History">
            <textarea className={textareaCls} value={form.clinicalHistory} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setForm((f: any) => ({ ...f, clinicalHistory: e.target.value }))} />
          </Field>
          <div className="flex gap-2 justify-end">
            <Button type="button" variant="ghost" onClick={() => setShowCreate(false)}>Cancel</Button>
            <Button type="submit" disabled={createMut.isPending}><Plus className="w-4 h-4 mr-1" /> Create Order</Button>
          </div>
        </form>
      </Modal>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { FileText, History, Printer, Send, PenLine, Search, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from '@/components/ui/sonner';
import { radApi } from '@/lib/api';
import RadiologyReportingModal from '@/components/radiology/RadiologyReportingModal';
import {
  Modal, StatusBadge, ModalityBadge, errMessage, fmtDateTime,
  patientNameOf, doctorNameOf,
} from '@/components/radiology/radShared';

const REPORT_STATUSES = ['Reported', 'Report Finalized', 'Report Released', 'Delivered'];
const TABS = ['All', 'MRI', 'X-Ray', 'CT Scan', 'Ultrasound', 'Doppler', 'Mammography', 'Other'];

export default function ReportCenter() {
  const qc = useQueryClient();
  const [tab, setTab] = useState('All');
  const [search, setSearch] = useState('');
  const [historyOrder, setHistoryOrder] = useState<any>(null);
  const [amendOrder, setAmendOrder] = useState<any>(null);
  const [printOrder, setPrintOrder] = useState<any>(null);

  const ordersQ = useQuery({ queryKey: ['radiology', 'orders', 'reports'], queryFn: () => radApi.getOrders({}) });
  const all: any[] = ordersQ.data?.orders || [];

  const reported = useMemo(() => all.filter((o: any) => REPORT_STATUSES.includes(o.status)), [all]);

  const filtered = reported.filter((o: any) => {
    const inTab = tab === 'All' || (tab === 'Other' ? !['MRI', 'X-Ray', 'CT Scan', 'Ultrasound', 'Doppler', 'Mammography'].includes(o.modality) : o.modality === tab);
    const s = search.toLowerCase();
    const inSearch = !s || [o.patientName, o.orderId, o.studyNumber, o.reportNumber, o.bodyPart].some((v: any) => String(v || '').toLowerCase().includes(s));
    return inTab && inSearch;
  });

  const invalidate = () => qc.invalidateQueries({ queryKey: ['radiology'] });

  const deliverMut = useMutation({
    mutationFn: (id: string) => radApi.deliver(id),
    onSuccess: () => { toast.success('Report delivered to patient'); invalidate(); },
    onError: (e: any) => toast.error(errMessage(e, 'Deliver failed')),
  });
  const reportMut = useMutation({
    mutationFn: ({ id, ...b }: any) => radApi.submitReport(id, b),
    onSuccess: () => { toast.success('Amended report signed'); invalidate(); setAmendOrder(null); },
    onError: (e: any) => toast.error(errMessage(e, 'Amendment failed')),
  });

  const counts: Record<string, number> = { All: reported.length };
  for (const o of reported) counts[o.modality || 'Other'] = (counts[o.modality || 'Other'] || 0) + 1;

  const handlePrint = () => {
    setPrintOrder(printOrder);
    setTimeout(() => window.print(), 120);
  };

  return (
    <div className="space-y-6">
      <div className="page-header flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h1 className="page-title">Radiology Report Center</h1>
          <p className="page-subtitle">{reported.length} signed reports · {reported.filter((o: any) => !['Delivered', 'Report Released'].includes(o.status)).length} awaiting delivery</p>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        {TABS.map((t: string) => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-3 h-9 rounded-lg text-sm font-medium ${tab === t ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/70'}`}>
            {t} ({counts[t] || 0})
          </button>
        ))}
      </div>

      <div className="relative max-w-sm">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input className="pl-10" placeholder="Search patient / report no..." value={search} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value)} />
      </div>

      <div className="bg-card rounded-xl border shadow-sm overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs text-muted-foreground border-b">
              <th className="p-3 font-medium">Patient</th>
              <th className="p-3 font-medium">Order No</th>
              <th className="p-3 font-medium">Study No</th>
              <th className="p-3 font-medium">Report No</th>
              <th className="p-3 font-medium">Modality</th>
              <th className="p-3 font-medium">Radiologist</th>
              <th className="p-3 font-medium">Status</th>
              <th className="p-3 font-medium text-right">Ver</th>
              <th className="p-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((o: any) => (
              <tr key={o._id} className="border-b last:border-0 hover:bg-muted/30">
                <td className="p-3">
                  <p className="font-medium">{patientNameOf(o.patientId || o)}</p>
                  <p className="text-[11px] text-muted-foreground">{o.bodyPart}</p>
