      expect(isCategoryEligibleForPhase('gym', 'R2')).toBe(true);
      expect(isCategoryEligibleForPhase('ivf', 'R2')).toBe(false);

      // In R4 phase:
      expect(isCategoryEligibleForPhase('ivf', 'R4')).toBe(true);
