import React, { useState, useEffect, useCallback } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import {
  Search, Filter, MapPin, CheckCircle2, Star, Clock, Phone, AlertTriangle,
  Building2, Stethoscope, Pill, ShieldCheck, HeartPulse, ExternalLink,
  ChevronRight, CalendarCheck, Home as HomeIcon, Video, SlidersHorizontal
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import UnifiedSearch from '@/components/search/UnifiedSearch';
import PublicNavbar from '@/components/PublicNavbar';
import PublicFooter from '@/components/PublicFooter';

const VERTICALS = [
  { key: '', label: 'All Services' },
  { key: 'doctor', label: 'Doctors' },
  { key: 'hospital', label: 'Hospitals' },
  { key: 'clinic', label: 'Clinics' },
  { key: 'lab', label: 'Diagnostic Labs' },
  { key: 'pharmacy', label: 'Pharmacies' },
  { key: 'transport', label: 'Ambulance / Rides' },
];

export default function SearchPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();

  const query = searchParams.get('q') || '';
  const city = searchParams.get('city') || '';

  const [vertical, setVertical] = useState(searchParams.get('vertical') || '');
  const [verifiedOnly, setVerifiedOnly] = useState(false);
  const [emergencyOnly, setEmergencyOnly] = useState(false);
  const [results, setResults] = useState<any[]>([]);
  const [taxonomy, setTaxonomy] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  const loadResults = useCallback(async () => {
    setLoading(true);
    try {
      const qParams = new URLSearchParams();
      if (query.trim()) qParams.set('q', query.trim());
      if (city && city !== 'All Cities') qParams.set('city', city);
      if (vertical) qParams.set('category', vertical);
      qParams.set('limit', '30');

      const res: any = await api.get(`/search/unified?${qParams.toString()}`);
      if (res?.success) {
        setResults(res.results || []);
        setTaxonomy(res.taxonomy || null);
      } else {
        setResults([]);
        setTaxonomy(null);
      }
    } catch {
      toast.error('Search request failed. Please check network.');
      setResults([]);
    } finally {
      setLoading(false);
    }
  }, [query, city, vertical]);

  useEffect(() => {
    loadResults();
  }, [loadResults]);

  // Client side facet filtering
  const filteredResults = results.filter((item) => {
    if (verifiedOnly && !item.verified) return false;
    if (emergencyOnly && !item.openNow && !item.emergency) return false;
    return true;
  });

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      <PublicNavbar />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 pt-24 pb-16 space-y-6">
        {/* Top Search Hero Strip */}
        <div className="bg-card border rounded-2xl p-4 sm:p-6 shadow-sm space-y-4">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
            <div>
              <h1 className="text-xl sm:text-2xl font-heading font-bold text-foreground flex items-center gap-2">
                <Search className="w-5 h-5 text-primary" />
                Find Healthcare Providers & Services
              </h1>
              <p className="text-xs text-muted-foreground mt-0.5">
                Unified discovery across clinics, hospitals, diagnostic centers, and certified doctors
              </p>
            </div>
            {city && city !== 'All Cities' && (
              <Badge variant="outline" className="w-fit text-xs gap-1 py-1 px-2.5">
                <MapPin className="w-3.5 h-3.5 text-primary" /> Location: {city}
              </Badge>
            )}
          </div>

          {/* Unified Search Input bar */}
          <UnifiedSearch
            initialQuery={query}
            initialCity={city}
            compact={true}
            onSearchSubmitted={(q, c) => {
              const nextParams = new URLSearchParams();
              if (q) nextParams.set('q', q);
              if (c) nextParams.set('city', c);
              setSearchParams(nextParams);
            }}
          />
        </div>

        {/* Emergency Alert Prompt if triggered by symptom */}
        {taxonomy?.isEmergency && (
          <div className="p-4 rounded-xl border border-destructive bg-destructive/10 text-destructive flex flex-col sm:flex-row sm:items-center justify-between gap-3" role="alert">
            <div className="flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 text-destructive shrink-0 mt-0.5" />
              <div>
                <h3 className="font-bold text-sm">Emergency Alert: Immediate Medical Care Needed</h3>
                <p className="text-xs text-foreground/80 mt-0.5">
                  {taxonomy.emergencyMessage || 'Your symptoms may indicate an acute medical emergency. Dial 108 or 112 immediately.'}
                </p>
              </div>
            </div>
            <Button size="sm" variant="destructive" className="gap-1.5 shrink-0" onClick={() => window.location.href = 'tel:108'}>
              <Phone className="w-3.5 h-3.5" /> Call 108 Ambulance
            </Button>
          </div>
        )}

        {/* Filter Strip */}
        <div className="flex items-center justify-between gap-3 flex-wrap pb-2 border-b border-border/60">
          {/* Vertical tabs */}
          <div className="flex gap-1 overflow-x-auto no-scrollbar py-1">
            {VERTICALS.map((v) => (
              <button
                key={v.key}
                type="button"
                onClick={() => setVertical(v.key)}
                className={`px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap transition-colors ${
                  vertical === v.key
                    ? 'bg-primary text-primary-foreground shadow-xs'
                    : 'bg-muted/70 text-muted-foreground hover:bg-muted hover:text-foreground'
                }`}
              >
                {v.label}
              </button>
            ))}
          </div>

          {/* Quick toggle chips */}
          <div className="flex items-center gap-2 text-xs">
            <button
              type="button"
              onClick={() => setVerifiedOnly(!verifiedOnly)}
              className={`px-2.5 py-1 rounded-md border text-xs font-medium transition-colors ${
                verifiedOnly
                  ? 'border-success bg-success/10 text-success'
                  : 'border-border text-muted-foreground hover:bg-muted'
              }`}
            >
              ✓ Verified Only
            </button>
            <button
              type="button"
              onClick={() => setEmergencyOnly(!emergencyOnly)}
              className={`px-2.5 py-1 rounded-md border text-xs font-medium transition-colors ${
                emergencyOnly
                  ? 'border-destructive bg-destructive/10 text-destructive'
                  : 'border-border text-muted-foreground hover:bg-muted'
              }`}
            >
              🚨 24x7 Emergency
            </button>
          </div>
        </div>

        {/* Results Count & Taxonomy insight */}
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <span>
            Showing <strong>{filteredResults.length}</strong> {filteredResults.length === 1 ? 'provider' : 'providers'}
            {query ? ` for "${query}"` : ''}
          </span>
          {taxonomy?.matchedSpecialty && (
            <span>
              Specialty: <strong className="text-foreground">{taxonomy.matchedSpecialty}</strong>
            </span>
          )}
        </div>

        {/* Results Grid / List */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {[1, 2, 3, 4, 5, 6].map((n) => (
              <Card key={n} className="animate-pulse">
                <CardContent className="p-5 space-y-3">
                  <div className="h-5 bg-muted rounded w-2/3" />
                  <div className="h-4 bg-muted rounded w-1/2" />
                  <div className="h-8 bg-muted rounded w-full mt-4" />
                </CardContent>
              </Card>
            ))}
          </div>
        ) : filteredResults.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredResults.map((item) => {
              const isDoc = item.vertical === 'doctor';
              const isMed = item.vertical === 'medicine';
              const detailPath = isDoc
                ? `/doctor/${item.id}`
                : isMed
                ? `/buy-medicine?q=${encodeURIComponent(item.fullName)}`
                : `/facility/${item.slug || item.id}`;

              return (
                <Card key={`${item.vertical}-${item.id}`} className="hover:shadow-md transition-all border-border/80 flex flex-col justify-between">
                  <CardContent className="p-5 space-y-3">
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0">
                        <Link to={detailPath} className="font-bold text-base text-foreground hover:text-primary transition-colors line-clamp-1">
                          {item.fullName}
                        </Link>
                        <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">
                          {[item.specialization || item.category, item.city].filter(Boolean).join(' · ')}
                        </p>
                      </div>
                      <Badge variant="outline" className="text-[10px] capitalize shrink-0">
                        {item.vertical}
                      </Badge>
                    </div>

                    {/* Address & Emergency Info */}
                    <div className="space-y-1 text-xs text-muted-foreground">
                      {item.address?.city && (
                        <p className="flex items-center gap-1.5 truncate">
                          <MapPin className="w-3.5 h-3.5 shrink-0 text-muted-foreground" />
                          {item.address.city}{item.address.area ? `, ${item.address.area}` : ''}
                        </p>
                      )}
                      {item.openNow && (
                        <p className="flex items-center gap-1.5 text-success font-medium">
                          <Clock className="w-3.5 h-3.5 shrink-0" /> Open 24/7 Emergency Service
                        </p>
                      )}
                    </div>

                    {/* Badges strip */}
                    <div className="flex flex-wrap items-center gap-1.5 text-[11px] pt-1">
                      {item.verified && (
                        <Badge variant="outline" className="text-[10px] text-success border-success/30 gap-1">
                          <CheckCircle2 className="w-2.5 h-2.5" /> Verified
                        </Badge>
                      )}
                      {item.rating > 0 && (
                        <span className="flex items-center gap-1 px-1.5 py-0.5 rounded bg-amber-500/10 text-amber-700 dark:text-amber-300 font-bold text-[10px]">
                          <Star className="w-2.5 h-2.5 fill-amber-500 text-amber-500" />
                          {item.rating.toFixed(1)}
                        </span>
                      )}
                      {item.fee && (
                        <Badge variant="secondary" className="text-[10px]">
                          ₹{item.fee} Consult
                        </Badge>
                      )}
                    </div>

                    {/* Action button */}
                    <div className="pt-2 border-t border-border/60">
                      <Button asChild size="sm" className="w-full gap-1.5 text-xs font-semibold">
                        <Link to={detailPath}>
                          View Profile & Book <ChevronRight className="w-3.5 h-3.5" />
                        </Link>
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        ) : (
          /* Zero-Results State */
          <Card className="p-12 text-center border-dashed">
            <HeartPulse className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
            <h3 className="text-base font-bold text-foreground">No Verified Providers Found</h3>
            <p className="text-xs text-muted-foreground max-w-md mx-auto mt-1 mb-5">
              We couldn't find any live providers matching "{query}" in {city || 'this region'}. Try clearing filters or submit a service request.
            </p>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setVertical('');
                setVerifiedOnly(false);
                setEmergencyOnly(false);
              }}
            >
              Reset Filters
            </Button>
          </Card>
        )}
      </main>

      <PublicFooter />
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { History, RefreshCw, ShieldAlert } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

type AccessEntry = {
  _id: string;
  createdAt?: string;
  actorId?: string;
  actorRole?: string;
  patientId?: string;
  action?: string;
  resourceType?: string;
  resourceId?: string;
  decision?: string;
  reason?: string;
  accessReason?: string;
  flagged?: boolean;
  flagReason?: string;
};

export default function AccessReview() {
  const [entries, setEntries] = useState<AccessEntry[]>([]);
  const [patientId, setPatientId] = useState('');
  const [actorId, setActorId] = useState('');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const limit = 50;

  const load = useCallback(async (nextPage = page) => {
    setLoading(true);
    try {
      const params: Record<string, string | number> = { page: nextPage, limit };
      if (patientId.trim()) params.patientId = patientId.trim();
      if (actorId.trim()) params.actorId = actorId.trim();
      const result = await api.getIamAccessLog(params);
      setEntries(result.entries || []);
      setTotal(result.total || 0);
      setPage(result.page || nextPage);
    } catch (error: any) {
      toast.error(error?.message || 'Could not load access history');
    } finally {
      setLoading(false);
    }
  }, [actorId, page, patientId]);

  useEffect(() => { void load(1); }, [load]);

  return (
    <div className="space-y-5">
      <div className="flex items-center gap-3">
        <History className="h-6 w-6 text-primary" />
        <div>
          <h1 className="text-2xl font-heading font-bold">Access Review</h1>
          <p className="text-sm text-muted-foreground">Read-only record of data access decisions and flagged activity.</p>
        </div>
      </div>

      <Card>
        <CardHeader><CardTitle className="text-base">Filter access events</CardTitle></CardHeader>
        <CardContent className="flex flex-wrap gap-3">
          <Input aria-label="Patient ID" placeholder="Patient ID" value={patientId} onChange={(e) => setPatientId(e.target.value)} className="max-w-xs" />
          <Input aria-label="Actor ID" placeholder="Admin / actor ID" value={actorId} onChange={(e) => setActorId(e.target.value)} className="max-w-xs" />
          <Button onClick={() => void load(1)} disabled={loading} className="gap-2"><RefreshCw className="h-4 w-4" />Refresh</Button>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle className="text-base">{total.toLocaleString()} access event(s)</CardTitle></CardHeader>
        <CardContent className="space-y-3">
          <div className="hidden grid-cols-[1.3fr_1fr_1fr_1fr_1fr] gap-3 border-b pb-2 text-xs font-semibold text-muted-foreground md:grid">
            <span>When / actor</span><span>Subject</span><span>Action / resource</span><span>Decision / reason</span><span>Review</span>
          </div>
          {entries.map((entry) => (
            <div key={entry._id} className="grid gap-2 rounded-lg border p-3 text-xs md:grid-cols-[1.3fr_1fr_1fr_1fr_1fr] md:gap-3">
              <div><div>{entry.createdAt ? new Date(entry.createdAt).toLocaleString() : 'Time unavailable'}</div><div className="text-muted-foreground">{entry.actorRole || 'unknown'} · {entry.actorId || 'unknown actor'}</div></div>
              <div className="break-all">{entry.patientId || 'No patient linked'}</div>
              <div><div>{entry.action || 'unknown action'}</div><div className="text-muted-foreground">{entry.resourceType || 'resource'} · {entry.resourceId || '—'}</div></div>
              <div><Badge variant={entry.decision === 'allow' ? 'outline' : 'secondary'}>{entry.decision || 'unknown'}</Badge><div className="mt-1 text-muted-foreground">{entry.accessReason || entry.reason || 'No reason supplied'}</div></div>
              <div>{entry.flagged ? <div className="flex items-start gap-1 text-destructive"><ShieldAlert className="h-4 w-4 shrink-0" /><span>{entry.flagReason || 'Flagged for review'}</span></div> : <span className="text-muted-foreground">No alert</span>}</div>
            </div>
          ))}
          {!loading && entries.length === 0 && <p className="py-8 text-center text-sm text-muted-foreground">No matching access events.</p>}
          <div className="flex items-center justify-between border-t pt-3 text-sm">
            <span className="text-muted-foreground">Page {page} · {Math.max(1, Math.ceil(total / limit))}</span>
            <div className="flex gap-2">
              <Button size="sm" variant="outline" disabled={loading || page <= 1} onClick={() => void load(page - 1)}>Previous</Button>
              <Button size="sm" variant="outline" disabled={loading || page * limit >= total} onClick={() => void load(page + 1)}>Next</Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { BrainCircuit, AlertOctagon, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

// SA-M4: every row below is a REAL event logged by the AI chat route.
// Token counts are provider estimates (chars/4) and labelled as such.
export default function AiSafety() {
  const [stats, setStats] = useState<any>(null);
  const [events, setEvents] = useState<any[]>([]);
  const [kind, setKind] = useState('all');
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [s, e] = await Promise.all([
        api.getAiSafetyStats(),
        api.getAiSafetyEvents({ kind, limit: 100 }),
      ]);
      setStats(s);
      setEvents(e.events || []);
    } catch { toast.error('Failed to load AI safety monitor'); }
    setLoading(false);
  }, [kind]);

  useEffect(() => { load(); }, [load]);

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-2xl font-heading font-bold text-foreground flex items-center gap-2">
          <BrainCircuit className="w-6 h-6 text-primary" /> AI Safety Monitor
        </h1>
        <p className="text-sm text-muted-foreground mt-1">Red-flag triggers, latency and token usage — logged live by the chat route</p>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {[
          { label: 'Requests (24h)', value: stats?.last24h ?? 0, color: '' },
          { label: 'Red flags (24h)', value: stats?.redFlags24h ?? 0, color: (stats?.redFlags24h || 0) > 0 ? 'text-destructive' : 'text-success' },
          { label: 'Avg latency (24h)', value: `${stats?.avgLatencyMs ?? 0} ms`, color: '' },
          { label: 'Tokens est. (24h)', value: Number(stats?.promptTokensEst24h || 0) + Number(stats?.replyTokensEst24h || 0), color: '' },
        ].map((s) => (
          <div key={s.label} className="bg-card rounded-xl border border-border/60 p-4 text-center">
            <p className={`text-2xl font-bold tabular-nums ${s.color || 'text-foreground'}`}>{s.value}</p>
            <p className="text-xs text-muted-foreground">{s.label}</p>
          </div>
        ))}
      </div>
      <p className="text-[11px] text-muted-foreground -mt-2">Lifetime: {stats?.total ?? 0} requests · {stats?.redFlags ?? 0} red flags · max latency {stats?.maxLatencyMs ?? 0} ms. {stats?.note}</p>

      <div className="flex gap-2 items-center">
        <span className="text-xs text-muted-foreground">Show:</span>
        {['all', 'red_flag', 'request'].map((k) => (
          <Button key={k} size="sm" variant={kind === k ? 'default' : 'outline'} onClick={() => setKind(k)}>
            {k === 'all' ? 'All' : k === 'red_flag' ? 'Red flags' : 'Requests'}
          </Button>
        ))}
      </div>

      {events.length === 0 ? (
        <Card><CardContent className="p-8 text-center text-muted-foreground text-sm">No events recorded yet — rows appear here as users chat.</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {events.map((e) => (
            <Card key={e._id || e.id}>
              <CardContent className="p-4">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-2">
                    {e.kind === 'red_flag'
                      ? <AlertOctagon className="w-4 h-4 text-destructive shrink-0" />
                      : <BrainCircuit className="w-4 h-4 text-primary shrink-0" />}
                    <div>
                      <p className="text-sm font-semibold">
                        {e.kind === 'red_flag' ? `Red flag: ${e.trigger || 'unknown trigger'}` : `Chat request · ${e.model || 'unknown model'}`}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {e.createdAt ? new Date(e.createdAt).toLocaleString('en-IN') : ''}
                        {` · ${e.latencyMs ?? 0} ms · ~${e.promptTokensEst ?? 0}+${e.replyTokensEst ?? 0} tokens (est.)`}
                      </p>
                    </div>
                  </div>
                  <Badge variant={e.kind === 'red_flag' ? 'destructive' : 'outline'} className="text-[11px] shrink-0">
                    {e.kind === 'red_flag' ? 'RED FLAG' : 'request'}
                  </Badge>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-base">Human review queue</CardTitle>
          <Button size="sm" variant="outline" className="gap-1.5 text-xs h-8" asChild>
            <Link to="/superadmin/ai-reviews">
              Open Review Workspace <ArrowRight className="w-3.5 h-3.5" />
            </Link>
          </Button>
        </CardHeader>
        <CardContent>
          <p className="text-xs text-muted-foreground">
            Review OCR extractions, clinical drafts, and flagged AI responses with human-in-the-loop verification (File 22 P2-37).
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Building2, Building, Search, Ban, Trash2, ChevronDown, ChevronRight,
  UserRound, Clock, CheckCircle, XCircle, Mail, MapPin, FileText,
  ShieldAlert, ShieldCheck, Lock, Unlock, Eye, AlertTriangle, ExternalLink,
  Layers, RefreshCw, Filter, UserCheck, AlertOctagon, UserX
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { DataGrid } from '@/components/ui/System';
import { api } from '@/lib/api';
import { toast } from '@/components/ui/sonner';

const STATUS_COLORS: Record<string, string> = {
  live: 'bg-success/10 text-success border-success/30',
  approved: 'bg-success/10 text-success border-success/30',
  under_review: 'bg-warning/10 text-warning border-warning/30',
  pending: 'bg-warning/10 text-warning border-warning/30',
  suspended: 'bg-destructive/10 text-destructive border-destructive/30',
  banned: 'bg-destructive/20 text-destructive border-destructive/50',
  rejected: 'bg-destructive/10 text-destructive border-destructive/30',
  draft: 'bg-muted text-muted-foreground border-border',
};

const PROVIDER_GROUPS = [
  { key: '', label: 'All Groups' },
  { key: 'clinical', label: 'Clinical (T1)' },
  { key: 'diagnostics', label: 'Diagnostics & Labs' },
  { key: 'pharmacy', label: 'Pharmacy & Supplies' },
  { key: 'transport', label: 'Transport & Fleet' },
  { key: 'home_service', label: 'Home Healthcare' },
  { key: 'wellness', label: 'Wellness & Fitness' },
  { key: 'professional', label: 'Professional Services' },
  { key: 'info', label: 'Info & Helplines' },
];

const SENSITIVE_KEYWORDS = ['ivf', 'fertility', 'de-addiction', 'deaddiction', 'palliative', 'hospice', 'sexual', 'cosmetic', 'transplant', 'organ', 'hiv', 'std', 'mental_health', 'psych'];

export function isSensitiveProvider(provider: any): boolean {
  if (provider?.isSensitive || provider?.sensitive) return true;
  const t = `${provider?.type || ''} ${provider?.category || ''} ${provider?.name || ''}`.toLowerCase();
  return SENSITIVE_KEYWORDS.some((kw) => t.includes(kw));
}

export function isInfoOnlyProvider(provider: any): boolean {
  return Boolean(
    provider?.isInfoOnly ||
    provider?.kind === 'info' ||
    provider?.type === 'helpline' ||
    provider?.type === 'govt_facility' ||
    provider?.type === 'info'
  );
}

const SUB_TABS = [
  { key: 'all_providers', label: 'All Providers (52 Types)', icon: Layers },
  { key: 'hospitals', label: 'Legacy Hospitals', icon: Building2 },
  { key: 'facilities', label: 'Legacy Pending Requests', icon: Building },
];

export default function AllFacilities() {
  const [subTab, setSubTab] = useState('all_providers');

  // All Providers State (Spec 08 §3)
  const [providers, setProviders] = useState<any[]>([]);
  const [providersTotal, setProvidersTotal] = useState(0);
  const [providersPage, setProvidersPage] = useState(1);
  const [providerSearch, setProviderSearch] = useState('');
  const [providerGroup, setProviderGroup] = useState('');
  const [providerStatus, setProviderStatus] = useState('all');
  const [providersLoading, setProvidersLoading] = useState(false);

  // Modals & Action State
  const [suspendModal, setSuspendModal] = useState<{ open: boolean; provider: any; reason: string; status: string }>({
    open: false, provider: null, reason: '', status: 'suspended'
  });
  const [probationModal, setProbationModal] = useState<{ open: boolean; provider: any; active: boolean; payoutHold: boolean; cap: number }>({
    open: false, provider: null, active: false, payoutHold: false, cap: 0
  });
  const [impersonateModal, setImpersonateModal] = useState<{ open: boolean; provider: any; reason: string }>({
    open: false, provider: null, reason: ''
  });
  const [strikeModal, setStrikeModal] = useState<{ open: boolean; provider: any; note: string }>({
    open: false, provider: null, note: ''
  });
  // Claim-listing review (08.md §3). Approve grants `claimedBy`; reject only
  // clears the queue entry, which is why both live here rather than one.
  const [claimModal, setClaimModal] = useState<{
    open: boolean; provider: any; action: 'approve' | 'reject'; reason: string;
  }>({ open: false, provider: null, action: 'approve', reason: '' });

  // Legacy Hospital & Facility State
  const [allHospitals, setAllHospitals] = useState<any[]>([]);
  const [hospitalSearch, setHospitalSearch] = useState('');
  const [hospitalsLoading, setHospitalsLoading] = useState(false);
  const [expandedHospitalId, setExpandedHospitalId] = useState<string | null>(null);
  const [hospitalDoctors, setHospitalDoctors] = useState<any[]>([]);
  const [doctorsLoading, setDoctorsLoading] = useState(false);
  const [pendingFacilities, setPendingFacilities] = useState<any[]>([]);
  const [facilityLoading, setFacilityLoading] = useState(false);
  const [facilityRejectingId, setFacilityRejectingId] = useState<string | null>(null);
  const [facilityRejectReason, setFacilityRejectReason] = useState('');

  // Fetch Providers (Admin endpoint with fallback)
  const fetchProviders = useCallback(async () => {
    setProvidersLoading(true);
    try {
      const q = new URLSearchParams();
      if (providerStatus && providerStatus !== 'all') q.set('status', providerStatus);
      if (providerGroup) q.set('group', providerGroup);
      if (providerSearch.trim()) q.set('q', providerSearch.trim());
      q.set('page', String(providersPage));
      q.set('limit', '25');

      const res: any = await api.get(`/providers/admin/list?${q.toString()}`).catch(async () => {
        // Fallback to public list if admin list is empty
        return await api.get(`/providers?${q.toString()}&all=1`);
      });

      const list = res?.providers || res?.data || (Array.isArray(res) ? res : []);
      setProviders(list);
      setProvidersTotal(Number(res?.total) || list.length);
    } catch {
      toast.error('Failed to load providers list');
    } finally {
      setProvidersLoading(false);
    }
  }, [providerStatus, providerGroup, providerSearch, providersPage]);

  useEffect(() => {
    if (subTab === 'all_providers') {
      fetchProviders();
    }
  }, [subTab, fetchProviders]);

  // Legacy Hospitals fetch
  useEffect(() => {
    if (subTab === 'hospitals') {
      setHospitalsLoading(true);
      api.getHospitals({})
        .then((data: any) => setAllHospitals(data?.hospitals || data?.data || (Array.isArray(data) ? data : [])))
        .catch(() => toast.error('Failed to load hospitals'))
        .finally(() => setHospitalsLoading(false));
    }
  }, [subTab]);

  // Legacy Facilities fetch
  useEffect(() => {
    if (subTab === 'facilities') {
      setFacilityLoading(true);
      api.getPendingFacilities('')
        .then((data: any) => setPendingFacilities(data?.facilities || data?.data || (Array.isArray(data) ? data : [])))
        .catch(() => toast.error('Failed to load facilities'))
        .finally(() => setFacilityLoading(false));
    }
  }, [subTab]);

  // Status transition handler (Suspend / Reinstate)
  const handleStatusTransition = async () => {
    if (!suspendModal.provider) return;
    try {
      await api.post(`/providers/${suspendModal.provider._id}/status`, {
        status: suspendModal.status,
        reason: suspendModal.reason.trim(),
      });
      toast.success(`Provider status updated to ${suspendModal.status}`);
      setSuspendModal({ open: false, provider: null, reason: '', status: 'suspended' });
      fetchProviders();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Failed to update status');
    }
  };

  // Probation toggle handler
  const handleSaveProbation = async () => {
    if (!probationModal.provider) return;
    try {
      await api.post(`/providers/${probationModal.provider._id}/probation`, {
        active: probationModal.active,
        bookingCap: Number(probationModal.cap) || 0,
        payoutHold: probationModal.payoutHold,
      });
      toast.success('Probation parameters updated');
      setProbationModal({ open: false, provider: null, active: false, payoutHold: false, cap: 0 });
      fetchProviders();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Failed to update probation');
    }
  };

  // Impersonate / View-As handler
  const handleImpersonate = async () => {
    if (!impersonateModal.provider || !impersonateModal.reason.trim()) {
      toast.error('An audited reason is required for View-As mode');
      return;
    }
    try {
      const res: any = await api.post(`/providers/${impersonateModal.provider._id}/view-as`, {
        reason: impersonateModal.reason.trim(),
      });
      toast.success(res?.message || 'Read-only View-As session authorized (30 min)');
      setImpersonateModal({ open: false, provider: null, reason: '' });
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Failed to start view-as session');
    }
  };

  // Issue Strike handler
  const handleIssueStrike = async () => {
    if (!strikeModal.provider || !strikeModal.note.trim()) {
      toast.error('A justification note is required to issue a strike');
      return;
    }
    try {
      await api.post(`/moderation/provider-${strikeModal.provider._id}/action`, {
        action: 'strike',
        note: strikeModal.note.trim(),
      }).catch(async () => {
        // Fallback to provider status suspension if direct strike action not in queue
        await api.post(`/providers/${strikeModal.provider._id}/status`, {
          status: 'suspended',
          reason: `Strike issued: ${strikeModal.note.trim()}`,
        });
      });
      toast.success('Strike recorded against provider profile');
      setStrikeModal({ open: false, provider: null, note: '' });
      fetchProviders();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Failed to issue strike');
    }
  };

  // Claim-listing decision (10.md §4.4)
  const handleClaimDecision = async () => {
    const provider = claimModal.provider;
    if (!provider) return;
    if (claimModal.action === 'reject' && !claimModal.reason.trim()) {
      toast.error('A reason is required to reject a claim');
      return;
    }
    try {
      await api.post(`/providers/${provider._id}/claim-${claimModal.action}`, {
        reason: claimModal.reason.trim(),
      });
      toast.success(
        claimModal.action === 'approve'
          ? `${provider.name} is now managed by its claimed owner`
          : 'Claim request rejected',
      );
      setClaimModal({ open: false, provider: null, action: 'approve', reason: '' });
      fetchProviders();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Failed to record the claim decision');
    }
  };

  // Legacy doctors toggle
  const toggleHospitalDoctors = async (hospitalId: string) => {
    if (expandedHospitalId === hospitalId) {
      setExpandedHospitalId(null);
      return;
    }
    setExpandedHospitalId(hospitalId);
    setDoctorsLoading(true);
    try {
      const res: any = await api.get(`/doctors?hospitalId=${hospitalId}`).catch(() => []);
      setHospitalDoctors(Array.isArray(res) ? res : res?.doctors || []);
    } catch {
      setHospitalDoctors([]);
    } finally {
      setDoctorsLoading(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground flex items-center gap-2">
            <Building2 className="w-6 h-6 text-primary" /> Provider & Facility Management Console
          </h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            Operational governance for 52 provider types across clinical, diagnostic, transport & wellness groups
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button size="sm" variant="outline" className="gap-1.5" onClick={() => fetchProviders()}>
            <RefreshCw className="w-3.5 h-3.5" /> Refresh
          </Button>
        </div>
      </div>

      {/* Sub Tabs */}
      <div className="flex gap-2 border-b border-border pb-2">
        {SUB_TABS.map((tab) => {
          const Icon = tab.icon;
          const active = subTab === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => setSubTab(tab.key)}
              className={`flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs font-semibold transition-colors ${
                active
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'bg-muted/50 text-muted-foreground hover:text-foreground hover:bg-muted'
              }`}
            >
              <Icon className="w-3.5 h-3.5" />
              {tab.label}
            </button>
          );
        })}
      </div>

      {/* ─── TAB 1: ALL PROVIDERS (52 TYPES) ─────────────────────────────── */}
      {subTab === 'all_providers' && (
        <div className="space-y-4">
          {/* Filters Bar */}
          <div className="flex flex-wrap items-center justify-between gap-3 bg-card p-3 rounded-xl border border-border">
            <div className="flex flex-wrap items-center gap-2 flex-1 min-w-[280px]">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  placeholder="Search by name, phone, city, slug..."
                  value={providerSearch}
                  onChange={(e) => setProviderSearch(e.target.value)}
                  className="pl-9 text-xs h-8"
                />
              </div>

              <select
                value={providerGroup}
                onChange={(e) => setProviderGroup(e.target.value)}
                className="text-xs bg-background border border-border rounded-lg px-2.5 h-8 text-foreground"
              >
                {PROVIDER_GROUPS.map((g) => (
                  <option key={g.key} value={g.key}>{g.label}</option>
                ))}
              </select>

              <select
                value={providerStatus}
                onChange={(e) => setProviderStatus(e.target.value)}
                className="text-xs bg-background border border-border rounded-lg px-2.5 h-8 text-foreground capitalize"
              >
                <option value="all">All Statuses</option>
                <option value="live">Live</option>
                <option value="under_review">Under Review</option>
                <option value="suspended">Suspended</option>
                <option value="banned">Banned</option>
                <option value="draft">Draft</option>
              </select>
            </div>

            <div className="text-xs text-muted-foreground">
              Total: <strong className="text-foreground">{providersTotal}</strong> providers
            </div>
          </div>

          {/* Providers Grid */}
          {providersLoading ? (
            <div className="py-16 flex justify-center">
              <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
          ) : providers.length === 0 ? (
            <div className="p-12 text-center border border-dashed rounded-xl bg-muted/20 text-muted-foreground text-sm">
              <Building className="w-10 h-10 mx-auto mb-2 opacity-40 text-primary" />
              <p className="font-semibold text-foreground">No providers found</p>
              <p className="text-xs mt-1">Try broadening your search term or status filter</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {providers.map((p) => {
                const statusChip = STATUS_COLORS[p.status] || STATUS_COLORS.draft;
                return (
                  <Card key={p._id} className="border border-border/70 hover:border-border transition-all shadow-sm">
                    <CardContent className="p-4 space-y-3">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <h3 className="text-sm font-bold text-foreground truncate">{p.name}</h3>
                          <p className="text-[11px] text-muted-foreground font-mono truncate">
                            /{p.slug || p._id} · {p.kind || 'facility'}
                          </p>
                        </div>
                        <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border uppercase ${statusChip}`}>
                          {p.status}
                        </span>
                      </div>

                      <div className="flex flex-wrap items-center gap-1.5 text-[11px]">
                        <Badge variant="outline" className="text-[10px] capitalize">
                          {p.type?.replace('_', ' ') || 'General'}
                        </Badge>
                        <Badge variant="secondary" className="text-[10px]">
                          Tier {p.tier || 'T3'}
                        </Badge>
                        {isInfoOnlyProvider(p) && (
                          <Badge className="bg-sky-500/15 text-sky-700 dark:text-sky-300 text-[10px] border-sky-500/30">
                            Info-Only · No Booking CTA
                          </Badge>
                        )}
                        {p.claimedBy && (
                          <Badge className="bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 text-[10px] border-emerald-500/30">
                            Claimed
                          </Badge>
                        )}
                        {p.claimRequest?.status === 'pending' && (
                          <Badge className="bg-amber-500/15 text-amber-700 dark:text-amber-300 text-[10px] border-amber-500/30 flex items-center gap-1">
                            <UserCheck className="w-2.5 h-2.5" /> Claim awaiting review
                          </Badge>
                        )}
                        {isSensitiveProvider(p) && (
                          <Badge className="bg-purple-500/15 text-purple-700 dark:text-purple-300 text-[10px] border-purple-500/30 flex items-center gap-1">
                            <Lock className="w-2.5 h-2.5" /> Sensitive 🔒
                          </Badge>
                        )}
                        {p.probation?.active && (
                          <Badge className="bg-amber-500/15 text-amber-700 dark:text-amber-300 text-[10px]">
                            Probation ({p.probation.bookingCap || 'Cap'} slots)
                          </Badge>
                        )}
                        {p.probation?.payoutHold && (
                          <Badge className="bg-destructive/15 text-destructive text-[10px]">
                            Payout Hold
                          </Badge>
                        )}
                      </div>

                      <div className="text-xs text-muted-foreground space-y-1 pt-1 border-t border-border/50">
                        <p className="truncate flex items-center gap-1.5">
                          <MapPin className="w-3 h-3 shrink-0 text-muted-foreground" />
                          {p.address?.city || 'No city'}{p.address?.area ? `, ${p.address.area}` : ''}
                        </p>
                        <p className="truncate flex items-center gap-1.5">
                          <Clock className="w-3 h-3 shrink-0 text-muted-foreground" />
                          Joined: {p.createdAt ? new Date(p.createdAt).toLocaleDateString('en-IN') : 'Recent'}
                        </p>
                        {(p.sourceVerifiedDate || p.lastVerifiedAt) && (
                          <p className="truncate flex items-center gap-1.5 text-sky-600 dark:text-sky-400 font-medium">
                            <CheckCircle className="w-3 h-3 shrink-0" />
                            Source verified: {new Date(p.sourceVerifiedDate || p.lastVerifiedAt).toLocaleDateString('en-IN')}
                          </p>
                        )}
                      </div>

                      {/* Action Bar */}
                      <div className="flex flex-wrap items-center gap-1.5 pt-2 border-t border-border/50">
                        {p.status === 'live' ? (
                          <Button
                            size="sm"
                            variant="outline"
                            className="h-7 text-[11px] gap-1 text-destructive border-destructive/30 hover:bg-destructive/10"
                            onClick={() => setSuspendModal({ open: true, provider: p, reason: '', status: 'suspended' })}
                          >
                            <Ban className="w-3 h-3" /> Suspend
                          </Button>
                        ) : (
                          <Button
                            size="sm"
                            variant="outline"
                            className="h-7 text-[11px] gap-1 text-success border-success/30 hover:bg-success/10"
                            onClick={() => setSuspendModal({ open: true, provider: p, reason: '', status: 'live' })}
                          >
                            <CheckCircle className="w-3 h-3" /> Reinstate
                          </Button>
                        )}

                        <Button
                          size="sm"
                          variant="outline"
                          className="h-7 text-[11px] gap-1"
                          onClick={() => setProbationModal({
                            open: true,
                            provider: p,
                            active: Boolean(p.probation?.active),
                            payoutHold: Boolean(p.probation?.payoutHold),
                            cap: p.probation?.bookingCap || 15
                          })}
                        >
                          <ShieldAlert className="w-3 h-3 text-amber-500" /> Probation
                        </Button>

                        <Button
                          size="sm"
                          variant="outline"
                          className="h-7 text-[11px] gap-1"
                          onClick={() => setImpersonateModal({ open: true, provider: p, reason: '' })}
                        >
                          <Eye className="w-3 h-3 text-blue-500" /> View-As
                        </Button>

                        {p.claimRequest?.status === 'pending' && (
                          <>
                            <Button
                              size="sm"
                              variant="outline"
                              className="h-7 text-[11px] gap-1 text-success border-success/30 hover:bg-success/10"
                              onClick={() => setClaimModal({ open: true, provider: p, action: 'approve', reason: '' })}
                            >
                              <UserCheck className="w-3 h-3" /> Approve Claim
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              className="h-7 text-[11px] gap-1 text-destructive border-destructive/30 hover:bg-destructive/10"
                              onClick={() => setClaimModal({ open: true, provider: p, action: 'reject', reason: '' })}
                            >
                              <XCircle className="w-3 h-3" /> Reject
                            </Button>
                          </>
                        )}

                        <Button
                          size="sm"
                          variant="ghost"
                          className="h-7 text-[11px] gap-1 text-muted-foreground hover:text-destructive"
                          onClick={() => setStrikeModal({ open: true, provider: p, note: '' })}
                        >
                          <AlertTriangle className="w-3 h-3" /> Strike
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* ─── TAB 2: LEGACY HOSPITALS ───────────────────────────────────────── */}
      {subTab === 'hospitals' && (
        <div className="space-y-4">
          <div className="flex items-center gap-3">
            <div className="relative flex-1 max-w-md">
