      {/* CLAIM-LISTING REVIEW (10.md §4.4) */}
      {claimModal.open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm" role="dialog" aria-modal="true">
