const PRIORITY_OPTIONS = [
  { value: 'normal', label: 'Normal', color: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' },
  { value: 'high', label: 'High', color: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400' },
  { value: 'urgent', label: 'Urgent', color: 'bg-destructive/10 text-destructive' },
];

export default function Broadcast() {
  const [broadcasts, setBroadcasts] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [title, setTitle] = useState('');
  const [message, setMessage] = useState('');
  const [priority, setPriority] = useState('normal');
  const [selectedRoles, setSelectedRoles] = useState(['all']);

  const load = async () => {
    setLoading(true);
    try {
      const res = await api.getBroadcasts({ limit: 50 });
      setBroadcasts(res?.data || res?.broadcasts || []);
    } catch { /* empty */ }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleSubmit = async (e: Unmodelled) => {
    e.preventDefault();
    if (!title.trim() || !message.trim()) return toast.error('Title and message are required');
    setSending(true);
    try {
      await api.createBroadcast({ title, message, priority, targetRoles: selectedRoles });
      toast.success('Broadcast sent successfully');
      setTitle('');
      setMessage('');
      setPriority('normal');
      setSelectedRoles(['all']);
      load();
    } catch (err: any) {
      toast.error(err?.message || 'Failed to send broadcast');
    }
    setSending(false);
  };

  const toggleRole = (role: Unmodelled) => {
    if (role === 'all') { setSelectedRoles(['all']); return; }
    const next = selectedRoles.filter(r => r !== 'all');
    if (next.includes(role)) {
      setSelectedRoles(next.filter(r => r !== role));
    } else {
      setSelectedRoles([...next, role]);
    }
  };

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground">Platform Broadcast</h1>
          <p className="text-sm text-muted-foreground mt-1">Send announcements to facilities and users across the platform</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-sm flex items-center gap-2">
            <Send className="w-4 h-4 text-primary" />
            New Broadcast
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">Title</label>
              <Input placeholder="e.g. Scheduled Maintenance - July 27" value={title} onChange={e => setTitle(e.target.value)} />
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-1.5 block">Message</label>
              <textarea
                className="w-full min-h-[100px] rounded-xl border border-input bg-background px-4 py-3 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring"
                placeholder="Type your announcement message..."
                value={message} onChange={e => setMessage(e.target.value)}
              />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Priority</label>
                <div className="flex gap-2">
                  {PRIORITY_OPTIONS.map(p => (
                    <button key={p.value} type="button" onClick={() => setPriority(p.value)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${priority === p.value ? p.color + ' ring-2 ring-ring' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      {p.label}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="text-sm font-medium text-foreground mb-1.5 block">Target Roles</label>
                <div className="flex flex-wrap gap-1.5">
                  {ROLE_OPTIONS.map(r => (
                    <button key={r.value} type="button" onClick={() => toggleRole(r.value)}
                      className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium transition-colors ${selectedRoles.includes(r.value) || (r.value === 'all' && selectedRoles.includes('all')) ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>
                      <r.icon className="w-3 h-3" />
                      {r.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
            <Button type="submit" disabled={sending} className="gap-2">
              {sending ? <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin" /> : <Send className="w-4 h-4" />}
              {sending ? 'Sending...' : 'Send Broadcast'}
            </Button>
          </form>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-sm flex items-center gap-2">
            <History className="w-4 h-4 text-primary" />
            Recent Broadcasts
          </CardTitle>
        </CardHeader>
        <CardContent>
          {broadcasts.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground text-sm">No broadcasts sent yet</div>
          ) : (
            <div className="space-y-2">
              {broadcasts.map((b, i) => (
                <div key={b._id || i} className="flex items-start gap-3 p-3 rounded-xl bg-muted/50">
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${b.type === 'system' && b.title?.includes('🔴') ? 'bg-destructive/10' : 'bg-primary/10'}`}>
                    <Megaphone className={`w-4 h-4 ${b.type === 'system' && b.title?.includes('🔴') ? 'text-destructive' : 'text-primary'}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <p className="text-sm font-medium text-foreground truncate">{b.title?.replace(/[🔴📢]/g, '').trim() || b.title}</p>
                      {b.title?.includes('🔴') && <Badge className="bg-destructive/10 text-destructive text-[10px]">Urgent</Badge>}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{b.message}</p>
                    <p className="text-[10px] text-muted-foreground/60 mt-1">{new Date(b.createdAt).toLocaleString()}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { MapPin, Plus, Search, CheckCircle, XCircle, ToggleLeft, ToggleRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { DataGrid } from '@/components/ui/System';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function Cities() {
  const [cities, setCities] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: '', state: '', isOnboarding: false });

  const load = async () => {
    setLoading(true);
    try {
      const res = await api.getCities({ search });
      setCities(res.cities || []);
    } catch { toast.error('Failed to load cities'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, [search]);

  const handleCreate = async (e: Unmodelled) => {
    e.preventDefault();
    if (!form.name.trim()) return toast.error('City name required');
    try {
      await api.createCity(form);
      toast.success('City added');
      setShowForm(false);
      setForm({ name: '', state: '', isOnboarding: false });
      load();
    } catch (err: any) { toast.error(err?.message || 'Failed to create city'); }
  };

  const handleToggle = async (city: Unmodelled) => {
    try {
      await api.updateCity(city._id, { isActive: !city.isActive });
      toast.success(city.isActive ? 'City deactivated' : 'City activated');
      load();
    } catch { toast.error('Failed to update'); }
  };

  const handleToggleOnboarding = async (city: Unmodelled) => {
    try {
      await api.updateCity(city._id, { isOnboarding: !city.isOnboarding, onboardingDate: !city.isOnboarding ? new Date() : null });
      toast.success(city.isOnboarding ? 'Onboarding closed' : 'Onboarding opened');
      load();
    } catch { toast.error('Failed to update'); }
  };

  const handleDelete = async (id: Unmodelled, name: Unmodelled) => {
    if (!confirm(`Delete ${name}?`)) return;
    try { await api.deleteCity(id); toast.success('City deleted'); load(); } catch { toast.error('Failed to delete'); }
  };

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground">Region & City Management</h1>
          <p className="text-sm text-muted-foreground mt-1">Manage cities where the platform is live, control onboarding</p>
        </div>
        <Badge variant="outline" className="gap-1.5"><MapPin className="w-3.5 h-3.5" /> {cities.length} cities</Badge>
      </div>

      <div className="flex items-center gap-3">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search cities..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <Button onClick={() => setShowForm(!showForm)} className="gap-2"><Plus className="w-4 h-4" /> Add City</Button>
      </div>

      {showForm && (
        <Card className="border-primary/30">
          <CardHeader><CardTitle className="text-sm">Add New City</CardTitle></CardHeader>
          <CardContent>
            <form onSubmit={handleCreate} className="flex gap-3 items-end">
              <div className="flex-1"><label className="text-xs font-medium mb-1 block">City Name</label><Input placeholder="e.g. Mumbai" value={form.name} onChange={e => setForm({...form, name: e.target.value})} required /></div>
              <div className="flex-1"><label className="text-xs font-medium mb-1 block">State</label><Input placeholder="e.g. Maharashtra" value={form.state} onChange={e => setForm({...form, state: e.target.value})} /></div>
              <Button type="submit">Add</Button>
            </form>
          </CardContent>
        </Card>
      )}

      <DataGrid
        columns={[
          { key: 'name', label: 'City', render: (v: Unmodelled) => <div className="flex items-center gap-2"><MapPin className="w-4 h-4 text-primary" /><span className="font-medium text-foreground">{v}</span></div> },
          { key: 'state', label: 'State', render: (v: Unmodelled) => v || '—' },
          { key: 'isActive', label: 'Status', render: (v: Unmodelled) => <Badge className={v ? 'bg-success/10 text-success' : 'bg-destructive/10 text-destructive'}>{v ? 'Live' : 'Inactive'}</Badge> },
          { key: 'isOnboarding', label: 'Onboarding', render: (v: Unmodelled, c: Unmodelled) => v ? <Badge className="bg-info/10 text-info text-xs">Open {c.onboardingDate ? `(${new Date(c.onboardingDate).toLocaleDateString()})` : ''}</Badge> : <span className="text-muted-foreground/50 text-xs">Closed</span> },
          {
            key: '_actions', label: 'Actions', sortable: false,
            render: (_v: Unmodelled, c: Unmodelled) => (
              <div className="flex items-center gap-1.5 justify-end">
                <Button variant="outline" size="sm" className="text-xs h-7 gap-1" aria-label={c.isActive ? `Deactivate ${c.name}` : `Activate ${c.name}`} onClick={() => handleToggle(c)}>
                  {c.isActive ? <XCircle className="w-3 h-3" /> : <CheckCircle className="w-3 h-3" />}
                  {c.isActive ? 'Deactivate' : 'Activate'}
                </Button>
                <Button variant="outline" size="sm" className="text-xs h-7 gap-1" aria-label={`${c.isOnboarding ? 'Close' : 'Open'} onboarding for ${c.name}`} onClick={() => handleToggleOnboarding(c)}>
                  {c.isOnboarding ? <ToggleLeft className="w-3 h-3" /> : <ToggleRight className="w-3 h-3" />}
                  {c.isOnboarding ? 'Close' : 'Open'} Onboarding
                </Button>
                <Button variant="outline" size="sm" className="text-xs h-7 text-destructive" onClick={() => handleDelete(c._id, c.name)}>Delete</Button>
              </div>
            ),
          },
        ]}
        rows={cities}
        rowKey="_id"
        empty="No cities configured"
        showSearch={false}
        manualPagination
      />
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ShieldAlert, Flag, CheckCircle, XCircle, AlertTriangle, Clock,
  Eye, EyeOff, MessageSquare, Building2, ShoppingBag, Calendar,
  FileText, ShieldCheck, UserX, AlertOctagon, Undo, UserCheck,
  Search, Filter, RefreshCw, ChevronRight, Scale
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

const TARGET_TYPES = [
  { key: '', label: 'All Queues', icon: Filter },
  { key: 'review', label: 'Reviews & Ratings', icon: MessageSquare },
  { key: 'provider_profile', label: 'Provider Profiles', icon: Building2 },
  { key: 'product_listing', label: 'Products & Equipment', icon: ShoppingBag },
  { key: 'event', label: 'Events & Camps', icon: Calendar },
  { key: 'article', label: 'Articles & Content', icon: FileText },
  { key: 'chat_report', label: 'Chat Reports', icon: AlertOctagon },
];

const SEVERITIES = [
  { key: '', label: 'All Severities' },
  { key: 'critical', label: 'Critical (8h SLA)', color: 'bg-destructive/15 text-destructive border-destructive/30' },
  { key: 'high', label: 'High (24h SLA)', color: 'bg-amber-500/15 text-amber-700 dark:text-amber-300 border-amber-500/30' },
  { key: 'medium', label: 'Medium (48h SLA)', color: 'bg-blue-500/15 text-blue-700 dark:text-blue-300 border-blue-500/30' },
  { key: 'low', label: 'Low (72h SLA)', color: 'bg-slate-500/15 text-slate-700 dark:text-slate-300 border-slate-500/30' },
];

const STATUSES = [
  { key: 'open', label: 'Open' },
  { key: 'in_review', label: 'In Review' },
  { key: 'appealed', label: 'Appealed' },
  { key: 'actioned', label: 'Actioned' },
  { key: 'dismissed', label: 'Dismissed' },
];

export default function ContentModeration() {
  const [items, setItems] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [targetType, setTargetType] = useState('');
  const [status, setStatus] = useState('open');
  const [severity, setSeverity] = useState('');
  const [overdueOnly, setOverdueOnly] = useState(false);
  const [selectedItem, setSelectedItem] = useState<any>(null);
  const [actionNote, setActionNote] = useState('');
  const [acting, setActing] = useState(false);
  const [unblurMedia, setUnblurMedia] = useState<Record<string, boolean>>({});

  const loadQueue = useCallback(async () => {
    setLoading(true);
    try {
      const q = new URLSearchParams();
      if (targetType) q.set('targetType', targetType);
      if (status) q.set('status', status);
      if (severity) q.set('severity', severity);
      if (overdueOnly) q.set('overdue', 'true');
      q.set('limit', '40');

      const res: any = await api.get(`/moderation?${q.toString()}`);
      setItems(Array.isArray(res?.items) ? res.items : []);
      setTotal(Number(res?.total) || 0);
    } catch {
      toast.error('Failed to load moderation items');
    } finally {
      setLoading(false);
    }
  }, [targetType, status, severity, overdueOnly]);

  useEffect(() => {
    loadQueue();
  }, [loadQueue]);

  const claimItem = async (id: string) => {
    try {
      const res: any = await api.post(`/moderation/${id}/claim`, {});
      toast.success('Item claimed for review');
      setSelectedItem(res?.item || null);
      loadQueue();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Could not claim item');
    }
  };

  const takeAction = async (action: string) => {
    if (!selectedItem) return;
    if (['remove', 'strike', 'warn_user'].includes(action) && !actionNote.trim()) {
      toast.error('A note/justification is required for this action');
      return;
    }
    setActing(true);
    try {
      const res: any = await api.post(`/moderation/${selectedItem._id}/action`, {
        action,
        note: actionNote.trim(),
      });
      if (res?.code === 'NEEDS_SECOND_REVIEWER') {
        toast.info('Action parked: awaiting confirmation by a second, different reviewer');
      } else {
        toast.success(`Action applied: ${action}`);
      }
      setActionNote('');
      setSelectedItem(null);
      loadQueue();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || e?.message || 'Action failed');
    } finally {
      setActing(false);
    }
  };

  const confirmPendingAction = async () => {
    if (!selectedItem?.pendingAction) return;
    setActing(true);
    try {
      await api.post(`/moderation/${selectedItem._id}/action`, {
        action: selectedItem.pendingAction.action,
        note: actionNote.trim() || 'Second reviewer confirmation',
      });
      toast.success('Second reviewer approval confirmed! Action applied.');
      setActionNote('');
      setSelectedItem(null);
      loadQueue();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || e?.message || 'Confirmation failed');
    } finally {
      setActing(false);
    }
  };

  const resolveAppeal = async (outcome: 'upheld' | 'overturned') => {
    if (!selectedItem) return;
    if (!actionNote.trim()) {
      toast.error('A resolution note is required to resolve this appeal');
      return;
    }
    setActing(true);
    try {
      await api.post(`/moderation/${selectedItem._id}/resolve-appeal`, {
        outcome,
        resolutionNote: actionNote.trim(),
      });
      toast.success(`Appeal ${outcome}`);
      setActionNote('');
      setSelectedItem(null);
      loadQueue();
    } catch (e: any) {
      toast.error(e?.response?.data?.message || 'Appeal resolution failed');
    } finally {
      setActing(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground flex items-center gap-2">
            <ShieldAlert className="w-6 h-6 text-primary" /> Content & UGC Moderation Console
          </h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            Operational review queue for reviews, profiles, UGC, medical claims & safety incidents ({total} items)
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button size="sm" variant="outline" className="gap-1.5" onClick={() => loadQueue()}>
            <RefreshCw className="w-3.5 h-3.5" /> Refresh
          </Button>
        </div>
      </div>

      {/* Target Type Filter Tabs */}
      <div className="flex gap-1.5 overflow-x-auto pb-1 bg-muted/50 p-1.5 rounded-xl border border-border/60">
        {TARGET_TYPES.map((t) => {
          const Icon = t.icon;
          const active = targetType === t.key;
          return (
            <button
              key={t.key}
              onClick={() => { setTargetType(t.key); setSelectedItem(null); }}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-colors ${
                active ? 'bg-background text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              <Icon className="w-3.5 h-3.5" /> {t.label}
            </button>
          );
        })}
      </div>

      {/* Filter Row */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="flex items-center gap-1 bg-muted/40 p-1 rounded-lg border border-border/60 text-xs">
          {STATUSES.map((s) => (
            <button
              key={s.key}
              onClick={() => { setStatus(s.key); setSelectedItem(null); }}
              className={`px-2.5 py-1 rounded-md font-medium transition-colors ${
                status === s.key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {s.label}
            </button>
          ))}
        </div>

        <select
          value={severity}
          onChange={(e) => setSeverity(e.target.value)}
          className="text-xs bg-background border border-border rounded-lg px-2.5 py-1.5 text-foreground focus:outline-none"
        >
          {SEVERITIES.map((sev) => (
            <option key={sev.key} value={sev.key}>{sev.label}</option>
          ))}
        </select>

        <label className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg border border-border text-xs cursor-pointer select-none">
          <input
            type="checkbox"
            checked={overdueOnly}
            onChange={(e) => setOverdueOnly(e.target.checked)}
            className="w-3.5 h-3.5 rounded text-destructive"
          />
          <Clock className="w-3 h-3 text-destructive" /> Overdue SLA Only
        </label>
      </div>

      {/* Main Workspace Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-6 items-start">
        {/* Left Column: Items Queue */}
        <div className="lg:col-span-2 space-y-3">
          {loading ? (
            <div className="py-12 flex justify-center">
              <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
          ) : items.length === 0 ? (
            <div className="p-8 text-center border border-dashed rounded-xl bg-muted/20 text-muted-foreground text-sm">
              <ShieldCheck className="w-10 h-10 mx-auto mb-2 opacity-40 text-emerald-500" />
              <p className="font-medium">Queue is clean</p>
              <p className="text-xs mt-0.5">No pending moderation items in this category</p>
            </div>
          ) : (
            items.map((item) => {
              const isSelected = selectedItem?._id === item._id;
              const isOverdue = item.slaDueAt && new Date(item.slaDueAt) < new Date() && ['open', 'in_review'].includes(item.status);
              const sevConfig = SEVERITIES.find((s) => s.key === item.severity);

              return (
                <div
                  key={item._id}
                  onClick={() => setSelectedItem(item)}
                  className={`p-3.5 rounded-xl border transition-all cursor-pointer text-left space-y-2 ${
                    isSelected
                      ? 'border-primary ring-2 ring-primary/20 bg-primary/5'
                      : 'border-border/60 bg-card hover:border-border'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <Badge variant="outline" className="text-[10px] font-mono capitalize">
                        {item.targetType.replace('_', ' ')}
                      </Badge>
                      <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${sevConfig?.color || 'bg-muted text-muted-foreground'}`}>
                        {item.severity}
                      </span>
                      {isOverdue && (
                        <Badge className="bg-destructive text-destructive-foreground text-[10px]">Overdue</Badge>
                      )}
                      {item.pendingAction && (
                        <Badge className="bg-amber-500 text-white text-[10px]">Needs 2nd Reviewer</Badge>
                      )}
                    </div>
                    <span className="text-[11px] text-muted-foreground font-mono">
                      {new Date(item.createdAt).toLocaleDateString('en-IN', { month: 'short', day: 'numeric' })}
                    </span>
                  </div>

                  <div>
                    <p className="text-xs font-semibold text-foreground line-clamp-1">
                      {item.category}: {item.reason || 'Flagged for moderation'}
                    </p>
                    <p className="text-[11px] text-muted-foreground font-mono mt-0.5">
                      Target ID: {item.targetId.slice(-8)} · Source: {item.source}
                    </p>
                  </div>

                  {item.slaDueAt && (
                    <div className="flex items-center gap-1 text-[11px] text-muted-foreground">
                      <Clock className="w-3 h-3 text-muted-foreground" />
                      SLA: {new Date(item.slaDueAt).toLocaleString('en-IN', { hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' })}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* Right Column: Review Workspace */}
        <div className="lg:col-span-3">
          {selectedItem ? (
            <Card className="border-border">
              <CardHeader className="pb-3 border-b">
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle className="text-base flex items-center gap-2">
                      <Scale className="w-4 h-4 text-primary" /> Moderation Case #{selectedItem._id.slice(-6)}
                    </CardTitle>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Category: <span className="font-semibold text-foreground capitalize">{selectedItem.category}</span> · Status: {selectedItem.status}
                    </p>
                  </div>
                  {!selectedItem.assignee && (
                    <Button size="sm" variant="outline" onClick={() => claimItem(selectedItem._id)}>
                      Claim Case
                    </Button>
                  )}
                </div>
              </CardHeader>

              <CardContent className="p-4 space-y-4">
                {/* Two-Person Approval Pending Banner */}
                {selectedItem.pendingAction && (
                  <div className="p-3 rounded-xl border border-amber-300 bg-amber-50 dark:bg-amber-500/10 text-amber-900 dark:text-amber-200 text-xs space-y-2" role="alert">
                    <div className="flex items-center gap-2 font-semibold">
                      <ShieldAlert className="w-4 h-4 text-amber-600" />
                      Two-Person Approval Required for Action: "{selectedItem.pendingAction.action.toUpperCase()}"
                    </div>
                    <p className="text-[11px]">
                      The first reviewer parked this action with note: "{selectedItem.pendingAction.note || 'No note'}".
                      A second, different reviewer must confirm before the action is enforced.
                    </p>
                    <Button
                      size="sm"
                      className="bg-amber-600 hover:bg-amber-700 text-white text-xs h-7 gap-1"
                      disabled={acting}
                      onClick={confirmPendingAction}
                    >
                      <CheckCircle className="w-3.5 h-3.5" /> Confirm As Second Reviewer
                    </Button>
                  </div>
                )}

                {/* Flagged Content Preview (with Reviewer Wellbeing Blur) */}
                <div className="p-3 rounded-xl border border-border bg-muted/30 space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                      <FileText className="w-3.5 h-3.5 text-primary" /> Flagged Content & Payload
                    </span>
                    <button
                      onClick={() => setUnblurMedia((p) => ({ ...p, [selectedItem._id]: !p[selectedItem._id] }))}
                      className="text-xs text-muted-foreground hover:text-foreground flex items-center gap-1"
                    >
                      {unblurMedia[selectedItem._id] ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                      {unblurMedia[selectedItem._id] ? 'Blur content' : 'Unblur content'}
                    </button>
                  </div>

                  <div className={`text-xs p-3 rounded-lg bg-card border transition-all ${!unblurMedia[selectedItem._id] ? 'blur-sm select-none' : ''}`}>
                    <p className="text-foreground leading-relaxed">
                      {selectedItem.reason || 'Flagged content details awaiting inspector review.'}
                    </p>
                    {selectedItem.note && (
                      <p className="text-muted-foreground mt-2 border-t pt-1.5 italic font-mono">
                        System note: {selectedItem.note}
                      </p>
                    )}
                  </div>
                  {!unblurMedia[selectedItem._id] && (
                    <p className="text-[10px] text-muted-foreground text-center">
                      Reviewer wellbeing protection: sensitive text/media is blurred by default.
                    </p>
