                )}

                {/* Canned Actions Panel */}
                <div className="space-y-3 pt-2">
                  <Input
                    value={actionNote}
                    onChange={(e) => setActionNote(e.target.value)}
                    placeholder="Moderator note / justification for audit trail (required for takedowns & strikes)…"
                    className="text-xs"
