                  <div className="flex flex-wrap gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      className="text-xs gap-1 text-emerald-600 border-emerald-300 hover:bg-emerald-50"
                      disabled={acting}
                      onClick={() => takeAction('restore')}
                    >
                      <CheckCircle className="w-3.5 h-3.5" /> Approve / Restore
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      className="text-xs gap-1 text-amber-600 border-amber-300 hover:bg-amber-50"
                      disabled={acting}
                      onClick={() => takeAction('hide')}
                    >
                      <EyeOff className="w-3.5 h-3.5" /> Hide Listing
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      className="text-xs gap-1 text-amber-700 border-amber-300 hover:bg-amber-50"
                      disabled={acting}
                      onClick={() => takeAction('shadow_hide')}
                    >
                      <EyeOff className="w-3.5 h-3.5" /> Shadow Hide
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      className="text-xs gap-1 text-destructive border-destructive/30 hover:bg-destructive/10"
                      disabled={acting}
                      onClick={() => takeAction('remove')}
                    >
                      <XCircle className="w-3.5 h-3.5" /> Remove Content
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      className="text-xs gap-1 text-blue-600 border-blue-300 hover:bg-blue-50"
                      disabled={acting}
                      onClick={() => takeAction('warn_user')}
                    >
                      <AlertTriangle className="w-3.5 h-3.5" /> Issue Warning
                    </Button>
                    <Button
                      size="sm"
                      variant="destructive"
                      className="text-xs gap-1"
                      disabled={acting}
                      onClick={() => takeAction('strike')}
                    >
                      <UserX className="w-3.5 h-3.5" /> Issue Strike (2-Person)
                    </Button>
                  </div>
                </div>

                {/* Audit & Decision Log */}
                {Array.isArray(selectedItem.actions) && selectedItem.actions.length > 0 && (
                  <div className="pt-3 border-t space-y-2">
                    <p className="text-xs font-semibold text-foreground">Decision & Action History</p>
                    <div className="space-y-1.5 max-h-36 overflow-y-auto">
                      {selectedItem.actions.map((act: any, i: number) => (
                        <div key={i} className="text-[11px] p-2 rounded bg-muted/40 border border-border/60 flex items-start justify-between">
                          <div>
                            <span className="font-semibold capitalize text-foreground">{act.action}</span>
                            {act.secondReviewer && <Badge className="ml-1.5 text-[9px] bg-amber-500">2nd Reviewer</Badge>}
                            <p className="text-muted-foreground mt-0.5">{act.note || 'No note recorded'}</p>
                          </div>
                          <span className="text-muted-foreground font-mono text-[10px]">
                            {new Date(act.at).toLocaleDateString('en-IN')}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          ) : (
            <div className="h-64 flex flex-col items-center justify-center border border-dashed rounded-xl text-muted-foreground text-sm p-6 text-center">
              <Scale className="w-10 h-10 mb-2 opacity-30 text-primary" />
              <p className="font-medium text-foreground">Select an item from the queue</p>
              <p className="text-xs text-muted-foreground mt-1 max-w-sm">
                Inspect applicant claims, verified booking flags, crisis keywords, and take audited moderation actions.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Download, Users, DollarSign, CalendarDays, Building2, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api, apiClient } from '@/lib/api';
import { getISTDateString } from '@/lib/dateUtils';
import type { Unmodelled } from '@/lib/apiTypes';

const EXPORTS = [
  { id: 'users', label: 'Users Export', icon: Users, desc: 'All platform users with role, status, contact info', endpoint: 'users' },
  { id: 'revenue', label: 'Revenue Report', icon: DollarSign, desc: 'Commission earnings, payouts, transaction ledger', endpoint: 'revenue' },
  { id: 'bookings', label: 'Bookings Report', icon: CalendarDays, desc: 'All appointments, lab bookings, pharmacy orders', endpoint: 'bookings' },
  { id: 'facilities', label: 'Facilities Report', icon: Building2, desc: 'Hospitals, clinics, labs, pharmacies with status', endpoint: 'facilities' },
  { id: 'audit', label: 'Audit Log Export', icon: FileText, desc: 'Complete audit trail for compliance', endpoint: 'audit' },
];

export default function DataExport() {
  const [dateRange, setDateRange] = useState({ from: '', to: '' });
  const [exporting, setExporting] = useState<Unmodelled>(null);

  const handleExport = async (type: Unmodelled) => {
    setExporting(type);
    try {
      const params = new URLSearchParams({ format: 'csv', ...dateRange });
      if (dateRange.from) params.set('from', dateRange.from);
      if (dateRange.to) params.set('to', dateRange.to);
      // SECURITY (P1-6): no localStorage token - apiClient attaches the
      // httpOnly session cookie (withCredentials) + CSRF header. The old
      // `Bearer ${localStorage.getItem('token')}` read a key nothing ever
      // wrote, so the header was literally `Bearer null`.
      const res = await apiClient.get(`/export/${type}?${params}`, {
        responseType: 'blob',
      });

      const blob = res.data;
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `${type}-${getISTDateString()}.csv`;
      a.click();
      URL.revokeObjectURL(a.href);
      toast.success(`${type} exported successfully`);
    } catch { toast.error('Export failed. Check backend /api/export/* endpoints.'); }
    setExporting(null);
  };

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-2xl font-heading font-bold text-foreground">Data Export & Reports</h1>
        <p className="text-sm text-muted-foreground mt-1">Export platform data as CSV for finance, legal & compliance teams</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-sm flex items-center gap-2">
            <CalendarDays className="w-4 h-4 text-primary" />
            Date Range Filter
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-3">
            <div><label className="text-xs font-medium mb-1 block">From</label><Input type="date" value={dateRange.from} onChange={e => setDateRange({...dateRange, from: e.target.value})} /></div>
            <div><label className="text-xs font-medium mb-1 block">To</label><Input type="date" value={dateRange.to} onChange={e => setDateRange({...dateRange, to: e.target.value})} /></div>
          </div>
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {EXPORTS.map(ex => (
          <Card key={ex.id}>
            <CardContent className="p-5">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center mb-3">
                <ex.icon className="w-5 h-5 text-primary" />
              </div>
              <h3 className="font-semibold text-foreground mb-1">{ex.label}</h3>
              <p className="text-xs text-muted-foreground mb-4">{ex.desc}</p>
              <Button onClick={() => handleExport(ex.id)} disabled={exporting === ex.id} className="w-full gap-2" variant="outline">
                {exporting === ex.id ? <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin" /> : <Download className="w-4 h-4" />}
                {exporting === ex.id ? 'Exporting...' : 'Export CSV'}
              </Button>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Siren, Clock, Megaphone, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { DataGrid } from '@/components/ui/System';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import ClinicalLockingAlert from '@/components/emergency/ClinicalLockingAlert';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

const ACTIVE = ['Pending', 'Assigned', 'Under Treatment'];
const SLA_TARGET_MIN = 60;

function ageMin(createdAt: Unmodelled) {
  const ms = Date.now() - new Date(createdAt).getTime();
  return Math.max(0, Math.floor(ms / 60000));
}

export default function EmergencyWarRoom() {
  const [emergencies, setEmergencies] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [severity, setSeverity] = useState('All');
  const [now, setNow] = useState(Date.now());
  const [blastTitle, setBlastTitle] = useState('');
  const [blastMsg, setBlastMsg] = useState('');
  const [blasting, setBlasting] = useState(false);
  const [lockingAlert, setLockingAlert] = useState<Unmodelled>(null);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      const data = await api.getEmergencies({});
      setEmergencies(Array.isArray(data) ? data : data?.emergencies || []);
    } catch { if (!silent) toast.error('Failed to load emergency queue'); }
    if (!silent) setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  // Live SLA clocks tick every 30s; silent list refresh every 60s.
  useEffect(() => {
    const t1 = setInterval(() => setNow(Date.now()), 30000);
    const t2 = setInterval(() => load(true), 60000);
    return () => { clearInterval(t1); clearInterval(t2); };
  }, [load]);

  // Socket: new SOS pushes refresh the board instantly.
  // Spec expansion-09: clinical alerts (code blue / lab panic / MTP) raise
  // the fullscreen locking modal (ClinicalLockingAlert) + tones.
  useEffect(() => {
    let socket: Unmodelled;
    (async () => {
      try {
        const { getSocket } = await import('@/lib/socket');
        socket = getSocket();
        if (!socket) return;
        const bump = () => load(true);
        const clinical = (kind: Unmodelled) => (payload: Unmodelled) => {
          const tone = payload?.toneType === 'lab_panic' ? 'lab_panic' : payload?.toneType === 'code_blue' ? 'code_blue' : 'siren';
          const titles: Unmodelled = {
            code_blue: payload?.patientName ? `Cardiac arrest — ${payload.patientName}` : 'Cardiac arrest',
            lab_panic: payload?.testName ? `${payload.testName}: ${payload.value}` : 'Critical lab value',
            mtp: payload?.bloodGroup ? `Pack ${payload?.units || 4} units ${payload.bloodGroup}` : 'MTP activated',
          };
          const details: Unmodelled = {
            code_blue: `Ward ${payload?.ward || '-'} · Bed ${payload?.bedId || '-'}${payload?.note ? ` · ${payload.note}` : ''}`,
            lab_panic: `${payload?.patientName || ''}${payload?.countermeasure ? ` → ${payload.countermeasure}` : ''}`,
            mtp: `Requested by ${payload?.requester || 'ER'} · Hospital ${payload?.hospitalId || ''}`,
          };
          const actions: Unmodelled = {
            code_blue: 'START RESUSCITATION TIMER',
            lab_panic: 'OPEN ORDER + COUNTERMEASURE',
            mtp: 'DISPATCH PACK 4U O-NEG',
          };
          setLockingAlert({
            alertId: payload?.alertId || `${kind}-${Date.now()}`,
            kind,
            title: titles[kind] || kind,
            detail: details[kind] || '',
            toneType: tone,
            actionLabel: actions[kind] || '',
            room: payload?.hospitalId ? `hospital:${payload.hospitalId}` : '',
          });
          toast.error(`Clinical alert: ${kind}`, {
            description: payload?.patientName || payload?.testName || payload?.bloodGroup || payload?.alertId || '',
          });
          load(true);
        };
        const onAck = (ack: Unmodelled) => {
          if (!ack?.alertId) return;
          setLockingAlert((cur: Unmodelled) => (cur && cur.alertId === ack.alertId ? null : cur));
          load(true);
        };
        socket.on('emergency_alert_critical', bump);
        socket.on('emergency_created', bump);
        socket.on('clinical:code_blue', clinical('code_blue'));
        socket.on('clinical:lab_panic', clinical('lab_panic'));
        socket.on('clinical:mtp', clinical('mtp'));
        socket.on('clinical:ack', onAck);
        socket._clinicalCleanup = () => {
          socket.off('emergency_alert_critical');
          socket.off('emergency_created');
          socket.off('clinical:code_blue');
          socket.off('clinical:lab_panic');
          socket.off('clinical:mtp');
          socket.off('clinical:ack', onAck);
        };
      } catch { /* manual refresh remains */ }
    })();
    return () => {
      try {
        if (socket?._clinicalCleanup) socket._clinicalCleanup();
        else {
          socket?.off('emergency_alert_critical');
          socket?.off('emergency_created');
        }
      } catch { /* noop */ }
    };
  }, [load]);

  const active = emergencies.filter((e) => ACTIVE.includes(e.status));
  const critical = active.filter((e) => e.severity === 'Critical');
  const breached = active.filter((e) => ageMin(e.createdAt) >= SLA_TARGET_MIN && e.status === 'Pending');
  const filtered = severity === 'All' ? active : active.filter((e) => e.severity === severity);

  const sendBlast = async () => {
    if (!blastTitle.trim() || !blastMsg.trim()) {
      toast.error('Title and message are required');
      return;
    }
    setBlasting(true);
    try {
      const res = await api.createBroadcast({
        title: blastTitle.trim(),
        message: blastMsg.trim(),
        priority: 'urgent',
        targetRoles: ['all'],
      });
      toast.success(`Disaster blast sent to ${res.recipientCount ?? 'all'} recipients`);
      setBlastTitle('');
      setBlastMsg('');
    } catch (err: any) {
      toast.error(err.message || 'Broadcast failed');
    } finally {
      setBlasting(false);
    }
  };

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-5">
      {lockingAlert ? (
        <ClinicalLockingAlert
          alert={lockingAlert}
          onAcked={() => { setLockingAlert(null); load(true); }}
          onAction={(a: Unmodelled) => { toast.success(`Action logged: ${a.actionLabel}`); }}
        />
      ) : null}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-heading font-bold text-foreground flex items-center gap-2">
            <Siren className="w-6 h-6 text-destructive" /> Emergency War Room
          </h1>
          <p className="text-sm text-muted-foreground mt-1">Live SOS queue · {SLA_TARGET_MIN}-min dispatch SLA · auto-refresh 60s</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => load()} className="gap-1.5">
          <RefreshCw className="w-3.5 h-3.5" /> Refresh
        </Button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {[
          { label: 'Active SOS', value: active.length, color: 'text-destructive' },
          { label: 'Critical', value: critical.length, color: 'text-destructive' },
          { label: 'SLA breached (Pending)', value: breached.length, color: breached.length ? 'text-destructive' : 'text-success' },
          { label: 'Total tracked', value: emergencies.length, color: '' },
        ].map((s) => (
          <div key={s.label} className="bg-card rounded-xl border border-border/60 p-4 text-center">
            <p className={`text-2xl font-bold ${s.color || 'text-foreground'}`}>{s.value}</p>
            <p className="text-xs text-muted-foreground">{s.label}</p>
          </div>
        ))}
      </div>

      <div className="flex gap-2 items-center">
        <span className="text-xs text-muted-foreground">Severity:</span>
        {['All', 'Critical', 'Serious', 'Stable'].map((s) => (
          <Button key={s} size="sm" variant={severity === s ? 'default' : 'outline'} onClick={() => setSeverity(s)}>{s}</Button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">No active emergencies{severity !== 'All' ? ` with severity ${severity}` : ''}. Board is clear.</div>
      ) : (
        // `key={now}` forces a fresh render every 30s so the SLA clocks tick;
        // the severity chips above already narrowed this list.
        <div className="overflow-x-auto rounded-xl border" key={now}>
          <DataGrid
            columns={[
              { key: 'patientName', label: 'Patient', render: (v: Unmodelled, e: Unmodelled) => <span className="font-medium">{v || 'Unknown'}{e.phone ? <span className="block text-xs text-muted-foreground">{e.phone}</span> : null}</span> },
              { key: 'condition', label: 'Condition', render: (v: Unmodelled) => <span className="text-xs text-muted-foreground max-w-xs truncate block">{v}</span> },
              { key: 'severity', label: 'Severity', render: (v: Unmodelled) => <Badge variant={v === 'Critical' ? 'destructive' : 'outline'}>{v}</Badge> },
              { key: 'status', label: 'Status', render: (v: Unmodelled, e: Unmodelled) => <span className="text-xs">{v}{e.assignedDoctorName ? ` · ${e.assignedDoctorName}` : ''}</span> },
              {
                key: '_sla', label: 'SLA clock', sortable: false,
                render: (_v: Unmodelled, e: Unmodelled) => {
                  const mins = ageMin(e.createdAt);
                  const bad = e.status === 'Pending' && mins >= SLA_TARGET_MIN;
                  return (
                    <span className={`inline-flex items-center gap-1 text-xs font-mono font-bold ${bad ? 'text-destructive' : 'text-foreground'}`}>
                      <Clock className="w-3.5 h-3.5" />{mins}m{bad ? ' · BREACH' : ''}
                    </span>
                  );
                },
              },
            ]}
            rows={filtered}
            rowKey="_id"
            empty="Board is clear."
            showSearch={false}
            manualPagination
            rowClassName={(e: Unmodelled) => (e.status === 'Pending' && ageMin(e.createdAt) >= SLA_TARGET_MIN ? 'bg-destructive/5' : '')}
          />
        </div>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Megaphone className="w-4 h-4 text-primary" /> Disaster override blast
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <p className="text-xs text-muted-foreground">Urgent-priority push to all roles (overrides quiet hours). Every blast is audit-logged.</p>
          <Input value={blastTitle} onChange={(e) => setBlastTitle(e.target.value)} placeholder="Blast title, e.g. Mass casualty — City Hospital needs O- blood" />
          <Input value={blastMsg} onChange={(e) => setBlastMsg(e.target.value)} placeholder="Message for all off-duty medical personnel" />
          <div className="flex justify-end">
            <Button onClick={sendBlast} disabled={blasting} className="bg-destructive hover:bg-destructive/90">
              {blasting ? 'Sending...' : 'Send urgent blast'}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState } from 'react';
import { DndContext, closestCenter, PointerSensor, useSensor, useSensors, type DragEndEvent } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy, useSortable, arrayMove } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import FormRenderer from '@/components/forms/FormRenderer';

/**
 * File 14 §14.1 — form builder: palette → canvas (sortable), property
 * panel, live preview, save draft + publish. framer-motion deliberately
 * unused here: dnd-kit handles drag ghosts + drop lines itself.
 */
const PALETTE = ['text', 'textarea', 'number', 'select', 'radio', 'checkbox', 'yesno', 'scale', 'date', 'signature', 'info'];

let seq = 0;
const nid = (type: string) => `${type}_${Date.now().toString(36)}_${(seq += 1)}`;

function SortableField({ field, selected, onSelect, onRemove }: any) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id: field.id });
  return (
    <div ref={setNodeRef} style={{ transform: CSS.Transform.toString(transform), transition }} className={`flex items-center gap-2 rounded-lg border p-2 text-sm ${selected ? 'border-primary' : 'border-border/50'}`}>
      <button aria-label="drag" className="cursor-grab px-1 text-muted-foreground" {...attributes} {...listeners}>⋮⋮</button>
      <span className="flex-1" onClick={() => onSelect(field.id)}><b>{field.label || field.type}</b> <span className="text-muted-foreground">· {field.type}</span></span>
      <Button size="sm" variant="ghost" onClick={() => onRemove(field.id)}>✕</Button>
    </div>
  );
}

export default function FormBuilder() {
  const [key, setKey] = useState('');
  const [title, setTitle] = useState('');
  const [fields, setFields] = useState<any[]>([]);
  const [selId, setSelId] = useState<string | null>(null);
  const [preview, setPreview] = useState(false);
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }));
  const sel = fields.find((f) => f.id === selId) || null;

  const add = (type: string) => setFields((p) => [...p, { id: nid(type), type, label: type, required: false, options: type === 'select' || type === 'radio' ? ['Option 1', 'Option 2'] : [] }]);
  const seedScores = async () => {
    try {
      const r: any = await api.seedScoreForms();
      toast.success(`Score forms: ${(r?.created || []).join(', ') || 'already present'}`);
    } catch { toast.error('Seed failed'); }
  };
  const patch = (patchObj: any) => setFields((p) => p.map((f) => (f.id === selId ? { ...f, ...patchObj } : f)));
  const onDragEnd = (e: DragEndEvent) => {
    const { active, over } = e;
    if (over && active.id !== over.id) {
      setFields((p) => {
        const from = p.findIndex((f) => f.id === active.id);
        const to = p.findIndex((f) => f.id === over.id);
        return arrayMove(p, from, to);
      });
    }
  };

  const payload = () => ({
    key, title,
    schema: { sections: [{ id: 's1', title: 'Section 1', fields }] },
    scoring: [], contexts: [],
  });

  const save = async (publish: boolean) => {
    try {
      if (!key || !title || !fields.length) { toast.error('Key, title and at least one field required'); return; }
      const r: any = await (api as any).createFormTemplate(payload());
      if (publish) await (api as any).publishFormTemplate(r.id);
      toast.success(publish ? 'Published' : `Saved (v${r.version})`);
    } catch (err: any) { toast.error(err?.message || 'Failed'); }
  };

  const template = { schema: { sections: [{ id: 's1', fields }] } };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        <h1 className="text-2xl font-heading font-bold mr-auto">Form Builder</h1>
        <Input className="w-40" placeholder="key (e.g. nursing-admit)" value={key} onChange={(e) => setKey(e.target.value)} />
        <Input className="w-56" placeholder="Title" value={title} onChange={(e) => setTitle(e.target.value)} />
        <Button variant="outline" onClick={() => setPreview(!preview)}>{preview ? 'Edit' : 'Preview'}</Button>
        <Button variant="outline" onClick={() => save(false)}>Save</Button>
        <Button onClick={() => save(true)}>Publish</Button>
        <Button variant="secondary" onClick={seedScores}>Seed NEWS2/Morse/Braden</Button>
      </div>

      {preview ? (
        <Card><CardContent className="p-4">
          <FormRenderer template={template} values={answers} onChange={setAnswers} onSubmit={() => toast.success('Preview only — publish to use live')} submitLabel="Test submit" />
        </CardContent></Card>
      ) : (
        <div className="grid md:grid-cols-[180px_1fr_240px] gap-3">
          <Card><CardHeader><CardTitle className="text-sm">Fields</CardTitle></CardHeader>
            <CardContent className="grid gap-1.5">
              {PALETTE.map((t) => <Button key={t} size="sm" variant="outline" onClick={() => add(t)}>{t}</Button>)}
            </CardContent>
          </Card>
          <Card><CardHeader><CardTitle className="text-sm">Canvas ({fields.length})</CardTitle></CardHeader>
            <CardContent>
              <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={onDragEnd}>
                <SortableContext items={fields.map((f) => f.id)} strategy={verticalListSortingStrategy}>
                  <div className="space-y-1.5">
                    {fields.map((f) => (
                      <SortableField key={f.id} field={f} selected={f.id === selId} onSelect={setSelId} onRemove={(id: string) => setFields((p) => p.filter((x) => x.id !== id))} />
                    ))}
                    {fields.length === 0 && <p className="text-sm text-muted-foreground">Add fields from the palette.</p>}
                  </div>
                </SortableContext>
              </DndContext>
            </CardContent>
          </Card>
          <Card><CardHeader><CardTitle className="text-sm">Properties</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              {!sel && <p className="text-sm text-muted-foreground">Select a field.</p>}
              {sel && (
                <>
                  <Input placeholder="Label" value={sel.label || ''} onChange={(e) => patch({ label: e.target.value })} />
                  <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={!!sel.required} onChange={(e) => patch({ required: e.target.checked })} /> Required</label>
                  {(sel.type === 'select' || sel.type === 'radio') && (
                    <Input placeholder="Options (comma separated)" value={(sel.options || []).join(', ')} onChange={(e) => patch({ options: e.target.value.split(',').map((s) => s.trim()).filter(Boolean) })} />
                  )}
                  {(sel.type === 'number' || sel.type === 'scale') && (
                    <div className="flex gap-2">
                      <Input type="number" placeholder="Min" value={sel.min ?? ''} onChange={(e) => patch({ min: e.target.value === '' ? undefined : Number(e.target.value) })} />
                      <Input type="number" placeholder="Max" value={sel.max ?? ''} onChange={(e) => patch({ max: e.target.value === '' ? undefined : Number(e.target.value) })} />
                    </div>
                  )}
                </>
              )}
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

