                  ),
                },
                { key: 'prescriptionRequired', label: 'Prescription Required', render: (v: Unmodelled) => (v ? <CheckCircle className="w-4 h-4 text-success" /> : '—') },
              ]}
              rows={filteredMeds.map((m, i) => ({ ...m, _id: m._id || `med-${i}` }))}
              rowKey="_id"
              empty="No medicines found"
              showSearch={false}
              manualPagination
            />
