import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';

interface DsrRow {
  id: string;
  _id?: string;
  userId?: string;
  type: 'access' | 'correction' | 'erasure' | 'export';
  status: 'submitted' | 'in_review' | 'verified' | 'fulfilled' | 'rejected';
  requestedAt: string;
  dueAt: string;
  overdue?: boolean;
  extensionReason?: string;
  resolutionNote?: string;
  exportRef?: string;
  fulfillmentApprovals?: Array<{ approverId: string; approvedAt: string }>;
  details?: Record<string, any>;
  verification?: {
    method: string;
    at: string;
    by: string;
  };
}

const TYPE_CONFIG: Record<string, { label: string; badgeClass: string; icon: any }> = {
  access: { label: 'Right to Access', badgeClass: 'bg-blue-500/10 text-blue-600 border-blue-500/20', icon: FileText },
  correction: { label: 'Right to Correction', badgeClass: 'bg-amber-500/10 text-amber-600 border-amber-500/20', icon: RefreshCw },
  erasure: { label: 'Right to Erasure (Forget)', badgeClass: 'bg-rose-500/10 text-rose-600 border-rose-500/20', icon: ShieldAlert },
  export: { label: 'Data Portability (Export)', badgeClass: 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20', icon: Download },
};

const STATUS_CONFIG: Record<string, { label: string; badgeClass: string }> = {
  submitted: { label: 'Submitted', badgeClass: 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300' },
  in_review: { label: 'In Review', badgeClass: 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400' },
  verified: { label: 'Identity Verified', badgeClass: 'bg-sky-500/10 text-sky-600 dark:text-sky-400' },
  fulfilled: { label: 'Fulfilled ✅', badgeClass: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' },
  rejected: { label: 'Rejected', badgeClass: 'bg-rose-500/10 text-rose-600 dark:text-rose-400' },
};

export default function SADsrQueue() {
  const [requests, setRequests] = useState<DsrRow[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('all');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  // Decision modal state
  const [selectedReq, setSelectedReq] = useState<DsrRow | null>(null);
  const [actionType, setActionType] = useState<'review' | 'verify' | 'fulfill' | 'reject' | 'extend' | null>(null);
  const [actionNote, setActionNote] = useState('');
  const [verifyMethod, setVerifyMethod] = useState('aadhaar_otp');
  const [extendReason, setExtendReason] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const fetchDsrQueue = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (activeTab === 'overdue') {
        params.set('overdue', '1');
      } else if (activeTab !== 'all') {
        params.set('status', activeTab);
      }
      params.set('page', String(page));
      params.set('limit', '25');

      const res: any = await api.get(`/admin/dsr?${params.toString()}`);
      setRequests(res?.requests || []);
      setTotal(res?.total || 0);
    } catch (err: any) {
      toast.error('Failed to load DSR compliance queue', {
        description: err?.response?.data?.message || err?.message || 'Check network / role permissions',
      });
      setRequests([]);
      setTotal(0);
    } finally {
      setLoading(false);
    }
  }, [activeTab, page]);

  useEffect(() => {
    fetchDsrQueue();
  }, [fetchDsrQueue]);

  const handleDecision = async () => {
    if (!selectedReq || !actionType) return;
    if (actionType === 'fulfill' && selectedReq.type === 'export') {
      toast.error('Identified export delivery is unavailable until the protected DPO artifact workflow is deployed');
      return;
    }
    setSubmitting(true);

    try {
      if (actionType === 'extend') {
        if (!extendReason.trim()) {
          toast.error('Audit justification reason is required for SLA extension');
          setSubmitting(false);
          return;
        }
        await api.post(`/admin/dsr/${selectedReq.id}/extend`, {
          reason: extendReason.trim(),
        });
        toast.success('DSR statutory deadline extended by 15 days');
      } else {
        const payload: any = { action: actionType };
        if (actionNote.trim()) payload.note = actionNote.trim();
        if (actionType === 'verify') payload.method = verifyMethod;
        const result: any = await api.post(`/admin/dsr/${selectedReq.id}/decision`, payload);
        toast.success(`Request status updated: ${actionType}`);
      }

      // Close modal & reload
      setActionType(null);
      setSelectedReq(null);
      setActionNote('');
      setExtendReason('');
      fetchDsrQueue();
    } catch (err: any) {
      toast.error('Action failed', {
        description: err?.response?.data?.message || err?.message || 'Check state machine rules',
      });
    } finally {
      setSubmitting(false);
    }
  };

  const getDaysRemaining = (dueAtStr: string) => {
    const diffMs = new Date(dueAtStr).getTime() - Date.now();
    const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
    return days;
  };

  const filteredRequests = requests.filter((r) => {
    if (!search.trim()) return true;
    const term = search.toLowerCase();
    return (
      r.id.toLowerCase().includes(term) ||
      r.type.toLowerCase().includes(term) ||
      r.status.toLowerCase().includes(term)
    );
  });

  return (
    <div className="space-y-6 max-w-7xl mx-auto px-4 py-6">
      {/* Top Banner */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b pb-5">
        <div>
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-primary/10 rounded-lg text-primary">
              <ShieldCheck className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2">
                DPDP Act 2023 · Data-Subject Requests (DSR)
              </h1>
              <p className="text-sm text-muted-foreground">
                Digital Personal Data Protection Act compliance console · Statutory 30-day SLA with audit logs
              </p>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2.5">
          <Badge variant="outline" className="px-3 py-1.5 bg-emerald-500/10 text-emerald-600 border-emerald-500/20 text-xs font-medium">
            DPO Gate Active
          </Badge>
          <Button variant="outline" size="sm" onClick={() => fetchDsrQueue()} disabled={loading} className="gap-1.5">
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} /> Refresh
          </Button>
        </div>
      </div>

      {/* KPI Quick Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card className="shadow-xs">
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground font-medium">Total DSR Queue</p>
            <p className="text-2xl font-bold mt-1">{total}</p>
            <p className="text-[11px] text-muted-foreground mt-0.5">All registered citizen requests</p>
          </CardContent>
        </Card>
        <Card className="shadow-xs border-amber-500/30 bg-amber-50/20 dark:bg-amber-950/10">
          <CardContent className="p-4">
            <p className="text-xs text-amber-600 dark:text-amber-400 font-medium flex items-center gap-1">
              <Clock className="w-3.5 h-3.5" /> In-Flight SLA
            </p>
            <p className="text-2xl font-bold mt-1 text-amber-700 dark:text-amber-300">
              {requests.filter((r) => ['submitted', 'in_review', 'verified'].includes(r.status)).length}
            </p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Active countdown clock</p>
          </CardContent>
        </Card>
        <Card className="shadow-xs border-rose-500/30 bg-rose-50/20 dark:bg-rose-950/10">
          <CardContent className="p-4">
            <p className="text-xs text-rose-600 dark:text-rose-400 font-medium flex items-center gap-1">
              <AlertTriangle className="w-3.5 h-3.5" /> Overdue Statutory
            </p>
            <p className="text-2xl font-bold mt-1 text-rose-700 dark:text-rose-300">
              {requests.filter((r) => r.overdue).length}
            </p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Urgent compliance escalation</p>
          </CardContent>
        </Card>
        <Card className="shadow-xs border-emerald-500/30 bg-emerald-50/20 dark:bg-emerald-950/10">
          <CardContent className="p-4">
            <p className="text-xs text-emerald-600 dark:text-emerald-400 font-medium flex items-center gap-1">
              <CheckCircle2 className="w-3.5 h-3.5" /> Fulfilled & Closed
            </p>
            <p className="text-2xl font-bold mt-1 text-emerald-700 dark:text-emerald-300">
              {requests.filter((r) => r.status === 'fulfilled').length}
            </p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Right executed with cryptographic audit</p>
          </CardContent>
        </Card>
      </div>

      {/* Filter Tabs & Search Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        <div className="flex flex-wrap gap-1.5 p-1 bg-muted/60 rounded-lg">
          {[
            { key: 'all', label: 'All Requests' },
            { key: 'submitted', label: 'Submitted' },
            { key: 'in_review', label: 'In Review' },
            { key: 'verified', label: 'Verified' },
            { key: 'overdue', label: 'Overdue ⚠️' },
            { key: 'fulfilled', label: 'Fulfilled' },
            { key: 'rejected', label: 'Rejected' },
          ].map((tab) => (
            <button
              key={tab.key}
              onClick={() => { setActiveTab(tab.key); setPage(1); }}
              className={`px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${
                activeTab === tab.key
                  ? 'bg-background text-foreground shadow-xs'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="relative w-full sm:w-64">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by ID or type..."
            className="pl-9 h-9 text-xs"
          />
        </div>
      </div>

      {/* Main Table / Card List */}
      <div className="border rounded-xl overflow-hidden bg-card shadow-xs">
        {loading ? (
          <div className="py-16 text-center space-y-3">
            <RefreshCw className="w-6 h-6 animate-spin mx-auto text-primary" />
            <p className="text-sm text-muted-foreground">Loading DPDP statutory queue...</p>
          </div>
        ) : filteredRequests.length === 0 ? (
          <div className="py-16 text-center space-y-2">
            <ShieldCheck className="w-10 h-10 text-muted-foreground/50 mx-auto" />
            <p className="text-base font-semibold">No requests in this view</p>
            <p className="text-xs text-muted-foreground">All citizen data protection requests are settled.</p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {filteredRequests.map((req) => {
              const typeCfg = TYPE_CONFIG[req.type] || { label: req.type, badgeClass: 'bg-muted text-foreground', icon: FileText };
              const statusCfg = STATUS_CONFIG[req.status] || { label: req.status, badgeClass: 'bg-muted text-foreground' };
              const daysLeft = getDaysRemaining(req.dueAt);
              const isOpen = ['submitted', 'in_review', 'verified'].includes(req.status);

              return (
                <div key={req.id} className="p-4 hover:bg-muted/30 transition-colors flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div className="space-y-2 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-mono text-xs font-semibold text-foreground/80 bg-muted px-2 py-0.5 rounded">
                        #{req.id.slice(-8).toUpperCase()}
                      </span>
                      <Badge variant="outline" className={`text-xs gap-1 py-0.5 ${typeCfg.badgeClass}`}>
                        <typeCfg.icon className="w-3 h-3" /> {typeCfg.label}
                      </Badge>
                      <Badge variant="outline" className={`text-xs ${statusCfg.badgeClass}`}>
                        {statusCfg.label}
                      </Badge>
                      {req.overdue && (
                        <Badge variant="destructive" className="text-xs animate-pulse">
                          Overdue SLA!
                        </Badge>
                      )}
                      {req.extensionReason && (
                        <Badge variant="outline" className="text-[10px] bg-purple-500/10 text-purple-600 border-purple-500/20">
                          +15d Extension Applied
                        </Badge>
                      )}
                    </div>

                    <div className="text-xs text-muted-foreground flex flex-wrap items-center gap-x-4 gap-y-1">
                      <span>Submitted: {new Date(req.requestedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                      <span className={`font-medium ${isOpen && daysLeft <= 5 ? 'text-destructive' : ''}`}>
                        SLA Due: {new Date(req.dueAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}
                        {isOpen && ` (${daysLeft > 0 ? `${daysLeft} days left` : `${Math.abs(daysLeft)} days overdue`})`}
                      </span>
                      {req.verification && (
                        <span className="text-sky-600 dark:text-sky-400">
                          Verified via {req.verification.method} on {new Date(req.verification.at).toLocaleDateString()}
                        </span>
                      )}
                  {req.type === 'export' && !!req.fulfillmentApprovals?.length && (
                    <span className="text-amber-700 dark:text-amber-400">
                      Identified export approvals: {req.fulfillmentApprovals.length}/2
                    </span>
                  )}
                    </div>

                    {req.details && (
                      <p className="text-xs bg-muted/40 p-2 rounded-md font-sans text-foreground/80">
                        {req.details.reason || JSON.stringify(req.details)}
                      </p>
                    )}

                    {req.resolutionNote && (
                      <p className="text-xs text-muted-foreground italic">
                        Resolution Note: &quot;{req.resolutionNote}&quot;
                      </p>
                    )}
                  </div>

                  {/* Actions Column */}
                  <div className="flex items-center gap-2 flex-wrap md:flex-nowrap justify-end">
                    {req.status === 'submitted' && (
                      <>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => { setSelectedReq(req); setActionType('review'); }}
                          className="text-xs h-8"
                        >
                          Mark In-Review
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => { setSelectedReq(req); setActionType('reject'); }}
                          className="text-xs h-8"
                        >
                          Reject
                        </Button>
                      </>
                    )}

                    {req.status === 'in_review' && (
                      <>
                        <Button
                          size="sm"
                          variant="default"
                          onClick={() => { setSelectedReq(req); setActionType('verify'); }}
                          className="text-xs h-8 bg-sky-600 hover:bg-sky-700 text-white gap-1"
                        >
                          <ShieldCheck className="w-3.5 h-3.5" /> Verify Identity
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => { setSelectedReq(req); setActionType('reject'); }}
                          className="text-xs h-8"
                        >
                          Reject
                        </Button>
                      </>
                    )}

                    {req.status === 'verified' && (
                      <>
                        <Button
                          size="sm"
                          variant="default"
                          onClick={() => { setSelectedReq(req); setActionType('fulfill'); }}
                          className="text-xs h-8 bg-emerald-600 hover:bg-emerald-700 text-white gap-1"
                        >
                          <CheckCircle2 className="w-3.5 h-3.5" /> Fulfill Right
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => { setSelectedReq(req); setActionType('reject'); }}
                          className="text-xs h-8"
                        >
                          Reject
                        </Button>
                      </>
                    )}

                    {isOpen && !req.extensionReason && (
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => { setSelectedReq(req); setActionType('extend'); }}
                        className="text-xs h-8 text-muted-foreground hover:text-foreground"
                      >
                        Extend +15d
                      </Button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Decision Dialog Modal */}
      <Dialog open={Boolean(selectedReq && actionType)} onOpenChange={(open) => { if (!open) setActionType(null); }}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              {actionType === 'verify' && <ShieldCheck className="w-5 h-5 text-sky-600" />}
              {actionType === 'fulfill' && <CheckCircle2 className="w-5 h-5 text-emerald-600" />}
              {actionType === 'reject' && <XCircle className="w-5 h-5 text-rose-600" />}
              {actionType === 'extend' && <Clock className="w-5 h-5 text-purple-600" />}
              {actionType === 'review' && <RefreshCw className="w-5 h-5 text-indigo-600" />}
              <span>
                {actionType === 'verify' && 'Verify Citizen Identity'}
                {actionType === 'fulfill' && 'Fulfill Data-Subject Right'}
                {actionType === 'reject' && 'Reject Data-Subject Request'}
                {actionType === 'extend' && 'Extend Statutory SLA (+15 Days)'}
                {actionType === 'review' && 'Assign to Active Legal Review'}
              </span>
            </DialogTitle>
            <DialogDescription>
              Request #{selectedReq?.id?.slice(-8).toUpperCase()} · DPDP Act 2023 Sec 12 statutory flow
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            {actionType === 'verify' && (
              <div className="space-y-2">
                <label className="text-xs font-semibold text-foreground">Verification Method</label>
                <Select value={verifyMethod} onValueChange={setVerifyMethod}>
                  <SelectTrigger className="text-xs">
                    <SelectValue placeholder="Select method" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="email_otp">Primary Registered Email OTP</SelectItem>
                    <SelectItem value="sms_otp">Primary Registered Mobile OTP</SelectItem>
                    <SelectItem value="in_person">In-person identity check</SelectItem>
                    <SelectItem value="manual">Manual verification record</SelectItem>
                  </SelectContent>
                </Select>
                <p className="text-[11px] text-muted-foreground">
                  DPDP compliance mandates verifying applicant identity before releasing personal data or erasing records.
                </p>
              </div>
            )}

            {actionType === 'fulfill' && selectedReq?.type === 'export' && (
              <p className="rounded-md border border-amber-300 bg-amber-50 p-3 text-xs text-amber-900">
                Identified export fulfillment is disabled until private artifact storage, de-identification/watermark checks, secure delivery, and expiry purge are deployed.
              </p>
            )}

            {actionType === 'extend' && (
              <div className="space-y-2">
                <label className="text-xs font-semibold text-foreground">Legal Grounds for SLA Extension *</label>
                <Textarea
                  value={extendReason}
                  onChange={(e) => setExtendReason(e.target.value)}
                  placeholder="Explain complex multi-tenant data retrieval, hospital clinical record hold, etc..."
                  className="text-xs min-h-[80px]"
                />
                <p className="text-[11px] text-muted-foreground">
                  Extension is recorded in compliance audit log and communicated to the data principal.
                </p>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-xs font-semibold text-foreground">
                {actionType === 'reject' ? 'Mandatory Rejection Ground *' : 'Resolution / Audit Note (Optional)'}
              </label>
              <Textarea
                value={actionNote}
                onChange={(e) => setActionNote(e.target.value)}
                placeholder={
                  actionType === 'reject'
                    ? 'State legal exception (e.g., active legal proceeding, statutory clinical record retention)...'
                    : 'Add reviewer observations for compliance auditor...'
                }
                className="text-xs min-h-[70px]"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" size="sm" onClick={() => setActionType(null)} disabled={submitting}>
              Cancel
            </Button>
            <Button
              size="sm"
              onClick={handleDecision}
              disabled={submitting}
              className={
                actionType === 'reject'
                  ? 'bg-destructive hover:bg-destructive/90 text-destructive-foreground'
                  : 'bg-primary hover:bg-primary/90 text-primary-foreground'
              }
            >
              {submitting ? 'Recording...' : 'Confirm Decision'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { ShieldAlert, MonitorSmartphone, KeyRound, CheckCircle2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { DataGrid } from '@/components/ui/System';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { userFacingError } from '@/lib/errorCopy';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

// FE-B-05: the superadmin console is the one place where a raw server string is
// most tempting to keep — an operator debugging needs detail. But this page
// renders into toasts that are also screenshot into tickets, and the console is
// reachable by support staff on a shared screen. `userFacingError` still lets a
// 4xx show the server's (human-written) message while never echoing a 5xx.
const serverMsg = (err: Unmodelled, fallback: Unmodelled) => userFacingError(err, { fallback });

// SA-M5: active sessions (kill switch) + payout four-eyes queue + 2FA enrolment readout.
export default function Security() {
  const [sessions, setSessions] = useState<ApiRow[]>([]);
  const [admins, setAdmins] = useState<ApiRow[]>([]);
  const [payouts, setPayouts] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [s, a, p] = await Promise.all([
        api.getAdminSessions().catch(() => ({ sessions: [] })),
        api.get2faStatus().catch(() => ({ admins: [] })),
        api.getPayouts({ limit: 50 }).catch(() => ({ payouts: [] })),
      ]);
      setSessions(s.sessions || []);
      setAdmins(a.admins || []);
      setPayouts((p.payouts || []).filter((x: Unmodelled) => x.status === 'pending'));
    } catch { toast.error('Failed to load security console'); }
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const kill = async (id: Unmodelled, email: Unmodelled) => {
    if (!confirm(`Revoke this session (${email || 'unknown'})? The admin will be signed out on that device.`)) return;
    try {
      await api.killAdminSession(id);
      toast.success('Session revoked');
      load();
    } catch (err: any) { toast.error(serverMsg(err, 'Revoke failed')); }
  };

  const approve = async (id: Unmodelled) => {
    try {
      await api.approvePayout(id);
      toast.success('Approval recorded');
      load();
    } catch (err: any) { toast.error(serverMsg(err, 'Approve failed')); }
  };

  const pay = async (p: Unmodelled) => {
    const distinct = new Set((p.approvals || []).map((a: Unmodelled) => String(a.adminId))).size;
    if ((p.netPayout || 0) >= 100000 && distinct < 2) {
      toast.error(`Four-eyes rule: ${distinct}/2 distinct approvals required before paying ₹${Number(p.netPayout).toLocaleString('en-IN')}`);
      return;
    }
    if (!confirm(`Mark ₹${Number(p.netPayout).toLocaleString('en-IN')} to ${p.facilityName} as paid?`)) return;
    try {
      await api.markPayoutPaid(p._id, { transactionRef: `TXN-${crypto.randomUUID()}` });
      toast.success('Payout marked as paid');
      load();
    } catch (err: any) { toast.error(serverMsg(err, 'Pay failed')); load(); }
  };

  const reset2fa = async (u: Unmodelled) => {
    if (!confirm(`Reset 2FA for ${u.name || u.email}? They must re-enrol on next login.`)) return;
    try {
      await api.reset2fa(u.id);
      toast.success('2FA reset — re-enrolment required');
      load();
    } catch (err: any) { toast.error(serverMsg(err, 'Reset failed')); }
  };

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  const bigTickets = payouts.filter((p) => (p.netPayout || 0) >= 100000);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-heading font-bold text-foreground flex items-center gap-2">
          <ShieldAlert className="w-6 h-6 text-primary" /> Security Console
        </h1>
        <p className="text-sm text-muted-foreground mt-1">Live sessions, four-eyes payouts (≥ ₹1,00,000) and 2FA enrolment</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-warning" /> Dual-approval queue ({bigTickets.length} need 2 admins)
          </CardTitle>
        </CardHeader>
        <CardContent>
          {payouts.length === 0 ? (
            <p className="text-sm text-muted-foreground">No pending payouts.</p>
          ) : (
            <div className="space-y-3">
              {payouts.map((p) => {
                const distinct = new Set((p.approvals || []).map((a: Unmodelled) => String(a.adminId))).size;
                const needsFourEyes = (p.netPayout || 0) >= 100000;
                return (
                  <div key={p._id} className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 rounded-xl border p-3">
                    <div>
                      <p className="font-semibold text-sm">{p.facilityName} · <span className="tabular-nums">₹{Number(p.netPayout || 0).toLocaleString('en-IN')}</span></p>
                      <p className="text-xs text-muted-foreground">
                        {needsFourEyes ? `${distinct}/2 approvals` : 'Single approval suffices (< ₹1L)'}
                        {(p.approvals || []).length > 0 && ` · by ${(p.approvals || []).map((a: Unmodelled) => a.adminName || 'admin').join(', ')}`}
                      </p>
                    </div>
                    <div className="flex gap-2 shrink-0">
                      <Button size="sm" variant="outline" onClick={() => approve(p._id)}>Approve</Button>
                      <Button size="sm" className="bg-success hover:bg-success/90" onClick={() => pay(p)}>Mark Paid</Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <MonitorSmartphone className="w-4 h-4 text-primary" /> Active sessions ({sessions.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          {sessions.length === 0 ? (
            <p className="text-sm text-muted-foreground">No unexpired refresh-token sessions.</p>
          ) : (
            <DataGrid
              columns={[
                {
                  key: 'name', label: 'Admin',
                  render: (v: Unmodelled, s: Unmodelled) => <span className="font-medium">{v || '—'}<span className="block text-xs text-muted-foreground">{s.email}</span></span>,
                },
                { key: 'role', label: 'Role', render: (v: Unmodelled) => <span className="text-xs">{v}</span> },
                { key: 'createdAt', label: 'Created', render: (v: Unmodelled) => <span className="text-xs text-muted-foreground">{v ? new Date(v).toLocaleString('en-IN') : '—'}</span> },
                { key: 'expiresAt', label: 'Expires', render: (v: Unmodelled) => <span className="text-xs text-muted-foreground">{v ? new Date(v).toLocaleString('en-IN') : '—'}</span> },
                {
                  key: '_actions', label: 'Action', sortable: false,
                  render: (_v: Unmodelled, s: Unmodelled) => <Button size="sm" variant="destructive" onClick={() => kill(s.id, s.email)}>Kill session</Button>,
                },
              ]}
              rows={sessions}
              rowKey="id"
              empty="No unexpired refresh-token sessions."
              showSearch={false}
              manualPagination
            />
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <KeyRound className="w-4 h-4 text-primary" /> Superadmin 2FA enrolment
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {admins.map((a) => (
              <div key={a.id} className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 rounded-xl border p-3">
                <div>
                  <p className="font-semibold text-sm">{a.name || a.email}</p>
                  <p className="text-xs text-muted-foreground">{a.email}</p>
                </div>
                <div className="flex gap-2 items-center shrink-0">
                  <Badge variant={a.twoFactorEnabled ? 'default' : 'destructive'} className="text-[11px]">
                    {a.twoFactorEnabled ? '2FA ON' : '2FA OFF'}
                  </Badge>
                  {a.twoFactorEnabled && (
                    <Button size="sm" variant="outline" onClick={() => reset2fa(a)}>Reset 2FA</Button>
                  )}
                </div>
              </div>
            ))}
            {admins.length === 0 && <p className="text-sm text-muted-foreground">No superadmin accounts found.</p>}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Headset, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

function SupportTicketsTab() {
  const [tickets, setTickets] = useState<ApiRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('All');
  const [search, setSearch] = useState('');
  const [stats, setStats] = useState<Unmodelled>(null);
  const [selected, setSelected] = useState<Unmodelled>(null);
  const [reply, setReply] = useState('');
  const { user } = useAuth();
  const [assistCode, setAssistCode] = useState('');
  const [assistReason, setAssistReason] = useState('');
  const [assistFields, setAssistFields] = useState<string[]>(['phone']);
  const [revealedContact, setRevealedContact] = useState<Unmodelled>(null);
  const isL2 = user?.role === 'support_l2';
  const isSuperAdmin = user?.role === 'superadmin' || user?.role === 'super_admin';

  const verifyAssistCode = async () => {
    if (assistReason.trim().length < 20) return toast.error('Enter a specific reason (at least 20 characters)');
    try {
      await api.verifySupportAssist(selected._id, { code: assistCode, reason: assistReason, fields: assistFields });
      const result = await api.getSupportAssistContact(selected._id);
      setRevealedContact(result.fields);
      toast.success('Patient-authorized contact details loaded; session expires in 15 minutes.');
    } catch (error: Unmodelled) { toast.error(error?.response?.data?.message || 'Could not verify consent'); }
  };

  useEffect(() => {
    let socket: Unmodelled;
    (async () => {
      try {
        const { getSocket } = await import('@/lib/socket');
        socket = getSocket();
        const onNew = (t: Unmodelled) => { setTickets((prev) => [t, ...prev]); toast.info(`New Support Ticket #${t.ticketNumber || String(t._id).slice(-6)} received`); };
        const onMsg = (p: Unmodelled) => {
          if (selected?._id === p.ticketId && isL2 && revealedContact) {
            setSelected((prev: Unmodelled) => ({ ...prev, messages: [...(prev.messages || []), p.message] }));
          }
        };
        socket?.on('support_ticket_created', onNew);
        socket?.on('support_message_received', onMsg);
      } catch {}
    })();
    return () => { socket?.off('support_ticket_created'); socket?.off('support_message_received'); };
  }, [selected?._id, isL2, revealedContact]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [res, s] = await Promise.all([api.getSupportTickets({}), user?.role === 'support_l2' ? api.getTicketStats() : Promise.resolve(null)]);
      setTickets(res.tickets || []);
      setStats(s);
    } catch { toast.error('Failed to load support tickets'); }
    setLoading(false);
  }, [user?.role]);

  useEffect(() => { load(); }, [load]);

  const handleReply = async () => {
    if (!reply.trim()) return;
    try {
      await api.addTicketMessage(selected._id, { message: reply });
      setReply('');
      const detail = await api.getSupportTicket(selected._id);
      setSelected(detail.ticket);
    } catch { toast.error('Failed to send reply'); }
  };

  if (loading) return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>;

  return (
    <div className="space-y-5">
      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {[
            { label: 'Total', value: stats.total, color: '' },
            { label: 'Open', value: stats.open, color: 'text-warning' },
            { label: 'In Progress', value: stats.inProgress, color: 'text-info' },
            { label: 'Resolved', value: stats.resolved, color: 'text-success' },
            { label: 'Urgent', value: stats.urgent, color: 'text-destructive' },
          ].map(s => (
            <div key={s.label} className="bg-card rounded-xl border border-border/60 p-4 text-center">
              <p className={`text-2xl font-bold ${s.color || 'text-foreground'}`}>{s.value}</p>
              <p className="text-xs text-muted-foreground">{s.label}</p>
            </div>
          ))}
        </div>
      )}
      <div className="flex gap-2 flex-wrap">
        {['All', 'Open', 'In Progress', 'Waiting on User', 'Resolved', 'Closed'].map(f => (
          <button key={f} onClick={() => setFilter(f)}
            className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${filter === f ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-muted/80'}`}>{f} ({f === 'All' ? tickets.length : tickets.filter(t => t.status === f).length})</button>
        ))}
      </div>
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search tickets..." className="pl-10" />
      </div>
      {tickets.filter(t => filter === 'All' || t.status === filter).filter(t => !search || t.ticketId?.includes(search)).length === 0 ? (
        <div className="text-center py-16 bg-card rounded-2xl border border-dashed">
          <Headset className="w-12 h-12 mx-auto text-muted-foreground/30 mb-3" />
          <p className="text-muted-foreground">No tickets found</p>
        </div>
      ) : (
        <div className="space-y-3">
          {tickets.filter(t => filter === 'All' || t.status === filter).filter(t => !search || t.ticketId?.includes(search)).map((t, i) => (
            <motion.div key={t._id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
              className="bg-card rounded-xl border border-border/60 p-4 hover:shadow-md transition-all cursor-pointer" onClick={async () => { try { const detail = await api.getSupportTicket(t._id); setSelected(detail.ticket); setAssistCode(''); setAssistReason(''); setRevealedContact(null); setReply(''); } catch (error: Unmodelled) { toast.error(error?.response?.data?.message || 'Could not open ticket'); } }}>
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-medium text-foreground text-sm">#{t.ticketId}</span>
                    <Badge variant="outline" className="text-[10px]">{t.category}</Badge>
                    <Badge className={t.priority === 'Urgent' ? 'bg-destructive/10 text-destructive' : 'bg-warning/10 text-warning'}>{t.priority}</Badge>
                  </div>
                  <p className="text-sm font-medium text-foreground">Support request</p>
                  <p className="text-xs text-muted-foreground">Customer</p>
                </div>
                <Badge className={t.status === 'Resolved' || t.status === 'Closed' ? 'bg-success/10 text-success' : t.status === 'In Progress' ? 'bg-info/10 text-info' : t.status === 'Waiting on User' ? 'bg-warning/10 text-warning' : 'bg-muted-foreground/10 text-muted-foreground'}>{t.status}</Badge>
              </div>
            </motion.div>
          ))}
        </div>
      )}
      {selected && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={() => setSelected(null)}>
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}
            className="bg-card rounded-2xl border border-border w-full max-w-2xl max-h-[90vh] overflow-y-auto p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-heading text-lg font-bold">#{selected.ticketId}</h3>
              <Badge className={selected.status === 'Resolved' || selected.status === 'Closed' ? 'bg-success/10 text-success' : 'bg-warning/10 text-warning'}>{selected.status}</Badge>
            </div>
            {isL2 ? <div className="p-4 bg-muted/20 rounded-xl mb-4">
              <p className="font-medium text-foreground">{selected.subject}</p>
              <p className="text-sm text-muted-foreground mt-2">{selected.description}</p>
              <p className="text-xs text-muted-foreground mt-2">From: {selected.raisedByName} | {selected.category}</p>
            </div> : <div className="p-4 bg-muted/20 rounded-xl mb-4 text-sm">Ticket content is restricted to the assigned L2 operator. This view is for masked status and assignment oversight.</div>}
            {isL2 && <div className="p-4 border rounded-xl mb-4 space-y-3">
              <p className="font-medium text-sm">Patient-consented contact access</p>
              <p className="text-xs text-muted-foreground">Ask the patient for the one-time code shown in their app. Access is limited to this assigned ticket and expires in 15 minutes.</p>
              <Input value={assistCode} onChange={(e) => setAssistCode(e.target.value)} placeholder="6-digit patient code" maxLength={6} inputMode="numeric" />
              <Input value={assistReason} onChange={(e) => setAssistReason(e.target.value)} placeholder="Reason for contact access (20+ characters)" />
              <div className="flex gap-3 text-sm">{['name', 'phone', 'email'].map((field) => <label key={field} className="flex items-center gap-1"><input type="checkbox" checked={assistFields.includes(field)} onChange={(e) => setAssistFields((old) => e.target.checked ? [...old, field] : old.filter((v) => v !== field))} />{field}</label>)}</div>
              <Button variant="outline" onClick={verifyAssistCode} disabled={!assistCode || assistFields.length === 0}>Verify consent & reveal selected fields</Button>
              {revealedContact && <p className="text-sm">{Object.entries(revealedContact).map(([key, value]) => `${key}: ${value}`).join(' · ')}</p>}
            </div>}
            {isL2 && selected.messages?.length > 0 && (
              <div className="mb-4">
                <p className="text-xs text-muted-foreground mb-2">Conversation</p>
                <div className="space-y-2">
                  {selected.messages.map((msg: Unmodelled, j: Unmodelled) => (
                    <div key={j} className={`p-3 rounded-xl ${msg.senderName === 'Super Admin' ? 'bg-primary/10 ml-8' : 'bg-muted/20 mr-8'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-xs font-medium text-foreground">{msg.senderName}</span>
                        <span className="text-[10px] text-muted-foreground">{msg.createdAt ? new Date(msg.createdAt).toLocaleString() : ''}</span>
                      </div>
                      <p className="text-sm">{msg.message}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {isL2 && revealedContact && selected.status !== 'Resolved' && selected.status !== 'Closed' && (
              <div className="flex gap-2">
                <Input value={reply} onChange={e => setReply(e.target.value)} placeholder="Type your reply..." className="flex-1" />
                <Button onClick={handleReply}>Send</Button>
                <Button variant="outline" size="sm" onClick={async () => { try { await api.updateTicketStatus(selected._id, { status: 'Resolved' }); setSelected(null); load(); } catch { toast.error('Failed to resolve'); } }}>Resolve</Button>
              </div>
            )}
            {isSuperAdmin && <div className="mt-4 space-y-2"><p className="text-xs text-muted-foreground">Assign this ticket to an L2 operator by their user ID.</p><Input id="support-assignee-id" placeholder="L2 operator user ID" /><Button variant="outline" className="w-full" onClick={async () => { const assignedTo = (document.getElementById('support-assignee-id') as HTMLInputElement)?.value; try { await api.assignTicket(selected._id, { assignedTo }); toast.success('Ticket assigned'); setSelected(null); load(); } catch (error: Unmodelled) { toast.error(error?.response?.data?.message || 'Assignment failed'); } }}>Assign</Button><Button variant="outline" className="w-full" onClick={async () => { try { await api.updateTicketStatus(selected._id, { status: selected.status === 'Closed' ? 'Open' : 'Closed' }); toast.success('Ticket status updated'); setSelected(null); load(); } catch (error: Unmodelled) { toast.error(error?.response?.data?.message || 'Could not update ticket status'); } }}>Mark {selected.status === 'Closed' ? 'Open' : 'Closed'}</Button></div>}
            <Button variant="outline" className="w-full mt-3" onClick={() => setSelected(null)}>Close</Button>
          </motion.div>
        </div>
      )}
    </div>
  );
}

export default SupportTicketsTab;

import React, { useState, useEffect, useCallback } from 'react';
import type { Unmodelled } from '@/lib/apiTypes';
import { motion } from 'framer-motion';
import { Settings } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import TenantQuotas from './TenantQuotas';

function SystemSettingsTab() {
  const [settings, setSettings] = useState<Unmodelled>(null);
  const [editKey, setEditKey] = useState<Unmodelled>(null);
  const [editValue, setEditValue] = useState('');
  const [loading, setLoading] = useState(true);

  const fetchSettings = useCallback(async () => {
    setLoading(true);
    try {
      const data = await api.getSystemSettings();
      setSettings(data);
    } catch { toast.error('Failed to load system settings'); }
    setLoading(false);
  }, []);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { fetchSettings(); }, []);

  const handleSave = async (key: Unmodelled) => {
    try {
      const setting = settings[key];
      if (!setting) { toast.error('Setting not found'); return; }
      let val: Unmodelled = editValue;
      if (setting.type === 'number') val = Number(val);
      else if (setting.type === 'boolean') val = val === 'true';
      else if (setting.type === 'array') val = val.split(',').map((s: Unmodelled) => s.trim());
      await api.updateSystemSetting(key, { value: val });
      toast.success('Setting updated');
      setEditKey(null);
      fetchSettings();
    } catch { toast.error('Failed to update setting'); }
  };

  if (loading) return <div className="flex justify-center py-12"><div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-3">
      {settings && Object.entries(settings).map(([key, config]: Unmodelled) => (
        <div key={key} className="bg-card rounded-xl border p-4 flex items-start justify-between gap-4">
          <div className="flex-1 min-w-0">
            <p className="font-medium text-foreground text-sm">{key.replace(/([A-Z])/g, ' $1').replace(/^./, (s: Unmodelled) => s.toUpperCase())}</p>
            <p className="text-xs text-muted-foreground">{config.description}</p>
            {editKey === key ? (
              <div className="flex items-center gap-2 mt-2">
                {config.type === 'boolean' ? (
                  <select value={String(editValue)} onChange={e => setEditValue(e.target.value)}
                    className="h-8 px-2 rounded border border-input bg-background text-sm">
                    <option value="true">True</option>
                    <option value="false">False</option>
                  </select>
                ) : (
                  <Input value={editValue} onChange={e => setEditValue(e.target.value)} className="text-sm h-8 max-w-xs" />
                )}
                <Button size="sm" onClick={() => handleSave(key)}>Save</Button>
                <Button size="sm" variant="outline" onClick={() => setEditKey(null)}>Cancel</Button>
              </div>
            ) : (
              <p className="text-sm font-semibold text-foreground mt-1">
                {config.type === 'boolean' ? (config.value ? '✅ Enabled' : '❌ Disabled') :
                 config.type === 'array' ? (config.value || []).join(', ') :
                 String(config.value)}
              </p>
            )}
          </div>
          <Badge variant="outline" className="shrink-0 text-xs">{config.type}</Badge>
          {editKey !== key && (
            <Button variant="ghost" size="sm" onClick={() => { setEditKey(key); setEditValue(String(config.value)); }}>
              <Settings className="w-3.5 h-3.5" />
            </Button>
          )}
        </div>
      ))}
      {/* ADM-M-06: per-tenant quota management lives beside the global settings it complements. */}
      <TenantQuotas />
    </div>
  );
}

export default SystemSettingsTab;

import React, { useState, useCallback, useEffect } from 'react';
import { Search, Shield, Stethoscope, UserRound, CheckCircle, Ban, Trash2, Activity, Flag, Filter, History } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { DataGrid } from '@/components/ui/System';
import { toast } from '@/components/ui/sonner';
import { api } from '@/lib/api';
import type { ApiRow, Unmodelled } from '@/lib/apiTypes';

export default function UserManagementTab() {
  const navigate = useNavigate();
  const [users, setUsers] = useState<ApiRow[]>([]);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('All');
  const [showFlagged, setShowFlagged] = useState(false);
  const [loading, setLoading] = useState(true);

  const loadUsers = useCallback(async () => {
    setLoading(true);
    try {
      const params: Unmodelled = { search, role: roleFilter };
      if (showFlagged) params.flagged = 'true';
      const data = await api.getUsers(params);
      setUsers(data?.users || data?.data || data || []);
    } catch { toast.error('Failed to load users'); }
    setLoading(false);
  }, [search, roleFilter, showFlagged]);

  useEffect(() => { loadUsers(); }, [search, roleFilter, showFlagged]);

  const handleDelete = async (id: Unmodelled) => {
    if (!confirm('Permanently delete this user?')) return;
    try { await api.deleteUser(id); loadUsers(); } catch { toast.error('Failed to delete user'); }
  };

  const handleBlock = async (id: Unmodelled) => {
    if (!confirm('Toggle block status for this user?')) return;
    try { await api.blockUser(id); loadUsers(); } catch { toast.error('Failed to update user status'); }
  };

  const handleFlag = async (id: Unmodelled, name: Unmodelled) => {
    const reason = prompt(`Flag ${name} as suspicious? Enter reason:`);
    if (!reason) return;
    try { await api.flagUser(id, { reason }); toast.success('User flagged'); loadUsers(); } catch { toast.error('Failed to flag user'); }
  };

  const handleUnflag = async (id: Unmodelled) => {
    try { await api.unflagUser(id); toast.success('User unflagged'); loadUsers(); } catch { toast.error('Failed to unflag user'); }
  };

  const roleColors: Unmodelled = {
    superadmin: 'bg-destructive/10 text-destructive',
    admin: 'bg-primary/10 text-primary',
    doctor: 'bg-info/10 text-info',
    clinic_doctor: 'bg-info/10 text-info',
    patient: 'bg-success/10 text-success',
    lab_owner: 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400',
