    }
    try {
      await apiClient.post('/crm/campaigns', {
        title: newCamp.title.trim(),
        type: newCamp.type,
        city: newCamp.city,
        venue: newCamp.venue,
        date: newCamp.date ? new Date(newCamp.date) : null,
