      setNewCamp({
        title: '',
        type: 'health_camp',
        city: 'Bhopal',
        venue: '',
        date: new Date(Date.now() + 7 * 864e5).toISOString().split('T')[0],
        budget: 15000,
        capacity: 200,
      });
      fetchCampaigns();
