                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CAMPAIGN_STAGES.map((s) => (
                        <SelectItem key={s.key} value={s.key} className="text-xs">
                          {s.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </td>
              </tr>
            ))}
            {campaigns.length === 0 && (
              <tr>
                <td colSpan={6} className="text-center py-10 text-sm text-muted-foreground">
                  No health camps or campaigns in pipeline yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Plan Camp Dialog */}
      <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Plan Health Camp / Campaign</DialogTitle>
            <DialogDescription>Setup a free/subsidized screening drive or wellness workshop.</DialogDescription>
          </DialogHeader>
          <form onSubmit={handleCreateCampaign} className="space-y-3.5 py-2">
            <div>
              <Label className="text-xs font-semibold">Camp Title *</Label>
              <Input
                placeholder="e.g. Free Dental & Eye Screening Camp"
                value={newCamp.title}
                onChange={(e) => setNewCamp({ ...newCamp, title: e.target.value })}
                required
                className="mt-1"
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs font-semibold">Event Type</Label>
                <Select value={newCamp.type} onValueChange={(v) => setNewCamp({ ...newCamp, type: v })}>
                  <SelectTrigger className="mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="health_camp">General Health Camp</SelectItem>
                    <SelectItem value="specialty_camp">Specialty Camp</SelectItem>
                    <SelectItem value="vaccination_drive">Vaccination Drive</SelectItem>
                    <SelectItem value="blood_drive">Blood Donation Camp</SelectItem>
                    <SelectItem value="workshop">Wellness Workshop</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs font-semibold">City</Label>
                <Input
                  value={newCamp.city}
                  onChange={(e) => setNewCamp({ ...newCamp, city: e.target.value })}
                  className="mt-1"
                />
              </div>
            </div>
            <div>
              <Label className="text-xs font-semibold">Venue / Community Hall</Label>
              <Input
                placeholder="e.g. Community Hall, Sector C, Shahpura"
                value={newCamp.venue}
                onChange={(e) => setNewCamp({ ...newCamp, venue: e.target.value })}
                className="mt-1"
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs font-semibold">Target Date</Label>
                <Input
                  type="date"
                  value={newCamp.date}
                  onChange={(e) => setNewCamp({ ...newCamp, date: e.target.value })}
                  className="mt-1"
                />
              </div>
              <div>
                <Label className="text-xs font-semibold">Capacity (People)</Label>
                <Input
                  type="number"
                  value={newCamp.capacity}
                  onChange={(e) => setNewCamp({ ...newCamp, capacity: Number(e.target.value) })}
                  className="mt-1"
                />
              </div>
            </div>
            <DialogFooter className="pt-2">
              <Button type="button" variant="outline" onClick={() => setIsAddOpen(false)}>Cancel</Button>
              <Button type="submit">Create Campaign</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import {
  BarChart3, RefreshCw, Download, Mail, Plus, Trash2, CalendarClock, Table2
} from 'lucide-react';
import { apiClient } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';

interface ReportMeta { key: string }
interface ReportData {
  key: string;
  title: string;
  columns: string[];
  rows: (string | number)[][];
  generatedAt?: string;
}
interface Schedule {
  id: string;
  reportKey: string;
  frequency: string;
  recipients: string[];
  active: boolean;
  lastRunAt?: string | null;
}

const REPORT_TITLES: Record<string, string> = {
  supply_funnel: 'Supply Funnel',
  field_productivity: 'Field Productivity',
  churn: 'Churn Analysis',
  partner_outcomes: 'Partnership Outcomes',
  cohort: 'Cohort & Retention',
};

const toCsv = (columns: string[], rows: (string | number)[][]) => {
  const esc = (v: string | number) => {
    const s = v === null || v === undefined ? '' : String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  return [columns.map(esc).join(','), ...rows.map((r) => r.map(esc).join(','))].join('\n');
};

export default function CrmReports() {
  const [reports, setReports] = useState<ReportMeta[]>([]);
  const [schedules, setSchedules] = useState<Schedule[]>([]);
  const [active, setActive] = useState<string | null>(null);
  const [data, setData] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);
  const [isScheduleOpen, setIsScheduleOpen] = useState(false);
  const [newSchedule, setNewSchedule] = useState({
    reportKey: 'supply_funnel',
    frequency: 'weekly',
    recipients: '',
  });

  const fetchList = async () => {
    setLoading(true);
    try {
      const res = await apiClient.get('/crm/reports');
      setReports(res.data.reports || []);
      setSchedules(res.data.schedules || []);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to load reports');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchList(); }, []);

  const loadReport = async (key: string) => {
    setRunning(true);
    setActive(key);
    try {
      const res = await apiClient.get(`/crm/reports/${key}`);
      setData(res.data);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to run report');
      setActive(null);
    } finally {
      setRunning(false);
    }
  };

  const downloadCsv = () => {
    if (!data) return;
    try {
      const csv = toCsv(data.columns, data.rows);
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `crm-${data.key}-${new Date().toISOString().slice(0, 10)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success('CSV downloaded');
    } catch {
      toast.error('Failed to build CSV');
    }
  };

  const createSchedule = async (e: React.FormEvent) => {
    e.preventDefault();
    const recipients = newSchedule.recipients
      .split(/[,;\s]+/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (!recipients.length) { toast.error('At least one recipient email required'); return; }
    try {
      await apiClient.post('/crm/reports/schedules', {
        reportKey: newSchedule.reportKey,
        frequency: newSchedule.frequency,
        recipients,
        active: true,
      });
      toast.success('Report schedule created');
      setIsScheduleOpen(false);
      setNewSchedule({ reportKey: 'supply_funnel', frequency: 'weekly', recipients: '' });
      fetchList();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to create schedule');
    }
  };

  const toggleSchedule = async (s: Schedule) => {
    try {
      await apiClient.patch(`/crm/reports/schedules/${s.id}`, { active: !s.active });
      setSchedules(schedules.map((x) => (x.id === s.id ? { ...x, active: !x.active } : x)));
      toast.success(s.active ? 'Schedule paused' : 'Schedule activated');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to update schedule');
    }
  };

  const deleteSchedule = async (s: Schedule) => {
    try {
      await apiClient.delete(`/crm/reports/schedules/${s.id}`);
      setSchedules(schedules.filter((x) => x.id !== s.id));
      toast.success('Schedule deleted');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to delete schedule');
    }
  };

  if (loading) return <div className="p-6 text-sm text-muted-foreground">Loading CRM reports…</div>;

  return (
    <div className="p-6 max-w-full mx-auto space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-2 border-b border-border">
        <div>
          <Badge variant="outline" className="text-xs uppercase bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 border-emerald-200">
            File 24 §4.12 — aggregate only, no PII
          </Badge>
          <h1 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2 mt-1">
            <BarChart3 className="h-6 w-6 text-primary" />
            CRM Reports
          </h1>
          <p className="text-sm text-muted-foreground">
            Supply funnel, field productivity, churn, partnership outcomes & cohort retention.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Button variant="outline" size="sm" onClick={fetchList} className="gap-1.5 h-9">
            <RefreshCw className="h-3.5 w-3.5" /> Refresh
          </Button>
          <Button size="sm" onClick={() => setIsScheduleOpen(true)} className="gap-1.5 h-9">
            <Plus className="h-4 w-4" /> Schedule Report
          </Button>
        </div>
      </div>

      {/* Report cards */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
        {reports.map((r) => (
          <Card
            key={r.key}
            className={`shadow-xs cursor-pointer hover:shadow-md transition-shadow ${active === r.key ? 'border-primary' : ''}`}
            onClick={() => loadReport(r.key)}
          >
            <CardContent className="p-4">
              <div className="text-xs font-semibold text-foreground">{REPORT_TITLES[r.key] || r.key}</div>
              <div className="text-[10px] text-muted-foreground font-mono mt-0.5">{r.key}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Report table */}
      {active && (
        <Card className="shadow-xs">
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="text-base">{data?.title || REPORT_TITLES[active]}</CardTitle>
                <CardDescription>
                  {data?.rows?.length ?? 0} rows
                  {data?.generatedAt ? ` • generated ${new Date(data.generatedAt).toLocaleString()}` : ''}
                </CardDescription>
              </div>
              <Button variant="outline" size="sm" onClick={downloadCsv} disabled={!data} className="gap-1.5 h-9">
                <Download className="h-3.5 w-3.5" /> Export CSV
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            {running || !data ? (
              <div className="text-sm text-muted-foreground py-6 text-center">Running report…</div>
            ) : (
              <div className="overflow-x-auto rounded-lg border border-border/60">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="bg-muted/60">
                      {data.columns.map((c) => (
                        <th key={c} className="text-left font-semibold px-3 py-2 whitespace-nowrap capitalize">
                          {c.replace(/_/g, ' ')}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {data.rows.map((row, i) => (
                      <tr key={i} className="border-t border-border/50 hover:bg-muted/30">
                        {row.map((cell, j) => (
                          <td key={j} className="px-3 py-1.5 whitespace-nowrap">
                            {typeof cell === 'number' ? cell.toLocaleString() : String(cell)}
                          </td>
                        ))}
                      </tr>
                    ))}
                    {data.rows.length === 0 && (
                      <tr><td colSpan={data.columns.length} className="px-3 py-6 text-center text-muted-foreground">No data yet</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Schedules */}
      <Card className="shadow-xs">
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <CalendarClock className="h-4 w-4 text-indigo-500" /> Scheduled Exports
          </CardTitle>
          <CardDescription>Emailed nightly as CSV to recipients (aggregate-only).</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          {schedules.length === 0 && (
            <div className="text-center py-6 text-sm text-muted-foreground">No schedules configured.</div>
          )}
          {schedules.map((s) => (
            <div key={s.id} className="flex items-center justify-between gap-3 p-3 rounded-lg bg-muted/40 border border-border/60">
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <Table2 className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                  <span className="text-sm font-semibold">{REPORT_TITLES[s.reportKey] || s.reportKey}</span>
                  <Badge variant="secondary" className="text-[10px] capitalize">{s.frequency}</Badge>
                  <Badge variant={s.active ? 'outline' : 'secondary'} className="text-[10px] capitalize">
                    {s.active ? 'active' : 'paused'}
                  </Badge>
                </div>
                <div className="text-[11px] text-muted-foreground mt-0.5 flex items-center gap-1 truncate">
                  <Mail className="h-3 w-3 shrink-0" />
                  {s.recipients.join(', ')}
                  {s.lastRunAt ? ` • last run ${new Date(s.lastRunAt).toLocaleDateString()}` : ' • never run'}
                </div>
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <Button variant="outline" size="sm" className="h-8 text-xs" onClick={() => toggleSchedule(s)}>
                  {s.active ? 'Pause' : 'Activate'}
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 text-rose-500 hover:text-rose-600"
                  onClick={() => deleteSchedule(s)}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            </div>
          ))}
        </CardContent>
      </Card>

      {/* Schedule dialog */}
      <Dialog open={isScheduleOpen} onOpenChange={setIsScheduleOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Schedule Report Export</DialogTitle>
            <DialogDescription>CSV emailed to recipients on the frequency you choose.</DialogDescription>
          </DialogHeader>
          <form onSubmit={createSchedule} className="space-y-3.5 py-2">
            <div>
              <Label className="text-xs font-semibold">Report</Label>
              <Select value={newSchedule.reportKey} onValueChange={(v) => setNewSchedule({ ...newSchedule, reportKey: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {reports.map((r) => (
                    <SelectItem key={r.key} value={r.key}>{REPORT_TITLES[r.key] || r.key}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs font-semibold">Frequency</Label>
              <Select value={newSchedule.frequency} onValueChange={(v) => setNewSchedule({ ...newSchedule, frequency: v })}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="daily">Daily (01:30)</SelectItem>
                  <SelectItem value="weekly">Weekly</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs font-semibold">Recipients (comma-separated emails) *</Label>
              <Input
                placeholder="ops@findmedi.com, admin@findmedi.com"
                value={newSchedule.recipients}
                onChange={(e) => setNewSchedule({ ...newSchedule, recipients: e.target.value })}
                required
                className="mt-1"
              />
            </div>
            <DialogFooter className="pt-2">
              <Button type="button" variant="outline" onClick={() => setIsScheduleOpen(false)}>Cancel</Button>
              <Button type="submit">Create Schedule</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import {
  Settings, RefreshCw, Plus, Play, ToggleLeft, ToggleRight, Timer,
  AlertTriangle, Zap, Trash2, Save
} from 'lucide-react';
import { apiClient } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';

interface StageRow { key: string; label: string; slaHours: number; terminal?: boolean }
interface PipelineConfig {
  leadStages: StageRow[];
  partnerStages: StageRow[];
  lostReasons: string[];
  leadSources?: string[];
  scoringWeights?: Record<string, number>;
  followUpSlaHours?: number;
  docRenewalLeadDays?: number;
}
interface Rule {
  id: string;
  name: string;
  trigger: string;
  enabled: boolean;
  conditions?: Record<string, any>;
  actions?: Array<{ type: string; params?: Record<string, any> }>;
  cooldownMinutes?: number;
  runs?: Array<{ at: string; matched: number; created: number }>;
}

const TRIGGER_LABELS: Record<string, string> = {
  lead_stage_idle: 'Lead idle in stage (SLA breach)',
  doc_expiring: 'Provider document expiring',
  task_overdue: 'Task overdue',
  at_risk_provider: 'Provider at risk (churn signal)',
  partner_next_step_due: 'Partner next-step due',
};

export default function CrmSettings() {
  const [config, setConfig] = useState<PipelineConfig | null>(null);
  const [rules, setRules] = useState<Rule[]>([]);
  const [triggers, setTriggers] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isRuleOpen, setIsRuleOpen] = useState(false);
  const [running, setRunning] = useState(false);
  const [newRule, setNewRule] = useState({
    name: '',
    trigger: 'lead_stage_idle',
    slaHours: 48,
    cooldownMinutes: 60,
    action: 'create_task',
  });

  const fetchAll = async () => {
    setLoading(true);
    try {
      const [settingsRes, rulesRes] = await Promise.all([
        apiClient.get('/crm/settings'),
        apiClient.get('/crm/automation/rules'),
      ]);
      setConfig(settingsRes.data.config);
      setRules(rulesRes.data.rules || []);
      setTriggers(rulesRes.data.triggers || []);
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to load CRM settings');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchAll(); }, []);

  const saveConfig = async () => {
    if (!config) return;
    setSaving(true);
    try {
      const res = await apiClient.put('/crm/settings', {
        leadStages: config.leadStages,
        partnerStages: config.partnerStages,
        lostReasons: config.lostReasons,
        followUpSlaHours: config.followUpSlaHours,
        docRenewalLeadDays: config.docRenewalLeadDays,
      });
      setConfig(res.data.config);
      toast.success('Pipeline config saved');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  const updateStage = (group: 'leadStages' | 'partnerStages', idx: number, slaHours: number) => {
    if (!config) return;
    const rows = config[group].map((s, i) => (i === idx ? { ...s, slaHours } : s));
    setConfig({ ...config, [group]: rows } as PipelineConfig);
  };

  const toggleRule = async (rule: Rule) => {
    try {
      await apiClient.patch(`/crm/automation/rules/${rule.id}`, { enabled: !rule.enabled });
      setRules(rules.map((r) => (r.id === rule.id ? { ...r, enabled: !r.enabled } : r)));
      toast.success(rule.enabled ? 'Rule paused' : 'Rule enabled');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to update rule');
    }
  };

  const createRule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRule.name.trim()) { toast.error('Rule name is required'); return; }
    try {
      await apiClient.post('/crm/automation/rules', {
        name: newRule.name.trim(),
        trigger: newRule.trigger,
        enabled: true,
        conditions: { slaHours: Number(newRule.slaHours) || 48 },
        actions: [{ type: newRule.action, params: {} }],
        cooldownMinutes: Number(newRule.cooldownMinutes) || 60,
      });
      toast.success('Automation rule created');
      setIsRuleOpen(false);
      setNewRule({ name: '', trigger: 'lead_stage_idle', slaHours: 48, cooldownMinutes: 60, action: 'create_task' });
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to create rule');
    }
  };

  const runAutomation = async () => {
    setRunning(true);
    try {
      const res = await apiClient.post('/crm/automation/run', { force: true });
      const s = res.data || {};
      toast.success(`Sweep done — evaluated: ${s.evaluated ?? 0}, matched: ${s.matched ?? 0}, tasks: ${s.created ?? 0}, skipped: ${s.skipped ?? 0}${s.failed ? `, failed: ${s.failed}` : ''}`);
      fetchAll();
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Automation sweep failed');
    } finally {
      setRunning(false);
    }
  };

  const deleteRule = async (rule: Rule) => {
    try {
      await apiClient.delete(`/crm/automation/rules/${rule.id}`);
      setRules(rules.filter((r) => r.id !== rule.id));
      toast.success('Rule deleted');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to delete rule');
    }
  };

  if (loading) {
    return <div className="p-6 text-sm text-muted-foreground">Loading CRM settings…</div>;
  }

  return (
    <div className="p-6 max-w-full mx-auto space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-2 border-b border-border">
        <div>
          <div className="flex items-center gap-2">
            <Badge variant="outline" className="text-xs uppercase bg-violet-50 text-violet-700 dark:bg-violet-950/40 border-violet-200">
              File 24 §4.13 + §5
            </Badge>
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2 mt-1">
            <Settings className="h-6 w-6 text-primary" />
            CRM Settings & Automation
          </h1>
          <p className="text-sm text-muted-foreground">
            Pipeline stages, SLAs, lost reasons, scoring + automation rules (trigger → task/notify).
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Button variant="outline" size="sm" onClick={fetchAll} disabled={loading} className="gap-1.5 h-9">
            <RefreshCw className="h-3.5 w-3.5" /> Refresh
          </Button>
          <Button size="sm" onClick={runAutomation} disabled={running} className="gap-1.5 h-9">
            <Play className="h-4 w-4" /> {running ? 'Running…' : 'Run Automation Now'}
          </Button>
        </div>
      </div>

      {/* Pipeline stages */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        <Card className="shadow-xs">
