                required
                className="mt-1"
              />
            </div>
            <div>
              <Label className="text-xs font-semibold">City</Label>
              <Input
                value={newTerritory.city}
                onChange={(e) => setNewTerritory({ ...newTerritory, city: e.target.value })}
                className="mt-1"
              />
            </div>
            <div>
              <Label className="text-xs font-semibold">Pincodes (comma-separated)</Label>
