import { UnleashClient } from '@unleash/proxy-client-react';
import posthog from 'posthog-js';
import type { Unmodelled } from '@/lib/apiTypes';

let unleash: UnleashClient | null = null;
let posthogInitialized = false;

export function initFeatureFlags(): UnleashClient | null {
  const unleashUrl = (import.meta as any).env?.VITE_UNLEASH_URL;
  const clientKey = (import.meta as any).env?.VITE_UNLEASH_CLIENT_KEY;

  if (!unleashUrl || !clientKey) {
    return null;
  }

  unleash = new UnleashClient({
    url: unleashUrl,
    clientKey,
    appName: 'findmedi-frontend',
    refreshInterval: 15,
    disableMetrics: true,
  });

  unleash.on('error', (err: Unmodelled) => console.error('Unleash error:', err));
  unleash.start().catch(() => {
    // Fail-soft: flags stay off, app keeps working.
  });

  return unleash;
}

export function initPostHog() {
  const apiKey = (import.meta as any).env?.VITE_POSTHOG_API_KEY;
  const host = (import.meta as any).env?.VITE_POSTHOG_HOST || 'https://app.posthog.com';

  if (!apiKey || posthogInitialized) {
    return;
  }

  try {
    posthog.init(apiKey, {
      api_host: host,
      capture_pageview: false,
      capture_pageleave: false,
      // §6.6: analytics must stay pseudonymous — no cookie/localStorage identity
      // that survives logout on a shared clinic PC, no autocapture of form/PHI
      // text, no session replay of clinical screens.
      persistence: 'memory',
      autocapture: false,
      disable_session_recording: true,
    });
    posthogInitialized = true;
  } catch {
    // Analytics must never break the app.
  }
}

export function isFeatureEnabled(flagName: string, context?: Record<string, unknown>): boolean {
  if (!unleash) return false;
  try {
    // §6.7: flag context must stay pseudonymous — hash any userId/email/phone
    // the caller passes instead of shipping raw PII to the flag service.
    return (unleash.isEnabled as Unmodelled)(flagName, scrubFlagContext(context));
  } catch {
    return false;
  }
}

export function getVariant(flagName: string, context?: Record<string, unknown>) {
  if (!unleash) return null;
  try {
    return (unleash.getVariant as Unmodelled)(flagName, scrubFlagContext(context));
  } catch {
    return null;
  }
}

function scrubFlagContext(context?: Record<string, unknown>): Record<string, unknown> | undefined {
  if (!context) return undefined;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(context)) {
    if (['userId', 'user_id', 'email', 'phone', 'mobile'].includes(k) && typeof v === 'string') {
      out[k] = pseudonymize(v);
      continue;
    }
    if (ANALYTICS_UNSAFE_KEY.test(k)) continue;
    out[k] = v;
  }
  return out;
}

export function capturePostHogEvent(event: string, properties?: Record<string, unknown>) {
  if (!posthogInitialized) return;
  try {
    posthog.capture(event, scrubAnalyticsProps(properties));
  } catch {
    // ignore
  }
}

export function identifyPostHogUser(userId: string, traits?: Record<string, unknown>) {
  if (!posthogInitialized) return;
  try {
    // §6.6: analytics identity is a pseudonymous hash, never raw email/phone —
    // and traits must never carry PHI/PII (name, email, phone, diagnosis...).
    posthog.identify(pseudonymize(userId), scrubAnalyticsProps(traits));
  } catch {
    // ignore
  }
}

// §6.6: allowlist, not denylist — unknown keys (a new PHI field tomorrow) are
// dropped instead of shipped to the analytics vendor.
const ANALYTICS_SAFE_KEYS = new Set([
  'role', 'plan', 'screen', 'surface', 'flag', 'variant', 'source', 'action',
  'success', 'error_code', 'duration_ms', 'count',
]);

const ANALYTICS_UNSAFE_KEY = /(name|email|phone|mobile|address|dob|birth|age|gender|sex|aadhaar|pan|passport|voter|bank|upi|card|diagnos|disease|symptom|prescription|treatment|therapy|mental|report|lab|record|patient|doctor|hospital|clinic|otp|password|token|secret|key)/i;

function scrubAnalyticsProps(props?: Record<string, unknown>): Record<string, unknown> | undefined {
  if (!props) return undefined;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(props)) {
    if (ANALYTICS_SAFE_KEYS.has(k)) {
      out[k] = v;
      continue;
    }
    if (ANALYTICS_UNSAFE_KEY.test(k)) continue;
    if (typeof v === 'string' && v.length > 200) continue;
    if (v !== null && typeof v === 'object') continue;
    out[k] = v;
  }
  return out;
}

function pseudonymize(userId: string): string {
  // Sync salted hash (cyrb53) — deterministic per user, but the raw id
  // (Mongo ObjectId / email) never leaves the browser. Not a crypto hash,
  // but analytics only needs unlinkability from the raw id, not secrecy.
  const raw = `findmedi-analytics|${String(userId || '')}`;
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < raw.length; i += 1) {
    const ch = raw.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return `fm-${(h2 >>> 0).toString(16).padStart(8, '0')}${(h1 >>> 0).toString(16).padStart(8, '0')}`;
}

/**
 * alarmAudio.ts
 * Web Audio API synthesizer for phone alarm-style looping tones.
 * Generates loud, looping alarm sounds without external audio asset dependencies.
 */

let activeAudioCtx: AudioContext | null = null;
let activeLoopTimer: any = null;
let activeAudioElement: HTMLAudioElement | null = null;
let isAlarmSoundPlaying = false;

function getAudioContext(): AudioContext {
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  if (!activeAudioCtx || activeAudioCtx.state === 'closed') {
    activeAudioCtx = new AudioContextClass();
  }
  if (activeAudioCtx.state === 'suspended') {
    activeAudioCtx.resume();
  }
  return activeAudioCtx;
}

/**
 * Tone 1: Classic Alarm (Pulsing high/low double beep)
 */
function playClassicAlarmCycle(ctx: AudioContext, gainNode: GainNode) {
  const now = ctx.currentTime;

  // Beep 1
  const osc1 = ctx.createOscillator();
  osc1.type = 'square';
  osc1.frequency.setValueAtTime(880, now);
  osc1.frequency.setValueAtTime(1760, now + 0.1);
  osc1.connect(gainNode);
  osc1.start(now);
  osc1.stop(now + 0.2);

  // Beep 2
  const osc2 = ctx.createOscillator();
  osc2.type = 'square';
  osc2.frequency.setValueAtTime(880, now + 0.25);
  osc2.frequency.setValueAtTime(1760, now + 0.35);
  osc2.connect(gainNode);
  osc2.start(now + 0.25);
  osc2.stop(now + 0.45);

  // Beep 3
  const osc3 = ctx.createOscillator();
  osc3.type = 'square';
  osc3.frequency.setValueAtTime(880, now + 0.5);
  osc3.frequency.setValueAtTime(1760, now + 0.6);
  osc3.connect(gainNode);
  osc3.start(now + 0.5);
  osc3.stop(now + 0.7);
}

/**
 * Tone 2: Digital Buzzer (Harsh, urgent electronic buzzer)
 */
function playDigitalBuzzerCycle(ctx: AudioContext, gainNode: GainNode) {
  const now = ctx.currentTime;
  const osc = ctx.createOscillator();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(320, now);
  osc.frequency.setValueAtTime(440, now + 0.15);
  osc.frequency.setValueAtTime(320, now + 0.3);
  osc.frequency.setValueAtTime(520, now + 0.45);

  const filter = ctx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.setValueAtTime(600, now);
  filter.Q.setValueAtTime(3, now);

  osc.connect(filter);
  filter.connect(gainNode);
  osc.start(now);
  osc.stop(now + 0.65);
}

/**
 * Tone 3: Gentle Rise (Rhythmic harmonic ascending chime)
 */
function playGentleRiseCycle(ctx: AudioContext, gainNode: GainNode) {
  const now = ctx.currentTime;
  const freqs = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6

  freqs.forEach((f, idx) => {
    const osc = ctx.createOscillator();
    const noteGain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(f, now + idx * 0.15);

    noteGain.gain.setValueAtTime(0, now + idx * 0.15);
    noteGain.gain.linearRampToValueAtTime(0.8, now + idx * 0.15 + 0.05);
    noteGain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.15 + 0.4);

    osc.connect(noteGain);
    noteGain.connect(gainNode);

    osc.start(now + idx * 0.15);
    osc.stop(now + idx * 0.15 + 0.45);
  });
}

/**
 * Tone 4: Chime Cascade (Melodic repeating marimba / bell cascade)
 */
function playChimeCascadeCycle(ctx: AudioContext, gainNode: GainNode) {
  const now = ctx.currentTime;
  const freqs = [880, 1174.66, 1318.51, 1760]; // A5, D6, E6, A6

  freqs.forEach((f, idx) => {
    const osc = ctx.createOscillator();
    const noteGain = ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(f, now + idx * 0.18);

    noteGain.gain.setValueAtTime(0.7, now + idx * 0.18);
    noteGain.gain.exponentialRampToValueAtTime(0.01, now + idx * 0.18 + 0.35);

    osc.connect(noteGain);
    noteGain.connect(gainNode);

    osc.start(now + idx * 0.18);
    osc.stop(now + idx * 0.18 + 0.38);
  });
}

/**
 * Start playing an alarm preset continuously in a loop.
 * Keeps ringing like a phone alarm until stopAlarmSound() is called.
 */
export function startAlarmSound(presetId = 'classic_alarm', customSoundUrl?: string): void {
  stopAlarmSound();
  isAlarmSoundPlaying = true;

  if (presetId === 'custom' && customSoundUrl) {
    try {
      activeAudioElement = new Audio(customSoundUrl);
      activeAudioElement.loop = true;
      activeAudioElement.volume = 1.0;
      activeAudioElement.play().catch(() => {
        // Fallback to classic alarm if custom audio failed
        startAlarmSound('classic_alarm');
      });
      return;
    } catch {
      // Fallback
    }
  }

  const ctx = getAudioContext();
  const masterGain = ctx.createGain();
  masterGain.gain.setValueAtTime(0.9, ctx.currentTime);
  masterGain.connect(ctx.destination);

  const cycleDuration = presetId === 'gentle_rise' ? 1200 : presetId === 'chime_cascade' ? 1100 : 1000;

  const triggerCycle = () => {
    if (!isAlarmSoundPlaying) return;
    try {
      if (presetId === 'digital_buzzer') {
        playDigitalBuzzerCycle(ctx, masterGain);
      } else if (presetId === 'gentle_rise') {
        playGentleRiseCycle(ctx, masterGain);
      } else if (presetId === 'chime_cascade') {
        playChimeCascadeCycle(ctx, masterGain);
      } else {
        playClassicAlarmCycle(ctx, masterGain);
      }
    } catch (e: any) {
      console.warn('Audio cycle failed:', e);
    }
  };

  triggerCycle();
  activeLoopTimer = setInterval(triggerCycle, cycleDuration);
}

/**
 * Stop any active alarm tone immediately.
 */
export function stopAlarmSound(): void {
  isAlarmSoundPlaying = false;
  if (activeLoopTimer) {
    clearInterval(activeLoopTimer);
    activeLoopTimer = null;
  }
  if (activeAudioElement) {
    activeAudioElement.pause();
    activeAudioElement.currentTime = 0;
    activeAudioElement = null;
  }
  if (activeAudioCtx && activeAudioCtx.state === 'running') {
    // Keep context alive for instant reuse without delay
  }
}

/**
 * Preview an alarm preset for ~2.5 seconds, then stop automatically.
 */
export function previewAlarmSound(presetId = 'classic_alarm', customSoundUrl?: string): void {
  startAlarmSound(presetId, customSoundUrl);
  setTimeout(() => {
    stopAlarmSound();
  }, 2500);
}

/**
 * Web Audio API Procedural Siren Engine
 * Synthesizes dual-tone clinical emergency chimes in-browser without external MP3 dependencies.
 */

let audioContext: AudioContext | null = null;
let oscillator: OscillatorNode | null = null;
let gainNode: GainNode | null = null;
let toneInterval: NodeJS.Timeout | null = null;

export function playEmergencyDoctorSiren() {
  try {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContextClass) return;

    if (!audioContext || audioContext.state === 'closed') {
      audioContext = new AudioContextClass();
    }

    if (audioContext.state === 'suspended') {
      audioContext.resume();
    }

    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();

    oscillator.type = 'triangle'; // Smooth medical dual-tone
    gainNode.gain.setValueAtTime(0.25, audioContext.currentTime);

    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);
    oscillator.start();

    let isHigh = false;
    toneInterval = setInterval(() => {
      if (!oscillator || !audioContext) return;
      const freq = isHigh ? 880 : 587.33; // D5 (587 Hz) to A5 (880 Hz) emergency alert chime
      oscillator.frequency.setTargetAtTime(freq, audioContext.currentTime, 0.05);
      isHigh = !isHigh;
    }, 450);
  } catch (err: any) {
    console.warn('Web Audio emergency alert autoplay blocked by browser policy:', err);
  }
}

export function stopEmergencyDoctorSiren() {
  if (toneInterval) {
    clearInterval(toneInterval);
    toneInterval = null;
  }
  if (oscillator) {
    try {
      oscillator.stop();
      oscillator.disconnect();
    } catch {}
    oscillator = null;
  }
  if (gainNode) {
    try {
      gainNode.disconnect();
    } catch {}
    gainNode = null;
  }
  if (audioContext && audioContext.state !== 'closed') {
    try {
      audioContext.close();
    } catch {}
    audioContext = null;
  }
}

// Emergency call ringtone + vibration (notification NAHI — sirf in-app full-screen call ke liye).
// Browser autoplay policy: AudioContext tabhi bajta hai jab user ne page par kabhi tap/click kiya ho.
// Isliye `installEmergencyAudioUnlock()` app mount par ek baar chalao — pehla tap context ko unlock kar dega.

let ctx: AudioContext | null = null;
let ringTimer: ReturnType<typeof setInterval> | null = null;
let vibTimer: ReturnType<typeof setInterval> | null = null;

function ensureCtx(): AudioContext | null {
  if (ctx) return ctx;
  const AC = window.AudioContext || (window as any).webkitAudioContext;
  if (!AC) return null;
  try {
    ctx = new AC();
  } catch {
    ctx = null;
  }
  return ctx;
}

export function unlockEmergencyAudio() {
  const c = ensureCtx();
  if (c && c.state === 'suspended') c.resume().catch(() => {});
}

/** App mount par ek baar. Cleanup function return karta hai. */
export function installEmergencyAudioUnlock() {
  const events = ['pointerdown', 'touchstart', 'keydown'] as const;
  const handler = () => unlockEmergencyAudio();
  events.forEach((e) => window.addEventListener(e, handler, { passive: true }));
  return () => events.forEach((e) => window.removeEventListener(e, handler));
}

function tone(c: AudioContext, freq: number, start: number, dur: number, gainPeak = 0.35) {
  const osc = c.createOscillator();
  const gain = c.createGain();
  osc.type = 'square';
  osc.frequency.setValueAtTime(freq, start);
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(gainPeak, start + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);
  osc.connect(gain);
  gain.connect(c.destination);
  osc.start(start);
  osc.stop(start + dur + 0.02);
}

// Phone-call jaisi repeating ring: do-tone siren x2, phir pause
function ringBurst(toneType: 'siren' | 'code_blue' | 'lab_panic' = 'siren') {
  const c = ensureCtx();
  if (!c) return;
  if (c.state === 'suspended') c.resume().catch(() => {});
  const t = c.currentTime;

  if (toneType === 'code_blue') {
    // 440 Hz continuous resonant clinical emergency pulse
    tone(c, 440, t, 0.45, 0.4);
    tone(c, 440, t + 0.6, 0.45, 0.4);
  } else if (toneType === 'lab_panic') {
    // High-pitched 880 Hz urgent warning tone
    tone(c, 880, t, 0.15, 0.35);
    tone(c, 880, t + 0.25, 0.15, 0.35);
    tone(c, 880, t + 0.5, 0.15, 0.35);
  } else {
    // Dual-frequency emergency transport siren
    tone(c, 960, t, 0.22);
    tone(c, 720, t + 0.25, 0.22);
    tone(c, 960, t + 0.55, 0.22);
    tone(c, 720, t + 0.8, 0.22);
  }
}

let wakeLockSentinel: any = null;

async function requestWakeLock() {
  try {
    if ('wakeLock' in navigator && (navigator as any).wakeLock) {
      wakeLockSentinel = await (navigator as any).wakeLock.request('screen');
    }
  } catch {
    /* wake lock unsupported */
  }
}

function releaseWakeLock() {
  try {
    if (wakeLockSentinel) {
      wakeLockSentinel.release().catch(() => {});
      wakeLockSentinel = null;
    }
  } catch {
    /* noop */
  }
}

export function startEmergencyRing(toneType: 'siren' | 'code_blue' | 'lab_panic' = 'siren') {
  stopEmergencyRing();
  requestWakeLock();
  ringBurst(toneType);
  ringTimer = setInterval(() => ringBurst(toneType), 1800);

  const vibrate = () => {
    try {
      navigator.vibrate?.([400, 200, 400, 200, 800]);
    } catch {
      /* vibration blocked / unsupported */
    }
  };
  vibrate();
  vibTimer = setInterval(vibrate, 2400);
}

export function stopEmergencyRing() {
  if (ringTimer) clearInterval(ringTimer);
  if (vibTimer) clearInterval(vibTimer);
  ringTimer = null;
  vibTimer = null;
  releaseWakeLock();
  try {
    navigator.vibrate?.(0);
  } catch {
    /* noop */
  }
}

